INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-1', 'en', 'Bài 1: Giáo dục & Trường học (1) - CEFR A1', 'CEFR A1', 'A1 · Giáo dục', '25 từ vựng Tiếng Anh CEFR A1 chủ đề giáo dục & trường học kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1001, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_library', 'en-a1-1', 'library', '/ˈlaɪbreri/', 'A1', 'thư viện; phòng đọc; kho tài liệu; kho lưu trữ số', 'n.', 'librarian (n.)', NULL, 'library là nơi mượn sách để đọc, còn bookshop là hiệu sách để mua.', 'I borrowed three books from the library after school.', NULL, 'Tôi đã mượn ba cuốn sách từ thư viện sau giờ học.', '{"wordId":"library","ukIpa":"/ˈlaɪbrəri/","usIpa":"/ˈlaɪbreri/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"A place where people read or borrow books and other materials.","vi":"thư viện; phòng đọc"},{"pos":"n.","en":"An organised collection of books, recordings, or digital resources.","vi":"kho tài liệu; kho lưu trữ số"}],"examples":[{"en":"I borrowed three books from the library after school.","vi":"Tôi đã mượn ba cuốn sách từ thư viện sau giờ học.","audioKind":"ex"},{"en":"Public libraries support lifelong learning by providing free access to books, digital resources, and quiet study spaces.","vi":"Các thư viện công cộng hỗ trợ việc học tập suốt đời bằng cách cung cấp quyền truy cập miễn phí vào sách, tài nguyên số và không gian học tập yên tĩnh.","audioKind":"ex2"}],"collocations":[{"en":"public library","vi":"thư viện công cộng"},{"en":"library card","vi":"thẻ thư viện"},{"en":"digital library","vi":"thư viện số"},{"en":"library resources","vi":"tài nguyên thư viện"}],"wordFamily":["librarian (n.)"],"synonyms":[],"antonyms":[],"tipVi":"library là nơi mượn sách để đọc, còn bookshop là hiệu sách để mua.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_writing', 'en-a1-1', 'writing', '/ˈraɪtɪŋ/', 'A1', 'hoạt động viết; kỹ năng viết chữ; chữ viết; nét chữ viết tay của ai đó; tác phẩm viết; bài viết; văn bản, đặc biệt là sách, bài báo hoặc tài liệu văn học', 'n.', 'write (v.), writer (n.), rewrite (v.)', NULL, 'writing thường là danh từ không đếm được; đây đồng thời là dạng phân từ hiện tại của write (bỏ e rồi thêm -ing).', 'I do most of my writing before breakfast.', NULL, 'Tôi hoàn thành phần lớn công việc viết lách trước bữa sáng.', '{"wordId":"writing","ukIpa":"/ˈraɪtɪŋ/","usIpa":"/ˈraɪtɪŋ/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"The activity or skill of producing words on a surface.","vi":"hoạt động viết; kỹ năng viết chữ"},{"pos":"n.","en":"The way someone''s handwritten words look.","vi":"chữ viết; nét chữ viết tay của ai đó"},{"pos":"n.","en":"Written work, especially books, articles or literary material.","vi":"tác phẩm viết; bài viết; văn bản, đặc biệt là sách, bài báo hoặc tài liệu văn học"}],"examples":[{"en":"I do most of my writing before breakfast.","vi":"Tôi hoàn thành phần lớn công việc viết lách trước bữa sáng.","audioKind":"ex"},{"en":"Regular writing practice helps students organise complex ideas and communicate their arguments more clearly.","vi":"Thói quen luyện viết thường xuyên giúp học sinh sắp xếp các ý tưởng phức tạp và truyền đạt luận điểm của mình mạch lạc hơn.","audioKind":"ex2"}],"collocations":[{"en":"creative writing","vi":"viết sáng tạo"},{"en":"writing skills","vi":"kỹ năng viết"},{"en":"in writing","vi":"bằng văn bản"},{"en":"academic writing","vi":"viết học thuật"}],"wordFamily":["write (v.)","writer (n.)","rewrite (v.)"],"synonyms":[],"antonyms":[],"tipVi":"writing thường là danh từ không đếm được; đây đồng thời là dạng phân từ hiện tại của write (bỏ e rồi thêm -ing).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_english', 'en-a1-1', 'English', '/ˈɪŋɡlɪʃ/', 'A1', 'tiếng Anh; thuộc về nước Anh; thuộc về tiếng Anh', 'n.', NULL, NULL, 'Chữ cái đầu tiên luôn viết hoa; English khác với British dùng để chỉ chung nước Anh/Vương quốc Anh.', 'We practise English together while walking home from college.', NULL, 'Chúng tôi cùng nhau thực hành tiếng Anh trên đường đi bộ từ trường cao đẳng về nhà.', '{"wordId":"english","ukIpa":"/ˈɪŋɡlɪʃ/","usIpa":"/ˈɪŋɡlɪʃ/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"the language originating in England and widely spoken internationally","vi":"tiếng Anh"},{"pos":"adj.","en":"relating to the English language, England or its people","vi":"thuộc về nước Anh; thuộc về tiếng Anh"}],"examples":[{"en":"We practise English together while walking home from college.","vi":"Chúng tôi cùng nhau thực hành tiếng Anh trên đường đi bộ từ trường cao đẳng về nhà.","audioKind":"ex"},{"en":"Learning English can widen access to international research and help students communicate across cultural boundaries.","vi":"Học tiếng Anh giúp mở rộng khả năng tiếp cận các nghiên cứu quốc tế và hỗ trợ học sinh giao tiếp vượt qua các rào cản văn hóa.","audioKind":"ex2"}],"collocations":[{"en":"speak English","vi":"nói tiếng Anh"},{"en":"fluent English","vi":"tiếng Anh lưu loát"},{"en":"English literature","vi":"văn học Anh"},{"en":"an English accent","vi":"giọng Anh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chữ cái đầu tiên luôn viết hoa; English khác với British dùng để chỉ chung nước Anh/Vương quốc Anh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_student', 'en-a1-1', 'student', '/ˈstuːdənt/', 'A1', 'học sinh; sinh viên', 'n.', 'study (v.)', 'Đồng nghĩa: learner, pupil', 'Từ student không chỉ giới hạn ở sinh viên đại học; pupil chủ yếu chỉ học sinh bậc tiểu học và trung học.', 'A student left her backpack under the library desk.', NULL, 'Một học sinh đã để quên ba lô dưới bàn học trong thư viện.', '{"wordId":"student","ukIpa":"/ˈstjuːdənt/","usIpa":"/ˈstuːdənt/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"a person who studies at a school, college, or university","vi":"học sinh; sinh viên"}],"examples":[{"en":"A student left her backpack under the library desk.","vi":"Một học sinh đã để quên ba lô dưới bàn học trong thư viện.","audioKind":"ex"},{"en":"Universities should ensure that every student can access affordable housing and appropriate support throughout their studies.","vi":"Các trường đại học nên đảm bảo mọi sinh viên đều có thể tiếp cận nhà ở có giá cả phải chăng và sự hỗ trợ phù hợp trong suốt quá trình học tập.","audioKind":"ex2"}],"collocations":[{"en":"university student","vi":"sinh viên đại học"},{"en":"international student","vi":"sinh viên quốc tế"},{"en":"student loan","vi":"khoản vay sinh viên"},{"en":"student accommodation","vi":"chỗ ở cho sinh viên"}],"wordFamily":["study (v.)"],"synonyms":["learner","pupil"],"antonyms":[],"tipVi":"Từ student không chỉ giới hạn ở sinh viên đại học; pupil chủ yếu chỉ học sinh bậc tiểu học và trung học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reading', 'en-a1-1', 'reading', '/ˈriːdɪŋ/', 'A1', 'việc đọc; hoạt động đọc sách; số đo; chỉ số trên thiết bị; buổi đọc sách; buổi ngâm thơ', 'n.', 'read (v.), reader (n.), readable (adj.), readability (n.)', NULL, 'Chỉ hoạt động đọc thường là danh từ không đếm được; chỉ số đo hoặc buổi đọc sách là danh từ đếm được.', 'Reading before bed helps me relax after a busy day.', NULL, 'Đọc sách trước khi đi ngủ giúp tôi thư giãn sau một ngày bận rộn.', '{"wordId":"reading","ukIpa":"/ˈriːdɪŋ/","usIpa":"/ˈriːdɪŋ/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"The activity of understanding written words.","vi":"việc đọc; hoạt động đọc sách"},{"pos":"n.","en":"A measurement shown by an instrument.","vi":"số đo; chỉ số trên thiết bị"},{"pos":"n.","en":"An occasion when someone reads a written work aloud.","vi":"buổi đọc sách; buổi ngâm thơ"}],"examples":[{"en":"Reading before bed helps me relax after a busy day.","vi":"Đọc sách trước khi đi ngủ giúp tôi thư giãn sau một ngày bận rộn.","audioKind":"ex"},{"en":"Regular reading exposes students to varied vocabulary and helps them develop stronger critical thinking skills.","vi":"Việc thường xuyên đọc sách giúp học sinh tiếp cận với vốn từ vựng phong phú và phát triển kỹ năng tư duy phản biện tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"reading comprehension","vi":"kỹ năng đọc hiểu"},{"en":"reading habits","vi":"thói quen đọc sách"},{"en":"take a reading","vi":"lấy chỉ số đo"},{"en":"poetry reading","vi":"buổi đọc thơ"}],"wordFamily":["read (v.)","reader (n.)","readable (adj.)","readability (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ hoạt động đọc thường là danh từ không đếm được; chỉ số đo hoặc buổi đọc sách là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_answer', 'en-a1-1', 'answer', '/ˈænsər/', 'A1', 'câu trả lời; đáp án; giải pháp; trả lời; đáp; nghe (điện thoại)', 'n.', 'answerable (adj.), unanswered (adj.)', 'Đồng nghĩa: reply, response, solution', 'Động từ answer đi thẳng với đối tượng câu hỏi; danh từ đi với the answer to.', 'I asked the price, but nobody gave an answer.', NULL, 'Tôi đã hỏi giá nhưng không ai trả lời.', '{"wordId":"answer","ukIpa":"/ˈɑːnsə/","usIpa":"/ˈænsər/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"a reply, correct result, or solution to a problem","vi":"câu trả lời; đáp án; giải pháp"},{"pos":"v.","en":"to reply to someone or respond to a call","vi":"trả lời; đáp; nghe (điện thoại)"}],"examples":[{"en":"I asked the price, but nobody gave an answer.","vi":"Tôi đã hỏi giá nhưng không ai trả lời.","audioKind":"ex"},{"en":"Improving public transport may provide an answer to traffic congestion in rapidly growing urban areas.","vi":"Cải thiện giao thông công cộng có thể cung cấp giải pháp cho tình trạng tắc nghẽn giao thông ở các đô thị đang phát triển nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"answer a question","vi":"trả lời câu hỏi"},{"en":"answer the phone","vi":"nghe điện thoại"},{"en":"the answer to a problem","vi":"câu trả lời cho một vấn đề"},{"en":"a clear answer","vi":"câu trả lời rõ ràng"}],"wordFamily":["answerable (adj.)","unanswered (adj.)"],"synonyms":["reply","response","solution"],"antonyms":[],"tipVi":"Động từ answer đi thẳng với đối tượng câu hỏi; danh từ đi với the answer to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_practise', 'en-a1-1', 'practise', '/ˈpræktɪs/', 'A1', 'luyện tập; rèn luyện; hành nghề (y, luật...); thực hành; tuân theo (tín ngưỡng, thói quen)', 'v.', 'practice (n.), practitioner (n.), practised (adj.)', 'Đồng nghĩa: rehearse', 'Trong tiếng Anh-Anh, động từ là practise, danh từ là practice; trong tiếng Anh-Mỹ, cả động từ và danh từ đều viết là practice.', 'I practise the violin quietly after dinner each evening.', NULL, 'Tôi tập đàn vĩ cầm khe khẽ sau bữa tối mỗi ngày.', '{"wordId":"practise","ukIpa":"/ˈpræktɪs/","usIpa":"/ˈpræktɪs/","cefr":"A1","topic":"education","senses":[{"pos":"v.","en":"Do something repeatedly to improve your skill","vi":"luyện tập; rèn luyện"},{"pos":"v.","en":"Work in a profession such as medicine or law","vi":"hành nghề (y, luật...)"},{"pos":"v.","en":"Regularly follow a belief, custom, or method","vi":"thực hành; tuân theo (tín ngưỡng, thói quen)"}],"examples":[{"en":"I practise the violin quietly after dinner each evening.","vi":"Tôi tập đàn vĩ cầm khe khẽ sau bữa tối mỗi ngày.","audioKind":"ex"},{"en":"Language learners should practise speaking regularly rather than rely entirely on memorising vocabulary and grammar rules.","vi":"Người học ngôn ngữ nên luyện nói thường xuyên thay vì chỉ dựa hoàn toàn vào việc ghi nhớ từ vựng và quy tắc ngữ pháp.","audioKind":"ex2"}],"collocations":[{"en":"practise speaking","vi":"luyện nói"},{"en":"practise medicine","vi":"hành nghề y"},{"en":"practise regularly","vi":"luyện tập thường xuyên"},{"en":"practise what you preach","vi":"nói đi đôi với làm"}],"wordFamily":["practice (n.)","practitioner (n.)","practised (adj.)"],"synonyms":["rehearse"],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh, động từ là practise, danh từ là practice; trong tiếng Anh-Mỹ, cả động từ và danh từ đều viết là practice.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_correct', 'en-a1-1', 'correct', '/kəˈrekt/', 'A1', 'chính xác; đúng; sửa; chữa; chấm bài; đúng đắn; thích hợp', 'adj.', 'correction (n.), correctly (adv.), incorrect (adj.), correctness (n.)', 'Đồng nghĩa: right, accurate · Trái nghĩa: incorrect, wrong', 'Vừa là tính từ vừa là động từ; correctly mới là trạng từ.', 'You were correct about the keys being under the sofa.', NULL, 'Bạn đã nói đúng về việc chìa khóa ở dưới ghế sofa.', '{"wordId":"correct","ukIpa":"/kəˈrekt/","usIpa":"/kəˈrekt/","cefr":"A1","topic":"education","senses":[{"pos":"adj.","en":"free from mistakes and matching the facts","vi":"chính xác; đúng"},{"pos":"v.","en":"to identify mistakes or change something to make it right","vi":"sửa; chữa; chấm bài"},{"pos":"adj.","en":"suitable or accepted as proper for a particular situation","vi":"đúng đắn; thích hợp"}],"examples":[{"en":"You were correct about the keys being under the sofa.","vi":"Bạn đã nói đúng về việc chìa khóa ở dưới ghế sofa.","audioKind":"ex"},{"en":"Teachers should help students correct their mistakes rather than simply provide them with the right answers.","vi":"Giáo viên nên giúp học sinh sửa lỗi sai của các em thay vì chỉ đưa ra câu trả lời đúng.","audioKind":"ex2"}],"collocations":[{"en":"the correct answer","vi":"câu trả lời đúng"},{"en":"correct a mistake","vi":"sửa lỗi"},{"en":"correct procedure","vi":"quy trình chuẩn"},{"en":"factually correct","vi":"đúng sự thật"}],"wordFamily":["correction (n.)","correctly (adv.)","incorrect (adj.)","correctness (n.)"],"synonyms":["right","accurate"],"antonyms":["incorrect","wrong"],"tipVi":"Vừa là tính từ vừa là động từ; correctly mới là trạng từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_french', 'en-a1-1', 'French', '/frentʃ/', 'A1', 'thuộc về nước Pháp; bằng tiếng Pháp; tiếng Pháp; người Pháp (dùng chung)', 'adj.', NULL, NULL, 'Chữ cái đầu luôn viết hoa; the French chỉ tổng thể người Pháp.', 'We bought fresh bread from a small French bakery.', NULL, 'Chúng tôi đã mua bánh mì tươi từ một tiệm bánh nhỏ kiểu Pháp.', '{"wordId":"french","ukIpa":"/frentʃ/","usIpa":"/frentʃ/","cefr":"A1","topic":"education","senses":[{"pos":"adj.","en":"relating to France, its people, or its language","vi":"thuộc về nước Pháp; bằng tiếng Pháp"},{"pos":"n.","en":"the language spoken in France and several other countries","vi":"tiếng Pháp"},{"pos":"n.","en":"the people of France, referred to collectively as the French","vi":"người Pháp (dùng chung)"}],"examples":[{"en":"We bought fresh bread from a small French bakery.","vi":"Chúng tôi đã mua bánh mì tươi từ một tiệm bánh nhỏ kiểu Pháp.","audioKind":"ex"},{"en":"Learning French can improve employment prospects in regions where the language is widely used in business.","vi":"Học tiếng Pháp có thể cải thiện cơ hội việc làm ở những vùng mà ngôn ngữ này được sử dụng rộng rãi trong kinh doanh.","audioKind":"ex2"}],"collocations":[{"en":"French cuisine","vi":"ẩm thực Pháp"},{"en":"speak French","vi":"nói tiếng Pháp"},{"en":"French literature","vi":"văn học Pháp"},{"en":"the French","vi":"người Pháp"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chữ cái đầu luôn viết hoa; the French chỉ tổng thể người Pháp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grammar', 'en-a1-1', 'grammar', '/ˈɡræmər/', 'A1', 'ngữ pháp; quy tắc ngữ pháp', 'n.', 'grammatical (adj.), grammatically (adv.), ungrammatical (adj.)', NULL, 'Không đếm được khi chỉ kiến thức ngữ pháp; một lỗi ngữ pháp dùng a grammar mistake.', 'Our teacher explains grammar using examples from everyday conversations.', NULL, 'Giáo viên của chúng tôi giải thích ngữ pháp bằng cách sử dụng các ví dụ từ các cuộc hội thoại hàng ngày.', '{"wordId":"grammar","ukIpa":"/ˈɡræmə/","usIpa":"/ˈɡræmər/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"The rules for combining words and changing their forms.","vi":"ngữ pháp; quy tắc ngữ pháp"}],"examples":[{"en":"Our teacher explains grammar using examples from everyday conversations.","vi":"Giáo viên của chúng tôi giải thích ngữ pháp bằng cách sử dụng các ví dụ từ các cuộc hội thoại hàng ngày.","audioKind":"ex"},{"en":"Although grammar instruction is important, language courses should also give learners opportunities to communicate in realistic situations.","vi":"Mặc dù việc giảng dạy ngữ pháp rất quan trọng, các khóa học ngôn ngữ cũng nên mang lại cho người học cơ hội giao tiếp trong các tình huống thực tế.","audioKind":"ex2"}],"collocations":[{"en":"grammar rules","vi":"quy tắc ngữ pháp"},{"en":"English grammar","vi":"ngữ pháp tiếng Anh"},{"en":"correct grammar","vi":"ngữ pháp đúng"},{"en":"a grammar exercise","vi":"bài tập ngữ pháp"}],"wordFamily":["grammatical (adj.)","grammatically (adv.)","ungrammatical (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Không đếm được khi chỉ kiến thức ngữ pháp; một lỗi ngữ pháp dùng a grammar mistake.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_maths', 'en-a1-1', 'maths', '/mæθs/', 'A1', 'môn toán; toán học', 'n.', 'mathematics (n.), mathematical (adj.), mathematically (adv.), mathematician (n.)', 'Đồng nghĩa: mathematics, math', 'Anh-Anh dùng maths, Anh-Mỹ dùng math; làm chủ ngữ thì đi với động từ số ít.', 'We used coloured blocks to practise maths after lunch.', NULL, 'Chúng tôi dùng các khối gỗ màu để thực hành toán sau bữa trưa.', '{"wordId":"maths","ukIpa":"/mæθs/","usIpa":"/mæθs/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"The study of quantities, shapes, and relationships using logical rules","vi":"môn toán; toán học"}],"examples":[{"en":"We used coloured blocks to practise maths after lunch.","vi":"Chúng tôi dùng các khối gỗ màu để thực hành toán sau bữa trưa.","audioKind":"ex"},{"en":"Strong maths skills help students interpret financial information and make informed decisions in everyday life.","vi":"Kỹ năng toán học vững vàng giúp học sinh phân tích thông tin tài chính và đưa ra quyết định sáng suốt trong cuộc sống hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"maths teacher","vi":"giáo viên toán"},{"en":"maths lesson","vi":"tiết học toán"},{"en":"maths skills","vi":"kỹ năng toán học"},{"en":"good at maths","vi":"giỏi toán"}],"wordFamily":["mathematics (n.)","mathematical (adj.)","mathematically (adv.)","mathematician (n.)"],"synonyms":["mathematics","math"],"antonyms":[],"tipVi":"Anh-Anh dùng maths, Anh-Mỹ dùng math; làm chủ ngữ thì đi với động từ số ít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_word', 'en-a1-1', 'word', '/wɝːd/', 'A1', 'n. từ; từ vựng; n. lời hứa; sự đảm bảo; v. diễn đạt; chọn từ ngữ', 'n.', 'wording (n.), wordy (adj.), wordless (adj.)', NULL, 'keep your word có nghĩa là giữ lời hứa, trong đó word không dùng số nhiều.', 'I looked up the unfamiliar word in a dictionary.', NULL, 'Tôi tra từ không quen thuộc đó trong từ điển.', '{"wordId":"word","ukIpa":"/wɜːd/","usIpa":"/wɝːd/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"A unit of language with meaning.","vi":"n. từ; từ vựng"},{"pos":"n.","en":"A promise or assurance that someone gives.","vi":"n. lời hứa; sự đảm bảo"},{"pos":"v.","en":"To express something using particular language.","vi":"v. diễn đạt; chọn từ ngữ"}],"examples":[{"en":"I looked up the unfamiliar word in a dictionary.","vi":"Tôi tra từ không quen thuộc đó trong từ điển.","audioKind":"ex"},{"en":"Students remember new words more effectively when they encounter them repeatedly in meaningful contexts.","vi":"Học sinh ghi nhớ từ mới hiệu quả hơn khi gặp lại chúng nhiều lần trong các ngữ cảnh có ý nghĩa.","audioKind":"ex2"}],"collocations":[{"en":"keep your word","vi":"giữ lời hứa"},{"en":"in other words","vi":"nói cách khác"},{"en":"word choice","vi":"sự lựa chọn từ ngữ"},{"en":"word a question carefully","vi":"chọn lọc từ ngữ cho câu hỏi một cách cẩn thận"}],"wordFamily":["wording (n.)","wordy (adj.)","wordless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"keep your word có nghĩa là giữ lời hứa, trong đó word không dùng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_desk', 'en-a1-1', 'desk', '/desk/', 'A1', 'bàn học; bàn làm việc; quầy lễ tân; bàn tiếp tân', 'n.', NULL, NULL, 'Ngồi ở bàn học dùng "at a desk", không dùng "on a desk".', 'I keep my pencils in the top desk drawer.', NULL, 'Tôi cất bút chì trong ngăn kéo phía trên cùng của bàn làm việc.', '{"wordId":"desk","ukIpa":"/desk/","usIpa":"/desk/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"A table used for studying, writing, or office work","vi":"bàn học; bàn làm việc"},{"pos":"n.","en":"A counter where people receive information or services","vi":"quầy lễ tân; bàn tiếp tân"}],"examples":[{"en":"I keep my pencils in the top desk drawer.","vi":"Tôi cất bút chì trong ngăn kéo phía trên cùng của bàn làm việc.","audioKind":"ex"},{"en":"Providing every student with a suitable desk can improve comfort and concentration in the classroom.","vi":"Việc cung cấp cho mỗi học sinh một chiếc bàn học phù hợp có thể cải thiện sự thoải mái và khả năng tập trung trong lớp.","audioKind":"ex2"}],"collocations":[{"en":"desk drawer","vi":"ngăn kéo bàn"},{"en":"reception desk","vi":"quầy tiếp tân"},{"en":"sit at a desk","vi":"ngồi trước bàn làm việc"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Ngồi ở bàn học dùng \"at a desk\", không dùng \"on a desk\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_course', 'en-a1-1', 'course', '/kɔːrs/', 'A1', 'khóa học; hướng đi; tiến trình; món ăn', 'n.', 'coursework (n.)', NULL, '"course" chỉ toàn bộ một khóa học; "lesson" chỉ một bài học nhỏ trong đó.', 'I joined a cooking course at the community centre.', NULL, 'Tôi đã tham gia một khóa học nấu ăn tại trung tâm cộng đồng.', '{"wordId":"course","ukIpa":"/kɔːs/","usIpa":"/kɔːrs/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"A series of lessons about a particular subject.","vi":"khóa học"},{"pos":"n.","en":"The route something follows or the way events develop.","vi":"hướng đi; tiến trình"},{"pos":"n.","en":"One part of a meal served separately from other parts.","vi":"món ăn"}],"examples":[{"en":"I joined a cooking course at the community centre.","vi":"Tôi đã tham gia một khóa học nấu ăn tại trung tâm cộng đồng.","audioKind":"ex"},{"en":"Universities should design each course to combine theoretical knowledge with practical skills relevant to future employment.","vi":"Các trường đại học nên thiết kế mỗi khóa học sao cho kết hợp hài hòa giữa kiến thức lý thuyết và các kỹ năng thực tế phục vụ cho công việc tương lai.","audioKind":"ex2"}],"collocations":[{"en":"take a course","vi":"tham gia khóa học"},{"en":"training course","vi":"khóa đào tạo"},{"en":"change course","vi":"đổi hướng"},{"en":"main course","vi":"món chính"}],"wordFamily":["coursework (n.)"],"synonyms":[],"antonyms":[],"tipVi":"\"course\" chỉ toàn bộ một khóa học; \"lesson\" chỉ một bài học nhỏ trong đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_teacher', 'en-a1-1', 'teacher', '/ˈtiːtʃər/', 'A1', 'giáo viên; thầy cô giáo', 'n.', 'teach (v.), teaching (n.)', 'Đồng nghĩa: educator, instructor', 'Trong tiếng Anh, cách xưng hô với thầy cô thường dùng Mr, Ms kèm theo họ, không gọi trực tiếp là Teacher.', 'Our teacher brought a plant into class today.', NULL, 'Giáo viên của chúng tôi đã mang một cây đến lớp vào ngày hôm nay.', '{"wordId":"teacher","ukIpa":"/ˈtiːtʃə/","usIpa":"/ˈtiːtʃər/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"someone whose job is to help people learn","vi":"giáo viên; thầy cô giáo"}],"examples":[{"en":"Our teacher brought a plant into class today.","vi":"Giáo viên của chúng tôi đã mang một cây đến lớp vào ngày hôm nay.","audioKind":"ex"},{"en":"A well-trained teacher can adapt classroom activities to support students with different learning needs and abilities.","vi":"Một giáo viên được đào tạo bài bản có thể điều chỉnh các hoạt động trên lớp để hỗ trợ học sinh có các nhu cầu và năng lực học tập khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"primary school teacher","vi":"giáo viên tiểu học"},{"en":"qualified teacher","vi":"giáo viên đạt chuẩn"},{"en":"teacher training","vi":"đào tạo giáo viên"}],"wordFamily":["teach (v.)","teaching (n.)"],"synonyms":["educator","instructor"],"antonyms":[],"tipVi":"Trong tiếng Anh, cách xưng hô với thầy cô thường dùng Mr, Ms kèm theo họ, không gọi trực tiếp là Teacher.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_notebook', 'en-a1-1', 'notebook', '/ˈnoʊtbʊk/', 'A1', 'sổ tay; vở ghi chép; máy tính xách tay nhỏ', 'n.', 'note (n.)', 'Đồng nghĩa: notepad', 'Thường chỉ sổ tay giấy; nghĩa máy tính cũng có thể dùng là "notebook computer".', 'She keeps a small notebook beside her bed.', NULL, 'Cô ấy để một cuốn sổ tay nhỏ bên cạnh giường.', '{"wordId":"notebook","ukIpa":"/ˈnəʊtbʊk/","usIpa":"/ˈnoʊtbʊk/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"A book of blank pages for writing notes.","vi":"sổ tay; vở ghi chép"},{"pos":"n.","en":"A small portable computer with a folding screen.","vi":"máy tính xách tay nhỏ"}],"examples":[{"en":"She keeps a small notebook beside her bed.","vi":"Cô ấy để một cuốn sổ tay nhỏ bên cạnh giường.","audioKind":"ex"},{"en":"Keeping a notebook during fieldwork allows researchers to record observations that photographs alone may not capture.","vi":"Việc mang theo sổ tay ghi chép khi đi thực địa giúp các nhà nghiên cứu lưu lại những quan sát mà chỉ riêng ảnh chụp có thể không ghi nhận được.","audioKind":"ex2"}],"collocations":[{"en":"write in a notebook","vi":"viết vào sổ tay"},{"en":"a spiral notebook","vi":"sổ tay gáy xoắn"},{"en":"a notebook computer","vi":"máy tính xách tay"}],"wordFamily":["note (n.)"],"synonyms":["notepad"],"antonyms":[],"tipVi":"Thường chỉ sổ tay giấy; nghĩa máy tính cũng có thể dùng là \"notebook computer\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ruler', 'en-a1-1', 'ruler', '/ˈruːlər/', 'A1', 'thước kẻ; người cai trị; nhà lãnh đạo', 'n.', 'rule (v.), ruling (adj.)', NULL, 'a ruler có thể chỉ một chiếc thước kẻ hoặc một nhà cai trị tùy thuộc vào ngữ cảnh.', 'Use a ruler to draw a straight line here.', NULL, 'Hãy dùng thước kẻ để vẽ một đường thẳng ở đây.', '{"wordId":"ruler","ukIpa":"/ˈruːlə/","usIpa":"/ˈruːlər/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"A straight tool for measuring lengths or drawing straight lines.","vi":"thước kẻ"},{"pos":"n.","en":"A person who governs a country or territory.","vi":"người cai trị; nhà lãnh đạo"}],"examples":[{"en":"Use a ruler to draw a straight line here.","vi":"Hãy dùng thước kẻ để vẽ một đường thẳng ở đây.","audioKind":"ex"},{"en":"The decisions of ancient rulers often influenced trade, architecture, and the daily lives of ordinary people.","vi":"Các quyết định của những nhà cai trị thời cổ đại thường chi phối thương mại, kiến trúc và đời sống thường ngày của người dân.","audioKind":"ex2"}],"collocations":[{"en":"a plastic ruler","vi":"thước nhựa"},{"en":"measure with a ruler","vi":"đo bằng thước kẻ"},{"en":"an absolute ruler","vi":"nhà độc tài; vị vua chuyên chế"}],"wordFamily":["rule (v.)","ruling (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"a ruler có thể chỉ một chiếc thước kẻ hoặc một nhà cai trị tùy thuộc vào ngữ cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_school', 'en-a1-1', 'school', '/skuːl/', 'A1', 'trường học; giờ học ở trường; trường phái; học thuyết; bầy cá', 'n.', 'schooling (n.), schoolchild (n.)', NULL, 'go to school nghĩa là đi học; go to the school nghĩa là đến địa điểm trường học.', 'We walk to school together along the river.', NULL, 'Chúng tôi cùng nhau đi bộ đến trường dọc theo bờ sông.', '{"wordId":"school","ukIpa":"/skuːl/","usIpa":"/skuːl/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"A place where children learn, or the time spent learning there.","vi":"trường học; giờ học ở trường"},{"pos":"n.","en":"A group sharing particular ideas, methods, or styles.","vi":"trường phái; học thuyết"},{"pos":"n.","en":"A group of fish swimming together.","vi":"bầy cá"}],"examples":[{"en":"We walk to school together along the river.","vi":"Chúng tôi cùng nhau đi bộ đến trường dọc theo bờ sông.","audioKind":"ex"},{"en":"Every school should provide opportunities for students to develop practical skills alongside their academic knowledge.","vi":"Mỗi trường học nên tạo cơ hội cho học sinh phát triển các kỹ năng thực tế bên cạnh kiến thức học thuật.","audioKind":"ex2"}],"collocations":[{"en":"primary school","vi":"trường tiểu học"},{"en":"secondary school","vi":"trường trung học"},{"en":"school of thought","vi":"trường phái tư tưởng"},{"en":"a school of fish","vi":"một bầy cá"}],"wordFamily":["schooling (n.)","schoolchild (n.)"],"synonyms":[],"antonyms":[],"tipVi":"go to school nghĩa là đi học; go to the school nghĩa là đến địa điểm trường học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_learn', 'en-a1-1', 'learn', '/lɝːn/', 'A1', 'học; học tập; tiếp thu; biết được; tìm hiểu', 'v.', 'learner (n.), learning (n.)', NULL, 'learn to do có nghĩa là học cách làm việc gì; dạng quá khứ có thể là learnt hoặc learned.', 'My grandfather is learning to swim at the local pool.', NULL, 'Ông tôi đang học bơi ở hồ bơi địa phương.', '{"wordId":"learn","ukIpa":"/lɜːn/","usIpa":"/lɝːn/","cefr":"A1","topic":"education","senses":[{"pos":"v.","en":"To gain knowledge or a skill through study or experience.","vi":"học; học tập; tiếp thu"},{"pos":"v.","en":"To find out information about something.","vi":"biết được; tìm hiểu"}],"examples":[{"en":"My grandfather is learning to swim at the local pool.","vi":"Ông tôi đang học bơi ở hồ bơi địa phương.","audioKind":"ex"},{"en":"Students often learn more effectively when they apply new knowledge to practical problems rather than memorise isolated facts.","vi":"Học sinh thường học hiệu quả hơn khi các em áp dụng kiến thức mới vào các vấn đề thực tế thay vì học thuộc lòng những sự kiện rời rạc.","audioKind":"ex2"}],"collocations":[{"en":"learn to drive","vi":"học lái xe"},{"en":"learn from mistakes","vi":"rút kinh nghiệm từ sai lầm"},{"en":"learn by heart","vi":"học thuộc lòng"},{"en":"learn about","vi":"tìm hiểu về"}],"wordFamily":["learner (n.)","learning (n.)"],"synonyms":[],"antonyms":[],"tipVi":"learn to do có nghĩa là học cách làm việc gì; dạng quá khứ có thể là learnt hoặc learned.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blackboard', 'en-a1-1', 'blackboard', '/ˈblækbɔːrd/', 'A1', 'bảng đen (dùng trong lớp học để viết hoặc vẽ bằng phấn)', 'n.', NULL, 'Đồng nghĩa: chalkboard', 'Dùng giới từ on trong cụm on the blackboard; được sử dụng kết hợp với phấn.', 'Our teacher drew a huge circle on the blackboard.', NULL, 'Cô giáo của chúng tôi đã vẽ một hình tròn lớn lên bảng đen.', '{"wordId":"blackboard","ukIpa":"/ˈblækbɔːd/","usIpa":"/ˈblækbɔːrd/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"A dark classroom board used for writing or drawing with chalk.","vi":"bảng đen (dùng trong lớp học để viết hoặc vẽ bằng phấn)"}],"examples":[{"en":"Our teacher drew a huge circle on the blackboard.","vi":"Cô giáo của chúng tôi đã vẽ một hình tròn lớn lên bảng đen.","audioKind":"ex"},{"en":"Although digital screens offer interactive features, a traditional blackboard remains an affordable teaching tool for many schools.","vi":"Mặc dù màn hình kỹ thuật số mang lại nhiều tính năng tương tác, bảng đen truyền thống vẫn là một công cụ giảng dạy tiết kiệm cho nhiều trường học.","audioKind":"ex2"}],"collocations":[{"en":"write on the blackboard","vi":"viết lên bảng đen"},{"en":"clean the blackboard","vi":"lau bảng đen"},{"en":"blackboard eraser","vi":"cục tẩy bảng đen"}],"wordFamily":[],"synonyms":["chalkboard"],"antonyms":[],"tipVi":"Dùng giới từ on trong cụm on the blackboard; được sử dụng kết hợp với phấn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_study', 'en-a1-1', 'study', '/ˈstʌdi/', 'A1', 'học tập; nghiên cứu; sự học tập; công trình nghiên cứu; phòng làm việc; phòng đọc sách', 'v.', 'student (n.), studious (adj.)', NULL, 'study nhấn mạnh quá trình học tập, learn thường nhấn mạnh việc đã học được hoặc thu nhận kiến thức.', 'I study English on the bus every morning.', NULL, 'Tôi học tiếng Anh trên xe buýt mỗi sáng.', '{"wordId":"study","ukIpa":"/ˈstʌdi/","usIpa":"/ˈstʌdi/","cefr":"A1","topic":"education","senses":[{"pos":"v.","en":"Spend time learning about or carefully examining a subject.","vi":"học tập; nghiên cứu"},{"pos":"n.","en":"The activity of learning, or an investigation of a subject.","vi":"sự học tập; công trình nghiên cứu"},{"pos":"n.","en":"A room used for reading, writing, or working.","vi":"phòng làm việc; phòng đọc sách"}],"examples":[{"en":"I study English on the bus every morning.","vi":"Tôi học tiếng Anh trên xe buýt mỗi sáng.","audioKind":"ex"},{"en":"A recent study suggests that regular exercise can improve students'' concentration during classroom activities.","vi":"Một nghiên cứu gần đây cho thấy việc tập luyện thường xuyên có thể cải thiện khả năng tập trung của học sinh trong các hoạt động trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"study abroad","vi":"du học"},{"en":"a recent study","vi":"một nghiên cứu gần đây"},{"en":"study for an exam","vi":"ôn thi"}],"wordFamily":["student (n.)","studious (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"study nhấn mạnh quá trình học tập, learn thường nhấn mạnh việc đã học được hoặc thu nhận kiến thức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exam', 'en-a1-1', 'exam', '/ɪɡˈzæm/', 'A1', 'kỳ thi; bài kiểm tra', 'n.', 'examination (n.), examine (v.), examiner (n.)', 'Đồng nghĩa: examination, test', 'exam là từ viết tắt phổ biến của examination; đi thi dùng động từ take.', 'I have a maths exam on Friday morning.', NULL, 'Tôi có một bài kiểm tra toán vào sáng thứ Sáu.', '{"wordId":"exam","ukIpa":"/ɪɡˈzæm/","usIpa":"/ɪɡˈzæm/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"A formal test of knowledge or ability.","vi":"kỳ thi; bài kiểm tra"}],"examples":[{"en":"I have a maths exam on Friday morning.","vi":"Tôi có một bài kiểm tra toán vào sáng thứ Sáu.","audioKind":"ex"},{"en":"Schools should consider practical skills alongside exam results when assessing students'' overall progress.","vi":"Các trường học nên cân nhắc các kỹ năng thực hành bên cạnh kết quả thi khi đánh giá sự tiến bộ tổng thể của học sinh.","audioKind":"ex2"}],"collocations":[{"en":"take an exam","vi":"tham gia kỳ thi; dự thi"},{"en":"pass an exam","vi":"vượt qua kỳ thi; đậu kỳ thi"},{"en":"revise for an exam","vi":"ôn thi"},{"en":"exam results","vi":"kết quả thi"}],"wordFamily":["examination (n.)","examine (v.)","examiner (n.)"],"synonyms":["examination","test"],"antonyms":[],"tipVi":"exam là từ viết tắt phổ biến của examination; đi thi dùng động từ take.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_class', 'en-a1-1', 'class', '/klæs/', 'A1', 'lớp học; tiết học; tầng lớp xã hội; loại; xếp loại; phân loại', 'n.', 'classmate (n.), classroom (n.), classify (v.), classification (n.)', NULL, 'Cụm từ in class thường có nghĩa là đang trong giờ học, còn in the class nghĩa là ở trong lớp học cụ thể đó.', 'Our class is learning how to grow vegetables.', NULL, 'Lớp chúng tôi đang học cách trồng rau.', '{"wordId":"class","ukIpa":"/klɑːs/","usIpa":"/klæs/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"A group learning together, or a lesson they attend.","vi":"lớp học; tiết học"},{"pos":"n.","en":"A social group or category sharing particular characteristics.","vi":"tầng lớp xã hội; loại"},{"pos":"v.","en":"To place someone or something in a particular category.","vi":"xếp loại; phân loại"}],"examples":[{"en":"Our class is learning how to grow vegetables.","vi":"Lớp chúng tôi đang học cách trồng rau.","audioKind":"ex"},{"en":"Smaller class sizes may allow teachers to give more individual attention to students with learning difficulties.","vi":"Quy mô lớp học nhỏ hơn có thể giúp giáo viên quan tâm nhiều hơn đến từng học sinh gặp khó khăn trong học tập.","audioKind":"ex2"}],"collocations":[{"en":"attend a class","vi":"đi học; tham gia lớp học"},{"en":"class size","vi":"sĩ số lớp học"},{"en":"social class","vi":"tầng lớp xã hội"},{"en":"be classed as","vi":"được xếp loại là"}],"wordFamily":["classmate (n.)","classroom (n.)","classify (v.)","classification (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ in class thường có nghĩa là đang trong giờ học, còn in the class nghĩa là ở trong lớp học cụ thể đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_paper', 'en-a1-1', 'paper', '/ˈpeɪpər/', 'A1', 'giấy; báo; tờ báo; bài báo khoa học; bài tiểu luận; bài thi', 'n.', 'paperless (adj.), papery (adj.)', NULL, 'Danh từ paper không đếm được khi chỉ chất liệu, dùng a piece of paper; khi chỉ bài báo, bài thi hay tờ báo thì đếm được.', 'She wrapped the small gift in bright yellow paper.', NULL, 'Cô ấy đã gói món quà nhỏ bằng lớp giấy màu vàng tươi.', '{"wordId":"paper","ukIpa":"/ˈpeɪpə/","usIpa":"/ˈpeɪpər/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"Thin material used for writing, printing, or wrapping.","vi":"giấy"},{"pos":"n.","en":"A publication containing news, usually printed on large sheets.","vi":"báo; tờ báo"},{"pos":"n.","en":"An academic article or a written examination.","vi":"bài báo khoa học; bài tiểu luận; bài thi"}],"examples":[{"en":"She wrapped the small gift in bright yellow paper.","vi":"Cô ấy đã gói món quà nhỏ bằng lớp giấy màu vàng tươi.","audioKind":"ex"},{"en":"The university encourages students to submit assignments electronically to reduce paper consumption across its departments.","vi":"Trường đại học khuyến khích sinh viên nộp bài tập qua đường điện tử để giảm lượng tiêu thụ giấy ở các khoa.","audioKind":"ex2"}],"collocations":[{"en":"a sheet of paper","vi":"một tờ giấy"},{"en":"recycled paper","vi":"giấy tái chế"},{"en":"research paper","vi":"bài báo nghiên cứu"},{"en":"exam paper","vi":"đề thi"}],"wordFamily":["paperless (adj.)","papery (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ paper không đếm được khi chỉ chất liệu, dùng a piece of paper; khi chỉ bài báo, bài thi hay tờ báo thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spell', 'en-a1-1', 'spell', '/spel/', 'A1', 'đánh vần; một khoảng thời gian; bùa chú; phép thuật', 'v.', 'spelling (n.), misspell (v.)', NULL, 'Thì quá khứ và phân từ hai ở Anh-Anh có thể dùng spelt hoặc spelled.', 'Could you spell your surname slowly for me, please?', NULL, 'Bạn có thể đánh vần từ từ họ của bạn giúp tôi được không?', '{"wordId":"spell","ukIpa":"/spel/","usIpa":"/spel/","cefr":"A1","topic":"education","senses":[{"pos":"v.","en":"To write or say the letters of a word in order.","vi":"đánh vần"},{"pos":"n.","en":"A period during which a particular condition or activity continues.","vi":"một khoảng thời gian"},{"pos":"n.","en":"Words or magic believed to have special powers.","vi":"bùa chú; phép thuật"}],"examples":[{"en":"Could you spell your surname slowly for me, please?","vi":"Bạn có thể đánh vần từ từ họ của bạn giúp tôi được không?","audioKind":"ex"},{"en":"A prolonged spell of dry weather can reduce crop yields and increase pressure on local water supplies.","vi":"Một đợt hạn kéo dài có thể làm giảm năng suất cây trồng và gây áp lực lớn lên nguồn nước sinh hoạt.","audioKind":"ex2"}],"collocations":[{"en":"spell a word","vi":"đánh vần một từ"},{"en":"a dry spell","vi":"một đợt khô hạn"},{"en":"a spell of illness","vi":"một thời gian bị ốm"},{"en":"cast a spell","vi":"yểm bùa"}],"wordFamily":["spelling (n.)","misspell (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Thì quá khứ và phân từ hai ở Anh-Anh có thể dùng spelt hoặc spelled.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_1_1', 'en-a1-1', 'Cách dùng “practise” (v.) — luyện tập; rèn luyện', 'practise speaking  ·  practise medicine  ·  practise regularly', 'Trong tiếng Anh-Anh, động từ là practise, danh từ là practice; trong tiếng Anh-Mỹ, cả động từ và danh từ đều viết là practice.', 'Họ từ (Word Family): practice (n.), practitioner (n.), practised (adj.) | Đồng nghĩa: rehearse', '[{"hanzi":"I practise the violin quietly after dinner each evening.","pinyin":"","meaning":"Tôi tập đàn vĩ cầm khe khẽ sau bữa tối mỗi ngày."},{"hanzi":"Language learners should practise speaking regularly rather than rely entirely on memorising vocabulary and grammar rules.","pinyin":"","meaning":"Người học ngôn ngữ nên luyện nói thường xuyên thay vì chỉ dựa hoàn toàn vào việc ghi nhớ từ vựng và quy tắc ngữ pháp."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_1_2', 'en-a1-1', 'Cách dùng “paper” (n.) — giấy', 'a sheet of paper  ·  recycled paper  ·  research paper', 'Danh từ paper không đếm được khi chỉ chất liệu, dùng a piece of paper; khi chỉ bài báo, bài thi hay tờ báo thì đếm được.', 'Họ từ (Word Family): paperless (adj.), papery (adj.)', '[{"hanzi":"She wrapped the small gift in bright yellow paper.","pinyin":"","meaning":"Cô ấy đã gói món quà nhỏ bằng lớp giấy màu vàng tươi."},{"hanzi":"The university encourages students to submit assignments electronically to reduce paper consumption across its departments.","pinyin":"","meaning":"Trường đại học khuyến khích sinh viên nộp bài tập qua đường điện tử để giảm lượng tiêu thụ giấy ở các khoa."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_1_3', 'en-a1-1', 'Cách dùng “writing” (n.) — hoạt động viết; kỹ năng viết chữ', 'creative writing  ·  writing skills  ·  in writing', 'writing thường là danh từ không đếm được; đây đồng thời là dạng phân từ hiện tại của write (bỏ e rồi thêm -ing).', 'Họ từ (Word Family): write (v.), writer (n.), rewrite (v.)', '[{"hanzi":"I do most of my writing before breakfast.","pinyin":"","meaning":"Tôi hoàn thành phần lớn công việc viết lách trước bữa sáng."},{"hanzi":"Regular writing practice helps students organise complex ideas and communicate their arguments more clearly.","pinyin":"","meaning":"Thói quen luyện viết thường xuyên giúp học sinh sắp xếp các ý tưởng phức tạp và truyền đạt luận điểm của mình mạch lạc hơn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_1_4', 'en-a1-1', 'Cách dùng “class” (n.) — lớp học; tiết học', 'attend a class  ·  class size  ·  social class', 'Cụm từ in class thường có nghĩa là đang trong giờ học, còn in the class nghĩa là ở trong lớp học cụ thể đó.', 'Họ từ (Word Family): classmate (n.), classroom (n.), classify (v.), classification (n.)', '[{"hanzi":"Our class is learning how to grow vegetables.","pinyin":"","meaning":"Lớp chúng tôi đang học cách trồng rau."},{"hanzi":"Smaller class sizes may allow teachers to give more individual attention to students with learning difficulties.","pinyin":"","meaning":"Quy mô lớp học nhỏ hơn có thể giúp giáo viên quan tâm nhiều hơn đến từng học sinh gặp khó khăn trong học tập."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_1_1', 'en-a1-1', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_1_1_1', 'ten_1_1', 'library', 'I borrowed three books from the library after school.', 'I borrowed three books from the library after school.', '/ˈlaɪbreri/', 'Tôi đã mượn ba cuốn sách từ thư viện sau giờ học.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_1_1_2', 'ten_1_1', 'writing', 'I do most of my writing before breakfast.', 'I do most of my writing before breakfast.', '/ˈraɪtɪŋ/', 'Tôi hoàn thành phần lớn công việc viết lách trước bữa sáng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_1_1_3', 'ten_1_1', 'English', 'We practise English together while walking home from college.', 'We practise English together while walking home from college.', '/ˈɪŋɡlɪʃ/', 'Chúng tôi cùng nhau thực hành tiếng Anh trên đường đi bộ từ trường cao đẳng về nhà.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_1_1_4', 'ten_1_1', 'student', 'A student left her backpack under the library desk.', 'A student left her backpack under the library desk.', '/ˈstuːdənt/', 'Một học sinh đã để quên ba lô dưới bàn học trong thư viện.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_1_1_5', 'ten_1_1', 'reading', 'Reading before bed helps me relax after a busy day.', 'Reading before bed helps me relax after a busy day.', '/ˈriːdɪŋ/', 'Đọc sách trước khi đi ngủ giúp tôi thư giãn sau một ngày bận rộn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
