INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_1_1_1', 'en-a1-1', 'ten_1_1', 'listening', 'listening', 'I borrowed three books from the library after school.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã mượn ba cuốn sách từ thư viện sau giờ học.","Tôi tập đàn vĩ cầm khe khẽ sau bữa tối mỗi ngày.","Bạn đã nói đúng về việc chìa khóa ở dưới ghế sofa.","Tôi đã hỏi giá nhưng không ai trả lời."]'::jsonb, 0, 'I borrowed three books from the library after school. → Tôi đã mượn ba cuốn sách từ thư viện sau giờ học.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_1_1_2', 'en-a1-1', 'ten_1_1', 'listening', 'listening', 'I do most of my writing before breakfast.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi hoàn thành phần lớn công việc viết lách trước bữa sáng.","Tôi đã mượn ba cuốn sách từ thư viện sau giờ học.","Tôi đã hỏi giá nhưng không ai trả lời.","Đọc sách trước khi đi ngủ giúp tôi thư giãn sau một ngày bận rộn."]'::jsonb, 0, 'I do most of my writing before breakfast. → Tôi hoàn thành phần lớn công việc viết lách trước bữa sáng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_1_1_3', 'en-a1-1', 'ten_1_1', 'listening', 'listening', 'We practise English together while walking home from college.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã hỏi giá nhưng không ai trả lời.","Chúng tôi cùng nhau thực hành tiếng Anh trên đường đi bộ từ trường cao đẳng về nhà.","Tôi hoàn thành phần lớn công việc viết lách trước bữa sáng.","Một học sinh đã để quên ba lô dưới bàn học trong thư viện."]'::jsonb, 1, 'We practise English together while walking home from college. → Chúng tôi cùng nhau thực hành tiếng Anh trên đường đi bộ từ trường cao đẳng về nhà.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_1_2', 'en-a1-1', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_1_2_1', 'ten_1_2', 'library', 'Public libraries support lifelong learning by providing free access to books, digital resources, and quiet study spaces.', 'Public libraries support lifelong learning by providing free access to books, digital resources, and quiet study spaces.', '/ˈlaɪbreri/', 'Các thư viện công cộng hỗ trợ việc học tập suốt đời bằng cách cung cấp quyền truy cập miễn phí vào sách, tài nguyên số và không gian học tập yên tĩnh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_1_2_2', 'ten_1_2', 'writing', 'Regular writing practice helps students organise complex ideas and communicate their arguments more clearly.', 'Regular writing practice helps students organise complex ideas and communicate their arguments more clearly.', '/ˈraɪtɪŋ/', 'Thói quen luyện viết thường xuyên giúp học sinh sắp xếp các ý tưởng phức tạp và truyền đạt luận điểm của mình mạch lạc hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_1_2_3', 'ten_1_2', 'English', 'Learning English can widen access to international research and help students communicate across cultural boundaries.', 'Learning English can widen access to international research and help students communicate across cultural boundaries.', '/ˈɪŋɡlɪʃ/', 'Học tiếng Anh giúp mở rộng khả năng tiếp cận các nghiên cứu quốc tế và hỗ trợ học sinh giao tiếp vượt qua các rào cản văn hóa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_1_2_4', 'ten_1_2', 'student', 'Universities should ensure that every student can access affordable housing and appropriate support throughout their studies.', 'Universities should ensure that every student can access affordable housing and appropriate support throughout their studies.', '/ˈstuːdənt/', 'Các trường đại học nên đảm bảo mọi sinh viên đều có thể tiếp cận nhà ở có giá cả phải chăng và sự hỗ trợ phù hợp trong suốt quá trình học tập.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_1_2_5', 'ten_1_2', 'reading', 'Regular reading exposes students to varied vocabulary and helps them develop stronger critical thinking skills.', 'Regular reading exposes students to varied vocabulary and helps them develop stronger critical thinking skills.', '/ˈriːdɪŋ/', 'Việc thường xuyên đọc sách giúp học sinh tiếp cận với vốn từ vựng phong phú và phát triển kỹ năng tư duy phản biện tốt hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_1_2_6', 'ten_1_2', 'answer', 'Improving public transport may provide an answer to traffic congestion in rapidly growing urban areas.', 'Improving public transport may provide an answer to traffic congestion in rapidly growing urban areas.', '/ˈænsər/', 'Cải thiện giao thông công cộng có thể cung cấp giải pháp cho tình trạng tắc nghẽn giao thông ở các đô thị đang phát triển nhanh chóng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_1_2_1', 'en-a1-1', 'ten_1_2', 'listening', 'listening', 'Public libraries support lifelong learning by providing free access to books, digital resources, and quiet study spaces.', NULL, 'Trong câu vừa nghe, từ “library” mang nghĩa nào sau đây?', '["nơi; địa điểm; chốn","thư viện; phòng đọc","nghệ thuật; mỹ thuật","trẻ em; đứa trẻ"]'::jsonb, 1, '“library” (/ˈlaɪbreri/): thư viện; phòng đọc. Câu đầy đủ: Public libraries support lifelong learning by providing free access to books, digital resources, and quiet study spaces.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_1_2_2', 'en-a1-1', 'ten_1_2', 'listening', 'listening', 'Regular writing practice helps students organise complex ideas and communicate their arguments more clearly.', NULL, 'Trong câu vừa nghe, từ “writing” mang nghĩa nào sau đây?', '["khoẻ mạnh; vạm vỡ","khác; ngoài ra","chị gái; em gái","hoạt động viết; kỹ năng viết chữ"]'::jsonb, 3, '“writing” (/ˈraɪtɪŋ/): hoạt động viết; kỹ năng viết chữ. Câu đầy đủ: Regular writing practice helps students organise complex ideas and communicate their arguments more clearly.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
