INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_1_2', 'en-a1-1', NULL, 'comprehensive_test', 'listening', 'I do most of my writing before breakfast.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi hoàn thành phần lớn công việc viết lách trước bữa sáng.","Tôi cất bút chì trong ngăn kéo phía trên cùng của bàn làm việc.","Chúng tôi đã mua bánh mì tươi từ một tiệm bánh nhỏ kiểu Pháp.","Giáo viên của chúng tôi đã mang một cây đến lớp vào ngày hôm nay."]'::jsonb, 0, 'I do most of my writing before breakfast. → Tôi hoàn thành phần lớn công việc viết lách trước bữa sáng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_1_3', 'en-a1-1', NULL, 'comprehensive_test', 'listening', 'English', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bánh mì kẹp; sandwich","thanh âm; âm thanh","Tây Ban Nha","tiếng Anh"]'::jsonb, 3, 'English (/ˈɪŋɡlɪʃ/) → tiếng Anh; thuộc về nước Anh; thuộc về tiếng Anh', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_1_4', 'en-a1-1', NULL, 'comprehensive_test', 'listening', 'A student left her backpack under the library desk.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Giáo viên của chúng tôi giải thích ngữ pháp bằng cách sử dụng các ví dụ từ các cuộc hội thoại hàng ngày.","Một học sinh đã để quên ba lô dưới bàn học trong thư viện.","Chúng tôi đã mua bánh mì tươi từ một tiệm bánh nhỏ kiểu Pháp.","Tôi tra từ không quen thuộc đó trong từ điển."]'::jsonb, 1, 'A student left her backpack under the library desk. → Một học sinh đã để quên ba lô dưới bàn học trong thư viện.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
