INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_1_6', 'en-a1-1', NULL, 'comprehensive_test', 'listening', 'I asked the price, but nobody gave an answer.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã tham gia một khóa học nấu ăn tại trung tâm cộng đồng.","Bạn đã nói đúng về việc chìa khóa ở dưới ghế sofa.","Tôi đã hỏi giá nhưng không ai trả lời.","Tôi cất bút chì trong ngăn kéo phía trên cùng của bàn làm việc."]'::jsonb, 2, 'I asked the price, but nobody gave an answer. → Tôi đã hỏi giá nhưng không ai trả lời.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
