INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_1_18', 'en-a1-1', NULL, 'comprehensive_test', 'reading', NULL, 'Public libraries support lifelong learning by providing free access to books, digital resources, and quiet study spaces.', 'Dựa vào câu trên, từ “library” có nghĩa phù hợp nhất là gì?', '["cuộc họp, cuộc hội nghị khi mọi người tụ tập để thảo luận vấn đề gì","thời tiết","thư viện; phòng đọc","mười hai"]'::jsonb, 2, 'library: thư viện; phòng đọc; kho tài liệu; kho lưu trữ số. Dịch cả câu: Các thư viện công cộng hỗ trợ việc học tập suốt đời bằng cách cung cấp quyền truy cập miễn phí vào sách, tài nguyên số và không gian học tập yên tĩnh.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_1_19', 'en-a1-1', NULL, 'comprehensive_test', 'reading', NULL, 'Regular writing practice helps students organise complex ideas and communicate their arguments more clearly.', 'Dựa vào câu trên, từ “writing” có nghĩa phù hợp nhất là gì?', '["thẻ; thẻ cứng (dùng để thanh toán, định danh, thông tin)","khoẻ mạnh; vạm vỡ","hoạt động viết; kỹ năng viết chữ","địa lý học"]'::jsonb, 2, 'writing: hoạt động viết; kỹ năng viết chữ; chữ viết; nét chữ viết tay của ai đó; tác phẩm viết; bài viết; văn bản, đặc biệt là sách, bài báo hoặc tài liệu văn học. Dịch cả câu: Thói quen luyện viết thường xuyên giúp học sinh sắp xếp các ý tưởng phức tạp và truyền đạt luận điểm của mình mạch lạc hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_1_20', 'en-a1-1', NULL, 'comprehensive_test', 'reading', NULL, 'Learning English can widen access to international research and help students communicate across cultural boundaries.', 'Dựa vào câu trên, từ “English” có nghĩa phù hợp nhất là gì?', '["lửa; vụ cháy","rất; lắm","rạp chiếu phim; rạp chiếu bóng","tiếng Anh"]'::jsonb, 3, 'English: tiếng Anh; thuộc về nước Anh; thuộc về tiếng Anh. Dịch cả câu: Học tiếng Anh giúp mở rộng khả năng tiếp cận các nghiên cứu quốc tế và hỗ trợ học sinh giao tiếp vượt qua các rào cản văn hóa.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_1_21', 'en-a1-1', NULL, 'comprehensive_test', 'reading', NULL, 'Universities should ensure that every student can access affordable housing and appropriate support throughout their studies.', 'Dựa vào câu trên, từ “student” có nghĩa phù hợp nhất là gì?', '["hoàn thành; kết thúc; làm xong","gia nhập; tham gia","học sinh; sinh viên","vẽ; phác họa"]'::jsonb, 2, 'student: học sinh; sinh viên. Dịch cả câu: Các trường đại học nên đảm bảo mọi sinh viên đều có thể tiếp cận nhà ở có giá cả phải chăng và sự hỗ trợ phù hợp trong suốt quá trình học tập.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_1_22', 'en-a1-1', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lớp học; tiết học”', '["class","ruler","rain","single"]'::jsonb, 0, 'lớp học; tiết học → class (/klæs/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_1_23', 'en-a1-1', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “giấy”', '["finish","paper","left","juice"]'::jsonb, 1, 'giấy → paper (/ˈpeɪpər/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_1_24', 'en-a1-1', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đánh vần”', '["video","China","bus","spell"]'::jsonb, 3, 'đánh vần → spell (/spel/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-2', 'en', 'Bài 2: Giáo dục & Trường học (2) - CEFR A1', 'CEFR A1', 'A1 · Giáo dục', '24 từ vựng Tiếng Anh CEFR A1 chủ đề giáo dục & trường học kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1002, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_beginner', 'en-a1-2', 'beginner', '/bɪˈɡɪnər/', 'A1', 'người mới bắt đầu; người mới học', 'n.', 'begin (v.), beginning (n.)', 'Đồng nghĩa: novice, newcomer · Trái nghĩa: expert', 'beginner là danh từ đếm được, dạng số ít thường phải đi kèm mạo từ.', 'This swimming class is perfect for a complete beginner.', NULL, 'Lớp bơi này cực kỳ phù hợp cho những người hoàn toàn chưa biết gì.', '{"wordId":"beginner","ukIpa":"/bɪˈɡɪnə/","usIpa":"/bɪˈɡɪnər/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"someone who has just started learning or doing something","vi":"người mới bắt đầu; người mới học"}],"examples":[{"en":"This swimming class is perfect for a complete beginner.","vi":"Lớp bơi này cực kỳ phù hợp cho những người hoàn toàn chưa biết gì.","audioKind":"ex"},{"en":"Courses designed for beginners should provide clear guidance and regular opportunities to practise new skills.","vi":"Các khóa học dành cho người mới bắt đầu cần cung cấp hướng dẫn rõ ràng và cơ hội luyện tập thường xuyên để thành thạo kỹ năng mới.","audioKind":"ex2"}],"collocations":[{"en":"a complete beginner","vi":"người mới hoàn toàn"},{"en":"suitable for beginners","vi":"thích hợp cho người mới"},{"en":"a beginner''s guide","vi":"hướng dẫn vỡ lòng"}],"wordFamily":["begin (v.)","beginning (n.)"],"synonyms":["novice","newcomer"],"antonyms":["expert"],"tipVi":"beginner là danh từ đếm được, dạng số ít thường phải đi kèm mạo từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sentence', 'en-a1-2', 'sentence', '/ˈsentəns/', 'A1', 'câu; hình phạt; bản án; kết án; tuyên án', 'n.', 'sentencing (n.)', NULL, 'Phạt ai đó một hình phạt dùng sentence sb to sth.', 'Our teacher asked us to write one sentence about autumn.', NULL, 'Giáo viên yêu cầu chúng tôi viết một câu về mùa thu.', '{"wordId":"sentence","ukIpa":"/ˈsentəns/","usIpa":"/ˈsentəns/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"a group of words expressing a complete statement, question, or command","vi":"câu"},{"pos":"n.","en":"a punishment officially given by a court","vi":"hình phạt; bản án"},{"pos":"v.","en":"to officially give someone a punishment in court","vi":"kết án; tuyên án"}],"examples":[{"en":"Our teacher asked us to write one sentence about autumn.","vi":"Giáo viên yêu cầu chúng tôi viết một câu về mùa thu.","audioKind":"ex"},{"en":"Learning to vary sentence length can help students express complex ideas more clearly in academic essays.","vi":"Việc học cách thay đổi độ dài câu có thể giúp học sinh diễn đạt các ý tưởng phức tạp một cách rõ ràng hơn trong các bài luận học thuật.","audioKind":"ex2"}],"collocations":[{"en":"complete sentence","vi":"câu hoàn chỉnh"},{"en":"sentence structure","vi":"cấu trúc câu"},{"en":"prison sentence","vi":"bản án tù"},{"en":"sentence someone to","vi":"kết án ai đó tội"}],"wordFamily":["sentencing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Phạt ai đó một hình phạt dùng sentence sb to sth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_homework', 'en-a1-2', 'homework', '/ˈhoʊmwɝːk/', 'A1', 'bài tập về nhà; việc chuẩn bị trước; công tác chuẩn bị', 'n.', NULL, NULL, 'Danh từ không đếm được; một bài tập về nhà dùng a piece of homework.', 'I finished my homework before dinner and went outside.', NULL, 'Tôi đã làm xong bài tập về nhà trước bữa tối và đi ra ngoài.', '{"wordId":"homework","ukIpa":"/ˈhəʊmwɜːk/","usIpa":"/ˈhoʊmwɝːk/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"Schoolwork that students are asked to complete outside lessons.","vi":"bài tập về nhà"},{"pos":"n.","en":"Research or preparation done before making a decision.","vi":"việc chuẩn bị trước; công tác chuẩn bị"}],"examples":[{"en":"I finished my homework before dinner and went outside.","vi":"Tôi đã làm xong bài tập về nhà trước bữa tối và đi ra ngoài.","audioKind":"ex"},{"en":"Schools should limit homework so that children have enough time for exercise and family activities.","vi":"Các trường học nên giới hạn bài tập về nhà để trẻ em có đủ thời gian tập thể dục và tham gia các hoạt động gia đình.","audioKind":"ex2"}],"collocations":[{"en":"do homework","vi":"làm bài tập về nhà"},{"en":"hand in homework","vi":"nộp bài tập về nhà"},{"en":"do your homework","vi":"chuẩn bị kỹ bài vở"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ không đếm được; một bài tập về nhà dùng a piece of homework.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_read', 'en-a1-2', 'read', '/riːd/', 'A1', 'đọc; đọc hiểu; đọc thành tiếng; đọc hiểu; giải mã (thông tin)', 'v.', 'reader (n.), reading (n.), readable (adj.), unread (adj.)', NULL, 'Nguyên thể đọc là /riːd/; quá khứ và quá khứ phân từ đọc là /red/.', 'I read a few pages before bed every night.', NULL, 'Tôi đọc vài trang sách trước khi đi ngủ mỗi tối.', '{"wordId":"read","ukIpa":"/riːd/","usIpa":"/riːd/","cefr":"A1","topic":"education","senses":[{"pos":"v.","en":"to look at written words and understand their meaning","vi":"đọc; đọc hiểu"},{"pos":"v.","en":"to say written words aloud","vi":"đọc thành tiếng"},{"pos":"v.","en":"to understand information shown by something","vi":"đọc hiểu; giải mã (thông tin)"}],"examples":[{"en":"I read a few pages before bed every night.","vi":"Tôi đọc vài trang sách trước khi đi ngủ mỗi tối.","audioKind":"ex"},{"en":"Children who read regularly often develop stronger language skills and a broader understanding of the world.","vi":"Trẻ em đọc sách thường xuyên thường phát triển kỹ năng ngôn ngữ tốt hơn và có hiểu biết rộng hơn về thế giới.","audioKind":"ex2"}],"collocations":[{"en":"read aloud","vi":"đọc to"},{"en":"read a map","vi":"đọc bản đồ"},{"en":"read widely","vi":"đọc rộng; đọc nhiều sách"}],"wordFamily":["reader (n.)","reading (n.)","readable (adj.)","unread (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nguyên thể đọc là /riːd/; quá khứ và quá khứ phân từ đọc là /red/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_test', 'en-a1-2', 'test', '/test/', 'A1', 'bài kiểm tra; bài trắc nghiệm; sự xét nghiệm; kiểm tra; trắc nghiệm; xét nghiệm', 'n.', 'testing (n.), tester (n.), testable (adj.)', 'Đồng nghĩa: examination, assessment', 'Tham gia bài kiểm tra dùng take a test; vượt qua bài kiểm tra dùng pass a test.', 'I have a spelling test at school tomorrow.', NULL, 'Tôi có bài kiểm tra chính tả ở trường vào ngày mai.', '{"wordId":"test","ukIpa":"/test/","usIpa":"/test/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"a procedure that checks knowledge, ability, condition, or performance","vi":"bài kiểm tra; bài trắc nghiệm; sự xét nghiệm"},{"pos":"v.","en":"to check what someone knows or how something performs","vi":"kiểm tra; trắc nghiệm; xét nghiệm"}],"examples":[{"en":"I have a spelling test at school tomorrow.","vi":"Tôi có bài kiểm tra chính tả ở trường vào ngày mai.","audioKind":"ex"},{"en":"Researchers must test new materials under different conditions before recommending their use in public buildings.","vi":"Các nhà nghiên cứu phải kiểm tra vật liệu mới trong các điều kiện khác nhau trước khi khuyến nghị sử dụng chúng trong các công trình công cộng.","audioKind":"ex2"}],"collocations":[{"en":"take a test","vi":"làm bài kiểm tra"},{"en":"blood test","vi":"xét nghiệm máu"},{"en":"test a theory","vi":"kiểm tra một lý thuyết"},{"en":"test results","vi":"kết quả kiểm tra"}],"wordFamily":["testing (n.)","tester (n.)","testable (adj.)"],"synonyms":["examination","assessment"],"antonyms":[],"tipVi":"Tham gia bài kiểm tra dùng take a test; vượt qua bài kiểm tra dùng pass a test.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lesson', 'en-a1-2', 'lesson', '/ˈlesən/', 'A1', 'tiết học; bài học; bài học (kinh nghiệm từ sai lầm hoặc trải nghiệm)', 'n.', NULL, NULL, 'learn a lesson thường mang nghĩa rút ra bài học kinh nghiệm, không chỉ là học kiến thức trên lớp.', 'Our swimming lesson starts after school on Thursday.', NULL, 'Tiết học bơi của chúng tôi bắt đầu sau giờ học vào thứ Năm.', '{"wordId":"lesson","ukIpa":"/ˈlesən/","usIpa":"/ˈlesən/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"A period of teaching or learning a particular subject.","vi":"tiết học; bài học"},{"pos":"n.","en":"Something useful learned from an experience, especially a mistake.","vi":"bài học (kinh nghiệm từ sai lầm hoặc trải nghiệm)"}],"examples":[{"en":"Our swimming lesson starts after school on Thursday.","vi":"Tiết học bơi của chúng tôi bắt đầu sau giờ học vào thứ Năm.","audioKind":"ex"},{"en":"A key lesson from previous environmental policies is that effective regulation requires consistent monitoring and public support.","vi":"Một bài học quan trọng từ các chính sách môi trường trước đây là quy định hiệu quả đòi hỏi sự giám sát liên tục và sự ủng hộ của công chúng.","audioKind":"ex2"}],"collocations":[{"en":"take lessons","vi":"tham gia các bài học"},{"en":"piano lesson","vi":"tiết học piano"},{"en":"learn a lesson","vi":"rút kinh nghiệm"},{"en":"a valuable lesson","vi":"một bài học đắt giá"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"learn a lesson thường mang nghĩa rút ra bài học kinh nghiệm, không chỉ là học kiến thức trên lớp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_geography', 'en-a1-2', 'geography', '/dʒiˈɑːɡrəfi/', 'A1', 'địa lý học; địa hình; đặc điểm địa lý', 'n.', 'geographer (n.), geographical (adj.), geographically (adv.)', NULL, 'geography là môn địa lý; geology là môn địa chất học.', 'In geography today, we learned how rivers shape valleys.', NULL, 'Trong tiết địa lý hôm nay, chúng tôi đã học cách các dòng sông tạo hình thung lũng.', '{"wordId":"geography","ukIpa":"/dʒiˈɒɡrəfi/","usIpa":"/dʒiˈɑːɡrəfi/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"the study of Earth''s places, environments, and human activity","vi":"địa lý học"},{"pos":"n.","en":"the physical features and arrangement of a particular area","vi":"địa hình; đặc điểm địa lý"}],"examples":[{"en":"In geography today, we learned how rivers shape valleys.","vi":"Trong tiết địa lý hôm nay, chúng tôi đã học cách các dòng sông tạo hình thung lũng.","audioKind":"ex"},{"en":"The geography of coastal regions influences settlement patterns and determines how communities respond to rising sea levels.","vi":"Đặc điểm địa lý của các vùng ven biển chi phối các mô hình định cư và quyết định cách các cộng đồng ứng phó với mực nước biển dâng.","audioKind":"ex2"}],"collocations":[{"en":"physical geography","vi":"địa lý tự nhiên"},{"en":"human geography","vi":"địa lý nhân văn"},{"en":"study geography","vi":"nghiên cứu địa lý"}],"wordFamily":["geographer (n.)","geographical (adj.)","geographically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"geography là môn địa lý; geology là môn địa chất học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_teach', 'en-a1-2', 'teach', '/tiːtʃ/', 'A1', 'dạy; giảng dạy; chỉ bảo', 'v.', 'teacher (n.), teaching (n.), teachable (adj.)', 'Đồng nghĩa: instruct, educate', 'Dạng quá khứ và quá khứ phân tư đều là taught; dạy ai đó làm gì dùng teach sb to do.', 'My aunt taught me how to mend a shirt.', NULL, 'Cô của tôi đã dạy tôi cách khâu vá một chiếc áo sơ mi.', '{"wordId":"teach","ukIpa":"/tiːtʃ/","usIpa":"/tiːtʃ/","cefr":"A1","topic":"education","senses":[{"pos":"v.","en":"Help someone learn knowledge, skills, or ways of behaving","vi":"dạy; giảng dạy; chỉ bảo"}],"examples":[{"en":"My aunt taught me how to mend a shirt.","vi":"Cô của tôi đã dạy tôi cách khâu vá một chiếc áo sơ mi.","audioKind":"ex"},{"en":"Schools should teach children how to evaluate online information rather than simply memorise facts.","vi":"Các trường học nên dạy trẻ em cách đánh giá thông tin trực tuyến thay vì chỉ học thuộc lòng các sự kiện.","audioKind":"ex2"}],"collocations":[{"en":"teach a subject","vi":"dạy một môn học"},{"en":"teach someone to swim","vi":"dạy ai đó bơi"},{"en":"teach a lesson","vi":"dạy một bài học; cho một bài học"}],"wordFamily":["teacher (n.)","teaching (n.)","teachable (adj.)"],"synonyms":["instruct","educate"],"antonyms":[],"tipVi":"Dạng quá khứ và quá khứ phân tư đều là taught; dạy ai đó làm gì dùng teach sb to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_classroom', 'en-a1-2', 'classroom', '/ˈklæsruːm/', 'A1', 'phòng học, lớp học nơi học sinh được giảng dạy', 'n.', 'class (n.)', NULL, 'in the classroom nhấn mạnh không gian bên trong phòng học; in class nhấn mạnh quá trình đang học tập trên lớp.', 'Sunlight filled the classroom as we opened our books.', NULL, 'Ánh sáng mặt trời tràn ngập căn phòng học khi chúng tôi mở sách ra.', '{"wordId":"classroom","ukIpa":"/ˈklɑːsruːm/","usIpa":"/ˈklæsruːm/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"a room where students are taught","vi":"phòng học, lớp học nơi học sinh được giảng dạy"}],"examples":[{"en":"Sunlight filled the classroom as we opened our books.","vi":"Ánh sáng mặt trời tràn ngập căn phòng học khi chúng tôi mở sách ra.","audioKind":"ex"},{"en":"A well-designed classroom should provide adequate lighting, comfortable furniture, and enough space for students to work together.","vi":"Một phòng học được thiết kế tốt cần cung cấp đầy đủ ánh sáng, nội thất thoải mái và đủ không gian để học sinh làm việc nhóm.","audioKind":"ex2"}],"collocations":[{"en":"classroom management","vi":"quản lý lớp học"},{"en":"classroom activities","vi":"hoạt động trong lớp học"},{"en":"classroom teaching","vi":"giảng dạy trên lớp"}],"wordFamily":["class (n.)"],"synonyms":[],"antonyms":[],"tipVi":"in the classroom nhấn mạnh không gian bên trong phòng học; in class nhấn mạnh quá trình đang học tập trên lớp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_repeat', 'en-a1-2', 'repeat', '/rɪˈpiːt/', 'A1', 'lặp lại; nói lại; làm lại; sự lặp lại; sự phát lại', 'v.', 'repetition (n.), repetitive (adj.), repeatedly (adv.), repeatable (adj.)', NULL, 'repeat đã hàm ý "lại", thông thường không cần dùng thêm again.', 'Could you repeat the address a little more slowly?', NULL, 'Bạn có thể đọc lại địa chỉ đó chậm hơn một chút được không?', '{"wordId":"repeat","ukIpa":"/rɪˈpiːt/","usIpa":"/rɪˈpiːt/","cefr":"A1","topic":"education","senses":[{"pos":"v.","en":"To say or do something again.","vi":"lặp lại; nói lại; làm lại"},{"pos":"n.","en":"Something that happens or is shown again.","vi":"sự lặp lại; sự phát lại"}],"examples":[{"en":"Could you repeat the address a little more slowly?","vi":"Bạn có thể đọc lại địa chỉ đó chậm hơn một chút được không?","audioKind":"ex"},{"en":"Students who repeat new vocabulary aloud regularly may develop greater confidence when speaking a foreign language.","vi":"Những học sinh thường xuyên phát âm lại các từ vựng mới một cách thành tiếng có thể trở nên tự tin hơn khi nói ngoại ngữ.","audioKind":"ex2"}],"collocations":[{"en":"repeat a mistake","vi":"lặp lại một lỗi sai"},{"en":"repeat a question","vi":"nhắc lại một câu hỏi"},{"en":"repeat after someone","vi":"nói theo sau ai đó"},{"en":"a repeat performance","vi":"một buổi biểu diễn lại"}],"wordFamily":["repetition (n.)","repetitive (adj.)","repeatedly (adv.)","repeatable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"repeat đã hàm ý \"lại\", thông thường không cần dùng thêm again.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_example', 'en-a1-2', 'example', '/ɪɡˈzæmpl/', 'A1', 'ví dụ; dẫn chứng; tấm gương; gương sáng', 'n.', 'exemplify (v.), exemplary (adj.)', 'Đồng nghĩa: instance, illustration', 'for example dùng để đưa ra ví dụ; set an example có nghĩa là làm gương.', 'Could you give me an example of a healthy breakfast?', NULL, 'Bạn có thể cho tôi một ví dụ về bữa sáng lành mạnh được không?', '{"wordId":"example","ukIpa":"/ɪɡˈzɑːmpl/","usIpa":"/ɪɡˈzæmpl/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"Something specific that shows what a general idea means","vi":"ví dụ; dẫn chứng"},{"pos":"n.","en":"A person or action that others can learn from or copy","vi":"tấm gương; gương sáng"}],"examples":[{"en":"Could you give me an example of a healthy breakfast?","vi":"Bạn có thể cho tôi một ví dụ về bữa sáng lành mạnh được không?","audioKind":"ex"},{"en":"Public buildings can set an example by using renewable energy and reducing unnecessary water consumption.","vi":"Các tòa nhà công cộng có thể làm gương bằng cách sử dụng năng lượng tái tạo và giảm thiểu lượng nước tiêu thụ không cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"for example","vi":"ví dụ như"},{"en":"give an example","vi":"đưa ra ví dụ"},{"en":"set an example","vi":"làm gương; nêu gương"},{"en":"a typical example","vi":"một ví dụ điển hình"}],"wordFamily":["exemplify (v.)","exemplary (adj.)"],"synonyms":["instance","illustration"],"antonyms":[],"tipVi":"for example dùng để đưa ra ví dụ; set an example có nghĩa là làm gương.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_note', 'en-a1-2', 'note', '/noʊt/', 'A1', 'mẩu giấy nhắn; ghi chú; lưu ý; ghi chép; nốt nhạc; âm', 'n.', 'notable (adj.), noted (adj.), noteworthy (adj.)', NULL, 'Ghi chép dùng take notes; sau note that cần có mệnh đề đầy đủ.', 'I left a note beside your breakfast bowl.', NULL, 'Tôi để lại một mẩu giấy nhắn cạnh bát ăn sáng của bạn.', '{"wordId":"note","ukIpa":"/nəʊt/","usIpa":"/noʊt/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"A short written message or record of useful information.","vi":"mẩu giấy nhắn; ghi chú"},{"pos":"v.","en":"To notice something or record it in writing.","vi":"lưu ý; ghi chép"},{"pos":"n.","en":"A single musical sound or a symbol representing it.","vi":"nốt nhạc; âm"}],"examples":[{"en":"I left a note beside your breakfast bowl.","vi":"Tôi để lại một mẩu giấy nhắn cạnh bát ăn sáng của bạn.","audioKind":"ex"},{"en":"Students who take notes in their own words may develop a deeper understanding of complex material.","vi":"Học sinh tự ghi chép bằng ngôn ngữ của riêng mình có thể hiểu sâu sắc hơn về tài liệu phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"take notes","vi":"ghi chép"},{"en":"leave a note","vi":"để lại lời nhắn"},{"en":"note that","vi":"lưu ý rằng"},{"en":"musical note","vi":"nốt nhạc"}],"wordFamily":["notable (adj.)","noted (adj.)","noteworthy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Ghi chép dùng take notes; sau note that cần có mệnh đề đầy đủ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alphabet', 'en-a1-2', 'alphabet', '/ˈælfəbet/', 'A1', 'bảng chữ cái', 'n.', 'alphabetical (adj.), alphabetically (adv.)', NULL, 'alphabet chỉ toàn bộ bảng chữ cái; một chữ cái riêng lẻ dùng letter.', 'My little sister learned the alphabet through a song.', NULL, 'Em gái tôi học bảng chữ cái thông qua một bài hát.', '{"wordId":"alphabet","ukIpa":"/ˈælfəbet/","usIpa":"/ˈælfəbet/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"the complete set of letters used in a language","vi":"bảng chữ cái"}],"examples":[{"en":"My little sister learned the alphabet through a song.","vi":"Em gái tôi học bảng chữ cái thông qua một bài hát.","audioKind":"ex"},{"en":"Learning the alphabet is an important early step towards literacy, but children also need regular reading practice.","vi":"Học bảng chữ cái là bước đầu quan trọng hướng tới việc biết đọc biết viết, nhưng trẻ em cũng cần luyện tập đọc thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"the English alphabet","vi":"bảng chữ cái tiếng Anh"},{"en":"learn the alphabet","vi":"học bảng chữ cái"},{"en":"alphabet song","vi":"bài hát bảng chữ cái"}],"wordFamily":["alphabetical (adj.)","alphabetically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"alphabet chỉ toàn bộ bảng chữ cái; một chữ cái riêng lẻ dùng letter.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pencil', 'en-a1-2', 'pencil', '/ˈpensl/', 'A1', 'bút chì; viết bằng bút chì; vẽ bằng bút chì', 'n.', NULL, NULL, 'Viết bằng bút chì dùng "in pencil"; "pencil in" chỉ việc tạm định lịch trình.', 'She sharpened her pencil before sketching the sleeping cat.', NULL, 'Cô ấy gọt bút chì trước khi phác họa con mèo đang ngủ.', '{"wordId":"pencil","ukIpa":"/ˈpensl/","usIpa":"/ˈpensl/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"A tool with a solid core for writing or drawing.","vi":"bút chì"},{"pos":"v.","en":"To write or draw something with a pencil.","vi":"viết bằng bút chì; vẽ bằng bút chì"}],"examples":[{"en":"She sharpened her pencil before sketching the sleeping cat.","vi":"Cô ấy gọt bút chì trước khi phác họa con mèo đang ngủ.","audioKind":"ex"},{"en":"Using a pencil allows students to revise diagrams easily as their understanding of scientific concepts develops.","vi":"Việc sử dụng bút chì giúp học sinh dễ dàng sửa chữa các sơ đồ khi hiểu biết của các em về các khái niệm khoa học phát triển hơn.","audioKind":"ex2"}],"collocations":[{"en":"sharpen a pencil","vi":"gọt bút chì"},{"en":"in pencil","vi":"viết bằng bút chì"},{"en":"coloured pencil","vi":"bút chì màu"},{"en":"pencil case","vi":"hộp bút chì"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Viết bằng bút chì dùng \"in pencil\"; \"pencil in\" chỉ việc tạm định lịch trình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_college', 'en-a1-2', 'college', '/ˈkɑːlɪdʒ/', 'A1', 'trường cao đẳng; cơ sở giáo dục đại học; trường thành viên; phân khoa đại học', 'n.', 'collegiate (adj.)', NULL, 'Ở Mỹ thường chỉ chung bậc đại học; ở Anh thường chỉ trường cao đẳng hoặc cơ sở giáo dục tiếp tục.', 'My cousin is studying nursing at a local college.', NULL, 'Anh họ của tôi đang học ngành điều dưỡng tại một trường cao đẳng địa phương.', '{"wordId":"college","ukIpa":"/ˈkɒlɪdʒ/","usIpa":"/ˈkɑːlɪdʒ/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"An institution offering education beyond school, including practical or academic courses.","vi":"trường cao đẳng; cơ sở giáo dục đại học"},{"pos":"n.","en":"A constituent institution or division within a university.","vi":"trường thành viên; phân khoa đại học"}],"examples":[{"en":"My cousin is studying nursing at a local college.","vi":"Anh họ của tôi đang học ngành điều dưỡng tại một trường cao đẳng địa phương.","audioKind":"ex"},{"en":"Making college education more affordable could improve social mobility and provide employers with a more skilled workforce.","vi":"Việc làm cho giáo dục đại học trở nên dễ tiếp cận hơn về mặt chi phí có thể thúc đẩy sự dịch chuyển xã hội và cung cấp cho người sử dụng lao động nguồn nhân lực có tay nghề cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"go to college","vi":"đi học đại học"},{"en":"college student","vi":"sinh viên cao đẳng; sinh viên đại học"},{"en":"college education","vi":"giáo dục đại học"},{"en":"community college","vi":"trường cao đẳng cộng đồng"}],"wordFamily":["collegiate (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Ở Mỹ thường chỉ chung bậc đại học; ở Anh thường chỉ trường cao đẳng hoặc cơ sở giáo dục tiếp tục.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_describe', 'en-a1-2', 'describe', '/dɪˈskraɪb/', 'A1', 'miêu tả; mô tả', 'v.', 'description (n.), descriptive (adj.)', 'Đồng nghĩa: portray, depict', 'Dùng describe something to someone, không dùng describe someone something.', 'Can you describe the bag you left on the bus?', NULL, 'Bạn có thể mô tả chiếc túi mà bạn để quên trên xe buýt không?', '{"wordId":"describe","ukIpa":"/dɪˈskraɪb/","usIpa":"/dɪˈskraɪb/","cefr":"A1","topic":"education","senses":[{"pos":"v.","en":"to explain what someone or something is like","vi":"miêu tả; mô tả"}],"examples":[{"en":"Can you describe the bag you left on the bus?","vi":"Bạn có thể mô tả chiếc túi mà bạn để quên trên xe buýt không?","audioKind":"ex"},{"en":"The report describes how access to public parks influences physical activity among residents of crowded cities.","vi":"Báo cáo này mô tả cách khả năng tiếp cận các công viên công cộng ảnh hưởng đến hoạt động thể chất của cư dân ở các thành phố đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"describe something in detail","vi":"miêu tả cái gì đó chi tiết"},{"en":"describe something as","vi":"mô tả cái gì như là"},{"en":"describe a process","vi":"mô tả một quá trình"}],"wordFamily":["description (n.)","descriptive (adj.)"],"synonyms":["portray","depict"],"antonyms":[],"tipVi":"Dùng describe something to someone, không dùng describe someone something.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_language', 'en-a1-2', 'language', '/ˈlæŋɡwɪdʒ/', 'A1', 'ngôn ngữ; lời ăn tiếng nói; phong cách diễn đạt', 'n.', NULL, NULL, 'Chỉ một thứ tiếng cụ thể thì đếm được; chỉ khả năng ngôn ngữ chung thì thường không đếm được.', 'My neighbour teaches me a little of her language.', NULL, 'Hàng xóm dạy tôi một chút ngôn ngữ của cô ấy.', '{"wordId":"language","ukIpa":"/ˈlæŋɡwɪdʒ/","usIpa":"/ˈlæŋɡwɪdʒ/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"a system of words or gestures used for communication","vi":"ngôn ngữ"},{"pos":"n.","en":"the words and style used in a particular context","vi":"lời ăn tiếng nói; phong cách diễn đạt"}],"examples":[{"en":"My neighbour teaches me a little of her language.","vi":"Hàng xóm dạy tôi một chút ngôn ngữ của cô ấy.","audioKind":"ex"},{"en":"Learning a foreign language can broaden students'' cultural understanding and improve their future employment prospects.","vi":"Học ngoại ngữ có thể mở rộng hiểu biết văn hóa của học sinh và cải thiện triển vọng việc làm trong tương lai.","audioKind":"ex2"}],"collocations":[{"en":"foreign language","vi":"ngoại ngữ"},{"en":"body language","vi":"ngôn ngữ cơ thể"},{"en":"language barrier","vi":"rào cản ngôn ngữ"},{"en":"formal language","vi":"ngôn ngữ trang trọng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ một thứ tiếng cụ thể thì đếm được; chỉ khả năng ngôn ngữ chung thì thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_write', 'en-a1-2', 'write', '/raɪt/', 'A1', 'v. viết; ghi chữ; v. sáng tác; viết; v. viết thư', 'v.', 'writer (n.), writing (n.), rewrite (v.)', NULL, 'Bất quy tắc: write—wrote—written.', 'Please write your address on this small card.', NULL, 'Vui lòng viết địa chỉ của bạn lên tấm thẻ nhỏ này.', '{"wordId":"write","ukIpa":"/raɪt/","usIpa":"/raɪt/","cefr":"A1","topic":"education","senses":[{"pos":"v.","en":"To form words on paper or a screen.","vi":"v. viết; ghi chữ"},{"pos":"v.","en":"To create a story, article, or piece of music.","vi":"v. sáng tác; viết"},{"pos":"v.","en":"To send someone a letter or written message.","vi":"v. viết thư"}],"examples":[{"en":"Please write your address on this small card.","vi":"Vui lòng viết địa chỉ của bạn lên tấm thẻ nhỏ này.","audioKind":"ex"},{"en":"Students who write regularly often develop stronger reasoning skills and express complex ideas more clearly.","vi":"Những học sinh thường xuyên viết lách thường phát triển kỹ năng tư duy sắc bén hơn và diễn đạt các ý tưởng phức tạp một cách mạch lạc hơn.","audioKind":"ex2"}],"collocations":[{"en":"write an essay","vi":"viết một bài luận"},{"en":"write to someone","vi":"viết thư cho ai đó"},{"en":"write down","vi":"viết ra; ghi chép lại"}],"wordFamily":["writer (n.)","writing (n.)","rewrite (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Bất quy tắc: write—wrote—written.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spanish', 'en-a1-2', 'Spanish', '/ˈspænɪʃ/', 'A1', 'n. tiếng Tây Ban Nha; adj. thuộc Tây Ban Nha; bằng tiếng Tây Ban Nha', 'n.', NULL, NULL, 'Viết hoa chữ cái đầu; một người Tây Ban Nha dùng a Spanish person.', 'I practise Spanish with my neighbour after dinner.', NULL, 'Tôi tập nói tiếng Tây Ban Nha với hàng xóm sau bữa tối.', '{"wordId":"spanish","ukIpa":"/ˈspænɪʃ/","usIpa":"/ˈspænɪʃ/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"the language spoken in Spain and many Latin American countries","vi":"n. tiếng Tây Ban Nha"},{"pos":"adj.","en":"relating to Spain, its people, culture, or language","vi":"adj. thuộc Tây Ban Nha; bằng tiếng Tây Ban Nha"}],"examples":[{"en":"I practise Spanish with my neighbour after dinner.","vi":"Tôi tập nói tiếng Tây Ban Nha với hàng xóm sau bữa tối.","audioKind":"ex"},{"en":"Learning Spanish can broaden students'' access to literature and improve their opportunities for international employment.","vi":"Học tiếng Tây Ban Nha có thể mở rộng khả năng tiếp cận các tác phẩm văn học của học sinh và cải thiện cơ hội việc làm quốc tế.","audioKind":"ex2"}],"collocations":[{"en":"speak Spanish","vi":"nói tiếng Tây Ban Nha"},{"en":"Spanish culture","vi":"văn hóa Tây Ban Nha"},{"en":"Spanish-speaking countries","vi":"các quốc gia nói tiếng Tây Ban Nha"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Viết hoa chữ cái đầu; một người Tây Ban Nha dùng a Spanish person.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_book', 'en-a1-2', 'book', '/bʊk/', 'A1', 'sách; quyển sách; đặt trước; giữ chỗ', 'n.', 'booking (n.), booklet (n.)', 'Đồng nghĩa: reserve', 'book khi là động từ có nghĩa là đặt chỗ trước, có thể đi trực tiếp với phòng, vé máy bay, v.v.', 'I left my book on the kitchen table.', NULL, 'Tôi để quên cuốn sách của mình trên bàn bếp.', '{"wordId":"book","ukIpa":"/bʊk/","usIpa":"/bʊk/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"A set of pages joined together for reading","vi":"sách; quyển sách"},{"pos":"v.","en":"To arrange in advance to use a service or attend something","vi":"đặt trước; giữ chỗ"}],"examples":[{"en":"I left my book on the kitchen table.","vi":"Tôi để quên cuốn sách của mình trên bàn bếp.","audioKind":"ex"},{"en":"Public libraries provide free access to books, helping people continue learning regardless of their income.","vi":"Các thư viện công cộng cung cấp quyền đọc sách miễn phí, giúp mọi người tiếp tục học tập bất kể thu nhập của họ ra sao.","audioKind":"ex2"}],"collocations":[{"en":"read a book","vi":"đọc sách"},{"en":"borrow a book","vi":"mượn sách"},{"en":"book a flight","vi":"đặt vé máy bay"},{"en":"book an appointment","vi":"đặt lịch hẹn"}],"wordFamily":["booking (n.)","booklet (n.)"],"synonyms":["reserve"],"antonyms":[],"tipVi":"book khi là động từ có nghĩa là đặt chỗ trước, có thể đi trực tiếp với phòng, vé máy bay, v.v.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hundred', 'en-a1-2', 'hundred', '/ˈhʌndrəd/', 'A1', 'một trăm', 'num.', 'hundredth (num.)', NULL, 'Dùng hundred sau các số đếm cụ thể; dùng hundreds of để chỉ số lượng hàng trăm (hàng loạt) không xác định.', 'The hall can hold about a hundred people.', NULL, 'Phòng hội lớn có thể chứa khoảng một trăm người.', '{"wordId":"hundred","ukIpa":"/ˈhʌndrəd/","usIpa":"/ˈhʌndrəd/","cefr":"A1","topic":"education","senses":[{"pos":"num.","en":"the number equal to ten times ten","vi":"một trăm"}],"examples":[{"en":"The hall can hold about a hundred people.","vi":"Phòng hội lớn có thể chứa khoảng một trăm người.","audioKind":"ex"},{"en":"Several hundred residents participated in the survey about proposed improvements to local parks and cycle routes.","vi":"Hàng trăm cư dân đã tham gia cuộc khảo sát về các đề xuất cải tạo công viên địa phương và tuyến đường xe đạp.","audioKind":"ex2"}],"collocations":[{"en":"a hundred people","vi":"một trăm người"},{"en":"two hundred","vi":"hai trăm"},{"en":"hundreds of","vi":"hàng trăm"}],"wordFamily":["hundredth (num.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng hundred sau các số đếm cụ thể; dùng hundreds of để chỉ số lượng hàng trăm (hàng loạt) không xác định.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dictionary', 'en-a1-2', 'dictionary', '/ˈdɪkʃəneri/', 'A1', 'từ điển', 'n.', NULL, NULL, 'Cấu trúc tra từ trong từ điển là look up a word in a dictionary.', 'I checked the pronunciation of this word in a dictionary.', NULL, 'Tôi đã tra cách phát âm của từ này trong từ điển.', '{"wordId":"dictionary","ukIpa":"/ˈdɪkʃənəri/","usIpa":"/ˈdɪkʃəneri/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"a resource listing words with their meanings, pronunciations, or translations","vi":"từ điển"}],"examples":[{"en":"I checked the pronunciation of this word in a dictionary.","vi":"Tôi đã tra cách phát âm của từ này trong từ điển.","audioKind":"ex"},{"en":"Using a bilingual dictionary can help language learners understand unfamiliar vocabulary without relying entirely on their teachers.","vi":"Sử dụng từ điển song ngữ có thể giúp người học ngôn ngữ hiểu các từ vựng lạ mà không cần phụ thuộc hoàn toàn vào giáo viên.","audioKind":"ex2"}],"collocations":[{"en":"bilingual dictionary","vi":"từ điển song ngữ"},{"en":"online dictionary","vi":"từ điển trực tuyến"},{"en":"consult a dictionary","vi":"tra cứu từ điển"},{"en":"dictionary entry","vi":"mục từ điển"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc tra từ trong từ điển là look up a word in a dictionary.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_university', 'en-a1-2', 'university', '/ˌjuːnɪˈvɜːrsəti/', 'A1', 'trường đại học', 'n.', NULL, NULL, 'Dùng a university thay vì an, vì âm đầu phát ra là phụ âm /j/.', 'My sister studies engineering at a university near home.', NULL, 'Chị gái tôi học ngành kỹ thuật tại một trường đại học gần nhà.', '{"wordId":"university","ukIpa":"/ˌjuːnɪˈvɜːsəti/","usIpa":"/ˌjuːnɪˈvɜːrsəti/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"an institution offering degree courses and conducting advanced research","vi":"trường đại học"}],"examples":[{"en":"My sister studies engineering at a university near home.","vi":"Chị gái tôi học ngành kỹ thuật tại một trường đại học gần nhà.","audioKind":"ex"},{"en":"Governments should improve access to university so that talented students are not excluded by financial barriers.","vi":"Chính phủ nên mở rộng cơ hội tiếp cận giáo dục đại học để những học sinh tài năng không bị rào cản tài chính tước đi cơ hội.","audioKind":"ex2"}],"collocations":[{"en":"go to university","vi":"đi học đại học"},{"en":"university degree","vi":"bằng đại học"},{"en":"university campus","vi":"khiêm túc"},{"en":"university tuition fees","vi":"học phí đại học"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dùng a university thay vì an, vì âm đầu phát ra là phụ âm /j/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eraser', 'en-a1-2', 'eraser', '/ɪˈreɪsər/', 'A1', 'cục tẩy; gôm', 'n.', 'erase (v.), erasure (n.)', 'Đồng nghĩa: rubber', 'eraser thường được dùng trong tiếng Anh-Mỹ; trong khi tiếng Anh-Anh thường dùng từ rubber.', 'I borrowed an eraser to correct my pencil drawing.', NULL, 'Tôi đã mượn một cục tẩy để sửa lại bản vẽ chì của mình.', '{"wordId":"eraser","ukIpa":"/ɪˈreɪzə/","usIpa":"/ɪˈreɪsər/","cefr":"A1","topic":"education","senses":[{"pos":"n.","en":"A small object used to remove pencil marks.","vi":"cục tẩy; gôm"}],"examples":[{"en":"I borrowed an eraser to correct my pencil drawing.","vi":"Tôi đã mượn một cục tẩy để sửa lại bản vẽ chì của mình.","audioKind":"ex"},{"en":"Providing basic classroom supplies, including pencils and erasers, helps ensure that all children can participate in lessons.","vi":"Việc cung cấp các dụng cụ học tập cơ bản như bút chì và cục tẩy giúp đảm bảo mọi trẻ em đều có thể tham gia vào các bài học.","audioKind":"ex2"}],"collocations":[{"en":"a pencil eraser","vi":"cục tẩy bút chì"},{"en":"use an eraser","vi":"dùng cục tẩy"}],"wordFamily":["erase (v.)","erasure (n.)"],"synonyms":["rubber"],"antonyms":[],"tipVi":"eraser thường được dùng trong tiếng Anh-Mỹ; trong khi tiếng Anh-Anh thường dùng từ rubber.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_2_1', 'en-a1-2', 'Cách dùng “classroom” (n.) — phòng học, lớp học nơi học sinh được giảng dạy', 'classroom management  ·  classroom activities  ·  classroom teaching', 'in the classroom nhấn mạnh không gian bên trong phòng học; in class nhấn mạnh quá trình đang học tập trên lớp.', 'Họ từ (Word Family): class (n.)', '[{"hanzi":"Sunlight filled the classroom as we opened our books.","pinyin":"","meaning":"Ánh sáng mặt trời tràn ngập căn phòng học khi chúng tôi mở sách ra."},{"hanzi":"A well-designed classroom should provide adequate lighting, comfortable furniture, and enough space for students to work together.","pinyin":"","meaning":"Một phòng học được thiết kế tốt cần cung cấp đầy đủ ánh sáng, nội thất thoải mái và đủ không gian để học sinh làm việc nhóm."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_2_2', 'en-a1-2', 'Cách dùng “hundred” (num.) — một trăm', 'a hundred people  ·  two hundred  ·  hundreds of', 'Dùng hundred sau các số đếm cụ thể; dùng hundreds of để chỉ số lượng hàng trăm (hàng loạt) không xác định.', 'Họ từ (Word Family): hundredth (num.)', '[{"hanzi":"The hall can hold about a hundred people.","pinyin":"","meaning":"Phòng hội lớn có thể chứa khoảng một trăm người."},{"hanzi":"Several hundred residents participated in the survey about proposed improvements to local parks and cycle routes.","pinyin":"","meaning":"Hàng trăm cư dân đã tham gia cuộc khảo sát về các đề xuất cải tạo công viên địa phương và tuyến đường xe đạp."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_2_3', 'en-a1-2', 'Cách dùng “lesson” (n.) — tiết học; bài học', 'take lessons  ·  piano lesson  ·  learn a lesson', 'learn a lesson thường mang nghĩa rút ra bài học kinh nghiệm, không chỉ là học kiến thức trên lớp.', NULL, '[{"hanzi":"Our swimming lesson starts after school on Thursday.","pinyin":"","meaning":"Tiết học bơi của chúng tôi bắt đầu sau giờ học vào thứ Năm."},{"hanzi":"A key lesson from previous environmental policies is that effective regulation requires consistent monitoring and public support.","pinyin":"","meaning":"Một bài học quan trọng từ các chính sách môi trường trước đây là quy định hiệu quả đòi hỏi sự giám sát liên tục và sự ủng hộ của công chúng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_2_4', 'en-a1-2', 'Cách dùng “college” (n.) — trường cao đẳng; cơ sở giáo dục đại học', 'go to college  ·  college student  ·  college education', 'Ở Mỹ thường chỉ chung bậc đại học; ở Anh thường chỉ trường cao đẳng hoặc cơ sở giáo dục tiếp tục.', 'Họ từ (Word Family): collegiate (adj.)', '[{"hanzi":"My cousin is studying nursing at a local college.","pinyin":"","meaning":"Anh họ của tôi đang học ngành điều dưỡng tại một trường cao đẳng địa phương."},{"hanzi":"Making college education more affordable could improve social mobility and provide employers with a more skilled workforce.","pinyin":"","meaning":"Việc làm cho giáo dục đại học trở nên dễ tiếp cận hơn về mặt chi phí có thể thúc đẩy sự dịch chuyển xã hội và cung cấp cho người sử dụng lao động nguồn nhân lực có tay nghề cao hơn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_2_1', 'en-a1-2', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_2_1_1', 'ten_2_1', 'beginner', 'This swimming class is perfect for a complete beginner.', 'This swimming class is perfect for a complete beginner.', '/bɪˈɡɪnər/', 'Lớp bơi này cực kỳ phù hợp cho những người hoàn toàn chưa biết gì.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_2_1_2', 'ten_2_1', 'sentence', 'Our teacher asked us to write one sentence about autumn.', 'Our teacher asked us to write one sentence about autumn.', '/ˈsentəns/', 'Giáo viên yêu cầu chúng tôi viết một câu về mùa thu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_2_1_3', 'ten_2_1', 'homework', 'I finished my homework before dinner and went outside.', 'I finished my homework before dinner and went outside.', '/ˈhoʊmwɝːk/', 'Tôi đã làm xong bài tập về nhà trước bữa tối và đi ra ngoài.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
