INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_2_1_1', 'en-a1-2', 'ten_2_1', 'listening', 'listening', 'This swimming class is perfect for a complete beginner.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đọc vài trang sách trước khi đi ngủ mỗi tối.","Lớp bơi này cực kỳ phù hợp cho những người hoàn toàn chưa biết gì.","Giáo viên yêu cầu chúng tôi viết một câu về mùa thu.","Tiết học bơi của chúng tôi bắt đầu sau giờ học vào thứ Năm."]'::jsonb, 1, 'This swimming class is perfect for a complete beginner. → Lớp bơi này cực kỳ phù hợp cho những người hoàn toàn chưa biết gì.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
