INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_2_2_1', 'ten_2_2', 'beginner', 'Courses designed for beginners should provide clear guidance and regular opportunities to practise new skills.', 'Courses designed for beginners should provide clear guidance and regular opportunities to practise new skills.', '/bɪˈɡɪnər/', 'Các khóa học dành cho người mới bắt đầu cần cung cấp hướng dẫn rõ ràng và cơ hội luyện tập thường xuyên để thành thạo kỹ năng mới.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_2_2_2', 'ten_2_2', 'sentence', 'Learning to vary sentence length can help students express complex ideas more clearly in academic essays.', 'Learning to vary sentence length can help students express complex ideas more clearly in academic essays.', '/ˈsentəns/', 'Việc học cách thay đổi độ dài câu có thể giúp học sinh diễn đạt các ý tưởng phức tạp một cách rõ ràng hơn trong các bài luận học thuật.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_2_2_3', 'ten_2_2', 'homework', 'Schools should limit homework so that children have enough time for exercise and family activities.', 'Schools should limit homework so that children have enough time for exercise and family activities.', '/ˈhoʊmwɝːk/', 'Các trường học nên giới hạn bài tập về nhà để trẻ em có đủ thời gian tập thể dục và tham gia các hoạt động gia đình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_2_2_4', 'ten_2_2', 'read', 'Children who read regularly often develop stronger language skills and a broader understanding of the world.', 'Children who read regularly often develop stronger language skills and a broader understanding of the world.', '/riːd/', 'Trẻ em đọc sách thường xuyên thường phát triển kỹ năng ngôn ngữ tốt hơn và có hiểu biết rộng hơn về thế giới.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_2_2_5', 'ten_2_2', 'test', 'Researchers must test new materials under different conditions before recommending their use in public buildings.', 'Researchers must test new materials under different conditions before recommending their use in public buildings.', '/test/', 'Các nhà nghiên cứu phải kiểm tra vật liệu mới trong các điều kiện khác nhau trước khi khuyến nghị sử dụng chúng trong các công trình công cộng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_2_2_6', 'ten_2_2', 'lesson', 'A key lesson from previous environmental policies is that effective regulation requires consistent monitoring and public support.', 'A key lesson from previous environmental policies is that effective regulation requires consistent monitoring and public support.', '/ˈlesən/', 'Một bài học quan trọng từ các chính sách môi trường trước đây là quy định hiệu quả đòi hỏi sự giám sát liên tục và sự ủng hộ của công chúng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
