INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_2_2', 'en-a1-2', NULL, 'comprehensive_test', 'listening', 'Our teacher asked us to write one sentence about autumn.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi để quên cuốn sách của mình trên bàn bếp.","Giáo viên yêu cầu chúng tôi viết một câu về mùa thu.","Trong tiết địa lý hôm nay, chúng tôi đã học cách các dòng sông tạo hình thung lũng.","Tôi để lại một mẩu giấy nhắn cạnh bát ăn sáng của bạn."]'::jsonb, 1, 'Our teacher asked us to write one sentence about autumn. → Giáo viên yêu cầu chúng tôi viết một câu về mùa thu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
