INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_2_18', 'en-a1-2', NULL, 'comprehensive_test', 'reading', NULL, 'Courses designed for beginners should provide clear guidance and regular opportunities to practise new skills.', 'Dựa vào câu trên, từ “beginner” có nghĩa phù hợp nhất là gì?', '["tất cả; toàn bộ","người mới bắt đầu; người mới học","mùi; khứu giác","thỉnh thoảng; đôi khi"]'::jsonb, 1, 'beginner: người mới bắt đầu; người mới học. Dịch cả câu: Các khóa học dành cho người mới bắt đầu cần cung cấp hướng dẫn rõ ràng và cơ hội luyện tập thường xuyên để thành thạo kỹ năng mới.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_2_19', 'en-a1-2', NULL, 'comprehensive_test', 'reading', NULL, 'Learning to vary sentence length can help students express complex ideas more clearly in academic essays.', 'Dựa vào câu trên, từ “sentence” có nghĩa phù hợp nhất là gì?', '["đội; nhóm","câu","ngôi sao; vì sao","màu đỏ; có màu đỏ"]'::jsonb, 1, 'sentence: câu; hình phạt; bản án; kết án; tuyên án. Dịch cả câu: Việc học cách thay đổi độ dài câu có thể giúp học sinh diễn đạt các ý tưởng phức tạp một cách rõ ràng hơn trong các bài luận học thuật.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_2_20', 'en-a1-2', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should limit homework so that children have enough time for exercise and family activities.', 'Dựa vào câu trên, từ “homework” có nghĩa phù hợp nhất là gì?', '["thường; thường xuyên","môn bơi lội; việc bơi","bài tập về nhà","mũ; nón"]'::jsonb, 2, 'homework: bài tập về nhà; việc chuẩn bị trước; công tác chuẩn bị. Dịch cả câu: Các trường học nên giới hạn bài tập về nhà để trẻ em có đủ thời gian tập thể dục và tham gia các hoạt động gia đình.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_2_21', 'en-a1-2', NULL, 'comprehensive_test', 'reading', NULL, 'Children who read regularly often develop stronger language skills and a broader understanding of the world.', 'Dựa vào câu trên, từ “read” có nghĩa phù hợp nhất là gì?', '["đọc; đọc hiểu","áo phông; áo thun","phụ nữ; người phụ nữ","ngày Chủ nhật"]'::jsonb, 0, 'read: đọc; đọc hiểu; đọc thành tiếng; đọc hiểu; giải mã (thông tin). Dịch cả câu: Trẻ em đọc sách thường xuyên thường phát triển kỹ năng ngôn ngữ tốt hơn và có hiểu biết rộng hơn về thế giới.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
