INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_2_23', 'en-a1-2', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “trường đại học”', '["old","early","university","building"]'::jsonb, 2, 'trường đại học → university (/ˌjuːnɪˈvɜːrsəti/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_2_24', 'en-a1-2', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cục tẩy; gôm”', '["life","bus","eraser","win"]'::jsonb, 2, 'cục tẩy; gôm → eraser (/ɪˈreɪsər/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-3', 'en', 'Bài 3: Du lịch & Di chuyển (1) - CEFR A1', 'CEFR A1', 'A1 · Du lịch', '27 từ vựng Tiếng Anh CEFR A1 chủ đề du lịch & di chuyển kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1003, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_australian', 'en-a1-3', 'Australian', '/ɔːˈstreɪliən/', 'A1', 'thuộc Úc; người Úc; người Úc', 'adj.', 'Australia (n.)', NULL, 'Tính từ chỉ quốc tịch viết hoa chữ cái đầu; chỉ một người Úc dùng an Australian.', 'We spotted several Australian animals at the wildlife park.', NULL, 'Chúng tôi đã phát hiện ra vài loài động vật đặc trưng của Úc tại công viên động vật hoang dã.', '{"wordId":"australian","ukIpa":"/ɒˈstreɪliən/","usIpa":"/ɔːˈstreɪliən/","cefr":"A1","topic":"travel","senses":[{"pos":"adj.","en":"Relating to Australia or its people.","vi":"thuộc Úc; người Úc"},{"pos":"n.","en":"A person from Australia.","vi":"người Úc"}],"examples":[{"en":"We spotted several Australian animals at the wildlife park.","vi":"Chúng tôi đã phát hiện ra vài loài động vật đặc trưng của Úc tại công viên động vật hoang dã.","audioKind":"ex"},{"en":"Australian universities attract international students through a combination of research opportunities and diverse academic programmes.","vi":"Các trường đại học Úc thu hút sinh viên quốc tế thông qua sự kết hợp giữa các cơ hội nghiên cứu và chương trình học đa dạng.","audioKind":"ex2"}],"collocations":[{"en":"Australian wildlife","vi":"động vật hoang dã Úc"},{"en":"Australian culture","vi":"văn hóa Úc"},{"en":"Australian English","vi":"tiếng Anh-Úc"}],"wordFamily":["Australia (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tính từ chỉ quốc tịch viết hoa chữ cái đầu; chỉ một người Úc dùng an Australian.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hotel', 'en-a1-3', 'hotel', '/hoʊˈtel/', 'A1', 'khách sạn', 'n.', NULL, NULL, 'Nói ở khách sạn có thể dùng stay at hoặc stay in a hotel.', 'Our hotel room overlooks a quiet sandy beach.', NULL, 'Phòng khách sạn của chúng tôi nhìn ra một bãi biển cát yên tĩnh.', '{"wordId":"hotel","ukIpa":"/həʊˈtel/","usIpa":"/hoʊˈtel/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"a building where people pay to stay in rooms","vi":"khách sạn"}],"examples":[{"en":"Our hotel room overlooks a quiet sandy beach.","vi":"Phòng khách sạn của chúng tôi nhìn ra một bãi biển cát yên tĩnh.","audioKind":"ex"},{"en":"Building a new hotel near the station could create jobs and attract more visitors to the area.","vi":"Việc xây dựng một khách sạn mới gần ga tàu có thể tạo ra việc làm và thu hút nhiều du khách hơn đến khu vực này.","audioKind":"ex2"}],"collocations":[{"en":"book a hotel","vi":"đặt phòng khách sạn"},{"en":"stay at a hotel","vi":"ở khách sạn"},{"en":"hotel reception","vi":"quầy lễ tân khách sạn"},{"en":"budget hotel","vi":"khách sạn bình dân"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nói ở khách sạn có thể dùng stay at hoặc stay in a hotel.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_arrive', 'en-a1-3', 'arrive', '/əˈraɪv/', 'A1', 'đến nơi; tới; đến (sự kiện, thời điểm)', 'v.', 'arrival (n.)', 'Đồng nghĩa: reach · Trái nghĩa: depart, leave', 'Địa điểm nhỏ dùng at, thành phố/quốc gia dùng in; trước home không dùng giới từ.', 'Our guests arrived just as dinner was ready.', NULL, 'Khách của chúng tôi vừa đến thì bữa tối cũng vừa chuẩn bị xong.', '{"wordId":"arrive","ukIpa":"/əˈraɪv/","usIpa":"/əˈraɪv/","cefr":"A1","topic":"travel","senses":[{"pos":"v.","en":"To reach the place you were travelling to.","vi":"đến nơi; tới"},{"pos":"v.","en":"For an event or a particular time to come.","vi":"đến (sự kiện, thời điểm)"}],"examples":[{"en":"Our guests arrived just as dinner was ready.","vi":"Khách của chúng tôi vừa đến thì bữa tối cũng vừa chuẩn bị xong.","audioKind":"ex"},{"en":"Reliable public transport helps employees arrive at work on time and reduces dependence on private cars.","vi":"Phương tiện giao thông công cộng đáng tin cậy giúp nhân viên đến công ty đúng giờ và giảm bớt sự phụ thuộc vào ô tô cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"arrive at the station","vi":"đến ga tàu"},{"en":"arrive in a city","vi":"đến một thành phố"},{"en":"arrive on time","vi":"đến đúng giờ"},{"en":"arrive at a conclusion","vi":"đạt được kết luận"}],"wordFamily":["arrival (n.)"],"synonyms":["reach"],"antonyms":["depart","leave"],"tipVi":"Địa điểm nhỏ dùng at, thành phố/quốc gia dùng in; trước home không dùng giới từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_postcard', 'en-a1-3', 'postcard', '/ˈpoʊstkɑːrd/', 'A1', 'bưu thiếp', 'n.', NULL, NULL, 'Gửi cho ai đó có thể nói send someone a postcard hoặc dùng to để chỉ người nhận.', 'She sent me a postcard from a seaside village.', NULL, 'Cô ấy gửi cho tôi một tấm bưu thiếp từ một ngôi làng ven biển.', '{"wordId":"postcard","ukIpa":"/ˈpəʊstkɑːd/","usIpa":"/ˈpoʊstkɑːrd/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"a card mailed without an envelope, often showing a picture","vi":"bưu thiếp"}],"examples":[{"en":"She sent me a postcard from a seaside village.","vi":"Cô ấy gửi cho tôi một tấm bưu thiếp từ một ngôi làng ven biển.","audioKind":"ex"},{"en":"Although digital messages are faster, sending a postcard can create a more personal connection between travellers and their families.","vi":"Mặc dù tin nhắn kỹ thuật số nhanh hơn, nhưng việc gửi bưu thiếp có thể tạo ra sự gắn kết cá nhân hơn giữa du khách và gia đình họ.","audioKind":"ex2"}],"collocations":[{"en":"send a postcard","vi":"gửi bưu thiếp"},{"en":"write a postcard","vi":"viết bưu thiếp"},{"en":"picture postcard","vi":"bưu thiếp phong cảnh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Gửi cho ai đó có thể nói send someone a postcard hoặc dùng to để chỉ người nhận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_holiday', 'en-a1-3', 'holiday', '/ˈhɑːlədeɪ/', 'A1', 'kỳ nghỉ; ngày nghỉ phép; ngày lễ; ngày nghỉ chính thức; đi nghỉ mát; đi du lịch', 'n.', 'holidaymaker (n.)', 'Đồng nghĩa: vacation', 'Tiếng Anh Anh dùng on holiday để chỉ kỳ nghỉ; tiếng Mỹ thường dùng on vacation.', 'We spent our holiday swimming and exploring quiet villages.', NULL, 'Chúng tôi dành kỳ nghỉ của mình để bơi lội và khám phá những ngôi làng yên bình.', '{"wordId":"holiday","ukIpa":"/ˈhɒlədeɪ/","usIpa":"/ˈhɑːlədeɪ/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"A period away from work or study for rest or travel.","vi":"kỳ nghỉ; ngày nghỉ phép"},{"pos":"n.","en":"An officially recognised day when many people do not work.","vi":"ngày lễ; ngày nghỉ chính thức"},{"pos":"v.","en":"To spend time away from home for pleasure.","vi":"đi nghỉ mát; đi du lịch"}],"examples":[{"en":"We spent our holiday swimming and exploring quiet villages.","vi":"Chúng tôi dành kỳ nghỉ của mình để bơi lội và khám phá những ngôi làng yên bình.","audioKind":"ex"},{"en":"Flexible holiday arrangements can improve employee wellbeing while allowing businesses to maintain essential services throughout the year.","vi":"Các thỏa thuận nghỉ phép linh hoạt có thể nâng cao phúc lợi cho nhân viên đồng thời giúp doanh nghiệp duy trì các dịch vụ thiết yếu suốt cả năm.","audioKind":"ex2"}],"collocations":[{"en":"go on holiday","vi":"đi nghỉ mát"},{"en":"public holiday","vi":"ngày nghỉ lễ"},{"en":"holiday destination","vi":"điểm đến nghỉ dưỡng"},{"en":"holiday entitlement","vi":"chế độ ngày nghỉ phép"}],"wordFamily":["holidaymaker (n.)"],"synonyms":["vacation"],"antonyms":[],"tipVi":"Tiếng Anh Anh dùng on holiday để chỉ kỳ nghỉ; tiếng Mỹ thường dùng on vacation.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_france', 'en-a1-3', 'France', '/fræns/', 'A1', 'quốc gia ở Tây Âu với thủ đô là Paris', 'n.', 'French (adj.)', NULL, 'Tên quốc gia France viết hoa chữ cái đầu và thường không đi kèm mạo từ the.', 'We travelled through France by train last summer.', NULL, 'Hè năm ngoái, chúng tôi đã đi du lịch qua Pháp bằng tàu hỏa.', '{"wordId":"france","ukIpa":"/frɑːns/","usIpa":"/fræns/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"a country in western Europe whose capital is Paris","vi":"quốc gia ở Tây Âu với thủ đô là Paris"}],"examples":[{"en":"We travelled through France by train last summer.","vi":"Hè năm ngoái, chúng tôi đã đi du lịch qua Pháp bằng tàu hỏa.","audioKind":"ex"},{"en":"France attracts international visitors through its cultural heritage, varied landscapes, and well-developed transport networks.","vi":"Pháp thu hút du khách quốc tế nhờ di sản văn hóa, cảnh quan đa dạng và hệ thống giao thông phát triển.","audioKind":"ex2"}],"collocations":[{"en":"visit France","vi":"thăm Pháp"},{"en":"southern France","vi":"miền nam nước Pháp"},{"en":"mainland France","vi":"lục địa Pháp"}],"wordFamily":["French (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Tên quốc gia France viết hoa chữ cái đầu và thường không đi kèm mạo từ the.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aeroplane', 'en-a1-3', 'aeroplane', '/ˈerəpleɪn/', 'A1', 'máy bay', 'n.', NULL, 'Đồng nghĩa: airplane, plane, aircraft', 'Tiếng Anh - Anh dùng aeroplane, tiếng Anh - Mỹ dùng airplane; trong văn nói thường dùng plane.', 'The aeroplane flew low over the sandy beach.', NULL, 'Chiếc máy bay bay là đà ở tầm thấp phía trên bãi cát.', '{"wordId":"aeroplane","ukIpa":"/ˈeərəpleɪn/","usIpa":"/ˈerəpleɪn/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"A powered flying vehicle with fixed wings.","vi":"máy bay"}],"examples":[{"en":"The aeroplane flew low over the sandy beach.","vi":"Chiếc máy bay bay là đà ở tầm thấp phía trên bãi cát.","audioKind":"ex"},{"en":"Travelling by aeroplane connects distant communities, but its environmental impact has encouraged debate about alternative transport.","vi":"Đi lại bằng máy bay kết nối các cộng đồng ở xa, nhưng tác động môi trường của nó đã thúc đẩy các cuộc tranh luận về phương tiện giao thông thay thế.","audioKind":"ex2"}],"collocations":[{"en":"board an aeroplane","vi":"lên máy bay"},{"en":"fly an aeroplane","vi":"lái máy bay"},{"en":"aeroplane engine","vi":"động cơ máy bay"}],"wordFamily":[],"synonyms":["airplane","plane","aircraft"],"antonyms":[],"tipVi":"Tiếng Anh - Anh dùng aeroplane, tiếng Anh - Mỹ dùng airplane; trong văn nói thường dùng plane.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rome', 'en-a1-3', 'Rome', '/roʊm/', 'A1', 'thủ đô của Ý', 'n.', 'Roman (adj.), Roman (n.)', NULL, 'Tên thành phố viết hoa chữ cái đầu, đằng trước thường không dùng mạo từ the.', 'We spent our first afternoon in Rome exploring ancient ruins.', NULL, 'Chúng tôi dành buổi chiều đầu tiên ở Rô-ma để khám phá các di tích cổ đại.', '{"wordId":"rome","ukIpa":"/rəʊm/","usIpa":"/roʊm/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"The capital city of Italy","vi":"thủ đô của Ý"}],"examples":[{"en":"We spent our first afternoon in Rome exploring ancient ruins.","vi":"Chúng tôi dành buổi chiều đầu tiên ở Rô-ma để khám phá các di tích cổ đại.","audioKind":"ex"},{"en":"Cities such as Rome must balance the economic benefits of tourism with the protection of historic sites.","vi":"Các thành phố như Rô-ma phải cân bằng giữa lợi ích kinh tế của ngành du lịch và việc bảo vệ các di tích lịch sử.","audioKind":"ex2"}],"collocations":[{"en":"ancient Rome","vi":"cổ đại Rô-ma"},{"en":"the city of Rome","vi":"thành phố Rô-ma"},{"en":"a trip to Rome","vi":"chuyến đi đến Rô-ma"}],"wordFamily":["Roman (adj.)","Roman (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tên thành phố viết hoa chữ cái đầu, đằng trước thường không dùng mạo từ the.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_east', 'en-a1-3', 'east', '/iːst/', 'A1', 'hướng đông; phía đông; thuộc phía đông; hướng về phía đông; về phía đông; ở phía đông', 'n.', 'eastern (adj.), eastward (adv.), easterly (adj.)', 'Trái nghĩa: west', 'in the east of chỉ vùng bên trong phía đông; east of chỉ vị trí nằm ở phía đông của một nơi nào đó.', 'Our kitchen window faces east and catches the morning sun.', NULL, 'Cửa sổ nhà bếp của chúng tôi quay về hướng đông và đón ánh nắng ban mai.', '{"wordId":"east","ukIpa":"/iːst/","usIpa":"/iːst/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"the direction where the sun rises, opposite west","vi":"hướng đông; phía đông"},{"pos":"adj.","en":"in the east or facing towards it","vi":"thuộc phía đông; hướng về phía đông"},{"pos":"adv.","en":"towards or in the east","vi":"về phía đông; ở phía đông"}],"examples":[{"en":"Our kitchen window faces east and catches the morning sun.","vi":"Cửa sổ nhà bếp của chúng tôi quay về hướng đông và đón ánh nắng ban mai.","audioKind":"ex"},{"en":"Investment in rail connections could improve access to employment for communities in the east of the country.","vi":"Đầu tư vào các kết nối đường sắt có thể giúp cư dân ở miền đông đất nước dễ dàng tiếp cận việc làm hơn.","audioKind":"ex2"}],"collocations":[{"en":"in the east","vi":"ở phía đông"},{"en":"east coast","vi":"bờ biển phía đông"},{"en":"head east","vi":"hướng về phía đông"},{"en":"east of","vi":"ở phía đông của"}],"wordFamily":["eastern (adj.)","eastward (adv.)","easterly (adj.)"],"synonyms":[],"antonyms":["west"],"tipVi":"in the east of chỉ vùng bên trong phía đông; east of chỉ vị trí nằm ở phía đông của một nơi nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_africa', 'en-a1-3', 'Africa', '/ˈæfrɪkə/', 'A1', 'châu Phi', 'n.', 'African (adj.), African (n.)', NULL, 'Tên châu lục viết hoa chữ cái đầu và thường không đi kèm mạo từ; châu Africa không phải là một quốc gia.', 'My cousin returned from Africa with beautiful handmade baskets.', NULL, 'Anh họ của tôi từ châu Phi trở về với những chiếc giỏ thủ công rất đẹp.', '{"wordId":"africa","ukIpa":"/ˈæfrɪkə/","usIpa":"/ˈæfrɪkə/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"The continent south of Europe, between the Atlantic and Indian oceans.","vi":"châu Phi"}],"examples":[{"en":"My cousin returned from Africa with beautiful handmade baskets.","vi":"Anh họ của tôi từ châu Phi trở về với những chiếc giỏ thủ công rất đẹp.","audioKind":"ex"},{"en":"Investment in renewable energy across Africa could expand electricity access while supporting sustainable economic development.","vi":"Đầu tư vào năng lượng tái tạo khắp châu Phi có thể mở rộng khả năng tiếp cận điện năng đồng thời hỗ trợ phát triển kinh tế bền vững.","audioKind":"ex2"}],"collocations":[{"en":"North Africa","vi":"Bắc Phi"},{"en":"sub-Saharan Africa","vi":"châu Phi Hạ Sahara"},{"en":"across Africa","vi":"khắp châu Phi"}],"wordFamily":["African (adj.)","African (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tên châu lục viết hoa chữ cái đầu và thường không đi kèm mạo từ; châu Africa không phải là một quốc gia.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_boat', 'en-a1-3', 'boat', '/boʊt/', 'A1', 'thuyền; ghe; tàu nhỏ', 'n.', 'boating (n.)', NULL, 'by boat không dùng mạo từ; on a boat diễn tả hành động ở trên thuyền.', 'We hired a small boat and explored the lake.', NULL, 'Chúng tôi thuê một chiếc thuyền nhỏ và khám phá hồ nước.', '{"wordId":"boat","ukIpa":"/bəʊt/","usIpa":"/boʊt/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"a vessel for travelling on water, usually smaller than a ship","vi":"thuyền; ghe; tàu nhỏ"}],"examples":[{"en":"We hired a small boat and explored the lake.","vi":"Chúng tôi thuê một chiếc thuyền nhỏ và khám phá hồ nước.","audioKind":"ex"},{"en":"In remote coastal communities, travelling by boat remains essential for accessing schools and medical services.","vi":"Ở các cộng đồng ven biển hẻo lánh, việc đi lại bằng thuyền vẫn đóng vai trò thiết yếu để tiếp cận trường học và dịch vụ y tế.","audioKind":"ex2"}],"collocations":[{"en":"fishing boat","vi":"thuyền đánh cá"},{"en":"rowing boat","vi":"thuyền chèo"},{"en":"by boat","vi":"bằng thuyền"},{"en":"boat trip","vi":"chuyến đi bằng thuyền"}],"wordFamily":["boating (n.)"],"synonyms":[],"antonyms":[],"tipVi":"by boat không dùng mạo từ; on a boat diễn tả hành động ở trên thuyền.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_station', 'en-a1-3', 'station', '/ˈsteɪʃən/', 'A1', 'bga; trạm dừng; trạm; đài; cơ quan dịch vụ; bố trí; phân công', 'n.', 'stationary (adj.)', NULL, 'Khi làm động từ thường dùng thể bị động be stationed at, chỉ việc được điều động, đóng quân tại đâu.', 'We hurried to the station with our heavy suitcases.', NULL, 'Chúng tôi vội vã ra ga tàu với những chiếc va li nặng trĩu.', '{"wordId":"station","ukIpa":"/ˈsteɪʃən/","usIpa":"/ˈsteɪʃən/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"A place where trains or buses stop for passengers.","vi":"bga; trạm dừng"},{"pos":"n.","en":"A place or organisation providing a particular service.","vi":"trạm; đài; cơ quan dịch vụ"},{"pos":"v.","en":"To place someone somewhere to perform a duty.","vi":"bố trí; phân công"}],"examples":[{"en":"We hurried to the station with our heavy suitcases.","vi":"Chúng tôi vội vã ra ga tàu với những chiếc va li nặng trĩu.","audioKind":"ex"},{"en":"Local authorities should station trained staff at busy transport hubs to assist passengers with limited mobility.","vi":"Chính quyền địa phương nên bố trí nhân viên được đào tạo tại các đầu mối giao thông bận rộn để hỗ trợ hành khách đi lại khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"railway station","vi":"ga tàu hỏa"},{"en":"police station","vi":"đồn cảnh sát"},{"en":"radio station","vi":"đài phát thanh"},{"en":"be stationed at","vi":"được điều động tại"}],"wordFamily":["stationary (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi làm động từ thường dùng thể bị động be stationed at, chỉ việc được điều động, đóng quân tại đâu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plane', 'en-a1-3', 'plane', '/pleɪn/', 'A1', 'máy bay; mặt phẳng; bào phẳng', 'n.', NULL, 'Đồng nghĩa: aircraft', 'Cụm by plane không dùng mạo từ; trong khi on a plane thì cần có mạo từ a.', 'Our plane landed just before the rain began.', NULL, 'Máy bay của chúng tôi vừa hạ cánh ngay trước khi trời bắt đầu đổ mưa.', '{"wordId":"plane","ukIpa":"/pleɪn/","usIpa":"/pleɪn/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"a flying vehicle with wings and at least one engine","vi":"máy bay"},{"pos":"n.","en":"a flat surface extending in every direction","vi":"mặt phẳng"},{"pos":"v.","en":"to make wood smooth using a special cutting tool","vi":"bào phẳng"}],"examples":[{"en":"Our plane landed just before the rain began.","vi":"Máy bay của chúng tôi vừa hạ cánh ngay trước khi trời bắt đầu đổ mưa.","audioKind":"ex"},{"en":"Travelling by plane saves time, but its environmental impact should be considered when planning transport policy.","vi":"Đi máy bay giúp tiết kiệm thời gian, nhưng tác động môi trường của nó cần được cân nhắc khi hoạch định chính sách giao thông.","audioKind":"ex2"}],"collocations":[{"en":"by plane","vi":"đi bằng máy bay"},{"en":"board a plane","vi":"lên máy bay; đăng cơ"},{"en":"a horizontal plane","vi":"mặt phẳng nằm ngang"},{"en":"plane a door","vi":"bào phẳng cánh cửa"}],"wordFamily":[],"synonyms":["aircraft"],"antonyms":[],"tipVi":"Cụm by plane không dùng mạo từ; trong khi on a plane thì cần có mạo từ a.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_north', 'en-a1-3', 'north', '/nɔːrθ/', 'A1', 'phía bắc; phương bắc; miền bắc; thuộc phía bắc; ở phía bắc; về hướng bắc; ở phía bắc', 'n.', 'northern (adj.), northward (adv.), northerly (adj.)', 'Trái nghĩa: south', 'Cụm in the north of chỉ vị trí nằm bên trong phần phía bắc; còn north of chỉ vị trí nằm ở phía bắc bên ngoài khu vực đó.', 'The north of the island gets snow every winter.', NULL, 'Miền bắc của hòn đảo có tuyết rơi vào mỗi mùa đông.', '{"wordId":"north","ukIpa":"/nɔːθ/","usIpa":"/nɔːrθ/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"the direction opposite south, or an area''s northern part","vi":"phía bắc; phương bắc; miền bắc"},{"pos":"adj.","en":"in the north or facing towards it","vi":"thuộc phía bắc; ở phía bắc"},{"pos":"adv.","en":"towards or in the north","vi":"về hướng bắc; ở phía bắc"}],"examples":[{"en":"The north of the island gets snow every winter.","vi":"Miền bắc của hòn đảo có tuyết rơi vào mỗi mùa đông.","audioKind":"ex"},{"en":"Investment in rail connections could help towns in the north attract businesses and create more local jobs.","vi":"Việc đầu tư vào các tuyến đường sắt có thể giúp các thị trấn ở miền bắc thu hút doanh nghiệp và tạo thêm nhiều việc làm tại địa phương.","audioKind":"ex2"}],"collocations":[{"en":"the north of","vi":"phần phía bắc của"},{"en":"head north","vi":"đi về hướng bắc"},{"en":"north coast","vi":"bờ biển phía bắc"},{"en":"further north","vi":"xa hơn về phía bắc"}],"wordFamily":["northern (adj.)","northward (adv.)","northerly (adj.)"],"synonyms":[],"antonyms":["south"],"tipVi":"Cụm in the north of chỉ vị trí nằm bên trong phần phía bắc; còn north of chỉ vị trí nằm ở phía bắc bên ngoài khu vực đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ride', 'en-a1-3', 'ride', '/raɪd/', 'A1', 'đi (xe đạp, xe máy, ngựa hoặc phương tiện khác); chuyến đi; lượt đi (bằng xe hoặc thú cưỡi)', 'v.', 'rider (n.), riding (n.)', NULL, 'Biến đổi bất quy tắc: "ride"—"rode"—"ridden".', 'We ride our bikes to the lake every weekend.', NULL, 'Chúng tôi đạp xe ra hồ vào mỗi cuối tuần.', '{"wordId":"ride","ukIpa":"/raɪd/","usIpa":"/raɪd/","cefr":"A1","topic":"travel","senses":[{"pos":"v.","en":"To travel on a bicycle, animal, or vehicle.","vi":"đi (xe đạp, xe máy, ngựa hoặc phương tiện khác)"},{"pos":"n.","en":"A journey on a bicycle, animal, or vehicle.","vi":"chuyến đi; lượt đi (bằng xe hoặc thú cưỡi)"}],"examples":[{"en":"We ride our bikes to the lake every weekend.","vi":"Chúng tôi đạp xe ra hồ vào mỗi cuối tuần.","audioKind":"ex"},{"en":"Safer cycling routes could encourage more residents to ride bicycles rather than drive for short urban journeys.","vi":"Các tuyến đường đạp xe an toàn hơn có thể khuyến khích nhiều cư dân đạp xe thay vì lái ô tô cho các chuyến đi ngắn trong đô thị.","audioKind":"ex2"}],"collocations":[{"en":"ride a bike","vi":"đi xe đạp"},{"en":"ride a horse","vi":"cưỡi ngựa"},{"en":"go for a ride","vi":"đi dạo bằng xe/ngựa"},{"en":"give someone a ride","vi":"cho ai đó đi nhờ xe"}],"wordFamily":["rider (n.)","riding (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Biến đổi bất quy tắc: \"ride\"—\"rode\"—\"ridden\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bus', 'en-a1-3', 'bus', '/bʌs/', 'A1', 'xe buýt; xe khách lớn chở hành khách; vận chuyển người bằng xe buýt', 'n.', NULL, NULL, 'by bus không cần mạo từ; take a bus cần có mạo từ.', 'We caught the last bus home after the concert.', NULL, 'Chúng tôi đã bắt chuyến xe buýt cuối cùng về nhà sau buổi biểu diễn.', '{"wordId":"bus","ukIpa":"/bʌs/","usIpa":"/bʌs/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"a large road vehicle that carries passengers","vi":"xe buýt; xe khách lớn chở hành khách"},{"pos":"v.","en":"to transport people somewhere by bus","vi":"vận chuyển người bằng xe buýt"}],"examples":[{"en":"We caught the last bus home after the concert.","vi":"Chúng tôi đã bắt chuyến xe buýt cuối cùng về nhà sau buổi biểu diễn.","audioKind":"ex"},{"en":"More frequent bus services could reduce traffic congestion and improve access to employment in outer suburbs.","vi":"Việc tăng cường tần suất các chuyến xe buýt có thể làm giảm tình trạng ùn tắc giao thông và cải thiện khả năng tiếp cận việc làm ở các vùng ngoại ô xa.","audioKind":"ex2"}],"collocations":[{"en":"catch a bus","vi":"bắt xe buýt"},{"en":"bus stop","vi":"trạm xe buýt"},{"en":"bus route","vi":"tuyến xe buýt"},{"en":"by bus","vi":"bằng xe buýt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"by bus không cần mạo từ; take a bus cần có mạo từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_airplane', 'en-a1-3', 'airplane', '/ˈerpleɪn/', 'A1', 'máy bay', 'n.', NULL, 'Đồng nghĩa: plane, aeroplane, aircraft', 'airplane thường dùng trong tiếng Mỹ, trong khi tiếng Anh-Anh thường dùng aeroplane.', 'We watched the airplane disappear behind a white cloud.', NULL, 'Chúng tôi nhìn theo chiếc máy bay khuất dần sau một đám mây trắng.', '{"wordId":"airplane","ukIpa":"/ˈeəpleɪn/","usIpa":"/ˈerpleɪn/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"A powered flying vehicle with fixed wings.","vi":"máy bay"}],"examples":[{"en":"We watched the airplane disappear behind a white cloud.","vi":"Chúng tôi nhìn theo chiếc máy bay khuất dần sau một đám mây trắng.","audioKind":"ex"},{"en":"Travelling by airplane connects remote communities to essential services, although it also contributes to carbon emissions.","vi":"Đi lại bằng máy bay giúp kết nối các cộng đồng vùng sâu vùng xa với các dịch vụ thiết yếu, mặc dù nó cũng góp phần làm tăng lượng khí thải carbon.","audioKind":"ex2"}],"collocations":[{"en":"board an airplane","vi":"lên máy bay"},{"en":"fly an airplane","vi":"lái máy bay"},{"en":"passenger airplane","vi":"máy bay chở khách"}],"wordFamily":[],"synonyms":["plane","aeroplane","aircraft"],"antonyms":[],"tipVi":"airplane thường dùng trong tiếng Mỹ, trong khi tiếng Anh-Anh thường dùng aeroplane.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ticket', 'en-a1-3', 'ticket', '/ˈtɪkɪt/', 'A1', 'vé; thẻ lên tàu xe; vé vào cửa; giấy phạt vi phạm giao thông; phạt tiền vi phạm giao thông', 'n.', NULL, NULL, 'Trong tiếng Anh-Anh, single và return ticket lần lượt chỉ vé một chiều và vé khứ hồi.', 'I bought a return ticket from the station machine.', NULL, 'Tôi đã mua một vé khứ hồi tại máy bán vé ở nhà ga.', '{"wordId":"ticket","ukIpa":"/ˈtɪkɪt/","usIpa":"/ˈtɪkɪt/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"A paper or electronic pass allowing travel or entry.","vi":"vé; thẻ lên tàu xe; vé vào cửa"},{"pos":"n.","en":"An official notice requiring payment for a traffic offence.","vi":"giấy phạt vi phạm giao thông"},{"pos":"v.","en":"To give someone an official notice for a traffic offence.","vi":"phạt tiền vi phạm giao thông"}],"examples":[{"en":"I bought a return ticket from the station machine.","vi":"Tôi đã mua một vé khứ hồi tại máy bán vé ở nhà ga.","audioKind":"ex"},{"en":"Lower ticket prices could encourage more commuters to choose trains instead of driving to work.","vi":"Giá vé rẻ hơn có thể khuyến khích nhiều người đi lại hằng ngày chọn tàu hỏa thay vì lái xe đi làm.","audioKind":"ex2"}],"collocations":[{"en":"return ticket","vi":"vé khứ hồi"},{"en":"single ticket","vi":"vé một chiều"},{"en":"parking ticket","vi":"giấy phạt đậu xe"},{"en":"book a ticket","vi":"đặt vé"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh, single và return ticket lần lượt chỉ vé một chiều và vé khứ hồi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_map', 'en-a1-3', 'map', '/mæp/', 'A1', 'bản đồ; vẽ bản đồ; định vị', 'n.', 'mapping (n.)', 'Đồng nghĩa: chart', 'Khi map đóng vai trò động từ, dạng quá khứ là mapped, phân tề là mapping.', 'We spread the map across the table before leaving.', NULL, 'Chúng tôi trải bản đồ lên bàn trước khi xuất phát.', '{"wordId":"map","ukIpa":"/mæp/","usIpa":"/mæp/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"A drawing showing where places or features are located","vi":"bản đồ"},{"pos":"v.","en":"To draw or record the position of places or features","vi":"vẽ bản đồ; định vị"}],"examples":[{"en":"We spread the map across the table before leaving.","vi":"Chúng tôi trải bản đồ lên bàn trước khi xuất phát.","audioKind":"ex"},{"en":"Researchers use satellite images to map changes in forest cover and identify areas needing urgent protection.","vi":"Các nhà nghiên cứu sử dụng hình ảnh vệ tinh để lập bản đồ biến động diện tích rừng và xác định các khu vực cần được bảo vệ khẩn cấp.","audioKind":"ex2"}],"collocations":[{"en":"read a map","vi":"đọc bản đồ"},{"en":"street map","vi":"bản đồ đường phố"},{"en":"map out a route","vi":"lên kế hoạch tuyến đường"},{"en":"map changes","vi":"lập bản đồ sự thay đổi"}],"wordFamily":["mapping (n.)"],"synonyms":["chart"],"antonyms":[],"tipVi":"Khi map đóng vai trò động từ, dạng quá khứ là mapped, phân tề là mapping.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stay', 'en-a1-3', 'stay', '/steɪ/', 'A1', 'ở lại; lưu trú; tạm trú; giữ nguyên trạng thái; kỳ lưu trú; thời gian ở lại', 'v.', NULL, 'Đồng nghĩa: remain · Trái nghĩa: leave', 'Sau stay có thể trực tiếp dùng tính từ, ví dụ như stay calm nghĩa là giữ bình tĩnh.', 'We stayed at a small hotel beside the lake.', NULL, 'Chúng tôi ở lại một khách sạn nhỏ bên hồ.', '{"wordId":"stay","ukIpa":"/steɪ/","usIpa":"/steɪ/","cefr":"A1","topic":"travel","senses":[{"pos":"v.","en":"To remain in a place or live somewhere temporarily.","vi":"ở lại; lưu trú; tạm trú"},{"pos":"v.","en":"To continue being in a particular condition.","vi":"giữ nguyên trạng thái"},{"pos":"n.","en":"A period spent living or visiting somewhere.","vi":"kỳ lưu trú; thời gian ở lại"}],"examples":[{"en":"We stayed at a small hotel beside the lake.","vi":"Chúng tôi ở lại một khách sạn nhỏ bên hồ.","audioKind":"ex"},{"en":"Tourists who stay longer in rural areas may contribute more to local businesses than short-term visitors.","vi":"Những du khách lưu trú lâu hơn ở các vùng nông thôn có thể đóng góp nhiều hơn cho các doanh nghiệp địa phương so với khách du lịch ngắn hạn.","audioKind":"ex2"}],"collocations":[{"en":"stay at a hotel","vi":"ở tại khách sạn"},{"en":"stay healthy","vi":"giữ gìn sức khỏe"},{"en":"stay in touch","vi":"giữ liên lạc"},{"en":"a short stay","vi":"một kỳ lưu trú ngắn"}],"wordFamily":[],"synonyms":["remain"],"antonyms":["leave"],"tipVi":"Sau stay có thể trực tiếp dùng tính từ, ví dụ như stay calm nghĩa là giữ bình tĩnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_china', 'en-a1-3', 'China', '/ˈtʃaɪnə/', 'A1', 'n. một quốc gia ở Đông Á', 'n.', 'Chinese (adj.), Chinese (n.)', NULL, 'China chỉ Trung Quốc; chữ thường china chỉ đồ sứ, tính từ dùng Chinese.', 'My cousin returned from China with beautiful mountain photographs.', NULL, 'Anh họ tôi từ Trung Quốc trở về với những bức ảnh phong cảnh núi non tuyệt đẹp.', '{"wordId":"china","ukIpa":"/ˈtʃaɪnə/","usIpa":"/ˈtʃaɪnə/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"a country in East Asia","vi":"n. một quốc gia ở Đông Á"}],"examples":[{"en":"My cousin returned from China with beautiful mountain photographs.","vi":"Anh họ tôi từ Trung Quốc trở về với những bức ảnh phong cảnh núi non tuyệt đẹp.","audioKind":"ex"},{"en":"The expansion of high-speed rail in China illustrates how transport investment can improve connections between major cities.","vi":"Sự mở rộng của mạng lưới đường sắt cao tốc ở Trung Quốc minh họa cách đầu tư giao thông có thể cải thiện kết nối giữa các thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"mainland China","vi":"Trung Quốc đại lục"},{"en":"visit China","vi":"thăm Trung Quốc"},{"en":"made in China","vi":"sản xuất tại Trung Quốc"}],"wordFamily":["Chinese (adj.)","Chinese (n.)"],"synonyms":[],"antonyms":[],"tipVi":"China chỉ Trung Quốc; chữ thường china chỉ đồ sứ, tính từ dùng Chinese.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fly', 'en-a1-3', 'fly', '/flaɪ/', 'A1', 'bay; đi máy bay; lái máy bay; con ruồi', 'v.', 'flight (n.), flying (adj.), flyer (n.)', NULL, 'Động từ bất quy tắc: fly–flew–flown; dạng số nhiều của "fly" (con ruồi) là "flies".', 'Small birds fly over our garden every morning.', NULL, 'Những chú chim nhỏ bay qua khu vườn của chúng tôi mỗi sáng.', '{"wordId":"fly","ukIpa":"/flaɪ/","usIpa":"/flaɪ/","cefr":"A1","topic":"travel","senses":[{"pos":"v.","en":"to move through the air using wings","vi":"bay"},{"pos":"v.","en":"to travel in or control an aircraft","vi":"đi máy bay; lái máy bay"},{"pos":"n.","en":"a small insect with two wings, often found near food","vi":"con ruồi"}],"examples":[{"en":"Small birds fly over our garden every morning.","vi":"Những chú chim nhỏ bay qua khu vườn của chúng tôi mỗi sáng.","audioKind":"ex"},{"en":"Choosing to travel by train rather than fly can significantly reduce the environmental impact of short journeys.","vi":"Việc lựa chọn đi lại bằng tàu hỏa thay vì đi máy bay có thể giảm đáng kể tác động môi trường của những chuyến đi ngắn.","audioKind":"ex2"}],"collocations":[{"en":"fly abroad","vi":"bay ra nước ngoài"},{"en":"fly a plane","vi":"lái máy bay"},{"en":"fly a kite","vi":"thả diều"},{"en":"a swarm of flies","vi":"một đàn ruồi"}],"wordFamily":["flight (n.)","flying (adj.)","flyer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ bất quy tắc: fly–flew–flown; dạng số nhiều của \"fly\" (con ruồi) là \"flies\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bike', 'en-a1-3', 'bike', '/baɪk/', 'A1', 'xe đạp; xe máy (thân mật); đi xe đạp', 'n.', 'biker (n.), biking (n.)', 'Đồng nghĩa: bicycle, cycle', 'Cụm "by bike" không thêm mạo từ; trong cụm "ride a bike" không được lược bỏ "a".', 'I locked my bike outside the corner shop.', NULL, 'Tôi khóa xe đạp bên ngoài cửa hàng góc phố.', '{"wordId":"bike","ukIpa":"/baɪk/","usIpa":"/baɪk/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"a bicycle or, informally, a motorcycle","vi":"xe đạp; xe máy (thân mật)"},{"pos":"v.","en":"to travel somewhere by bicycle","vi":"đi xe đạp"}],"examples":[{"en":"I locked my bike outside the corner shop.","vi":"Tôi khóa xe đạp bên ngoài cửa hàng góc phố.","audioKind":"ex"},{"en":"Encouraging commuters to travel by bike could reduce urban congestion and improve public health.","vi":"Việc khuyến khích người đi làm di chuyển bằng xe đạp có thể giảm tình trạng tắc nghẽn đô thị và cải thiện sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"ride a bike","vi":"đi xe đạp"},{"en":"by bike","vi":"bằng xe đạp"},{"en":"bike lane","vi":"làn đường dành cho xe đạp"},{"en":"mountain bike","vi":"xe đạp địa hình"}],"wordFamily":["biker (n.)","biking (n.)"],"synonyms":["bicycle","cycle"],"antonyms":[],"tipVi":"Cụm \"by bike\" không thêm mạo từ; trong cụm \"ride a bike\" không được lược bỏ \"a\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_beach', 'en-a1-3', 'beach', '/biːtʃ/', 'A1', 'bãi biển; đưa tàu thuyền lên cạn', 'n.', NULL, 'Đồng nghĩa: shore', 'Ở trên bãi biển dùng "on the beach"; "shore" dùng chung cho vùng bờ nước.', 'We collected smooth stones on the beach after breakfast.', NULL, 'Chúng tôi nhặt những hòn sỏi nhẵn nhụi trên bãi biển sau bữa sáng.', '{"wordId":"beach","ukIpa":"/biːtʃ/","usIpa":"/biːtʃ/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"an area of sand or small stones beside water","vi":"bãi biển"},{"pos":"v.","en":"to bring a boat onto a shore","vi":"đưa tàu thuyền lên cạn"}],"examples":[{"en":"We collected smooth stones on the beach after breakfast.","vi":"Chúng tôi nhặt những hòn sỏi nhẵn nhụi trên bãi biển sau bữa sáng.","audioKind":"ex"},{"en":"Local authorities should protect beaches from plastic waste while ensuring that tourism benefits nearby communities.","vi":"Chính quyền địa phương nên bảo vệ các bãi biển khỏi rác thải nhựa đồng thời đảm bảo ngành du lịch mang lại lợi ích cho cộng đồng xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"sandy beach","vi":"bãi cát"},{"en":"a pebble beach","vi":"bãi biển đầy sỏi"},{"en":"on the beach","vi":"trên bãi biển"},{"en":"beach cleanup","vi":"hoạt động dọn dẹp bãi biển"}],"wordFamily":[],"synonyms":["shore"],"antonyms":[],"tipVi":"Ở trên bãi biển dùng \"on the beach\"; \"shore\" dùng chung cho vùng bờ nước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drive', 'en-a1-3', 'drive', '/draɪv/', 'A1', 'lái xe; điều khiển phương tiện; thúc đẩy; thúc giục; khiến; chuyến đi xe ô tô; động lực; ổ đĩa', 'v.', 'driver (n.), driving (n.), driven (adj.)', NULL, 'Biểu hiện bất quy tắc: drive—drove—driven; chở/đưa ai đó đi dùng drive sb to.', 'Can you drive me to the station after breakfast?', NULL, 'Bạn có thể lái xe đưa tôi ra ga sau bữa sáng không?', '{"wordId":"drive","ukIpa":"/draɪv/","usIpa":"/draɪv/","cefr":"A1","topic":"travel","senses":[{"pos":"v.","en":"to control a vehicle and make it move","vi":"lái xe; điều khiển phương tiện"},{"pos":"v.","en":"to cause something to develop or someone to act","vi":"thúc đẩy; thúc giục; khiến"},{"pos":"n.","en":"a car journey, strong motivation, or a computer storage device","vi":"chuyến đi xe ô tô; động lực; ổ đĩa"}],"examples":[{"en":"Can you drive me to the station after breakfast?","vi":"Bạn có thể lái xe đưa tôi ra ga sau bữa sáng không?","audioKind":"ex"},{"en":"Consumer demand can drive innovation by encouraging companies to develop products that use fewer natural resources.","vi":"Nhu cầu của người tiêu dùng có thể thúc đẩy đổi mới sáng tạo bằng cách khuyến khích các công ty phát triển các sản phẩm sử dụng ít tài nguyên thiên nhiên hơn.","audioKind":"ex2"}],"collocations":[{"en":"drive to work","vi":"lái xe đi làm"},{"en":"drive economic growth","vi":"thúc đẩy tăng trưởng kinh tế"},{"en":"go for a drive","vi":"đi lái xe dạo chơi"},{"en":"hard drive","vi":"ổ đĩa cứng"}],"wordFamily":["driver (n.)","driving (n.)","driven (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Biểu hiện bất quy tắc: drive—drove—driven; chở/đưa ai đó đi dùng drive sb to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_road', 'en-a1-3', 'road', '/roʊd/', 'A1', 'con đường; đường đi; con đường; cách thức đạt được kết quả', 'n.', 'roadside (n.), roadway (n.)', NULL, 'Cụm từ on the road thường chỉ việc đang trong chuyến đi; road to có thể dùng theo nghĩa ẩn dụ là con đường dẫn đến một kết quả nào đó.', 'Look both ways before you cross the road.', NULL, 'Hãy nhìn về cả hai phía trước khi bạn băng qua đường.', '{"wordId":"road","ukIpa":"/rəʊd/","usIpa":"/roʊd/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"a hard surface built for vehicles to travel along","vi":"con đường; đường đi"},{"pos":"n.","en":"a way of reaching a particular result or situation","vi":"con đường; cách thức đạt được kết quả"}],"examples":[{"en":"Look both ways before you cross the road.","vi":"Hãy nhìn về cả hai phía trước khi bạn băng qua đường.","audioKind":"ex"},{"en":"Investment in road maintenance can improve public safety and reduce transport costs for local businesses.","vi":"Đầu tư vào việc bảo trì đường xá có thể nâng cao an toàn giao thông và giảm chi phí vận chuyển cho các doanh nghiệp địa phương.","audioKind":"ex2"}],"collocations":[{"en":"road safety","vi":"an toàn giao thông"},{"en":"a main road","vi":"đường trục chính"},{"en":"road maintenance","vi":"bảo trì đường bộ"},{"en":"the road to recovery","vi":"con đường phục hồi"}],"wordFamily":["roadside (n.)","roadway (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ on the road thường chỉ việc đang trong chuyến đi; road to có thể dùng theo nghĩa ẩn dụ là con đường dẫn đến một kết quả nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_taxi', 'en-a1-3', 'taxi', '/ˈtæksi/', 'A1', 'xe taxi; (máy bay) di chuyển trên mặt đất (trước khi cất cánh hoặc sau khi hạ cánh)', 'n.', NULL, 'Đồng nghĩa: cab', 'Đi taxi có thể dùng "take a taxi" hoặc "by taxi".', 'We took a taxi home with our heavy bags.', NULL, 'Chúng tôi bắt taxi về nhà với những chiếc túi nặng.', '{"wordId":"taxi","ukIpa":"/ˈtæksi/","usIpa":"/ˈtæksi/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"A car with a driver whom you pay for a journey.","vi":"xe taxi"},{"pos":"v.","en":"To move slowly on the ground before takeoff or after landing.","vi":"(máy bay) di chuyển trên mặt đất (trước khi cất cánh hoặc sau khi hạ cánh)"}],"examples":[{"en":"We took a taxi home with our heavy bags.","vi":"Chúng tôi bắt taxi về nhà với những chiếc túi nặng.","audioKind":"ex"},{"en":"Improving public transport could reduce dependence on taxis and private cars in crowded city centres.","vi":"Việc cải thiện giao thông công cộng có thể làm giảm sự phụ thuộc vào taxi và xe hơi cá nhân ở các trung tâm thành phố đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"take a taxi","vi":"đi taxi"},{"en":"hail a taxi","vi":"vẫy xe taxi"},{"en":"taxi fare","vi":"tiền cước taxi"},{"en":"taxi rank","vi":"bến đỗ taxi"}],"wordFamily":[],"synonyms":["cab"],"antonyms":[],"tipVi":"Đi taxi có thể dùng \"take a taxi\" hoặc \"by taxi\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_3_1', 'en-a1-3', 'Cách dùng “road” (n.) — con đường; đường đi', 'road safety  ·  a main road  ·  road maintenance', 'Cụm từ on the road thường chỉ việc đang trong chuyến đi; road to có thể dùng theo nghĩa ẩn dụ là con đường dẫn đến một kết quả nào đó.', 'Họ từ (Word Family): roadside (n.), roadway (n.)', '[{"hanzi":"Look both ways before you cross the road.","pinyin":"","meaning":"Hãy nhìn về cả hai phía trước khi bạn băng qua đường."},{"hanzi":"Investment in road maintenance can improve public safety and reduce transport costs for local businesses.","pinyin":"","meaning":"Đầu tư vào việc bảo trì đường xá có thể nâng cao an toàn giao thông và giảm chi phí vận chuyển cho các doanh nghiệp địa phương."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_3_2', 'en-a1-3', 'Cách dùng “north” (n.) — phía bắc; phương bắc; miền bắc', 'the north of  ·  head north  ·  north coast', 'Cụm in the north of chỉ vị trí nằm bên trong phần phía bắc; còn north of chỉ vị trí nằm ở phía bắc bên ngoài khu vực đó.', 'Họ từ (Word Family): northern (adj.), northward (adv.), northerly (adj.) | Trái nghĩa: south', '[{"hanzi":"The north of the island gets snow every winter.","pinyin":"","meaning":"Miền bắc của hòn đảo có tuyết rơi vào mỗi mùa đông."},{"hanzi":"Investment in rail connections could help towns in the north attract businesses and create more local jobs.","pinyin":"","meaning":"Việc đầu tư vào các tuyến đường sắt có thể giúp các thị trấn ở miền bắc thu hút doanh nghiệp và tạo thêm nhiều việc làm tại địa phương."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_3_3', 'en-a1-3', 'Cách dùng “Africa” (n.) — châu Phi', 'North Africa  ·  sub-Saharan Africa  ·  across Africa', 'Tên châu lục viết hoa chữ cái đầu và thường không đi kèm mạo từ; châu Africa không phải là một quốc gia.', 'Họ từ (Word Family): African (adj.), African (n.)', '[{"hanzi":"My cousin returned from Africa with beautiful handmade baskets.","pinyin":"","meaning":"Anh họ của tôi từ châu Phi trở về với những chiếc giỏ thủ công rất đẹp."},{"hanzi":"Investment in renewable energy across Africa could expand electricity access while supporting sustainable economic development.","pinyin":"","meaning":"Đầu tư vào năng lượng tái tạo khắp châu Phi có thể mở rộng khả năng tiếp cận điện năng đồng thời hỗ trợ phát triển kinh tế bền vững."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_3_4', 'en-a1-3', 'Cách dùng “station” (n.) — bga; trạm dừng', 'railway station  ·  police station  ·  radio station', 'Khi làm động từ thường dùng thể bị động be stationed at, chỉ việc được điều động, đóng quân tại đâu.', 'Họ từ (Word Family): stationary (adj.)', '[{"hanzi":"We hurried to the station with our heavy suitcases.","pinyin":"","meaning":"Chúng tôi vội vã ra ga tàu với những chiếc va li nặng trĩu."},{"hanzi":"Local authorities should station trained staff at busy transport hubs to assist passengers with limited mobility.","pinyin":"","meaning":"Chính quyền địa phương nên bố trí nhân viên được đào tạo tại các đầu mối giao thông bận rộn để hỗ trợ hành khách đi lại khó khăn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
