INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_3_1_1', 'en-a1-3', 'ten_3_1', 'listening', 'listening', 'We spotted several Australian animals at the wildlife park.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chiếc máy bay bay là đà ở tầm thấp phía trên bãi cát.","Phòng khách sạn của chúng tôi nhìn ra một bãi biển cát yên tĩnh.","Chúng tôi đã phát hiện ra vài loài động vật đặc trưng của Úc tại công viên động vật hoang dã.","Chúng tôi dành buổi chiều đầu tiên ở Rô-ma để khám phá các di tích cổ đại."]'::jsonb, 2, 'We spotted several Australian animals at the wildlife park. → Chúng tôi đã phát hiện ra vài loài động vật đặc trưng của Úc tại công viên động vật hoang dã.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_3_1_2', 'en-a1-3', 'ten_3_1', 'listening', 'listening', 'Our hotel room overlooks a quiet sandy beach.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hè năm ngoái, chúng tôi đã đi du lịch qua Pháp bằng tàu hỏa.","Khách của chúng tôi vừa đến thì bữa tối cũng vừa chuẩn bị xong.","Chiếc máy bay bay là đà ở tầm thấp phía trên bãi cát.","Phòng khách sạn của chúng tôi nhìn ra một bãi biển cát yên tĩnh."]'::jsonb, 3, 'Our hotel room overlooks a quiet sandy beach. → Phòng khách sạn của chúng tôi nhìn ra một bãi biển cát yên tĩnh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_3_1_3', 'en-a1-3', 'ten_3_1', 'listening', 'listening', 'Our guests arrived just as dinner was ready.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi dành kỳ nghỉ của mình để bơi lội và khám phá những ngôi làng yên bình.","Chiếc máy bay bay là đà ở tầm thấp phía trên bãi cát.","Chúng tôi đã phát hiện ra vài loài động vật đặc trưng của Úc tại công viên động vật hoang dã.","Khách của chúng tôi vừa đến thì bữa tối cũng vừa chuẩn bị xong."]'::jsonb, 3, 'Our guests arrived just as dinner was ready. → Khách của chúng tôi vừa đến thì bữa tối cũng vừa chuẩn bị xong.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_3_2', 'en-a1-3', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_3_2_1', 'ten_3_2', 'Australian', 'Australian universities attract international students through a combination of research opportunities and diverse academic programmes.', 'Australian universities attract international students through a combination of research opportunities and diverse academic programmes.', '/ɔːˈstreɪliən/', 'Các trường đại học Úc thu hút sinh viên quốc tế thông qua sự kết hợp giữa các cơ hội nghiên cứu và chương trình học đa dạng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_3_2_2', 'ten_3_2', 'hotel', 'Building a new hotel near the station could create jobs and attract more visitors to the area.', 'Building a new hotel near the station could create jobs and attract more visitors to the area.', '/hoʊˈtel/', 'Việc xây dựng một khách sạn mới gần ga tàu có thể tạo ra việc làm và thu hút nhiều du khách hơn đến khu vực này.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_3_2_3', 'ten_3_2', 'arrive', 'Reliable public transport helps employees arrive at work on time and reduces dependence on private cars.', 'Reliable public transport helps employees arrive at work on time and reduces dependence on private cars.', '/əˈraɪv/', 'Phương tiện giao thông công cộng đáng tin cậy giúp nhân viên đến công ty đúng giờ và giảm bớt sự phụ thuộc vào ô tô cá nhân.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_3_2_4', 'ten_3_2', 'postcard', 'Although digital messages are faster, sending a postcard can create a more personal connection between travellers and their families.', 'Although digital messages are faster, sending a postcard can create a more personal connection between travellers and their families.', '/ˈpoʊstkɑːrd/', 'Mặc dù tin nhắn kỹ thuật số nhanh hơn, nhưng việc gửi bưu thiếp có thể tạo ra sự gắn kết cá nhân hơn giữa du khách và gia đình họ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_3_2_5', 'ten_3_2', 'holiday', 'Flexible holiday arrangements can improve employee wellbeing while allowing businesses to maintain essential services throughout the year.', 'Flexible holiday arrangements can improve employee wellbeing while allowing businesses to maintain essential services throughout the year.', '/ˈhɑːlədeɪ/', 'Các thỏa thuận nghỉ phép linh hoạt có thể nâng cao phúc lợi cho nhân viên đồng thời giúp doanh nghiệp duy trì các dịch vụ thiết yếu suốt cả năm.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_3_2_6', 'ten_3_2', 'France', 'France attracts international visitors through its cultural heritage, varied landscapes, and well-developed transport networks.', 'France attracts international visitors through its cultural heritage, varied landscapes, and well-developed transport networks.', '/fræns/', 'Pháp thu hút du khách quốc tế nhờ di sản văn hóa, cảnh quan đa dạng và hệ thống giao thông phát triển.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_3_2_1', 'en-a1-3', 'ten_3_2', 'listening', 'listening', 'Australian universities attract international students through a combination of research opportunities and diverse academic programmes.', NULL, 'Trong câu vừa nghe, từ “Australian” mang nghĩa nào sau đây?', '["chiếc giày","thuộc Úc; người Úc","xe ô tô; xe hơi","giá cả; giá tiền"]'::jsonb, 1, '“Australian” (/ɔːˈstreɪliən/): thuộc Úc; người Úc. Câu đầy đủ: Australian universities attract international students through a combination of research opportunities and diverse academic programmes.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
