INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_3_4', 'en-a1-3', NULL, 'comprehensive_test', 'listening', 'She sent me a postcard from a seaside village.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã mua một vé khứ hồi tại máy bán vé ở nhà ga.","Chúng tôi thuê một chiếc thuyền nhỏ và khám phá hồ nước.","Chúng tôi dành buổi chiều đầu tiên ở Rô-ma để khám phá các di tích cổ đại.","Cô ấy gửi cho tôi một tấm bưu thiếp từ một ngôi làng ven biển."]'::jsonb, 3, 'She sent me a postcard from a seaside village. → Cô ấy gửi cho tôi một tấm bưu thiếp từ một ngôi làng ven biển.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_3_5', 'en-a1-3', NULL, 'comprehensive_test', 'listening', 'holiday', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bầu trời","vé; thẻ lên tàu xe; vé vào cửa","kỳ nghỉ; ngày nghỉ phép","tòa nhà; công trình kiến trúc"]'::jsonb, 2, 'holiday (/ˈhɑːlədeɪ/) → kỳ nghỉ; ngày nghỉ phép; ngày lễ; ngày nghỉ chính thức; đi nghỉ mát; đi du lịch', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_3_6', 'en-a1-3', NULL, 'comprehensive_test', 'listening', 'We travelled through France by train last summer.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh họ của tôi từ châu Phi trở về với những chiếc giỏ thủ công rất đẹp.","Chúng tôi ở lại một khách sạn nhỏ bên hồ.","Chúng tôi đạp xe ra hồ vào mỗi cuối tuần.","Hè năm ngoái, chúng tôi đã đi du lịch qua Pháp bằng tàu hỏa."]'::jsonb, 3, 'We travelled through France by train last summer. → Hè năm ngoái, chúng tôi đã đi du lịch qua Pháp bằng tàu hỏa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_3_7', 'en-a1-3', NULL, 'comprehensive_test', 'listening', 'aeroplane', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["gặp gỡ; hội họp; làm quen","máy bay","bữa trưa","rẻ; giá rẻ; giá thấp"]'::jsonb, 1, 'aeroplane (/ˈerəpleɪn/) → máy bay', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_3_8', 'en-a1-3', NULL, 'comprehensive_test', 'listening', 'We spent our first afternoon in Rome exploring ancient ruins.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi dành buổi chiều đầu tiên ở Rô-ma để khám phá các di tích cổ đại.","Anh họ tôi từ Trung Quốc trở về với những bức ảnh phong cảnh núi non tuyệt đẹp.","Chúng tôi đạp xe ra hồ vào mỗi cuối tuần.","Khách của chúng tôi vừa đến thì bữa tối cũng vừa chuẩn bị xong."]'::jsonb, 0, 'We spent our first afternoon in Rome exploring ancient ruins. → Chúng tôi dành buổi chiều đầu tiên ở Rô-ma để khám phá các di tích cổ đại.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_3_9', 'en-a1-3', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A period away from work or study for rest or travel.”?', '["bus","holiday","hotel","aeroplane"]'::jsonb, 1, 'holiday (/ˈhɑːlədeɪ/) → kỳ nghỉ; ngày nghỉ phép', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_3_10', 'en-a1-3', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a country in western Europe whose capital is Paris”?', '["France","bus","holiday","Rome"]'::jsonb, 0, 'France (/fræns/) → quốc gia ở Tây Âu với thủ đô là Paris', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_3_11', 'en-a1-3', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A powered flying vehicle with fixed wings.”?', '["ride","boat","Africa","aeroplane"]'::jsonb, 3, 'aeroplane (/ˈerəpleɪn/) → máy bay', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_3_12', 'en-a1-3', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The capital city of Italy”?', '["plane","Rome","station","east"]'::jsonb, 1, 'Rome (/roʊm/) → thủ đô của Ý', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
