INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_3_18', 'en-a1-3', NULL, 'comprehensive_test', 'reading', NULL, 'Australian universities attract international students through a combination of research opportunities and diverse academic programmes.', 'Dựa vào câu trên, từ “Australian” có nghĩa phù hợp nhất là gì?', '["câu","việc mua sắm","thuộc Úc; người Úc","của tôi"]'::jsonb, 2, 'Australian: thuộc Úc; người Úc; người Úc. Dịch cả câu: Các trường đại học Úc thu hút sinh viên quốc tế thông qua sự kết hợp giữa các cơ hội nghiên cứu và chương trình học đa dạng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_3_19', 'en-a1-3', NULL, 'comprehensive_test', 'reading', NULL, 'Building a new hotel near the station could create jobs and attract more visitors to the area.', 'Dựa vào câu trên, từ “hotel” có nghĩa phù hợp nhất là gì?', '["chiều; tối (từ sau buổi trưa đến trước nửa đêm)","khách sạn","ông; bà; ông bà","gửi; truyền đi"]'::jsonb, 1, 'hotel: khách sạn. Dịch cả câu: Việc xây dựng một khách sạn mới gần ga tàu có thể tạo ra việc làm và thu hút nhiều du khách hơn đến khu vực này.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_3_20', 'en-a1-3', NULL, 'comprehensive_test', 'reading', NULL, 'Reliable public transport helps employees arrive at work on time and reduces dependence on private cars.', 'Dựa vào câu trên, từ “arrive” có nghĩa phù hợp nhất là gì?', '["thứ Bảy","nước Đức","đến nơi; tới","cầm, nắm hoặc đỡ cái gì đó trong lúc di chuyển nó đến đâu; mang vác"]'::jsonb, 2, 'arrive: đến nơi; tới; đến (sự kiện, thời điểm). Dịch cả câu: Phương tiện giao thông công cộng đáng tin cậy giúp nhân viên đến công ty đúng giờ và giảm bớt sự phụ thuộc vào ô tô cá nhân.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_3_21', 'en-a1-3', NULL, 'comprehensive_test', 'reading', NULL, 'Although digital messages are faster, sending a postcard can create a more personal connection between travellers and their families.', 'Dựa vào câu trên, từ “postcard” có nghĩa phù hợp nhất là gì?', '["tháng Bảy","trường học; giờ học ở trường","cho phép; để cho","bưu thiếp"]'::jsonb, 3, 'postcard: bưu thiếp. Dịch cả câu: Mặc dù tin nhắn kỹ thuật số nhanh hơn, nhưng việc gửi bưu thiếp có thể tạo ra sự gắn kết cá nhân hơn giữa du khách và gia đình họ.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_3_22', 'en-a1-3', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lái xe; điều khiển phương tiện”', '["drive","orange","slow","town"]'::jsonb, 0, 'lái xe; điều khiển phương tiện → drive (/draɪv/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_3_23', 'en-a1-3', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “con đường; đường đi”', '["road","July","even","expensive"]'::jsonb, 0, 'con đường; đường đi → road (/roʊd/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
