INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-4', 'en', 'Bài 4: Du lịch & Di chuyển (2) - CEFR A1', 'CEFR A1', 'A1 · Du lịch', '26 từ vựng Tiếng Anh CEFR A1 chủ đề du lịch & di chuyển kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1004, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spain', 'en-a1-4', 'Spain', '/speɪn/', 'A1', 'Tây Ban Nha', 'n.', 'Spanish (adj.), Spaniard (n.)', NULL, 'Tên quốc gia viết hoa chữ cái đầu, phía trước thường không thêm "the".', 'We travelled around Spain by train last summer.', NULL, 'Mùa hè năm ngoái chúng tôi đã đi du lịch khắp Tây Ban Nha bằng tàu hỏa.', '{"wordId":"spain","ukIpa":"/speɪn/","usIpa":"/speɪn/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"a country in southwestern Europe","vi":"Tây Ban Nha"}],"examples":[{"en":"We travelled around Spain by train last summer.","vi":"Mùa hè năm ngoái chúng tôi đã đi du lịch khắp Tây Ban Nha bằng tàu hỏa.","audioKind":"ex"},{"en":"Spain attracts international visitors through its cultural heritage, varied landscapes, and well-developed tourism infrastructure.","vi":"Tây Ban Nha thu hút du khách quốc tế nhờ di sản văn hóa, cảnh quan đa dạng và cơ sở hạ tầng du lịch phát triển tốt.","audioKind":"ex2"}],"collocations":[{"en":"southern Spain","vi":"miền nam Tây Ban Nha"},{"en":"mainland Spain","vi":"đất liền Tây Ban Nha"},{"en":"travel to Spain","vi":"du lịch đến Tây Ban Nha"}],"wordFamily":["Spanish (adj.)","Spaniard (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tên quốc gia viết hoa chữ cái đầu, phía trước thường không thêm \"the\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_europe', 'en-a1-4', 'Europe', '/ˈjʊrəp/', 'A1', 'châu Âu', 'n.', 'European (adj.), European (n.)', NULL, '"Europe" viết hoa chữ cái đầu, thường không có "the"; không đồng nghĩa với Liên minh châu Âu (EU).', 'My cousin travelled across Europe by train last summer.', NULL, 'Anh họ tôi đã đi du lịch khắp châu Âu bằng tàu hỏa vào mùa hè năm ngoái.', '{"wordId":"europe","ukIpa":"/ˈjʊərəp/","usIpa":"/ˈjʊrəp/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"the continent west of Asia and north of Africa","vi":"châu Âu"}],"examples":[{"en":"My cousin travelled across Europe by train last summer.","vi":"Anh họ tôi đã đi du lịch khắp châu Âu bằng tàu hỏa vào mùa hè năm ngoái.","audioKind":"ex"},{"en":"Many cities in Europe are expanding cycling networks to reduce traffic congestion and improve urban air quality.","vi":"Nhiều thành phố ở châu Âu đang mở rộng mạng lưới đường dành cho xe đạp để giảm ùn tắc giao thông và cải thiện chất lượng không khí đô thị.","audioKind":"ex2"}],"collocations":[{"en":"across Europe","vi":"khắp châu Âu"},{"en":"continental Europe","vi":"lục địa châu Âu"},{"en":"Eastern Europe","vi":"Đông Âu"},{"en":"Western Europe","vi":"Tây Âu"}],"wordFamily":["European (adj.)","European (n.)"],"synonyms":[],"antonyms":[],"tipVi":"\"Europe\" viết hoa chữ cái đầu, thường không có \"the\"; không đồng nghĩa với Liên minh châu Âu (EU).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_airport', 'en-a1-4', 'airport', '/ˈerpɔːrt/', 'A1', 'sân bay', 'n.', NULL, NULL, 'Khi ở sân bay thường dùng giới từ at the airport; khu vực nhà ga sân bay được gọi là terminal.', 'We arrived at the airport before the sun rose.', NULL, 'Chúng tôi đã đến sân bay trước khi mặt trời mọc.', '{"wordId":"airport","ukIpa":"/ˈeəpɔːt/","usIpa":"/ˈerpɔːrt/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"A place where planes take off, land, and collect passengers","vi":"sân bay"}],"examples":[{"en":"We arrived at the airport before the sun rose.","vi":"Chúng tôi đã đến sân bay trước khi mặt trời mọc.","audioKind":"ex"},{"en":"Expanding an airport may boost tourism, but it can also increase noise pollution for nearby residents.","vi":"Việc mở rộng sân bay có thể thúc đẩy ngành du lịch, nhưng nó cũng có thể làm tăng ô nhiễm tiếng ồn đối với cư dân sống ở khu vực lân cận.","audioKind":"ex2"}],"collocations":[{"en":"international airport","vi":"sân bay quốc tế"},{"en":"airport terminal","vi":"nhà ga sân bay"},{"en":"airport shuttle","vi":"xe buýt đưa đón sân bay"},{"en":"airport security","vi":"an ninh sân bay"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi ở sân bay thường dùng giới từ at the airport; khu vực nhà ga sân bay được gọi là terminal.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_far', 'en-a1-4', 'far', '/fɑr/', 'A1', 'ở khoảng cách xa; xa xôi; hơn rất nhiều; đáng kể; xa hơn; ở xa hơn', 'adv.', 'farther (adv.), further (adv.), farthest (adv.), furthest (adv.)', 'Trái nghĩa: near', 'far có thể dùng để bổ nghĩa cho tính từ so sánh hơn, chẳng hạn như far better; không dùng far good.', 'We walked so far that our feet began to ache.', NULL, 'Chúng tôi đi bộ xa đến mức chân bắt đầu ê ẩm.', '{"wordId":"far","ukIpa":"/fɑː/","usIpa":"/fɑr/","cefr":"A1","topic":"travel","senses":[{"pos":"adv.","en":"At, to, or over a great distance.","vi":"ở khoảng cách xa; xa xôi"},{"pos":"adv.","en":"To a much greater degree.","vi":"hơn rất nhiều; đáng kể"},{"pos":"adj.","en":"More distant from you or a particular point.","vi":"xa hơn; ở xa hơn"}],"examples":[{"en":"We walked so far that our feet began to ache.","vi":"Chúng tôi đi bộ xa đến mức chân bắt đầu ê ẩm.","audioKind":"ex"},{"en":"Reliable public transport can make commuting far more affordable for people who live outside major city centres.","vi":"Hệ thống giao thông công cộng đáng tin cậy có thể giúp cho việc đi lại của những người sống ngoài khu vực trung tâm thành phố trở nên tiết kiệm hơn rất nhiều.","audioKind":"ex2"}],"collocations":[{"en":"far away","vi":"ở xa"},{"en":"far from","vi":"cách xa; hoàn toàn không"},{"en":"far more","vi":"nhiều hơn hẳn"},{"en":"so far","vi":"cho đến nay"}],"wordFamily":["farther (adv.)","further (adv.)","farthest (adv.)","furthest (adv.)"],"synonyms":[],"antonyms":["near"],"tipVi":"far có thể dùng để bổ nghĩa cho tính từ so sánh hơn, chẳng hạn như far better; không dùng far good.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_australia', 'en-a1-4', 'Australia', '/ɔːˈstreɪljə/', 'A1', 'Úc; nước Úc; Australia', 'n.', 'Australian (adj.), Australian (n.)', NULL, 'Australia chỉ nước Úc; Austria mới là nước Áo.', 'My cousin moved to Australia to study marine biology.', NULL, 'Anh họ của tôi đã chuyển đến Úc để học ngành sinh học biển.', '{"wordId":"australia","ukIpa":"/ɒˈstreɪliə/","usIpa":"/ɔːˈstreɪljə/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"a country occupying a continent between the Indian and Pacific Oceans","vi":"Úc; nước Úc; Australia"}],"examples":[{"en":"My cousin moved to Australia to study marine biology.","vi":"Anh họ của tôi đã chuyển đến Úc để học ngành sinh học biển.","audioKind":"ex"},{"en":"Australia attracts international students through its universities, diverse cities, and opportunities to study in English.","vi":"Úc thu hút sinh viên quốc tế nhờ các trường đại học, các thành phố đa dạng văn hóa và cơ hội học tập bằng tiếng Anh.","audioKind":"ex2"}],"collocations":[{"en":"travel to Australia","vi":"du lịch Úc"},{"en":"study in Australia","vi":"du học Úc"},{"en":"mainland Australia","vi":"lục địa Úc"}],"wordFamily":["Australian (adj.)","Australian (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Australia chỉ nước Úc; Austria mới là nước Áo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_asia', 'en-a1-4', 'Asia', '/ˈeɪʒə/', 'A1', 'châu Á', 'n.', 'Asian (adj.)', NULL, 'Tên châu lục phải viết hoa chữ cái đầu và thường không đi kèm mạo từ the; tính từ tương ứng là Asian.', 'My cousin spent three months travelling around Asia.', NULL, 'Anh họ của tôi đã dành ba tháng để du lịch khắp châu Á.', '{"wordId":"asia","ukIpa":"/ˈeɪʒə/","usIpa":"/ˈeɪʒə/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"The world''s largest continent, lying mainly east of Europe.","vi":"châu Á"}],"examples":[{"en":"My cousin spent three months travelling around Asia.","vi":"Anh họ của tôi đã dành ba tháng để du lịch khắp châu Á.","audioKind":"ex"},{"en":"Rapid urban growth in Asia has increased the need for affordable housing and reliable public transport.","vi":"Sự phát triển đô thị nhanh chóng ở châu Á đã làm tăng nhu cầu về nhà ở giá rẻ và giao thông công cộng đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"East Asia","vi":"Đông Á"},{"en":"Southeast Asia","vi":"Đông Nam Á"},{"en":"Central Asia","vi":"Trung Á"},{"en":"across Asia","vi":"khắp châu Á"}],"wordFamily":["Asian (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Tên châu lục phải viết hoa chữ cái đầu và thường không đi kèm mạo từ the; tính từ tương ứng là Asian.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mexico', 'en-a1-4', 'Mexico', '/ˈmeksɪkoʊ/', 'A1', 'nước Mê-hi-cô', 'n.', 'Mexican (adj.), Mexican (n.)', NULL, 'Tên quốc gia thường không đi kèm the; Mexican chỉ thuộc về Mê-hi-cô hoặc người Mê-hi-cô.', 'We explored ancient ruins during our holiday in Mexico.', NULL, 'Chúng tôi đã khám phá các di tích cổ trong kỳ nghỉ ở Mê-hi-cô.', '{"wordId":"mexico","ukIpa":"/ˈmeksɪkəʊ/","usIpa":"/ˈmeksɪkoʊ/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"A country in North America, south of the United States.","vi":"nước Mê-hi-cô"}],"examples":[{"en":"We explored ancient ruins during our holiday in Mexico.","vi":"Chúng tôi đã khám phá các di tích cổ trong kỳ nghỉ ở Mê-hi-cô.","audioKind":"ex"},{"en":"Tourism in Mexico creates employment, but popular coastal destinations also face pressure on water supplies and natural habitats.","vi":"Ngành du lịch ở Mê-hi-cô tạo ra việc làm, nhưng các điểm đến ven biển nổi tiếng cũng phải đối mặt với áp lực về nguồn cung cấp nước và môi trường sống tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"visit Mexico","vi":"tham quan Mê-hi-cô"},{"en":"southern Mexico","vi":"miền nam Mê-hi-cô"},{"en":"the coast of Mexico","vi":"bờ biển Mê-hi-cô"}],"wordFamily":["Mexican (adj.)","Mexican (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tên quốc gia thường không đi kèm the; Mexican chỉ thuộc về Mê-hi-cô hoặc người Mê-hi-cô.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_south', 'en-a1-4', 'south', '/saʊθ/', 'A1', 'phương nam; hướng nam; thuộc về phía nam; hướng về phía nam; về phía nam; ở phía nam', 'n.', 'southern (adj.), southward (adv.)', 'Trái nghĩa: north', 'Nói về vị trí ở miền nam dùng in the south; đi về hướng nam dùng go south, không cần giới từ to.', 'Our balcony faces south and gets plenty of sunshine.', NULL, 'Ban công nhà chúng tôi quay về hướng nam và đón được rất nhiều ánh nắng.', '{"wordId":"south","ukIpa":"/saʊθ/","usIpa":"/saʊθ/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"the direction opposite north","vi":"phương nam; hướng nam"},{"pos":"adj.","en":"in, towards, or facing the south","vi":"thuộc về phía nam; hướng về phía nam"},{"pos":"adv.","en":"towards or in the south","vi":"về phía nam; ở phía nam"}],"examples":[{"en":"Our balcony faces south and gets plenty of sunshine.","vi":"Ban công nhà chúng tôi quay về hướng nam và đón được rất nhiều ánh nắng.","audioKind":"ex"},{"en":"Many families move to the south because its warmer climate allows more outdoor activities throughout the year.","vi":"Nhiều gia đình chuyển về miền nam vì khí hậu ấm áp hơn giúp họ có thể tham gia nhiều hoạt động ngoài trời quanh năm.","audioKind":"ex2"}],"collocations":[{"en":"in the south","vi":"ở phía nam"},{"en":"head south","vi":"đi về phía nam"},{"en":"south coast","vi":"bờ biển phía nam"}],"wordFamily":["southern (adj.)","southward (adv.)"],"synonyms":[],"antonyms":["north"],"tipVi":"Nói về vị trí ở miền nam dùng in the south; đi về hướng nam dùng go south, không cần giới từ to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_train', 'en-a1-4', 'train', '/treɪn/', 'A1', 'tàu hỏa; tàu điện; đào tạo; huấn luyện', 'n.', 'training (n.), trainer (n.), trainee (n.)', NULL, 'Di chuyển bằng phương tiện dùng by train; ở trên tàu dùng on the train.', 'We caught the last train home after dinner.', NULL, 'Chúng tôi đã bắt chuyến tàu cuối cùng về nhà sau bữa tối.', '{"wordId":"train","ukIpa":"/treɪn/","usIpa":"/treɪn/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"Connected railway vehicles that carry passengers or goods.","vi":"tàu hỏa; tàu điện"},{"pos":"v.","en":"Teach or practise skills needed for an activity or job.","vi":"đào tạo; huấn luyện"}],"examples":[{"en":"We caught the last train home after dinner.","vi":"Chúng tôi đã bắt chuyến tàu cuối cùng về nhà sau bữa tối.","audioKind":"ex"},{"en":"Governments should train more healthcare workers to meet the needs of an ageing population.","vi":"Chính phủ nên đào tạo nhiều nhân viên y tế hơn để đáp ứng nhu cầu của dân số đang già hóa.","audioKind":"ex2"}],"collocations":[{"en":"catch a train","vi":"bắt tàu"},{"en":"train station","vi":"ga tàu hỏa"},{"en":"train staff","vi":"đào tạo nhân viên"},{"en":"train for a marathon","vi":"tập luyện cho giải marathon"}],"wordFamily":["training (n.)","trainer (n.)","trainee (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Di chuyển bằng phương tiện dùng by train; ở trên tàu dùng on the train.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_germany', 'en-a1-4', 'Germany', '/ˈdʒɝːməni/', 'A1', 'nước Đức', 'n.', 'German (adj.), German (n.)', NULL, 'Germany là tên quốc gia; German có thể chỉ tiếng Đức, người Đức hoặc thuộc về nước Đức.', 'My cousin moved to Germany to study engineering.', NULL, 'Anh họ tôi đã chuyển đến Đức để học ngành kỹ thuật.', '{"wordId":"germany","ukIpa":"/ˈdʒɜːməni/","usIpa":"/ˈdʒɝːməni/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"a country in central Europe","vi":"nước Đức"}],"examples":[{"en":"My cousin moved to Germany to study engineering.","vi":"Anh họ tôi đã chuyển đến Đức để học ngành kỹ thuật.","audioKind":"ex"},{"en":"Germany has invested in renewable energy as part of its efforts to reduce dependence on fossil fuels.","vi":"Nước Đức đã đầu tư vào năng lượng tái tạo như một phần trong nỗ lực giảm sự phụ thuộc vào nhiên liệu hóa thạch.","audioKind":"ex2"}],"collocations":[{"en":"in Germany","vi":"ở Đức"},{"en":"travel to Germany","vi":"đi du lịch Đức"},{"en":"made in Germany","vi":"sản xuất tại Đức"}],"wordFamily":["German (adj.)","German (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Germany là tên quốc gia; German có thể chỉ tiếng Đức, người Đức hoặc thuộc về nước Đức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_car', 'en-a1-4', 'car', '/kɑːr/', 'A1', 'xe ô tô; xe hơi; toà tàu; toa xe lửa', 'n.', NULL, 'Đồng nghĩa: automobile', 'by car không có mạo từ; in a car cần có mạo từ.', 'Our car is parked under the tree outside.', NULL, 'Xe ô tô của chúng tôi đang đậu dưới tán cây bên ngoài.', '{"wordId":"car","ukIpa":"/kɑː/","usIpa":"/kɑːr/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"a road vehicle with wheels, usually carrying a few people","vi":"xe ô tô; xe hơi"},{"pos":"n.","en":"one of the separate sections of a train","vi":"toà tàu; toa xe lửa"}],"examples":[{"en":"Our car is parked under the tree outside.","vi":"Xe ô tô của chúng tôi đang đậu dưới tán cây bên ngoài.","audioKind":"ex"},{"en":"Reducing private car use could improve urban air quality and make streets safer for pedestrians.","vi":"Việc hạn chế sử dụng xe cá nhân có thể cải thiện chất lượng không khí đô thị và giúp đường phố an toàn hơn cho người đi bộ.","audioKind":"ex2"}],"collocations":[{"en":"by car","vi":"đi bằng xe hơi"},{"en":"electric car","vi":"xe điện"},{"en":"car park","vi":"bãi đậu xe"},{"en":"dining car","vi":"toa ăn (trên tàu)"}],"wordFamily":[],"synonyms":["automobile"],"antonyms":[],"tipVi":"by car không có mạo từ; in a car cần có mạo từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bicycle', 'en-a1-4', 'bicycle', '/ˈbaɪsɪkəl/', 'A1', 'xe đạp; đi xe đạp', 'n.', 'bicycling (n.), bicyclist (n.)', 'Đồng nghĩa: bike', 'by bicycle không dùng mạo từ; ride a bicycle phải dùng mạo từ a.', 'I locked my bicycle outside the small bakery.', NULL, 'Tôi đã khóa chiếc xe đạp của mình ở bên ngoài tiệm bánh nhỏ.', '{"wordId":"bicycle","ukIpa":"/ˈbaɪsɪkəl/","usIpa":"/ˈbaɪsɪkəl/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"a two-wheeled vehicle moved by pushing pedals","vi":"xe đạp"},{"pos":"v.","en":"to travel by bicycle","vi":"đi xe đạp"}],"examples":[{"en":"I locked my bicycle outside the small bakery.","vi":"Tôi đã khóa chiếc xe đạp của mình ở bên ngoài tiệm bánh nhỏ.","audioKind":"ex"},{"en":"Travelling by bicycle can reduce urban air pollution while providing residents with regular physical exercise.","vi":"Di chuyển bằng xe đạp có thể làm giảm ô nhiễm không khí đô thị đồng thời cung cấp cho người dân hoạt động thể chất thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"ride a bicycle","vi":"lái xe đạp"},{"en":"by bicycle","vi":"bằng xe đạp"},{"en":"bicycle lane","vi":"làn đường dành cho xe đạp"},{"en":"bicycle helmet","vi":"mũ bảo hiểm xe đạp"}],"wordFamily":["bicycling (n.)","bicyclist (n.)"],"synonyms":["bike"],"antonyms":[],"tipVi":"by bicycle không dùng mạo từ; ride a bicycle phải dùng mạo từ a.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_visit', 'en-a1-4', 'visit', '/ˈvɪzɪt/', 'A1', 'thăm; ghé thăm; tham quan; chuyến thăm; chuyến viếng thăm', 'v.', 'visitor (n.)', NULL, 'Động từ visit trực tiếp đi với tân ngữ; danh từ dùng cấu trúc a visit to.', 'We visited our neighbours and shared some homemade soup.', NULL, 'Chúng tôi đến thăm hàng xóm và cùng nhau thưởng thức một ít súp tự nấu.', '{"wordId":"visit","ukIpa":"/ˈvɪzɪt/","usIpa":"/ˈvɪzɪt/","cefr":"A1","topic":"travel","senses":[{"pos":"v.","en":"To go to see a person or place.","vi":"thăm; ghé thăm; tham quan"},{"pos":"n.","en":"An occasion when someone goes to see someone or somewhere.","vi":"chuyến thăm; chuyến viếng thăm"}],"examples":[{"en":"We visited our neighbours and shared some homemade soup.","vi":"Chúng tôi đến thăm hàng xóm và cùng nhau thưởng thức một ít súp tự nấu.","audioKind":"ex"},{"en":"Students who visit science museums can connect classroom theories with practical examples from everyday life.","vi":"Học sinh tham quan các bảo tàng khoa học có thể kết nối lý thuyết trên lớp với các ví dụ thực tế từ đời sống hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"visit relatives","vi":"thăm họ hàng"},{"en":"pay a visit to","vi":"ghé thăm; tới thăm"},{"en":"a guided visit","vi":"chuyến tham quan có hướng dẫn"}],"wordFamily":["visitor (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ visit trực tiếp đi với tân ngữ; danh từ dùng cấu trúc a visit to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_canada', 'en-a1-4', 'Canada', '/ˈkænədə/', 'A1', 'Ca-na-đa', 'n.', 'Canadian (adj.), Canadian (n.)', NULL, 'Tên quốc gia viết hoa chữ cái đầu, đằng trước thường không dùng mạo từ the.', 'My cousin moved to Canada to study environmental science.', NULL, 'Anh họ của tôi đã chuyển đến Ca-na-đa để học khoa học môi trường.', '{"wordId":"canada","ukIpa":"/ˈkænədə/","usIpa":"/ˈkænədə/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"a country in North America, north of the United States","vi":"Ca-na-đa"}],"examples":[{"en":"My cousin moved to Canada to study environmental science.","vi":"Anh họ của tôi đã chuyển đến Ca-na-đa để học khoa học môi trường.","audioKind":"ex"},{"en":"Canada attracts international students through its universities, although living costs vary considerably between cities.","vi":"Ca-na-đa thu hút sinh viên quốc tế thông qua các trường đại học của mình, mặc dù chi phí sinh hoạt có sự chênh lệch đáng kể giữa các thành phố.","audioKind":"ex2"}],"collocations":[{"en":"study in Canada","vi":"du học tại Ca-na-đa"},{"en":"across Canada","vi":"khắp Ca-na-đa"},{"en":"move to Canada","vi":"chuyển đến Ca-na-đa"}],"wordFamily":["Canadian (adj.)","Canadian (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tên quốc gia viết hoa chữ cái đầu, đằng trước thường không dùng mạo từ the.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_america', 'en-a1-4', 'America', '/əˈmerɪkə/', 'A1', 'Hợp chủng quốc Hoa Kỳ; nước Mỹ; châu Mỹ (gồm cả Bắc và Nam Mỹ)', 'n.', 'American (adj.), American (n.)', NULL, 'Trong đời sống thường chỉ nước Mỹ; từ the Americas dùng để chỉ chung hai châu Mỹ.', 'My cousin moved to America to study engineering.', NULL, 'Anh họ của tôi đã chuyển đến Mỹ để học ngành kỹ thuật.', '{"wordId":"america","ukIpa":"/əˈmerɪkə/","usIpa":"/əˈmerɪkə/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"the United States of America","vi":"Hợp chủng quốc Hoa Kỳ; nước Mỹ"},{"pos":"n.","en":"North and South America considered together","vi":"châu Mỹ (gồm cả Bắc và Nam Mỹ)"}],"examples":[{"en":"My cousin moved to America to study engineering.","vi":"Anh họ của tôi đã chuyển đến Mỹ để học ngành kỹ thuật.","audioKind":"ex"},{"en":"Many universities in America attract international students through their research facilities and diverse academic programmes.","vi":"Nhiều trường đại học ở Mỹ thu hút sinh viên quốc tế thông qua các cơ sở nghiên cứu và chương trình học thuật đa dạng.","audioKind":"ex2"}],"collocations":[{"en":"North America","vi":"Bắc Mỹ"},{"en":"South America","vi":"Nam Mỹ"},{"en":"across America","vi":"khắp nước Mỹ"}],"wordFamily":["American (adj.)","American (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong đời sống thường chỉ nước Mỹ; từ the Americas dùng để chỉ chung hai châu Mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sweden', 'en-a1-4', 'Sweden', '/ˈswiːdən/', 'A1', 'Thụy Điển', 'n.', 'Swedish (adj.), Swede (n.)', NULL, 'Sweden là Thụy Điển; Switzerland mới là Thụy Sĩ.', 'We travelled through Sweden by train last summer.', NULL, 'Chúng tôi đã đi du lịch qua Thụy Điển bằng tàu hỏa vào mùa hè năm ngoái.', '{"wordId":"sweden","ukIpa":"/ˈswiːdən/","usIpa":"/ˈswiːdən/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"a country in northern Europe, with Stockholm as its capital","vi":"Thụy Điển"}],"examples":[{"en":"We travelled through Sweden by train last summer.","vi":"Chúng tôi đã đi du lịch qua Thụy Điển bằng tàu hỏa vào mùa hè năm ngoái.","audioKind":"ex"},{"en":"Sweden is frequently discussed in international debates about public welfare, environmental policy, and the funding of education.","vi":"Thụy Điển thường xuyên được nhắc đến trong các cuộc tranh luận quốc tế về phúc lợi công cộng, chính sách môi trường và nguồn vốn cho giáo dục.","audioKind":"ex2"}],"collocations":[{"en":"southern Sweden","vi":"miền nam Thụy Điển"},{"en":"travel to Sweden","vi":"đi du lịch Thụy Điển"},{"en":"Sweden''s capital","vi":"thủ đô của Thụy Điển"}],"wordFamily":["Swedish (adj.)","Swede (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Sweden là Thụy Điển; Switzerland mới là Thụy Sĩ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_portugal', 'en-a1-4', 'Portugal', '/ˈpɔːrtʃəɡəl/', 'A1', 'Bồ Đào Nha', 'n.', 'Portuguese (adj.), Portuguese (n.)', NULL, 'Tên quốc gia thường không đi kèm mạo từ the; Portuguese chỉ tiếng Bồ Đào Nha hoặc thuộc về Bồ Đào Nha.', 'We travelled along the coast of Portugal by train.', NULL, 'Chúng tôi đã đi dọc theo bờ biển Bồ Đào Nha bằng tàu hỏa.', '{"wordId":"portugal","ukIpa":"/ˈpɔːtʃʊɡəl/","usIpa":"/ˈpɔːrtʃəɡəl/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"A country in southwestern Europe, west of Spain.","vi":"Bồ Đào Nha"}],"examples":[{"en":"We travelled along the coast of Portugal by train.","vi":"Chúng tôi đã đi dọc theo bờ biển Bồ Đào Nha bằng tàu hỏa.","audioKind":"ex"},{"en":"Tourism contributes to the economy of Portugal, but coastal development requires careful planning to protect natural habitats.","vi":"Du lịch đóng góp vào nền kinh tế Bồ Đào Nha, nhưng việc phát triển vùng ven biển đòi hỏi phải lập kế hoạch cẩn trọng để bảo vệ các sinh cảnh tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"mainland Portugal","vi":"lục địa Bồ Đào Nha"},{"en":"northern Portugal","vi":"miền bắc Bồ Đào Nha"},{"en":"the coast of Portugal","vi":"bờ biển Bồ Đào Nha"}],"wordFamily":["Portuguese (adj.)","Portuguese (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tên quốc gia thường không đi kèm mạo từ the; Portuguese chỉ tiếng Bồ Đào Nha hoặc thuộc về Bồ Đào Nha.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_england', 'en-a1-4', 'England', '/ˈɪŋɡlənd/', 'A1', 'Nước Anh', 'n.', 'English (adj.)', NULL, 'England chỉ dùng cho nước Anh, không đồng nghĩa với toàn bộ Vương quốc Anh (United Kingdom).', 'My cousin lives in a quiet village in England.', NULL, 'Anh họ của tôi sống ở một ngôi làng yên bình tại nước Anh.', '{"wordId":"england","ukIpa":"/ˈɪŋɡlənd/","usIpa":"/ˈɪŋɡlənd/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"A country forming part of the United Kingdom.","vi":"Nước Anh"}],"examples":[{"en":"My cousin lives in a quiet village in England.","vi":"Anh họ của tôi sống ở một ngôi làng yên bình tại nước Anh.","audioKind":"ex"},{"en":"Historic towns in England attract international visitors, creating jobs while increasing pressure on local infrastructure.","vi":"Những thị trấn lịch sử ở nước Anh thu hút du khách quốc tế, tạo ra việc làm đồng thời gia tăng áp lực lên cơ sở hạ tầng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"southern England","vi":"miền nam nước Anh"},{"en":"the north of England","vi":"miền bắc nước Anh"},{"en":"travel to England","vi":"đi du lịch Anh"}],"wordFamily":["English (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"England chỉ dùng cho nước Anh, không đồng nghĩa với toàn bộ Vương quốc Anh (United Kingdom).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_switzerland', 'en-a1-4', 'Switzerland', '/ˈswɪtsərlənd/', 'A1', 'Thụy Sĩ', 'n.', 'Swiss (adj.), Swiss (n.)', NULL, 'Switzerland là Thụy Sĩ, còn Sweden là Thụy Điển; tính từ và người/tiếng Thụy Sĩ dùng Swiss.', 'We travelled through Switzerland by train during our holiday.', NULL, 'Trong kỳ nghỉ, chúng tôi đã đi tàu hỏa du lịch khắp Thụy Sĩ.', '{"wordId":"switzerland","ukIpa":"/ˈswɪtsələnd/","usIpa":"/ˈswɪtsərlənd/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"a country in central Europe known for the Alps","vi":"Thụy Sĩ"}],"examples":[{"en":"We travelled through Switzerland by train during our holiday.","vi":"Trong kỳ nghỉ, chúng tôi đã đi tàu hỏa du lịch khắp Thụy Sĩ.","audioKind":"ex"},{"en":"Switzerland demonstrates how reliable rail networks can support tourism while reducing dependence on private cars.","vi":"Thụy Sĩ cho thấy mạng lưới đường sắt đáng tin cậy có thể hỗ trợ ngành du lịch đồng thời giảm sự phụ thuộc vào ô tô cá nhân như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"visit Switzerland","vi":"du lịch Thụy Sĩ"},{"en":"in Switzerland","vi":"ở Thụy Sĩ"},{"en":"travel to Switzerland","vi":"đi đến Thụy Sĩ"}],"wordFamily":["Swiss (adj.)","Swiss (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Switzerland là Thụy Sĩ, còn Sweden là Thụy Điển; tính từ và người/tiếng Thụy Sĩ dùng Swiss.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_italy', 'en-a1-4', 'Italy', '/ˈɪtəli/', 'A1', 'Ý (Italy)', 'n.', 'Italian (adj.), Italian (n.)', NULL, 'Tên quốc gia viết hoa chữ cái đầu và thường không đi kèm mạo từ the; Italian chỉ tiếng Ý hoặc người Ý.', 'We travelled around Italy by train last summer.', NULL, 'Mùa hè năm ngoái, chúng tôi đã đi du lịch vòng quanh nước Ý bằng tàu hỏa.', '{"wordId":"italy","ukIpa":"/ˈɪtəli/","usIpa":"/ˈɪtəli/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"A country in southern Europe whose capital is Rome.","vi":"Ý (Italy)"}],"examples":[{"en":"We travelled around Italy by train last summer.","vi":"Mùa hè năm ngoái, chúng tôi đã đi du lịch vòng quanh nước Ý bằng tàu hỏa.","audioKind":"ex"},{"en":"Italy attracts international visitors through its historic cities, distinctive cuisine, and rich artistic heritage.","vi":"Ý thu hút du khách quốc tế nhờ các thành phố lịch sử, ẩm thực đặc sắc và di sản nghệ thuật phong phú.","audioKind":"ex2"}],"collocations":[{"en":"southern Italy","vi":"miền Nam nước Ý"},{"en":"travel to Italy","vi":"đi du lịch Ý"},{"en":"made in Italy","vi":"sản xuất tại Ý"}],"wordFamily":["Italian (adj.)","Italian (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tên quốc gia viết hoa chữ cái đầu và thường không đi kèm mạo từ the; Italian chỉ tiếng Ý hoặc người Ý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_west', 'en-a1-4', 'west', '/west/', 'A1', 'hướng tây; phương tây; miền tây; thuộc phía tây; hướng về phía tây; về hướng tây; ở phía tây', 'n.', 'western (adj.), westward (adv.), westerly (adj.)', 'Trái nghĩa: east', 'Tên phương hướng thường viết thường; the West viết hoa khi chỉ các nước phương Tây.', 'Our kitchen window faces west, catching the evening sunshine.', NULL, 'Cửa sổ bếp nhà chúng tôi hướng về phía tây, đón ánh nắng chiều.', '{"wordId":"west","ukIpa":"/west/","usIpa":"/west/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"the direction where the sun sets, opposite east","vi":"hướng tây; phương tây; miền tây"},{"pos":"adj.","en":"in or facing the direction where the sun sets","vi":"thuộc phía tây; hướng về phía tây"},{"pos":"adv.","en":"towards or in the west","vi":"về hướng tây; ở phía tây"}],"examples":[{"en":"Our kitchen window faces west, catching the evening sunshine.","vi":"Cửa sổ bếp nhà chúng tôi hướng về phía tây, đón ánh nắng chiều.","audioKind":"ex"},{"en":"Investment in the west of the country could reduce regional inequalities and create employment opportunities.","vi":"Việc đầu tư vào miền tây của đất nước có thể thu hẹp khoảng cách vùng miền và tạo ra nhiều cơ hội việc làm.","audioKind":"ex2"}],"collocations":[{"en":"in the west","vi":"ở phía tây"},{"en":"head west","vi":"đi về hướng tây"},{"en":"west coast","vi":"bờ biển phía tây"},{"en":"due west","vi":"hướng chính tây"}],"wordFamily":["western (adj.)","westward (adv.)","westerly (adj.)"],"synonyms":[],"antonyms":["east"],"tipVi":"Tên phương hướng thường viết thường; the West viết hoa khi chỉ các nước phương Tây.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_japan', 'en-a1-4', 'Japan', '/dʒəˈpæn/', 'A1', 'Nhật Bản', 'n.', 'Japanese (adj.), Japanese (n.)', NULL, 'Tên quốc gia phải viết hoa chữ cái đầu và thường không đi kèm mạo từ the; người Nhật hoặc tiếng Nhật là Japanese.', 'We travelled around Japan by train during our holiday.', NULL, 'Chúng tôi đã đi du lịch vòng quanh Nhật Bản bằng tàu hỏa trong kỳ nghỉ của mình.', '{"wordId":"japan","ukIpa":"/dʒəˈpæn/","usIpa":"/dʒəˈpæn/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"An island country in East Asia","vi":"Nhật Bản"}],"examples":[{"en":"We travelled around Japan by train during our holiday.","vi":"Chúng tôi đã đi du lịch vòng quanh Nhật Bản bằng tàu hỏa trong kỳ nghỉ của mình.","audioKind":"ex"},{"en":"Japan has invested in earthquake-resistant buildings to reduce the risks associated with living in a seismically active region.","vi":"Nhật Bản đã đầu tư vào các tòa nhà chống động đất để giảm thiểu rủi ro liên quan đến việc sinh sống trong khu vực có hoạt động địa chấn cao.","audioKind":"ex2"}],"collocations":[{"en":"visit Japan","vi":"thăm Nhật Bản"},{"en":"in Japan","vi":"ở Nhật Bản"},{"en":"travel to Japan","vi":"đi du lịch Nhật Bản"}],"wordFamily":["Japanese (adj.)","Japanese (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tên quốc gia phải viết hoa chữ cái đầu và thường không đi kèm mạo từ the; người Nhật hoặc tiếng Nhật là Japanese.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_travel', 'en-a1-4', 'travel', '/ˈtrævl/', 'A1', 'đi lại; du lịch; chuyến đi; sự di chuyển; lan truyền; truyền đi', 'v.', 'traveller (n.), travelling (adj.)', 'Đồng nghĩa: journey', 'Khi chỉ việc đi du lịch chung chung thì travel là danh từ không đếm được; dùng a trip cho một chuyến đi cụ thể.', 'We usually travel by train to visit our grandparents.', NULL, 'Chúng tôi thường đi tàu hỏa đến thăm ông bà.', '{"wordId":"travel","ukIpa":"/ˈtrævl/","usIpa":"/ˈtrævl/","cefr":"A1","topic":"travel","senses":[{"pos":"v.","en":"To go from one place to another.","vi":"đi lại; du lịch"},{"pos":"n.","en":"The activity of going to other places.","vi":"chuyến đi; sự di chuyển"},{"pos":"v.","en":"To move or spread from one place to another.","vi":"lan truyền; truyền đi"}],"examples":[{"en":"We usually travel by train to visit our grandparents.","vi":"Chúng tôi thường đi tàu hỏa đến thăm ông bà.","audioKind":"ex"},{"en":"Affordable public transport enables residents to travel more sustainably and reduces dependence on private cars.","vi":"Hệ thống giao thông công cộng giá cả phải chăng giúp người dân di chuyển bền vững hơn và giảm sự phụ thuộc vào ô tô cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"travel abroad","vi":"đi du lịch nước ngoài"},{"en":"travel by train","vi":"đi du lịch bằng tàu hỏa"},{"en":"air travel","vi":"chuyến du lịch đường hàng không"},{"en":"travel insurance","vi":"bảo hiểm du lịch"}],"wordFamily":["traveller (n.)","travelling (adj.)"],"synonyms":["journey"],"antonyms":[],"tipVi":"Khi chỉ việc đi du lịch chung chung thì travel là danh từ không đếm được; dùng a trip cho một chuyến đi cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_britain', 'en-a1-4', 'Britain', '/ˈbrɪtən/', 'A1', 'nước Anh; đảo Anh; Đại Anh', 'n.', 'British (adj.), Briton (n.)', NULL, 'Britain thường chỉ Vương quốc Anh; Great Britain không bao gồm Bắc Ireland.', 'My cousin moved to Britain to study nursing.', NULL, 'Anh họ tôi đã chuyển đến Anh để học ngành điều dưỡng.', '{"wordId":"britain","ukIpa":"/ˈbrɪtən/","usIpa":"/ˈbrɪtən/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"the United Kingdom, or the island containing England, Scotland and Wales","vi":"nước Anh; đảo Anh; Đại Anh"}],"examples":[{"en":"My cousin moved to Britain to study nursing.","vi":"Anh họ tôi đã chuyển đến Anh để học ngành điều dưỡng.","audioKind":"ex"},{"en":"Britain has invested in offshore wind farms to reduce its reliance on fossil fuels for electricity generation.","vi":"Anh Quốc đã đầu tư vào các trang trại điện gió ngoài khơi để giảm sự phụ thuộc vào nhiên liệu hóa thạch trong việc phát điện.","audioKind":"ex2"}],"collocations":[{"en":"across Britain","vi":"khắp nước Anh"},{"en":"modern Britain","vi":"nước Anh hiện đại"},{"en":"Great Britain","vi":"Đại Anh"}],"wordFamily":["British (adj.)","Briton (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Britain thường chỉ Vương quốc Anh; Great Britain không bao gồm Bắc Ireland.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trip', 'en-a1-4', 'trip', '/trɪp/', 'A1', 'chuyến đi; cuộc hành trình; vấp ngã; làm vấp chân', 'n.', NULL, 'Đồng nghĩa: excursion, journey', 'trip là một danh từ đếm được; trong khi travel khi nói về hoạt động du lịch chung thường là danh từ không đếm được.', 'Our weekend trip to the coast was wonderfully relaxing.', NULL, 'Chuyến đi cuối tuần của chúng tôi đến vùng ven biển thật sự rất thư giãn.', '{"wordId":"trip","ukIpa":"/trɪp/","usIpa":"/trɪp/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"a journey to a place and usually back again","vi":"chuyến đi; cuộc hành trình"},{"pos":"v.","en":"to stumble or make someone stumble by catching a foot","vi":"vấp ngã; làm vấp chân"}],"examples":[{"en":"Our weekend trip to the coast was wonderfully relaxing.","vi":"Chuyến đi cuối tuần của chúng tôi đến vùng ven biển thật sự rất thư giãn.","audioKind":"ex"},{"en":"School trips to museums can enrich classroom learning by giving students direct access to historical objects.","vi":"Các chuyến tham quan bảo tàng do trường tổ chức có thể làm phong phú thêm việc học trên lớp bằng cách cho học sinh tiếp cận trực tiếp với các hiện vật lịch sử.","audioKind":"ex2"}],"collocations":[{"en":"go on a trip","vi":"đi du lịch; đi chơi"},{"en":"business trip","vi":"chuyến công tác"},{"en":"school trip","vi":"chuyến đi dã ngoại của trường"},{"en":"trip over","vi":"vấp phải"}],"wordFamily":[],"synonyms":["excursion","journey"],"antonyms":[],"tipVi":"trip là một danh từ đếm được; trong khi travel khi nói về hoạt động du lịch chung thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_driver', 'en-a1-4', 'driver', '/ˈdraɪvər/', 'A1', 'tài xế; người lái xe; động lực; nhân tố thúc đẩy; trình điều khiển thiết bị', 'n.', 'drive (v.), driving (n.)', 'Đồng nghĩa: motorist', 'a driver of change dùng để chỉ nhân tố thúc đẩy sự thay đổi.', 'The bus driver waited while I found my ticket.', NULL, 'Người lái xe buýt đã đợi trong lúc tôi tìm vé xe.', '{"wordId":"driver","ukIpa":"/ˈdraɪvə/","usIpa":"/ˈdraɪvər/","cefr":"A1","topic":"travel","senses":[{"pos":"n.","en":"A person who controls a car or another road vehicle.","vi":"tài xế; người lái xe"},{"pos":"n.","en":"Something that strongly influences or causes a development.","vi":"động lực; nhân tố thúc đẩy"},{"pos":"n.","en":"Software that lets a computer communicate with a device.","vi":"trình điều khiển thiết bị"}],"examples":[{"en":"The bus driver waited while I found my ticket.","vi":"Người lái xe buýt đã đợi trong lúc tôi tìm vé xe.","audioKind":"ex"},{"en":"Investment in public transport can be a major driver of economic growth in expanding cities.","vi":"Việc đầu tư vào giao thông công cộng có thể trở thành động lực chính thúc đẩy tăng trưởng kinh tế ở những thành phố đang mở rộng.","audioKind":"ex2"}],"collocations":[{"en":"bus driver","vi":"tài xế xe buýt"},{"en":"a key driver of growth","vi":"động lực chính của sự tăng trưởng"},{"en":"install a driver","vi":"cài đặt trình điều khiển"}],"wordFamily":["drive (v.)","driving (n.)"],"synonyms":["motorist"],"antonyms":[],"tipVi":"a driver of change dùng để chỉ nhân tố thúc đẩy sự thay đổi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_4_1', 'en-a1-4', 'Cách dùng “trip” (n.) — chuyến đi; cuộc hành trình', 'go on a trip  ·  business trip  ·  school trip', 'trip là một danh từ đếm được; trong khi travel khi nói về hoạt động du lịch chung thường là danh từ không đếm được.', 'Đồng nghĩa: excursion, journey', '[{"hanzi":"Our weekend trip to the coast was wonderfully relaxing.","pinyin":"","meaning":"Chuyến đi cuối tuần của chúng tôi đến vùng ven biển thật sự rất thư giãn."},{"hanzi":"School trips to museums can enrich classroom learning by giving students direct access to historical objects.","pinyin":"","meaning":"Các chuyến tham quan bảo tàng do trường tổ chức có thể làm phong phú thêm việc học trên lớp bằng cách cho học sinh tiếp cận trực tiếp với các hiện vật lịch sử."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_4_2', 'en-a1-4', 'Cách dùng “Japan” (n.) — Nhật Bản', 'visit Japan  ·  in Japan  ·  travel to Japan', 'Tên quốc gia phải viết hoa chữ cái đầu và thường không đi kèm mạo từ the; người Nhật hoặc tiếng Nhật là Japanese.', 'Họ từ (Word Family): Japanese (adj.), Japanese (n.)', '[{"hanzi":"We travelled around Japan by train during our holiday.","pinyin":"","meaning":"Chúng tôi đã đi du lịch vòng quanh Nhật Bản bằng tàu hỏa trong kỳ nghỉ của mình."},{"hanzi":"Japan has invested in earthquake-resistant buildings to reduce the risks associated with living in a seismically active region.","pinyin":"","meaning":"Nhật Bản đã đầu tư vào các tòa nhà chống động đất để giảm thiểu rủi ro liên quan đến việc sinh sống trong khu vực có hoạt động địa chấn cao."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_4_3', 'en-a1-4', 'Cách dùng “travel” (v.) — đi lại; du lịch', 'travel abroad  ·  travel by train  ·  air travel', 'Khi chỉ việc đi du lịch chung chung thì travel là danh từ không đếm được; dùng a trip cho một chuyến đi cụ thể.', 'Họ từ (Word Family): traveller (n.), travelling (adj.) | Đồng nghĩa: journey', '[{"hanzi":"We usually travel by train to visit our grandparents.","pinyin":"","meaning":"Chúng tôi thường đi tàu hỏa đến thăm ông bà."},{"hanzi":"Affordable public transport enables residents to travel more sustainably and reduces dependence on private cars.","pinyin":"","meaning":"Hệ thống giao thông công cộng giá cả phải chăng giúp người dân di chuyển bền vững hơn và giảm sự phụ thuộc vào ô tô cá nhân."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_4_4', 'en-a1-4', 'Cách dùng “Asia” (n.) — châu Á', 'East Asia  ·  Southeast Asia  ·  Central Asia', 'Tên châu lục phải viết hoa chữ cái đầu và thường không đi kèm mạo từ the; tính từ tương ứng là Asian.', 'Họ từ (Word Family): Asian (adj.)', '[{"hanzi":"My cousin spent three months travelling around Asia.","pinyin":"","meaning":"Anh họ của tôi đã dành ba tháng để du lịch khắp châu Á."},{"hanzi":"Rapid urban growth in Asia has increased the need for affordable housing and reliable public transport.","pinyin":"","meaning":"Sự phát triển đô thị nhanh chóng ở châu Á đã làm tăng nhu cầu về nhà ở giá rẻ và giao thông công cộng đáng tin cậy."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
