INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_4_1_5', 'ten_4_1', 'Australia', 'My cousin moved to Australia to study marine biology.', 'My cousin moved to Australia to study marine biology.', '/ɔːˈstreɪljə/', 'Anh họ của tôi đã chuyển đến Úc để học ngành sinh học biển.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
