INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_4_1_8', 'ten_4_1', 'south', 'Our balcony faces south and gets plenty of sunshine.', 'Our balcony faces south and gets plenty of sunshine.', '/saʊθ/', 'Ban công nhà chúng tôi quay về hướng nam và đón được rất nhiều ánh nắng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_4_1_1', 'en-a1-4', 'ten_4_1', 'listening', 'listening', 'We travelled around Spain by train last summer.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã khám phá các di tích cổ trong kỳ nghỉ ở Mê-hi-cô.","Mùa hè năm ngoái chúng tôi đã đi du lịch khắp Tây Ban Nha bằng tàu hỏa.","Ban công nhà chúng tôi quay về hướng nam và đón được rất nhiều ánh nắng.","Anh họ của tôi đã chuyển đến Úc để học ngành sinh học biển."]'::jsonb, 1, 'We travelled around Spain by train last summer. → Mùa hè năm ngoái chúng tôi đã đi du lịch khắp Tây Ban Nha bằng tàu hỏa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_4_1_2', 'en-a1-4', 'ten_4_1', 'listening', 'listening', 'My cousin travelled across Europe by train last summer.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã khám phá các di tích cổ trong kỳ nghỉ ở Mê-hi-cô.","Anh họ tôi đã đi du lịch khắp châu Âu bằng tàu hỏa vào mùa hè năm ngoái.","Ban công nhà chúng tôi quay về hướng nam và đón được rất nhiều ánh nắng.","Chúng tôi đã đến sân bay trước khi mặt trời mọc."]'::jsonb, 1, 'My cousin travelled across Europe by train last summer. → Anh họ tôi đã đi du lịch khắp châu Âu bằng tàu hỏa vào mùa hè năm ngoái.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_4_1_3', 'en-a1-4', 'ten_4_1', 'listening', 'listening', 'We arrived at the airport before the sun rose.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã đến sân bay trước khi mặt trời mọc.","Anh họ tôi đã đi du lịch khắp châu Âu bằng tàu hỏa vào mùa hè năm ngoái.","Mùa hè năm ngoái chúng tôi đã đi du lịch khắp Tây Ban Nha bằng tàu hỏa.","Anh họ của tôi đã chuyển đến Úc để học ngành sinh học biển."]'::jsonb, 0, 'We arrived at the airport before the sun rose. → Chúng tôi đã đến sân bay trước khi mặt trời mọc.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_4_2', 'en-a1-4', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_4_2_1', 'ten_4_2', 'Spain', 'Spain attracts international visitors through its cultural heritage, varied landscapes, and well-developed tourism infrastructure.', 'Spain attracts international visitors through its cultural heritage, varied landscapes, and well-developed tourism infrastructure.', '/speɪn/', 'Tây Ban Nha thu hút du khách quốc tế nhờ di sản văn hóa, cảnh quan đa dạng và cơ sở hạ tầng du lịch phát triển tốt.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_4_2_2', 'ten_4_2', 'Europe', 'Many cities in Europe are expanding cycling networks to reduce traffic congestion and improve urban air quality.', 'Many cities in Europe are expanding cycling networks to reduce traffic congestion and improve urban air quality.', '/ˈjʊrəp/', 'Nhiều thành phố ở châu Âu đang mở rộng mạng lưới đường dành cho xe đạp để giảm ùn tắc giao thông và cải thiện chất lượng không khí đô thị.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_4_2_3', 'ten_4_2', 'airport', 'Expanding an airport may boost tourism, but it can also increase noise pollution for nearby residents.', 'Expanding an airport may boost tourism, but it can also increase noise pollution for nearby residents.', '/ˈerpɔːrt/', 'Việc mở rộng sân bay có thể thúc đẩy ngành du lịch, nhưng nó cũng có thể làm tăng ô nhiễm tiếng ồn đối với cư dân sống ở khu vực lân cận.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_4_2_4', 'ten_4_2', 'far', 'Reliable public transport can make commuting far more affordable for people who live outside major city centres.', 'Reliable public transport can make commuting far more affordable for people who live outside major city centres.', '/fɑr/', 'Hệ thống giao thông công cộng đáng tin cậy có thể giúp cho việc đi lại của những người sống ngoài khu vực trung tâm thành phố trở nên tiết kiệm hơn rất nhiều.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_4_2_5', 'ten_4_2', 'Australia', 'Australia attracts international students through its universities, diverse cities, and opportunities to study in English.', 'Australia attracts international students through its universities, diverse cities, and opportunities to study in English.', '/ɔːˈstreɪljə/', 'Úc thu hút sinh viên quốc tế nhờ các trường đại học, các thành phố đa dạng văn hóa và cơ hội học tập bằng tiếng Anh.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_4_2_6', 'ten_4_2', 'Asia', 'Rapid urban growth in Asia has increased the need for affordable housing and reliable public transport.', 'Rapid urban growth in Asia has increased the need for affordable housing and reliable public transport.', '/ˈeɪʒə/', 'Sự phát triển đô thị nhanh chóng ở châu Á đã làm tăng nhu cầu về nhà ở giá rẻ và giao thông công cộng đáng tin cậy.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_4_2_1', 'en-a1-4', 'ten_4_2', 'listening', 'listening', 'Spain attracts international visitors through its cultural heritage, varied landscapes, and well-developed tourism infrastructure.', NULL, 'Trong câu vừa nghe, từ “Spain” mang nghĩa nào sau đây?', '["môn bóng rổ","Tây Ban Nha","xám; có màu xám","thông tin; tài liệu"]'::jsonb, 1, '“Spain” (/speɪn/): Tây Ban Nha. Câu đầy đủ: Spain attracts international visitors through its cultural heritage, varied landscapes, and well-developed tourism infrastructure.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_4_2_2', 'en-a1-4', 'ten_4_2', 'listening', 'listening', 'Many cities in Europe are expanding cycling networks to reduce traffic congestion and improve urban air quality.', NULL, 'Trong câu vừa nghe, từ “Europe” mang nghĩa nào sau đây?', '["hứng khởi; hào hứng; phấn khích","ở giữa; trong khoảng thời gian giữa","châu Âu","nam cảnh sát"]'::jsonb, 2, '“Europe” (/ˈjʊrəp/): châu Âu. Câu đầy đủ: Many cities in Europe are expanding cycling networks to reduce traffic congestion and improve urban air quality.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
