INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_4_4', 'en-a1-4', NULL, 'comprehensive_test', 'listening', 'We walked so far that our feet began to ache.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Trong kỳ nghỉ, chúng tôi đã đi tàu hỏa du lịch khắp Thụy Sĩ.","Người lái xe buýt đã đợi trong lúc tôi tìm vé xe.","Chúng tôi đi bộ xa đến mức chân bắt đầu ê ẩm.","Anh họ của tôi sống ở một ngôi làng yên bình tại nước Anh."]'::jsonb, 2, 'We walked so far that our feet began to ache. → Chúng tôi đi bộ xa đến mức chân bắt đầu ê ẩm.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_4_5', 'en-a1-4', NULL, 'comprehensive_test', 'listening', 'Australia', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["máy ảnh; máy quay phim; camera","bắt đầu; khởi đầu","một... nữa; khác","Úc; nước Úc; Australia"]'::jsonb, 3, 'Australia (/ɔːˈstreɪljə/) → Úc; nước Úc; Australia', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_4_6', 'en-a1-4', NULL, 'comprehensive_test', 'listening', 'My cousin spent three months travelling around Asia.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mùa hè năm ngoái chúng tôi đã đi du lịch khắp Tây Ban Nha bằng tàu hỏa.","Anh họ của tôi đã chuyển đến Mỹ để học ngành kỹ thuật.","Anh họ của tôi đã chuyển đến Úc để học ngành sinh học biển.","Anh họ của tôi đã dành ba tháng để du lịch khắp châu Á."]'::jsonb, 3, 'My cousin spent three months travelling around Asia. → Anh họ của tôi đã dành ba tháng để du lịch khắp châu Á.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_4_7', 'en-a1-4', NULL, 'comprehensive_test', 'listening', 'Mexico', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sẵn sàng; đã chuẩn bị xong","nước Mê-hi-cô","quả bóng; vật hình cầu","một nửa; nửa"]'::jsonb, 1, 'Mexico (/ˈmeksɪkoʊ/) → nước Mê-hi-cô', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_4_8', 'en-a1-4', NULL, 'comprehensive_test', 'listening', 'Our balcony faces south and gets plenty of sunshine.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi thường đi tàu hỏa đến thăm ông bà.","Chúng tôi đi bộ xa đến mức chân bắt đầu ê ẩm.","Chúng tôi đã đến sân bay trước khi mặt trời mọc.","Ban công nhà chúng tôi quay về hướng nam và đón được rất nhiều ánh nắng."]'::jsonb, 3, 'Our balcony faces south and gets plenty of sunshine. → Ban công nhà chúng tôi quay về hướng nam và đón được rất nhiều ánh nắng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_4_9', 'en-a1-4', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a country occupying a continent between the Indian and Pacific Oceans”?', '["Australia","Italy","visit","Spain"]'::jsonb, 0, 'Australia (/ɔːˈstreɪljə/) → Úc; nước Úc; Australia', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
