INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_4_12', 'en-a1-4', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the direction opposite north”?', '["Sweden","Asia","far","south"]'::jsonb, 3, 'south (/saʊθ/) → phương nam; hướng nam', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
