INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_4_18', 'en-a1-4', NULL, 'comprehensive_test', 'reading', NULL, 'Spain attracts international visitors through its cultural heritage, varied landscapes, and well-developed tourism infrastructure.', 'Dựa vào câu trên, từ “Spain” có nghĩa phù hợp nhất là gì?', '["danhmục; danh sách","Tây Ban Nha","này; chào (dùng thân mật để chào hỏi hoặc thu hút sự chú ý)","mẩu giấy nhắn; ghi chú"]'::jsonb, 1, 'Spain: Tây Ban Nha. Dịch cả câu: Tây Ban Nha thu hút du khách quốc tế nhờ di sản văn hóa, cảnh quan đa dạng và cơ sở hạ tầng du lịch phát triển tốt.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_4_19', 'en-a1-4', NULL, 'comprehensive_test', 'reading', NULL, 'Many cities in Europe are expanding cycling networks to reduce traffic congestion and improve urban air quality.', 'Dựa vào câu trên, từ “Europe” có nghĩa phù hợp nhất là gì?', '["chồng","nhà văn; tác giả; người viết sách, bài báo hoặc các văn bản khác","châu Âu","tháng"]'::jsonb, 2, 'Europe: châu Âu. Dịch cả câu: Nhiều thành phố ở châu Âu đang mở rộng mạng lưới đường dành cho xe đạp để giảm ùn tắc giao thông và cải thiện chất lượng không khí đô thị.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_4_20', 'en-a1-4', NULL, 'comprehensive_test', 'reading', NULL, 'Expanding an airport may boost tourism, but it can also increase noise pollution for nearby residents.', 'Dựa vào câu trên, từ “airport” có nghĩa phù hợp nhất là gì?', '["sự nghỉ ngơi; khoảng thời gian thư giãn","lạnh; lạnh lẽo","sân bay","xu (đơn vị tiền tệ bằng một phần trăm của đô-la hoặc ơ-rô)"]'::jsonb, 2, 'airport: sân bay. Dịch cả câu: Việc mở rộng sân bay có thể thúc đẩy ngành du lịch, nhưng nó cũng có thể làm tăng ô nhiễm tiếng ồn đối với cư dân sống ở khu vực lân cận.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_4_21', 'en-a1-4', NULL, 'comprehensive_test', 'reading', NULL, 'Reliable public transport can make commuting far more affordable for people who live outside major city centres.', 'Dựa vào câu trên, từ “far” có nghĩa phù hợp nhất là gì?', '["ở khoảng cách xa; xa xôi","n. rượu vang; rượu nho","lái xe; điều khiển phương tiện","đường; đường ăn"]'::jsonb, 0, 'far: ở khoảng cách xa; xa xôi; hơn rất nhiều; đáng kể; xa hơn; ở xa hơn. Dịch cả câu: Hệ thống giao thông công cộng đáng tin cậy có thể giúp cho việc đi lại của những người sống ngoài khu vực trung tâm thành phố trở nên tiết kiệm hơn rất nhiều.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
