INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-5', 'en', 'Bài 5: Xã hội & Cộng đồng (1) - CEFR A1', 'CEFR A1', 'A1 · Xã hội', '24 từ vựng Tiếng Anh CEFR A1 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1005, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_born', 'en-a1-5', 'born', '/bɔːrn/', 'A1', 'sinh ra; bẩm sinh; có năng khiếu', 'v.', 'bear (v.), newborn (adj.)', NULL, 'Nói về việc sinh ra dùng be born; quá khứ dùng was/were born.', 'My little sister was born on a snowy morning.', NULL, 'Em gái tôi sinh vào một buổi sáng có tuyết.', '{"wordId":"born","ukIpa":"/bɔːn/","usIpa":"/bɔːrn/","cefr":"A1","topic":"society","senses":[{"pos":"v.","en":"Brought into the world as a baby","vi":"sinh ra"},{"pos":"adj.","en":"Having a natural ability for a particular activity","vi":"bẩm sinh; có năng khiếu"}],"examples":[{"en":"My little sister was born on a snowy morning.","vi":"Em gái tôi sinh vào một buổi sáng có tuyết.","audioKind":"ex"},{"en":"Children born in rural areas may face greater difficulties accessing specialist healthcare than those in cities.","vi":"Trẻ em sinh ra ở các vùng nông thôn có thể phải đối mặt với nhiều khó khăn hơn trong việc tiếp cận dịch vụ chăm sóc y tế chuyên khoa so với trẻ em ở thành phố.","audioKind":"ex2"}],"collocations":[{"en":"be born in","vi":"sinh ra ở"},{"en":"be born into a family","vi":"sinh ra trong một gia đình"},{"en":"a born leader","vi":"một nhà lãnh đạo bẩm sinh"}],"wordFamily":["bear (v.)","newborn (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nói về việc sinh ra dùng be born; quá khứ dùng was/were born.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_japanese', 'en-a1-5', 'Japanese', '/ˌdʒæpəˈniːz/', 'A1', 'thuộc về Nhật Bản; thuộc về tiếng Nhật; tiếng Nhật; người Nhật Bản', 'adj.', 'Japan (n.)', NULL, 'Chữ cái đầu luôn được viết hoa; để chỉ một người Nhật Bản, thường dùng a Japanese person.', 'We enjoyed Japanese food at a small restaurant yesterday.', NULL, 'Hôm qua chúng tôi đã thưởng thức món ăn Nhật tại một nhà hàng nhỏ.', '{"wordId":"japanese","ukIpa":"/ˌdʒæpəˈniːz/","usIpa":"/ˌdʒæpəˈniːz/","cefr":"A1","topic":"society","senses":[{"pos":"adj.","en":"Relating to Japan, its people, or its language.","vi":"thuộc về Nhật Bản; thuộc về tiếng Nhật"},{"pos":"n.","en":"The language used by most people in Japan.","vi":"tiếng Nhật"},{"pos":"n.","en":"A person from Japan, or the people of Japan collectively.","vi":"người Nhật Bản"}],"examples":[{"en":"We enjoyed Japanese food at a small restaurant yesterday.","vi":"Hôm qua chúng tôi đã thưởng thức món ăn Nhật tại một nhà hàng nhỏ.","audioKind":"ex"},{"en":"Studying Japanese architecture can help students understand how traditional design responds to local environmental conditions.","vi":"Nghiên cứu kiến trúc Nhật Bản có thể giúp sinh viên hiểu cách các thiết kế truyền thống ứng phó với điều kiện môi trường địa phương.","audioKind":"ex2"}],"collocations":[{"en":"Japanese cuisine","vi":"ẩm thực Nhật Bản"},{"en":"Japanese architecture","vi":"kiến trúc Nhật Bản"},{"en":"learn Japanese","vi":"học tiếng Nhật"},{"en":"Japanese culture","vi":"văn hóa Nhật Bản"}],"wordFamily":["Japan (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ cái đầu luôn được viết hoa; để chỉ một người Nhật Bản, thường dùng a Japanese person.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_child', 'en-a1-5', 'child', '/tʃaɪld/', 'A1', 'trẻ em; đứa trẻ; con cái', 'n.', 'childhood (n.), childish (adj.), childlike (adj.), childless (adj.)', 'Đồng nghĩa: kid · Trái nghĩa: adult', 'Dạng số nhiều là children; childish mang nghĩa hơi tiêu cực (trẻ con, ngớ ngẩn), còn childlike mang nghĩa tích cực (ngây thơ như trẻ thơ).', 'The child carefully carried a bowl of water outside.', NULL, 'Đứa trẻ cẩn thận bưng một bát nước đi ra ngoài.', '{"wordId":"child","ukIpa":"/tʃaɪld/","usIpa":"/tʃaɪld/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"a young person who has not yet become an adult","vi":"trẻ em; đứa trẻ"},{"pos":"n.","en":"someone''s son or daughter, regardless of age","vi":"con cái"}],"examples":[{"en":"The child carefully carried a bowl of water outside.","vi":"Đứa trẻ cẩn thận bưng một bát nước đi ra ngoài.","audioKind":"ex"},{"en":"Every child should have access to quality education, regardless of family income or place of residence.","vi":"Mỗi đứa trẻ đều nên được tiếp cận với nền giáo dục chất lượng, bất kể thu nhập của gia đình hay nơi sinh sống.","audioKind":"ex2"}],"collocations":[{"en":"an only child","vi":"con một"},{"en":"child development","vi":"sự phát triển của trẻ em"},{"en":"raise a child","vi":"nuôi dạy con cái"}],"wordFamily":["childhood (n.)","childish (adj.)","childlike (adj.)","childless (adj.)"],"synonyms":["kid"],"antonyms":["adult"],"tipVi":"Dạng số nhiều là children; childish mang nghĩa hơi tiêu cực (trẻ con, ngớ ngẩn), còn childlike mang nghĩa tích cực (ngây thơ như trẻ thơ).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kind', 'en-a1-5', 'kind', '/kaɪnd/', 'A1', 'tử tế; tốt bụng; chu đáo; loại; loài', 'adj.', 'kindness (n.), kindly (adv.), unkind (adj.)', 'Đồng nghĩa: caring, considerate · Trái nghĩa: unkind, cruel', 'Tính từ thường đi với giới từ to; để chỉ chủng loại thì dùng cấu trúc a kind of kết hợp với danh từ.', 'Our kind neighbour brought us soup when we were ill.', NULL, 'Người hàng xóm tốt bụng đã mang súp cho chúng tôi khi chúng tôi ốm.', '{"wordId":"kind","ukIpa":"/kaɪnd/","usIpa":"/kaɪnd/","cefr":"A1","topic":"society","senses":[{"pos":"adj.","en":"Caring about others and willing to help them.","vi":"tử tế; tốt bụng; chu đáo"},{"pos":"n.","en":"A group of things sharing similar features.","vi":"loại; loài"}],"examples":[{"en":"Our kind neighbour brought us soup when we were ill.","vi":"Người hàng xóm tốt bụng đã mang súp cho chúng tôi khi chúng tôi ốm.","audioKind":"ex"},{"en":"Schools should encourage students to be kind to others, helping create a more supportive learning environment.","vi":"Các trường học nên khuyến khích học sinh đối xử tử tế với người khác, giúp tạo ra một môi trường học tập hỗ trợ tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"be kind to someone","vi":"tử tế với ai đó"},{"en":"a kind of","vi":"một loại"},{"en":"all kinds of","vi":"tất cả các loại"},{"en":"kind words","vi":"những lời nói ấm lòng"}],"wordFamily":["kindness (n.)","kindly (adv.)","unkind (adj.)"],"synonyms":["caring","considerate"],"antonyms":["unkind","cruel"],"tipVi":"Tính từ thường đi với giới từ to; để chỉ chủng loại thì dùng cấu trúc a kind of kết hợp với danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_policeman', 'en-a1-5', 'policeman', '/pəˈliːsmən/', 'A1', 'nam cảnh sát', 'n.', 'police (n.), policewoman (n.)', NULL, 'policeman chỉ nam giới; khi không muốn nhấn mạnh giới tính, hãy dùng police officer.', 'A policeman helped us cross the busy road.', NULL, 'Một nam cảnh sát đã giúp chúng tôi băng qua con đường đông đúc.', '{"wordId":"policeman","ukIpa":"/pəˈliːsmən/","usIpa":"/pəˈliːsmən/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"a male police officer","vi":"nam cảnh sát"}],"examples":[{"en":"A policeman helped us cross the busy road.","vi":"Một nam cảnh sát đã giúp chúng tôi băng qua con đường đông đúc.","audioKind":"ex"},{"en":"A local policeman visited the school to explain how children can stay safe online.","vi":"Một nam cảnh sát địa phương đã đến trường để giải thích cho học sinh cách giữ an toàn khi trực tuyến.","audioKind":"ex2"}],"collocations":[{"en":"traffic policeman","vi":"cảnh sát giao thông"},{"en":"uniformed policeman","vi":"nam cảnh sát mặc đồng phục"}],"wordFamily":["police (n.)","policewoman (n.)"],"synonyms":[],"antonyms":[],"tipVi":"policeman chỉ nam giới; khi không muốn nhấn mạnh giới tính, hãy dùng police officer.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_poor', 'en-a1-5', 'poor', '/pʊr/', 'A1', 'nghèo; nghèo khó; kém; kém chất lượng; thiếu thốn; đáng thương', 'adj.', 'poverty (n.), poorly (adv.)', 'Trái nghĩa: rich', 'poor at dùng khi không giỏi việc gì; poor in dùng khi thiếu cái gì.', 'The poor family could barely afford fresh vegetables.', NULL, 'Gia đình nghèo khó đó hầu như không đủ tiền mua rau tươi.', '{"wordId":"poor","ukIpa":"/pɔː/","usIpa":"/pʊr/","cefr":"A1","topic":"society","senses":[{"pos":"adj.","en":"Having very little money or few possessions","vi":"nghèo; nghèo khó"},{"pos":"adj.","en":"Of low quality or lacking something necessary","vi":"kém; kém chất lượng; thiếu thốn"},{"pos":"adj.","en":"Deserving sympathy because of an unfortunate situation","vi":"đáng thương"}],"examples":[{"en":"The poor family could barely afford fresh vegetables.","vi":"Gia đình nghèo khó đó hầu như không đủ tiền mua rau tươi.","audioKind":"ex"},{"en":"Poor public transport can limit employment opportunities for people living far from major urban centres.","vi":"Hệ thống giao thông công cộng kém phát triển có thể làm hạn chế cơ hội việc làm của những người sống xa các trung tâm đô thị lớn.","audioKind":"ex2"}],"collocations":[{"en":"poor health","vi":"sức khỏe kém"},{"en":"poor quality","vi":"chất lượng kém"},{"en":"poor in nutrients","vi":"thiếu dưỡng chất"},{"en":"poor families","vi":"các gia đình nghèo"}],"wordFamily":["poverty (n.)","poorly (adv.)"],"synonyms":[],"antonyms":["rich"],"tipVi":"poor at dùng khi không giỏi việc gì; poor in dùng khi thiếu cái gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_girl', 'en-a1-5', 'girl', '/ɡɝːl/', 'A1', 'bé gái; con gái; thiếu nữ', 'n.', 'girlhood (n.), girlish (adj.)', 'Trái nghĩa: boy', 'Phụ nữ trưởng thành gọi chính thức là woman; girl không dùng trực tiếp để chỉ bạn gái.', 'The girl carefully carried her kitten into the house.', NULL, 'Cô bé cẩn thận bế chú mèo con của mình vào nhà.', '{"wordId":"girl","ukIpa":"/ɡɜːl/","usIpa":"/ɡɝːl/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"A female child or young woman","vi":"bé gái; con gái; thiếu nữ"}],"examples":[{"en":"The girl carefully carried her kitten into the house.","vi":"Cô bé cẩn thận bế chú mèo con của mình vào nhà.","audioKind":"ex"},{"en":"Ensuring that every girl can attend school is essential for reducing inequality and supporting economic development.","vi":"Đảm bảo mọi bé gái đều được đến trường là điều cốt yếu để giảm thiểu bất bình đẳng và hỗ trợ phát triển kinh tế.","audioKind":"ex2"}],"collocations":[{"en":"young girl","vi":"bé gái"},{"en":"teenage girl","vi":"thiếu nữ tuổi teen"},{"en":"school girl","vi":"nữ sinh"}],"wordFamily":["girlhood (n.)","girlish (adj.)"],"synonyms":[],"antonyms":["boy"],"tipVi":"Phụ nữ trưởng thành gọi chính thức là woman; girl không dùng trực tiếp để chỉ bạn gái.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_husband', 'en-a1-5', 'husband', '/ˈhʌzbənd/', 'A1', 'chồng; tiết kiệm; sử dụng tiết kiệm', 'n.', NULL, 'Đồng nghĩa: spouse', 'Khi là động từ, từ này mang tính trang trọng, chỉ việc sử dụng tài nguyên một cách tiết kiệm.', 'Her husband brought her lunch during a busy shift.', NULL, 'Chồng cô ấy đã mang bữa trưa đến cho cô ấy trong một ca làm việc bận rộn.', '{"wordId":"husband","ukIpa":"/ˈhʌzbənd/","usIpa":"/ˈhʌzbənd/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"a married man considered in relation to his spouse","vi":"chồng"},{"pos":"v.","en":"to use resources carefully so they last longer","vi":"tiết kiệm; sử dụng tiết kiệm"}],"examples":[{"en":"Her husband brought her lunch during a busy shift.","vi":"Chồng cô ấy đã mang bữa trưa đến cho cô ấy trong một ca làm việc bận rộn.","audioKind":"ex"},{"en":"When husbands share household responsibilities equally, both partners have more opportunities to pursue their careers.","vi":"Khi người chồng chia sẻ việc nhà một cách bình đẳng, cả hai vợ chồng đều có nhiều cơ hội hơn để theo đuổi sự nghiệp của mình.","audioKind":"ex2"}],"collocations":[{"en":"her husband","vi":"chồng cô ấy"},{"en":"husband and wife","vi":"vợ chồng"},{"en":"husband resources","vi":"sử dụng tiết kiệm tài nguyên"}],"wordFamily":[],"synonyms":["spouse"],"antonyms":[],"tipVi":"Khi là động từ, từ này mang tính trang trọng, chỉ việc sử dụng tài nguyên một cách tiết kiệm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_friendly', 'en-a1-5', 'friendly', '/ˈfrendli/', 'A1', 'adj. thân thiện; cởi mở; niềm nở; n. trận đấu giao hữu', 'adj.', 'friend (n.), friendship (n.), friendliness (n.), unfriendly (adj.)', 'Đồng nghĩa: welcoming, amiable · Trái nghĩa: unfriendly, hostile', 'Mặc dù tận cùng bằng đuôi -ly, từ này là tính từ chứ không phải phó từ.', 'Our new neighbour is friendly and always waves hello.', NULL, 'Người hàng xóm mới của chúng tôi rất thân thiện và luôn vẫy tay chào.', '{"wordId":"friendly","ukIpa":"/ˈfrendli/","usIpa":"/ˈfrendli/","cefr":"A1","topic":"society","senses":[{"pos":"adj.","en":"Kind, welcoming, and pleasant towards other people.","vi":"adj. thân thiện; cởi mở; niềm nở"},{"pos":"n.","en":"A sports match played outside an official competition.","vi":"n. trận đấu giao hữu"}],"examples":[{"en":"Our new neighbour is friendly and always waves hello.","vi":"Người hàng xóm mới của chúng tôi rất thân thiện và luôn vẫy tay chào.","audioKind":"ex"},{"en":"Friendly staff can improve patients'' experiences and encourage them to seek medical advice earlier.","vi":"Nhân viên thân thiện có thể cải thiện trải nghiệm của bệnh nhân và khuyến khích họ tìm kiếm lời khuyên y tế sớm hơn.","audioKind":"ex2"}],"collocations":[{"en":"friendly smile","vi":"nụ cười thân thiện"},{"en":"friendly atmosphere","vi":"bầu không khí thân thiện"},{"en":"friendly match","vi":"trận đấu giao hữu"},{"en":"friendly towards newcomers","vi":"thân thiện với người mới đến"}],"wordFamily":["friend (n.)","friendship (n.)","friendliness (n.)","unfriendly (adj.)"],"synonyms":["welcoming","amiable"],"antonyms":["unfriendly","hostile"],"tipVi":"Mặc dù tận cùng bằng đuôi -ly, từ này là tính từ chứ không phải phó từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_children', 'en-a1-5', 'children', '/ˈtʃɪldrən/', 'A1', 'trẻ em; những đứa trẻ; con cái', 'n.', 'child (n.), childhood (n.), childish (adj.), childless (adj.)', 'Đồng nghĩa: kids · Trái nghĩa: adults', 'Dạng số nhiều bất quy tắc của "child"; dạng sở hữu cách là "children''s".', 'The children built a sandcastle together on the beach.', NULL, 'Lũ trẻ cùng nhau xây một lâu đài cát trên bãi biển.', '{"wordId":"children","ukIpa":"/ˈtʃɪldrən/","usIpa":"/ˈtʃɪldrən/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"Young people who have not yet become adults.","vi":"trẻ em; những đứa trẻ"},{"pos":"n.","en":"Someone''s sons or daughters, regardless of their age.","vi":"con cái"}],"examples":[{"en":"The children built a sandcastle together on the beach.","vi":"Lũ trẻ cùng nhau xây một lâu đài cát trên bãi biển.","audioKind":"ex"},{"en":"Safe public parks give children opportunities to exercise, develop social skills, and explore the natural world.","vi":"Các công viên công cộng an toàn mang lại cho trẻ em cơ hội rèn luyện sức khỏe, phát triển kỹ năng xã hội và khám phá thế giới tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"young children","vi":"trẻ nhỏ"},{"en":"raise children","vi":"nuôi dạy con cái"},{"en":"children''s books","vi":"sách thiếu nhi"}],"wordFamily":["child (n.)","childhood (n.)","childish (adj.)","childless (adj.)"],"synonyms":["kids"],"antonyms":["adults"],"tipVi":"Dạng số nhiều bất quy tắc của \"child\"; dạng sở hữu cách là \"children''s\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_christmas', 'en-a1-5', 'Christmas', '/ˈkrɪsməs/', 'A1', 'lễ Giáng Sinh; mùa Giáng Sinh', 'n.', NULL, NULL, 'Viết hoa chữ cái đầu; trong dịp lễ dùng "at", vào đúng ngày dùng "on Christmas Day".', 'Our family usually shares a special meal at Christmas.', NULL, 'Gia đình chúng tôi thường quây quần bên một bữa ăn đặc biệt vào dịp Giáng Sinh.', '{"wordId":"christmas","ukIpa":"/ˈkrɪsməs/","usIpa":"/ˈkrɪsməs/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"the Christian festival celebrating Jesus''s birth, or the surrounding period","vi":"lễ Giáng Sinh; mùa Giáng Sinh"}],"examples":[{"en":"Our family usually shares a special meal at Christmas.","vi":"Gia đình chúng tôi thường quây quần bên một bữa ăn đặc biệt vào dịp Giáng Sinh.","audioKind":"ex"},{"en":"During Christmas, increased consumer spending can benefit local shops, although it may also generate additional packaging waste.","vi":"Vào dịp Giáng Sinh, mức chi tiêu tiêu dùng tăng cao có thể mang lại lợi ích cho các cửa hàng địa phương, dù nó cũng có thể tạo ra lượng rác thải bao bì lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"Christmas Eve","vi":"đêm Giáng Sinh"},{"en":"Christmas Day","vi":"ngày Giáng Sinh"},{"en":"Christmas tree","vi":"cây thông Noel"},{"en":"at Christmas","vi":"vào dịp Giáng Sinh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Viết hoa chữ cái đầu; trong dịp lễ dùng \"at\", vào đúng ngày dùng \"on Christmas Day\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wife', 'en-a1-5', 'wife', '/waɪf/', 'A1', 'vợ', 'n.', NULL, 'Đồng nghĩa: spouse', 'Dạng số nhiều là wives; spouse chỉ người phối ngẫu, không giới hạn giới tính.', 'His wife packed sandwiches for their afternoon walk.', NULL, 'Vợ anh ấy đã chuẩn bị bánh mì kẹp cho buổi đi dạo buổi chiều của họ.', '{"wordId":"wife","ukIpa":"/waɪf/","usIpa":"/waɪf/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"a woman who is married to someone","vi":"vợ"}],"examples":[{"en":"His wife packed sandwiches for their afternoon walk.","vi":"Vợ anh ấy đã chuẩn bị bánh mì kẹp cho buổi đi dạo buổi chiều của họ.","audioKind":"ex"},{"en":"A husband and wife may share childcare responsibilities more equally when both have flexible working hours.","vi":"Vợ chồng có thể chia sẻ trách nhiệm chăm sóc con cái công bằng hơn khi cả hai đều có giờ làm việc linh hoạt.","audioKind":"ex2"}],"collocations":[{"en":"husband and wife","vi":"vợ chồng"},{"en":"his wife","vi":"vợ anh ấy"},{"en":"future wife","vi":"vợ tương lai"}],"wordFamily":[],"synonyms":["spouse"],"antonyms":[],"tipVi":"Dạng số nhiều là wives; spouse chỉ người phối ngẫu, không giới hạn giới tính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_married', 'en-a1-5', 'married', '/ˈmærid/', 'A1', 'đã kết hôn; có gia đình; thuộc về hôn nhân; đời sống vợ chồng', 'adj.', 'marry (v.), marriage (n.), unmarried (adj.)', 'Trái nghĩa: unmarried, single', 'Kết hôn với ai dùng "be/get married to", không dùng "with".', 'My sister is married and lives near the coast.', NULL, 'Chị gái tôi đã kết hôn và sống gần bờ biển.', '{"wordId":"married","ukIpa":"/ˈmærid/","usIpa":"/ˈmærid/","cefr":"A1","topic":"society","senses":[{"pos":"adj.","en":"Having a husband or wife.","vi":"đã kết hôn; có gia đình"},{"pos":"adj.","en":"Relating to marriage or life as a couple.","vi":"thuộc về hôn nhân; đời sống vợ chồng"}],"examples":[{"en":"My sister is married and lives near the coast.","vi":"Chị gái tôi đã kết hôn và sống gần bờ biển.","audioKind":"ex"},{"en":"Affordable housing can help newly married couples establish independent households without placing excessive pressure on their finances.","vi":"Nhà ở giá phải chăng có thể giúp các cặp vợ chồng mới cưới lập gia đình riêng mà không tạo áp lực quá lớn lên tài chính của họ.","audioKind":"ex2"}],"collocations":[{"en":"get married","vi":"kết hôn"},{"en":"be married to","vi":"kết hôn với"},{"en":"married couple","vi":"cặp vợ chồng"},{"en":"married life","vi":"đời sống hôn nhân"}],"wordFamily":["marry (v.)","marriage (n.)","unmarried (adj.)"],"synonyms":[],"antonyms":["unmarried","single"],"tipVi":"Kết hôn với ai dùng \"be/get married to\", không dùng \"with\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lady', 'en-a1-5', 'lady', '/ˈleɪdi/', 'A1', 'quý bà; phụ nữ (cách gọi lịch sự)', 'n.', 'ladylike (adj.)', 'Đồng nghĩa: woman', 'Woman là từ trung tính, thông dụng; lady thường dùng trong ngữ cảnh lịch sự.', 'A kind lady helped me find the station.', NULL, 'Một người phụ nữ tốt bụng đã giúp tôi tìm bến xe.', '{"wordId":"lady","ukIpa":"/ˈleɪdi/","usIpa":"/ˈleɪdi/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"a polite word for an adult woman","vi":"quý bà; phụ nữ (cách gọi lịch sự)"}],"examples":[{"en":"A kind lady helped me find the station.","vi":"Một người phụ nữ tốt bụng đã giúp tôi tìm bến xe.","audioKind":"ex"},{"en":"An elderly lady at the meeting explained how the new bus route had improved her daily life.","vi":"Tại cuộc họp, một phụ nữ lớn tuổi đã giải thích tuyến xe buýt mới đã cải thiện đời sống hàng ngày của bà như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"an elderly lady","vi":"một phụ nữ lớn tuổi"},{"en":"a young lady","vi":"một thiếu nữ; một cô gái trẻ"},{"en":"ladies and gentlemen","vi":"thưa các bà và các ông; kính thưa quý vị"}],"wordFamily":["ladylike (adj.)"],"synonyms":["woman"],"antonyms":[],"tipVi":"Woman là từ trung tính, thông dụng; lady thường dùng trong ngữ cảnh lịch sự.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_age', 'en-a1-5', 'age', '/eɪdʒ/', 'A1', 'tuổi; độ tuổi; thời đại; kỷ nguyên; già đi; làm cho già đi', 'n.', 'aged (adj.), ageing (n.), ageless (adj.)', NULL, 'Diễn đạt độ tuổi dùng at the age of, không dùng in.', 'My grandmother learned to swim at the age of seventy.', NULL, 'Bà tôi học bơi ở tuổi bảy mươi.', '{"wordId":"age","ukIpa":"/eɪdʒ/","usIpa":"/eɪdʒ/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"The length of time someone or something has existed.","vi":"tuổi; độ tuổi"},{"pos":"n.","en":"A period of history with particular features.","vi":"thời đại; kỷ nguyên"},{"pos":"v.","en":"To become older or make someone or something seem older.","vi":"già đi; làm cho già đi"}],"examples":[{"en":"My grandmother learned to swim at the age of seventy.","vi":"Bà tôi học bơi ở tuổi bảy mươi.","audioKind":"ex"},{"en":"As populations age, governments need to invest more in accessible housing and community healthcare services.","vi":"Khi dân số già đi, chính phủ cần đầu tư nhiều hơn vào nhà ở dễ tiếp cận và các dịch vụ chăm sóc sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"at the age of","vi":"vào lúc... tuổi"},{"en":"the digital age","vi":"thời đại kỹ thuật số"},{"en":"people of all ages","vi":"mọi lứa tuổi; người ở mọi độ tuổi"},{"en":"age gracefully","vi":"già đi một cách tao nhã"}],"wordFamily":["aged (adj.)","ageing (n.)","ageless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Diễn đạt độ tuổi dùng at the age of, không dùng in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nationality', 'en-a1-5', 'nationality', '/ˌnæʃəˈnæləti/', 'A1', 'quốc tịch; nhóm dân tộc; quốc gia', 'n.', 'nation (n.), national (adj.), nationally (adv.), international (adj.)', NULL, 'nationality chỉ quốc tịch, không đồng nhất với nơi sinh hoặc dân tộc.', 'The application form asks for my nationality and address.', NULL, 'Mẫu đơn đăng ký yêu cầu điền quốc tịch và địa chỉ của tôi.', '{"wordId":"nationality","ukIpa":"/ˌnæʃəˈnæləti/","usIpa":"/ˌnæʃəˈnæləti/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"the legal status of belonging to a particular country","vi":"quốc tịch"},{"pos":"n.","en":"a group sharing a national identity, culture, or history","vi":"nhóm dân tộc; quốc gia"}],"examples":[{"en":"The application form asks for my nationality and address.","vi":"Mẫu đơn đăng ký yêu cầu điền quốc tịch và địa chỉ của tôi.","audioKind":"ex"},{"en":"Access to essential healthcare should depend on medical need rather than a person''s nationality or income.","vi":"Việc tiếp cận chăm sóc y tế thiết yếu nên phụ thuộc vào nhu cầu y tế chứ không phải quốc tịch hay thu nhập của một cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"dual nationality","vi":"hai quốc tịch"},{"en":"acquire nationality","vi":"đạt được quốc tịch"},{"en":"people of different nationalities","vi":"những người có quốc tịch khác nhau"}],"wordFamily":["nation (n.)","national (adj.)","nationally (adv.)","international (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"nationality chỉ quốc tịch, không đồng nhất với nơi sinh hoặc dân tộc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_anyone', 'en-a1-5', 'anyone', '/ˈeniwʌn/', 'A1', 'bất kỳ ai; bất cứ người nào; ai đó', 'pron.', NULL, 'Đồng nghĩa: anybody', 'Khi làm chủ ngữ, động từ theo sau chia ở ngôi thứ ba số ít; any one nhấn mạnh vào từng cá thể riêng biệt.', 'Anyone can join our weekend walk by the river.', NULL, 'Bất kỳ ai cũng có thể tham gia buổi đi dạo ven sông vào cuối tuần của chúng tôi.', '{"wordId":"anyone","ukIpa":"/ˈeniwʌn/","usIpa":"/ˈeniwʌn/","cefr":"A1","topic":"society","senses":[{"pos":"pron.","en":"any person, without restriction","vi":"bất kỳ ai"},{"pos":"pron.","en":"a person, used in questions and negative statements","vi":"bất cứ người nào; ai đó"}],"examples":[{"en":"Anyone can join our weekend walk by the river.","vi":"Bất kỳ ai cũng có thể tham gia buổi đi dạo ven sông vào cuối tuần của chúng tôi.","audioKind":"ex"},{"en":"Public libraries should provide free internet access to anyone who needs it, regardless of income.","vi":"Các thư viện công cộng nên cung cấp quyền truy cập internet miễn phí cho bất kỳ ai có nhu cầu, không phân biệt thu nhập.","audioKind":"ex2"}],"collocations":[{"en":"anyone else","vi":"bất kỳ ai khác"},{"en":"almost anyone","vi":"hầu như bất cứ ai"},{"en":"anyone who","vi":"bất kỳ ai mà"}],"wordFamily":[],"synonyms":["anybody"],"antonyms":[],"tipVi":"Khi làm chủ ngữ, động từ theo sau chia ở ngôi thứ ba số ít; any one nhấn mạnh vào từng cá thể riêng biệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_group', 'en-a1-5', 'group', '/ɡruːp/', 'A1', 'nhóm; hội; tập thể; nhóm lại; phân loại', 'n.', 'grouping (n.), regroup (v.)', NULL, 'a group of thường đi với danh từ số nhiều; động từ thường dùng group A by B.', 'A group of cyclists stopped outside the village bakery.', NULL, 'Một nhóm người đi xe đạp đã dừng lại bên ngoài tiệm bánh của làng.', '{"wordId":"group","ukIpa":"/ɡruːp/","usIpa":"/ɡruːp/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"People or things together or connected by a shared feature.","vi":"nhóm; hội; tập thể"},{"pos":"v.","en":"Arrange people or things together, often according to shared features.","vi":"nhóm lại; phân loại"}],"examples":[{"en":"A group of cyclists stopped outside the village bakery.","vi":"Một nhóm người đi xe đạp đã dừng lại bên ngoài tiệm bánh của làng.","audioKind":"ex"},{"en":"Teachers can group students by their learning needs to provide more effective support during classroom activities.","vi":"Giáo viên có thể phân nhóm học sinh theo nhu cầu học tập để hỗ trợ hiệu quả hơn trong các hoạt động trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"a group of","vi":"một nhóm"},{"en":"age group","vi":"nhóm tuổi"},{"en":"group discussion","vi":"thảo luận nhóm"},{"en":"group work","vi":"làm việc nhóm"}],"wordFamily":["grouping (n.)","regroup (v.)"],"synonyms":[],"antonyms":[],"tipVi":"a group of thường đi với danh từ số nhiều; động từ thường dùng group A by B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_member', 'en-a1-5', 'member', '/ˈmembɚ/', 'A1', 'thành viên; hội viên', 'n.', 'membership (n)', NULL, 'Chỉ thành viên của một tổ chức nào đó, dùng a member of.', 'Each club member brought a dish to share.', NULL, 'Mỗi thành viên câu lạc bộ đều mang một món ăn để chia sẻ.', '{"wordId":"member","ukIpa":"/ˈmembə/","usIpa":"/ˈmembɚ/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"a person who belongs to a group or organisation","vi":"thành viên; hội viên"}],"examples":[{"en":"Each club member brought a dish to share.","vi":"Mỗi thành viên câu lạc bộ đều mang một món ăn để chia sẻ.","audioKind":"ex"},{"en":"Every member of a community can contribute to protecting local green spaces through regular volunteer work.","vi":"Mỗi thành viên trong cộng đồng đều có thể góp phần bảo vệ không gian xanh địa phương thông qua hoạt động tình nguyện thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"a member of","vi":"thành viên của"},{"en":"a team member","vi":"thành viên đội"},{"en":"a family member","vi":"thành viên trong gia đình"},{"en":"a founding member","vi":"thành viên sáng lập"}],"wordFamily":["membership (n)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ thành viên của một tổ chức nào đó, dùng a member of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_daughter', 'en-a1-5', 'daughter', '/ˈdɔtər/', 'A1', 'con gái', 'n.', 'daughter-in-law (n.)', NULL, 'daughter-in-law là con dâu, không phải con gái kế.', 'Their daughter made pancakes for the whole family.', NULL, 'Con gái của họ đã làm bánh kếp cho cả nhà.', '{"wordId":"daughter","ukIpa":"/ˈdɔːtə/","usIpa":"/ˈdɔtər/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"Someone''s female child.","vi":"con gái"}],"examples":[{"en":"Their daughter made pancakes for the whole family.","vi":"Con gái của họ đã làm bánh kếp cho cả nhà.","audioKind":"ex"},{"en":"Equal access to education ensures that daughters and sons have similar opportunities to develop their talents.","vi":"Quyền tiếp cận giáo dục bình đẳng đảm bảo rằng con gái và con trai đều có cơ hội tương tự để phát triển tài năng của mình.","audioKind":"ex2"}],"collocations":[{"en":"an eldest daughter","vi":"con gái cả"},{"en":"a teenage daughter","vi":"con gái tuổi teen"},{"en":"a mother and daughter","vi":"hai mẹ con"}],"wordFamily":["daughter-in-law (n.)"],"synonyms":[],"antonyms":[],"tipVi":"daughter-in-law là con dâu, không phải con gái kế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_world', 'en-a1-5', 'world', '/wɝːld/', 'A1', 'thế giới; trái đất; lĩnh vực; giới', 'n.', 'worldwide (adj.), worldwide (adv.), worldly (adj.)', 'Đồng nghĩa: globe', 'Chỉ toàn bộ thế giới thường dùng the world; giới kinh doanh là the business world.', 'She dreams of travelling around the world by train.', NULL, 'Con bé mơ ước được đi du lịch vòng quanh thế giới bằng tàu hỏa.', '{"wordId":"world","ukIpa":"/wɜːld/","usIpa":"/wɝːld/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"The earth and all the people and things on it.","vi":"thế giới; trái đất"},{"pos":"n.","en":"A particular area of activity and the people involved.","vi":"lĩnh vực; giới"}],"examples":[{"en":"She dreams of travelling around the world by train.","vi":"Con bé mơ ước được đi du lịch vòng quanh thế giới bằng tàu hỏa.","audioKind":"ex"},{"en":"Countries around the world need to cooperate more closely to address climate change and protect shared natural resources.","vi":"Các quốc gia trên thế giới cần hợp tác chặt chẽ hơn để giải quyết biến đổi khí hậu và bảo vệ các nguồn tài nguyên thiên nhiên chung.","audioKind":"ex2"}],"collocations":[{"en":"around the world","vi":"khắp thế giới"},{"en":"the natural world","vi":"giới tự nhiên"},{"en":"the business world","vi":"giới kinh doanh"},{"en":"world population","vi":"dân số thế giới"}],"wordFamily":["worldwide (adj.)","worldwide (adv.)","worldly (adj.)"],"synonyms":["globe"],"antonyms":[],"tipVi":"Chỉ toàn bộ thế giới thường dùng the world; giới kinh doanh là the business world.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_man', 'en-a1-5', 'man', '/mæn/', 'A1', 'đàn ông; nam giới trưởng thành; loài người; nhân loại; cử người túc trực; vận hành', 'n.', 'manhood (n.), manned (adj.), unmanned (adj.)', 'Trái nghĩa: woman', 'Dạng số nhiều là men; khi chỉ chung loài người, văn phong hiện đại thường chuộng dùng humankind.', 'A man in a blue coat held the door open.', NULL, 'Một người đàn ông mặc áo khoác xanh đã giữ cửa mở cho người khác.', '{"wordId":"man","ukIpa":"/mæn/","usIpa":"/mæn/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"An adult male human","vi":"đàn ông; nam giới trưởng thành"},{"pos":"n.","en":"Human beings considered collectively","vi":"loài người; nhân loại"},{"pos":"v.","en":"To provide people to operate or guard something","vi":"cử người túc trực; vận hành"}],"examples":[{"en":"A man in a blue coat held the door open.","vi":"Một người đàn ông mặc áo khoác xanh đã giữ cửa mở cho người khác.","audioKind":"ex"},{"en":"Additional volunteers are needed to man information desks during the city''s annual cultural festival.","vi":"Cần thêm nhiều tình nguyện viên để trực bàn thông tin trong suốt lễ hội văn hóa thường niên của thành phố.","audioKind":"ex2"}],"collocations":[{"en":"young man","vi":"thanh niên; nam thanh niên"},{"en":"man a desk","vi":"trực bàn hướng dẫn"},{"en":"man a checkpoint","vi":"trực chốt kiểm soát"}],"wordFamily":["manhood (n.)","manned (adj.)","unmanned (adj.)"],"synonyms":[],"antonyms":["woman"],"tipVi":"Dạng số nhiều là men; khi chỉ chung loài người, văn phong hiện đại thường chuộng dùng humankind.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adult', 'en-a1-5', 'adult', '/əˈdʌlt/', 'A1', 'người trưởng thành; động vật đã trưởng thành; đã trưởng thành; thuộc về người lớn', 'n.', 'adulthood (n.)', 'Đồng nghĩa: grown-up · Trái nghĩa: child', 'Có thể dùng làm danh từ đếm được hoặc tính từ, ví dụ như adult education.', 'Children must visit the swimming pool with an adult.', NULL, 'Trẻ em phải đi bơi cùng với người lớn.', '{"wordId":"adult","ukIpa":"/ˈædʌlt/","usIpa":"/əˈdʌlt/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"A person or animal that has finished growing.","vi":"người trưởng thành; động vật đã trưởng thành"},{"pos":"adj.","en":"Fully grown, or relating to grown people.","vi":"đã trưởng thành; thuộc về người lớn"}],"examples":[{"en":"Children must visit the swimming pool with an adult.","vi":"Trẻ em phải đi bơi cùng với người lớn.","audioKind":"ex"},{"en":"Adult education programmes help people gain new qualifications and adapt to changes in the labour market.","vi":"Các chương trình giáo dục người lớn giúp mọi người có được các văn bằng chứng chỉ mới và thích ứng với những thay đổi của thị trường lao động.","audioKind":"ex2"}],"collocations":[{"en":"young adult","vi":"thanh thiếu niên lớn tuổi; người trẻ tuổi"},{"en":"adult education","vi":"giáo dục người lớn"},{"en":"adult life","vi":"cuộc sống trưởng thành"},{"en":"responsible adult","vi":"người lớn có trách nhiệm"}],"wordFamily":["adulthood (n.)"],"synonyms":["grown-up"],"antonyms":["child"],"tipVi":"Có thể dùng làm danh từ đếm được hoặc tính từ, ví dụ như adult education.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_party', 'en-a1-5', 'party', '/ˈpɑːrti/', 'A1', 'bữa tiệc; buổi liên hoan; đảng phái chính trị; bên tham gia (trong hợp đồng, tranh chấp)', 'n.', 'partygoer (n.), partying (n.)', NULL, 'Trong hợp đồng, party chỉ các bên tham gia chứ không mang nghĩa là bữa tiệc hay chính đảng.', 'We held a small party in the garden yesterday.', NULL, 'Chúng tôi đã tổ chức một bữa tiệc nhỏ ở khu vườn ngày hôm qua.', '{"wordId":"party","ukIpa":"/ˈpɑːti/","usIpa":"/ˈpɑːrti/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"A social gathering where people celebrate or enjoy themselves.","vi":"bữa tiệc; buổi liên hoan"},{"pos":"n.","en":"An organised group seeking political power through shared policies.","vi":"đảng phái chính trị"},{"pos":"n.","en":"A person or group involved in an agreement or dispute.","vi":"bên tham gia (trong hợp đồng, tranh chấp)"}],"examples":[{"en":"We held a small party in the garden yesterday.","vi":"Chúng tôi đã tổ chức một bữa tiệc nhỏ ở khu vườn ngày hôm qua.","audioKind":"ex"},{"en":"Each political party should explain how its education policies will benefit students from disadvantaged backgrounds.","vi":"Mỗi chính đảng nên giải thích rõ các chính sách giáo dục của mình sẽ mang lại lợi ích ra sao cho học sinh đến từ các hoàn cảnh khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"a birthday party","vi":"tiệc sinh nhật"},{"en":"a political party","vi":"một đảng phái chính trị"},{"en":"a third party","vi":"bên thứ ba"},{"en":"throw a party","vi":"tổ chức tiệc tùng"}],"wordFamily":["partygoer (n.)","partying (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong hợp đồng, party chỉ các bên tham gia chứ không mang nghĩa là bữa tiệc hay chính đảng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_5_1', 'en-a1-5', 'Cách dùng “child” (n.) — trẻ em; đứa trẻ', 'an only child  ·  child development  ·  raise a child', 'Dạng số nhiều là children; childish mang nghĩa hơi tiêu cực (trẻ con, ngớ ngẩn), còn childlike mang nghĩa tích cực (ngây thơ như trẻ thơ).', 'Họ từ (Word Family): childhood (n.), childish (adj.), childlike (adj.), childless (adj.) | Đồng nghĩa: kid | Trái nghĩa: adult', '[{"hanzi":"The child carefully carried a bowl of water outside.","pinyin":"","meaning":"Đứa trẻ cẩn thận bưng một bát nước đi ra ngoài."},{"hanzi":"Every child should have access to quality education, regardless of family income or place of residence.","pinyin":"","meaning":"Mỗi đứa trẻ đều nên được tiếp cận với nền giáo dục chất lượng, bất kể thu nhập của gia đình hay nơi sinh sống."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_5_2', 'en-a1-5', 'Cách dùng “anyone” (pron.) — bất kỳ ai', 'anyone else  ·  almost anyone  ·  anyone who', 'Khi làm chủ ngữ, động từ theo sau chia ở ngôi thứ ba số ít; any one nhấn mạnh vào từng cá thể riêng biệt.', 'Đồng nghĩa: anybody', '[{"hanzi":"Anyone can join our weekend walk by the river.","pinyin":"","meaning":"Bất kỳ ai cũng có thể tham gia buổi đi dạo ven sông vào cuối tuần của chúng tôi."},{"hanzi":"Public libraries should provide free internet access to anyone who needs it, regardless of income.","pinyin":"","meaning":"Các thư viện công cộng nên cung cấp quyền truy cập internet miễn phí cho bất kỳ ai có nhu cầu, không phân biệt thu nhập."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_5_3', 'en-a1-5', 'Cách dùng “kind” (adj.) — tử tế; tốt bụng; chu đáo', 'be kind to someone  ·  a kind of  ·  all kinds of', 'Tính từ thường đi với giới từ to; để chỉ chủng loại thì dùng cấu trúc a kind of kết hợp với danh từ.', 'Họ từ (Word Family): kindness (n.), kindly (adv.), unkind (adj.) | Đồng nghĩa: caring, considerate | Trái nghĩa: unkind, cruel', '[{"hanzi":"Our kind neighbour brought us soup when we were ill.","pinyin":"","meaning":"Người hàng xóm tốt bụng đã mang súp cho chúng tôi khi chúng tôi ốm."},{"hanzi":"Schools should encourage students to be kind to others, helping create a more supportive learning environment.","pinyin":"","meaning":"Các trường học nên khuyến khích học sinh đối xử tử tế với người khác, giúp tạo ra một môi trường học tập hỗ trợ tốt hơn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_5_4', 'en-a1-5', 'Cách dùng “man” (n.) — đàn ông; nam giới trưởng thành', 'young man  ·  man a desk  ·  man a checkpoint', 'Dạng số nhiều là men; khi chỉ chung loài người, văn phong hiện đại thường chuộng dùng humankind.', 'Họ từ (Word Family): manhood (n.), manned (adj.), unmanned (adj.) | Trái nghĩa: woman', '[{"hanzi":"A man in a blue coat held the door open.","pinyin":"","meaning":"Một người đàn ông mặc áo khoác xanh đã giữ cửa mở cho người khác."},{"hanzi":"Additional volunteers are needed to man information desks during the city''s annual cultural festival.","pinyin":"","meaning":"Cần thêm nhiều tình nguyện viên để trực bàn thông tin trong suốt lễ hội văn hóa thường niên của thành phố."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
