INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_5_1_1', 'en-a1-5', 'ten_5_1', 'listening', 'listening', 'My little sister was born on a snowy morning.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chồng cô ấy đã mang bữa trưa đến cho cô ấy trong một ca làm việc bận rộn.","Hôm qua chúng tôi đã thưởng thức món ăn Nhật tại một nhà hàng nhỏ.","Đứa trẻ cẩn thận bưng một bát nước đi ra ngoài.","Em gái tôi sinh vào một buổi sáng có tuyết."]'::jsonb, 3, 'My little sister was born on a snowy morning. → Em gái tôi sinh vào một buổi sáng có tuyết.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
