INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_5_2', 'en-a1-5', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_5_2_1', 'ten_5_2', 'born', 'Children born in rural areas may face greater difficulties accessing specialist healthcare than those in cities.', 'Children born in rural areas may face greater difficulties accessing specialist healthcare than those in cities.', '/bɔːrn/', 'Trẻ em sinh ra ở các vùng nông thôn có thể phải đối mặt với nhiều khó khăn hơn trong việc tiếp cận dịch vụ chăm sóc y tế chuyên khoa so với trẻ em ở thành phố.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_5_2_2', 'ten_5_2', 'Japanese', 'Studying Japanese architecture can help students understand how traditional design responds to local environmental conditions.', 'Studying Japanese architecture can help students understand how traditional design responds to local environmental conditions.', '/ˌdʒæpəˈniːz/', 'Nghiên cứu kiến trúc Nhật Bản có thể giúp sinh viên hiểu cách các thiết kế truyền thống ứng phó với điều kiện môi trường địa phương.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_5_2_3', 'ten_5_2', 'child', 'Every child should have access to quality education, regardless of family income or place of residence.', 'Every child should have access to quality education, regardless of family income or place of residence.', '/tʃaɪld/', 'Mỗi đứa trẻ đều nên được tiếp cận với nền giáo dục chất lượng, bất kể thu nhập của gia đình hay nơi sinh sống.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_5_2_4', 'ten_5_2', 'kind', 'Schools should encourage students to be kind to others, helping create a more supportive learning environment.', 'Schools should encourage students to be kind to others, helping create a more supportive learning environment.', '/kaɪnd/', 'Các trường học nên khuyến khích học sinh đối xử tử tế với người khác, giúp tạo ra một môi trường học tập hỗ trợ tốt hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_5_2_5', 'ten_5_2', 'policeman', 'A local policeman visited the school to explain how children can stay safe online.', 'A local policeman visited the school to explain how children can stay safe online.', '/pəˈliːsmən/', 'Một nam cảnh sát địa phương đã đến trường để giải thích cho học sinh cách giữ an toàn khi trực tuyến.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_5_2_6', 'ten_5_2', 'poor', 'Poor public transport can limit employment opportunities for people living far from major urban centres.', 'Poor public transport can limit employment opportunities for people living far from major urban centres.', '/pʊr/', 'Hệ thống giao thông công cộng kém phát triển có thể làm hạn chế cơ hội việc làm của những người sống xa các trung tâm đô thị lớn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
