INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_5_2_2', 'en-a1-5', 'ten_5_2', 'listening', 'listening', 'Studying Japanese architecture can help students understand how traditional design responds to local environmental conditions.', NULL, 'Trong câu vừa nghe, từ “Japanese” mang nghĩa nào sau đây?', '["thỉnh thoảng; đôi khi","đơn; duy nhất; một","khóc; rơi nước mắt","thuộc về Nhật Bản; thuộc về tiếng Nhật"]'::jsonb, 3, '“Japanese” (/ˌdʒæpəˈniːz/): thuộc về Nhật Bản; thuộc về tiếng Nhật. Câu đầy đủ: Studying Japanese architecture can help students understand how traditional design responds to local environmental conditions.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
