INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_5_2', 'en-a1-5', NULL, 'comprehensive_test', 'listening', 'We enjoyed Japanese food at a small restaurant yesterday.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mẫu đơn đăng ký yêu cầu điền quốc tịch và địa chỉ của tôi.","Bà tôi học bơi ở tuổi bảy mươi.","Hôm qua chúng tôi đã thưởng thức món ăn Nhật tại một nhà hàng nhỏ.","Người hàng xóm tốt bụng đã mang súp cho chúng tôi khi chúng tôi ốm."]'::jsonb, 2, 'We enjoyed Japanese food at a small restaurant yesterday. → Hôm qua chúng tôi đã thưởng thức món ăn Nhật tại một nhà hàng nhỏ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_5_3', 'en-a1-5', NULL, 'comprehensive_test', 'listening', 'child', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thường; thường xuyên","trẻ em; đứa trẻ","thuyền; ghe; tàu nhỏ","thị trấn; thị xã"]'::jsonb, 1, 'child (/tʃaɪld/) → trẻ em; đứa trẻ; con cái', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_5_4', 'en-a1-5', NULL, 'comprehensive_test', 'listening', 'Our kind neighbour brought us soup when we were ill.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một nam cảnh sát đã giúp chúng tôi băng qua con đường đông đúc.","Người hàng xóm tốt bụng đã mang súp cho chúng tôi khi chúng tôi ốm.","Em gái tôi sinh vào một buổi sáng có tuyết.","Chồng cô ấy đã mang bữa trưa đến cho cô ấy trong một ca làm việc bận rộn."]'::jsonb, 1, 'Our kind neighbour brought us soup when we were ill. → Người hàng xóm tốt bụng đã mang súp cho chúng tôi khi chúng tôi ốm.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_5_5', 'en-a1-5', NULL, 'comprehensive_test', 'listening', 'policeman', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thủ đô của Vương quốc Anh","thanh âm; âm thanh","nam cảnh sát","dễ dàng; không phức tạp"]'::jsonb, 2, 'policeman (/pəˈliːsmən/) → nam cảnh sát', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_5_6', 'en-a1-5', NULL, 'comprehensive_test', 'listening', 'The poor family could barely afford fresh vegetables.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bất kỳ ai cũng có thể tham gia buổi đi dạo ven sông vào cuối tuần của chúng tôi.","Gia đình nghèo khó đó hầu như không đủ tiền mua rau tươi.","Con gái của họ đã làm bánh kếp cho cả nhà.","Mẫu đơn đăng ký yêu cầu điền quốc tịch và địa chỉ của tôi."]'::jsonb, 1, 'The poor family could barely afford fresh vegetables. → Gia đình nghèo khó đó hầu như không đủ tiền mua rau tươi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
