INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_5_8', 'en-a1-5', NULL, 'comprehensive_test', 'listening', 'Her husband brought her lunch during a busy shift.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một nhóm người đi xe đạp đã dừng lại bên ngoài tiệm bánh của làng.","Gia đình nghèo khó đó hầu như không đủ tiền mua rau tươi.","Chồng cô ấy đã mang bữa trưa đến cho cô ấy trong một ca làm việc bận rộn.","Cô bé cẩn thận bế chú mèo con của mình vào nhà."]'::jsonb, 2, 'Her husband brought her lunch during a busy shift. → Chồng cô ấy đã mang bữa trưa đến cho cô ấy trong một ca làm việc bận rộn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
