INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_5_18', 'en-a1-5', NULL, 'comprehensive_test', 'reading', NULL, 'Children born in rural areas may face greater difficulties accessing specialist healthcare than those in cities.', 'Dựa vào câu trên, từ “born” có nghĩa phù hợp nhất là gì?', '["mưa; nước mưa","sinh ra","ngoài ra; cũng","được yêu thích nhất (hơn bất kỳ thứ gì cùng loại)"]'::jsonb, 1, 'born: sinh ra; bẩm sinh; có năng khiếu. Dịch cả câu: Trẻ em sinh ra ở các vùng nông thôn có thể phải đối mặt với nhiều khó khăn hơn trong việc tiếp cận dịch vụ chăm sóc y tế chuyên khoa so với trẻ em ở thành phố.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_5_19', 'en-a1-5', NULL, 'comprehensive_test', 'reading', NULL, 'Studying Japanese architecture can help students understand how traditional design responds to local environmental conditions.', 'Dựa vào câu trên, từ “Japanese” có nghĩa phù hợp nhất là gì?', '["cha; bố","bánh mì kẹp; sandwich","áo len; áo chui đầu bằng len","thuộc về Nhật Bản; thuộc về tiếng Nhật"]'::jsonb, 3, 'Japanese: thuộc về Nhật Bản; thuộc về tiếng Nhật; tiếng Nhật; người Nhật Bản. Dịch cả câu: Nghiên cứu kiến trúc Nhật Bản có thể giúp sinh viên hiểu cách các thiết kế truyền thống ứng phó với điều kiện môi trường địa phương.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_5_20', 'en-a1-5', NULL, 'comprehensive_test', 'reading', NULL, 'Every child should have access to quality education, regardless of family income or place of residence.', 'Dựa vào câu trên, từ “child” có nghĩa phù hợp nhất là gì?', '["chỉ; vừa vặn","sau; sau khi","trẻ em; đứa trẻ","thậm chí; ngay cả"]'::jsonb, 2, 'child: trẻ em; đứa trẻ; con cái. Dịch cả câu: Mỗi đứa trẻ đều nên được tiếp cận với nền giáo dục chất lượng, bất kể thu nhập của gia đình hay nơi sinh sống.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_5_21', 'en-a1-5', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should encourage students to be kind to others, helping create a more supportive learning environment.', 'Dựa vào câu trên, từ “kind” có nghĩa phù hợp nhất là gì?', '["tử tế; tốt bụng; chu đáo","sách; quyển sách","đầu; phần đầu","hai lần"]'::jsonb, 0, 'kind: tử tế; tốt bụng; chu đáo; loại; loài. Dịch cả câu: Các trường học nên khuyến khích học sinh đối xử tử tế với người khác, giúp tạo ra một môi trường học tập hỗ trợ tốt hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
