INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_5_24', 'en-a1-5', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bữa tiệc; buổi liên hoan”', '["mother","ask","anyone","party"]'::jsonb, 3, 'bữa tiệc; buổi liên hoan → party (/ˈpɑːrti/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-6', 'en', 'Bài 6: Xã hội & Cộng đồng (2) - CEFR A1', 'CEFR A1', 'A1 · Xã hội', '23 từ vựng Tiếng Anh CEFR A1 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1006, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_together', 'en-a1-6', 'together', '/təˈɡeðɚ/', 'A1', 'cùng nhau; với nhau; hợp lại; kết hợp với nhau', 'adv.', 'togetherness (n.)', 'Đồng nghĩa: jointly · Trái nghĩa: apart, separately', '"together" thường làm trạng từ: dùng động từ + "together" để diễn đạt việc cùng làm gì.', 'We cooked dinner together and shared stories about our day.', NULL, 'Chúng tôi cùng nhau nấu bữa tối và chia sẻ những câu chuyện về ngày hôm nay.', '{"wordId":"together","ukIpa":"/təˈɡeðə/","usIpa":"/təˈɡeðɚ/","cefr":"A1","topic":"society","senses":[{"pos":"adv.","en":"with another person or other people","vi":"cùng nhau; với nhau"},{"pos":"adv.","en":"joined or combined with something else","vi":"hợp lại; kết hợp với nhau"}],"examples":[{"en":"We cooked dinner together and shared stories about our day.","vi":"Chúng tôi cùng nhau nấu bữa tối và chia sẻ những câu chuyện về ngày hôm nay.","audioKind":"ex"},{"en":"Schools and families should work together to help children develop healthy habits from an early age.","vi":"Nhà trường và gia đình nên cùng nhau nỗ lực để giúp trẻ hình thành thói quen lành mạnh ngay từ nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"work together","vi":"làm việc cùng nhau"},{"en":"get together","vi":"tụ họp; gặp gỡ"},{"en":"put together","vi":"lắp ráp; sắp xếp lại"},{"en":"live together","vi":"sống chung"}],"wordFamily":["togetherness (n.)"],"synonyms":["jointly"],"antonyms":["apart","separately"],"tipVi":"\"together\" thường làm trạng từ: dùng động từ + \"together\" để diễn đạt việc cùng làm gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cousin', 'en-a1-6', 'cousin', '/ˈkʌzən/', 'A1', 'anh chị em họ (con của bác, chú, cậu, cô, dì)', 'n.', NULL, NULL, 'Từ này không phân biệt họ nội hay họ ngoại, nam hay nữ, lớn hay nhỏ; cần làm rõ thì dùng thêm từ bổ nghĩa.', 'My cousin taught me to ride a bicycle yesterday.', NULL, 'Người em họ của tôi đã dạy tôi đi xe đạp ngày hôm qua.', '{"wordId":"cousin","ukIpa":"/ˈkʌzən/","usIpa":"/ˈkʌzən/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"A child of your aunt or uncle","vi":"anh chị em họ (con của bác, chú, cậu, cô, dì)"}],"examples":[{"en":"My cousin taught me to ride a bicycle yesterday.","vi":"Người em họ của tôi đã dạy tôi đi xe đạp ngày hôm qua.","audioKind":"ex"},{"en":"Children who regularly spend time with their cousins may develop strong family bonds beyond their immediate household.","vi":"Những đứa trẻ thường xuyên dành thời gian với anh chị em họ của chúng có thể phát triển mối liên kết gia đình mạnh mẽ ngoài phạm vi gia đình hạt nhân.","audioKind":"ex2"}],"collocations":[{"en":"a first cousin","vi":"anh chị em họ đời đầu"},{"en":"a distant cousin","vi":"anh chị em họ xa"},{"en":"a younger cousin","vi":"em họ nhỏ tuổi hơn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ này không phân biệt họ nội hay họ ngoại, nam hay nữ, lớn hay nhỏ; cần làm rõ thì dùng thêm từ bổ nghĩa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_everyone', 'en-a1-6', 'everyone', '/ˈevriwʌn/', 'A1', 'mọi người; tất cả mọi người', 'pron.', NULL, 'Đồng nghĩa: everybody · Trái nghĩa: nobody, no one', 'everyone đi với động từ số ít; every one nhấn mạnh từng cá nhân một.', 'Everyone brought a dish to share at the picnic.', NULL, 'Mọi người đều mang theo một món ăn để chia sẻ trong buổi dã ngoại.', '{"wordId":"everyone","ukIpa":"/ˈevriwʌn/","usIpa":"/ˈevriwʌn/","cefr":"A1","topic":"society","senses":[{"pos":"pron.","en":"Every person in a group, or all people.","vi":"mọi người; tất cả mọi người"}],"examples":[{"en":"Everyone brought a dish to share at the picnic.","vi":"Mọi người đều mang theo một món ăn để chia sẻ trong buổi dã ngoại.","audioKind":"ex"},{"en":"Public libraries should ensure that everyone can access reliable information, regardless of income or educational background.","vi":"Các thư viện công cộng nên đảm bảo rằng mọi người đều có thể tiếp cận thông tin đáng tin cậy, bất kể thu nhập hay nền tảng học vấn.","audioKind":"ex2"}],"collocations":[{"en":"everyone else","vi":"những người khác; tất cả những người còn lại"},{"en":"almost everyone","vi":"hầu như mọi người"},{"en":"everyone involved","vi":"tất cả những người có liên quan"}],"wordFamily":[],"synonyms":["everybody"],"antonyms":["nobody","no one"],"tipVi":"everyone đi với động từ số ít; every one nhấn mạnh từng cá nhân một.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_people', 'en-a1-6', 'people', '/ˈpiːpəl/', 'A1', 'mọi người; con người; dân tộc; tộc người', 'n.', 'person (n.)', 'Đồng nghĩa: persons, individuals', 'Chỉ con người chung chung dùng people; peoples dùng để chỉ nhiều dân tộc khác nhau.', 'Several people were waiting outside the bakery this morning.', NULL, 'Sáng nay có vài người đang đợi bên ngoài tiệm bánh.', '{"wordId":"people","ukIpa":"/ˈpiːpəl/","usIpa":"/ˈpiːpəl/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"Human beings considered together or referred to in general.","vi":"mọi người; con người"},{"pos":"n.","en":"A group sharing a culture, history, or national identity.","vi":"dân tộc; tộc người"}],"examples":[{"en":"Several people were waiting outside the bakery this morning.","vi":"Sáng nay có vài người đang đợi bên ngoài tiệm bánh.","audioKind":"ex"},{"en":"Cities should provide accessible public transport so that people of all ages can travel independently.","vi":"Các thành phố nên cung cấp giao thông công cộng dễ tiếp cận để mọi người ở mọi lứa tuổi có thể di chuyển độc lập.","audioKind":"ex2"}],"collocations":[{"en":"local people","vi":"người dân địa phương"},{"en":"young people","vi":"giới trẻ; người trẻ tuổi"},{"en":"indigenous peoples","vi":"các dân tộc bản địa"},{"en":"people from all walks of life","vi":"người từ mọi tầng lớp xã hội"}],"wordFamily":["person (n.)"],"synonyms":["persons","individuals"],"antonyms":[],"tipVi":"Chỉ con người chung chung dùng people; peoples dùng để chỉ nhiều dân tộc khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_women', 'en-a1-6', 'women', '/ˈwɪmɪn/', 'A1', 'những người phụ nữ; phái nữ', 'n.', 'woman (n.)', NULL, 'Là dạng số nhiều của woman; âm tiết đầu phát âm là /wɪ/ chứ không phải /wʊ/.', 'Three women were planting flowers in the shared garden.', NULL, 'Ba người phụ nữ đang trồng hoa trong khu vườn chung.', '{"wordId":"women","ukIpa":"/ˈwɪmɪn/","usIpa":"/ˈwɪmɪn/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"More than one adult female person.","vi":"những người phụ nữ; phái nữ"}],"examples":[{"en":"Three women were planting flowers in the shared garden.","vi":"Ba người phụ nữ đang trồng hoa trong khu vườn chung.","audioKind":"ex"},{"en":"Equal access to education enables more women to pursue careers in science and technology.","vi":"Cơ hội tiếp cận giáo dục bình đẳng giúp nhiều phụ nữ theo đuổi sự nghiệp trong lĩnh vực khoa học và công nghệ.","audioKind":"ex2"}],"collocations":[{"en":"women''s health","vi":"sức khỏe phụ nữ"},{"en":"women''s rights","vi":"quyền lợi của phụ nữ"},{"en":"women in leadership","vi":"phụ nữ giữ các vị trí lãnh đạo"}],"wordFamily":["woman (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Là dạng số nhiều của woman; âm tiết đầu phát âm là /wɪ/ chứ không phải /wʊ/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_welcome', 'en-a1-6', 'welcome', '/ˈwelkəm/', 'A1', 'chào đón; hoan nghênh; đón tiếp nồng nhiệt; đáng chào đón; dễ chịu; được đón nhận; sự chào đón; sự đón tiếp', 'v.', 'welcoming (adj.), unwelcome (adj.)', NULL, 'be welcome to do biểu thị có thể thoải mái làm gì; You''re welcome dùng để đáp lại lời cảm ơn.', 'Our neighbours came outside to welcome us home.', NULL, 'Những người hàng xóm đã bước ra ngoài để chào đón chúng tôi về nhà.', '{"wordId":"welcome","ukIpa":"/ˈwelkəm/","usIpa":"/ˈwelkəm/","cefr":"A1","topic":"society","senses":[{"pos":"v.","en":"to greet someone warmly or accept something with pleasure","vi":"chào đón; hoan nghênh; đón tiếp nồng nhiệt"},{"pos":"adj.","en":"wanted, appreciated, or gladly accepted","vi":"đáng chào đón; dễ chịu; được đón nhận"},{"pos":"n.","en":"the way someone is greeted when they arrive","vi":"sự chào đón; sự đón tiếp"}],"examples":[{"en":"Our neighbours came outside to welcome us home.","vi":"Những người hàng xóm đã bước ra ngoài để chào đón chúng tôi về nhà.","audioKind":"ex"},{"en":"Many communities welcome new cultural festivals because they encourage social interaction and support local businesses.","vi":"Nhiều cộng đồng hoan nghênh các lễ hội văn hóa mới vì chúng thúc đẩy giao lưu xã hội và hỗ trợ các doanh nghiệp địa phương.","audioKind":"ex2"}],"collocations":[{"en":"welcome visitors","vi":"chào đón khách tham quan"},{"en":"a warm welcome","vi":"một sự đón tiếp nồng nhiệt"},{"en":"a welcome change","vi":"một sự thay đổi đáng mừng"},{"en":"you''re welcome","vi":"không có chi"}],"wordFamily":["welcoming (adj.)","unwelcome (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"be welcome to do biểu thị có thể thoải mái làm gì; You''re welcome dùng để đáp lại lời cảm ơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_join', 'en-a1-6', 'join', '/dʒɔɪn/', 'A1', 'gia nhập; tham gia; nối; kết nối; nhập vào; cùng đi với', 'v.', 'joint (n.)', NULL, 'join a club nghĩa là trở thành thành viên của một tổ chức; join in nghĩa là tham gia vào một hoạt động.', 'Would you like to join us for lunch today?', NULL, 'Bạn có muốn dùng bữa trưa chung với chúng tôi hôm nay không?', '{"wordId":"join","ukIpa":"/dʒɔɪn/","usIpa":"/dʒɔɪn/","cefr":"A1","topic":"society","senses":[{"pos":"v.","en":"To become a member or take part with others.","vi":"gia nhập; tham gia"},{"pos":"v.","en":"To connect things or become connected.","vi":"nối; kết nối"},{"pos":"v.","en":"To go where someone is and spend time with them.","vi":"nhập vào; cùng đi với"}],"examples":[{"en":"Would you like to join us for lunch today?","vi":"Bạn có muốn dùng bữa trưa chung với chúng tôi hôm nay không?","audioKind":"ex"},{"en":"Students who join local volunteer groups can develop practical skills while contributing to their communities.","vi":"Những học sinh tham gia các nhóm tình nguyện địa phương có thể phát triển các kỹ năng thực tế đồng thời đóng góp cho cộng đồng của họ.","audioKind":"ex2"}],"collocations":[{"en":"join a club","vi":"gia nhập câu lạc bộ"},{"en":"join in","vi":"tham gia vào"},{"en":"join forces","vi":"hợp sức; chung tay"},{"en":"join together","vi":"nối liền với nhau"}],"wordFamily":["joint (n.)"],"synonyms":[],"antonyms":[],"tipVi":"join a club nghĩa là trở thành thành viên của một tổ chức; join in nghĩa là tham gia vào một hoạt động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chinese', 'en-a1-6', 'Chinese', '/ˌtʃaɪˈniːz/', 'A1', 'thuộc Trung Quốc; thuộc tiếng Trung; tiếng Trung; tiếng Hán; người Trung Quốc', 'adj.', 'China (n.)', NULL, 'Chữ cái đầu luôn viết hoa; chỉ một người Trung Quốc thường dùng a Chinese person.', 'We shared Chinese dumplings at a small restaurant yesterday.', NULL, 'Chúng tôi đã cùng nhau ăn sủi cảo Trung Hoa tại một quán ăn nhỏ hôm qua.', '{"wordId":"chinese","ukIpa":"/ˌtʃaɪˈniːz/","usIpa":"/ˌtʃaɪˈniːz/","cefr":"A1","topic":"society","senses":[{"pos":"adj.","en":"Relating to China, its people, or its languages.","vi":"thuộc Trung Quốc; thuộc tiếng Trung"},{"pos":"n.","en":"The group of languages spoken in China, especially Mandarin.","vi":"tiếng Trung; tiếng Hán"},{"pos":"n.","en":"People who come from China.","vi":"người Trung Quốc"}],"examples":[{"en":"We shared Chinese dumplings at a small restaurant yesterday.","vi":"Chúng tôi đã cùng nhau ăn sủi cảo Trung Hoa tại một quán ăn nhỏ hôm qua.","audioKind":"ex"},{"en":"Learning Chinese can help international students develop a deeper understanding of cultural traditions in China.","vi":"Học tiếng Trung có thể giúp sinh viên quốc tế nâng cao hiểu biết sâu sắc hơn về các truyền thống văn hóa tại Trung Quốc.","audioKind":"ex2"}],"collocations":[{"en":"Chinese culture","vi":"văn hóa Trung Hoa"},{"en":"learn Chinese","vi":"học tiếng Trung"},{"en":"Chinese characters","vi":"chữ Hán"},{"en":"Chinese cuisine","vi":"ẩm thực Trung Hoa"}],"wordFamily":["China (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ cái đầu luôn viết hoa; chỉ một người Trung Quốc thường dùng a Chinese person.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_person', 'en-a1-6', 'person', '/ˈpɝːsən/', 'A1', 'người; cá nhân; ngôi (trong ngữ pháp)', 'n.', 'personal (adj.), personally (adv.), personality (n.)', 'Đồng nghĩa: individual', 'Dạng số nhiều thông thường là people; persons thường gặp hơn trong văn cảnh pháp lý trang trọng.', 'Only one person was waiting outside the bakery.', NULL, 'Chỉ có một người đang đứng đợi bên ngoài tiệm bánh.', '{"wordId":"person","ukIpa":"/ˈpɜːsən/","usIpa":"/ˈpɝːsən/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"an individual human being","vi":"người; cá nhân"},{"pos":"n.","en":"a grammatical category distinguishing speakers, listeners, and others","vi":"ngôi (trong ngữ pháp)"}],"examples":[{"en":"Only one person was waiting outside the bakery.","vi":"Chỉ có một người đang đứng đợi bên ngoài tiệm bánh.","audioKind":"ex"},{"en":"Every person should have access to affordable healthcare, regardless of income or employment status.","vi":"Mỗi cá nhân nên được tiếp cận dịch vụ y tế phải chăng, bất kể thu nhập hay tình trạng việc làm.","audioKind":"ex2"}],"collocations":[{"en":"in person","vi":"trực tiếp; gặp mặt trực tiếp"},{"en":"a young person","vi":"một người trẻ tuổi"},{"en":"the average person","vi":"người bình thường"},{"en":"first person","vi":"ngôi thứ nhất"}],"wordFamily":["personal (adj.)","personally (adv.)","personality (n.)"],"synonyms":["individual"],"antonyms":[],"tipVi":"Dạng số nhiều thông thường là people; persons thường gặp hơn trong văn cảnh pháp lý trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_german', 'en-a1-6', 'German', '/ˈdʒɝːmən/', 'A1', 'thuộc về nước Đức, người Đức hoặc tiếng Đức; người Đức; tiếng Đức', 'adj.', 'Germany (n.)', NULL, 'Chữ cái đầu tiên phải viết hoa; khi chỉ tiếng Đức thường không dùng mạo từ.', 'We shared a traditional German cake after dinner.', NULL, 'Chúng tôi cùng nhau thưởng thức một chiếc bánh ngọt truyền thống của Đức sau bữa tối.', '{"wordId":"german","ukIpa":"/ˈdʒɜːmən/","usIpa":"/ˈdʒɝːmən/","cefr":"A1","topic":"society","senses":[{"pos":"adj.","en":"relating to Germany, its people, or its language","vi":"thuộc về nước Đức, người Đức hoặc tiếng Đức"},{"pos":"n.","en":"a person from Germany","vi":"người Đức"},{"pos":"n.","en":"the language spoken in Germany and some neighbouring countries","vi":"tiếng Đức"}],"examples":[{"en":"We shared a traditional German cake after dinner.","vi":"Chúng tôi cùng nhau thưởng thức một chiếc bánh ngọt truyền thống của Đức sau bữa tối.","audioKind":"ex"},{"en":"German universities attract international students through research opportunities and a wide range of degree programmes.","vi":"Các trường đại học ở Đức thu hút sinh viên quốc tế thông qua các cơ hội nghiên cứu và đa dạng các chương trình cấp bằng.","audioKind":"ex2"}],"collocations":[{"en":"German culture","vi":"văn hóa Đức"},{"en":"learn German","vi":"học tiếng Đức"},{"en":"a German citizen","vi":"công dân Đức"}],"wordFamily":["Germany (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ cái đầu tiên phải viết hoa; khi chỉ tiếng Đức thường không dùng mạo từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_parent', 'en-a1-6', 'parent', '/ˈperənt/', 'A1', 'cha hoặc mẹ; phụ huynh; công ty mẹ; nuôi dạy; chăm sóc con cái', 'n.', 'parental (adj.), parenting (n.), parenthood (n.)', NULL, 'parent chỉ một trong hai người (cha hoặc mẹ); parents thường chỉ cả cha lẫn mẹ.', 'Each parent brought a snack for the school picnic.', NULL, 'Mỗi bậc phụ huynh đã chuẩn bị một phần đồ ăn nhẹ cho buổi dã ngoại của trường.', '{"wordId":"parent","ukIpa":"/ˈpeərənt/","usIpa":"/ˈperənt/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"a person''s mother or father","vi":"cha hoặc mẹ; phụ huynh"},{"pos":"n.","en":"a company that owns or controls another company","vi":"công ty mẹ"},{"pos":"v.","en":"to raise and care for a child as a parent","vi":"nuôi dạy; chăm sóc con cái"}],"examples":[{"en":"Each parent brought a snack for the school picnic.","vi":"Mỗi bậc phụ huynh đã chuẩn bị một phần đồ ăn nhẹ cho buổi dã ngoại của trường.","audioKind":"ex"},{"en":"Schools should involve parents in educational decisions because family support plays an important role in children''s learning.","vi":"Nhà trường nên tạo điều kiện để phụ huynh tham gia vào các quyết định giáo dục vì sự hỗ trợ từ gia đình đóng vai trò quan trọng trong việc học tập của trẻ.","audioKind":"ex2"}],"collocations":[{"en":"single parent","vi":"cha/mẹ đơn thân"},{"en":"working parents","vi":"các bậc cha mẹ đang đi làm"},{"en":"parent company","vi":"công ty mẹ"},{"en":"parent involvement","vi":"sự tham gia của phụ huynh"}],"wordFamily":["parental (adj.)","parenting (n.)","parenthood (n.)"],"synonyms":[],"antonyms":[],"tipVi":"parent chỉ một trong hai người (cha hoặc mẹ); parents thường chỉ cả cha lẫn mẹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_famous', 'en-a1-6', 'famous', '/ˈfeɪməs/', 'A1', 'nổi tiếng; được nhiều người biết đến', 'adj.', 'fame (n.), famously (adv.)', 'Đồng nghĩa: well-known, renowned, celebrated · Trái nghĩa: unknown, obscure', 'famous for đi kèm với lý do nổi tiếng, famous as đi kèm với vai trò hoặc danh nghĩa.', 'This village is famous for its delicious apple pies.', NULL, 'Ngôi làng này nổi tiếng với những chiếc bánh táo thơm ngon.', '{"wordId":"famous","ukIpa":"/ˈfeɪməs/","usIpa":"/ˈfeɪməs/","cefr":"A1","topic":"society","senses":[{"pos":"adj.","en":"Known by many people.","vi":"nổi tiếng; được nhiều người biết đến"}],"examples":[{"en":"This village is famous for its delicious apple pies.","vi":"Ngôi làng này nổi tiếng với những chiếc bánh táo thơm ngon.","audioKind":"ex"},{"en":"Famous landmarks attract international visitors, but tourism revenue should also support the communities surrounding them.","vi":"Những thắng cảnh nổi tiếng thu hút du khách quốc tế, nhưng doanh thu từ du lịch cũng cần hỗ trợ cho các cộng đồng xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"famous for","vi":"nổi tiếng vì điều gì"},{"en":"famous as","vi":"nổi tiếng với tư cách là"},{"en":"world famous","vi":"nổi tiếng thế giới"}],"wordFamily":["fame (n.)","famously (adv.)"],"synonyms":["well-known","renowned","celebrated"],"antonyms":["unknown","obscure"],"tipVi":"famous for đi kèm với lý do nổi tiếng, famous as đi kèm với vai trò hoặc danh nghĩa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grandfather', 'en-a1-6', 'grandfather', '/ˈɡrænfɑːðər/', 'A1', 'ông nội; ông ngoại', 'n.', 'grandmother (n.), grandparent (n.), grandchild (n.)', 'Đồng nghĩa: granddad, grandpa', 'Không phân biệt ông nội hay ông ngoại trong từ này; ông ngoại có thể gọi cụ thể là maternal grandfather.', 'My grandfather taught me how to grow tomatoes.', NULL, 'Ông nội đã dạy tôi cách trồng cà chua.', '{"wordId":"grandfather","ukIpa":"/ˈɡrænfɑːðə/","usIpa":"/ˈɡrænfɑːðər/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"The father of your mother or father.","vi":"ông nội; ông ngoại"}],"examples":[{"en":"My grandfather taught me how to grow tomatoes.","vi":"Ông nội đã dạy tôi cách trồng cà chua.","audioKind":"ex"},{"en":"A grandfather who provides regular childcare can strengthen family bonds and support working parents.","vi":"Một người ông thường xuyên chăm sóc cháu có thể thắt chặt tình cảm gia đình và hỗ trợ các bậc cha mẹ đang đi làm.","audioKind":"ex2"}],"collocations":[{"en":"maternal grandfather","vi":"ông ngoại"},{"en":"paternal grandfather","vi":"ông nội"}],"wordFamily":["grandmother (n.)","grandparent (n.)","grandchild (n.)"],"synonyms":["granddad","grandpa"],"antonyms":[],"tipVi":"Không phân biệt ông nội hay ông ngoại trong từ này; ông ngoại có thể gọi cụ thể là maternal grandfather.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_friend', 'en-a1-6', 'friend', '/frend/', 'A1', 'n. bạn; bạn bè; chiến hữu', 'n.', 'friendly (adj.), friendship (n.), befriend (v.), unfriendly (adj.)', 'Đồng nghĩa: companion, pal · Trái nghĩa: enemy', 'Cụm từ “kết bạn với ai” dùng make friends with, trong đó friends ở dạng số nhiều.', 'I met an old friend at the market yesterday.', NULL, 'Tôi đã gặp một người bạn cũ ở chợ vào ngày hôm qua.', '{"wordId":"friend","ukIpa":"/frend/","usIpa":"/frend/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"someone you know well, like, and enjoy spending time with","vi":"n. bạn; bạn bè; chiến hữu"}],"examples":[{"en":"I met an old friend at the market yesterday.","vi":"Tôi đã gặp một người bạn cũ ở chợ vào ngày hôm qua.","audioKind":"ex"},{"en":"Maintaining close friendships can improve mental wellbeing, as friends often provide emotional support during difficult periods.","vi":"Duy trì tình bạn thân thiết có thể cải thiện sức khỏe tinh thần, bởi vì bạn bè thường mang lại sự hỗ trợ cảm xúc trong những giai đoạn khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"close friend","vi":"bạn thân"},{"en":"childhood friend","vi":"bạn thuở nhỏ"},{"en":"make friends with","vi":"kết bạn với"},{"en":"keep in touch with friends","vi":"giữ liên lạc với bạn bè"}],"wordFamily":["friendly (adj.)","friendship (n.)","befriend (v.)","unfriendly (adj.)"],"synonyms":["companion","pal"],"antonyms":["enemy"],"tipVi":"Cụm từ “kết bạn với ai” dùng make friends with, trong đó friends ở dạng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_club', 'en-a1-6', 'club', '/klʌb/', 'A1', 'câu lạc bộ; hội nhóm; hộp đêm; quán bar nhảy; gậy đánh golf; gậy tày', 'n.', NULL, NULL, 'join a club có nghĩa là gia nhập một câu lạc bộ, không dùng join in a club.', 'I joined a chess club to meet new people.', NULL, 'Tôi đã gia nhập một câu lạc bộ cờ vua để làm quen với những người bạn mới.', '{"wordId":"club","ukIpa":"/klʌb/","usIpa":"/klʌb/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"an organisation whose members share an interest or activity","vi":"câu lạc bộ; hội nhóm"},{"pos":"n.","en":"a place where people dance and socialise at night","vi":"hộp đêm; quán bar nhảy"},{"pos":"n.","en":"a stick used to hit a golf ball or strike something","vi":"gậy đánh golf; gậy tày"}],"examples":[{"en":"I joined a chess club to meet new people.","vi":"Tôi đã gia nhập một câu lạc bộ cờ vua để làm quen với những người bạn mới.","audioKind":"ex"},{"en":"A school sports club can help students develop teamwork skills while encouraging regular physical activity.","vi":"Câu lạc bộ thể thao trường học có thể giúp học sinh phát triển kỹ năng làm việc nhóm đồng thời khuyến khích tập thể dục thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"join a club","vi":"gia nhập câu lạc bộ"},{"en":"a sports club","vi":"câu lạc bộ thể thao"},{"en":"a club member","vi":"thành viên câu lạc bộ"},{"en":"a golf club","vi":"gậy đánh golf"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"join a club có nghĩa là gia nhập một câu lạc bộ, không dùng join in a club.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_woman', 'en-a1-6', 'woman', '/ˈwʊmən/', 'A1', 'phụ nữ; người phụ nữ', 'n.', 'womanhood (n.)', 'Trái nghĩa: man', 'Danh từ số nhiều women phát âm là /ˈwɪmɪn/, chú ý sự thay đổi ở âm tiết đầu.', 'The woman next door grows beautiful flowers on her balcony.', NULL, 'Người phụ nữ nhà bên trồng rất nhiều hoa đẹp ngoài ban công.', '{"wordId":"woman","ukIpa":"/ˈwʊmən/","usIpa":"/ˈwʊmən/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"An adult female person.","vi":"phụ nữ; người phụ nữ"}],"examples":[{"en":"The woman next door grows beautiful flowers on her balcony.","vi":"Người phụ nữ nhà bên trồng rất nhiều hoa đẹp ngoài ban công.","audioKind":"ex"},{"en":"Ensuring that every woman has access to education can improve health and economic opportunities across generations.","vi":"Đảm bảo mọi phụ nữ đều có quyền tiếp cận giáo dục có thể cải thiện sức khỏe và cơ hội kinh tế qua các thế hệ.","audioKind":"ex2"}],"collocations":[{"en":"young woman","vi":"phụ nữ trẻ"},{"en":"working woman","vi":"nữ nhân viên; phụ nữ đi làm"},{"en":"women''s rights","vi":"quyền của phụ nữ"}],"wordFamily":["womanhood (n.)"],"synonyms":[],"antonyms":["man"],"tipVi":"Danh từ số nhiều women phát âm là /ˈwɪmɪn/, chú ý sự thay đổi ở âm tiết đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_police', 'en-a1-6', 'police', '/pəˈliːs/', 'A1', 'cảnh sát; lực lượng công an; giữ gìn trật tự; kiểm soát', 'n.', 'policing (n.)', NULL, 'the police làm chủ ngữ đi với động từ số nhiều; một cảnh sát dùng a police officer.', 'The police helped us find our missing bicycle.', NULL, 'Cảnh sát đã giúp chúng tôi tìm lại chiếc xe đạp bị mất.', '{"wordId":"police","ukIpa":"/pəˈliːs/","usIpa":"/pəˈliːs/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"The official organisation responsible for preventing crime and maintaining order.","vi":"cảnh sát; lực lượng công an"},{"pos":"v.","en":"To maintain order somewhere or ensure rules are obeyed.","vi":"giữ gìn trật tự; kiểm soát"}],"examples":[{"en":"The police helped us find our missing bicycle.","vi":"Cảnh sát đã giúp chúng tôi tìm lại chiếc xe đạp bị mất.","audioKind":"ex"},{"en":"Effective cooperation between police and local residents can improve public safety and build trust within communities.","vi":"Sự hợp tác hiệu quả giữa cảnh sát và người dân địa phương có thể cải thiện an ninh công cộng và xây dựng lòng tin trong cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"police officer","vi":"viên cảnh sát"},{"en":"police station","vi":"đồn cảnh sát"},{"en":"call the police","vi":"gọi cảnh sát"},{"en":"police an event","vi":"bảo đảm trật tự sự kiện"}],"wordFamily":["policing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"the police làm chủ ngữ đi với động từ số nhiều; một cảnh sát dùng a police officer.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_everybody', 'en-a1-6', 'everybody', '/ˈevribɑːdi/', 'A1', 'mọi người; tất cả mọi người', 'pron.', NULL, 'Đồng nghĩa: everyone · Trái nghĩa: nobody', 'Khi làm chủ ngữ, động từ đi kèm ở ngôi thứ ba số ít: Everybody is ready.', 'Everybody is waiting outside for the doors to open.', NULL, 'Mọi người đều đang đứng chờ ở bên ngoài để mở cửa.', '{"wordId":"everybody","ukIpa":"/ˈevribɒdi/","usIpa":"/ˈevribɑːdi/","cefr":"A1","topic":"society","senses":[{"pos":"pron.","en":"Every person in a group, or all people generally.","vi":"mọi người; tất cả mọi người"}],"examples":[{"en":"Everybody is waiting outside for the doors to open.","vi":"Mọi người đều đang đứng chờ ở bên ngoài để mở cửa.","audioKind":"ex"},{"en":"Public libraries should offer accessible services so that everybody can benefit from opportunities for lifelong learning.","vi":"Các thư viện công cộng nên cung cấp các dịch vụ tiếp cận thuận lợi để mọi người đều có thể hưởng lợi từ cơ hội học tập suốt đời.","audioKind":"ex2"}],"collocations":[{"en":"everybody else","vi":"mọi người khác"},{"en":"almost everybody","vi":"hầu như tất cả mọi người"},{"en":"everybody involved","vi":"tất cả những người có liên quan"}],"wordFamily":[],"synonyms":["everyone"],"antonyms":["nobody"],"tipVi":"Khi làm chủ ngữ, động từ đi kèm ở ngôi thứ ba số ít: Everybody is ready.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_son', 'en-a1-6', 'son', '/sʌn/', 'A1', 'con trai', 'n.', NULL, NULL, 'son phát âm giống từ sun; một người đàn ông dù đã trưởng thành vẫn là son của cha mẹ mình.', 'Their son helped them plant flowers in the garden.', NULL, 'Con trai họ đã giúp họ trồng hoa trong vườn.', '{"wordId":"son","ukIpa":"/sʌn/","usIpa":"/sʌn/","cefr":"A1","topic":"society","senses":[{"pos":"n.","en":"A male child in relation to his parents.","vi":"con trai"}],"examples":[{"en":"Their son helped them plant flowers in the garden.","vi":"Con trai họ đã giúp họ trồng hoa trong vườn.","audioKind":"ex"},{"en":"Parents should give their sons and daughters equal opportunities to pursue education and develop practical skills.","vi":"Cha mẹ nên tạo cơ hội công bằng cho cả con trai và con gái để theo đuổi học tập và phát triển các kỹ năng thực tế.","audioKind":"ex2"}],"collocations":[{"en":"an only son","vi":"con trai một"},{"en":"an eldest son","vi":"con trai trưởng"},{"en":"raise a son","vi":"nuôi dạy con trai"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"son phát âm giống từ sun; một người đàn ông dù đã trưởng thành vẫn là son của cha mẹ mình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_invite', 'en-a1-6', 'invite', '/ɪnˈvaɪt/', 'A1', 'mời; mời gọi; đòi hỏi; thu hút; rước lấy', 'v.', 'invitation (n.), inviting (adj.)', 'Đồng nghĩa: ask', 'Cấu trúc invite sb to + sự kiện; invite sb to do + hành động.', 'Let''s invite our new neighbours over for dinner.', NULL, 'Chúng ta hãy mời những người hàng xóm mới sang ăn tối nhé.', '{"wordId":"invite","ukIpa":"/ɪnˈvaɪt/","usIpa":"/ɪnˈvaɪt/","cefr":"A1","topic":"society","senses":[{"pos":"v.","en":"to ask someone to attend something or do something","vi":"mời; mời gọi"},{"pos":"v.","en":"to request a response or make a reaction likely","vi":"đòi hỏi; thu hút; rước lấy"}],"examples":[{"en":"Let''s invite our new neighbours over for dinner.","vi":"Chúng ta hãy mời những người hàng xóm mới sang ăn tối nhé.","audioKind":"ex"},{"en":"Local councils should invite residents to discuss proposed changes before making decisions about public spaces.","vi":"Chính quyền địa phương nên mời người dân thảo luận về các thay đổi dự kiến trước khi đưa ra quyết định về không gian công cộng.","audioKind":"ex2"}],"collocations":[{"en":"invite someone to dinner","vi":"mời ai ăn tối"},{"en":"invite someone to do something","vi":"mời ai làm việc gì"},{"en":"invite feedback","vi":"kêu gọi đóng góp ý kiến"},{"en":"invite criticism","vi":"rước họa vào thân; chuốc lấy chỉ trích"}],"wordFamily":["invitation (n.)","inviting (adj.)"],"synonyms":["ask"],"antonyms":[],"tipVi":"Cấu trúc invite sb to + sự kiện; invite sb to do + hành động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_american', 'en-a1-6', 'American', '/əˈmerɪkən/', 'A1', 'thuộc về nước Mỹ; thuộc về người Mỹ; người Mỹ', 'adj.', 'America (n.)', NULL, 'Chữ cái đầu luôn viết hoa; thường chỉ nước Mỹ thay vì toàn bộ châu Mỹ.', 'My American neighbour invited us over for pumpkin pie.', NULL, 'Người hàng xóm người Mỹ của chúng tôi đã mời chúng tôi sang ăn bánh bí ngô.', '{"wordId":"american","ukIpa":"/əˈmerɪkən/","usIpa":"/əˈmerɪkən/","cefr":"A1","topic":"society","senses":[{"pos":"adj.","en":"relating to the United States, its people, or its culture","vi":"thuộc về nước Mỹ; thuộc về người Mỹ"},{"pos":"n.","en":"a person from the United States","vi":"người Mỹ"}],"examples":[{"en":"My American neighbour invited us over for pumpkin pie.","vi":"Người hàng xóm người Mỹ của chúng tôi đã mời chúng tôi sang ăn bánh bí ngô.","audioKind":"ex"},{"en":"American universities attract international students through their diverse courses, research facilities, and opportunities for professional development.","vi":"Các trường đại học Mỹ thu hút sinh viên quốc tế thông qua các chương trình học đa dạng, cơ hội nghiên cứu và phát triển nghề nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"American English","vi":"tiếng Anh Mỹ"},{"en":"American culture","vi":"văn hóa Mỹ"},{"en":"an American citizen","vi":"một công dân Mỹ"}],"wordFamily":["America (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ cái đầu luôn viết hoa; thường chỉ nước Mỹ thay vì toàn bộ châu Mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_russian', 'en-a1-6', 'Russian', '/ˈrʌʃən/', 'A1', 'thuộc về nước Nga; tiếng Nga; người Nga; tiếng Nga', 'adj.', 'Russia (n.)', NULL, 'Chữ cái đầu bắt buộc viết hoa; khi chỉ tiếng Nga thì thường không dùng mạo từ.', 'We cooked Russian dumplings for dinner last night.', NULL, 'Tối qua chúng tôi đã nấu món bánh xếp kiểu Nga cho bữa tối.', '{"wordId":"russian","ukIpa":"/ˈrʌʃən/","usIpa":"/ˈrʌʃən/","cefr":"A1","topic":"society","senses":[{"pos":"adj.","en":"Relating to Russia, its people, or its language.","vi":"thuộc về nước Nga; tiếng Nga"},{"pos":"n.","en":"A person from Russia.","vi":"người Nga"},{"pos":"n.","en":"The main language spoken in Russia.","vi":"tiếng Nga"}],"examples":[{"en":"We cooked Russian dumplings for dinner last night.","vi":"Tối qua chúng tôi đã nấu món bánh xếp kiểu Nga cho bữa tối.","audioKind":"ex"},{"en":"Studying Russian literature can help students explore how historical events influence cultural identity and artistic expression.","vi":"Việc học văn hóa và văn học Nga có thể giúp học sinh khám phá cách các sự kiện lịch sử định hình bản sắc văn hóa và biểu đạt nghệ thuật.","audioKind":"ex2"}],"collocations":[{"en":"Russian literature","vi":"văn học Nga"},{"en":"Russian speaker","vi":"người nói tiếng Nga"},{"en":"learn Russian","vi":"học tiếng Nga"}],"wordFamily":["Russia (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ cái đầu bắt buộc viết hoa; khi chỉ tiếng Nga thì thường không dùng mạo từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_british', 'en-a1-6', 'British', '/ˈbrɪtɪʃ/', 'A1', 'thuộc về hoặc liên quan đến Vương quốc Anh, người dân hoặc văn hóa nước này; người Anh (tên gọi chung cho người dân Vương quốc Anh)', 'adj.', 'Britain (n.), Briton (n.)', NULL, 'Cách gọi chung cho người Anh là the British; một cá nhân người Anh dùng a Briton.', 'My British neighbour invited us over for tea.', NULL, 'Người hàng xóm gốc Anh của chúng tôi đã mời chúng tôi sang uống trà.', '{"wordId":"british","ukIpa":"/ˈbrɪtɪʃ/","usIpa":"/ˈbrɪtɪʃ/","cefr":"A1","topic":"society","senses":[{"pos":"adj.","en":"Relating to the United Kingdom, its people, or their culture.","vi":"thuộc về hoặc liên quan đến Vương quốc Anh, người dân hoặc văn hóa nước này"},{"pos":"n.","en":"The people of the United Kingdom, considered collectively.","vi":"người Anh (tên gọi chung cho người dân Vương quốc Anh)"}],"examples":[{"en":"My British neighbour invited us over for tea.","vi":"Người hàng xóm gốc Anh của chúng tôi đã mời chúng tôi sang uống trà.","audioKind":"ex"},{"en":"British universities attract international students through their research strengths and the wide range of courses they offer.","vi":"Các trường đại học Anh quốc thu hút sinh viên quốc tế nhờ vào thế mạnh nghiên cứu và đa dạng các chương trình học mà họ cung cấp.","audioKind":"ex2"}],"collocations":[{"en":"British culture","vi":"văn hóa Anh"},{"en":"British citizen","vi":"công dân Anh"},{"en":"British English","vi":"tiếng Anh (Anh)"}],"wordFamily":["Britain (n.)","Briton (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cách gọi chung cho người Anh là the British; một cá nhân người Anh dùng a Briton.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_6_1', 'en-a1-6', 'Cách dùng “cousin” (n.) — anh chị em họ (con của bác, chú, cậu, cô, dì)', 'a first cousin  ·  a distant cousin  ·  a younger cousin', 'Từ này không phân biệt họ nội hay họ ngoại, nam hay nữ, lớn hay nhỏ; cần làm rõ thì dùng thêm từ bổ nghĩa.', NULL, '[{"hanzi":"My cousin taught me to ride a bicycle yesterday.","pinyin":"","meaning":"Người em họ của tôi đã dạy tôi đi xe đạp ngày hôm qua."},{"hanzi":"Children who regularly spend time with their cousins may develop strong family bonds beyond their immediate household.","pinyin":"","meaning":"Những đứa trẻ thường xuyên dành thời gian với anh chị em họ của chúng có thể phát triển mối liên kết gia đình mạnh mẽ ngoài phạm vi gia đình hạt nhân."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_6_2', 'en-a1-6', 'Cách dùng “join” (v.) — gia nhập; tham gia', 'join a club  ·  join in  ·  join forces', 'join a club nghĩa là trở thành thành viên của một tổ chức; join in nghĩa là tham gia vào một hoạt động.', 'Họ từ (Word Family): joint (n.)', '[{"hanzi":"Would you like to join us for lunch today?","pinyin":"","meaning":"Bạn có muốn dùng bữa trưa chung với chúng tôi hôm nay không?"},{"hanzi":"Students who join local volunteer groups can develop practical skills while contributing to their communities.","pinyin":"","meaning":"Những học sinh tham gia các nhóm tình nguyện địa phương có thể phát triển các kỹ năng thực tế đồng thời đóng góp cho cộng đồng của họ."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_6_3', 'en-a1-6', 'Cách dùng “grandfather” (n.) — ông nội; ông ngoại', 'maternal grandfather  ·  paternal grandfather', 'Không phân biệt ông nội hay ông ngoại trong từ này; ông ngoại có thể gọi cụ thể là maternal grandfather.', 'Họ từ (Word Family): grandmother (n.), grandparent (n.), grandchild (n.) | Đồng nghĩa: granddad, grandpa', '[{"hanzi":"My grandfather taught me how to grow tomatoes.","pinyin":"","meaning":"Ông nội đã dạy tôi cách trồng cà chua."},{"hanzi":"A grandfather who provides regular childcare can strengthen family bonds and support working parents.","pinyin":"","meaning":"Một người ông thường xuyên chăm sóc cháu có thể thắt chặt tình cảm gia đình và hỗ trợ các bậc cha mẹ đang đi làm."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_6_4', 'en-a1-6', 'Cách dùng “person” (n.) — người; cá nhân', 'in person  ·  a young person  ·  the average person', 'Dạng số nhiều thông thường là people; persons thường gặp hơn trong văn cảnh pháp lý trang trọng.', 'Họ từ (Word Family): personal (adj.), personally (adv.), personality (n.) | Đồng nghĩa: individual', '[{"hanzi":"Only one person was waiting outside the bakery.","pinyin":"","meaning":"Chỉ có một người đang đứng đợi bên ngoài tiệm bánh."},{"hanzi":"Every person should have access to affordable healthcare, regardless of income or employment status.","pinyin":"","meaning":"Mỗi cá nhân nên được tiếp cận dịch vụ y tế phải chăng, bất kể thu nhập hay tình trạng việc làm."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
