INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_6_1_1', 'en-a1-6', 'ten_6_1', 'listening', 'listening', 'We cooked dinner together and shared stories about our day.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi cùng nhau nấu bữa tối và chia sẻ những câu chuyện về ngày hôm nay.","Những người hàng xóm đã bước ra ngoài để chào đón chúng tôi về nhà.","Ba người phụ nữ đang trồng hoa trong khu vườn chung.","Sáng nay có vài người đang đợi bên ngoài tiệm bánh."]'::jsonb, 0, 'We cooked dinner together and shared stories about our day. → Chúng tôi cùng nhau nấu bữa tối và chia sẻ những câu chuyện về ngày hôm nay.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
