INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_6_1_3', 'en-a1-6', 'ten_6_1', 'listening', 'listening', 'Everyone brought a dish to share at the picnic.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Mọi người đều mang theo một món ăn để chia sẻ trong buổi dã ngoại.","Chúng tôi đã cùng nhau ăn sủi cảo Trung Hoa tại một quán ăn nhỏ hôm qua.","Ba người phụ nữ đang trồng hoa trong khu vườn chung.","Chúng tôi cùng nhau nấu bữa tối và chia sẻ những câu chuyện về ngày hôm nay."]'::jsonb, 0, 'Everyone brought a dish to share at the picnic. → Mọi người đều mang theo một món ăn để chia sẻ trong buổi dã ngoại.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_6_2', 'en-a1-6', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_6_2_1', 'ten_6_2', 'together', 'Schools and families should work together to help children develop healthy habits from an early age.', 'Schools and families should work together to help children develop healthy habits from an early age.', '/təˈɡeðɚ/', 'Nhà trường và gia đình nên cùng nhau nỗ lực để giúp trẻ hình thành thói quen lành mạnh ngay từ nhỏ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_6_2_2', 'ten_6_2', 'cousin', 'Children who regularly spend time with their cousins may develop strong family bonds beyond their immediate household.', 'Children who regularly spend time with their cousins may develop strong family bonds beyond their immediate household.', '/ˈkʌzən/', 'Những đứa trẻ thường xuyên dành thời gian với anh chị em họ của chúng có thể phát triển mối liên kết gia đình mạnh mẽ ngoài phạm vi gia đình hạt nhân.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_6_2_3', 'ten_6_2', 'everyone', 'Public libraries should ensure that everyone can access reliable information, regardless of income or educational background.', 'Public libraries should ensure that everyone can access reliable information, regardless of income or educational background.', '/ˈevriwʌn/', 'Các thư viện công cộng nên đảm bảo rằng mọi người đều có thể tiếp cận thông tin đáng tin cậy, bất kể thu nhập hay nền tảng học vấn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_6_2_4', 'ten_6_2', 'people', 'Cities should provide accessible public transport so that people of all ages can travel independently.', 'Cities should provide accessible public transport so that people of all ages can travel independently.', '/ˈpiːpəl/', 'Các thành phố nên cung cấp giao thông công cộng dễ tiếp cận để mọi người ở mọi lứa tuổi có thể di chuyển độc lập.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_6_2_5', 'ten_6_2', 'women', 'Equal access to education enables more women to pursue careers in science and technology.', 'Equal access to education enables more women to pursue careers in science and technology.', '/ˈwɪmɪn/', 'Cơ hội tiếp cận giáo dục bình đẳng giúp nhiều phụ nữ theo đuổi sự nghiệp trong lĩnh vực khoa học và công nghệ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_6_2_6', 'ten_6_2', 'welcome', 'Many communities welcome new cultural festivals because they encourage social interaction and support local businesses.', 'Many communities welcome new cultural festivals because they encourage social interaction and support local businesses.', '/ˈwelkəm/', 'Nhiều cộng đồng hoan nghênh các lễ hội văn hóa mới vì chúng thúc đẩy giao lưu xã hội và hỗ trợ các doanh nghiệp địa phương.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_6_2_1', 'en-a1-6', 'ten_6_2', 'listening', 'listening', 'Schools and families should work together to help children develop healthy habits from an early age.', NULL, 'Trong câu vừa nghe, từ “together” mang nghĩa nào sau đây?', '["đàn ghi-ta; đàn guitar","lặp lại; nói lại; làm lại","từ điển","cùng nhau; với nhau"]'::jsonb, 3, '“together” (/təˈɡeðɚ/): cùng nhau; với nhau. Câu đầy đủ: Schools and families should work together to help children develop healthy habits from an early age.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_6_2_2', 'en-a1-6', 'ten_6_2', 'listening', 'listening', 'Children who regularly spend time with their cousins may develop strong family bonds beyond their immediate household.', NULL, 'Trong câu vừa nghe, từ “cousin” mang nghĩa nào sau đây?', '["anh chị em họ (con của bác, chú, cậu, cô, dì)","thân yêu; quý giá; được trân trọng","thức ăn; đồ ăn; thực phẩm","bàn tay"]'::jsonb, 0, '“cousin” (/ˈkʌzən/): anh chị em họ (con của bác, chú, cậu, cô, dì). Câu đầy đủ: Children who regularly spend time with their cousins may develop strong family bonds beyond their immediate household.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
