INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_6_2', 'en-a1-6', NULL, 'comprehensive_test', 'listening', 'My cousin taught me to ride a bicycle yesterday.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng ta hãy mời những người hàng xóm mới sang ăn tối nhé.","Chúng tôi đã cùng nhau ăn sủi cảo Trung Hoa tại một quán ăn nhỏ hôm qua.","Người em họ của tôi đã dạy tôi đi xe đạp ngày hôm qua.","Tối qua chúng tôi đã nấu món bánh xếp kiểu Nga cho bữa tối."]'::jsonb, 2, 'My cousin taught me to ride a bicycle yesterday. → Người em họ của tôi đã dạy tôi đi xe đạp ngày hôm qua.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_6_3', 'en-a1-6', NULL, 'comprehensive_test', 'listening', 'everyone', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["n. rượu vang; rượu nho","uống","mọi người; tất cả mọi người","nông dân; chủ trang trại"]'::jsonb, 2, 'everyone (/ˈevriwʌn/) → mọi người; tất cả mọi người', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_6_4', 'en-a1-6', NULL, 'comprehensive_test', 'listening', 'Several people were waiting outside the bakery this morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi cùng nhau thưởng thức một chiếc bánh ngọt truyền thống của Đức sau bữa tối.","Sáng nay có vài người đang đợi bên ngoài tiệm bánh.","Tôi đã gặp một người bạn cũ ở chợ vào ngày hôm qua.","Người hàng xóm người Mỹ của chúng tôi đã mời chúng tôi sang ăn bánh bí ngô."]'::jsonb, 1, 'Several people were waiting outside the bakery this morning. → Sáng nay có vài người đang đợi bên ngoài tiệm bánh.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_6_5', 'en-a1-6', NULL, 'comprehensive_test', 'listening', 'women', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["những người phụ nữ; phái nữ","tiệm sách; hiệu sách","màu tím; có màu tím","quả chuối"]'::jsonb, 0, 'women (/ˈwɪmɪn/) → những người phụ nữ; phái nữ', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_6_6', 'en-a1-6', NULL, 'comprehensive_test', 'listening', 'Our neighbours came outside to welcome us home.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chỉ có một người đang đứng đợi bên ngoài tiệm bánh.","Tôi đã gặp một người bạn cũ ở chợ vào ngày hôm qua.","Những người hàng xóm đã bước ra ngoài để chào đón chúng tôi về nhà.","Tôi đã gia nhập một câu lạc bộ cờ vua để làm quen với những người bạn mới."]'::jsonb, 2, 'Our neighbours came outside to welcome us home. → Những người hàng xóm đã bước ra ngoài để chào đón chúng tôi về nhà.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
