INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_6_18', 'en-a1-6', NULL, 'comprehensive_test', 'reading', NULL, 'Schools and families should work together to help children develop healthy habits from an early age.', 'Dựa vào câu trên, từ “together” có nghĩa phù hợp nhất là gì?', '["bàn học; bàn làm việc","vé; thẻ lên tàu xe; vé vào cửa","nhiều (dùng với danh từ đếm được số nhiều)","cùng nhau; với nhau"]'::jsonb, 3, 'together: cùng nhau; với nhau; hợp lại; kết hợp với nhau. Dịch cả câu: Nhà trường và gia đình nên cùng nhau nỗ lực để giúp trẻ hình thành thói quen lành mạnh ngay từ nhỏ.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_6_19', 'en-a1-6', NULL, 'comprehensive_test', 'reading', NULL, 'Children who regularly spend time with their cousins may develop strong family bonds beyond their immediate household.', 'Dựa vào câu trên, từ “cousin” có nghĩa phù hợp nhất là gì?', '["anh chị em họ (con của bác, chú, cậu, cô, dì)","lắng nghe; chú ý lắng nghe","thỉnh thoảng; đôi khi","tuyết"]'::jsonb, 0, 'cousin: anh chị em họ (con của bác, chú, cậu, cô, dì). Dịch cả câu: Những đứa trẻ thường xuyên dành thời gian với anh chị em họ của chúng có thể phát triển mối liên kết gia đình mạnh mẽ ngoài phạm vi gia đình hạt nhân.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_6_20', 'en-a1-6', NULL, 'comprehensive_test', 'reading', NULL, 'Public libraries should ensure that everyone can access reliable information, regardless of income or educational background.', 'Dựa vào câu trên, từ “everyone” có nghĩa phù hợp nhất là gì?', '["may mắn","số một (số nguyên dương nhỏ nhất)","tờ báo; báo chí","mọi người; tất cả mọi người"]'::jsonb, 3, 'everyone: mọi người; tất cả mọi người. Dịch cả câu: Các thư viện công cộng nên đảm bảo rằng mọi người đều có thể tiếp cận thông tin đáng tin cậy, bất kể thu nhập hay nền tảng học vấn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_6_21', 'en-a1-6', NULL, 'comprehensive_test', 'reading', NULL, 'Cities should provide accessible public transport so that people of all ages can travel independently.', 'Dựa vào câu trên, từ “people” có nghĩa phù hợp nhất là gì?', '["mọi người; con người","bán; tiêu thụ","nhớ; hồi tưởng","thường; thường xuyên"]'::jsonb, 0, 'people: mọi người; con người; dân tộc; tộc người. Dịch cả câu: Các thành phố nên cung cấp giao thông công cộng dễ tiếp cận để mọi người ở mọi lứa tuổi có thể di chuyển độc lập.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
