INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_6_23', 'en-a1-6', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuộc về nước Nga; tiếng Nga”', '["remember","card","Russian","machine"]'::jsonb, 2, 'thuộc về nước Nga; tiếng Nga → Russian (/ˈrʌʃən/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_6_24', 'en-a1-6', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuộc về hoặc liên quan đến Vương quốc Anh, người dân hoặc văn hóa nước này”', '["look","British","daughter","bedroom"]'::jsonb, 1, 'thuộc về hoặc liên quan đến Vương quốc Anh, người dân hoặc văn hóa nước này → British (/ˈbrɪtɪʃ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-7', 'en', 'Bài 7: Thiên nhiên & Thời tiết (1) - CEFR A1', 'CEFR A1', 'A1 · Thiên nhiên', '20 từ vựng Tiếng Anh CEFR A1 chủ đề thiên nhiên & thời tiết kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1007, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_river', 'en-a1-7', 'river', '/ˈrɪvər/', 'A1', 'sông; dòng sông', 'n.', NULL, NULL, 'Tên các con sông thường đi kèm mạo từ the, ví dụ như the River Nile.', 'We watched ducks swimming across the river this morning.', NULL, 'Sáng nay chúng tôi ngắm những chú vịt bơi qua sông.', '{"wordId":"river","ukIpa":"/ˈrɪvə/","usIpa":"/ˈrɪvər/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"a large natural stream of water flowing towards another water body","vi":"sông; dòng sông"}],"examples":[{"en":"We watched ducks swimming across the river this morning.","vi":"Sáng nay chúng tôi ngắm những chú vịt bơi qua sông.","audioKind":"ex"},{"en":"Protecting river ecosystems requires cooperation between farming communities, local industries, and environmental agencies.","vi":"Việc bảo vệ các hệ sinh thái sông ngòi đòi hỏi sự hợp tác giữa các cộng đồng làm nông nghiệp, các khu công nghiệp địa phương và các cơ quan môi trường.","audioKind":"ex2"}],"collocations":[{"en":"river bank","vi":"bờ sông"},{"en":"river basin","vi":"lưu vực sông"},{"en":"cross a river","vi":"băng qua sông"},{"en":"river pollution","vi":"ô nhiễm sông ngòi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tên các con sông thường đi kèm mạo từ the, ví dụ như the River Nile.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_horse', 'en-a1-7', 'horse', '/hɔːrs/', 'A1', 'con ngựa', 'n.', NULL, NULL, 'Cưỡi ngựa dùng cụm ride a horse; on horseback có nghĩa là đang ở trên lưng ngựa.', 'The brown horse gently took an apple from my hand.', NULL, 'Con ngựa màu nâu nhẹ nhàng nhận lấy quả táo từ tay tôi.', '{"wordId":"horse","ukIpa":"/hɔːs/","usIpa":"/hɔːrs/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"A large animal used for riding, racing, or pulling loads.","vi":"con ngựa"}],"examples":[{"en":"The brown horse gently took an apple from my hand.","vi":"Con ngựa màu nâu nhẹ nhàng nhận lấy quả táo từ tay tôi.","audioKind":"ex"},{"en":"Before motor vehicles became widespread, horses played a central role in farming and transporting goods.","vi":"Trước khi các phương tiện cơ giới trở nên phổ biến, ngựa đóng vai trò cốt lõi trong nông nghiệp và vận chuyển hàng hóa.","audioKind":"ex2"}],"collocations":[{"en":"ride a horse","vi":"cưỡi ngựa"},{"en":"horse riding","vi":"môn cưỡi ngựa"},{"en":"wild horse","vi":"ngựa hoang"},{"en":"horse racing","vi":"đua ngựa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cưỡi ngựa dùng cụm ride a horse; on horseback có nghĩa là đang ở trên lưng ngựa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_elephant', 'en-a1-7', 'elephant', '/ˈeləfənt/', 'A1', 'con voi', 'n.', NULL, NULL, 'Dạng số nhiều là ''elephants''; vòi voi dùng ''trunk'', không dùng ''nose''.', 'The elephant sprayed water over its back with its trunk.', NULL, 'Con voi dùng vòi phun nước lên lưng của nó.', '{"wordId":"elephant","ukIpa":"/ˈelɪfənt/","usIpa":"/ˈeləfənt/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"A very large animal with a long trunk and large ears.","vi":"con voi"}],"examples":[{"en":"The elephant sprayed water over its back with its trunk.","vi":"Con voi dùng vòi phun nước lên lưng của nó.","audioKind":"ex"},{"en":"Protecting elephant habitats requires cooperation between conservation organisations, local communities, and governments across national borders.","vi":"Việc bảo vệ môi trường sống của loài voi đòi hỏi sự hợp tác giữa các tổ chức bảo tồn, cộng đồng địa phương và các chính phủ vượt qua ranh giới quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"a herd of elephants","vi":"một đàn voi"},{"en":"an elephant''s trunk","vi":"vòi voi"},{"en":"elephant conservation","vi":"bảo tồn voi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là ''elephants''; vòi voi dùng ''trunk'', không dùng ''nose''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rainy', 'en-a1-7', 'rainy', '/ˈreɪni/', 'A1', 'có mưa; mưa nhiều; nhiều mưa', 'adj.', 'rain (n.), rain (v.), rainfall (n.)', 'Đồng nghĩa: wet · Trái nghĩa: dry', 'Rainy là tính từ; diễn tả trời đang mưa thì dùng It is raining.', 'We stayed indoors and baked bread on that rainy afternoon.', NULL, 'Chúng tôi ở trong nhà và nướng bánh mì vào buổi chiều mưa gió đó.', '{"wordId":"rainy","ukIpa":"/ˈreɪni/","usIpa":"/ˈreɪni/","cefr":"A1","topic":"nature","senses":[{"pos":"adj.","en":"Having rain, either now or frequently.","vi":"có mưa; mưa nhiều; nhiều mưa"}],"examples":[{"en":"We stayed indoors and baked bread on that rainy afternoon.","vi":"Chúng tôi ở trong nhà và nướng bánh mì vào buổi chiều mưa gió đó.","audioKind":"ex"},{"en":"In regions with a long rainy season, reliable drainage systems are essential for protecting homes and roads.","vi":"Ở những vùng có mùa mưa kéo dài, hệ thống thoát nước đáng tin cậy là điều tối quan trọng để bảo vệ nhà cửa và đường xá.","audioKind":"ex2"}],"collocations":[{"en":"rainy day","vi":"ngày mưa"},{"en":"rainy season","vi":"mùa mưa"},{"en":"rainy weather","vi":"thời tiết mưa phùn/mưa gió"}],"wordFamily":["rain (n.)","rain (v.)","rainfall (n.)"],"synonyms":["wet"],"antonyms":["dry"],"tipVi":"Rainy là tính từ; diễn tả trời đang mưa thì dùng It is raining.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_winter', 'en-a1-7', 'winter', '/ˈwɪntər/', 'A1', 'mùa đông; trú đông; qua đông', 'n.', 'wintry (adj.), overwinter (v.)', 'Trái nghĩa: summer', 'Nói chung chung trong mùa đông dùng in winter; nhắc đến một năm cụ thể dùng in the winter of…', 'We wear thick coats when winter brings cold winds.', NULL, 'Chúng tôi mặc áo khoác dày khi mùa đông mang theo những cơn gió lạnh.', '{"wordId":"winter","ukIpa":"/ˈwɪntə/","usIpa":"/ˈwɪntər/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"The coldest season, between autumn and spring.","vi":"mùa đông"},{"pos":"v.","en":"To spend the winter in a particular place.","vi":"trú đông; qua đông"}],"examples":[{"en":"We wear thick coats when winter brings cold winds.","vi":"Chúng tôi mặc áo khoác dày khi mùa đông mang theo những cơn gió lạnh.","audioKind":"ex"},{"en":"Warmer winters can disrupt natural ecosystems by changing the seasonal behaviour of plants and migrating animals.","vi":"Mùa đông ấm hơn có thể làm xáo trộn hệ sinh thái tự nhiên bằng cách thay đổi hành vi theo mùa của thực vật và động vật di cư.","audioKind":"ex2"}],"collocations":[{"en":"in winter","vi":"vào mùa đông"},{"en":"a harsh winter","vi":"mùa đông khắc nghiệt"},{"en":"winter months","vi":"các tháng mùa đông"},{"en":"winter clothing","vi":"trang phục mùa đông"}],"wordFamily":["wintry (adj.)","overwinter (v.)"],"synonyms":[],"antonyms":["summer"],"tipVi":"Nói chung chung trong mùa đông dùng in winter; nhắc đến một năm cụ thể dùng in the winter of…","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sun', 'en-a1-7', 'sun', '/sʌn/', 'A1', 'mặt trời; ánh nắng mặt trời; ánh sáng mặt trời; tắm nắng', 'n.', 'sunny (adj.), sunlight (n.), sunshine (n.), sunless (adj.)', NULL, 'Chỉ mặt trời thường dùng the sun; in the sun có nghĩa là ở dưới ánh nắng.', 'The sun appeared just as we reached the beach.', NULL, 'Mặt trời vừa ló dạng ngay khi chúng tôi ra đến bãi biển.', '{"wordId":"sun","ukIpa":"/sʌn/","usIpa":"/sʌn/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"The star that gives Earth light and heat.","vi":"mặt trời"},{"pos":"n.","en":"The light and warmth coming from the sun.","vi":"ánh nắng mặt trời; ánh sáng mặt trời"},{"pos":"v.","en":"Sit or lie where sunlight warms your body.","vi":"tắm nắng"}],"examples":[{"en":"The sun appeared just as we reached the beach.","vi":"Mặt trời vừa ló dạng ngay khi chúng tôi ra đến bãi biển.","audioKind":"ex"},{"en":"Energy from the sun can provide a renewable alternative to fossil fuels in regions with suitable conditions.","vi":"Năng lượng từ mặt trời có thể cung cấp nguồn năng lượng tái tạo thay thế cho nhiên liệu hóa thạch ở những vùng có điều kiện phù hợp.","audioKind":"ex2"}],"collocations":[{"en":"the rising sun","vi":"mặt trời mọc"},{"en":"in the sun","vi":"dưới ánh nắng"},{"en":"direct sun","vi":"ánh nắng trực tiếp"},{"en":"sun yourself","vi":"tắm nắng"}],"wordFamily":["sunny (adj.)","sunlight (n.)","sunshine (n.)","sunless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ mặt trời thường dùng the sun; in the sun có nghĩa là ở dưới ánh nắng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spring', 'en-a1-7', 'spring', '/sprɪŋ/', 'A1', 'mùa xuân; lò xo; suối nước', 'n.', 'springtime (n.)', NULL, 'Trước các mùa trong năm thường dùng in; nghĩa suối và lò xo đều là danh từ đếm được.', 'We plant flowers in the garden every spring.', NULL, 'Chúng tôi trồng hoa trong vườn vào mỗi mùa xuân.', '{"wordId":"spring","ukIpa":"/sprɪŋ/","usIpa":"/sprɪŋ/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"the season between winter and summer","vi":"mùa xuân"},{"pos":"n.","en":"a coiled piece of metal that stretches or compresses","vi":"lò xo"},{"pos":"n.","en":"a place where water flows naturally out of the ground","vi":"suối nước"}],"examples":[{"en":"We plant flowers in the garden every spring.","vi":"Chúng tôi trồng hoa trong vườn vào mỗi mùa xuân.","audioKind":"ex"},{"en":"Warmer temperatures in spring can cause plants to flower earlier, affecting insects that depend on them.","vi":"Nhiệt độ ấm hơn vào mùa xuân có thể làm cây cối nở hoa sớm hơn, ảnh hưởng đến các loài côn trùng phụ thuộc vào chúng.","audioKind":"ex2"}],"collocations":[{"en":"in spring","vi":"vào mùa xuân"},{"en":"early spring","vi":"đầu xuân"},{"en":"a natural spring","vi":"suối tự nhiên"},{"en":"a coil spring","vi":"lò xo cuộn"}],"wordFamily":["springtime (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trước các mùa trong năm thường dùng in; nghĩa suối và lò xo đều là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pig', 'en-a1-7', 'pig', '/pɪɡ/', 'A1', 'con lợn; con heo', 'n.', 'piglet (n.)', NULL, 'pig chỉ con vật; thịt lợn dùng làm thức ăn thường dùng từ pork.', 'A pink pig was sleeping beside the wooden fence.', NULL, 'Một chú lợn màu hồng đang ngủ bên cạnh hàng rào gỗ.', '{"wordId":"pig","ukIpa":"/pɪɡ/","usIpa":"/pɪɡ/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"A farm animal with a broad snout and short legs.","vi":"con lợn; con heo"}],"examples":[{"en":"A pink pig was sleeping beside the wooden fence.","vi":"Một chú lợn màu hồng đang ngủ bên cạnh hàng rào gỗ.","audioKind":"ex"},{"en":"Farmers can improve animal welfare by giving pigs enough space to move freely and explore.","vi":"Nông dân có thể cải thiện phúc lợi động vật bằng cách cho lợn đủ không gian để tự do di chuyển và khám phá.","audioKind":"ex2"}],"collocations":[{"en":"pig farm","vi":"trang trại nuôi lợn"},{"en":"raise pigs","vi":"nuôi lợn"},{"en":"wild pig","vi":"lợn rừng"}],"wordFamily":["piglet (n.)"],"synonyms":[],"antonyms":[],"tipVi":"pig chỉ con vật; thịt lợn dùng làm thức ăn thường dùng từ pork.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_animal', 'en-a1-7', 'animal', '/ˈænɪməl/', 'A1', 'động vật; thuộc động vật', 'n.', NULL, 'Đồng nghĩa: creature', 'Animal không chỉ chỉ thú có vú mà chim, cá và côn trùng cũng thuộc về động vật.', 'My sister loves watching animals at the local farm.', NULL, 'Em gái tôi rất thích ngắm nhìn các loài động vật ở trang trại địa phương.', '{"wordId":"animal","ukIpa":"/ˈænɪməl/","usIpa":"/ˈænɪməl/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"a living creature that feeds on plants or other creatures","vi":"động vật"},{"pos":"adj.","en":"relating to animals rather than plants","vi":"thuộc động vật"}],"examples":[{"en":"My sister loves watching animals at the local farm.","vi":"Em gái tôi rất thích ngắm nhìn các loài động vật ở trang trại địa phương.","audioKind":"ex"},{"en":"Protecting animal habitats is essential because biodiversity supports stable ecosystems and benefits human wellbeing.","vi":"Bảo vệ môi trường sống của động vật là điều cốt yếu vì đa dạng sinh học giúp duy trì hệ sinh thái ổn định và mang lại lợi ích cho hạnh phúc con người.","audioKind":"ex2"}],"collocations":[{"en":"wild animal","vi":"động vật hoang dã"},{"en":"animal welfare","vi":"phúc lợi động vật"},{"en":"animal behaviour","vi":"hành vi động vật"},{"en":"animal habitat","vi":"môi trường sống của động vật"}],"wordFamily":[],"synonyms":["creature"],"antonyms":[],"tipVi":"Animal không chỉ chỉ thú có vú mà chim, cá và côn trùng cũng thuộc về động vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tiger', 'en-a1-7', 'tiger', '/ˈtaɪɡər/', 'A1', 'con hổ', 'n.', NULL, NULL, 'Là danh từ đếm được; một con hổ dùng "a tiger".', 'The tiger rested in the shade beside a pool.', NULL, 'Con hổ nghỉ ngơi trong bóng râm cạnh một vũng nước.', '{"wordId":"tiger","ukIpa":"/ˈtaɪɡə/","usIpa":"/ˈtaɪɡər/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"A large wild cat with dark stripes on orange fur","vi":"con hổ"}],"examples":[{"en":"The tiger rested in the shade beside a pool.","vi":"Con hổ nghỉ ngơi trong bóng râm cạnh một vũng nước.","audioKind":"ex"},{"en":"Protecting tiger habitats also helps conserve other species that share the same forest ecosystems.","vi":"Bảo vệ môi trường sống của hổ cũng đồng thời giúp bảo tồn các loài động vật khác cùng chung hệ sinh thái rừng.","audioKind":"ex2"}],"collocations":[{"en":"a wild tiger","vi":"hổ hoang dã"},{"en":"tiger conservation","vi":"bảo tồn hổ"},{"en":"tiger habitat","vi":"môi trường sống của hổ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ đếm được; một con hổ dùng \"a tiger\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_star', 'en-a1-7', 'star', '/stɑːr/', 'A1', 'ngôi sao; vì sao; ngôi sao (người nổi tiếng); danh nhân; đóng vai chính; do... đóng vai chính', 'n.', 'starry (adj.), stardom (n.), starlight (n.)', 'Đồng nghĩa: celebrity', 'star in có nghĩa là đóng vai chính; thể quá khứ là starred, thể tiếp diễn là starring.', 'We watched the stars from our tent beside the lake.', NULL, 'Chúng tôi ngắm nhìn các vì sao từ chiếc lều cạnh hồ nước.', '{"wordId":"star","ukIpa":"/stɑː/","usIpa":"/stɑːr/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"a huge ball of hot gas shining in space","vi":"ngôi sao; vì sao"},{"pos":"n.","en":"a famous or exceptionally successful performer or other person","vi":"ngôi sao (người nổi tiếng); danh nhân"},{"pos":"v.","en":"to play a leading role or feature someone doing so","vi":"đóng vai chính; do... đóng vai chính"}],"examples":[{"en":"We watched the stars from our tent beside the lake.","vi":"Chúng tôi ngắm nhìn các vì sao từ chiếc lều cạnh hồ nước.","audioKind":"ex"},{"en":"Light pollution prevents many urban residents from seeing stars, reducing their connection with the natural night sky.","vi":"Ô nhiễm ánh sáng ngăn cản nhiều cư dân thành thị ngắm nhìn các vì sao, làm giảm sự kết nối của họ với bầu trời đêm tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"a bright star","vi":"một ngôi sao sáng"},{"en":"a film star","vi":"ngôi sao điện ảnh"},{"en":"a rising star","vi":"ngôi sao đang lên"},{"en":"star in a film","vi":"đóng vai chính trong phim"}],"wordFamily":["starry (adj.)","stardom (n.)","starlight (n.)"],"synonyms":["celebrity"],"antonyms":[],"tipVi":"star in có nghĩa là đóng vai chính; thể quá khứ là starred, thể tiếp diễn là starring.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sky', 'en-a1-7', 'sky', '/skaɪ/', 'A1', 'bầu trời', 'n.', NULL, NULL, 'Thường dùng "the sky"; "skies" thường được dùng để miêu tả thời tiết hoặc bầu trời ở một nơi nào đó.', 'The sky turned orange as we walked home.', NULL, 'Bầu trời chuyển sang màu cam khi chúng tôi đi bộ về nhà.', '{"wordId":"sky","ukIpa":"/skaɪ/","usIpa":"/skaɪ/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"The space above the earth where clouds and stars appear.","vi":"bầu trời"}],"examples":[{"en":"The sky turned orange as we walked home.","vi":"Bầu trời chuyển sang màu cam khi chúng tôi đi bộ về nhà.","audioKind":"ex"},{"en":"Light pollution prevents many urban residents from seeing stars clearly in the night sky.","vi":"Ô nhiễm ánh sáng khiến nhiều cư dân đô thị không thể nhìn rõ các vì sao trên bầu trời đêm.","audioKind":"ex2"}],"collocations":[{"en":"clear sky","vi":"bầu trời quang đãng"},{"en":"night sky","vi":"bầu trời đêm"},{"en":"blue sky","vi":"bầu trời xanh"},{"en":"cloudy skies","vi":"bầu trời nhiều mây"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng \"the sky\"; \"skies\" thường được dùng để miêu tả thời tiết hoặc bầu trời ở một nơi nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flower', 'en-a1-7', 'flower', '/ˈflaʊər/', 'A1', 'hoa; bông hoa; nở hoa; ra hoa', 'n.', 'flowering (adj.), flowery (adj.)', 'Đồng nghĩa: bloom, blossom', '''flower'' vừa có thể làm danh từ (hoa) vừa có thể làm động từ (nở hoa).', 'She placed fresh flowers in a vase by the window.', NULL, 'Cô ấy cắm những bông hoa tươi vào chiếc bình bên cửa sổ.', '{"wordId":"flower","ukIpa":"/ˈflaʊə/","usIpa":"/ˈflaʊər/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"The often colourful part of a plant that produces seeds.","vi":"hoa; bông hoa"},{"pos":"v.","en":"To produce flowers.","vi":"nở hoa; ra hoa"}],"examples":[{"en":"She placed fresh flowers in a vase by the window.","vi":"Cô ấy cắm những bông hoa tươi vào chiếc bình bên cửa sổ.","audioKind":"ex"},{"en":"Planting native flowers in urban parks can support pollinating insects and improve local biodiversity.","vi":"Việc trồng các loài hoa bản địa trong công viên đô thị có thể hỗ trợ các loài côn trùng thụ phấn và cải thiện đa dạng sinh học địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a bunch of flowers","vi":"một bó hoa"},{"en":"cut flowers","vi":"hoa cắt cành"},{"en":"in flower","vi":"đang nở hoa"}],"wordFamily":["flowering (adj.)","flowery (adj.)"],"synonyms":["bloom","blossom"],"antonyms":[],"tipVi":"''flower'' vừa có thể làm danh từ (hoa) vừa có thể làm động từ (nở hoa).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cloudy', 'en-a1-7', 'cloudy', '/ˈklaʊdi/', 'A1', 'nhiều mây; u ám; đục; không trong suốt', 'adj.', 'cloud (n.), cloud (v.), cloudless (adj.), cloudiness (n.)', 'Đồng nghĩa: overcast · Trái nghĩa: clear', 'Vừa có thể dùng để miêu tả bầu trời nhiều mây, vừa có thể miêu tả chất lỏng bị đục.', 'It was cloudy, so we left our sunglasses at home.', NULL, 'Trời nhiều mây nên chúng tôi đã để kính râm ở nhà.', '{"wordId":"cloudy","ukIpa":"/ˈklaʊdi/","usIpa":"/ˈklaʊdi/","cefr":"A1","topic":"nature","senses":[{"pos":"adj.","en":"having many clouds in the sky","vi":"nhiều mây; u ám"},{"pos":"adj.","en":"not clear or transparent","vi":"đục; không trong suốt"}],"examples":[{"en":"It was cloudy, so we left our sunglasses at home.","vi":"Trời nhiều mây nên chúng tôi đã để kính râm ở nhà.","audioKind":"ex"},{"en":"Solar panels can still generate electricity on cloudy days, although their output is usually lower.","vi":"Các tấm pin mặt trời vẫn có thể tạo ra điện vào những ngày nhiều mây, mặc dù sản lượng thường thấp hơn.","audioKind":"ex2"}],"collocations":[{"en":"cloudy sky","vi":"bầu trời nhiều mây"},{"en":"cloudy weather","vi":"thời tiết nhiều mây"},{"en":"cloudy water","vi":"nước đục"}],"wordFamily":["cloud (n.)","cloud (v.)","cloudless (adj.)","cloudiness (n.)"],"synonyms":["overcast"],"antonyms":["clear"],"tipVi":"Vừa có thể dùng để miêu tả bầu trời nhiều mây, vừa có thể miêu tả chất lỏng bị đục.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hill', 'en-a1-7', 'hill', '/hɪl/', 'A1', 'đồi; ngọn đồi nhỏ', 'n.', 'hilly (adj.), hillside (n.), hilltop (n.)', NULL, 'Hill thường thấp hơn mountain, nhưng không có ranh giới chiều cao cố định.', 'We climbed the hill and watched the sunset.', NULL, 'Chúng tôi trèo lên ngọn đồi và ngắm hoàng hôn.', '{"wordId":"hill","ukIpa":"/hɪl/","usIpa":"/hɪl/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"A raised area of land, usually lower than a mountain.","vi":"đồi; ngọn đồi nhỏ"}],"examples":[{"en":"We climbed the hill and watched the sunset.","vi":"Chúng tôi trèo lên ngọn đồi và ngắm hoàng hôn.","audioKind":"ex"},{"en":"Building houses on steep hills can increase construction costs and expose residents to the risk of landslides.","vi":"Xây nhà trên những sườn đồi dốc có thể làm tăng chi phí xây dựng và khiến cư dân đối mặt với nguy cơ sạt lở đất.","audioKind":"ex2"}],"collocations":[{"en":"climb a hill","vi":"trèo đồi; leo đồi"},{"en":"rolling hills","vi":"những ngọn đồi nhấp nhô"},{"en":"a steep hill","vi":"một ngọn đồi dốc"}],"wordFamily":["hilly (adj.)","hillside (n.)","hilltop (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Hill thường thấp hơn mountain, nhưng không có ranh giới chiều cao cố định.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_beautiful', 'en-a1-7', 'beautiful', '/ˈbjuːtɪfl/', 'A1', 'đẹp; xinh đẹp; tuyệt vời', 'adj.', 'beauty (n.), beautifully (adv.), beautify (v.)', 'Đồng nghĩa: lovely, gorgeous · Trái nghĩa: ugly', 'Có thể dùng để bổ nghĩa cho cảnh vật, âm thanh v.v.; dạng so sánh hơn là more beautiful.', 'The garden looks beautiful after the spring rain.', NULL, 'Khu vườn trông thật đẹp sau trận mưa xuân.', '{"wordId":"beautiful","ukIpa":"/ˈbjuːtɪfl/","usIpa":"/ˈbjuːtɪfl/","cefr":"A1","topic":"nature","senses":[{"pos":"adj.","en":"Very pleasing to see, hear, or experience.","vi":"đẹp; xinh đẹp; tuyệt vời"}],"examples":[{"en":"The garden looks beautiful after the spring rain.","vi":"Khu vườn trông thật đẹp sau trận mưa xuân.","audioKind":"ex"},{"en":"Protecting beautiful natural landscapes can attract visitors while preserving valuable habitats for future generations.","vi":"Việc bảo vệ các cảnh quan thiên nhiên tuyệt đẹp có thể thu hút khách du lịch đồng thời gìn giữ các môi trường sống quý giá cho các thế hệ mai sau.","audioKind":"ex2"}],"collocations":[{"en":"beautiful scenery","vi":"cảnh quan tươi đẹp"},{"en":"a beautiful voice","vi":"giọng hát hay"},{"en":"a beautiful view","vi":"cảnh đẹp"}],"wordFamily":["beauty (n.)","beautifully (adv.)","beautify (v.)"],"synonyms":["lovely","gorgeous"],"antonyms":["ugly"],"tipVi":"Có thể dùng để bổ nghĩa cho cảnh vật, âm thanh v.v.; dạng so sánh hơn là more beautiful.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_summer', 'en-a1-7', 'summer', '/ˈsʌmər/', 'A1', 'mùa hè; mùa hạ', 'n.', 'summery (adj.), summertime (n.)', 'Trái nghĩa: winter', 'Phân chỉ mùa hè dùng in summer; tên các mùa thường viết thường.', 'We often eat outside during the long summer evenings.', NULL, 'Chúng tôi thường ăn ở ngoài trời vào những buổi tối mùa hè dài.', '{"wordId":"summer","ukIpa":"/ˈsʌmə/","usIpa":"/ˈsʌmər/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"The warmest season, between spring and autumn.","vi":"mùa hè; mùa hạ"}],"examples":[{"en":"We often eat outside during the long summer evenings.","vi":"Chúng tôi thường ăn ở ngoài trời vào những buổi tối mùa hè dài.","audioKind":"ex"},{"en":"Rising summer temperatures may increase demand for electricity as more households rely on air conditioning.","vi":"Nhiệt độ mùa hè tăng cao có thể làm tăng nhu cầu điện khi ngày càng nhiều hộ gia đình phụ thuộc vào điều hòa.","audioKind":"ex2"}],"collocations":[{"en":"in summer","vi":"vào mùa hè"},{"en":"summer holidays","vi":"kỳ nghỉ hè"},{"en":"summer heat","vi":"cái nóng mùa hè"},{"en":"summer camp","vi":"trại hè"}],"wordFamily":["summery (adj.)","summertime (n.)"],"synonyms":[],"antonyms":["winter"],"tipVi":"Phân chỉ mùa hè dùng in summer; tên các mùa thường viết thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fish', 'en-a1-7', 'fish', '/fɪʃ/', 'A1', 'con cá; thịt cá; câu cá; đánh cá', 'n.', 'fishing (n.), fishery (n.)', NULL, 'Chỉ nhiều con cá thường vẫn dùng fish; thịt cá là danh từ không đếm được.', 'We watched small fish swimming under the wooden bridge.', NULL, 'Chúng tôi ngắm những chú cá nhỏ bơi lội dưới cây cầu gỗ.', '{"wordId":"fish","ukIpa":"/fɪʃ/","usIpa":"/fɪʃ/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"an animal living in water with fins; its edible flesh","vi":"con cá; thịt cá"},{"pos":"v.","en":"to try to catch fish","vi":"câu cá; đánh cá"}],"examples":[{"en":"We watched small fish swimming under the wooden bridge.","vi":"Chúng tôi ngắm những chú cá nhỏ bơi lội dưới cây cầu gỗ.","audioKind":"ex"},{"en":"Eating locally caught fish can support coastal communities, provided that fishing practices protect marine ecosystems.","vi":"Việc ăn cá đánh bắt tại địa phương có thể hỗ trợ các cộng đồng ven biển, với điều kiện các hoạt động đánh bắt bảo vệ được hệ sinh thái biển.","audioKind":"ex2"}],"collocations":[{"en":"fresh fish","vi":"cá tươi"},{"en":"go fishing","vi":"đi câu cá"},{"en":"fish stocks","vi":"nguồn lợi thủy sản"}],"wordFamily":["fishing (n.)","fishery (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ nhiều con cá thường vẫn dùng fish; thịt cá là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sheep', 'en-a1-7', 'sheep', '/ʃiːp/', 'A1', 'con cừu; cừu', 'n.', NULL, NULL, 'sheep có hình thức số ít và số nhiều giống nhau; dê là goat.', 'Several sheep were resting under a tree near the farm.', NULL, 'Vài con cừu đang nghỉ ngơi dưới gốc cây gần trang trại.', '{"wordId":"sheep","ukIpa":"/ʃiːp/","usIpa":"/ʃiːp/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"a farm animal kept for its wool, meat or milk","vi":"con cừu; cừu"}],"examples":[{"en":"Several sheep were resting under a tree near the farm.","vi":"Vài con cừu đang nghỉ ngơi dưới gốc cây gần trang trại.","audioKind":"ex"},{"en":"Keeping too many sheep on fragile grasslands can damage vegetation and increase the risk of soil erosion.","vi":"Nuôi quá nhiều cừu trên các đồng cỏ mỏng manh có thể tàn phá thảm thực vật và làm tăng nguy cơ xói mòn đất.","audioKind":"ex2"}],"collocations":[{"en":"a flock of sheep","vi":"một bầy cừu"},{"en":"raise sheep","vi":"nuôi cừu"},{"en":"shear sheep","vi":"xén lông cừu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"sheep có hình thức số ít và số nhiều giống nhau; dê là goat.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rabbit', 'en-a1-7', 'rabbit', '/ˈræbɪt/', 'A1', 'con thỏ', 'n.', NULL, NULL, 'rabbit dùng chung cho các loài thỏ; trong khi hare thường chỉ thỏ rừng có tai và chân dài hơn.', 'A white rabbit hopped across the grass towards us.', NULL, 'Một chú thỏ trắng vừa nhảy tưng tưng qua bãi cỏ hướng về phía chúng tôi.', '{"wordId":"rabbit","ukIpa":"/ˈræbɪt/","usIpa":"/ˈræbɪt/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"a small animal with long ears, soft fur, and strong back legs","vi":"con thỏ"}],"examples":[{"en":"A white rabbit hopped across the grass towards us.","vi":"Một chú thỏ trắng vừa nhảy tưng tưng qua bãi cỏ hướng về phía chúng tôi.","audioKind":"ex"},{"en":"Introducing rabbits into new environments can damage native vegetation and disrupt the balance of local ecosystems.","vi":"Việc đưa thỏ vào những môi trường sống mới có thể gây tổn hại cho thảm thực vật bản địa và phá vỡ sự cân bằng của các hệ sinh thái địa phương.","audioKind":"ex2"}],"collocations":[{"en":"pet rabbit","vi":"thỏ cảnh"},{"en":"wild rabbit","vi":"thỏ rừng"},{"en":"rabbit hole","vi":"hang thỏ; tình huống phức tạp khó lường"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"rabbit dùng chung cho các loài thỏ; trong khi hare thường chỉ thỏ rừng có tai và chân dài hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_7_1', 'en-a1-7', 'Cách dùng “sky” (n.) — bầu trời', 'clear sky  ·  night sky  ·  blue sky', 'Thường dùng "the sky"; "skies" thường được dùng để miêu tả thời tiết hoặc bầu trời ở một nơi nào đó.', NULL, '[{"hanzi":"The sky turned orange as we walked home.","pinyin":"","meaning":"Bầu trời chuyển sang màu cam khi chúng tôi đi bộ về nhà."},{"hanzi":"Light pollution prevents many urban residents from seeing stars clearly in the night sky.","pinyin":"","meaning":"Ô nhiễm ánh sáng khiến nhiều cư dân đô thị không thể nhìn rõ các vì sao trên bầu trời đêm."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_7_2', 'en-a1-7', 'Cách dùng “winter” (n.) — mùa đông', 'in winter  ·  a harsh winter  ·  winter months', 'Nói chung chung trong mùa đông dùng in winter; nhắc đến một năm cụ thể dùng in the winter of…', 'Họ từ (Word Family): wintry (adj.), overwinter (v.) | Trái nghĩa: summer', '[{"hanzi":"We wear thick coats when winter brings cold winds.","pinyin":"","meaning":"Chúng tôi mặc áo khoác dày khi mùa đông mang theo những cơn gió lạnh."},{"hanzi":"Warmer winters can disrupt natural ecosystems by changing the seasonal behaviour of plants and migrating animals.","pinyin":"","meaning":"Mùa đông ấm hơn có thể làm xáo trộn hệ sinh thái tự nhiên bằng cách thay đổi hành vi theo mùa của thực vật và động vật di cư."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_7_3', 'en-a1-7', 'Cách dùng “rabbit” (n.) — con thỏ', 'pet rabbit  ·  wild rabbit  ·  rabbit hole', 'rabbit dùng chung cho các loài thỏ; trong khi hare thường chỉ thỏ rừng có tai và chân dài hơn.', NULL, '[{"hanzi":"A white rabbit hopped across the grass towards us.","pinyin":"","meaning":"Một chú thỏ trắng vừa nhảy tưng tưng qua bãi cỏ hướng về phía chúng tôi."},{"hanzi":"Introducing rabbits into new environments can damage native vegetation and disrupt the balance of local ecosystems.","pinyin":"","meaning":"Việc đưa thỏ vào những môi trường sống mới có thể gây tổn hại cho thảm thực vật bản địa và phá vỡ sự cân bằng của các hệ sinh thái địa phương."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_7_4', 'en-a1-7', 'Cách dùng “beautiful” (adj.) — đẹp; xinh đẹp; tuyệt vời', 'beautiful scenery  ·  a beautiful voice  ·  a beautiful view', 'Có thể dùng để bổ nghĩa cho cảnh vật, âm thanh v.v.; dạng so sánh hơn là more beautiful.', 'Họ từ (Word Family): beauty (n.), beautifully (adv.), beautify (v.) | Đồng nghĩa: lovely, gorgeous | Trái nghĩa: ugly', '[{"hanzi":"The garden looks beautiful after the spring rain.","pinyin":"","meaning":"Khu vườn trông thật đẹp sau trận mưa xuân."},{"hanzi":"Protecting beautiful natural landscapes can attract visitors while preserving valuable habitats for future generations.","pinyin":"","meaning":"Việc bảo vệ các cảnh quan thiên nhiên tuyệt đẹp có thể thu hút khách du lịch đồng thời gìn giữ các môi trường sống quý giá cho các thế hệ mai sau."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_7_1', 'en-a1-7', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_7_1_1', 'ten_7_1', 'river', 'We watched ducks swimming across the river this morning.', 'We watched ducks swimming across the river this morning.', '/ˈrɪvər/', 'Sáng nay chúng tôi ngắm những chú vịt bơi qua sông.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_7_1_2', 'ten_7_1', 'horse', 'The brown horse gently took an apple from my hand.', 'The brown horse gently took an apple from my hand.', '/hɔːrs/', 'Con ngựa màu nâu nhẹ nhàng nhận lấy quả táo từ tay tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_7_1_3', 'ten_7_1', 'elephant', 'The elephant sprayed water over its back with its trunk.', 'The elephant sprayed water over its back with its trunk.', '/ˈeləfənt/', 'Con voi dùng vòi phun nước lên lưng của nó.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_7_1_4', 'ten_7_1', 'rainy', 'We stayed indoors and baked bread on that rainy afternoon.', 'We stayed indoors and baked bread on that rainy afternoon.', '/ˈreɪni/', 'Chúng tôi ở trong nhà và nướng bánh mì vào buổi chiều mưa gió đó.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_7_1_5', 'ten_7_1', 'winter', 'We wear thick coats when winter brings cold winds.', 'We wear thick coats when winter brings cold winds.', '/ˈwɪntər/', 'Chúng tôi mặc áo khoác dày khi mùa đông mang theo những cơn gió lạnh.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_7_1_6', 'ten_7_1', 'sun', 'The sun appeared just as we reached the beach.', 'The sun appeared just as we reached the beach.', '/sʌn/', 'Mặt trời vừa ló dạng ngay khi chúng tôi ra đến bãi biển.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_7_1_7', 'ten_7_1', 'spring', 'We plant flowers in the garden every spring.', 'We plant flowers in the garden every spring.', '/sprɪŋ/', 'Chúng tôi trồng hoa trong vườn vào mỗi mùa xuân.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_7_1_8', 'ten_7_1', 'pig', 'A pink pig was sleeping beside the wooden fence.', 'A pink pig was sleeping beside the wooden fence.', '/pɪɡ/', 'Một chú lợn màu hồng đang ngủ bên cạnh hàng rào gỗ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_7_1_1', 'en-a1-7', 'ten_7_1', 'listening', 'listening', 'We watched ducks swimming across the river this morning.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Mặt trời vừa ló dạng ngay khi chúng tôi ra đến bãi biển.","Một chú lợn màu hồng đang ngủ bên cạnh hàng rào gỗ.","Sáng nay chúng tôi ngắm những chú vịt bơi qua sông.","Chúng tôi mặc áo khoác dày khi mùa đông mang theo những cơn gió lạnh."]'::jsonb, 2, 'We watched ducks swimming across the river this morning. → Sáng nay chúng tôi ngắm những chú vịt bơi qua sông.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_7_1_2', 'en-a1-7', 'ten_7_1', 'listening', 'listening', 'The brown horse gently took an apple from my hand.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi mặc áo khoác dày khi mùa đông mang theo những cơn gió lạnh.","Con ngựa màu nâu nhẹ nhàng nhận lấy quả táo từ tay tôi.","Sáng nay chúng tôi ngắm những chú vịt bơi qua sông.","Con voi dùng vòi phun nước lên lưng của nó."]'::jsonb, 1, 'The brown horse gently took an apple from my hand. → Con ngựa màu nâu nhẹ nhàng nhận lấy quả táo từ tay tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_7_1_3', 'en-a1-7', 'ten_7_1', 'listening', 'listening', 'The elephant sprayed water over its back with its trunk.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi mặc áo khoác dày khi mùa đông mang theo những cơn gió lạnh.","Con ngựa màu nâu nhẹ nhàng nhận lấy quả táo từ tay tôi.","Con voi dùng vòi phun nước lên lưng của nó.","Mặt trời vừa ló dạng ngay khi chúng tôi ra đến bãi biển."]'::jsonb, 2, 'The elephant sprayed water over its back with its trunk. → Con voi dùng vòi phun nước lên lưng của nó.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_7_2', 'en-a1-7', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_7_2_1', 'ten_7_2', 'river', 'Protecting river ecosystems requires cooperation between farming communities, local industries, and environmental agencies.', 'Protecting river ecosystems requires cooperation between farming communities, local industries, and environmental agencies.', '/ˈrɪvər/', 'Việc bảo vệ các hệ sinh thái sông ngòi đòi hỏi sự hợp tác giữa các cộng đồng làm nông nghiệp, các khu công nghiệp địa phương và các cơ quan môi trường.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_7_2_2', 'ten_7_2', 'horse', 'Before motor vehicles became widespread, horses played a central role in farming and transporting goods.', 'Before motor vehicles became widespread, horses played a central role in farming and transporting goods.', '/hɔːrs/', 'Trước khi các phương tiện cơ giới trở nên phổ biến, ngựa đóng vai trò cốt lõi trong nông nghiệp và vận chuyển hàng hóa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_7_2_3', 'ten_7_2', 'elephant', 'Protecting elephant habitats requires cooperation between conservation organisations, local communities, and governments across national borders.', 'Protecting elephant habitats requires cooperation between conservation organisations, local communities, and governments across national borders.', '/ˈeləfənt/', 'Việc bảo vệ môi trường sống của loài voi đòi hỏi sự hợp tác giữa các tổ chức bảo tồn, cộng đồng địa phương và các chính phủ vượt qua ranh giới quốc gia.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_7_2_4', 'ten_7_2', 'rainy', 'In regions with a long rainy season, reliable drainage systems are essential for protecting homes and roads.', 'In regions with a long rainy season, reliable drainage systems are essential for protecting homes and roads.', '/ˈreɪni/', 'Ở những vùng có mùa mưa kéo dài, hệ thống thoát nước đáng tin cậy là điều tối quan trọng để bảo vệ nhà cửa và đường xá.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_7_2_5', 'ten_7_2', 'winter', 'Warmer winters can disrupt natural ecosystems by changing the seasonal behaviour of plants and migrating animals.', 'Warmer winters can disrupt natural ecosystems by changing the seasonal behaviour of plants and migrating animals.', '/ˈwɪntər/', 'Mùa đông ấm hơn có thể làm xáo trộn hệ sinh thái tự nhiên bằng cách thay đổi hành vi theo mùa của thực vật và động vật di cư.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_7_2_6', 'ten_7_2', 'sun', 'Energy from the sun can provide a renewable alternative to fossil fuels in regions with suitable conditions.', 'Energy from the sun can provide a renewable alternative to fossil fuels in regions with suitable conditions.', '/sʌn/', 'Năng lượng từ mặt trời có thể cung cấp nguồn năng lượng tái tạo thay thế cho nhiên liệu hóa thạch ở những vùng có điều kiện phù hợp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
