INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_7_2_2', 'en-a1-7', 'ten_7_2', 'listening', 'listening', 'Before motor vehicles became widespread, horses played a central role in farming and transporting goods.', NULL, 'Trong câu vừa nghe, từ “horse” mang nghĩa nào sau đây?', '["tuyệt vời; kỳ diệu","thực vật; cây cối","trẻ; trẻ tuổi; non trẻ","con ngựa"]'::jsonb, 3, '“horse” (/hɔːrs/): con ngựa. Câu đầy đủ: Before motor vehicles became widespread, horses played a central role in farming and transporting goods.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
