INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_7_2', 'en-a1-7', NULL, 'comprehensive_test', 'listening', 'The brown horse gently took an apple from my hand.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi trèo lên ngọn đồi và ngắm hoàng hôn.","Vài con cừu đang nghỉ ngơi dưới gốc cây gần trang trại.","Con ngựa màu nâu nhẹ nhàng nhận lấy quả táo từ tay tôi.","Chúng tôi ngắm những chú cá nhỏ bơi lội dưới cây cầu gỗ."]'::jsonb, 2, 'The brown horse gently took an apple from my hand. → Con ngựa màu nâu nhẹ nhàng nhận lấy quả táo từ tay tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_7_3', 'en-a1-7', NULL, 'comprehensive_test', 'listening', 'elephant', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tháng mười","sữa","Ca-na-đa","con voi"]'::jsonb, 3, 'elephant (/ˈeləfənt/) → con voi', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_7_4', 'en-a1-7', NULL, 'comprehensive_test', 'listening', 'We stayed indoors and baked bread on that rainy afternoon.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một chú lợn màu hồng đang ngủ bên cạnh hàng rào gỗ.","Vài con cừu đang nghỉ ngơi dưới gốc cây gần trang trại.","Khu vườn trông thật đẹp sau trận mưa xuân.","Chúng tôi ở trong nhà và nướng bánh mì vào buổi chiều mưa gió đó."]'::jsonb, 3, 'We stayed indoors and baked bread on that rainy afternoon. → Chúng tôi ở trong nhà và nướng bánh mì vào buổi chiều mưa gió đó.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_7_5', 'en-a1-7', NULL, 'comprehensive_test', 'listening', 'winter', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phòng học, lớp học nơi học sinh được giảng dạy","mùa đông","đọc; đọc hiểu","mặc; đeo; đội; mang"]'::jsonb, 1, 'winter (/ˈwɪntər/) → mùa đông; trú đông; qua đông', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_7_6', 'en-a1-7', NULL, 'comprehensive_test', 'listening', 'The sun appeared just as we reached the beach.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy cắm những bông hoa tươi vào chiếc bình bên cửa sổ.","Mặt trời vừa ló dạng ngay khi chúng tôi ra đến bãi biển.","Trời nhiều mây nên chúng tôi đã để kính râm ở nhà.","Chúng tôi ngắm nhìn các vì sao từ chiếc lều cạnh hồ nước."]'::jsonb, 1, 'The sun appeared just as we reached the beach. → Mặt trời vừa ló dạng ngay khi chúng tôi ra đến bãi biển.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
