INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_7_8', 'en-a1-7', NULL, 'comprehensive_test', 'listening', 'A pink pig was sleeping beside the wooden fence.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một chú lợn màu hồng đang ngủ bên cạnh hàng rào gỗ.","Chúng tôi ngắm nhìn các vì sao từ chiếc lều cạnh hồ nước.","Chúng tôi mặc áo khoác dày khi mùa đông mang theo những cơn gió lạnh.","Trời nhiều mây nên chúng tôi đã để kính râm ở nhà."]'::jsonb, 0, 'A pink pig was sleeping beside the wooden fence. → Một chú lợn màu hồng đang ngủ bên cạnh hàng rào gỗ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_7_9', 'en-a1-7', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The coldest season, between autumn and spring.”?', '["tiger","winter","spring","rainy"]'::jsonb, 1, 'winter (/ˈwɪntər/) → mùa đông', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
