INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_7_18', 'en-a1-7', NULL, 'comprehensive_test', 'reading', NULL, 'Protecting river ecosystems requires cooperation between farming communities, local industries, and environmental agencies.', 'Dựa vào câu trên, từ “river” có nghĩa phù hợp nhất là gì?', '["làm đầy; lấp đầy; đổ đầy","nơi; địa điểm; chốn","kế hoạch, dự định về những việc sẽ làm trong tương lai","sông; dòng sông"]'::jsonb, 3, 'river: sông; dòng sông. Dịch cả câu: Việc bảo vệ các hệ sinh thái sông ngòi đòi hỏi sự hợp tác giữa các cộng đồng làm nông nghiệp, các khu công nghiệp địa phương và các cơ quan môi trường.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_7_19', 'en-a1-7', NULL, 'comprehensive_test', 'reading', NULL, 'Before motor vehicles became widespread, horses played a central role in farming and transporting goods.', 'Dựa vào câu trên, từ “horse” có nghĩa phù hợp nhất là gì?', '["câu chuyện; chuyện kể","con ngựa","một... nữa; khác","thú vị; hay; hấp dẫn"]'::jsonb, 1, 'horse: con ngựa. Dịch cả câu: Trước khi các phương tiện cơ giới trở nên phổ biến, ngựa đóng vai trò cốt lõi trong nông nghiệp và vận chuyển hàng hóa.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_7_20', 'en-a1-7', NULL, 'comprehensive_test', 'reading', NULL, 'Protecting elephant habitats requires cooperation between conservation organisations, local communities, and governments across national borders.', 'Dựa vào câu trên, từ “elephant” có nghĩa phù hợp nhất là gì?', '["con voi","ông nội; ông ngoại","khác; nữa","đường; đường ăn"]'::jsonb, 0, 'elephant: con voi. Dịch cả câu: Việc bảo vệ môi trường sống của loài voi đòi hỏi sự hợp tác giữa các tổ chức bảo tồn, cộng đồng địa phương và các chính phủ vượt qua ranh giới quốc gia.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_7_21', 'en-a1-7', NULL, 'comprehensive_test', 'reading', NULL, 'In regions with a long rainy season, reliable drainage systems are essential for protecting homes and roads.', 'Dựa vào câu trên, từ “rainy” có nghĩa phù hợp nhất là gì?', '["có mưa; mưa nhiều; nhiều mưa","sinh ra","rơi; ngã; giảm","kích cỡ; quy mô"]'::jsonb, 0, 'rainy: có mưa; mưa nhiều; nhiều mưa. Dịch cả câu: Ở những vùng có mùa mưa kéo dài, hệ thống thoát nước đáng tin cậy là điều tối quan trọng để bảo vệ nhà cửa và đường xá.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_7_22', 'en-a1-7', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “con cá; thịt cá”', '["hear","today","fish","sing"]'::jsonb, 2, 'con cá; thịt cá → fish (/fɪʃ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_7_23', 'en-a1-7', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “con cừu; cừu”', '["afraid","sheep","give","juice"]'::jsonb, 1, 'con cừu; cừu → sheep (/ʃiːp/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_7_24', 'en-a1-7', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “con thỏ”', '["tree","Tuesday","rabbit","activity"]'::jsonb, 2, 'con thỏ → rabbit (/ˈræbɪt/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-8', 'en', 'Bài 8: Thiên nhiên & Thời tiết (2) - CEFR A1', 'CEFR A1', 'A1 · Thiên nhiên', '20 từ vựng Tiếng Anh CEFR A1 chủ đề thiên nhiên & thời tiết kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1008, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sea', 'en-a1-8', 'sea', '/siː/', 'A1', 'biển; đại dương; một lượng lớn; một vùng bạt ngàn', 'n.', 'seaside (n.), seawater (n.), seagoing (adj.)', NULL, 'at sea chỉ việc ở trên biển hoặc lênh đênh ngoài khơi; by the sea chỉ vị trí ở gần bờ biển.', 'The children watched small boats sailing across the sea.', NULL, 'Bọn trẻ đứng ngắm những chiếc thuyền nhỏ đang giương buồm ra khơi.', '{"wordId":"sea","ukIpa":"/siː/","usIpa":"/siː/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"the large area of salt water covering much of Earth","vi":"biển; đại dương"},{"pos":"n.","en":"a large mass of similar things seen together","vi":"một lượng lớn; một vùng bạt ngàn"}],"examples":[{"en":"The children watched small boats sailing across the sea.","vi":"Bọn trẻ đứng ngắm những chiếc thuyền nhỏ đang giương buồm ra khơi.","audioKind":"ex"},{"en":"Plastic waste entering the sea threatens marine wildlife and can eventually affect human food supplies.","vi":"Rác thải nhựa trôi dạt ra biển đe dọa các loài sinh vật hoang dã dưới nước và cuối cùng có thể ảnh hưởng đến nguồn cung cấp thực phẩm của con người.","audioKind":"ex2"}],"collocations":[{"en":"by the sea","vi":"ở gần biển; bên bờ biển"},{"en":"at sea","vi":"ở ngoài khơi; đi biển"},{"en":"sea level","vi":"mực nước biển"},{"en":"a sea of faces","vi":"một biển người"}],"wordFamily":["seaside (n.)","seawater (n.)","seagoing (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"at sea chỉ việc ở trên biển hoặc lênh đênh ngoài khơi; by the sea chỉ vị trí ở gần bờ biển.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tree', 'en-a1-8', 'tree', '/triː/', 'A1', 'cây; cây gỗ', 'n.', NULL, NULL, 'tree chỉ cây cối; wood có thể chỉ gỗ, còn woods thường chỉ khu rừng nhỏ.', 'A small bird built its nest in our tree.', NULL, 'Một chú chim nhỏ đã làm tổ trên cây nhà chúng tôi.', '{"wordId":"tree","ukIpa":"/triː/","usIpa":"/triː/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"A tall plant with a wooden trunk and branches.","vi":"cây; cây gỗ"}],"examples":[{"en":"A small bird built its nest in our tree.","vi":"Một chú chim nhỏ đã làm tổ trên cây nhà chúng tôi.","audioKind":"ex"},{"en":"Planting trees in urban areas provides shade, improves air quality, and creates valuable habitats for wildlife.","vi":"Trồng cây ở khu vực đô thị giúp tạo bóng mát, cải thiện chất lượng không khí và tạo ra môi trường sống quý giá cho động vật hoang dã.","audioKind":"ex2"}],"collocations":[{"en":"plant a tree","vi":"trồng cây"},{"en":"climb a tree","vi":"trèo cây"},{"en":"tree trunk","vi":"thân cây"},{"en":"family tree","vi":"sơ đồ gia phả"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"tree chỉ cây cối; wood có thể chỉ gỗ, còn woods thường chỉ khu rừng nhỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cow', 'en-a1-8', 'cow', '/kaʊ/', 'A1', 'bò cái; bò sữa; đe dọa; uy hiếp; khuất phục', 'n.', NULL, NULL, 'cow chỉ con bò cái trưởng thành; cattle là danh từ chỉ chung loài bò, không dùng hình thức số ít a cattle.', 'A brown cow stood quietly beside the farm gate.', NULL, 'Một con bò cái màu nâu đứng lặng lẽ bên cạnh cổng trang trại.', '{"wordId":"cow","ukIpa":"/kaʊ/","usIpa":"/kaʊ/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"an adult female bovine, often kept for milk","vi":"bò cái; bò sữa"},{"pos":"v.","en":"to frighten someone into obeying or giving up resistance","vi":"đe dọa; uy hiếp; khuất phục"}],"examples":[{"en":"A brown cow stood quietly beside the farm gate.","vi":"Một con bò cái màu nâu đứng lặng lẽ bên cạnh cổng trang trại.","audioKind":"ex"},{"en":"Improving the diet of dairy cows can increase milk production while supporting animal health.","vi":"Cải thiện chế độ ăn của bò sữa có thể làm tăng sản lượng sữa đồng thời hỗ trợ sức khỏe của vật nuôi.","audioKind":"ex2"}],"collocations":[{"en":"dairy cow","vi":"bò sữa"},{"en":"milk a cow","vi":"vắt sữa bò"},{"en":"be cowed into silence","vi":"bị dọa cho im bặt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"cow chỉ con bò cái trưởng thành; cattle là danh từ chỉ chung loài bò, không dùng hình thức số ít a cattle.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_die', 'en-a1-8', 'die', '/daɪ/', 'A1', 'chết; tàn lụi; ngừng hoạt động; lụi tàn dần; con xúc xắc', 'v.', 'death (n.), dead (adj.), dying (adj.)', 'Đồng nghĩa: pass away · Trái nghĩa: live, survive', 'die là động từ, dead là tính từ, và death là danh từ.', 'These plants will die if we forget to water them.', NULL, 'Những cái cây này sẽ chết nếu chúng ta quên tưới nước.', '{"wordId":"die","ukIpa":"/daɪ/","usIpa":"/daɪ/","cefr":"A1","topic":"nature","senses":[{"pos":"v.","en":"Stop living.","vi":"chết; tàn lụi"},{"pos":"v.","en":"Stop working or gradually become weaker and disappear.","vi":"ngừng hoạt động; lụi tàn dần"},{"pos":"n.","en":"A small cube with marked faces, thrown in games.","vi":"con xúc xắc"}],"examples":[{"en":"These plants will die if we forget to water them.","vi":"Những cái cây này sẽ chết nếu chúng ta quên tưới nước.","audioKind":"ex"},{"en":"Many marine animals die after swallowing plastic waste, highlighting the urgent need to reduce ocean pollution.","vi":"Nhiều loài động vật biển chết sau khi nuốt phải rác thải nhựa, điều này làm nổi bật sự cấp bách phải giảm thiểu ô nhiễm đại dương.","audioKind":"ex2"}],"collocations":[{"en":"die of cancer","vi":"chết vì ung thư"},{"en":"die out","vi":"tuyệt chủng; mất hút"},{"en":"die down","vi":"dịu đi; lắng xuống"},{"en":"die from injuries","vi":"chết vì chấn thương"}],"wordFamily":["death (n.)","dead (adj.)","dying (adj.)"],"synonyms":["pass away"],"antonyms":["live","survive"],"tipVi":"die là động từ, dead là tính từ, và death là danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_autumn', 'en-a1-8', 'autumn', '/ˈɔːtəm/', 'A1', 'mùa thu', 'n.', 'autumnal (adj.)', 'Đồng nghĩa: fall', 'Chữ "n" bị câm; tiếng Anh-Mỹ thường dùng "fall" để chỉ mùa thu.', 'We collect fallen leaves in the park every autumn.', NULL, 'Chúng tôi nhặt lá rụng trong công viên vào mỗi mùa thu.', '{"wordId":"autumn","ukIpa":"/ˈɔːtəm/","usIpa":"/ˈɔːtəm/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"The season between summer and winter","vi":"mùa thu"}],"examples":[{"en":"We collect fallen leaves in the park every autumn.","vi":"Chúng tôi nhặt lá rụng trong công viên vào mỗi mùa thu.","audioKind":"ex"},{"en":"Warmer autumn temperatures may delay leaf fall and affect the seasonal behaviour of local wildlife.","vi":"Nhiệt độ mùa thu ấm hơn có thể làm chậm quá trình rụng lá và ảnh hưởng đến tập tính theo mùa của động vật hoang dã địa phương.","audioKind":"ex2"}],"collocations":[{"en":"in autumn","vi":"vào mùa thu"},{"en":"autumn leaves","vi":"lá mùa thu"},{"en":"early autumn","vi":"đầu thu"}],"wordFamily":["autumnal (adj.)"],"synonyms":["fall"],"antonyms":[],"tipVi":"Chữ \"n\" bị câm; tiếng Anh-Mỹ thường dùng \"fall\" để chỉ mùa thu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cat', 'en-a1-8', 'cat', '/kæt/', 'A1', 'con mèo; động vật thuộc họ mèo', 'n.', NULL, 'Đồng nghĩa: feline', 'Big cats chỉ các loài thú lớn thuộc họ mèo như sư tử và hổ.', 'Our cat sleeps in a sunny spot by the window.', NULL, 'Con mèo nhà chúng tôi ngủ ở một góc đầy nắng bên cửa sổ.', '{"wordId":"cat","ukIpa":"/kæt/","usIpa":"/kæt/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"A small furry animal often kept as a pet.","vi":"con mèo"},{"pos":"n.","en":"An animal belonging to the same family as lions.","vi":"động vật thuộc họ mèo"}],"examples":[{"en":"Our cat sleeps in a sunny spot by the window.","vi":"Con mèo nhà chúng tôi ngủ ở một góc đầy nắng bên cửa sổ.","audioKind":"ex"},{"en":"Keeping pet cats indoors can help protect native birds, particularly in areas with vulnerable wildlife populations.","vi":"Nuôi mèo cảnh trong nhà có thể giúp bảo vệ các loài chim bản địa, đặc biệt là ở những khu vực có quần thể động vật hoang dã dễ bị tổn thương.","audioKind":"ex2"}],"collocations":[{"en":"a pet cat","vi":"mèo cưng"},{"en":"a stray cat","vi":"mèo hoang"},{"en":"big cats","vi":"họ mèo lớn"}],"wordFamily":[],"synonyms":["feline"],"antonyms":[],"tipVi":"Big cats chỉ các loài thú lớn thuộc họ mèo như sư tử và hổ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mouse', 'en-a1-8', 'mouse', '/maʊs/', 'A1', 'con chuột; chuột máy tính', 'n.', 'mousy (adj.)', NULL, 'Số nhiều của chuột là mice; số nhiều của chuột máy tính có thể dùng là mice hoặc mouses.', 'A tiny mouse slipped behind the cupboard before breakfast.', NULL, 'Một con chuột nhỏ đã lẻn ra phía sau tủ trước bữa sáng.', '{"wordId":"mouse","ukIpa":"/maʊs/","usIpa":"/maʊs/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"A small rodent with a pointed nose and long thin tail.","vi":"con chuột"},{"pos":"n.","en":"A handheld device for moving a pointer on a computer screen.","vi":"chuột máy tính"}],"examples":[{"en":"A tiny mouse slipped behind the cupboard before breakfast.","vi":"Một con chuột nhỏ đã lẻn ra phía sau tủ trước bữa sáng.","audioKind":"ex"},{"en":"Using a mouse for long periods may cause wrist discomfort, so office workers should take regular breaks.","vi":"Sử dụng chuột máy tính trong thời gian dài có thể gây khó chịu ở cổ tay, vì vậy nhân viên văn phòng nên nghỉ giải lao đều đặn.","audioKind":"ex2"}],"collocations":[{"en":"a field mouse","vi":"chuột đồng"},{"en":"a wireless mouse","vi":"chuột không dây"},{"en":"a mouse click","vi":"cú nhấp chuột"}],"wordFamily":["mousy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Số nhiều của chuột là mice; số nhiều của chuột máy tính có thể dùng là mice hoặc mouses.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_monkey', 'en-a1-8', 'monkey', '/ˈmʌŋki/', 'A1', 'con khỉ', 'n.', NULL, NULL, 'monkey thường có đuôi; ape chỉ loài vượn, thường không có đuôi.', 'A little monkey swung between branches above our heads.', NULL, 'Một chú khỉ nhỏ chuyền cành giữa các tán cây trên đầu chúng tôi.', '{"wordId":"monkey","ukIpa":"/ˈmʌŋki/","usIpa":"/ˈmʌŋki/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"A primate that usually has a tail and climbs trees.","vi":"con khỉ"}],"examples":[{"en":"A little monkey swung between branches above our heads.","vi":"Một chú khỉ nhỏ chuyền cành giữa các tán cây trên đầu chúng tôi.","audioKind":"ex"},{"en":"Protecting tropical forests helps preserve monkey populations and the complex ecosystems on which they depend.","vi":"Bảo vệ các khu rừng nhiệt đới giúp duy trì các quần thể khỉ và các hệ sinh thái phức tạp mà chúng phụ thuộc vào.","audioKind":"ex2"}],"collocations":[{"en":"a troop of monkeys","vi":"một bầy khỉ"},{"en":"wild monkeys","vi":"khỉ hoang dã"},{"en":"monkey around","vi":"làm trò quậy phá; đùa nghịch"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"monkey thường có đuôi; ape chỉ loài vượn, thường không có đuôi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sunny', 'en-a1-8', 'sunny', '/ˈsʌni/', 'A1', 'nắng; có nhiều ánh nắng; vui vẻ; lạc quan', 'adj.', 'sun (n.), sunshine (n.), sunless (adj.)', 'Đồng nghĩa: bright, sunlit · Trái nghĩa: cloudy, overcast', 'sunny nhấn mạnh có nhiều ánh nắng, không nhất thiết chỉ nhiệt độ cao.', 'We ate breakfast on the sunny balcony this morning.', NULL, 'Sáng nay chúng tôi ăn sáng ở ban công lộng gió và ngập tràn ánh nắng.', '{"wordId":"sunny","ukIpa":"/ˈsʌni/","usIpa":"/ˈsʌni/","cefr":"A1","topic":"nature","senses":[{"pos":"adj.","en":"having plenty of bright sunlight","vi":"nắng; có nhiều ánh nắng"},{"pos":"adj.","en":"cheerful and positive in character or mood","vi":"vui vẻ; lạc quan"}],"examples":[{"en":"We ate breakfast on the sunny balcony this morning.","vi":"Sáng nay chúng tôi ăn sáng ở ban công lộng gió và ngập tràn ánh nắng.","audioKind":"ex"},{"en":"Regions with sunny climates can generate substantial amounts of electricity through well-planned solar energy projects.","vi":"Các vùng có khí hậu nhiều nắng có thể tạo ra lượng điện năng đáng kể thông qua các dự án năng lượng mặt trời được quy hoạch tốt.","audioKind":"ex2"}],"collocations":[{"en":"sunny weather","vi":"thời tiết có nắng"},{"en":"sunny day","vi":"ngày nắng"},{"en":"sunny spot","vi":"nơi ngập tràn ánh nắng"},{"en":"sunny disposition","vi":"tính cách vui vẻ, lạc quan"}],"wordFamily":["sun (n.)","sunshine (n.)","sunless (adj.)"],"synonyms":["bright","sunlit"],"antonyms":["cloudy","overcast"],"tipVi":"sunny nhấn mạnh có nhiều ánh nắng, không nhất thiết chỉ nhiệt độ cao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_snow', 'en-a1-8', 'snow', '/snoʊ/', 'A1', 'tuyết; tuyết rơi', 'n.', 'snowy (adj.), snowfall (n.)', NULL, 'snow khi là danh từ thường không đếm được; nói trời đang đổ tuyết dùng it snows.', 'Fresh snow covered the garden when we woke up.', NULL, 'Tuyết mới phủ trắng khu vườn khi chúng tôi thức dậy.', '{"wordId":"snow","ukIpa":"/snəʊ/","usIpa":"/snoʊ/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"Soft white frozen flakes falling from clouds or covering the ground.","vi":"tuyết"},{"pos":"v.","en":"For snow to fall from the sky.","vi":"tuyết rơi"}],"examples":[{"en":"Fresh snow covered the garden when we woke up.","vi":"Tuyết mới phủ trắng khu vườn khi chúng tôi thức dậy.","audioKind":"ex"},{"en":"Heavy snow can disrupt public transport and prevent rural communities from accessing essential services.","vi":"Tuyết rơi dày đặc có thể làm gián đoạn giao thông công cộng và khiến các cộng đồng nông thôn không thể tiếp cận các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"heavy snow","vi":"tuyết lớn"},{"en":"fresh snow","vi":"tuyết mới rơi"},{"en":"snow heavily","vi":"tuyết rơi dày"}],"wordFamily":["snowy (adj.)","snowfall (n.)"],"synonyms":[],"antonyms":[],"tipVi":"snow khi là danh từ thường không đếm được; nói trời đang đổ tuyết dùng it snows.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plant', 'en-a1-8', 'plant', '/plænt/', 'A1', 'thực vật; cây cối; trồng; gieo trồng; nhà máy; xưởng công nghiệp', 'n.', 'planting (n.), planter (n.)', NULL, 'plant vừa có nghĩa là thực vật vừa là nhà máy; khi làm động từ thì mang nghĩa là trồng cây.', 'This little plant needs more sunlight and less water.', NULL, 'Cây nhỏ này cần nhiều ánh sáng mặt trời hơn và ít nước hơn.', '{"wordId":"plant","ukIpa":"/plɑːnt/","usIpa":"/plænt/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"a living thing that usually grows in soil and has leaves","vi":"thực vật; cây cối"},{"pos":"v.","en":"to put seeds or young plants into soil to grow","vi":"trồng; gieo trồng"},{"pos":"n.","en":"a factory or facility where industrial processes take place","vi":"nhà máy; xưởng công nghiệp"}],"examples":[{"en":"This little plant needs more sunlight and less water.","vi":"Cây nhỏ này cần nhiều ánh sáng mặt trời hơn và ít nước hơn.","audioKind":"ex"},{"en":"Local authorities should plant more trees to improve air quality and provide shade in crowded neighbourhoods.","vi":"Chính quyền địa phương nên trồng thêm cây xanh để cải thiện chất lượng không khí và tạo bóng râm ở những khu dân cư đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"water a plant","vi":"tưới cây"},{"en":"plant trees","vi":"trồng cây"},{"en":"power plant","vi":"nhà máy điện"},{"en":"manufacturing plant","vi":"nhà máy sản xuất"}],"wordFamily":["planting (n.)","planter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"plant vừa có nghĩa là thực vật vừa là nhà máy; khi làm động từ thì mang nghĩa là trồng cây.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grass', 'en-a1-8', 'grass', '/ɡræs/', 'A1', 'cỏ; thảm cỏ', 'n.', 'grassy (adj.), grassland (n.)', NULL, 'Thường là danh từ không đếm được; một ngọn cỏ dùng a blade of grass.', 'We spread a blanket on the grass beside the river.', NULL, 'Chúng tôi trải một tấm chăn lên bãi cỏ cạnh con sông.', '{"wordId":"grass","ukIpa":"/ɡrɑːs/","usIpa":"/ɡræs/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"A low plant with narrow green leaves covering the ground.","vi":"cỏ; thảm cỏ"}],"examples":[{"en":"We spread a blanket on the grass beside the river.","vi":"Chúng tôi trải một tấm chăn lên bãi cỏ cạnh con sông.","audioKind":"ex"},{"en":"Replacing natural grass with artificial surfaces can reduce habitats for insects and increase local temperatures.","vi":"Việc thay thế thảm cỏ tự nhiên bằng bề mặt nhân tạo có thể làm giảm môi trường sống của côn trùng và làm tăng nhiệt độ địa phương.","audioKind":"ex2"}],"collocations":[{"en":"cut the grass","vi":"cắt cỏ"},{"en":"a blade of grass","vi":"một ngọn cỏ"},{"en":"long grass","vi":"cỏ dài"},{"en":"wet grass","vi":"bãi cỏ ướt"}],"wordFamily":["grassy (adj.)","grassland (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; một ngọn cỏ dùng a blade of grass.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grow', 'en-a1-8', 'grow', '/ɡroʊ/', 'A1', 'lớn lên; phát triển; tăng trưởng; trồng trọt; trở nên; dần trở thành', 'v.', 'growth (n.), grower (n.), growing (adj.)', 'Trái nghĩa: shrink', 'Có dạng quá khứ là grew, quá khứ phân từ là grown; dùng chỉ sự biến đổi trạng thái thì theo sau là tính từ.', 'We grow fresh herbs in pots beside the kitchen window.', NULL, 'Chúng tôi trồng các loại rau thơm tươi trong chậu bên cửa sổ nhà bếp.', '{"wordId":"grow","ukIpa":"/ɡrəʊ/","usIpa":"/ɡroʊ/","cefr":"A1","topic":"nature","senses":[{"pos":"v.","en":"To become bigger or develop over time.","vi":"lớn lên; phát triển; tăng trưởng"},{"pos":"v.","en":"To raise plants for food or other purposes.","vi":"trồng trọt"},{"pos":"v.","en":"To gradually become different in condition or feeling.","vi":"trở nên; dần trở thành"}],"examples":[{"en":"We grow fresh herbs in pots beside the kitchen window.","vi":"Chúng tôi trồng các loại rau thơm tươi trong chậu bên cửa sổ nhà bếp.","audioKind":"ex"},{"en":"As cities grow, local authorities must invest in transport systems that serve expanding populations.","vi":"Khi các thành phố phát triển, chính quyền địa phương phải đầu tư vào các hệ thống giao thông phục vụ lượng dân cư ngày càng tăng.","audioKind":"ex2"}],"collocations":[{"en":"grow rapidly","vi":"phát triển nhanh chóng"},{"en":"grow vegetables","vi":"trồng rau"},{"en":"grow older","vi":"già đi"},{"en":"grow increasingly concerned","vi":"ngày càng trở nên lo lắng"}],"wordFamily":["growth (n.)","grower (n.)","growing (adj.)"],"synonyms":[],"antonyms":["shrink"],"tipVi":"Có dạng quá khứ là grew, quá khứ phân từ là grown; dùng chỉ sự biến đổi trạng thái thì theo sau là tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bird', 'en-a1-8', 'bird', '/bɝːd/', 'A1', 'chim', 'n.', 'birdwatcher (n.), birdwatching (n.)', NULL, 'Cụm từ chỉ đàn chim là "a flock of birds"; "bird" vốn là một danh từ đếm được.', 'A small bird built a nest above our window.', NULL, 'Một chú chim nhỏ đã làm tổ ngay phía trên cửa sổ nhà chúng tôi.', '{"wordId":"bird","ukIpa":"/bɜːd/","usIpa":"/bɝːd/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"an animal with feathers, wings, and a beak that lays eggs","vi":"chim"}],"examples":[{"en":"A small bird built a nest above our window.","vi":"Một chú chim nhỏ đã làm tổ ngay phía trên cửa sổ nhà chúng tôi.","audioKind":"ex"},{"en":"Protecting native bird species requires preserving their habitats and reducing pollution in both rural and urban areas.","vi":"Việc bảo vệ các loài chim bản địa đòi hỏi phải gìn giữ môi trường sống của chúng và giảm thiểu ô nhiễm ở cả khu vực nông thôn lẫn thành thị.","audioKind":"ex2"}],"collocations":[{"en":"a flock of birds","vi":"đàn chim"},{"en":"a migratory bird","vi":"chim di cư"},{"en":"bird watching","vi":"ngắm chim"},{"en":"a bird of prey","vi":"chim săn mồi"}],"wordFamily":["birdwatcher (n.)","birdwatching (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ chỉ đàn chim là \"a flock of birds\"; \"bird\" vốn là một danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ice', 'en-a1-8', 'ice', '/aɪs/', 'A1', 'băng; đá; phủ lớp đường kem lên bánh', 'n.', 'icy (adj.), icing (n.)', NULL, 'Ice khi chỉ băng thường không đếm được; một khối đá dùng an ice cube.', 'She dropped a few cubes of ice into her juice.', NULL, 'Cô ấy thả vài viên đá vào ly nước ép của mình.', '{"wordId":"ice","ukIpa":"/aɪs/","usIpa":"/aɪs/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"water that has frozen solid","vi":"băng; đá"},{"pos":"v.","en":"to cover a cake or biscuit with icing","vi":"phủ lớp đường kem lên bánh"}],"examples":[{"en":"She dropped a few cubes of ice into her juice.","vi":"Cô ấy thả vài viên đá vào ly nước ép của mình.","audioKind":"ex"},{"en":"The loss of polar ice threatens wildlife habitats and can accelerate warming by reducing the reflection of sunlight.","vi":"Sự suy giảm băng ở vùng cực đe dọa môi trường sống của động vật hoang dã và có thể đẩy nhanh tốc độ ấm lên bằng cách làm giảm khả năng phản xạ ánh sáng mặt trời.","audioKind":"ex2"}],"collocations":[{"en":"ice cube","vi":"viên đá"},{"en":"sea ice","vi":"băng biển"},{"en":"melt the ice","vi":"làm tan băng"},{"en":"ice a cake","vi":"phủ kem lên bánh"}],"wordFamily":["icy (adj.)","icing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Ice khi chỉ băng thường không đếm được; một khối đá dùng an ice cube.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mountain', 'en-a1-8', 'mountain', '/ˈmaʊntən/', 'A1', 'núi; ngọn núi; một lượng rất lớn; hàng núi', 'n.', 'mountainous (adj.), mountaineer (n.), mountaineering (n.)', NULL, 'Một ngọn núi dùng "mountain"; dãy núi thường dùng "mountain range".', 'Snow covered the mountain even in the middle of summer.', NULL, 'Tuyết phủ trắng ngọn núi ngay cả vào giữa mùa hè.', '{"wordId":"mountain","ukIpa":"/ˈmaʊntɪn/","usIpa":"/ˈmaʊntən/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"a very high area of land with steep sides","vi":"núi; ngọn núi"},{"pos":"n.","en":"a very large amount of something","vi":"một lượng rất lớn; hàng núi"}],"examples":[{"en":"Snow covered the mountain even in the middle of summer.","vi":"Tuyết phủ trắng ngọn núi ngay cả vào giữa mùa hè.","audioKind":"ex"},{"en":"Mountain communities often face higher transport costs because steep terrain makes road construction more difficult.","vi":"Các cộng đồng miền núi thường phải đối mặt với chi phí vận chuyển cao hơn vì địa hình dốc khiến việc xây dựng đường sá trở nên khó khăn hơn.","audioKind":"ex2"}],"collocations":[{"en":"mountain range","vi":"dãy núi"},{"en":"mountain peak","vi":"đỉnh núi"},{"en":"climb a mountain","vi":"leo núi"},{"en":"a mountain of work","vi":"một núi công việc"}],"wordFamily":["mountainous (adj.)","mountaineer (n.)","mountaineering (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Một ngọn núi dùng \"mountain\"; dãy núi thường dùng \"mountain range\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dog', 'en-a1-8', 'dog', '/dɔːɡ/', 'A1', 'n. chó; con chó; v. đeo bám; gây khó khăn lâu dài', 'n.', NULL, NULL, 'Động từ thường gặp dạng bị động be dogged by, diễn tả việc bị đeo bám hoặc quấy rầy lâu dài.', 'Our dog waits by the door every afternoon.', NULL, 'Chú chó nhà chúng tôi ngồi đợi bên cửa vào mỗi buổi chiều.', '{"wordId":"dog","ukIpa":"/dɒɡ/","usIpa":"/dɔːɡ/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"An animal often kept as a pet or trained for work.","vi":"n. chó; con chó"},{"pos":"v.","en":"To cause persistent problems for someone or something.","vi":"v. đeo bám; gây khó khăn lâu dài"}],"examples":[{"en":"Our dog waits by the door every afternoon.","vi":"Chú chó nhà chúng tôi ngồi đợi bên cửa vào mỗi buổi chiều.","audioKind":"ex"},{"en":"Training a guide dog requires considerable time, but it can greatly improve someone''s independence.","vi":"Việc huấn luyện một chú chó dẫn đường đòi hỏi rất nhiều thời gian, nhưng nó có thể cải thiện đáng kể tính tự lập của người sử dụng.","audioKind":"ex2"}],"collocations":[{"en":"walk the dog","vi":"dắt chó đi dạo"},{"en":"a guide dog","vi":"chó dẫn đường"},{"en":"a stray dog","vi":"chó hoang"},{"en":"be dogged by problems","vi":"bị rắc rối đeo bám"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Động từ thường gặp dạng bị động be dogged by, diễn tả việc bị đeo bám hoặc quấy rầy lâu dài.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lion', 'en-a1-8', 'lion', '/ˈlaɪən/', 'A1', 'sư tử', 'n.', 'lioness (n.)', NULL, 'Một bầy sư tử dùng cụm a pride of lions; sư tử cái gọi là lioness.', 'The lion rested beneath a tree in the shade.', NULL, 'Con sư tử nghỉ ngơi dưới bóng râm của một cái cây.', '{"wordId":"lion","ukIpa":"/ˈlaɪən/","usIpa":"/ˈlaɪən/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"A large wild cat, whose males usually have thick neck hair.","vi":"sư tử"}],"examples":[{"en":"The lion rested beneath a tree in the shade.","vi":"Con sư tử nghỉ ngơi dưới bóng râm của một cái cây.","audioKind":"ex"},{"en":"Protecting lions requires large habitats where they can hunt naturally without coming into conflict with farmers.","vi":"Việc bảo vệ loài sư tử đòi hỏi những môi trường sống rộng lớn nơi chúng có thể săn mồi tự nhiên mà không xảy ra xung đột với nông dân.","audioKind":"ex2"}],"collocations":[{"en":"a pride of lions","vi":"một bầy sư tử"},{"en":"a lion''s mane","vi":"bờm sư tử"},{"en":"the lion''s share","vi":"phần lớn nhất; phần ngon nghẻ nhất"}],"wordFamily":["lioness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Một bầy sư tử dùng cụm a pride of lions; sư tử cái gọi là lioness.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_giraffe', 'en-a1-8', 'giraffe', '/dʒəˈræf/', 'A1', 'hươu cao cổ', 'n.', NULL, NULL, 'Trọng âm rơi vào âm tiết thứ hai, số nhiều thường thêm -s.', 'The giraffe stretched its neck to reach the highest leaves.', NULL, 'Con hươu cao cổ vươn chiếc cổ dài để với tới những chiếc lá ở trên cao nhất.', '{"wordId":"giraffe","ukIpa":"/dʒəˈrɑːf/","usIpa":"/dʒəˈræf/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"A tall African animal with a long neck and spotted coat","vi":"hươu cao cổ"}],"examples":[{"en":"The giraffe stretched its neck to reach the highest leaves.","vi":"Con hươu cao cổ vươn chiếc cổ dài để với tới những chiếc lá ở trên cao nhất.","audioKind":"ex"},{"en":"Protecting natural habitats is essential for maintaining healthy giraffe populations and preserving biodiversity in African grasslands.","vi":"Bảo vệ môi trường sống tự nhiên là điều cần thiết để duy trì số lượng hươu cao cổ khỏe mạnh và bảo tồn đa dạng sinh học ở các đồng cỏ châu Phi.","audioKind":"ex2"}],"collocations":[{"en":"a herd of giraffes","vi":"một đàn hươu cao cổ"},{"en":"a giraffe calf","vi":"hươu cao cổ con"},{"en":"giraffe conservation","vi":"bảo tồn hươu cao cổ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trọng âm rơi vào âm tiết thứ hai, số nhiều thường thêm -s.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rain', 'en-a1-8', 'rain', '/reɪn/', 'A1', 'mưa; nước mưa; mưa', 'n.', 'rainy (adj.), rainfall (n.)', NULL, 'rain đóng vai trò danh từ thường không đếm được; khi nói trời đang mưa dùng cấu trúc It rains.', 'Heavy rain kept us inside for the whole afternoon.', NULL, 'Cơn mưa lớn đã khiến chúng tôi ở trong nhà suốt cả buổi chiều.', '{"wordId":"rain","ukIpa":"/reɪn/","usIpa":"/reɪn/","cefr":"A1","topic":"nature","senses":[{"pos":"n.","en":"Water that falls from clouds in drops","vi":"mưa; nước mưa"},{"pos":"v.","en":"For water drops to fall from clouds","vi":"mưa"}],"examples":[{"en":"Heavy rain kept us inside for the whole afternoon.","vi":"Cơn mưa lớn đã khiến chúng tôi ở trong nhà suốt cả buổi chiều.","audioKind":"ex"},{"en":"Farmers increasingly depend on stored water because seasonal rain has become less predictable in many regions.","vi":"Nông dân ngày càng phụ thuộc vào nguồn nước dự trữ vì lượng mưa theo mùa ở nhiều vùng trở nên khó dự đoán hơn.","audioKind":"ex2"}],"collocations":[{"en":"heavy rain","vi":"mưa lớn"},{"en":"pouring rain","vi":"mưa xối xả"},{"en":"rain heavily","vi":"mưa to"},{"en":"a chance of rain","vi":"khả năng có mưa"}],"wordFamily":["rainy (adj.)","rainfall (n.)"],"synonyms":[],"antonyms":[],"tipVi":"rain đóng vai trò danh từ thường không đếm được; khi nói trời đang mưa dùng cấu trúc It rains.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_8_1', 'en-a1-8', 'Cách dùng “grow” (v.) — lớn lên; phát triển; tăng trưởng', 'grow rapidly  ·  grow vegetables  ·  grow older', 'Có dạng quá khứ là grew, quá khứ phân từ là grown; dùng chỉ sự biến đổi trạng thái thì theo sau là tính từ.', 'Họ từ (Word Family): growth (n.), grower (n.), growing (adj.) | Trái nghĩa: shrink', '[{"hanzi":"We grow fresh herbs in pots beside the kitchen window.","pinyin":"","meaning":"Chúng tôi trồng các loại rau thơm tươi trong chậu bên cửa sổ nhà bếp."},{"hanzi":"As cities grow, local authorities must invest in transport systems that serve expanding populations.","pinyin":"","meaning":"Khi các thành phố phát triển, chính quyền địa phương phải đầu tư vào các hệ thống giao thông phục vụ lượng dân cư ngày càng tăng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_8_2', 'en-a1-8', 'Cách dùng “cow” (n.) — bò cái; bò sữa', 'dairy cow  ·  milk a cow  ·  be cowed into silence', 'cow chỉ con bò cái trưởng thành; cattle là danh từ chỉ chung loài bò, không dùng hình thức số ít a cattle.', NULL, '[{"hanzi":"A brown cow stood quietly beside the farm gate.","pinyin":"","meaning":"Một con bò cái màu nâu đứng lặng lẽ bên cạnh cổng trang trại."},{"hanzi":"Improving the diet of dairy cows can increase milk production while supporting animal health.","pinyin":"","meaning":"Cải thiện chế độ ăn của bò sữa có thể làm tăng sản lượng sữa đồng thời hỗ trợ sức khỏe của vật nuôi."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_8_3', 'en-a1-8', 'Cách dùng “rain” (n.) — mưa; nước mưa', 'heavy rain  ·  pouring rain  ·  rain heavily', 'rain đóng vai trò danh từ thường không đếm được; khi nói trời đang mưa dùng cấu trúc It rains.', 'Họ từ (Word Family): rainy (adj.), rainfall (n.)', '[{"hanzi":"Heavy rain kept us inside for the whole afternoon.","pinyin":"","meaning":"Cơn mưa lớn đã khiến chúng tôi ở trong nhà suốt cả buổi chiều."},{"hanzi":"Farmers increasingly depend on stored water because seasonal rain has become less predictable in many regions.","pinyin":"","meaning":"Nông dân ngày càng phụ thuộc vào nguồn nước dự trữ vì lượng mưa theo mùa ở nhiều vùng trở nên khó dự đoán hơn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_8_4', 'en-a1-8', 'Cách dùng “dog” (n.) — n. chó; con chó', 'walk the dog  ·  a guide dog  ·  a stray dog', 'Động từ thường gặp dạng bị động be dogged by, diễn tả việc bị đeo bám hoặc quấy rầy lâu dài.', NULL, '[{"hanzi":"Our dog waits by the door every afternoon.","pinyin":"","meaning":"Chú chó nhà chúng tôi ngồi đợi bên cửa vào mỗi buổi chiều."},{"hanzi":"Training a guide dog requires considerable time, but it can greatly improve someone''s independence.","pinyin":"","meaning":"Việc huấn luyện một chú chó dẫn đường đòi hỏi rất nhiều thời gian, nhưng nó có thể cải thiện đáng kể tính tự lập của người sử dụng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_8_1', 'en-a1-8', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_8_1_1', 'ten_8_1', 'sea', 'The children watched small boats sailing across the sea.', 'The children watched small boats sailing across the sea.', '/siː/', 'Bọn trẻ đứng ngắm những chiếc thuyền nhỏ đang giương buồm ra khơi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_8_1_2', 'ten_8_1', 'tree', 'A small bird built its nest in our tree.', 'A small bird built its nest in our tree.', '/triː/', 'Một chú chim nhỏ đã làm tổ trên cây nhà chúng tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_8_1_3', 'ten_8_1', 'cow', 'A brown cow stood quietly beside the farm gate.', 'A brown cow stood quietly beside the farm gate.', '/kaʊ/', 'Một con bò cái màu nâu đứng lặng lẽ bên cạnh cổng trang trại.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
