INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_8_1_1', 'en-a1-8', 'ten_8_1', 'listening', 'listening', 'The children watched small boats sailing across the sea.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Con mèo nhà chúng tôi ngủ ở một góc đầy nắng bên cửa sổ.","Một chú khỉ nhỏ chuyền cành giữa các tán cây trên đầu chúng tôi.","Một con bò cái màu nâu đứng lặng lẽ bên cạnh cổng trang trại.","Bọn trẻ đứng ngắm những chiếc thuyền nhỏ đang giương buồm ra khơi."]'::jsonb, 3, 'The children watched small boats sailing across the sea. → Bọn trẻ đứng ngắm những chiếc thuyền nhỏ đang giương buồm ra khơi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
