INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_8_2', 'en-a1-8', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_8_2_1', 'ten_8_2', 'sea', 'Plastic waste entering the sea threatens marine wildlife and can eventually affect human food supplies.', 'Plastic waste entering the sea threatens marine wildlife and can eventually affect human food supplies.', '/siː/', 'Rác thải nhựa trôi dạt ra biển đe dọa các loài sinh vật hoang dã dưới nước và cuối cùng có thể ảnh hưởng đến nguồn cung cấp thực phẩm của con người.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_8_2_2', 'ten_8_2', 'tree', 'Planting trees in urban areas provides shade, improves air quality, and creates valuable habitats for wildlife.', 'Planting trees in urban areas provides shade, improves air quality, and creates valuable habitats for wildlife.', '/triː/', 'Trồng cây ở khu vực đô thị giúp tạo bóng mát, cải thiện chất lượng không khí và tạo ra môi trường sống quý giá cho động vật hoang dã.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_8_2_3', 'ten_8_2', 'cow', 'Improving the diet of dairy cows can increase milk production while supporting animal health.', 'Improving the diet of dairy cows can increase milk production while supporting animal health.', '/kaʊ/', 'Cải thiện chế độ ăn của bò sữa có thể làm tăng sản lượng sữa đồng thời hỗ trợ sức khỏe của vật nuôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_8_2_4', 'ten_8_2', 'die', 'Many marine animals die after swallowing plastic waste, highlighting the urgent need to reduce ocean pollution.', 'Many marine animals die after swallowing plastic waste, highlighting the urgent need to reduce ocean pollution.', '/daɪ/', 'Nhiều loài động vật biển chết sau khi nuốt phải rác thải nhựa, điều này làm nổi bật sự cấp bách phải giảm thiểu ô nhiễm đại dương.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_8_2_5', 'ten_8_2', 'autumn', 'Warmer autumn temperatures may delay leaf fall and affect the seasonal behaviour of local wildlife.', 'Warmer autumn temperatures may delay leaf fall and affect the seasonal behaviour of local wildlife.', '/ˈɔːtəm/', 'Nhiệt độ mùa thu ấm hơn có thể làm chậm quá trình rụng lá và ảnh hưởng đến tập tính theo mùa của động vật hoang dã địa phương.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_8_2_6', 'ten_8_2', 'cat', 'Keeping pet cats indoors can help protect native birds, particularly in areas with vulnerable wildlife populations.', 'Keeping pet cats indoors can help protect native birds, particularly in areas with vulnerable wildlife populations.', '/kæt/', 'Nuôi mèo cảnh trong nhà có thể giúp bảo vệ các loài chim bản địa, đặc biệt là ở những khu vực có quần thể động vật hoang dã dễ bị tổn thương.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_8_2_1', 'en-a1-8', 'ten_8_2', 'listening', 'listening', 'Plastic waste entering the sea threatens marine wildlife and can eventually affect human food supplies.', NULL, 'Trong câu vừa nghe, từ “sea” mang nghĩa nào sau đây?', '["ông","áo sơ mi","bánh mì kẹp; sandwich","biển; đại dương"]'::jsonb, 3, '“sea” (/siː/): biển; đại dương. Câu đầy đủ: Plastic waste entering the sea threatens marine wildlife and can eventually affect human food supplies.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_8_2_2', 'en-a1-8', 'ten_8_2', 'listening', 'listening', 'Planting trees in urban areas provides shade, improves air quality, and creates valuable habitats for wildlife.', NULL, 'Trong câu vừa nghe, từ “tree” mang nghĩa nào sau đây?', '["đường; đường ăn","môn bơi lội; việc bơi","adj. thân thiện; cởi mở; niềm nở","cây; cây gỗ"]'::jsonb, 3, '“tree” (/triː/): cây; cây gỗ. Câu đầy đủ: Planting trees in urban areas provides shade, improves air quality, and creates valuable habitats for wildlife.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
