INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_8_2', 'en-a1-8', NULL, 'comprehensive_test', 'listening', 'A small bird built its nest in our tree.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một chú chim nhỏ đã làm tổ trên cây nhà chúng tôi.","Cơn mưa lớn đã khiến chúng tôi ở trong nhà suốt cả buổi chiều.","Chúng tôi trồng các loại rau thơm tươi trong chậu bên cửa sổ nhà bếp.","Bọn trẻ đứng ngắm những chiếc thuyền nhỏ đang giương buồm ra khơi."]'::jsonb, 0, 'A small bird built its nest in our tree. → Một chú chim nhỏ đã làm tổ trên cây nhà chúng tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_8_3', 'en-a1-8', NULL, 'comprehensive_test', 'listening', 'cow', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thú vị; hay; hấp dẫn","mặt trời","bò cái; bò sữa","cuộc sống; đời sống"]'::jsonb, 2, 'cow (/kaʊ/) → bò cái; bò sữa; đe dọa; uy hiếp; khuất phục', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_8_4', 'en-a1-8', NULL, 'comprehensive_test', 'listening', 'These plants will die if we forget to water them.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy thả vài viên đá vào ly nước ép của mình.","Những cái cây này sẽ chết nếu chúng ta quên tưới nước.","Tuyết mới phủ trắng khu vườn khi chúng tôi thức dậy.","Một chú khỉ nhỏ chuyền cành giữa các tán cây trên đầu chúng tôi."]'::jsonb, 1, 'These plants will die if we forget to water them. → Những cái cây này sẽ chết nếu chúng ta quên tưới nước.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
