INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_8_6', 'en-a1-8', NULL, 'comprehensive_test', 'listening', 'Our cat sleeps in a sunny spot by the window.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi trải một tấm chăn lên bãi cỏ cạnh con sông.","Cô ấy thả vài viên đá vào ly nước ép của mình.","Cơn mưa lớn đã khiến chúng tôi ở trong nhà suốt cả buổi chiều.","Con mèo nhà chúng tôi ngủ ở một góc đầy nắng bên cửa sổ."]'::jsonb, 3, 'Our cat sleeps in a sunny spot by the window. → Con mèo nhà chúng tôi ngủ ở một góc đầy nắng bên cửa sổ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
