INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_8_8', 'en-a1-8', NULL, 'comprehensive_test', 'listening', 'A little monkey swung between branches above our heads.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một chú khỉ nhỏ chuyền cành giữa các tán cây trên đầu chúng tôi.","Một con chuột nhỏ đã lẻn ra phía sau tủ trước bữa sáng.","Tuyết mới phủ trắng khu vườn khi chúng tôi thức dậy.","Chú chó nhà chúng tôi ngồi đợi bên cửa vào mỗi buổi chiều."]'::jsonb, 0, 'A little monkey swung between branches above our heads. → Một chú khỉ nhỏ chuyền cành giữa các tán cây trên đầu chúng tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
