INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_8_18', 'en-a1-8', NULL, 'comprehensive_test', 'reading', NULL, 'Plastic waste entering the sea threatens marine wildlife and can eventually affect human food supplies.', 'Dựa vào câu trên, từ “sea” có nghĩa phù hợp nhất là gì?', '["nông trại; trang trại","vòi hoa sen; việc tắm dưới vòi hoa sen","biển; đại dương","cái cốc; tách; một cốc (định lượng)"]'::jsonb, 2, 'sea: biển; đại dương; một lượng lớn; một vùng bạt ngàn. Dịch cả câu: Rác thải nhựa trôi dạt ra biển đe dọa các loài sinh vật hoang dã dưới nước và cuối cùng có thể ảnh hưởng đến nguồn cung cấp thực phẩm của con người.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_8_19', 'en-a1-8', NULL, 'comprehensive_test', 'reading', NULL, 'Planting trees in urban areas provides shade, improves air quality, and creates valuable habitats for wildlife.', 'Dựa vào câu trên, từ “tree” có nghĩa phù hợp nhất là gì?', '["trẻ em; những đứa trẻ","ngoài ra; cũng","cây; cây gỗ","vào tối nay; trong đêm nay"]'::jsonb, 2, 'tree: cây; cây gỗ. Dịch cả câu: Trồng cây ở khu vực đô thị giúp tạo bóng mát, cải thiện chất lượng không khí và tạo ra môi trường sống quý giá cho động vật hoang dã.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_8_20', 'en-a1-8', NULL, 'comprehensive_test', 'reading', NULL, 'Improving the diet of dairy cows can increase milk production while supporting animal health.', 'Dựa vào câu trên, từ “cow” có nghĩa phù hợp nhất là gì?', '["thức ăn; đồ ăn; thực phẩm","bò cái; bò sữa","quả cam; trái cam","hoàn thành; kết thúc; làm xong"]'::jsonb, 1, 'cow: bò cái; bò sữa; đe dọa; uy hiếp; khuất phục. Dịch cả câu: Cải thiện chế độ ăn của bò sữa có thể làm tăng sản lượng sữa đồng thời hỗ trợ sức khỏe của vật nuôi.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_8_21', 'en-a1-8', NULL, 'comprehensive_test', 'reading', NULL, 'Many marine animals die after swallowing plastic waste, highlighting the urgent need to reduce ocean pollution.', 'Dựa vào câu trên, từ “die” có nghĩa phù hợp nhất là gì?', '["con cá; thịt cá","ở bên ngoài; ra ngoài","chết; tàn lụi","sáng; trước trưa (tính từ nửa đêm đến trước buổi trưa)"]'::jsonb, 2, 'die: chết; tàn lụi; ngừng hoạt động; lụi tàn dần; con xúc xắc. Dịch cả câu: Nhiều loài động vật biển chết sau khi nuốt phải rác thải nhựa, điều này làm nổi bật sự cấp bách phải giảm thiểu ô nhiễm đại dương.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_8_22', 'en-a1-8', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sư tử”', '["twice","waitress","say","lion"]'::jsonb, 3, 'sư tử → lion (/ˈlaɪən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_8_23', 'en-a1-8', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hươu cao cổ”', '["cinema","below","milk","giraffe"]'::jsonb, 3, 'hươu cao cổ → giraffe (/dʒəˈræf/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_8_24', 'en-a1-8', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “mưa; nước mưa”', '["rain","pair","Italy","tomorrow"]'::jsonb, 0, 'mưa; nước mưa → rain (/reɪn/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-9', 'en', 'Bài 9: Sức khỏe & Cơ thể - CEFR A1', 'CEFR A1', 'A1 · Sức khỏe', '24 từ vựng Tiếng Anh CEFR A1 chủ đề sức khỏe & cơ thể kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1009, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_body', 'en-a1-9', 'body', '/ˈbɑːdi/', 'A1', 'thân thể; cơ thể; tổ chức; cơ quan; thân bài; phần chính', 'n.', 'bodily (adj.)', NULL, 'body có thể chỉ tổ chức; phần body của bài viết chỉ phần thân bài chính.', 'My whole body aches after yesterday''s long walk.', NULL, 'Toàn thân tôi ê ẩm sau chuyến đi bộ dài ngày hôm qua.', '{"wordId":"body","ukIpa":"/ˈbɒdi/","usIpa":"/ˈbɑːdi/","cefr":"A1","topic":"health","senses":[{"pos":"n.","en":"The whole physical structure of a person or animal.","vi":"thân thể; cơ thể"},{"pos":"n.","en":"An organized group with a particular purpose.","vi":"tổ chức; cơ quan"},{"pos":"n.","en":"The main or central part of something.","vi":"thân bài; phần chính"}],"examples":[{"en":"My whole body aches after yesterday''s long walk.","vi":"Toàn thân tôi ê ẩm sau chuyến đi bộ dài ngày hôm qua.","audioKind":"ex"},{"en":"An independent body should monitor water quality and publish its findings for the public.","vi":"Một cơ quan độc lập nên giám sát chất lượng nước và công bố kết quả cho công chúng.","audioKind":"ex2"}],"collocations":[{"en":"human body","vi":"cơ thể người"},{"en":"governing body","vi":"cơ quan quản lý"},{"en":"a body of evidence","vi":"một loạt bằng chứng"},{"en":"the body of an essay","vi":"phần thân bài của một bài luận"}],"wordFamily":["bodily (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"body có thể chỉ tổ chức; phần body của bài viết chỉ phần thân bài chính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nose', 'en-a1-9', 'nose', '/noʊz/', 'A1', 'mũi (bộ phận trên khuôn mặt dùng để ngửi và thở); phần mũi; phần phía trước của máy bay hoặc phương tiện tương tự', 'n.', 'nosy (adj.)', NULL, 'Hỉ mũi dùng cụm blow your nose, không dùng clean.', 'My nose turned red in the cold wind.', NULL, 'Mũi của tôi đỏ bừng lên trong gió lạnh.', '{"wordId":"nose","ukIpa":"/nəʊz/","usIpa":"/noʊz/","cefr":"A1","topic":"health","senses":[{"pos":"n.","en":"The part of your face used for smelling and breathing.","vi":"mũi (bộ phận trên khuôn mặt dùng để ngửi và thở)"},{"pos":"n.","en":"The front part of an aircraft or similar vehicle.","vi":"phần mũi; phần phía trước của máy bay hoặc phương tiện tương tự"}],"examples":[{"en":"My nose turned red in the cold wind.","vi":"Mũi của tôi đỏ bừng lên trong gió lạnh.","audioKind":"ex"},{"en":"Wearing a mask over the nose and mouth can reduce exposure to airborne dust.","vi":"Đeo khẩu trang che kín mũi và miệng có thể làm giảm việc hít phải bụi trong không khí.","audioKind":"ex2"}],"collocations":[{"en":"blow your nose","vi":"hỉ mũi"},{"en":"a runny nose","vi":"sổ mũi"},{"en":"the nose of an aircraft","vi":"mũi máy bay"}],"wordFamily":["nosy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Hỉ mũi dùng cụm blow your nose, không dùng clean.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_doctor', 'en-a1-9', 'doctor', '/ˈdɑːk.tɚ/', 'A1', 'bác sĩ; tiến sĩ; sửa đổi; làm giả', 'n.', 'doctoral (adj.), doctorate (n.)', 'Đồng nghĩa: physician', 'Đi khám bác sĩ thường nói see a doctor; động từ doctor có thể mang nghĩa là làm giả, chỉnh sửa tài liệu.', 'The doctor listened carefully as I described my symptoms.', NULL, 'Bác sĩ lắng nghe chăm chú khi tôi miêu tả các triệu chứng của mình.', '{"wordId":"doctor","ukIpa":"/ˈdɒk.tə/","usIpa":"/ˈdɑːk.tɚ/","cefr":"A1","topic":"health","senses":[{"pos":"n.","en":"a trained professional who diagnoses and treats illnesses","vi":"bác sĩ"},{"pos":"n.","en":"a person who has earned the highest university degree","vi":"tiến sĩ"},{"pos":"v.","en":"to change something dishonestly to deceive people","vi":"sửa đổi; làm giả"}],"examples":[{"en":"The doctor listened carefully as I described my symptoms.","vi":"Bác sĩ lắng nghe chăm chú khi tôi miêu tả các triệu chứng của mình.","audioKind":"ex"},{"en":"Governments should train more doctors to ensure that rural communities have reliable access to healthcare.","vi":"Chính phủ nên đào tạo thêm bác sĩ để đảm bảo các vùng nông thôn có thể tiếp cận dịch vụ chăm sóc sức khỏe đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"see a doctor","vi":"đi khám bác sĩ"},{"en":"family doctor","vi":"bác sĩ gia đình"},{"en":"a doctor of philosophy","vi":"tiến sĩ triết học"},{"en":"doctor the evidence","vi":"làm giả bằng chứng"}],"wordFamily":["doctoral (adj.)","doctorate (n.)"],"synonyms":["physician"],"antonyms":[],"tipVi":"Đi khám bác sĩ thường nói see a doctor; động từ doctor có thể mang nghĩa là làm giả, chỉnh sửa tài liệu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gym', 'en-a1-9', 'gym', '/dʒɪm/', 'A1', 'phòng tập thể hình; phòng gym; giờ thể dục; môn thể dục ở trường', 'n.', 'gymnasium (n.)', 'Đồng nghĩa: gymnasium', 'gym là từ viết tắt của gymnasium; đi tập gym dùng cụm từ go to the gym.', 'I usually go to the gym before work.', NULL, 'Tôi thường đi tập gym trước giờ làm việc.', '{"wordId":"gym","ukIpa":"/dʒɪm/","usIpa":"/dʒɪm/","cefr":"A1","topic":"health","senses":[{"pos":"n.","en":"A room or building equipped for exercise and sport.","vi":"phòng tập thể hình; phòng gym"},{"pos":"n.","en":"Physical exercise taught or practised at school.","vi":"giờ thể dục; môn thể dục ở trường"}],"examples":[{"en":"I usually go to the gym before work.","vi":"Tôi thường đi tập gym trước giờ làm việc.","audioKind":"ex"},{"en":"Affordable gym membership can encourage regular exercise, although safe outdoor spaces are equally important for public health.","vi":"Thẻ tập gym có giá cả phải chăng có thể khuyến khích việc tập luyện đều đặn, mặc dù không gian ngoài trời an toàn cũng quan trọng không kém đối với sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"go to the gym","vi":"đi tập gym"},{"en":"gym membership","vi":"thẻ thành viên phòng gym"},{"en":"gym equipment","vi":"dụng cụ tập gym"},{"en":"gym class","vi":"tiết học thể dục"}],"wordFamily":["gymnasium (n.)"],"synonyms":["gymnasium"],"antonyms":[],"tipVi":"gym là từ viết tắt của gymnasium; đi tập gym dùng cụm từ go to the gym.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hospital', 'en-a1-9', 'hospital', '/ˈhɑːspɪtl/', 'A1', 'bệnh viện', 'n.', 'hospitalisation (n.), hospitalise (v.)', NULL, 'Nằm viện điều trị: tiếng Anh-Anh dùng in hospital, tiếng Anh-Mỹ dùng in the hospital.', 'She works as a nurse at the local hospital.', NULL, 'Cô ấy làm y tá tại bệnh viện địa phương.', '{"wordId":"hospital","ukIpa":"/ˈhɒspɪtl/","usIpa":"/ˈhɑːspɪtl/","cefr":"A1","topic":"health","senses":[{"pos":"n.","en":"A place where ill or injured people receive medical treatment.","vi":"bệnh viện"}],"examples":[{"en":"She works as a nurse at the local hospital.","vi":"Cô ấy làm y tá tại bệnh viện địa phương.","audioKind":"ex"},{"en":"Building a new hospital in the region would improve access to specialist care for rural communities.","vi":"Việc xây dựng một bệnh viện mới trong khu vực sẽ giúp người dân nông thôn tiếp cận tốt hơn với các dịch vụ y tế chuyên khoa.","audioKind":"ex2"}],"collocations":[{"en":"be admitted to hospital","vi":"nhập viện điều trị"},{"en":"be discharged from hospital","vi":"xuất viện"},{"en":"a public hospital","vi":"bệnh viện công"},{"en":"hospital staff","vi":"nhân viên bệnh viện"}],"wordFamily":["hospitalisation (n.)","hospitalise (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Nằm viện điều trị: tiếng Anh-Anh dùng in hospital, tiếng Anh-Mỹ dùng in the hospital.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sugar', 'en-a1-9', 'sugar', '/ˈʃʊɡɚ/', 'A1', 'đường; đường ăn', 'n.', 'sugary (adj.), sugarless (adj.)', NULL, 'Khi chỉ đường ăn nói chung, từ này thường không đếm được; cụm a spoonful of sugar có nghĩa là một muỗng đường.', 'She stirred a spoonful of sugar into her tea.', NULL, 'Cô ấy khuấy một thìa đường vào ly trà của mình.', '{"wordId":"sugar","ukIpa":"/ˈʃʊɡə/","usIpa":"/ˈʃʊɡɚ/","cefr":"A1","topic":"health","senses":[{"pos":"n.","en":"A sweet substance used to make food and drinks sweeter","vi":"đường; đường ăn"}],"examples":[{"en":"She stirred a spoonful of sugar into her tea.","vi":"Cô ấy khuấy một thìa đường vào ly trà của mình.","audioKind":"ex"},{"en":"Reducing sugar consumption can help prevent health problems associated with an unhealthy diet.","vi":"Việc giảm tiêu thụ đường có thể giúp ngăn ngừa các vấn đề sức khỏe liên quan đến chế độ ăn uống không lành mạnh.","audioKind":"ex2"}],"collocations":[{"en":"add sugar","vi":"thêm đường"},{"en":"sugar intake","vi":"lượng đường nạp vào cơ thể"},{"en":"blood sugar","vi":"đường huyết"},{"en":"sugar content","vi":"hàm lượng đường"}],"wordFamily":["sugary (adj.)","sugarless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ đường ăn nói chung, từ này thường không đếm được; cụm a spoonful of sugar có nghĩa là một muỗng đường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thirsty', 'en-a1-9', 'thirsty', '/ˈθɜːrsti/', 'A1', 'khát; cảm thấy cần uống nước; khao khát; tha thiết', 'adj.', 'thirst (n.), thirst (v.)', NULL, 'Biểu ạt sự khao khát cái gì dùng thirsty for, không dùng thirsty of.', 'I felt thirsty after walking home in the sun.', NULL, 'Tôi cảm thấy khát nước sau khi đi bộ dưới trời nắng về nhà.', '{"wordId":"thirsty","ukIpa":"/ˈθɜːsti/","usIpa":"/ˈθɜːrsti/","cefr":"A1","topic":"health","senses":[{"pos":"adj.","en":"feeling that you need or want a drink","vi":"khát; cảm thấy cần uống nước"},{"pos":"adj.","en":"having a strong desire for something","vi":"khao khát; tha thiết"}],"examples":[{"en":"I felt thirsty after walking home in the sun.","vi":"Tôi cảm thấy khát nước sau khi đi bộ dưới trời nắng về nhà.","audioKind":"ex"},{"en":"Children who are thirsty for knowledge benefit from lessons that encourage questions and independent exploration.","vi":"Trẻ em khao khát kiến thức sẽ được hưởng lợi từ các bài học khuyến khích đặt câu hỏi và tự khám phá.","audioKind":"ex2"}],"collocations":[{"en":"feel thirsty","vi":"cảm thấy khát"},{"en":"thirsty for knowledge","vi":"khao khát kiến thức"},{"en":"make someone thirsty","vi":"làm cho ai đó khát"}],"wordFamily":["thirst (n.)","thirst (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Biểu ạt sự khao khát cái gì dùng thirsty for, không dùng thirsty of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_food', 'en-a1-9', 'food', '/fuːd/', 'A1', 'thức ăn; đồ ăn; thực phẩm', 'n.', NULL, 'Đồng nghĩa: nourishment', 'Khi chỉ chung chung thì food là danh từ không đếm được; dùng foods khi chỉ các loại thực phẩm khác nhau.', 'We packed enough food for a picnic by the lake.', NULL, 'Chúng tôi đã chuẩn bị đủ đồ ăn cho buổi dã ngoại bên hồ.', '{"wordId":"food","ukIpa":"/fuːd/","usIpa":"/fuːd/","cefr":"A1","topic":"health","senses":[{"pos":"n.","en":"Things people or animals eat to live and grow.","vi":"thức ăn; đồ ăn; thực phẩm"}],"examples":[{"en":"We packed enough food for a picnic by the lake.","vi":"Chúng tôi đã chuẩn bị đủ đồ ăn cho buổi dã ngoại bên hồ.","audioKind":"ex"},{"en":"Reducing food waste at home can save money and lower the environmental impact of household consumption.","vi":"Việc giảm lãng phí thực phẩm tại nhà có thể tiết kiệm tiền bạc và giảm tác động môi trường từ việc tiêu dùng của hộ gia đình.","audioKind":"ex2"}],"collocations":[{"en":"fresh food","vi":"thực phẩm tươi sống"},{"en":"food waste","vi":"lãng phí thực phẩm"},{"en":"food safety","vi":"an toàn thực phẩm"},{"en":"processed food","vi":"thực phẩm chế biến sẵn"}],"wordFamily":[],"synonyms":["nourishment"],"antonyms":[],"tipVi":"Khi chỉ chung chung thì food là danh từ không đếm được; dùng foods khi chỉ các loại thực phẩm khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tired', 'en-a1-9', 'tired', '/ˈtaɪərd/', 'A1', 'mệt mỏi; mệt; chán ngấy; phát ngán', 'adj.', 'tire (v.), tiring (adj.), tiredness (n.), tireless (adj.)', 'Đồng nghĩa: weary, exhausted · Trái nghĩa: rested, energetic', '"tired" dùng để diễn tả người cảm thấy mệt; "tiring" dùng để diễn tả sự việc gây mệt mỏi.', 'I felt too tired to cook after the walk.', NULL, 'Tôi cảm thấy quá mệt để nấu ăn sau khi đi bộ.', '{"wordId":"tired","ukIpa":"/ˈtaɪəd/","usIpa":"/ˈtaɪərd/","cefr":"A1","topic":"health","senses":[{"pos":"adj.","en":"needing rest or sleep because of physical or mental effort","vi":"mệt mỏi; mệt"},{"pos":"adj.","en":"annoyed or bored by something that continues or repeats","vi":"chán ngấy; phát ngán"}],"examples":[{"en":"I felt too tired to cook after the walk.","vi":"Tôi cảm thấy quá mệt để nấu ăn sau khi đi bộ.","audioKind":"ex"},{"en":"Employees who regularly work long hours may become too tired to perform their duties safely.","vi":"Những nhân viên thường xuyên làm việc nhiều giờ có thể trở nên quá mệt mỏi để thực hiện nhiệm vụ một cách an toàn.","audioKind":"ex2"}],"collocations":[{"en":"feel tired","vi":"cảm thấy mệt mỏi"},{"en":"tired of waiting","vi":"chán ngấy việc chờ đợi"},{"en":"too tired to concentrate","vi":"quá mệt để tập trung"}],"wordFamily":["tire (v.)","tiring (adj.)","tiredness (n.)","tireless (adj.)"],"synonyms":["weary","exhausted"],"antonyms":["rested","energetic"],"tipVi":"\"tired\" dùng để diễn tả người cảm thấy mệt; \"tiring\" dùng để diễn tả sự việc gây mệt mỏi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tooth', 'en-a1-9', 'tooth', '/tuːθ/', 'A1', 'răng; răng (của công cụ, lược hoặc bánh xe)', 'n.', 'toothless (adj.), toothy (adj.)', NULL, 'Dạng số nhiều là teeth theo quy tắc bất quy tắc, lưu ý sự thay đổi của nguyên âm ở giữa.', 'The dentist checked each tooth with a small mirror.', NULL, 'Nha sĩ đã kiểm tra từng chiếc răng bằng một chiếc gương nhỏ.', '{"wordId":"tooth","ukIpa":"/tuːθ/","usIpa":"/tuːθ/","cefr":"A1","topic":"health","senses":[{"pos":"n.","en":"a hard structure in the mouth used for biting and chewing","vi":"răng"},{"pos":"n.","en":"a pointed part of a tool, comb or wheel","vi":"răng (của công cụ, lược hoặc bánh xe)"}],"examples":[{"en":"The dentist checked each tooth with a small mirror.","vi":"Nha sĩ đã kiểm tra từng chiếc răng bằng một chiếc gương nhỏ.","audioKind":"ex"},{"en":"Regular dental checkups can help prevent tooth decay and reduce the need for expensive treatment.","vi":"Việc khám răng định kỳ có thể giúp ngăn ngừa sâu răng và giảm thiểu nhu cầu điều trị tốn kém.","audioKind":"ex2"}],"collocations":[{"en":"brush your teeth","vi":"đánh răng"},{"en":"tooth decay","vi":"sâu răng"},{"en":"a loose tooth","vi":"răng lung lay"},{"en":"wisdom tooth","vi":"răng khôn"}],"wordFamily":["toothless (adj.)","toothy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là teeth theo quy tắc bất quy tắc, lưu ý sự thay đổi của nguyên âm ở giữa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_relax', 'en-a1-9', 'relax', '/rɪˈlæks/', 'A1', 'thư giãn; nghỉ ngơi; thả lỏng; duỗi cơ; nới lỏng; nới lỏng quy định', 'v.', 'relaxation (n.), relaxed (adj.), relaxing (adj.)', 'Đồng nghĩa: unwind · Trái nghĩa: tense up', 'Người cảm thấy thư giãn dùng relaxed; sự vật làm cho thư giãn dùng relaxing.', 'I like to relax with music after dinner.', NULL, 'Tôi thích nghe nhạc để thư giãn sau bữa tối.', '{"wordId":"relax","ukIpa":"/rɪˈlæks/","usIpa":"/rɪˈlæks/","cefr":"A1","topic":"health","senses":[{"pos":"v.","en":"To become calm and comfortable, or make someone feel this way.","vi":"thư giãn; nghỉ ngơi"},{"pos":"v.","en":"To make muscles less tight, or become less tight.","vi":"thả lỏng; duỗi cơ"},{"pos":"v.","en":"To make rules or restrictions less strict.","vi":"nới lỏng; nới lỏng quy định"}],"examples":[{"en":"I like to relax with music after dinner.","vi":"Tôi thích nghe nhạc để thư giãn sau bữa tối.","audioKind":"ex"},{"en":"Regular access to green spaces helps urban residents relax and may improve their overall mental health.","vi":"Việc thường xuyên tiếp cận với không gian xanh giúp cư dân thành thị thư giãn và có thể cải thiện sức khỏe tinh thần tổng thể của họ.","audioKind":"ex2"}],"collocations":[{"en":"relax your muscles","vi":"thả lỏng cơ bắp"},{"en":"relax restrictions","vi":"nới lỏng các hạn chế"},{"en":"sit back and relax","vi":"ngồi ngả lưng và thư giãn"}],"wordFamily":["relaxation (n.)","relaxed (adj.)","relaxing (adj.)"],"synonyms":["unwind"],"antonyms":["tense up"],"tipVi":"Người cảm thấy thư giãn dùng relaxed; sự vật làm cho thư giãn dùng relaxing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_walking', 'en-a1-9', 'walking', '/ˈwɔːkɪŋ/', 'A1', 'sự đi bộ; việc đi dạo', 'n.', 'walk (v.), walk (n.), walker (n.)', NULL, 'Phụ âm l trong từ walking là âm câm; ngoài ra hành động đi bộ đến đâu cũng có thể diễn đạt bằng cụm on foot.', 'Walking to the shops takes about ten minutes.', NULL, 'Đi bộ ra các cửa hàng mất khoảng mười phút.', '{"wordId":"walking","ukIpa":"/ˈwɔːkɪŋ/","usIpa":"/ˈwɔːkɪŋ/","cefr":"A1","topic":"health","senses":[{"pos":"n.","en":"Moving on foot, especially for exercise or pleasure.","vi":"sự đi bộ; việc đi dạo"}],"examples":[{"en":"Walking to the shops takes about ten minutes.","vi":"Đi bộ ra các cửa hàng mất khoảng mười phút.","audioKind":"ex"},{"en":"Cities can encourage walking by improving pavement quality and creating safer crossings near schools and shopping areas.","vi":"Các thành phố có thể khuyến khích người dân đi bộ bằng cách nâng cao chất lượng vỉa hè và bố trí các lối sang đường an toàn hơn gần trường học và khu mua sắm.","audioKind":"ex2"}],"collocations":[{"en":"go walking","vi":"đi dạo"},{"en":"walking boots","vi":"giày đi bộ đường dài"},{"en":"walking distance","vi":"khoảng cách có thể đi bộ được"},{"en":"brisk walking","vi":"đi bộ nhanh"}],"wordFamily":["walk (v.)","walk (n.)","walker (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Phụ âm l trong từ walking là âm câm; ngoài ra hành động đi bộ đến đâu cũng có thể diễn đạt bằng cụm on foot.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dangerous', 'en-a1-9', 'dangerous', '/ˈdeɪndʒərəs/', 'A1', 'nguy hiểm', 'adj.', 'danger (n.), dangerously (adv.), endanger (v.)', 'Đồng nghĩa: unsafe, hazardous, risky · Trái nghĩa: safe, harmless', 'dangerous là tính từ; để bổ nghĩa cho hành động cần dùng trạng từ dangerously.', 'That broken step is dangerous, so please avoid it.', NULL, 'Bậc thềm bị hỏng đó rất nguy hiểm, vì vậy xin hãy tránh xa nó ra.', '{"wordId":"dangerous","ukIpa":"/ˈdeɪndʒərəs/","usIpa":"/ˈdeɪndʒərəs/","cefr":"A1","topic":"health","senses":[{"pos":"adj.","en":"Likely to cause harm, injury, or serious problems.","vi":"nguy hiểm"}],"examples":[{"en":"That broken step is dangerous, so please avoid it.","vi":"Bậc thềm bị hỏng đó rất nguy hiểm, vì vậy xin hãy tránh xa nó ra.","audioKind":"ex"},{"en":"Poorly maintained roads can create dangerous conditions for cyclists, especially during heavy rain or after dark.","vi":"Những con đường không được bảo trì tốt có thể tạo ra các điều kiện nguy hiểm cho người đi xe đạp, đặc biệt là trong trận mưa lớn hoặc khi trời đã tối.","audioKind":"ex2"}],"collocations":[{"en":"dangerous conditions","vi":"điều kiện nguy hiểm"},{"en":"highly dangerous","vi":"rất nguy hiểm"},{"en":"dangerous driving","vi":"lái xe nguy hiểm"}],"wordFamily":["danger (n.)","dangerously (adv.)","endanger (v.)"],"synonyms":["unsafe","hazardous","risky"],"antonyms":["safe","harmless"],"tipVi":"dangerous là tính từ; để bổ nghĩa cho hành động cần dùng trạng từ dangerously.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eye', 'en-a1-9', 'eye', '/aɪ/', 'A1', 'mắt; bộ phận cơ thể dùng để nhìn; con mắt thẩm mỹ; năng lực đánh giá; nhìn chăm chú; ngắm nghía', 'n.', 'eyebrow (n.), eyelid (n.), eyesight (n.)', NULL, 'an eye for biểu thị khả năng thẩm mỹ; keep an eye on biểu thị việc trông nom, theo dõi.', 'She closed her eyes and listened to the rain.', NULL, 'Cô ấy nhắm mắt lại và lắng nghe tiếng mưa rơi.', '{"wordId":"eye","ukIpa":"/aɪ/","usIpa":"/aɪ/","cefr":"A1","topic":"health","senses":[{"pos":"n.","en":"one of the two body parts used for seeing","vi":"mắt; bộ phận cơ thể dùng để nhìn"},{"pos":"n.","en":"an ability to notice or judge particular qualities","vi":"con mắt thẩm mỹ; năng lực đánh giá"},{"pos":"v.","en":"to look at someone or something with particular interest","vi":"nhìn chăm chú; ngắm nghía"}],"examples":[{"en":"She closed her eyes and listened to the rain.","vi":"Cô ấy nhắm mắt lại và lắng nghe tiếng mưa rơi.","audioKind":"ex"},{"en":"Designers need an eye for detail to create public spaces that are both attractive and accessible.","vi":"Các nhà thiết kế cần có sự nhạy bén về chi tiết để tạo ra không gian công cộng vừa thu hút vừa dễ tiếp cận.","audioKind":"ex2"}],"collocations":[{"en":"eye contact","vi":"giao tiếp bằng mắt"},{"en":"keep an eye on","vi":"trông chừng; theo dõi"},{"en":"an eye for detail","vi":"khả năng quan sát chi tiết tinh tế"},{"en":"catch someone''s eye","vi":"thu hút sự chú ý của ai đó"}],"wordFamily":["eyebrow (n.)","eyelid (n.)","eyesight (n.)"],"synonyms":[],"antonyms":[],"tipVi":"an eye for biểu thị khả năng thẩm mỹ; keep an eye on biểu thị việc trông nom, theo dõi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drink', 'en-a1-9', 'drink', '/drɪŋk/', 'A1', 'uống; đồ uống; thức uống; uống rượu bia', 'v.', 'drinker (n.), drinkable (adj.), drinking (n.)', 'Đồng nghĩa: beverage', 'Biến đổi bất quy tắc: drink—drank—drunk.', 'I always drink some water after walking the dog.', NULL, 'Tôi luôn uống một ít nước sau khi dắt chó đi dạo.', '{"wordId":"drink","ukIpa":"/drɪŋk/","usIpa":"/drɪŋk/","cefr":"A1","topic":"health","senses":[{"pos":"v.","en":"to take liquid into your mouth and swallow it","vi":"uống"},{"pos":"n.","en":"a liquid for swallowing or a serving of it","vi":"đồ uống; thức uống"},{"pos":"v.","en":"to consume alcoholic beverages","vi":"uống rượu bia"}],"examples":[{"en":"I always drink some water after walking the dog.","vi":"Tôi luôn uống một ít nước sau khi dắt chó đi dạo.","audioKind":"ex"},{"en":"Encouraging children to drink water instead of sugary beverages may improve their dental health over time.","vi":"Việc khuyến khích trẻ em uống nước thay vì đồ uống có đường có thể cải thiện sức khỏe răng miệng của chúng theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"drink water","vi":"uống nước"},{"en":"a hot drink","vi":"đồ uống nóng"},{"en":"drinking water","vi":"nước uống"},{"en":"soft drink","vi":"đồ uống không có cồn"}],"wordFamily":["drinker (n.)","drinkable (adj.)","drinking (n.)"],"synonyms":["beverage"],"antonyms":[],"tipVi":"Biến đổi bất quy tắc: drink—drank—drunk.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mouth', 'en-a1-9', 'mouth', '/maʊθ/ (n.); /maʊð/ (v.)', 'A1', 'miệng; khoang miệng; cửa hang; cửa sông; mấp máy môi không thành tiếng', 'n.', 'mouthful (n.), mouthwash (n.), mouthpiece (n.)', NULL, 'Danh từ có âm cuối là /θ/; động từ có âm cuối là /ð/.', 'The dentist asked me to open my mouth wider.', NULL, 'Nha sĩ yêu cầu tôi há miệng to hơn nữa.', '{"wordId":"mouth","ukIpa":"/maʊθ/ (n.); /maʊð/ (v.)","usIpa":"/maʊθ/ (n.); /maʊð/ (v.)","cefr":"A1","topic":"health","senses":[{"pos":"n.","en":"the opening in your face used for eating and speaking","vi":"miệng; khoang miệng"},{"pos":"n.","en":"the opening of a cave or where a river meets the sea","vi":"cửa hang; cửa sông"},{"pos":"v.","en":"to form words with your lips without making a sound","vi":"mấp máy môi không thành tiếng"}],"examples":[{"en":"The dentist asked me to open my mouth wider.","vi":"Nha sĩ yêu cầu tôi há miệng to hơn nữa.","audioKind":"ex"},{"en":"Wetlands near the mouth of a river provide valuable habitats and help protect coastal communities from flooding.","vi":"Các vùng đất ngập nước gần cửa sông cung cấp môi trường sống có giá trị và giúp bảo vệ các cộng đồng ven biển khỏi lũ lụt.","audioKind":"ex2"}],"collocations":[{"en":"open your mouth","vi":"há miệng"},{"en":"the mouth of a river","vi":"cửa sông"},{"en":"word of mouth","vi":"lời đồn miệng; truyền miệng"}],"wordFamily":["mouthful (n.)","mouthwash (n.)","mouthpiece (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ có âm cuối là /θ/; động từ có âm cuối là /ð/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_salt', 'en-a1-9', 'salt', '/sɔlt/', 'A1', 'muối; muối ăn; nêm muối; ướp muối', 'n.', 'salty (adj.), salted (adj.), unsalted (adj.)', NULL, 'Muối ăn thường là danh từ không đếm được; cụm a pinch of salt dùng để chỉ một nhúm muối.', 'Please pass the salt before the soup gets cold.', NULL, 'Làm ơn chuyền hộ lọ muối trước khi món súp nguội đi.', '{"wordId":"salt","ukIpa":"/sɔːlt/","usIpa":"/sɔlt/","cefr":"A1","topic":"health","senses":[{"pos":"n.","en":"a white substance used to flavour or preserve food","vi":"muối; muối ăn"},{"pos":"v.","en":"to add salt to food or preserve it with salt","vi":"nêm muối; ướp muối"}],"examples":[{"en":"Please pass the salt before the soup gets cold.","vi":"Làm ơn chuyền hộ lọ muối trước khi món súp nguội đi.","audioKind":"ex"},{"en":"Reducing salt intake is an effective way to lower the risk of high blood pressure.","vi":"Giảm lượng muối tiêu thụ là một cách hiệu quả để hạ nguy cơ cao huyết áp.","audioKind":"ex2"}],"collocations":[{"en":"a pinch of salt","vi":"một nhúm muối"},{"en":"salt intake","vi":"lượng muối tiêu thụ"},{"en":"sea salt","vi":"muối biển"},{"en":"add salt","vi":"thêm muối"}],"wordFamily":["salty (adj.)","salted (adj.)","unsalted (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Muối ăn thường là danh từ không đếm được; cụm a pinch of salt dùng để chỉ một nhúm muối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sleep', 'en-a1-9', 'sleep', '/sliːp/', 'A1', 'ngủ; giấc ngủ', 'v.', 'asleep (adj.), sleepy (adj.), sleepless (adj.), sleeper (n.)', 'Đồng nghĩa: slumber · Trái nghĩa: wake', 'Dạng quá khứ và quá khứ phân từ đều là slept; cụm từ chìm vào giấc ngủ là fall asleep.', 'Our cat likes to sleep beside the warm radiator.', NULL, 'Con mèo nhà tôi thích ngủ cạnh chiếc lò sưởi ấm áp.', '{"wordId":"sleep","ukIpa":"/sliːp/","usIpa":"/sliːp/","cefr":"A1","topic":"health","senses":[{"pos":"v.","en":"to rest with eyes closed and awareness reduced","vi":"ngủ"},{"pos":"n.","en":"the natural resting state in which awareness is reduced","vi":"giấc ngủ"}],"examples":[{"en":"Our cat likes to sleep beside the warm radiator.","vi":"Con mèo nhà tôi thích ngủ cạnh chiếc lò sưởi ấm áp.","audioKind":"ex"},{"en":"Regular sleep supports memory and concentration, making it particularly important for students preparing for examinations.","vi":"Giấc ngủ điều độ hỗ trợ trí nhớ và sự tập trung, điều này đặc biệt quan trọng đối với học sinh sinh viên đang chuẩn bị cho các kỳ thi.","audioKind":"ex2"}],"collocations":[{"en":"get enough sleep","vi":"ngủ đủ giấc"},{"en":"fall asleep","vi":"chìm vào giấc ngủ; buồn ngủ"},{"en":"sleep well","vi":"ngủ ngon"},{"en":"lack of sleep","vi":"thiếu ngủ"}],"wordFamily":["asleep (adj.)","sleepy (adj.)","sleepless (adj.)","sleeper (n.)"],"synonyms":["slumber"],"antonyms":["wake"],"tipVi":"Dạng quá khứ và quá khứ phân từ đều là slept; cụm từ chìm vào giấc ngủ là fall asleep.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_toothbrush', 'en-a1-9', 'toothbrush', '/ˈtuːθbrʌʃ/', 'A1', 'bàn chải đánh răng', 'n.', 'tooth (n.), brush (n.)', NULL, 'Dạng số nhiều là toothbrushes, không phải teethbrushes.', 'I packed my toothbrush in the side pocket.', NULL, 'Tôi đã xếp bàn chải đánh răng vào chiếc túi bên hông.', '{"wordId":"toothbrush","ukIpa":"/ˈtuːθbrʌʃ/","usIpa":"/ˈtuːθbrʌʃ/","cefr":"A1","topic":"health","senses":[{"pos":"n.","en":"A small brush used for cleaning your teeth.","vi":"bàn chải đánh răng"}],"examples":[{"en":"I packed my toothbrush in the side pocket.","vi":"Tôi đã xếp bàn chải đánh răng vào chiếc túi bên hông.","audioKind":"ex"},{"en":"Replacing a worn toothbrush regularly helps maintain oral hygiene by ensuring that teeth are cleaned effectively.","vi":"Thường xuyên thay bàn chải đánh răng đã mòn giúp duy trì vệ sinh răng miệng bằng cách đảm bảo răng được làm sạch hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"electric toothbrush","vi":"bàn chải đánh răng điện"},{"en":"soft toothbrush","vi":"bàn chải đánh răng lông mềm"},{"en":"toothbrush holder","vi":"giá đựng bàn chải đánh răng"}],"wordFamily":["tooth (n.)","brush (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là toothbrushes, không phải teethbrushes.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ear', 'en-a1-9', 'ear', '/ɪr/', 'A1', 'tai; khả năng nhận biết âm thanh; thính giác; bông (lúa); tai (cây ngũ cốc)', 'n.', NULL, NULL, 'have an ear for chỉ sự nhạy bén trong việc cảm thụ âm nhạc, ngôn ngữ, v.v.', 'My ears felt cold, so I pulled on a hat.', NULL, 'Tai tôi thấy lạnh nên tôi đã kéo đội một chiếc mũ lên.', '{"wordId":"ear","ukIpa":"/ɪə/","usIpa":"/ɪr/","cefr":"A1","topic":"health","senses":[{"pos":"n.","en":"One of the organs on your head used for hearing.","vi":"tai"},{"pos":"n.","en":"The ability to recognise and distinguish sounds.","vi":"khả năng nhận biết âm thanh; thính giác"},{"pos":"n.","en":"The grain-bearing part of a cereal plant, such as wheat.","vi":"bông (lúa); tai (cây ngũ cốc)"}],"examples":[{"en":"My ears felt cold, so I pulled on a hat.","vi":"Tai tôi thấy lạnh nên tôi đã kéo đội một chiếc mũ lên.","audioKind":"ex"},{"en":"Regular exposure to loud music can damage the ears and lead to permanent hearing loss.","vi":"Việc thường xuyên nghe nhạc âm lượng lớn có thể làm hỏng tai và dẫn đến mất thính lực vĩnh viễn.","audioKind":"ex2"}],"collocations":[{"en":"an ear for music","vi":"tai cảm thụ âm nhạc"},{"en":"ear infection","vi":"nhiễm trùng tai"},{"en":"an ear of wheat","vi":"một bông lúa mì"},{"en":"ear protection","vi":"thiết bị bảo vệ tai"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"have an ear for chỉ sự nhạy bén trong việc cảm thụ âm nhạc, ngôn ngữ, v.v.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_healthy', 'en-a1-9', 'healthy', '/ˈhelθi/', 'A1', 'khỏe mạnh; có lợi cho sức khỏe; lành mạnh; phát triển tốt; thịnh vượng; vững mạnh', 'adj.', 'health (n.), healthily (adv.), unhealthy (adj.)', 'Đồng nghĩa: well, fit · Trái nghĩa: unhealthy, ill', 'Có thể dùng để chỉ cơ thể khỏe mạnh hoặc chế độ ăn uống, lối sống có lợi cho sức khỏe.', 'Our cat stays healthy with regular exercise and checkups.', NULL, 'Con mèo của chúng tôi luôn khỏe mạnh nhờ tập thể dục thường xuyên và khám sức khỏe định kỳ.', '{"wordId":"healthy","ukIpa":"/ˈhelθi/","usIpa":"/ˈhelθi/","cefr":"A1","topic":"health","senses":[{"pos":"adj.","en":"physically well and not suffering from illness","vi":"khỏe mạnh"},{"pos":"adj.","en":"helping to maintain or improve health","vi":"có lợi cho sức khỏe; lành mạnh"},{"pos":"adj.","en":"successful, strong, or developing in a positive way","vi":"phát triển tốt; thịnh vượng; vững mạnh"}],"examples":[{"en":"Our cat stays healthy with regular exercise and checkups.","vi":"Con mèo của chúng tôi luôn khỏe mạnh nhờ tập thể dục thường xuyên và khám sức khỏe định kỳ.","audioKind":"ex"},{"en":"Schools should provide healthy meals to support children''s physical development and encourage better eating habits from an early age.","vi":"Các trường học nên cung cấp các bữa ăn lành mạnh để hỗ trợ sự phát triển thể chất của trẻ em và khuyến khích thói quen ăn uống tốt hơn từ khi còn nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"a healthy diet","vi":"chế độ ăn uống lành mạnh"},{"en":"a healthy lifestyle","vi":"lối sống lành mạnh"},{"en":"stay healthy","vi":"giữ gìn sức khỏe"},{"en":"a healthy economy","vi":"nền kinh tế thịnh vượng"}],"wordFamily":["health (n.)","healthily (adv.)","unhealthy (adj.)"],"synonyms":["well","fit"],"antonyms":["unhealthy","ill"],"tipVi":"Có thể dùng để chỉ cơ thể khỏe mạnh hoặc chế độ ăn uống, lối sống có lợi cho sức khỏe.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exercise', 'en-a1-9', 'exercise', '/ˈeksərsaɪz/', 'A1', 'sự vận động; bài tập; tập luyện; vận động; thực hiện; vận dụng', 'n.', NULL, NULL, 'Khi chỉ hoạt động thể chất nói chung, exercise là danh từ không đếm được; khi chỉ một bài tập hay động tác cụ thể thì đếm được.', 'I get some exercise by walking to the shops.', NULL, 'Tôi tập thể dục bằng cách đi bộ ra cửa hàng.', '{"wordId":"exercise","ukIpa":"/ˈeksəsaɪz/","usIpa":"/ˈeksərsaɪz/","cefr":"A1","topic":"health","senses":[{"pos":"n.","en":"Physical activity for health, or a task for practising skills.","vi":"sự vận động; bài tập"},{"pos":"v.","en":"To do physical activity to stay healthy or become stronger.","vi":"tập luyện; vận động"},{"pos":"v.","en":"To use a right, power, ability, or quality.","vi":"thực hiện; vận dụng"}],"examples":[{"en":"I get some exercise by walking to the shops.","vi":"Tôi tập thể dục bằng cách đi bộ ra cửa hàng.","audioKind":"ex"},{"en":"Regular exercise can improve mental health and reduce the risk of several common chronic diseases.","vi":"Thường xuyên tập thể dục có thể cải thiện sức khỏe tinh thần và giảm nguy cơ mắc một số bệnh mạn tính phổ biến.","audioKind":"ex2"}],"collocations":[{"en":"regular exercise","vi":"tập thể dục thường xuyên"},{"en":"do exercises","vi":"làm bài tập"},{"en":"exercise caution","vi":"thận trọng; cẩn trọng"},{"en":"exercise your rights","vi":"thực thi quyền lợi của bạn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ hoạt động thể chất nói chung, exercise là danh từ không đếm được; khi chỉ một bài tập hay động tác cụ thể thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fruit', 'en-a1-9', 'fruit', '/fruːt/', 'A1', 'trái cây; quả; thành quả; kết quả; ra quả; kết trái', 'n.', 'fruitful (adj.), fruitless (adj.), fruity (adj.)', NULL, 'Danh từ fruit khi chỉ chung loại quả thường không đếm được; fruits có thể dùng để chỉ các loại quả khác nhau hoặc thành quả.', 'She packed fresh fruit in my lunch box.', NULL, 'Cô ấy chuẩn bị trái cây tươi vào hộp cơm trưa cho tôi.', '{"wordId":"fruit","ukIpa":"/fruːt/","usIpa":"/fruːt/","cefr":"A1","topic":"health","senses":[{"pos":"n.","en":"Plant products containing seeds, often sweet and eaten as food.","vi":"trái cây; quả"},{"pos":"n.","en":"The useful results of work or effort.","vi":"thành quả; kết quả"},{"pos":"v.","en":"To produce fruit.","vi":"ra quả; kết trái"}],"examples":[{"en":"She packed fresh fruit in my lunch box.","vi":"Cô ấy chuẩn bị trái cây tươi vào hộp cơm trưa cho tôi.","audioKind":"ex"},{"en":"Making fresh fruit affordable could encourage healthier eating habits among families with limited incomes.","vi":"Việc làm cho trái cây tươi có giá cả phải chăng có thể khuyến khích thói quen ăn uống lành mạnh hơn ở các gia đình có thu nhập hạn hẹp.","audioKind":"ex2"}],"collocations":[{"en":"fresh fruit","vi":"trái cây tươi"},{"en":"fruit juice","vi":"nước ép trái cây"},{"en":"bear fruit","vi":"ra quả; đơm hoa kết trái"},{"en":"the fruits of your labour","vi":"thành quả lao động của bạn"}],"wordFamily":["fruitful (adj.)","fruitless (adj.)","fruity (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ fruit khi chỉ chung loại quả thường không đếm được; fruits có thể dùng để chỉ các loại quả khác nhau hoặc thành quả.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vegetable', 'en-a1-9', 'vegetable', '/ˈvedʒtəbl/', 'A1', 'rau; rau củ', 'n.', NULL, NULL, 'vegetable thường là danh từ đếm được; khi nói chung chung về rau củ thường dùng dạng số nhiều vegetables.', 'We bought fresh vegetables at the market this morning.', NULL, 'Chúng tôi đã mua rau tươi ở chợ vào sáng nay.', '{"wordId":"vegetable","ukIpa":"/ˈvedʒtəbl/","usIpa":"/ˈvedʒtəbl/","cefr":"A1","topic":"health","senses":[{"pos":"n.","en":"a plant or plant part eaten as food","vi":"rau; rau củ"}],"examples":[{"en":"We bought fresh vegetables at the market this morning.","vi":"Chúng tôi đã mua rau tươi ở chợ vào sáng nay.","audioKind":"ex"},{"en":"Schools can encourage healthier eating by serving a wider variety of vegetables at lunchtime.","vi":"Các trường học có thể khuyến khích ăn uống lành mạnh hơn bằng cách phục vụ đa dạng các loại rau hơn vào bữa trưa.","audioKind":"ex2"}],"collocations":[{"en":"fresh vegetables","vi":"rau tươi"},{"en":"leafy vegetables","vi":"rau lá xanh"},{"en":"vegetable soup","vi":"súp rau củ"},{"en":"vegetable garden","vi":"vườn rau"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"vegetable thường là danh từ đếm được; khi nói chung chung về rau củ thường dùng dạng số nhiều vegetables.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_9_1', 'en-a1-9', 'Cách dùng “exercise” (n.) — sự vận động; bài tập', 'regular exercise  ·  do exercises  ·  exercise caution', 'Khi chỉ hoạt động thể chất nói chung, exercise là danh từ không đếm được; khi chỉ một bài tập hay động tác cụ thể thì đếm được.', NULL, '[{"hanzi":"I get some exercise by walking to the shops.","pinyin":"","meaning":"Tôi tập thể dục bằng cách đi bộ ra cửa hàng."},{"hanzi":"Regular exercise can improve mental health and reduce the risk of several common chronic diseases.","pinyin":"","meaning":"Thường xuyên tập thể dục có thể cải thiện sức khỏe tinh thần và giảm nguy cơ mắc một số bệnh mạn tính phổ biến."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_9_2', 'en-a1-9', 'Cách dùng “fruit” (n.) — trái cây; quả', 'fresh fruit  ·  fruit juice  ·  bear fruit', 'Danh từ fruit khi chỉ chung loại quả thường không đếm được; fruits có thể dùng để chỉ các loại quả khác nhau hoặc thành quả.', 'Họ từ (Word Family): fruitful (adj.), fruitless (adj.), fruity (adj.)', '[{"hanzi":"She packed fresh fruit in my lunch box.","pinyin":"","meaning":"Cô ấy chuẩn bị trái cây tươi vào hộp cơm trưa cho tôi."},{"hanzi":"Making fresh fruit affordable could encourage healthier eating habits among families with limited incomes.","pinyin":"","meaning":"Việc làm cho trái cây tươi có giá cả phải chăng có thể khuyến khích thói quen ăn uống lành mạnh hơn ở các gia đình có thu nhập hạn hẹp."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_9_3', 'en-a1-9', 'Cách dùng “sugar” (n.) — đường; đường ăn', 'add sugar  ·  sugar intake  ·  blood sugar', 'Khi chỉ đường ăn nói chung, từ này thường không đếm được; cụm a spoonful of sugar có nghĩa là một muỗng đường.', 'Họ từ (Word Family): sugary (adj.), sugarless (adj.)', '[{"hanzi":"She stirred a spoonful of sugar into her tea.","pinyin":"","meaning":"Cô ấy khuấy một thìa đường vào ly trà của mình."},{"hanzi":"Reducing sugar consumption can help prevent health problems associated with an unhealthy diet.","pinyin":"","meaning":"Việc giảm tiêu thụ đường có thể giúp ngăn ngừa các vấn đề sức khỏe liên quan đến chế độ ăn uống không lành mạnh."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_9_4', 'en-a1-9', 'Cách dùng “walking” (n.) — sự đi bộ; việc đi dạo', 'go walking  ·  walking boots  ·  walking distance', 'Phụ âm l trong từ walking là âm câm; ngoài ra hành động đi bộ đến đâu cũng có thể diễn đạt bằng cụm on foot.', 'Họ từ (Word Family): walk (v.), walk (n.), walker (n.)', '[{"hanzi":"Walking to the shops takes about ten minutes.","pinyin":"","meaning":"Đi bộ ra các cửa hàng mất khoảng mười phút."},{"hanzi":"Cities can encourage walking by improving pavement quality and creating safer crossings near schools and shopping areas.","pinyin":"","meaning":"Các thành phố có thể khuyến khích người dân đi bộ bằng cách nâng cao chất lượng vỉa hè và bố trí các lối sang đường an toàn hơn gần trường học và khu mua sắm."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_9_1', 'en-a1-9', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_9_1_1', 'ten_9_1', 'body', 'My whole body aches after yesterday''s long walk.', 'My whole body aches after yesterday''s long walk.', '/ˈbɑːdi/', 'Toàn thân tôi ê ẩm sau chuyến đi bộ dài ngày hôm qua.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
