INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_9_1_1', 'en-a1-9', 'ten_9_1', 'listening', 'listening', 'My whole body aches after yesterday''s long walk.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã chuẩn bị đủ đồ ăn cho buổi dã ngoại bên hồ.","Toàn thân tôi ê ẩm sau chuyến đi bộ dài ngày hôm qua.","Tôi cảm thấy khát nước sau khi đi bộ dưới trời nắng về nhà.","Bác sĩ lắng nghe chăm chú khi tôi miêu tả các triệu chứng của mình."]'::jsonb, 1, 'My whole body aches after yesterday''s long walk. → Toàn thân tôi ê ẩm sau chuyến đi bộ dài ngày hôm qua.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
