INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_9_2_2', 'ten_9_2', 'nose', 'Wearing a mask over the nose and mouth can reduce exposure to airborne dust.', 'Wearing a mask over the nose and mouth can reduce exposure to airborne dust.', '/noʊz/', 'Đeo khẩu trang che kín mũi và miệng có thể làm giảm việc hít phải bụi trong không khí.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_9_2_3', 'ten_9_2', 'doctor', 'Governments should train more doctors to ensure that rural communities have reliable access to healthcare.', 'Governments should train more doctors to ensure that rural communities have reliable access to healthcare.', '/ˈdɑːk.tɚ/', 'Chính phủ nên đào tạo thêm bác sĩ để đảm bảo các vùng nông thôn có thể tiếp cận dịch vụ chăm sóc sức khỏe đáng tin cậy.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_9_2_4', 'ten_9_2', 'gym', 'Affordable gym membership can encourage regular exercise, although safe outdoor spaces are equally important for public health.', 'Affordable gym membership can encourage regular exercise, although safe outdoor spaces are equally important for public health.', '/dʒɪm/', 'Thẻ tập gym có giá cả phải chăng có thể khuyến khích việc tập luyện đều đặn, mặc dù không gian ngoài trời an toàn cũng quan trọng không kém đối với sức khỏe cộng đồng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_9_2_5', 'ten_9_2', 'hospital', 'Building a new hospital in the region would improve access to specialist care for rural communities.', 'Building a new hospital in the region would improve access to specialist care for rural communities.', '/ˈhɑːspɪtl/', 'Việc xây dựng một bệnh viện mới trong khu vực sẽ giúp người dân nông thôn tiếp cận tốt hơn với các dịch vụ y tế chuyên khoa.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_9_2_6', 'ten_9_2', 'sugar', 'Reducing sugar consumption can help prevent health problems associated with an unhealthy diet.', 'Reducing sugar consumption can help prevent health problems associated with an unhealthy diet.', '/ˈʃʊɡɚ/', 'Việc giảm tiêu thụ đường có thể giúp ngăn ngừa các vấn đề sức khỏe liên quan đến chế độ ăn uống không lành mạnh.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
