INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_9_2', 'en-a1-9', NULL, 'comprehensive_test', 'listening', 'My nose turned red in the cold wind.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã chuẩn bị đủ đồ ăn cho buổi dã ngoại bên hồ.","Mũi của tôi đỏ bừng lên trong gió lạnh.","Toàn thân tôi ê ẩm sau chuyến đi bộ dài ngày hôm qua.","Tai tôi thấy lạnh nên tôi đã kéo đội một chiếc mũ lên."]'::jsonb, 1, 'My nose turned red in the cold wind. → Mũi của tôi đỏ bừng lên trong gió lạnh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_9_3', 'en-a1-9', NULL, 'comprehensive_test', 'listening', 'doctor', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cuối cùng; gần đây nhất","bác sĩ","trở thành; trở nên","giáo viên; thầy cô giáo"]'::jsonb, 1, 'doctor (/ˈdɑːk.tɚ/) → bác sĩ; tiến sĩ; sửa đổi; làm giả', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_9_4', 'en-a1-9', NULL, 'comprehensive_test', 'listening', 'I usually go to the gym before work.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bậc thềm bị hỏng đó rất nguy hiểm, vì vậy xin hãy tránh xa nó ra.","Nha sĩ yêu cầu tôi há miệng to hơn nữa.","Tôi thường đi tập gym trước giờ làm việc.","Tai tôi thấy lạnh nên tôi đã kéo đội một chiếc mũ lên."]'::jsonb, 2, 'I usually go to the gym before work. → Tôi thường đi tập gym trước giờ làm việc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
