INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_9_6', 'en-a1-9', NULL, 'comprehensive_test', 'listening', 'She stirred a spoonful of sugar into her tea.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi cảm thấy quá mệt để nấu ăn sau khi đi bộ.","Tai tôi thấy lạnh nên tôi đã kéo đội một chiếc mũ lên.","Cô ấy khuấy một thìa đường vào ly trà của mình.","Bậc thềm bị hỏng đó rất nguy hiểm, vì vậy xin hãy tránh xa nó ra."]'::jsonb, 2, 'She stirred a spoonful of sugar into her tea. → Cô ấy khuấy một thìa đường vào ly trà của mình.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
