INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_9_8', 'en-a1-9', NULL, 'comprehensive_test', 'listening', 'We packed enough food for a picnic by the lake.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã chuẩn bị đủ đồ ăn cho buổi dã ngoại bên hồ.","Tôi tập thể dục bằng cách đi bộ ra cửa hàng.","Bậc thềm bị hỏng đó rất nguy hiểm, vì vậy xin hãy tránh xa nó ra.","Chúng tôi đã mua rau tươi ở chợ vào sáng nay."]'::jsonb, 0, 'We packed enough food for a picnic by the lake. → Chúng tôi đã chuẩn bị đủ đồ ăn cho buổi dã ngoại bên hồ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
