INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_9_18', 'en-a1-9', NULL, 'comprehensive_test', 'reading', NULL, 'An independent body should monitor water quality and publish its findings for the public.', 'Dựa vào câu trên, từ “body” có nghĩa phù hợp nhất là gì?', '["màu nâu","thân thể; cơ thể","lễ Giáng Sinh; mùa Giáng Sinh","câu lạc bộ; hội nhóm"]'::jsonb, 1, 'body: thân thể; cơ thể; tổ chức; cơ quan; thân bài; phần chính. Dịch cả câu: Một cơ quan độc lập nên giám sát chất lượng nước và công bố kết quả cho công chúng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_9_19', 'en-a1-9', NULL, 'comprehensive_test', 'reading', NULL, 'Wearing a mask over the nose and mouth can reduce exposure to airborne dust.', 'Dựa vào câu trên, từ “nose” có nghĩa phù hợp nhất là gì?', '["Nhật Bản","mũi (bộ phận trên khuôn mặt dùng để ngửi và thở)","phía bắc; phương bắc; miền bắc","ở bên ngoài; ra ngoài"]'::jsonb, 1, 'nose: mũi (bộ phận trên khuôn mặt dùng để ngửi và thở); phần mũi; phần phía trước của máy bay hoặc phương tiện tương tự. Dịch cả câu: Đeo khẩu trang che kín mũi và miệng có thể làm giảm việc hít phải bụi trong không khí.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_9_20', 'en-a1-9', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should train more doctors to ensure that rural communities have reliable access to healthcare.', 'Dựa vào câu trên, từ “doctor” có nghĩa phù hợp nhất là gì?', '["có thể xảy ra; có thể thực hiện được","bác sĩ","đi bộ","máy tính; vi tính"]'::jsonb, 1, 'doctor: bác sĩ; tiến sĩ; sửa đổi; làm giả. Dịch cả câu: Chính phủ nên đào tạo thêm bác sĩ để đảm bảo các vùng nông thôn có thể tiếp cận dịch vụ chăm sóc sức khỏe đáng tin cậy.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_9_21', 'en-a1-9', NULL, 'comprehensive_test', 'reading', NULL, 'Affordable gym membership can encourage regular exercise, although safe outdoor spaces are equally important for public health.', 'Dựa vào câu trên, từ “gym” có nghĩa phù hợp nhất là gì?', '["từ; đến từ","phòng tập thể hình; phòng gym","chắc chắn; tự tin","ở phía sau; đằng sau"]'::jsonb, 1, 'gym: phòng tập thể hình; phòng gym; giờ thể dục; môn thể dục ở trường. Dịch cả câu: Thẻ tập gym có giá cả phải chăng có thể khuyến khích việc tập luyện đều đặn, mặc dù không gian ngoài trời an toàn cũng quan trọng không kém đối với sức khỏe cộng đồng.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_9_22', 'en-a1-9', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự vận động; bài tập”', '["exercise","hard","dinner","much"]'::jsonb, 0, 'sự vận động; bài tập → exercise (/ˈeksərsaɪz/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_9_23', 'en-a1-9', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “trái cây; quả”', '["fruit","dog","rice","first"]'::jsonb, 0, 'trái cây; quả → fruit (/fruːt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_9_24', 'en-a1-9', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “rau; rau củ”', '["close","vegetable","cut","river"]'::jsonb, 1, 'rau; rau củ → vegetable (/ˈvedʒtəbl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-10', 'en', 'Bài 10: Nghệ thuật & Sáng tạo - CEFR A1', 'CEFR A1', 'A1 · Nghệ thuật', '23 từ vựng Tiếng Anh CEFR A1 chủ đề nghệ thuật & sáng tạo kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1010, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_paint', 'en-a1-10', 'paint', '/peɪnt/', 'A1', 'sơn; chất màu; quét sơn; sơn; vẽ tranh', 'n.', 'painter (n.), painting (n.), repaint (v.)', NULL, 'paint thường chỉ vẽ bằng màu nước/dầu; draw thường chỉ vẽ bằng bút chì hoặc đường nét.', 'There is blue paint all over your hands.', NULL, 'Có sơn màu xanh dính đầy trên tay bạn kìa.', '{"wordId":"paint","ukIpa":"/peɪnt/","usIpa":"/peɪnt/","cefr":"A1","topic":"arts","senses":[{"pos":"n.","en":"a coloured substance spread on surfaces for protection or decoration","vi":"sơn; chất màu"},{"pos":"v.","en":"to cover a surface with paint","vi":"quét sơn; sơn"},{"pos":"v.","en":"to create a picture using paint","vi":"vẽ tranh"}],"examples":[{"en":"There is blue paint all over your hands.","vi":"Có sơn màu xanh dính đầy trên tay bạn kìa.","audioKind":"ex"},{"en":"Schools should allow children to paint regularly, as creative activities can support emotional development and self-expression.","vi":"Nhà trường nên cho phép trẻ em vẽ tranh thường xuyên, bởi các hoạt động sáng tạo có thể hỗ trợ sự phát triển cảm xúc và khả năng thể hiện bản thân.","audioKind":"ex2"}],"collocations":[{"en":"wet paint","vi":"sơn chưa khô"},{"en":"a coat of paint","vi":"một lớp sơn"},{"en":"paint a picture","vi":"vẽ một bức tranh"},{"en":"paint a wall","vi":"sơn một bức tường"}],"wordFamily":["painter (n.)","painting (n.)","repaint (v.)"],"synonyms":[],"antonyms":[],"tipVi":"paint thường chỉ vẽ bằng màu nước/dầu; draw thường chỉ vẽ bằng bút chì hoặc đường nét.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_picture', 'en-a1-10', 'picture', '/ˈpɪktʃər/', 'A1', 'bức tranh; hình ảnh; bức ảnh; tình hình; bức tranh tổng thể; tưởng tượng; hình dung', 'n.', 'pictorial (adj.)', 'Đồng nghĩa: image', 'take a picture là chụp ảnh; draw a picture là vẽ tranh.', 'She hung a picture of the sea above her bed.', NULL, 'Cô ấy treo một bức tranh phong cảnh biển phía trên giường của mình.', '{"wordId":"picture","ukIpa":"/ˈpɪktʃə/","usIpa":"/ˈpɪktʃər/","cefr":"A1","topic":"arts","senses":[{"pos":"n.","en":"an image made by drawing, painting, or taking a photograph","vi":"bức tranh; hình ảnh; bức ảnh"},{"pos":"n.","en":"an idea or description of what a situation is like","vi":"tình hình; bức tranh tổng thể"},{"pos":"v.","en":"to form an image of someone or something in your mind","vi":"tưởng tượng; hình dung"}],"examples":[{"en":"She hung a picture of the sea above her bed.","vi":"Cô ấy treo một bức tranh phong cảnh biển phía trên giường của mình.","audioKind":"ex"},{"en":"Survey results provide a clearer picture of how housing costs affect the wellbeing of young adults.","vi":"Kết quả khảo sát mang lại cái nhìn rõ ràng hơn về việc chi phí nhà ở ảnh hưởng như thế nào đến sự hạnh phúc của người trưởng thành trẻ tuổi.","audioKind":"ex2"}],"collocations":[{"en":"take a picture","vi":"chụp ảnh"},{"en":"a clear picture","vi":"một cái nhìn rõ ràng"},{"en":"the bigger picture","vi":"bức tranh toàn cảnh; tổng thể vấn đề"},{"en":"picture yourself doing something","vi":"tưởng tượng bản thân đang làm gì"}],"wordFamily":["pictorial (adj.)"],"synonyms":["image"],"antonyms":[],"tipVi":"take a picture là chụp ảnh; draw a picture là vẽ tranh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_guitar', 'en-a1-10', 'guitar', '/ɡɪˈtɑːr/', 'A1', 'đàn ghi-ta; đàn guitar', 'n.', 'guitarist (n.)', NULL, 'Khi nói chơi đàn guitar, thường dùng play the guitar.', 'My sister plays the guitar beside the window every evening.', NULL, 'Chị gái tôi chơi đàn ghi-ta bên cửa sổ vào mỗi buổi tối.', '{"wordId":"guitar","ukIpa":"/ɡɪˈtɑː/","usIpa":"/ɡɪˈtɑːr/","cefr":"A1","topic":"arts","senses":[{"pos":"n.","en":"A stringed musical instrument played by plucking or strumming.","vi":"đàn ghi-ta; đàn guitar"}],"examples":[{"en":"My sister plays the guitar beside the window every evening.","vi":"Chị gái tôi chơi đàn ghi-ta bên cửa sổ vào mỗi buổi tối.","audioKind":"ex"},{"en":"Learning to play the guitar can help students develop patience, coordination, and confidence through regular practice.","vi":"Học chơi đàn ghi-ta có thể giúp học sinh rèn luyện tính kiên nhẫn, sự phối hợp nhịp nhàng và sự tự tin thông qua việc luyện tập thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"play the guitar","vi":"chơi đàn guitar"},{"en":"acoustic guitar","vi":"đàn guitar thùng"},{"en":"electric guitar","vi":"đàn guitar điện"},{"en":"guitar strings","vi":"dây đàn guitar"}],"wordFamily":["guitarist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi nói chơi đàn guitar, thường dùng play the guitar.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_band', 'en-a1-10', 'band', '/bænd/', 'A1', 'ban nhạc; nhóm nhạc; dải; vòng; đai (bằng vật liệu hoặc màu sắc); khoảng; dải tần số; mức; bậc', 'n.', 'banded (adj.), banding (n.)', NULL, 'Trong IELTS, band chỉ mức điểm hoặc bậc, không phải ban nhạc.', 'My sister plays the drums in a local band.', NULL, 'Chị gái tôi chơi trống trong một ban nhạc địa phương.', '{"wordId":"band","ukIpa":"/bænd/","usIpa":"/bænd/","cefr":"A1","topic":"arts","senses":[{"pos":"n.","en":"A group of musicians who perform together.","vi":"ban nhạc; nhóm nhạc"},{"pos":"n.","en":"A narrow strip or ring of material or colour.","vi":"dải; vòng; đai (bằng vật liệu hoặc màu sắc)"},{"pos":"n.","en":"A range of frequencies, values, or levels within a system.","vi":"khoảng; dải tần số; mức; bậc"}],"examples":[{"en":"My sister plays the drums in a local band.","vi":"Chị gái tôi chơi trống trong một ban nhạc địa phương.","audioKind":"ex"},{"en":"Live bands at community festivals can attract visitors and create opportunities for local businesses.","vi":"Các ban nhạc biểu diễn trực tiếp tại lễ hội cộng đồng có thể thu hút khách du lịch và tạo cơ hội cho các doanh nghiệp địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a rock band","vi":"ban nhạc rock"},{"en":"a rubber band","vi":"dây thun; dây cao su"},{"en":"a frequency band","vi":"dải tần số"},{"en":"an income band","vi":"khoảng thu nhập"}],"wordFamily":["banded (adj.)","banding (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong IELTS, band chỉ mức điểm hoặc bậc, không phải ban nhạc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_painting', 'en-a1-10', 'painting', '/ˈpeɪntɪŋ/', 'A1', 'bức tranh; tác phẩm hội họa; nghệ thuật vẽ tranh; việc sơn quét; việc sơn tường', 'n.', 'paint (v.), paint (n.), painter (n.)', 'Đồng nghĩa: artwork', 'Chỉ một bức tranh thì đếm được; chỉ hoạt động hội họa thì không đếm được.', 'We hung a colourful painting above the sofa.', NULL, 'Chúng tôi treo một bức tranh đầy màu sắc phía trên chiếc ghế sofa.', '{"wordId":"painting","ukIpa":"/ˈpeɪntɪŋ/","usIpa":"/ˈpeɪntɪŋ/","cefr":"A1","topic":"arts","senses":[{"pos":"n.","en":"A picture made using paint.","vi":"bức tranh; tác phẩm hội họa"},{"pos":"n.","en":"The activity of creating pictures with paint.","vi":"nghệ thuật vẽ tranh"},{"pos":"n.","en":"The activity of covering a surface with paint.","vi":"việc sơn quét; việc sơn tường"}],"examples":[{"en":"We hung a colourful painting above the sofa.","vi":"Chúng tôi treo một bức tranh đầy màu sắc phía trên chiếc ghế sofa.","audioKind":"ex"},{"en":"Public galleries make important paintings accessible to everyone, regardless of their income or educational background.","vi":"Các phòng trưng bày nghệ thuật công cộng giúp mọi người đều có thể tiếp cận các bức tranh quý giá, không phân biệt thu nhập hay nền tảng giáo dục.","audioKind":"ex2"}],"collocations":[{"en":"oil painting","vi":"tranh sơn dầu"},{"en":"landscape painting","vi":"tranh phong cảnh"},{"en":"abstract painting","vi":"tranh trừu tượng"},{"en":"house painting","vi":"việc sơn nhà"}],"wordFamily":["paint (v.)","paint (n.)","painter (n.)"],"synonyms":["artwork"],"antonyms":[],"tipVi":"Chỉ một bức tranh thì đếm được; chỉ hoạt động hội họa thì không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_music', 'en-a1-10', 'music', '/ˈmjuːzɪk/', 'A1', 'âm nhạc; giai điệu; bản nhạc; bản giao hưởng', 'n.', 'musical (adj.), musician (n.), musically (adv.)', NULL, 'music là danh từ không đếm được; để chỉ một bản nhạc cụ thể, dùng cụm a piece of music.', 'Soft music drifted through the kitchen while we cooked.', NULL, 'Âm nhạc du dương vang lên trong căn bếp khi chúng tôi nấu ăn.', '{"wordId":"music","ukIpa":"/ˈmjuːzɪk/","usIpa":"/ˈmjuːzɪk/","cefr":"A1","topic":"arts","senses":[{"pos":"n.","en":"Sounds arranged with rhythm or melody for people to enjoy","vi":"âm nhạc; giai điệu"},{"pos":"n.","en":"Written symbols showing how a piece should be played or sung","vi":"bản nhạc; bản giao hưởng"}],"examples":[{"en":"Soft music drifted through the kitchen while we cooked.","vi":"Âm nhạc du dương vang lên trong căn bếp khi chúng tôi nấu ăn.","audioKind":"ex"},{"en":"Learning music at school can develop children''s creativity and provide opportunities for cooperation through group performances.","vi":"Học nhạc ở trường có thể phát triển sự sáng tạo của trẻ em và tạo cơ hội hợp tác thông qua các buổi biểu diễn nhóm.","audioKind":"ex2"}],"collocations":[{"en":"listen to music","vi":"nghe nhạc"},{"en":"live music","vi":"nhạc sống"},{"en":"classical music","vi":"nhạc cổ điển"},{"en":"a piece of music","vi":"một bản nhạc"}],"wordFamily":["musical (adj.)","musician (n.)","musically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"music là danh từ không đếm được; để chỉ một bản nhạc cụ thể, dùng cụm a piece of music.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_actor', 'en-a1-10', 'actor', '/ˈæktər/', 'A1', 'diễn viên; người tham gia; bên tham gia', 'n.', 'act (v.), acting (n.), actress (n.)', 'Đồng nghĩa: performer', 'actor có thể chỉ diễn viên ở mọi giới tính; actress dùng riêng cho nữ diễn viên.', 'The actor wore a silver crown on stage.', NULL, 'Nam diễn viên đội chiếc vương miện bằng bạc trên sân khấu.', '{"wordId":"actor","ukIpa":"/ˈæktə/","usIpa":"/ˈæktər/","cefr":"A1","topic":"arts","senses":[{"pos":"n.","en":"Someone who performs characters in plays, films, or television","vi":"diễn viên"},{"pos":"n.","en":"A person or organisation involved in a particular situation","vi":"người tham gia; bên tham gia"}],"examples":[{"en":"The actor wore a silver crown on stage.","vi":"Nam diễn viên đội chiếc vương miện bằng bạc trên sân khấu.","audioKind":"ex"},{"en":"Professional actors can help students develop communication skills through drama workshops that encourage teamwork and creative expression.","vi":"Các diễn viên chuyên nghiệp có thể giúp học sinh phát triển kỹ năng giao tiếp thông qua các buổi hội thảo kịch nghệ nhằm khuyến khích tinh thần làm việc nhóm và biểu đạt sáng tạo.","audioKind":"ex2"}],"collocations":[{"en":"a leading actor","vi":"diễn viên chính"},{"en":"a professional actor","vi":"diễn viên chuyên nghiệp"},{"en":"a supporting actor","vi":"diễn viên phụ"},{"en":"a key actor","vi":"nhân tố quan trọng"}],"wordFamily":["act (v.)","acting (n.)","actress (n.)"],"synonyms":["performer"],"antonyms":[],"tipVi":"actor có thể chỉ diễn viên ở mọi giới tính; actress dùng riêng cho nữ diễn viên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_art', 'en-a1-10', 'art', '/ɑːrt/', 'A1', 'nghệ thuật; mỹ thuật; tác phẩm nghệ thuật; kỹ năng; nghệ thuật (phương pháp tinh tế)', 'n.', 'artist (n.), artistic (adj.), artistically (adv.)', NULL, 'art chỉ nghệ thuật thường không đếm được; một tác phẩm cụ thể dùng a work of art.', 'We spent the afternoon making art with coloured paper.', NULL, 'Chúng tôi đã dành cả buổi chiều để làm nghệ thuật bằng giấy màu.', '{"wordId":"art","ukIpa":"/ɑːt/","usIpa":"/ɑːrt/","cefr":"A1","topic":"arts","senses":[{"pos":"n.","en":"creative expression through activities such as painting, sculpture, or drawing","vi":"nghệ thuật; mỹ thuật"},{"pos":"n.","en":"objects or images created to express ideas or beauty","vi":"tác phẩm nghệ thuật"},{"pos":"n.","en":"a skill developed through practice and careful understanding","vi":"kỹ năng; nghệ thuật (phương pháp tinh tế)"}],"examples":[{"en":"We spent the afternoon making art with coloured paper.","vi":"Chúng tôi đã dành cả buổi chiều để làm nghệ thuật bằng giấy màu.","audioKind":"ex"},{"en":"Public funding for art can enrich community life and make cultural experiences accessible to a wider audience.","vi":"Nguồn tài trợ công cho nghệ thuật có thể làm phong phú đời sống cộng đồng và giúp công chúng tiếp cận rộng rãi hơn với các trải nghiệm văn hóa.","audioKind":"ex2"}],"collocations":[{"en":"a work of art","vi":"một tác phẩm nghệ thuật"},{"en":"modern art","vi":"nghệ thuật hiện đại"},{"en":"an art gallery","vi":"phòng trưng bày nghệ thuật"},{"en":"the art of conversation","vi":"nghệ thuật trò chuyện"}],"wordFamily":["artist (n.)","artistic (adj.)","artistically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"art chỉ nghệ thuật thường không đếm được; một tác phẩm cụ thể dùng a work of art.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_museum', 'en-a1-10', 'museum', '/mjuˈziːəm/', 'A1', 'viện bảo tàng', 'n.', NULL, NULL, 'museum là danh từ đếm được; đi thăm bảo tàng nói visit a museum.', 'We saw a huge dinosaur skeleton at the museum.', NULL, 'Chúng tôi đã nhìn thấy bộ xương khủng long khổng lồ tại viện bảo tàng.', '{"wordId":"museum","ukIpa":"/mjuˈziːəm/","usIpa":"/mjuˈziːəm/","cefr":"A1","topic":"arts","senses":[{"pos":"n.","en":"a building displaying objects of historical, scientific, or artistic interest","vi":"viện bảo tàng"}],"examples":[{"en":"We saw a huge dinosaur skeleton at the museum.","vi":"Chúng tôi đã nhìn thấy bộ xương khủng long khổng lồ tại viện bảo tàng.","audioKind":"ex"},{"en":"Museums can help young people understand local history by connecting everyday objects with the lives of previous generations.","vi":"Các bảo tàng có thể giúp người trẻ hiểu về lịch sử địa phương bằng cách kết nối các đồ vật hàng ngày với cuộc sống của các thế hệ trước.","audioKind":"ex2"}],"collocations":[{"en":"visit a museum","vi":"thăm bảo tàng"},{"en":"natural history museum","vi":"bảo tàng lịch sử tự nhiên"},{"en":"museum collection","vi":"bộ sưu tập của bảo tàng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"museum là danh từ đếm được; đi thăm bảo tàng nói visit a museum.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_artist', 'en-a1-10', 'artist', '/ˈɑːrtɪst/', 'A1', 'nghệ sĩ; họa sĩ; nghệ sĩ biểu diễn; ca sĩ', 'n.', 'art (n.), artistic (adj.), artistically (adv.)', NULL, '"artist" chỉ nghệ sĩ; "artistic" là tính từ nghĩa là "thuộc về nghệ thuật".', 'The artist painted the harbour in soft blue colours.', NULL, 'Người họa sĩ đã vẽ bến cảng bằng những gam màu xanh dịu mắt.', '{"wordId":"artist","ukIpa":"/ˈɑːtɪst/","usIpa":"/ˈɑːrtɪst/","cefr":"A1","topic":"arts","senses":[{"pos":"n.","en":"a person who creates paintings, sculptures, or other art","vi":"nghệ sĩ; họa sĩ"},{"pos":"n.","en":"a person who performs music or other entertainment professionally","vi":"nghệ sĩ biểu diễn; ca sĩ"}],"examples":[{"en":"The artist painted the harbour in soft blue colours.","vi":"Người họa sĩ đã vẽ bến cảng bằng những gam màu xanh dịu mắt.","audioKind":"ex"},{"en":"Public funding allows an artist to create work that enriches community life without depending entirely on sales.","vi":"Nguồn tài trợ công cho phép nghệ sĩ sáng tạo những tác phẩm làm phong phú đời sống cộng đồng mà không phải phụ thuộc hoàn toàn vào doanh thu.","audioKind":"ex2"}],"collocations":[{"en":"professional artist","vi":"nghệ sĩ chuyên nghiệp"},{"en":"local artist","vi":"nghệ sĩ địa phương"},{"en":"recording artist","vi":"nghệ sĩ thu âm"},{"en":"talented artist","vi":"nghệ sĩ tài năng"}],"wordFamily":["art (n.)","artistic (adj.)","artistically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"\"artist\" chỉ nghệ sĩ; \"artistic\" là tính từ nghĩa là \"thuộc về nghệ thuật\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_piano', 'en-a1-10', 'piano', '/piˈænoʊ/', 'A1', 'đàn piano; dương cầm', 'n.', 'pianist (n.)', NULL, 'Nói chơi đàn piano thường dùng play the piano.', 'My sister practises the piano after dinner every evening.', NULL, 'Chị tôi tập đàn piano sau bữa tối mỗi ngày.', '{"wordId":"piano","ukIpa":"/piˈænəʊ/","usIpa":"/piˈænoʊ/","cefr":"A1","topic":"arts","senses":[{"pos":"n.","en":"A large musical instrument played by pressing black and white keys.","vi":"đàn piano; dương cầm"}],"examples":[{"en":"My sister practises the piano after dinner every evening.","vi":"Chị tôi tập đàn piano sau bữa tối mỗi ngày.","audioKind":"ex"},{"en":"Learning to play the piano can help children develop concentration and express their emotions creatively.","vi":"Học chơi đàn piano có thể giúp trẻ em phát triển khả năng tập trung và bộc lộ cảm xúc một cách sáng tạo.","audioKind":"ex2"}],"collocations":[{"en":"play the piano","vi":"chơi đàn piano"},{"en":"piano lessons","vi":"các buổi học piano"},{"en":"grand piano","vi":"đàn đại dương cầm"}],"wordFamily":["pianist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nói chơi đàn piano thường dùng play the piano.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_photograph', 'en-a1-10', 'photograph', '/ˈfoʊtəɡræf/', 'A1', 'bức ảnh; bức hình; chụp ảnh; chụp hình', 'n.', 'photography (n.), photographer (n.), photographic (adj.)', 'Đồng nghĩa: photo, picture', 'Dùng take a photograph khi nói về hành động chụp ảnh, không dùng make.', 'This photograph shows my grandparents standing beside their first house.', NULL, 'Bức ảnh này chụp ông bà tôi đang đứng bên ngôi nhà đầu tiên của họ.', '{"wordId":"photograph","ukIpa":"/ˈfəʊtəɡrɑːf/","usIpa":"/ˈfoʊtəɡræf/","cefr":"A1","topic":"arts","senses":[{"pos":"n.","en":"a picture made using a camera","vi":"bức ảnh; bức hình"},{"pos":"v.","en":"to take a picture of someone or something using a camera","vi":"chụp ảnh; chụp hình"}],"examples":[{"en":"This photograph shows my grandparents standing beside their first house.","vi":"Bức ảnh này chụp ông bà tôi đang đứng bên ngôi nhà đầu tiên của họ.","audioKind":"ex"},{"en":"Historical photographs provide valuable evidence of how urban landscapes and everyday lifestyles have changed over time.","vi":"Những bức ảnh lịch sử cung cấp bằng chứng quý giá về sự thay đổi của cảnh quan đô thị và lối sống hằng ngày theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"take a photograph","vi":"chụp một bức ảnh"},{"en":"a family photograph","vi":"ảnh gia đình"},{"en":"a black-and-white photograph","vi":"bức ảnh trắng đen"}],"wordFamily":["photography (n.)","photographer (n.)","photographic (adj.)"],"synonyms":["photo","picture"],"antonyms":[],"tipVi":"Dùng take a photograph khi nói về hành động chụp ảnh, không dùng make.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_singer', 'en-a1-10', 'singer', '/ˈsɪŋər/', 'A1', 'ca sĩ', 'n.', 'sing (v.), singing (n.)', 'Đồng nghĩa: vocalist', 'Quá khứ và quá khứ phân từ của sing lần lượt là sang và sung.', 'The singer smiled as the audience began to clap.', NULL, 'Nữ ca sĩ mỉm cười khi khán giả bắt đầu vỗ tay.', '{"wordId":"singer","ukIpa":"/ˈsɪŋə/","usIpa":"/ˈsɪŋər/","cefr":"A1","topic":"arts","senses":[{"pos":"n.","en":"A person who sings, especially as a job.","vi":"ca sĩ"}],"examples":[{"en":"The singer smiled as the audience began to clap.","vi":"Nữ ca sĩ mỉm cười khi khán giả bắt đầu vỗ tay.","audioKind":"ex"},{"en":"Local festivals provide young singers with valuable opportunities to perform publicly and develop confidence in their abilities.","vi":"Các lễ hội địa phương mang đến cho các ca sĩ trẻ cơ hội quý giá để biểu diễn trước công chúng và vun đắp sự tự tin vào năng lực của bản thân.","audioKind":"ex2"}],"collocations":[{"en":"lead singer","vi":"ca sĩ hát chính"},{"en":"professional singer","vi":"ca sĩ chuyên nghiệp"},{"en":"opera singer","vi":"ca sĩ opera"}],"wordFamily":["sing (v.)","singing (n.)"],"synonyms":["vocalist"],"antonyms":[],"tipVi":"Quá khứ và quá khứ phân từ của sing lần lượt là sang và sung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dance', 'en-a1-10', 'dance', '/dæns/', 'A1', 'nhảy múa; khiêu vũ; điệu nhảy; vũ đạo; buổi khiêu vũ', 'v.', 'dancer (n.), dancing (n.)', NULL, 'Diễn đạt nhảy theo điệu nhạc dùng dance to music, đi kèm giới từ to.', 'We danced in the kitchen while dinner was cooking.', NULL, 'Chúng tôi đã nhảy múa trong bếp trong lúc bữa tối đang được nấu.', '{"wordId":"dance","ukIpa":"/dɑːns/","usIpa":"/dæns/","cefr":"A1","topic":"arts","senses":[{"pos":"v.","en":"to move your body rhythmically, usually to music","vi":"nhảy múa; khiêu vũ"},{"pos":"n.","en":"rhythmic movement to music, or an event for dancing","vi":"điệu nhảy; vũ đạo; buổi khiêu vũ"}],"examples":[{"en":"We danced in the kitchen while dinner was cooking.","vi":"Chúng tôi đã nhảy múa trong bếp trong lúc bữa tối đang được nấu.","audioKind":"ex"},{"en":"Traditional dance can strengthen community identity while offering younger generations a connection to their cultural heritage.","vi":"Múa truyền thống có thể củng cố bản sắc cộng đồng đồng thời kết nối thế hệ trẻ với di sản văn hóa của họ.","audioKind":"ex2"}],"collocations":[{"en":"dance to music","vi":"nhảy theo điệu nhạc"},{"en":"traditional dance","vi":"múa truyền thống"},{"en":"dance class","vi":"lớp học nhảy"},{"en":"go dancing","vi":"đi khiêu vũ"}],"wordFamily":["dancer (n.)","dancing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Diễn đạt nhảy theo điệu nhạc dùng dance to music, đi kèm giới từ to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_draw', 'en-a1-10', 'draw', '/drɔː/', 'A1', 'vẽ; phác họa; kéo; lôi kéo; thu hút; gây sự chú ý', 'v.', 'drawing (n.)', 'Đồng nghĩa: sketch, pull, attract', 'Quá khứ là drew, quá khứ phân từ là drawn; ngoài ra từ này còn có thể chỉ kết quả hòa trong thể thao.', 'She drew a sleeping cat in her sketchbook.', NULL, 'Cô ấy vẽ một chú mèo đang ngủ trong sổ phác thảo của mình.', '{"wordId":"draw","ukIpa":"/drɔː/","usIpa":"/drɔː/","cefr":"A1","topic":"arts","senses":[{"pos":"v.","en":"Make a picture using a pencil, pen, or similar tool.","vi":"vẽ; phác họa"},{"pos":"v.","en":"Move something by pulling it in a particular direction.","vi":"kéo; lôi kéo"},{"pos":"v.","en":"Attract people, interest, or attention to something.","vi":"thu hút; gây sự chú ý"}],"examples":[{"en":"She drew a sleeping cat in her sketchbook.","vi":"Cô ấy vẽ một chú mèo đang ngủ trong sổ phác thảo của mình.","audioKind":"ex"},{"en":"Free cultural events can draw more visitors to museums and encourage wider participation in the arts.","vi":"Các sự kiện văn hóa miễn phí có thể thu hút nhiều du khách hơn đến với các bảo tàng và khuyến khích người dân tham gia nghệ thuật rộng rãi hơn.","audioKind":"ex2"}],"collocations":[{"en":"draw a picture","vi":"vẽ một bức tranh"},{"en":"draw attention to","vi":"thu hút sự chú ý vào"},{"en":"draw a conclusion","vi":"đưa ra kết luận"},{"en":"draw the curtains","vi":"kéo rèm cửa"}],"wordFamily":["drawing (n.)"],"synonyms":["sketch","pull","attract"],"antonyms":[],"tipVi":"Quá khứ là drew, quá khứ phân từ là drawn; ngoài ra từ này còn có thể chỉ kết quả hòa trong thể thao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_movie', 'en-a1-10', 'movie', '/ˈmuːvi/', 'A1', 'phim; điện ảnh', 'n.', NULL, 'Đồng nghĩa: film', 'movie thiên về tiếng Mỹ, tiếng Anh-Anh thường dùng film; the movies có thể chỉ rạp chiếu phim.', 'We watched a funny movie after dinner last night.', NULL, 'Chúng tôi đã xem một bộ phim hài sau bữa tối tối qua.', '{"wordId":"movie","ukIpa":"/ˈmuːvi/","usIpa":"/ˈmuːvi/","cefr":"A1","topic":"arts","senses":[{"pos":"n.","en":"a recorded story or sequence of moving images for watching","vi":"phim; điện ảnh"}],"examples":[{"en":"We watched a funny movie after dinner last night.","vi":"Chúng tôi đã xem một bộ phim hài sau bữa tối tối qua.","audioKind":"ex"},{"en":"Movies can introduce audiences to unfamiliar cultures, although they sometimes reinforce stereotypes rather than challenge them.","vi":"Phim ảnh có thể giới thiệu cho khán giả những nền văn hóa xa lạ, mặc dù đôi khi chúng củng cố các định kiến thay vì thách thức chúng.","audioKind":"ex2"}],"collocations":[{"en":"watch a movie","vi":"xem phim"},{"en":"movie star","vi":"ngôi sao điện ảnh"},{"en":"movie theatre","vi":"rạp chiếu phim"},{"en":"go to the movies","vi":"đi xem phim"}],"wordFamily":[],"synonyms":["film"],"antonyms":[],"tipVi":"movie thiên về tiếng Mỹ, tiếng Anh-Anh thường dùng film; the movies có thể chỉ rạp chiếu phim.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_film', 'en-a1-10', 'film', '/fɪlm/', 'A1', 'phim; phim điện ảnh; quay phim; chụp hình; màng mỏng; phim chụp ảnh', 'n.', 'filmmaker (n.), filming (n.)', 'Đồng nghĩa: movie', 'Khi chỉ phim ảnh, film phổ biến trong tiếng Anh-Anh, còn movie phổ biến trong tiếng Anh-Mỹ.', 'We watched a funny film after dinner yesterday.', NULL, 'Chúng tôi đã xem một bộ phim hài sau bữa tối ngày hôm qua.', '{"wordId":"film","ukIpa":"/fɪlm/","usIpa":"/fɪlm/","cefr":"A1","topic":"arts","senses":[{"pos":"n.","en":"a story or events recorded as moving pictures","vi":"phim; phim điện ảnh"},{"pos":"v.","en":"to record moving pictures using a camera","vi":"quay phim; chụp hình"},{"pos":"n.","en":"a thin layer, or material used to record photographs","vi":"màng mỏng; phim chụp ảnh"}],"examples":[{"en":"We watched a funny film after dinner yesterday.","vi":"Chúng tôi đã xem một bộ phim hài sau bữa tối ngày hôm qua.","audioKind":"ex"},{"en":"Documentary films can raise public awareness of environmental problems by showing their effects on local communities.","vi":"Phim tài liệu có thể nâng cao nhận thức của công chúng về các vấn đề môi trường bằng cách cho thấy tác động của chúng đối với cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"watch a film","vi":"xem phim"},{"en":"film industry","vi":"ngành công nghiệp điện ảnh"},{"en":"a thin film of oil","vi":"một lớp màng dầu mỏng"}],"wordFamily":["filmmaker (n.)","filming (n.)"],"synonyms":["movie"],"antonyms":[],"tipVi":"Khi chỉ phim ảnh, film phổ biến trong tiếng Anh-Anh, còn movie phổ biến trong tiếng Anh-Mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_story', 'en-a1-10', 'story', '/ˈstɔːri/', 'A1', 'câu chuyện; chuyện kể; bài báo; bản tin; tầng (nhà)', 'n.', 'storyteller (n.), storytelling (n.)', 'Đồng nghĩa: tale, account', 'Từ chỉ tầng nhà tiếng Anh-Anh viết là storey, tiếng Anh-Mỹ viết là story; chiều cao không cố định.', 'Grandma told us a funny story about her childhood.', NULL, 'Bà đã kể cho chúng tôi nghe một câu chuyện thú vị về thời thơ ấu của bà.', '{"wordId":"story","ukIpa":"/ˈstɔːri/","usIpa":"/ˈstɔːri/","cefr":"A1","topic":"arts","senses":[{"pos":"n.","en":"an account of real or imagined events","vi":"câu chuyện; chuyện kể"},{"pos":"n.","en":"a report about an event in the news","vi":"bài báo; bản tin"},{"pos":"n.","en":"one level of a building, in American English","vi":"tầng (nhà)"}],"examples":[{"en":"Grandma told us a funny story about her childhood.","vi":"Bà đã kể cho chúng tôi nghe một câu chuyện thú vị về thời thơ ấu của bà.","audioKind":"ex"},{"en":"Sharing a personal story can help students understand historical events from a more human perspective.","vi":"Việc chia sẻ một câu chuyện cá nhân có thể giúp học sinh hiểu các sự kiện lịch sử từ góc nhìn mang tính nhân văn hơn.","audioKind":"ex2"}],"collocations":[{"en":"tell a story","vi":"kể chuyện"},{"en":"short story","vi":"truyện ngắn"},{"en":"news story","vi":"bản tin thời sự"},{"en":"true story","vi":"câu chuyện có thật"}],"wordFamily":["storyteller (n.)","storytelling (n.)"],"synonyms":["tale","account"],"antonyms":[],"tipVi":"Từ chỉ tầng nhà tiếng Anh-Anh viết là storey, tiếng Anh-Mỹ viết là story; chiều cao không cố định.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_italian', 'en-a1-10', 'Italian', '/ɪˈtæljən/', 'A1', 'thuộc Ý; thuộc tiếng Ý; tiếng Ý; người Ý', 'adj.', NULL, NULL, 'Tên quốc gia và ngôn ngữ viết hoa chữ cái đầu; danh từ chỉ người Ý số nhiều là Italians.', 'We cooked Italian pasta with tomatoes and fresh basil.', NULL, 'Chúng tôi đã nấu món mì Ý với cà chua và rau húng quế tươi.', '{"wordId":"italian","ukIpa":"/ɪˈtæliən/","usIpa":"/ɪˈtæljən/","cefr":"A1","topic":"arts","senses":[{"pos":"adj.","en":"Relating to Italy, its people, culture, or language","vi":"thuộc Ý; thuộc tiếng Ý"},{"pos":"n.","en":"The main language spoken in Italy","vi":"tiếng Ý"},{"pos":"n.","en":"A person from Italy","vi":"người Ý"}],"examples":[{"en":"We cooked Italian pasta with tomatoes and fresh basil.","vi":"Chúng tôi đã nấu món mì Ý với cà chua và rau húng quế tươi.","audioKind":"ex"},{"en":"Studying Italian architecture can help students understand how historical buildings influence contemporary urban design.","vi":"Việc nghiên cứu kiến trúc Ý có thể giúp học sinh hiểu được cách các công trình lịch sử ảnh hưởng đến thiết kế đô thị đương đại.","audioKind":"ex2"}],"collocations":[{"en":"Italian cuisine","vi":"ẩm thực Ý"},{"en":"speak Italian","vi":"nói tiếng Ý"},{"en":"Italian architecture","vi":"kiến trúc Ý"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tên quốc gia và ngôn ngữ viết hoa chữ cái đầu; danh từ chỉ người Ý số nhiều là Italians.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dancing', 'en-a1-10', 'dancing', '/ˈdænsɪŋ/', 'A1', 'hoạt động khiêu vũ; múa', 'n.', 'dance (v.), dance (n.), dancer (n.)', NULL, 'Khi là danh từ chỉ hoạt động, từ này thường không đếm được; cụm từ đi khiêu vũ là go dancing.', 'We go dancing together at the community centre every Saturday.', NULL, 'Chúng tôi cùng nhau đến trung tâm cộng đồng để khiêu vũ vào mỗi thứ Bảy.', '{"wordId":"dancing","ukIpa":"/ˈdɑːnsɪŋ/","usIpa":"/ˈdænsɪŋ/","cefr":"A1","topic":"arts","senses":[{"pos":"n.","en":"the activity of moving your body rhythmically, usually to music","vi":"hoạt động khiêu vũ; múa"}],"examples":[{"en":"We go dancing together at the community centre every Saturday.","vi":"Chúng tôi cùng nhau đến trung tâm cộng đồng để khiêu vũ vào mỗi thứ Bảy.","audioKind":"ex"},{"en":"Regular dancing can improve physical fitness while providing opportunities for social interaction across different age groups.","vi":"Khiêu vũ thường xuyên có thể cải thiện thể lực đồng thời tạo cơ hội giao lưu xã hội giữa các nhóm tuổi khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"go dancing","vi":"đi khiêu vũ; đi nhảy"},{"en":"ballroom dancing","vi":"khiêu vũ tập thể; khiêu vũ giao tế"},{"en":"folk dancing","vi":"múa dân gian"}],"wordFamily":["dance (v.)","dance (n.)","dancer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi là danh từ chỉ hoạt động, từ này thường không đếm được; cụm từ đi khiêu vũ là go dancing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cinema', 'en-a1-10', 'cinema', '/ˈsɪnəmə/', 'A1', 'rạp chiếu phim; rạp chiếu bóng; nghệ thuật điện ảnh; ngành công nghiệp điện ảnh', 'n.', 'cinematic (adj.)', 'Đồng nghĩa: movie theater', 'Tiếng Anh-Anh thường dùng go to the cinema, trong khi tiếng Anh-Mỹ dùng go to the movies.', 'We met outside the cinema and bought some popcorn.', NULL, 'Chúng tôi hẹn gặp nhau ở ngoài rạp chiếu phim và mua một ít bỏng ngô.', '{"wordId":"cinema","ukIpa":"/ˈsɪnəmə/","usIpa":"/ˈsɪnəmə/","cefr":"A1","topic":"arts","senses":[{"pos":"n.","en":"A place where people pay to watch films.","vi":"rạp chiếu phim; rạp chiếu bóng"},{"pos":"n.","en":"Films considered as an art form or industry.","vi":"nghệ thuật điện ảnh; ngành công nghiệp điện ảnh"}],"examples":[{"en":"We met outside the cinema and bought some popcorn.","vi":"Chúng tôi hẹn gặp nhau ở ngoài rạp chiếu phim và mua một ít bỏng ngô.","audioKind":"ex"},{"en":"International cinema allows audiences to explore unfamiliar cultures and consider social issues from different perspectives.","vi":"Điện ảnh quốc tế giúp khán giả khám phá những nền văn hóa xa lạ và nhìn nhận các vấn đề xã hội từ nhiều góc độ khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"go to the cinema","vi":"đi xem phim"},{"en":"a cinema ticket","vi":"vé xem phim"},{"en":"world cinema","vi":"điện ảnh thế giới"},{"en":"independent cinema","vi":"phim độc lập"}],"wordFamily":["cinematic (adj.)"],"synonyms":["movie theater"],"antonyms":[],"tipVi":"Tiếng Anh-Anh thường dùng go to the cinema, trong khi tiếng Anh-Mỹ dùng go to the movies.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sing', 'en-a1-10', 'sing', '/sɪŋ/', 'A1', 'hát; ca hát; hót; kêu hót', 'v.', 'singer (n.), singing (n.)', NULL, 'Biến đổi bất quy tắc: sing—sang—sung.', 'We sing our favourite songs while washing the dishes.', NULL, 'Chúng tôi vừa rửa bát vừa hát những bài hát yêu thích của mình.', '{"wordId":"sing","ukIpa":"/sɪŋ/","usIpa":"/sɪŋ/","cefr":"A1","topic":"arts","senses":[{"pos":"v.","en":"To make musical sounds with your voice.","vi":"hát; ca hát"},{"pos":"v.","en":"For a bird to make pleasant musical sounds.","vi":"hót; kêu hót"}],"examples":[{"en":"We sing our favourite songs while washing the dishes.","vi":"Chúng tôi vừa rửa bát vừa hát những bài hát yêu thích của mình.","audioKind":"ex"},{"en":"Children who sing together regularly may develop greater confidence and stronger relationships with their classmates.","vi":"Những đứa trẻ thường xuyên cùng nhau ca hát có thể trở nên tự tin hơn và gắn kết sâu sắc hơn với các bạn cùng lớp.","audioKind":"ex2"}],"collocations":[{"en":"sing a song","vi":"hát một bài hát"},{"en":"sing along","vi":"hát theo"},{"en":"sing in a choir","vi":"hát trong đội hợp xướng"}],"wordFamily":["singer (n.)","singing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Biến đổi bất quy tắc: sing—sang—sung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_writer', 'en-a1-10', 'writer', '/ˈraɪtər/', 'A1', 'nhà văn; tác giả; người viết sách, bài báo hoặc các văn bản khác', 'n.', 'write (v.), writing (n.), written (adj.)', 'Đồng nghĩa: author', 'writer có phạm vi nghĩa rộng; author thường dùng để chỉ tác giả của một tác phẩm cụ thể.', 'The writer filled her notebook while waiting for the train.', NULL, 'Nữ nhà văn đã viết đầy kín cuốn sổ tay của mình trong lúc chờ tàu.', '{"wordId":"writer","ukIpa":"/ˈraɪtə/","usIpa":"/ˈraɪtər/","cefr":"A1","topic":"arts","senses":[{"pos":"n.","en":"someone who writes books, articles, or other texts","vi":"nhà văn; tác giả; người viết sách, bài báo hoặc các văn bản khác"}],"examples":[{"en":"The writer filled her notebook while waiting for the train.","vi":"Nữ nhà văn đã viết đầy kín cuốn sổ tay của mình trong lúc chờ tàu.","audioKind":"ex"},{"en":"A skilled writer can make complex environmental issues accessible to readers without oversimplifying the scientific evidence.","vi":"Một nhà văn tài năng có thể giúp người đọc tiếp cận các vấn đề môi trường phức tạp mà không làm đơn giản hóa quá mức các bằng chứng khoa học.","audioKind":"ex2"}],"collocations":[{"en":"professional writer","vi":"nhà văn chuyên nghiệp"},{"en":"travel writer","vi":"nhà văn viết truyện du lịch"},{"en":"freelance writer","vi":"tác giả tự do; cây bút tự do"},{"en":"short-story writer","vi":"nhà văn viết truyện ngắn"}],"wordFamily":["write (v.)","writing (n.)","written (adj.)"],"synonyms":["author"],"antonyms":[],"tipVi":"writer có phạm vi nghĩa rộng; author thường dùng để chỉ tác giả của một tác phẩm cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_10_1', 'en-a1-10', 'Cách dùng “draw” (v.) — vẽ; phác họa', 'draw a picture  ·  draw attention to  ·  draw a conclusion', 'Quá khứ là drew, quá khứ phân từ là drawn; ngoài ra từ này còn có thể chỉ kết quả hòa trong thể thao.', 'Họ từ (Word Family): drawing (n.) | Đồng nghĩa: sketch, pull, attract', '[{"hanzi":"She drew a sleeping cat in her sketchbook.","pinyin":"","meaning":"Cô ấy vẽ một chú mèo đang ngủ trong sổ phác thảo của mình."},{"hanzi":"Free cultural events can draw more visitors to museums and encourage wider participation in the arts.","pinyin":"","meaning":"Các sự kiện văn hóa miễn phí có thể thu hút nhiều du khách hơn đến với các bảo tàng và khuyến khích người dân tham gia nghệ thuật rộng rãi hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_10_2', 'en-a1-10', 'Cách dùng “story” (n.) — câu chuyện; chuyện kể', 'tell a story  ·  short story  ·  news story', 'Từ chỉ tầng nhà tiếng Anh-Anh viết là storey, tiếng Anh-Mỹ viết là story; chiều cao không cố định.', 'Họ từ (Word Family): storyteller (n.), storytelling (n.) | Đồng nghĩa: tale, account', '[{"hanzi":"Grandma told us a funny story about her childhood.","pinyin":"","meaning":"Bà đã kể cho chúng tôi nghe một câu chuyện thú vị về thời thơ ấu của bà."},{"hanzi":"Sharing a personal story can help students understand historical events from a more human perspective.","pinyin":"","meaning":"Việc chia sẻ một câu chuyện cá nhân có thể giúp học sinh hiểu các sự kiện lịch sử từ góc nhìn mang tính nhân văn hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_10_3', 'en-a1-10', 'Cách dùng “movie” (n.) — phim; điện ảnh', 'watch a movie  ·  movie star  ·  movie theatre', 'movie thiên về tiếng Mỹ, tiếng Anh-Anh thường dùng film; the movies có thể chỉ rạp chiếu phim.', 'Đồng nghĩa: film', '[{"hanzi":"We watched a funny movie after dinner last night.","pinyin":"","meaning":"Chúng tôi đã xem một bộ phim hài sau bữa tối tối qua."},{"hanzi":"Movies can introduce audiences to unfamiliar cultures, although they sometimes reinforce stereotypes rather than challenge them.","pinyin":"","meaning":"Phim ảnh có thể giới thiệu cho khán giả những nền văn hóa xa lạ, mặc dù đôi khi chúng củng cố các định kiến thay vì thách thức chúng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_10_4', 'en-a1-10', 'Cách dùng “dancing” (n.) — hoạt động khiêu vũ; múa', 'go dancing  ·  ballroom dancing  ·  folk dancing', 'Khi là danh từ chỉ hoạt động, từ này thường không đếm được; cụm từ đi khiêu vũ là go dancing.', 'Họ từ (Word Family): dance (v.), dance (n.), dancer (n.)', '[{"hanzi":"We go dancing together at the community centre every Saturday.","pinyin":"","meaning":"Chúng tôi cùng nhau đến trung tâm cộng đồng để khiêu vũ vào mỗi thứ Bảy."},{"hanzi":"Regular dancing can improve physical fitness while providing opportunities for social interaction across different age groups.","pinyin":"","meaning":"Khiêu vũ thường xuyên có thể cải thiện thể lực đồng thời tạo cơ hội giao lưu xã hội giữa các nhóm tuổi khác nhau."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_10_1', 'en-a1-10', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_10_1_1', 'ten_10_1', 'paint', 'There is blue paint all over your hands.', 'There is blue paint all over your hands.', '/peɪnt/', 'Có sơn màu xanh dính đầy trên tay bạn kìa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_10_1_2', 'ten_10_1', 'picture', 'She hung a picture of the sea above her bed.', 'She hung a picture of the sea above her bed.', '/ˈpɪktʃər/', 'Cô ấy treo một bức tranh phong cảnh biển phía trên giường của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_10_1_3', 'ten_10_1', 'guitar', 'My sister plays the guitar beside the window every evening.', 'My sister plays the guitar beside the window every evening.', '/ɡɪˈtɑːr/', 'Chị gái tôi chơi đàn ghi-ta bên cửa sổ vào mỗi buổi tối.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_10_1_4', 'ten_10_1', 'band', 'My sister plays the drums in a local band.', 'My sister plays the drums in a local band.', '/bænd/', 'Chị gái tôi chơi trống trong một ban nhạc địa phương.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_10_1_5', 'ten_10_1', 'painting', 'We hung a colourful painting above the sofa.', 'We hung a colourful painting above the sofa.', '/ˈpeɪntɪŋ/', 'Chúng tôi treo một bức tranh đầy màu sắc phía trên chiếc ghế sofa.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_10_1_6', 'ten_10_1', 'music', 'Soft music drifted through the kitchen while we cooked.', 'Soft music drifted through the kitchen while we cooked.', '/ˈmjuːzɪk/', 'Âm nhạc du dương vang lên trong căn bếp khi chúng tôi nấu ăn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
