INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_10_1_1', 'en-a1-10', 'ten_10_1', 'listening', 'listening', 'There is blue paint all over your hands.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chị gái tôi chơi đàn ghi-ta bên cửa sổ vào mỗi buổi tối.","Chúng tôi treo một bức tranh đầy màu sắc phía trên chiếc ghế sofa.","Có sơn màu xanh dính đầy trên tay bạn kìa.","Cô ấy treo một bức tranh phong cảnh biển phía trên giường của mình."]'::jsonb, 2, 'There is blue paint all over your hands. → Có sơn màu xanh dính đầy trên tay bạn kìa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_10_1_2', 'en-a1-10', 'ten_10_1', 'listening', 'listening', 'She hung a picture of the sea above her bed.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã dành cả buổi chiều để làm nghệ thuật bằng giấy màu.","Cô ấy treo một bức tranh phong cảnh biển phía trên giường của mình.","Âm nhạc du dương vang lên trong căn bếp khi chúng tôi nấu ăn.","Nam diễn viên đội chiếc vương miện bằng bạc trên sân khấu."]'::jsonb, 1, 'She hung a picture of the sea above her bed. → Cô ấy treo một bức tranh phong cảnh biển phía trên giường của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_10_1_3', 'en-a1-10', 'ten_10_1', 'listening', 'listening', 'My sister plays the guitar beside the window every evening.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chị gái tôi chơi đàn ghi-ta bên cửa sổ vào mỗi buổi tối.","Chúng tôi treo một bức tranh đầy màu sắc phía trên chiếc ghế sofa.","Chị gái tôi chơi trống trong một ban nhạc địa phương.","Nam diễn viên đội chiếc vương miện bằng bạc trên sân khấu."]'::jsonb, 0, 'My sister plays the guitar beside the window every evening. → Chị gái tôi chơi đàn ghi-ta bên cửa sổ vào mỗi buổi tối.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_10_2', 'en-a1-10', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_10_2_1', 'ten_10_2', 'paint', 'Schools should allow children to paint regularly, as creative activities can support emotional development and self-expression.', 'Schools should allow children to paint regularly, as creative activities can support emotional development and self-expression.', '/peɪnt/', 'Nhà trường nên cho phép trẻ em vẽ tranh thường xuyên, bởi các hoạt động sáng tạo có thể hỗ trợ sự phát triển cảm xúc và khả năng thể hiện bản thân.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_10_2_2', 'ten_10_2', 'picture', 'Survey results provide a clearer picture of how housing costs affect the wellbeing of young adults.', 'Survey results provide a clearer picture of how housing costs affect the wellbeing of young adults.', '/ˈpɪktʃər/', 'Kết quả khảo sát mang lại cái nhìn rõ ràng hơn về việc chi phí nhà ở ảnh hưởng như thế nào đến sự hạnh phúc của người trưởng thành trẻ tuổi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_10_2_3', 'ten_10_2', 'guitar', 'Learning to play the guitar can help students develop patience, coordination, and confidence through regular practice.', 'Learning to play the guitar can help students develop patience, coordination, and confidence through regular practice.', '/ɡɪˈtɑːr/', 'Học chơi đàn ghi-ta có thể giúp học sinh rèn luyện tính kiên nhẫn, sự phối hợp nhịp nhàng và sự tự tin thông qua việc luyện tập thường xuyên.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_10_2_4', 'ten_10_2', 'band', 'Live bands at community festivals can attract visitors and create opportunities for local businesses.', 'Live bands at community festivals can attract visitors and create opportunities for local businesses.', '/bænd/', 'Các ban nhạc biểu diễn trực tiếp tại lễ hội cộng đồng có thể thu hút khách du lịch và tạo cơ hội cho các doanh nghiệp địa phương.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_10_2_5', 'ten_10_2', 'painting', 'Public galleries make important paintings accessible to everyone, regardless of their income or educational background.', 'Public galleries make important paintings accessible to everyone, regardless of their income or educational background.', '/ˈpeɪntɪŋ/', 'Các phòng trưng bày nghệ thuật công cộng giúp mọi người đều có thể tiếp cận các bức tranh quý giá, không phân biệt thu nhập hay nền tảng giáo dục.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_10_2_6', 'ten_10_2', 'music', 'Learning music at school can develop children''s creativity and provide opportunities for cooperation through group performances.', 'Learning music at school can develop children''s creativity and provide opportunities for cooperation through group performances.', '/ˈmjuːzɪk/', 'Học nhạc ở trường có thể phát triển sự sáng tạo của trẻ em và tạo cơ hội hợp tác thông qua các buổi biểu diễn nhóm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
