INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_10_2', 'en-a1-10', NULL, 'comprehensive_test', 'listening', 'She hung a picture of the sea above her bed.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chị tôi tập đàn piano sau bữa tối mỗi ngày.","Bà đã kể cho chúng tôi nghe một câu chuyện thú vị về thời thơ ấu của bà.","Cô ấy treo một bức tranh phong cảnh biển phía trên giường của mình.","Chị gái tôi chơi trống trong một ban nhạc địa phương."]'::jsonb, 2, 'She hung a picture of the sea above her bed. → Cô ấy treo một bức tranh phong cảnh biển phía trên giường của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
