INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_10_4', 'en-a1-10', NULL, 'comprehensive_test', 'listening', 'My sister plays the drums in a local band.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bà đã kể cho chúng tôi nghe một câu chuyện thú vị về thời thơ ấu của bà.","Có sơn màu xanh dính đầy trên tay bạn kìa.","Chị gái tôi chơi trống trong một ban nhạc địa phương.","Chị gái tôi chơi đàn ghi-ta bên cửa sổ vào mỗi buổi tối."]'::jsonb, 2, 'My sister plays the drums in a local band. → Chị gái tôi chơi trống trong một ban nhạc địa phương.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
