INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_10_6', 'en-a1-10', NULL, 'comprehensive_test', 'listening', 'Soft music drifted through the kitchen while we cooked.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã xem một bộ phim hài sau bữa tối tối qua.","Âm nhạc du dương vang lên trong căn bếp khi chúng tôi nấu ăn.","Cô ấy vẽ một chú mèo đang ngủ trong sổ phác thảo của mình.","Có sơn màu xanh dính đầy trên tay bạn kìa."]'::jsonb, 1, 'Soft music drifted through the kitchen while we cooked. → Âm nhạc du dương vang lên trong căn bếp khi chúng tôi nấu ăn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
