INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_10_8', 'en-a1-10', NULL, 'comprehensive_test', 'listening', 'We spent the afternoon making art with coloured paper.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã dành cả buổi chiều để làm nghệ thuật bằng giấy màu.","Cô ấy vẽ một chú mèo đang ngủ trong sổ phác thảo của mình.","Âm nhạc du dương vang lên trong căn bếp khi chúng tôi nấu ăn.","Chúng tôi đã xem một bộ phim hài sau bữa tối tối qua."]'::jsonb, 0, 'We spent the afternoon making art with coloured paper. → Chúng tôi đã dành cả buổi chiều để làm nghệ thuật bằng giấy màu.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
