INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_10_18', 'en-a1-10', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should allow children to paint regularly, as creative activities can support emotional development and self-expression.', 'Dựa vào câu trên, từ “paint” có nghĩa phù hợp nhất là gì?', '["sơn; chất màu","tốt hơn; phù hợp hơn","một lần duy nhất","một... nữa; khác"]'::jsonb, 0, 'paint: sơn; chất màu; quét sơn; sơn; vẽ tranh. Dịch cả câu: Nhà trường nên cho phép trẻ em vẽ tranh thường xuyên, bởi các hoạt động sáng tạo có thể hỗ trợ sự phát triển cảm xúc và khả năng thể hiện bản thân.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_10_19', 'en-a1-10', NULL, 'comprehensive_test', 'reading', NULL, 'Survey results provide a clearer picture of how housing costs affect the wellbeing of young adults.', 'Dựa vào câu trên, từ “picture” có nghĩa phù hợp nhất là gì?', '["được yêu thích nhất (hơn bất kỳ thứ gì cùng loại)","thích; yêu thích","bức tranh; hình ảnh; bức ảnh","từ; đến từ"]'::jsonb, 2, 'picture: bức tranh; hình ảnh; bức ảnh; tình hình; bức tranh tổng thể; tưởng tượng; hình dung. Dịch cả câu: Kết quả khảo sát mang lại cái nhìn rõ ràng hơn về việc chi phí nhà ở ảnh hưởng như thế nào đến sự hạnh phúc của người trưởng thành trẻ tuổi.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_10_20', 'en-a1-10', NULL, 'comprehensive_test', 'reading', NULL, 'Learning to play the guitar can help students develop patience, coordination, and confidence through regular practice.', 'Dựa vào câu trên, từ “guitar” có nghĩa phù hợp nhất là gì?', '["nước ép trái cây; nước ép rau củ","đóng; khép; kết thúc","đàn ghi-ta; đàn guitar","hầu hết; phần lớn"]'::jsonb, 2, 'guitar: đàn ghi-ta; đàn guitar. Dịch cả câu: Học chơi đàn ghi-ta có thể giúp học sinh rèn luyện tính kiên nhẫn, sự phối hợp nhịp nhàng và sự tự tin thông qua việc luyện tập thường xuyên.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_10_21', 'en-a1-10', NULL, 'comprehensive_test', 'reading', NULL, 'Live bands at community festivals can attract visitors and create opportunities for local businesses.', 'Dựa vào câu trên, từ “band” có nghĩa phù hợp nhất là gì?', '["đi theo; đi sát phía sau","ban nhạc; nhóm nhạc","của tôi","mặt trời"]'::jsonb, 1, 'band: ban nhạc; nhóm nhạc; dải; vòng; đai (bằng vật liệu hoặc màu sắc); khoảng; dải tần số; mức; bậc. Dịch cả câu: Các ban nhạc biểu diễn trực tiếp tại lễ hội cộng đồng có thể thu hút khách du lịch và tạo cơ hội cho các doanh nghiệp địa phương.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_10_22', 'en-a1-10', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “rạp chiếu phim; rạp chiếu bóng”', '["and","dress","cinema","boring"]'::jsonb, 2, 'rạp chiếu phim; rạp chiếu bóng → cinema (/ˈsɪnəmə/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_10_23', 'en-a1-10', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hát; ca hát”', '["sing","fill","meal","water"]'::jsonb, 0, 'hát; ca hát → sing (/sɪŋ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_10_24', 'en-a1-10', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nhà văn; tác giả; người viết sách, bài báo hoặc các văn bản khác”', '["o''clock","writer","street","glasses"]'::jsonb, 1, 'nhà văn; tác giả; người viết sách, bài báo hoặc các văn bản khác → writer (/ˈraɪtər/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-11', 'en', 'Bài 11: Tư duy & Nhận thức - CEFR A1', 'CEFR A1', 'A1 · Tư duy', '22 từ vựng Tiếng Anh CEFR A1 chủ đề tư duy & nhận thức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1011, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_remember', 'en-a1-11', 'remember', '/rɪˈmembər/', 'A1', 'nhớ; hồi tưởng; nhớ phải làm gì; tưởng nhớ; ghi ơn', 'v.', 'remembrance (n.)', 'Đồng nghĩa: recall, recollect · Trái nghĩa: forget', 'remember to do là nhớ phải làm; remember doing là nhớ đã làm trong quá khứ.', 'I still remember the smell of my grandmother''s kitchen.', NULL, 'Tôi vẫn nhớ mùi hương từ căn bếp của bà tôi.', '{"wordId":"remember","ukIpa":"/rɪˈmembə/","usIpa":"/rɪˈmembər/","cefr":"A1","topic":"thinking","senses":[{"pos":"v.","en":"Keep information in your mind or bring it back.","vi":"nhớ; hồi tưởng"},{"pos":"v.","en":"Not forget to do something necessary.","vi":"nhớ phải làm gì"},{"pos":"v.","en":"Honour someone or something from the past.","vi":"tưởng nhớ; ghi ơn"}],"examples":[{"en":"I still remember the smell of my grandmother''s kitchen.","vi":"Tôi vẫn nhớ mùi hương từ căn bếp của bà tôi.","audioKind":"ex"},{"en":"Students often remember new vocabulary more effectively when they use it in meaningful conversations.","vi":"Học sinh thường ghi nhớ từ vựng mới hiệu quả hơn khi các em sử dụng chúng trong các cuộc trò chuyện có ý nghĩa.","audioKind":"ex2"}],"collocations":[{"en":"remember clearly","vi":"nhớ rõ"},{"en":"remember to do something","vi":"nhớ phải làm việc gì"},{"en":"remember doing something","vi":"nhớ đã làm việc gì"},{"en":"be remembered for","vi":"được ghi nhớ vì"}],"wordFamily":["remembrance (n.)"],"synonyms":["recall","recollect"],"antonyms":["forget"],"tipVi":"remember to do là nhớ phải làm; remember doing là nhớ đã làm trong quá khứ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_why', 'en-a1-11', 'why', '/waɪ/', 'A1', 'tại sao; vì sao; lý do', 'adv.', NULL, NULL, 'Trong câu hỏi gián tiếp, dùng trật tự câu trần thuật: I know why he left.', 'Why are your shoes still wet this morning?', NULL, 'Tại sao sáng nay giày của bạn vẫn còn ướt vậy?', '{"wordId":"why","ukIpa":"/waɪ/","usIpa":"/waɪ/","cefr":"A1","topic":"thinking","senses":[{"pos":"adv.","en":"used to ask about the reason for something","vi":"tại sao; vì sao"},{"pos":"adv.","en":"introduces the reason for a situation or action","vi":"lý do"}],"examples":[{"en":"Why are your shoes still wet this morning?","vi":"Tại sao sáng nay giày của bạn vẫn còn ướt vậy?","audioKind":"ex"},{"en":"Researchers need to understand why some students leave education before completing their secondary school qualifications.","vi":"Các nhà nghiên cứu cần tìm hiểu lý do tại sao một số học sinh bỏ học trước khi hoàn thành bằng cấp trung học.","audioKind":"ex2"}],"collocations":[{"en":"why not","vi":"tại sao không; sao lại không"},{"en":"the reason why","vi":"lý do tại sao"},{"en":"wonder why","vi":"tự hỏi tại sao"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong câu hỏi gián tiếp, dùng trật tự câu trần thuật: I know why he left.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_question', 'en-a1-11', 'question', '/ˈkwestʃən/', 'A1', 'n. câu hỏi; thắc mắc; n. vấn đề; đề tài cần thảo luận, xem xét hoặc quyết định; v. hỏi; đặt câu hỏi; chất vấn; hoài nghi', 'n.', 'questionable (adj.), questioning (adj.), questioner (n.)', 'Đồng nghĩa: query', 'Động từ question có thể đi trực tiếp với tân ngữ chỉ người, mang ý nghĩa hỏi hoặc tra hỏi.', 'I raised my hand to ask the teacher a question.', NULL, 'Tôi giơ tay để hỏi giáo viên một câu hỏi.', '{"wordId":"question","ukIpa":"/ˈkwestʃən/","usIpa":"/ˈkwestʃən/","cefr":"A1","topic":"thinking","senses":[{"pos":"n.","en":"Something you ask to obtain information or an answer","vi":"n. câu hỏi; thắc mắc"},{"pos":"n.","en":"An issue that needs discussion, consideration, or a decision","vi":"n. vấn đề; đề tài cần thảo luận, xem xét hoặc quyết định"},{"pos":"v.","en":"To ask someone for information or express doubt about something","vi":"v. hỏi; đặt câu hỏi; chất vấn; hoài nghi"}],"examples":[{"en":"I raised my hand to ask the teacher a question.","vi":"Tôi giơ tay để hỏi giáo viên một câu hỏi.","audioKind":"ex"},{"en":"Researchers increasingly question whether longer working hours actually improve productivity in modern office environments.","vi":"Các nhà nghiên cứu ngày càng hoài nghi về việc liệu thời gian làm việc kéo dài có thực sự cải thiện năng suất trong môi trường văn phòng hiện đại hay không.","audioKind":"ex2"}],"collocations":[{"en":"ask a question","vi":"đặt câu hỏi"},{"en":"answer a question","vi":"trả lời câu hỏi"},{"en":"raise a question","vi":"đưa ra câu hỏi"},{"en":"question an assumption","vi":"chất vấn một giả định"}],"wordFamily":["questionable (adj.)","questioning (adj.)","questioner (n.)"],"synonyms":["query"],"antonyms":[],"tipVi":"Động từ question có thể đi trực tiếp với tân ngữ chỉ người, mang ý nghĩa hỏi hoặc tra hỏi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fact', 'en-a1-11', 'fact', '/fækt/', 'A1', 'sự thật; thực tế', 'n.', 'factual (adj.), factually (adv.)', NULL, 'Sau ''the fact that'' là một mệnh đề hoàn chỉnh nhằm giải thích nội dung của sự thật đó.', 'We checked the facts before booking our train tickets.', NULL, 'Chúng tôi đã kiểm tra lại thông tin thực tế trước khi đặt vé tàu.', '{"wordId":"fact","ukIpa":"/fækt/","usIpa":"/fækt/","cefr":"A1","topic":"thinking","senses":[{"pos":"n.","en":"Something known or proved to be true.","vi":"sự thật; thực tế"}],"examples":[{"en":"We checked the facts before booking our train tickets.","vi":"Chúng tôi đã kiểm tra lại thông tin thực tế trước khi đặt vé tàu.","audioKind":"ex"},{"en":"Students should learn to distinguish facts from opinions when evaluating information shared through digital media.","vi":"Học sinh nên học cách phân biệt giữa sự thật và ý kiến cá nhân khi đánh giá thông tin được chia sẻ qua các phương tiện truyền thông kỹ thuật số.","audioKind":"ex2"}],"collocations":[{"en":"in fact","vi":"trên thực tế; thực ra"},{"en":"the fact that","vi":"sự thật là"},{"en":"establish the facts","vi":"xác minh sự thật"},{"en":"facts and figures","vi":"số liệu và sự kiện thực tế"}],"wordFamily":["factual (adj.)","factually (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Sau ''the fact that'' là một mệnh đề hoàn chỉnh nhằm giải thích nội dung của sự thật đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_true', 'en-a1-11', 'TRUE', '/truː/', 'A1', 'đúng sự thật; chính xác; đích thực; thực sự; trung thành; tận tụy', 'adj.', 'truth (n.), truly (adv.), truthful (adj.), untrue (adj.)', 'Đồng nghĩa: correct, accurate · Trái nghĩa: false, untrue', 'true nhấn mạnh sự phù hợp với thực tế; real nhấn mạnh sự tồn tại thực tế.', 'Is it TRUE that your cat can open doors?', NULL, 'Có thật là con mèo của bạn biết mở cửa không?', '{"wordId":"true","ukIpa":"/truː/","usIpa":"/truː/","cefr":"A1","topic":"thinking","senses":[{"pos":"adj.","en":"matching the facts rather than being false or invented","vi":"đúng sự thật; chính xác"},{"pos":"adj.","en":"having the essential qualities expected of someone or something","vi":"đích thực; thực sự"},{"pos":"adj.","en":"remaining loyal to a person, belief, or principle","vi":"trung thành; tận tụy"}],"examples":[{"en":"Is it TRUE that your cat can open doors?","vi":"Có thật là con mèo của bạn biết mở cửa không?","audioKind":"ex"},{"en":"Students must assess whether online claims are TRUE before using them as evidence in academic essays.","vi":"Học sinh phải đánh giá xem các thông tin trên mạng có đúng sự thật hay không trước khi sử dụng chúng làm bằng chứng trong các bài luận học thuật.","audioKind":"ex2"}],"collocations":[{"en":"true story","vi":"câu chuyện có thật"},{"en":"come true","vi":"trở thành hiện thực"},{"en":"hold true","vi":"vẫn đúng; có hiệu lực"},{"en":"true to your word","vi":"giữ lời hứa"}],"wordFamily":["truth (n.)","truly (adv.)","truthful (adj.)","untrue (adj.)"],"synonyms":["correct","accurate"],"antonyms":["false","untrue"],"tipVi":"true nhấn mạnh sự phù hợp với thực tế; real nhấn mạnh sự tồn tại thực tế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_interesting', 'en-a1-11', 'interesting', '/ˈɪntrəstɪŋ/', 'A1', 'thú vị; hay; hấp dẫn', 'adj.', 'interest (n.), interest (v.), interested (adj.), interestingly (adv.)', 'Đồng nghĩa: engaging · Trái nghĩa: boring, uninteresting', 'interesting dùng để mô tả sự vật, sự việc khơi gợi sự hứng thú, không đồng nghĩa với funny (buồn cười, hài hước).', 'We found an interesting little museum near the station.', NULL, 'Chúng tôi đã tìm thấy một bảo tàng nhỏ thú vị gần nhà ga.', '{"wordId":"interesting","ukIpa":"/ˈɪntrəstɪŋ/","usIpa":"/ˈɪntrəstɪŋ/","cefr":"A1","topic":"thinking","senses":[{"pos":"adj.","en":"Making you want to pay attention or learn more.","vi":"thú vị; hay; hấp dẫn"}],"examples":[{"en":"We found an interesting little museum near the station.","vi":"Chúng tôi đã tìm thấy một bảo tàng nhỏ thú vị gần nhà ga.","audioKind":"ex"},{"en":"The survey revealed an interesting connection between access to green spaces and residents'' overall satisfaction with urban life.","vi":"Cuộc khảo sát đã tiết lộ một mối liên hệ thú vị giữa khả năng tiếp cận không gian xanh và mức độ hài lòng chung của cư dân đối với cuộc sống đô thị.","audioKind":"ex2"}],"collocations":[{"en":"an interesting question","vi":"một câu hỏi hay"},{"en":"an interesting finding","vi":"một phát hiện đáng chú ý"},{"en":"find something interesting","vi":"cảm thấy điều gì đó thú vị"}],"wordFamily":["interest (n.)","interest (v.)","interested (adj.)","interestingly (adv.)"],"synonyms":["engaging"],"antonyms":["boring","uninteresting"],"tipVi":"interesting dùng để mô tả sự vật, sự việc khơi gợi sự hứng thú, không đồng nghĩa với funny (buồn cười, hài hước).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_idea', 'en-a1-11', 'idea', '/aɪˈdiːə/', 'A1', 'ý tưởng; suy nghĩ; gợi ý; quan niệm; ý niệm; sự hiểu biết; ấn tượng sơ lược', 'n.', NULL, 'Đồng nghĩa: thought, notion', 'idea là danh từ đếm được; “không biết” có thể nói have no idea.', 'Your idea of growing herbs on the balcony sounds lovely.', NULL, 'Ý tưởng trồng các loại thảo mộc ngoài ban công của bạn nghe hay đấy.', '{"wordId":"idea","ukIpa":"/aɪˈdɪə/","usIpa":"/aɪˈdiːə/","cefr":"A1","topic":"thinking","senses":[{"pos":"n.","en":"A thought or suggestion about what to do.","vi":"ý tưởng; suy nghĩ; gợi ý"},{"pos":"n.","en":"A mental understanding or belief about something.","vi":"quan niệm; ý niệm"},{"pos":"n.","en":"Some knowledge or understanding of a situation.","vi":"sự hiểu biết; ấn tượng sơ lược"}],"examples":[{"en":"Your idea of growing herbs on the balcony sounds lovely.","vi":"Ý tưởng trồng các loại thảo mộc ngoài ban công của bạn nghe hay đấy.","audioKind":"ex"},{"en":"The idea of free public transport attracts support, but its financial implications require careful consideration.","vi":"Ý tưởng giao thông công cộng miễn phí thu hút được sự ủng hộ, nhưng những hệ quả tài chính của nó đòi hỏi phải được cân nhắc kỹ lưỡng.","audioKind":"ex2"}],"collocations":[{"en":"come up with an idea","vi":"nảy ra ý tưởng"},{"en":"a good idea","vi":"một ý tưởng hay"},{"en":"have no idea","vi":"hoàn toàn không biết"},{"en":"a rough idea","vi":"một ý tưởng sơ bộ"}],"wordFamily":[],"synonyms":["thought","notion"],"antonyms":[],"tipVi":"idea là danh từ đếm được; “không biết” có thể nói have no idea.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reason', 'en-a1-11', 'reason', '/ˈriːzən/', 'A1', 'lý do; nguyên nhân; cớ; lý trí; năng lực lập luận; lập luận; suy luận', 'n.', 'reasonable (adj.), reasonably (adv.), reasoning (n.), unreasonable (adj.)', NULL, 'Thường dùng reason for đi với danh từ, hoặc reason why đi với mệnh đề.', 'The heavy rain was the reason we stayed home.', NULL, 'Cơn mưa lớn là lý do khiến chúng tôi ở nhà.', '{"wordId":"reason","ukIpa":"/ˈriːzən/","usIpa":"/ˈriːzən/","cefr":"A1","topic":"thinking","senses":[{"pos":"n.","en":"Something that explains why something happens or someone acts.","vi":"lý do; nguyên nhân; cớ"},{"pos":"n.","en":"The ability to think logically and make sensible judgments.","vi":"lý trí; năng lực lập luận"},{"pos":"v.","en":"To think logically in order to reach a conclusion.","vi":"lập luận; suy luận"}],"examples":[{"en":"The heavy rain was the reason we stayed home.","vi":"Cơn mưa lớn là lý do khiến chúng tôi ở nhà.","audioKind":"ex"},{"en":"One reason for rising urban rents is that housing supply has failed to keep pace with population growth.","vi":"Một lý do khiến tiền thuê nhà đô thị tăng cao là nguồn cung nhà ở đã không theo kịp tốc độ tăng trưởng dân số.","audioKind":"ex2"}],"collocations":[{"en":"reason for","vi":"lý do cho"},{"en":"a valid reason","vi":"một lý do chính đáng"},{"en":"reason with someone","vi":"lẽ phải với ai; khuyên bảo ai"},{"en":"within reason","vi":"trong giới hạn hợp lý"}],"wordFamily":["reasonable (adj.)","reasonably (adv.)","reasoning (n.)","unreasonable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng reason for đi với danh từ, hoặc reason why đi với mệnh đề.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_understand', 'en-a1-11', 'understand', '/ˌʌndərˈstænd/', 'A1', 'hiểu; nắm rõ; thông cảm; thấu hiểu; hiểu rằng; cho rằng', 'v.', 'understanding (n.), understandable (adj.), understandably (adv.), misunderstand (v.)', 'Đồng nghĩa: comprehend, grasp · Trái nghĩa: misunderstand', 'Dạng quá khứ và quá khứ phân từ của từ này đều là understood.', 'I finally understand how to use this washing machine.', NULL, 'Cuối cùng tôi cũng biết cách sử dụng chiếc máy giặt này.', '{"wordId":"understand","ukIpa":"/ˌʌndəˈstænd/","usIpa":"/ˌʌndərˈstænd/","cefr":"A1","topic":"thinking","senses":[{"pos":"v.","en":"to know what something means or how it works","vi":"hiểu; nắm rõ"},{"pos":"v.","en":"to recognise why someone feels or behaves a certain way","vi":"thông cảm; thấu hiểu"},{"pos":"v.","en":"to believe something is true based on available information","vi":"hiểu rằng; cho rằng"}],"examples":[{"en":"I finally understand how to use this washing machine.","vi":"Cuối cùng tôi cũng biết cách sử dụng chiếc máy giặt này.","audioKind":"ex"},{"en":"Schools should help students understand how their daily choices affect the natural environment.","vi":"Nhà trường nên giúp học sinh hiểu được cách những lựa chọn hàng ngày của các em tác động đến môi trường tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"understand the meaning","vi":"hiểu ý nghĩa"},{"en":"fully understand","vi":"hiểu thấu đáo"},{"en":"understand how","vi":"hiểu cách thức"}],"wordFamily":["understanding (n.)","understandable (adj.)","understandably (adv.)","misunderstand (v.)"],"synonyms":["comprehend","grasp"],"antonyms":["misunderstand"],"tipVi":"Dạng quá khứ và quá khứ phân từ của từ này đều là understood.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_choose', 'en-a1-11', 'choose', '/tʃuːz/', 'A1', 'chọn; lựa chọn; quyết định; chọn làm', 'v.', 'choice (n.), choosy (adj.), chosen (adj.)', 'Đồng nghĩa: select, pick', 'Quá khứ là "chose", quá khứ phân từ là "chosen"; theo sau là "to do".', 'You can choose a seat beside the window.', NULL, 'Bạn có thể chọn một chỗ ngồi cạnh cửa sổ.', '{"wordId":"choose","ukIpa":"/tʃuːz/","usIpa":"/tʃuːz/","cefr":"A1","topic":"thinking","senses":[{"pos":"v.","en":"to decide which person or thing you want","vi":"chọn; lựa chọn"},{"pos":"v.","en":"to decide to do something rather than something else","vi":"quyết định; chọn làm"}],"examples":[{"en":"You can choose a seat beside the window.","vi":"Bạn có thể chọn một chỗ ngồi cạnh cửa sổ.","audioKind":"ex"},{"en":"Many students choose to study abroad because they want to experience different cultures and teaching methods.","vi":"Nhiều sinh viên chọn đi du học vì muốn trải nghiệm các nền văn hóa và phương pháp giảng dạy khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"choose between","vi":"chọn giữa"},{"en":"choose from","vi":"chọn từ"},{"en":"choose to do something","vi":"chọn làm việc gì"},{"en":"choose wisely","vi":"lựa chọn khôn ngoan"}],"wordFamily":["choice (n.)","choosy (adj.)","chosen (adj.)"],"synonyms":["select","pick"],"antonyms":[],"tipVi":"Quá khứ là \"chose\", quá khứ phân từ là \"chosen\"; theo sau là \"to do\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_believe', 'en-a1-11', 'believe', '/bɪˈliːv/', 'A1', 'tin; tin là thật; cho rằng; nghĩ rằng; tin tưởng; tín nhiệm', 'v.', 'belief (n.), believable (adj.), unbelievable (adj.), believer (n.)', 'Trái nghĩa: disbelieve, doubt', 'believe someone có nghĩa là tin lời ai nói; believe in someone có nghĩa là tin tưởng vào năng lực của ai.', 'I believe you, but your story sounds quite unusual.', NULL, 'Tôi tin bạn, nhưng câu chuyện của bạn nghe có vẻ khá bất thường.', '{"wordId":"believe","ukIpa":"/bɪˈliːv/","usIpa":"/bɪˈliːv/","cefr":"A1","topic":"thinking","senses":[{"pos":"v.","en":"To accept that something is true or someone is truthful.","vi":"tin; tin là thật"},{"pos":"v.","en":"To think that something is likely or correct.","vi":"cho rằng; nghĩ rằng"},{"pos":"v.","en":"To have confidence or faith in someone or something.","vi":"tin tưởng; tín nhiệm"}],"examples":[{"en":"I believe you, but your story sounds quite unusual.","vi":"Tôi tin bạn, nhưng câu chuyện của bạn nghe có vẻ khá bất thường.","audioKind":"ex"},{"en":"Some educators believe that practical experience is just as valuable as academic knowledge in preparing students for employment.","vi":"Một số nhà giáo dục tin rằng kinh nghiệm thực tế cũng có giá trị như kiến thức hàn lâm trong việc chuẩn bị cho học sinh sinh viên đi làm.","audioKind":"ex2"}],"collocations":[{"en":"believe that","vi":"tin rằng"},{"en":"believe in yourself","vi":"tin tưởng vào bản thân"},{"en":"widely believed","vi":"được tin tưởng rộng rãi"},{"en":"hard to believe","vi":"khó mà tin được"}],"wordFamily":["belief (n.)","believable (adj.)","unbelievable (adj.)","believer (n.)"],"synonyms":[],"antonyms":["disbelieve","doubt"],"tipVi":"believe someone có nghĩa là tin lời ai nói; believe in someone có nghĩa là tin tưởng vào năng lực của ai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_if', 'en-a1-11', 'if', '/ɪf/', 'A1', 'nếu; nếu như; liệu rằng', 'conj.', NULL, NULL, 'Khi nói về điều kiện trong tương lai, mệnh đề bắt đầu bằng if thường dùng thì hiện tại đơn.', 'If it rains, we can play indoors instead.', NULL, 'Nếu trời mưa, chúng ta có thể chuyển sang chơi ở trong nhà.', '{"wordId":"if","ukIpa":"/ɪf/","usIpa":"/ɪf/","cefr":"A1","topic":"thinking","senses":[{"pos":"conj.","en":"introduces a condition for something to happen","vi":"nếu; nếu như"},{"pos":"conj.","en":"introduces an indirect question about whether something is true","vi":"liệu rằng"}],"examples":[{"en":"If it rains, we can play indoors instead.","vi":"Nếu trời mưa, chúng ta có thể chuyển sang chơi ở trong nhà.","audioKind":"ex"},{"en":"If cities invest in safe cycling routes, more residents may choose bicycles for their daily journeys.","vi":"Nếu các thành phố đầu tư vào các tuyến đường dành cho xe đạp an toàn, nhiều cư dân có thể chọn xe đạp cho việc đi lại hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"even if","vi":"ngay cả khi"},{"en":"only if","vi":"chỉ khi"},{"en":"as if","vi":"như thể là"},{"en":"if necessary","vi":"nếu cần thiết"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi nói về điều kiện trong tương lai, mệnh đề bắt đầu bằng if thường dùng thì hiện tại đơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_know', 'en-a1-11', 'know', '/noʊ/', 'A1', 'biết; nắm được thông tin; biết; quen biết; hiểu rõ', 'v.', 'knowledge (n.), knowledgeable (adj.), known (adj.), unknown (adj.)', NULL, 'Dạng quá khứ là knew, quá phân từ là known; động từ này thường không dùng ở thì tiếp diễn.', 'Do you know how to fix this bicycle?', NULL, 'Bạn có biết cách sửa chiếc xe đạp này không?', '{"wordId":"know","ukIpa":"/nəʊ/","usIpa":"/noʊ/","cefr":"A1","topic":"thinking","senses":[{"pos":"v.","en":"To have information or understanding about something","vi":"biết; nắm được thông tin"},{"pos":"v.","en":"To be familiar with a person, place, or thing","vi":"biết; quen biết; hiểu rõ"}],"examples":[{"en":"Do you know how to fix this bicycle?","vi":"Bạn có biết cách sửa chiếc xe đạp này không?","audioKind":"ex"},{"en":"Consumers need to know how their personal information is collected before they can make informed choices online.","vi":"Người tiêu dùng cần biết thông tin cá nhân của họ được thu thập như thế nào trước khi họ có thể đưa ra các lựa chọn có hiểu biết trên mạng.","audioKind":"ex2"}],"collocations":[{"en":"know how to","vi":"biết cách làm gì"},{"en":"know the answer","vi":"biết câu trả lời"},{"en":"know someone well","vi":"biết rõ ai đó"},{"en":"know for sure","vi":"biết chắc chắn"}],"wordFamily":["knowledge (n.)","knowledgeable (adj.)","known (adj.)","unknown (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ là knew, quá phân từ là known; động từ này thường không dùng ở thì tiếp diễn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_think', 'en-a1-11', 'think', '/θɪŋk/', 'A1', 'nghĩ; cho rằng; suy nghĩ; cân nhắc', 'v.', 'thought (n.), thinker (n.), thinking (n.), thoughtful (adj.)', 'Đồng nghĩa: believe, consider', 'Quá khứ và quá khứ phân từ đều là thought; khi mang nghĩa "cho rằng", động từ này thường không dùng ở thì tiếp diễn.', 'I think this soup needs a little more salt.', NULL, 'Tôi nghĩ món súp này cần thêm một chút muối.', '{"wordId":"think","ukIpa":"/θɪŋk/","usIpa":"/θɪŋk/","cefr":"A1","topic":"thinking","senses":[{"pos":"v.","en":"To have an opinion or belief about something.","vi":"nghĩ; cho rằng"},{"pos":"v.","en":"To use your mind to consider ideas or solve problems.","vi":"suy nghĩ; cân nhắc"}],"examples":[{"en":"I think this soup needs a little more salt.","vi":"Tôi nghĩ món súp này cần thêm một chút muối.","audioKind":"ex"},{"en":"Some people think that schools should devote more time to practical skills rather than examination preparation.","vi":"Một số người cho rằng trường học nên dành nhiều thời gian hơn cho các kỹ năng thực tế thay vì luyện thi.","audioKind":"ex2"}],"collocations":[{"en":"think about","vi":"suy nghĩ về; cân nhắc"},{"en":"think of","vi":"nghĩ đến; nhớ đến"},{"en":"think carefully","vi":"suy nghĩ cẩn thận"},{"en":"think critically","vi":"tư duy phản biện"}],"wordFamily":["thought (n.)","thinker (n.)","thinking (n.)","thoughtful (adj.)"],"synonyms":["believe","consider"],"antonyms":[],"tipVi":"Quá khứ và quá khứ phân từ đều là thought; khi mang nghĩa \"cho rằng\", động từ này thường không dùng ở thì tiếp diễn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_forget', 'en-a1-11', 'forget', '/fərˈɡet/', 'A1', 'quên; không nhớ; quên làm hoặc quên mang cái gì', 'v.', 'forgot (v.), forgotten (v.), forgetful (adj.), forgettable (adj.)', 'Trái nghĩa: remember, recall', 'forget to do nghĩa là quên phải làm việc gì; forget doing nghĩa là quên việc đã làm trong quá khứ.', 'I always forget where I put my reading glasses.', NULL, 'Tôi luôn quên mất mình để kính đọc sách ở đâu.', '{"wordId":"forget","ukIpa":"/fəˈɡet/","usIpa":"/fərˈɡet/","cefr":"A1","topic":"thinking","senses":[{"pos":"v.","en":"to fail to remember a fact, person, or experience","vi":"quên; không nhớ"},{"pos":"v.","en":"to fail to do or bring something through not remembering","vi":"quên làm hoặc quên mang cái gì"}],"examples":[{"en":"I always forget where I put my reading glasses.","vi":"Tôi luôn quên mất mình để kính đọc sách ở đâu.","audioKind":"ex"},{"en":"Students may quickly forget new vocabulary unless they review it regularly and use it in meaningful contexts.","vi":"Học sinh có thể nhanh chóng quên từ vựng mới trừ khi các em ôn tập thường xuyên và sử dụng chúng trong các ngữ cảnh có ý nghĩa.","audioKind":"ex2"}],"collocations":[{"en":"forget to do something","vi":"quên làm việc gì đó"},{"en":"forget about","vi":"quên về; bỏ qua"},{"en":"completely forget","vi":"hoàn toàn quên"}],"wordFamily":["forgot (v.)","forgotten (v.)","forgetful (adj.)","forgettable (adj.)"],"synonyms":[],"antonyms":["remember","recall"],"tipVi":"forget to do nghĩa là quên phải làm việc gì; forget doing nghĩa là quên việc đã làm trong quá khứ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plan', 'en-a1-11', 'plan', '/plæn/', 'A1', 'kế hoạch, dự định về những việc sẽ làm trong tương lai; lên kế hoạch, dự định làm gì và cách thức thực hiện; bản vẽ mặt bằng thể hiện bố cục của một tòa nhà hoặc khu vực', 'n.', 'planning (n.), planner (n.), planned (adj.)', 'Đồng nghĩa: scheme', 'plan to do diễn tả dự định làm gì; dạng quá khứ planned được gấp đôi chữ n.', 'Our plan is to leave early and avoid traffic.', NULL, 'Kế hoạch của chúng tôi là khởi hành sớm để tránh ùn tắc giao thông.', '{"wordId":"plan","ukIpa":"/plæn/","usIpa":"/plæn/","cefr":"A1","topic":"thinking","senses":[{"pos":"n.","en":"An arrangement or idea for what to do in future.","vi":"kế hoạch, dự định về những việc sẽ làm trong tương lai"},{"pos":"v.","en":"To decide what to do and how to do it.","vi":"lên kế hoạch, dự định làm gì và cách thức thực hiện"},{"pos":"n.","en":"A drawing showing the layout of a building or area.","vi":"bản vẽ mặt bằng thể hiện bố cục của một tòa nhà hoặc khu vực"}],"examples":[{"en":"Our plan is to leave early and avoid traffic.","vi":"Kế hoạch của chúng tôi là khởi hành sớm để tránh ùn tắc giao thông.","audioKind":"ex"},{"en":"Cities need a clear plan for expanding public transport before introducing restrictions on private vehicles.","vi":"Các thành phố cần có một kế hoạch rõ ràng để mở rộng giao thông công cộng trước khi ban hành các biện pháp hạn chế phương tiện cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"make a plan","vi":"lên kế hoạch"},{"en":"plan to do something","vi":"dự định làm điều gì"},{"en":"floor plan","vi":"bản vẽ mặt bằng"},{"en":"long-term plan","vi":"kế hoạch dài hạn"}],"wordFamily":["planning (n.)","planner (n.)","planned (adj.)"],"synonyms":["scheme"],"antonyms":[],"tipVi":"plan to do diễn tả dự định làm gì; dạng quá khứ planned được gấp đôi chữ n.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mistake', 'en-a1-11', 'mistake', '/mɪˈsteɪk/', 'A1', 'lỗi; sai sót; sự nhầm lẫn; nhầm lẫn; nhận diện sai', 'n.', 'mistaken (adj.), mistakenly (adv.), unmistakable (adj.)', 'Đồng nghĩa: error', 'Dùng động từ make a mistake, không dùng do; dạng quá khứ của động từ mistake là mistook.', 'I took your umbrella by mistake this morning.', NULL, 'Sáng nay tôi đã lấy nhầm chiếc ô của bạn.', '{"wordId":"mistake","ukIpa":"/mɪˈsteɪk/","usIpa":"/mɪˈsteɪk/","cefr":"A1","topic":"thinking","senses":[{"pos":"n.","en":"Something incorrect that you do, say, or believe.","vi":"lỗi; sai sót; sự nhầm lẫn"},{"pos":"v.","en":"To wrongly identify someone or understand something incorrectly.","vi":"nhầm lẫn; nhận diện sai"}],"examples":[{"en":"I took your umbrella by mistake this morning.","vi":"Sáng nay tôi đã lấy nhầm chiếc ô của bạn.","audioKind":"ex"},{"en":"Teachers should encourage students to learn from mistakes rather than feel ashamed of making them.","vi":"Giáo viên nên khuyến khích học sinh học hỏi từ những sai lầm thay vì cảm thấy xấu hổ vì đã mắc lỗi.","audioKind":"ex2"}],"collocations":[{"en":"make a mistake","vi":"mắc lỗi"},{"en":"by mistake","vi":"nhầm lẫn; vô tình"},{"en":"learn from mistakes","vi":"học hỏi từ sai lầm"},{"en":"mistake A for B","vi":"nhầm A với B"}],"wordFamily":["mistaken (adj.)","mistakenly (adv.)","unmistakable (adj.)"],"synonyms":["error"],"antonyms":[],"tipVi":"Dùng động từ make a mistake, không dùng do; dạng quá khứ của động từ mistake là mistook.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_agree', 'en-a1-11', 'agree', '/əˈɡriː/', 'A1', 'đồng ý; tán thành; thống nhất; thỏa thuận; đồng ý làm gì', 'v.', 'agreement (n.), disagree (v.), disagreement (n.)', 'Đồng nghĩa: concur · Trái nghĩa: disagree', 'Đồng ý với ai dùng with; thống nhất về việc gì dùng on; đồng ý thực hiện hành động dùng to do.', 'I agree with you that this soup needs salt.', NULL, 'Tôi đồng ý với bạn rằng món súp này cần thêm chút muối.', '{"wordId":"agree","ukIpa":"/əˈɡriː/","usIpa":"/əˈɡriː/","cefr":"A1","topic":"thinking","senses":[{"pos":"v.","en":"Have the same opinion or accept someone else''s view","vi":"đồng ý; tán thành"},{"pos":"v.","en":"Decide something together or promise to do something","vi":"thống nhất; thỏa thuận; đồng ý làm gì"}],"examples":[{"en":"I agree with you that this soup needs salt.","vi":"Tôi đồng ý với bạn rằng món súp này cần thêm chút muối.","audioKind":"ex"},{"en":"Most researchers agree that regular physical activity can improve both mental health and academic performance.","vi":"Hầu hết các nhà nghiên cứu đều đồng tình rằng việc tập thể dục thường xuyên có thể cải thiện cả sức khỏe tinh thần lẫn kết quả học tập.","audioKind":"ex2"}],"collocations":[{"en":"agree with someone","vi":"đồng ý với ai đó"},{"en":"agree on a plan","vi":"thống nhất về một kế hoạch"},{"en":"agree to do something","vi":"đồng ý làm điều gì đó"},{"en":"agree to a proposal","vi":"chấp thuận một đề xuất"}],"wordFamily":["agreement (n.)","disagree (v.)","disagreement (n.)"],"synonyms":["concur"],"antonyms":["disagree"],"tipVi":"Đồng ý với ai dùng with; thống nhất về việc gì dùng on; đồng ý thực hiện hành động dùng to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_future', 'en-a1-11', 'future', '/ˈfjuːtʃər/', 'A1', 'tương lai; tiền đồ; tương lai; sắp tới', 'n.', NULL, 'Trái nghĩa: past', '"in the future" chỉ tương lai nói chung; trong tiếng Anh-Anh, "in future" thường chỉ từ nay trở đi.', 'We talked about our future while walking home.', NULL, 'Chúng tôi đã nói về tương lai của mình khi đang đi bộ về nhà.', '{"wordId":"future","ukIpa":"/ˈfjuːtʃə/","usIpa":"/ˈfjuːtʃər/","cefr":"A1","topic":"thinking","senses":[{"pos":"n.","en":"The time ahead, or what will happen to someone or something.","vi":"tương lai; tiền đồ"},{"pos":"adj.","en":"Happening or existing at a time after the present.","vi":"tương lai; sắp tới"}],"examples":[{"en":"We talked about our future while walking home.","vi":"Chúng tôi đã nói về tương lai của mình khi đang đi bộ về nhà.","audioKind":"ex"},{"en":"Governments should invest in renewable energy to protect the environment for future generations worldwide.","vi":"Chính phủ các nước nên đầu tư vào năng lượng tái tạo để bảo vệ môi trường cho các thế hệ tương lai trên toàn thế giới.","audioKind":"ex2"}],"collocations":[{"en":"in the future","vi":"trong tương lai"},{"en":"near future","vi":"tương lai gần"},{"en":"future generations","vi":"các thế hệ tương lai"},{"en":"bright future","vi":"tương lai tươi sáng"}],"wordFamily":[],"synonyms":[],"antonyms":["past"],"tipVi":"\"in the future\" chỉ tương lai nói chung; trong tiếng Anh-Anh, \"in future\" thường chỉ từ nay trở đi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_possible', 'en-a1-11', 'possible', '/ˈpɑːsəbl/', 'A1', 'có thể xảy ra; có thể thực hiện được; có thể xem xét như một lựa chọn hoặc lời giải thích', 'adj.', 'possibility (n.), possibly (adv.), impossible (adj.)', 'Đồng nghĩa: feasible · Trái nghĩa: impossible', 'Thường dùng cấu trúc it is possible to do; không dùng chủ ngữ chỉ người với is possible to do.', 'Is it possible to book a table for tonight?', NULL, 'Tôi có thể đặt một bàn ăn cho tối nay không?', '{"wordId":"possible","ukIpa":"/ˈpɒsəbl/","usIpa":"/ˈpɑːsəbl/","cefr":"A1","topic":"thinking","senses":[{"pos":"adj.","en":"able to happen, exist, or be done","vi":"có thể xảy ra; có thể thực hiện được"},{"pos":"adj.","en":"worth considering as a choice or explanation","vi":"có thể xem xét như một lựa chọn hoặc lời giải thích"}],"examples":[{"en":"Is it possible to book a table for tonight?","vi":"Tôi có thể đặt một bàn ăn cho tối nay không?","audioKind":"ex"},{"en":"Investment in renewable energy makes it possible for countries to reduce their dependence on imported fuels.","vi":"Việc đầu tư vào năng lượng tái tạo giúp các quốc gia có thể giảm bớt sự phụ thuộc vào nhiên liệu nhập khẩu.","audioKind":"ex2"}],"collocations":[{"en":"as soon as possible","vi":"càng sớm càng tốt"},{"en":"possible explanation","vi":"lời giải thích có thể"},{"en":"make it possible","vi":"làm cho có thể"}],"wordFamily":["possibility (n.)","possibly (adv.)","impossible (adj.)"],"synonyms":["feasible"],"antonyms":["impossible"],"tipVi":"Thường dùng cấu trúc it is possible to do; không dùng chủ ngữ chỉ người với is possible to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sure', 'en-a1-11', 'sure', '/ʃʊr/', 'A1', 'chắc chắn; tự tin; chắc chắn (sẽ xảy ra); nhất định; tất nhiên; chắc chắn rồi', 'adj.', 'surely (adv.), sureness (n.), unsure (adj.)', 'Đồng nghĩa: certain, confident · Trái nghĩa: unsure, uncertain', 'be sure of dùng để chỉ sự chắc chắn; be sure to có thể diễn tả sự tất yếu hoặc lời dặn dò.', 'Are you sure you left your keys here?', NULL, 'Bạn có chắc là mình để quên chìa khóa ở đây không?', '{"wordId":"sure","ukIpa":"/ʃɔː/","usIpa":"/ʃʊr/","cefr":"A1","topic":"thinking","senses":[{"pos":"adj.","en":"Feeling no doubt that something is true or correct.","vi":"chắc chắn; tự tin"},{"pos":"adj.","en":"Certain to happen or do something.","vi":"chắc chắn (sẽ xảy ra); nhất định"},{"pos":"adv.","en":"Used informally to agree or strongly confirm something.","vi":"tất nhiên; chắc chắn rồi"}],"examples":[{"en":"Are you sure you left your keys here?","vi":"Bạn có chắc là mình để quên chìa khóa ở đây không?","audioKind":"ex"},{"en":"Governments must make sure that rural communities have reliable access to essential healthcare services.","vi":"Chính phủ phải đảm bảo rằng các cộng đồng nông thôn có khả năng tiếp cận ổn định với các dịch vụ chăm sóc sức khỏe thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"make sure","vi":"đảm bảo; chắc chắn"},{"en":"be sure of","vi":"chắc chắn về điều gì"},{"en":"be sure to","vi":"chắc chắn sẽ"},{"en":"for sure","vi":"chắc chắn rồi; khẳng định"}],"wordFamily":["surely (adv.)","sureness (n.)","unsure (adj.)"],"synonyms":["certain","confident"],"antonyms":["unsure","uncertain"],"tipVi":"be sure of dùng để chỉ sự chắc chắn; be sure to có thể diễn tả sự tất yếu hoặc lời dặn dò.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_maybe', 'en-a1-11', 'maybe', '/ˈmeɪbi/', 'A1', 'có lẽ; có thể', 'adv.', NULL, 'Đồng nghĩa: perhaps, possibly', 'maybe là trạng từ; trong khi may be là cụm động từ gồm trợ động từ may và động từ be.', 'Maybe we can have a picnic if the weather improves.', NULL, 'Có lẽ chúng ta có thể đi dã ngoại nếu thời tiết khá hơn.', '{"wordId":"maybe","ukIpa":"/ˈmeɪbi/","usIpa":"/ˈmeɪbi/","cefr":"A1","topic":"thinking","senses":[{"pos":"adv.","en":"Used to say that something is possible but not certain.","vi":"có lẽ; có thể"}],"examples":[{"en":"Maybe we can have a picnic if the weather improves.","vi":"Có lẽ chúng ta có thể đi dã ngoại nếu thời tiết khá hơn.","audioKind":"ex"},{"en":"Maybe cities could reduce traffic congestion by offering cheaper public transport rather than building more roads.","vi":"Có lẽ các thành phố có thể giảm thiểu tình trạng ùn tắc giao thông bằng cách cung cấp phương tiện giao thông công cộng giá rẻ hơn thay vì xây dựng thêm nhiều đường xá.","audioKind":"ex2"}],"collocations":[{"en":"maybe later","vi":"có lẽ để sau"},{"en":"maybe not","vi":"có lẽ là không"},{"en":"maybe next time","vi":"có lẽ là lần sau"}],"wordFamily":[],"synonyms":["perhaps","possibly"],"antonyms":[],"tipVi":"maybe là trạng từ; trong khi may be là cụm động từ gồm trợ động từ may và động từ be.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_11_1', 'en-a1-11', 'Cách dùng “think” (v.) — nghĩ; cho rằng', 'think about  ·  think of  ·  think carefully', 'Quá khứ và quá khứ phân từ đều là thought; khi mang nghĩa "cho rằng", động từ này thường không dùng ở thì tiếp diễn.', 'Họ từ (Word Family): thought (n.), thinker (n.), thinking (n.), thoughtful (adj.) | Đồng nghĩa: believe, consider', '[{"hanzi":"I think this soup needs a little more salt.","pinyin":"","meaning":"Tôi nghĩ món súp này cần thêm một chút muối."},{"hanzi":"Some people think that schools should devote more time to practical skills rather than examination preparation.","pinyin":"","meaning":"Một số người cho rằng trường học nên dành nhiều thời gian hơn cho các kỹ năng thực tế thay vì luyện thi."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_11_2', 'en-a1-11', 'Cách dùng “interesting” (adj.) — thú vị; hay; hấp dẫn', 'an interesting question  ·  an interesting finding  ·  find something interesting', 'interesting dùng để mô tả sự vật, sự việc khơi gợi sự hứng thú, không đồng nghĩa với funny (buồn cười, hài hước).', 'Họ từ (Word Family): interest (n.), interest (v.), interested (adj.), interestingly (adv.) | Đồng nghĩa: engaging | Trái nghĩa: boring, uninteresting', '[{"hanzi":"We found an interesting little museum near the station.","pinyin":"","meaning":"Chúng tôi đã tìm thấy một bảo tàng nhỏ thú vị gần nhà ga."},{"hanzi":"The survey revealed an interesting connection between access to green spaces and residents'' overall satisfaction with urban life.","pinyin":"","meaning":"Cuộc khảo sát đã tiết lộ một mối liên hệ thú vị giữa khả năng tiếp cận không gian xanh và mức độ hài lòng chung của cư dân đối với cuộc sống đô thị."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_11_3', 'en-a1-11', 'Cách dùng “believe” (v.) — tin; tin là thật', 'believe that  ·  believe in yourself  ·  widely believed', 'believe someone có nghĩa là tin lời ai nói; believe in someone có nghĩa là tin tưởng vào năng lực của ai.', 'Họ từ (Word Family): belief (n.), believable (adj.), unbelievable (adj.), believer (n.) | Trái nghĩa: disbelieve, doubt', '[{"hanzi":"I believe you, but your story sounds quite unusual.","pinyin":"","meaning":"Tôi tin bạn, nhưng câu chuyện của bạn nghe có vẻ khá bất thường."},{"hanzi":"Some educators believe that practical experience is just as valuable as academic knowledge in preparing students for employment.","pinyin":"","meaning":"Một số nhà giáo dục tin rằng kinh nghiệm thực tế cũng có giá trị như kiến thức hàn lâm trong việc chuẩn bị cho học sinh sinh viên đi làm."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_11_4', 'en-a1-11', 'Cách dùng “future” (n.) — tương lai; tiền đồ', 'in the future  ·  near future  ·  future generations', '"in the future" chỉ tương lai nói chung; trong tiếng Anh-Anh, "in future" thường chỉ từ nay trở đi.', 'Trái nghĩa: past', '[{"hanzi":"We talked about our future while walking home.","pinyin":"","meaning":"Chúng tôi đã nói về tương lai của mình khi đang đi bộ về nhà."},{"hanzi":"Governments should invest in renewable energy to protect the environment for future generations worldwide.","pinyin":"","meaning":"Chính phủ các nước nên đầu tư vào năng lượng tái tạo để bảo vệ môi trường cho các thế hệ tương lai trên toàn thế giới."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_11_1', 'en-a1-11', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_11_1_1', 'ten_11_1', 'remember', 'I still remember the smell of my grandmother''s kitchen.', 'I still remember the smell of my grandmother''s kitchen.', '/rɪˈmembər/', 'Tôi vẫn nhớ mùi hương từ căn bếp của bà tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_11_1_2', 'ten_11_1', 'why', 'Why are your shoes still wet this morning?', 'Why are your shoes still wet this morning?', '/waɪ/', 'Tại sao sáng nay giày của bạn vẫn còn ướt vậy?', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_11_1_3', 'ten_11_1', 'question', 'I raised my hand to ask the teacher a question.', 'I raised my hand to ask the teacher a question.', '/ˈkwestʃən/', 'Tôi giơ tay để hỏi giáo viên một câu hỏi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_11_1_4', 'ten_11_1', 'fact', 'We checked the facts before booking our train tickets.', 'We checked the facts before booking our train tickets.', '/fækt/', 'Chúng tôi đã kiểm tra lại thông tin thực tế trước khi đặt vé tàu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_11_1_5', 'ten_11_1', 'TRUE', 'Is it TRUE that your cat can open doors?', 'Is it TRUE that your cat can open doors?', '/truː/', 'Có thật là con mèo của bạn biết mở cửa không?', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_11_1_6', 'ten_11_1', 'interesting', 'We found an interesting little museum near the station.', 'We found an interesting little museum near the station.', '/ˈɪntrəstɪŋ/', 'Chúng tôi đã tìm thấy một bảo tàng nhỏ thú vị gần nhà ga.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_11_1_7', 'ten_11_1', 'idea', 'Your idea of growing herbs on the balcony sounds lovely.', 'Your idea of growing herbs on the balcony sounds lovely.', '/aɪˈdiːə/', 'Ý tưởng trồng các loại thảo mộc ngoài ban công của bạn nghe hay đấy.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_11_1_8', 'ten_11_1', 'reason', 'The heavy rain was the reason we stayed home.', 'The heavy rain was the reason we stayed home.', '/ˈriːzən/', 'Cơn mưa lớn là lý do khiến chúng tôi ở nhà.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_11_1_1', 'en-a1-11', 'ten_11_1', 'listening', 'listening', 'I still remember the smell of my grandmother''s kitchen.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi giơ tay để hỏi giáo viên một câu hỏi.","Có thật là con mèo của bạn biết mở cửa không?","Tôi vẫn nhớ mùi hương từ căn bếp của bà tôi.","Tại sao sáng nay giày của bạn vẫn còn ướt vậy?"]'::jsonb, 2, 'I still remember the smell of my grandmother''s kitchen. → Tôi vẫn nhớ mùi hương từ căn bếp của bà tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_11_1_2', 'en-a1-11', 'ten_11_1', 'listening', 'listening', 'Why are your shoes still wet this morning?', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã tìm thấy một bảo tàng nhỏ thú vị gần nhà ga.","Tôi vẫn nhớ mùi hương từ căn bếp của bà tôi.","Tôi giơ tay để hỏi giáo viên một câu hỏi.","Tại sao sáng nay giày của bạn vẫn còn ướt vậy?"]'::jsonb, 3, 'Why are your shoes still wet this morning? → Tại sao sáng nay giày của bạn vẫn còn ướt vậy?', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_11_1_3', 'en-a1-11', 'ten_11_1', 'listening', 'listening', 'I raised my hand to ask the teacher a question.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã kiểm tra lại thông tin thực tế trước khi đặt vé tàu.","Tôi vẫn nhớ mùi hương từ căn bếp của bà tôi.","Tại sao sáng nay giày của bạn vẫn còn ướt vậy?","Tôi giơ tay để hỏi giáo viên một câu hỏi."]'::jsonb, 3, 'I raised my hand to ask the teacher a question. → Tôi giơ tay để hỏi giáo viên một câu hỏi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_11_2', 'en-a1-11', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_11_2_1', 'ten_11_2', 'remember', 'Students often remember new vocabulary more effectively when they use it in meaningful conversations.', 'Students often remember new vocabulary more effectively when they use it in meaningful conversations.', '/rɪˈmembər/', 'Học sinh thường ghi nhớ từ vựng mới hiệu quả hơn khi các em sử dụng chúng trong các cuộc trò chuyện có ý nghĩa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_11_2_2', 'ten_11_2', 'why', 'Researchers need to understand why some students leave education before completing their secondary school qualifications.', 'Researchers need to understand why some students leave education before completing their secondary school qualifications.', '/waɪ/', 'Các nhà nghiên cứu cần tìm hiểu lý do tại sao một số học sinh bỏ học trước khi hoàn thành bằng cấp trung học.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_11_2_3', 'ten_11_2', 'question', 'Researchers increasingly question whether longer working hours actually improve productivity in modern office environments.', 'Researchers increasingly question whether longer working hours actually improve productivity in modern office environments.', '/ˈkwestʃən/', 'Các nhà nghiên cứu ngày càng hoài nghi về việc liệu thời gian làm việc kéo dài có thực sự cải thiện năng suất trong môi trường văn phòng hiện đại hay không.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_11_2_4', 'ten_11_2', 'fact', 'Students should learn to distinguish facts from opinions when evaluating information shared through digital media.', 'Students should learn to distinguish facts from opinions when evaluating information shared through digital media.', '/fækt/', 'Học sinh nên học cách phân biệt giữa sự thật và ý kiến cá nhân khi đánh giá thông tin được chia sẻ qua các phương tiện truyền thông kỹ thuật số.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_11_2_5', 'ten_11_2', 'TRUE', 'Students must assess whether online claims are TRUE before using them as evidence in academic essays.', 'Students must assess whether online claims are TRUE before using them as evidence in academic essays.', '/truː/', 'Học sinh phải đánh giá xem các thông tin trên mạng có đúng sự thật hay không trước khi sử dụng chúng làm bằng chứng trong các bài luận học thuật.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_11_2_6', 'ten_11_2', 'interesting', 'The survey revealed an interesting connection between access to green spaces and residents'' overall satisfaction with urban life.', 'The survey revealed an interesting connection between access to green spaces and residents'' overall satisfaction with urban life.', '/ˈɪntrəstɪŋ/', 'Cuộc khảo sát đã tiết lộ một mối liên hệ thú vị giữa khả năng tiếp cận không gian xanh và mức độ hài lòng chung của cư dân đối với cuộc sống đô thị.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
