INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_11_2_2', 'en-a1-11', 'ten_11_2', 'listening', 'listening', 'Researchers need to understand why some students leave education before completing their secondary school qualifications.', NULL, 'Trong câu vừa nghe, từ “why” mang nghĩa nào sau đây?', '["thứ hai","n. văn phòng; tòa nhà văn phòng","tại sao; vì sao","gọi điện thoại cho ai đó hoặc hét lên để thu hút sự chú ý"]'::jsonb, 2, '“why” (/waɪ/): tại sao; vì sao. Câu đầy đủ: Researchers need to understand why some students leave education before completing their secondary school qualifications.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
