INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_11_1', 'en-a1-11', NULL, 'comprehensive_test', 'listening', 'remember', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cây; cây gỗ","thuộc về hoặc liên quan đến Vương quốc Anh, người dân hoặc văn hóa nước này","xem; quan sát; theo dõi","nhớ; hồi tưởng"]'::jsonb, 3, 'remember (/rɪˈmembər/) → nhớ; hồi tưởng; nhớ phải làm gì; tưởng nhớ; ghi ơn', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_11_2', 'en-a1-11', NULL, 'comprehensive_test', 'listening', 'Why are your shoes still wet this morning?', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã kiểm tra lại thông tin thực tế trước khi đặt vé tàu.","Tại sao sáng nay giày của bạn vẫn còn ướt vậy?","Bạn có thể chọn một chỗ ngồi cạnh cửa sổ.","Kế hoạch của chúng tôi là khởi hành sớm để tránh ùn tắc giao thông."]'::jsonb, 1, 'Why are your shoes still wet this morning? → Tại sao sáng nay giày của bạn vẫn còn ướt vậy?', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_11_3', 'en-a1-11', NULL, 'comprehensive_test', 'listening', 'question', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đẹp; xinh đẹp; tuyệt vời","n. câu hỏi; thắc mắc","mua; tậu","quá (vượt mức mong muốn, cần thiết hoặc phù hợp)"]'::jsonb, 1, 'question (/ˈkwestʃən/) → n. câu hỏi; thắc mắc; n. vấn đề; đề tài cần thảo luận, xem xét hoặc quyết định; v. hỏi; đặt câu hỏi; chất vấn; hoài nghi', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_11_4', 'en-a1-11', NULL, 'comprehensive_test', 'listening', 'We checked the facts before booking our train tickets.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã kiểm tra lại thông tin thực tế trước khi đặt vé tàu.","Bạn có biết cách sửa chiếc xe đạp này không?","Bạn có thể chọn một chỗ ngồi cạnh cửa sổ.","Tôi tin bạn, nhưng câu chuyện của bạn nghe có vẻ khá bất thường."]'::jsonb, 0, 'We checked the facts before booking our train tickets. → Chúng tôi đã kiểm tra lại thông tin thực tế trước khi đặt vé tàu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_11_5', 'en-a1-11', NULL, 'comprehensive_test', 'listening', 'TRUE', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ai đó; một người nào đó","đúng sự thật; chính xác","thay đổi; đổi; quy đổi tiền tệ","n. bạn; bạn bè; chiến hữu"]'::jsonb, 1, 'TRUE (/truː/) → đúng sự thật; chính xác; đích thực; thực sự; trung thành; tận tụy', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_11_6', 'en-a1-11', NULL, 'comprehensive_test', 'listening', 'We found an interesting little museum near the station.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã tìm thấy một bảo tàng nhỏ thú vị gần nhà ga.","Tại sao sáng nay giày của bạn vẫn còn ướt vậy?","Tôi nghĩ món súp này cần thêm một chút muối.","Nếu trời mưa, chúng ta có thể chuyển sang chơi ở trong nhà."]'::jsonb, 0, 'We found an interesting little museum near the station. → Chúng tôi đã tìm thấy một bảo tàng nhỏ thú vị gần nhà ga.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_11_7', 'en-a1-11', NULL, 'comprehensive_test', 'listening', 'idea', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mùa xuân","hoạt động khiêu vũ; múa","sinh ra","ý tưởng; suy nghĩ; gợi ý"]'::jsonb, 3, 'idea (/aɪˈdiːə/) → ý tưởng; suy nghĩ; gợi ý; quan niệm; ý niệm; sự hiểu biết; ấn tượng sơ lược', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_11_8', 'en-a1-11', NULL, 'comprehensive_test', 'listening', 'The heavy rain was the reason we stayed home.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nếu trời mưa, chúng ta có thể chuyển sang chơi ở trong nhà.","Chúng tôi đã tìm thấy một bảo tàng nhỏ thú vị gần nhà ga.","Tôi đồng ý với bạn rằng món súp này cần thêm chút muối.","Cơn mưa lớn là lý do khiến chúng tôi ở nhà."]'::jsonb, 3, 'The heavy rain was the reason we stayed home. → Cơn mưa lớn là lý do khiến chúng tôi ở nhà.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_11_9', 'en-a1-11', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “matching the facts rather than being false or invented”?', '["idea","mistake","TRUE","know"]'::jsonb, 2, 'TRUE (/truː/) → đúng sự thật; chính xác', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_11_10', 'en-a1-11', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Making you want to pay attention or learn more.”?', '["forget","understand","interesting","maybe"]'::jsonb, 2, 'interesting (/ˈɪntrəstɪŋ/) → thú vị; hay; hấp dẫn', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_11_11', 'en-a1-11', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A thought or suggestion about what to do.”?', '["why","future","understand","idea"]'::jsonb, 3, 'idea (/aɪˈdiːə/) → ý tưởng; suy nghĩ; gợi ý', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_11_12', 'en-a1-11', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Something that explains why something happens or someone acts.”?', '["know","question","choose","reason"]'::jsonb, 3, 'reason (/ˈriːzən/) → lý do; nguyên nhân; cớ', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
