INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_11_18', 'en-a1-11', NULL, 'comprehensive_test', 'reading', NULL, 'Students often remember new vocabulary more effectively when they use it in meaningful conversations.', 'Dựa vào câu trên, từ “remember” có nghĩa phù hợp nhất là gì?', '["nhớ; hồi tưởng","nơi; địa điểm; chốn","buổi sáng; sáng","video; đoạn ghi hình ảnh chuyển động, thường có kèm âm thanh"]'::jsonb, 0, 'remember: nhớ; hồi tưởng; nhớ phải làm gì; tưởng nhớ; ghi ơn. Dịch cả câu: Học sinh thường ghi nhớ từ vựng mới hiệu quả hơn khi các em sử dụng chúng trong các cuộc trò chuyện có ý nghĩa.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_11_19', 'en-a1-11', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers need to understand why some students leave education before completing their secondary school qualifications.', 'Dựa vào câu trên, từ “why” có nghĩa phù hợp nhất là gì?', '["nhớ; hồi tưởng","địa lý học","tại sao; vì sao","động vật"]'::jsonb, 2, 'why: tại sao; vì sao; lý do. Dịch cả câu: Các nhà nghiên cứu cần tìm hiểu lý do tại sao một số học sinh bỏ học trước khi hoàn thành bằng cấp trung học.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_11_20', 'en-a1-11', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers increasingly question whether longer working hours actually improve productivity in modern office environments.', 'Dựa vào câu trên, từ “question” có nghĩa phù hợp nhất là gì?', '["Ca-na-đa","cha; bố","bán; tiêu thụ","n. câu hỏi; thắc mắc"]'::jsonb, 3, 'question: n. câu hỏi; thắc mắc; n. vấn đề; đề tài cần thảo luận, xem xét hoặc quyết định; v. hỏi; đặt câu hỏi; chất vấn; hoài nghi. Dịch cả câu: Các nhà nghiên cứu ngày càng hoài nghi về việc liệu thời gian làm việc kéo dài có thực sự cải thiện năng suất trong môi trường văn phòng hiện đại hay không.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_11_21', 'en-a1-11', NULL, 'comprehensive_test', 'reading', NULL, 'Students should learn to distinguish facts from opinions when evaluating information shared through digital media.', 'Dựa vào câu trên, từ “fact” có nghĩa phù hợp nhất là gì?', '["sự thật; thực tế","adj. thân thiện; cởi mở; niềm nở","di chuyển; dời chỗ ở","thú vị; hay; hấp dẫn"]'::jsonb, 0, 'fact: sự thật; thực tế. Dịch cả câu: Học sinh nên học cách phân biệt giữa sự thật và ý kiến cá nhân khi đánh giá thông tin được chia sẻ qua các phương tiện truyền thông kỹ thuật số.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_11_22', 'en-a1-11', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “có thể xảy ra; có thể thực hiện được”', '["twelve","possible","jacket","grandfather"]'::jsonb, 1, 'có thể xảy ra; có thể thực hiện được → possible (/ˈpɑːsəbl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_11_23', 'en-a1-11', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chắc chắn; tự tin”', '["book","cent","sure","coffee"]'::jsonb, 2, 'chắc chắn; tự tin → sure (/ʃʊr/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_11_24', 'en-a1-11', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “có lẽ; có thể”', '["class","hot","maybe","pasta"]'::jsonb, 2, 'có lẽ; có thể → maybe (/ˈmeɪbi/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-12', 'en', 'Bài 12: Cảm xúc & Tính cách - CEFR A1', 'CEFR A1', 'A1 · Cảm xúc', '18 từ vựng Tiếng Anh CEFR A1 chủ đề cảm xúc & tính cách kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1012, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lucky', 'en-a1-12', 'lucky', '/ˈlʌki/', 'A1', 'may mắn; mang lại vận may', 'adj.', 'luck (n.), luckily (adv.), unlucky (adj.), unluckily (adv.)', 'Đồng nghĩa: fortunate · Trái nghĩa: unlucky, unfortunate', 'Diễn đạt "có/thấy may mắn khi làm gì" dùng ''be lucky to do something''.', 'We were lucky to catch the last bus home.', NULL, 'Chúng tôi rất may mắn khi bắt được chuyến xe buýt cuối cùng về nhà.', '{"wordId":"lucky","ukIpa":"/ˈlʌki/","usIpa":"/ˈlʌki/","cefr":"A1","topic":"emotion","senses":[{"pos":"adj.","en":"Having good things happen by chance.","vi":"may mắn"},{"pos":"adj.","en":"Believed to bring good fortune.","vi":"mang lại vận may"}],"examples":[{"en":"We were lucky to catch the last bus home.","vi":"Chúng tôi rất may mắn khi bắt được chuyến xe buýt cuối cùng về nhà.","audioKind":"ex"},{"en":"Although some entrepreneurs benefit from lucky opportunities, long-term business success usually requires careful planning and consistent effort.","vi":"Mặc dù một số nhà khởi nghiệp hưởng lợi từ những cơ hội may mắn, nhưng thành công trong kinh doanh dài hạn thường đòi hỏi kế hoạch chu đáo và nỗ lực bền bỉ.","audioKind":"ex2"}],"collocations":[{"en":"lucky enough to","vi":"may mắn có thể"},{"en":"a lucky escape","vi":"thoát nạn trong gang tấc"},{"en":"a lucky charm","vi":"bùa may mắn"},{"en":"a lucky break","vi":"cơ hội may mắn"}],"wordFamily":["luck (n.)","luckily (adv.)","unlucky (adj.)","unluckily (adv.)"],"synonyms":["fortunate"],"antonyms":["unlucky","unfortunate"],"tipVi":"Diễn đạt \"có/thấy may mắn khi làm gì\" dùng ''be lucky to do something''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_angry', 'en-a1-12', 'angry', '/ˈæŋɡri/', 'A1', 'tức giận; cáu giận', 'adj.', 'anger (n.), anger (v.), angrily (adv.)', 'Đồng nghĩa: mad, furious · Trái nghĩa: calm', 'Tức giận với ai dùng angry with; tức giận về việc gì dùng about.', 'He felt angry when someone damaged his bicycle.', NULL, 'Anh ấy cảm thấy rất tức giận khi có ai đó làm hỏng chiếc xe đạp của mình.', '{"wordId":"angry","ukIpa":"/ˈæŋɡri/","usIpa":"/ˈæŋɡri/","cefr":"A1","topic":"emotion","senses":[{"pos":"adj.","en":"feeling strong displeasure about something unfair, wrong, or unpleasant","vi":"tức giận; cáu giận"}],"examples":[{"en":"He felt angry when someone damaged his bicycle.","vi":"Anh ấy cảm thấy rất tức giận khi có ai đó làm hỏng chiếc xe đạp của mình.","audioKind":"ex"},{"en":"Residents became angry about the council''s decision to close the only library in their neighbourhood.","vi":"Cư dân đã tỏ ra tức giận trước quyết định của hội đồng thành phố về việc đóng cửa thư viện duy nhất trong khu phố của họ.","audioKind":"ex2"}],"collocations":[{"en":"angry with someone","vi":"tức giận với ai đó"},{"en":"angry about something","vi":"tức giận về điều gì đó"},{"en":"get angry","vi":"nổi giận"}],"wordFamily":["anger (n.)","anger (v.)","angrily (adv.)"],"synonyms":["mad","furious"],"antonyms":["calm"],"tipVi":"Tức giận với ai dùng angry with; tức giận về việc gì dùng about.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_smile', 'en-a1-12', 'smile', '/smaɪl/', 'A1', 'cười; mỉm cười; nụ cười', 'v.', 'smiling (adj.)', 'Trái nghĩa: frown', 'Cười với ai đó dùng smile at, không dùng smile to.', 'The baby smiled when I waved across the room.', NULL, 'Em bé mỉm cười khi tôi vẫy tay từ phía bên kia căn phòng.', '{"wordId":"smile","ukIpa":"/smaɪl/","usIpa":"/smaɪl/","cefr":"A1","topic":"emotion","senses":[{"pos":"v.","en":"To raise the corners of your mouth, showing happiness or friendliness.","vi":"cười; mỉm cười"},{"pos":"n.","en":"A facial expression with raised mouth corners, often showing happiness.","vi":"nụ cười"}],"examples":[{"en":"The baby smiled when I waved across the room.","vi":"Em bé mỉm cười khi tôi vẫy tay từ phía bên kia căn phòng.","audioKind":"ex"},{"en":"A friendly smile can help patients feel more comfortable when discussing their concerns with healthcare professionals.","vi":"Một nụ cười thân thiện có thể giúp bệnh nhân cảm thấy thoải mái hơn khi thảo luận về những lo lắng của họ với các chuyên gia y tế.","audioKind":"ex2"}],"collocations":[{"en":"smile at someone","vi":"cười với ai đó"},{"en":"a warm smile","vi":"nụ cười ấm áp"},{"en":"a broad smile","vi":"nụ cười tươi rạng rỡ"}],"wordFamily":["smiling (adj.)"],"synonyms":[],"antonyms":["frown"],"tipVi":"Cười với ai đó dùng smile at, không dùng smile to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exciting', 'en-a1-12', 'exciting', '/ɪkˈsaɪtɪŋ/', 'A1', 'thú vị; kích thích; làm phấn khích', 'adj.', 'excite (v.), excited (adj.), excitement (n.), excitedly (adv.)', 'Đồng nghĩa: thrilling, exhilarating · Trái nghĩa: boring, dull', 'exciting dùng cho sự vật/sự việc gây phấn khích; excited dùng cho cảm xúc của con người.', 'The final minutes of the match were incredibly exciting.', NULL, 'Những phút cuối của trận đấu vô cùng gay cấn và thú vị.', '{"wordId":"exciting","ukIpa":"/ɪkˈsaɪtɪŋ/","usIpa":"/ɪkˈsaɪtɪŋ/","cefr":"A1","topic":"emotion","senses":[{"pos":"adj.","en":"Making someone feel eager, enthusiastic, or thrilled.","vi":"thú vị; kích thích; làm phấn khích"}],"examples":[{"en":"The final minutes of the match were incredibly exciting.","vi":"Những phút cuối của trận đấu vô cùng gay cấn và thú vị.","audioKind":"ex"},{"en":"Advances in renewable energy offer exciting opportunities for young engineers seeking to address global environmental challenges.","vi":"Sự tiến bộ trong năng lượng tái tạo mang đến những cơ hội đầy phấn khích cho các kỹ sư trẻ đang tìm cách giải quyết các thách thức môi trường toàn cầu.","audioKind":"ex2"}],"collocations":[{"en":"exciting opportunity","vi":"cơ hội đầy triển vọng"},{"en":"exciting development","vi":"tiến triển đáng mừng"},{"en":"exciting experience","vi":"trải nghiệm thú vị"}],"wordFamily":["excite (v.)","excited (adj.)","excitement (n.)","excitedly (adv.)"],"synonyms":["thrilling","exhilarating"],"antonyms":["boring","dull"],"tipVi":"exciting dùng cho sự vật/sự việc gây phấn khích; excited dùng cho cảm xúc của con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_afraid', 'en-a1-12', 'afraid', '/əˈfreɪd/', 'A1', 'sợ; lo sợ; e ngại; e rằng; lấy làm tiếc (dùng để thông báo điều không vui một cách lịch sự)', 'adj.', NULL, 'Đồng nghĩa: frightened, scared · Trái nghĩa: unafraid', 'Thường làm vị ngữ sau to be, không đứng trước danh từ; dùng cấu trúc afraid of hoặc afraid to do.', 'The puppy was afraid of the noisy vacuum cleaner.', NULL, 'Chú cún con rất sợ tiếng ồn của máy hút bụi.', '{"wordId":"afraid","ukIpa":"/əˈfreɪd/","usIpa":"/əˈfreɪd/","cefr":"A1","topic":"emotion","senses":[{"pos":"adj.","en":"feeling fear or worry about something","vi":"sợ; lo sợ; e ngại"},{"pos":"adj.","en":"used to introduce unwelcome information politely","vi":"e rằng; lấy làm tiếc (dùng để thông báo điều không vui một cách lịch sự)"}],"examples":[{"en":"The puppy was afraid of the noisy vacuum cleaner.","vi":"Chú cún con rất sợ tiếng ồn của máy hút bụi.","audioKind":"ex"},{"en":"Some employees are afraid to report workplace problems because they worry about losing their jobs.","vi":"Một số nhân viên e ngại phản ánh các vấn đề tại nơi làm việc vì họ lo sợ bị mất việc.","audioKind":"ex2"}],"collocations":[{"en":"afraid of","vi":"sợ..."},{"en":"afraid to ask","vi":"không dám hỏi"},{"en":"afraid of making mistakes","vi":"sợ mắc lỗi"},{"en":"I''m afraid that","vi":"tôi e rằng..."}],"wordFamily":[],"synonyms":["frightened","scared"],"antonyms":["unafraid"],"tipVi":"Thường làm vị ngữ sau to be, không đứng trước danh từ; dùng cấu trúc afraid of hoặc afraid to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_boring', 'en-a1-12', 'boring', '/ˈbɔːrɪŋ/', 'A1', 'nhàm chán; tẻ nhạt', 'adj.', 'bore (v.), bored (adj.), boredom (n.), boringly (adv.)', 'Đồng nghĩa: dull, tedious, uninteresting · Trái nghĩa: interesting, exciting', 'boring chỉ đặc điểm của sự vật/sự việc (gây cảm giác chán ngắt); bored chỉ cảm xúc của con người (cảm thấy buồn chán).', 'The film was so boring that I fell asleep.', NULL, 'Bộ phim chán đến mức tôi ngủ thiếp đi.', '{"wordId":"boring","ukIpa":"/ˈbɔːrɪŋ/","usIpa":"/ˈbɔːrɪŋ/","cefr":"A1","topic":"emotion","senses":[{"pos":"adj.","en":"Not interesting or exciting.","vi":"nhàm chán; tẻ nhạt"}],"examples":[{"en":"The film was so boring that I fell asleep.","vi":"Bộ phim chán đến mức tôi ngủ thiếp đi.","audioKind":"ex"},{"en":"Students may find repetitive exercises boring unless teachers explain their purpose and introduce variety.","vi":"Học sinh có thể thấy các bài tập lặp đi lặp lại rất tẻ nhạt trừ khi giáo viên giải thích mục đích của chúng và lồng ghép thêm nhiều hình thức đa dạng.","audioKind":"ex2"}],"collocations":[{"en":"boring task","vi":"nhiệm vụ tẻ nhạt"},{"en":"boring lecture","vi":"bài giảng khô khan"},{"en":"find something boring","vi":"thấy điều gì đó nhàm chán"}],"wordFamily":["bore (v.)","bored (adj.)","boredom (n.)","boringly (adv.)"],"synonyms":["dull","tedious","uninteresting"],"antonyms":["interesting","exciting"],"tipVi":"boring chỉ đặc điểm của sự vật/sự việc (gây cảm giác chán ngắt); bored chỉ cảm xúc của con người (cảm thấy buồn chán).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wonderful', 'en-a1-12', 'wonderful', '/ˈwʌndɚfəl/', 'A1', 'tuyệt vời; kỳ diệu', 'adj.', 'wonder (n.), wonder (v.), wonderfully (adv.)', 'Đồng nghĩa: excellent, fantastic, marvellous · Trái nghĩa: awful, terrible', 'Mang nghĩa cực kỳ tốt hoặc thú vị, không mang nghĩa là kỳ lạ.', 'We had a wonderful picnic beside the lake.', NULL, 'Chúng tôi đã có một buổi dã ngoại tuyệt vời bên hồ.', '{"wordId":"wonderful","ukIpa":"/ˈwʌndəfəl/","usIpa":"/ˈwʌndɚfəl/","cefr":"A1","topic":"emotion","senses":[{"pos":"adj.","en":"Extremely good or enjoyable.","vi":"tuyệt vời; kỳ diệu"}],"examples":[{"en":"We had a wonderful picnic beside the lake.","vi":"Chúng tôi đã có một buổi dã ngoại tuyệt vời bên hồ.","audioKind":"ex"},{"en":"Public libraries offer wonderful opportunities for children to discover new interests without placing financial pressure on families.","vi":"Các thư viện công cộng mang lại những cơ hội tuyệt vời để trẻ em khám phá những sở thích mới mà không gây áp lực tài chính cho gia đình.","audioKind":"ex2"}],"collocations":[{"en":"a wonderful experience","vi":"một trải nghiệm tuyệt vời"},{"en":"a wonderful opportunity","vi":"một cơ hội tuyệt vời"},{"en":"wonderful news","vi":"tin vui; tin tuyệt vời"}],"wordFamily":["wonder (n.)","wonder (v.)","wonderfully (adv.)"],"synonyms":["excellent","fantastic","marvellous"],"antonyms":["awful","terrible"],"tipVi":"Mang nghĩa cực kỳ tốt hoặc thú vị, không mang nghĩa là kỳ lạ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_love', 'en-a1-12', 'love', '/lʌv/', 'A1', 'yêu; quý mến; rất thích; tình yêu; lòng nhiệt thành', 'v.', 'loving (adj.), lovable (adj.), lovely (adj.)', 'Đồng nghĩa: adore · Trái nghĩa: hate', 'Cả love doing và love to do đều dùng được để diễn tả sở thích.', 'I love walking by the river after dinner.', NULL, 'Tôi rất thích đi dạo dọc bờ sông sau bữa tối.', '{"wordId":"love","ukIpa":"/lʌv/","usIpa":"/lʌv/","cefr":"A1","topic":"emotion","senses":[{"pos":"v.","en":"feel deep affection for someone or enjoy something very much","vi":"yêu; quý mến; rất thích"},{"pos":"n.","en":"a strong feeling of affection or great enjoyment","vi":"tình yêu; lòng nhiệt thành"}],"examples":[{"en":"I love walking by the river after dinner.","vi":"Tôi rất thích đi dạo dọc bờ sông sau bữa tối.","audioKind":"ex"},{"en":"Schools can develop children''s love of reading by providing diverse books and regular library visits.","vi":"Nhà trường có thể khơi gợi tình yêu đọc sách ở trẻ em thông qua việc cung cấp đa dạng đầu sách và duy trì lịch thăm thư viện thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"fall in love","vi":"phải lòng; yêu"},{"en":"love of learning","vi":"niềm đam mê học hỏi"},{"en":"love doing something","vi":"thích làm gì đó"}],"wordFamily":["loving (adj.)","lovable (adj.)","lovely (adj.)"],"synonyms":["adore"],"antonyms":["hate"],"tipVi":"Cả love doing và love to do đều dùng được để diễn tả sở thích.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cry', 'en-a1-12', 'cry', '/kraɪ/', 'A1', 'khóc; rơi nước mắt; la lớn; kêu gọi; tiếng kêu; tiếng khóc', 'v.', 'crying (n.)', 'Đồng nghĩa: weep, sob', 'Quá khứ là cried; V-ing là crying; gọi lớn dùng cry out.', 'The baby began to cry when her toy fell.', NULL, 'Em bé bắt đầu khóc khi món đồ chơi bị rơi xuống.', '{"wordId":"cry","ukIpa":"/kraɪ/","usIpa":"/kraɪ/","cefr":"A1","topic":"emotion","senses":[{"pos":"v.","en":"Produce tears because of sadness, pain, or strong emotion.","vi":"khóc; rơi nước mắt"},{"pos":"v.","en":"Call out loudly because of strong emotion or urgent need.","vi":"la lớn; kêu gọi"},{"pos":"n.","en":"A loud sound expressing emotion or attracting attention.","vi":"tiếng kêu; tiếng khóc"}],"examples":[{"en":"The baby began to cry when her toy fell.","vi":"Em bé bắt đầu khóc khi món đồ chơi bị rơi xuống.","audioKind":"ex"},{"en":"Young children may cry when separated from their parents, so schools should provide a welcoming environment.","vi":"Trẻ nhỏ có thể khóc khi phải xa bố mẹ, vì vậy nhà trường cần tạo ra một môi trường thân thiện, chào đón.","audioKind":"ex2"}],"collocations":[{"en":"cry for help","vi":"kêu cứu"},{"en":"cry with joy","vi":"khóc vì hạnh phúc"},{"en":"a loud cry","vi":"tiếng hét lớn"},{"en":"have a good cry","vi":"khóc một trận đã đời"}],"wordFamily":["crying (n.)"],"synonyms":["weep","sob"],"antonyms":[],"tipVi":"Quá khứ là cried; V-ing là crying; gọi lớn dùng cry out.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_feeling', 'en-a1-12', 'feeling', '/ˈfiːlɪŋ/', 'A1', 'cảm xúc; tâm trạng; cảm giác; xúc giác; linh cảm; quan điểm', 'n.', 'feel (v.)', 'Đồng nghĩa: emotion, sensation', 'feelings thường chỉ cảmף; have a feeling that biểu thị linh cảm.', 'A feeling of relief washed over me after the exam.', NULL, 'Cảm giác nhẹ nhõm tràn ngập trong tôi sau kỳ thi.', '{"wordId":"feeling","ukIpa":"/ˈfiːlɪŋ/","usIpa":"/ˈfiːlɪŋ/","cefr":"A1","topic":"emotion","senses":[{"pos":"n.","en":"An emotional state or response to something","vi":"cảm xúc; tâm trạng"},{"pos":"n.","en":"A physical sensation or the ability to sense touch","vi":"cảm giác; xúc giác"},{"pos":"n.","en":"An impression or belief not necessarily supported by evidence","vi":"linh cảm; quan điểm"}],"examples":[{"en":"A feeling of relief washed over me after the exam.","vi":"Cảm giác nhẹ nhõm tràn ngập trong tôi sau kỳ thi.","audioKind":"ex"},{"en":"A strong feeling of belonging can improve students'' confidence and encourage participation in school activities.","vi":"Cảm giác thân thuộc mạnh mẽ có thể nâng cao sự tự tin của học sinh và khuyến khích các em tham gia các hoạt động trường học.","audioKind":"ex2"}],"collocations":[{"en":"a feeling of relief","vi":"cảm giác nhẹ nhõm"},{"en":"hurt someone''s feelings","vi":"làm tổn thương tình cảm của ai đó"},{"en":"lose feeling","vi":"mất cảm giác"},{"en":"mixed feelings","vi":"tâm trạng phức tạp"}],"wordFamily":["feel (v.)"],"synonyms":["emotion","sensation"],"antonyms":[],"tipVi":"feelings thường chỉ cảmף; have a feeling that biểu thị linh cảm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_funny', 'en-a1-12', 'funny', '/ˈfʌni/', 'A1', 'vui nhộn; buồn cười; hài hước; kỳ lạ; khó giải thích; bất thường', 'adj.', 'funnily (adv.), funniness (n.)', 'Đồng nghĩa: amusing, humorous, odd · Trái nghĩa: unfunny', 'funny thiên về gây cười hoặc kỳ lạ; fun thiên về sự thú vị, mang lại niềm vui.', 'That funny story made everyone at the table laugh.', NULL, 'Câu chuyện hài hước đó đã làm cho mọi người ở bàn cười vang.', '{"wordId":"funny","ukIpa":"/ˈfʌni/","usIpa":"/ˈfʌni/","cefr":"A1","topic":"emotion","senses":[{"pos":"adj.","en":"making you laugh or smile","vi":"vui nhộn; buồn cười; hài hước"},{"pos":"adj.","en":"unusual or difficult to explain","vi":"kỳ lạ; khó giải thích; bất thường"}],"examples":[{"en":"That funny story made everyone at the table laugh.","vi":"Câu chuyện hài hước đó đã làm cho mọi người ở bàn cười vang.","audioKind":"ex"},{"en":"Teachers sometimes use funny examples to make difficult concepts more memorable and encourage students to participate.","vi":"Giáo viên đôi khi sử dụng các ví dụ hài hước để giúp các khái niệm khó trở nên dễ nhớ hơn và khuyến khích học sinh tham gia.","audioKind":"ex2"}],"collocations":[{"en":"a funny story","vi":"một câu chuyện vui"},{"en":"a funny joke","vi":"một câu nói đùa vui nhộn"},{"en":"a funny smell","vi":"một mùi lạ"},{"en":"find something funny","vi":"thấy điều gì đó buồn cười"}],"wordFamily":["funnily (adv.)","funniness (n.)"],"synonyms":["amusing","humorous","odd"],"antonyms":["unfunny"],"tipVi":"funny thiên về gây cười hoặc kỳ lạ; fun thiên về sự thú vị, mang lại niềm vui.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hate', 'en-a1-12', 'hate', '/heɪt/', 'A1', 'căm ghét; rất ghét; sự căm thù; mối thù hằn', 'v.', 'hatred (n.), hateful (adj.)', 'Đồng nghĩa: loathe, detest · Trái nghĩa: love', 'hate có thể đi với danh động từ hoặc động từ nguyên thể, mang sắc thái mạnh hơn dislike.', 'I hate finding wet socks on the bathroom floor.', NULL, 'Tôi cực kỳ ghét việc thấy tất vớ ướt trên sàn phòng tắm.', '{"wordId":"hate","ukIpa":"/heɪt/","usIpa":"/heɪt/","cefr":"A1","topic":"emotion","senses":[{"pos":"v.","en":"To dislike someone or something very strongly.","vi":"căm ghét; rất ghét"},{"pos":"n.","en":"A very strong feeling of dislike towards someone or something.","vi":"sự căm thù; mối thù hằn"}],"examples":[{"en":"I hate finding wet socks on the bathroom floor.","vi":"Tôi cực kỳ ghét việc thấy tất vớ ướt trên sàn phòng tắm.","audioKind":"ex"},{"en":"Although many commuters hate crowded trains, affordable public transport remains essential for reducing urban traffic.","vi":"Mặc dù nhiều người đi làm ghét cảnh tàu xe đông đúc, giao thông công cộng giá rẻ vẫn đóng vai trò thiết yếu trong việc giảm thiểu ùn tắc đô thị.","audioKind":"ex2"}],"collocations":[{"en":"hate doing something","vi":"ghét làm việc gì"},{"en":"hate to admit","vi":"không thích thừa nhận; ngại thừa nhận"},{"en":"full of hate","vi":"đầy lòng căm thù"}],"wordFamily":["hatred (n.)","hateful (adj.)"],"synonyms":["loathe","detest"],"antonyms":["love"],"tipVi":"hate có thể đi với danh động từ hoặc động từ nguyên thể, mang sắc thái mạnh hơn dislike.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_feel', 'en-a1-12', 'feel', '/fiːl/', 'A1', 'cảm thấy; thấy; sờ; chạm; dò dẫm; cảm giác; bầu không khí', 'v.', 'feeling (n.)', 'Đồng nghĩa: sense, experience', 'Thì quá khứ và phân từ hai đều là felt; sau feel có thể trực tiếp dùng tính từ.', 'I feel much warmer with this soft blanket.', NULL, 'Tôi cảm thấy ấm hơn nhiều với chiếc chăn mềm mại này.', '{"wordId":"feel","ukIpa":"/fiːl/","usIpa":"/fiːl/","cefr":"A1","topic":"emotion","senses":[{"pos":"v.","en":"Experience an emotion, physical sensation, or personal belief.","vi":"cảm thấy; thấy"},{"pos":"v.","en":"Touch something to discover its texture, shape, or position.","vi":"sờ; chạm; dò dẫm"},{"pos":"n.","en":"The quality something has when touched or experienced.","vi":"cảm giác; bầu không khí"}],"examples":[{"en":"I feel much warmer with this soft blanket.","vi":"Tôi cảm thấy ấm hơn nhiều với chiếc chăn mềm mại này.","audioKind":"ex"},{"en":"Residents often feel safer when public spaces are well lit and regularly maintained by local authorities.","vi":"Cư dân thường cảm thấy an toàn hơn khi các không gian công cộng được chiếu sáng tốt và được chính quyền địa phương bảo trì thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"feel comfortable","vi":"cảm thấy thoải mái"},{"en":"feel strongly about","vi":"có quan điểm mạnh mẽ về"},{"en":"feel like doing something","vi":"có hứng làm việc gì"},{"en":"get a feel for","vi":"dần làm quen với"}],"wordFamily":["feeling (n.)"],"synonyms":["sense","experience"],"antonyms":[],"tipVi":"Thì quá khứ và phân từ hai đều là felt; sau feel có thể trực tiếp dùng tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dear', 'en-a1-12', 'dear', '/dɪr/', 'A1', 'thân yêu; quý giá; được trân trọng; đắt đỏ; ôi chao; trời ơi (dùng để diễn tả sự ngạc nhiên, lo lắng hoặc thất vọng)', 'adj.', 'dearly (adv.)', 'Đồng nghĩa: beloved, precious', 'Từ dear mang nghĩa "đắt" chủ yếu được dùng trong tiếng Anh-Anh; từ này cũng thường dùng ở đầu thư để xưng hô (Dear).', 'This little garden is very dear to my grandmother.', NULL, 'Khu vườn nhỏ này rất thân thương đối với bà tôi.', '{"wordId":"dear","ukIpa":"/dɪə/","usIpa":"/dɪr/","cefr":"A1","topic":"emotion","senses":[{"pos":"adj.","en":"loved or valued very much","vi":"thân yêu; quý giá; được trân trọng"},{"pos":"adj.","en":"costing a lot of money","vi":"đắt đỏ"},{"pos":"int.","en":"used to express surprise, worry, or disappointment","vi":"ôi chao; trời ơi (dùng để diễn tả sự ngạc nhiên, lo lắng hoặc thất vọng)"}],"examples":[{"en":"This little garden is very dear to my grandmother.","vi":"Khu vườn nhỏ này rất thân thương đối với bà tôi.","audioKind":"ex"},{"en":"Places that are dear to local residents deserve consideration when urban redevelopment plans are prepared.","vi":"Những địa điểm gắn bó sâu sắc với người dân địa phương cần được xem xét cẩn trọng khi lập kế hoạch tái phát triển đô thị.","audioKind":"ex2"}],"collocations":[{"en":"a dear friend","vi":"một người bạn thân thiết"},{"en":"dear to someone","vi":"quý giá đối với ai"},{"en":"oh dear","vi":"ôi trời ơi"}],"wordFamily":["dearly (adv.)"],"synonyms":["beloved","precious"],"antonyms":[],"tipVi":"Từ dear mang nghĩa \"đắt\" chủ yếu được dùng trong tiếng Anh-Anh; từ này cũng thường dùng ở đầu thư để xưng hô (Dear).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sorry', 'en-a1-12', 'sorry', '/ˈsɑːri/', 'A1', 'tiếc; hối hận; buồn; thương cảm', 'adj.', NULL, 'Đồng nghĩa: apologetic, regretful', 'sorry for doing biểu thị sự hối lỗi về việc đã làm.', 'I''m sorry I spilled juice on your clean shirt.', NULL, 'Tôi xin lỗi vì đã làm đổ nước ép lên chiếc áo sơ mi sạch của bạn.', '{"wordId":"sorry","ukIpa":"/ˈsɒri/","usIpa":"/ˈsɑːri/","cefr":"A1","topic":"emotion","senses":[{"pos":"adj.","en":"feeling regret about something you did or something that happened","vi":"tiếc; hối hận"},{"pos":"adj.","en":"feeling sadness or sympathy because of someone''s difficulties","vi":"buồn; thương cảm"}],"examples":[{"en":"I''m sorry I spilled juice on your clean shirt.","vi":"Tôi xin lỗi vì đã làm đổ nước ép lên chiếc áo sơ mi sạch của bạn.","audioKind":"ex"},{"en":"Although companies may say they are sorry for environmental damage, meaningful action is needed to restore public trust.","vi":"Mặc dù các công ty có thể bày tỏ sự hối tiếc vì tổn hại môi trường, nhưng cần phải có hành động thiết thực để khôi phục niềm tin của công chúng.","audioKind":"ex2"}],"collocations":[{"en":"sorry for being late","vi":"xin lỗi vì đến muộn"},{"en":"sorry about the mistake","vi":"xin lỗi về sai sót"},{"en":"feel sorry for someone","vi":"thương cảm cho ai đó"},{"en":"sorry to hear that","vi":"thật buồn khi nghe tin đó"}],"wordFamily":[],"synonyms":["apologetic","regretful"],"antonyms":[],"tipVi":"sorry for doing biểu thị sự hối lỗi về việc đã làm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_laugh', 'en-a1-12', 'laugh', '/læf/', 'A1', 'cười; phát ra tiếng cười; tiếng cười', 'v.', 'laughter (n.), laughable (adj.)', 'Đồng nghĩa: chuckle · Trái nghĩa: cry', 'laugh at ai đó thường mang nghĩa chế nhạo; laugh with ai đó nghĩa là cùng cười với họ.', 'The baby''s funny dance made everyone laugh at dinner.', NULL, 'Điệu nhảy hài hước của em bé đã làm cho mọi người cười vang trong bữa tối.', '{"wordId":"laugh","ukIpa":"/lɑːf/","usIpa":"/læf/","cefr":"A1","topic":"emotion","senses":[{"pos":"v.","en":"To make sounds showing amusement or happiness.","vi":"cười; phát ra tiếng cười"},{"pos":"n.","en":"The sound or act of expressing amusement.","vi":"tiếng cười"}],"examples":[{"en":"The baby''s funny dance made everyone laugh at dinner.","vi":"Điệu nhảy hài hước của em bé đã làm cho mọi người cười vang trong bữa tối.","audioKind":"ex"},{"en":"People who laugh together regularly may develop stronger social bonds and cope better with everyday stress.","vi":"Những người thường xuyên cùng nhau cười đùa có thể xây dựng mối quan hệ xã hội khăng khít hơn và đối phó tốt hơn với áp lực hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"laugh out loud","vi":"cười lớn"},{"en":"make someone laugh","vi":"làm ai đó cười"},{"en":"laugh at a joke","vi":"cười trước một câu nói đùa"},{"en":"a hearty laugh","vi":"một tràng cười sảng khoái"}],"wordFamily":["laughter (n.)","laughable (adj.)"],"synonyms":["chuckle"],"antonyms":["cry"],"tipVi":"laugh at ai đó thường mang nghĩa chế nhạo; laugh with ai đó nghĩa là cùng cười với họ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_interested', 'en-a1-12', 'interested', '/ˈɪntrəstɪd/', 'A1', 'quan tâm; có hứng thú; có liên quan đến quyền lợi', 'adj.', 'interest (n.), interest (v.), interesting (adj.), interestingly (adv.)', 'Trái nghĩa: uninterested', 'Người cảm thấy có hứng thú dùng interested; theo sau là in cộng với danh từ hoặc danh động từ.', 'My sister is interested in learning to grow vegetables.', NULL, 'Chị gái tôi rất thích học trồng rau.', '{"wordId":"interested","ukIpa":"/ˈɪntrəstɪd/","usIpa":"/ˈɪntrəstɪd/","cefr":"A1","topic":"emotion","senses":[{"pos":"adj.","en":"Wanting to learn about or take part in something.","vi":"quan tâm; có hứng thú"},{"pos":"adj.","en":"Likely to be affected by a situation or decision.","vi":"có liên quan đến quyền lợi"}],"examples":[{"en":"My sister is interested in learning to grow vegetables.","vi":"Chị gái tôi rất thích học trồng rau.","audioKind":"ex"},{"en":"Students who are interested in science should have regular opportunities to conduct practical experiments.","vi":"Những học sinh quan tâm đến khoa học nên có cơ hội thường xuyên thực hiện các thí nghiệm thực tế.","audioKind":"ex2"}],"collocations":[{"en":"interested in","vi":"quan tâm đến"},{"en":"interested to hear","vi":"hứng thú khi nghe"},{"en":"interested parties","vi":"các bên liên quan"}],"wordFamily":["interest (n.)","interest (v.)","interesting (adj.)","interestingly (adv.)"],"synonyms":[],"antonyms":["uninterested"],"tipVi":"Người cảm thấy có hứng thú dùng interested; theo sau là in cộng với danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_excited', 'en-a1-12', 'excited', '/ɪkˈsaɪtɪd/', 'A1', 'hứng khởi; hào hứng; phấn khích', 'adj.', 'excite (v.), excitement (n.), exciting (adj.), excitedly (adv.)', 'Đồng nghĩa: thrilled, enthusiastic · Trái nghĩa: bored', 'Dùng excited khi chỉ cảm xúc của con người; dùng exciting để chỉ sự vật, sự việc gây hứng thú.', 'The children were excited about their first camping trip.', NULL, 'Bọn trẻ vô cùng hào hứng về chuyến cắm trại đầu tiên của chúng.', '{"wordId":"excited","ukIpa":"/ɪkˈsaɪtɪd/","usIpa":"/ɪkˈsaɪtɪd/","cefr":"A1","topic":"emotion","senses":[{"pos":"adj.","en":"Feeling very happy and enthusiastic about something.","vi":"hứng khởi; hào hứng; phấn khích"}],"examples":[{"en":"The children were excited about their first camping trip.","vi":"Bọn trẻ vô cùng hào hứng về chuyến cắm trại đầu tiên của chúng.","audioKind":"ex"},{"en":"Students are often more excited about learning when lessons involve practical experiments and opportunities for discovery.","vi":"Học sinh thường có hứng thú học tập hơn khi các bài học bao gồm các thí nghiệm thực tế và cơ hội khám phá.","audioKind":"ex2"}],"collocations":[{"en":"excited about","vi":"hào hứng về điều gì"},{"en":"excited to hear","vi":"rất đỗi vui mừng khi nghe tin"},{"en":"get excited","vi":"trở nên phấn khích"}],"wordFamily":["excite (v.)","excitement (n.)","exciting (adj.)","excitedly (adv.)"],"synonyms":["thrilled","enthusiastic"],"antonyms":["bored"],"tipVi":"Dùng excited khi chỉ cảm xúc của con người; dùng exciting để chỉ sự vật, sự việc gây hứng thú.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_12_1', 'en-a1-12', 'Cách dùng “boring” (adj.) — nhàm chán; tẻ nhạt', 'boring task  ·  boring lecture  ·  find something boring', 'boring chỉ đặc điểm của sự vật/sự việc (gây cảm giác chán ngắt); bored chỉ cảm xúc của con người (cảm thấy buồn chán).', 'Họ từ (Word Family): bore (v.), bored (adj.), boredom (n.), boringly (adv.) | Đồng nghĩa: dull, tedious, uninteresting | Trái nghĩa: interesting, exciting', '[{"hanzi":"The film was so boring that I fell asleep.","pinyin":"","meaning":"Bộ phim chán đến mức tôi ngủ thiếp đi."},{"hanzi":"Students may find repetitive exercises boring unless teachers explain their purpose and introduce variety.","pinyin":"","meaning":"Học sinh có thể thấy các bài tập lặp đi lặp lại rất tẻ nhạt trừ khi giáo viên giải thích mục đích của chúng và lồng ghép thêm nhiều hình thức đa dạng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_12_2', 'en-a1-12', 'Cách dùng “dear” (adj.) — thân yêu; quý giá; được trân trọng', 'a dear friend  ·  dear to someone  ·  oh dear', 'Từ dear mang nghĩa "đắt" chủ yếu được dùng trong tiếng Anh-Anh; từ này cũng thường dùng ở đầu thư để xưng hô (Dear).', 'Họ từ (Word Family): dearly (adv.) | Đồng nghĩa: beloved, precious', '[{"hanzi":"This little garden is very dear to my grandmother.","pinyin":"","meaning":"Khu vườn nhỏ này rất thân thương đối với bà tôi."},{"hanzi":"Places that are dear to local residents deserve consideration when urban redevelopment plans are prepared.","pinyin":"","meaning":"Những địa điểm gắn bó sâu sắc với người dân địa phương cần được xem xét cẩn trọng khi lập kế hoạch tái phát triển đô thị."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_12_3', 'en-a1-12', 'Cách dùng “afraid” (adj.) — sợ; lo sợ; e ngại', 'afraid of  ·  afraid to ask  ·  afraid of making mistakes', 'Thường làm vị ngữ sau to be, không đứng trước danh từ; dùng cấu trúc afraid of hoặc afraid to do.', 'Đồng nghĩa: frightened, scared | Trái nghĩa: unafraid', '[{"hanzi":"The puppy was afraid of the noisy vacuum cleaner.","pinyin":"","meaning":"Chú cún con rất sợ tiếng ồn của máy hút bụi."},{"hanzi":"Some employees are afraid to report workplace problems because they worry about losing their jobs.","pinyin":"","meaning":"Một số nhân viên e ngại phản ánh các vấn đề tại nơi làm việc vì họ lo sợ bị mất việc."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_12_4', 'en-a1-12', 'Cách dùng “interested” (adj.) — quan tâm; có hứng thú', 'interested in  ·  interested to hear  ·  interested parties', 'Người cảm thấy có hứng thú dùng interested; theo sau là in cộng với danh từ hoặc danh động từ.', 'Họ từ (Word Family): interest (n.), interest (v.), interesting (adj.), interestingly (adv.) | Trái nghĩa: uninterested', '[{"hanzi":"My sister is interested in learning to grow vegetables.","pinyin":"","meaning":"Chị gái tôi rất thích học trồng rau."},{"hanzi":"Students who are interested in science should have regular opportunities to conduct practical experiments.","pinyin":"","meaning":"Những học sinh quan tâm đến khoa học nên có cơ hội thường xuyên thực hiện các thí nghiệm thực tế."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_12_1', 'en-a1-12', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
