INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_12_1_1', 'en-a1-12', 'ten_12_1', 'listening', 'listening', 'We were lucky to catch the last bus home.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chú cún con rất sợ tiếng ồn của máy hút bụi.","Chúng tôi rất may mắn khi bắt được chuyến xe buýt cuối cùng về nhà.","Những phút cuối của trận đấu vô cùng gay cấn và thú vị.","Chúng tôi đã có một buổi dã ngoại tuyệt vời bên hồ."]'::jsonb, 1, 'We were lucky to catch the last bus home. → Chúng tôi rất may mắn khi bắt được chuyến xe buýt cuối cùng về nhà.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
