INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_12_2_1', 'ten_12_2', 'lucky', 'Although some entrepreneurs benefit from lucky opportunities, long-term business success usually requires careful planning and consistent effort.', 'Although some entrepreneurs benefit from lucky opportunities, long-term business success usually requires careful planning and consistent effort.', '/ˈlʌki/', 'Mặc dù một số nhà khởi nghiệp hưởng lợi từ những cơ hội may mắn, nhưng thành công trong kinh doanh dài hạn thường đòi hỏi kế hoạch chu đáo và nỗ lực bền bỉ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_12_2_2', 'ten_12_2', 'angry', 'Residents became angry about the council''s decision to close the only library in their neighbourhood.', 'Residents became angry about the council''s decision to close the only library in their neighbourhood.', '/ˈæŋɡri/', 'Cư dân đã tỏ ra tức giận trước quyết định của hội đồng thành phố về việc đóng cửa thư viện duy nhất trong khu phố của họ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_12_2_3', 'ten_12_2', 'smile', 'A friendly smile can help patients feel more comfortable when discussing their concerns with healthcare professionals.', 'A friendly smile can help patients feel more comfortable when discussing their concerns with healthcare professionals.', '/smaɪl/', 'Một nụ cười thân thiện có thể giúp bệnh nhân cảm thấy thoải mái hơn khi thảo luận về những lo lắng của họ với các chuyên gia y tế.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_12_2_4', 'ten_12_2', 'exciting', 'Advances in renewable energy offer exciting opportunities for young engineers seeking to address global environmental challenges.', 'Advances in renewable energy offer exciting opportunities for young engineers seeking to address global environmental challenges.', '/ɪkˈsaɪtɪŋ/', 'Sự tiến bộ trong năng lượng tái tạo mang đến những cơ hội đầy phấn khích cho các kỹ sư trẻ đang tìm cách giải quyết các thách thức môi trường toàn cầu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_12_2_5', 'ten_12_2', 'afraid', 'Some employees are afraid to report workplace problems because they worry about losing their jobs.', 'Some employees are afraid to report workplace problems because they worry about losing their jobs.', '/əˈfreɪd/', 'Một số nhân viên e ngại phản ánh các vấn đề tại nơi làm việc vì họ lo sợ bị mất việc.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_12_2_6', 'ten_12_2', 'boring', 'Students may find repetitive exercises boring unless teachers explain their purpose and introduce variety.', 'Students may find repetitive exercises boring unless teachers explain their purpose and introduce variety.', '/ˈbɔːrɪŋ/', 'Học sinh có thể thấy các bài tập lặp đi lặp lại rất tẻ nhạt trừ khi giáo viên giải thích mục đích của chúng và lồng ghép thêm nhiều hình thức đa dạng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_12_2_1', 'en-a1-12', 'ten_12_2', 'listening', 'listening', 'Although some entrepreneurs benefit from lucky opportunities, long-term business success usually requires careful planning and consistent effort.', NULL, 'Trong câu vừa nghe, từ “lucky” mang nghĩa nào sau đây?', '["chết; tàn lụi","làm mất; đánh rơi; thất lạc","may mắn","tai"]'::jsonb, 2, '“lucky” (/ˈlʌki/): may mắn. Câu đầy đủ: Although some entrepreneurs benefit from lucky opportunities, long-term business success usually requires careful planning and consistent effort.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_12_2_2', 'en-a1-12', 'ten_12_2', 'listening', 'listening', 'Residents became angry about the council''s decision to close the only library in their neighbourhood.', NULL, 'Trong câu vừa nghe, từ “angry” mang nghĩa nào sau đây?', '["quá (vượt mức mong muốn, cần thiết hoặc phù hợp)","tức giận; cáu giận","thế giới; trái đất","bốn; số bốn"]'::jsonb, 1, '“angry” (/ˈæŋɡri/): tức giận; cáu giận. Câu đầy đủ: Residents became angry about the council''s decision to close the only library in their neighbourhood.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
