INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_12_2', 'en-a1-12', NULL, 'comprehensive_test', 'listening', 'He felt angry when someone damaged his bicycle.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bọn trẻ vô cùng hào hứng về chuyến cắm trại đầu tiên của chúng.","Chị gái tôi rất thích học trồng rau.","Anh ấy cảm thấy rất tức giận khi có ai đó làm hỏng chiếc xe đạp của mình.","Em bé mỉm cười khi tôi vẫy tay từ phía bên kia căn phòng."]'::jsonb, 2, 'He felt angry when someone damaged his bicycle. → Anh ấy cảm thấy rất tức giận khi có ai đó làm hỏng chiếc xe đạp của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_12_3', 'en-a1-12', NULL, 'comprehensive_test', 'listening', 'smile', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["không khí","cười; mỉm cười","n. tiếng Tây Ban Nha","không có gì; không điều gì"]'::jsonb, 1, 'smile (/smaɪl/) → cười; mỉm cười; nụ cười', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_12_4', 'en-a1-12', NULL, 'comprehensive_test', 'listening', 'The final minutes of the match were incredibly exciting.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh ấy cảm thấy rất tức giận khi có ai đó làm hỏng chiếc xe đạp của mình.","Những phút cuối của trận đấu vô cùng gay cấn và thú vị.","Chú cún con rất sợ tiếng ồn của máy hút bụi.","Chị gái tôi rất thích học trồng rau."]'::jsonb, 1, 'The final minutes of the match were incredibly exciting. → Những phút cuối của trận đấu vô cùng gay cấn và thú vị.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
