INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_12_18', 'en-a1-12', NULL, 'comprehensive_test', 'reading', NULL, 'Although some entrepreneurs benefit from lucky opportunities, long-term business success usually requires careful planning and consistent effort.', 'Dựa vào câu trên, từ “lucky” có nghĩa phù hợp nhất là gì?', '["dễ dàng; không phức tạp","may mắn","màu hồng","quốc gia; đất nước"]'::jsonb, 1, 'lucky: may mắn; mang lại vận may. Dịch cả câu: Mặc dù một số nhà khởi nghiệp hưởng lợi từ những cơ hội may mắn, nhưng thành công trong kinh doanh dài hạn thường đòi hỏi kế hoạch chu đáo và nỗ lực bền bỉ.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_12_19', 'en-a1-12', NULL, 'comprehensive_test', 'reading', NULL, 'Residents became angry about the council''s decision to close the only library in their neighbourhood.', 'Dựa vào câu trên, từ “angry” có nghĩa phù hợp nhất là gì?', '["đồ vật; vật dụng","xin vui lòng; làm ơn","trẻ em; những đứa trẻ","tức giận; cáu giận"]'::jsonb, 3, 'angry: tức giận; cáu giận. Dịch cả câu: Cư dân đã tỏ ra tức giận trước quyết định của hội đồng thành phố về việc đóng cửa thư viện duy nhất trong khu phố của họ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_12_20', 'en-a1-12', NULL, 'comprehensive_test', 'reading', NULL, 'A friendly smile can help patients feel more comfortable when discussing their concerns with healthcare professionals.', 'Dựa vào câu trên, từ “smile” có nghĩa phù hợp nhất là gì?', '["bẩn; dơ dáy","cười; mỉm cười","sự bắt đầu; phần đầu; khởi đầu","viện bảo tàng"]'::jsonb, 1, 'smile: cười; mỉm cười; nụ cười. Dịch cả câu: Một nụ cười thân thiện có thể giúp bệnh nhân cảm thấy thoải mái hơn khi thảo luận về những lo lắng của họ với các chuyên gia y tế.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_12_21', 'en-a1-12', NULL, 'comprehensive_test', 'reading', NULL, 'Advances in renewable energy offer exciting opportunities for young engineers seeking to address global environmental challenges.', 'Dựa vào câu trên, từ “exciting” có nghĩa phù hợp nhất là gì?', '["củ cà rốt","thú vị; kích thích; làm phấn khích","được ưa chuộng nhất; yêu thích nhất","xe đạp; xe máy (thân mật)"]'::jsonb, 1, 'exciting: thú vị; kích thích; làm phấn khích. Dịch cả câu: Sự tiến bộ trong năng lượng tái tạo mang đến những cơ hội đầy phấn khích cho các kỹ sư trẻ đang tìm cách giải quyết các thách thức môi trường toàn cầu.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_12_22', 'en-a1-12', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cười; phát ra tiếng cười”', '["laugh","useful","letter","weather"]'::jsonb, 0, 'cười; phát ra tiếng cười → laugh (/læf/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_12_23', 'en-a1-12', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “quan tâm; có hứng thú”', '["interested","China","please","bread"]'::jsonb, 0, 'quan tâm; có hứng thú → interested (/ˈɪntrəstɪd/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_12_24', 'en-a1-12', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hứng khởi; hào hứng; phấn khích”', '["relax","excited","fact","leave"]'::jsonb, 1, 'hứng khởi; hào hứng; phấn khích → excited (/ɪkˈsaɪtɪd/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-13', 'en', 'Bài 13: Công việc & Kinh tế - CEFR A1', 'CEFR A1', 'A1 · Công việc & Kinh tế', '22 từ vựng Tiếng Anh CEFR A1 chủ đề công việc & kinh tế kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1013, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_worker', 'en-a1-13', 'worker', '/ˈwɝːkɚ/', 'A1', 'người lao động; công nhân; nhân viên', 'n.', 'work (v.), working (adj.), workforce (n.)', 'Đồng nghĩa: employee', 'Không chỉ chỉ lao động chân tay, từ này còn có thể chỉ nhân viên y tế và các nghề nghiệp khác.', 'A worker in orange overalls repaired the broken fence.', NULL, 'Một công nhân mặc quần áo bảo hộ màu cam đã sửa chiếc hàng rào bị hỏng.', '{"wordId":"worker","ukIpa":"/ˈwɜːkə/","usIpa":"/ˈwɝːkɚ/","cefr":"A1","topic":"work","senses":[{"pos":"n.","en":"A person who works, especially for pay.","vi":"người lao động; công nhân; nhân viên"}],"examples":[{"en":"A worker in orange overalls repaired the broken fence.","vi":"Một công nhân mặc quần áo bảo hộ màu cam đã sửa chiếc hàng rào bị hỏng.","audioKind":"ex"},{"en":"Employers should provide every worker with appropriate training and equipment to reduce the risk of workplace injuries.","vi":"Người sử dụng lao động nên cung cấp cho mọi nhân viên các khóa đào tạo và trang thiết bị phù hợp để giảm thiểu nguy cơ tai nạn tại nơi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"factory worker","vi":"công nhân nhà máy"},{"en":"skilled worker","vi":"công nhân lành nghề"},{"en":"healthcare worker","vi":"nhân viên y tế"},{"en":"migrant worker","vi":"người lao động di cư"}],"wordFamily":["work (v.)","working (adj.)","workforce (n.)"],"synonyms":["employee"],"antonyms":[],"tipVi":"Không chỉ chỉ lao động chân tay, từ này còn có thể chỉ nhân viên y tế và các nghề nghiệp khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_waitress', 'en-a1-13', 'waitress', '/ˈweɪtrəs/', 'A1', 'nữ phục vụ bàn; nữ bồi bàn', 'n.', 'waiter (n.), wait (v.)', 'Đồng nghĩa: server', 'waitress chỉ dùng cho nữ; server là từ trung tính về giới tính.', 'The waitress brought us warm bread and fresh soup.', NULL, 'Nữ phục vụ mang đến cho chúng tôi bánh mì ấm và súp nóng hổi.', '{"wordId":"waitress","ukIpa":"/ˈweɪtrəs/","usIpa":"/ˈweɪtrəs/","cefr":"A1","topic":"work","senses":[{"pos":"n.","en":"A woman who serves food and drinks in a restaurant.","vi":"nữ phục vụ bàn; nữ bồi bàn"}],"examples":[{"en":"The waitress brought us warm bread and fresh soup.","vi":"Nữ phục vụ mang đến cho chúng tôi bánh mì ấm và súp nóng hổi.","audioKind":"ex"},{"en":"Working as a waitress can help students develop communication skills while earning money to support their studies.","vi":"Làm việc như một nữ phục vụ bàn có thể giúp sinh viên phát triển kỹ năng giao tiếp đồng thời kiếm tiền trang trải việc học.","audioKind":"ex2"}],"collocations":[{"en":"work as a waitress","vi":"làm nhân viên phục vụ bàn"},{"en":"a friendly waitress","vi":"một nữ phục vụ thân thiện"},{"en":"ask the waitress","vi":"hỏi nhân viên phục vụ"}],"wordFamily":["waiter (n.)","wait (v.)"],"synonyms":["server"],"antonyms":[],"tipVi":"waitress chỉ dùng cho nữ; server là từ trung tính về giới tính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_job', 'en-a1-13', 'job', '/dʒɑːb/', 'A1', 'công việc; nghề nghiệp; việc làm; nhiệm vụ; công việc cụ thể', 'n.', 'jobless (adj.)', NULL, 'Từ job chỉ công việc cụ thể và là danh từ đếm được; trong khi work chỉ công việc chung chung và thường không đếm được.', 'My sister found a job at the local library.', NULL, 'Chị tôi đã tìm được một công việc tại thư viện địa phương.', '{"wordId":"job","ukIpa":"/dʒɒb/","usIpa":"/dʒɑːb/","cefr":"A1","topic":"work","senses":[{"pos":"n.","en":"paid work that someone does regularly","vi":"công việc; nghề nghiệp; việc làm"},{"pos":"n.","en":"a particular task or piece of work","vi":"nhiệm vụ; công việc cụ thể"}],"examples":[{"en":"My sister found a job at the local library.","vi":"Chị tôi đã tìm được một công việc tại thư viện địa phương.","audioKind":"ex"},{"en":"Access to practical training can help young people secure a job in a competitive labour market.","vi":"Việc tiếp cận đào tạo thực tế có thể giúp những người trẻ tuổi tìm được việc làm trong một thị trường lao động cạnh tranh.","audioKind":"ex2"}],"collocations":[{"en":"apply for a job","vi":"nộp đơn xin việc"},{"en":"a full-time job","vi":"công việc toàn thời gian"},{"en":"job satisfaction","vi":"sự hài lòng trong công việc"},{"en":"do a good job","vi":"làm tốt nhiệm vụ"}],"wordFamily":["jobless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ job chỉ công việc cụ thể và là danh từ đếm được; trong khi work chỉ công việc chung chung và thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_farm', 'en-a1-13', 'farm', '/fɑːrm/', 'A1', 'nông trại; trang trại; làm nông; canh tác; chăn nuôi', 'n.', 'farmer (n.), farming (n.), farmland (n.)', NULL, 'Nói làm việc ở trang trại thường dùng on a farm, không dùng in.', 'We bought fresh eggs from a nearby farm.', NULL, 'Chúng tôi mua trứng tươi từ một trang trại gần nhà.', '{"wordId":"farm","ukIpa":"/fɑːm/","usIpa":"/fɑːrm/","cefr":"A1","topic":"work","senses":[{"pos":"n.","en":"land and buildings used for growing crops or raising animals","vi":"nông trại; trang trại"},{"pos":"v.","en":"to grow crops or raise animals for food or other products","vi":"làm nông; canh tác; chăn nuôi"}],"examples":[{"en":"We bought fresh eggs from a nearby farm.","vi":"Chúng tôi mua trứng tươi từ một trang trại gần nhà.","audioKind":"ex"},{"en":"Small farms can support local food supplies while creating employment opportunities in rural communities.","vi":"Các trang trại quy mô nhỏ có thể duy trì nguồn cung thực phẩm địa phương đồng thời tạo ra cơ hội việc làm ở các vùng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"a dairy farm","vi":"trang trại bò sữa"},{"en":"work on a farm","vi":"làm việc ở trang trại"},{"en":"farm animals","vi":"động vật trang trại"},{"en":"farm the land","vi":"khai thác đất đai canh tác"}],"wordFamily":["farmer (n.)","farming (n.)","farmland (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nói làm việc ở trang trại thường dùng on a farm, không dùng in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_farmer', 'en-a1-13', 'farmer', '/ˈfɑːrmər/', 'A1', 'nông dân; chủ trang trại', 'n.', 'farm (n.), farm (v.), farming (n.)', NULL, '"farmer" chỉ người nông dân, "farm" chỉ trang trại, còn "farming" chỉ hoạt động nông nghiệp.', 'The farmer feeds her chickens before the sun rises.', NULL, 'Người nông dân cho đàn gà ăn trước khi mặt trời mọc.', '{"wordId":"farmer","ukIpa":"/ˈfɑːmə/","usIpa":"/ˈfɑːrmər/","cefr":"A1","topic":"work","senses":[{"pos":"n.","en":"someone who grows crops or raises animals on a farm","vi":"nông dân; chủ trang trại"}],"examples":[{"en":"The farmer feeds her chickens before the sun rises.","vi":"Người nông dân cho đàn gà ăn trước khi mặt trời mọc.","audioKind":"ex"},{"en":"Small farmers need reliable access to water and affordable technology to maintain production during dry periods.","vi":"Các hộ nông dân nhỏ cần được tiếp cận nguồn nước ổn định và công nghệ giá cả phải chăng để duy trì sản xuất trong những giai đoạn khô hạn.","audioKind":"ex2"}],"collocations":[{"en":"dairy farmer","vi":"nông dân chăn nuôi bò sữa"},{"en":"local farmers","vi":"nông dân địa phương"},{"en":"small farmers","vi":"các hộ nông dân nhỏ"},{"en":"sheep farmer","vi":"nông dân nuôi cừu"}],"wordFamily":["farm (n.)","farm (v.)","farming (n.)"],"synonyms":[],"antonyms":[],"tipVi":"\"farmer\" chỉ người nông dân, \"farm\" chỉ trang trại, còn \"farming\" chỉ hoạt động nông nghiệp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_business', 'en-a1-13', 'business', '/ˈbɪznəs/', 'A1', 'việc kinh doanh; thương mại; doanh nghiệp; công ty; việc riêng; công chuyện; trách nhiệm', 'n.', 'businessperson (n.), businesslike (adj.)', NULL, 'Khi chỉ hoạt động thương mại thì danh từ không đếm được; khi chỉ một công ty, doanh nghiệp cụ thể thì đếm được.', 'Business is usually slow at the café on Mondays.', NULL, 'Việc kinh doanh tại quán cà phê thường khá ế ẩm vào các ngày thứ Hai.', '{"wordId":"business","ukIpa":"/ˈbɪznəs/","usIpa":"/ˈbɪznəs/","cefr":"A1","topic":"work","senses":[{"pos":"n.","en":"The activity of buying and selling goods or services.","vi":"việc kinh doanh; thương mại"},{"pos":"n.","en":"An organisation that sells goods or services.","vi":"doanh nghiệp; công ty"},{"pos":"n.","en":"Matters that someone needs to deal with or is responsible for.","vi":"việc riêng; công chuyện; trách nhiệm"}],"examples":[{"en":"Business is usually slow at the café on Mondays.","vi":"Việc kinh doanh tại quán cà phê thường khá ế ẩm vào các ngày thứ Hai.","audioKind":"ex"},{"en":"Small businesses often create local employment, but they may struggle to compete with larger companies.","vi":"Các doanh nghiệp nhỏ thường tạo ra việc làm tại địa phương, nhưng họ có thể gặp khó khăn khi cạnh tranh với các công ty lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"do business with","vi":"làm ăn kinh doanh với"},{"en":"run a business","vi":"điều hành một doanh nghiệp"},{"en":"on business","vi":"đi công tác"},{"en":"none of your business","vi":"không phải việc của bạn"}],"wordFamily":["businessperson (n.)","businesslike (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ hoạt động thương mại thì danh từ không đếm được; khi chỉ một công ty, doanh nghiệp cụ thể thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_company', 'en-a1-13', 'company', '/ˈkʌmpəni/', 'A1', 'công ty; hãng; sự bầu bạn; sự đồng hành', 'n.', NULL, 'Đồng nghĩa: business, firm, companionship', 'Khi mang nghĩa "công ty", từ này đếm được; khi mang nghĩa "sự bầu bạn", nó không đếm được.', 'My sister works for a company that makes bicycles.', NULL, 'Chị gái tôi làm việc cho một công ty sản xuất xe đạp.', '{"wordId":"company","ukIpa":"/ˈkʌmpəni/","usIpa":"/ˈkʌmpəni/","cefr":"A1","topic":"work","senses":[{"pos":"n.","en":"An organisation that sells goods or services","vi":"công ty; hãng"},{"pos":"n.","en":"The presence of another person or people with you","vi":"sự bầu bạn; sự đồng hành"}],"examples":[{"en":"My sister works for a company that makes bicycles.","vi":"Chị gái tôi làm việc cho một công ty sản xuất xe đạp.","audioKind":"ex"},{"en":"A company that invests in staff training is more likely to retain skilled employees over time.","vi":"Một công ty đầu tư vào việc đào tạo nhân viên sẽ có nhiều khả năng giữ chân được nhân sự lành nghề lâu dài hơn.","audioKind":"ex2"}],"collocations":[{"en":"work for a company","vi":"làm việc cho một công ty"},{"en":"set up a company","vi":"thành lập công ty"},{"en":"keep someone company","vi":"bầu bạn với ai"},{"en":"enjoy someone''s company","vi":"thích ở bên cạnh ai"}],"wordFamily":[],"synonyms":["business","firm","companionship"],"antonyms":[],"tipVi":"Khi mang nghĩa \"công ty\", từ này đếm được; khi mang nghĩa \"sự bầu bạn\", nó không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_meeting', 'en-a1-13', 'meeting', '/ˈmiːtɪŋ/', 'A1', 'cuộc họp, cuộc hội nghị khi mọi người tụ tập để thảo luận vấn đề gì; cuộc gặp gỡ, buổi hẹn mặt tình cờ hoặc đã được sắp xếp từ trước', 'n.', 'meet (v.)', 'Đồng nghĩa: gathering', 'Tham gia cuộc họp dùng attend a meeting; meeting cũng có thể chỉ cuộc gặp gỡ nói chung.', 'Our team meeting starts right after lunch today.', NULL, 'Cuộc họp nhóm của chúng ta bắt đầu ngay sau bữa trưa hôm nay.', '{"wordId":"meeting","ukIpa":"/ˈmiːtɪŋ/","usIpa":"/ˈmiːtɪŋ/","cefr":"A1","topic":"work","senses":[{"pos":"n.","en":"an occasion when people gather to discuss something","vi":"cuộc họp, cuộc hội nghị khi mọi người tụ tập để thảo luận vấn đề gì"},{"pos":"n.","en":"an occasion when people come together, by arrangement or chance","vi":"cuộc gặp gỡ, buổi hẹn mặt tình cờ hoặc đã được sắp xếp từ trước"}],"examples":[{"en":"Our team meeting starts right after lunch today.","vi":"Cuộc họp nhóm của chúng ta bắt đầu ngay sau bữa trưa hôm nay.","audioKind":"ex"},{"en":"Regular meetings between teachers and parents can help identify learning difficulties at an early stage.","vi":"Các cuộc gặp mặt định kỳ giữa giáo viên và phụ huynh có thể giúp phát hiện sớm các khó khăn trong học tập.","audioKind":"ex2"}],"collocations":[{"en":"hold a meeting","vi":"tổ chức cuộc họp"},{"en":"attend a meeting","vi":"tham dự cuộc họp"},{"en":"arrange a meeting","vi":"sắp xếp một cuộc gặp gỡ"},{"en":"staff meeting","vi":"cuộc họp nhân viên"}],"wordFamily":["meet (v.)"],"synonyms":["gathering"],"antonyms":[],"tipVi":"Tham gia cuộc họp dùng attend a meeting; meeting cũng có thể chỉ cuộc gặp gỡ nói chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_waiter', 'en-a1-13', 'waiter', '/ˈweɪtər/', 'A1', 'nhân viên phục vụ bàn, nam bồi bàn trong nhà hàng', 'n.', 'waitress (n.), wait (v.)', 'Đồng nghĩa: server', 'waiter theo truyền thống chỉ nam nhân viên phục vụ; server là từ trung tính về giới tính hơn.', 'The waiter brought our soup and two warm rolls.', NULL, 'Người phục vụ bàn đã mang súp và hai chiếc bánh mì ấm nóng ra cho chúng tôi.', '{"wordId":"waiter","ukIpa":"/ˈweɪtə/","usIpa":"/ˈweɪtər/","cefr":"A1","topic":"work","senses":[{"pos":"n.","en":"A person, traditionally male, who serves food in a restaurant","vi":"nhân viên phục vụ bàn, nam bồi bàn trong nhà hàng"}],"examples":[{"en":"The waiter brought our soup and two warm rolls.","vi":"Người phục vụ bàn đã mang súp và hai chiếc bánh mì ấm nóng ra cho chúng tôi.","audioKind":"ex"},{"en":"A well-trained waiter can improve the dining experience by responding patiently to customers with different needs.","vi":"Một nhân viên phục vụ được đào tạo bài bản có thể cải thiện trải nghiệm ăn uống bằng cách kiên nhẫn đáp ứng nhu cầu đa dạng của khách hàng.","audioKind":"ex2"}],"collocations":[{"en":"work as a waiter","vi":"làm nghề phục vụ bàn"},{"en":"head waiter","vi":"trưởng bồi bàn"},{"en":"ask the waiter","vi":"hỏi nhân viên phục vụ"}],"wordFamily":["waitress (n.)","wait (v.)"],"synonyms":["server"],"antonyms":[],"tipVi":"waiter theo truyền thống chỉ nam nhân viên phục vụ; server là từ trung tính về giới tính hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_team', 'en-a1-13', 'team', '/tiːm/', 'A1', 'đội; nhóm; hợp tác; lập đội', 'n.', 'teamwork (n.), teammate (n.)', 'Đồng nghĩa: squad, crew', 'Trong tiếng Anh-Anh, team có thể đi với động từ số ít hoặc số nhiều.', 'Our team celebrated with pizza after winning the match.', NULL, 'Đội của chúng tôi đã ăn mừng bằng bánh pizza sau khi giành chiến thắng trong trận đấu.', '{"wordId":"team","ukIpa":"/tiːm/","usIpa":"/tiːm/","cefr":"A1","topic":"work","senses":[{"pos":"n.","en":"a group working together or playing a sport together","vi":"đội; nhóm"},{"pos":"v.","en":"to join someone to work together, usually with up","vi":"hợp tác; lập đội"}],"examples":[{"en":"Our team celebrated with pizza after winning the match.","vi":"Đội của chúng tôi đã ăn mừng bằng bánh pizza sau khi giành chiến thắng trong trận đấu.","audioKind":"ex"},{"en":"Working in a team helps students develop communication skills that are essential for future employment.","vi":"Làm việc nhóm giúp học sinh phát triển các kỹ năng giao tiếp vốn rất cần thiết cho công việc trong tương lai.","audioKind":"ex2"}],"collocations":[{"en":"team member","vi":"thành viên trong nhóm"},{"en":"team spirit","vi":"tinh thần đồng đội"},{"en":"team up with","vi":"hợp tác với"},{"en":"research team","vi":"nhóm nghiên cứu"}],"wordFamily":["teamwork (n.)","teammate (n.)"],"synonyms":["squad","crew"],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh, team có thể đi với động từ số ít hoặc số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_office', 'en-a1-13', 'office', '/ˈɑːfɪs/', 'A1', 'n. văn phòng; tòa nhà văn phòng; n. cơ quan; văn phòng dịch vụ; n. chức vụ; địa vị (nhất là trong bộ máy nhà nước)', 'n.', 'officer (n.), official (adj.)', 'Đồng nghĩa: workplace', 'Dùng in the office khi ở văn phòng; dùng in office khi đang nắm giữ chức vụ.', 'I left my umbrella under the desk at the office.', NULL, 'Tôi để quên chiếc ô dưới bàn làm việc ở văn phòng.', '{"wordId":"office","ukIpa":"/ˈɒfɪs/","usIpa":"/ˈɑːfɪs/","cefr":"A1","topic":"work","senses":[{"pos":"n.","en":"a room or building where people do administrative work","vi":"n. văn phòng; tòa nhà văn phòng"},{"pos":"n.","en":"a place providing a particular service or handling official business","vi":"n. cơ quan; văn phòng dịch vụ"},{"pos":"n.","en":"an official position of responsibility, especially in government","vi":"n. chức vụ; địa vị (nhất là trong bộ máy nhà nước)"}],"examples":[{"en":"I left my umbrella under the desk at the office.","vi":"Tôi để quên chiếc ô dưới bàn làm việc ở văn phòng.","audioKind":"ex"},{"en":"Flexible working arrangements allow employees to divide their time between the office and home.","vi":"Các thỏa thuận làm việc linh hoạt cho phép nhân viên phân chia thời gian làm việc giữa văn phòng và nhà riêng.","audioKind":"ex2"}],"collocations":[{"en":"office hours","vi":"giờ hành chính; giờ làm việc"},{"en":"head office","vi":"trụ sở chính"},{"en":"hold office","vi":"giữ chức vụ"},{"en":"take office","vi":"nhậm chức"}],"wordFamily":["officer (n.)","official (adj.)"],"synonyms":["workplace"],"antonyms":[],"tipVi":"Dùng in the office khi ở văn phòng; dùng in office khi đang nắm giữ chức vụ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_price', 'en-a1-13', 'price', '/praɪs/', 'A1', 'giá cả; giá tiền; cái giá phải trả; định giá', 'n.', 'priceless (adj.), pricey (adj.), pricing (n.)', NULL, 'Nói giá cao hay thấp dùng tính từ high hoặc low; nói món đồ đắt hay rẻ dùng expensive hoặc cheap.', 'The price of fresh strawberries has fallen this week.', NULL, 'Giá của dâu tây tươi đã giảm trong tuần này.', '{"wordId":"price","ukIpa":"/praɪs/","usIpa":"/praɪs/","cefr":"A1","topic":"economy","senses":[{"pos":"n.","en":"The amount of money needed to buy something.","vi":"giá cả; giá tiền"},{"pos":"n.","en":"Something unpleasant experienced to achieve or obtain something else.","vi":"cái giá phải trả"},{"pos":"v.","en":"To decide how much money something will cost.","vi":"định giá"}],"examples":[{"en":"The price of fresh strawberries has fallen this week.","vi":"Giá của dâu tây tươi đã giảm trong tuần này.","audioKind":"ex"},{"en":"Rising food prices place considerable pressure on families with limited incomes, particularly in urban areas.","vi":"Giá lương thực tăng cao gây áp lực đáng kể cho các gia đình có thu nhập hạn hẹp, đặc biệt là ở khu vực thành thị.","audioKind":"ex2"}],"collocations":[{"en":"high prices","vi":"giá cao"},{"en":"pay the price","vi":"trả giá"},{"en":"price rise","vi":"giá tăng"},{"en":"reasonably priced","vi":"giá cả phải chăng"}],"wordFamily":["priceless (adj.)","pricey (adj.)","pricing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nói giá cao hay thấp dùng tính từ high hoặc low; nói món đồ đắt hay rẻ dùng expensive hoặc cheap.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_market', 'en-a1-13', 'market', '/ˈmɑːrkɪt/', 'A1', 'chợ; hội chợ; thị trường; nhu cầu thị trường; tiếp thị; quảng bá và bán sản phẩm', 'n.', 'marketing (n.), marketer (n.), marketable (adj.)', NULL, 'A market for sth chỉ nhu cầu thị trường đối với cái gì.', 'We bought fresh peaches at the market this morning.', NULL, 'Chúng tôi đã mua những quả đào tươi ở chợ vào sáng nay.', '{"wordId":"market","ukIpa":"/ˈmɑːkɪt/","usIpa":"/ˈmɑːrkɪt/","cefr":"A1","topic":"economy","senses":[{"pos":"n.","en":"a place where people buy and sell goods","vi":"chợ; hội chợ"},{"pos":"n.","en":"the demand for something or the business of trading particular goods","vi":"thị trường; nhu cầu thị trường"},{"pos":"v.","en":"to promote and offer a product for sale","vi":"tiếp thị; quảng bá và bán sản phẩm"}],"examples":[{"en":"We bought fresh peaches at the market this morning.","vi":"Chúng tôi đã mua những quả đào tươi ở chợ vào sáng nay.","audioKind":"ex"},{"en":"Companies increasingly market environmentally friendly products to consumers who want to reduce their impact on the planet.","vi":"Các công ty ngày càng tiếp thị các sản phẩm thân thiện với môi trường tới những người tiêu dùng muốn giảm thiểu tác động của họ đến hành tinh.","audioKind":"ex2"}],"collocations":[{"en":"local market","vi":"chợ địa phương"},{"en":"job market","vi":"thị trường lao động"},{"en":"market research","vi":"nghiên cứu thị trường"},{"en":"market share","vi":"thị phần"}],"wordFamily":["marketing (n.)","marketer (n.)","marketable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"A market for sth chỉ nhu cầu thị trường đối với cái gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dollar', 'en-a1-13', 'dollar', '/ˈdɑːlər/', 'A1', 'đô la; đồng đô la', 'n.', NULL, NULL, 'Không chỉ chỉ đồng đô la Mỹ, từ này còn được dùng cho đồng đô la Canada, đô la Úc, v.v.', 'I paid one dollar for this small notebook.', NULL, 'Tôi đã trả một đô la cho cuốn sổ tay nhỏ này.', '{"wordId":"dollar","ukIpa":"/ˈdɒlə/","usIpa":"/ˈdɑːlər/","cefr":"A1","topic":"economy","senses":[{"pos":"n.","en":"A currency unit used in the US and several other countries.","vi":"đô la; đồng đô la"}],"examples":[{"en":"I paid one dollar for this small notebook.","vi":"Tôi đã trả một đô la cho cuốn sổ tay nhỏ này.","audioKind":"ex"},{"en":"A stronger dollar can make imported goods cheaper for American consumers while increasing costs for overseas buyers.","vi":"Đồng đô la mạnh hơn có thể giúp hàng hóa nhập khẩu trở nên rẻ hơn đối với người tiêu dùng Mỹ, đồng thời làm tăng chi phí cho người mua ở nước ngoài.","audioKind":"ex2"}],"collocations":[{"en":"US dollar","vi":"đô la Mỹ"},{"en":"Australian dollar","vi":"đô la Úc"},{"en":"a strong dollar","vi":"đồng đô la mạnh"},{"en":"the dollar exchange rate","vi":"tỷ giá đồng đô la"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Không chỉ chỉ đồng đô la Mỹ, từ này còn được dùng cho đồng đô la Canada, đô la Úc, v.v.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spend', 'en-a1-13', 'spend', '/spend/', 'A1', 'tiêu (tiền); chi trả; dành (thời gian); trải qua', 'v.', 'spending (n.), spender (n.)', 'Trái nghĩa: save', 'Dùng "spend" + thời gian + "doing" hoặc "spend" + tiền + "on"; quá khứ là "spent".', 'We spent all our money on fresh fruit.', NULL, 'Chúng tôi đã tiêu hết tiền vào trái cây tươi.', '{"wordId":"spend","ukIpa":"/spend/","usIpa":"/spend/","cefr":"A1","topic":"economy","senses":[{"pos":"v.","en":"to use money to pay for something","vi":"tiêu (tiền); chi trả"},{"pos":"v.","en":"to use time doing something or being somewhere","vi":"dành (thời gian); trải qua"}],"examples":[{"en":"We spent all our money on fresh fruit.","vi":"Chúng tôi đã tiêu hết tiền vào trái cây tươi.","audioKind":"ex"},{"en":"Governments should spend more on preventive healthcare to reduce the future costs of treating chronic diseases.","vi":"Chính phủ nên chi nhiều hơn cho y tế dự phòng để giảm chi phí điều trị các bệnh mãn tính trong tương lai.","audioKind":"ex2"}],"collocations":[{"en":"spend money on","vi":"tiêu tiền vào"},{"en":"spend time doing","vi":"dành thời gian làm gì"},{"en":"spend the night","vi":"qua đêm"}],"wordFamily":["spending (n.)","spender (n.)"],"synonyms":[],"antonyms":["save"],"tipVi":"Dùng \"spend\" + thời gian + \"doing\" hoặc \"spend\" + tiền + \"on\"; quá khứ là \"spent\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rich', 'en-a1-13', 'rich', '/rɪtʃ/', 'A1', 'giàu có; giàu; giàu; phong phú; dồi dào; ngậy; béo; đậm đà', 'adj.', 'richness (n.), richly (adv.), enrich (v.), riches (n.)', 'Đồng nghĩa: wealthy, affluent · Trái nghĩa: poor', 'Cấu trúc "giàu cái gì" dùng rich in, không dùng rich of.', 'Their rich uncle owns a large house by the sea.', NULL, 'Người chú giàu có của họ sở hữu một ngôi nhà lớn cạnh bờ biển.', '{"wordId":"rich","ukIpa":"/rɪtʃ/","usIpa":"/rɪtʃ/","cefr":"A1","topic":"economy","senses":[{"pos":"adj.","en":"Having a lot of money or valuable possessions.","vi":"giàu có; giàu"},{"pos":"adj.","en":"Containing a large amount or variety of something valuable.","vi":"giàu; phong phú; dồi dào"},{"pos":"adj.","en":"Containing plenty of fat, cream, sugar, or strong flavour.","vi":"ngậy; béo; đậm đà"}],"examples":[{"en":"Their rich uncle owns a large house by the sea.","vi":"Người chú giàu có của họ sở hữu một ngôi nhà lớn cạnh bờ biển.","audioKind":"ex"},{"en":"Rich countries can support global development by investing in clean energy projects in poorer regions.","vi":"Các quốc gia giàu có có thể hỗ trợ phát triển toàn cầu bằng cách đầu tư vào các dự án năng lượng sạch ở các khu vực nghèo hơn.","audioKind":"ex2"}],"collocations":[{"en":"rich countries","vi":"các quốc gia giàu có"},{"en":"rich in nutrients","vi":"giàu chất dinh dưỡng"},{"en":"rich cultural heritage","vi":"di sản văn hóa phong phú"},{"en":"rich food","vi":"thức ăn nhiều dầu mỡ"}],"wordFamily":["richness (n.)","richly (adv.)","enrich (v.)","riches (n.)"],"synonyms":["wealthy","affluent"],"antonyms":["poor"],"tipVi":"Cấu trúc \"giàu cái gì\" dùng rich in, không dùng rich of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bank', 'en-a1-13', 'bank', '/bæŋk/', 'A1', 'ngân hàng, tổ chức tài chính giữ tiền và cung cấp dịch vụ tài chính; bờ sông hoặc bờ hồ; gửi tiền vào tài khoản tại ngân hàng', 'n.', 'banker (n.), banking (n.)', NULL, 'Phần đất ven sông dùng on the bank; giao dịch tại ngân hàng dùng at hoặc in the bank.', 'I went to the bank to open an account.', NULL, 'Tôi đã ra ngân hàng để mở một tài khoản.', '{"wordId":"bank","ukIpa":"/bæŋk/","usIpa":"/bæŋk/","cefr":"A1","topic":"economy","senses":[{"pos":"n.","en":"an organisation that holds money and provides financial services","vi":"ngân hàng, tổ chức tài chính giữ tiền và cung cấp dịch vụ tài chính"},{"pos":"n.","en":"land along the edge of a river or lake","vi":"bờ sông hoặc bờ hồ"},{"pos":"v.","en":"put money into an account at a bank","vi":"gửi tiền vào tài khoản tại ngân hàng"}],"examples":[{"en":"I went to the bank to open an account.","vi":"Tôi đã ra ngân hàng để mở một tài khoản.","audioKind":"ex"},{"en":"Banks can support local economic development by offering affordable loans to small businesses and new entrepreneurs.","vi":"Các ngân hàng có thể hỗ trợ phát triển kinh tế địa phương bằng cách cung cấp các khoản vay có lãi suất hợp lý cho các doanh nghiệp nhỏ và chủ doanh nghiệp mới khởi nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"bank account","vi":"tài khoản ngân hàng"},{"en":"bank loan","vi":"khoản vay ngân hàng"},{"en":"river bank","vi":"bờ sông"},{"en":"bank statement","vi":"sao kê ngân hàng"}],"wordFamily":["banker (n.)","banking (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Phần đất ven sông dùng on the bank; giao dịch tại ngân hàng dùng at hoặc in the bank.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_money', 'en-a1-13', 'money', '/ˈmʌni/', 'A1', 'tiền; tiền tệ; của cải; tài sản', 'n.', 'moneyed (adj.), moneyless (adj.)', NULL, 'Thông thường là danh từ không đếm được: nói much money, tuyệt đối không dùng many money.', 'I saved enough money to buy a new bicycle.', NULL, 'Tôi đã tiết kiệm đủ tiền để mua một chiếc xe đạp mới.', '{"wordId":"money","ukIpa":"/ˈmʌni/","usIpa":"/ˈmʌni/","cefr":"A1","topic":"economy","senses":[{"pos":"n.","en":"What people use to pay for goods and services.","vi":"tiền; tiền tệ"},{"pos":"n.","en":"The wealth that a person or organisation owns.","vi":"của cải; tài sản"}],"examples":[{"en":"I saved enough money to buy a new bicycle.","vi":"Tôi đã tiết kiệm đủ tiền để mua một chiếc xe đạp mới.","audioKind":"ex"},{"en":"Governments should invest more money in public transport to reduce congestion and improve air quality.","vi":"Chính phủ nên đầu tư nhiều tiền hơn vào giao thông công cộng để giảm thiểu tình trạng tắc nghẽn và cải thiện chất lượng không khí.","audioKind":"ex2"}],"collocations":[{"en":"save money","vi":"tiết kiệm tiền"},{"en":"spend money on","vi":"tiêu tiền vào"},{"en":"value for money","vi":"đáng đồng tiền bát gạo"},{"en":"raise money","vi":"gây quỹ; quyên góp tiền"}],"wordFamily":["moneyed (adj.)","moneyless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thông thường là danh từ không đếm được: nói much money, tuyệt đối không dùng many money.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cent', 'en-a1-13', 'cent', '/sent/', 'A1', 'xu (đơn vị tiền tệ bằng một phần trăm của đô-la hoặc ơ-rô); đồng xu một xu', 'n.', NULL, NULL, 'Cent là danh từ đếm được; số tiền lớn hơn một xu thường dùng dạng số nhiều cents.', 'I found a cent under the sofa cushion.', NULL, 'Tôi tìm thấy một đồng xu một xu ở dưới đệm ghế sofa.', '{"wordId":"cent","ukIpa":"/sent/","usIpa":"/sent/","cefr":"A1","topic":"economy","senses":[{"pos":"n.","en":"a monetary unit worth one hundredth of a dollar or euro","vi":"xu (đơn vị tiền tệ bằng một phần trăm của đô-la hoặc ơ-rô)"},{"pos":"n.","en":"a coin worth one cent","vi":"đồng xu một xu"}],"examples":[{"en":"I found a cent under the sofa cushion.","vi":"Tôi tìm thấy một đồng xu một xu ở dưới đệm ghế sofa.","audioKind":"ex"},{"en":"For households with limited incomes, every cent saved on essential goods can contribute to greater financial security.","vi":"Đối với các hộ gia đình có thu nhập hạn hẹp, từng xu tiết kiệm được từ các mặt hàng thiết yếu có thể góp phần mang lại sự ổn định tài chính lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"every cent","vi":"mỗi xu"},{"en":"not a cent","vi":"không một xu dính túi"},{"en":"a fifty-cent coin","vi":"đồng xu năm mươi xu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cent là danh từ đếm được; số tiền lớn hơn một xu thường dùng dạng số nhiều cents.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sell', 'en-a1-13', 'sell', '/sel/', 'A1', 'bán; tiêu thụ; bán được (với số lượng hoặc cách thức nào đó); thuyết phục (chấp nhận một ý tưởng hoặc đề xuất); bán ý tưởng', 'v.', 'seller (n.), sale (n.), selling (n.)', 'Trái nghĩa: buy', 'Quá khứ và phân từ hai đều là sold; sell well thường dùng dạng chủ động.', 'They sell fresh bread at the market every Saturday.', NULL, 'Họ bán bánh mì tươi ở chợ vào mỗi thứ Bảy.', '{"wordId":"sell","ukIpa":"/sel/","usIpa":"/sel/","cefr":"A1","topic":"economy","senses":[{"pos":"v.","en":"to give something to someone in exchange for money","vi":"bán; tiêu thụ"},{"pos":"v.","en":"to be bought in a particular quantity or way","vi":"bán được (với số lượng hoặc cách thức nào đó)"},{"pos":"v.","en":"to persuade someone to accept an idea or proposal","vi":"thuyết phục (chấp nhận một ý tưởng hoặc đề xuất); bán ý tưởng"}],"examples":[{"en":"They sell fresh bread at the market every Saturday.","vi":"Họ bán bánh mì tươi ở chợ vào mỗi thứ Bảy.","audioKind":"ex"},{"en":"Small businesses increasingly sell their products online to reach customers beyond their local communities.","vi":"Các doanh nghiệp nhỏ ngày càng tích cực bán sản phẩm của mình trực tuyến để tiếp cận khách hàng ngoài cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"sell out","vi":"bán sạch; bán hết"},{"en":"sell well","vi":"bán chạy"},{"en":"sell something to someone","vi":"bán cái gì cho ai"},{"en":"sell an idea","vi":"thuyết phục một ý tưởng"}],"wordFamily":["seller (n.)","sale (n.)","selling (n.)"],"synonyms":[],"antonyms":["buy"],"tipVi":"Quá khứ và phân từ hai đều là sold; sell well thường dùng dạng chủ động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_expensive', 'en-a1-13', 'expensive', '/ɪkˈspensɪv/', 'A1', 'đắt đỏ; tốn kém', 'adj.', 'expense (n.), expensively (adv.), inexpensive (adj.)', 'Đồng nghĩa: costly, pricey · Trái nghĩa: cheap, inexpensive', 'Vật phẩm đắt đỏ dùng expensive, giá cả cao dùng high.', 'These boots are too expensive for my budget.', NULL, 'Đôi bốt này quá đắt so với ngân sách của tôi.', '{"wordId":"expensive","ukIpa":"/ɪkˈspensɪv/","usIpa":"/ɪkˈspensɪv/","cefr":"A1","topic":"economy","senses":[{"pos":"adj.","en":"costing a large amount of money","vi":"đắt đỏ; tốn kém"}],"examples":[{"en":"These boots are too expensive for my budget.","vi":"Đôi bốt này quá đắt so với ngân sách của tôi.","audioKind":"ex"},{"en":"Housing in major cities is becoming increasingly expensive, forcing many young workers to live farther from their workplaces.","vi":"Nhà ở tại các thành phố lớn đang ngày càng trở nên đắt đỏ, buộc nhiều lao động trẻ phải sống xa nơi làm việc hơn.","audioKind":"ex2"}],"collocations":[{"en":"too expensive","vi":"quá đắt"},{"en":"increasingly expensive","vi":"ngày càng đắt đỏ"},{"en":"expensive to maintain","vi":"tốn kém chi phí bảo dưỡng"},{"en":"an expensive mistake","vi":"một sai lầm tốn kém"}],"wordFamily":["expense (n.)","expensively (adv.)","inexpensive (adj.)"],"synonyms":["costly","pricey"],"antonyms":["cheap","inexpensive"],"tipVi":"Vật phẩm đắt đỏ dùng expensive, giá cả cao dùng high.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cheap', 'en-a1-13', 'cheap', '/tʃiːp/', 'A1', 'rẻ; giá rẻ; giá thấp; kém chất lượng; rẻ tiền', 'adj.', 'cheaply (adv.), cheapness (n.), cheapen (v.)', 'Đồng nghĩa: inexpensive, low-cost · Trái nghĩa: expensive, costly', 'cheap đôi khi mang hàm ý chất lượng kém; từ trung lập hơn có thể dùng inexpensive.', 'We found a cheap café near the train station.', NULL, 'Chúng tôi tìm thấy một quán cà phê giá rẻ gần ga tàu.', '{"wordId":"cheap","ukIpa":"/tʃiːp/","usIpa":"/tʃiːp/","cefr":"A1","topic":"economy","senses":[{"pos":"adj.","en":"costing little money or less than usual","vi":"rẻ; giá rẻ; giá thấp"},{"pos":"adj.","en":"of poor quality and little value","vi":"kém chất lượng; rẻ tiền"}],"examples":[{"en":"We found a cheap café near the train station.","vi":"Chúng tôi tìm thấy một quán cà phê giá rẻ gần ga tàu.","audioKind":"ex"},{"en":"Cheap public transport can improve access to employment and reduce dependence on private cars in large cities.","vi":"Giao thông công cộng giá rẻ có thể giúp cải thiện khả năng tiếp cận việc làm và giảm sự phụ thuộc vào ô tô cá nhân ở các thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"cheap tickets","vi":"vé giá rẻ"},{"en":"cheap labour","vi":"lao động giá rẻ"},{"en":"cheap and cheerful","vi":"rẻ mà tốt"},{"en":"a cheap alternative","vi":"một phương án thay thế giá rẻ"}],"wordFamily":["cheaply (adv.)","cheapness (n.)","cheapen (v.)"],"synonyms":["inexpensive","low-cost"],"antonyms":["expensive","costly"],"tipVi":"cheap đôi khi mang hàm ý chất lượng kém; từ trung lập hơn có thể dùng inexpensive.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_13_1', 'en-a1-13', 'Cách dùng “job” (n.) — công việc; nghề nghiệp; việc làm', 'apply for a job  ·  a full-time job  ·  job satisfaction', 'Từ job chỉ công việc cụ thể và là danh từ đếm được; trong khi work chỉ công việc chung chung và thường không đếm được.', 'Họ từ (Word Family): jobless (adj.)', '[{"hanzi":"My sister found a job at the local library.","pinyin":"","meaning":"Chị tôi đã tìm được một công việc tại thư viện địa phương."},{"hanzi":"Access to practical training can help young people secure a job in a competitive labour market.","pinyin":"","meaning":"Việc tiếp cận đào tạo thực tế có thể giúp những người trẻ tuổi tìm được việc làm trong một thị trường lao động cạnh tranh."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_13_2', 'en-a1-13', 'Cách dùng “business” (n.) — việc kinh doanh; thương mại', 'do business with  ·  run a business  ·  on business', 'Khi chỉ hoạt động thương mại thì danh từ không đếm được; khi chỉ một công ty, doanh nghiệp cụ thể thì đếm được.', 'Họ từ (Word Family): businessperson (n.), businesslike (adj.)', '[{"hanzi":"Business is usually slow at the café on Mondays.","pinyin":"","meaning":"Việc kinh doanh tại quán cà phê thường khá ế ẩm vào các ngày thứ Hai."},{"hanzi":"Small businesses often create local employment, but they may struggle to compete with larger companies.","pinyin":"","meaning":"Các doanh nghiệp nhỏ thường tạo ra việc làm tại địa phương, nhưng họ có thể gặp khó khăn khi cạnh tranh với các công ty lớn hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_13_3', 'en-a1-13', 'Cách dùng “price” (n.) — giá cả; giá tiền', 'high prices  ·  pay the price  ·  price rise', 'Nói giá cao hay thấp dùng tính từ high hoặc low; nói món đồ đắt hay rẻ dùng expensive hoặc cheap.', 'Họ từ (Word Family): priceless (adj.), pricey (adj.), pricing (n.)', '[{"hanzi":"The price of fresh strawberries has fallen this week.","pinyin":"","meaning":"Giá của dâu tây tươi đã giảm trong tuần này."},{"hanzi":"Rising food prices place considerable pressure on families with limited incomes, particularly in urban areas.","pinyin":"","meaning":"Giá lương thực tăng cao gây áp lực đáng kể cho các gia đình có thu nhập hạn hẹp, đặc biệt là ở khu vực thành thị."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_13_4', 'en-a1-13', 'Cách dùng “worker” (n.) — người lao động; công nhân; nhân viên', 'factory worker  ·  skilled worker  ·  healthcare worker', 'Không chỉ chỉ lao động chân tay, từ này còn có thể chỉ nhân viên y tế và các nghề nghiệp khác.', 'Họ từ (Word Family): work (v.), working (adj.), workforce (n.) | Đồng nghĩa: employee', '[{"hanzi":"A worker in orange overalls repaired the broken fence.","pinyin":"","meaning":"Một công nhân mặc quần áo bảo hộ màu cam đã sửa chiếc hàng rào bị hỏng."},{"hanzi":"Employers should provide every worker with appropriate training and equipment to reduce the risk of workplace injuries.","pinyin":"","meaning":"Người sử dụng lao động nên cung cấp cho mọi nhân viên các khóa đào tạo và trang thiết bị phù hợp để giảm thiểu nguy cơ tai nạn tại nơi làm việc."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_13_1', 'en-a1-13', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_13_1_1', 'ten_13_1', 'worker', 'A worker in orange overalls repaired the broken fence.', 'A worker in orange overalls repaired the broken fence.', '/ˈwɝːkɚ/', 'Một công nhân mặc quần áo bảo hộ màu cam đã sửa chiếc hàng rào bị hỏng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_13_1_2', 'ten_13_1', 'waitress', 'The waitress brought us warm bread and fresh soup.', 'The waitress brought us warm bread and fresh soup.', '/ˈweɪtrəs/', 'Nữ phục vụ mang đến cho chúng tôi bánh mì ấm và súp nóng hổi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_13_1_3', 'ten_13_1', 'job', 'My sister found a job at the local library.', 'My sister found a job at the local library.', '/dʒɑːb/', 'Chị tôi đã tìm được một công việc tại thư viện địa phương.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_13_1_4', 'ten_13_1', 'farm', 'We bought fresh eggs from a nearby farm.', 'We bought fresh eggs from a nearby farm.', '/fɑːrm/', 'Chúng tôi mua trứng tươi từ một trang trại gần nhà.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_13_1_5', 'ten_13_1', 'farmer', 'The farmer feeds her chickens before the sun rises.', 'The farmer feeds her chickens before the sun rises.', '/ˈfɑːrmər/', 'Người nông dân cho đàn gà ăn trước khi mặt trời mọc.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_13_1_6', 'ten_13_1', 'business', 'Business is usually slow at the café on Mondays.', 'Business is usually slow at the café on Mondays.', '/ˈbɪznəs/', 'Việc kinh doanh tại quán cà phê thường khá ế ẩm vào các ngày thứ Hai.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_13_1_7', 'ten_13_1', 'company', 'My sister works for a company that makes bicycles.', 'My sister works for a company that makes bicycles.', '/ˈkʌmpəni/', 'Chị gái tôi làm việc cho một công ty sản xuất xe đạp.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_13_1_8', 'ten_13_1', 'meeting', 'Our team meeting starts right after lunch today.', 'Our team meeting starts right after lunch today.', '/ˈmiːtɪŋ/', 'Cuộc họp nhóm của chúng ta bắt đầu ngay sau bữa trưa hôm nay.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_13_1_1', 'en-a1-13', 'ten_13_1', 'listening', 'listening', 'A worker in orange overalls repaired the broken fence.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một công nhân mặc quần áo bảo hộ màu cam đã sửa chiếc hàng rào bị hỏng.","Chúng tôi mua trứng tươi từ một trang trại gần nhà.","Cuộc họp nhóm của chúng ta bắt đầu ngay sau bữa trưa hôm nay.","Nữ phục vụ mang đến cho chúng tôi bánh mì ấm và súp nóng hổi."]'::jsonb, 0, 'A worker in orange overalls repaired the broken fence. → Một công nhân mặc quần áo bảo hộ màu cam đã sửa chiếc hàng rào bị hỏng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_13_1_2', 'en-a1-13', 'ten_13_1', 'listening', 'listening', 'The waitress brought us warm bread and fresh soup.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chị tôi đã tìm được một công việc tại thư viện địa phương.","Nữ phục vụ mang đến cho chúng tôi bánh mì ấm và súp nóng hổi.","Một công nhân mặc quần áo bảo hộ màu cam đã sửa chiếc hàng rào bị hỏng.","Chúng tôi mua trứng tươi từ một trang trại gần nhà."]'::jsonb, 1, 'The waitress brought us warm bread and fresh soup. → Nữ phục vụ mang đến cho chúng tôi bánh mì ấm và súp nóng hổi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_13_1_3', 'en-a1-13', 'ten_13_1', 'listening', 'listening', 'My sister found a job at the local library.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chị tôi đã tìm được một công việc tại thư viện địa phương.","Chúng tôi mua trứng tươi từ một trang trại gần nhà.","Một công nhân mặc quần áo bảo hộ màu cam đã sửa chiếc hàng rào bị hỏng.","Cuộc họp nhóm của chúng ta bắt đầu ngay sau bữa trưa hôm nay."]'::jsonb, 0, 'My sister found a job at the local library. → Chị tôi đã tìm được một công việc tại thư viện địa phương.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_13_2', 'en-a1-13', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_13_2_1', 'ten_13_2', 'worker', 'Employers should provide every worker with appropriate training and equipment to reduce the risk of workplace injuries.', 'Employers should provide every worker with appropriate training and equipment to reduce the risk of workplace injuries.', '/ˈwɝːkɚ/', 'Người sử dụng lao động nên cung cấp cho mọi nhân viên các khóa đào tạo và trang thiết bị phù hợp để giảm thiểu nguy cơ tai nạn tại nơi làm việc.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_13_2_2', 'ten_13_2', 'waitress', 'Working as a waitress can help students develop communication skills while earning money to support their studies.', 'Working as a waitress can help students develop communication skills while earning money to support their studies.', '/ˈweɪtrəs/', 'Làm việc như một nữ phục vụ bàn có thể giúp sinh viên phát triển kỹ năng giao tiếp đồng thời kiếm tiền trang trải việc học.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_13_2_3', 'ten_13_2', 'job', 'Access to practical training can help young people secure a job in a competitive labour market.', 'Access to practical training can help young people secure a job in a competitive labour market.', '/dʒɑːb/', 'Việc tiếp cận đào tạo thực tế có thể giúp những người trẻ tuổi tìm được việc làm trong một thị trường lao động cạnh tranh.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_13_2_4', 'ten_13_2', 'farm', 'Small farms can support local food supplies while creating employment opportunities in rural communities.', 'Small farms can support local food supplies while creating employment opportunities in rural communities.', '/fɑːrm/', 'Các trang trại quy mô nhỏ có thể duy trì nguồn cung thực phẩm địa phương đồng thời tạo ra cơ hội việc làm ở các vùng nông thôn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_13_2_5', 'ten_13_2', 'farmer', 'Small farmers need reliable access to water and affordable technology to maintain production during dry periods.', 'Small farmers need reliable access to water and affordable technology to maintain production during dry periods.', '/ˈfɑːrmər/', 'Các hộ nông dân nhỏ cần được tiếp cận nguồn nước ổn định và công nghệ giá cả phải chăng để duy trì sản xuất trong những giai đoạn khô hạn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_13_2_6', 'ten_13_2', 'business', 'Small businesses often create local employment, but they may struggle to compete with larger companies.', 'Small businesses often create local employment, but they may struggle to compete with larger companies.', '/ˈbɪznəs/', 'Các doanh nghiệp nhỏ thường tạo ra việc làm tại địa phương, nhưng họ có thể gặp khó khăn khi cạnh tranh với các công ty lớn hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_13_2_1', 'en-a1-13', 'ten_13_2', 'listening', 'listening', 'Employers should provide every worker with appropriate training and equipment to reduce the risk of workplace injuries.', NULL, 'Trong câu vừa nghe, từ “worker” mang nghĩa nào sau đây?', '["tắm; ngâm bồn","sự nghỉ ngơi; khoảng thời gian thư giãn","người lao động; công nhân; nhân viên","không có gì; không điều gì"]'::jsonb, 2, '“worker” (/ˈwɝːkɚ/): người lao động; công nhân; nhân viên. Câu đầy đủ: Employers should provide every worker with appropriate training and equipment to reduce the risk of workplace injuries.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_13_2_2', 'en-a1-13', 'ten_13_2', 'listening', 'listening', 'Working as a waitress can help students develop communication skills while earning money to support their studies.', NULL, 'Trong câu vừa nghe, từ “waitress” mang nghĩa nào sau đây?', '["nữ phục vụ bàn; nữ bồi bàn","số một (số nguyên dương nhỏ nhất)","ở ngoài; ra ngoài; vắng nhà","xu (đơn vị tiền tệ bằng một phần trăm của đô-la hoặc ơ-rô)"]'::jsonb, 0, '“waitress” (/ˈweɪtrəs/): nữ phục vụ bàn; nữ bồi bàn. Câu đầy đủ: Working as a waitress can help students develop communication skills while earning money to support their studies.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
