INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_13_1', 'en-a1-13', NULL, 'comprehensive_test', 'listening', 'worker', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["xám; xám xịt; hoa râm","mặt trời","người lao động; công nhân; nhân viên","xe đạp"]'::jsonb, 2, 'worker (/ˈwɝːkɚ/) → người lao động; công nhân; nhân viên', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_13_2', 'en-a1-13', NULL, 'comprehensive_test', 'listening', 'The waitress brought us warm bread and fresh soup.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi tìm thấy một đồng xu một xu ở dưới đệm ghế sofa.","Nữ phục vụ mang đến cho chúng tôi bánh mì ấm và súp nóng hổi.","Chúng tôi tìm thấy một quán cà phê giá rẻ gần ga tàu.","Chúng tôi đã mua những quả đào tươi ở chợ vào sáng nay."]'::jsonb, 1, 'The waitress brought us warm bread and fresh soup. → Nữ phục vụ mang đến cho chúng tôi bánh mì ấm và súp nóng hổi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_13_3', 'en-a1-13', NULL, 'comprehensive_test', 'listening', 'job', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["công việc; nghề nghiệp; việc làm","thị trấn; thị xã","bay","nhiều (dùng với danh từ không đếm được)"]'::jsonb, 0, 'job (/dʒɑːb/) → công việc; nghề nghiệp; việc làm; nhiệm vụ; công việc cụ thể', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_13_4', 'en-a1-13', NULL, 'comprehensive_test', 'listening', 'We bought fresh eggs from a nearby farm.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Đội của chúng tôi đã ăn mừng bằng bánh pizza sau khi giành chiến thắng trong trận đấu.","Chúng tôi tìm thấy một quán cà phê giá rẻ gần ga tàu.","Chúng tôi mua trứng tươi từ một trang trại gần nhà.","Cuộc họp nhóm của chúng ta bắt đầu ngay sau bữa trưa hôm nay."]'::jsonb, 2, 'We bought fresh eggs from a nearby farm. → Chúng tôi mua trứng tươi từ một trang trại gần nhà.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_13_5', 'en-a1-13', NULL, 'comprehensive_test', 'listening', 'farmer', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nghệ sĩ; họa sĩ","nông dân; chủ trang trại","bất kỳ ai","vợ"]'::jsonb, 1, 'farmer (/ˈfɑːrmər/) → nông dân; chủ trang trại', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_13_6', 'en-a1-13', NULL, 'comprehensive_test', 'listening', 'Business is usually slow at the café on Mondays.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cuộc họp nhóm của chúng ta bắt đầu ngay sau bữa trưa hôm nay.","Đội của chúng tôi đã ăn mừng bằng bánh pizza sau khi giành chiến thắng trong trận đấu.","Tôi để quên chiếc ô dưới bàn làm việc ở văn phòng.","Việc kinh doanh tại quán cà phê thường khá ế ẩm vào các ngày thứ Hai."]'::jsonb, 3, 'Business is usually slow at the café on Mondays. → Việc kinh doanh tại quán cà phê thường khá ế ẩm vào các ngày thứ Hai.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
