INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_13_8', 'en-a1-13', NULL, 'comprehensive_test', 'listening', 'Our team meeting starts right after lunch today.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Đôi bốt này quá đắt so với ngân sách của tôi.","Cuộc họp nhóm của chúng ta bắt đầu ngay sau bữa trưa hôm nay.","Chúng tôi đã mua những quả đào tươi ở chợ vào sáng nay.","Chúng tôi đã tiêu hết tiền vào trái cây tươi."]'::jsonb, 1, 'Our team meeting starts right after lunch today. → Cuộc họp nhóm của chúng ta bắt đầu ngay sau bữa trưa hôm nay.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
