INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_13_18', 'en-a1-13', NULL, 'comprehensive_test', 'reading', NULL, 'Employers should provide every worker with appropriate training and equipment to reduce the risk of workplace injuries.', 'Dựa vào câu trên, từ “worker” có nghĩa phù hợp nhất là gì?', '["người lao động; công nhân; nhân viên","Thụy Sĩ","trở thành; trở nên","sự vận động; bài tập"]'::jsonb, 0, 'worker: người lao động; công nhân; nhân viên. Dịch cả câu: Người sử dụng lao động nên cung cấp cho mọi nhân viên các khóa đào tạo và trang thiết bị phù hợp để giảm thiểu nguy cơ tai nạn tại nơi làm việc.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_13_19', 'en-a1-13', NULL, 'comprehensive_test', 'reading', NULL, 'Working as a waitress can help students develop communication skills while earning money to support their studies.', 'Dựa vào câu trên, từ “waitress” có nghĩa phù hợp nhất là gì?', '["nữ phục vụ bàn; nữ bồi bàn","chọn; lựa chọn","máy ảnh; máy quay phim; camera","mặt trước; phần trước"]'::jsonb, 0, 'waitress: nữ phục vụ bàn; nữ bồi bàn. Dịch cả câu: Làm việc như một nữ phục vụ bàn có thể giúp sinh viên phát triển kỹ năng giao tiếp đồng thời kiếm tiền trang trải việc học.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_13_20', 'en-a1-13', NULL, 'comprehensive_test', 'reading', NULL, 'Access to practical training can help young people secure a job in a competitive labour market.', 'Dựa vào câu trên, từ “job” có nghĩa phù hợp nhất là gì?', '["hoa; bông hoa","công việc; nghề nghiệp; việc làm","bài kiểm tra; bài trắc nghiệm; sự xét nghiệm","hoạt động"]'::jsonb, 1, 'job: công việc; nghề nghiệp; việc làm; nhiệm vụ; công việc cụ thể. Dịch cả câu: Việc tiếp cận đào tạo thực tế có thể giúp những người trẻ tuổi tìm được việc làm trong một thị trường lao động cạnh tranh.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_13_21', 'en-a1-13', NULL, 'comprehensive_test', 'reading', NULL, 'Small farms can support local food supplies while creating employment opportunities in rural communities.', 'Dựa vào câu trên, từ “farm” có nghĩa phù hợp nhất là gì?', '["lịch sử; môn lịch sử","phòng; buồng","cao; cao lớn","nông trại; trang trại"]'::jsonb, 3, 'farm: nông trại; trang trại; làm nông; canh tác; chăn nuôi. Dịch cả câu: Các trang trại quy mô nhỏ có thể duy trì nguồn cung thực phẩm địa phương đồng thời tạo ra cơ hội việc làm ở các vùng nông thôn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_13_22', 'en-a1-13', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bán; tiêu thụ”', '["football","twelve","sell","as"]'::jsonb, 2, 'bán; tiêu thụ → sell (/sel/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_13_23', 'en-a1-13', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đắt đỏ; tốn kém”', '["expensive","useful","into","every"]'::jsonb, 0, 'đắt đỏ; tốn kém → expensive (/ɪkˈspensɪv/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_13_24', 'en-a1-13', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “rẻ; giá rẻ; giá thấp”', '["cheap","there","watch","later"]'::jsonb, 0, 'rẻ; giá rẻ; giá thấp → cheap (/tʃiːp/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-14', 'en', 'Bài 14: Đô thị & Thể thao - CEFR A1', 'CEFR A1', 'A1 · Đô thị & Thể thao', '25 từ vựng Tiếng Anh CEFR A1 chủ đề đô thị & thể thao kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1014, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_town', 'en-a1-14', 'town', '/taʊn/', 'A1', 'thị trấn; thị xã; thị trấn; khu trung tâm thương mại', 'n.', NULL, NULL, 'go into town có nghĩa là đi vào trung tâm thành phố, trong trường hợp này town không đi kèm mạo từ.', 'Our town has a bakery beside the old bridge.', NULL, 'Thị trấn của chúng tôi có một tiệm bánh nằm cạnh cây cầu cổ.', '{"wordId":"town","ukIpa":"/taʊn/","usIpa":"/taʊn/","cefr":"A1","topic":"city","senses":[{"pos":"n.","en":"A settlement usually larger than a village but smaller than a city","vi":"thị trấn; thị xã"},{"pos":"n.","en":"The central area where people go shopping or do business","vi":"thị trấn; khu trung tâm thương mại"}],"examples":[{"en":"Our town has a bakery beside the old bridge.","vi":"Thị trấn của chúng tôi có một tiệm bánh nằm cạnh cây cầu cổ.","audioKind":"ex"},{"en":"Improving public transport in a small town can help residents access jobs and essential services.","vi":"Việc cải thiện giao thông công cộng ở một thị trấn nhỏ có thể giúp cư dân tiếp cận việc làm và các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"small town","vi":"thị trấn nhỏ"},{"en":"town centre","vi":"trung tâm thị trấn; trung tâm thành phố"},{"en":"coastal town","vi":"thị trấn ven biển"},{"en":"go into town","vi":"đi vào trung tâm thành phố"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"go into town có nghĩa là đi vào trung tâm thành phố, trong trường hợp này town không đi kèm mạo từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_london', 'en-a1-14', 'London', '/ˈlʌndən/', 'A1', 'thủ đô của Vương quốc Anh', 'n.', 'Londoner (n.)', NULL, 'Tên thành phố viết hoa chữ cái đầu; thường không đi kèm mạo từ the.', 'We spent a rainy afternoon exploring London by bus.', NULL, 'Chúng tôi đã dành một buổi chiều mưa để khám phá Luân Đôn bằng xe buýt.', '{"wordId":"london","ukIpa":"/ˈlʌndən/","usIpa":"/ˈlʌndən/","cefr":"A1","topic":"city","senses":[{"pos":"n.","en":"The capital city of the United Kingdom.","vi":"thủ đô của Vương quốc Anh"}],"examples":[{"en":"We spent a rainy afternoon exploring London by bus.","vi":"Chúng tôi đã dành một buổi chiều mưa để khám phá Luân Đôn bằng xe buýt.","audioKind":"ex"},{"en":"London attracts international students because its universities offer diverse courses and access to extensive cultural resources.","vi":"Luân Đôn thu hút sinh viên quốc tế vì các trường đại học ở đây cung cấp nhiều khóa học đa dạng và nguồn tài nguyên văn hóa phong phú.","audioKind":"ex2"}],"collocations":[{"en":"central London","vi":"trung tâm Luân Đôn"},{"en":"Greater London","vi":"Đại Luân Đôn"},{"en":"the London Underground","vi":"tuyến tàu điện ngầm Luân Đôn"}],"wordFamily":["Londoner (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tên thành phố viết hoa chữ cái đầu; thường không đi kèm mạo từ the.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_centre', 'en-a1-14', 'centre', '/ˈsentər/', 'A1', 'trung tâm; điểm chính giữa; trung tâm (nơi cung cấp dịch vụ, hoạt động cụ thể); tập trung vào; lấy làm trung tâm', 'n.', 'central (adj.), centrally (adv.)', 'Đồng nghĩa: middle · Trái nghĩa: edge', 'centre là chính tả Anh-Anh, Anh-Mỹ viết là center; động từ thường đi kèm với on.', 'We placed a vase in the centre of the table.', NULL, 'Chúng tôi đặt một bình hoa ở ngay chính giữa bàn.', '{"wordId":"centre","ukIpa":"/ˈsentə/","usIpa":"/ˈsentər/","cefr":"A1","topic":"city","senses":[{"pos":"n.","en":"The middle point or area of something.","vi":"trung tâm; điểm chính giữa"},{"pos":"n.","en":"A place providing particular activities, services, or facilities.","vi":"trung tâm (nơi cung cấp dịch vụ, hoạt động cụ thể)"},{"pos":"v.","en":"Make something the main focus of attention or activity.","vi":"tập trung vào; lấy làm trung tâm"}],"examples":[{"en":"We placed a vase in the centre of the table.","vi":"Chúng tôi đặt một bình hoa ở ngay chính giữa bàn.","audioKind":"ex"},{"en":"A new community centre could provide affordable exercise facilities and meeting spaces for local residents.","vi":"Một trung tâm cộng đồng mới có thể cung cấp các cơ sở tập thể dục vừa túi tiền và không gian hội họp cho người dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"city centre","vi":"trung tâm thành phố"},{"en":"community centre","vi":"trung tâm cộng đồng"},{"en":"centre on","vi":"tập trung vào..."}],"wordFamily":["central (adj.)","centrally (adv.)"],"synonyms":["middle"],"antonyms":["edge"],"tipVi":"centre là chính tả Anh-Anh, Anh-Mỹ viết là center; động từ thường đi kèm với on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_city', 'en-a1-14', 'city', '/ˈsɪti/', 'A1', 'thành phố; đô thị', 'n.', NULL, NULL, 'Dạng số nhiều là cities; trung tâm thành phố trong tiếng Anh-Anh thường dùng city centre.', 'We explored the city on foot all afternoon.', NULL, 'Chúng tôi đã dành cả buổi chiều đi bộ khám phá thành phố.', '{"wordId":"city","ukIpa":"/ˈsɪti/","usIpa":"/ˈsɪti/","cefr":"A1","topic":"city","senses":[{"pos":"n.","en":"A large town where many people live and work.","vi":"thành phố; đô thị"}],"examples":[{"en":"We explored the city on foot all afternoon.","vi":"Chúng tôi đã dành cả buổi chiều đi bộ khám phá thành phố.","audioKind":"ex"},{"en":"A well-designed city provides accessible public transport and green spaces that improve residents'' quality of life.","vi":"Một thành phố được quy hoạch tốt sẽ cung cấp hệ thống giao thông công cộng thuận tiện và các mảng xanh giúp nâng cao chất lượng cuộc sống của cư dân.","audioKind":"ex2"}],"collocations":[{"en":"city centre","vi":"trung tâm thành phố"},{"en":"a major city","vi":"thành phố lớn"},{"en":"city life","vi":"cuộc sống thành thị"},{"en":"city planning","vi":"quy hoạch đô thị"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là cities; trung tâm thành phố trong tiếng Anh-Anh thường dùng city centre.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_village', 'en-a1-14', 'village', '/ˈvɪlɪdʒ/', 'A1', 'n. làng; làng mạc; thôn; n. dân làng; toàn thể người dân trong làng', 'n.', 'villager (n.)', NULL, 'Cụm từ the whole village có thể chỉ toàn thể người dân trong làng chứ không phải các công trình xây dựng.', 'Our village has a bakery beside the old bridge.', NULL, 'Làng chúng tôi có một tiệm bánh nằm cạnh cây cầu cổ.', '{"wordId":"village","ukIpa":"/ˈvɪlɪdʒ/","usIpa":"/ˈvɪlɪdʒ/","cefr":"A1","topic":"city","senses":[{"pos":"n.","en":"A small community of homes, usually in the countryside.","vi":"n. làng; làng mạc; thôn"},{"pos":"n.","en":"The people who live in a village, considered together.","vi":"n. dân làng; toàn thể người dân trong làng"}],"examples":[{"en":"Our village has a bakery beside the old bridge.","vi":"Làng chúng tôi có một tiệm bánh nằm cạnh cây cầu cổ.","audioKind":"ex"},{"en":"Reliable public transport can help village residents access employment, education, and healthcare in nearby towns.","vi":"Giao thông công cộng đáng tin cậy có thể giúp dân làng tiếp cận việc làm, giáo dục và y tế ở các thị trấn gần đó.","audioKind":"ex2"}],"collocations":[{"en":"a remote village","vi":"một ngôi làng hẻo lánh"},{"en":"a fishing village","vi":"làng chài"},{"en":"village life","vi":"đời sống nông thôn"},{"en":"village residents","vi":"cư dân trong làng"}],"wordFamily":["villager (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ the whole village có thể chỉ toàn thể người dân trong làng chứ không phải các công trình xây dựng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_house', 'en-a1-14', 'house', '/haʊs/', 'A1', 'nhà; ngôi nhà để ở; cung cấp chỗ ở; chứa, dung nạp', 'n.', 'housing (n.), household (n.), householder (n.)', NULL, 'Danh từ đọc /haʊs/, động từ đọc /haʊz/; home nhấn mạnh sự gắn bó tình cảm hơn.', 'Their house has a small garden behind the kitchen.', NULL, 'Ngôi nhà của họ có một khu vườn nhỏ phía sau nhà bếp.', '{"wordId":"house","ukIpa":"/haʊs/","usIpa":"/haʊs/","cefr":"A1","topic":"city","senses":[{"pos":"n.","en":"A building where a person or family lives.","vi":"nhà; ngôi nhà để ở"},{"pos":"v.","en":"To provide a place for people or things to stay.","vi":"cung cấp chỗ ở; chứa, dung nạp"}],"examples":[{"en":"Their house has a small garden behind the kitchen.","vi":"Ngôi nhà của họ có một khu vườn nhỏ phía sau nhà bếp.","audioKind":"ex"},{"en":"Local authorities could convert unused office buildings into apartments to house families in need of affordable accommodation.","vi":"Chính quyền địa phương có thể chuyển đổi các tòa nhà văn phòng bỏ trống thành căn hộ để cung cấp chỗ ở cho các gia đình cần nhà ở giá rẻ.","audioKind":"ex2"}],"collocations":[{"en":"buy a house","vi":"mua nhà"},{"en":"move house","vi":"dọn nhà; chuyển nhà"},{"en":"house prices","vi":"giá nhà"},{"en":"house families","vi":"cung cấp nhà ở cho các gia đình"}],"wordFamily":["housing (n.)","household (n.)","householder (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ đọc /haʊs/, động từ đọc /haʊz/; home nhấn mạnh sự gắn bó tình cảm hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_area', 'en-a1-14', 'area', '/ˈeriə/', 'A1', 'vùng; khu vực; địa bàn; diện tích; lĩnh vực; mảng', 'n.', NULL, NULL, 'Khi chỉ kích thước bề mặt thường dùng kèm các đơn vị như mét vuông; ngoài ra từ này cũng dùng để chỉ lĩnh vực học tập hoặc nghiên cứu.', 'There is a quiet picnic area beside the lake.', NULL, 'Có một khu vực dã ngoại yên tĩnh nằm bên cạnh hồ nước.', '{"wordId":"area","ukIpa":"/ˈeəriə/","usIpa":"/ˈeriə/","cefr":"A1","topic":"city","senses":[{"pos":"n.","en":"A particular part of a place or geographical region","vi":"vùng; khu vực; địa bàn"},{"pos":"n.","en":"The amount of surface that something covers","vi":"diện tích"},{"pos":"n.","en":"A particular subject or part of an activity","vi":"lĩnh vực; mảng"}],"examples":[{"en":"There is a quiet picnic area beside the lake.","vi":"Có một khu vực dã ngoại yên tĩnh nằm bên cạnh hồ nước.","audioKind":"ex"},{"en":"Investment in public transport can improve access to employment for people living in rural areas.","vi":"Việc đầu tư vào giao thông công cộng có thể giúp những người sống ở vùng nông thôn dễ dàng tiếp cận cơ hội việc làm hơn.","audioKind":"ex2"}],"collocations":[{"en":"a residential area","vi":"khu dân cư"},{"en":"surface area","vi":"diện tích bề mặt"},{"en":"an area of research","vi":"lĩnh vực nghiên cứu"},{"en":"rural areas","vi":"các vùng nông thôn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ kích thước bề mặt thường dùng kèm các đơn vị như mét vuông; ngoài ra từ này cũng dùng để chỉ lĩnh vực học tập hoặc nghiên cứu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_build', 'en-a1-14', 'build', '/bɪld/', 'A1', 'xây dựng; kiến thiết; vóc dáng; thể hình', 'v.', 'builder (n.), building (n.), rebuild (v.)', 'Đồng nghĩa: construct · Trái nghĩa: demolish', 'Dạng quá khứ và quá phân từ của build đều là built; build cũng dùng để chỉ vóc dáng cơ thể.', 'We built a small wooden shelter in the garden.', NULL, 'Chúng tôi đã dựng một cái lán gỗ nhỏ trong vườn.', '{"wordId":"build","ukIpa":"/bɪld/","usIpa":"/bɪld/","cefr":"A1","topic":"city","senses":[{"pos":"v.","en":"to make structures or develop something over time","vi":"xây dựng; kiến thiết"},{"pos":"n.","en":"the size and shape of a person''s body","vi":"vóc dáng; thể hình"}],"examples":[{"en":"We built a small wooden shelter in the garden.","vi":"Chúng tôi đã dựng một cái lán gỗ nhỏ trong vườn.","audioKind":"ex"},{"en":"Local authorities should build more affordable homes near public transport to support families on low incomes.","vi":"Chính quyền địa phương nên xây dựng nhiều nhà ở giá rẻ gần các tuyến giao thông công cộng để hỗ trợ các gia đình thu nhập thấp.","audioKind":"ex2"}],"collocations":[{"en":"build a house","vi":"xây nhà"},{"en":"build confidence","vi":"xây dựng sự tự tin"},{"en":"build relationships","vi":"xây dựng mối quan hệ"},{"en":"a slim build","vi":"vóc dáng mảnh mai"}],"wordFamily":["builder (n.)","building (n.)","rebuild (v.)"],"synonyms":["construct"],"antonyms":["demolish"],"tipVi":"Dạng quá khứ và quá phân từ của build đều là built; build cũng dùng để chỉ vóc dáng cơ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_building', 'en-a1-14', 'building', '/ˈbɪldɪŋ/', 'A1', 'tòa nhà; công trình kiến trúc; sự xây dựng; ngành xây dựng', 'n.', 'build (v.), builder (n.), rebuild (v.)', NULL, 'Khi chỉ công trình xây dựng thì đếm được, khi chỉ hoạt động xây dựng thì thường không đếm được.', 'Our apartment building has a garden on the roof.', NULL, 'Tòa nhà chung cư của chúng tôi có một khu vườn trên mái.', '{"wordId":"building","ukIpa":"/ˈbɪldɪŋ/","usIpa":"/ˈbɪldɪŋ/","cefr":"A1","topic":"city","senses":[{"pos":"n.","en":"a structure with walls and a roof","vi":"tòa nhà; công trình kiến trúc"},{"pos":"n.","en":"the activity of constructing houses or other structures","vi":"sự xây dựng; ngành xây dựng"}],"examples":[{"en":"Our apartment building has a garden on the roof.","vi":"Tòa nhà chung cư của chúng tôi có một khu vườn trên mái.","audioKind":"ex"},{"en":"Improving insulation in older buildings can reduce energy consumption and lower heating costs for residents.","vi":"Cải thiện khả năng cách nhiệt ở các tòa nhà cũ có thể làm giảm tiêu thụ năng lượng và hạ chi phí sưởi ấm cho cư dân.","audioKind":"ex2"}],"collocations":[{"en":"office building","vi":"tòa nhà văn phòng"},{"en":"building materials","vi":"vật liệu xây dựng"},{"en":"building site","vi":"công trường xây dựng"},{"en":"historic building","vi":"công trình lịch sử"}],"wordFamily":["build (v.)","builder (n.)","rebuild (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ công trình xây dựng thì đếm được, khi chỉ hoạt động xây dựng thì thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flat', 'en-a1-14', 'flat', '/flæt/', 'A1', 'căn hộ; phẳng; bằng phẳng; xì hơi; bẹp', 'n.', 'flatten (v.), flatness (n.)', 'Đồng nghĩa: apartment, level · Trái nghĩa: uneven', 'Từ "căn hộ" thì tiếng Anh-Anh hay dùng flat, còn tiếng Anh-Mỹ dùng apartment.', 'We rent a small flat above a busy bakery.', NULL, 'Chúng tôi thuê một căn hộ nhỏ ở tầng trên của một tiệm bánh đông khách.', '{"wordId":"flat","ukIpa":"/flæt/","usIpa":"/flæt/","cefr":"A1","topic":"city","senses":[{"pos":"n.","en":"a set of rooms forming a home within a building","vi":"căn hộ"},{"pos":"adj.","en":"level and smooth, without raised or curved parts","vi":"phẳng; bằng phẳng"},{"pos":"adj.","en":"having too little air inside, especially a tyre","vi":"xì hơi; bẹp"}],"examples":[{"en":"We rent a small flat above a busy bakery.","vi":"Chúng tôi thuê một căn hộ nhỏ ở tầng trên của một tiệm bánh đông khách.","audioKind":"ex"},{"en":"Building affordable flats near public transport could reduce commuting costs for many urban workers.","vi":"Việc xây dựng các căn hộ giá cả phải chăng gần các phương tiện giao thông công cộng có thể làm giảm chi phí đi lại cho nhiều người lao động đô thị.","audioKind":"ex2"}],"collocations":[{"en":"rent a flat","vi":"thuê căn hộ"},{"en":"flat surface","vi":"bề mặt phẳng"},{"en":"flat tyre","vi":"lốp xe xì hơi"}],"wordFamily":["flatten (v.)","flatness (n.)"],"synonyms":["apartment","level"],"antonyms":["uneven"],"tipVi":"Từ \"căn hộ\" thì tiếng Anh-Anh hay dùng flat, còn tiếng Anh-Mỹ dùng apartment.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_park', 'en-a1-14', 'park', '/pɑrk/', 'A1', 'công viên; đỗ xe; dừng xe; khu công nghiệp; khu chức năng', 'n.', 'parking (n.)', NULL, 'Công viên dùng park; trong tiếng Anh-Anh, bãi đậu xe dùng car park.', 'We shared a picnic under the trees in the park.', NULL, 'Chúng tôi đã cùng nhau ăn buổi dã ngoại dưới những tán cây trong công viên.', '{"wordId":"park","ukIpa":"/pɑːk/","usIpa":"/pɑrk/","cefr":"A1","topic":"city","senses":[{"pos":"n.","en":"An open area with grass and trees for public enjoyment.","vi":"công viên"},{"pos":"v.","en":"To stop a vehicle somewhere and leave it there.","vi":"đỗ xe; dừng xe"},{"pos":"n.","en":"An area set aside for a particular activity or purpose.","vi":"khu công nghiệp; khu chức năng"}],"examples":[{"en":"We shared a picnic under the trees in the park.","vi":"Chúng tôi đã cùng nhau ăn buổi dã ngoại dưới những tán cây trong công viên.","audioKind":"ex"},{"en":"Providing a park within walking distance of every neighbourhood can encourage exercise and strengthen community ties.","vi":"Việc xây dựng một công viên trong khoảng cách có thể đi bộ từ mỗi khu dân cư có thể khuyến khích việc tập thể dục và thắt chặt tình làng nghĩa xóm.","audioKind":"ex2"}],"collocations":[{"en":"public park","vi":"công viên công cộng"},{"en":"park a car","vi":"đỗ xe ô tô"},{"en":"business park","vi":"khu thương mại; khu doanh nghiệp"},{"en":"national park","vi":"vườn quốc gia"}],"wordFamily":["parking (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Công viên dùng park; trong tiếng Anh-Anh, bãi đậu xe dùng car park.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_street', 'en-a1-14', 'street', '/striːt/', 'A1', 'đường phố; phố', 'n.', NULL, NULL, 'Street thường chỉ con đường trong thị trấn có các tòa nhà nằm hai bên.', 'We crossed the street to reach the bakery.', NULL, 'Chúng tôi băng qua đường để đi đến tiệm bánh.', '{"wordId":"street","ukIpa":"/striːt/","usIpa":"/striːt/","cefr":"A1","topic":"city","senses":[{"pos":"n.","en":"a public road in a town, usually lined with buildings","vi":"đường phố; phố"}],"examples":[{"en":"We crossed the street to reach the bakery.","vi":"Chúng tôi băng qua đường để đi đến tiệm bánh.","audioKind":"ex"},{"en":"Planting trees along busy streets can improve air quality and make urban neighbourhoods more pleasant for pedestrians.","vi":"Việc trồng cây dọc các tuyến phố đông đúc có thể cải thiện chất lượng không khí và khiến các khu phố đô thị dễ chịu hơn cho người đi bộ.","audioKind":"ex2"}],"collocations":[{"en":"cross the street","vi":"băng qua đường"},{"en":"busy street","vi":"con đường nhộn nhịp"},{"en":"residential street","vi":"đường khu dân cư"},{"en":"street lighting","vi":"hệ thống chiếu sáng đường phố"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Street thường chỉ con đường trong thị trấn có các tòa nhà nằm hai bên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_post-office', 'en-a1-14', 'post office', '/ˈpoʊst ˌɑːfɪs/', 'A1', 'bưu điện', 'n.', 'post (n.), post (v.), postal (adj.)', NULL, 'Cách viết chuẩn là post office, không có gạch nối giữa hai từ.', 'I took the parcel to the post office before lunch.', NULL, 'Tôi đã mang bưu kiện ra bưu điện trước bữa trưa.', '{"wordId":"post-office","ukIpa":"/ˈpəʊst ˌɒfɪs/","usIpa":"/ˈpoʊst ˌɑːfɪs/","cefr":"A1","topic":"city","senses":[{"pos":"n.","en":"a place where people send mail and buy stamps","vi":"bưu điện"}],"examples":[{"en":"I took the parcel to the post office before lunch.","vi":"Tôi đã mang bưu kiện ra bưu điện trước bữa trưa.","audioKind":"ex"},{"en":"A local post office can provide essential services for rural residents who lack reliable internet access.","vi":"Một bưu điện địa phương có thể cung cấp các dịch vụ thiết yếu cho cư dân nông thôn thiếu kết nối Internet ổn định.","audioKind":"ex2"}],"collocations":[{"en":"local post office","vi":"bưu điện địa phương"},{"en":"post office counter","vi":"quầy bưu điện"},{"en":"post office branch","vi":"chi nhánh bưu điện"}],"wordFamily":["post (n.)","post (v.)","postal (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cách viết chuẩn là post office, không có gạch nối giữa hai từ.","noteVi":"Đã chuyển đổi cách viết có gạch nối không chuẩn thành post office.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_football', 'en-a1-14', 'football', '/ˈfʊtbɔːl/', 'A1', 'bóng đá; môn bóng đá; bóng bầu dục Mỹ', 'n.', 'footballer (n.)', NULL, 'Từ football tiếng Anh-Anh chỉ bóng đá; tiếng Anh-Mỹ thường chỉ bóng bầu dục.', 'We play football in the park every Saturday morning.', NULL, 'Chúng tôi chơi bóng đá ở công viên vào mỗi sáng thứ Bảy.', '{"wordId":"football","ukIpa":"/ˈfʊtbɔːl/","usIpa":"/ˈfʊtbɔːl/","cefr":"A1","topic":"sport","senses":[{"pos":"n.","en":"a game where teams kick a ball into opposing goals","vi":"bóng đá; môn bóng đá"},{"pos":"n.","en":"an American game involving carrying, throwing, and kicking an oval ball","vi":"bóng bầu dục Mỹ"}],"examples":[{"en":"We play football in the park every Saturday morning.","vi":"Chúng tôi chơi bóng đá ở công viên vào mỗi sáng thứ Bảy.","audioKind":"ex"},{"en":"Local football clubs can strengthen community relationships by bringing together people from different social backgrounds.","vi":"Các câu lạc bộ bóng đá địa phương có thể thắt chặt tình đoàn kết cộng đồng bằng cách quy tụ mọi người từ các tầng lớp xã hội khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"play football","vi":"chơi bóng đá"},{"en":"football match","vi":"trận đấu bóng đá"},{"en":"football pitch","vi":"sân bóng đá"},{"en":"football club","vi":"câu lạc bộ bóng đá"}],"wordFamily":["footballer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ football tiếng Anh-Anh chỉ bóng đá; tiếng Anh-Mỹ thường chỉ bóng bầu dục.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_basketball', 'en-a1-14', 'basketball', '/ˈbæskɪtbɔːl/', 'A1', 'môn bóng rổ; quả bóng rổ', 'n.', NULL, NULL, '"play basketball" không dùng mạo từ; chỉ một quả bóng dùng "a basketball".', 'We play basketball at the park after school.', NULL, 'Chúng tôi chơi bóng rổ ở công viên sau giờ học.', '{"wordId":"basketball","ukIpa":"/ˈbɑːskɪtbɔːl/","usIpa":"/ˈbæskɪtbɔːl/","cefr":"A1","topic":"sport","senses":[{"pos":"n.","en":"a game where teams throw a ball through raised hoops","vi":"môn bóng rổ"},{"pos":"n.","en":"the large round ball used in this game","vi":"quả bóng rổ"}],"examples":[{"en":"We play basketball at the park after school.","vi":"Chúng tôi chơi bóng rổ ở công viên sau giờ học.","audioKind":"ex"},{"en":"Team sports such as basketball help young people develop cooperation skills while improving their physical fitness.","vi":"Các môn thể thao tập thể như bóng rổ giúp giới trẻ phát triển kỹ năng hợp tác đồng thời nâng cao thể lực.","audioKind":"ex2"}],"collocations":[{"en":"play basketball","vi":"chơi bóng rổ"},{"en":"basketball court","vi":"sân bóng rổ"},{"en":"basketball team","vi":"đội bóng rổ"},{"en":"basketball hoop","vi":"rổ bóng rổ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"\"play basketball\" không dùng mạo từ; chỉ một quả bóng dùng \"a basketball\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_player', 'en-a1-14', 'player', '/ˈpleɪər/', 'A1', 'người chơi; cầu thủ; vận động viên; người chơi nhạc cụ; thiết bị phát (nhạc, video); phần mềm phát đa phương tiện', 'n.', 'play (v.), playful (adj.), playable (adj.)', NULL, 'Người chơi nhạc cụ có thể dùng cấu trúc "tên nhạc cụ + player", ví dụ như piano player.', 'Each player shook hands before the football match began.', NULL, 'Mỗi cầu thủ bắt tay nhau trước khi trận bóng đá bắt đầu.', '{"wordId":"player","ukIpa":"/ˈpleɪə/","usIpa":"/ˈpleɪər/","cefr":"A1","topic":"sport","senses":[{"pos":"n.","en":"someone who takes part in a sport or game","vi":"người chơi; cầu thủ; vận động viên"},{"pos":"n.","en":"someone who plays a musical instrument","vi":"người chơi nhạc cụ"},{"pos":"n.","en":"a device or program that plays recorded sound or video","vi":"thiết bị phát (nhạc, video); phần mềm phát đa phương tiện"}],"examples":[{"en":"Each player shook hands before the football match began.","vi":"Mỗi cầu thủ bắt tay nhau trước khi trận bóng đá bắt đầu.","audioKind":"ex"},{"en":"Young players benefit from coaches who value teamwork and personal development rather than winning alone.","vi":"Các cầu thủ trẻ sẽ được hưởng lợi từ những huấn luyện viên coi trọng tinh thần đồng đội và sự phát triển cá nhân hơn là việc chỉ chăm chăm chiến thắng.","audioKind":"ex2"}],"collocations":[{"en":"football player","vi":"cầu thủ bóng đá"},{"en":"team player","vi":"người có tinh thần đồng đội"},{"en":"piano player","vi":"người chơi đàn piano"},{"en":"media player","vi":"trình phát đa phương tiện"}],"wordFamily":["play (v.)","playful (adj.)","playable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Người chơi nhạc cụ có thể dùng cấu trúc \"tên nhạc cụ + player\", ví dụ như piano player.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sport', 'en-a1-14', 'sport', '/spɔːrt/', 'A1', 'thể thao; môn thể thao; trưng diện; chưng diện', 'n.', 'sporting (adj.), sporty (adj.)', NULL, 'Khi chỉ thể thao nói chung, tiếng Anh Anh thường dùng sport, trong khi tiếng Anh Mỹ thường dùng sports.', 'Swimming is the only sport my sister really enjoys.', NULL, 'Bơi lội là môn thể thao duy nhất mà chị gái tôi thực sự thích.', '{"wordId":"sport","ukIpa":"/spɔːt/","usIpa":"/spɔːrt/","cefr":"A1","topic":"sport","senses":[{"pos":"n.","en":"Physical activities involving skill, effort, and often competition","vi":"thể thao; môn thể thao"},{"pos":"v.","en":"To wear or display something in a noticeable way","vi":"trưng diện; chưng diện"}],"examples":[{"en":"Swimming is the only sport my sister really enjoys.","vi":"Bơi lội là môn thể thao duy nhất mà chị gái tôi thực sự thích.","audioKind":"ex"},{"en":"Regular participation in sport can improve physical health and help young people develop teamwork skills.","vi":"Việc thường xuyên tham gia thể thao có thể cải thiện sức khỏe thể chất và giúp giới trẻ phát triển kỹ năng làm việc nhóm.","audioKind":"ex2"}],"collocations":[{"en":"take part in sport","vi":"tham gia thể thao"},{"en":"competitive sport","vi":"thể thao thành tích cao; thể thao cạnh tranh"},{"en":"team sport","vi":"môn thể thao đồng đội"},{"en":"sporting event","vi":"sự kiện thể thao"}],"wordFamily":["sporting (adj.)","sporty (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ thể thao nói chung, tiếng Anh Anh thường dùng sport, trong khi tiếng Anh Mỹ thường dùng sports.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ball', 'en-a1-14', 'ball', '/bɔːl/', 'A1', 'quả bóng; vật hình cầu; vũ hội', 'n.', NULL, NULL, 'Trước các tên môn thể thao có dùng bóng thường không có mạo từ, ví dụ như play football.', 'The dog chased the ball across the grass.', NULL, 'Con chó đuổi theo quả bóng chạy qua bãi cỏ.', '{"wordId":"ball","ukIpa":"/bɔːl/","usIpa":"/bɔːl/","cefr":"A1","topic":"sport","senses":[{"pos":"n.","en":"A round object used in games or shaped like one.","vi":"quả bóng; vật hình cầu"},{"pos":"n.","en":"A formal social event where people dance.","vi":"vũ hội"}],"examples":[{"en":"The dog chased the ball across the grass.","vi":"Con chó đuổi theo quả bóng chạy qua bãi cỏ.","audioKind":"ex"},{"en":"Simple ball games can help children develop coordination while encouraging cooperation and regular physical activity.","vi":"Các trò chơi bóng đơn giản có thể giúp trẻ phát triển khả năng phối hợp đồng thời khuyến khích sự hợp tác và vận động thể chất thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"throw a ball","vi":"ném bóng"},{"en":"catch a ball","vi":"bắt bóng"},{"en":"a ball of wool","vi":"một cuộn len"},{"en":"a charity ball","vi":"một buổi vũ hội từ thiện"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trước các tên môn thể thao có dùng bóng thường không có mạo từ, ví dụ như play football.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tennis', 'en-a1-14', 'tennis', '/ˈtenɪs/', 'A1', 'môn quần vợt; môn tennis', 'n.', NULL, NULL, 'Dùng play tennis mà không cần mạo từ; vợt tennis gọi là racket.', 'We play tennis at the park on Sundays.', NULL, 'Chúng tôi chơi quần vợt ở công viên vào các ngày Chủ nhật.', '{"wordId":"tennis","ukIpa":"/ˈtenɪs/","usIpa":"/ˈtenɪs/","cefr":"A1","topic":"sport","senses":[{"pos":"n.","en":"a sport involving hitting a ball over a net with rackets","vi":"môn quần vợt; môn tennis"}],"examples":[{"en":"We play tennis at the park on Sundays.","vi":"Chúng tôi chơi quần vợt ở công viên vào các ngày Chủ nhật.","audioKind":"ex"},{"en":"Providing affordable tennis lessons can encourage young people to exercise regularly and develop greater physical coordination.","vi":"Cung cấp các lớp học quần vợt với chi phí hợp lý có thể khuyến khích giới trẻ tập thể dục thường xuyên và phát triển sự phối hợp thể chất tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"play tennis","vi":"chơi quần vợt"},{"en":"tennis court","vi":"sân quần vợt"},{"en":"tennis racket","vi":"vợt quần vợt"},{"en":"tennis match","vi":"trận đấu quần vợt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dùng play tennis mà không cần mạo từ; vợt tennis gọi là racket.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_swim', 'en-a1-14', 'swim', '/swɪm/', 'A1', 'bơi lội; cuộc bơi lội', 'v.', 'swimmer (n.), swimming (n.)', NULL, 'Biến đổi bất quy tắc: swim — swam — swum.', 'We swim in the indoor pool every Saturday morning.', NULL, 'Chúng tôi bơi ở hồ bơi trong nhà vào sáng thứ Bảy hàng tuần.', '{"wordId":"swim","ukIpa":"/swɪm/","usIpa":"/swɪm/","cefr":"A1","topic":"sport","senses":[{"pos":"v.","en":"To move through water using your body.","vi":"bơi lội"},{"pos":"n.","en":"An occasion when you move through water for exercise or pleasure.","vi":"cuộc bơi lội"}],"examples":[{"en":"We swim in the indoor pool every Saturday morning.","vi":"Chúng tôi bơi ở hồ bơi trong nhà vào sáng thứ Bảy hàng tuần.","audioKind":"ex"},{"en":"Schools should teach children to swim because this essential skill improves both physical fitness and water safety.","vi":"Nhà trường nên dạy trẻ em bơi lội vì kỹ năng thiết yếu này vừa giúp tăng cường thể lực vừa nâng cao sự an toàn dưới nước.","audioKind":"ex2"}],"collocations":[{"en":"go for a swim","vi":"đi bơi"},{"en":"learn to swim","vi":"học bơi"},{"en":"swim across","vi":"bơi qua"}],"wordFamily":["swimmer (n.)","swimming (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Biến đổi bất quy tắc: swim — swam — swum.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_swimming', 'en-a1-14', 'swimming', '/ˈswɪmɪŋ/', 'A1', 'môn bơi lội; việc bơi', 'n.', 'swim (v.), swimmer (n.)', NULL, 'Khi nói về bộ môn thể thao này thì không đếm được; đi bơi dùng cụm go swimming.', 'We go swimming at the indoor pool every Saturday.', NULL, 'Chúng tôi đi bơi ở hồ bơi trong nhà vào mỗi thứ Bảy.', '{"wordId":"swimming","ukIpa":"/ˈswɪmɪŋ/","usIpa":"/ˈswɪmɪŋ/","cefr":"A1","topic":"sport","senses":[{"pos":"n.","en":"The activity of moving through water using your body.","vi":"môn bơi lội; việc bơi"}],"examples":[{"en":"We go swimming at the indoor pool every Saturday.","vi":"Chúng tôi đi bơi ở hồ bơi trong nhà vào mỗi thứ Bảy.","audioKind":"ex"},{"en":"Regular swimming can improve physical fitness while placing relatively little stress on the joints.","vi":"Bơi lội thường xuyên có thể nâng cao thể lực đồng thời ít gây áp lực lên các khớp xương.","audioKind":"ex2"}],"collocations":[{"en":"go swimming","vi":"đi bơi"},{"en":"swimming pool","vi":"hồ bơi"},{"en":"swimming lessons","vi":"lớp học bơi"}],"wordFamily":["swim (v.)","swimmer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi nói về bộ môn thể thao này thì không đếm được; đi bơi dùng cụm go swimming.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_win', 'en-a1-14', 'win', '/wɪn/', 'A1', 'thắng; giành chiến thắng; giành được; thu hút được; chiến thắng', 'v.', 'winner (n.), winning (adj.)', 'Đồng nghĩa: triumph · Trái nghĩa: lose', 'Dạng quá khứ và quá khứ phân từ đều là won; dùng win cho trận đấu và beat cho đối thủ.', 'Our team won the match despite the heavy rain.', NULL, 'Đội của chúng tôi đã thắng trận đấu bất chấp trời mưa lớn.', '{"wordId":"win","ukIpa":"/wɪn/","usIpa":"/wɪn/","cefr":"A1","topic":"sport","senses":[{"pos":"v.","en":"To succeed in a competition or receive a prize.","vi":"thắng; giành chiến thắng"},{"pos":"v.","en":"To gain something through effort or personal qualities.","vi":"giành được; thu hút được"},{"pos":"n.","en":"A successful result in a competition or contest.","vi":"chiến thắng"}],"examples":[{"en":"Our team won the match despite the heavy rain.","vi":"Đội của chúng tôi đã thắng trận đấu bất chấp trời mưa lớn.","audioKind":"ex"},{"en":"To win public support, governments must explain how environmental policies will benefit communities in the long term.","vi":"Để giành được sự ủng hộ của công chúng, chính phủ phải giải thích cách các chính sách môi trường mang lại lợi ích lâu dài cho cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"win a prize","vi":"giải thưởng"},{"en":"win a match","vi":"thắng một trận đấu"},{"en":"win support","vi":"giành sự ủng hộ"},{"en":"win someone''s trust","vi":"chiếm được lòng tin của ai đó"}],"wordFamily":["winner (n.)","winning (adj.)"],"synonyms":["triumph"],"antonyms":["lose"],"tipVi":"Dạng quá khứ và quá khứ phân từ đều là won; dùng win cho trận đấu và beat cho đối thủ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_climb', 'en-a1-14', 'climb', '/klaɪm/', 'A1', 'leo; trèo; tăng lên; leo thang; sự leo; sự trèo; sự tăng', 'v.', 'climber (n.), climbing (n.)', 'Đồng nghĩa: ascend · Trái nghĩa: descend', 'Chữ cái b cuối từ không phát âm; cụm từ climb a mountain không dùng giới từ đi kèm.', 'We climbed the hill before stopping for a picnic.', NULL, 'Chúng tôi leo lên đồi trước khi dừng lại để cắm trại.', '{"wordId":"climb","ukIpa":"/klaɪm/","usIpa":"/klaɪm/","cefr":"A1","topic":"sport","senses":[{"pos":"v.","en":"to move upwards using your feet and often your hands","vi":"leo; trèo"},{"pos":"v.","en":"to increase in amount or level","vi":"tăng lên; leo thang"},{"pos":"n.","en":"an act of moving upwards or an increase in level","vi":"sự leo; sự trèo; sự tăng"}],"examples":[{"en":"We climbed the hill before stopping for a picnic.","vi":"Chúng tôi leo lên đồi trước khi dừng lại để cắm trại.","audioKind":"ex"},{"en":"As housing costs continue to climb, many young adults struggle to live independently in major cities.","vi":"Khi chi phí nhà ở tiếp tục tăng cao, nhiều người trẻ tuổi phải vật lộn để có thể tự lập ở các thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"climb a mountain","vi":"leo núi"},{"en":"climb stairs","vi":"leo cầu thang"},{"en":"a steep climb","vi":"đoạn đường leo dốc"},{"en":"climb steadily","vi":"tăng đều đặn"}],"wordFamily":["climber (n.)","climbing (n.)"],"synonyms":["ascend"],"antonyms":["descend"],"tipVi":"Chữ cái b cuối từ không phát âm; cụm từ climb a mountain không dùng giới từ đi kèm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_game', 'en-a1-14', 'game', '/ɡeɪm/', 'A1', 'trò chơi; cuộc thi đấu; thú săn; thịt thú săn; sẵn sàng thử; có tinh thần', 'n.', 'gaming (n.), gamer (n.)', NULL, 'Nghĩa thú săn là danh từ không đếm được; cụm từ be game for diễn tả sự sẵn sàng thử thách.', 'We played a board game after dinner yesterday.', NULL, 'Chúng tôi đã chơi một trò chơi cờ bàn sau bữa tối ngày hôm qua.', '{"wordId":"game","ukIpa":"/ɡeɪm/","usIpa":"/ɡeɪm/","cefr":"A1","topic":"sport","senses":[{"pos":"n.","en":"an activity or contest played according to rules","vi":"trò chơi; cuộc thi đấu"},{"pos":"n.","en":"wild animals hunted for food or sport, or their meat","vi":"thú săn; thịt thú săn"},{"pos":"adj.","en":"willing to try something difficult or unfamiliar","vi":"sẵn sàng thử; có tinh thần"}],"examples":[{"en":"We played a board game after dinner yesterday.","vi":"Chúng tôi đã chơi một trò chơi cờ bàn sau bữa tối ngày hôm qua.","audioKind":"ex"},{"en":"Cooperative games can help children develop communication skills and learn to solve problems together.","vi":"Các trò chơi đồng đội có thể giúp trẻ em phát triển kỹ năng giao tiếp và học cách cùng nhau giải quyết vấn đề.","audioKind":"ex2"}],"collocations":[{"en":"board game","vi":"cờ bàn"},{"en":"team game","vi":"trò chơi đồng đội"},{"en":"video game","vi":"trò chơi điện tử"},{"en":"be game for","vi":"sẵn sàng thử"}],"wordFamily":["gaming (n.)","gamer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa thú săn là danh từ không đếm được; cụm từ be game for diễn tả sự sẵn sàng thử thách.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_match', 'en-a1-14', 'match', '/mætʃ/', 'A1', 'trận đấu; cuộc thi đấu thể thao; phù hợp; ăn khớp; sánh kịp; cây diêm', 'n.', 'matching (adj.), unmatched (adj.)', NULL, 'match nhấn mạnh sự hài hòa, tương hợp; fit thường chỉ sự vừa vặn về kích cỡ.', 'We watched a football match at the local park.', NULL, 'Chúng tôi đã xem một trận đấu bóng đá tại công viên địa phương.', '{"wordId":"match","ukIpa":"/mætʃ/","usIpa":"/mætʃ/","cefr":"A1","topic":"sport","senses":[{"pos":"n.","en":"a sports contest between two people or teams","vi":"trận đấu; cuộc thi đấu thể thao"},{"pos":"v.","en":"to go well together, correspond, or equal something","vi":"phù hợp; ăn khớp; sánh kịp"},{"pos":"n.","en":"a small stick that produces fire when rubbed","vi":"cây diêm"}],"examples":[{"en":"We watched a football match at the local park.","vi":"Chúng tôi đã xem một trận đấu bóng đá tại công viên địa phương.","audioKind":"ex"},{"en":"Training programmes should match the skills taught in colleges with the needs of local employers.","vi":"Các chương trình đào tạo cần gắn kết các kỹ năng được giảng dạy tại trường cao đẳng với nhu cầu của các nhà tuyển dụng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"win a match","vi":"thắng trận đấu"},{"en":"match A with B","vi":"ghép đôi A với B"},{"en":"strike a match","vi":"quẹt diêm"},{"en":"a perfect match","vi":"một cặp trời sinh"}],"wordFamily":["matching (adj.)","unmatched (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"match nhấn mạnh sự hài hòa, tương hợp; fit thường chỉ sự vừa vặn về kích cỡ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_14_1', 'en-a1-14', 'Cách dùng “area” (n.) — vùng; khu vực; địa bàn', 'a residential area  ·  surface area  ·  an area of research', 'Khi chỉ kích thước bề mặt thường dùng kèm các đơn vị như mét vuông; ngoài ra từ này cũng dùng để chỉ lĩnh vực học tập hoặc nghiên cứu.', NULL, '[{"hanzi":"There is a quiet picnic area beside the lake.","pinyin":"","meaning":"Có một khu vực dã ngoại yên tĩnh nằm bên cạnh hồ nước."},{"hanzi":"Investment in public transport can improve access to employment for people living in rural areas.","pinyin":"","meaning":"Việc đầu tư vào giao thông công cộng có thể giúp những người sống ở vùng nông thôn dễ dàng tiếp cận cơ hội việc làm hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_14_2', 'en-a1-14', 'Cách dùng “village” (n.) — n. làng; làng mạc; thôn', 'a remote village  ·  a fishing village  ·  village life', 'Cụm từ the whole village có thể chỉ toàn thể người dân trong làng chứ không phải các công trình xây dựng.', 'Họ từ (Word Family): villager (n.)', '[{"hanzi":"Our village has a bakery beside the old bridge.","pinyin":"","meaning":"Làng chúng tôi có một tiệm bánh nằm cạnh cây cầu cổ."},{"hanzi":"Reliable public transport can help village residents access employment, education, and healthcare in nearby towns.","pinyin":"","meaning":"Giao thông công cộng đáng tin cậy có thể giúp dân làng tiếp cận việc làm, giáo dục và y tế ở các thị trấn gần đó."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_14_3', 'en-a1-14', 'Cách dùng “sport” (n.) — thể thao; môn thể thao', 'take part in sport  ·  competitive sport  ·  team sport', 'Khi chỉ thể thao nói chung, tiếng Anh Anh thường dùng sport, trong khi tiếng Anh Mỹ thường dùng sports.', 'Họ từ (Word Family): sporting (adj.), sporty (adj.)', '[{"hanzi":"Swimming is the only sport my sister really enjoys.","pinyin":"","meaning":"Bơi lội là môn thể thao duy nhất mà chị gái tôi thực sự thích."},{"hanzi":"Regular participation in sport can improve physical health and help young people develop teamwork skills.","pinyin":"","meaning":"Việc thường xuyên tham gia thể thao có thể cải thiện sức khỏe thể chất và giúp giới trẻ phát triển kỹ năng làm việc nhóm."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_14_4', 'en-a1-14', 'Cách dùng “town” (n.) — thị trấn; thị xã', 'small town  ·  town centre  ·  coastal town', 'go into town có nghĩa là đi vào trung tâm thành phố, trong trường hợp này town không đi kèm mạo từ.', NULL, '[{"hanzi":"Our town has a bakery beside the old bridge.","pinyin":"","meaning":"Thị trấn của chúng tôi có một tiệm bánh nằm cạnh cây cầu cổ."},{"hanzi":"Improving public transport in a small town can help residents access jobs and essential services.","pinyin":"","meaning":"Việc cải thiện giao thông công cộng ở một thị trấn nhỏ có thể giúp cư dân tiếp cận việc làm và các dịch vụ thiết yếu."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_14_1', 'en-a1-14', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_14_1_1', 'ten_14_1', 'town', 'Our town has a bakery beside the old bridge.', 'Our town has a bakery beside the old bridge.', '/taʊn/', 'Thị trấn của chúng tôi có một tiệm bánh nằm cạnh cây cầu cổ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_14_1_2', 'ten_14_1', 'London', 'We spent a rainy afternoon exploring London by bus.', 'We spent a rainy afternoon exploring London by bus.', '/ˈlʌndən/', 'Chúng tôi đã dành một buổi chiều mưa để khám phá Luân Đôn bằng xe buýt.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
