INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_14_1_1', 'en-a1-14', 'ten_14_1', 'listening', 'listening', 'Our town has a bakery beside the old bridge.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã dành cả buổi chiều đi bộ khám phá thành phố.","Chúng tôi đã dành một buổi chiều mưa để khám phá Luân Đôn bằng xe buýt.","Làng chúng tôi có một tiệm bánh nằm cạnh cây cầu cổ.","Thị trấn của chúng tôi có một tiệm bánh nằm cạnh cây cầu cổ."]'::jsonb, 3, 'Our town has a bakery beside the old bridge. → Thị trấn của chúng tôi có một tiệm bánh nằm cạnh cây cầu cổ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
