INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_14_2', 'en-a1-14', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_14_2_1', 'ten_14_2', 'town', 'Improving public transport in a small town can help residents access jobs and essential services.', 'Improving public transport in a small town can help residents access jobs and essential services.', '/taʊn/', 'Việc cải thiện giao thông công cộng ở một thị trấn nhỏ có thể giúp cư dân tiếp cận việc làm và các dịch vụ thiết yếu.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_14_2_2', 'ten_14_2', 'London', 'London attracts international students because its universities offer diverse courses and access to extensive cultural resources.', 'London attracts international students because its universities offer diverse courses and access to extensive cultural resources.', '/ˈlʌndən/', 'Luân Đôn thu hút sinh viên quốc tế vì các trường đại học ở đây cung cấp nhiều khóa học đa dạng và nguồn tài nguyên văn hóa phong phú.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_14_2_3', 'ten_14_2', 'centre', 'A new community centre could provide affordable exercise facilities and meeting spaces for local residents.', 'A new community centre could provide affordable exercise facilities and meeting spaces for local residents.', '/ˈsentər/', 'Một trung tâm cộng đồng mới có thể cung cấp các cơ sở tập thể dục vừa túi tiền và không gian hội họp cho người dân địa phương.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_14_2_4', 'ten_14_2', 'city', 'A well-designed city provides accessible public transport and green spaces that improve residents'' quality of life.', 'A well-designed city provides accessible public transport and green spaces that improve residents'' quality of life.', '/ˈsɪti/', 'Một thành phố được quy hoạch tốt sẽ cung cấp hệ thống giao thông công cộng thuận tiện và các mảng xanh giúp nâng cao chất lượng cuộc sống của cư dân.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_14_2_5', 'ten_14_2', 'village', 'Reliable public transport can help village residents access employment, education, and healthcare in nearby towns.', 'Reliable public transport can help village residents access employment, education, and healthcare in nearby towns.', '/ˈvɪlɪdʒ/', 'Giao thông công cộng đáng tin cậy có thể giúp dân làng tiếp cận việc làm, giáo dục và y tế ở các thị trấn gần đó.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_14_2_6', 'ten_14_2', 'house', 'Local authorities could convert unused office buildings into apartments to house families in need of affordable accommodation.', 'Local authorities could convert unused office buildings into apartments to house families in need of affordable accommodation.', '/haʊs/', 'Chính quyền địa phương có thể chuyển đổi các tòa nhà văn phòng bỏ trống thành căn hộ để cung cấp chỗ ở cho các gia đình cần nhà ở giá rẻ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_14_2_1', 'en-a1-14', 'ten_14_2', 'listening', 'listening', 'Improving public transport in a small town can help residents access jobs and essential services.', NULL, 'Trong câu vừa nghe, từ “town” mang nghĩa nào sau đây?', '["thể thao; môn thể thao","thị trấn; thị xã","đủ","sông; dòng sông"]'::jsonb, 1, '“town” (/taʊn/): thị trấn; thị xã. Câu đầy đủ: Improving public transport in a small town can help residents access jobs and essential services.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_14_2_2', 'en-a1-14', 'ten_14_2', 'listening', 'listening', 'London attracts international students because its universities offer diverse courses and access to extensive cultural resources.', NULL, 'Trong câu vừa nghe, từ “London” mang nghĩa nào sau đây?', '["chú; bác; cậu; dượng","bé gái; con gái; thiếu nữ","con lợn; con heo","thủ đô của Vương quốc Anh"]'::jsonb, 3, '“London” (/ˈlʌndən/): thủ đô của Vương quốc Anh. Câu đầy đủ: London attracts international students because its universities offer diverse courses and access to extensive cultural resources.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
