INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_14_2', 'en-a1-14', NULL, 'comprehensive_test', 'listening', 'We spent a rainy afternoon exploring London by bus.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Con chó đuổi theo quả bóng chạy qua bãi cỏ.","Mỗi cầu thủ bắt tay nhau trước khi trận bóng đá bắt đầu.","Chúng tôi đã dành một buổi chiều mưa để khám phá Luân Đôn bằng xe buýt.","Đội của chúng tôi đã thắng trận đấu bất chấp trời mưa lớn."]'::jsonb, 2, 'We spent a rainy afternoon exploring London by bus. → Chúng tôi đã dành một buổi chiều mưa để khám phá Luân Đôn bằng xe buýt.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_14_3', 'en-a1-14', NULL, 'comprehensive_test', 'listening', 'centre', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đường; đường ăn","trung tâm; điểm chính giữa","giữ lại; bảo quản","bữa ăn; bữa cơm"]'::jsonb, 1, 'centre (/ˈsentər/) → trung tâm; điểm chính giữa; trung tâm (nơi cung cấp dịch vụ, hoạt động cụ thể); tập trung vào; lấy làm trung tâm', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_14_4', 'en-a1-14', NULL, 'comprehensive_test', 'listening', 'We explored the city on foot all afternoon.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã dành cả buổi chiều đi bộ khám phá thành phố.","Chúng tôi thuê một căn hộ nhỏ ở tầng trên của một tiệm bánh đông khách.","Chúng tôi chơi quần vợt ở công viên vào các ngày Chủ nhật.","Chúng tôi bơi ở hồ bơi trong nhà vào sáng thứ Bảy hàng tuần."]'::jsonb, 0, 'We explored the city on foot all afternoon. → Chúng tôi đã dành cả buổi chiều đi bộ khám phá thành phố.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_14_5', 'en-a1-14', NULL, 'comprehensive_test', 'listening', 'village', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bao gồm; gồm có","n. làng; làng mạc; thôn","mùa hè; mùa hạ","chỉ; trưng bày; cho xem"]'::jsonb, 1, 'village (/ˈvɪlɪdʒ/) → n. làng; làng mạc; thôn; n. dân làng; toàn thể người dân trong làng', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_14_6', 'en-a1-14', NULL, 'comprehensive_test', 'listening', 'Their house has a small garden behind the kitchen.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Có một khu vực dã ngoại yên tĩnh nằm bên cạnh hồ nước.","Chúng tôi đã dành một buổi chiều mưa để khám phá Luân Đôn bằng xe buýt.","Chúng tôi đã chơi một trò chơi cờ bàn sau bữa tối ngày hôm qua.","Ngôi nhà của họ có một khu vườn nhỏ phía sau nhà bếp."]'::jsonb, 3, 'Their house has a small garden behind the kitchen. → Ngôi nhà của họ có một khu vườn nhỏ phía sau nhà bếp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
