INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_14_8', 'en-a1-14', NULL, 'comprehensive_test', 'listening', 'We built a small wooden shelter in the garden.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã xem một trận đấu bóng đá tại công viên địa phương.","Có một khu vực dã ngoại yên tĩnh nằm bên cạnh hồ nước.","Chúng tôi đã dựng một cái lán gỗ nhỏ trong vườn.","Chúng tôi đã cùng nhau ăn buổi dã ngoại dưới những tán cây trong công viên."]'::jsonb, 2, 'We built a small wooden shelter in the garden. → Chúng tôi đã dựng một cái lán gỗ nhỏ trong vườn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
