INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_14_18', 'en-a1-14', NULL, 'comprehensive_test', 'reading', NULL, 'Improving public transport in a small town can help residents access jobs and essential services.', 'Dựa vào câu trên, từ “town” có nghĩa phù hợp nhất là gì?', '["bơi lội","phần giữa; điểm giữa; trung tâm","phụ nữ; người phụ nữ","thị trấn; thị xã"]'::jsonb, 3, 'town: thị trấn; thị xã; thị trấn; khu trung tâm thương mại. Dịch cả câu: Việc cải thiện giao thông công cộng ở một thị trấn nhỏ có thể giúp cư dân tiếp cận việc làm và các dịch vụ thiết yếu.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_14_19', 'en-a1-14', NULL, 'comprehensive_test', 'reading', NULL, 'London attracts international students because its universities offer diverse courses and access to extensive cultural resources.', 'Dựa vào câu trên, từ “London” có nghĩa phù hợp nhất là gì?', '["gặp gỡ; hội họp; làm quen","già; lớn tuổi; cũ; lâu đời","thủ đô của Vương quốc Anh","tin; tin là thật"]'::jsonb, 2, 'London: thủ đô của Vương quốc Anh. Dịch cả câu: Luân Đôn thu hút sinh viên quốc tế vì các trường đại học ở đây cung cấp nhiều khóa học đa dạng và nguồn tài nguyên văn hóa phong phú.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_14_20', 'en-a1-14', NULL, 'comprehensive_test', 'reading', NULL, 'A new community centre could provide affordable exercise facilities and meeting spaces for local residents.', 'Dựa vào câu trên, từ “centre” có nghĩa phù hợp nhất là gì?', '["cười; mỉm cười","ở ngoài; ra ngoài; vắng nhà","già; lớn tuổi; cũ; lâu đời","trung tâm; điểm chính giữa"]'::jsonb, 3, 'centre: trung tâm; điểm chính giữa; trung tâm (nơi cung cấp dịch vụ, hoạt động cụ thể); tập trung vào; lấy làm trung tâm. Dịch cả câu: Một trung tâm cộng đồng mới có thể cung cấp các cơ sở tập thể dục vừa túi tiền và không gian hội họp cho người dân địa phương.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_14_21', 'en-a1-14', NULL, 'comprehensive_test', 'reading', NULL, 'A well-designed city provides accessible public transport and green spaces that improve residents'' quality of life.', 'Dựa vào câu trên, từ “city” có nghĩa phù hợp nhất là gì?', '["thêm vào; bổ sung","cứng; rắn","thành phố; đô thị","khoa học; nghiên cứu thế giới tự nhiên"]'::jsonb, 2, 'city: thành phố; đô thị. Dịch cả câu: Một thành phố được quy hoạch tốt sẽ cung cấp hệ thống giao thông công cộng thuận tiện và các mảng xanh giúp nâng cao chất lượng cuộc sống của cư dân.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_14_22', 'en-a1-14', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “leo; trèo”', '["climb","Canada","pizza","Tuesday"]'::jsonb, 0, 'leo; trèo → climb (/klaɪm/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_14_23', 'en-a1-14', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “trò chơi; cuộc thi đấu”', '["game","into","Germany","agree"]'::jsonb, 0, 'trò chơi; cuộc thi đấu → game (/ɡeɪm/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_14_24', 'en-a1-14', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “trận đấu; cuộc thi đấu thể thao”', '["carry","match","job","food"]'::jsonb, 1, 'trận đấu; cuộc thi đấu thể thao → match (/mætʃ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-15', 'en', 'Bài 15: Công nghệ, Khoa học & Thế giới - CEFR A1', 'CEFR A1', 'A1 · Công nghệ & Khoa học', '23 từ vựng Tiếng Anh CEFR A1 chủ đề công nghệ, khoa học & thế giới kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1015, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_camera', 'en-a1-15', 'camera', '/ˈkæmərə/', 'A1', 'máy ảnh; máy quay phim; camera', 'n.', 'cameraman (n.), camerawoman (n.)', NULL, 'camera có thể chỉ máy ảnh hoặc máy quay phim, tùy thuộc vào ngữ cảnh.', 'She raised her camera to photograph the sleeping cat.', NULL, 'Cô ấy giơ máy ảnh lên để chụp con mèo đang ngủ.', '{"wordId":"camera","ukIpa":"/ˈkæmərə/","usIpa":"/ˈkæmərə/","cefr":"A1","topic":"technology","senses":[{"pos":"n.","en":"A device used to take photographs or record moving images.","vi":"máy ảnh; máy quay phim; camera"}],"examples":[{"en":"She raised her camera to photograph the sleeping cat.","vi":"Cô ấy giơ máy ảnh lên để chụp con mèo đang ngủ.","audioKind":"ex"},{"en":"Installing a camera at each entrance may improve security, but residents have raised concerns about privacy.","vi":"Việc lắp đặt camera ở mỗi lối ra vào có thể nâng cao an ninh, nhưng cư dân đã bày tỏ lo ngại về vấn đề quyền riêng tư.","audioKind":"ex2"}],"collocations":[{"en":"a digital camera","vi":"máy ảnh kỹ thuật số"},{"en":"a security camera","vi":"camera an ninh"},{"en":"a camera lens","vi":"ống kính máy ảnh"},{"en":"on camera","vi":"trước ống kính"}],"wordFamily":["cameraman (n.)","camerawoman (n.)"],"synonyms":[],"antonyms":[],"tipVi":"camera có thể chỉ máy ảnh hoặc máy quay phim, tùy thuộc vào ngữ cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_website', 'en-a1-15', 'website', '/ˈwebsaɪt/', 'A1', 'trang web; trang mạng', 'n.', 'web (n.)', 'Đồng nghĩa: site', 'Dùng giới từ on khi nói on a website; từ webpage chỉ dùng cho một trang web đơn lẻ.', 'I found the museum''s opening hours on its website.', NULL, 'Tôi đã tìm thấy giờ mở cửa của viện bảo hiểm trên trang web của họ.', '{"wordId":"website","ukIpa":"/ˈwebsaɪt/","usIpa":"/ˈwebsaɪt/","cefr":"A1","topic":"technology","senses":[{"pos":"n.","en":"A collection of connected web pages available on the internet","vi":"trang web; trang mạng"}],"examples":[{"en":"I found the museum''s opening hours on its website.","vi":"Tôi đã tìm thấy giờ mở cửa của viện bảo hiểm trên trang web của họ.","audioKind":"ex"},{"en":"A well-designed government website can make public services more accessible to people in remote areas.","vi":"Một trang web chính phủ được thiết kế tốt có thể giúp người dân ở các vùng sâu vùng xa tiếp cận các dịch vụ công dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"visit a website","vi":"ghé thăm một trang web"},{"en":"official website","vi":"trang web chính thức"},{"en":"website design","vi":"thiết kế trang web"},{"en":"launch a website","vi":"ra mắt trang web"}],"wordFamily":["web (n.)"],"synonyms":["site"],"antonyms":[],"tipVi":"Dùng giới từ on khi nói on a website; từ webpage chỉ dùng cho một trang web đơn lẻ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_telephone', 'en-a1-15', 'telephone', '/ˈteləfoʊn/', 'A1', 'n. điện thoại; máy điện thoại; v. gọi điện thoại; gọi điện cho ai', 'n.', NULL, 'Đồng nghĩa: phone', 'telephone không phải từ chỉ dùng riêng ở Mỹ; hàng ngày thường gọi tắt là phone.', 'The telephone rang just as I opened the door.', NULL, 'Điện thoại vừa reo thì tôi mở cửa.', '{"wordId":"telephone","ukIpa":"/ˈtelɪfəʊn/","usIpa":"/ˈteləfoʊn/","cefr":"A1","topic":"technology","senses":[{"pos":"n.","en":"A device or system for speaking to people far away.","vi":"n. điện thoại; máy điện thoại"},{"pos":"v.","en":"To contact someone or speak to them using a phone.","vi":"v. gọi điện thoại; gọi điện cho ai"}],"examples":[{"en":"The telephone rang just as I opened the door.","vi":"Điện thoại vừa reo thì tôi mở cửa.","audioKind":"ex"},{"en":"Telephone consultations can improve access to healthcare for rural residents who live far from medical centres.","vi":"Tư vấn qua điện thoại có thể cải thiện khả năng tiếp cận dịch vụ chăm sóc sức khỏe cho cư dân nông thôn sống xa các trung tâm y tế.","audioKind":"ex2"}],"collocations":[{"en":"telephone call","vi":"cuộc gọi điện thoại"},{"en":"telephone number","vi":"số điện thoại"},{"en":"by telephone","vi":"qua điện thoại"},{"en":"answer the telephone","vi":"nghe điện thoại"}],"wordFamily":[],"synonyms":["phone"],"antonyms":[],"tipVi":"telephone không phải từ chỉ dùng riêng ở Mỹ; hàng ngày thường gọi tắt là phone.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_internet', 'en-a1-15', 'internet', '/ˈɪntərnet/', 'A1', 'mạng internet; mạng toàn cầu', 'n.', NULL, 'Đồng nghĩa: the net', 'Thường dùng là "the internet"; khi làm định từ (tính từ bổ nghĩa) thì không cần "the".', 'The internet stopped working halfway through our video call.', NULL, 'Mạng internet bị ngắt giữa chừng cuộc gọi video của chúng tôi.', '{"wordId":"internet","ukIpa":"/ˈɪntənet/","usIpa":"/ˈɪntərnet/","cefr":"A1","topic":"technology","senses":[{"pos":"n.","en":"The worldwide network connecting computers and other devices.","vi":"mạng internet; mạng toàn cầu"}],"examples":[{"en":"The internet stopped working halfway through our video call.","vi":"Mạng internet bị ngắt giữa chừng cuộc gọi video của chúng tôi.","audioKind":"ex"},{"en":"Reliable internet access enables rural students to use educational resources that may be unavailable locally.","vi":"Việc truy cập internet ổn định giúp học sinh vùng sâu vùng xa tiếp cận các nguồn tài nguyên giáo dục có thể không có sẵn tại địa phương.","audioKind":"ex2"}],"collocations":[{"en":"internet access","vi":"khả năng truy cập internet"},{"en":"an internet connection","vi":"kết nối internet"},{"en":"on the internet","vi":"trên internet"},{"en":"internet users","vi":"người dùng internet"}],"wordFamily":[],"synonyms":["the net"],"antonyms":[],"tipVi":"Thường dùng là \"the internet\"; khi làm định từ (tính từ bổ nghĩa) thì không cần \"the\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_message', 'en-a1-15', 'message', '/ˈmesɪdʒ/', 'A1', 'tin nhắn; lời nhắn; th thông điệp; ý nghĩa chính; gửi tin nhắn', 'n.', 'messaging (n.), messenger (n.)', NULL, 'message là danh từ đếm được; trong khi information thường là danh từ không đếm được.', 'Please leave a message if I miss your call.', NULL, 'Xin hãy để lại lời nhắn nếu tôi lỡ cuộc gọi của bạn.', '{"wordId":"message","ukIpa":"/ˈmesɪdʒ/","usIpa":"/ˈmesɪdʒ/","cefr":"A1","topic":"technology","senses":[{"pos":"n.","en":"Information sent or left for someone to read or hear.","vi":"tin nhắn; lời nhắn"},{"pos":"n.","en":"The main idea that a story, speech, or artwork communicates.","vi":"th thông điệp; ý nghĩa chính"},{"pos":"v.","en":"To send someone an electronic communication.","vi":"gửi tin nhắn"}],"examples":[{"en":"Please leave a message if I miss your call.","vi":"Xin hãy để lại lời nhắn nếu tôi lỡ cuộc gọi của bạn.","audioKind":"ex"},{"en":"Public health campaigns need a clear message that people from different backgrounds can easily understand.","vi":"Các chiến dịch y tế công cộng cần truyền tải một thông điệp rõ ràng mà mọi người từ các hoàn cảnh khác nhau đều có thể dễ dàng thấu hiểu.","audioKind":"ex2"}],"collocations":[{"en":"leave a message","vi":"để lại lời nhắn"},{"en":"send a message","vi":"gửi tin nhắn"},{"en":"get the message across","vi":"truyền đạt rõ thông điệp"},{"en":"text message","vi":"tin nhắn văn bản"}],"wordFamily":["messaging (n.)","messenger (n.)"],"synonyms":[],"antonyms":[],"tipVi":"message là danh từ đếm được; trong khi information thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_machine', 'en-a1-15', 'machine', '/məˈʃiːn/', 'A1', 'máy; máy móc; thiết bị cơ khí; gia công bằng máy', 'n.', 'machinery (n.), machinist (n.), machining (n.)', NULL, 'machine là danh từ đếm được; machinery là danh từ tập hợp không đếm được.', 'The washing machine shook loudly during its final spin.', NULL, 'Máy giặt rung lắc mạnh trong chu trình vắt cuối cùng.', '{"wordId":"machine","ukIpa":"/məˈʃiːn/","usIpa":"/məˈʃiːn/","cefr":"A1","topic":"technology","senses":[{"pos":"n.","en":"A device with moving parts that performs a particular job.","vi":"máy; máy móc; thiết bị cơ khí"},{"pos":"v.","en":"To shape or finish material using a machine.","vi":"gia công bằng máy"}],"examples":[{"en":"The washing machine shook loudly during its final spin.","vi":"Máy giặt rung lắc mạnh trong chu trình vắt cuối cùng.","audioKind":"ex"},{"en":"A modern machine can perform repetitive tasks efficiently, allowing workers to focus on more complex problems.","vi":"Một cỗ máy hiện đại có thể thực hiện các công việc lặp đi lặp lại một cách hiệu quả, cho phép người lao động tập trung vào các vấn đề phức tạp hơn.","audioKind":"ex2"}],"collocations":[{"en":"washing machine","vi":"máy giặt"},{"en":"operate a machine","vi":"vận hành máy móc"},{"en":"machine learning","vi":"học máy"},{"en":"machine parts","vi":"chi tiết máy"}],"wordFamily":["machinery (n.)","machinist (n.)","machining (n.)"],"synonyms":[],"antonyms":[],"tipVi":"machine là danh từ đếm được; machinery là danh từ tập hợp không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_email', 'en-a1-15', 'email', '/ˈiːmeɪl/', 'A1', 'thư điện tử; hệ thống thư điện tử; gửi thư điện tử', 'n.', NULL, NULL, 'Chỉ một bức thư thì đếm được; chỉ phương thức liên lạc thì không đếm được, như by email.', 'Please email me the photos from our camping trip.', NULL, 'Hãy gửi cho tôi những bức ảnh từ chuyến đi cắm trại qua email nhé.', '{"wordId":"email","ukIpa":"/ˈiːmeɪl/","usIpa":"/ˈiːmeɪl/","cefr":"A1","topic":"technology","senses":[{"pos":"n.","en":"An electronic message, or the system used to send it","vi":"thư điện tử; hệ thống thư điện tử"},{"pos":"v.","en":"Send someone a message using email","vi":"gửi thư điện tử"}],"examples":[{"en":"Please email me the photos from our camping trip.","vi":"Hãy gửi cho tôi những bức ảnh từ chuyến đi cắm trại qua email nhé.","audioKind":"ex"},{"en":"Although email enables rapid communication, excessive messages can distract employees and reduce productivity at work.","vi":"Mặc dù thư điện tử giúp giao tiếp nhanh chóng, nhưng quá nhiều tin nhắn có thể làm nhân viên mất tập trung và giảm năng suất làm việc.","audioKind":"ex2"}],"collocations":[{"en":"send an email","vi":"gửi một email"},{"en":"check your email","vi":"kiểm tra email của bạn"},{"en":"an email address","vi":"địa chỉ email"},{"en":"by email","vi":"bằng email"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ một bức thư thì đếm được; chỉ phương thức liên lạc thì không đếm được, như by email.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_computer', 'en-a1-15', 'computer', '/kəmˈpjuːtər/', 'A1', 'máy tính; vi tính', 'n.', 'compute (v.), computing (n.), computation (n.), computerise (v.)', NULL, 'Làm việc trên máy tính dùng work on a computer.', 'My computer froze while I was editing holiday photos.', NULL, 'Máy tính của tôi bị đơ khi tôi đang chỉnh sửa các bức ảnh kỳ nghỉ.', '{"wordId":"computer","ukIpa":"/kəmˈpjuːtə/","usIpa":"/kəmˈpjuːtər/","cefr":"A1","topic":"technology","senses":[{"pos":"n.","en":"An electronic machine that stores and processes information using programs.","vi":"máy tính; vi tính"}],"examples":[{"en":"My computer froze while I was editing holiday photos.","vi":"Máy tính của tôi bị đơ khi tôi đang chỉnh sửa các bức ảnh kỳ nghỉ.","audioKind":"ex"},{"en":"Access to a computer at home can help students complete assignments and develop essential digital skills.","vi":"Việc có quyền truy cập máy tính ở nhà có thể giúp học sinh hoàn thành bài tập và phát triển các kỹ năng số thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"computer software","vi":"phần mềm máy tính"},{"en":"computer skills","vi":"kỹ năng tin học"},{"en":"computer network","vi":"mạng máy tính"},{"en":"computer science","vi":"khoa học máy tính"}],"wordFamily":["compute (v.)","computing (n.)","computation (n.)","computerise (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Làm việc trên máy tính dùng work on a computer.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_phone', 'en-a1-15', 'phone', '/foʊn/', 'A1', 'điện thoại; gọi điện thoại', 'n.', 'telephone (n.)', 'Đồng nghĩa: telephone, call', 'Động từ trực tiếp tiếp nhận tân ngữ chỉ người: phone someone, không dùng giới từ to.', 'My phone rang while I was washing the dishes.', NULL, 'Điện thoại của tôi reo lên trong lúc tôi đang rửa bát.', '{"wordId":"phone","ukIpa":"/fəʊn/","usIpa":"/foʊn/","cefr":"A1","topic":"technology","senses":[{"pos":"n.","en":"a device used to speak to people at a distance","vi":"điện thoại"},{"pos":"v.","en":"to contact someone using a telephone","vi":"gọi điện thoại"}],"examples":[{"en":"My phone rang while I was washing the dishes.","vi":"Điện thoại của tôi reo lên trong lúc tôi đang rửa bát.","audioKind":"ex"},{"en":"Limiting phone use in classrooms may help students concentrate more effectively on lessons and group activities.","vi":"Việc hạn chế sử dụng điện thoại trong lớp học có thể giúp học sinh tập trung hiệu quả hơn vào các bài học và hoạt động nhóm.","audioKind":"ex2"}],"collocations":[{"en":"answer the phone","vi":"nhấc máy nghe điện thoại"},{"en":"on the phone","vi":"đang trong cuộc gọi"},{"en":"mobile phone","vi":"điện thoại di động"},{"en":"phone someone back","vi":"gọi điện thoại lại cho ai"}],"wordFamily":["telephone (n.)"],"synonyms":["telephone","call"],"antonyms":[],"tipVi":"Động từ trực tiếp tiếp nhận tân ngữ chỉ người: phone someone, không dùng giới từ to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_newspaper', 'en-a1-15', 'newspaper', '/ˈnuːzpeɪpər/', 'A1', 'tờ báo; báo chí; tòa soạn báo', 'n.', NULL, NULL, 'a newspaper là một tờ báo (đếm được); newspaper cũng có thể dùng không đếm được khi chỉ chất liệu giấy báo.', 'My grandfather reads the newspaper while eating breakfast.', NULL, 'Ông tôi đọc báo trong lúc ăn sáng.', '{"wordId":"newspaper","ukIpa":"/ˈnjuːzpeɪpə/","usIpa":"/ˈnuːzpeɪpər/","cefr":"A1","topic":"media","senses":[{"pos":"n.","en":"A publication containing news, articles, and advertisements, usually printed daily.","vi":"tờ báo; báo chí"},{"pos":"n.","en":"An organization that produces and publishes news in a newspaper.","vi":"tòa soạn báo"}],"examples":[{"en":"My grandfather reads the newspaper while eating breakfast.","vi":"Ông tôi đọc báo trong lúc ăn sáng.","audioKind":"ex"},{"en":"Local newspapers provide valuable coverage of community issues that national media may overlook.","vi":"Các tờ báo địa phương cung cấp thông tin có giá trị về các vấn đề cộng đồng mà truyền thông quốc gia có thể bỏ sót.","audioKind":"ex2"}],"collocations":[{"en":"daily newspaper","vi":"báo ra hàng ngày"},{"en":"local newspaper","vi":"báo địa phương"},{"en":"newspaper article","vi":"bài báo"},{"en":"read a newspaper","vi":"đọc báo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"a newspaper là một tờ báo (đếm được); newspaper cũng có thể dùng không đếm được khi chỉ chất liệu giấy báo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_magazine', 'en-a1-15', 'magazine', '/ˈmæɡəziːn/', 'A1', 'tạp chí', 'n.', NULL, 'Đồng nghĩa: periodical', 'Là danh từ đếm được; trọng âm tiếng Anh-Anh thường rơi vào âm tiết cuối, trong khi tiếng Anh-Mỹ rơi vào âm tiết đầu.', 'She bought a gardening magazine at the station.', NULL, 'Cô ấy đã mua một cuốn tạp chí làm vườn ở nhà ga.', '{"wordId":"magazine","ukIpa":"/ˌmæɡəˈziːn/","usIpa":"/ˈmæɡəziːn/","cefr":"A1","topic":"media","senses":[{"pos":"n.","en":"A regularly published collection of articles and pictures.","vi":"tạp chí"}],"examples":[{"en":"She bought a gardening magazine at the station.","vi":"Cô ấy đã mua một cuốn tạp chí làm vườn ở nhà ga.","audioKind":"ex"},{"en":"A specialist magazine can provide practical career advice that general news websites may not offer.","vi":"Một cuốn tạp chí chuyên ngành có thể cung cấp những lời khuyên nghề nghiệp thiết thực mà các trang tin tức tổng hợp có thể không có.","audioKind":"ex2"}],"collocations":[{"en":"monthly magazine","vi":"tạp chí phát hành hàng tháng"},{"en":"fashion magazine","vi":"tạp chí thời trang"},{"en":"magazine subscription","vi":"sự đặt mua tạp chí dài hạn"},{"en":"magazine article","vi":"bài báo trên tạp chí"}],"wordFamily":[],"synonyms":["periodical"],"antonyms":[],"tipVi":"Là danh từ đếm được; trọng âm tiếng Anh-Anh thường rơi vào âm tiết cuối, trong khi tiếng Anh-Mỹ rơi vào âm tiết đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_news', 'en-a1-15', 'news', '/nuːz/', 'A1', 'n. tin tức; thông tin mới; n. bản tin; chương trình thời sự', 'n.', NULL, NULL, 'news là danh từ không đếm được và đi với động từ số ít: The news is good.', 'She called her sister to share the good news.', NULL, 'Cô ấy gọi điện cho chị gái để chia sẻ tin vui.', '{"wordId":"news","ukIpa":"/njuːz/","usIpa":"/nuːz/","cefr":"A1","topic":"media","senses":[{"pos":"n.","en":"information about recent events or something previously unknown","vi":"n. tin tức; thông tin mới"},{"pos":"n.","en":"a broadcast or report presenting recent events","vi":"n. bản tin; chương trình thời sự"}],"examples":[{"en":"She called her sister to share the good news.","vi":"Cô ấy gọi điện cho chị gái để chia sẻ tin vui.","audioKind":"ex"},{"en":"People should check several reliable sources before sharing news about health issues on social media.","vi":"Mọi người nên kiểm tra nhiều nguồn đáng tin cậy trước khi chia sẻ tin tức về các vấn đề sức khỏe trên mạng xã hội.","audioKind":"ex2"}],"collocations":[{"en":"good news","vi":"tin vui"},{"en":"breaking news","vi":"tin nóng"},{"en":"watch the news","vi":"xem tin tức"},{"en":"a piece of news","vi":"một mẩu tin tức"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"news là danh từ không đếm được và đi với động từ số ít: The news is good.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_television', 'en-a1-15', 'television', '/ˈteləvɪʒən/', 'A1', 'truyền hình; chương trình truyền hình; ti vi; máy thu hình; ngành truyền hình', 'n.', 'televise (v.), televised (adj.)', 'Đồng nghĩa: TV', 'watch television không dùng mạo từ; chỉ một chiếc máy thu hình thì dùng a television.', 'We watched a wildlife programme on television after dinner.', NULL, 'Chúng tôi đã xem một chương trình về thế giới động vật trên ti vi sau bữa tối.', '{"wordId":"television","ukIpa":"/ˈtelɪvɪʒən/","usIpa":"/ˈteləvɪʒən/","cefr":"A1","topic":"media","senses":[{"pos":"n.","en":"broadcast programmes with moving pictures and sound","vi":"truyền hình; chương trình truyền hình"},{"pos":"n.","en":"a device used to watch broadcast or streamed programmes","vi":"ti vi; máy thu hình"},{"pos":"n.","en":"the industry that produces and broadcasts television programmes","vi":"ngành truyền hình"}],"examples":[{"en":"We watched a wildlife programme on television after dinner.","vi":"Chúng tôi đã xem một chương trình về thế giới động vật trên ti vi sau bữa tối.","audioKind":"ex"},{"en":"Educational television can introduce children to scientific ideas that are difficult to demonstrate in classrooms.","vi":"Truyền hình giáo dục có thể giúp trẻ em tiếp cận với các khái niệm khoa học vốn khó minh họa trực tiếp trong lớp học.","audioKind":"ex2"}],"collocations":[{"en":"watch television","vi":"xem ti vi"},{"en":"on television","vi":"trên ti vi"},{"en":"television programme","vi":"chương trình truyền hình"},{"en":"television industry","vi":"ngành công nghiệp truyền hình"}],"wordFamily":["televise (v.)","televised (adj.)"],"synonyms":["TV"],"antonyms":[],"tipVi":"watch television không dùng mạo từ; chỉ một chiếc máy thu hình thì dùng a television.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_information', 'en-a1-15', 'information', '/ˌɪnfərˈmeɪʃən/', 'A1', 'thông tin; tài liệu', 'n.', 'inform (v.), informative (adj.), informed (adj.)', 'Đồng nghĩa: details, facts', 'Là danh từ không đếm được: dùng some information, không dùng an information.', 'The receptionist gave us useful information about local buses.', NULL, 'Nhân viên lễ tân đã cung cấp cho chúng tôi những thông tin hữu ích về xe buýt địa phương.', '{"wordId":"information","ukIpa":"/ˌɪnfəˈmeɪʃən/","usIpa":"/ˌɪnfərˈmeɪʃən/","cefr":"A1","topic":"media","senses":[{"pos":"n.","en":"Facts or details about someone or something","vi":"thông tin; tài liệu"}],"examples":[{"en":"The receptionist gave us useful information about local buses.","vi":"Nhân viên lễ tân đã cung cấp cho chúng tôi những thông tin hữu ích về xe buýt địa phương.","audioKind":"ex"},{"en":"Access to reliable information enables patients to make better decisions about their treatment and long-term health.","vi":"Việc tiếp cận thông tin đáng tin cậy giúp bệnh nhân đưa ra những quyết định tốt hơn về quá trình điều trị và sức khỏe lâu dài của họ.","audioKind":"ex2"}],"collocations":[{"en":"reliable information","vi":"thông tin đáng tin cậy"},{"en":"access to information","vi":"khả năng tiếp cận thông tin"},{"en":"provide information","vi":"cung cấp thông tin"},{"en":"a piece of information","vi":"một mẩu thông tin"}],"wordFamily":["inform (v.)","informative (adj.)","informed (adj.)"],"synonyms":["details","facts"],"antonyms":[],"tipVi":"Là danh từ không đếm được: dùng some information, không dùng an information.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_radio', 'en-a1-15', 'radio', '/ˈreɪdioʊ/', 'A1', 'máy thu thanh; đài; vô tuyến phát thanh; sóng vô tuyến; gọi bằng vô tuyến; liên lạc vô tuyến', 'n.', NULL, NULL, 'Nghe đài thường dùng listen to the radio; phát trên đài dùng on the radio.', 'Dad keeps a small radio on the kitchen shelf.', NULL, 'Bố đặt một chiếc đài nhỏ trên kệ bếp.', '{"wordId":"radio","ukIpa":"/ˈreɪdiəʊ/","usIpa":"/ˈreɪdioʊ/","cefr":"A1","topic":"media","senses":[{"pos":"n.","en":"a device used to receive and play broadcast sound","vi":"máy thu thanh; đài"},{"pos":"n.","en":"broadcasting or communication using electromagnetic waves","vi":"vô tuyến phát thanh; sóng vô tuyến"},{"pos":"v.","en":"to contact someone or send information using radio equipment","vi":"gọi bằng vô tuyến; liên lạc vô tuyến"}],"examples":[{"en":"Dad keeps a small radio on the kitchen shelf.","vi":"Bố đặt một chiếc đài nhỏ trên kệ bếp.","audioKind":"ex"},{"en":"Radio remains an important source of information in remote communities where reliable internet access is limited.","vi":"Đài phát thanh vẫn là một nguồn thông tin quan trọng ở các cộng đồng vùng sâu vùng xa nơi khả năng truy cập Internet ổn định còn hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"listen to the radio","vi":"nghe đài"},{"en":"radio station","vi":"đài phát thanh"},{"en":"radio programme","vi":"chương trình phát thanh"},{"en":"radio signal","vi":"tín hiệu vô tuyến"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nghe đài thường dùng listen to the radio; phát trên đài dùng on the radio.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_video', 'en-a1-15', 'video', '/ˈvɪdioʊ/', 'A1', 'video; đoạn ghi hình ảnh chuyển động, thường có kèm âm thanh; quay video; ghi hình ảnh chuyển động của ai hoặc cái gì', 'n.', NULL, NULL, 'Một đoạn video dùng a video; khi chỉ phương tiện truyền thông video thì có thể dùng ở dạng không đếm được.', 'We watched a video of penguins sliding across ice.', NULL, 'Chúng tôi đã xem một đoạn video quay cảnh những chú chim cánh cụt trượt trên băng.', '{"wordId":"video","ukIpa":"/ˈvɪdiəʊ/","usIpa":"/ˈvɪdioʊ/","cefr":"A1","topic":"media","senses":[{"pos":"n.","en":"A recording of moving images, usually with sound.","vi":"video; đoạn ghi hình ảnh chuyển động, thường có kèm âm thanh"},{"pos":"v.","en":"Record moving images of someone or something.","vi":"quay video; ghi hình ảnh chuyển động của ai hoặc cái gì"}],"examples":[{"en":"We watched a video of penguins sliding across ice.","vi":"Chúng tôi đã xem một đoạn video quay cảnh những chú chim cánh cụt trượt trên băng.","audioKind":"ex"},{"en":"Educational video can make complex processes easier to understand, especially for students with limited background knowledge.","vi":"Video giáo dục có thể giúp các quá trình phức tạp trở nên dễ hiểu hơn, đặc biệt đối với học sinh có ít kiến thức nền tảng.","audioKind":"ex2"}],"collocations":[{"en":"watch a video","vi":"xem video"},{"en":"record a video","vi":"quay video; ghi hình"},{"en":"video clip","vi":"đoạn video ngắn"},{"en":"video call","vi":"cuộc gọi video"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Một đoạn video dùng a video; khi chỉ phương tiện truyền thông video thì có thể dùng ở dạng không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_zero', 'en-a1-15', 'zero', '/ˈzɪroʊ/', 'A1', 'số không; số không; độ không', 'num.', NULL, NULL, 'Khi đọc số điện thoại, số 0 thường đọc là oh; nhiệt độ dùng zero.', 'The temperature fell below zero while we were sleeping.', NULL, 'Nhiệt độ đã giảm xuống dưới không độ khi chúng tôi đang ngủ.', '{"wordId":"zero","ukIpa":"/ˈzɪərəʊ/","usIpa":"/ˈzɪroʊ/","cefr":"A1","topic":"science","senses":[{"pos":"num.","en":"The number representing no quantity.","vi":"số không"},{"pos":"n.","en":"The point marked as nothing on a measuring scale.","vi":"số không; độ không"}],"examples":[{"en":"The temperature fell below zero while we were sleeping.","vi":"Nhiệt độ đã giảm xuống dưới không độ khi chúng tôi đang ngủ.","audioKind":"ex"},{"en":"Achieving zero carbon emissions will require substantial investment in renewable energy, public transport, and more efficient buildings.","vi":"Việc đạt được lượng phát thải carbon bằng không sẽ đòi hỏi các khoản đầu tư đáng kể vào năng lượng tái tạo, giao thông công cộng và các tòa nhà hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"below zero","vi":"dưới không độ"},{"en":"zero emissions","vi":"phát thải bằng không"},{"en":"zero tolerance","vi":"không khoan nhượng"},{"en":"absolute zero","vi":"độ không tuyệt đối"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi đọc số điện thoại, số 0 thường đọc là oh; nhiệt độ dùng zero.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_science', 'en-a1-15', 'science', '/ˈsaɪəns/', 'A1', 'khoa học; nghiên cứu thế giới tự nhiên; ngành khoa học; lĩnh vực khoa học', 'n.', 'scientist (n.), scientific (adj.), scientifically (adv.)', NULL, 'Danh từ chỉ khoa học nói chung thường không đếm được; khi chỉ một môn khoa học cụ thể, có thể dùng a science.', 'We grew tiny crystals in our science class today.', NULL, 'Chúng tôi đã nuôi cấy những tinh thể nhỏ trong tiết học khoa học hôm nay.', '{"wordId":"science","ukIpa":"/ˈsaɪəns/","usIpa":"/ˈsaɪəns/","cefr":"A1","topic":"science","senses":[{"pos":"n.","en":"Study of the natural world through observation and experiments","vi":"khoa học; nghiên cứu thế giới tự nhiên"},{"pos":"n.","en":"A particular field of study using scientific methods","vi":"ngành khoa học; lĩnh vực khoa học"}],"examples":[{"en":"We grew tiny crystals in our science class today.","vi":"Chúng tôi đã nuôi cấy những tinh thể nhỏ trong tiết học khoa học hôm nay.","audioKind":"ex"},{"en":"Investment in science can help countries develop cleaner energy sources and improve public health.","vi":"Đầu tư vào khoa học có thể giúp các quốc gia phát triển các nguồn năng lượng sạch hơn và cải thiện sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"science education","vi":"giáo dục khoa học"},{"en":"natural sciences","vi":"khoa học tự nhiên"},{"en":"advances in science","vi":"những tiến bộ trong khoa học"},{"en":"computer science","vi":"khoa học máy tính"}],"wordFamily":["scientist (n.)","scientific (adj.)","scientifically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ chỉ khoa học nói chung thường không đếm được; khi chỉ một môn khoa học cụ thể, có thể dùng a science.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_metre', 'en-a1-15', 'metre', '/ˈmiːtər/', 'A1', 'mét; nhịp thơ', 'n.', NULL, NULL, 'Đơn vị chiều dài viết là metre theo kiểu Anh và meter theo kiểu Mỹ; dạng số nhiều là metres.', 'This shelf is just over a metre long.', NULL, 'Chiếc kệ này dài hơn một mét một chút.', '{"wordId":"metre","ukIpa":"/ˈmiːtə/","usIpa":"/ˈmiːtər/","cefr":"A1","topic":"science","senses":[{"pos":"n.","en":"A unit of length equal to one hundred centimetres.","vi":"mét"},{"pos":"n.","en":"A regular pattern of stressed and unstressed syllables in poetry.","vi":"nhịp thơ"}],"examples":[{"en":"This shelf is just over a metre long.","vi":"Chiếc kệ này dài hơn một mét một chút.","audioKind":"ex"},{"en":"Raising coastal barriers by one metre could help protect nearby homes from increasingly severe flooding.","vi":"Việc nâng các bức chắn ven biển lên một mét có thể giúp bảo vệ các khu vực nhà dân lân cận khỏi tình trạng ngập lụt ngày càng nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"a square metre","vi":"một mét vuông"},{"en":"a cubic metre","vi":"một mét khối"},{"en":"a metre long","vi":"dài một mét"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Đơn vị chiều dài viết là metre theo kiểu Anh và meter theo kiểu Mỹ; dạng số nhiều là metres.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_air', 'en-a1-15', 'air', '/er/', 'A1', 'không khí; vẻ bề ngoài; phong thái; làm thoáng khí; công khai bày tỏ', 'n.', 'airy (adj.), airless (adj.)', NULL, 'Chỉ không khí thì không đếm được; an air of diễn tả "mang bầu không khí/vẻ gì đó".', 'I opened the window to let fresh air in.', NULL, 'Tôi mở cửa sổ để cho không khí trong lành tràn vào.', '{"wordId":"air","ukIpa":"/eə/","usIpa":"/er/","cefr":"A1","topic":"environment","senses":[{"pos":"n.","en":"The mixture of gases surrounding Earth that people breathe.","vi":"không khí"},{"pos":"n.","en":"A particular quality that someone or something seems to have.","vi":"vẻ bề ngoài; phong thái"},{"pos":"v.","en":"To let fresh air in, or express views publicly.","vi":"làm thoáng khí; công khai bày tỏ"}],"examples":[{"en":"I opened the window to let fresh air in.","vi":"Tôi mở cửa sổ để cho không khí trong lành tràn vào.","audioKind":"ex"},{"en":"Improving air quality in cities requires cleaner transport and stricter controls on industrial emissions.","vi":"Việc cải thiện chất lượng không khí ở các thành phố đòi hỏi các phương tiện giao thông sạch hơn và sự kiểm soát nghiêm ngặt hơn đối với lượng khí thải công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"fresh air","vi":"không khí trong lành"},{"en":"air pollution","vi":"ô nhiễm không khí"},{"en":"an air of confidence","vi":"vẻ tự tin"},{"en":"air concerns","vi":"công khai bày tỏ mối bận tâm"}],"wordFamily":["airy (adj.)","airless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ không khí thì không đếm được; an air of diễn tả \"mang bầu không khí/vẻ gì đó\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_weather', 'en-a1-15', 'weather', '/ˈweðɚ/', 'A1', 'thời tiết; vượt qua; chống chọi; bị phong hóa; bị bào mòn', 'n.', 'weathered (adj.), weathering (n.)', NULL, 'Khi chỉ thời tiết thì đây là danh từ không đếm được; climate dùng để chỉ đặc điểm khí hậu lâu dài.', 'The weather turned sunny just before our picnic.', NULL, 'Trời đã chuyển sang nắng đẹp ngay trước buổi dã ngoại của chúng tôi.', '{"wordId":"weather","ukIpa":"/ˈweðə(r)/","usIpa":"/ˈweðɚ/","cefr":"A1","topic":"environment","senses":[{"pos":"n.","en":"Conditions outside, such as rain, sunshine, wind, and temperature.","vi":"thời tiết"},{"pos":"v.","en":"To survive a difficult situation without serious damage.","vi":"vượt qua; chống chọi"},{"pos":"v.","en":"To change or become damaged through exposure to outdoor conditions.","vi":"bị phong hóa; bị bào mòn"}],"examples":[{"en":"The weather turned sunny just before our picnic.","vi":"Trời đã chuyển sang nắng đẹp ngay trước buổi dã ngoại của chúng tôi.","audioKind":"ex"},{"en":"Extreme weather can disrupt food production and increase the cost of basic goods for vulnerable communities.","vi":"Thời tiết cực đoan có thể làm gián đoạn sản xuất lương thực và làm tăng chi phí các mặt hàng thiết yếu đối với các cộng đồng dễ bị tổn thương.","audioKind":"ex2"}],"collocations":[{"en":"weather forecast","vi":"dự báo thời tiết"},{"en":"extreme weather","vi":"thời tiết cực đoan"},{"en":"weather conditions","vi":"tình hình thời tiết"},{"en":"weather a storm","vi":"vượt qua cơn bão khó khăn"}],"wordFamily":["weathered (adj.)","weathering (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ thời tiết thì đây là danh từ không đếm được; climate dùng để chỉ đặc điểm khí hậu lâu dài.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_history', 'en-a1-15', 'history', '/ˈhɪstəri/', 'A1', 'lịch sử; môn lịch sử; tiểu sử; quá khứ', 'n.', 'historian (n.), historical (adj.), historically (adv.), historic (adj.)', NULL, 'historical chỉ những gì liên quan đến lịch sử; historic chỉ những gì có ý nghĩa lịch sử.', 'Our guide explained the history of the old castle.', NULL, 'Hướng dẫn viên giải thích lịch sử của lâu đài cổ.', '{"wordId":"history","ukIpa":"/ˈhɪstəri/","usIpa":"/ˈhɪstəri/","cefr":"A1","topic":"history","senses":[{"pos":"n.","en":"Past events, or the study of them.","vi":"lịch sử; môn lịch sử"},{"pos":"n.","en":"A record of someone''s or something''s past experiences or conditions.","vi":"tiểu sử; quá khứ"}],"examples":[{"en":"Our guide explained the history of the old castle.","vi":"Hướng dẫn viên giải thích lịch sử của lâu đài cổ.","audioKind":"ex"},{"en":"Studying history helps citizens understand how past decisions continue to shape modern societies and institutions.","vi":"Học lịch sử giúp công dân hiểu được các quyết định trong quá khứ tiếp tục định hình các xã hội và thể chế hiện đại như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"ancient history","vi":"lịch sử cổ đại"},{"en":"medical history","vi":"tiểu sử bệnh án"},{"en":"a history of","vi":"lịch sử có..."},{"en":"throughout history","vi":"xuyên suốt lịch sử"}],"wordFamily":["historian (n.)","historical (adj.)","historically (adv.)","historic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"historical chỉ những gì liên quan đến lịch sử; historic chỉ những gì có ý nghĩa lịch sử.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_country', 'en-a1-15', 'country', '/ˈkʌntri/', 'A1', 'quốc gia; đất nước; vùng quê; miền quê; nhạc đồng quê', 'n.', NULL, 'Đồng nghĩa: nation, countryside', 'Để chỉ "vùng quê/nông thôn", thường dùng mạo từ the country để phân biệt với nghĩa "quốc gia".', 'She hopes to visit another country next summer.', NULL, 'Cô ấy hy vọng sẽ đến thăm một quốc gia khác vào mùa hè tới.', '{"wordId":"country","ukIpa":"/ˈkʌntri/","usIpa":"/ˈkʌntri/","cefr":"A1","topic":"government","senses":[{"pos":"n.","en":"An area of land governed as an independent political unit.","vi":"quốc gia; đất nước"},{"pos":"n.","en":"Land outside towns and cities, often with farms and villages.","vi":"vùng quê; miền quê"},{"pos":"n.","en":"A popular music style rooted in rural American traditions.","vi":"nhạc đồng quê"}],"examples":[{"en":"She hopes to visit another country next summer.","vi":"Cô ấy hy vọng sẽ đến thăm một quốc gia khác vào mùa hè tới.","audioKind":"ex"},{"en":"Each country should develop energy policies that reflect its natural resources and long-term environmental goals.","vi":"Mỗi quốc gia nên xây dựng các chính sách năng lượng phù hợp với tài nguyên thiên nhiên và mục tiêu môi trường dài hạn của mình.","audioKind":"ex2"}],"collocations":[{"en":"a developing country","vi":"một quốc gia đang phát triển"},{"en":"a neighbouring country","vi":"một nước láng giềng"},{"en":"live in the country","vi":"sống ở vùng quê"},{"en":"country music","vi":"nhạc đồng quê"}],"wordFamily":[],"synonyms":["nation","countryside"],"antonyms":[],"tipVi":"Để chỉ \"vùng quê/nông thôn\", thường dùng mạo từ the country để phân biệt với nghĩa \"quốc gia\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_15_1', 'en-a1-15', 'Cách dùng “magazine” (n.) — tạp chí', 'monthly magazine  ·  fashion magazine  ·  magazine subscription', 'Là danh từ đếm được; trọng âm tiếng Anh-Anh thường rơi vào âm tiết cuối, trong khi tiếng Anh-Mỹ rơi vào âm tiết đầu.', 'Đồng nghĩa: periodical', '[{"hanzi":"She bought a gardening magazine at the station.","pinyin":"","meaning":"Cô ấy đã mua một cuốn tạp chí làm vườn ở nhà ga."},{"hanzi":"A specialist magazine can provide practical career advice that general news websites may not offer.","pinyin":"","meaning":"Một cuốn tạp chí chuyên ngành có thể cung cấp những lời khuyên nghề nghiệp thiết thực mà các trang tin tức tổng hợp có thể không có."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_15_2', 'en-a1-15', 'Cách dùng “science” (n.) — khoa học; nghiên cứu thế giới tự nhiên', 'science education  ·  natural sciences  ·  advances in science', 'Danh từ chỉ khoa học nói chung thường không đếm được; khi chỉ một môn khoa học cụ thể, có thể dùng a science.', 'Họ từ (Word Family): scientist (n.), scientific (adj.), scientifically (adv.)', '[{"hanzi":"We grew tiny crystals in our science class today.","pinyin":"","meaning":"Chúng tôi đã nuôi cấy những tinh thể nhỏ trong tiết học khoa học hôm nay."},{"hanzi":"Investment in science can help countries develop cleaner energy sources and improve public health.","pinyin":"","meaning":"Đầu tư vào khoa học có thể giúp các quốc gia phát triển các nguồn năng lượng sạch hơn và cải thiện sức khỏe cộng đồng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_15_3', 'en-a1-15', 'Cách dùng “newspaper” (n.) — tờ báo; báo chí', 'daily newspaper  ·  local newspaper  ·  newspaper article', 'a newspaper là một tờ báo (đếm được); newspaper cũng có thể dùng không đếm được khi chỉ chất liệu giấy báo.', NULL, '[{"hanzi":"My grandfather reads the newspaper while eating breakfast.","pinyin":"","meaning":"Ông tôi đọc báo trong lúc ăn sáng."},{"hanzi":"Local newspapers provide valuable coverage of community issues that national media may overlook.","pinyin":"","meaning":"Các tờ báo địa phương cung cấp thông tin có giá trị về các vấn đề cộng đồng mà truyền thông quốc gia có thể bỏ sót."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_15_4', 'en-a1-15', 'Cách dùng “video” (n.) — video; đoạn ghi hình ảnh chuyển động, thường có kèm âm thanh', 'watch a video  ·  record a video  ·  video clip', 'Một đoạn video dùng a video; khi chỉ phương tiện truyền thông video thì có thể dùng ở dạng không đếm được.', NULL, '[{"hanzi":"We watched a video of penguins sliding across ice.","pinyin":"","meaning":"Chúng tôi đã xem một đoạn video quay cảnh những chú chim cánh cụt trượt trên băng."},{"hanzi":"Educational video can make complex processes easier to understand, especially for students with limited background knowledge.","pinyin":"","meaning":"Video giáo dục có thể giúp các quá trình phức tạp trở nên dễ hiểu hơn, đặc biệt đối với học sinh có ít kiến thức nền tảng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_15_1', 'en-a1-15', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_15_1_1', 'ten_15_1', 'camera', 'She raised her camera to photograph the sleeping cat.', 'She raised her camera to photograph the sleeping cat.', '/ˈkæmərə/', 'Cô ấy giơ máy ảnh lên để chụp con mèo đang ngủ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_15_1_2', 'ten_15_1', 'website', 'I found the museum''s opening hours on its website.', 'I found the museum''s opening hours on its website.', '/ˈwebsaɪt/', 'Tôi đã tìm thấy giờ mở cửa của viện bảo hiểm trên trang web của họ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_15_1_3', 'ten_15_1', 'telephone', 'The telephone rang just as I opened the door.', 'The telephone rang just as I opened the door.', '/ˈteləfoʊn/', 'Điện thoại vừa reo thì tôi mở cửa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_15_1_4', 'ten_15_1', 'internet', 'The internet stopped working halfway through our video call.', 'The internet stopped working halfway through our video call.', '/ˈɪntərnet/', 'Mạng internet bị ngắt giữa chừng cuộc gọi video của chúng tôi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_15_1_5', 'ten_15_1', 'message', 'Please leave a message if I miss your call.', 'Please leave a message if I miss your call.', '/ˈmesɪdʒ/', 'Xin hãy để lại lời nhắn nếu tôi lỡ cuộc gọi của bạn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_15_1_6', 'ten_15_1', 'machine', 'The washing machine shook loudly during its final spin.', 'The washing machine shook loudly during its final spin.', '/məˈʃiːn/', 'Máy giặt rung lắc mạnh trong chu trình vắt cuối cùng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_15_1_7', 'ten_15_1', 'email', 'Please email me the photos from our camping trip.', 'Please email me the photos from our camping trip.', '/ˈiːmeɪl/', 'Hãy gửi cho tôi những bức ảnh từ chuyến đi cắm trại qua email nhé.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_15_1_8', 'ten_15_1', 'computer', 'My computer froze while I was editing holiday photos.', 'My computer froze while I was editing holiday photos.', '/kəmˈpjuːtər/', 'Máy tính của tôi bị đơ khi tôi đang chỉnh sửa các bức ảnh kỳ nghỉ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_15_1_1', 'en-a1-15', 'ten_15_1', 'listening', 'listening', 'She raised her camera to photograph the sleeping cat.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Xin hãy để lại lời nhắn nếu tôi lỡ cuộc gọi của bạn.","Máy giặt rung lắc mạnh trong chu trình vắt cuối cùng.","Cô ấy giơ máy ảnh lên để chụp con mèo đang ngủ.","Mạng internet bị ngắt giữa chừng cuộc gọi video của chúng tôi."]'::jsonb, 2, 'She raised her camera to photograph the sleeping cat. → Cô ấy giơ máy ảnh lên để chụp con mèo đang ngủ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_15_1_2', 'en-a1-15', 'ten_15_1', 'listening', 'listening', 'I found the museum''s opening hours on its website.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Xin hãy để lại lời nhắn nếu tôi lỡ cuộc gọi của bạn.","Cô ấy giơ máy ảnh lên để chụp con mèo đang ngủ.","Máy giặt rung lắc mạnh trong chu trình vắt cuối cùng.","Tôi đã tìm thấy giờ mở cửa của viện bảo hiểm trên trang web của họ."]'::jsonb, 3, 'I found the museum''s opening hours on its website. → Tôi đã tìm thấy giờ mở cửa của viện bảo hiểm trên trang web của họ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_15_1_3', 'en-a1-15', 'ten_15_1', 'listening', 'listening', 'The telephone rang just as I opened the door.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Xin hãy để lại lời nhắn nếu tôi lỡ cuộc gọi của bạn.","Điện thoại vừa reo thì tôi mở cửa.","Hãy gửi cho tôi những bức ảnh từ chuyến đi cắm trại qua email nhé.","Máy tính của tôi bị đơ khi tôi đang chỉnh sửa các bức ảnh kỳ nghỉ."]'::jsonb, 1, 'The telephone rang just as I opened the door. → Điện thoại vừa reo thì tôi mở cửa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
