INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_15_2_1', 'ten_15_2', 'camera', 'Installing a camera at each entrance may improve security, but residents have raised concerns about privacy.', 'Installing a camera at each entrance may improve security, but residents have raised concerns about privacy.', '/ˈkæmərə/', 'Việc lắp đặt camera ở mỗi lối ra vào có thể nâng cao an ninh, nhưng cư dân đã bày tỏ lo ngại về vấn đề quyền riêng tư.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_15_2_2', 'ten_15_2', 'website', 'A well-designed government website can make public services more accessible to people in remote areas.', 'A well-designed government website can make public services more accessible to people in remote areas.', '/ˈwebsaɪt/', 'Một trang web chính phủ được thiết kế tốt có thể giúp người dân ở các vùng sâu vùng xa tiếp cận các dịch vụ công dễ dàng hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_15_2_3', 'ten_15_2', 'telephone', 'Telephone consultations can improve access to healthcare for rural residents who live far from medical centres.', 'Telephone consultations can improve access to healthcare for rural residents who live far from medical centres.', '/ˈteləfoʊn/', 'Tư vấn qua điện thoại có thể cải thiện khả năng tiếp cận dịch vụ chăm sóc sức khỏe cho cư dân nông thôn sống xa các trung tâm y tế.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_15_2_4', 'ten_15_2', 'internet', 'Reliable internet access enables rural students to use educational resources that may be unavailable locally.', 'Reliable internet access enables rural students to use educational resources that may be unavailable locally.', '/ˈɪntərnet/', 'Việc truy cập internet ổn định giúp học sinh vùng sâu vùng xa tiếp cận các nguồn tài nguyên giáo dục có thể không có sẵn tại địa phương.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_15_2_5', 'ten_15_2', 'message', 'Public health campaigns need a clear message that people from different backgrounds can easily understand.', 'Public health campaigns need a clear message that people from different backgrounds can easily understand.', '/ˈmesɪdʒ/', 'Các chiến dịch y tế công cộng cần truyền tải một thông điệp rõ ràng mà mọi người từ các hoàn cảnh khác nhau đều có thể dễ dàng thấu hiểu.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_15_2_6', 'ten_15_2', 'machine', 'A modern machine can perform repetitive tasks efficiently, allowing workers to focus on more complex problems.', 'A modern machine can perform repetitive tasks efficiently, allowing workers to focus on more complex problems.', '/məˈʃiːn/', 'Một cỗ máy hiện đại có thể thực hiện các công việc lặp đi lặp lại một cách hiệu quả, cho phép người lao động tập trung vào các vấn đề phức tạp hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
