INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_15_2', 'en-a1-15', NULL, 'comprehensive_test', 'listening', 'I found the museum''s opening hours on its website.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Điện thoại của tôi reo lên trong lúc tôi đang rửa bát.","Ông tôi đọc báo trong lúc ăn sáng.","Tôi đã tìm thấy giờ mở cửa của viện bảo hiểm trên trang web của họ.","Cô ấy gọi điện cho chị gái để chia sẻ tin vui."]'::jsonb, 2, 'I found the museum''s opening hours on its website. → Tôi đã tìm thấy giờ mở cửa của viện bảo hiểm trên trang web của họ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
