INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_15_4', 'en-a1-15', NULL, 'comprehensive_test', 'listening', 'The internet stopped working halfway through our video call.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Trời đã chuyển sang nắng đẹp ngay trước buổi dã ngoại của chúng tôi.","Nhiệt độ đã giảm xuống dưới không độ khi chúng tôi đang ngủ.","Mạng internet bị ngắt giữa chừng cuộc gọi video của chúng tôi.","Cô ấy giơ máy ảnh lên để chụp con mèo đang ngủ."]'::jsonb, 2, 'The internet stopped working halfway through our video call. → Mạng internet bị ngắt giữa chừng cuộc gọi video của chúng tôi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
