INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_15_6', 'en-a1-15', NULL, 'comprehensive_test', 'listening', 'The washing machine shook loudly during its final spin.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy giơ máy ảnh lên để chụp con mèo đang ngủ.","Trời đã chuyển sang nắng đẹp ngay trước buổi dã ngoại của chúng tôi.","Nhân viên lễ tân đã cung cấp cho chúng tôi những thông tin hữu ích về xe buýt địa phương.","Máy giặt rung lắc mạnh trong chu trình vắt cuối cùng."]'::jsonb, 3, 'The washing machine shook loudly during its final spin. → Máy giặt rung lắc mạnh trong chu trình vắt cuối cùng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
