INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_15_8', 'en-a1-15', NULL, 'comprehensive_test', 'listening', 'My computer froze while I was editing holiday photos.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc kệ này dài hơn một mét một chút.","Tôi mở cửa sổ để cho không khí trong lành tràn vào.","Cô ấy đã mua một cuốn tạp chí làm vườn ở nhà ga.","Máy tính của tôi bị đơ khi tôi đang chỉnh sửa các bức ảnh kỳ nghỉ."]'::jsonb, 3, 'My computer froze while I was editing holiday photos. → Máy tính của tôi bị đơ khi tôi đang chỉnh sửa các bức ảnh kỳ nghỉ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
