INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_15_18', 'en-a1-15', NULL, 'comprehensive_test', 'reading', NULL, 'Installing a camera at each entrance may improve security, but residents have raised concerns about privacy.', 'Dựa vào câu trên, từ “camera” có nghĩa phù hợp nhất là gì?', '["cái giường (đồ nội thất dùng để ngủ)","máy ảnh; máy quay phim; camera","chậm rãi; từ từ","nhìn thấy; trông thấy"]'::jsonb, 1, 'camera: máy ảnh; máy quay phim; camera. Dịch cả câu: Việc lắp đặt camera ở mỗi lối ra vào có thể nâng cao an ninh, nhưng cư dân đã bày tỏ lo ngại về vấn đề quyền riêng tư.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_15_19', 'en-a1-15', NULL, 'comprehensive_test', 'reading', NULL, 'A well-designed government website can make public services more accessible to people in remote areas.', 'Dựa vào câu trên, từ “website” có nghĩa phù hợp nhất là gì?', '["đồ vật; vật dụng","máy thu thanh; đài","trang web; trang mạng","đặc biệt; khác thường"]'::jsonb, 2, 'website: trang web; trang mạng. Dịch cả câu: Một trang web chính phủ được thiết kế tốt có thể giúp người dân ở các vùng sâu vùng xa tiếp cận các dịch vụ công dễ dàng hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_15_20', 'en-a1-15', NULL, 'comprehensive_test', 'reading', NULL, 'Telephone consultations can improve access to healthcare for rural residents who live far from medical centres.', 'Dựa vào câu trên, từ “telephone” có nghĩa phù hợp nhất là gì?', '["sô-cô-la","n. điện thoại; máy điện thoại","lỗi; sai sót; sự nhầm lẫn","ở bên ngoài; ra ngoài"]'::jsonb, 1, 'telephone: n. điện thoại; máy điện thoại; v. gọi điện thoại; gọi điện cho ai. Dịch cả câu: Tư vấn qua điện thoại có thể cải thiện khả năng tiếp cận dịch vụ chăm sóc sức khỏe cho cư dân nông thôn sống xa các trung tâm y tế.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_15_21', 'en-a1-15', NULL, 'comprehensive_test', 'reading', NULL, 'Reliable internet access enables rural students to use educational resources that may be unavailable locally.', 'Dựa vào câu trên, từ “internet” có nghĩa phù hợp nhất là gì?', '["thứ Hai","con voi","mạng internet; mạng toàn cầu","mỗi; từng"]'::jsonb, 2, 'internet: mạng internet; mạng toàn cầu. Dịch cả câu: Việc truy cập internet ổn định giúp học sinh vùng sâu vùng xa tiếp cận các nguồn tài nguyên giáo dục có thể không có sẵn tại địa phương.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_15_22', 'en-a1-15', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thời tiết”', '["lady","sell","weather","now"]'::jsonb, 2, 'thời tiết → weather (/ˈweðɚ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_15_23', 'en-a1-15', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lịch sử; môn lịch sử”', '["leg","light","history","bookshop"]'::jsonb, 2, 'lịch sử; môn lịch sử → history (/ˈhɪstəri/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_15_24', 'en-a1-15', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “quốc gia; đất nước”', '["cloudy","finish","country","our"]'::jsonb, 2, 'quốc gia; đất nước → country (/ˈkʌntri/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-16', 'en', 'Bài 16: Đời sống hằng ngày (1) - CEFR A1', 'CEFR A1', 'A1 · Đời sống', '28 từ vựng Tiếng Anh CEFR A1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1016, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thursday', 'en-a1-16', 'Thursday', '/ˈθɝːzdeɪ/', 'A1', 'ngày thứ năm', 'n.', NULL, NULL, 'Tên các ngày trong tuần luôn phải viết hoa chữ cái đầu; dùng giới từ on trước chỉ một ngày cụ thể.', 'We usually meet for lunch at home on Thursday.', NULL, 'Chúng tôi thường gặp nhau ăn trưa ở nhà vào thứ Năm.', '{"wordId":"thursday","ukIpa":"/ˈθɜːzdeɪ/","usIpa":"/ˈθɝːzdeɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"the day after Wednesday and before Friday","vi":"ngày thứ năm"}],"examples":[{"en":"We usually meet for lunch at home on Thursday.","vi":"Chúng tôi thường gặp nhau ăn trưa ở nhà vào thứ Năm.","audioKind":"ex"},{"en":"The university will host a public discussion on sustainable transport next Thursday evening.","vi":"Trường đại học sẽ tổ chức một buổi thảo luận công khai về giao thông bền vững vào tối thứ Năm tới đây.","audioKind":"ex2"}],"collocations":[{"en":"on Thursday","vi":"vào thứ Năm"},{"en":"Thursday morning","vi":"sáng thứ Năm"},{"en":"every Thursday","vi":"mỗi thứ Năm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tên các ngày trong tuần luôn phải viết hoa chữ cái đầu; dùng giới từ on trước chỉ một ngày cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bedroom', 'en-a1-16', 'bedroom', '/ˈbedruːm/', 'A1', 'phòng ngủ', 'n.', NULL, NULL, 'Là danh từ đếm được; cụm từ a two-bedroom flat dùng để chỉ căn hộ có hai phòng ngủ.', 'My bedroom gets plenty of sunlight in the morning.', NULL, 'Phòng ngủ của tôi đón rất nhiều ánh nắng mặt trời vào buổi sáng.', '{"wordId":"bedroom","ukIpa":"/ˈbedruːm/","usIpa":"/ˈbedruːm/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A room used mainly for sleeping.","vi":"phòng ngủ"}],"examples":[{"en":"My bedroom gets plenty of sunlight in the morning.","vi":"Phòng ngủ của tôi đón rất nhiều ánh nắng mặt trời vào buổi sáng.","audioKind":"ex"},{"en":"Children who share a bedroom may develop cooperation skills, but they also need sufficient privacy as they grow.","vi":"Những đứa trẻ ở chung phòng ngủ có thể phát triển kỹ năng hợp tác, nhưng chúng cũng cần có đủ không gian riêng tư khi lớn lên.","audioKind":"ex2"}],"collocations":[{"en":"share a bedroom","vi":"chia sẻ phòng ngủ"},{"en":"main bedroom","vi":"phòng ngủ chính"},{"en":"spare bedroom","vi":"phòng ngủ phụ"},{"en":"bedroom furniture","vi":"nội thất phòng ngủ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ đếm được; cụm từ a two-bedroom flat dùng để chỉ căn hộ có hai phòng ngủ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clothes', 'en-a1-16', 'clothes', '/kloʊðz/', 'A1', 'quần áo; trang phục', 'n.', 'clothe (v.), clothing (n.)', 'Đồng nghĩa: clothing, garments', 'Từ này chỉ có hình thức số nhiều; nếu muốn nói một món đồ quần áo cụ thể, dùng an item of clothing.', 'Your clean clothes are drying outside in the sunshine.', NULL, 'Quần áo sạch của bạn đang phơi ngoài nắng kia kìa.', '{"wordId":"clothes","ukIpa":"/kləʊðz/","usIpa":"/kloʊðz/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"items worn to cover the body","vi":"quần áo; trang phục"}],"examples":[{"en":"Your clean clothes are drying outside in the sunshine.","vi":"Quần áo sạch của bạn đang phơi ngoài nắng kia kìa.","audioKind":"ex"},{"en":"Buying durable clothes rather than frequently replacing cheap garments can reduce household waste and save resources.","vi":"Việc mua những bộ quần áo bền bỉ thay vì liên tục thay mới những món đồ giá rẻ có thể giúp giảm thiểu rác thải sinh hoạt và tiết kiệm tài nguyên.","audioKind":"ex2"}],"collocations":[{"en":"casual clothes","vi":"quần áo thường ngày"},{"en":"clean clothes","vi":"quần áo sạch"},{"en":"change clothes","vi":"thay quần áo"},{"en":"try on clothes","vi":"thử quần áo"}],"wordFamily":["clothe (v.)","clothing (n.)"],"synonyms":["clothing","garments"],"antonyms":[],"tipVi":"Từ này chỉ có hình thức số nhiều; nếu muốn nói một món đồ quần áo cụ thể, dùng an item of clothing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_strong', 'en-a1-16', 'strong', '/strɔːŋ/', 'A1', 'khoẻ mạnh; vạm vỡ; bền chắc; vững chắc; mạnh mẽ; dữ dội; có sức thuyết phục cao', 'adj.', 'strength (n.), strengthen (v.), strongly (adv.)', 'Đồng nghĩa: powerful, sturdy · Trái nghĩa: weak', 'Cấu trúc strong at dùng để chỉ sự giỏi giang trong lĩnh vực gì; strong chủ yếu đóng vai trò là tính từ.', 'My brother is strong enough to lift this sofa.', NULL, 'Anh trai tôi đủ khỏe để nhấc bổng chiếc ghế sofa này.', '{"wordId":"strong","ukIpa":"/strɒŋ/","usIpa":"/strɔːŋ/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"having great physical power or force","vi":"khoẻ mạnh; vạm vỡ"},{"pos":"adj.","en":"not easily broken or damaged","vi":"bền chắc; vững chắc"},{"pos":"adj.","en":"great in intensity, influence, or convincing power","vi":"mạnh mẽ; dữ dội; có sức thuyết phục cao"}],"examples":[{"en":"My brother is strong enough to lift this sofa.","vi":"Anh trai tôi đủ khỏe để nhấc bổng chiếc ghế sofa này.","audioKind":"ex"},{"en":"There is strong evidence that regular physical activity improves both mental health and academic performance.","vi":"Có bằng chứng rõ ràng cho thấy việc vận động thể chất thường xuyên giúp cải thiện cả sức khỏe tinh thần lẫn kết quả học tập.","audioKind":"ex2"}],"collocations":[{"en":"strong evidence","vi":"bằng chứng xác thực"},{"en":"strong winds","vi":"gió mạnh"},{"en":"strong foundation","vi":"nền tảng vững chắc"},{"en":"strong at maths","vi":"giỏi toán"}],"wordFamily":["strength (n.)","strengthen (v.)","strongly (adv.)"],"synonyms":["powerful","sturdy"],"antonyms":["weak"],"tipVi":"Cấu trúc strong at dùng để chỉ sự giỏi giang trong lĩnh vực gì; strong chủ yếu đóng vai trò là tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_month', 'en-a1-16', 'month', '/mʌnθ/', 'A1', 'tháng', 'n.', 'monthly (adj.)', NULL, 'Trước last, next, every month thường không dùng giới từ.', 'I put aside a little money every month.', NULL, 'Tôi để dành một ít tiền mỗi tháng.', '{"wordId":"month","ukIpa":"/mʌnθ/","usIpa":"/mʌnθ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"one of twelve yearly divisions, or roughly four weeks","vi":"tháng"}],"examples":[{"en":"I put aside a little money every month.","vi":"Tôi để dành một ít tiền mỗi tháng.","audioKind":"ex"},{"en":"Offering employees one additional day off each month could improve wellbeing without significantly reducing overall productivity.","vi":"Việc cho phép nhân viên nghỉ thêm một ngày mỗi tháng có thể cải thiện sức khỏe tinh thần mà không làm giảm đáng kể năng suất tổng thể.","audioKind":"ex2"}],"collocations":[{"en":"last month","vi":"tháng trước"},{"en":"next month","vi":"tháng sau"},{"en":"once a month","vi":"mỗi tháng một lần"},{"en":"per month","vi":"mỗi tháng"}],"wordFamily":["monthly (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trước last, next, every month thường không dùng giới từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_let', 'en-a1-16', 'let', '/let/', 'A1', 'cho phép; để cho; cho thuê', 'v.', NULL, 'Đồng nghĩa: allow, permit · Trái nghĩa: forbid', 'Sau let sb do sth không dùng to; dạng quá khứ và phân từ hai đều là let.', 'Please let me know when you arrive home safely.', NULL, 'Hãy cho tôi biết khi bạn về đến nhà an toàn nhé.', '{"wordId":"let","ukIpa":"/let/","usIpa":"/let/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To allow someone to do something or something to happen.","vi":"cho phép; để cho"},{"pos":"v.","en":"To allow someone to use property in exchange for rent.","vi":"cho thuê"}],"examples":[{"en":"Please let me know when you arrive home safely.","vi":"Hãy cho tôi biết khi bạn về đến nhà an toàn nhé.","audioKind":"ex"},{"en":"Schools should let students explore different subjects before requiring them to choose a specialist pathway.","vi":"Các trường học nên để học sinh khám phá các môn học khác nhau trước khi yêu cầu các em chọn định hướng chuyên sâu.","audioKind":"ex2"}],"collocations":[{"en":"let someone know","vi":"cho ai đó biết"},{"en":"let someone in","vi":"cho ai đó vào"},{"en":"let a flat","vi":"cho thuê một căn hộ"},{"en":"let go of","vi":"buông bỏ; buông tay"}],"wordFamily":[],"synonyms":["allow","permit"],"antonyms":["forbid"],"tipVi":"Sau let sb do sth không dùng to; dạng quá khứ và phân từ hai đều là let.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_use', 'en-a1-16', 'use', '/juːz/, /juːs/', 'A1', 'sử dụng; dùng; sự sử dụng; việc tận dụng; công dụng; mục đích sử dụng', 'v.', 'user (n.), useful (adj.), useless (adj.), reusable (adj.)', 'Đồng nghĩa: employ, utilise', 'Động từ phát âm là /juːz/, danh từ phát âm là /juːs/.', 'Can I use your scissors to open this package?', NULL, 'Tôi có thể dùng kéo của bạn để mở gói hàng này không?', '{"wordId":"use","ukIpa":"/juːz/, /juːs/","usIpa":"/juːz/, /juːs/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To do something with a tool, resource, or method.","vi":"sử dụng; dùng"},{"pos":"n.","en":"The act of employing something for a purpose.","vi":"sự sử dụng; việc tận dụng"},{"pos":"n.","en":"A purpose something serves or a way it can help.","vi":"công dụng; mục đích sử dụng"}],"examples":[{"en":"Can I use your scissors to open this package?","vi":"Tôi có thể dùng kéo của bạn để mở gói hàng này không?","audioKind":"ex"},{"en":"Governments should encourage people to use public transport by making services more reliable and affordable.","vi":"Chính phủ nên khuyến khích người dân sử dụng phương tiện giao thông công cộng bằng cách làm cho dịch vụ trở nên đáng tin cậy và có giá cả phải chăng hơn.","audioKind":"ex2"}],"collocations":[{"en":"use public transport","vi":"sử dụng giao thông công cộng"},{"en":"make use of","vi":"tận dụng"},{"en":"in use","vi":"đang được sử dụng"},{"en":"a wide range of uses","vi":"nhiều công dụng đa dạng"}],"wordFamily":["user (n.)","useful (adj.)","useless (adj.)","reusable (adj.)"],"synonyms":["employ","utilise"],"antonyms":[],"tipVi":"Động từ phát âm là /juːz/, danh từ phát âm là /juːs/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_minute', 'en-a1-16', 'minute', '/ˈmɪnɪt/, /maɪˈnuːt/', 'A1', 'phút; chốc lát; biên bản cuộc họp; nhỏ bé; chi tiết tỉ mỉ', 'n.', 'minutely (adv.)', NULL, 'Biên bản cuộc họp dùng dạng số nhiều minutes; tính từ chỉ sự nhỏ bé có trọng âm rơi vào âm tiết sau.', 'Wait a minute while I find my keys.', NULL, 'Đợi một chút để tôi tìm chìa khóa nhé.', '{"wordId":"minute","ukIpa":"/ˈmɪnɪt/, /maɪˈnjuːt/","usIpa":"/ˈmɪnɪt/, /maɪˈnuːt/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A period of sixty seconds, or a very short time","vi":"phút; chốc lát"},{"pos":"n.","en":"A written record of what happened at a meeting","vi":"biên bản cuộc họp"},{"pos":"adj.","en":"Extremely small in size or amount","vi":"nhỏ bé; chi tiết tỉ mỉ"}],"examples":[{"en":"Wait a minute while I find my keys.","vi":"Đợi một chút để tôi tìm chìa khóa nhé.","audioKind":"ex"},{"en":"Even a minute of regular classroom discussion can encourage students to reflect on what they have learned.","vi":"Ngay cả một phút thảo luận thông thường trên lớp cũng có thể khuyến khích học sinh suy ngẫm về những gì các em đã học.","audioKind":"ex2"}],"collocations":[{"en":"a few minutes","vi":"vài phút"},{"en":"at the last minute","vi":"vào phút chót"},{"en":"take the minutes","vi":"lập biên bản cuộc họp"},{"en":"minute details","vi":"những chi tiết tỉ mỉ"}],"wordFamily":["minutely (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Biên bản cuộc họp dùng dạng số nhiều minutes; tính từ chỉ sự nhỏ bé có trọng âm rơi vào âm tiết sau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_even', 'en-a1-16', 'even', '/ˈiːvən/', 'A1', 'thậm chí; ngay cả; bằng phẳng; đều đặn; ngang bằng; chẵn', 'adv.', 'evenly (adv.), evenness (n.), uneven (adj.)', NULL, 'even if dùng cho giả định "thậm chí nếu"; even though dùng cho sự thật "mặc dù".', 'Everyone joined the dance, even our shy uncle.', NULL, 'Mọi người đều tham gia nhảy múa, thậm chí cả người chú nhút nhát của chúng tôi.', '{"wordId":"even","ukIpa":"/ˈiːvən/","usIpa":"/ˈiːvən/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"Used to emphasise something surprising or unexpected.","vi":"thậm chí; ngay cả"},{"pos":"adj.","en":"Flat, regular, or equal in amount or level.","vi":"bằng phẳng; đều đặn; ngang bằng"},{"pos":"adj.","en":"Divisible by two without leaving a remainder.","vi":"chẵn"}],"examples":[{"en":"Everyone joined the dance, even our shy uncle.","vi":"Mọi người đều tham gia nhảy múa, thậm chí cả người chú nhút nhát của chúng tôi.","audioKind":"ex"},{"en":"Even small improvements in public transport can make daily travel easier for people with limited mobility.","vi":"Ngay cả những cải thiện nhỏ trong giao thông công cộng cũng có thể giúp việc đi lại hàng ngày trở nên dễ dàng hơn đối với những người bị hạn chế khả năng đi lại.","audioKind":"ex2"}],"collocations":[{"en":"even if","vi":"ngay cả khi; dù cho"},{"en":"even though","vi":"mặc dù"},{"en":"even better","vi":"tốt hơn nữa"},{"en":"an even number","vi":"một số chẵn"}],"wordFamily":["evenly (adv.)","evenness (n.)","uneven (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"even if dùng cho giả định \"thậm chí nếu\"; even though dùng cho sự thật \"mặc dù\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_o-clock', 'en-a1-16', 'o''clock', '/əˈklɑːk/', 'A1', 'đúng... giờ (giờ chẵn)', 'adv.', NULL, NULL, 'Chỉ dùng cho giờ chẵn; viết là o''clock, không dùng gạch nối.', 'Please meet me outside the library at three o''clock.', NULL, 'Hãy gặp tôi bên ngoài thư viện lúc ba giờ đúng nhé.', '{"wordId":"o-clock","ukIpa":"/əˈklɒk/","usIpa":"/əˈklɑːk/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"Used after a number to give the exact hour.","vi":"đúng... giờ (giờ chẵn)"}],"examples":[{"en":"Please meet me outside the library at three o''clock.","vi":"Hãy gặp tôi bên ngoài thư viện lúc ba giờ đúng nhé.","audioKind":"ex"},{"en":"Starting school at nine o''clock rather than earlier may help teenagers concentrate better during morning lessons.","vi":"Việc bắt đầu đi học lúc chín giờ thay vì sớm hơn có thể giúp thanh niên tập trung tốt hơn trong các tiết học buổi sáng.","audioKind":"ex2"}],"collocations":[{"en":"at six o''clock","vi":"vào lúc sáu giờ đúng"},{"en":"around eight o''clock","vi":"khoảng tám giờ"},{"en":"by ten o''clock","vi":"trước mười giờ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ dùng cho giờ chẵn; viết là o''clock, không dùng gạch nối.","noteVi":"Đã đổi cách viết phi tiêu chuẩn o-clock thành o''clock.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cut', 'en-a1-16', 'cut', '/kʌt/', 'A1', 'cắt; thái; chặt; cắt giảm; giảm bớt; vết cắt; sự cắt giảm', 'v.', 'cutting (n.), cutter (n.)', NULL, 'Dạng quá khứ và phân từ hai đều là cut; phân từ hiện đại là cutting.', 'She cut the apple into slices for her brother.', NULL, 'Cô ấy cắt quả táo thành từng lát cho em trai ăn.', '{"wordId":"cut","ukIpa":"/kʌt/","usIpa":"/kʌt/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"divide or remove something using a sharp tool","vi":"cắt; thái; chặt"},{"pos":"v.","en":"reduce the amount, size, or length of something","vi":"cắt giảm; giảm bớt"},{"pos":"n.","en":"an opening made by something sharp, or a reduction","vi":"vết cắt; sự cắt giảm"}],"examples":[{"en":"She cut the apple into slices for her brother.","vi":"Cô ấy cắt quả táo thành từng lát cho em trai ăn.","audioKind":"ex"},{"en":"Local councils can cut energy costs by installing efficient lighting in public buildings.","vi":"Các hội đồng địa phương có thể cắt giảm chi phí năng lượng bằng cách lắp đặt hệ thống chiếu sáng hiệu quả trong các tòa nhà công cộng.","audioKind":"ex2"}],"collocations":[{"en":"cut into pieces","vi":"cắt thành từng miếng"},{"en":"cut costs","vi":"cắt giảm chi phí"},{"en":"cut down on","vi":"giảm bớt; cắt giảm"}],"wordFamily":["cutting (n.)","cutter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ và phân từ hai đều là cut; phân từ hiện đại là cutting.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wake', 'en-a1-16', 'wake', '/weɪk/', 'A1', 'thức dậy; đánh thức; dòng nước xoáy phía sau thuyền; lễ tang; lễ thức đêm cầu hồn', 'v.', 'awake (adj.), awaken (v.), wakeful (adj.)', 'Đồng nghĩa: awaken', 'Quá khứ woke, quá khứ phân từ woken; thường đi kèm với up.', 'Please wake me before you leave for work.', NULL, 'Xin hãy đánh thức tôi trước khi bạn đi làm.', '{"wordId":"wake","ukIpa":"/weɪk/","usIpa":"/weɪk/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to stop sleeping, or make someone stop sleeping","vi":"thức dậy; đánh thức"},{"pos":"n.","en":"the disturbed water left behind a moving boat","vi":"dòng nước xoáy phía sau thuyền"},{"pos":"n.","en":"a gathering to remember someone who has recently died","vi":"lễ tang; lễ thức đêm cầu hồn"}],"examples":[{"en":"Please wake me before you leave for work.","vi":"Xin hãy đánh thức tôi trước khi bạn đi làm.","audioKind":"ex"},{"en":"People who wake at consistent times may find it easier to maintain healthy sleep patterns.","vi":"Những người thức dậy vào những khung giờ cố định có thể dễ dàng duy trì nhịp sinh học lành mạnh hơn.","audioKind":"ex2"}],"collocations":[{"en":"wake up","vi":"thức dậy; đánh thức"},{"en":"wake someone","vi":"đánh thức ai đó"},{"en":"in the wake of","vi":"ngay sau; do ảnh hưởng của"}],"wordFamily":["awake (adj.)","awaken (v.)","wakeful (adj.)"],"synonyms":["awaken"],"antonyms":[],"tipVi":"Quá khứ woke, quá khứ phân từ woken; thường đi kèm với up.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_juice', 'en-a1-16', 'juice', '/dʒuːs/', 'A1', 'nước ép trái cây; nước ép rau củ', 'n.', 'juicy (adj.), juicer (n.)', NULL, 'juice thường không đếm được; khi gọi món, a juice có thể dùng để chỉ một cốc nước ép.', 'She squeezed fresh orange juice into a glass.', NULL, 'Cô ấy vắt nước cam tươi vào một chiếc cốc.', '{"wordId":"juice","ukIpa":"/dʒuːs/","usIpa":"/dʒuːs/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"liquid obtained from fruit or vegetables","vi":"nước ép trái cây; nước ép rau củ"}],"examples":[{"en":"She squeezed fresh orange juice into a glass.","vi":"Cô ấy vắt nước cam tươi vào một chiếc cốc.","audioKind":"ex"},{"en":"Although fruit juice contains vitamins, eating whole fruit usually provides more fibre and helps limit sugar intake.","vi":"Mặc dù nước ép trái cây chứa vitamin, nhưng việc ăn nguyên quả thường cung cấp nhiều chất xơ hơn và giúp hạn chế lượng đường nạp vào.","audioKind":"ex2"}],"collocations":[{"en":"freshly squeezed juice","vi":"nước ép tươi"},{"en":"orange juice","vi":"nước cam"},{"en":"lemon juice","vi":"nước chanh"}],"wordFamily":["juicy (adj.)","juicer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"juice thường không đếm được; khi gọi món, a juice có thể dùng để chỉ một cốc nước ép.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_really', 'en-a1-16', 'really', '/ˈriːəli/', 'A1', 'rất; vô cùng; thực sự; trên thực tế; thật sao; thực sự ư', 'adv.', 'real (adj.), reality (n.), realistic (adj.)', 'Đồng nghĩa: actually, truly, very', 'not really thường có nghĩa là "không hẳn", mang sắc thái nhẹ nhàng hơn so với việc từ chối thẳng thừng là no.', 'This soup is really hot, so let it cool.', NULL, 'Món súp này rất nóng, hãy để nó nguội bớt đã.', '{"wordId":"really","ukIpa":"/ˈrɪəli/","usIpa":"/ˈriːəli/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"Used to make an adjective, adverb, or statement stronger.","vi":"rất; vô cùng"},{"pos":"adv.","en":"In fact, rather than only apparently or supposedly.","vi":"thực sự; trên thực tế"},{"pos":"adv.","en":"Used in questions to express surprise or doubt.","vi":"thật sao; thực sự ư"}],"examples":[{"en":"This soup is really hot, so let it cool.","vi":"Món súp này rất nóng, hãy để nó nguội bớt đã.","audioKind":"ex"},{"en":"Before expanding online education, policymakers should consider whether digital courses really meet the needs of disadvantaged learners.","vi":"Trước khi mở rộng giáo dục trực tuyến, các nhà hoạch định chính sách nên cân nhắc xem các khóa học kỹ thuật số có thực sự đáp ứng nhu cầu của người học yếu thế hay không.","audioKind":"ex2"}],"collocations":[{"en":"really useful","vi":"rất hữu ích"},{"en":"really enjoy","vi":"rất thích"},{"en":"not really","vi":"không hẳn; thực ra là không"}],"wordFamily":["real (adj.)","reality (n.)","realistic (adj.)"],"synonyms":["actually","truly","very"],"antonyms":[],"tipVi":"not really thường có nghĩa là \"không hẳn\", mang sắc thái nhẹ nhàng hơn so với việc từ chối thẳng thừng là no.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lunch', 'en-a1-16', 'lunch', '/lʌntʃ/', 'A1', 'bữa trưa; ăn trưa', 'n.', 'lunchtime (n.)', NULL, 'Khi nói chung chung về việc ăn trưa, dùng have lunch và thường không đi kèm mạo từ.', 'We ate lunch under a tree beside the river.', NULL, 'Chúng tôi đã ăn trưa dưới gốc cây bên bờ sông.', '{"wordId":"lunch","ukIpa":"/lʌntʃ/","usIpa":"/lʌntʃ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a meal eaten around the middle of the day","vi":"bữa trưa"},{"pos":"v.","en":"to eat a meal around midday","vi":"ăn trưa"}],"examples":[{"en":"We ate lunch under a tree beside the river.","vi":"Chúng tôi đã ăn trưa dưới gốc cây bên bờ sông.","audioKind":"ex"},{"en":"Providing nutritious school lunches can improve children''s concentration and support healthier eating habits over time.","vi":"Việc cung cấp các bữa trưa học đường đầy đủ dinh dưỡng có thể cải thiện sự tập trung của trẻ em và duy trì thói quen ăn uống lành mạnh hơn theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"have lunch","vi":"ăn trưa"},{"en":"lunch break","vi":"giờ nghỉ trưa"},{"en":"packed lunch","vi":"cơm hộp mang theo"},{"en":"school lunch","vi":"bữa trưa ở trường"}],"wordFamily":["lunchtime (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi nói chung chung về việc ăn trưa, dùng have lunch và thường không đi kèm mạo từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tall', 'en-a1-16', 'tall', '/tɔːl/', 'A1', 'cao; cao lớn', 'adj.', 'tallness (n.)', 'Trái nghĩa: short', 'Con người, cây cối và các tòa nhà thường dùng tall; đối với núi, người ta thường dùng high.', 'A tall tree shades our garden in the afternoon.', NULL, 'Một cái cây cao tạo bóng râm cho khu vườn của chúng tôi vào buổi chiều.', '{"wordId":"tall","ukIpa":"/tɔːl/","usIpa":"/tɔːl/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"having greater than average height","vi":"cao; cao lớn"}],"examples":[{"en":"A tall tree shades our garden in the afternoon.","vi":"Một cái cây cao tạo bóng râm cho khu vườn của chúng tôi vào buổi chiều.","audioKind":"ex"},{"en":"Tall buildings can accommodate more residents, but careful planning is needed to preserve sunlight and public space.","vi":"Các tòa nhà cao tầng có thể chứa được nhiều cư dân hơn, nhưng cần phải có quy hoạch cẩn thận để giữ gìn ánh sáng tự nhiên và không gian công cộng.","audioKind":"ex2"}],"collocations":[{"en":"a tall building","vi":"tòa nhà cao tầng"},{"en":"a tall tree","vi":"cây cao"},{"en":"grow tall","vi":"trở nên cao lớn"},{"en":"stand tall","vi":"đứng thẳng"}],"wordFamily":["tallness (n.)"],"synonyms":[],"antonyms":["short"],"tipVi":"Con người, cây cối và các tòa nhà thường dùng tall; đối với núi, người ta thường dùng high.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_also', 'en-a1-16', 'also', '/ˈɔːlsoʊ/', 'A1', 'ngoài ra; cũng', 'adv.', NULL, 'Đồng nghĩa: too, additionally', 'Thường đặt trước động từ thường, sau động từ ''be''; không phải là liên từ.', 'My sister plays tennis and also enjoys swimming.', NULL, 'Chị gái tôi chơi quần vợt và cũng thích bơi lội.', '{"wordId":"also","ukIpa":"/ˈɔːlsəʊ/","usIpa":"/ˈɔːlsoʊ/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"in addition to something already mentioned","vi":"ngoài ra; cũng"}],"examples":[{"en":"My sister plays tennis and also enjoys swimming.","vi":"Chị gái tôi chơi quần vợt và cũng thích bơi lội.","audioKind":"ex"},{"en":"Public libraries provide free books, but they also offer valuable spaces for community learning.","vi":"Các thư viện công cộng cung cấp sách miễn phí, đồng thời họ cũng mang đến những không gian quý giá cho việc học tập của cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"also available","vi":"cũng có sẵn"},{"en":"also known as","vi":"còn được gọi là"},{"en":"not only ... but also","vi":"không những... mà còn"}],"wordFamily":[],"synonyms":["too","additionally"],"antonyms":[],"tipVi":"Thường đặt trước động từ thường, sau động từ ''be''; không phải là liên từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coat', 'en-a1-16', 'coat', '/koʊt/', 'A1', 'áo khoác; áo choàng; lớp sơn; lớp phủ; phủ; tráng; bôi một lớp', 'n.', 'coating (n.)', NULL, 'Động từ thường dùng ''coat A with B'', nghĩa là phủ lên A một lớp B.', 'Hang your wet coat by the kitchen door.', NULL, 'Hãy treo chiếc áo khoác bị ướt của bạn cạnh cửa bếp.', '{"wordId":"coat","ukIpa":"/kəʊt/","usIpa":"/koʊt/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"an outer garment worn for warmth or protection","vi":"áo khoác; áo choàng"},{"pos":"n.","en":"a layer of paint or another covering substance","vi":"lớp sơn; lớp phủ"},{"pos":"v.","en":"cover a surface with a layer of something","vi":"phủ; tráng; bôi một lớp"}],"examples":[{"en":"Hang your wet coat by the kitchen door.","vi":"Hãy treo chiếc áo khoác bị ướt của bạn cạnh cửa bếp.","audioKind":"ex"},{"en":"Applying a protective coat to metal structures can reduce maintenance costs and extend their useful life.","vi":"Việc phủ một lớp bảo vệ lên các cấu trúc kim loại có thể làm giảm chi phí bảo trì và kéo dài tuổi thọ của chúng.","audioKind":"ex2"}],"collocations":[{"en":"winter coat","vi":"áo khoác mùa đông"},{"en":"a coat of paint","vi":"một lớp sơn"},{"en":"coat with chocolate","vi":"nhúng phủ sô-cô-la"}],"wordFamily":["coating (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ thường dùng ''coat A with B'', nghĩa là phủ lên A một lớp B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fast', 'en-a1-16', 'fast', '/fæst/', 'A1', 'nhanh; cao tốc; nhanh chóng; mau; nhịn ăn; ăn chay tịnh', 'adj.', 'fasting (n.)', 'Đồng nghĩa: quick, rapid · Trái nghĩa: slow', 'Bản thân ''fast'' đã có thể làm phó từ, không dùng dạng ''fastly''.', 'We caught a fast train and arrived before lunch.', NULL, 'Chúng tôi đã bắt một chuyến tàu nhanh và đến nơi trước bữa trưa.', '{"wordId":"fast","ukIpa":"/fɑːst/","usIpa":"/fæst/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"moving or happening at high speed","vi":"nhanh; cao tốc"},{"pos":"adv.","en":"at high speed or within a short time","vi":"nhanh chóng; mau"},{"pos":"v.","en":"to eat no food for a period of time","vi":"nhịn ăn; ăn chay tịnh"}],"examples":[{"en":"We caught a fast train and arrived before lunch.","vi":"Chúng tôi đã bắt một chuyến tàu nhanh và đến nơi trước bữa trưa.","audioKind":"ex"},{"en":"Fast internet connections allow rural businesses to reach wider markets and compete with companies in major cities.","vi":"Kết nối internet tốc độ cao cho phép các doanh nghiệp nông thôn tiếp cận thị trường rộng lớn hơn và cạnh tranh với các công ty ở các thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"a fast train","vi":"một chuyến tàu nhanh"},{"en":"grow fast","vi":"phát triển nhanh"},{"en":"fast food","vi":"đồ ăn nhanh"},{"en":"fast asleep","vi":"ngủ say"}],"wordFamily":["fasting (n.)"],"synonyms":["quick","rapid"],"antonyms":["slow"],"tipVi":"Bản thân ''fast'' đã có thể làm phó từ, không dùng dạng ''fastly''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_from', 'en-a1-16', 'from', '/frʌm/', 'A1', 'từ; đến từ; do; vì; khác với; cách', 'prep.', NULL, NULL, 'from biểu thị điểm khởi đầu, thường đi kèm với to biểu thị điểm kết thúc.', 'This postcard came from my cousin in the mountains.', NULL, 'Tấm bưu ảnh này được gửi từ người anh họ ở miền núi của tôi.', '{"wordId":"from","ukIpa":"/frɒm/","usIpa":"/frʌm/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"showing where someone or something starts or originates","vi":"từ; đến từ"},{"pos":"prep.","en":"showing what causes something","vi":"do; vì"},{"pos":"prep.","en":"showing separation, difference, or distance","vi":"khác với; cách"}],"examples":[{"en":"This postcard came from my cousin in the mountains.","vi":"Tấm bưu ảnh này được gửi từ người anh họ ở miền núi của tôi.","audioKind":"ex"},{"en":"Students from rural communities may face additional barriers when applying to universities in major cities.","vi":"Học sinh đến từ các vùng nông thôn có thể phải đối mặt với những rào cản bổ sung khi nộp hồ sơ vào các trường đại học ở các thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"from time to time","vi":"thỉnh thoảng"},{"en":"suffer from","vi":"mắc bệnh; chịu đựng"},{"en":"different from","vi":"khác với"},{"en":"from start to finish","vi":"từ đầu đến cuối"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"from biểu thị điểm khởi đầu, thường đi kèm với to biểu thị điểm kết thúc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quickly', 'en-a1-16', 'quickly', '/ˈkwɪkli/', 'A1', 'nhanh chóng; một cách nhanh chóng', 'adv.', 'quick (adj.), quickness (n.), quicken (v.)', 'Đồng nghĩa: rapidly, swiftly · Trái nghĩa: slowly', 'quickly là trạng từ bổ nghĩa cho hành động; quick là tính từ bổ nghĩa cho danh từ.', 'We quickly packed our bags when the taxi arrived.', NULL, 'Chúng tôi nhanh chóng thu dọn hành lý khi xe taxi đến.', '{"wordId":"quickly","ukIpa":"/ˈkwɪkli/","usIpa":"/ˈkwɪkli/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"At a fast speed or after only a short time.","vi":"nhanh chóng; một cách nhanh chóng"}],"examples":[{"en":"We quickly packed our bags when the taxi arrived.","vi":"Chúng tôi nhanh chóng thu dọn hành lý khi xe taxi đến.","audioKind":"ex"},{"en":"Cities must respond quickly to extreme weather events to protect vulnerable residents and maintain essential services.","vi":"Các thành phố phải phản ứng nhanh chóng với các hiện tượng thời tiết cực đoan để bảo vệ cư dân dễ bị tổn thương và duy trì các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"respond quickly","vi":"phản ứng nhanh chóng"},{"en":"act quickly","vi":"hành động nhanh chóng"},{"en":"learn quickly","vi":"tiếp thu nhanh"},{"en":"as quickly as possible","vi":"càng nhanh càng tốt"}],"wordFamily":["quick (adj.)","quickness (n.)","quicken (v.)"],"synonyms":["rapidly","swiftly"],"antonyms":["slowly"],"tipVi":"quickly là trạng từ bổ nghĩa cho hành động; quick là tính từ bổ nghĩa cho danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_activity', 'en-a1-16', 'activity', '/ækˈtɪvəti/', 'A1', 'hoạt động; sự bận rộn; mức độ hoạt động', 'n.', 'active (adj.), actively (adv.), inactive (adj.), activate (v.)', 'Trái nghĩa: inactivity', 'Hoạt động cụ thể thì đếm được; khi chỉ sự náo nhiệt hoặc mức độ hoạt động chung thì không đếm được.', 'Painting is my favourite activity on rainy afternoons.', NULL, 'Vẽ tranh là hoạt động yêu thích của tôi vào những buổi chiều mưa.', '{"wordId":"activity","ukIpa":"/ækˈtɪvəti/","usIpa":"/ækˈtɪvəti/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"Something people do for enjoyment, learning, or a particular purpose.","vi":"hoạt động"},{"pos":"n.","en":"The state of being busy or doing things.","vi":"sự bận rộn; mức độ hoạt động"}],"examples":[{"en":"Painting is my favourite activity on rainy afternoons.","vi":"Vẽ tranh là hoạt động yêu thích của tôi vào những buổi chiều mưa.","audioKind":"ex"},{"en":"Regular physical activity can improve mental health and reduce the risk of several long-term illnesses.","vi":"Hoạt động thể chất thường xuyên có thể cải thiện sức khỏe tinh thần và giảm nguy cơ mắc một số bệnh mãn tính.","audioKind":"ex2"}],"collocations":[{"en":"physical activity","vi":"hoạt động thể chất"},{"en":"outdoor activities","vi":"hoạt động ngoài trời"},{"en":"economic activity","vi":"hoạt động kinh tế"},{"en":"leisure activities","vi":"hoạt động giải trí"}],"wordFamily":["active (adj.)","actively (adv.)","inactive (adj.)","activate (v.)"],"synonyms":[],"antonyms":["inactivity"],"tipVi":"Hoạt động cụ thể thì đếm được; khi chỉ sự náo nhiệt hoặc mức độ hoạt động chung thì không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_without', 'en-a1-16', 'without', '/wɪˈðaʊt/', 'A1', 'không; không có; không mang theo; không làm gì', 'prep.', NULL, 'Trái nghĩa: with', 'without là giới từ, theo sau bởi danh từ, đại từ hoặc động từ thêm đuôi -ing.', 'I left the house without my keys this morning.', NULL, 'Sáng nay tôi rời khỏi nhà mà không mang theo chìa khóa.', '{"wordId":"without","ukIpa":"/wɪˈðaʊt/","usIpa":"/wɪˈðaʊt/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"not having, using, or being accompanied by someone or something","vi":"không; không có; không mang theo"},{"pos":"prep.","en":"not doing the action mentioned","vi":"không làm gì"}],"examples":[{"en":"I left the house without my keys this morning.","vi":"Sáng nay tôi rời khỏi nhà mà không mang theo chìa khóa.","audioKind":"ex"},{"en":"Cities cannot achieve lasting reductions in air pollution without investing in reliable public transport.","vi":"Các thành phố không thể đạt được sự giảm thiểu ô nhiễm không khí bền vững nếu không đầu tư vào hệ thống giao thông công cộng đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"without doubt","vi":"không còn nghi ngờ gì"},{"en":"without permission","vi":"không có sự cho phép"},{"en":"without delay","vi":"ngay lập tức; không chậm trễ"},{"en":"without saying a word","vi":"nói không nên lời"}],"wordFamily":[],"synonyms":[],"antonyms":["with"],"tipVi":"without là giới từ, theo sau bởi danh từ, đại từ hoặc động từ thêm đuôi -ing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nothing', 'en-a1-16', 'nothing', '/ˈnʌθɪŋ/', 'A1', 'không có gì; không điều gì; hoàn toàn không', 'pron.', NULL, 'Trái nghĩa: something', 'nothing bản thân nó đã mang nghĩa phủ định, thông thường không dùng chung với từ not nữa.', 'I opened the fridge, but there was nothing inside.', NULL, 'Tôi mở tủ lạnh ra nhưng bên trong chẳng có gì cả.', '{"wordId":"nothing","ukIpa":"/ˈnʌθɪŋ/","usIpa":"/ˈnʌθɪŋ/","cefr":"A1","topic":"daily","senses":[{"pos":"pron.","en":"not anything; no thing at all","vi":"không có gì; không điều gì"},{"pos":"adv.","en":"not at all, used to strengthen certain comparisons","vi":"hoàn toàn không"}],"examples":[{"en":"I opened the fridge, but there was nothing inside.","vi":"Tôi mở tủ lạnh ra nhưng bên trong chẳng có gì cả.","audioKind":"ex"},{"en":"Without affordable public transport, some residents have nothing to rely on except their own cars.","vi":"Nếu không có giao thông công cộng giá cả phải chăng, một số cư dân chẳng có gì để dựa vào ngoài chiếc ô tô của chính họ.","audioKind":"ex2"}],"collocations":[{"en":"nothing to do with","vi":"không liên quan gì đến"},{"en":"nothing but","vi":"chỉ là; không gì khác ngoài"},{"en":"nothing like","vi":"hoàn toàn không giống"},{"en":"for nothing","vi":"miễn phí; công cốc"}],"wordFamily":[],"synonyms":[],"antonyms":["something"],"tipVi":"nothing bản thân nó đã mang nghĩa phủ định, thông thường không dùng chung với từ not nữa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tuesday', 'en-a1-16', 'Tuesday', '/ˈtuːzdeɪ/', 'A1', 'thứ Ba', 'n.', NULL, NULL, 'Tên các ngày trong tuần phải viết hoa chữ cái đầu; trước every Tuesday không dùng giới từ on.', 'We usually have dinner together on Tuesday evenings.', NULL, 'Chúng tôi thường ăn tối cùng nhau vào các tối thứ Ba.', '{"wordId":"tuesday","ukIpa":"/ˈtjuːzdeɪ/","usIpa":"/ˈtuːzdeɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"the day after Monday and before Wednesday","vi":"thứ Ba"}],"examples":[{"en":"We usually have dinner together on Tuesday evenings.","vi":"Chúng tôi thường ăn tối cùng nhau vào các tối thứ Ba.","audioKind":"ex"},{"en":"The community centre offers free language classes every Tuesday to help newcomers settle into the area.","vi":"Trung tâm cộng đồng cung cấp các lớp học ngôn ngữ miễn phí vào mỗi thứ Ba để giúp những người mới đến hòa nhập với khu vực này.","audioKind":"ex2"}],"collocations":[{"en":"on Tuesday","vi":"vào thứ Ba"},{"en":"Tuesday morning","vi":"sáng thứ Ba"},{"en":"every Tuesday","vi":"mỗi thứ Ba"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tên các ngày trong tuần phải viết hoa chữ cái đầu; trước every Tuesday không dùng giới từ on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hat', 'en-a1-16', 'hat', '/hæt/', 'A1', 'mũ; nón', 'n.', 'hatless (adj.)', NULL, 'Đang đội mũ thì dùng động từ wear; hành động đội mũ lên đầu thì dùng put on.', 'I grabbed my hat before stepping into the sunshine.', NULL, 'Tôi vớ lấy chiếc mũ của mình trước khi bước ra ánh nắng.', '{"wordId":"hat","ukIpa":"/hæt/","usIpa":"/hæt/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a covering worn on the head for protection or decoration","vi":"mũ; nón"}],"examples":[{"en":"I grabbed my hat before stepping into the sunshine.","vi":"Tôi vớ lấy chiếc mũ của mình trước khi bước ra ánh nắng.","audioKind":"ex"},{"en":"Wearing a wide-brimmed hat can reduce sun exposure, particularly for people who spend long hours working outdoors.","vi":"Đội một chiếc mũ rộng vành có thể làm giảm tác hại của ánh nắng mặt trời, đặc biệt đối với những người làm việc ngoài trời trong thời gian dài.","audioKind":"ex2"}],"collocations":[{"en":"wear a hat","vi":"đội mũ"},{"en":"wide-brimmed hat","vi":"mũ rộng vành"},{"en":"sun hat","vi":"mũ chống nắng"},{"en":"take off your hat","vi":"bỏ mũ ra; ngả mũ"}],"wordFamily":["hatless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Đang đội mũ thì dùng động từ wear; hành động đội mũ lên đầu thì dùng put on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chips', 'en-a1-16', 'chips', '/tʃɪps/', 'A1', 'khoai tây chiên (tiếng Anh Anh); khoai tây lát mỏng (tiếng Anh Mỹ); mảnh vụn; mảnh vỡ nhỏ; vi mạch; chip điện tử', 'n.', 'chip (n.), chip (v.)', NULL, 'Tiếng Anh Anh dùng chips là khoai tây chiên, crisps là bim bim; tiếng Anh Mỹ gọi khoai tây chiên là fries.', 'These chips are crispy outside and soft in the middle.', NULL, 'Mấy miếng khoai tây chiên này giòn ở bên ngoài và mềm ở bên trong.', '{"wordId":"chips","ukIpa":"/tʃɪps/","usIpa":"/tʃɪps/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"fried potato strips in British English; thin slices in American English","vi":"khoai tây chiên (tiếng Anh Anh); khoai tây lát mỏng (tiếng Anh Mỹ)"},{"pos":"n.","en":"small pieces broken or cut off a larger object","vi":"mảnh vụn; mảnh vỡ nhỏ"},{"pos":"n.","en":"tiny electronic components containing circuits that process or store information","vi":"vi mạch; chip điện tử"}],"examples":[{"en":"These chips are crispy outside and soft in the middle.","vi":"Mấy miếng khoai tây chiên này giòn ở bên ngoài và mềm ở bên trong.","audioKind":"ex"},{"en":"Schools can encourage healthier eating by replacing chips with vegetables and other nutritious side dishes.","vi":"Nhà trường có thể khuyến khích chế độ ăn uống lành mạnh hơn bằng cách thay thế khoai tây chiên bằng rau củ và các món ăn kèm giàu dinh dưỡng khác.","audioKind":"ex2"}],"collocations":[{"en":"fish and chips","vi":"món cá và khoai tây chiên"},{"en":"wood chips","vi":"mạt gỗ; dăm gỗ"},{"en":"computer chips","vi":"chip máy tính"}],"wordFamily":["chip (n.)","chip (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Anh Anh dùng chips là khoai tây chiên, crisps là bim bim; tiếng Anh Mỹ gọi khoai tây chiên là fries.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_keep', 'en-a1-16', 'keep', '/kiːp/', 'A1', 'giữ lại; bảo quản; giữ cho; duy trì; tiếp tục làm gì đó; lặp đi lặp lại', 'v.', 'keeper (n.), keeping (n.)', 'Đồng nghĩa: retain', 'Dạng quá khứ và phân từ hai đều là kept; cấu trúc tiếp tục làm gì dùng keep doing.', 'You can keep the umbrella until the rain stops.', NULL, 'Bạn có thể giữ chiếc ô này cho đến khi trời tạnh mưa.', '{"wordId":"keep","ukIpa":"/kiːp/","usIpa":"/kiːp/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To continue having something rather than giving it away.","vi":"giữ lại; bảo quản"},{"pos":"v.","en":"To stay, or make something stay, in a particular state.","vi":"giữ cho; duy trì"},{"pos":"v.","en":"To continue doing something or do it repeatedly.","vi":"tiếp tục làm gì đó; lặp đi lặp lại"}],"examples":[{"en":"You can keep the umbrella until the rain stops.","vi":"Bạn có thể giữ chiếc ô này cho đến khi trời tạnh mưa.","audioKind":"ex"},{"en":"Governments should keep public transport affordable to encourage residents to leave their cars at home.","vi":"Chính phủ nên giữ cho giá cước giao thông công cộng ở mức hợp lý để khuyến khích người dân không lái xe hơi cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"keep a record","vi":"lưu giữ hồ sơ"},{"en":"keep in touch","vi":"giữ liên lạc"},{"en":"keep doing something","vi":"tiếp tục làm việc gì"},{"en":"keep a promise","vi":"giữ lời hứa"}],"wordFamily":["keeper (n.)","keeping (n.)"],"synonyms":["retain"],"antonyms":[],"tipVi":"Dạng quá khứ và phân từ hai đều là kept; cấu trúc tiếp tục làm gì dùng keep doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 28, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_16_1', 'en-a1-16', 'Cách dùng “really” (adv.) — rất; vô cùng', 'really useful  ·  really enjoy  ·  not really', 'not really thường có nghĩa là "không hẳn", mang sắc thái nhẹ nhàng hơn so với việc từ chối thẳng thừng là no.', 'Họ từ (Word Family): real (adj.), reality (n.), realistic (adj.) | Đồng nghĩa: actually, truly, very', '[{"hanzi":"This soup is really hot, so let it cool.","pinyin":"","meaning":"Món súp này rất nóng, hãy để nó nguội bớt đã."},{"hanzi":"Before expanding online education, policymakers should consider whether digital courses really meet the needs of disadvantaged learners.","pinyin":"","meaning":"Trước khi mở rộng giáo dục trực tuyến, các nhà hoạch định chính sách nên cân nhắc xem các khóa học kỹ thuật số có thực sự đáp ứng nhu cầu của người học yếu thế hay không."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_16_2', 'en-a1-16', 'Cách dùng “chips” (n.) — khoai tây chiên (tiếng Anh Anh); khoai tây lát mỏng (tiếng Anh Mỹ)', 'fish and chips  ·  wood chips  ·  computer chips', 'Tiếng Anh Anh dùng chips là khoai tây chiên, crisps là bim bim; tiếng Anh Mỹ gọi khoai tây chiên là fries.', 'Họ từ (Word Family): chip (n.), chip (v.)', '[{"hanzi":"These chips are crispy outside and soft in the middle.","pinyin":"","meaning":"Mấy miếng khoai tây chiên này giòn ở bên ngoài và mềm ở bên trong."},{"hanzi":"Schools can encourage healthier eating by replacing chips with vegetables and other nutritious side dishes.","pinyin":"","meaning":"Nhà trường có thể khuyến khích chế độ ăn uống lành mạnh hơn bằng cách thay thế khoai tây chiên bằng rau củ và các món ăn kèm giàu dinh dưỡng khác."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_16_3', 'en-a1-16', 'Cách dùng “strong” (adj.) — khoẻ mạnh; vạm vỡ', 'strong evidence  ·  strong winds  ·  strong foundation', 'Cấu trúc strong at dùng để chỉ sự giỏi giang trong lĩnh vực gì; strong chủ yếu đóng vai trò là tính từ.', 'Họ từ (Word Family): strength (n.), strengthen (v.), strongly (adv.) | Đồng nghĩa: powerful, sturdy | Trái nghĩa: weak', '[{"hanzi":"My brother is strong enough to lift this sofa.","pinyin":"","meaning":"Anh trai tôi đủ khỏe để nhấc bổng chiếc ghế sofa này."},{"hanzi":"There is strong evidence that regular physical activity improves both mental health and academic performance.","pinyin":"","meaning":"Có bằng chứng rõ ràng cho thấy việc vận động thể chất thường xuyên giúp cải thiện cả sức khỏe tinh thần lẫn kết quả học tập."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_16_4', 'en-a1-16', 'Cách dùng “minute” (n.) — phút; chốc lát', 'a few minutes  ·  at the last minute  ·  take the minutes', 'Biên bản cuộc họp dùng dạng số nhiều minutes; tính từ chỉ sự nhỏ bé có trọng âm rơi vào âm tiết sau.', 'Họ từ (Word Family): minutely (adv.)', '[{"hanzi":"Wait a minute while I find my keys.","pinyin":"","meaning":"Đợi một chút để tôi tìm chìa khóa nhé."},{"hanzi":"Even a minute of regular classroom discussion can encourage students to reflect on what they have learned.","pinyin":"","meaning":"Ngay cả một phút thảo luận thông thường trên lớp cũng có thể khuyến khích học sinh suy ngẫm về những gì các em đã học."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
