INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_16_1_1', 'en-a1-16', 'ten_16_1', 'listening', 'listening', 'We usually meet for lunch at home on Thursday.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi có thể dùng kéo của bạn để mở gói hàng này không?","Anh trai tôi đủ khỏe để nhấc bổng chiếc ghế sofa này.","Tôi để dành một ít tiền mỗi tháng.","Chúng tôi thường gặp nhau ăn trưa ở nhà vào thứ Năm."]'::jsonb, 3, 'We usually meet for lunch at home on Thursday. → Chúng tôi thường gặp nhau ăn trưa ở nhà vào thứ Năm.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
