INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_16_1_3', 'en-a1-16', 'ten_16_1', 'listening', 'listening', 'Your clean clothes are drying outside in the sunshine.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Anh trai tôi đủ khỏe để nhấc bổng chiếc ghế sofa này.","Quần áo sạch của bạn đang phơi ngoài nắng kia kìa.","Chúng tôi thường gặp nhau ăn trưa ở nhà vào thứ Năm.","Tôi có thể dùng kéo của bạn để mở gói hàng này không?"]'::jsonb, 1, 'Your clean clothes are drying outside in the sunshine. → Quần áo sạch của bạn đang phơi ngoài nắng kia kìa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_16_2', 'en-a1-16', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_16_2_1', 'ten_16_2', 'Thursday', 'The university will host a public discussion on sustainable transport next Thursday evening.', 'The university will host a public discussion on sustainable transport next Thursday evening.', '/ˈθɝːzdeɪ/', 'Trường đại học sẽ tổ chức một buổi thảo luận công khai về giao thông bền vững vào tối thứ Năm tới đây.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_16_2_2', 'ten_16_2', 'bedroom', 'Children who share a bedroom may develop cooperation skills, but they also need sufficient privacy as they grow.', 'Children who share a bedroom may develop cooperation skills, but they also need sufficient privacy as they grow.', '/ˈbedruːm/', 'Những đứa trẻ ở chung phòng ngủ có thể phát triển kỹ năng hợp tác, nhưng chúng cũng cần có đủ không gian riêng tư khi lớn lên.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_16_2_3', 'ten_16_2', 'clothes', 'Buying durable clothes rather than frequently replacing cheap garments can reduce household waste and save resources.', 'Buying durable clothes rather than frequently replacing cheap garments can reduce household waste and save resources.', '/kloʊðz/', 'Việc mua những bộ quần áo bền bỉ thay vì liên tục thay mới những món đồ giá rẻ có thể giúp giảm thiểu rác thải sinh hoạt và tiết kiệm tài nguyên.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_16_2_4', 'ten_16_2', 'strong', 'There is strong evidence that regular physical activity improves both mental health and academic performance.', 'There is strong evidence that regular physical activity improves both mental health and academic performance.', '/strɔːŋ/', 'Có bằng chứng rõ ràng cho thấy việc vận động thể chất thường xuyên giúp cải thiện cả sức khỏe tinh thần lẫn kết quả học tập.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_16_2_5', 'ten_16_2', 'month', 'Offering employees one additional day off each month could improve wellbeing without significantly reducing overall productivity.', 'Offering employees one additional day off each month could improve wellbeing without significantly reducing overall productivity.', '/mʌnθ/', 'Việc cho phép nhân viên nghỉ thêm một ngày mỗi tháng có thể cải thiện sức khỏe tinh thần mà không làm giảm đáng kể năng suất tổng thể.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_16_2_6', 'ten_16_2', 'let', 'Schools should let students explore different subjects before requiring them to choose a specialist pathway.', 'Schools should let students explore different subjects before requiring them to choose a specialist pathway.', '/let/', 'Các trường học nên để học sinh khám phá các môn học khác nhau trước khi yêu cầu các em chọn định hướng chuyên sâu.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
