INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_16_4', 'en-a1-16', NULL, 'comprehensive_test', 'listening', 'My brother is strong enough to lift this sofa.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mọi người đều tham gia nhảy múa, thậm chí cả người chú nhút nhát của chúng tôi.","Anh trai tôi đủ khỏe để nhấc bổng chiếc ghế sofa này.","Đợi một chút để tôi tìm chìa khóa nhé.","Cô ấy cắt quả táo thành từng lát cho em trai ăn."]'::jsonb, 1, 'My brother is strong enough to lift this sofa. → Anh trai tôi đủ khỏe để nhấc bổng chiếc ghế sofa này.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_16_5', 'en-a1-16', NULL, 'comprehensive_test', 'listening', 'month', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ở trên; tiếp xúc và được bề mặt nâng đỡ","có mưa; mưa nhiều; nhiều mưa","ở ngoài; ra ngoài; vắng nhà","tháng"]'::jsonb, 3, 'month (/mʌnθ/) → tháng', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_16_6', 'en-a1-16', NULL, 'comprehensive_test', 'listening', 'Please let me know when you arrive home safely.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Quần áo sạch của bạn đang phơi ngoài nắng kia kìa.","Sáng nay tôi rời khỏi nhà mà không mang theo chìa khóa.","Chúng tôi thường ăn tối cùng nhau vào các tối thứ Ba.","Hãy cho tôi biết khi bạn về đến nhà an toàn nhé."]'::jsonb, 3, 'Please let me know when you arrive home safely. → Hãy cho tôi biết khi bạn về đến nhà an toàn nhé.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
