INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_16_8', 'en-a1-16', NULL, 'comprehensive_test', 'listening', 'Wait a minute while I find my keys.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Đợi một chút để tôi tìm chìa khóa nhé.","Mấy miếng khoai tây chiên này giòn ở bên ngoài và mềm ở bên trong.","Chúng tôi đã bắt một chuyến tàu nhanh và đến nơi trước bữa trưa.","Một cái cây cao tạo bóng râm cho khu vườn của chúng tôi vào buổi chiều."]'::jsonb, 0, 'Wait a minute while I find my keys. → Đợi một chút để tôi tìm chìa khóa nhé.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
