INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_16_18', 'en-a1-16', NULL, 'comprehensive_test', 'reading', NULL, 'The university will host a public discussion on sustainable transport next Thursday evening.', 'Dựa vào câu trên, từ “Thursday” có nghĩa phù hợp nhất là gì?', '["súp; canh","sự nghỉ ngơi; khoảng thời gian thư giãn","ở bên trong; vào bên trong","ngày thứ năm"]'::jsonb, 3, 'Thursday: ngày thứ năm. Dịch cả câu: Trường đại học sẽ tổ chức một buổi thảo luận công khai về giao thông bền vững vào tối thứ Năm tới đây.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_16_19', 'en-a1-16', NULL, 'comprehensive_test', 'reading', NULL, 'Children who share a bedroom may develop cooperation skills, but they also need sufficient privacy as they grow.', 'Dựa vào câu trên, từ “bedroom” có nghĩa phù hợp nhất là gì?', '["phòng ngủ","không; không có; không mang theo","màu hồng","máy; máy móc; thiết bị cơ khí"]'::jsonb, 0, 'bedroom: phòng ngủ. Dịch cả câu: Những đứa trẻ ở chung phòng ngủ có thể phát triển kỹ năng hợp tác, nhưng chúng cũng cần có đủ không gian riêng tư khi lớn lên.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_16_20', 'en-a1-16', NULL, 'comprehensive_test', 'reading', NULL, 'Buying durable clothes rather than frequently replacing cheap garments can reduce household waste and save resources.', 'Dựa vào câu trên, từ “clothes” có nghĩa phù hợp nhất là gì?', '["quần áo; trang phục","con voi","nghèo; nghèo khó","cảnh sát; lực lượng công an"]'::jsonb, 0, 'clothes: quần áo; trang phục. Dịch cả câu: Việc mua những bộ quần áo bền bỉ thay vì liên tục thay mới những món đồ giá rẻ có thể giúp giảm thiểu rác thải sinh hoạt và tiết kiệm tài nguyên.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_16_21', 'en-a1-16', NULL, 'comprehensive_test', 'reading', NULL, 'There is strong evidence that regular physical activity improves both mental health and academic performance.', 'Dựa vào câu trên, từ “strong” có nghĩa phù hợp nhất là gì?', '["chú; bác; cậu; dượng","khoẻ mạnh; vạm vỡ","đồi; ngọn đồi nhỏ","cầm; lấy; mang đi"]'::jsonb, 1, 'strong: khoẻ mạnh; vạm vỡ; bền chắc; vững chắc; mạnh mẽ; dữ dội; có sức thuyết phục cao. Dịch cả câu: Có bằng chứng rõ ràng cho thấy việc vận động thể chất thường xuyên giúp cải thiện cả sức khỏe tinh thần lẫn kết quả học tập.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
