INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_16_23', 'en-a1-16', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khoai tây chiên (tiếng Anh Anh); khoai tây lát mỏng (tiếng Anh Mỹ)”', '["want","fun","box","chips"]'::jsonb, 3, 'khoai tây chiên (tiếng Anh Anh); khoai tây lát mỏng (tiếng Anh Mỹ) → chips (/tʃɪps/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_16_24', 'en-a1-16', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “giữ lại; bảo quản”', '["few","cheap","keep","any"]'::jsonb, 2, 'giữ lại; bảo quản → keep (/kiːp/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-17', 'en', 'Bài 17: Đời sống hằng ngày (2) - CEFR A1', 'CEFR A1', 'A1 · Đời sống', '28 từ vựng Tiếng Anh CEFR A1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1017, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_left', 'en-a1-17', 'left', '/left/', 'A1', 'bên trái; phía bên trái; sang bên trái; ở bên trái; còn lại; thừa lại', 'adj.', 'left-handed (adj.), leftmost (adj.)', 'Trái nghĩa: right', 'Đây cũng là dạng quá khứ và phân từ hai của leave; khi mang nghĩa "còn lại", từ này được đặt sau danh từ.', 'I carry my shopping bag in my left hand.', NULL, 'Tôi xách túi mua sắm bằng tay trái.', '{"wordId":"left","ukIpa":"/left/","usIpa":"/left/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"On the side opposite the right.","vi":"bên trái; phía bên trái"},{"pos":"adv.","en":"Towards or on the side opposite the right.","vi":"sang bên trái; ở bên trái"},{"pos":"adj.","en":"Still available or remaining after others have gone or been used.","vi":"còn lại; thừa lại"}],"examples":[{"en":"I carry my shopping bag in my left hand.","vi":"Tôi xách túi mua sắm bằng tay trái.","audioKind":"ex"},{"en":"Drivers should check their mirrors carefully before turning left, especially where cyclists share the road.","vi":"Người lái xe nên quan sát kỹ gương chiếu hậu trước khi rẽ trái, đặc biệt là ở những đoạn đường đi chung với người đi xe đạp.","audioKind":"ex2"}],"collocations":[{"en":"left hand","vi":"tay trái"},{"en":"turn left","vi":"rẽ trái"},{"en":"on the left","vi":"ở bên trái"},{"en":"time left","vi":"thời gian còn lại"}],"wordFamily":["left-handed (adj.)","leftmost (adj.)"],"synonyms":[],"antonyms":["right"],"tipVi":"Đây cũng là dạng quá khứ và phân từ hai của leave; khi mang nghĩa \"còn lại\", từ này được đặt sau danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_put', 'en-a1-17', 'put', '/pʊt/', 'A1', 'đặt; để; bố trí; diễn đạt; bày tỏ; làm cho ai/cái gì rơi vào trạng thái nào đó', 'v.', NULL, 'Đồng nghĩa: place', 'Dạng quá khứ và phân từ hai đều là put; nghĩa "đặt để" thường đi kèm trạng ngữ chỉ địa điểm.', 'Please put your wet umbrella beside the door.', NULL, 'Làm ơn đặt chiếc ô ướt của bạn cạnh cửa ra vào.', '{"wordId":"put","ukIpa":"/pʊt/","usIpa":"/pʊt/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to move something into a particular place or position","vi":"đặt; để; bố trí"},{"pos":"v.","en":"to express something in a particular way","vi":"diễn đạt; bày tỏ"},{"pos":"v.","en":"to cause someone or something to enter a particular state","vi":"làm cho ai/cái gì rơi vào trạng thái nào đó"}],"examples":[{"en":"Please put your wet umbrella beside the door.","vi":"Làm ơn đặt chiếc ô ướt của bạn cạnh cửa ra vào.","audioKind":"ex"},{"en":"Rising housing costs put considerable pressure on young people who are starting their careers.","vi":"Chi phí nhà ở gia tăng đặt áp lực đáng kể lên những người trẻ tuổi mới bắt đầu sự nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"put something away","vi":"cất đi; thu dọn"},{"en":"put pressure on","vi":"gây áp lực lên"},{"en":"put into words","vi":"diễn đạt thành lời"},{"en":"put something in place","vi":"đưa vào thực thi"}],"wordFamily":[],"synonyms":["place"],"antonyms":[],"tipVi":"Dạng quá khứ và phân từ hai đều là put; nghĩa \"đặt để\" thường đi kèm trạng ngữ chỉ địa điểm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sunday', 'en-a1-17', 'Sunday', '/ˈsʌndeɪ/', 'A1', 'ngày Chủ nhật', 'n.', NULL, NULL, 'Tên các ngày trong tuần viết hoa chữ cái đầu; dùng on Sunday, nhưng next Sunday thì không cần dùng on.', 'We usually cook a big lunch together on Sunday.', NULL, 'Chúng tôi thường cùng nhau nấu một bữa trưa thịnh soạn vào ngày Chủ nhật.', '{"wordId":"sunday","ukIpa":"/ˈsʌndeɪ/","usIpa":"/ˈsʌndeɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"the day after Saturday and before Monday","vi":"ngày Chủ nhật"}],"examples":[{"en":"We usually cook a big lunch together on Sunday.","vi":"Chúng tôi thường cùng nhau nấu một bữa trưa thịnh soạn vào ngày Chủ nhật.","audioKind":"ex"},{"en":"Opening public libraries on Sunday allows people with busy weekday schedules to access essential community services.","vi":"Việc mở cửa các thư viện công cộng vào ngày Chủ nhật giúp những người bận rộn vào các ngày trong tuần có thể tiếp cận các dịch vụ cộng đồng thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"on Sunday","vi":"vào ngày Chủ nhật"},{"en":"Sunday morning","vi":"buổi sáng Chủ nhật"},{"en":"every Sunday","vi":"mọi Chủ nhật; Chủ nhật nào cũng vậy"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tên các ngày trong tuần viết hoa chữ cái đầu; dùng on Sunday, nhưng next Sunday thì không cần dùng on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_skirt', 'en-a1-17', 'skirt', '/skɝːt/', 'A1', 'váy (trang phục từ eo thả xuống, không chia ống); đi vòng quanh mép; đi dọc theo rìa; tránh né; né tránh trực tiếp', 'n.', NULL, NULL, 'Skirt chỉ váy ngắn/chân váy; dress thường chỉ váy liền thân.', 'Her blue skirt swayed as she walked upstairs.', NULL, 'Chiếc váy xanh của cô ấy lay động theo từng bước chân khi cô đi lên lầu.', '{"wordId":"skirt","ukIpa":"/skɜːt/","usIpa":"/skɝːt/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"Clothing hanging from the waist, without separate sections for legs.","vi":"váy (trang phục từ eo thả xuống, không chia ống)"},{"pos":"v.","en":"To move around the edge of something.","vi":"đi vòng quanh mép; đi dọc theo rìa"},{"pos":"v.","en":"To avoid dealing directly with a difficult subject.","vi":"tránh né; né tránh trực tiếp"}],"examples":[{"en":"Her blue skirt swayed as she walked upstairs.","vi":"Chiếc váy xanh của cô ấy lay động theo từng bước chân khi cô đi lên lầu.","audioKind":"ex"},{"en":"Public discussions often skirt the issue of who should pay for environmental protection.","vi":"Các cuộc thảo luận công khai thường né tránh vấn đề ai là người nên chi trả cho công tác bảo vệ môi trường.","audioKind":"ex2"}],"collocations":[{"en":"a pleated skirt","vi":"váy xếp ly"},{"en":"a knee-length skirt","vi":"váy dài đến đầu gối"},{"en":"skirt the issue","vi":"né tránh vấn đề"},{"en":"skirt the edge of","vi":"đi dọc theo mép của"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Skirt chỉ váy ngắn/chân váy; dress thường chỉ váy liền thân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_side', 'en-a1-17', 'side', '/saɪd/', 'A1', 'bên; mặt bên; cạnh; khía cạnh; phe; bên trong một cuộc tranh cãi; ủng hộ; đứng về phía ai', 'n.', 'sideways (adv.)', NULL, 'Side with mang nghĩa ủng hộ một bên nào đó; side by side nghĩa là đặt cạnh nhau hoặc sóng vai bên nhau.', 'Please leave your muddy boots by the side door.', NULL, 'Làm ơn để những chiếc ủng dính bùn của bạn cạnh cửa hông.', '{"wordId":"side","ukIpa":"/saɪd/","usIpa":"/saɪd/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"An edge or surface of something, or the space beside it.","vi":"bên; mặt bên; cạnh"},{"pos":"n.","en":"One aspect of something or one group in a disagreement.","vi":"khía cạnh; phe; bên trong một cuộc tranh cãi"},{"pos":"v.","en":"To support one person or group in a disagreement.","vi":"ủng hộ; đứng về phía ai"}],"examples":[{"en":"Please leave your muddy boots by the side door.","vi":"Làm ơn để những chiếc ủng dính bùn của bạn cạnh cửa hông.","audioKind":"ex"},{"en":"Public debates should consider both sides of an issue before any major policy decision is made.","vi":"Các cuộc tranh luận công khai nên xem xét cả hai mặt của vấn đề trước khi đưa ra bất kỳ quyết định chính sách lớn nào.","audioKind":"ex2"}],"collocations":[{"en":"on either side","vi":"ở mỗi bên"},{"en":"side by side","vi":"song song; sát bên nhau"},{"en":"side with someone","vi":"đứng về phía ai"},{"en":"the other side of the argument","vi":"quan điểm đối lập của cuộc tranh luận"}],"wordFamily":["sideways (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Side with mang nghĩa ủng hộ một bên nào đó; side by side nghĩa là đặt cạnh nhau hoặc sóng vai bên nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pretty', 'en-a1-17', 'pretty', '/ˈprɪti/', 'A1', 'xinh đẹp; xinh xắn; ưa nhìn; khá; tương đối (dùng trong văn phong thân mật)', 'adj.', 'prettily (adv.), prettiness (n.)', 'Đồng nghĩa: attractive, lovely · Trái nghĩa: ugly', 'Khi làm trạng từ với nghĩa "khá", từ này mang tính khẩu ngữ; trong văn viết trang trọng nên dùng fairly.', 'We found a pretty cottage beside a quiet stream.', NULL, 'Chúng tôi tìm thấy một ngôi nhà tranh xinh xắn nằm bên cạnh con suối thanh bình.', '{"wordId":"pretty","ukIpa":"/ˈprɪti/","usIpa":"/ˈprɪti/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Attractive and pleasant to look at.","vi":"xinh đẹp; xinh xắn; ưa nhìn"},{"pos":"adv.","en":"To a fairly large degree, especially in informal speech.","vi":"khá; tương đối (dùng trong văn phong thân mật)"}],"examples":[{"en":"We found a pretty cottage beside a quiet stream.","vi":"Chúng tôi tìm thấy một ngôi nhà tranh xinh xắn nằm bên cạnh con suối thanh bình.","audioKind":"ex"},{"en":"Although pretty public gardens attract visitors, cities must also ensure that these spaces remain accessible to residents.","vi":"Mặc dù những khu vườn công cộng xinh đẹp thu hút khách du lịch, các thành phố cũng phải đảm bảo rằng không gian này vẫn thuận tiện cho người dân sử dụng.","audioKind":"ex2"}],"collocations":[{"en":"a pretty village","vi":"một ngôi làng xinh đẹp"},{"en":"a pretty dress","vi":"một chiếc váy xinh xắn"},{"en":"pretty good","vi":"khá tốt; khá ổn"},{"en":"pretty much","vi":"hầu như; gần như"}],"wordFamily":["prettily (adv.)","prettiness (n.)"],"synonyms":["attractive","lovely"],"antonyms":["ugly"],"tipVi":"Khi làm trạng từ với nghĩa \"khá\", từ này mang tính khẩu ngữ; trong văn viết trang trọng nên dùng fairly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_too', 'en-a1-17', 'too', '/tuː/', 'A1', 'quá (vượt mức mong muốn, cần thiết hoặc phù hợp); cũng; ngoài ra', 'adv.', NULL, 'Đồng nghĩa: also, excessively', 'too nhấn mạnh vượt quá mức độ thích hợp; very chỉ nhấn mạnh mức độ cao.', 'This soup is too hot to eat now.', NULL, 'Món súp này quá nóng để ăn lúc này.', '{"wordId":"too","ukIpa":"/tuː/","usIpa":"/tuː/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"more than is wanted, needed, or suitable","vi":"quá (vượt mức mong muốn, cần thiết hoặc phù hợp)"},{"pos":"adv.","en":"in addition; also","vi":"cũng; ngoài ra"}],"examples":[{"en":"This soup is too hot to eat now.","vi":"Món súp này quá nóng để ăn lúc này.","audioKind":"ex"},{"en":"Public transport cannot attract more passengers if fares are too high for regular commuters.","vi":"Phương tiện giao thông công cộng không thể thu hút thêm hành khách nếu giá vé quá cao đối với những người đi lại thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"too much","vi":"quá nhiều"},{"en":"too late","vi":"quá muộn"},{"en":"too tired to work","vi":"quá mệt mỏi để làm việc"},{"en":"me too","vi":"tôi cũng vậy"}],"wordFamily":[],"synonyms":["also","excessively"],"antonyms":[],"tipVi":"too nhấn mạnh vượt quá mức độ thích hợp; very chỉ nhấn mạnh mức độ cao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_glass', 'en-a1-17', 'glass', '/ɡlæs/', 'A1', 'chất liệu kính, thủy tinh cứng, thường trong suốt dùng làm cửa sổ và vật dụng; cốc thủy tinh, ly thủy tinh; hoặc lượng chứa trong đó; kính mắt (mắt kính lắp trong gọng để cải thiện tầm nhìn)', 'n.', 'glassy (adj.), glassware (n.)', NULL, 'Thủy tinh là danh từ không đếm được, cốc thủy tinh đếm được; kính mắt luôn dùng dạng số nhiều glasses.', 'The ball hit the window and shattered the glass.', NULL, 'Quả bóng đập trúng cửa sổ và làm vỡ tan mặt kính.', '{"wordId":"glass","ukIpa":"/ɡlɑːs/","usIpa":"/ɡlæs/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A hard, usually transparent material used for windows and containers.","vi":"chất liệu kính, thủy tinh cứng, thường trong suốt dùng làm cửa sổ và vật dụng"},{"pos":"n.","en":"A drinking container, or the amount it holds.","vi":"cốc thủy tinh, ly thủy tinh; hoặc lượng chứa trong đó"},{"pos":"n.","en":"Lenses held in a frame worn to improve sight.","vi":"kính mắt (mắt kính lắp trong gọng để cải thiện tầm nhìn)"}],"examples":[{"en":"The ball hit the window and shattered the glass.","vi":"Quả bóng đập trúng cửa sổ và làm vỡ tan mặt kính.","audioKind":"ex"},{"en":"Recycling glass reduces demand for raw materials and can lower energy consumption in the manufacturing sector.","vi":"Việc tái chế thủy tinh làm giảm nhu cầu về nguyên liệu thô và có thể hạ mức tiêu thụ năng lượng trong ngành sản xuất.","audioKind":"ex2"}],"collocations":[{"en":"broken glass","vi":"mảnh thủy tinh vỡ"},{"en":"a glass of water","vi":"một cốc nước"},{"en":"wear glasses","vi":"đeo kính"},{"en":"glass bottle","vi":"chai thủy tinh"}],"wordFamily":["glassy (adj.)","glassware (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thủy tinh là danh từ không đếm được, cốc thủy tinh đếm được; kính mắt luôn dùng dạng số nhiều glasses.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_or', 'en-a1-17', 'or', '/ɔːr/', 'A1', 'hoặc; hay (dùng để nối các lựa chọn); nếu không thì; hoặc là (dùng để nêu hậu quả nếu không làm điều gì)', 'conj.', NULL, NULL, 'Trong câu phủ định, khi nối các yếu tố song song, người ta thường dùng or thay vì and.', 'Would you like rice or noodles with your vegetables?', NULL, 'Bạn muốn ăn cơm hay mì cùng với rau củ?', '{"wordId":"or","ukIpa":"/ɔː/","usIpa":"/ɔːr/","cefr":"A1","topic":"daily","senses":[{"pos":"conj.","en":"Used to connect alternatives or choices","vi":"hoặc; hay (dùng để nối các lựa chọn)"},{"pos":"conj.","en":"Used to introduce what happens if something is not done","vi":"nếu không thì; hoặc là (dùng để nêu hậu quả nếu không làm điều gì)"}],"examples":[{"en":"Would you like rice or noodles with your vegetables?","vi":"Bạn muốn ăn cơm hay mì cùng với rau củ?","audioKind":"ex"},{"en":"Governments must improve public transport or face increasing congestion and air pollution in major cities.","vi":"Chính phủ phải cải thiện hệ thống giao thông công cộng, nếu không các thành phố lớn sẽ đối mặt với tình trạng tắc nghẽn và ô nhiễm không khí ngày càng trầm trọng.","audioKind":"ex2"}],"collocations":[{"en":"either ... or ...","vi":"hoặc là... hoặc là..."},{"en":"or else","vi":"nếu không thì"},{"en":"sooner or later","vi":"sớm muộn gì"},{"en":"one or two","vi":"một hoặc hai"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong câu phủ định, khi nối các yếu tố song song, người ta thường dùng or thay vì and.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_once', 'en-a1-17', 'once', '/wʌns/', 'A1', 'một lần duy nhất; đã từng; trước đây; một khi; ngay khi điều gì đó xảy ra hoặc đúng sự thật', 'adv.', NULL, NULL, 'Khi once mở đầu mệnh đề chỉ thời gian trong tương lai, thường dùng thì hiện tại đơn.', 'I water this little cactus once every two weeks.', NULL, 'Tôi tưới chậu xương rồng nhỏ này hai tuần một lần.', '{"wordId":"once","ukIpa":"/wʌns/","usIpa":"/wʌns/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"on one occasion only","vi":"một lần duy nhất"},{"pos":"adv.","en":"at a time in the past","vi":"đã từng; trước đây"},{"pos":"conj.","en":"as soon as something happens or becomes true","vi":"một khi; ngay khi điều gì đó xảy ra hoặc đúng sự thật"}],"examples":[{"en":"I water this little cactus once every two weeks.","vi":"Tôi tưới chậu xương rồng nhỏ này hai tuần một lần.","audioKind":"ex"},{"en":"Once reliable public transport becomes available, more commuters may choose to leave their cars at home.","vi":"Một khi phương tiện giao thông công cộng đáng tin cậy đi vào hoạt động, nhiều người đi làm có thể chọn cách không lái xe cá nhân nữa.","audioKind":"ex2"}],"collocations":[{"en":"once a week","vi":"mỗi tuần một lần"},{"en":"at once","vi":"ngay lập tức"},{"en":"once again","vi":"một lần nữa"},{"en":"once in a while","vi":"thỉnh thoảng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi once mở đầu mệnh đề chỉ thời gian trong tương lai, thường dùng thì hiện tại đơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sock', 'en-a1-17', 'sock', '/sɑːk/', 'A1', 'tất chân; vớ', 'n.', NULL, NULL, 'Một đôi tất nói là a pair of socks, trong đó sock là danh từ đếm được.', 'One blue sock was hiding under the bed.', NULL, 'Một chiếc tất xanh đang giấu dưới gầm giường.', '{"wordId":"sock","ukIpa":"/sɒk/","usIpa":"/sɑːk/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a clothing item covering the foot and lower leg","vi":"tất chân; vớ"}],"examples":[{"en":"One blue sock was hiding under the bed.","vi":"Một chiếc tất xanh đang giấu dưới gầm giường.","audioKind":"ex"},{"en":"Choosing durable socks made from recycled materials can help consumers reduce clothing waste over time.","vi":"Việc chọn những đôi tất bền làm từ vật liệu tái chế có thể giúp người tiêu dùng giảm thiểu lượng rác thải dệt may theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"a pair of socks","vi":"một đôi tất"},{"en":"woollen socks","vi":"tất len"},{"en":"put on socks","vi":"đi tất"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Một đôi tất nói là a pair of socks, trong đó sock là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_letter', 'en-a1-17', 'letter', '/ˈletər/', 'A1', 'thư tín; bức thư gửi cho cá nhân hoặc tổ chức; chữ cái (ký hiệu viết thể hiện một âm trong bảng chữ cái)', 'n.', 'lettering (n.)', NULL, 'letter vừa có nghĩa là bức thư, vừa là chữ cái; từ character còn có thể chỉ ký tự chữ Hán v.v.', 'A letter from my sister arrived this morning.', NULL, 'Một bức thư từ chị tôi đã đến vào sáng nay.', '{"wordId":"letter","ukIpa":"/ˈletə/","usIpa":"/ˈletər/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a written message sent to a person or organisation","vi":"thư tín; bức thư gửi cho cá nhân hoặc tổ chức"},{"pos":"n.","en":"a written symbol representing a sound in an alphabet","vi":"chữ cái (ký hiệu viết thể hiện một âm trong bảng chữ cái)"}],"examples":[{"en":"A letter from my sister arrived this morning.","vi":"Một bức thư từ chị tôi đã đến vào sáng nay.","audioKind":"ex"},{"en":"Writing a formal letter of complaint can encourage companies to address problems with their services.","vi":"Việc viết một bức thư khiếu nại trang trọng có thể thúc đẩy các công ty giải quyết các vấn đề về dịch vụ của họ.","audioKind":"ex2"}],"collocations":[{"en":"write a letter","vi":"viết thư"},{"en":"letter of complaint","vi":"thư khiếu nại"},{"en":"capital letter","vi":"chữ cái viết hoa"},{"en":"covering letter","vi":"thư xin việc"}],"wordFamily":["lettering (n.)"],"synonyms":[],"antonyms":[],"tipVi":"letter vừa có nghĩa là bức thư, vừa là chữ cái; từ character còn có thể chỉ ký tự chữ Hán v.v.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bad', 'en-a1-17', 'bad', '/bæd/', 'A1', 'kém; tồi; chất lượng không tốt hoặc không đạt yêu cầu; trầm trọng; tồi tệ; nghiêm trọng, khó chịu hoặc dễ gây tổn hại; hư; xấu; cư xử sai trái hoặc vi phạm quy tắc chung', 'adj.', 'badly (adv.), badness (n.)', 'Đồng nghĩa: poor, unpleasant · Trái nghĩa: good', 'Tính từ so sánh hơn là worse, so sánh nhất là worst; badly là phó từ tương ứng.', 'The soup tasted so bad that I stopped eating.', NULL, 'Món súp dở đến mức tôi ngừng ăn luôn.', '{"wordId":"bad","ukIpa":"/bæd/","usIpa":"/bæd/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Not good in quality or not satisfactory.","vi":"kém; tồi; chất lượng không tốt hoặc không đạt yêu cầu"},{"pos":"adj.","en":"Serious, unpleasant, or likely to cause harm.","vi":"trầm trọng; tồi tệ; nghiêm trọng, khó chịu hoặc dễ gây tổn hại"},{"pos":"adj.","en":"Behaving wrongly or breaking accepted rules.","vi":"hư; xấu; cư xử sai trái hoặc vi phạm quy tắc chung"}],"examples":[{"en":"The soup tasted so bad that I stopped eating.","vi":"Món súp dở đến mức tôi ngừng ăn luôn.","audioKind":"ex"},{"en":"Bad air quality can discourage outdoor exercise and increase health risks among children and older adults.","vi":"Chất lượng không khí kém có thể làm giảm hứng thú tập thể dục ngoài trời và làm tăng rủi ro sức khỏe ở trẻ em và người lớn tuổi.","audioKind":"ex2"}],"collocations":[{"en":"bad weather","vi":"thời tiết xấu"},{"en":"bad habits","vi":"thói quen xấu"},{"en":"bad for your health","vi":"có hại cho sức khỏe của bạn"},{"en":"a bad cold","vi":"cảm lạnh nặng"}],"wordFamily":["badly (adv.)","badness (n.)"],"synonyms":["poor","unpleasant"],"antonyms":["good"],"tipVi":"Tính từ so sánh hơn là worse, so sánh nhất là worst; badly là phó từ tương ứng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_upstairs', 'en-a1-17', 'upstairs', '/ˌʌpˈsterz/', 'A1', 'ở trên lầu; lên lầu; ở tầng trên của một tòa nhà', 'adv.', 'downstairs (adv.)', 'Trái nghĩa: downstairs', 'Khi đóng vai trò là phó từ, trước upstairs không dùng giới từ to: go upstairs.', 'I left my glasses upstairs beside the bed.', NULL, 'Tôi để quên kính ở cạnh giường trên lầu.', '{"wordId":"upstairs","ukIpa":"/ˌʌpˈsteəz/","usIpa":"/ˌʌpˈsterz/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"On or towards a higher floor of a building.","vi":"ở trên lầu; lên lầu"},{"pos":"adj.","en":"Located on a higher floor of a building.","vi":"ở tầng trên của một tòa nhà"}],"examples":[{"en":"I left my glasses upstairs beside the bed.","vi":"Tôi để quên kính ở cạnh giường trên lầu.","audioKind":"ex"},{"en":"Moving bedrooms upstairs can provide greater privacy in homes where the ground floor is used for work.","vi":"Việc chuyển các phòng ngủ lên tầng trên có thể mang lại sự riêng tư lớn hơn trong những ngôi nhà có tầng trệt dùng làm nơi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"go upstairs","vi":"đi lên lầu"},{"en":"upstairs bedroom","vi":"phòng ngủ trên lầu"},{"en":"upstairs neighbour","vi":"người hàng xóm ở tầng trên"}],"wordFamily":["downstairs (adv.)"],"synonyms":[],"antonyms":["downstairs"],"tipVi":"Khi đóng vai trò là phó từ, trước upstairs không dùng giới từ to: go upstairs.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_head', 'en-a1-17', 'head', '/hed/', 'A1', 'đầu; phần đầu; người đứng đầu; thủ lĩnh; người lãnh đạo; đi về hướng; hướng tới', 'n.', 'headship (n.), headless (adj.)', NULL, 'head for cộng với địa điểm mang nghĩa "đi đến vùng đất hoặc địa điểm nào đó".', 'She shook her head when I offered more soup.', NULL, 'Cô ấy lắc đầu khi tôi mời thêm súp.', '{"wordId":"head","ukIpa":"/hed/","usIpa":"/hed/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"the body part containing the brain, eyes, and mouth","vi":"đầu; phần đầu"},{"pos":"n.","en":"the person in charge of a group or organisation","vi":"người đứng đầu; thủ lĩnh; người lãnh đạo"},{"pos":"v.","en":"to move or travel in a particular direction","vi":"đi về hướng; hướng tới"}],"examples":[{"en":"She shook her head when I offered more soup.","vi":"Cô ấy lắc đầu khi tôi mời thêm súp.","audioKind":"ex"},{"en":"Cyclists should wear suitable helmets to reduce the risk of head injuries when travelling on busy roads.","vi":"Người đi xe đạp nên đội mũ bảo hiểm phù hợp để giảm nguy cơ chấn thương vùng đầu khi di chuyển trên những con đường đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"shake your head","vi":"lắc đầu"},{"en":"head teacher","vi":"hiệu trưởng"},{"en":"head of department","vi":"trưởng bộ phận"},{"en":"head for","vi":"đi về phía; hướng tới"}],"wordFamily":["headship (n.)","headless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"head for cộng với địa điểm mang nghĩa \"đi đến vùng đất hoặc địa điểm nào đó\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_yesterday', 'en-a1-17', 'yesterday', '/ˈjestərdeɪ/', 'A1', 'hôm qua; ngày hôm qua', 'adv.', NULL, 'Trái nghĩa: tomorrow', 'Trước yesterday thường không dùng giới từ, hay đi kèm với thì quá khứ đơn.', 'I left my umbrella on the bus yesterday.', NULL, 'Tôi để quên ô trên xe buýt ngày hôm qua.', '{"wordId":"yesterday","ukIpa":"/ˈjestədeɪ/","usIpa":"/ˈjestərdeɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"On the day before today.","vi":"hôm qua"},{"pos":"n.","en":"The day immediately before today.","vi":"ngày hôm qua"}],"examples":[{"en":"I left my umbrella on the bus yesterday.","vi":"Tôi để quên ô trên xe buýt ngày hôm qua.","audioKind":"ex"},{"en":"The transport survey published yesterday suggests that commuters increasingly prefer cycling to driving in city centres.","vi":"Cuộc khảo sát giao thông công bố ngày hôm qua cho thấy những người đi làm có xu hướng thích đạp xe hơn là lái xe ở khu vực trung tâm thành phố.","audioKind":"ex2"}],"collocations":[{"en":"yesterday morning","vi":"sáng hôm qua"},{"en":"yesterday afternoon","vi":"chiều hôm qua"},{"en":"yesterday evening","vi":"tối hôm qua"},{"en":"the day before yesterday","vi":"hôm kia"}],"wordFamily":[],"synonyms":[],"antonyms":["tomorrow"],"tipVi":"Trước yesterday thường không dùng giới từ, hay đi kèm với thì quá khứ đơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_something', 'en-a1-17', 'something', '/ˈsʌmθɪŋ/', 'A1', 'thứ gì đó; điều gì đó; vật gì', 'pron.', NULL, 'Trái nghĩa: nothing', 'Tính từ bổ nghĩa cho something được đặt ở phía sau, ví dụ something useful; làm chủ ngữ thì chia động từ số ít.', 'There is something soft inside this little box.', NULL, 'Có cái gì đó mềm mại bên trong chiếc hộp nhỏ này.', '{"wordId":"something","ukIpa":"/ˈsʌmθɪŋ/","usIpa":"/ˈsʌmθɪŋ/","cefr":"A1","topic":"daily","senses":[{"pos":"pron.","en":"A thing that is not named or specified.","vi":"thứ gì đó; điều gì đó; vật gì"}],"examples":[{"en":"There is something soft inside this little box.","vi":"Có cái gì đó mềm mại bên trong chiếc hộp nhỏ này.","audioKind":"ex"},{"en":"Learning something new every day can help adults remain curious and adapt to changes in the workplace.","vi":"Học hỏi một điều gì đó mới mỗi ngày giúp người lớn duy trì sự tò mò và thích nghi với những thay đổi nơi công sở.","audioKind":"ex2"}],"collocations":[{"en":"something else","vi":"thứ gì khác"},{"en":"something new","vi":"điều gì mới mẻ"},{"en":"something to eat","vi":"thứ gì để ăn"},{"en":"something wrong","vi":"có điều gì đó bất thường"}],"wordFamily":[],"synonyms":[],"antonyms":["nothing"],"tipVi":"Tính từ bổ nghĩa cho something được đặt ở phía sau, ví dụ something useful; làm chủ ngữ thì chia động từ số ít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pet', 'en-a1-17', 'pet', '/pet/', 'A1', 'thú cưng; vật nuôi; vuốt ve; âu yếm', 'n.', 'petting (n.)', NULL, 'Dạng quá khứ của động từ là petted; trong tiếng Anh Anh, hành động vuốt ve còn dùng từ stroke.', 'Our pet rabbit loves hiding under the kitchen table.', NULL, 'Chú thỏ cưng của chúng tôi rất thích trốn dưới gầm bàn bếp.', '{"wordId":"pet","ukIpa":"/pet/","usIpa":"/pet/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"An animal kept at home for company and pleasure.","vi":"thú cưng; vật nuôi"},{"pos":"v.","en":"To gently touch an animal with your hand.","vi":"vuốt ve; âu yếm"}],"examples":[{"en":"Our pet rabbit loves hiding under the kitchen table.","vi":"Chú thỏ cưng của chúng tôi rất thích trốn dưới gầm bàn bếp.","audioKind":"ex"},{"en":"Caring for a pet can help children develop responsibility and learn to recognise the needs of others.","vi":"Chăm sóc thú cưng có thể giúp trẻ em phát triển tinh thần trách nhiệm và học cách nhận biết nhu cầu của người khác.","audioKind":"ex2"}],"collocations":[{"en":"keep a pet","vi":"nuôi thú cưng"},{"en":"a pet owner","vi":"chủ nuôi thú cưng"},{"en":"pet care","vi":"chăm sóc thú cưng"},{"en":"pet a dog","vi":"vuốt ve một chú chó"}],"wordFamily":["petting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ của động từ là petted; trong tiếng Anh Anh, hành động vuốt ve còn dùng từ stroke.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stop', 'en-a1-17', 'stop', '/stɑːp/', 'A1', 'dừng lại; ngừng; ngăn chặn; bến (xe buýt, tàu hỏa); sự dừng lại; điểm dừng chân', 'v.', 'stoppage (n.), unstoppable (adj.)', 'Đồng nghĩa: halt, cease · Trái nghĩa: continue', 'stop doing mang nghĩa dừng hẳn việc đang làm; stop to do mang nghĩa dừng lại để làm việc khác.', 'We stopped walking when the rain became heavier.', NULL, 'Chúng tôi ngừng đi bộ khi trời bắt đầu mưa to hơn.', '{"wordId":"stop","ukIpa":"/stɒp/","usIpa":"/stɑːp/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To end an activity or prevent something from happening.","vi":"dừng lại; ngừng; ngăn chặn"},{"pos":"n.","en":"A place where buses or other vehicles regularly collect passengers.","vi":"bến (xe buýt, tàu hỏa)"},{"pos":"n.","en":"An interruption of movement or a brief stay somewhere.","vi":"sự dừng lại; điểm dừng chân"}],"examples":[{"en":"We stopped walking when the rain became heavier.","vi":"Chúng tôi ngừng đi bộ khi trời bắt đầu mưa to hơn.","audioKind":"ex"},{"en":"Cities should improve public transport to stop traffic congestion from becoming worse as populations grow.","vi":"Các thành phố nên cải thiện giao thông công cộng để ngăn chặn tình trạng ùn tắc giao thông trở nên tồi tệ hơn khi dân số gia tăng.","audioKind":"ex2"}],"collocations":[{"en":"stop doing something","vi":"ngừng làm việc gì"},{"en":"stop someone from doing something","vi":"ngăn cản ai làm việc gì"},{"en":"bus stop","vi":"bến xe buýt"},{"en":"come to a stop","vi":"dừng hẳn lại"}],"wordFamily":["stoppage (n.)","unstoppable (adj.)"],"synonyms":["halt","cease"],"antonyms":["continue"],"tipVi":"stop doing mang nghĩa dừng hẳn việc đang làm; stop to do mang nghĩa dừng lại để làm việc khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_front', 'en-a1-17', 'front', '/frʌnt/', 'A1', 'mặt trước; phần trước; ở phía trước; ở mặt trước; đường front; frông (khí tượng)', 'n.', NULL, 'Trái nghĩa: back, rear', 'in front of chỉ vị trí ở phía trước bên ngoài; at the front of chỉ phần phía trước thuộc về cấu trúc vật đó.', 'Please leave your muddy boots by the front door.', NULL, 'Vui lòng để những chiếc ủng dính bùn của bạn ở cửa trước.', '{"wordId":"front","ukIpa":"/frʌnt/","usIpa":"/frʌnt/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The forward part or outward-facing surface of something.","vi":"mặt trước; phần trước"},{"pos":"adj.","en":"Located at or near the forward part of something.","vi":"ở phía trước; ở mặt trước"},{"pos":"n.","en":"A boundary where masses of warm and cold air meet.","vi":"đường front; frông (khí tượng)"}],"examples":[{"en":"Please leave your muddy boots by the front door.","vi":"Vui lòng để những chiếc ủng dính bùn của bạn ở cửa trước.","audioKind":"ex"},{"en":"Placing bicycle racks at the front of public buildings can encourage more residents to cycle.","vi":"Việc lắp đặt các giá để xe đạp ở phía trước các tòa nhà công cộng có thể khuyến khích nhiều cư dân đạp xe hơn.","audioKind":"ex2"}],"collocations":[{"en":"front door","vi":"cửa trước"},{"en":"at the front of","vi":"ở phía trước của"},{"en":"in front of","vi":"ở đằng trước"},{"en":"cold front","vi":"frông lạnh"}],"wordFamily":[],"synonyms":[],"antonyms":["back","rear"],"tipVi":"in front of chỉ vị trí ở phía trước bên ngoài; at the front of chỉ phần phía trước thuộc về cấu trúc vật đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_night', 'en-a1-17', 'night', '/naɪt/', 'A1', 'ban đêm; đêm tối', 'n.', 'nightly (adj.), nightly (adv.), nighttime (n.)', 'Trái nghĩa: day', 'Chỉ thời điểm ban đêm dùng at night; cụm last night không đi kèm giới từ trước đó.', 'We watched the stars from our balcony last night.', NULL, 'Chúng tôi ngắm các vì sao từ ban công nhà mình vào tối qua.', '{"wordId":"night","ukIpa":"/naɪt/","usIpa":"/naɪt/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The dark part of each day when the sun is down.","vi":"ban đêm; đêm tối"}],"examples":[{"en":"We watched the stars from our balcony last night.","vi":"Chúng tôi ngắm các vì sao từ ban công nhà mình vào tối qua.","audioKind":"ex"},{"en":"Excessive artificial light at night can disrupt sleep patterns and affect the behaviour of urban wildlife.","vi":"Ánh sáng nhân tạo quá mức vào ban đêm có thể làm gián đoạn chu kỳ giấc ngủ và ảnh hưởng đến tập tính của động vật hoang dã đô thị.","audioKind":"ex2"}],"collocations":[{"en":"at night","vi":"vào ban đêm"},{"en":"last night","vi":"đêm hôm qua"},{"en":"night shift","vi":"ca đêm"},{"en":"a good night''s sleep","vi":"một giấc ngủ ngon"}],"wordFamily":["nightly (adj.)","nightly (adv.)","nighttime (n.)"],"synonyms":[],"antonyms":["day"],"tipVi":"Chỉ thời điểm ban đêm dùng at night; cụm last night không đi kèm giới từ trước đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ask', 'en-a1-17', 'ask', '/æsk/', 'A1', 'hỏi; hỏi thăm; yêu cầu; xin; mời', 'v.', NULL, 'Đồng nghĩa: inquire, request · Trái nghĩa: answer', 'ask for dùng khi muốn lấy thứ gì; ask someone to do dùng khi nhờ ai làm việc gì.', 'I asked the driver where the bus stopped.', NULL, 'Tôi đã hỏi người lái xe xem xe buýt dừng ở đâu.', '{"wordId":"ask","ukIpa":"/ɑːsk/","usIpa":"/æsk/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"say something to get information or an answer","vi":"hỏi; hỏi thăm"},{"pos":"v.","en":"say that you want someone to do or give something","vi":"yêu cầu; xin"},{"pos":"v.","en":"invite someone to come somewhere or join an activity","vi":"mời"}],"examples":[{"en":"I asked the driver where the bus stopped.","vi":"Tôi đã hỏi người lái xe xem xe buýt dừng ở đâu.","audioKind":"ex"},{"en":"Schools should ask students for feedback before introducing major changes to classroom teaching methods.","vi":"Các trường học nên xin ý kiến phản hồi từ học sinh trước khi đưa ra các thay đổi lớn đối với phương pháp giảng dạy trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"ask a question","vi":"đặt câu hỏi"},{"en":"ask for help","vi":"xin giúp đỡ"},{"en":"ask someone to do something","vi":"nhờ ai làm việc gì"},{"en":"ask someone over","vi":"mời ai đến chơi nhà"}],"wordFamily":[],"synonyms":["inquire","request"],"antonyms":["answer"],"tipVi":"ask for dùng khi muốn lấy thứ gì; ask someone to do dùng khi nhờ ai làm việc gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jacket', 'en-a1-17', 'jacket', '/ˈdʒækɪt/', 'A1', 'áo khoác ngắn; áo vét-tông; bìa sách; vỏ bọc bảo vệ', 'n.', NULL, NULL, 'Jacket thường là áo khoác ngắn, không chuyên chỉ áo phông hay áo lông vũ dày.', 'I grabbed my jacket before stepping into the cold.', NULL, 'Tôi vội lấy chiếc áo khoác của mình trước khi bước ra ngoài trời lạnh.', '{"wordId":"jacket","ukIpa":"/ˈdʒækɪt/","usIpa":"/ˈdʒækɪt/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A short coat covering the upper body and arms.","vi":"áo khoác ngắn; áo vét-tông"},{"pos":"n.","en":"An outer cover that protects a book or object.","vi":"bìa sách; vỏ bọc bảo vệ"}],"examples":[{"en":"I grabbed my jacket before stepping into the cold.","vi":"Tôi vội lấy chiếc áo khoác của mình trước khi bước ra ngoài trời lạnh.","audioKind":"ex"},{"en":"A durable jacket made from recycled materials can offer consumers a more sustainable clothing choice.","vi":"Một chiếc áo khoác bền làm từ vật liệu tái chế có thể mang đến cho người tiêu dùng một lựa chọn thời trang bền vững hơn.","audioKind":"ex2"}],"collocations":[{"en":"a waterproof jacket","vi":"áo khoác chống nước"},{"en":"a suit jacket","vi":"áo khoác vest"},{"en":"a book jacket","vi":"bìa sách"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Jacket thường là áo khoác ngắn, không chuyên chỉ áo phông hay áo lông vũ dày.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jeans', 'en-a1-17', 'jeans', '/dʒiːnz/', 'A1', 'quần bò; quần jean', 'n.', NULL, NULL, 'Từ ''jeans'' luôn ở dạng số nhiều; một chiếc dùng ''a pair of jeans''.', 'These jeans are still wet from the wash.', NULL, 'Chiếc quần jean này vẫn còn ẩm sau khi giặt.', '{"wordId":"jeans","ukIpa":"/dʒiːnz/","usIpa":"/dʒiːnz/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"Trousers made from strong cotton cloth, usually denim.","vi":"quần bò; quần jean"}],"examples":[{"en":"These jeans are still wet from the wash.","vi":"Chiếc quần jean này vẫn còn ẩm sau khi giặt.","audioKind":"ex"},{"en":"Allowing employees to wear jeans may create a more relaxed workplace without necessarily reducing professional standards.","vi":"Việc cho phép nhân viên mặc quần jean có thể tạo ra một môi trường làm việc thoải mái hơn mà không nhất thiết làm giảm tiêu chuẩn nghề nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"a pair of jeans","vi":"một chiếc quần jean"},{"en":"blue jeans","vi":"quần jean xanh"},{"en":"faded jeans","vi":"quần jean bạc màu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ ''jeans'' luôn ở dạng số nhiều; một chiếc dùng ''a pair of jeans''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fire', 'en-a1-17', 'fire', '/ˈfaɪr/', 'A1', 'lửa; vụ cháy; sa thải; đuổi việc; bắn (súng); phóng (vũ khí)', 'n.', 'firefighter (n.), fireproof (adj.), fiery (adj.)', 'Đồng nghĩa: dismiss, sack · Trái nghĩa: hire', '''catch fire'' chỉ việc bắt đầu bén lửa; ''be on fire'' chỉ trạng thái đang cháy.', 'We warmed our hands by the fire after dinner.', NULL, 'Chúng tôi sưởi ấm tay bên đống lửa sau bữa tối.', '{"wordId":"fire","ukIpa":"/ˈfaɪə/","usIpa":"/ˈfaɪr/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"Burning that produces heat and light, sometimes causing damage.","vi":"lửa; vụ cháy"},{"pos":"v.","en":"To make someone leave their job.","vi":"sa thải; đuổi việc"},{"pos":"v.","en":"To shoot a gun or launch a weapon.","vi":"bắn (súng); phóng (vũ khí)"}],"examples":[{"en":"We warmed our hands by the fire after dinner.","vi":"Chúng tôi sưởi ấm tay bên đống lửa sau bữa tối.","audioKind":"ex"},{"en":"Regular safety inspections can reduce the risk of fire in older residential buildings with outdated electrical systems.","vi":"Các cuộc kiểm tra an toàn định kỳ có thể làm giảm nguy cơ hỏa hoạn ở các tòa nhà dân cư cũ với hệ thống điện đã lỗi thời.","audioKind":"ex2"}],"collocations":[{"en":"catch fire","vi":"bắt lửa"},{"en":"put out a fire","vi":"dập lửa"},{"en":"fire safety","vi":"an toàn phòng cháy chữa cháy"},{"en":"fire an employee","vi":"sa thải nhân viên"}],"wordFamily":["firefighter (n.)","fireproof (adj.)","fiery (adj.)"],"synonyms":["dismiss","sack"],"antonyms":["hire"],"tipVi":"''catch fire'' chỉ việc bắt đầu bén lửa; ''be on fire'' chỉ trạng thái đang cháy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sister', 'en-a1-17', 'sister', '/ˈsɪstər/', 'A1', 'chị gái; em gái; nữ tu sĩ', 'n.', 'sisterhood (n.), sisterly (adj.)', NULL, 'Từ sister không phân biệt chị hay em; cần dùng older hoặc older sister để chỉ chị và younger sister để chỉ em.', 'My younger sister always borrows my favourite blue jumper.', NULL, 'Em gái tôi luôn mượn chiếc áo len xanh yêu thích của tôi.', '{"wordId":"sister","ukIpa":"/ˈsɪstə/","usIpa":"/ˈsɪstər/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a female sibling","vi":"chị gái; em gái"},{"pos":"n.","en":"a woman who belongs to a religious community","vi":"nữ tu sĩ"}],"examples":[{"en":"My younger sister always borrows my favourite blue jumper.","vi":"Em gái tôi luôn mượn chiếc áo len xanh yêu thích của tôi.","audioKind":"ex"},{"en":"Children who regularly share responsibilities with a brother or sister may develop stronger cooperation skills at home.","vi":"Những đứa trẻ thường xuyên cùng anh chị em chia sẻ trách nhiệm có thể phát triển kỹ năng hợp tác tốt hơn ở nhà.","audioKind":"ex2"}],"collocations":[{"en":"an older sister","vi":"chị gái"},{"en":"a younger sister","vi":"em gái"},{"en":"a twin sister","vi":"chị em sinh đôi"},{"en":"a sister company","vi":"công ty liên kết"}],"wordFamily":["sisterhood (n.)","sisterly (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ sister không phân biệt chị hay em; cần dùng older hoặc older sister để chỉ chị và younger sister để chỉ em.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pizza', 'en-a1-17', 'pizza', '/ˈpiːtsə/', 'A1', 'bánh pizza', 'n.', NULL, NULL, 'Cả chiếc pizza là danh từ đếm được (a pizza); khi nói chung về món ăn có thể dùng some pizza.', 'We shared a mushroom pizza after the film.', NULL, 'Chúng tôi đã chia nhau ăn một chiếc bánh pizza nấm sau khi xem phim xong.', '{"wordId":"pizza","ukIpa":"/ˈpiːtsə/","usIpa":"/ˈpiːtsə/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"Flat bread baked with toppings such as tomato sauce and cheese.","vi":"bánh pizza"}],"examples":[{"en":"We shared a mushroom pizza after the film.","vi":"Chúng tôi đã chia nhau ăn một chiếc bánh pizza nấm sau khi xem phim xong.","audioKind":"ex"},{"en":"Although pizza is convenient, its nutritional value depends largely on the ingredients and portion size.","vi":"Mặc dù pizza rất tiện lợi, giá trị dinh dưỡng của nó phần lớn phụ thuộc vào các nguyên liệu và khẩu phần ăn.","audioKind":"ex2"}],"collocations":[{"en":"a slice of pizza","vi":"một miếng pizza"},{"en":"pizza dough","vi":"bột làm bánh pizza"},{"en":"order a pizza","vi":"đặt một chiếc pizza"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cả chiếc pizza là danh từ đếm được (a pizza); khi nói chung về món ăn có thể dùng some pizza.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pair', 'en-a1-17', 'pair', '/per/', 'A1', 'một đôi; một cặp; một bộ; cặp đôi; nhóm hai người; ghép đôi; kết thành cặp', 'n.', 'paired (adj.), pairing (n.)', 'Đồng nghĩa: couple, duo', 'Khi a pair of shoes làm chủ ngữ, động từ theo sau thường ở dạng số ít.', 'I left my favourite pair of gloves on the bus.', NULL, 'Tôi để quên đôi găng tay yêu thích của mình trên xe buýt.', '{"wordId":"pair","ukIpa":"/peə/","usIpa":"/per/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"Two matching things, or one object with two connected parts.","vi":"một đôi; một cặp; một bộ"},{"pos":"n.","en":"Two people who are together or work together.","vi":"cặp đôi; nhóm hai người"},{"pos":"v.","en":"To put people or things together in groups of two.","vi":"ghép đôi; kết thành cặp"}],"examples":[{"en":"I left my favourite pair of gloves on the bus.","vi":"Tôi để quên đôi găng tay yêu thích của mình trên xe buýt.","audioKind":"ex"},{"en":"Teachers often pair students with different strengths to encourage cooperation and improve learning outcomes.","vi":"Giáo viên thường ghép cặp những học sinh có điểm mạnh khác nhau để khuyến khích sự hợp tác và cải thiện kết quả học tập.","audioKind":"ex2"}],"collocations":[{"en":"a pair of shoes","vi":"một đôi giày"},{"en":"a pair of scissors","vi":"một chiếc kéo"},{"en":"work in pairs","vi":"làm việc theo cặp"},{"en":"pair up with someone","vi":"ghép cặp với ai đó"}],"wordFamily":["paired (adj.)","pairing (n.)"],"synonyms":["couple","duo"],"antonyms":[],"tipVi":"Khi a pair of shoes làm chủ ngữ, động từ theo sau thường ở dạng số ít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 28, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_17_1', 'en-a1-17', 'Cách dùng “something” (pron.) — thứ gì đó; điều gì đó; vật gì', 'something else  ·  something new  ·  something to eat', 'Tính từ bổ nghĩa cho something được đặt ở phía sau, ví dụ something useful; làm chủ ngữ thì chia động từ số ít.', 'Trái nghĩa: nothing', '[{"hanzi":"There is something soft inside this little box.","pinyin":"","meaning":"Có cái gì đó mềm mại bên trong chiếc hộp nhỏ này."},{"hanzi":"Learning something new every day can help adults remain curious and adapt to changes in the workplace.","pinyin":"","meaning":"Học hỏi một điều gì đó mới mỗi ngày giúp người lớn duy trì sự tò mò và thích nghi với những thay đổi nơi công sở."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_17_2', 'en-a1-17', 'Cách dùng “sister” (n.) — chị gái; em gái', 'an older sister  ·  a younger sister  ·  a twin sister', 'Từ sister không phân biệt chị hay em; cần dùng older hoặc older sister để chỉ chị và younger sister để chỉ em.', 'Họ từ (Word Family): sisterhood (n.), sisterly (adj.)', '[{"hanzi":"My younger sister always borrows my favourite blue jumper.","pinyin":"","meaning":"Em gái tôi luôn mượn chiếc áo len xanh yêu thích của tôi."},{"hanzi":"Children who regularly share responsibilities with a brother or sister may develop stronger cooperation skills at home.","pinyin":"","meaning":"Những đứa trẻ thường xuyên cùng anh chị em chia sẻ trách nhiệm có thể phát triển kỹ năng hợp tác tốt hơn ở nhà."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_17_3', 'en-a1-17', 'Cách dùng “front” (n.) — mặt trước; phần trước', 'front door  ·  at the front of  ·  in front of', 'in front of chỉ vị trí ở phía trước bên ngoài; at the front of chỉ phần phía trước thuộc về cấu trúc vật đó.', 'Trái nghĩa: back, rear', '[{"hanzi":"Please leave your muddy boots by the front door.","pinyin":"","meaning":"Vui lòng để những chiếc ủng dính bùn của bạn ở cửa trước."},{"hanzi":"Placing bicycle racks at the front of public buildings can encourage more residents to cycle.","pinyin":"","meaning":"Việc lắp đặt các giá để xe đạp ở phía trước các tòa nhà công cộng có thể khuyến khích nhiều cư dân đạp xe hơn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_17_4', 'en-a1-17', 'Cách dùng “left” (adj.) — bên trái; phía bên trái', 'left hand  ·  turn left  ·  on the left', 'Đây cũng là dạng quá khứ và phân từ hai của leave; khi mang nghĩa "còn lại", từ này được đặt sau danh từ.', 'Họ từ (Word Family): left-handed (adj.), leftmost (adj.) | Trái nghĩa: right', '[{"hanzi":"I carry my shopping bag in my left hand.","pinyin":"","meaning":"Tôi xách túi mua sắm bằng tay trái."},{"hanzi":"Drivers should check their mirrors carefully before turning left, especially where cyclists share the road.","pinyin":"","meaning":"Người lái xe nên quan sát kỹ gương chiếu hậu trước khi rẽ trái, đặc biệt là ở những đoạn đường đi chung với người đi xe đạp."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
