INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_17_1_1', 'en-a1-17', 'ten_17_1', 'listening', 'listening', 'I carry my shopping bag in my left hand.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chiếc váy xanh của cô ấy lay động theo từng bước chân khi cô đi lên lầu.","Quả bóng đập trúng cửa sổ và làm vỡ tan mặt kính.","Tôi xách túi mua sắm bằng tay trái.","Làm ơn đặt chiếc ô ướt của bạn cạnh cửa ra vào."]'::jsonb, 2, 'I carry my shopping bag in my left hand. → Tôi xách túi mua sắm bằng tay trái.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_17_1_2', 'en-a1-17', 'ten_17_1', 'listening', 'listening', 'Please put your wet umbrella beside the door.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Món súp này quá nóng để ăn lúc này.","Chúng tôi thường cùng nhau nấu một bữa trưa thịnh soạn vào ngày Chủ nhật.","Làm ơn đặt chiếc ô ướt của bạn cạnh cửa ra vào.","Làm ơn để những chiếc ủng dính bùn của bạn cạnh cửa hông."]'::jsonb, 2, 'Please put your wet umbrella beside the door. → Làm ơn đặt chiếc ô ướt của bạn cạnh cửa ra vào.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_17_1_3', 'en-a1-17', 'ten_17_1', 'listening', 'listening', 'We usually cook a big lunch together on Sunday.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi tìm thấy một ngôi nhà tranh xinh xắn nằm bên cạnh con suối thanh bình.","Chúng tôi thường cùng nhau nấu một bữa trưa thịnh soạn vào ngày Chủ nhật.","Chiếc váy xanh của cô ấy lay động theo từng bước chân khi cô đi lên lầu.","Làm ơn đặt chiếc ô ướt của bạn cạnh cửa ra vào."]'::jsonb, 1, 'We usually cook a big lunch together on Sunday. → Chúng tôi thường cùng nhau nấu một bữa trưa thịnh soạn vào ngày Chủ nhật.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_17_2', 'en-a1-17', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_17_2_1', 'ten_17_2', 'left', 'Drivers should check their mirrors carefully before turning left, especially where cyclists share the road.', 'Drivers should check their mirrors carefully before turning left, especially where cyclists share the road.', '/left/', 'Người lái xe nên quan sát kỹ gương chiếu hậu trước khi rẽ trái, đặc biệt là ở những đoạn đường đi chung với người đi xe đạp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_17_2_2', 'ten_17_2', 'put', 'Rising housing costs put considerable pressure on young people who are starting their careers.', 'Rising housing costs put considerable pressure on young people who are starting their careers.', '/pʊt/', 'Chi phí nhà ở gia tăng đặt áp lực đáng kể lên những người trẻ tuổi mới bắt đầu sự nghiệp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_17_2_3', 'ten_17_2', 'Sunday', 'Opening public libraries on Sunday allows people with busy weekday schedules to access essential community services.', 'Opening public libraries on Sunday allows people with busy weekday schedules to access essential community services.', '/ˈsʌndeɪ/', 'Việc mở cửa các thư viện công cộng vào ngày Chủ nhật giúp những người bận rộn vào các ngày trong tuần có thể tiếp cận các dịch vụ cộng đồng thiết yếu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_17_2_4', 'ten_17_2', 'skirt', 'Public discussions often skirt the issue of who should pay for environmental protection.', 'Public discussions often skirt the issue of who should pay for environmental protection.', '/skɝːt/', 'Các cuộc thảo luận công khai thường né tránh vấn đề ai là người nên chi trả cho công tác bảo vệ môi trường.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_17_2_5', 'ten_17_2', 'side', 'Public debates should consider both sides of an issue before any major policy decision is made.', 'Public debates should consider both sides of an issue before any major policy decision is made.', '/saɪd/', 'Các cuộc tranh luận công khai nên xem xét cả hai mặt của vấn đề trước khi đưa ra bất kỳ quyết định chính sách lớn nào.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_17_2_6', 'ten_17_2', 'pretty', 'Although pretty public gardens attract visitors, cities must also ensure that these spaces remain accessible to residents.', 'Although pretty public gardens attract visitors, cities must also ensure that these spaces remain accessible to residents.', '/ˈprɪti/', 'Mặc dù những khu vườn công cộng xinh đẹp thu hút khách du lịch, các thành phố cũng phải đảm bảo rằng không gian này vẫn thuận tiện cho người dân sử dụng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_17_2_1', 'en-a1-17', 'ten_17_2', 'listening', 'listening', 'Drivers should check their mirrors carefully before turning left, especially where cyclists share the road.', NULL, 'Trong câu vừa nghe, từ “left” mang nghĩa nào sau đây?', '["mọi người; tất cả mọi người","bên trái; phía bên trái","dễ dàng; không phức tạp","chú; bác; cậu; dượng"]'::jsonb, 1, '“left” (/left/): bên trái; phía bên trái. Câu đầy đủ: Drivers should check their mirrors carefully before turning left, especially where cyclists share the road.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
