INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_17_4', 'en-a1-17', NULL, 'comprehensive_test', 'listening', 'Her blue skirt swayed as she walked upstairs.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi để quên ô trên xe buýt ngày hôm qua.","Tôi đã hỏi người lái xe xem xe buýt dừng ở đâu.","Chiếc váy xanh của cô ấy lay động theo từng bước chân khi cô đi lên lầu.","Chiếc quần jean này vẫn còn ẩm sau khi giặt."]'::jsonb, 2, 'Her blue skirt swayed as she walked upstairs. → Chiếc váy xanh của cô ấy lay động theo từng bước chân khi cô đi lên lầu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
