INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_17_6', 'en-a1-17', NULL, 'comprehensive_test', 'listening', 'We found a pretty cottage beside a quiet stream.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi tìm thấy một ngôi nhà tranh xinh xắn nằm bên cạnh con suối thanh bình.","Chiếc quần jean này vẫn còn ẩm sau khi giặt.","Tôi xách túi mua sắm bằng tay trái.","Tôi tưới chậu xương rồng nhỏ này hai tuần một lần."]'::jsonb, 0, 'We found a pretty cottage beside a quiet stream. → Chúng tôi tìm thấy một ngôi nhà tranh xinh xắn nằm bên cạnh con suối thanh bình.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_17_7', 'en-a1-17', NULL, 'comprehensive_test', 'listening', 'too', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["con thỏ","quá (vượt mức mong muốn, cần thiết hoặc phù hợp)","tóc, lông mọc trên da người và động vật","đội; nhóm"]'::jsonb, 1, 'too (/tuː/) → quá (vượt mức mong muốn, cần thiết hoặc phù hợp); cũng; ngoài ra', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_17_8', 'en-a1-17', NULL, 'comprehensive_test', 'listening', 'The ball hit the window and shattered the glass.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã hỏi người lái xe xem xe buýt dừng ở đâu.","Món súp này quá nóng để ăn lúc này.","Quả bóng đập trúng cửa sổ và làm vỡ tan mặt kính.","Làm ơn đặt chiếc ô ướt của bạn cạnh cửa ra vào."]'::jsonb, 2, 'The ball hit the window and shattered the glass. → Quả bóng đập trúng cửa sổ và làm vỡ tan mặt kính.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_17_9', 'en-a1-17', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “An edge or surface of something, or the space beside it.”?', '["skirt","side","letter","pizza"]'::jsonb, 1, 'side (/saɪd/) → bên; mặt bên; cạnh', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_17_10', 'en-a1-17', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Attractive and pleasant to look at.”?', '["fire","left","night","pretty"]'::jsonb, 3, 'pretty (/ˈprɪti/) → xinh đẹp; xinh xắn; ưa nhìn', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_17_11', 'en-a1-17', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “more than is wanted, needed, or suitable”?', '["too","sock","night","pizza"]'::jsonb, 0, 'too (/tuː/) → quá (vượt mức mong muốn, cần thiết hoặc phù hợp)', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_17_12', 'en-a1-17', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A hard, usually transparent material used for windows and containers.”?', '["ask","fire","skirt","glass"]'::jsonb, 3, 'glass (/ɡlæs/) → chất liệu kính, thủy tinh cứng, thường trong suốt dùng làm cửa sổ và vật dụng', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_17_13', 'en-a1-17', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Used to connect alternatives or choices”?', '["bad","or","night","something"]'::jsonb, 1, 'or (/ɔːr/) → hoặc; hay (dùng để nối các lựa chọn)', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
