INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_17_18', 'en-a1-17', NULL, 'comprehensive_test', 'reading', NULL, 'Drivers should check their mirrors carefully before turning left, especially where cyclists share the road.', 'Dựa vào câu trên, từ “left” có nghĩa phù hợp nhất là gì?', '["bên trái; phía bên trái","tại sao; vì sao","học sinh; sinh viên","sơn; chất màu"]'::jsonb, 0, 'left: bên trái; phía bên trái; sang bên trái; ở bên trái; còn lại; thừa lại. Dịch cả câu: Người lái xe nên quan sát kỹ gương chiếu hậu trước khi rẽ trái, đặc biệt là ở những đoạn đường đi chung với người đi xe đạp.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_17_19', 'en-a1-17', NULL, 'comprehensive_test', 'reading', NULL, 'Rising housing costs put considerable pressure on young people who are starting their careers.', 'Dựa vào câu trên, từ “put” có nghĩa phù hợp nhất là gì?', '["vé; thẻ lên tàu xe; vé vào cửa","đặt; để; bố trí","đủ","vào trong; đến bên trong"]'::jsonb, 1, 'put: đặt; để; bố trí; diễn đạt; bày tỏ; làm cho ai/cái gì rơi vào trạng thái nào đó. Dịch cả câu: Chi phí nhà ở gia tăng đặt áp lực đáng kể lên những người trẻ tuổi mới bắt đầu sự nghiệp.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_17_20', 'en-a1-17', NULL, 'comprehensive_test', 'reading', NULL, 'Opening public libraries on Sunday allows people with busy weekday schedules to access essential community services.', 'Dựa vào câu trên, từ “Sunday” có nghĩa phù hợp nhất là gì?', '["tuyệt vời; kỳ diệu","ngày Chủ nhật","Nhật Bản","đủ"]'::jsonb, 1, 'Sunday: ngày Chủ nhật. Dịch cả câu: Việc mở cửa các thư viện công cộng vào ngày Chủ nhật giúp những người bận rộn vào các ngày trong tuần có thể tiếp cận các dịch vụ cộng đồng thiết yếu.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_17_21', 'en-a1-17', NULL, 'comprehensive_test', 'reading', NULL, 'Public discussions often skirt the issue of who should pay for environmental protection.', 'Dựa vào câu trên, từ “skirt” có nghĩa phù hợp nhất là gì?', '["hai lần","lỗi; sai sót; sự nhầm lẫn","bga; trạm dừng","váy (trang phục từ eo thả xuống, không chia ống)"]'::jsonb, 3, 'skirt: váy (trang phục từ eo thả xuống, không chia ống); đi vòng quanh mép; đi dọc theo rìa; tránh né; né tránh trực tiếp. Dịch cả câu: Các cuộc thảo luận công khai thường né tránh vấn đề ai là người nên chi trả cho công tác bảo vệ môi trường.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_17_22', 'en-a1-17', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chị gái; em gái”', '["leg","enough","shop","sister"]'::jsonb, 3, 'chị gái; em gái → sister (/ˈsɪstər/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_17_23', 'en-a1-17', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bánh pizza”', '["with","when","pizza","they"]'::jsonb, 2, 'bánh pizza → pizza (/ˈpiːtsə/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_17_24', 'en-a1-17', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “một đôi; một cặp; một bộ”', '["flat","pair","friendly","stay"]'::jsonb, 1, 'một đôi; một cặp; một bộ → pair (/per/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-18', 'en', 'Bài 18: Đời sống hằng ngày (3) - CEFR A1', 'CEFR A1', 'A1 · Đời sống', '28 từ vựng Tiếng Anh CEFR A1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1018, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_yourself', 'en-a1-18', 'yourself', '/jʊrˈself/', 'A1', 'chính bạn; bản thân bạn; chính ngài; chính bạn (dùng để nhấn mạnh)', 'pron.', 'you (pron.), your (det.), yours (pron.), yourselves (pron.)', NULL, 'Dùng cho đại từ số ít you; khi nói với nhiều người ''các bạn tự làm'' thì dùng yourselves.', 'Be careful not to cut yourself with that knife.', NULL, 'Hãy cẩn thận kẻo tự cắt vào tay mình bằng con dao đó.', '{"wordId":"yourself","ukIpa":"/jɔːˈself/","usIpa":"/jʊrˈself/","cefr":"A1","topic":"daily","senses":[{"pos":"pron.","en":"Used when you are both the subject and object.","vi":"chính bạn; bản thân bạn"},{"pos":"pron.","en":"Used to emphasize the person being addressed.","vi":"chính ngài; chính bạn (dùng để nhấn mạnh)"}],"examples":[{"en":"Be careful not to cut yourself with that knife.","vi":"Hãy cẩn thận kẻo tự cắt vào tay mình bằng con dao đó.","audioKind":"ex"},{"en":"Preparing meals yourself can reduce household spending while giving you greater control over nutritional quality.","vi":"Tự nấu ăn có thể giúp giảm chi phí sinh hoạt đồng thời giúp bạn kiểm soát tốt hơn chất lượng dinh dưỡng.","audioKind":"ex2"}],"collocations":[{"en":"by yourself","vi":"tự mình; một mình"},{"en":"help yourself to","vi":"cứ tự nhiên dùng"},{"en":"enjoy yourself","vi":"chơi vui vẻ nhé"},{"en":"be yourself","vi":"là chính mình"}],"wordFamily":["you (pron.)","your (det.)","yours (pron.)","yourselves (pron.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng cho đại từ số ít you; khi nói với nhiều người ''các bạn tự làm'' thì dùng yourselves.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_last', 'en-a1-18', 'last', '/læst/', 'A1', 'cuối cùng; gần đây nhất; kéo dài; đủ dùng; sau cùng; lần gần đây nhất', 'adj.', 'lasting (adj.), lastly (adv.)', 'Đồng nghĩa: final, previous · Trái nghĩa: first', 'last week chỉ tuần trước; the last week có thể chỉ tuần cuối cùng.', 'I caught the last bus home just before midnight.', NULL, 'Tôi vừa kịp bắt chuyến xe buýt cuối cùng về nhà ngay trước nửa đêm.', '{"wordId":"last","ukIpa":"/lɑːst/","usIpa":"/læst/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Final in a sequence, or most recent before the present.","vi":"cuối cùng; gần đây nhất"},{"pos":"v.","en":"To continue for a period or remain usable.","vi":"kéo dài; đủ dùng"},{"pos":"adv.","en":"After everyone else, or on the most recent previous occasion.","vi":"sau cùng; lần gần đây nhất"}],"examples":[{"en":"I caught the last bus home just before midnight.","vi":"Tôi vừa kịp bắt chuyến xe buýt cuối cùng về nhà ngay trước nửa đêm.","audioKind":"ex"},{"en":"Products that last longer can reduce household spending and limit the amount of waste sent to landfill.","vi":"Những sản phẩm có độ bền cao hơn có thể giúp giảm chi phí sinh hoạt cho gia đình và hạn chế lượng rác thải đưa ra các bãi chôn lấp.","audioKind":"ex2"}],"collocations":[{"en":"last week","vi":"tuần trước"},{"en":"last chance","vi":"cơ hội cuối cùng"},{"en":"last for years","vi":"kéo dài nhiều năm"},{"en":"last a lifetime","vi":"bền suốt đời"}],"wordFamily":["lasting (adj.)","lastly (adv.)"],"synonyms":["final","previous"],"antonyms":["first"],"tipVi":"last week chỉ tuần trước; the last week có thể chỉ tuần cuối cùng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_listen', 'en-a1-18', 'listen', '/ˈlɪsən/', 'A1', 'lắng nghe; chú ý lắng nghe; lắng nghe; tiếp thu lời khuyên', 'v.', 'listener (n.), listening (n.)', NULL, 'Khi có đối tượng cần dùng listen to; hear nhấn mạnh kết quả của việc nghe.', 'I listen to music while cooking dinner every evening.', NULL, 'Tôi thường nghe nhạc trong lúc nấu bữa tối vào mỗi buổi tối.', '{"wordId":"listen","ukIpa":"/ˈlɪsən/","usIpa":"/ˈlɪsən/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to pay attention to sounds or what someone is saying","vi":"lắng nghe; chú ý lắng nghe"},{"pos":"v.","en":"to take someone''s advice or warnings seriously","vi":"lắng nghe; tiếp thu lời khuyên"}],"examples":[{"en":"I listen to music while cooking dinner every evening.","vi":"Tôi thường nghe nhạc trong lúc nấu bữa tối vào mỗi buổi tối.","audioKind":"ex"},{"en":"Local authorities should listen to residents before making decisions that significantly affect their neighbourhoods.","vi":"Chính quyền địa phương nên lắng nghe ý kiến người dân trước khi đưa ra các quyết định ảnh hưởng lớn đến khu dân cư của họ.","audioKind":"ex2"}],"collocations":[{"en":"listen to music","vi":"nghe nhạc"},{"en":"listen carefully","vi":"lắng nghe cẩn thận"},{"en":"listen to advice","vi":"lắng nghe lời khuyên"}],"wordFamily":["listener (n.)","listening (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi có đối tượng cần dùng listen to; hear nhấn mạnh kết quả của việc nghe.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_toothpaste', 'en-a1-18', 'toothpaste', '/ˈtuːθpeɪst/', 'A1', 'kem đánh răng', 'n.', NULL, NULL, 'toothpaste là danh từ không đếm được; một tuýp kem đánh răng dùng a tube of toothpaste.', 'I squeezed some toothpaste onto my brush before breakfast.', NULL, 'Tôi nặn một ít kem đánh răng lên bàn chải trước bữa sáng.', '{"wordId":"toothpaste","ukIpa":"/ˈtuːθpeɪst/","usIpa":"/ˈtuːθpeɪst/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A substance used with a toothbrush to clean teeth.","vi":"kem đánh răng"}],"examples":[{"en":"I squeezed some toothpaste onto my brush before breakfast.","vi":"Tôi nặn một ít kem đánh răng lên bàn chải trước bữa sáng.","audioKind":"ex"},{"en":"Regular brushing with fluoride toothpaste helps prevent tooth decay and can reduce the need for costly dental treatment.","vi":"Đánh răng thường xuyên bằng kem đánh răng chứa florua giúp ngăn ngừa sâu răng và giảm nhu cầu điều trị nha khoa tốn kém.","audioKind":"ex2"}],"collocations":[{"en":"a tube of toothpaste","vi":"một tuýp kem đánh răng"},{"en":"fluoride toothpaste","vi":"kem đánh răng chứa florua"},{"en":"squeeze out toothpaste","vi":"nặn kem đánh răng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"toothpaste là danh từ không đếm được; một tuýp kem đánh răng dùng a tube of toothpaste.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_banana', 'en-a1-18', 'banana', '/bəˈnænə/', 'A1', 'quả chuối', 'n.', NULL, NULL, 'Danh từ đếm được: một quả chuối là a banana.', 'He peeled a banana and sliced it over his cereal.', NULL, 'Anh ấy bóc vỏ một quả chuối và cắt lát lên bát ngũ cốc của mình.', '{"wordId":"banana","ukIpa":"/bəˈnɑːnə/","usIpa":"/bəˈnænə/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A long curved fruit with soft flesh and usually yellow skin","vi":"quả chuối"}],"examples":[{"en":"He peeled a banana and sliced it over his cereal.","vi":"Anh ấy bóc vỏ một quả chuối và cắt lát lên bát ngũ cốc của mình.","audioKind":"ex"},{"en":"Banana farming provides an important source of income for many families in tropical regions.","vi":"Trồng chuối mang lại nguồn thu nhập quan trọng cho nhiều gia đình ở các vùng nhiệt đới.","audioKind":"ex2"}],"collocations":[{"en":"ripe banana","vi":"chuối chín"},{"en":"banana peel","vi":"vỏ chuối"},{"en":"a bunch of bananas","vi":"một buồng chuối; một nải chuối"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ đếm được: một quả chuối là a banana.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_menu', 'en-a1-18', 'menu', '/ˈmenjuː/', 'A1', 'thực đơn; thực đơn (trên máy tính hoặc thiết bị điện tử); bảng chọn', 'n.', NULL, NULL, 'Nói món ăn có trong thực đơn, dùng on the menu, không dùng in.', 'There are several vegetarian dishes on the menu.', NULL, 'Có một số món chay trong thực đơn.', '{"wordId":"menu","ukIpa":"/ˈmenjuː/","usIpa":"/ˈmenjuː/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A list of food and drinks available to order","vi":"thực đơn"},{"pos":"n.","en":"A list of choices available on a computer or device","vi":"thực đơn (trên máy tính hoặc thiết bị điện tử); bảng chọn"}],"examples":[{"en":"There are several vegetarian dishes on the menu.","vi":"Có một số món chay trong thực đơn.","audioKind":"ex"},{"en":"Displaying nutritional information on a restaurant menu may help customers make healthier choices when eating out.","vi":"Việc hiển thị thông tin dinh dưỡng trên thực đơn nhà hàng có thể giúp khách hàng đưa ra lựa chọn lành mạnh hơn khi đi ăn ngoài.","audioKind":"ex2"}],"collocations":[{"en":"on the menu","vi":"có trong thực đơn"},{"en":"set menu","vi":"thực đơn chọn gói; suất ăn trọn gói"},{"en":"drop-down menu","vi":"thực đơn thả xuống"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nói món ăn có trong thực đơn, dùng on the menu, không dùng in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_line', 'en-a1-18', 'line', '/laɪn/', 'A1', 'đường; nét; vạch; hàng; dãy; hàng người; tuyến; đường dây; đường ống', 'n.', 'lined (adj.), lining (n.)', NULL, 'Xếp hàng trong tiếng Anh Mỹ thường dùng stand in line, tiếng Anh Anh dùng queue.', 'Draw a straight line across the page with your ruler.', NULL, 'Hãy dùng thước kẻ vẽ một đường thẳng ngang qua trang giấy.', '{"wordId":"line","ukIpa":"/laɪn/","usIpa":"/laɪn/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a long, thin mark on a surface","vi":"đường; nét; vạch"},{"pos":"n.","en":"people or things arranged one behind or beside another","vi":"hàng; dãy; hàng người"},{"pos":"n.","en":"a route or connection for transport or communication","vi":"tuyến; đường dây; đường ống"}],"examples":[{"en":"Draw a straight line across the page with your ruler.","vi":"Hãy dùng thước kẻ vẽ một đường thẳng ngang qua trang giấy.","audioKind":"ex"},{"en":"Extending the railway line could connect rural communities with employment opportunities in nearby cities.","vi":"Việc kéo dài tuyến đường sắt có thể kết nối các cộng đồng nông thôn với cơ hội việc làm tại các thành phố lân cận.","audioKind":"ex2"}],"collocations":[{"en":"straight line","vi":"đường thẳng"},{"en":"stand in line","vi":"xếp hàng"},{"en":"railway line","vi":"tuyến đường sắt"},{"en":"telephone line","vi":"đường dây điện thoại"}],"wordFamily":["lined (adj.)","lining (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Xếp hàng trong tiếng Anh Mỹ thường dùng stand in line, tiếng Anh Anh dùng queue.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mister', 'en-a1-18', 'Mister', '/ˈmɪstɚ/', 'A1', 'ông', 'n.', NULL, NULL, 'Thường viết tắt là Mr (Mỹ là Mr.), phát âm là Mister, theo sau là họ.', 'The children greeted their new neighbour as Mister Green.', NULL, 'Bọn trẻ chào người hàng xóm mới của chúng là ông Green.', '{"wordId":"mister","ukIpa":"/ˈmɪstə/","usIpa":"/ˈmɪstɚ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A title used before a man''s surname or full name","vi":"ông"}],"examples":[{"en":"The children greeted their new neighbour as Mister Green.","vi":"Bọn trẻ chào người hàng xóm mới của chúng là ông Green.","audioKind":"ex"},{"en":"In formal interviews, candidates may address a male interviewer as Mister followed by his surname.","vi":"Trong các buổi phỏng vấn trang trọng, ứng viên có thể gọi người phỏng vấn nam là Mister đi kèm với họ của ông ấy.","audioKind":"ex2"}],"collocations":[{"en":"Mister President","vi":"Thưa ngài Chủ tịch nước"},{"en":"Mister Chairman","vi":"Thưa ngài Chủ tịch"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường viết tắt là Mr (Mỹ là Mr.), phát âm là Mister, theo sau là họ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_door', 'en-a1-18', 'door', '/dɔːr/', 'A1', 'cửa; cửa ra vào', 'n.', 'doorway (n.), doorknob (n.), doorbell (n.)', NULL, 'at the door chỉ ở ngay ngoài cửa; answer the door chỉ hành động ra mở cửa khi có người gọi.', 'Please close the door before the cat gets out.', NULL, 'Xin hãy đóng cửa lại trước khi con mèo chạy ra ngoài.', '{"wordId":"door","ukIpa":"/dɔː/","usIpa":"/dɔːr/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A movable barrier used to open or close an entrance.","vi":"cửa; cửa ra vào"}],"examples":[{"en":"Please close the door before the cat gets out.","vi":"Xin hãy đóng cửa lại trước khi con mèo chạy ra ngoài.","audioKind":"ex"},{"en":"Installing wider doors in public buildings can make everyday journeys easier for people who use wheelchairs.","vi":"Việc lắp đặt các ô cửa rộng hơn trong các công việc công cộng có thể giúp việc di chuyển hàng ngày trở nên dễ dàng hơn đối với những người ngồi xe lăn.","audioKind":"ex2"}],"collocations":[{"en":"front door","vi":"cửa chính; cửa trước"},{"en":"answer the door","vi":"ra mở cửa"},{"en":"knock on the door","vi":"gõ cửa"}],"wordFamily":["doorway (n.)","doorknob (n.)","doorbell (n.)"],"synonyms":[],"antonyms":[],"tipVi":"at the door chỉ ở ngay ngoài cửa; answer the door chỉ hành động ra mở cửa khi có người gọi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_october', 'en-a1-18', 'October', '/ɑːkˈtoʊbər/', 'A1', 'tháng mười', 'n.', NULL, NULL, 'Tháng viết hoa chữ cái đầu; dùng in trước tên tháng, on trước ngày cụ thể.', 'Our local swimming pool will open again in October.', NULL, 'Hồ bơi địa phương của chúng tôi sẽ mở cửa trở lại vào tháng mười.', '{"wordId":"october","ukIpa":"/ɒkˈtəʊbə/","usIpa":"/ɑːkˈtoʊbər/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The tenth month of the year, between September and November.","vi":"tháng mười"}],"examples":[{"en":"Our local swimming pool will open again in October.","vi":"Hồ bơi địa phương của chúng tôi sẽ mở cửa trở lại vào tháng mười.","audioKind":"ex"},{"en":"The university begins its annual community research programme in October, giving students opportunities to investigate local environmental issues.","vi":"Trường đại học bắt đầu chương trình nghiên cứu cộng đồng hàng năm vào tháng mười, tạo cơ hội cho sinh viên điều tra các vấn đề môi trường địa phương.","audioKind":"ex2"}],"collocations":[{"en":"in October","vi":"vào tháng mười"},{"en":"early October","vi":"đầu tháng mười"},{"en":"late October","vi":"cuối tháng mười"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tháng viết hoa chữ cái đầu; dùng in trước tên tháng, on trước ngày cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_room', 'en-a1-18', 'room', '/ruːm/', 'A1', 'phòng; buồng; không gian; khoảng trống; cơ hội', 'n.', 'roomy (adj.), roommate (n.)', NULL, 'Phòng (room) đếm được khi chỉ căn phòng; không đếm được khi chỉ không gian hoặc cơ hội.', 'My room has a desk beside the window.', NULL, 'Phòng của tôi có một chiếc bàn làm việc bên cạnh cửa sổ.', '{"wordId":"room","ukIpa":"/ruːm/","usIpa":"/ruːm/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A part of a building separated by walls and doors.","vi":"phòng; buồng"},{"pos":"n.","en":"Available space or opportunity for something.","vi":"không gian; khoảng trống; cơ hội"}],"examples":[{"en":"My room has a desk beside the window.","vi":"Phòng của tôi có một chiếc bàn làm việc bên cạnh cửa sổ.","audioKind":"ex"},{"en":"Although public transport has improved significantly, there is still room for further investment in rural services.","vi":"Mặc dù giao thông công cộng đã được cải thiện đáng kể, vẫn còn không gian cho việc đầu tư thêm vào các dịch vụ nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"living room","vi":"phòng khách"},{"en":"make room for","vi":"dành chỗ cho; nhường chỗ cho"},{"en":"room for improvement","vi":"dư địa để cải thiện"}],"wordFamily":["roomy (adj.)","roommate (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Phòng (room) đếm được khi chỉ căn phòng; không đếm được khi chỉ không gian hoặc cơ hội.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rest', 'en-a1-18', 'rest', '/rest/', 'A1', 'sự nghỉ ngơi; khoảng thời gian thư giãn; nghỉ ngơi; thư giãn để phục hồi sức lực; phần còn lại; những người hoặc vật còn lại', 'n.', 'restful (adj.), restless (adj.), rested (adj.)', NULL, 'the rest of đi với danh từ, động từ chia số ít hay số nhiều tùy thuộc vào danh từ theo sau.', 'Let''s have a rest under that shady tree.', NULL, 'Chúng ta hãy nghỉ ngơi dưới gốc cây râm mát đó nhé.', '{"wordId":"rest","ukIpa":"/rest/","usIpa":"/rest/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a period of relaxing without working or being active","vi":"sự nghỉ ngơi; khoảng thời gian thư giãn"},{"pos":"v.","en":"to relax or allow someone or something to recover","vi":"nghỉ ngơi; thư giãn để phục hồi sức lực"},{"pos":"n.","en":"the people or things that remain","vi":"phần còn lại; những người hoặc vật còn lại"}],"examples":[{"en":"Let''s have a rest under that shady tree.","vi":"Chúng ta hãy nghỉ ngơi dưới gốc cây râm mát đó nhé.","audioKind":"ex"},{"en":"Regular periods of rest can help employees maintain concentration and reduce the risk of workplace accidents.","vi":"Những khoảng thời gian nghỉ ngơi đều đặn có thể giúp nhân viên duy trì sự tập trung và giảm nguy cơ tai nạn nơi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"have a rest","vi":"nghỉ ngơi một lát"},{"en":"get some rest","vi":"tranh thủ nghỉ ngơi"},{"en":"the rest of","vi":"phần còn lại của"}],"wordFamily":["restful (adj.)","restless (adj.)","rested (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"the rest of đi với danh từ, động từ chia số ít hay số nhiều tùy thuộc vào danh từ theo sau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aunt', 'en-a1-18', 'aunt', '/ænt/', 'A1', 'cô; dì; bác gái; mợ; thím', 'n.', 'auntie (n.)', NULL, 'Không phân biệt họ hàng bên nội hay bên ngoại; phát âm tiếng Anh Mỹ thường là /ɑːnt/.', 'My aunt taught me how to bake bread.', NULL, 'Dì của tôi đã dạy tôi cách nướng bánh mì.', '{"wordId":"aunt","ukIpa":"/ɑːnt/","usIpa":"/ænt/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"Your parent''s sister, or the wife of your parent''s sibling.","vi":"cô; dì; bác gái; mợ; thím"}],"examples":[{"en":"My aunt taught me how to bake bread.","vi":"Dì của tôi đã dạy tôi cách nướng bánh mì.","audioKind":"ex"},{"en":"Extended family members, such as aunts and uncles, often provide valuable childcare support for working parents.","vi":"Các thành viên trong đại gia đình như cô, dì, chú, bác thường cung cấp sự hỗ trợ chăm sóc trẻ em quý giá cho các bậc cha mẹ bận đi làm.","audioKind":"ex2"}],"collocations":[{"en":"aunt and uncle","vi":"cô dì chú bác và các thân nhân khác"},{"en":"maternal aunt","vi":"dì (bên mẹ)"},{"en":"paternal aunt","vi":"cô (bên bố)"}],"wordFamily":["auntie (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Không phân biệt họ hàng bên nội hay bên ngoại; phát âm tiếng Anh Mỹ thường là /ɑːnt/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_watch', 'en-a1-18', 'watch', '/wɑːtʃ/', 'A1', 'xem; quan sát; theo dõi; đồng hồ đeo tay; trông nom; canh chừng; đề phòng', 'v.', 'watcher (n.), watchful (adj.), watchfulness (n.)', 'Đồng nghĩa: observe', 'watch nhấn mạnh việc quan sát có chú ý trong một khoảng thời gian; see nhấn mạnh kết quả nhìn thấy.', 'We watched the ducks swimming across the quiet pond.', NULL, 'Chúng tôi ngắm nhìn những chú vịt bơi lội qua ao nước yên bình.', '{"wordId":"watch","ukIpa":"/wɒtʃ/","usIpa":"/wɑːtʃ/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To look at something attentively for a period of time.","vi":"xem; quan sát; theo dõi"},{"pos":"n.","en":"A small clock worn on the wrist or carried.","vi":"đồng hồ đeo tay"},{"pos":"v.","en":"To take care of someone or look for possible danger.","vi":"trông nom; canh chừng; đề phòng"}],"examples":[{"en":"We watched the ducks swimming across the quiet pond.","vi":"Chúng tôi ngắm nhìn những chú vịt bơi lội qua ao nước yên bình.","audioKind":"ex"},{"en":"Students who watch educational programmes may gain useful knowledge, but active discussion helps deepen their understanding.","vi":"Những học sinh xem các chương trình giáo dục có thể thu, nhưng thảo luận tích cực giúp đào sâu hiểu biết của các em.","audioKind":"ex2"}],"collocations":[{"en":"watch television","vi":"xem tivi"},{"en":"watch closely","vi":"quan sát kỹ"},{"en":"wear a watch","vi":"đeo đồng hồ đeo tay"},{"en":"watch out","vi":"cẩn thận; chú ý"}],"wordFamily":["watcher (n.)","watchful (adj.)","watchfulness (n.)"],"synonyms":["observe"],"antonyms":[],"tipVi":"watch nhấn mạnh việc quan sát có chú ý trong một khoảng thời gian; see nhấn mạnh kết quả nhìn thấy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sometimes', 'en-a1-18', 'sometimes', '/ˈsʌmtaɪmz/', 'A1', 'thỉnh thoảng; đôi khi', 'adv.', NULL, 'Đồng nghĩa: occasionally, at times · Trái nghĩa: always, never', 'sometimes là trạng từ chỉ tần suất (đôi khi); some time là danh từ chỉ một khoảng thời gian.', 'I sometimes take the longer route home through the park.', NULL, 'Tôi thỉnh thoảng đi con đường dài hơn về nhà qua công viên.', '{"wordId":"sometimes","ukIpa":"/ˈsʌmtaɪmz/","usIpa":"/ˈsʌmtaɪmz/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"on certain occasions, but not always or regularly","vi":"thỉnh thoảng; đôi khi"}],"examples":[{"en":"I sometimes take the longer route home through the park.","vi":"Tôi thỉnh thoảng đi con đường dài hơn về nhà qua công viên.","audioKind":"ex"},{"en":"Working from home sometimes improves productivity, although its benefits depend on suitable equipment and a quiet environment.","vi":"Làm việc tại nhà đôi khi cải thiện năng suất, mặc dù lợi ích của nó phụ thuộc vào thiết bị phù hợp và môi trường yên tĩnh.","audioKind":"ex2"}],"collocations":[{"en":"sometimes feel","vi":"đôi khi cảm thấy"},{"en":"sometimes happen","vi":"thỉnh thoảng xảy ra"},{"en":"only sometimes","vi":"chỉ thỉnh thoảng"}],"wordFamily":[],"synonyms":["occasionally","at times"],"antonyms":["always","never"],"tipVi":"sometimes là trạng từ chỉ tần suất (đôi khi); some time là danh từ chỉ một khoảng thời gian.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fine', 'en-a1-18', 'fine', '/faɪn/', 'A1', 'tốt; khỏe mạnh; hay; chất lượng cao; mịn; nhỏ; mảnh; thanh mảnh; tiền phạt; án phạt tiền', 'adj.', 'finely (adv.), fineness (n.)', NULL, 'fine khi là động từ cũng có nghĩa là phạt tiền ai đó: fine sb for sth.', 'I feel fine now, so let''s go for a walk.', NULL, 'Bây giờ tôi thấy khỏe rồi, chúng ta đi dạo nhé.', '{"wordId":"fine","ukIpa":"/faɪn/","usIpa":"/faɪn/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Good, satisfactory, healthy, or of high quality.","vi":"tốt; khỏe mạnh; hay; chất lượng cao"},{"pos":"adj.","en":"Made of very small particles or having little thickness.","vi":"mịn; nhỏ; mảnh; thanh mảnh"},{"pos":"n.","en":"Money that must be paid as punishment for breaking rules.","vi":"tiền phạt; án phạt tiền"}],"examples":[{"en":"I feel fine now, so let''s go for a walk.","vi":"Bây giờ tôi thấy khỏe rồi, chúng ta đi dạo nhé.","audioKind":"ex"},{"en":"A substantial fine may discourage companies from dumping industrial waste into rivers and damaging local ecosystems.","vi":"Khoản tiền phạt nặng có thể ngăn chặn các công ty xả thải công nghiệp xuống sông ngòi và làm tàn phá các hệ sinh thái địa phương.","audioKind":"ex2"}],"collocations":[{"en":"feel fine","vi":"cảm thấy khỏe"},{"en":"fine sand","vi":"cát mịn"},{"en":"pay a fine","vi":"nộp tiền phạt"},{"en":"fine art","vi":"mỹ thuật"}],"wordFamily":["finely (adv.)","fineness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"fine khi là động từ cũng có nghĩa là phạt tiền ai đó: fine sb for sth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_card', 'en-a1-18', 'card', '/kɑːrd/', 'A1', 'thẻ; thẻ cứng (dùng để thanh toán, định danh, thông tin); thiệp (chúc mừng); quân bài (trong bộ bài)', 'n.', NULL, NULL, 'play cards là chơi bài, dùng danh từ cards ở số nhiều và không có mạo từ đi trước.', 'I tapped my card to pay for the groceries.', NULL, 'Tôi đã quẹt thẻ để thanh toán tiền mua hàng tạp hóa.', '{"wordId":"card","ukIpa":"/kɑːd/","usIpa":"/kɑːrd/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A small stiff rectangle used for payment, identification, or information.","vi":"thẻ; thẻ cứng (dùng để thanh toán, định danh, thông tin)"},{"pos":"n.","en":"A decorated card sent with a greeting or personal message.","vi":"thiệp (chúc mừng)"},{"pos":"n.","en":"One of a set of small rectangles used in games.","vi":"quân bài (trong bộ bài)"}],"examples":[{"en":"I tapped my card to pay for the groceries.","vi":"Tôi đã quẹt thẻ để thanh toán tiền mua hàng tạp hóa.","audioKind":"ex"},{"en":"Providing every student with a library card encourages independent reading and improves access to educational resources.","vi":"Việc cung cấp cho mỗi học sinh một thẻ thư viện khuyến khích thói quen tự đọc và cải thiện khả năng tiếp cận các nguồn tài nguyên giáo dục.","audioKind":"ex2"}],"collocations":[{"en":"a credit card","vi":"thẻ tín dụng"},{"en":"an identity card","vi":"thẻ căn cước"},{"en":"a birthday card","vi":"thiệp sinh nhật"},{"en":"play cards","vi":"chơi bài"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"play cards là chơi bài, dùng danh từ cards ở số nhiều và không có mạo từ đi trước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_start', 'en-a1-18', 'start', '/stɑːrt/', 'A1', 'bắt đầu; khởi đầu; khởi động; nổ máy; sự bắt đầu; điểm xuất phát; khởi đầu', 'v.', 'starter (n.), restart (v.)', 'Đồng nghĩa: begin, commence · Trái nghĩa: finish, stop', 'Cả start doing và start to do đều có thể dùng để diễn đạt việc bắt đầu làm một điều gì đó.', 'We started cooking dinner as soon as we got home.', NULL, 'Chúng tôi bắt đầu nấu bữa tối ngay khi vừa về đến nhà.', '{"wordId":"start","ukIpa":"/stɑːt/","usIpa":"/stɑːrt/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To begin doing something or cause something to begin.","vi":"bắt đầu; khởi đầu"},{"pos":"v.","en":"To make a machine operate, or begin operating.","vi":"khởi động; nổ máy"},{"pos":"n.","en":"The moment or place where something begins.","vi":"sự bắt đầu; điểm xuất phát; khởi đầu"}],"examples":[{"en":"We started cooking dinner as soon as we got home.","vi":"Chúng tôi bắt đầu nấu bữa tối ngay khi vừa về đến nhà.","audioKind":"ex"},{"en":"Schools should start teaching financial skills early so that young people can make informed decisions about money.","vi":"Các trường học nên bắt đầu dạy kỹ năng tài chính từ sớm để người trẻ có thể đưa ra những quyết định sáng suốt về tiền bạc.","audioKind":"ex2"}],"collocations":[{"en":"start a business","vi":"khởi nghiệp; bắt đầu kinh doanh"},{"en":"start the engine","vi":"nổ máy; khởi động động cơ"},{"en":"at the start of","vi":"vào lúc bắt đầu..."},{"en":"make a fresh start","vi":"bắt đầu lại từ đầu"}],"wordFamily":["starter (n.)","restart (v.)"],"synonyms":["begin","commence"],"antonyms":["finish","stop"],"tipVi":"Cả start doing và start to do đều có thể dùng để diễn đạt việc bắt đầu làm một điều gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_life', 'en-a1-18', 'life', '/laɪf/', 'A1', 'cuộc sống; đời sống; sự sống; tính mạng; tuổi thọ; thời hạn sử dụng', 'n.', 'lifelong (adj.), lifeless (adj.), lively (adj.)', 'Trái nghĩa: death', 'Dạng số nhiều là lives; khi chỉ cuộc sống nói chung thì thường là danh từ không đếm được.', 'Life feels quieter since we moved to the countryside.', NULL, 'Cuộc sống có cảm giác yên bình hơn kể từ khi chúng tôi chuyển về vùng nông thôn.', '{"wordId":"life","ukIpa":"/laɪf/","usIpa":"/laɪf/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"the experiences and activities of being alive","vi":"cuộc sống; đời sống"},{"pos":"n.","en":"the state of being alive","vi":"sự sống; tính mạng"},{"pos":"n.","en":"the period during which someone lives or something works","vi":"tuổi thọ; thời hạn sử dụng"}],"examples":[{"en":"Life feels quieter since we moved to the countryside.","vi":"Cuộc sống có cảm giác yên bình hơn kể từ khi chúng tôi chuyển về vùng nông thôn.","audioKind":"ex"},{"en":"Access to affordable housing can significantly improve the quality of life in large cities.","vi":"Khả năng tiếp cận nhà ở giá phải chăng có thể cải thiện đáng kể chất lượng cuộc sống tại các thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"quality of life","vi":"chất lượng cuộc sống"},{"en":"daily life","vi":"cuộc sống thường nhật"},{"en":"save a life","vi":"cứu một mạng người"},{"en":"battery life","vi":"thời lượng pin"}],"wordFamily":["lifelong (adj.)","lifeless (adj.)","lively (adj.)"],"synonyms":[],"antonyms":["death"],"tipVi":"Dạng số nhiều là lives; khi chỉ cuộc sống nói chung thì thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_finish', 'en-a1-18', 'finish', '/ˈfɪnɪʃ/', 'A1', 'hoàn thành; kết thúc; làm xong; phần kết; chặng cuối; vạch đích; lớp hoàn thiện bề mặt; độ bóng mịn', 'v.', 'finished (adj.), unfinished (adj.), finishing (n.)', 'Đồng nghĩa: complete, end · Trái nghĩa: start, begin', 'Diễn đạt việc làm xong việc gì đó dùng finish doing, không dùng finish to do.', 'I''ll finish washing the dishes before we go.', NULL, 'Tôi sẽ rửa bát xong trước khi chúng ta đi.', '{"wordId":"finish","ukIpa":"/ˈfɪnɪʃ/","usIpa":"/ˈfɪnɪʃ/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to complete something or reach its end","vi":"hoàn thành; kết thúc; làm xong"},{"pos":"n.","en":"the final part or end of something","vi":"phần kết; chặng cuối; vạch đích"},{"pos":"n.","en":"the appearance or texture of a completed surface","vi":"lớp hoàn thiện bề mặt; độ bóng mịn"}],"examples":[{"en":"I''ll finish washing the dishes before we go.","vi":"Tôi sẽ rửa bát xong trước khi chúng ta đi.","audioKind":"ex"},{"en":"Students who finish their assignments early have more time to review feedback and improve their understanding.","vi":"Những học sinh hoàn thành bài tập sớm sẽ có nhiều thời gian hơn để xem lại nhận xét và hiểu sâu bài học hơn.","audioKind":"ex2"}],"collocations":[{"en":"finish doing something","vi":"làm xong việc gì"},{"en":"finish an assignment","vi":"hoàn thành bài tập"},{"en":"finish line","vi":"vạch đích"},{"en":"a smooth finish","vi":"bề mặt nhẵn bóng"}],"wordFamily":["finished (adj.)","unfinished (adj.)","finishing (n.)"],"synonyms":["complete","end"],"antonyms":["start","begin"],"tipVi":"Diễn đạt việc làm xong việc gì đó dùng finish doing, không dùng finish to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_our', 'en-a1-18', 'our', '/aʊr/', 'A1', 'của chúng tôi; của chúng ta', 'det.', 'we (pron.), us (pron.), ours (pron.), ourselves (pron.)', NULL, 'Sau our bắt buộc phải có danh từ; đại từ sở hữu ours được dùng độc lập không cần danh từ theo sau.', 'Our kitchen smells wonderful when Dad bakes fresh bread.', NULL, 'Căn bếp của chúng tôi ngập tràn mùi thơm ngào ngạt khi bố nướng bánh mì mới.', '{"wordId":"our","ukIpa":"/aʊə/","usIpa":"/aʊr/","cefr":"A1","topic":"daily","senses":[{"pos":"det.","en":"Belonging to or connected with the speaker and other people.","vi":"của chúng tôi; của chúng ta"}],"examples":[{"en":"Our kitchen smells wonderful when Dad bakes fresh bread.","vi":"Căn bếp của chúng tôi ngập tràn mùi thơm ngào ngạt khi bố nướng bánh mì mới.","audioKind":"ex"},{"en":"Investing in public transport could improve our quality of life and reduce urban air pollution.","vi":"Đầu tư vào giao thông công cộng có thể nâng cao chất lượng cuộc sống của chúng ta và giảm thiểu ô nhiễm không khí đô thị.","audioKind":"ex2"}],"collocations":[{"en":"our daily lives","vi":"cuộc sống hàng ngày của chúng ta"},{"en":"our local community","vi":"cộng đồng địa phương của chúng ta"},{"en":"our shared future","vi":"tương lai chung của chúng ta"}],"wordFamily":["we (pron.)","us (pron.)","ours (pron.)","ourselves (pron.)"],"synonyms":[],"antonyms":[],"tipVi":"Sau our bắt buộc phải có danh từ; đại từ sở hữu ours được dùng độc lập không cần danh từ theo sau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tomorrow', 'en-a1-18', 'tomorrow', '/təˈmɑːroʊ/', 'A1', 'ngày mai; ngày mai; tương lai', 'adv.', NULL, 'Trái nghĩa: yesterday', 'Trước tomorrow thường không dùng giới từ on; cụm sáng mai là tomorrow morning.', 'We are meeting at the swimming pool tomorrow morning.', NULL, 'Chúng ta sẽ gặp nhau ở hồ bơi vào sáng mai.', '{"wordId":"tomorrow","ukIpa":"/təˈmɒrəʊ/","usIpa":"/təˈmɑːroʊ/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"On the day after today.","vi":"ngày mai"},{"pos":"n.","en":"The day after today, or the future more generally.","vi":"ngày mai; tương lai"}],"examples":[{"en":"We are meeting at the swimming pool tomorrow morning.","vi":"Chúng ta sẽ gặp nhau ở hồ bơi vào sáng mai.","audioKind":"ex"},{"en":"The environmental decisions made today will shape the world that the children of tomorrow inherit.","vi":"Những quyết định về môi trường được đưa ra hôm nay sẽ định hình thế giới mà thế hệ tương lai thừa hưởng.","audioKind":"ex2"}],"collocations":[{"en":"tomorrow morning","vi":"sáng ngày mai"},{"en":"by tomorrow","vi":"trước ngày mai"},{"en":"the day after tomorrow","vi":"ngày kia"},{"en":"tomorrow''s world","vi":"thế giới tương lai"}],"wordFamily":[],"synonyms":[],"antonyms":["yesterday"],"tipVi":"Trước tomorrow thường không dùng giới từ on; cụm sáng mai là tomorrow morning.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fourth', 'en-a1-18', 'fourth', '/fɔːrθ/', 'A1', 'thứ tư; một phần tư', 'num.', 'four (num.), fourthly (adv.)', NULL, 'Số thứ tự là fourth; từ forth có nghĩa là về phía trước, cần chú ý phân biệt chính tả.', 'Our apartment is on the fourth floor, beside the lift.', NULL, 'Căn hộ của chúng tôi ở tầng bốn, ngay cạnh thang máy.', '{"wordId":"fourth","ukIpa":"/fɔːθ/","usIpa":"/fɔːrθ/","cefr":"A1","topic":"daily","senses":[{"pos":"num.","en":"coming immediately after the third in a sequence","vi":"thứ tư"},{"pos":"n.","en":"one of four equal parts of a whole","vi":"một phần tư"}],"examples":[{"en":"Our apartment is on the fourth floor, beside the lift.","vi":"Căn hộ của chúng tôi ở tầng bốn, ngay cạnh thang máy.","audioKind":"ex"},{"en":"The fourth stage of the recycling process involves transforming cleaned plastic into material suitable for new products.","vi":"Giai đoạn thứ tư của quy trình tái chế bao gồm việc chuyển đổi nhựa đã làm sạch thành nguyên liệu phù hợp cho các sản phẩm mới.","audioKind":"ex2"}],"collocations":[{"en":"the fourth floor","vi":"tầng bốn"},{"en":"fourth place","vi":"vị trí thứ tư; hạng tư"},{"en":"a fourth of","vi":"một phần tư của"}],"wordFamily":["four (num.)","fourthly (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Số thứ tự là fourth; từ forth có nghĩa là về phía trước, cần chú ý phân biệt chính tả.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_today', 'en-a1-18', 'today', '/təˈdeɪ/', 'A1', 'hôm nay; hiện nay; ngày nay; thời hiện tại', 'adv.', NULL, 'Đồng nghĩa: nowadays', 'Từ today có thể chỉ ngày hôm nay hoặc thời đại ngày nay; phía trước không dùng giới từ on.', 'Let''s eat outside today while the weather is warm.', NULL, 'Hôm nay trời ấm áp, chúng ta hãy ăn ở ngoài trời nhé.', '{"wordId":"today","ukIpa":"/təˈdeɪ/","usIpa":"/təˈdeɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"on this day, or during the present period","vi":"hôm nay; hiện nay"},{"pos":"n.","en":"the current day or the present period","vi":"ngày nay; thời hiện tại"}],"examples":[{"en":"Let''s eat outside today while the weather is warm.","vi":"Hôm nay trời ấm áp, chúng ta hãy ăn ở ngoài trời nhé.","audioKind":"ex"},{"en":"Today, many universities offer flexible courses that allow students to combine employment with further education.","vi":"Ngày nay, nhiều trường đại học cung cấp các khóa học linh hoạt cho phép sinh viên vừa đi làm vừa tiếp tục học lên cao.","audioKind":"ex2"}],"collocations":[{"en":"earlier today","vi":"hôm nay (lúc trước trong ngày)"},{"en":"today''s society","vi":"xã hội ngày nay"},{"en":"from today","vi":"từ hôm nay"}],"wordFamily":[],"synonyms":["nowadays"],"antonyms":[],"tipVi":"Từ today có thể chỉ ngày hôm nay hoặc thời đại ngày nay; phía trước không dùng giới từ on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_supermarket', 'en-a1-18', 'supermarket', '/ˈsuːpɚmɑːrkɪt/', 'A1', 'siêu thị', 'n.', NULL, NULL, 'Khi mua sắm ở siêu thị, người ta thường dùng cụm từ shop at a supermarket.', 'We stopped at the supermarket to buy milk and rice.', NULL, 'Chúng tôi đã ghé qua siêu thị để mua sữa và gạo.', '{"wordId":"supermarket","ukIpa":"/ˈsuːpəmɑːkɪt/","usIpa":"/ˈsuːpɚmɑːrkɪt/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a large shop selling food and other everyday goods","vi":"siêu thị"}],"examples":[{"en":"We stopped at the supermarket to buy milk and rice.","vi":"Chúng tôi đã ghé qua siêu thị để mua sữa và gạo.","audioKind":"ex"},{"en":"Large supermarkets can offer lower prices, but their expansion may threaten independent shops in smaller communities.","vi":"Các siêu thị lớn có thể đưa ra mức giá rẻ hơn, nhưng sự bành trướng của họ có thể đe dọa các cửa hàng nhỏ lẻ độc lập trong các cộng đồng dân cư nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"supermarket chain","vi":"chuỗi siêu thị"},{"en":"supermarket checkout","vi":"quầy thanh toán siêu thị"},{"en":"supermarket shelves","vi":"kệ hàng siêu thị"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi mua sắm ở siêu thị, người ta thường dùng cụm từ shop at a supermarket.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kitchen', 'en-a1-18', 'kitchen', '/ˈkɪtʃən/', 'A1', 'phòng bếp; nhà bếp', 'n.', 'kitchenette (n.)', NULL, 'Cụm in the kitchen có nghĩa là ở trong phòng bếp; âm ch được phát âm là /tʃ/.', 'The kitchen smells of fresh bread and roasted vegetables.', NULL, 'Căn bếp thoang thoảng mùi bánh mì mới nướng và rau củ quay.', '{"wordId":"kitchen","ukIpa":"/ˈkɪtʃɪn/","usIpa":"/ˈkɪtʃən/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A room where food is prepared and cooked","vi":"phòng bếp; nhà bếp"}],"examples":[{"en":"The kitchen smells of fresh bread and roasted vegetables.","vi":"Căn bếp thoang thoảng mùi bánh mì mới nướng và rau củ quay.","audioKind":"ex"},{"en":"Shared kitchen facilities can encourage social interaction among students living in university accommodation away from home.","vi":"Khu vực bếp chung có thể thúc đẩy sự giao lưu tương tác giữa các sinh viên sống xa nhà trong khu ký túc xá đại học.","audioKind":"ex2"}],"collocations":[{"en":"kitchen appliances","vi":"thiết bị nhà bếp"},{"en":"kitchen sink","vi":"bồn rửa chén trong bếp"},{"en":"shared kitchen","vi":"phòng bếp chung"},{"en":"kitchen utensils","vi":"dụng cụ nhà bếp"}],"wordFamily":["kitchenette (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm in the kitchen có nghĩa là ở trong phòng bếp; âm ch được phát âm là /tʃ/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_when', 'en-a1-18', 'when', '/wen/', 'A1', 'khi nào; lúc nào; khi mà; lúc; ngay khi; xét thấy rằng; khi mà', 'adv.', 'whenever (conj.)', NULL, 'Trong mệnh đề chỉ thời gian mang nghĩa tương lai, sau when thường dùng thì hiện tại đơn.', 'When does the next bus leave for town?', NULL, 'Chuyến xe buýt tiếp theo đi thị trấn khởi hành lúc mấy giờ?', '{"wordId":"when","ukIpa":"/wen/","usIpa":"/wen/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"At what time.","vi":"khi nào; lúc nào"},{"pos":"conj.","en":"At the time that something happens.","vi":"khi mà; lúc; ngay khi"},{"pos":"conj.","en":"Considering that something is true.","vi":"xét thấy rằng; khi mà"}],"examples":[{"en":"When does the next bus leave for town?","vi":"Chuyến xe buýt tiếp theo đi thị trấn khởi hành lúc mấy giờ?","audioKind":"ex"},{"en":"When cities invest in reliable public transport, residents are more likely to leave their cars at home.","vi":"Khi các thành phố đầu tư vào hệ thống giao thông công cộng đáng tin cậy, cư dân sẽ có nhiều khả năng để xe ở nhà hơn.","audioKind":"ex2"}],"collocations":[{"en":"when necessary","vi":"khi cần thiết"},{"en":"when possible","vi":"khi có thể"},{"en":"since when","vi":"từ khi nào"}],"wordFamily":["whenever (conj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong mệnh đề chỉ thời gian mang nghĩa tương lai, sau when thường dùng thì hiện tại đơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pen', 'en-a1-18', 'pen', '/pen/', 'A1', 'bút; bút mực; chuồng gia súc; rào nuôi động vật; viết; soạn thảo', 'n.', NULL, NULL, '"pen" chỉ chung bút mực; bút máy có thể nói rõ là "fountain pen".', 'Could you lend me a pen for this form?', NULL, 'Bạn có thể cho tôi mượn một cây bút để điền vào tờ mẫu này không?', '{"wordId":"pen","ukIpa":"/pen/","usIpa":"/pen/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A tool that uses ink to write or draw.","vi":"bút; bút mực"},{"pos":"n.","en":"A small enclosed area where animals are kept.","vi":"chuồng gia súc; rào nuôi động vật"},{"pos":"v.","en":"To write a letter, story or other piece of writing.","vi":"viết; soạn thảo"}],"examples":[{"en":"Could you lend me a pen for this form?","vi":"Bạn có thể cho tôi mượn một cây bút để điền vào tờ mẫu này không?","audioKind":"ex"},{"en":"Some students prefer using a pen because writing by hand helps them organise their ideas.","vi":"Một số học sinh thích dùng bút hơn vì việc viết tay giúp các em sắp xếp ý tưởng của mình.","audioKind":"ex2"}],"collocations":[{"en":"ballpoint pen","vi":"bút bi"},{"en":"fountain pen","vi":"bút máy"},{"en":"a sheep pen","vi":"chuồng cừu"},{"en":"pen a letter","vi":"viết một bức thư"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"\"pen\" chỉ chung bút mực; bút máy có thể nói rõ là \"fountain pen\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 28, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_18_1', 'en-a1-18', 'Cách dùng “watch” (v.) — xem; quan sát; theo dõi', 'watch television  ·  watch closely  ·  wear a watch', 'watch nhấn mạnh việc quan sát có chú ý trong một khoảng thời gian; see nhấn mạnh kết quả nhìn thấy.', 'Họ từ (Word Family): watcher (n.), watchful (adj.), watchfulness (n.) | Đồng nghĩa: observe', '[{"hanzi":"We watched the ducks swimming across the quiet pond.","pinyin":"","meaning":"Chúng tôi ngắm nhìn những chú vịt bơi lội qua ao nước yên bình."},{"hanzi":"Students who watch educational programmes may gain useful knowledge, but active discussion helps deepen their understanding.","pinyin":"","meaning":"Những học sinh xem các chương trình giáo dục có thể thu, nhưng thảo luận tích cực giúp đào sâu hiểu biết của các em."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_18_2', 'en-a1-18', 'Cách dùng “our” (det.) — của chúng tôi; của chúng ta', 'our daily lives  ·  our local community  ·  our shared future', 'Sau our bắt buộc phải có danh từ; đại từ sở hữu ours được dùng độc lập không cần danh từ theo sau.', 'Họ từ (Word Family): we (pron.), us (pron.), ours (pron.), ourselves (pron.)', '[{"hanzi":"Our kitchen smells wonderful when Dad bakes fresh bread.","pinyin":"","meaning":"Căn bếp của chúng tôi ngập tràn mùi thơm ngào ngạt khi bố nướng bánh mì mới."},{"hanzi":"Investing in public transport could improve our quality of life and reduce urban air pollution.","pinyin":"","meaning":"Đầu tư vào giao thông công cộng có thể nâng cao chất lượng cuộc sống của chúng ta và giảm thiểu ô nhiễm không khí đô thị."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_18_3', 'en-a1-18', 'Cách dùng “sometimes” (adv.) — thỉnh thoảng; đôi khi', 'sometimes feel  ·  sometimes happen  ·  only sometimes', 'sometimes là trạng từ chỉ tần suất (đôi khi); some time là danh từ chỉ một khoảng thời gian.', 'Đồng nghĩa: occasionally, at times | Trái nghĩa: always, never', '[{"hanzi":"I sometimes take the longer route home through the park.","pinyin":"","meaning":"Tôi thỉnh thoảng đi con đường dài hơn về nhà qua công viên."},{"hanzi":"Working from home sometimes improves productivity, although its benefits depend on suitable equipment and a quiet environment.","pinyin":"","meaning":"Làm việc tại nhà đôi khi cải thiện năng suất, mặc dù lợi ích của nó phụ thuộc vào thiết bị phù hợp và môi trường yên tĩnh."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_18_4', 'en-a1-18', 'Cách dùng “door” (n.) — cửa; cửa ra vào', 'front door  ·  answer the door  ·  knock on the door', 'at the door chỉ ở ngay ngoài cửa; answer the door chỉ hành động ra mở cửa khi có người gọi.', 'Họ từ (Word Family): doorway (n.), doorknob (n.), doorbell (n.)', '[{"hanzi":"Please close the door before the cat gets out.","pinyin":"","meaning":"Xin hãy đóng cửa lại trước khi con mèo chạy ra ngoài."},{"hanzi":"Installing wider doors in public buildings can make everyday journeys easier for people who use wheelchairs.","pinyin":"","meaning":"Việc lắp đặt các ô cửa rộng hơn trong các công việc công cộng có thể giúp việc di chuyển hàng ngày trở nên dễ dàng hơn đối với những người ngồi xe lăn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_18_1', 'en-a1-18', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_18_1_1', 'ten_18_1', 'yourself', 'Be careful not to cut yourself with that knife.', 'Be careful not to cut yourself with that knife.', '/jʊrˈself/', 'Hãy cẩn thận kẻo tự cắt vào tay mình bằng con dao đó.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_18_1_2', 'ten_18_1', 'last', 'I caught the last bus home just before midnight.', 'I caught the last bus home just before midnight.', '/læst/', 'Tôi vừa kịp bắt chuyến xe buýt cuối cùng về nhà ngay trước nửa đêm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_18_1_3', 'ten_18_1', 'listen', 'I listen to music while cooking dinner every evening.', 'I listen to music while cooking dinner every evening.', '/ˈlɪsən/', 'Tôi thường nghe nhạc trong lúc nấu bữa tối vào mỗi buổi tối.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_18_1_4', 'ten_18_1', 'toothpaste', 'I squeezed some toothpaste onto my brush before breakfast.', 'I squeezed some toothpaste onto my brush before breakfast.', '/ˈtuːθpeɪst/', 'Tôi nặn một ít kem đánh răng lên bàn chải trước bữa sáng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_18_1_5', 'ten_18_1', 'banana', 'He peeled a banana and sliced it over his cereal.', 'He peeled a banana and sliced it over his cereal.', '/bəˈnænə/', 'Anh ấy bóc vỏ một quả chuối và cắt lát lên bát ngũ cốc của mình.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_18_1_6', 'ten_18_1', 'menu', 'There are several vegetarian dishes on the menu.', 'There are several vegetarian dishes on the menu.', '/ˈmenjuː/', 'Có một số món chay trong thực đơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
