INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_18_1_1', 'en-a1-18', 'ten_18_1', 'listening', 'listening', 'Be careful not to cut yourself with that knife.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi vừa kịp bắt chuyến xe buýt cuối cùng về nhà ngay trước nửa đêm.","Bọn trẻ chào người hàng xóm mới của chúng là ông Green.","Tôi thường nghe nhạc trong lúc nấu bữa tối vào mỗi buổi tối.","Hãy cẩn thận kẻo tự cắt vào tay mình bằng con dao đó."]'::jsonb, 3, 'Be careful not to cut yourself with that knife. → Hãy cẩn thận kẻo tự cắt vào tay mình bằng con dao đó.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_18_1_2', 'en-a1-18', 'ten_18_1', 'listening', 'listening', 'I caught the last bus home just before midnight.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi vừa kịp bắt chuyến xe buýt cuối cùng về nhà ngay trước nửa đêm.","Tôi thường nghe nhạc trong lúc nấu bữa tối vào mỗi buổi tối.","Bọn trẻ chào người hàng xóm mới của chúng là ông Green.","Anh ấy bóc vỏ một quả chuối và cắt lát lên bát ngũ cốc của mình."]'::jsonb, 0, 'I caught the last bus home just before midnight. → Tôi vừa kịp bắt chuyến xe buýt cuối cùng về nhà ngay trước nửa đêm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_18_1_3', 'en-a1-18', 'ten_18_1', 'listening', 'listening', 'I listen to music while cooking dinner every evening.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Anh ấy bóc vỏ một quả chuối và cắt lát lên bát ngũ cốc của mình.","Tôi thường nghe nhạc trong lúc nấu bữa tối vào mỗi buổi tối.","Tôi nặn một ít kem đánh răng lên bàn chải trước bữa sáng.","Tôi vừa kịp bắt chuyến xe buýt cuối cùng về nhà ngay trước nửa đêm."]'::jsonb, 1, 'I listen to music while cooking dinner every evening. → Tôi thường nghe nhạc trong lúc nấu bữa tối vào mỗi buổi tối.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
