INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_18_2_1', 'ten_18_2', 'yourself', 'Preparing meals yourself can reduce household spending while giving you greater control over nutritional quality.', 'Preparing meals yourself can reduce household spending while giving you greater control over nutritional quality.', '/jʊrˈself/', 'Tự nấu ăn có thể giúp giảm chi phí sinh hoạt đồng thời giúp bạn kiểm soát tốt hơn chất lượng dinh dưỡng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_18_2_2', 'ten_18_2', 'last', 'Products that last longer can reduce household spending and limit the amount of waste sent to landfill.', 'Products that last longer can reduce household spending and limit the amount of waste sent to landfill.', '/læst/', 'Những sản phẩm có độ bền cao hơn có thể giúp giảm chi phí sinh hoạt cho gia đình và hạn chế lượng rác thải đưa ra các bãi chôn lấp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_18_2_3', 'ten_18_2', 'listen', 'Local authorities should listen to residents before making decisions that significantly affect their neighbourhoods.', 'Local authorities should listen to residents before making decisions that significantly affect their neighbourhoods.', '/ˈlɪsən/', 'Chính quyền địa phương nên lắng nghe ý kiến người dân trước khi đưa ra các quyết định ảnh hưởng lớn đến khu dân cư của họ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_18_2_4', 'ten_18_2', 'toothpaste', 'Regular brushing with fluoride toothpaste helps prevent tooth decay and can reduce the need for costly dental treatment.', 'Regular brushing with fluoride toothpaste helps prevent tooth decay and can reduce the need for costly dental treatment.', '/ˈtuːθpeɪst/', 'Đánh răng thường xuyên bằng kem đánh răng chứa florua giúp ngăn ngừa sâu răng và giảm nhu cầu điều trị nha khoa tốn kém.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_18_2_5', 'ten_18_2', 'banana', 'Banana farming provides an important source of income for many families in tropical regions.', 'Banana farming provides an important source of income for many families in tropical regions.', '/bəˈnænə/', 'Trồng chuối mang lại nguồn thu nhập quan trọng cho nhiều gia đình ở các vùng nhiệt đới.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_18_2_6', 'ten_18_2', 'menu', 'Displaying nutritional information on a restaurant menu may help customers make healthier choices when eating out.', 'Displaying nutritional information on a restaurant menu may help customers make healthier choices when eating out.', '/ˈmenjuː/', 'Việc hiển thị thông tin dinh dưỡng trên thực đơn nhà hàng có thể giúp khách hàng đưa ra lựa chọn lành mạnh hơn khi đi ăn ngoài.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
