INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_18_2_2', 'en-a1-18', 'ten_18_2', 'listening', 'listening', 'Products that last longer can reduce household spending and limit the amount of waste sent to landfill.', NULL, 'Trong câu vừa nghe, từ “last” mang nghĩa nào sau đây?', '["kỳ thi; bài kiểm tra","cuối cùng; gần đây nhất","đến nơi; tới","vòi hoa sen; việc tắm dưới vòi hoa sen"]'::jsonb, 1, '“last” (/læst/): cuối cùng; gần đây nhất. Câu đầy đủ: Products that last longer can reduce household spending and limit the amount of waste sent to landfill.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
