INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_18_2', 'en-a1-18', NULL, 'comprehensive_test', 'listening', 'I caught the last bus home just before midnight.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hồ bơi địa phương của chúng tôi sẽ mở cửa trở lại vào tháng mười.","Hãy cẩn thận kẻo tự cắt vào tay mình bằng con dao đó.","Anh ấy bóc vỏ một quả chuối và cắt lát lên bát ngũ cốc của mình.","Tôi vừa kịp bắt chuyến xe buýt cuối cùng về nhà ngay trước nửa đêm."]'::jsonb, 3, 'I caught the last bus home just before midnight. → Tôi vừa kịp bắt chuyến xe buýt cuối cùng về nhà ngay trước nửa đêm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_18_3', 'en-a1-18', NULL, 'comprehensive_test', 'listening', 'listen', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["giống hệt; cùng một (sự vật, sự việc)","tốt; khỏe mạnh; hay; chất lượng cao","hứng khởi; hào hứng; phấn khích","lắng nghe; chú ý lắng nghe"]'::jsonb, 3, 'listen (/ˈlɪsən/) → lắng nghe; chú ý lắng nghe; lắng nghe; tiếp thu lời khuyên', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_18_4', 'en-a1-18', NULL, 'comprehensive_test', 'listening', 'I squeezed some toothpaste onto my brush before breakfast.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hồ bơi địa phương của chúng tôi sẽ mở cửa trở lại vào tháng mười.","Căn hộ của chúng tôi ở tầng bốn, ngay cạnh thang máy.","Chuyến xe buýt tiếp theo đi thị trấn khởi hành lúc mấy giờ?","Tôi nặn một ít kem đánh răng lên bàn chải trước bữa sáng."]'::jsonb, 3, 'I squeezed some toothpaste onto my brush before breakfast. → Tôi nặn một ít kem đánh răng lên bàn chải trước bữa sáng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_18_5', 'en-a1-18', NULL, 'comprehensive_test', 'listening', 'banana', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bình; chai; dung tích một chai","quả chuối","tàu hỏa; tàu điện","sẵn sàng; đã chuẩn bị xong"]'::jsonb, 1, 'banana (/bəˈnænə/) → quả chuối', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_18_6', 'en-a1-18', NULL, 'comprehensive_test', 'listening', 'There are several vegetarian dishes on the menu.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Dì của tôi đã dạy tôi cách nướng bánh mì.","Bây giờ tôi thấy khỏe rồi, chúng ta đi dạo nhé.","Chúng tôi ngắm nhìn những chú vịt bơi lội qua ao nước yên bình.","Có một số món chay trong thực đơn."]'::jsonb, 3, 'There are several vegetarian dishes on the menu. → Có một số món chay trong thực đơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
