INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_18_8', 'en-a1-18', NULL, 'comprehensive_test', 'listening', 'The children greeted their new neighbour as Mister Green.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bọn trẻ chào người hàng xóm mới của chúng là ông Green.","Tôi vừa kịp bắt chuyến xe buýt cuối cùng về nhà ngay trước nửa đêm.","Chuyến xe buýt tiếp theo đi thị trấn khởi hành lúc mấy giờ?","Dì của tôi đã dạy tôi cách nướng bánh mì."]'::jsonb, 0, 'The children greeted their new neighbour as Mister Green. → Bọn trẻ chào người hàng xóm mới của chúng là ông Green.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
