INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_18_18', 'en-a1-18', NULL, 'comprehensive_test', 'reading', NULL, 'Preparing meals yourself can reduce household spending while giving you greater control over nutritional quality.', 'Dựa vào câu trên, từ “yourself” có nghĩa phù hợp nhất là gì?', '["phòng bếp; nhà bếp","chính bạn; bản thân bạn","gọi điện thoại cho ai đó hoặc hét lên để thu hút sự chú ý","có mưa; mưa nhiều; nhiều mưa"]'::jsonb, 1, 'yourself: chính bạn; bản thân bạn; chính ngài; chính bạn (dùng để nhấn mạnh). Dịch cả câu: Tự nấu ăn có thể giúp giảm chi phí sinh hoạt đồng thời giúp bạn kiểm soát tốt hơn chất lượng dinh dưỡng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_18_19', 'en-a1-18', NULL, 'comprehensive_test', 'reading', NULL, 'Products that last longer can reduce household spending and limit the amount of waste sent to landfill.', 'Dựa vào câu trên, từ “last” có nghĩa phù hợp nhất là gì?', '["ở phía trên; cao hơn","diễn viên","cuối cùng; gần đây nhất","dạy; giảng dạy; chỉ bảo"]'::jsonb, 2, 'last: cuối cùng; gần đây nhất; kéo dài; đủ dùng; sau cùng; lần gần đây nhất. Dịch cả câu: Những sản phẩm có độ bền cao hơn có thể giúp giảm chi phí sinh hoạt cho gia đình và hạn chế lượng rác thải đưa ra các bãi chôn lấp.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_18_20', 'en-a1-18', NULL, 'comprehensive_test', 'reading', NULL, 'Local authorities should listen to residents before making decisions that significantly affect their neighbourhoods.', 'Dựa vào câu trên, từ “listen” có nghĩa phù hợp nhất là gì?', '["đồ chơi","con mèo","một trăm","lắng nghe; chú ý lắng nghe"]'::jsonb, 3, 'listen: lắng nghe; chú ý lắng nghe; lắng nghe; tiếp thu lời khuyên. Dịch cả câu: Chính quyền địa phương nên lắng nghe ý kiến người dân trước khi đưa ra các quyết định ảnh hưởng lớn đến khu dân cư của họ.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_18_21', 'en-a1-18', NULL, 'comprehensive_test', 'reading', NULL, 'Regular brushing with fluoride toothpaste helps prevent tooth decay and can reduce the need for costly dental treatment.', 'Dựa vào câu trên, từ “toothpaste” có nghĩa phù hợp nhất là gì?', '["cảm thấy; thấy","cái đĩa","kem đánh răng","muối; muối ăn"]'::jsonb, 2, 'toothpaste: kem đánh răng. Dịch cả câu: Đánh răng thường xuyên bằng kem đánh răng chứa florua giúp ngăn ngừa sâu răng và giảm nhu cầu điều trị nha khoa tốn kém.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_18_22', 'en-a1-18', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phòng bếp; nhà bếp”', '["apple","beard","kitchen","cheese"]'::jsonb, 2, 'phòng bếp; nhà bếp → kitchen (/ˈkɪtʃən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_18_23', 'en-a1-18', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khi nào; lúc nào”', '["when","apple","hand","look"]'::jsonb, 0, 'khi nào; lúc nào → when (/wen/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_18_24', 'en-a1-18', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bút; bút mực”', '["high","it","pen","add"]'::jsonb, 2, 'bút; bút mực → pen (/pen/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-19', 'en', 'Bài 19: Đời sống hằng ngày (4) - CEFR A1', 'CEFR A1', 'A1 · Đời sống', '28 từ vựng Tiếng Anh CEFR A1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1019, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_leave', 'en-a1-19', 'leave', '/liːv/', 'A1', 'rời đi; xuất phát; để lại; bỏ quên; nghỉ phép; kỳ nghỉ', 'v.', 'leaver (n.)', 'Đồng nghĩa: depart · Trái nghĩa: arrive', 'Dạng quá khứ và quá khứ phân từ của "leave" đều là "left".', 'We need to leave before the traffic gets worse.', NULL, 'Chúng ta cần phải rời đi trước khi tình trạng giao thông trở nên tồi tệ hơn.', '{"wordId":"leave","ukIpa":"/liːv/","usIpa":"/liːv/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To go away from a person or place.","vi":"rời đi; xuất phát"},{"pos":"v.","en":"To let something remain somewhere, deliberately or accidentally.","vi":"để lại; bỏ quên"},{"pos":"n.","en":"An officially allowed period away from work.","vi":"nghỉ phép; kỳ nghỉ"}],"examples":[{"en":"We need to leave before the traffic gets worse.","vi":"Chúng ta cần phải rời đi trước khi tình trạng giao thông trở nên tồi tệ hơn.","audioKind":"ex"},{"en":"Paid parental leave allows new parents to care for their children without immediately returning to work.","vi":"Chế độ nghỉ phép chăm sóc con có lương giúp các bậc cha mẹ mới sinh có thể chăm sóc con cái mà không phải quay lại làm việc ngay lập tức.","audioKind":"ex2"}],"collocations":[{"en":"leave home","vi":"rời khỏi nhà"},{"en":"leave a message","vi":"để lại lời nhắn; nhắn lại"},{"en":"leave for","vi":"lên đường đi đến"},{"en":"annual leave","vi":"nghỉ phép năm"}],"wordFamily":["leaver (n.)"],"synonyms":["depart"],"antonyms":["arrive"],"tipVi":"Dạng quá khứ và quá khứ phân từ của \"leave\" đều là \"left\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_window', 'en-a1-19', 'window', '/ˈwɪndoʊ/', 'A1', 'cửa sổ; cửa sổ hiển thị (trên màn hình); thời điểm; cơ hội ngắn ngủi', 'n.', 'windowless (adj.)', NULL, 'Cửa sổ máy tính cũng gọi là "window"; "cơ hội hiếm có" nhấn mạnh khoảng thời gian cơ hội có hạn.', 'Please open the window and let some fresh air in.', NULL, 'Xin hãy mở cửa sổ ra và để một chút không khí trong lành tràn vào.', '{"wordId":"window","ukIpa":"/ˈwɪndəʊ/","usIpa":"/ˈwɪndoʊ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"An opening with glass that lets light into a building","vi":"cửa sổ"},{"pos":"n.","en":"An area on a screen displaying a program or document","vi":"cửa sổ hiển thị (trên màn hình)"},{"pos":"n.","en":"A limited period when something can be done","vi":"thời điểm; cơ hội ngắn ngủi"}],"examples":[{"en":"Please open the window and let some fresh air in.","vi":"Xin hãy mở cửa sổ ra và để một chút không khí trong lành tràn vào.","audioKind":"ex"},{"en":"Installing larger windows can reduce the need for artificial lighting in homes during daylight hours.","vi":"Lắp đặt các ô cửa sổ lớn hơn có thể làm giảm nhu cầu sử dụng đèn nhân tạo trong nhà vào ban ngày.","audioKind":"ex2"}],"collocations":[{"en":"open a window","vi":"mở cửa sổ"},{"en":"window frame","vi":"khung cửa sổ"},{"en":"browser window","vi":"cửa sổ trình duyệt"},{"en":"a window of opportunity","vi":"cơ hội hiếm có"}],"wordFamily":["windowless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cửa sổ máy tính cũng gọi là \"window\"; \"cơ hội hiếm có\" nhấn mạnh khoảng thời gian cơ hội có hạn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_leg', 'en-a1-19', 'leg', '/leɡ/', 'A1', 'chân; chân (bàn, ghế hoặc vật dụng tương tự); chặng (của một cuộc hành trình hoặc cuộc đua)', 'n.', 'legged (adj.), legless (adj.)', NULL, '"leg" cũng chỉ chân chống của bàn ghế hoặc một chặng trong hành trình.', 'My legs felt tired after the long walk home.', NULL, 'Chân tôi cảm thấy mỏi nhừ sau quãng đường đi bộ dài về nhà.', '{"wordId":"leg","ukIpa":"/leɡ/","usIpa":"/leɡ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a body part used for standing and walking","vi":"chân"},{"pos":"n.","en":"a support beneath a table, chair, or similar object","vi":"chân (bàn, ghế hoặc vật dụng tương tự)"},{"pos":"n.","en":"one stage of a journey or race","vi":"chặng (của một cuộc hành trình hoặc cuộc đua)"}],"examples":[{"en":"My legs felt tired after the long walk home.","vi":"Chân tôi cảm thấy mỏi nhừ sau quãng đường đi bộ dài về nhà.","audioKind":"ex"},{"en":"Regular walking strengthens the muscles in our legs and can improve health without expensive equipment.","vi":"Việc đi bộ thường xuyên giúp tăng cường cơ chân và có thể cải thiện sức khỏe mà không cần các thiết bị đắt tiền.","audioKind":"ex2"}],"collocations":[{"en":"stretch your legs","vi":"duỗi chân"},{"en":"a table leg","vi":"chân bàn"},{"en":"the final leg of a journey","vi":"chặng cuối của một hành trình"}],"wordFamily":["legged (adj.)","legless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"\"leg\" cũng chỉ chân chống của bàn ghế hoặc một chặng trong hành trình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tomato', 'en-a1-19', 'tomato', '/təˈmeɪtoʊ/', 'A1', 'cà chua', 'n.', NULL, NULL, 'Dạng số nhiều là "tomatoes"; phát âm nguyên âm nhấn trọng lượng trong tiếng Anh-Anh và Anh-Mỹ khác nhau.', 'She sliced a ripe tomato for her cheese sandwich.', NULL, 'Cô ấy cắt một quả cà chua chín để làm bánh mì kẹp phô mai.', '{"wordId":"tomato","ukIpa":"/təˈmɑːtəʊ/","usIpa":"/təˈmeɪtoʊ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a soft, juicy fruit often eaten as a vegetable","vi":"cà chua"}],"examples":[{"en":"She sliced a ripe tomato for her cheese sandwich.","vi":"Cô ấy cắt một quả cà chua chín để làm bánh mì kẹp phô mai.","audioKind":"ex"},{"en":"Growing tomatoes in community gardens can improve access to fresh food in urban neighbourhoods.","vi":"Trồng cà chua trong các khu vườn cộng đồng có thể giúp cư dân đô thị dễ dàng tiếp cận thực phẩm tươi hơn.","audioKind":"ex2"}],"collocations":[{"en":"ripe tomato","vi":"cà chua chín"},{"en":"tomato sauce","vi":"sốt cà chua"},{"en":"cherry tomato","vi":"cà chua bi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là \"tomatoes\"; phát âm nguyên âm nhấn trọng lượng trong tiếng Anh-Anh và Anh-Mỹ khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_try', 'en-a1-19', 'try', '/traɪ/', 'A1', 'cố gắng; thử; thử nghiệm; dùng thử; sự cố gắng; lần thử', 'v.', 'retry (v.)', 'Đồng nghĩa: attempt', '"try to do" nhấn mạnh sự nỗ lực; "try doing" nhấn mạnh việc thử nghiệm một cách làm.', 'I''ll try to fix the lamp before dinner.', NULL, 'Tôi sẽ cố gắng sửa cái đèn này trước bữa tối.', '{"wordId":"try","ukIpa":"/traɪ/","usIpa":"/traɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"make an effort to do something","vi":"cố gắng; thử"},{"pos":"v.","en":"use or do something to see whether it works","vi":"thử nghiệm; dùng thử"},{"pos":"n.","en":"an attempt to do something","vi":"sự cố gắng; lần thử"}],"examples":[{"en":"I''ll try to fix the lamp before dinner.","vi":"Tôi sẽ cố gắng sửa cái đèn này trước bữa tối.","audioKind":"ex"},{"en":"Schools should try different teaching methods to meet the needs of students with varying abilities.","vi":"Các trường học nên thử nghiệm các phương pháp giảng dạy khác nhau để đáp ứng nhu cầu của học sinh có năng lực khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"try to do something","vi":"cố gắng làm gì đó"},{"en":"try doing something","vi":"thử làm gì đó"},{"en":"give it a try","vi":"thử một lần xem sao"},{"en":"try on clothes","vi":"thử quần áo"}],"wordFamily":["retry (v.)"],"synonyms":["attempt"],"antonyms":[],"tipVi":"\"try to do\" nhấn mạnh sự nỗ lực; \"try doing\" nhấn mạnh việc thử nghiệm một cách làm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_restaurant', 'en-a1-19', 'restaurant', '/ˈrestərɑːnt/', 'A1', 'nhà hàng; quán ăn', 'n.', NULL, NULL, 'restaurant chỉ dùng để chỉ nơi ăn uống; hotel chủ yếu dùng để chỉ khách sạn lưu trú.', 'We found a quiet restaurant beside the river.', NULL, 'Chúng tôi tìm thấy một nhà hàng yên tĩnh bên bờ sông.', '{"wordId":"restaurant","ukIpa":"/ˈrestrɒnt/","usIpa":"/ˈrestərɑːnt/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A place where people pay to eat prepared meals.","vi":"nhà hàng; quán ăn"}],"examples":[{"en":"We found a quiet restaurant beside the river.","vi":"Chúng tôi tìm thấy một nhà hàng yên tĩnh bên bờ sông.","audioKind":"ex"},{"en":"Local restaurants can attract tourists by serving traditional dishes made with ingredients from nearby farms.","vi":"Các nhà hàng địa phương có thể thu hút khách du lịch bằng cách phục vụ các món ăn truyền thống làm từ nguyên liệu của các trang trại gần đó.","audioKind":"ex2"}],"collocations":[{"en":"book a table at a restaurant","vi":"đặt bàn tại nhà hàng"},{"en":"run a restaurant","vi":"điều hành một nhà hàng"},{"en":"a seafood restaurant","vi":"một nhà hàng hải sản"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"restaurant chỉ dùng để chỉ nơi ăn uống; hotel chủ yếu dùng để chỉ khách sạn lưu trú.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_father', 'en-a1-19', 'father', '/ˈfɑːðər/', 'A1', 'cha; bố; người sáng lập; bậc khai sáng; làm cha; sinh con', 'n.', 'fatherhood (n.), fatherly (adj.)', 'Đồng nghĩa: dad', 'father mang tính trang trọng hơn, dad mang sắc thái thân mật; ngày của cha là Father''s Day.', 'Her father taught her to ride a bicycle.', NULL, 'Cha cô ấy đã dạy cô ấy tập đi xe đạp.', '{"wordId":"father","ukIpa":"/ˈfɑːðə/","usIpa":"/ˈfɑːðər/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A male parent.","vi":"cha; bố"},{"pos":"n.","en":"A man who established or greatly influenced a field.","vi":"người sáng lập; bậc khai sáng"},{"pos":"v.","en":"To become the biological father of a child.","vi":"làm cha; sinh con"}],"examples":[{"en":"Her father taught her to ride a bicycle.","vi":"Cha cô ấy đã dạy cô ấy tập đi xe đạp.","audioKind":"ex"},{"en":"Flexible working arrangements can allow fathers to take a more active role in raising their children.","vi":"Các thỏa thuận làm việc linh hoạt có thể giúp những người làm cha có vai trò tích cực hơn trong việc nuôi dạy con cái.","audioKind":"ex2"}],"collocations":[{"en":"single father","vi":"cha đơn thân"},{"en":"father figure","vi":"hình mẫu người cha"},{"en":"biological father","vi":"cha đẻ"},{"en":"the father of modern medicine","vi":"cha đẻ của y học hiện đại"}],"wordFamily":["fatherhood (n.)","fatherly (adj.)"],"synonyms":["dad"],"antonyms":[],"tipVi":"father mang tính trang trọng hơn, dad mang sắc thái thân mật; ngày của cha là Father''s Day.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_foot', 'en-a1-19', 'foot', '/fʊt/', 'A1', 'bàn chân; phút (đơn vị chiều dài); chân (phần dưới cùng của vật cao hoặc dốc)', 'n.', 'footwear (n.), footprint (n.), footstep (n.)', NULL, 'Số nhiều của foot là feet; đi bộ dùng on foot.', 'A tiny stone in my shoe hurt my foot.', NULL, 'Một viên sỏi nhỏ trong giày đã làm đau bàn chân tôi.', '{"wordId":"foot","ukIpa":"/fʊt/","usIpa":"/fʊt/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"the body part below the ankle used for standing and walking","vi":"bàn chân"},{"pos":"n.","en":"a unit of length equal to twelve inches","vi":"phút (đơn vị chiều dài)"},{"pos":"n.","en":"the lowest part of something tall or sloping","vi":"chân (phần dưới cùng của vật cao hoặc dốc)"}],"examples":[{"en":"A tiny stone in my shoe hurt my foot.","vi":"Một viên sỏi nhỏ trong giày đã làm đau bàn chân tôi.","audioKind":"ex"},{"en":"Making essential services accessible on foot can encourage physical activity and reduce dependence on private cars.","vi":"Việc làm cho các dịch vụ thiết yếu có thể tiếp cận bằng cách đi bộ có thể thúc đẩy vận động thể chất và giảm sự phụ thuộc vào ô tô cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"on foot","vi":"đi bộ"},{"en":"at the foot of","vi":"ở chân (núi/tòa nhà)"},{"en":"set foot in","vi":"đặt chân vào"},{"en":"foot the bill","vi":"thanh toán hóa đơn"}],"wordFamily":["footwear (n.)","footprint (n.)","footstep (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Số nhiều của foot là feet; đi bộ dùng on foot.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_him', 'en-a1-19', 'him', '/hɪm/', 'A1', 'nó; anh ấy; cậu ấy (dạng tân ngữ)', 'pron.', 'he (pron.), his (det.), himself (pron.)', NULL, 'he làm chủ ngữ, còn him làm tân ngữ của động từ hoặc giới từ.', 'My brother forgot his lunch, so I brought it to him.', NULL, 'Anh trai tôi quên mang bữa trưa, vì vậy tôi đã mang nó đến cho anh ấy.', '{"wordId":"him","ukIpa":"/hɪm/","usIpa":"/hɪm/","cefr":"A1","topic":"daily","senses":[{"pos":"pron.","en":"used for a male person receiving an action or following a preposition","vi":"nó; anh ấy; cậu ấy (dạng tân ngữ)"}],"examples":[{"en":"My brother forgot his lunch, so I brought it to him.","vi":"Anh trai tôi quên mang bữa trưa, vì vậy tôi đã mang nó đến cho anh ấy.","audioKind":"ex"},{"en":"When a student struggles with reading, teachers can support him through regular practice and constructive feedback.","vi":"Khi một học sinh nam gặp khó khăn trong việc đọc, giáo viên có thể hỗ trợ em ấy thông qua việc luyện tập thường xuyên và những phản hồi mang tính xây dựng.","audioKind":"ex2"}],"collocations":[{"en":"help him","vi":"giúp đỡ anh ấy"},{"en":"with him","vi":"ở cùng anh ấy"},{"en":"give him a chance","vi":"cho anh ấy một cơ hội"}],"wordFamily":["he (pron.)","his (det.)","himself (pron.)"],"synonyms":[],"antonyms":[],"tipVi":"he làm chủ ngữ, còn him làm tân ngữ của động từ hoặc giới từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_p-m', 'en-a1-19', 'p.m.', '/ˌpiː ˈem/', 'A1', 'chiều; tối (từ sau buổi trưa đến trước nửa đêm)', 'adv.', NULL, 'Trái nghĩa: a.m.', 'Đặt sau mốc thời gian; 12 p.m. là buổi trưa, còn 12 a.m. là nửa đêm.', 'The swimming pool closes at eight p.m. today.', NULL, 'Hồ bơi đóng cửa lúc tám giờ tối nay.', '{"wordId":"p-m","ukIpa":"/ˌpiː ˈem/","usIpa":"/ˌpiː ˈem/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"after noon and before midnight, used when stating a time","vi":"chiều; tối (từ sau buổi trưa đến trước nửa đêm)"}],"examples":[{"en":"The swimming pool closes at eight p.m. today.","vi":"Hồ bơi đóng cửa lúc tám giờ tối nay.","audioKind":"ex"},{"en":"Keeping public libraries open until nine p.m. would allow more working adults to access educational resources.","vi":"Việc mở cửa các thư viện công cộng cho đến chín giờ tối sẽ cho phép nhiều người lao động trưởng thành hơn tiếp cận được các nguồn tài nguyên giáo dục.","audioKind":"ex2"}],"collocations":[{"en":"at three p.m.","vi":"vào lúc ba giờ chiều"},{"en":"until ten p.m.","vi":"cho đến mười giờ tối"}],"wordFamily":[],"synonyms":[],"antonyms":["a.m."],"tipVi":"Đặt sau mốc thời gian; 12 p.m. là buổi trưa, còn 12 a.m. là nửa đêm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_beginning', 'en-a1-19', 'beginning', '/bɪˈɡɪnɪŋ/', 'A1', 'sự bắt đầu; phần đầu; khởi đầu', 'n.', 'begin (v.), beginner (n.)', 'Đồng nghĩa: start, opening · Trái nghĩa: end', 'at the beginning of đi với danh từ; in the beginning mang nghĩa là lúc đầu.', 'We missed the beginning of the film yesterday.', NULL, 'Chúng tôi đã bỏ lỡ phần đầu của bộ phim ngày hôm qua.', '{"wordId":"beginning","ukIpa":"/bɪˈɡɪnɪŋ/","usIpa":"/bɪˈɡɪnɪŋ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The first part or starting point of something.","vi":"sự bắt đầu; phần đầu; khởi đầu"}],"examples":[{"en":"We missed the beginning of the film yesterday.","vi":"Chúng tôi đã bỏ lỡ phần đầu của bộ phim ngày hôm qua.","audioKind":"ex"},{"en":"The beginning of formal education marks an important stage in a child''s social development.","vi":"Sự khởi đầu của giáo dục chính quy đánh dấu một giai đoạn quan trọng trong sự phát triển xã hội của trẻ em.","audioKind":"ex2"}],"collocations":[{"en":"at the beginning of","vi":"vào lúc bắt đầu"},{"en":"from beginning to end","vi":"từ đầu đến cuối"},{"en":"a new beginning","vi":"một khởi đầu mới"}],"wordFamily":["begin (v.)","beginner (n.)"],"synonyms":["start","opening"],"antonyms":["end"],"tipVi":"at the beginning of đi với danh từ; in the beginning mang nghĩa là lúc đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dirty', 'en-a1-19', 'dirty', '/ˈdɝːti/', 'A1', 'bẩn; dơ dáy; bỉ ổi; không công bằng; làm bẩn; trở nên bẩn', 'adj.', 'dirt (n.), dirtiness (n.)', 'Đồng nghĩa: unclean, filthy · Trái nghĩa: clean', 'Tính từ so sánh hơn là dirtier, so sánh nhất là dirtiest.', 'Please leave your dirty boots outside the kitchen door.', NULL, 'Làm ơn hãy để những đôi bốt bẩn của bạn ở bên ngoài cửa bếp.', '{"wordId":"dirty","ukIpa":"/ˈdɜːti/","usIpa":"/ˈdɝːti/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Covered with dirt or other unwanted substances.","vi":"bẩn; dơ dáy"},{"pos":"adj.","en":"Dishonest or unfair, especially when trying to gain an advantage.","vi":"bỉ ổi; không công bằng"},{"pos":"v.","en":"To make something dirty or become dirty.","vi":"làm bẩn; trở nên bẩn"}],"examples":[{"en":"Please leave your dirty boots outside the kitchen door.","vi":"Làm ơn hãy để những đôi bốt bẩn của bạn ở bên ngoài cửa bếp.","audioKind":"ex"},{"en":"Limited access to clean water forces many communities to rely on dirty sources that can spread disease.","vi":"Tình trạng thiếu nước sạch buộc nhiều cộng đồng phải phụ thuộc vào các nguồn nước ô nhiễm có thể truyền bệnh.","audioKind":"ex2"}],"collocations":[{"en":"dirty clothes","vi":"quần áo bẩn"},{"en":"dirty water","vi":"nước bẩn"},{"en":"get dirty","vi":"làm bẩn"},{"en":"dirty tricks","vi":"mưu hèn kế bẩn"}],"wordFamily":["dirt (n.)","dirtiness (n.)"],"synonyms":["unclean","filthy"],"antonyms":["clean"],"tipVi":"Tính từ so sánh hơn là dirtier, so sánh nhất là dirtiest.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_that', 'en-a1-19', 'that', '/ðæt/', 'A1', 'kia; đó (chỉ vật ở xa); điều đó; cái đó; đại từ quan hệ; rằng (dùng để dẫn dắt mệnh đề danh ngữ/trần thuật)', 'det.', NULL, NULL, 'Số nhiều của đại từ/tính từ chỉ định này là those; có thể lược bỏ that khi dẫn dắt mệnh đề tân ngữ.', 'Could you pass me that bowl beside the window?', NULL, 'Bạn có thể đưa cho tôi chiếc bát ở cạnh cửa sổ đó không?', '{"wordId":"that","ukIpa":"/ðæt/","usIpa":"/ðæt/","cefr":"A1","topic":"daily","senses":[{"pos":"det.","en":"used before a noun to identify something farther away","vi":"kia; đó (chỉ vật ở xa)"},{"pos":"pron.","en":"refers to something indicated, or introduces a defining relative clause","vi":"điều đó; cái đó; đại từ quan hệ"},{"pos":"conj.","en":"introduces a clause expressing a statement, belief, or fact","vi":"rằng (dùng để dẫn dắt mệnh đề danh ngữ/trần thuật)"}],"examples":[{"en":"Could you pass me that bowl beside the window?","vi":"Bạn có thể đưa cho tôi chiếc bát ở cạnh cửa sổ đó không?","audioKind":"ex"},{"en":"Research suggests that access to green spaces can improve mental health among people living in cities.","vi":"Nghiên cứu cho thấy việc tiếp cận không gian xanh có thể cải thiện sức khỏe tinh thần của những người sống ở các thành phố.","audioKind":"ex2"}],"collocations":[{"en":"at that time","vi":"vào lúc đó"},{"en":"that kind of","vi":"loại đó"},{"en":"now that","vi":"già mà; vì giờ đây"},{"en":"so that","vi":"để mà"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Số nhiều của đại từ/tính từ chỉ định này là those; có thể lược bỏ that khi dẫn dắt mệnh đề tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_third', 'en-a1-19', 'third', '/θɝːd/', 'A1', 'thứ ba; một phần ba', 'num.', 'three (num.), thirdly (adv.)', NULL, 'Biểu thị phân số: one third; two thirds.', 'Our flat is on the third floor, beside the lift.', NULL, 'Căn hộ của chúng tôi ở tầng ba, ngay bên cạnh thang máy.', '{"wordId":"third","ukIpa":"/θɜːd/","usIpa":"/θɝːd/","cefr":"A1","topic":"daily","senses":[{"pos":"num.","en":"Coming after the second and before the fourth.","vi":"thứ ba"},{"pos":"n.","en":"One of three equal parts of something.","vi":"một phần ba"}],"examples":[{"en":"Our flat is on the third floor, beside the lift.","vi":"Căn hộ của chúng tôi ở tầng ba, ngay bên cạnh thang máy.","audioKind":"ex"},{"en":"Approximately one third of the city''s residents rely on public transport for their daily commute.","vi":"Khoảng một phần ba cư dân thành phố dựa vào phương tiện giao thông công cộng cho việc đi lại hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"third place","vi":"hạng ba"},{"en":"the third floor","vi":"tầng ba"},{"en":"one third of","vi":"một phần ba của"},{"en":"a third party","vi":"bên thứ ba"}],"wordFamily":["three (num.)","thirdly (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Biểu thị phân số: one third; two thirds.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_second', 'en-a1-19', 'second', '/ˈsekənd/', 'A1', 'thứ hai; giây; khoảnh khắc; ủng hộ; tán thành', 'num.', 'secondly (adv.), secondary (adj.)', NULL, 'the second chỉ người/vật thứ hai; a second có thể chỉ thêm một lần nữa.', 'This is my second cup of tea today.', NULL, 'Đây là tách trà thứ hai của tôi trong ngày hôm nay.', '{"wordId":"second","ukIpa":"/ˈsekənd/","usIpa":"/ˈsekənd/","cefr":"A1","topic":"daily","senses":[{"pos":"num.","en":"Coming immediately after the first in an order.","vi":"thứ hai"},{"pos":"n.","en":"A unit of time equal to one sixtieth of a minute.","vi":"giây; khoảnh khắc"},{"pos":"v.","en":"To formally support a proposal made by someone else.","vi":"ủng hộ; tán thành"}],"examples":[{"en":"This is my second cup of tea today.","vi":"Đây là tách trà thứ hai của tôi trong ngày hôm nay.","audioKind":"ex"},{"en":"Learning a second language can broaden career opportunities and help students understand perspectives from other cultures.","vi":"Học ngôn ngữ thứ hai có thể mở rộng cơ hội nghề nghiệp và giúp học sinh thấu hiểu góc nhìn từ các nền văn hóa khác.","audioKind":"ex2"}],"collocations":[{"en":"second place","vi":"vị trí thứ hai"},{"en":"a second chance","vi":"cơ hội thứ hai"},{"en":"a split second","vi":"một khoảnh khắc ngắn ngủi"},{"en":"second a motion","vi":"biểu quyết tán thành một kiến nghị"}],"wordFamily":["secondly (adv.)","secondary (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"the second chỉ người/vật thứ hai; a second có thể chỉ thêm một lần nữa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_floor', 'en-a1-19', 'floor', '/flɔːr/', 'A1', 'sàn nhà; mặt đất; tầng nhà; đáy biển; đáy thung lũng', 'n.', 'flooring (n.)', NULL, 'Trong tiếng Anh-Anh, first floor là tầng hai; trong tiếng Anh-Mỹ, first floor là tầng một.', 'My keys fell onto the kitchen floor again.', NULL, 'Chìa khóa của tôi lại rơi xuống sàn nhà bếp rồi.', '{"wordId":"floor","ukIpa":"/flɔː/","usIpa":"/flɔːr/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The surface inside a building that people walk on.","vi":"sàn nhà; mặt đất"},{"pos":"n.","en":"A level of a building.","vi":"tầng nhà"},{"pos":"n.","en":"The bottom surface of a sea, valley, or similar area.","vi":"đáy biển; đáy thung lũng"}],"examples":[{"en":"My keys fell onto the kitchen floor again.","vi":"Chìa khóa của tôi lại rơi xuống sàn nhà bếp rồi.","audioKind":"ex"},{"en":"Converting unused upper floors into apartments could help cities address housing shortages without expanding outwards.","vi":"Việc chuyển đổi các tầng trên bỏ trống thành căn hộ có thể giúp các đô thị giải quyết tình trạng thiếu nhà ở mà không cần mở rộng ra vùng ngoại ô.","audioKind":"ex2"}],"collocations":[{"en":"wooden floor","vi":"sàn gỗ"},{"en":"ground floor","vi":"tầng trệt"},{"en":"top floor","vi":"tầng trên cùng"},{"en":"ocean floor","vi":"đáy đại dương"}],"wordFamily":["flooring (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh, first floor là tầng hai; trong tiếng Anh-Mỹ, first floor là tầng một.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_low', 'en-a1-19', 'low', '/loʊ/', 'A1', 'thấp; ít; tâm trạng buồn rầu; thiếu tự tin; ở mức thấp; nhỏ tiếng', 'adj.', 'lower (v.), lowly (adj.)', 'Trái nghĩa: high', 'Mức giá thấp dùng low, còn hàng hóa bán giá rẻ dùng cheap.', 'The low shelf is easy for children to reach.', NULL, 'Chiếc kệ thấp giúp trẻ em dễ dàng với tới đồ vật.', '{"wordId":"low","ukIpa":"/ləʊ/","usIpa":"/loʊ/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Not high in position, amount, level, or degree.","vi":"thấp; ít"},{"pos":"adj.","en":"Feeling sad or lacking confidence.","vi":"tâm trạng buồn rầu; thiếu tự tin"},{"pos":"adv.","en":"At a small height, level, or volume.","vi":"ở mức thấp; nhỏ tiếng"}],"examples":[{"en":"The low shelf is easy for children to reach.","vi":"Chiếc kệ thấp giúp trẻ em dễ dàng với tới đồ vật.","audioKind":"ex"},{"en":"Low wages can prevent essential workers from finding affordable housing close to their places of employment.","vi":"Mức lương thấp có thể khiến những người lao động thiết yếu khó tìm được nhà ở vừa túi tiền gần nơi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"low income","vi":"thu nhập thấp"},{"en":"low temperatures","vi":"nhiệt độ thấp"},{"en":"feel low","vi":"tâm trạng chán nản"},{"en":"run low on","vi":"cạn kiệt dần"}],"wordFamily":["lower (v.)","lowly (adj.)"],"synonyms":[],"antonyms":["high"],"tipVi":"Mức giá thấp dùng low, còn hàng hóa bán giá rẻ dùng cheap.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_move', 'en-a1-19', 'move', '/muːv/', 'A1', 'di chuyển; dời chỗ ở; làm cảm động; khuấy động cảm xúc; biện pháp; bước đi; động thái', 'v.', 'movement (n.), moving (adj.), movable (adj.)', NULL, 'moving chỉ tính chất gây xúc động, còn moved chỉ trạng thái cảm thấy xúc động.', 'Could you move this chair closer to the window?', NULL, 'Bạn có thể dịch chiếc ghế này lại gần cửa sổ hơn một chút được không?', '{"wordId":"move","ukIpa":"/muːv/","usIpa":"/muːv/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To change position or go to live somewhere else.","vi":"di chuyển; dời chỗ ở"},{"pos":"v.","en":"To make someone feel a strong emotion.","vi":"làm cảm động; khuấy động cảm xúc"},{"pos":"n.","en":"An action taken to achieve a particular result.","vi":"biện pháp; bước đi; động thái"}],"examples":[{"en":"Could you move this chair closer to the window?","vi":"Bạn có thể dịch chiếc ghế này lại gần cửa sổ hơn một chút được không?","audioKind":"ex"},{"en":"The decision to expand public transport is a positive move towards reducing urban congestion.","vi":"Quyết định mở rộng hệ thống giao thông công cộng là một động thái tích cực nhằm giảm thiểu tình trạng ùn tắc đô thị.","audioKind":"ex2"}],"collocations":[{"en":"move house","vi":"dọn nhà"},{"en":"move forward","vi":"tiến lên phía trước; đạt được tiến bộ"},{"en":"be deeply moved","vi":"vô cùng cảm động"},{"en":"a positive move","vi":"một động thái tích cực"}],"wordFamily":["movement (n.)","moving (adj.)","movable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"moving chỉ tính chất gây xúc động, còn moved chỉ trạng thái cảm thấy xúc động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_send', 'en-a1-19', 'send', '/send/', 'A1', 'gửi; truyền đi; cử đi; phái đi', 'v.', 'sender (n.), resend (v.)', 'Đồng nghĩa: dispatch · Trái nghĩa: receive', 'Dạng quá khứ và quá khứ phân từ đều là sent; có thể dùng cấu trúc send sth to sb.', 'Please send me a photo of your new puppy.', NULL, 'Làm ơn gửi cho tôi một bức ảnh chú chó con mới của bạn nhé.', '{"wordId":"send","ukIpa":"/send/","usIpa":"/send/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To make something go or be delivered to another place.","vi":"gửi; truyền đi"},{"pos":"v.","en":"To arrange for someone to go somewhere.","vi":"cử đi; phái đi"}],"examples":[{"en":"Please send me a photo of your new puppy.","vi":"Làm ơn gửi cho tôi một bức ảnh chú chó con mới của bạn nhé.","audioKind":"ex"},{"en":"Governments should send medical teams to isolated communities that lack access to basic healthcare.","vi":"Chính phủ nên cử các đội ngũ y tế đến những cộng đồng cô lập thiếu thốn dịch vụ chăm sóc sức khỏe cơ bản.","audioKind":"ex2"}],"collocations":[{"en":"send a message","vi":"gửi tin nhắn"},{"en":"send a parcel","vi":"gửi bưu kiện"},{"en":"send someone to do something","vi":"cử ai đó làm việc gì"}],"wordFamily":["sender (n.)","resend (v.)"],"synonyms":["dispatch"],"antonyms":["receive"],"tipVi":"Dạng quá khứ và quá khứ phân từ đều là sent; có thể dùng cấu trúc send sth to sb.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sixty', 'en-a1-19', 'sixty', '/ˈsɪksti/', 'A1', 'sáu mươi', 'num.', 'sixtieth (num.)', NULL, 'Từ sixty trọng âm rơi vào âm tiết đầu; từ sixteen thường trọng âm rơi vào âm tiết cuối.', 'My grandfather turned sixty and celebrated with a picnic.', NULL, 'Ông tôi bước sang tuổi sáu mươi và tổ chức một buổi dã ngoại để ăn mừng.', '{"wordId":"sixty","ukIpa":"/ˈsɪksti/","usIpa":"/ˈsɪksti/","cefr":"A1","topic":"daily","senses":[{"pos":"num.","en":"the number equal to six times ten","vi":"sáu mươi"}],"examples":[{"en":"My grandfather turned sixty and celebrated with a picnic.","vi":"Ông tôi bước sang tuổi sáu mươi và tổ chức một buổi dã ngoại để ăn mừng.","audioKind":"ex"},{"en":"The survey found that sixty percent of respondents preferred reliable buses to additional parking spaces.","vi":"Cuộc khảo sát cho thấy sáu mươi phần trăm người được hỏi thích xe buýt đáng tin cậy hơn là có thêm không gian đậu xe.","audioKind":"ex2"}],"collocations":[{"en":"sixty percent","vi":"sáu mươi phần trăm"},{"en":"sixty years old","vi":"sáu mươi tuổi"},{"en":"in your sixties","vi":"ở độ tuổi sáu mươi"}],"wordFamily":["sixtieth (num.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ sixty trọng âm rơi vào âm tiết đầu; từ sixteen thường trọng âm rơi vào âm tiết cuối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_list', 'en-a1-19', 'list', '/lɪst/', 'A1', 'danhmục; danh sách; liệt kê', 'n.', 'listing (n.)', NULL, 'Nói có tên trong danh sách dùng on the list, không dùng in.', 'I made a shopping list before leaving home.', NULL, 'Tôi đã lập một danh sách mua sắm trước khi rời nhà.', '{"wordId":"list","ukIpa":"/lɪst/","usIpa":"/lɪst/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"Related items or names written one below another.","vi":"danhmục; danh sách"},{"pos":"v.","en":"To write or state items one after another.","vi":"liệt kê"}],"examples":[{"en":"I made a shopping list before leaving home.","vi":"Tôi đã lập một danh sách mua sắm trước khi rời nhà.","audioKind":"ex"},{"en":"The report lists several practical measures that cities can adopt to reduce traffic congestion.","vi":"Bản báo cáo liệt kê một số biện pháp thực tế mà các thành phố có thể áp dụng để giảm thiểu tình trạng ùn tắc giao thông.","audioKind":"ex2"}],"collocations":[{"en":"make a list","vi":"lập danh sách"},{"en":"shopping list","vi":"danh sách mua sắm"},{"en":"waiting list","vi":"danh sách chờ"}],"wordFamily":["listing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nói có tên trong danh sách dùng on the list, không dùng in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_meet', 'en-a1-19', 'meet', '/miːt/', 'A1', 'gặp gỡ; hội họp; làm quen; đáp ứng; thỏa mãn; đạt tiêu chuẩn', 'v.', 'meeting (n.)', NULL, 'Dạng quá khứ và quá khứ phân từ của meet đều là met; khi đi với yêu cầu, meet có nghĩa là đáp ứng.', 'Let''s meet outside the library after lunch today.', NULL, 'Hôm nay chúng ta gặp nhau ở ngoài thư viện sau bữa trưa nhé.', '{"wordId":"meet","ukIpa":"/miːt/","usIpa":"/miːt/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"come together with someone, by arrangement or chance","vi":"gặp gỡ; hội họp; làm quen"},{"pos":"v.","en":"fulfil a need or reach a required standard","vi":"đáp ứng; thỏa mãn; đạt tiêu chuẩn"}],"examples":[{"en":"Let''s meet outside the library after lunch today.","vi":"Hôm nay chúng ta gặp nhau ở ngoài thư viện sau bữa trưa nhé.","audioKind":"ex"},{"en":"Public transport services must meet the needs of residents who cannot afford private cars.","vi":"Các dịch vụ giao thông công cộng phải đáp ứng nhu cầu của những cư dân không đủ khả năng mua ô tô riêng.","audioKind":"ex2"}],"collocations":[{"en":"meet someone for the first time","vi":"gặp ai đó lần đầu tiên"},{"en":"meet requirements","vi":"đáp ứng các yêu cầu"},{"en":"meet a deadline","vi":"hoàn thành đúng hạn"},{"en":"meet demand","vi":"đáp ứng nhu cầu"}],"wordFamily":["meeting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ và quá khứ phân từ của meet đều là met; khi đi với yêu cầu, meet có nghĩa là đáp ứng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fridge', 'en-a1-19', 'fridge', '/frɪdʒ/', 'A1', 'tủ lạnh', 'n.', NULL, 'Đồng nghĩa: refrigerator', 'fridge là cách viết tắt thông dụng của từ refrigerator.', 'Put the milk back in the fridge, please.', NULL, 'Làm ơn cất sữa lại vào tủ lạnh giúp tôi.', '{"wordId":"fridge","ukIpa":"/frɪdʒ/","usIpa":"/frɪdʒ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"An electrical appliance that keeps food and drinks cold.","vi":"tủ lạnh"}],"examples":[{"en":"Put the milk back in the fridge, please.","vi":"Làm ơn cất sữa lại vào tủ lạnh giúp tôi.","audioKind":"ex"},{"en":"Choosing an energy-efficient fridge can reduce household electricity consumption and lower costs over time.","vi":"Việc lựa chọn một chiếc tủ lạnh tiết kiệm năng lượng có thể làm giảm lượng điện tiêu thụ trong gia đình và tiết kiệm chi phí về lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"in the fridge","vi":"ở trong tủ lạnh"},{"en":"fridge door","vi":"cửa tủ lạnh"},{"en":"fridge freezer","vi":"tủ lạnh kết hợp ngăn đông"}],"wordFamily":[],"synonyms":["refrigerator"],"antonyms":[],"tipVi":"fridge là cách viết tắt thông dụng của từ refrigerator.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dark', 'en-a1-19', 'dark', '/dɑrk/', 'A1', 'tối; tối tăm; thiếu ánh sáng; sậm màu; tối màu; bóng tối; màn đêm', 'adj.', 'darkness (n.), darken (v.), darkish (adj.)', 'Đồng nghĩa: dim · Trái nghĩa: bright, light', 'dark vừa chỉ ánh sáng yếu vừa chỉ màu sắc đậm; bóng tối thường dùng cụm the dark.', 'The hallway was too dark to find my shoes.', NULL, 'Hành lang tối quá nên tôi không tìm thấy giày của mình.', '{"wordId":"dark","ukIpa":"/dɑːk/","usIpa":"/dɑrk/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"having little or no light","vi":"tối; tối tăm; thiếu ánh sáng"},{"pos":"adj.","en":"having a colour closer to black than white","vi":"sậm màu; tối màu"},{"pos":"n.","en":"the absence of light, especially at night","vi":"bóng tối; màn đêm"}],"examples":[{"en":"The hallway was too dark to find my shoes.","vi":"Hành lang tối quá nên tôi không tìm thấy giày của mình.","audioKind":"ex"},{"en":"Poorly lit streets can feel dark and unsafe, discouraging residents from walking after sunset.","vi":"Những con đường thiếu ánh sáng có thể trở nên tối tăm và kém an toàn, khiến người dân ngại đi bộ sau khi trời lặn.","audioKind":"ex2"}],"collocations":[{"en":"get dark","vi":"trở nên tối"},{"en":"dark blue","vi":"màu xanh đậm"},{"en":"in the dark","vi":"trong bóng tối; không hay biết gì"},{"en":"after dark","vi":"sau khi trời tối"}],"wordFamily":["darkness (n.)","darken (v.)","darkish (adj.)"],"synonyms":["dim"],"antonyms":["bright","light"],"tipVi":"dark vừa chỉ ánh sáng yếu vừa chỉ màu sắc đậm; bóng tối thường dùng cụm the dark.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_see', 'en-a1-19', 'see', '/siː/', 'A1', 'nhìn thấy; trông thấy; hiểu; nhận ra; gặp gỡ; thăm hỏi', 'v.', 'unseen (adj.)', NULL, 'Dạng quá khứ là saw, phân từ hai là seen; nhấn mạnh vào việc nhận thức bằng thị giác thay vì chỉ nhìn ngắm chủ động.', 'I can see a rainbow above the trees.', NULL, 'Tôi có thể nhìn thấy một chiếc cầu vồng phía trên ngọn cây.', '{"wordId":"see","ukIpa":"/siː/","usIpa":"/siː/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to notice something using your eyes","vi":"nhìn thấy; trông thấy"},{"pos":"v.","en":"to understand something","vi":"hiểu; nhận ra"},{"pos":"v.","en":"to meet or visit someone","vi":"gặp gỡ; thăm hỏi"}],"examples":[{"en":"I can see a rainbow above the trees.","vi":"Tôi có thể nhìn thấy một chiếc cầu vồng phía trên ngọn cây.","audioKind":"ex"},{"en":"When students see how science applies to everyday life, they often become more interested in learning.","vi":"Khi học sinh hiểu được khoa học được ứng dụng như thế nào vào đời sống hàng ngày, các em thường trở nên hứng thú hơn với việc học.","audioKind":"ex2"}],"collocations":[{"en":"see a doctor","vi":"đi khám bác sĩ"},{"en":"see the difference","vi":"thấy sự khác biệt"},{"en":"see someone''s point","vi":"hiểu quan điểm của ai đó"}],"wordFamily":["unseen (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ là saw, phân từ hai là seen; nhấn mạnh vào việc nhận thức bằng thị giác thay vì chỉ nhìn ngắm chủ động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_potato', 'en-a1-19', 'potato', '/pəˈteɪtoʊ/', 'A1', 'củ khoai tây', 'n.', NULL, NULL, 'Dạng số nhiều là potatoes, thêm -es vào cuối từ.', 'I baked a potato and filled it with cheese.', NULL, 'Tôi đã nướng một củ khoai tây và nhồi phô mai vào bên trong.', '{"wordId":"potato","ukIpa":"/pəˈteɪtəʊ/","usIpa":"/pəˈteɪtoʊ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A round underground vegetable with brown, red, or yellow skin.","vi":"củ khoai tây"}],"examples":[{"en":"I baked a potato and filled it with cheese.","vi":"Tôi đã nướng một củ khoai tây và nhồi phô mai vào bên trong.","audioKind":"ex"},{"en":"Potato farming provides an important source of food and income for many rural communities worldwide.","vi":"Việc trồng khoai tây cung cấp nguồn lương thực và thu nhập quan trọng cho nhiều cộng đồng nông thôn trên toàn thế giới.","audioKind":"ex2"}],"collocations":[{"en":"baked potato","vi":"khoai tây nướng"},{"en":"mashed potato","vi":"khoai tây nghiền"},{"en":"peel potatoes","vi":"gọt vỏ khoai tây"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là potatoes, thêm -es vào cuối từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_my', 'en-a1-19', 'my', '/maɪ/', 'A1', 'của tôi', 'det.', 'I (pron.), me (pron.), mine (pron.), myself (pron.)', NULL, 'my phải đứng trước danh từ; từ mine có thể đứng độc lập mang nghĩa ''của tôi''.', 'I left my umbrella beside the front door.', NULL, 'Tôi để chiếc ô của mình ngay bên cạnh cửa trước.', '{"wordId":"my","ukIpa":"/maɪ/","usIpa":"/maɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"det.","en":"Belonging to or connected with the person speaking.","vi":"của tôi"}],"examples":[{"en":"I left my umbrella beside the front door.","vi":"Tôi để chiếc ô của mình ngay bên cạnh cửa trước.","audioKind":"ex"},{"en":"In my view, cities should prioritise affordable housing rather than invest heavily in prestigious construction projects.","vi":"Theo quan điểm của tôi, các thành phố nên ưu tiên nhà ở giá rẻ thay vì đầu tư mạnh tay vào các dự án xây dựng mang tính đánh bóng tên tuổi.","audioKind":"ex2"}],"collocations":[{"en":"my own","vi":"của riêng tôi"},{"en":"in my opinion","vi":"theo quan điểm của tôi"},{"en":"to my surprise","vi":"thật ngạc nhiên là"}],"wordFamily":["I (pron.)","me (pron.)","mine (pron.)","myself (pron.)"],"synonyms":[],"antonyms":[],"tipVi":"my phải đứng trước danh từ; từ mine có thể đứng độc lập mang nghĩa ''của tôi''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_later', 'en-a1-19', 'later', '/ˈleɪtər/', 'A1', 'sau; lát nữa; sau đó; sau này; về sau', 'adv.', 'late (adj.), late (adv.), lateness (n.)', 'Đồng nghĩa: afterwards · Trái nghĩa: earlier', 'later chỉ thời gian muộn hơn; latter chỉ người hoặc vật thứ hai trong hai đối tượng vừa nhắc tới.', 'I''ll wash the dishes later, after we finish eating.', NULL, 'Lát nữa ăn xong tôi sẽ rửa bát.', '{"wordId":"later","ukIpa":"/ˈleɪtə/","usIpa":"/ˈleɪtər/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"at a time after now or another mentioned time","vi":"sau; lát nữa; sau đó"},{"pos":"adj.","en":"happening or existing after another time or stage","vi":"sau này; về sau"}],"examples":[{"en":"I''ll wash the dishes later, after we finish eating.","vi":"Lát nữa ăn xong tôi sẽ rửa bát.","audioKind":"ex"},{"en":"Children who develop strong reading habits often achieve better academic results later in life.","vi":"Những đứa trẻ phát triển được thói quen đọc sách tốt thường đạt được kết quả học tập cao hơn trong giai đoạn sau của cuộc đời.","audioKind":"ex2"}],"collocations":[{"en":"see you later","vi":"hẹn gặp lại sau"},{"en":"later on","vi":"về sau; sau này"},{"en":"later in life","vi":"vào giai đoạn sau của cuộc đời"},{"en":"at a later stage","vi":"ở một giai đoạn sau"}],"wordFamily":["late (adj.)","late (adv.)","lateness (n.)"],"synonyms":["afterwards"],"antonyms":["earlier"],"tipVi":"later chỉ thời gian muộn hơn; latter chỉ người hoặc vật thứ hai trong hai đối tượng vừa nhắc tới.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 28, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_19_1', 'en-a1-19', 'Cách dùng “see” (v.) — nhìn thấy; trông thấy', 'see a doctor  ·  see the difference  ·  see someone''s point', 'Dạng quá khứ là saw, phân từ hai là seen; nhấn mạnh vào việc nhận thức bằng thị giác thay vì chỉ nhìn ngắm chủ động.', 'Họ từ (Word Family): unseen (adj.)', '[{"hanzi":"I can see a rainbow above the trees.","pinyin":"","meaning":"Tôi có thể nhìn thấy một chiếc cầu vồng phía trên ngọn cây."},{"hanzi":"When students see how science applies to everyday life, they often become more interested in learning.","pinyin":"","meaning":"Khi học sinh hiểu được khoa học được ứng dụng như thế nào vào đời sống hàng ngày, các em thường trở nên hứng thú hơn với việc học."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_19_2', 'en-a1-19', 'Cách dùng “tomato” (n.) — cà chua', 'ripe tomato  ·  tomato sauce  ·  cherry tomato', 'Dạng số nhiều là "tomatoes"; phát âm nguyên âm nhấn trọng lượng trong tiếng Anh-Anh và Anh-Mỹ khác nhau.', NULL, '[{"hanzi":"She sliced a ripe tomato for her cheese sandwich.","pinyin":"","meaning":"Cô ấy cắt một quả cà chua chín để làm bánh mì kẹp phô mai."},{"hanzi":"Growing tomatoes in community gardens can improve access to fresh food in urban neighbourhoods.","pinyin":"","meaning":"Trồng cà chua trong các khu vườn cộng đồng có thể giúp cư dân đô thị dễ dàng tiếp cận thực phẩm tươi hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_19_3', 'en-a1-19', 'Cách dùng “that” (det.) — kia; đó (chỉ vật ở xa)', 'at that time  ·  that kind of  ·  now that', 'Số nhiều của đại từ/tính từ chỉ định này là those; có thể lược bỏ that khi dẫn dắt mệnh đề tân ngữ.', NULL, '[{"hanzi":"Could you pass me that bowl beside the window?","pinyin":"","meaning":"Bạn có thể đưa cho tôi chiếc bát ở cạnh cửa sổ đó không?"},{"hanzi":"Research suggests that access to green spaces can improve mental health among people living in cities.","pinyin":"","meaning":"Nghiên cứu cho thấy việc tiếp cận không gian xanh có thể cải thiện sức khỏe tinh thần của những người sống ở các thành phố."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_19_4', 'en-a1-19', 'Cách dùng “meet” (v.) — gặp gỡ; hội họp; làm quen', 'meet someone for the first time  ·  meet requirements  ·  meet a deadline', 'Dạng quá khứ và quá khứ phân từ của meet đều là met; khi đi với yêu cầu, meet có nghĩa là đáp ứng.', 'Họ từ (Word Family): meeting (n.)', '[{"hanzi":"Let''s meet outside the library after lunch today.","pinyin":"","meaning":"Hôm nay chúng ta gặp nhau ở ngoài thư viện sau bữa trưa nhé."},{"hanzi":"Public transport services must meet the needs of residents who cannot afford private cars.","pinyin":"","meaning":"Các dịch vụ giao thông công cộng phải đáp ứng nhu cầu của những cư dân không đủ khả năng mua ô tô riêng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
