INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_19_1_1', 'en-a1-19', 'ten_19_1', 'listening', 'listening', 'We need to leave before the traffic gets worse.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Xin hãy mở cửa sổ ra và để một chút không khí trong lành tràn vào.","Chân tôi cảm thấy mỏi nhừ sau quãng đường đi bộ dài về nhà.","Chúng ta cần phải rời đi trước khi tình trạng giao thông trở nên tồi tệ hơn.","Tôi sẽ cố gắng sửa cái đèn này trước bữa tối."]'::jsonb, 2, 'We need to leave before the traffic gets worse. → Chúng ta cần phải rời đi trước khi tình trạng giao thông trở nên tồi tệ hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_19_1_2', 'en-a1-19', 'ten_19_1', 'listening', 'listening', 'Please open the window and let some fresh air in.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chân tôi cảm thấy mỏi nhừ sau quãng đường đi bộ dài về nhà.","Tôi sẽ cố gắng sửa cái đèn này trước bữa tối.","Chúng ta cần phải rời đi trước khi tình trạng giao thông trở nên tồi tệ hơn.","Xin hãy mở cửa sổ ra và để một chút không khí trong lành tràn vào."]'::jsonb, 3, 'Please open the window and let some fresh air in. → Xin hãy mở cửa sổ ra và để một chút không khí trong lành tràn vào.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_19_1_3', 'en-a1-19', 'ten_19_1', 'listening', 'listening', 'My legs felt tired after the long walk home.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng ta cần phải rời đi trước khi tình trạng giao thông trở nên tồi tệ hơn.","Cô ấy cắt một quả cà chua chín để làm bánh mì kẹp phô mai.","Chân tôi cảm thấy mỏi nhừ sau quãng đường đi bộ dài về nhà.","Xin hãy mở cửa sổ ra và để một chút không khí trong lành tràn vào."]'::jsonb, 2, 'My legs felt tired after the long walk home. → Chân tôi cảm thấy mỏi nhừ sau quãng đường đi bộ dài về nhà.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_19_2', 'en-a1-19', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_19_2_1', 'ten_19_2', 'leave', 'Paid parental leave allows new parents to care for their children without immediately returning to work.', 'Paid parental leave allows new parents to care for their children without immediately returning to work.', '/liːv/', 'Chế độ nghỉ phép chăm sóc con có lương giúp các bậc cha mẹ mới sinh có thể chăm sóc con cái mà không phải quay lại làm việc ngay lập tức.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_19_2_2', 'ten_19_2', 'window', 'Installing larger windows can reduce the need for artificial lighting in homes during daylight hours.', 'Installing larger windows can reduce the need for artificial lighting in homes during daylight hours.', '/ˈwɪndoʊ/', 'Lắp đặt các ô cửa sổ lớn hơn có thể làm giảm nhu cầu sử dụng đèn nhân tạo trong nhà vào ban ngày.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_19_2_3', 'ten_19_2', 'leg', 'Regular walking strengthens the muscles in our legs and can improve health without expensive equipment.', 'Regular walking strengthens the muscles in our legs and can improve health without expensive equipment.', '/leɡ/', 'Việc đi bộ thường xuyên giúp tăng cường cơ chân và có thể cải thiện sức khỏe mà không cần các thiết bị đắt tiền.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_19_2_4', 'ten_19_2', 'tomato', 'Growing tomatoes in community gardens can improve access to fresh food in urban neighbourhoods.', 'Growing tomatoes in community gardens can improve access to fresh food in urban neighbourhoods.', '/təˈmeɪtoʊ/', 'Trồng cà chua trong các khu vườn cộng đồng có thể giúp cư dân đô thị dễ dàng tiếp cận thực phẩm tươi hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_19_2_5', 'ten_19_2', 'try', 'Schools should try different teaching methods to meet the needs of students with varying abilities.', 'Schools should try different teaching methods to meet the needs of students with varying abilities.', '/traɪ/', 'Các trường học nên thử nghiệm các phương pháp giảng dạy khác nhau để đáp ứng nhu cầu của học sinh có năng lực khác nhau.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_19_2_6', 'ten_19_2', 'restaurant', 'Local restaurants can attract tourists by serving traditional dishes made with ingredients from nearby farms.', 'Local restaurants can attract tourists by serving traditional dishes made with ingredients from nearby farms.', '/ˈrestərɑːnt/', 'Các nhà hàng địa phương có thể thu hút khách du lịch bằng cách phục vụ các món ăn truyền thống làm từ nguyên liệu của các trang trại gần đó.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
