INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_19_2', 'en-a1-19', NULL, 'comprehensive_test', 'listening', 'Please open the window and let some fresh air in.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Xin hãy mở cửa sổ ra và để một chút không khí trong lành tràn vào.","Tôi đã lập một danh sách mua sắm trước khi rời nhà.","Anh trai tôi quên mang bữa trưa, vì vậy tôi đã mang nó đến cho anh ấy.","Hôm nay chúng ta gặp nhau ở ngoài thư viện sau bữa trưa nhé."]'::jsonb, 0, 'Please open the window and let some fresh air in. → Xin hãy mở cửa sổ ra và để một chút không khí trong lành tràn vào.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
