INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_19_4', 'en-a1-19', NULL, 'comprehensive_test', 'listening', 'She sliced a ripe tomato for her cheese sandwich.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy cắt một quả cà chua chín để làm bánh mì kẹp phô mai.","Căn hộ của chúng tôi ở tầng ba, ngay bên cạnh thang máy.","Chìa khóa của tôi lại rơi xuống sàn nhà bếp rồi.","Ông tôi bước sang tuổi sáu mươi và tổ chức một buổi dã ngoại để ăn mừng."]'::jsonb, 0, 'She sliced a ripe tomato for her cheese sandwich. → Cô ấy cắt một quả cà chua chín để làm bánh mì kẹp phô mai.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
