INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_19_6', 'en-a1-19', NULL, 'comprehensive_test', 'listening', 'We found a quiet restaurant beside the river.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã nướng một củ khoai tây và nhồi phô mai vào bên trong.","Tôi để chiếc ô của mình ngay bên cạnh cửa trước.","Chúng tôi tìm thấy một nhà hàng yên tĩnh bên bờ sông.","Ông tôi bước sang tuổi sáu mươi và tổ chức một buổi dã ngoại để ăn mừng."]'::jsonb, 2, 'We found a quiet restaurant beside the river. → Chúng tôi tìm thấy một nhà hàng yên tĩnh bên bờ sông.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_19_7', 'en-a1-19', NULL, 'comprehensive_test', 'listening', 'father', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thậm chí; ngay cả","cha; bố","váy liền thân; đầm","nước Anh; đảo Anh; Đại Anh"]'::jsonb, 1, 'father (/ˈfɑːðər/) → cha; bố; người sáng lập; bậc khai sáng; làm cha; sinh con', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_19_8', 'en-a1-19', NULL, 'comprehensive_test', 'listening', 'A tiny stone in my shoe hurt my foot.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chìa khóa của tôi lại rơi xuống sàn nhà bếp rồi.","Căn hộ của chúng tôi ở tầng ba, ngay bên cạnh thang máy.","Một viên sỏi nhỏ trong giày đã làm đau bàn chân tôi.","Bạn có thể dịch chiếc ghế này lại gần cửa sổ hơn một chút được không?"]'::jsonb, 2, 'A tiny stone in my shoe hurt my foot. → Một viên sỏi nhỏ trong giày đã làm đau bàn chân tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_19_9', 'en-a1-19', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “make an effort to do something”?', '["floor","send","try","tomato"]'::jsonb, 2, 'try (/traɪ/) → cố gắng; thử', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
