INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_19_18', 'en-a1-19', NULL, 'comprehensive_test', 'reading', NULL, 'Paid parental leave allows new parents to care for their children without immediately returning to work.', 'Dựa vào câu trên, từ “leave” có nghĩa phù hợp nhất là gì?', '["cảm xúc; tâm trạng","cái ô; cái dù","rời đi; xuất phát","tai"]'::jsonb, 2, 'leave: rời đi; xuất phát; để lại; bỏ quên; nghỉ phép; kỳ nghỉ. Dịch cả câu: Chế độ nghỉ phép chăm sóc con có lương giúp các bậc cha mẹ mới sinh có thể chăm sóc con cái mà không phải quay lại làm việc ngay lập tức.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_19_19', 'en-a1-19', NULL, 'comprehensive_test', 'reading', NULL, 'Installing larger windows can reduce the need for artificial lighting in homes during daylight hours.', 'Dựa vào câu trên, từ “window” có nghĩa phù hợp nhất là gì?', '["vào tối nay; trong đêm nay","cái ô; cái dù","rẻ; giá rẻ; giá thấp","cửa sổ"]'::jsonb, 3, 'window: cửa sổ; cửa sổ hiển thị (trên màn hình); thời điểm; cơ hội ngắn ngủi. Dịch cả câu: Lắp đặt các ô cửa sổ lớn hơn có thể làm giảm nhu cầu sử dụng đèn nhân tạo trong nhà vào ban ngày.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_19_20', 'en-a1-19', NULL, 'comprehensive_test', 'reading', NULL, 'Regular walking strengthens the muscles in our legs and can improve health without expensive equipment.', 'Dựa vào câu trên, từ “leg” có nghĩa phù hợp nhất là gì?', '["chân","súp; canh","bút chì","đẹp; xinh đẹp; tuyệt vời"]'::jsonb, 0, 'leg: chân; chân (bàn, ghế hoặc vật dụng tương tự); chặng (của một cuộc hành trình hoặc cuộc đua). Dịch cả câu: Việc đi bộ thường xuyên giúp tăng cường cơ chân và có thể cải thiện sức khỏe mà không cần các thiết bị đắt tiền.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_19_21', 'en-a1-19', NULL, 'comprehensive_test', 'reading', NULL, 'Growing tomatoes in community gardens can improve access to fresh food in urban neighbourhoods.', 'Dựa vào câu trên, từ “tomato” có nghĩa phù hợp nhất là gì?', '["ở tầng dưới; xuống tầng dưới","lớn; to lớn","một nửa; nửa","cà chua"]'::jsonb, 3, 'tomato: cà chua. Dịch cả câu: Trồng cà chua trong các khu vườn cộng đồng có thể giúp cư dân đô thị dễ dàng tiếp cận thực phẩm tươi hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
