INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-20', 'en', 'Bài 20: Đời sống hằng ngày (5) - CEFR A1', 'CEFR A1', 'A1 · Đời sống', '28 từ vựng Tiếng Anh CEFR A1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1020, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_soon', 'en-a1-20', 'soon', '/suːn/', 'A1', 'chẳng bao lâu; sớm; nhanh chóng', 'adv.', NULL, 'Đồng nghĩa: shortly', 'Khi as soon as dẫn dắt mệnh đề chỉ thời gian trong tương lai, người ta thường dùng thì hiện tại đơn.', 'Dinner will be ready soon, so wash your hands.', NULL, 'Bữa tối sắp xong rồi, hãy đi rửa tay đi.', '{"wordId":"soon","ukIpa":"/suːn/","usIpa":"/suːn/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"After a short time from now or another stated time.","vi":"chẳng bao lâu; sớm; nhanh chóng"}],"examples":[{"en":"Dinner will be ready soon, so wash your hands.","vi":"Bữa tối sắp xong rồi, hãy đi rửa tay đi.","audioKind":"ex"},{"en":"Unless cities improve public transport soon, traffic congestion is likely to become increasingly severe.","vi":"Trừ khi các thành phố cải thiện giao thông công cộng sớm, tình trạng ùn tắc giao thông có xu hướng ngày càng trở nên nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"as soon as possible","vi":"càng sớm càng tốt"},{"en":"soon after","vi":"chẳng bao lâu sau"},{"en":"too soon","vi":"quá sớm"},{"en":"see you soon","vi":"hẹn sớm gặp lại"}],"wordFamily":[],"synonyms":["shortly"],"antonyms":[],"tipVi":"Khi as soon as dẫn dắt mệnh đề chỉ thời gian trong tương lai, người ta thường dùng thì hiện tại đơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_umbrella', 'en-a1-20', 'umbrella', '/ʌmˈbrelə/', 'A1', 'cái ô; cái dù; mang tính tổng hợp; bao quát', 'n.', NULL, NULL, 'umbrella term chỉ thuật ngữ bao trùm nhiều khái niệm liên quan.', 'We shared an umbrella on the walk home.', NULL, 'Chúng tôi cùng che chung một chiếc ô trên quãng đường đi bộ về nhà.', '{"wordId":"umbrella","ukIpa":"/ʌmˈbrelə/","usIpa":"/ʌmˈbrelə/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a folding cover on a stick protecting against rain or sun","vi":"cái ô; cái dù"},{"pos":"adj.","en":"including several different groups, activities, or ideas","vi":"mang tính tổng hợp; bao quát"}],"examples":[{"en":"We shared an umbrella on the walk home.","vi":"Chúng tôi cùng che chung một chiếc ô trên quãng đường đi bộ về nhà.","audioKind":"ex"},{"en":"An umbrella organisation can help small charities coordinate their activities and share resources more effectively.","vi":"Một tổ chức mái nhà chung có thể giúp các tổ chức từ thiện nhỏ điều phối hoạt động và chia sẻ nguồn lực hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"open an umbrella","vi":"mở ô"},{"en":"under an umbrella","vi":"dưới ô"},{"en":"umbrella organisation","vi":"tổ chức mái nhà chung; tổ chức đầu mối"},{"en":"umbrella term","vi":"thuật ngữ chung"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"umbrella term chỉ thuật ngữ bao trùm nhiều khái niệm liên quan.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_after', 'en-a1-20', 'after', '/ˈæftər/', 'A1', 'sau; sau khi; sau khi; sau; đằng sau; đuổi theo', 'prep.', NULL, 'Trái nghĩa: before', 'Giới từ theo sau là danh từ hoặc danh động từ; liên từ theo sau là một mệnh đề hoàn chỉnh.', 'We usually take a short walk after dinner.', NULL, 'Chúng tôi thường đi dạo ngắn sau bữa tối.', '{"wordId":"after","ukIpa":"/ˈɑːftə/","usIpa":"/ˈæftər/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"later than an event or time","vi":"sau; sau khi"},{"pos":"conj.","en":"following the time when something happens","vi":"sau khi"},{"pos":"prep.","en":"behind or following someone or something","vi":"sau; đằng sau; đuổi theo"}],"examples":[{"en":"We usually take a short walk after dinner.","vi":"Chúng tôi thường đi dạo ngắn sau bữa tối.","audioKind":"ex"},{"en":"After cities improve public transport, more residents may choose to leave their cars at home.","vi":"Sau khi các thành phố cải thiện hệ thống giao thông công cộng, nhiều cư dân có thể chọn cách để xe ở nhà.","audioKind":"ex2"}],"collocations":[{"en":"after school","vi":"sau giờ học"},{"en":"after a while","vi":"sau một lúc"},{"en":"look after","vi":"chăm sóc; trông nom"},{"en":"run after","vi":"đuổi theo"}],"wordFamily":[],"synonyms":[],"antonyms":["before"],"tipVi":"Giới từ theo sau là danh từ hoặc danh động từ; liên từ theo sau là một mệnh đề hoàn chỉnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_around', 'en-a1-20', 'around', '/əˈraʊnd/', 'A1', 'xung quanh; vòng quanh; khoảng; xấp xỉ; quanh đây; khắp nơi', 'prep.', NULL, NULL, 'around có thể dùng để chỉ mức độ xấp xỉ; around ten nghĩa là khoảng mười giờ hoặc mười mấy.', 'We sat around the fire and watched the stars.', NULL, 'Chúng tôi ngồi quây quần bên đống lửa và ngắm những vì sao.', '{"wordId":"around","ukIpa":"/əˈraʊnd/","usIpa":"/əˈraʊnd/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"On different sides of something or surrounding it.","vi":"xung quanh; vòng quanh"},{"pos":"adv.","en":"Approximately, rather than exactly.","vi":"khoảng; xấp xỉ"},{"pos":"adv.","en":"In or to various places within an area.","vi":"quanh đây; khắp nơi"}],"examples":[{"en":"We sat around the fire and watched the stars.","vi":"Chúng tôi ngồi quây quần bên đống lửa và ngắm những vì sao.","audioKind":"ex"},{"en":"Planting trees around school buildings can provide shade and reduce indoor temperatures during hot weather.","vi":"Trồng cây xanh xung quanh các tòa nhà trường học có thể tạo bóng râm và giảm nhiệt độ trong nhà khi thời tiết oi bức.","audioKind":"ex2"}],"collocations":[{"en":"around the world","vi":"khắp thế giới"},{"en":"around the corner","vi":"sắp đến nơi; ngay gần góc phố"},{"en":"look around","vi":"nhìn xung quanh"},{"en":"around midday","vi":"vào khoảng giữa trưa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"around có thể dùng để chỉ mức độ xấp xỉ; around ten nghĩa là khoảng mười giờ hoặc mười mấy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_by', 'en-a1-20', 'by', '/baɪ/', 'A1', 'bởi; bằng; thông qua; trước; không muộn hơn', 'prep.', NULL, NULL, 'by chỉ mốc thời gian hoàn thành; until chỉ hành động hoặc trạng thái kéo dài đến một thời điểm.', 'This wooden bowl was made by my grandfather.', NULL, 'Chiếc bát gỗ này được làm bởi ông tôi.', '{"wordId":"by","ukIpa":"/baɪ/","usIpa":"/baɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"Shows who or what performs an action in passive sentences.","vi":"bởi"},{"pos":"prep.","en":"Using a particular method or means.","vi":"bằng; thông qua"},{"pos":"prep.","en":"No later than a particular time.","vi":"trước; không muộn hơn"}],"examples":[{"en":"This wooden bowl was made by my grandfather.","vi":"Chiếc bát gỗ này được làm bởi ông tôi.","audioKind":"ex"},{"en":"Urban air quality can be improved by expanding public transport and encouraging residents to cycle more often.","vi":"Chất lượng không khí đô thị có thể được cải thiện bằng cách mở rộng giao thông công cộng và khuyến khích người dân đi xe đạp nhiều hơn.","audioKind":"ex2"}],"collocations":[{"en":"by bus","vi":"bằng xe buýt"},{"en":"by doing something","vi":"bằng cách làm gì đó"},{"en":"by the end of","vi":"vào trước thời điểm kết thúc"},{"en":"by hand","vi":"làm thủ công"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"by chỉ mốc thời gian hoàn thành; until chỉ hành động hoặc trạng thái kéo dài đến một thời điểm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_smell', 'en-a1-20', 'smell', '/smel/', 'A1', 'mùi; khứu giác; ngửi thấy; đánh hơi; có mùi; tỏa mùi', 'n.', 'smelly (adj.)', 'Đồng nghĩa: odour, scent', 'smell đóng vai trò là động từ nối theo sau bởi tính từ, ví dụ như smell good.', 'The smell of fresh bread filled our kitchen.', NULL, 'Mùi bánh mỳ tươi lan tỏa khắp căn bếp của chúng tôi.', '{"wordId":"smell","ukIpa":"/smel/","usIpa":"/smel/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a quality sensed through the nose, or that sensing ability","vi":"mùi; khứu giác"},{"pos":"v.","en":"notice or examine something using your nose","vi":"ngửi thấy; đánh hơi"},{"pos":"v.","en":"have or give off a particular scent","vi":"có mùi; tỏa mùi"}],"examples":[{"en":"The smell of fresh bread filled our kitchen.","vi":"Mùi bánh mỳ tươi lan tỏa khắp căn bếp của chúng tôi.","audioKind":"ex"},{"en":"A reduced sense of smell can affect appetite and make it harder to detect spoiled food.","vi":"Khứu giác suy giảm có thể ảnh hưởng đến vị giác và khiến việc phát hiện thực phẩm bị hỏng trở nên khó khăn hơn.","audioKind":"ex2"}],"collocations":[{"en":"sense of smell","vi":"khứu giác"},{"en":"strong smell","vi":"mùi nồng"},{"en":"smell fresh","vi":"mùi thơm tươi mới"},{"en":"smell of smoke","vi":"có mùi khói"}],"wordFamily":["smelly (adj.)"],"synonyms":["odour","scent"],"antonyms":[],"tipVi":"smell đóng vai trò là động từ nối theo sau bởi tính từ, ví dụ như smell good.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grandparent', 'en-a1-20', 'grandparent', '/ˈɡrænperənt/', 'A1', 'ông; bà; ông bà', 'n.', 'grandmother (n.), grandfather (n.), grandchild (n.)', NULL, 'Dạng số ít chỉ một người ông hoặc người bà; dạng số nhiều chỉ chung ông bà nội ngoại.', 'Each grandparent brought a homemade dish to our picnic.', NULL, 'Mỗi ông bà đều mang một món ăn tự nấu đến buổi dã ngoại của chúng tôi.', '{"wordId":"grandparent","ukIpa":"/ˈɡrænpeərənt/","usIpa":"/ˈɡrænperənt/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The father or mother of one of your parents.","vi":"ông; bà; ông bà"}],"examples":[{"en":"Each grandparent brought a homemade dish to our picnic.","vi":"Mỗi ông bà đều mang một món ăn tự nấu đến buổi dã ngoại của chúng tôi.","audioKind":"ex"},{"en":"A grandparent can provide valuable emotional support when both parents work outside the home.","vi":"Ông bà có thể mang lại nguồn hỗ trợ tinh thần vô giá khi cả bố lẫn mẹ đều bận rộn làm việc bên ngoài.","audioKind":"ex2"}],"collocations":[{"en":"grandparents and grandchildren","vi":"ông bà và cháu"},{"en":"visit your grandparents","vi":"thăm ông bà"},{"en":"maternal grandparents","vi":"ông bà ngoại"}],"wordFamily":["grandmother (n.)","grandfather (n.)","grandchild (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng số ít chỉ một người ông hoặc người bà; dạng số nhiều chỉ chung ông bà nội ngoại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wide', 'en-a1-20', 'wide', '/waɪd/', 'A1', 'adj. rộng; rộng lớn; adj. rộng rãi; bao quát; đa dạng; adv. mở rộng hết cỡ', 'adj.', 'width (n.), widen (v.), widely (adv.)', 'Đồng nghĩa: broad · Trái nghĩa: narrow', 'wide chỉ mức độ mở rộng hoặc khoảng cách; widely thường dùng với ý nghĩa rộng rãi, phổ biến.', 'The sofa will not fit through this wide doorway.', NULL, 'Chiếc ghế sofa sẽ không thể lọt qua khung cửa rộng này.', '{"wordId":"wide","ukIpa":"/waɪd/","usIpa":"/waɪd/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"measuring a large distance from one side to the other","vi":"adj. rộng; rộng lớn"},{"pos":"adj.","en":"including many different people, things, or possibilities","vi":"adj. rộng rãi; bao quát; đa dạng"},{"pos":"adv.","en":"as far open as possible","vi":"adv. mở rộng hết cỡ"}],"examples":[{"en":"The sofa will not fit through this wide doorway.","vi":"Chiếc ghế sofa sẽ không thể lọt qua khung cửa rộng này.","audioKind":"ex"},{"en":"Universities should offer a wide range of courses to meet students'' different interests and career goals.","vi":"Các trường đại học nên cung cấp nhiều loại khóa học phong phú để đáp ứng các sở thích và mục tiêu nghề nghiệp khác nhau của sinh viên.","audioKind":"ex2"}],"collocations":[{"en":"a wide road","vi":"con đường rộng"},{"en":"a wide range of","vi":"nhiều loại; đa dạng"},{"en":"wide open","vi":"mở toang"},{"en":"a wide gap","vi":"khoảng cách lớn"}],"wordFamily":["width (n.)","widen (v.)","widely (adv.)"],"synonyms":["broad"],"antonyms":["narrow"],"tipVi":"wide chỉ mức độ mở rộng hoặc khoảng cách; widely thường dùng với ý nghĩa rộng rãi, phổ biến.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cold', 'en-a1-20', 'cold', '/koʊld/', 'A1', 'lạnh; lạnh lẽo; bệnh cảm lạnh; lạnh nhạt; thiếu thân thiện', 'adj.', 'coldness (n.), coldly (adv.)', 'Đồng nghĩa: chilly · Trái nghĩa: hot, warm', 'Dùng "be cold" để diễn tả cảm thấy lạnh; dùng "have a cold" để diễn tả bị cảm lạnh.', 'My hands were cold, so I put on gloves.', NULL, 'Tay tôi bị lạnh nên tôi đã đeo găng tay vào.', '{"wordId":"cold","ukIpa":"/kəʊld/","usIpa":"/koʊld/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Having a low temperature or feeling a lack of warmth.","vi":"lạnh; lạnh lẽo"},{"pos":"n.","en":"A common illness causing sneezing, coughing, and a runny nose.","vi":"bệnh cảm lạnh"},{"pos":"adj.","en":"Showing little friendliness, affection, or sympathy.","vi":"lạnh nhạt; thiếu thân thiện"}],"examples":[{"en":"My hands were cold, so I put on gloves.","vi":"Tay tôi bị lạnh nên tôi đã đeo găng tay vào.","audioKind":"ex"},{"en":"Cold weather can increase household energy costs, placing additional pressure on families with limited incomes.","vi":"Thời tiết lạnh giá có thể làm tăng chi phí năng lượng hộ gia đình, gây thêm áp lực cho các gia đình có thu nhập hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"cold weather","vi":"thời tiết lạnh"},{"en":"catch a cold","vi":"bị cảm lạnh"},{"en":"have a cold","vi":"đang bị cảm lạnh"},{"en":"a cold welcome","vi":"sự đón tiếp lạnh nhạt"}],"wordFamily":["coldness (n.)","coldly (adv.)"],"synonyms":["chilly"],"antonyms":["hot","warm"],"tipVi":"Dùng \"be cold\" để diễn tả cảm thấy lạnh; dùng \"have a cold\" để diễn tả bị cảm lạnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trousers', 'en-a1-20', 'trousers', '/ˈtraʊzərz/', 'A1', 'quần dài', 'n.', NULL, 'Đồng nghĩa: pants', 'Luôn dùng ở dạng số nhiều: "trousers are"; một chiếc quần dùng "a pair of trousers".', 'These trousers are too long, so I need them shortened.', NULL, 'Chiếc quần này dài quá nên tôi cần đi cắt ngắn lại.', '{"wordId":"trousers","ukIpa":"/ˈtraʊzəz/","usIpa":"/ˈtraʊzərz/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"Clothing covering the waist and legs, with separate leg sections.","vi":"quần dài"}],"examples":[{"en":"These trousers are too long, so I need them shortened.","vi":"Chiếc quần này dài quá nên tôi cần đi cắt ngắn lại.","audioKind":"ex"},{"en":"Some employers require staff to wear formal trousers, while others allow more casual clothing in the workplace.","vi":"Một số nhà tuyển dụng yêu cầu nhân viên mặc quần tây trang trọng, trong khi những người khác cho phép ăn mặc thoải mái hơn tại nơi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"a pair of trousers","vi":"một chiếc quần dài"},{"en":"formal trousers","vi":"quần tây trang trọng"},{"en":"try on trousers","vi":"thử quần"}],"wordFamily":[],"synonyms":["pants"],"antonyms":[],"tipVi":"Luôn dùng ở dạng số nhiều: \"trousers are\"; một chiếc quần dùng \"a pair of trousers\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coffee', 'en-a1-20', 'coffee', '/ˈkɑːfi/', 'A1', 'cà phê; bột cà phê; hạt cà phê', 'n.', NULL, NULL, 'Thường là danh từ không đếm được; khi gọi món, "two coffees" có nghĩa là hai tách cà phê.', 'I drink coffee with milk before leaving for work.', NULL, 'Tôi uống cà phê sữa trước khi đi làm.', '{"wordId":"coffee","ukIpa":"/ˈkɒfi/","usIpa":"/ˈkɑːfi/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A drink made from roasted beans, or the beans and powder.","vi":"cà phê; bột cà phê; hạt cà phê"}],"examples":[{"en":"I drink coffee with milk before leaving for work.","vi":"Tôi uống cà phê sữa trước khi đi làm.","audioKind":"ex"},{"en":"Rising temperatures may threaten coffee production, affecting the incomes of farmers in several developing countries.","vi":"Nhiệt độ tăng cao có thể đe dọa sản lượng cà phê, ảnh hưởng đến thu nhập của nông dân ở một số quốc gia đang phát triển.","audioKind":"ex2"}],"collocations":[{"en":"a cup of coffee","vi":"một tách cà phê"},{"en":"black coffee","vi":"cà phê đen"},{"en":"coffee beans","vi":"hạt cà phê"},{"en":"instant coffee","vi":"cà phê hòa tan"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; khi gọi món, \"two coffees\" có nghĩa là hai tách cà phê.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shoe', 'en-a1-20', 'shoe', '/ʃuː/', 'A1', 'chiếc giày', 'n.', 'shoeless (adj.), shoemaker (n.)', NULL, 'Một đôi giày dùng "a pair of shoes"; "shoe" là danh từ đếm được.', 'There was a small stone inside my shoe.', NULL, 'Có một viên đá nhỏ bên trong chiếc giày của tôi.', '{"wordId":"shoe","ukIpa":"/ʃuː/","usIpa":"/ʃuː/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A covering for the foot, usually with a firm sole.","vi":"chiếc giày"}],"examples":[{"en":"There was a small stone inside my shoe.","vi":"Có một viên đá nhỏ bên trong chiếc giày của tôi.","audioKind":"ex"},{"en":"Comfortable shoes are essential for workers who spend most of their working day standing.","vi":"Những đôi giày thoải mái rất cần thiết đối với những người lao động phải đứng trong phần lớn thời gian làm việc.","audioKind":"ex2"}],"collocations":[{"en":"a pair of shoes","vi":"một đôi giày"},{"en":"running shoes","vi":"giày chạy bộ"},{"en":"put on your shoes","vi":"mang giày vào"}],"wordFamily":["shoeless (adj.)","shoemaker (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Một đôi giày dùng \"a pair of shoes\"; \"shoe\" là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_little', 'en-a1-20', 'little', '/ˈlɪtəl/', 'A1', 'nhỏ; nhỏ tuổi; rất ít; hầu như không có; ít; hơi', 'adj.', 'littleness (n.)', 'Đồng nghĩa: small, tiny · Trái nghĩa: big, much', 'little đi với danh từ không đếm được chỉ nghĩa hầu như không; a little chỉ có một ít.', 'A little bird landed on our kitchen windowsill.', NULL, 'Một chú chim nhỏ đậu trên bệ cửa sổ phòng bếp nhà chúng tôi.', '{"wordId":"little","ukIpa":"/ˈlɪtəl/","usIpa":"/ˈlɪtəl/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Small in size or young in age.","vi":"nhỏ; nhỏ tuổi"},{"pos":"det.","en":"Not much; almost no amount of something.","vi":"rất ít; hầu như không có"},{"pos":"adv.","en":"Only slightly or not very much.","vi":"ít; hơi"}],"examples":[{"en":"A little bird landed on our kitchen windowsill.","vi":"Một chú chim nhỏ đậu trên bệ cửa sổ phòng bếp nhà chúng tôi.","audioKind":"ex"},{"en":"Many rural schools have little access to digital resources, which can widen existing educational inequalities.","vi":"Nhiều trường học vùng nông thôn có rất ít điều kiện tiếp cận các nguồn tài nguyên số, điều này có thể làm gia tăng khoảng cách bất bình đẳng giáo dục hiện có.","audioKind":"ex2"}],"collocations":[{"en":"a little child","vi":"một đứa trẻ nhỏ"},{"en":"little time","vi":"ít thời gian"},{"en":"a little water","vi":"một chút nước"},{"en":"little by little","vi":"dần dần; từng chút một"}],"wordFamily":["littleness (n.)"],"synonyms":["small","tiny"],"antonyms":["big","much"],"tipVi":"little đi với danh từ không đếm được chỉ nghĩa hầu như không; a little chỉ có một ít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sweet', 'en-a1-20', 'sweet', '/swiːt/', 'A1', 'ngọt; tử tế; dịu dàng; chu đáo; kẹo', 'adj.', 'sweeten (v.), sweetness (n.), sweetener (n.), sweetly (adv.)', 'Đồng nghĩa: sugary, kind · Trái nghĩa: bitter', 'Kẹo trong tiếng Anh-Anh thường dùng sweets, trong tiếng Anh-Mỹ dùng candy.', 'These strawberries are sweet enough to eat without sugar.', NULL, 'Những quả dâu tây này đủ ngọt để ăn mà không cần đường.', '{"wordId":"sweet","ukIpa":"/swiːt/","usIpa":"/swiːt/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Having a taste like sugar or honey.","vi":"ngọt"},{"pos":"adj.","en":"Kind, gentle, or thoughtful.","vi":"tử tế; dịu dàng; chu đáo"},{"pos":"n.","en":"A small piece of sugary food eaten as a treat.","vi":"kẹo"}],"examples":[{"en":"These strawberries are sweet enough to eat without sugar.","vi":"Những quả dâu tây này đủ ngọt để ăn mà không cần đường.","audioKind":"ex"},{"en":"Reducing children''s consumption of sweet drinks may lower their risk of tooth decay and excessive weight gain.","vi":"Việc giảm tiêu thụ đồ uống ngọt ở trẻ em có thể làm giảm nguy cơ sâu răng và tăng cân quá mức.","audioKind":"ex2"}],"collocations":[{"en":"sweet taste","vi":"vị ngọt"},{"en":"sweet tooth","vi":"thích ăn đồ ngọt"},{"en":"sweet smile","vi":"nụ cười ngọt ngào"},{"en":"sweet drinks","vi":"đồ uống ngọt"}],"wordFamily":["sweeten (v.)","sweetness (n.)","sweetener (n.)","sweetly (adv.)"],"synonyms":["sugary","kind"],"antonyms":["bitter"],"tipVi":"Kẹo trong tiếng Anh-Anh thường dùng sweets, trong tiếng Anh-Mỹ dùng candy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_morning', 'en-a1-20', 'morning', '/ˈmɔːrnɪŋ/', 'A1', 'buổi sáng; sáng', 'n.', NULL, NULL, 'Phần lớn dùng "in the morning"; chỉ rõ ngày nào trong tuần dùng "on".', 'I open the curtains every morning and water my plants.', NULL, 'Tôi mở rèm cửa mỗi sáng và tưới cây.', '{"wordId":"morning","ukIpa":"/ˈmɔːnɪŋ/","usIpa":"/ˈmɔːrnɪŋ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The part of the day between midnight and noon","vi":"buổi sáng; sáng"}],"examples":[{"en":"I open the curtains every morning and water my plants.","vi":"Tôi mở rèm cửa mỗi sáng và tưới cây.","audioKind":"ex"},{"en":"Schools that start later in the morning may help teenagers get enough sleep and concentrate better.","vi":"Các trường học bắt đầu muộn hơn vào buổi sáng có thể giúp thanh thiếu niên ngủ đủ giấc và tập trung tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"early morning","vi":"sáng sớm"},{"en":"in the morning","vi":"vào buổi sáng"},{"en":"on Monday morning","vi":"vào sáng thứ Hai"},{"en":"every morning","vi":"mỗi buổi sáng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Phần lớn dùng \"in the morning\"; chỉ rõ ngày nào trong tuần dùng \"on\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outside', 'en-a1-20', 'outside', '/ˌaʊtˈsaɪd/', 'A1', 'ở bên ngoài; ra ngoài; bên ngoài; ngoài; ngoài trời; bề ngoài', 'adv.', 'outsider (n.)', 'Trái nghĩa: inside', 'Đi sau một địa điểm dùng giới từ "outside"; đứng độc lập đóng vai trò phó từ.', 'The children played outside while their parents prepared lunch.', NULL, 'Bọn trẻ chơi đùa ở bên ngoài trong lúc bố mẹ chuẩn bị bữa trưa.', '{"wordId":"outside","ukIpa":"/ˌaʊtˈsaɪd/","usIpa":"/ˌaʊtˈsaɪd/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"In or towards a place that is not inside.","vi":"ở bên ngoài; ra ngoài"},{"pos":"prep.","en":"Beyond the boundaries or limits of something.","vi":"bên ngoài; ngoài"},{"pos":"adj.","en":"Located on the outer part or coming from elsewhere.","vi":"ngoài trời; bề ngoài"}],"examples":[{"en":"The children played outside while their parents prepared lunch.","vi":"Bọn trẻ chơi đùa ở bên ngoài trong lúc bố mẹ chuẩn bị bữa trưa.","audioKind":"ex"},{"en":"Schools should provide opportunities for students to learn outside the classroom through practical activities and community projects.","vi":"Nhà trường nên tạo cơ hội cho học sinh học tập bên ngoài lớp học thông qua các hoạt động thực tế và dự án cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"go outside","vi":"đi ra ngoài"},{"en":"outside the classroom","vi":"bên ngoài lớp học"},{"en":"outside help","vi":"sự giúp đỡ từ bên ngoài"},{"en":"the outside world","vi":"thế giới bên ngoài"}],"wordFamily":["outsider (n.)"],"synonyms":[],"antonyms":["inside"],"tipVi":"Đi sau một địa điểm dùng giới từ \"outside\"; đứng độc lập đóng vai trò phó từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pasta', 'en-a1-20', 'pasta', '/ˈpɑːstə/', 'A1', 'mì Ý; các món mì ống', 'n.', NULL, NULL, 'Là danh từ không đếm được; một suất mì Ý có thể nói "a bowl of pasta".', 'We cooked pasta with fresh tomatoes and mushrooms.', NULL, 'Chúng tôi nấu món mì Ý với cà chua tươi và nấm.', '{"wordId":"pasta","ukIpa":"/ˈpæstə/","usIpa":"/ˈpɑːstə/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"food made from flour and water, shaped and usually boiled","vi":"mì Ý; các món mì ống"}],"examples":[{"en":"We cooked pasta with fresh tomatoes and mushrooms.","vi":"Chúng tôi nấu món mì Ý với cà chua tươi và nấm.","audioKind":"ex"},{"en":"School canteens can serve wholegrain pasta with vegetables to provide affordable meals with more fibre.","vi":"Căng-tin trường học có thể phục vụ mì ống làm từ ngũ cốc nguyên hạt kèm rau củ để cung cấp các bữa ăn vừa phải về giá cả lại dồi dào chất xơ.","audioKind":"ex2"}],"collocations":[{"en":"cook pasta","vi":"nấu mì Ý"},{"en":"pasta sauce","vi":"sốp mì Ý"},{"en":"fresh pasta","vi":"mì Ý tươi"},{"en":"wholegrain pasta","vi":"mì ống ngũ cốc nguyên hạt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được; một suất mì Ý có thể nói \"a bowl of pasta\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_black', 'en-a1-20', 'black', '/blæk/', 'A1', 'màu đen; đen; màu đen; da đen', 'adj.', 'blackness (n.), blacken (v.), blackish (adj.)', 'Trái nghĩa: white', 'Khi chỉ chủng tộc thường viết hoa chữ "Black"; tránh dùng danh từ số ít để gọi người.', 'She wore a black coat and bright yellow boots.', NULL, 'Cô ấy mặc một chiếc áo khoác màu đen và đi đôi bốt màu vàng rực.', '{"wordId":"black","ukIpa":"/blæk/","usIpa":"/blæk/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"having the darkest colour, like coal","vi":"màu đen; đen"},{"pos":"n.","en":"the darkest colour","vi":"màu đen"},{"pos":"adj.","en":"relating to people with ancestry from sub-Saharan Africa","vi":"da đen"}],"examples":[{"en":"She wore a black coat and bright yellow boots.","vi":"Cô ấy mặc một chiếc áo khoác màu đen và đi đôi bốt màu vàng rực.","audioKind":"ex"},{"en":"Black roofs absorb more sunlight than pale roofs, potentially increasing the energy needed for cooling.","vi":"Mái nhà màu đen hấp thụ nhiều ánh nắng hơn mái nhà màu sáng, có thể làm tăng lượng năng lượng cần dùng cho việc làm mát.","audioKind":"ex2"}],"collocations":[{"en":"black coffee","vi":"cà phê đen"},{"en":"black and white","vi":"đen trắng"},{"en":"turn black","vi":"chuyển sang màu đen"}],"wordFamily":["blackness (n.)","blacken (v.)","blackish (adj.)"],"synonyms":[],"antonyms":["white"],"tipVi":"Khi chỉ chủng tộc thường viết hoa chữ \"Black\"; tránh dùng danh từ số ít để gọi người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tell', 'en-a1-20', 'tell', '/tel/', 'A1', 'nói; kể; bảo; sai bảo; bảo; phân biệt; nhận biết', 'v.', 'teller (n.), retell (v.)', NULL, '"tell" thường đi thẳng với tân ngữ chỉ người; "say" khi đi với người thường cần có "to".', 'Please tell me what happened at school today.', NULL, 'Xin hãy kể cho tôi nghe chuyện gì đã xảy ra ở trường hôm nay.', '{"wordId":"tell","ukIpa":"/tel/","usIpa":"/tel/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"Give someone information or describe something in words.","vi":"nói; kể; bảo"},{"pos":"v.","en":"Instruct someone to do something.","vi":"sai bảo; bảo"},{"pos":"v.","en":"Recognise a difference or know something from available evidence.","vi":"phân biệt; nhận biết"}],"examples":[{"en":"Please tell me what happened at school today.","vi":"Xin hãy kể cho tôi nghe chuyện gì đã xảy ra ở trường hôm nay.","audioKind":"ex"},{"en":"Schools should tell parents how personal information about their children is collected and stored.","vi":"Nhà trường nên thông báo cho phụ huynh cách thức thông tin cá nhân của con cái họ được thu thập và lưu trữ.","audioKind":"ex2"}],"collocations":[{"en":"tell a story","vi":"kể chuyện"},{"en":"tell the truth","vi":"nói sự thật"},{"en":"tell someone to do something","vi":"bảo ai đó làm gì"},{"en":"tell the difference","vi":"phân biệt sự khác nhau"}],"wordFamily":["teller (n.)","retell (v.)"],"synonyms":[],"antonyms":[],"tipVi":"\"tell\" thường đi thẳng với tân ngữ chỉ người; \"say\" khi đi với người thường cần có \"to\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_below', 'en-a1-20', 'below', '/bɪˈloʊ/', 'A1', 'ở dưới; thấp hơn; ở phía dưới; phần dưới', 'prep.', NULL, 'Trái nghĩa: above', '"below" nhấn mạnh vị trí hoặc giá trị thấp hơn, không nhất thiết phải nằm ngay phía bên dưới.', 'Our cat sleeps on the shelf below the window.', NULL, 'Con mèo của chúng tôi ngủ trên kệ tủ nằm ngay dưới cửa sổ.', '{"wordId":"below","ukIpa":"/bɪˈləʊ/","usIpa":"/bɪˈloʊ/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"At a lower position, level, or amount than something.","vi":"ở dưới; thấp hơn"},{"pos":"adv.","en":"In a lower place or later in a piece of writing.","vi":"ở phía dưới; phần dưới"}],"examples":[{"en":"Our cat sleeps on the shelf below the window.","vi":"Con mèo của chúng tôi ngủ trên kệ tủ nằm ngay dưới cửa sổ.","audioKind":"ex"},{"en":"Households with incomes below the national average may struggle to afford adequate heating during winter.","vi":"Các hộ gia đình có mức thu nhập thấp hơn mức trung bình quốc gia có thể gặp khó khăn trong việc chi trả chi phí sưởi ấm đầy đủ vào mùa đông.","audioKind":"ex2"}],"collocations":[{"en":"below average","vi":"dưới mức trung bình"},{"en":"below sea level","vi":"dưới mực nước biển"},{"en":"below freezing","vi":"dưới độ đóng băng"}],"wordFamily":[],"synonyms":[],"antonyms":["above"],"tipVi":"\"below\" nhấn mạnh vị trí hoặc giá trị thấp hơn, không nhất thiết phải nằm ngay phía bên dưới.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_there', 'en-a1-20', 'there', '/ðer/', 'A1', 'ở đó; tại đó; đến đó; có (dùng trước động từ để chỉ sự tồn tại)', 'adv.', NULL, 'Trái nghĩa: here', 'there dùng để chỉ địa điểm hoặc mở đầu câu chỉ sự tồn tại; tránh nhầm lẫn với their.', 'Leave your muddy boots there, beside the back door.', NULL, 'Cứ để đôi bốt dính bùn của bạn ở đó, ngay cạnh cửa sau.', '{"wordId":"there","ukIpa":"/ðeə/","usIpa":"/ðer/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"In, at, or towards that place.","vi":"ở đó; tại đó; đến đó"},{"pos":"pron.","en":"Used before a verb to introduce something that exists.","vi":"có (dùng trước động từ để chỉ sự tồn tại)"}],"examples":[{"en":"Leave your muddy boots there, beside the back door.","vi":"Cứ để đôi bốt dính bùn của bạn ở đó, ngay cạnh cửa sau.","audioKind":"ex"},{"en":"There are several practical ways for cities to reduce waste without increasing household expenses.","vi":"Có một số cách thiết thực để các thành phố giảm thiểu rác thải mà không làm tăng chi phí sinh hoạt của hộ gia đình.","audioKind":"ex2"}],"collocations":[{"en":"over there","vi":"ở đằng kia"},{"en":"there is","vi":"có (dùng cho số ít)"},{"en":"there are","vi":"có (dùng cho số nhiều)"},{"en":"from there","vi":"từ đó"}],"wordFamily":[],"synonyms":[],"antonyms":["here"],"tipVi":"there dùng để chỉ địa điểm hoặc mở đầu câu chỉ sự tồn tại; tránh nhầm lẫn với their.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_face', 'en-a1-20', 'face', '/feɪs/', 'A1', 'mặt; khuôn mặt; đối mặt; đương đầu với; hướng về; quay mặt về', 'n.', 'facial (adj.), faceless (adj.)', NULL, 'Đối mặt với khó khăn có thể nói là face difficulties hoặc be faced with difficulties.', 'He washed his face before sitting down for breakfast.', NULL, 'Anh ấy rửa mặt trước khi ngồi xuống ăn bữa sáng.', '{"wordId":"face","ukIpa":"/feɪs/","usIpa":"/feɪs/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The front of the head, including eyes, nose, and mouth.","vi":"mặt; khuôn mặt"},{"pos":"v.","en":"To encounter or deal with a difficult situation.","vi":"đối mặt; đương đầu với"},{"pos":"v.","en":"To look or point in a particular direction.","vi":"hướng về; quay mặt về"}],"examples":[{"en":"He washed his face before sitting down for breakfast.","vi":"Anh ấy rửa mặt trước khi ngồi xuống ăn bữa sáng.","audioKind":"ex"},{"en":"Many coastal cities face increasing risks from flooding as sea levels rise and extreme weather becomes more frequent.","vi":"Nhiều thành phố ven biển đang phải đối mặt với rủi ro ngập lụt ngày càng tăng khi mực nước biển dâng cao và thời tiết cực đoan trở nên thường xuyên hơn.","audioKind":"ex2"}],"collocations":[{"en":"wash your face","vi":"rửa mặt"},{"en":"face a challenge","vi":"đối mặt với thách thức"},{"en":"face south","vi":"hướng về phía nam"},{"en":"face to face","vi":"đối mặt trực tiếp"}],"wordFamily":["facial (adj.)","faceless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Đối mặt với khó khăn có thể nói là face difficulties hoặc be faced with difficulties.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hot', 'en-a1-20', 'hot', '/hɑːt/', 'A1', 'nóng; có nhiệt độ cao; cay (vị làm bỏng rát miệng); được quan tâm; được bàn tán nhiều; sốt dẻo', 'adj.', 'hotly (adv.), hotness (n.)', 'Đồng nghĩa: heated · Trái nghĩa: cold', 'Khi nói về đồ ăn, từ này có thể chỉ "nóng" hoặc "cay", cần xét theo ngữ cảnh.', 'Be careful; the soup is still very hot.', NULL, 'Hãy cẩn thận, súp vẫn còn rất nóng.', '{"wordId":"hot","ukIpa":"/hɒt/","usIpa":"/hɑːt/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Having a high temperature.","vi":"nóng; có nhiệt độ cao"},{"pos":"adj.","en":"Having a strong taste that burns your mouth.","vi":"cay (vị làm bỏng rát miệng)"},{"pos":"adj.","en":"Attracting a lot of interest or discussion.","vi":"được quan tâm; được bàn tán nhiều; sốt dẻo"}],"examples":[{"en":"Be careful; the soup is still very hot.","vi":"Hãy cẩn thận, súp vẫn còn rất nóng.","audioKind":"ex"},{"en":"As summers become increasingly hot, cities need more shaded public spaces to protect residents from heat.","vi":"Khi mùa hè ngày càng trở nên oi bức, các thành phố cần nhiều không gian công bố có bóng râm hơn để bảo vệ người dân khỏi ảnh hưởng của nắng nóng.","audioKind":"ex2"}],"collocations":[{"en":"hot weather","vi":"thời tiết nóng"},{"en":"hot water","vi":"nước nóng"},{"en":"hot peppers","vi":"ớt cay"},{"en":"a hot topic","vi":"một chủ đề nóng"}],"wordFamily":["hotly (adv.)","hotness (n.)"],"synonyms":["heated"],"antonyms":["cold"],"tipVi":"Khi nói về đồ ăn, từ này có thể chỉ \"nóng\" hoặc \"cay\", cần xét theo ngữ cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blue', 'en-a1-20', 'blue', '/bluː/', 'A1', 'màu xanh da trời; buồn; u sầu; chán nản', 'adj.', 'bluish (adj.), blueness (n.)', NULL, '"Feel blue" diễn tả tâm trạng thấp thỏm, buồn bã; màu nhạt hơn dùng "light blue".', 'He wore a blue jacket to the picnic.', NULL, 'Anh ấy mặc một chiếc áo khoác màu xanh da trời đi dã ngoại.', '{"wordId":"blue","ukIpa":"/bluː/","usIpa":"/bluː/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"having the colour of a clear daytime sky","vi":"màu xanh da trời"},{"pos":"n.","en":"the colour of a clear daytime sky","vi":"màu xanh da trời"},{"pos":"adj.","en":"feeling sad or unhappy","vi":"buồn; u sầu; chán nản"}],"examples":[{"en":"He wore a blue jacket to the picnic.","vi":"Anh ấy mặc một chiếc áo khoác màu xanh da trời đi dã ngoại.","audioKind":"ex"},{"en":"Urban designers often use blue surfaces to create a sense of calm in busy public spaces.","vi":"Các nhà thiết kế đô thị thường sử dụng các bề mặt màu xanh dương để tạo cảm giác bình yên trong các không gian công cộng bận rộn.","audioKind":"ex2"}],"collocations":[{"en":"bright blue","vi":"xanh sáng"},{"en":"dark blue","vi":"xanh đậm"},{"en":"blue sky","vi":"bầu trời xanh"},{"en":"feel blue","vi":"cảm thấy buồn"}],"wordFamily":["bluish (adj.)","blueness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"\"Feel blue\" diễn tả tâm trạng thấp thỏm, buồn bã; màu nhạt hơn dùng \"light blue\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tonight', 'en-a1-20', 'tonight', '/təˈnaɪt/', 'A1', 'vào tối nay; trong đêm nay; buổi tối nay; đêm nay', 'adv.', NULL, NULL, 'Làm trạng ngữ chỉ thời gian thì dùng trực tiếp "tonight", không đi kèm giới từ phía trước.', 'We are making vegetable soup for dinner tonight.', NULL, 'Chúng tôi làm súp rau củ cho bữa tối nay.', '{"wordId":"tonight","ukIpa":"/təˈnaɪt/","usIpa":"/təˈnaɪt/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"during the evening or night of today","vi":"vào tối nay; trong đêm nay"},{"pos":"n.","en":"the evening or night of today","vi":"buổi tối nay; đêm nay"}],"examples":[{"en":"We are making vegetable soup for dinner tonight.","vi":"Chúng tôi làm súp rau củ cho bữa tối nay.","audioKind":"ex"},{"en":"Residents will meet tonight to discuss how public transport could better serve the local community.","vi":"Cư dân sẽ họp tối nay để thảo luận về cách hệ thống giao thông công cộng có thể phục vụ cộng đồng tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"tonight''s meeting","vi":"cuộc họp tối nay"},{"en":"late tonight","vi":"muộn tối nay"},{"en":"by tonight","vi":"trước tối nay"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Làm trạng ngữ chỉ thời gian thì dùng trực tiếp \"tonight\", không đi kèm giới từ phía trước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_february', 'en-a1-20', 'February', '/ˈfebrueri/', 'A1', 'tháng Hai', 'n.', NULL, NULL, 'Tên tháng phải viết hoa chữ cái đầu; dùng "in" trước tháng và "on" trước ngày cụ thể.', 'My sister starts her new job in February.', NULL, 'Chị tôi bắt đầu công việc mới vào tháng Hai.', '{"wordId":"february","ukIpa":"/ˈfebruəri/","usIpa":"/ˈfebrueri/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The second month of the year.","vi":"tháng Hai"}],"examples":[{"en":"My sister starts her new job in February.","vi":"Chị tôi bắt đầu công việc mới vào tháng Hai.","audioKind":"ex"},{"en":"The community centre will introduce additional evening classes in February to meet growing demand.","vi":"Trung tâm cộng đồng sẽ giới thiệu thêm các lớp học buổi tối vào tháng Hai để đáp ứng nhu cầu ngày càng tăng.","audioKind":"ex2"}],"collocations":[{"en":"in February","vi":"vào tháng Hai"},{"en":"early February","vi":"đầu tháng Hai"},{"en":"late February","vi":"cuối tháng Hai"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tên tháng phải viết hoa chữ cái đầu; dùng \"in\" trước tháng và \"on\" trước ngày cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lose', 'en-a1-20', 'lose', '/luːz/', 'A1', 'làm mất; đánh rơi; thất lạc; mất; suy giảm; ít đi; thua; thất bại', 'v.', 'loss (n.), lost (adj.), loser (n.)', 'Trái nghĩa: find, win', 'Dạng quá khứ và quá khứ phân từ đều là lost; đừng nhầm lẫn với loose.', 'I always lose my keys inside this enormous bag.', NULL, 'Tôi luôn làm mất chìa khóa trong chiếc túi xách to tướng này.', '{"wordId":"lose","ukIpa":"/luːz/","usIpa":"/luːz/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to become unable to find something you had","vi":"làm mất; đánh rơi; thất lạc"},{"pos":"v.","en":"to stop having something or have less of it","vi":"mất; suy giảm; ít đi"},{"pos":"v.","en":"to fail to win a game or competition","vi":"thua; thất bại"}],"examples":[{"en":"I always lose my keys inside this enormous bag.","vi":"Tôi luôn làm mất chìa khóa trong chiếc túi xách to tướng này.","audioKind":"ex"},{"en":"Small businesses may lose customers when major retailers offer similar products at significantly lower prices.","vi":"Các doanh nghiệp nhỏ có thể mất khách hàng khi các nhà bán lẻ lớn cung cấp sản phẩm tương tự với mức giá thấp hơn đáng kể.","audioKind":"ex2"}],"collocations":[{"en":"lose weight","vi":"giảm cân"},{"en":"lose touch","vi":"mất liên lạc"},{"en":"lose a match","vi":"thua một trận đấu"},{"en":"lose your temper","vi":"nổi giận"}],"wordFamily":["loss (n.)","lost (adj.)","loser (n.)"],"synonyms":[],"antonyms":["find","win"],"tipVi":"Dạng quá khứ và quá khứ phân từ đều là lost; đừng nhầm lẫn với loose.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_your', 'en-a1-20', 'your', '/jʊr/', 'A1', 'của bạn; của các bạn; của anh chị', 'det.', 'you (pron.), yours (pron.), yourself (pron.), yourselves (pron.)', NULL, 'your đứng trước danh từ; yours dùng độc lập; you''re có nghĩa là bạn là.', 'Please leave your shoes by the door before entering.', NULL, 'Vui lòng để giày của bạn ở ngoài cửa trước khi bước vào.', '{"wordId":"your","ukIpa":"/jɔː/","usIpa":"/jʊr/","cefr":"A1","topic":"daily","senses":[{"pos":"det.","en":"Belonging or relating to the person or people being addressed","vi":"của bạn; của các bạn; của anh chị"}],"examples":[{"en":"Please leave your shoes by the door before entering.","vi":"Vui lòng để giày của bạn ở ngoài cửa trước khi bước vào.","audioKind":"ex"},{"en":"Choosing a university near your home can reduce living expenses and make higher education more affordable.","vi":"Việc chọn một trường đại học gần nhà có thể giúp giảm chi phí sinh hoạt và làm cho giáo dục đại học trở nên vừa túi tiền hơn.","audioKind":"ex2"}],"collocations":[{"en":"your own","vi":"của chính bạn"},{"en":"your family","vi":"gia đình bạn"},{"en":"do your best","vi":"làm hết sức mình"}],"wordFamily":["you (pron.)","yours (pron.)","yourself (pron.)","yourselves (pron.)"],"synonyms":[],"antonyms":[],"tipVi":"your đứng trước danh từ; yours dùng độc lập; you''re có nghĩa là bạn là.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 28, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_20_1', 'en-a1-20', 'Cách dùng “soon” (adv.) — chẳng bao lâu; sớm; nhanh chóng', 'as soon as possible  ·  soon after  ·  too soon', 'Khi as soon as dẫn dắt mệnh đề chỉ thời gian trong tương lai, người ta thường dùng thì hiện tại đơn.', 'Đồng nghĩa: shortly', '[{"hanzi":"Dinner will be ready soon, so wash your hands.","pinyin":"","meaning":"Bữa tối sắp xong rồi, hãy đi rửa tay đi."},{"hanzi":"Unless cities improve public transport soon, traffic congestion is likely to become increasingly severe.","pinyin":"","meaning":"Trừ khi các thành phố cải thiện giao thông công cộng sớm, tình trạng ùn tắc giao thông có xu hướng ngày càng trở nên nghiêm trọng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_20_2', 'en-a1-20', 'Cách dùng “by” (prep.) — bởi', 'by bus  ·  by doing something  ·  by the end of', 'by chỉ mốc thời gian hoàn thành; until chỉ hành động hoặc trạng thái kéo dài đến một thời điểm.', NULL, '[{"hanzi":"This wooden bowl was made by my grandfather.","pinyin":"","meaning":"Chiếc bát gỗ này được làm bởi ông tôi."},{"hanzi":"Urban air quality can be improved by expanding public transport and encouraging residents to cycle more often.","pinyin":"","meaning":"Chất lượng không khí đô thị có thể được cải thiện bằng cách mở rộng giao thông công cộng và khuyến khích người dân đi xe đạp nhiều hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_20_3', 'en-a1-20', 'Cách dùng “wide” (adj.) — adj. rộng; rộng lớn', 'a wide road  ·  a wide range of  ·  wide open', 'wide chỉ mức độ mở rộng hoặc khoảng cách; widely thường dùng với ý nghĩa rộng rãi, phổ biến.', 'Họ từ (Word Family): width (n.), widen (v.), widely (adv.) | Đồng nghĩa: broad | Trái nghĩa: narrow', '[{"hanzi":"The sofa will not fit through this wide doorway.","pinyin":"","meaning":"Chiếc ghế sofa sẽ không thể lọt qua khung cửa rộng này."},{"hanzi":"Universities should offer a wide range of courses to meet students'' different interests and career goals.","pinyin":"","meaning":"Các trường đại học nên cung cấp nhiều loại khóa học phong phú để đáp ứng các sở thích và mục tiêu nghề nghiệp khác nhau của sinh viên."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_20_4', 'en-a1-20', 'Cách dùng “below” (prep.) — ở dưới; thấp hơn', 'below average  ·  below sea level  ·  below freezing', '"below" nhấn mạnh vị trí hoặc giá trị thấp hơn, không nhất thiết phải nằm ngay phía bên dưới.', 'Trái nghĩa: above', '[{"hanzi":"Our cat sleeps on the shelf below the window.","pinyin":"","meaning":"Con mèo của chúng tôi ngủ trên kệ tủ nằm ngay dưới cửa sổ."},{"hanzi":"Households with incomes below the national average may struggle to afford adequate heating during winter.","pinyin":"","meaning":"Các hộ gia đình có mức thu nhập thấp hơn mức trung bình quốc gia có thể gặp khó khăn trong việc chi trả chi phí sưởi ấm đầy đủ vào mùa đông."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
