INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_20_1_1', 'en-a1-20', 'ten_20_1', 'listening', 'listening', 'Dinner will be ready soon, so wash your hands.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bữa tối sắp xong rồi, hãy đi rửa tay đi.","Chiếc ghế sofa sẽ không thể lọt qua khung cửa rộng này.","Chúng tôi thường đi dạo ngắn sau bữa tối.","Chiếc bát gỗ này được làm bởi ông tôi."]'::jsonb, 0, 'Dinner will be ready soon, so wash your hands. → Bữa tối sắp xong rồi, hãy đi rửa tay đi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
