INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_20_1_3', 'en-a1-20', 'ten_20_1', 'listening', 'listening', 'We usually take a short walk after dinner.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi thường đi dạo ngắn sau bữa tối.","Chúng tôi ngồi quây quần bên đống lửa và ngắm những vì sao.","Bữa tối sắp xong rồi, hãy đi rửa tay đi.","Chiếc ghế sofa sẽ không thể lọt qua khung cửa rộng này."]'::jsonb, 0, 'We usually take a short walk after dinner. → Chúng tôi thường đi dạo ngắn sau bữa tối.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_20_2', 'en-a1-20', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_20_2_1', 'ten_20_2', 'soon', 'Unless cities improve public transport soon, traffic congestion is likely to become increasingly severe.', 'Unless cities improve public transport soon, traffic congestion is likely to become increasingly severe.', '/suːn/', 'Trừ khi các thành phố cải thiện giao thông công cộng sớm, tình trạng ùn tắc giao thông có xu hướng ngày càng trở nên nghiêm trọng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_20_2_2', 'ten_20_2', 'umbrella', 'An umbrella organisation can help small charities coordinate their activities and share resources more effectively.', 'An umbrella organisation can help small charities coordinate their activities and share resources more effectively.', '/ʌmˈbrelə/', 'Một tổ chức mái nhà chung có thể giúp các tổ chức từ thiện nhỏ điều phối hoạt động và chia sẻ nguồn lực hiệu quả hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_20_2_3', 'ten_20_2', 'after', 'After cities improve public transport, more residents may choose to leave their cars at home.', 'After cities improve public transport, more residents may choose to leave their cars at home.', '/ˈæftər/', 'Sau khi các thành phố cải thiện hệ thống giao thông công cộng, nhiều cư dân có thể chọn cách để xe ở nhà.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_20_2_4', 'ten_20_2', 'around', 'Planting trees around school buildings can provide shade and reduce indoor temperatures during hot weather.', 'Planting trees around school buildings can provide shade and reduce indoor temperatures during hot weather.', '/əˈraʊnd/', 'Trồng cây xanh xung quanh các tòa nhà trường học có thể tạo bóng râm và giảm nhiệt độ trong nhà khi thời tiết oi bức.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_20_2_5', 'ten_20_2', 'by', 'Urban air quality can be improved by expanding public transport and encouraging residents to cycle more often.', 'Urban air quality can be improved by expanding public transport and encouraging residents to cycle more often.', '/baɪ/', 'Chất lượng không khí đô thị có thể được cải thiện bằng cách mở rộng giao thông công cộng và khuyến khích người dân đi xe đạp nhiều hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_20_2_6', 'ten_20_2', 'smell', 'A reduced sense of smell can affect appetite and make it harder to detect spoiled food.', 'A reduced sense of smell can affect appetite and make it harder to detect spoiled food.', '/smel/', 'Khứu giác suy giảm có thể ảnh hưởng đến vị giác và khiến việc phát hiện thực phẩm bị hỏng trở nên khó khăn hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_20_2_1', 'en-a1-20', 'ten_20_2', 'listening', 'listening', 'Unless cities improve public transport soon, traffic congestion is likely to become increasingly severe.', NULL, 'Trong câu vừa nghe, từ “soon” mang nghĩa nào sau đây?', '["ánh sáng; đèn","áo khoác ngắn; áo vét-tông","trở thành; trở nên","chẳng bao lâu; sớm; nhanh chóng"]'::jsonb, 3, '“soon” (/suːn/): chẳng bao lâu; sớm; nhanh chóng. Câu đầy đủ: Unless cities improve public transport soon, traffic congestion is likely to become increasingly severe.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_20_2_2', 'en-a1-20', 'ten_20_2', 'listening', 'listening', 'An umbrella organisation can help small charities coordinate their activities and share resources more effectively.', NULL, 'Trong câu vừa nghe, từ “umbrella” mang nghĩa nào sau đây?', '["bay","tiệm sách; hiệu sách","tuyết","cái ô; cái dù"]'::jsonb, 3, '“umbrella” (/ʌmˈbrelə/): cái ô; cái dù. Câu đầy đủ: An umbrella organisation can help small charities coordinate their activities and share resources more effectively.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
