INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_20_2', 'en-a1-20', NULL, 'comprehensive_test', 'listening', 'We shared an umbrella on the walk home.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi thường đi dạo ngắn sau bữa tối.","Tay tôi bị lạnh nên tôi đã đeo găng tay vào.","Cứ để đôi bốt dính bùn của bạn ở đó, ngay cạnh cửa sau.","Chúng tôi cùng che chung một chiếc ô trên quãng đường đi bộ về nhà."]'::jsonb, 3, 'We shared an umbrella on the walk home. → Chúng tôi cùng che chung một chiếc ô trên quãng đường đi bộ về nhà.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
