INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_20_4', 'en-a1-20', NULL, 'comprehensive_test', 'listening', 'We sat around the fire and watched the stars.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc ghế sofa sẽ không thể lọt qua khung cửa rộng này.","Tôi uống cà phê sữa trước khi đi làm.","Chúng tôi ngồi quây quần bên đống lửa và ngắm những vì sao.","Tôi mở rèm cửa mỗi sáng và tưới cây."]'::jsonb, 2, 'We sat around the fire and watched the stars. → Chúng tôi ngồi quây quần bên đống lửa và ngắm những vì sao.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
