INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_20_6', 'en-a1-20', NULL, 'comprehensive_test', 'listening', 'The smell of fresh bread filled our kitchen.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi uống cà phê sữa trước khi đi làm.","Mùi bánh mỳ tươi lan tỏa khắp căn bếp của chúng tôi.","Tôi mở rèm cửa mỗi sáng và tưới cây.","Chị tôi bắt đầu công việc mới vào tháng Hai."]'::jsonb, 1, 'The smell of fresh bread filled our kitchen. → Mùi bánh mỳ tươi lan tỏa khắp căn bếp của chúng tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
