INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_20_8', 'en-a1-20', NULL, 'comprehensive_test', 'listening', 'The sofa will not fit through this wide doorway.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cứ để đôi bốt dính bùn của bạn ở đó, ngay cạnh cửa sau.","Chiếc ghế sofa sẽ không thể lọt qua khung cửa rộng này.","Vui lòng để giày của bạn ở ngoài cửa trước khi bước vào.","Tôi luôn làm mất chìa khóa trong chiếc túi xách to tướng này."]'::jsonb, 1, 'The sofa will not fit through this wide doorway. → Chiếc ghế sofa sẽ không thể lọt qua khung cửa rộng này.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
