INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_20_18', 'en-a1-20', NULL, 'comprehensive_test', 'reading', NULL, 'Unless cities improve public transport soon, traffic congestion is likely to become increasingly severe.', 'Dựa vào câu trên, từ “soon” có nghĩa phù hợp nhất là gì?', '["tàu hỏa; tàu điện","video; đoạn ghi hình ảnh chuyển động, thường có kèm âm thanh","chẳng bao lâu; sớm; nhanh chóng","thư giãn; nghỉ ngơi"]'::jsonb, 2, 'soon: chẳng bao lâu; sớm; nhanh chóng. Dịch cả câu: Trừ khi các thành phố cải thiện giao thông công cộng sớm, tình trạng ùn tắc giao thông có xu hướng ngày càng trở nên nghiêm trọng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_20_19', 'en-a1-20', NULL, 'comprehensive_test', 'reading', NULL, 'An umbrella organisation can help small charities coordinate their activities and share resources more effectively.', 'Dựa vào câu trên, từ “umbrella” có nghĩa phù hợp nhất là gì?', '["cái ô; cái dù","màu đỏ; có màu đỏ","vùng; khu vực; địa bàn","phòng tắm; phòng vệ sinh"]'::jsonb, 0, 'umbrella: cái ô; cái dù; mang tính tổng hợp; bao quát. Dịch cả câu: Một tổ chức mái nhà chung có thể giúp các tổ chức từ thiện nhỏ điều phối hoạt động và chia sẻ nguồn lực hiệu quả hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_20_20', 'en-a1-20', NULL, 'comprehensive_test', 'reading', NULL, 'After cities improve public transport, more residents may choose to leave their cars at home.', 'Dựa vào câu trên, từ “after” có nghĩa phù hợp nhất là gì?', '["cuối tuần","sau; sau khi","mặc; đeo; đội; mang","không khí"]'::jsonb, 1, 'after: sau; sau khi; sau khi; sau; đằng sau; đuổi theo. Dịch cả câu: Sau khi các thành phố cải thiện hệ thống giao thông công cộng, nhiều cư dân có thể chọn cách để xe ở nhà.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_20_21', 'en-a1-20', NULL, 'comprehensive_test', 'reading', NULL, 'Planting trees around school buildings can provide shade and reduce indoor temperatures during hot weather.', 'Dựa vào câu trên, từ “around” có nghĩa phù hợp nhất là gì?', '["xung quanh; vòng quanh","mùa đông","con voi","thư giãn; nghỉ ngơi"]'::jsonb, 0, 'around: xung quanh; vòng quanh; khoảng; xấp xỉ; quanh đây; khắp nơi. Dịch cả câu: Trồng cây xanh xung quanh các tòa nhà trường học có thể tạo bóng râm và giảm nhiệt độ trong nhà khi thời tiết oi bức.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_20_22', 'en-a1-20', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tháng Hai”', '["with","phone","February","wife"]'::jsonb, 2, 'tháng Hai → February (/ˈfebrueri/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_20_23', 'en-a1-20', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “làm mất; đánh rơi; thất lạc”', '["favorite","lose","egg","call"]'::jsonb, 1, 'làm mất; đánh rơi; thất lạc → lose (/luːz/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_20_24', 'en-a1-20', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “của bạn; của các bạn; của anh chị”', '["your","juice","class","big"]'::jsonb, 0, 'của bạn; của các bạn; của anh chị → your (/jʊr/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-21', 'en', 'Bài 21: Đời sống hằng ngày (6) - CEFR A1', 'CEFR A1', 'A1 · Đời sống', '28 từ vựng Tiếng Anh CEFR A1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1021, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_break', 'en-a1-21', 'break', '/breɪk/', 'A1', 'làm vỡ; làm gãy; làm hỏng; giờ giải lao; khoảng nghỉ; vi phạm; làm trái', 'v.', 'broken (adj.), breakable (adj.), unbreakable (adj.), breakage (n.)', 'Đồng nghĩa: shatter, pause · Trái nghĩa: repair', 'Biến đổi động từ là break—broke—broken; nghỉ ngơi dùng take a break.', 'Be careful not to break that glass bowl.', NULL, 'Cẩn thận kẻo làm vỡ cái bát thủy tinh đó.', '{"wordId":"break","ukIpa":"/breɪk/","usIpa":"/breɪk/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To separate into pieces or damage something so it stops working.","vi":"làm vỡ; làm gãy; làm hỏng"},{"pos":"n.","en":"A short period when an activity stops.","vi":"giờ giải lao; khoảng nghỉ"},{"pos":"v.","en":"To fail to obey a rule or keep a promise.","vi":"vi phạm; làm trái"}],"examples":[{"en":"Be careful not to break that glass bowl.","vi":"Cẩn thận kẻo làm vỡ cái bát thủy tinh đó.","audioKind":"ex"},{"en":"Regular breaks during study sessions may improve concentration and help students retain new information.","vi":"Việc nghỉ giải lao định kỳ trong các buổi học có thể cải thiện sự tập trung và giúp học sinh ghi nhớ kiến thức mới.","audioKind":"ex2"}],"collocations":[{"en":"take a break","vi":"nghỉ giải lao"},{"en":"break the law","vi":"phạm pháp"},{"en":"break a promise","vi":"thất hứa"},{"en":"break a record","vi":"phá vỡ kỷ lục"}],"wordFamily":["broken (adj.)","breakable (adj.)","unbreakable (adj.)","breakage (n.)"],"synonyms":["shatter","pause"],"antonyms":["repair"],"tipVi":"Biến đổi động từ là break—broke—broken; nghỉ ngơi dùng take a break.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_egg', 'en-a1-21', 'egg', '/eɡ/', 'A1', 'trứng; tế bào trứng; noãn', 'n.', 'eggshell (n.)', NULL, 'scrambled eggs chỉ trứng ốc/trứng bác; egg white chỉ lòng trắng trứng.', 'She cracked an egg into the hot frying pan.', NULL, 'Cô ấy đập một quả trứng vào chiếc chảo rán nóng.', '{"wordId":"egg","ukIpa":"/eɡ/","usIpa":"/eɡ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a rounded object laid by female birds and some other animals","vi":"trứng"},{"pos":"n.","en":"a female reproductive cell that can develop after fertilisation","vi":"tế bào trứng; noãn"}],"examples":[{"en":"She cracked an egg into the hot frying pan.","vi":"Cô ấy đập một quả trứng vào chiếc chảo rán nóng.","audioKind":"ex"},{"en":"Eggs provide an affordable source of protein and can form part of a balanced diet.","vi":"Trứng cung cấp nguồn protein giá cả phải chăng và có thể là một phần trong chế độ ăn uống cân bằng.","audioKind":"ex2"}],"collocations":[{"en":"boiled egg","vi":"trứng luộc"},{"en":"lay eggs","vi":"đẻ trứng"},{"en":"egg yolk","vi":"lòng đỏ trứng"},{"en":"egg cell","vi":"tế bào trứng"}],"wordFamily":["eggshell (n.)"],"synonyms":[],"antonyms":[],"tipVi":"scrambled eggs chỉ trứng ốc/trứng bác; egg white chỉ lòng trắng trứng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bookshop', 'en-a1-21', 'bookshop', '/ˈbʊkʃɑːp/', 'A1', 'tiệm sách; hiệu sách', 'n.', 'book (n.), bookseller (n.), bookselling (n.)', 'Đồng nghĩa: bookstore', 'bookshop thường dùng trong tiếng Anh-Anh, tiếng Anh-Mỹ thường dùng bookstore.', 'We found a tiny bookshop beside the railway station.', NULL, 'Chúng tôi tìm thấy một hiệu sách nhỏ xíu bên cạnh nhà ga xe lửa.', '{"wordId":"bookshop","ukIpa":"/ˈbʊkʃɒp/","usIpa":"/ˈbʊkʃɑːp/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a shop where books are sold","vi":"tiệm sách; hiệu sách"}],"examples":[{"en":"We found a tiny bookshop beside the railway station.","vi":"Chúng tôi tìm thấy một hiệu sách nhỏ xíu bên cạnh nhà ga xe lửa.","audioKind":"ex"},{"en":"An independent bookshop can strengthen local cultural life by hosting reading groups and supporting emerging writers.","vi":"Một hiệu sách độc lập có thể củng cố đời sống văn hóa địa phương bằng cách tổ chức các câu lạc bộ đọc sách và hỗ trợ các nhà văn mới nổi.","audioKind":"ex2"}],"collocations":[{"en":"independent bookshop","vi":"hiệu sách độc lập"},{"en":"second-hand bookshop","vi":"tiệm sách cũ"},{"en":"local bookshop","vi":"hiệu sách địa phương"}],"wordFamily":["book (n.)","bookseller (n.)","bookselling (n.)"],"synonyms":["bookstore"],"antonyms":[],"tipVi":"bookshop thường dùng trong tiếng Anh-Anh, tiếng Anh-Mỹ thường dùng bookstore.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_year', 'en-a1-21', 'year', '/jɪr/', 'A1', 'năm; năm học; năm công tác', 'n.', 'yearly (adj.), yearly (adv.)', NULL, 'Trước các cụm chỉ thời gian như last year không dùng giới từ; diễn tả tuổi dùng years old.', 'We moved into this flat almost a year ago.', NULL, 'Chúng tôi chuyển đến căn hộ này gần một năm trước.', '{"wordId":"year","ukIpa":"/jɪə/","usIpa":"/jɪr/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A period of twelve months","vi":"năm"},{"pos":"n.","en":"An annual period organised for education, business, or another purpose","vi":"năm học; năm công tác"}],"examples":[{"en":"We moved into this flat almost a year ago.","vi":"Chúng tôi chuyển đến căn hộ này gần một năm trước.","audioKind":"ex"},{"en":"A gap year can give students valuable work experience before they begin university studies.","vi":"Một năm nghỉ trải nghiệm (gap year) có thể mang lại cho học sinh những kinh nghiệm làm việc quý giá trước khi bắt đầu bậc học đại học.","audioKind":"ex2"}],"collocations":[{"en":"academic year","vi":"năm học"},{"en":"every year","vi":"mỗi năm"},{"en":"all year round","vi":"quanh năm"},{"en":"gap year","vi":"năm trải nghiệm trước đại học"}],"wordFamily":["yearly (adj.)","yearly (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Trước các cụm chỉ thời gian như last year không dùng giới từ; diễn tả tuổi dùng years old.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_free', 'en-a1-21', 'free', '/friː/', 'A1', 'miễn phí; tự do; không bị ràng buộc; giải phóng; làm cho tự do', 'adj.', 'freedom (n.), freely (adv.)', NULL, 'be free to do thể hiện sự tự do làm gì; for free có nghĩa là miễn phí.', 'The café offers free biscuits with every hot drink.', NULL, 'Quán cà phê có phục vụ bánh quy miễn phí với mỗi ly đồ uống nóng.', '{"wordId":"free","ukIpa":"/friː/","usIpa":"/friː/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Costing no money.","vi":"miễn phí"},{"pos":"adj.","en":"Able to act or move without being controlled or restricted.","vi":"tự do; không bị ràng buộc"},{"pos":"v.","en":"To release someone or something from control or confinement.","vi":"giải phóng; làm cho tự do"}],"examples":[{"en":"The café offers free biscuits with every hot drink.","vi":"Quán cà phê có phục vụ bánh quy miễn phí với mỗi ly đồ uống nóng.","audioKind":"ex"},{"en":"Providing free public transport could reduce traffic congestion and improve access to employment for disadvantaged residents.","vi":"Việc cung cấp giao thông công cộng miễn phí có thể làm giảm ùn tắc giao thông và cải thiện khả năng tiếp cận việc làm cho cư dân có hoàn cảnh khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"free admission","vi":"vào cửa miễn phí"},{"en":"free of charge","vi":"miễn phí"},{"en":"free speech","vi":"tự do ngôn luận"},{"en":"free someone from","vi":"giải thoát ai khỏi"}],"wordFamily":["freedom (n.)","freely (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"be free to do thể hiện sự tự do làm gì; for free có nghĩa là miễn phí.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shop', 'en-a1-21', 'shop', '/ʃɑːp/', 'A1', 'cửa hàng; tiệm; mua sắm; đi mua hàng', 'n.', 'shopping (n.), shopper (n.), shopkeeper (n.)', 'Đồng nghĩa: store', 'Mua loại hàng hóa gì dùng shop for; nói chung chung đi mua sắm dùng go shopping.', 'The little shop near our house sells fresh bread.', NULL, 'Cửa hàng nhỏ gần nhà chúng tôi bán bánh mì tươi.', '{"wordId":"shop","ukIpa":"/ʃɒp/","usIpa":"/ʃɑːp/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A place where people buy goods or services.","vi":"cửa hàng; tiệm"},{"pos":"v.","en":"To visit stores or websites to look for and buy things.","vi":"mua sắm; đi mua hàng"}],"examples":[{"en":"The little shop near our house sells fresh bread.","vi":"Cửa hàng nhỏ gần nhà chúng tôi bán bánh mì tươi.","audioKind":"ex"},{"en":"Independent shops can strengthen local economies by creating jobs and keeping spending within the community.","vi":"Các cửa hàng độc lập có thể củng cố nền kinh tế địa phương bằng cách tạo ra việc làm và giữ lại nguồn chi tiêu trong cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"local shop","vi":"cửa hàng địa phương"},{"en":"shop window","vi":"cửa sổ trưng bày cửa hàng"},{"en":"shop for clothes","vi":"mua sắm quần áo"},{"en":"shop around","vi":"khảo giá; so sánh giá cả"}],"wordFamily":["shopping (n.)","shopper (n.)","shopkeeper (n.)"],"synonyms":["store"],"antonyms":[],"tipVi":"Mua loại hàng hóa gì dùng shop for; nói chung chung đi mua sắm dùng go shopping.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_weekend', 'en-a1-21', 'weekend', '/ˈwiːkend/', 'A1', 'cuối tuần', 'n.', NULL, NULL, 'Tiếng Anh - Anh thường dùng "at the weekend", còn tiếng Anh - Mỹ dùng "on the weekend".', 'We usually visit the farmers'' market at the weekend.', NULL, 'Chúng tôi thường ghé thăm chợ nông sản vào cuối tuần.', '{"wordId":"weekend","ukIpa":"/ˌwiːkˈend/","usIpa":"/ˈwiːkend/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"Saturday and Sunday, often a time away from work.","vi":"cuối tuần"}],"examples":[{"en":"We usually visit the farmers'' market at the weekend.","vi":"Chúng tôi thường ghé thăm chợ nông sản vào cuối tuần.","audioKind":"ex"},{"en":"Affordable weekend activities can encourage families to spend more time together in their local communities.","vi":"Các hoạt động cuối tuần giá cả phải chăng có thể khuyến khích các gia đình dành nhiều thời gian bên nhau hơn tại cộng đồng địa phương của họ.","audioKind":"ex2"}],"collocations":[{"en":"at the weekend","vi":"vào cuối tuần (tiếng Anh - Anh)"},{"en":"on the weekend","vi":"vào cuối tuần (tiếng Anh - Mỹ)"},{"en":"a long weekend","vi":"kỳ nghỉ cuối tuần kéo dài"},{"en":"weekend break","vi":"chuyến nghỉ dưỡng ngắn cuối tuần"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Anh - Anh thường dùng \"at the weekend\", còn tiếng Anh - Mỹ dùng \"on the weekend\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sweater', 'en-a1-21', 'sweater', '/ˈswetər/', 'A1', 'áo len; áo chui đầu bằng len', 'n.', NULL, 'Đồng nghĩa: jumper, pullover', 'Tiếng Anh - Anh cũng hay dùng "jumper"; còn "sweatshirt" chỉ áo nỉ thể thao.', 'I pulled on a warm sweater before going outside.', NULL, 'Tôi mặc vội chiếc áo len ấm áp trước khi bước ra ngoài.', '{"wordId":"sweater","ukIpa":"/ˈswetə/","usIpa":"/ˈswetər/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A knitted garment worn over the upper body for warmth.","vi":"áo len; áo chui đầu bằng len"}],"examples":[{"en":"I pulled on a warm sweater before going outside.","vi":"Tôi mặc vội chiếc áo len ấm áp trước khi bước ra ngoài.","audioKind":"ex"},{"en":"Choosing a durable wool sweater rather than several cheap alternatives can reduce clothing waste over time.","vi":"Việc chọn một chiếc áo len bền thay vì mua nhiều lựa chọn giá rẻ khác có thể giúp giảm thiểu rác thải thời trang về lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"wool sweater","vi":"áo len lông cừu"},{"en":"knitted sweater","vi":"áo len dệt kim"},{"en":"thick sweater","vi":"áo len dày"}],"wordFamily":[],"synonyms":["jumper","pullover"],"antonyms":[],"tipVi":"Tiếng Anh - Anh cũng hay dùng \"jumper\"; còn \"sweatshirt\" chỉ áo nỉ thể thao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mother', 'en-a1-21', 'mother', '/ˈmʌðər/', 'A1', 'mẹ; má; chăm sóc như mẹ', 'n.', 'motherhood (n.), motherly (adj.)', 'Đồng nghĩa: mum, mom', 'Trong văn nói tiếng Anh-Anh thường dùng "mum", còn tiếng Anh-Mỹ thường dùng "mom".', 'My mother taught me how to ride a bicycle.', NULL, 'Mẹ tôi đã dạy tôi cách đi xe đạp.', '{"wordId":"mother","ukIpa":"/ˈmʌðə/","usIpa":"/ˈmʌðər/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A female parent.","vi":"mẹ; má"},{"pos":"v.","en":"Care for someone protectively, as a mother would.","vi":"chăm sóc như mẹ"}],"examples":[{"en":"My mother taught me how to ride a bicycle.","vi":"Mẹ tôi đã dạy tôi cách đi xe đạp.","audioKind":"ex"},{"en":"Affordable childcare can help a mother return to work without placing excessive pressure on the family budget.","vi":"Dịch vụ chăm sóc trẻ em có giá cả phải chăng có thể giúp người mẹ quay trở lại làm việc mà không gây áp lực quá lớn lên ngân sách gia đình.","audioKind":"ex2"}],"collocations":[{"en":"working mother","vi":"bà mẹ đi làm"},{"en":"single mother","vi":"mẹ đơn thân"},{"en":"expectant mother","vi":"bà bầu; mẹ bầu"},{"en":"mother tongue","vi":"tiếng mẹ đẻ"}],"wordFamily":["motherhood (n.)","motherly (adj.)"],"synonyms":["mum","mom"],"antonyms":[],"tipVi":"Trong văn nói tiếng Anh-Anh thường dùng \"mum\", còn tiếng Anh-Mỹ thường dùng \"mom\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_play', 'en-a1-21', 'play', '/pleɪ/', 'A1', 'chơi; tham gia trò chơi hoặc thể thao; chơi (nhạc cụ); phát (nhạc); đóng vai; vở kịch; kịch bản', 'v.', 'player (n.), playful (adj.), playfully (adv.), playfulness (n.)', NULL, 'Trước tên các môn thể thao bóng thường không dùng mạo từ; trước tên nhạc cụ thường dùng "the".', 'The children played with wooden blocks on the floor.', NULL, 'Lũ trẻ chơi với những khối gỗ trên sàn nhà.', '{"wordId":"play","ukIpa":"/pleɪ/","usIpa":"/pleɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"Enjoy an activity or take part in a game","vi":"chơi; tham gia trò chơi hoặc thể thao"},{"pos":"v.","en":"Perform music or a role, or make a recording run","vi":"chơi (nhạc cụ); phát (nhạc); đóng vai"},{"pos":"n.","en":"A story written for actors to perform","vi":"vở kịch; kịch bản"}],"examples":[{"en":"The children played with wooden blocks on the floor.","vi":"Lũ trẻ chơi với những khối gỗ trên sàn nhà.","audioKind":"ex"},{"en":"Schools should provide safe outdoor spaces where children can play and develop essential social skills.","vi":"Các trường học nên cung cấp không gian ngoài trời an toàn để trẻ em có thể vui chơi và phát triển các kỹ năng xã hội thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"play football","vi":"chơi bóng đá"},{"en":"play the piano","vi":"chơi đàn piano"},{"en":"play a role in","vi":"đóng vai trò trong"},{"en":"put on a play","vi":"công diễn một vở kịch"}],"wordFamily":["player (n.)","playful (adj.)","playfully (adv.)","playfulness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trước tên các môn thể thao bóng thường không dùng mạo từ; trước tên nhạc cụ thường dùng \"the\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_different', 'en-a1-21', 'different', '/ˈdɪfrənt/', 'A1', 'khác nhau; không giống nhau; khác nhau; đa dạng', 'adj.', 'difference (n.), differ (v.), differently (adv.), differentiate (v.)', 'Đồng nghĩa: dissimilar, distinct · Trái nghĩa: same, identical', 'Diễn tả sự khác biệt thường dùng "different from", rất phù hợp trong văn viết trang trọng.', 'These gloves look similar, but their sizes are different.', NULL, 'Đôi găng tay này trông giống nhau, nhưng kích cỡ của chúng lại khác nhau.', '{"wordId":"different","ukIpa":"/ˈdɪfrənt/","usIpa":"/ˈdɪfrənt/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"not the same as someone or something else","vi":"khác nhau; không giống nhau"},{"pos":"adj.","en":"used to describe several separate people, things, or types","vi":"khác nhau; đa dạng"}],"examples":[{"en":"These gloves look similar, but their sizes are different.","vi":"Đôi găng tay này trông giống nhau, nhưng kích cỡ của chúng lại khác nhau.","audioKind":"ex"},{"en":"Students from different cultural backgrounds can contribute valuable perspectives to classroom discussions about global issues.","vi":"Sinh viên đến từ các nền văn hóa khác nhau có thể đóng góp những góc nhìn quý giá cho các cuộc thảo luận trên lớp về các vấn đề toàn cầu.","audioKind":"ex2"}],"collocations":[{"en":"different from","vi":"khác với"},{"en":"different perspectives","vi":"những góc nhìn khác nhau"},{"en":"completely different","vi":"hoàn toàn khác biệt"}],"wordFamily":["difference (n.)","differ (v.)","differently (adv.)","differentiate (v.)"],"synonyms":["dissimilar","distinct"],"antonyms":["same","identical"],"tipVi":"Diễn tả sự khác biệt thường dùng \"different from\", rất phù hợp trong văn viết trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pool', 'en-a1-21', 'pool', '/puːl/', 'A1', 'hồ bơi; vũng nước; nguồn dự trữ chung; quỹ chung; góp chung; sử dụng chung', 'n.', NULL, NULL, '"pool resources" nghĩa là góp chung nguồn lực; còn "play pool" nghĩa là chơi bi-a kiểu Mỹ.', 'We spent the afternoon swimming in the outdoor pool.', NULL, 'Chúng tôi đã dành cả buổi chiều để bơi ở hồ bơi ngoài trời.', '{"wordId":"pool","ukIpa":"/puːl/","usIpa":"/puːl/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"An artificial swimming basin or a small area of still water","vi":"hồ bơi; vũng nước"},{"pos":"n.","en":"A supply of money, people, or resources available for shared use","vi":"nguồn dự trữ chung; quỹ chung"},{"pos":"v.","en":"To combine resources so people can use them together","vi":"góp chung; sử dụng chung"}],"examples":[{"en":"We spent the afternoon swimming in the outdoor pool.","vi":"Chúng tôi đã dành cả buổi chiều để bơi ở hồ bơi ngoài trời.","audioKind":"ex"},{"en":"Small businesses can pool their resources to purchase equipment that would otherwise be too expensive.","vi":"Các doanh nghiệp nhỏ có thể góp chung nguồn lực để mua những thiết bị mà nếu tự mua sẽ quá đắt đỏ.","audioKind":"ex2"}],"collocations":[{"en":"a swimming pool","vi":"hồ bơi"},{"en":"a pool of talent","vi":"nguồn nhân lực dồi dào"},{"en":"pool resources","vi":"góp chung nguồn lực"},{"en":"pool knowledge","vi":"chia sẻ kiến thức"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"\"pool resources\" nghĩa là góp chung nguồn lực; còn \"play pool\" nghĩa là chơi bi-a kiểu Mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_before', 'en-a1-21', 'before', '/bɪˈfɔːr/', 'A1', 'trước (một thời điểm hoặc sự kiện); trước khi; trước đây; trước kia', 'prep.', NULL, 'Trái nghĩa: after', 'Trong mệnh đề thời gian chỉ tương lai, sau "before" thường dùng thì hiện tại đơn.', 'Please put your shoes by the door before dinner.', NULL, 'Làm ơn để giày của bạn cạnh cửa trước bữa tối.', '{"wordId":"before","ukIpa":"/bɪˈfɔː/","usIpa":"/bɪˈfɔːr/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"Earlier than a particular time or event.","vi":"trước (một thời điểm hoặc sự kiện)"},{"pos":"conj.","en":"Earlier than the time when something happens.","vi":"trước khi"},{"pos":"adv.","en":"At an earlier time.","vi":"trước đây; trước kia"}],"examples":[{"en":"Please put your shoes by the door before dinner.","vi":"Làm ơn để giày của bạn cạnh cửa trước bữa tối.","audioKind":"ex"},{"en":"Before introducing new transport policies, local authorities should consult residents about their daily travel needs.","vi":"Trước khi ban hành các chính sách giao thông mới, chính quyền địa phương nên tham khảo ý kiến người dân về nhu cầu đi lại hằng ngày của họ.","audioKind":"ex2"}],"collocations":[{"en":"before long","vi":"chẳng bao lâu nữa"},{"en":"the day before","vi":"ngày hôm trước"},{"en":"before breakfast","vi":"trước bữa sáng"},{"en":"before making a decision","vi":"trước khi đưa ra quyết định"}],"wordFamily":[],"synonyms":[],"antonyms":["after"],"tipVi":"Trong mệnh đề thời gian chỉ tương lai, sau \"before\" thường dùng thì hiện tại đơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_white', 'en-a1-21', 'white', '/waɪt/', 'A1', 'trắng; có màu trắng; màu trắng; lòng trắng trứng', 'adj.', 'whiten (v.), whiteness (n.), whitish (adj.)', 'Trái nghĩa: black', '"egg white" chỉ lòng trắng trứng; lòng đỏ trứng là "yolk".', 'She wore a white cotton shirt to the picnic.', NULL, 'Cô ấy mặc một chiếc áo sơ mi cotton màu trắng đi dã ngoại.', '{"wordId":"white","ukIpa":"/waɪt/","usIpa":"/waɪt/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"having the colour of fresh snow or milk","vi":"trắng; có màu trắng"},{"pos":"n.","en":"the colour of fresh snow or milk","vi":"màu trắng"},{"pos":"n.","en":"the clear part of an egg that turns white when cooked","vi":"lòng trắng trứng"}],"examples":[{"en":"She wore a white cotton shirt to the picnic.","vi":"Cô ấy mặc một chiếc áo sơ mi cotton màu trắng đi dã ngoại.","audioKind":"ex"},{"en":"Painting roofs white can help buildings reflect sunlight and reduce the energy needed for cooling.","vi":"Sơn mái nhà màu trắng có thể giúp các tòa nhà phản xạ ánh nắng mặt trời và giảm năng lượng cần thiết cho việc làm mát.","audioKind":"ex2"}],"collocations":[{"en":"white paint","vi":"sơn trắng"},{"en":"egg white","vi":"lòng trắng trứng"},{"en":"black and white","vi":"đen trắng"}],"wordFamily":["whiten (v.)","whiteness (n.)","whitish (adj.)"],"synonyms":[],"antonyms":["black"],"tipVi":"\"egg white\" chỉ lòng trắng trứng; lòng đỏ trứng là \"yolk\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_large', 'en-a1-21', 'large', '/lɑːrdʒ/', 'A1', 'lớn; rộng; nhiều', 'adj.', 'largely (adv.), enlarge (v.), enlargement (n.)', 'Đồng nghĩa: big · Trái nghĩa: small', '"large number" đi với danh từ đếm được, còn "large amount" đi với danh từ không đếm được.', 'A large dog was sleeping beside the kitchen door.', NULL, 'Một con chó lớn đang ngủ cạnh cửa bếp.', '{"wordId":"large","ukIpa":"/lɑːdʒ/","usIpa":"/lɑːrdʒ/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"greater than usual in size, amount, or number","vi":"lớn; rộng; nhiều"}],"examples":[{"en":"A large dog was sleeping beside the kitchen door.","vi":"Một con chó lớn đang ngủ cạnh cửa bếp.","audioKind":"ex"},{"en":"Large cities often offer better employment opportunities, although high housing costs can reduce residents'' quality of life.","vi":"Các thành phố lớn thường mang lại nhiều cơ hội việc làm hơn, mặc dù chi phí nhà ở cao có thể làm giảm chất lượng cuộc sống của cư dân.","audioKind":"ex2"}],"collocations":[{"en":"a large number of","vi":"một số lượng lớn"},{"en":"a large amount of","vi":"một lượng lớn"},{"en":"large-scale development","vi":"phát triển quy mô lớn"},{"en":"a large population","vi":"dân số đông"}],"wordFamily":["largely (adv.)","enlarge (v.)","enlargement (n.)"],"synonyms":["big"],"antonyms":["small"],"tipVi":"\"large number\" đi với danh từ đếm được, còn \"large amount\" đi với danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hour', 'en-a1-21', 'hour', '/ˈaʊər/', 'A1', 'giờ; tiếng đồng hồ; giờ làm việc; giờ mở cửa', 'n.', 'hourly (adj.)', NULL, 'Chữ "h" bị câm nên dùng "an hour", không dùng "a hour".', 'The walk to the lake took us an hour.', NULL, 'Chúng tôi đi bộ đến hồ mất một tiếng đồng hồ.', '{"wordId":"hour","ukIpa":"/ˈaʊə/","usIpa":"/ˈaʊər/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a period of sixty minutes","vi":"giờ; tiếng đồng hồ"},{"pos":"n.","en":"the times when someone works or a service operates","vi":"giờ làm việc; giờ mở cửa"}],"examples":[{"en":"The walk to the lake took us an hour.","vi":"Chúng tôi đi bộ đến hồ mất một tiếng đồng hồ.","audioKind":"ex"},{"en":"Reducing working hours may improve employee wellbeing without necessarily lowering overall productivity in the workplace.","vi":"Việc giảm giờ làm có thể cải thiện sức khỏe tinh thần và thể chất của nhân viên mà không nhất thiết làm giảm năng suất chung tại nơi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"an hour","vi":"một giờ"},{"en":"working hours","vi":"giờ làm việc"},{"en":"opening hours","vi":"giờ mở cửa"},{"en":"rush hour","vi":"giờ cao điểm"}],"wordFamily":["hourly (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ \"h\" bị câm nên dùng \"an hour\", không dùng \"a hour\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_full', 'en-a1-21', 'full', '/fʊl/', 'A1', 'đầy; tràn đầy; đầy đủ; trọn vẹn; no; ăn no', 'adj.', 'fully (adv.), fullness (n.)', 'Đồng nghĩa: filled, complete · Trái nghĩa: empty, partial', '"full of" nghĩa là "đầy"; chú ý phát âm của "full" khác với "fool".', 'The basket is full, so we need another one.', NULL, 'Cái giỏ đầy rồi, nên chúng ta cần một cái khác.', '{"wordId":"full","ukIpa":"/fʊl/","usIpa":"/fʊl/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Containing as much as possible, with no space left.","vi":"đầy; tràn đầy"},{"pos":"adj.","en":"Including everything, with nothing missing.","vi":"đầy đủ; trọn vẹn"},{"pos":"adj.","en":"Having eaten enough and not wanting more food.","vi":"no; ăn no"}],"examples":[{"en":"The basket is full, so we need another one.","vi":"Cái giỏ đầy rồi, nên chúng ta cần một cái khác.","audioKind":"ex"},{"en":"Governments should publish the full results of environmental studies so that citizens can make informed decisions.","vi":"Chính phủ nên công bố đầy đủ kết quả các nghiên cứu môi trường để người dân có thể đưa ra quyết định sáng suốt.","audioKind":"ex2"}],"collocations":[{"en":"full of","vi":"đầy"},{"en":"full details","vi":"chi tiết đầy đủ"},{"en":"full potential","vi":"toàn bộ tiềm năng"},{"en":"feel full","vi":"cảm thấy no"}],"wordFamily":["fully (adv.)","fullness (n.)"],"synonyms":["filled","complete"],"antonyms":["empty","partial"],"tipVi":"\"full of\" nghĩa là \"đầy\"; chú ý phát âm của \"full\" khác với \"fool\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_happen', 'en-a1-21', 'happen', '/ˈhæpən/', 'A1', 'xảy ra; diễn ra; tình cờ; ngẫu nhiên', 'v.', 'happening (n.)', 'Đồng nghĩa: occur', 'Không dùng ở thể bị động; "happen to do" nghĩa là tình cờ làm gì.', 'What happened to the plant beside your window?', NULL, 'Chuyện gì đã xảy ra với chậu cây bên cửa sổ nhà bạn vậy?', '{"wordId":"happen","ukIpa":"/ˈhæpən/","usIpa":"/ˈhæpən/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to take place, often without being planned","vi":"xảy ra; diễn ra"},{"pos":"v.","en":"to do or be something by chance","vi":"tình cờ; ngẫu nhiên"}],"examples":[{"en":"What happened to the plant beside your window?","vi":"Chuyện gì đã xảy ra với chậu cây bên cửa sổ nhà bạn vậy?","audioKind":"ex"},{"en":"Traffic accidents are more likely to happen when drivers are tired or distracted by mobile phones.","vi":"Tai nạn giao thông dễ xảy ra hơn khi tài xế mệt mỏi hoặc bị phân tâm bởi điện thoại di động.","audioKind":"ex2"}],"collocations":[{"en":"happen to someone","vi":"xảy ra với ai đó"},{"en":"happen to do something","vi":"tình cờ làm gì đó"},{"en":"happen by chance","vi":"xảy ra tình cờ"}],"wordFamily":["happening (n.)"],"synonyms":["occur"],"antonyms":[],"tipVi":"Không dùng ở thể bị động; \"happen to do\" nghĩa là tình cờ làm gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_number', 'en-a1-21', 'number', '/ˈnʌmbɚ/', 'A1', 'số; con số; mã số; số lượng; đánh số; tổng cộng', 'n.', 'numerical (adj.), numbering (n.), numbered (adj.)', NULL, '"a number of" đi với động từ số nhiều; "the number of" đi với động từ số ít.', 'I saved your phone number on my new phone.', NULL, 'Tôi đã lưu số điện thoại của bạn vào chiếc điện thoại mới của mình.', '{"wordId":"number","ukIpa":"/ˈnʌmbə/","usIpa":"/ˈnʌmbɚ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a value used for counting, measuring, or identifying something","vi":"số; con số; mã số"},{"pos":"n.","en":"the total amount of people or things","vi":"số lượng"},{"pos":"v.","en":"to assign identifying figures or add up to a total","vi":"đánh số; tổng cộng"}],"examples":[{"en":"I saved your phone number on my new phone.","vi":"Tôi đã lưu số điện thoại của bạn vào chiếc điện thoại mới của mình.","audioKind":"ex"},{"en":"The number of people working from home has increased as digital communication tools have improved.","vi":"Số lượng người làm việc tại nhà đã tăng lên khi các công cụ giao tiếp kỹ thuật số được cải thiện.","audioKind":"ex2"}],"collocations":[{"en":"phone number","vi":"số điện thoại"},{"en":"a large number of","vi":"một số lượng lớn"},{"en":"the number of","vi":"số lượng của"},{"en":"number the pages","vi":"đánh số trang"}],"wordFamily":["numerical (adj.)","numbering (n.)","numbered (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"\"a number of\" đi với động từ số nhiều; \"the number of\" đi với động từ số ít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_take', 'en-a1-21', 'take', '/teɪk/', 'A1', 'cầm; lấy; mang đi; mất; tốn (thời gian, công sức); đi (bằng phương tiện giao thông)', 'v.', NULL, NULL, 'Quá khứ là "took", quá khứ phân từ là "taken"; "take" là mang đi, "bring" là mang đến.', 'Take an umbrella because it might rain this afternoon.', NULL, 'Mang theo ô đi vì chiều nay trời có thể mưa đấy.', '{"wordId":"take","ukIpa":"/teɪk/","usIpa":"/teɪk/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To pick up, hold, or carry something away.","vi":"cầm; lấy; mang đi"},{"pos":"v.","en":"To require a particular amount of time or effort.","vi":"mất; tốn (thời gian, công sức)"},{"pos":"v.","en":"To use a particular form of transport.","vi":"đi (bằng phương tiện giao thông)"}],"examples":[{"en":"Take an umbrella because it might rain this afternoon.","vi":"Mang theo ô đi vì chiều nay trời có thể mưa đấy.","audioKind":"ex"},{"en":"Developing reliable public transport networks takes considerable time and requires sustained investment from local authorities.","vi":"Việc phát triển mạng lưới giao thông công cộng đáng tin cậy đòi hỏi nhiều thời gian và cần sự đầu tư bền vững từ chính quyền địa phương.","audioKind":"ex2"}],"collocations":[{"en":"take a bus","vi":"đi xe buýt"},{"en":"take time","vi":"tốn thời gian"},{"en":"take responsibility","vi":"chịu trách nhiệm"},{"en":"take notes","vi":"ghi chép"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Quá khứ là \"took\", quá khứ phân từ là \"taken\"; \"take\" là mang đi, \"bring\" là mang đến.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_enjoy', 'en-a1-21', 'enjoy', '/ɪnˈdʒɔɪ/', 'A1', 'thích thú; tận hưởng; có được; hưởng (quyền lợi, lợi thế)', 'v.', 'enjoyable (adj.), enjoyment (n.)', 'Đồng nghĩa: like, relish · Trái nghĩa: dislike', 'Theo sau là động từ dạng "-ing", không dùng "to do".', 'We enjoy walking beside the river after dinner.', NULL, 'Chúng tôi thích đi dạo bên bờ sông sau bữa tối.', '{"wordId":"enjoy","ukIpa":"/ɪnˈdʒɔɪ/","usIpa":"/ɪnˈdʒɔɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"get pleasure from an activity or experience","vi":"thích thú; tận hưởng"},{"pos":"v.","en":"have something good, such as a right or advantage","vi":"có được; hưởng (quyền lợi, lợi thế)"}],"examples":[{"en":"We enjoy walking beside the river after dinner.","vi":"Chúng tôi thích đi dạo bên bờ sông sau bữa tối.","audioKind":"ex"},{"en":"Residents enjoy better health when their neighbourhoods provide safe walking routes and accessible green spaces.","vi":"Người dân có sức khỏe tốt hơn khi khu vực họ sống có các tuyến đường đi bộ an toàn và không gian xanh dễ tiếp cận.","audioKind":"ex2"}],"collocations":[{"en":"enjoy doing something","vi":"thích làm gì đó"},{"en":"enjoy yourself","vi":"tận hưởng niềm vui"},{"en":"enjoy good health","vi":"có sức khỏe tốt"},{"en":"enjoy the benefits","vi":"hưởng lợi ích"}],"wordFamily":["enjoyable (adj.)","enjoyment (n.)"],"synonyms":["like","relish"],"antonyms":["dislike"],"tipVi":"Theo sau là động từ dạng \"-ing\", không dùng \"to do\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_january', 'en-a1-21', 'January', '/ˈdʒænjueri/', 'A1', 'tháng Một; tháng Giêng', 'n.', NULL, NULL, 'Tên tháng viết hoa chữ cái đầu; vào tháng Một dùng "in January".', 'Our swimming lessons begin in January this year.', NULL, 'Lớp học bơi của chúng tôi bắt đầu vào tháng Một năm nay.', '{"wordId":"january","ukIpa":"/ˈdʒænjuəri/","usIpa":"/ˈdʒænjueri/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"the first month of the year","vi":"tháng Một; tháng Giêng"}],"examples":[{"en":"Our swimming lessons begin in January this year.","vi":"Lớp học bơi của chúng tôi bắt đầu vào tháng Một năm nay.","audioKind":"ex"},{"en":"Many people set health goals in January, but maintaining new habits requires consistent support.","vi":"Nhiều người đặt ra mục tiêu sức khỏe vào tháng Một, nhưng việc duy trì thói quen mới đòi hỏi sự hỗ trợ liên tục.","audioKind":"ex2"}],"collocations":[{"en":"in January","vi":"vào tháng Một"},{"en":"early January","vi":"đầu tháng Một"},{"en":"late January","vi":"cuối tháng Một"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tên tháng viết hoa chữ cái đầu; vào tháng Một dùng \"in January\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hobby', 'en-a1-21', 'hobby', '/ˈhɑːbi/', 'A1', 'sở thích; thú vui', 'n.', 'hobbyist (n.)', 'Đồng nghĩa: pastime', 'Danh từ đếm được, số nhiều là "hobbies"; bắt đầu một sở thích dùng "take up".', 'Growing herbs on my balcony has become my favourite hobby.', NULL, 'Trồng rau thơm trên ban công đã trở thành sở thích yêu thích nhất của tôi.', '{"wordId":"hobby","ukIpa":"/ˈhɒbi/","usIpa":"/ˈhɑːbi/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"An activity you regularly do for pleasure in your free time","vi":"sở thích; thú vui"}],"examples":[{"en":"Growing herbs on my balcony has become my favourite hobby.","vi":"Trồng rau thơm trên ban công đã trở thành sở thích yêu thích nhất của tôi.","audioKind":"ex"},{"en":"Having a creative hobby can help people manage stress and maintain a healthy balance between work and leisure.","vi":"Có một sở thích sáng tạo có thể giúp mọi người kiểm soát căng thẳng và duy trì sự cân bằng lành mạnh giữa công việc và giải trí.","audioKind":"ex2"}],"collocations":[{"en":"take up a hobby","vi":"bắt đầu một sở thích"},{"en":"a creative hobby","vi":"sở thích sáng tạo"},{"en":"pursue a hobby","vi":"theo đuổi sở thích"}],"wordFamily":["hobbyist (n.)"],"synonyms":["pastime"],"antonyms":[],"tipVi":"Danh từ đếm được, số nhiều là \"hobbies\"; bắt đầu một sở thích dùng \"take up\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stand', 'en-a1-21', 'stand', '/stænd/', 'A1', 'đứng; đứng dậy; chịu đựng; chấp nhận; lập trường; quan điểm kiên quyết', 'v.', 'standing (adj.)', 'Trái nghĩa: sit', 'Quá khứ đơn và quá khứ phân từ đều là "stood"; nghĩa chịu đựng thường dùng "can''t stand".', 'Please stand near the door until the bus stops.', NULL, 'Vui lòng đứng gần cửa cho đến khi xe buýt dừng hẳn.', '{"wordId":"stand","ukIpa":"/stænd/","usIpa":"/stænd/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To be upright on your feet, or get into this position.","vi":"đứng; đứng dậy"},{"pos":"v.","en":"To accept something unpleasant without becoming too upset.","vi":"chịu đựng; chấp nhận"},{"pos":"n.","en":"A firm opinion or action supporting or opposing something.","vi":"lập trường; quan điểm kiên quyết"}],"examples":[{"en":"Please stand near the door until the bus stops.","vi":"Vui lòng đứng gần cửa cho đến khi xe buýt dừng hẳn.","audioKind":"ex"},{"en":"Local residents took a stand against the proposed road because it would destroy valuable woodland.","vi":"Người dân địa phương đã có lập trường phản đối con đường dự kiến xây dựng vì nó sẽ phá hủy khu rừng quý giá.","audioKind":"ex2"}],"collocations":[{"en":"stand still","vi":"đứng yên"},{"en":"stand up","vi":"đứng lên"},{"en":"can''t stand doing something","vi":"không thể chịu đựng việc làm gì"},{"en":"take a stand","vi":"bày tỏ lập trường kiên quyết"}],"wordFamily":["standing (adj.)"],"synonyms":[],"antonyms":["sit"],"tipVi":"Quá khứ đơn và quá khứ phân từ đều là \"stood\"; nghĩa chịu đựng thường dùng \"can''t stand\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_must', 'en-a1-21', 'must', '/mʌst/', 'A1', 'phải; cần phải; chắc hẳn; nhất định là; điều thiết yếu; thứ bắt buộc phải có', 'v.', NULL, NULL, '"must" là động từ khuyết thiếu; "mustn''t" mang nghĩa cấm đoán, không phải "không cần phải".', 'You must wear a helmet when riding here.', NULL, 'Bạn phải đội mũ bảo hiểm khi đi xe ở đây.', '{"wordId":"must","ukIpa":"/mʌst/","usIpa":"/mʌst/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"used to express a strong obligation or requirement","vi":"phải; cần phải"},{"pos":"v.","en":"used to express a confident conclusion","vi":"chắc hẳn; nhất định là"},{"pos":"n.","en":"something considered essential","vi":"điều thiết yếu; thứ bắt buộc phải có"}],"examples":[{"en":"You must wear a helmet when riding here.","vi":"Bạn phải đội mũ bảo hiểm khi đi xe ở đây.","audioKind":"ex"},{"en":"Governments must ensure that all children have access to quality education, regardless of their family income.","vi":"Chính phủ phải đảm bảo rằng mọi trẻ em đều được tiếp cận nền giáo dục chất lượng, bất kể thu nhập gia đình của các em ra sao.","audioKind":"ex2"}],"collocations":[{"en":"must be","vi":"chắc hẳn là"},{"en":"must have done","vi":"chắc hẳn đã làm"},{"en":"an absolute must","vi":"điều tuyệt đối cần thiết"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"\"must\" là động từ khuyết thiếu; \"mustn''t\" mang nghĩa cấm đoán, không phải \"không cần phải\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_about', 'en-a1-21', 'about', '/əˈbaʊt/', 'A1', 'về; liên quan đến; khoảng; chừng; xung quanh; khắp nơi', 'prep.', NULL, NULL, '"about" có thể chỉ chủ đề hoặc số lượng ước chừng; "be about to" có nghĩa là sắp sửa.', 'We talked about our holiday plans over dinner.', NULL, 'Chúng tôi đã nói chuyện về kế hoạch kỳ nghỉ trong bữa tối.', '{"wordId":"about","ukIpa":"/əˈbaʊt/","usIpa":"/əˈbaʊt/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"concerning a particular subject","vi":"về; liên quan đến"},{"pos":"adv.","en":"approximately, rather than exactly","vi":"khoảng; chừng"},{"pos":"prep.","en":"in various places within or around somewhere","vi":"xung quanh; khắp nơi"}],"examples":[{"en":"We talked about our holiday plans over dinner.","vi":"Chúng tôi đã nói chuyện về kế hoạch kỳ nghỉ trong bữa tối.","audioKind":"ex"},{"en":"Schools should teach children about the environmental consequences of their everyday choices and habits.","vi":"Nhà trường nên dạy trẻ em về những hệ quả môi trường từ các lựa chọn và thói quen hằng ngày của các em.","audioKind":"ex2"}],"collocations":[{"en":"talk about","vi":"nói về"},{"en":"worry about","vi":"lo lắng về"},{"en":"about an hour","vi":"khoảng một giờ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"\"about\" có thể chỉ chủ đề hoặc số lượng ước chừng; \"be about to\" có nghĩa là sắp sửa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sandwich', 'en-a1-21', 'sandwich', '/ˈsænwɪtʃ/', 'A1', 'bánh mì kẹp; sandwich; kẹp vào giữa', 'n.', NULL, NULL, 'Động từ thường dùng ở dạng bị động "be sandwiched between".', 'I packed a cheese sandwich and an apple for lunch.', NULL, 'Tôi đã gói một chiếc bánh mì kẹp phô mai và một quả táo cho bữa trưa.', '{"wordId":"sandwich","ukIpa":"/ˈsænwɪdʒ/","usIpa":"/ˈsænwɪtʃ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"Two slices of bread with a filling between them.","vi":"bánh mì kẹp; sandwich"},{"pos":"v.","en":"To place or squeeze something between two other things.","vi":"kẹp vào giữa"}],"examples":[{"en":"I packed a cheese sandwich and an apple for lunch.","vi":"Tôi đã gói một chiếc bánh mì kẹp phô mai và một quả táo cho bữa trưa.","audioKind":"ex"},{"en":"School cafeterias can promote healthier eating by offering sandwiches made with wholegrain bread and fresh vegetables.","vi":"Căn tin trường học có thể khuyến khích việc ăn uống lành mạnh hơn bằng cách cung cấp bánh mì kẹp làm từ bánh mì nguyên cám và rau tươi.","audioKind":"ex2"}],"collocations":[{"en":"cheese sandwich","vi":"bánh mì kẹp phô mai"},{"en":"make a sandwich","vi":"làm bánh mì kẹp"},{"en":"be sandwiched between","vi":"bị kẹp giữa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Động từ thường dùng ở dạng bị động \"be sandwiched between\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slow', 'en-a1-21', 'slow', '/sloʊ/', 'A1', 'chậm; chậm chạp; làm chậm lại; giảm tốc độ; chạy chậm (đồng hồ)', 'adj.', 'slowly (adv.), slowness (n.), slowdown (n.)', 'Đồng nghĩa: unhurried, sluggish · Trái nghĩa: fast, quick', '"slow" thường là tính từ; để bổ nghĩa cho hành động thông thường, ta thường dùng "slowly".', 'We took a slow walk along the river.', NULL, 'Chúng tôi đã đi dạo chậm rãi dọc theo bờ sông.', '{"wordId":"slow","ukIpa":"/sləʊ/","usIpa":"/sloʊ/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Moving, happening, or taking place at a low speed.","vi":"chậm; chậm chạp"},{"pos":"v.","en":"To move or happen less quickly, or make something do so.","vi":"làm chậm lại; giảm tốc độ"},{"pos":"adj.","en":"Showing a time earlier than the correct time.","vi":"chạy chậm (đồng hồ)"}],"examples":[{"en":"We took a slow walk along the river.","vi":"Chúng tôi đã đi dạo chậm rãi dọc theo bờ sông.","audioKind":"ex"},{"en":"Slow progress in expanding public transport may discourage commuters from giving up their private cars.","vi":"Tiến độ chậm chạp trong việc mở rộng giao thông công cộng có thể làm nản lòng những người đi làm trong việc từ bỏ ô tô cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"slow progress","vi":"tiến độ chậm"},{"en":"slow down","vi":"chậm lại; giảm tốc độ"},{"en":"a slow pace","vi":"nhịp độ chậm"},{"en":"slow economic growth","vi":"tăng trưởng kinh tế chậm"}],"wordFamily":["slowly (adv.)","slowness (n.)","slowdown (n.)"],"synonyms":["unhurried","sluggish"],"antonyms":["fast","quick"],"tipVi":"\"slow\" thường là tính từ; để bổ nghĩa cho hành động thông thường, ta thường dùng \"slowly\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 28, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_21_1', 'en-a1-21', 'Cách dùng “play” (v.) — chơi; tham gia trò chơi hoặc thể thao', 'play football  ·  play the piano  ·  play a role in', 'Trước tên các môn thể thao bóng thường không dùng mạo từ; trước tên nhạc cụ thường dùng "the".', 'Họ từ (Word Family): player (n.), playful (adj.), playfully (adv.), playfulness (n.)', '[{"hanzi":"The children played with wooden blocks on the floor.","pinyin":"","meaning":"Lũ trẻ chơi với những khối gỗ trên sàn nhà."},{"hanzi":"Schools should provide safe outdoor spaces where children can play and develop essential social skills.","pinyin":"","meaning":"Các trường học nên cung cấp không gian ngoài trời an toàn để trẻ em có thể vui chơi và phát triển các kỹ năng xã hội thiết yếu."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_21_2', 'en-a1-21', 'Cách dùng “year” (n.) — năm', 'academic year  ·  every year  ·  all year round', 'Trước các cụm chỉ thời gian như last year không dùng giới từ; diễn tả tuổi dùng years old.', 'Họ từ (Word Family): yearly (adj.), yearly (adv.)', '[{"hanzi":"We moved into this flat almost a year ago.","pinyin":"","meaning":"Chúng tôi chuyển đến căn hộ này gần một năm trước."},{"hanzi":"A gap year can give students valuable work experience before they begin university studies.","pinyin":"","meaning":"Một năm nghỉ trải nghiệm (gap year) có thể mang lại cho học sinh những kinh nghiệm làm việc quý giá trước khi bắt đầu bậc học đại học."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_21_3', 'en-a1-21', 'Cách dùng “pool” (n.) — hồ bơi; vũng nước', 'a swimming pool  ·  a pool of talent  ·  pool resources', '"pool resources" nghĩa là góp chung nguồn lực; còn "play pool" nghĩa là chơi bi-a kiểu Mỹ.', NULL, '[{"hanzi":"We spent the afternoon swimming in the outdoor pool.","pinyin":"","meaning":"Chúng tôi đã dành cả buổi chiều để bơi ở hồ bơi ngoài trời."},{"hanzi":"Small businesses can pool their resources to purchase equipment that would otherwise be too expensive.","pinyin":"","meaning":"Các doanh nghiệp nhỏ có thể góp chung nguồn lực để mua những thiết bị mà nếu tự mua sẽ quá đắt đỏ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_21_4', 'en-a1-21', 'Cách dùng “must” (v.) — phải; cần phải', 'must be  ·  must have done  ·  an absolute must', '"must" là động từ khuyết thiếu; "mustn''t" mang nghĩa cấm đoán, không phải "không cần phải".', NULL, '[{"hanzi":"You must wear a helmet when riding here.","pinyin":"","meaning":"Bạn phải đội mũ bảo hiểm khi đi xe ở đây."},{"hanzi":"Governments must ensure that all children have access to quality education, regardless of their family income.","pinyin":"","meaning":"Chính phủ phải đảm bảo rằng mọi trẻ em đều được tiếp cận nền giáo dục chất lượng, bất kể thu nhập gia đình của các em ra sao."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_21_1', 'en-a1-21', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_21_1_1', 'ten_21_1', 'break', 'Be careful not to break that glass bowl.', 'Be careful not to break that glass bowl.', '/breɪk/', 'Cẩn thận kẻo làm vỡ cái bát thủy tinh đó.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_21_1_2', 'ten_21_1', 'egg', 'She cracked an egg into the hot frying pan.', 'She cracked an egg into the hot frying pan.', '/eɡ/', 'Cô ấy đập một quả trứng vào chiếc chảo rán nóng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_21_1_3', 'ten_21_1', 'bookshop', 'We found a tiny bookshop beside the railway station.', 'We found a tiny bookshop beside the railway station.', '/ˈbʊkʃɑːp/', 'Chúng tôi tìm thấy một hiệu sách nhỏ xíu bên cạnh nhà ga xe lửa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_21_1_4', 'ten_21_1', 'year', 'We moved into this flat almost a year ago.', 'We moved into this flat almost a year ago.', '/jɪr/', 'Chúng tôi chuyển đến căn hộ này gần một năm trước.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_21_1_5', 'ten_21_1', 'free', 'The café offers free biscuits with every hot drink.', 'The café offers free biscuits with every hot drink.', '/friː/', 'Quán cà phê có phục vụ bánh quy miễn phí với mỗi ly đồ uống nóng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_21_1_6', 'ten_21_1', 'shop', 'The little shop near our house sells fresh bread.', 'The little shop near our house sells fresh bread.', '/ʃɑːp/', 'Cửa hàng nhỏ gần nhà chúng tôi bán bánh mì tươi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_21_1_7', 'ten_21_1', 'weekend', 'We usually visit the farmers'' market at the weekend.', 'We usually visit the farmers'' market at the weekend.', '/ˈwiːkend/', 'Chúng tôi thường ghé thăm chợ nông sản vào cuối tuần.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_21_1_8', 'ten_21_1', 'sweater', 'I pulled on a warm sweater before going outside.', 'I pulled on a warm sweater before going outside.', '/ˈswetər/', 'Tôi mặc vội chiếc áo len ấm áp trước khi bước ra ngoài.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_21_1_1', 'en-a1-21', 'ten_21_1', 'listening', 'listening', 'Be careful not to break that glass bowl.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cẩn thận kẻo làm vỡ cái bát thủy tinh đó.","Cửa hàng nhỏ gần nhà chúng tôi bán bánh mì tươi.","Tôi mặc vội chiếc áo len ấm áp trước khi bước ra ngoài.","Quán cà phê có phục vụ bánh quy miễn phí với mỗi ly đồ uống nóng."]'::jsonb, 0, 'Be careful not to break that glass bowl. → Cẩn thận kẻo làm vỡ cái bát thủy tinh đó.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_21_1_2', 'en-a1-21', 'ten_21_1', 'listening', 'listening', 'She cracked an egg into the hot frying pan.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi mặc vội chiếc áo len ấm áp trước khi bước ra ngoài.","Cẩn thận kẻo làm vỡ cái bát thủy tinh đó.","Chúng tôi chuyển đến căn hộ này gần một năm trước.","Cô ấy đập một quả trứng vào chiếc chảo rán nóng."]'::jsonb, 3, 'She cracked an egg into the hot frying pan. → Cô ấy đập một quả trứng vào chiếc chảo rán nóng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_21_1_3', 'en-a1-21', 'ten_21_1', 'listening', 'listening', 'We found a tiny bookshop beside the railway station.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi tìm thấy một hiệu sách nhỏ xíu bên cạnh nhà ga xe lửa.","Chúng tôi thường ghé thăm chợ nông sản vào cuối tuần.","Chúng tôi chuyển đến căn hộ này gần một năm trước.","Cẩn thận kẻo làm vỡ cái bát thủy tinh đó."]'::jsonb, 0, 'We found a tiny bookshop beside the railway station. → Chúng tôi tìm thấy một hiệu sách nhỏ xíu bên cạnh nhà ga xe lửa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_21_2', 'en-a1-21', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_21_2_1', 'ten_21_2', 'break', 'Regular breaks during study sessions may improve concentration and help students retain new information.', 'Regular breaks during study sessions may improve concentration and help students retain new information.', '/breɪk/', 'Việc nghỉ giải lao định kỳ trong các buổi học có thể cải thiện sự tập trung và giúp học sinh ghi nhớ kiến thức mới.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_21_2_2', 'ten_21_2', 'egg', 'Eggs provide an affordable source of protein and can form part of a balanced diet.', 'Eggs provide an affordable source of protein and can form part of a balanced diet.', '/eɡ/', 'Trứng cung cấp nguồn protein giá cả phải chăng và có thể là một phần trong chế độ ăn uống cân bằng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_21_2_3', 'ten_21_2', 'bookshop', 'An independent bookshop can strengthen local cultural life by hosting reading groups and supporting emerging writers.', 'An independent bookshop can strengthen local cultural life by hosting reading groups and supporting emerging writers.', '/ˈbʊkʃɑːp/', 'Một hiệu sách độc lập có thể củng cố đời sống văn hóa địa phương bằng cách tổ chức các câu lạc bộ đọc sách và hỗ trợ các nhà văn mới nổi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_21_2_4', 'ten_21_2', 'year', 'A gap year can give students valuable work experience before they begin university studies.', 'A gap year can give students valuable work experience before they begin university studies.', '/jɪr/', 'Một năm nghỉ trải nghiệm (gap year) có thể mang lại cho học sinh những kinh nghiệm làm việc quý giá trước khi bắt đầu bậc học đại học.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_21_2_5', 'ten_21_2', 'free', 'Providing free public transport could reduce traffic congestion and improve access to employment for disadvantaged residents.', 'Providing free public transport could reduce traffic congestion and improve access to employment for disadvantaged residents.', '/friː/', 'Việc cung cấp giao thông công cộng miễn phí có thể làm giảm ùn tắc giao thông và cải thiện khả năng tiếp cận việc làm cho cư dân có hoàn cảnh khó khăn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_21_2_6', 'ten_21_2', 'shop', 'Independent shops can strengthen local economies by creating jobs and keeping spending within the community.', 'Independent shops can strengthen local economies by creating jobs and keeping spending within the community.', '/ʃɑːp/', 'Các cửa hàng độc lập có thể củng cố nền kinh tế địa phương bằng cách tạo ra việc làm và giữ lại nguồn chi tiêu trong cộng đồng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
