INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_21_2', 'en-a1-21', NULL, 'comprehensive_test', 'listening', 'She cracked an egg into the hot frying pan.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Quán cà phê có phục vụ bánh quy miễn phí với mỗi ly đồ uống nóng.","Chuyện gì đã xảy ra với chậu cây bên cửa sổ nhà bạn vậy?","Cô ấy đập một quả trứng vào chiếc chảo rán nóng.","Chúng tôi tìm thấy một hiệu sách nhỏ xíu bên cạnh nhà ga xe lửa."]'::jsonb, 2, 'She cracked an egg into the hot frying pan. → Cô ấy đập một quả trứng vào chiếc chảo rán nóng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_21_3', 'en-a1-21', NULL, 'comprehensive_test', 'listening', 'bookshop', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phim; điện ảnh","tiệm sách; hiệu sách","con dao","thuộc về Nhật Bản; thuộc về tiếng Nhật"]'::jsonb, 1, 'bookshop (/ˈbʊkʃɑːp/) → tiệm sách; hiệu sách', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_21_4', 'en-a1-21', NULL, 'comprehensive_test', 'listening', 'We moved into this flat almost a year ago.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi chuyển đến căn hộ này gần một năm trước.","Cái giỏ đầy rồi, nên chúng ta cần một cái khác.","Cô ấy đập một quả trứng vào chiếc chảo rán nóng.","Chúng tôi tìm thấy một hiệu sách nhỏ xíu bên cạnh nhà ga xe lửa."]'::jsonb, 0, 'We moved into this flat almost a year ago. → Chúng tôi chuyển đến căn hộ này gần một năm trước.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_21_5', 'en-a1-21', NULL, 'comprehensive_test', 'listening', 'free', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nghĩ; cho rằng","số; con số; mã số","hồ bơi; vũng nước","miễn phí"]'::jsonb, 3, 'free (/friː/) → miễn phí; tự do; không bị ràng buộc; giải phóng; làm cho tự do', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_21_6', 'en-a1-21', NULL, 'comprehensive_test', 'listening', 'The little shop near our house sells fresh bread.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cửa hàng nhỏ gần nhà chúng tôi bán bánh mì tươi.","Trồng rau thơm trên ban công đã trở thành sở thích yêu thích nhất của tôi.","Đôi găng tay này trông giống nhau, nhưng kích cỡ của chúng lại khác nhau.","Chúng tôi đã nói chuyện về kế hoạch kỳ nghỉ trong bữa tối."]'::jsonb, 0, 'The little shop near our house sells fresh bread. → Cửa hàng nhỏ gần nhà chúng tôi bán bánh mì tươi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
