INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_21_18', 'en-a1-21', NULL, 'comprehensive_test', 'reading', NULL, 'Regular breaks during study sessions may improve concentration and help students retain new information.', 'Dựa vào câu trên, từ “break” có nghĩa phù hợp nhất là gì?', '["bắt đầu; khởi đầu","cho đến khi","nhà; tổ ấm; quê hương","làm vỡ; làm gãy; làm hỏng"]'::jsonb, 3, 'break: làm vỡ; làm gãy; làm hỏng; giờ giải lao; khoảng nghỉ; vi phạm; làm trái. Dịch cả câu: Việc nghỉ giải lao định kỳ trong các buổi học có thể cải thiện sự tập trung và giúp học sinh ghi nhớ kiến thức mới.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_21_19', 'en-a1-21', NULL, 'comprehensive_test', 'reading', NULL, 'Eggs provide an affordable source of protein and can form part of a balanced diet.', 'Dựa vào câu trên, từ “egg” có nghĩa phù hợp nhất là gì?', '["bút; bút mực","trở thành; trở nên","quả cam; trái cam","trứng"]'::jsonb, 3, 'egg: trứng; tế bào trứng; noãn. Dịch cả câu: Trứng cung cấp nguồn protein giá cả phải chăng và có thể là một phần trong chế độ ăn uống cân bằng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_21_20', 'en-a1-21', NULL, 'comprehensive_test', 'reading', NULL, 'An independent bookshop can strengthen local cultural life by hosting reading groups and supporting emerging writers.', 'Dựa vào câu trên, từ “bookshop” có nghĩa phù hợp nhất là gì?', '["tiệm sách; hiệu sách","thông tin; tài liệu","n. câu hỏi; thắc mắc","con thỏ"]'::jsonb, 0, 'bookshop: tiệm sách; hiệu sách. Dịch cả câu: Một hiệu sách độc lập có thể củng cố đời sống văn hóa địa phương bằng cách tổ chức các câu lạc bộ đọc sách và hỗ trợ các nhà văn mới nổi.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_21_21', 'en-a1-21', NULL, 'comprehensive_test', 'reading', NULL, 'A gap year can give students valuable work experience before they begin university studies.', 'Dựa vào câu trên, từ “year” có nghĩa phù hợp nhất là gì?', '["thời gian; thời điểm","năm","tiệm sách; hiệu sách","ở trong; bên trong"]'::jsonb, 1, 'year: năm; năm học; năm công tác. Dịch cả câu: Một năm nghỉ trải nghiệm (gap year) có thể mang lại cho học sinh những kinh nghiệm làm việc quý giá trước khi bắt đầu bậc học đại học.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
