INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-22', 'en', 'Bài 22: Đời sống hằng ngày (7) - CEFR A1', 'CEFR A1', 'A1 · Đời sống', '28 từ vựng Tiếng Anh CEFR A1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1022, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_make', 'en-a1-22', 'make', '/meɪk/', 'A1', 'làm; chế tạo; sản xuất; khiến; bắt buộc; thương hiệu; nhãn hiệu; kiểu máy', 'v.', 'maker (n.), making (n.)', 'Đồng nghĩa: create, produce', 'Thể chủ động dùng ''make sb do''; thể bị động dùng ''be made to do''.', 'We made a small table from leftover pieces of wood.', NULL, 'Chúng tôi đã làm một chiếc bàn nhỏ từ những mảnh gỗ thừa.', '{"wordId":"make","ukIpa":"/meɪk/","usIpa":"/meɪk/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to create or produce something","vi":"làm; chế tạo; sản xuất"},{"pos":"v.","en":"to cause a state or force an action","vi":"khiến; bắt buộc"},{"pos":"n.","en":"the brand or type of a manufactured product","vi":"thương hiệu; nhãn hiệu; kiểu máy"}],"examples":[{"en":"We made a small table from leftover pieces of wood.","vi":"Chúng tôi đã làm một chiếc bàn nhỏ từ những mảnh gỗ thừa.","audioKind":"ex"},{"en":"Schools can make science more accessible by allowing students to conduct simple experiments with everyday materials.","vi":"Nhà trường có thể giúp môn khoa học trở nên dễ tiếp cận hơn bằng cách cho phép học sinh thực hiện các thí nghiệm đơn giản với những vật liệu hằng ngày.","audioKind":"ex2"}],"collocations":[{"en":"make a decision","vi":"đưa ra quyết định"},{"en":"make progress","vi":"tiến bộ"},{"en":"make a difference","vi":"tạo ra sự khác biệt"},{"en":"make someone happy","vi":"làm ai đó vui vẻ"}],"wordFamily":["maker (n.)","making (n.)"],"synonyms":["create","produce"],"antonyms":[],"tipVi":"Thể chủ động dùng ''make sb do''; thể bị động dùng ''be made to do''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_every', 'en-a1-22', 'every', '/ˈevri/', 'A1', 'mỗi; mọi; cứ mỗi; cách mỗi; tất cả; mọi (nhấn mạnh mức độ cao nhất)', 'det.', NULL, NULL, 'Sau ''every'' thường là danh từ đếm được số ít và động từ chia ở ngôi thứ ba số ít.', 'Every child brought a favourite toy to the picnic.', NULL, 'Mỗi đứa trẻ đều mang theo một món đồ chơi yêu thích đến buổi dã ngoại.', '{"wordId":"every","ukIpa":"/ˈevri/","usIpa":"/ˈevri/","cefr":"A1","topic":"daily","senses":[{"pos":"det.","en":"referring to all members of a group individually","vi":"mỗi; mọi"},{"pos":"det.","en":"used to show how regularly something happens","vi":"cứ mỗi; cách mỗi"},{"pos":"det.","en":"used to emphasize all possibilities or a strong degree","vi":"tất cả; mọi (nhấn mạnh mức độ cao nhất)"}],"examples":[{"en":"Every child brought a favourite toy to the picnic.","vi":"Mỗi đứa trẻ đều mang theo một món đồ chơi yêu thích đến buổi dã ngoại.","audioKind":"ex"},{"en":"Governments should ensure that every student has access to reliable internet services for learning.","vi":"Chính phủ nên đảm bảo rằng mọi học sinh đều có thể tiếp cận các dịch vụ internet đáng tin cậy để phục vụ việc học tập.","audioKind":"ex2"}],"collocations":[{"en":"every day","vi":"mỗi ngày; hằng ngày"},{"en":"every other week","vi":"cứ hai tuần một lần"},{"en":"every effort","vi":"mọi nỗ lực"},{"en":"every reason to believe","vi":"đầy đủ lý do để tin rằng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Sau ''every'' thường là danh từ đếm được số ít và động từ chia ở ngôi thứ ba số ít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quiet', 'en-a1-22', 'quiet', '/ˈkwaɪət/', 'A1', 'yên tĩnh; im ắng; thanh bình; ít nhộn nhịp; sự yên tĩnh; sự thanh bình', 'adj.', 'quietly (adv.), quietness (n.)', 'Đồng nghĩa: silent, peaceful · Trái nghĩa: noisy, loud', '''quiet'' có nghĩa là ''yên tĩnh'', còn ''quite'' có nghĩa là ''khá'', cần chú ý chính tả để tránh nhầm lẫn.', 'The house was quiet after the children fell asleep.', NULL, 'Ngôi nhà trở nên yên tĩnh sau khi bọn trẻ đã ngủ say.', '{"wordId":"quiet","ukIpa":"/ˈkwaɪət/","usIpa":"/ˈkwaɪət/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"making little or no noise","vi":"yên tĩnh; im ắng"},{"pos":"adj.","en":"having little activity or excitement","vi":"thanh bình; ít nhộn nhịp"},{"pos":"n.","en":"a state with little or no noise","vi":"sự yên tĩnh; sự thanh bình"}],"examples":[{"en":"The house was quiet after the children fell asleep.","vi":"Ngôi nhà trở nên yên tĩnh sau khi bọn trẻ đã ngủ say.","audioKind":"ex"},{"en":"Quiet study spaces in public libraries are essential for students who cannot concentrate at home.","vi":"Không gian học tập yên tĩnh trong các thư viện công cộng rất cần thiết cho những học sinh không thể tập trung ở nhà.","audioKind":"ex2"}],"collocations":[{"en":"keep quiet","vi":"giữ im lặng"},{"en":"a quiet neighbourhood","vi":"một khu phố yên tĩnh"},{"en":"peace and quiet","vi":"sự bình yên và tĩnh lặng"}],"wordFamily":["quietly (adv.)","quietness (n.)"],"synonyms":["silent","peaceful"],"antonyms":["noisy","loud"],"tipVi":"''quiet'' có nghĩa là ''yên tĩnh'', còn ''quite'' có nghĩa là ''khá'', cần chú ý chính tả để tránh nhầm lẫn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_add', 'en-a1-22', 'add', '/æd/', 'A1', 'thêm vào; bổ sung; cộng; làm phép cộng; nói thêm; bổ sung ý', 'v.', 'addition (n.), additional (adj.), additionally (adv.)', 'Trái nghĩa: subtract, remove', '''add A to B'' nghĩa là thêm A vào B; ''add to'' còn có nghĩa là làm tăng thêm.', 'Add a little milk if the soup is too thick.', NULL, 'Hãy thêm một chút sữa nếu súp quá đặc.', '{"wordId":"add","ukIpa":"/æd/","usIpa":"/æd/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to put something with something else or increase an amount","vi":"thêm vào; bổ sung"},{"pos":"v.","en":"to combine numbers to find their total","vi":"cộng; làm phép cộng"},{"pos":"v.","en":"to say something more after an earlier statement","vi":"nói thêm; bổ sung ý"}],"examples":[{"en":"Add a little milk if the soup is too thick.","vi":"Hãy thêm một chút sữa nếu súp quá đặc.","audioKind":"ex"},{"en":"Adding more green spaces to urban neighbourhoods can improve residents'' wellbeing and provide habitats for wildlife.","vi":"Việc bổ sung thêm nhiều không gian xanh vào các khu dân cư đô thị có thể cải thiện sức khỏe tinh thần và thể chất của người dân, đồng thời cung cấp môi trường sống cho động vật hoang dã.","audioKind":"ex2"}],"collocations":[{"en":"add something to","vi":"thêm cái gì vào..."},{"en":"add up","vi":"cộng lại"},{"en":"add value","vi":"gia tăng giá trị"},{"en":"add that","vi":"nói thêm rằng"}],"wordFamily":["addition (n.)","additional (adj.)","additionally (adv.)"],"synonyms":[],"antonyms":["subtract","remove"],"tipVi":"''add A to B'' nghĩa là thêm A vào B; ''add to'' còn có nghĩa là làm tăng thêm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nice', 'en-a1-22', 'nice', '/naɪs/', 'A1', 'tốt đẹp; dễ chịu; thú vị; tử tế; thân thiện', 'adj.', 'nicely (adv.), niceness (n.)', 'Đồng nghĩa: pleasant, lovely · Trái nghĩa: unpleasant', 'Từ ''nice'' có nghĩa khá rộng, trong văn viết trang trọng nên thay bằng các tính từ cụ thể hơn.', 'We had a nice picnic beside the lake.', NULL, 'Chúng tôi đã có một buổi dã ngoại thật vui bên bờ hồ.', '{"wordId":"nice","ukIpa":"/naɪs/","usIpa":"/naɪs/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"pleasant or enjoyable","vi":"tốt đẹp; dễ chịu; thú vị"},{"pos":"adj.","en":"kind and friendly towards other people","vi":"tử tế; thân thiện"}],"examples":[{"en":"We had a nice picnic beside the lake.","vi":"Chúng tôi đã có một buổi dã ngoại thật vui bên bờ hồ.","audioKind":"ex"},{"en":"Although nice surroundings matter, affordable housing and reliable transport are more important to many urban residents.","vi":"Mặc dù môi trường sống dễ chịu rất quan trọng, nhưng nhà ở giá cả phải chăng và giao thông đáng tin cậy còn quan trọng hơn đối với nhiều cư dân đô thị.","audioKind":"ex2"}],"collocations":[{"en":"nice weather","vi":"thời tiết đẹp"},{"en":"a nice time","vi":"khoảng thời gian vui vẻ"},{"en":"be nice to someone","vi":"tử tế với ai đó"}],"wordFamily":["nicely (adv.)","niceness (n.)"],"synonyms":["pleasant","lovely"],"antonyms":["unpleasant"],"tipVi":"Từ ''nice'' có nghĩa khá rộng, trong văn viết trang trọng nên thay bằng các tính từ cụ thể hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_important', 'en-a1-22', 'important', '/ɪmˈpɔːrtənt/', 'A1', 'quan trọng; có giá trị lớn hoặc ảnh hưởng đáng kể; có quyền lực, ảnh hưởng hoặc địa vị đáng kể', 'adj.', 'importance (n.), importantly (adv.), unimportant (adj.)', 'Đồng nghĩa: significant, crucial · Trái nghĩa: unimportant, insignificant', 'Dùng It is important to do; importance là danh từ.', 'Keep your important documents in this waterproof folder.', NULL, 'Hãy cất giữ các tài liệu quan trọng của bạn trong chiếc cặp chống nước này.', '{"wordId":"important","ukIpa":"/ɪmˈpɔːtənt/","usIpa":"/ɪmˈpɔːrtənt/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Having great value or a significant effect.","vi":"quan trọng; có giá trị lớn hoặc ảnh hưởng đáng kể"},{"pos":"adj.","en":"Having considerable power, influence, or status.","vi":"có quyền lực, ảnh hưởng hoặc địa vị đáng kể"}],"examples":[{"en":"Keep your important documents in this waterproof folder.","vi":"Hãy cất giữ các tài liệu quan trọng của bạn trong chiếc cặp chống nước này.","audioKind":"ex"},{"en":"Access to reliable information plays an important role in helping citizens make informed decisions about their health.","vi":"Việc tiếp cận thông tin đáng tin cậy đóng vai trò quan trọng trong việc giúp công dân đưa ra các quyết định sáng suốt về sức khỏe của họ.","audioKind":"ex2"}],"collocations":[{"en":"an important role","vi":"một vai trò quan trọng"},{"en":"an important factor","vi":"một yếu tố quan trọng"},{"en":"important to someone","vi":"quan trọng đối với ai đó"},{"en":"equally important","vi":"quan trọng như nhau"}],"wordFamily":["importance (n.)","importantly (adv.)","unimportant (adj.)"],"synonyms":["significant","crucial"],"antonyms":["unimportant","insignificant"],"tipVi":"Dùng It is important to do; importance là danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_late', 'en-a1-22', 'late', '/leɪt/', 'A1', 'muộn; trễ; muộn; trễ (về thời gian); quá cố; đã qua đời (dùng trước danh từ chỉ người)', 'adj.', 'lateness (n.), lately (adv.)', 'Đồng nghĩa: delayed · Trái nghĩa: early', 'Late là trạng từ chỉ sự muộn màng; lately có nghĩa là gần đây, không được nhầm lẫn.', 'I was late because my bicycle had a flat tyre.', NULL, 'Tôi bị muộn vì xe đạp bị thủng lốp.', '{"wordId":"late","ukIpa":"/leɪt/","usIpa":"/leɪt/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"after the expected time or near the end of a period","vi":"muộn; trễ"},{"pos":"adv.","en":"after the expected time or towards a period''s end","vi":"muộn; trễ (về thời gian)"},{"pos":"adj.","en":"used before mentioning a person who has died","vi":"quá cố; đã qua đời (dùng trước danh từ chỉ người)"}],"examples":[{"en":"I was late because my bicycle had a flat tyre.","vi":"Tôi bị muộn vì xe đạp bị thủng lốp.","audioKind":"ex"},{"en":"Students who regularly stay up late may struggle to concentrate and perform well in morning classes.","vi":"Những học sinh thường xuyên thức khuya có thể gặp khó khăn trong việc tập trung và đạt kết quả tốt trong các lớp học buổi sáng.","audioKind":"ex2"}],"collocations":[{"en":"be late for","vi":"đến muộn; trễ giờ"},{"en":"stay up late","vi":"thức khuya"},{"en":"late at night","vi":"đêm muộn; khuya"},{"en":"in the late stages","vi":"ở giai đoạn cuối"}],"wordFamily":["lateness (n.)","lately (adv.)"],"synonyms":["delayed"],"antonyms":["early"],"tipVi":"Late là trạng từ chỉ sự muộn màng; lately có nghĩa là gần đây, không được nhầm lẫn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cake', 'en-a1-22', 'cake', '/keɪk/', 'A1', 'bánh ngọt; phủ một lớp dày; đóng cục', 'n.', NULL, NULL, 'Cả cái bánh là danh từ đếm được; khi chỉ chung món bánh ngọt thì thường là không đếm được.', 'We shared a slice of lemon cake after lunch.', NULL, 'Chúng tôi chia nhau một miếng bánh chanh sau bữa trưa.', '{"wordId":"cake","ukIpa":"/keɪk/","usIpa":"/keɪk/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A sweet food baked from flour, eggs, sugar, and fat.","vi":"bánh ngọt"},{"pos":"v.","en":"To cover with a thick layer or form hard lumps.","vi":"phủ một lớp dày; đóng cục"}],"examples":[{"en":"We shared a slice of lemon cake after lunch.","vi":"Chúng tôi chia nhau một miếng bánh chanh sau bữa trưa.","audioKind":"ex"},{"en":"Schools can encourage healthier eating by offering fresh fruit instead of cake at school celebrations.","vi":"Các trường học có thể khuyến khích chế độ ăn uống lành mạnh hơn bằng cách cung cấp trái cây tươi thay vì bánh ngọt trong các dịp kỷ niệm ở trường.","audioKind":"ex2"}],"collocations":[{"en":"a slice of cake","vi":"một miếng bánh ngọt"},{"en":"bake a cake","vi":"nướng bánh"},{"en":"a birthday cake","vi":"bánh sinh nhật"},{"en":"be caked in mud","vi":"dính đầy bùn đất"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cả cái bánh là danh từ đếm được; khi chỉ chung món bánh ngọt thì thường là không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sound', 'en-a1-22', 'sound', '/saʊnd/', 'A1', 'thanh âm; âm thanh; nghe có vẻ; phát ra âm thanh; hợp lý; đáng tin cậy; lành mạnh, nguyên vẹn', 'n.', 'soundless (adj.), soundlessly (adv.), soundness (n.), soundly (adv.)', NULL, 'sound sau cộng với tính từ; sound like cộng với danh từ.', 'The sound of rain woke me before sunrise.', NULL, 'Tiếng mưa rơi đã đánh thức tôi dậy trước khi trời sáng.', '{"wordId":"sound","ukIpa":"/saʊnd/","usIpa":"/saʊnd/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"something you hear","vi":"thanh âm; âm thanh"},{"pos":"v.","en":"to seem a certain way when heard, or produce noise","vi":"nghe có vẻ; phát ra âm thanh"},{"pos":"adj.","en":"sensible, reliable, or in good condition","vi":"hợp lý; đáng tin cậy; lành mạnh, nguyên vẹn"}],"examples":[{"en":"The sound of rain woke me before sunrise.","vi":"Tiếng mưa rơi đã đánh thức tôi dậy trước khi trời sáng.","audioKind":"ex"},{"en":"Environmental policies should be based on sound scientific evidence rather than assumptions about public behaviour.","vi":"Các chính sách môi trường nên dựa trên các bằng chứng khoa học đáng tin cậy thay vì những giả định về hành vi của công chúng.","audioKind":"ex2"}],"collocations":[{"en":"sound advice","vi":"lời khuyên hữu ích"},{"en":"sound evidence","vi":"bằng chứng đáng tin cậy"},{"en":"sound like","vi":"nghe có vẻ như"},{"en":"sound the alarm","vi":"báo động; la làng"}],"wordFamily":["soundless (adj.)","soundlessly (adv.)","soundness (n.)","soundly (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"sound sau cộng với tính từ; sound like cộng với danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_open', 'en-a1-22', 'open', '/ˈoʊpən/', 'A1', 'mở; mở cửa; hoạt động; mở ra; khai trương; bắt đầu; cởi mở; phóng khoáng; sẵn sàng tiếp thu', 'adj.', 'opening (n.), openness (n.), openly (adv.), reopen (v.)', 'Trái nghĩa: closed, close', 'be open diễn tả trạng thái mở; open làm động từ diễn tả hành động mở.', 'Leave the window open so fresh air can come in.', NULL, 'Hãy để cửa sổ mở để không khí trong lành có thể lùa vào.', '{"wordId":"open","ukIpa":"/ˈəʊpən/","usIpa":"/ˈoʊpən/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Not closed, or available for people to enter and use.","vi":"mở; mở cửa; hoạt động"},{"pos":"v.","en":"To make something accessible or start operating a business.","vi":"mở ra; khai trương; bắt đầu"},{"pos":"adj.","en":"Honest about your thoughts, or willing to consider new ideas.","vi":"cởi mở; phóng khoáng; sẵn sàng tiếp thu"}],"examples":[{"en":"Leave the window open so fresh air can come in.","vi":"Hãy để cửa sổ mở để không khí trong lành có thể lùa vào.","audioKind":"ex"},{"en":"Governments should remain open to public feedback when developing policies that affect access to essential services.","vi":"Chính phủ nên duy trì thái độ cởi mở trước các ý kiến đóng góp của công chúng khi xây dựng các chính sách ảnh hưởng đến việc tiếp cận dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"open the door","vi":"mở cửa"},{"en":"open to the public","vi":"mở cửa công khai cho công chúng"},{"en":"open to suggestions","vi":"sẵn sàng lắng nghe góp ý"},{"en":"keep an open mind","vi":"giữ một tâm trí cởi mở"}],"wordFamily":["opening (n.)","openness (n.)","openly (adv.)","reopen (v.)"],"synonyms":[],"antonyms":["closed","close"],"tipVi":"be open diễn tả trạng thái mở; open làm động từ diễn tả hành động mở.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_back', 'en-a1-22', 'back', '/bæk/', 'A1', 'lưng; phần sau; lùi lại; về phía sau; trở lại; ủng hộ; hỗ trợ', 'n.', 'backward (adv.), backwards (adv.), backing (n.)', NULL, 'go back chỉ sự quay lại; back đóng vai trò động từ có nghĩa là ủng hộ.', 'My back feels stiff after sitting all morning.', NULL, 'Lưng của tôi cảm thấy cứng đờ sau khi ngồi suốt cả buổi sáng.', '{"wordId":"back","ukIpa":"/bæk/","usIpa":"/bæk/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The rear part of your body or of something else.","vi":"lưng; phần sau"},{"pos":"adv.","en":"Towards the rear, or to a previous place or state.","vi":"lùi lại; về phía sau; trở lại"},{"pos":"v.","en":"To support a person, plan, or organization.","vi":"ủng hộ; hỗ trợ"}],"examples":[{"en":"My back feels stiff after sitting all morning.","vi":"Lưng của tôi cảm thấy cứng đờ sau khi ngồi suốt cả buổi sáng.","audioKind":"ex"},{"en":"Local residents are likely to back transport projects that reduce congestion and improve access to employment.","vi":"Cư dân địa phương có nhiều khả năng ủng hộ các dự án giao thông giúp giảm thiểu ùn tắc và cải thiện việc đi lại phục vụ công việc.","audioKind":"ex2"}],"collocations":[{"en":"back pain","vi":"đau lưng"},{"en":"go back","vi":"quay về"},{"en":"back a proposal","vi":"ủng hộ một đề xuất"},{"en":"at the back of","vi":"ở phía sau của"}],"wordFamily":["backward (adv.)","backwards (adv.)","backing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"go back chỉ sự quay lại; back đóng vai trò động từ có nghĩa là ủng hộ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gray', 'en-a1-22', 'gray', '/ɡreɪ/', 'A1', 'xám; xám xịt; hoa râm; màu xám; u ám; ảm đạm', 'adj.', 'grayness (n.), grayish (adj.)', 'Đồng nghĩa: grey', 'gray là cách viết theo tiếng Mỹ, còn tiếng Anh-Anh thường viết là grey.', 'My grandfather wears a gray coat every winter.', NULL, 'Ông của tôi mặc một chiếc áo khoác màu xám vào mỗi mùa đông.', '{"wordId":"gray","ukIpa":"/ɡreɪ/","usIpa":"/ɡreɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"having a colour between black and white","vi":"xám; xám xịt; hoa râm"},{"pos":"n.","en":"the colour between black and white","vi":"màu xám"},{"pos":"adj.","en":"dark and cloudy, or lacking cheerfulness","vi":"u ám; ảm đạm"}],"examples":[{"en":"My grandfather wears a gray coat every winter.","vi":"Ông của tôi mặc một chiếc áo khoác màu xám vào mỗi mùa đông.","audioKind":"ex"},{"en":"Replacing gray concrete surfaces with green spaces can make urban neighbourhoods more attractive and welcoming.","vi":"Việc thay thế các bề mặt bê tông xám bằng các không gian xanh có thể làm cho các khu đô thị trở nên hấp dẫn và đáng sống hơn.","audioKind":"ex2"}],"collocations":[{"en":"gray hair","vi":"tóc hoa râm"},{"en":"gray skies","vi":"bầu trời u ám"},{"en":"a gray area","vi":"vùng xám"}],"wordFamily":["grayness (n.)","grayish (adj.)"],"synonyms":["grey"],"antonyms":[],"tipVi":"gray là cách viết theo tiếng Mỹ, còn tiếng Anh-Anh thường viết là grey.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_always', 'en-a1-22', 'always', '/ˈɔːlweɪz/', 'A1', 'luôn luôn; lúc nào cũng; mãi mãi; từ trước đến nay', 'adv.', NULL, 'Đồng nghĩa: invariably · Trái nghĩa: never', 'Thường đặt trước động từ thường và sau động từ to be; not always nghĩa là không phải lúc nào cũng.', 'My neighbour always waves when she sees me.', NULL, 'Hàng xóm của tôi luôn vẫy tay chào mỗi khi cô ấy nhìn thấy tôi.', '{"wordId":"always","ukIpa":"/ˈɔːlweɪz/","usIpa":"/ˈɔːlweɪz/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"every time or on every occasion","vi":"luôn luôn; lúc nào cũng"},{"pos":"adv.","en":"throughout all time or for ever","vi":"mãi mãi; từ trước đến nay"}],"examples":[{"en":"My neighbour always waves when she sees me.","vi":"Hàng xóm của tôi luôn vẫy tay chào mỗi khi cô ấy nhìn thấy tôi.","audioKind":"ex"},{"en":"Higher levels of economic growth do not always lead to better living conditions for every citizen.","vi":"Mức tăng trưởng kinh tế cao hơn không phải lúc nào cũng mang lại điều kiện sống tốt hơn cho mọi công dân.","audioKind":"ex2"}],"collocations":[{"en":"almost always","vi":"hầu như luôn luôn"},{"en":"not always","vi":"không phải lúc nào cũng"},{"en":"as always","vi":"như mọi khi"}],"wordFamily":[],"synonyms":["invariably"],"antonyms":["never"],"tipVi":"Thường đặt trước động từ thường và sau động từ to be; not always nghĩa là không phải lúc nào cũng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_usually', 'en-a1-22', 'usually', '/ˈjuːʒuəli/', 'A1', 'thường xuyên; thông thường', 'adv.', 'usual (adj.), unusual (adj.), unusually (adv.)', 'Đồng nghĩa: normally, generally · Trái nghĩa: rarely, never', 'Thường đặt trước động từ thường và sau động từ to be.', 'I usually walk to work unless it rains.', NULL, 'Tôi thường đi bộ đi làm trừ khi trời mưa.', '{"wordId":"usually","ukIpa":"/ˈjuːʒuəli/","usIpa":"/ˈjuːʒuəli/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"On most occasions, but not always.","vi":"thường xuyên; thông thường"}],"examples":[{"en":"I usually walk to work unless it rains.","vi":"Tôi thường đi bộ đi làm trừ khi trời mưa.","audioKind":"ex"},{"en":"People usually find it easier to maintain healthy habits when their friends and family offer support.","vi":"Mọi người thường thấy việc duy trì thói quen lành mạnh dễ dàng hơn khi có sự hỗ trợ từ bạn bè và gia đình.","audioKind":"ex2"}],"collocations":[{"en":"usually go","vi":"thường đi"},{"en":"usually available","vi":"thường có sẵn"},{"en":"as usually happens","vi":"như thường lệ"}],"wordFamily":["usual (adj.)","unusual (adj.)","unusually (adv.)"],"synonyms":["normally","generally"],"antonyms":["rarely","never"],"tipVi":"Thường đặt trước động từ thường và sau động từ to be.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_friday', 'en-a1-22', 'Friday', '/ˈfraɪdeɪ/', 'A1', 'ngày thứ Sáu', 'n.', NULL, NULL, 'Viết hoa chữ cái đầu; dùng on Friday, nhưng trước next Friday không dùng on.', 'We usually cook dinner together at home on Friday.', NULL, 'Chúng tôi thường cùng nhau nấu bữa tối ở nhà vào ngày thứ Sáu.', '{"wordId":"friday","ukIpa":"/ˈfraɪdeɪ/","usIpa":"/ˈfraɪdeɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"the day after Thursday and before Saturday","vi":"ngày thứ Sáu"}],"examples":[{"en":"We usually cook dinner together at home on Friday.","vi":"Chúng tôi thường cùng nhau nấu bữa tối ở nhà vào ngày thứ Sáu.","audioKind":"ex"},{"en":"Allowing employees to work from home on Friday may reduce commuting pressure and improve job satisfaction.","vi":"Cho phép nhân viên làm việc từ nhà vào thứ Sáu có thể giảm áp lực đi lại và cải thiện mức độ hài lòng trong công việc.","audioKind":"ex2"}],"collocations":[{"en":"on Friday","vi":"vào thứ Sáu"},{"en":"Friday evening","vi":"tối thứ Sáu"},{"en":"every Friday","vi":"mỗi thứ Sáu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Viết hoa chữ cái đầu; dùng on Friday, nhưng trước next Friday không dùng on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_feet', 'en-a1-22', 'feet', '/fiːt/', 'A1', 'bàn chân; mét (đơn vị đo lường)', 'n.', 'foot (n.)', NULL, 'foot có số nhiều là feet; khi đóng vai trò làm tính từ bổ nghĩa phía trước thì dùng dạng số ít, ví dụ như six-foot.', 'My feet felt cold against the kitchen tiles.', NULL, 'Bàn chân tôi thấy lạnh khi chạm vào nền gạch trong bếp.', '{"wordId":"feet","ukIpa":"/fiːt/","usIpa":"/fiːt/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"the body parts at the ends of the legs","vi":"bàn chân"},{"pos":"n.","en":"units of length, each equal to twelve inches","vi":"mét (đơn vị đo lường)"}],"examples":[{"en":"My feet felt cold against the kitchen tiles.","vi":"Bàn chân tôi thấy lạnh khi chạm vào nền gạch trong bếp.","audioKind":"ex"},{"en":"Designing comfortable footwear can protect the feet of workers who spend most of their day standing.","vi":"Việc thiết kế giày dép thoải mái có thể bảo vệ đôi chân của những công nhân phải đứng làm việc gần như cả ngày.","audioKind":"ex2"}],"collocations":[{"en":"bare feet","vi":"chân trần"},{"en":"on your feet","vi":"đang đứng"},{"en":"six feet tall","vi":"cao sáu foot"},{"en":"get to your feet","vi":"đứng dậy"}],"wordFamily":["foot (n.)"],"synonyms":[],"antonyms":[],"tipVi":"foot có số nhiều là feet; khi đóng vai trò làm tính từ bổ nghĩa phía trước thì dùng dạng số ít, ví dụ như six-foot.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wash', 'en-a1-22', 'wash', '/wɑːʃ/', 'A1', 'rửa; giặt; tẩy rửa; cuốn trôi; xói mòn; sự rửa; sự giặt giũ', 'v.', 'washing (n.), washable (adj.), unwashed (adj.)', 'Đồng nghĩa: clean, cleanse', 'wash nhấn mạnh việc làm sạch bằng nước; clean mang nghĩa tổng quát là làm sạch và không nhất thiết phải dùng nước.', 'Please wash your hands before you help prepare dinner.', NULL, 'Vui lòng rửa tay trước khi bạn giúp chuẩn bị bữa tối.', '{"wordId":"wash","ukIpa":"/wɒʃ/","usIpa":"/wɑːʃ/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To clean something using water, often with soap.","vi":"rửa; giặt; tẩy rửa"},{"pos":"v.","en":"To carry or move something through flowing water.","vi":"cuốn trôi; xói mòn"},{"pos":"n.","en":"An act of cleaning with water.","vi":"sự rửa; sự giặt giũ"}],"examples":[{"en":"Please wash your hands before you help prepare dinner.","vi":"Vui lòng rửa tay trước khi bạn giúp chuẩn bị bữa tối.","audioKind":"ex"},{"en":"Schools should teach children to wash their hands properly to reduce the spread of infectious diseases.","vi":"Nhà trường nên dạy học sinh cách rửa tay đúng cách để giảm thiểu sự lây lan của các bệnh truyền nhiễm.","audioKind":"ex2"}],"collocations":[{"en":"wash your hands","vi":"rửa tay"},{"en":"wash the dishes","vi":"rửa bát đĩa"},{"en":"wash away","vi":"cuốn trôi"},{"en":"give something a wash","vi":"rửa qua thứ gì đó"}],"wordFamily":["washing (n.)","washable (adj.)","unwashed (adj.)"],"synonyms":["clean","cleanse"],"antonyms":[],"tipVi":"wash nhấn mạnh việc làm sạch bằng nước; clean mang nghĩa tổng quát là làm sạch và không nhất thiết phải dùng nước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sofa', 'en-a1-22', 'sofa', '/ˈsoʊfə/', 'A1', 'ghế sô-fa; ghế dài có tựa', 'n.', NULL, 'Đồng nghĩa: couch', 'Khi nói ngồi trên ghế sô-fa thì dùng giới từ on the sofa chứ không dùng in.', 'We curled up on the sofa after dinner.', NULL, 'Chúng tôi cuộn tròn người trên chiếc ghế sô-fa sau bữa tối.', '{"wordId":"sofa","ukIpa":"/ˈsəʊfə/","usIpa":"/ˈsoʊfə/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A soft seat with a back for several people","vi":"ghế sô-fa; ghế dài có tựa"}],"examples":[{"en":"We curled up on the sofa after dinner.","vi":"Chúng tôi cuộn tròn người trên chiếc ghế sô-fa sau bữa tối.","audioKind":"ex"},{"en":"A comfortable sofa in a shared lounge can encourage residents to spend more time together.","vi":"Một chiếc ghế sô-fa thoải mái ở khu vực sinh hoạt chung có thể khuyến khích cư dân dành nhiều thời gian quây quần bên nhau hơn.","audioKind":"ex2"}],"collocations":[{"en":"sit on the sofa","vi":"ngồi trên ghế sô-fa"},{"en":"sofa bed","vi":"ghế sô-fa giường"},{"en":"leather sofa","vi":"ghế sô-fa da"}],"wordFamily":[],"synonyms":["couch"],"antonyms":[],"tipVi":"Khi nói ngồi trên ghế sô-fa thì dùng giới từ on the sofa chứ không dùng in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rice', 'en-a1-22', 'rice', '/raɪs/', 'A1', 'gạo; cơm; lúa', 'n.', NULL, NULL, 'rice thường là danh từ không đếm được; để chỉ một hạt gạo, dùng a grain of rice.', 'We had rice with steamed fish for dinner.', NULL, 'Bữa tối của chúng tôi có cơm và cá hấp.', '{"wordId":"rice","ukIpa":"/raɪs/","usIpa":"/raɪs/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A cereal plant whose grains are cooked and eaten.","vi":"gạo; cơm; lúa"}],"examples":[{"en":"We had rice with steamed fish for dinner.","vi":"Bữa tối của chúng tôi có cơm và cá hấp.","audioKind":"ex"},{"en":"Improved irrigation methods can help farmers grow rice while using less water in regions affected by drought.","vi":"Các phương pháp tưới tiêu được cải thiện có thể giúp nông dân trồng lúa mà vẫn tiết kiệm nước hơn ở các khu vực chịu ảnh hưởng bởi hạn hán.","audioKind":"ex2"}],"collocations":[{"en":"a bowl of rice","vi":"một bát cơm"},{"en":"brown rice","vi":"gạo lứt"},{"en":"grow rice","vi":"trồng lúa"},{"en":"rice field","vi":"cánh đồng lúa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"rice thường là danh từ không đếm được; để chỉ một hạt gạo, dùng a grain of rice.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clean', 'en-a1-22', 'clean', '/kliːn/', 'A1', 'sạch sẽ; không vấy bẩn; làm sạch; dọn dẹp; sạch, ít hoặc không gây ô nhiễm', 'adj.', 'cleaner (n.), cleanliness (n.), cleanly (adv.), unclean (adj.)', 'Đồng nghĩa: spotless, wash · Trái nghĩa: dirty, polluted', 'clean mang nghĩa sạch sẽ; clear mang nghĩa trong suốt hoặc rõ ràng, hai từ này không thể dùng thay thế cho nhau một cách tùy tiện.', 'There are clean towels on the shelf beside you.', NULL, 'Có những chiếc khăn tắm sạch đặt trên giá ở cạnh bạn kìa.', '{"wordId":"clean","ukIpa":"/kliːn/","usIpa":"/kliːn/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Free from dirt, marks, or unwanted substances.","vi":"sạch sẽ; không vấy bẩn"},{"pos":"v.","en":"To remove dirt or unwanted substances from something.","vi":"làm sạch; dọn dẹp"},{"pos":"adj.","en":"Producing little or no pollution.","vi":"sạch, ít hoặc không gây ô nhiễm"}],"examples":[{"en":"There are clean towels on the shelf beside you.","vi":"Có những chiếc khăn tắm sạch đặt trên giá ở cạnh bạn kìa.","audioKind":"ex"},{"en":"Investing in clean energy can reduce air pollution while creating new employment opportunities in developing industries.","vi":"Đầu tư vào năng lượng sạch có thể làm giảm ô nhiễm không khí đồng thời tạo ra các cơ hội việc làm mới trong các ngành công nghiệp đang phát triển.","audioKind":"ex2"}],"collocations":[{"en":"keep clean","vi":"giữ gìn sạch sẽ"},{"en":"clean water","vi":"nước sạch"},{"en":"clean energy","vi":"năng lượng sạch"},{"en":"clean the kitchen","vi":"dọn dẹp nhà bếp"}],"wordFamily":["cleaner (n.)","cleanliness (n.)","cleanly (adv.)","unclean (adj.)"],"synonyms":["spotless","wash"],"antonyms":["dirty","polluted"],"tipVi":"clean mang nghĩa sạch sẽ; clear mang nghĩa trong suốt hoặc rõ ràng, hai từ này không thể dùng thay thế cho nhau một cách tùy tiện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_name', 'en-a1-22', 'name', '/neɪm/', 'A1', 'tên; danh nghĩa; đặt tên; gọi tên; nêu tên; danh tiếng; tiếng tăm', 'n.', 'nameless (adj.), rename (v.)', NULL, 'Cấu trúc name A after B trong tiếng Anh-Anh mang nghĩa đặt tên của A theo tên của B.', 'What name did you choose for your new kitten?', NULL, 'Bạn đã chọn cái tên nào cho chú mèo con mới của mình vậy?', '{"wordId":"name","ukIpa":"/neɪm/","usIpa":"/neɪm/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a word or words used to identify someone or something","vi":"tên; danh nghĩa"},{"pos":"v.","en":"to give a name or say what someone is called","vi":"đặt tên; gọi tên; nêu tên"},{"pos":"n.","en":"the reputation someone or something has","vi":"danh tiếng; tiếng tăm"}],"examples":[{"en":"What name did you choose for your new kitten?","vi":"Bạn đã chọn cái tên nào cho chú mèo con mới của mình vậy?","audioKind":"ex"},{"en":"Companies often choose a memorable name to distinguish their products in an increasingly competitive market.","vi":"Các công ty thường chọn một cái tên dễ nhớ để làm nổi bật sản phẩm của họ trong một thị trường ngày càng cạnh tranh khốc liệt.","audioKind":"ex2"}],"collocations":[{"en":"full name","vi":"họ tên đầy đủ"},{"en":"brand name","vi":"tên thương hiệu"},{"en":"name after","vi":"đặt tên theo"},{"en":"make a name for yourself","vi":"tạo dựng tên tuổi cho bản thân"}],"wordFamily":["nameless (adj.)","rename (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc name A after B trong tiếng Anh-Anh mang nghĩa đặt tên của A theo tên của B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_often', 'en-a1-22', 'often', '/ˈɔːfən/', 'A1', 'thường; thường xuyên', 'adv.', NULL, 'Đồng nghĩa: frequently · Trái nghĩa: rarely, seldom', 'Trạng từ này thường đứng trước động từ thường và đứng sau động từ to be; âm t đôi khi cũng được phát âm trong một số ngữ cảnh.', 'We often walk by the river after dinner.', NULL, 'Chúng tôi thường đi dạo dọc bờ sông sau bữa tối.', '{"wordId":"often","ukIpa":"/ˈɒfən/","usIpa":"/ˈɔːfən/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"many times or on many occasions","vi":"thường; thường xuyên"}],"examples":[{"en":"We often walk by the river after dinner.","vi":"Chúng tôi thường đi dạo dọc bờ sông sau bữa tối.","audioKind":"ex"},{"en":"People who exercise regularly often report better sleep and higher energy levels throughout the day.","vi":"Những người tập thể dục đều đặn thường cho biết họ ngủ ngon hơn và có nhiều năng lượng hơn trong suốt cả ngày.","audioKind":"ex2"}],"collocations":[{"en":"quite often","vi":"khá thường xuyên"},{"en":"more often","vi":"thường xuyên hơn"},{"en":"how often","vi":"tần suất như thế nào"},{"en":"as often as possible","vi":"càng thường xuyên càng tốt"}],"wordFamily":[],"synonyms":["frequently"],"antonyms":["rarely","seldom"],"tipVi":"Trạng từ này thường đứng trước động từ thường và đứng sau động từ to be; âm t đôi khi cũng được phát âm trong một số ngữ cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_it', 'en-a1-22', 'it', '/ɪt/', 'A1', 'nó; điều đó; làm chủ ngữ hoặc tân ngữ giả', 'pron.', NULL, NULL, 'Chữ it viết thường là đại từ; chữ IT viết hoa mới chỉ công nghệ thông tin.', 'I found your scarf and put it by the door.', NULL, 'Tôi tìm thấy chiếc khăn choàng cổ của bạn và đã để nó ở gần cửa.', '{"wordId":"it","ukIpa":"/ɪt/","usIpa":"/ɪt/","cefr":"A1","topic":"daily","senses":[{"pos":"pron.","en":"refers to a thing, animal, or situation already mentioned","vi":"nó; điều đó"},{"pos":"pron.","en":"used as a grammatical subject or object without naming anything","vi":"làm chủ ngữ hoặc tân ngữ giả"}],"examples":[{"en":"I found your scarf and put it by the door.","vi":"Tôi tìm thấy chiếc khăn choàng cổ của bạn và đã để nó ở gần cửa.","audioKind":"ex"},{"en":"It is essential for cities to provide reliable public transport if they want to reduce traffic congestion.","vi":"Việc các thành phố cung cấp hệ thống giao thông công cộng đáng tin cậy là điều cốt yếu nếu họ muốn giảm thiểu tình trạng ùn tắc giao thông.","audioKind":"ex2"}],"collocations":[{"en":"it depends","vi":"tùy tình hình; tùy trường hợp"},{"en":"it seems that","vi":"dường như là; có vẻ như"},{"en":"make it clear","vi":"làm cho rõ ràng; nói rõ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chữ it viết thường là đại từ; chữ IT viết hoa mới chỉ công nghệ thông tin.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_baby', 'en-a1-22', 'baby', '/ˈbeɪbi/', 'A1', 'em bé; trẻ sơ sinh; con non; thuộc về trẻ sơ sinh; nhỏ tuổi; chiều chuộng; đối xử như trẻ con', 'n.', 'babyhood (n.), babyish (adj.)', 'Đồng nghĩa: infant', 'Số nhiều là babies; baby khi làm động từ thường mang hàm ý "chăm sóc quá mức".', 'The baby fell asleep while her father sang softly.', NULL, 'Em bé đã chìm vào giấc ngủ trong lúc bố em hát khẽ.', '{"wordId":"baby","ukIpa":"/ˈbeɪbi/","usIpa":"/ˈbeɪbi/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a very young child or animal","vi":"em bé; trẻ sơ sinh; con non"},{"pos":"adj.","en":"very young, or intended for babies","vi":"thuộc về trẻ sơ sinh; nhỏ tuổi"},{"pos":"v.","en":"treat someone as helpless or needing excessive care","vi":"chiều chuộng; đối xử như trẻ con"}],"examples":[{"en":"The baby fell asleep while her father sang softly.","vi":"Em bé đã chìm vào giấc ngủ trong lúc bố em hát khẽ.","audioKind":"ex"},{"en":"Affordable childcare helps parents of young babies return to work without placing excessive pressure on family finances.","vi":"Dịch vụ chăm sóc trẻ em với chi phí phải chăng giúp các bậc phụ huynh có con nhỏ quay trở lại làm việc mà không tạo ra áp lực quá lớn lên tài chính gia đình.","audioKind":"ex2"}],"collocations":[{"en":"newborn baby","vi":"trẻ sơ sinh"},{"en":"have a baby","vi":"sinh con"},{"en":"baby food","vi":"thức ăn cho trẻ em"},{"en":"baby clothes","vi":"quần áo trẻ em"}],"wordFamily":["babyhood (n.)","babyish (adj.)"],"synonyms":["infant"],"antonyms":[],"tipVi":"Số nhiều là babies; baby khi làm động từ thường mang hàm ý \"chăm sóc quá mức\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_water', 'en-a1-22', 'water', '/ˈwɔːtər/', 'A1', 'nước; tưới nước', 'n.', 'watery (adj.), waterless (adj.)', NULL, 'Danh từ chỉ nước thường không đếm được: a glass of water là một cốc nước.', 'Please water the plants before we leave today.', NULL, 'Làm ơn hãy tưới nước cho mấy chậu cây trước khi chúng ta rời đi hôm nay.', '{"wordId":"water","ukIpa":"/ˈwɔːtə/","usIpa":"/ˈwɔːtər/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The clear liquid people drink and plants need to grow.","vi":"nước"},{"pos":"v.","en":"To give water to plants or soil.","vi":"tưới nước"}],"examples":[{"en":"Please water the plants before we leave today.","vi":"Làm ơn hãy tưới nước cho mấy chậu cây trước khi chúng ta rời đi hôm nay.","audioKind":"ex"},{"en":"Access to clean drinking water is essential for preventing disease and improving public health.","vi":"Khả năng tiếp cận nguồn nước uống sạch là điều tối quan trọng để phòng ngừa bệnh tật và nâng cao sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"drinking water","vi":"nước uống"},{"en":"running water","vi":"nước máy; nước chảy"},{"en":"water shortage","vi":"tình trạng thiếu nước"},{"en":"water the garden","vi":"tưới nước cho vườn"}],"wordFamily":["watery (adj.)","waterless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ chỉ nước thường không đếm được: a glass of water là một cốc nước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_half', 'en-a1-22', 'half', '/hæf/', 'A1', 'một nửa; nửa; một nửa; một phần; nửa chừng', 'n.', 'halve (v.), halves (n.)', NULL, 'Số nhiều là halves; cụm từ "nửa giờ" dùng là half an hour.', 'I saved half of my sandwich for later.', NULL, 'Tôi đã để dành lại một nửa chiếc bánh mì kẹp của mình để ăn sau.', '{"wordId":"half","ukIpa":"/hɑːf/","usIpa":"/hæf/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"one of two equal parts of something","vi":"một nửa; nửa"},{"pos":"det.","en":"equal to one of two equal parts of something","vi":"một nửa"},{"pos":"adv.","en":"to an extent that is not complete","vi":"một phần; nửa chừng"}],"examples":[{"en":"I saved half of my sandwich for later.","vi":"Tôi đã để dành lại một nửa chiếc bánh mì kẹp của mình để ăn sau.","audioKind":"ex"},{"en":"Nearly half of the residents surveyed supported creating more green spaces in the city centre.","vi":"Gần một nửa số cư dân được khảo sát ủng hộ việc tạo thêm không gian xanh ở khu1 vực trung tâm thành phố.","audioKind":"ex2"}],"collocations":[{"en":"half an hour","vi":"nửa tiếng; nửa giờ"},{"en":"half of","vi":"một nửa của"},{"en":"half price","vi":"giá nửa tiền; nửa giá"},{"en":"half asleep","vi":"nửa tỉnh nửa mê"}],"wordFamily":["halve (v.)","halves (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Số nhiều là halves; cụm từ \"nửa giờ\" dùng là half an hour.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_knife', 'en-a1-22', 'knife', '/naɪf/', 'A1', 'con dao', 'n.', 'knives (n.)', NULL, 'Âm k ở đầu không phát âm; số nhiều đổi đuôi -fe thành -ves: knives.', 'Use a sharp knife to slice the bread.', NULL, 'Hãy dùng một con dao sắc bén để thái bánh mì thành từng lát.', '{"wordId":"knife","ukIpa":"/naɪf/","usIpa":"/naɪf/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a tool with a handle and blade used for cutting","vi":"con dao"}],"examples":[{"en":"Use a sharp knife to slice the bread.","vi":"Hãy dùng một con dao sắc bén để thái bánh mì thành từng lát.","audioKind":"ex"},{"en":"Learning to use a kitchen knife safely is an important part of practical food education.","vi":"Học cách sử dụng dao nhà bếp một cách an toàn là một phần quan trọng trong giáo dục kỹ năng nội trợ thực tế.","audioKind":"ex2"}],"collocations":[{"en":"kitchen knife","vi":"dao thái bếp"},{"en":"sharp knife","vi":"dao sắc"},{"en":"bread knife","vi":"dao cắt bánh mì"},{"en":"knife and fork","vi":"dao và nĩa"}],"wordFamily":["knives (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Âm k ở đầu không phát âm; số nhiều đổi đuôi -fe thành -ves: knives.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thanks', 'en-a1-22', 'thanks', '/θæŋks/', 'A1', 'cảm ơn; lời cảm ơn; sự biết ơn', 'int.', 'thank (v.), thankful (adj.), thankfully (adv.), thankfulness (n.)', 'Đồng nghĩa: thank you', 'thanks for đi sau với danh từ hoặc danh động từ; thanks to mang nghĩa là nhờ có.', 'Thanks for helping me carry these heavy bags upstairs.', NULL, 'Cảm ơn bạn đã giúp tôi khiêng những chiếc túi nặng này lên lầu.', '{"wordId":"thanks","ukIpa":"/θæŋks/","usIpa":"/θæŋks/","cefr":"A1","topic":"daily","senses":[{"pos":"int.","en":"used to tell someone you are grateful","vi":"cảm ơn"},{"pos":"n.","en":"words or actions expressing gratitude","vi":"lời cảm ơn; sự biết ơn"}],"examples":[{"en":"Thanks for helping me carry these heavy bags upstairs.","vi":"Cảm ơn bạn đã giúp tôi khiêng những chiếc túi nặng này lên lầu.","audioKind":"ex"},{"en":"Public expressions of thanks can help volunteers feel valued and encourage continued participation in community projects.","vi":"Việc công khai bày tỏ lời cảm ơn có thể giúp các tình nguyện viên cảm thấy được trân trọng và khuyến khích họ tiếp tục tham gia vào các dự án cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"thanks for your help","vi":"cảm ơn sự giúp đỡ của bạn"},{"en":"many thanks","vi":"vô cùng cảm ơn"},{"en":"express thanks","vi":"bày tỏ lòng biết ơn"},{"en":"thanks to","vi":"nhờ có; do"}],"wordFamily":["thank (v.)","thankful (adj.)","thankfully (adv.)","thankfulness (n.)"],"synonyms":["thank you"],"antonyms":[],"tipVi":"thanks for đi sau với danh từ hoặc danh động từ; thanks to mang nghĩa là nhờ có.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 28, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_22_1', 'en-a1-22', 'Cách dùng “clean” (adj.) — sạch sẽ; không vấy bẩn', 'keep clean  ·  clean water  ·  clean energy', 'clean mang nghĩa sạch sẽ; clear mang nghĩa trong suốt hoặc rõ ràng, hai từ này không thể dùng thay thế cho nhau một cách tùy tiện.', 'Họ từ (Word Family): cleaner (n.), cleanliness (n.), cleanly (adv.), unclean (adj.) | Đồng nghĩa: spotless, wash | Trái nghĩa: dirty, polluted', '[{"hanzi":"There are clean towels on the shelf beside you.","pinyin":"","meaning":"Có những chiếc khăn tắm sạch đặt trên giá ở cạnh bạn kìa."},{"hanzi":"Investing in clean energy can reduce air pollution while creating new employment opportunities in developing industries.","pinyin":"","meaning":"Đầu tư vào năng lượng sạch có thể làm giảm ô nhiễm không khí đồng thời tạo ra các cơ hội việc làm mới trong các ngành công nghiệp đang phát triển."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_22_2', 'en-a1-22', 'Cách dùng “often” (adv.) — thường; thường xuyên', 'quite often  ·  more often  ·  how often', 'Trạng từ này thường đứng trước động từ thường và đứng sau động từ to be; âm t đôi khi cũng được phát âm trong một số ngữ cảnh.', 'Đồng nghĩa: frequently | Trái nghĩa: rarely, seldom', '[{"hanzi":"We often walk by the river after dinner.","pinyin":"","meaning":"Chúng tôi thường đi dạo dọc bờ sông sau bữa tối."},{"hanzi":"People who exercise regularly often report better sleep and higher energy levels throughout the day.","pinyin":"","meaning":"Những người tập thể dục đều đặn thường cho biết họ ngủ ngon hơn và có nhiều năng lượng hơn trong suốt cả ngày."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_22_3', 'en-a1-22', 'Cách dùng “feet” (n.) — bàn chân', 'bare feet  ·  on your feet  ·  six feet tall', 'foot có số nhiều là feet; khi đóng vai trò làm tính từ bổ nghĩa phía trước thì dùng dạng số ít, ví dụ như six-foot.', 'Họ từ (Word Family): foot (n.)', '[{"hanzi":"My feet felt cold against the kitchen tiles.","pinyin":"","meaning":"Bàn chân tôi thấy lạnh khi chạm vào nền gạch trong bếp."},{"hanzi":"Designing comfortable footwear can protect the feet of workers who spend most of their day standing.","pinyin":"","meaning":"Việc thiết kế giày dép thoải mái có thể bảo vệ đôi chân của những công nhân phải đứng làm việc gần như cả ngày."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_22_4', 'en-a1-22', 'Cách dùng “wash” (v.) — rửa; giặt; tẩy rửa', 'wash your hands  ·  wash the dishes  ·  wash away', 'wash nhấn mạnh việc làm sạch bằng nước; clean mang nghĩa tổng quát là làm sạch và không nhất thiết phải dùng nước.', 'Họ từ (Word Family): washing (n.), washable (adj.), unwashed (adj.) | Đồng nghĩa: clean, cleanse', '[{"hanzi":"Please wash your hands before you help prepare dinner.","pinyin":"","meaning":"Vui lòng rửa tay trước khi bạn giúp chuẩn bị bữa tối."},{"hanzi":"Schools should teach children to wash their hands properly to reduce the spread of infectious diseases.","pinyin":"","meaning":"Nhà trường nên dạy học sinh cách rửa tay đúng cách để giảm thiểu sự lây lan của các bệnh truyền nhiễm."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
