INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_22_1_8', 'ten_22_1', 'cake', 'We shared a slice of lemon cake after lunch.', 'We shared a slice of lemon cake after lunch.', '/keɪk/', 'Chúng tôi chia nhau một miếng bánh chanh sau bữa trưa.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_22_1_1', 'en-a1-22', 'ten_22_1', 'listening', 'listening', 'We made a small table from leftover pieces of wood.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã có một buổi dã ngoại thật vui bên bờ hồ.","Chúng tôi đã làm một chiếc bàn nhỏ từ những mảnh gỗ thừa.","Chúng tôi chia nhau một miếng bánh chanh sau bữa trưa.","Hãy thêm một chút sữa nếu súp quá đặc."]'::jsonb, 1, 'We made a small table from leftover pieces of wood. → Chúng tôi đã làm một chiếc bàn nhỏ từ những mảnh gỗ thừa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_22_1_2', 'en-a1-22', 'ten_22_1', 'listening', 'listening', 'Every child brought a favourite toy to the picnic.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Mỗi đứa trẻ đều mang theo một món đồ chơi yêu thích đến buổi dã ngoại.","Hãy cất giữ các tài liệu quan trọng của bạn trong chiếc cặp chống nước này.","Chúng tôi đã làm một chiếc bàn nhỏ từ những mảnh gỗ thừa.","Ngôi nhà trở nên yên tĩnh sau khi bọn trẻ đã ngủ say."]'::jsonb, 0, 'Every child brought a favourite toy to the picnic. → Mỗi đứa trẻ đều mang theo một món đồ chơi yêu thích đến buổi dã ngoại.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_22_1_3', 'en-a1-22', 'ten_22_1', 'listening', 'listening', 'The house was quiet after the children fell asleep.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi chia nhau một miếng bánh chanh sau bữa trưa.","Tôi bị muộn vì xe đạp bị thủng lốp.","Mỗi đứa trẻ đều mang theo một món đồ chơi yêu thích đến buổi dã ngoại.","Ngôi nhà trở nên yên tĩnh sau khi bọn trẻ đã ngủ say."]'::jsonb, 3, 'The house was quiet after the children fell asleep. → Ngôi nhà trở nên yên tĩnh sau khi bọn trẻ đã ngủ say.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_22_2', 'en-a1-22', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_22_2_1', 'ten_22_2', 'make', 'Schools can make science more accessible by allowing students to conduct simple experiments with everyday materials.', 'Schools can make science more accessible by allowing students to conduct simple experiments with everyday materials.', '/meɪk/', 'Nhà trường có thể giúp môn khoa học trở nên dễ tiếp cận hơn bằng cách cho phép học sinh thực hiện các thí nghiệm đơn giản với những vật liệu hằng ngày.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_22_2_2', 'ten_22_2', 'every', 'Governments should ensure that every student has access to reliable internet services for learning.', 'Governments should ensure that every student has access to reliable internet services for learning.', '/ˈevri/', 'Chính phủ nên đảm bảo rằng mọi học sinh đều có thể tiếp cận các dịch vụ internet đáng tin cậy để phục vụ việc học tập.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_22_2_3', 'ten_22_2', 'quiet', 'Quiet study spaces in public libraries are essential for students who cannot concentrate at home.', 'Quiet study spaces in public libraries are essential for students who cannot concentrate at home.', '/ˈkwaɪət/', 'Không gian học tập yên tĩnh trong các thư viện công cộng rất cần thiết cho những học sinh không thể tập trung ở nhà.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_22_2_4', 'ten_22_2', 'add', 'Adding more green spaces to urban neighbourhoods can improve residents'' wellbeing and provide habitats for wildlife.', 'Adding more green spaces to urban neighbourhoods can improve residents'' wellbeing and provide habitats for wildlife.', '/æd/', 'Việc bổ sung thêm nhiều không gian xanh vào các khu dân cư đô thị có thể cải thiện sức khỏe tinh thần và thể chất của người dân, đồng thời cung cấp môi trường sống cho động vật hoang dã.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_22_2_5', 'ten_22_2', 'nice', 'Although nice surroundings matter, affordable housing and reliable transport are more important to many urban residents.', 'Although nice surroundings matter, affordable housing and reliable transport are more important to many urban residents.', '/naɪs/', 'Mặc dù môi trường sống dễ chịu rất quan trọng, nhưng nhà ở giá cả phải chăng và giao thông đáng tin cậy còn quan trọng hơn đối với nhiều cư dân đô thị.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_22_2_6', 'ten_22_2', 'important', 'Access to reliable information plays an important role in helping citizens make informed decisions about their health.', 'Access to reliable information plays an important role in helping citizens make informed decisions about their health.', '/ɪmˈpɔːrtənt/', 'Việc tiếp cận thông tin đáng tin cậy đóng vai trò quan trọng trong việc giúp công dân đưa ra các quyết định sáng suốt về sức khỏe của họ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
