INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_22_2', 'en-a1-22', NULL, 'comprehensive_test', 'listening', 'Every child brought a favourite toy to the picnic.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi cuộn tròn người trên chiếc ghế sô-fa sau bữa tối.","Bạn đã chọn cái tên nào cho chú mèo con mới của mình vậy?","Mỗi đứa trẻ đều mang theo một món đồ chơi yêu thích đến buổi dã ngoại.","Bữa tối của chúng tôi có cơm và cá hấp."]'::jsonb, 2, 'Every child brought a favourite toy to the picnic. → Mỗi đứa trẻ đều mang theo một món đồ chơi yêu thích đến buổi dã ngoại.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
