INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_22_4', 'en-a1-22', NULL, 'comprehensive_test', 'listening', 'Add a little milk if the soup is too thick.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bàn chân tôi thấy lạnh khi chạm vào nền gạch trong bếp.","Hãy thêm một chút sữa nếu súp quá đặc.","Bạn đã chọn cái tên nào cho chú mèo con mới của mình vậy?","Vui lòng rửa tay trước khi bạn giúp chuẩn bị bữa tối."]'::jsonb, 1, 'Add a little milk if the soup is too thick. → Hãy thêm một chút sữa nếu súp quá đặc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_22_5', 'en-a1-22', NULL, 'comprehensive_test', 'listening', 'nice', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tốt đẹp; dễ chịu; thú vị","nhà văn; tác giả; người viết sách, bài báo hoặc các văn bản khác","có thể xảy ra; có thể thực hiện được","hai lần"]'::jsonb, 0, 'nice (/naɪs/) → tốt đẹp; dễ chịu; thú vị; tử tế; thân thiện', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_22_6', 'en-a1-22', NULL, 'comprehensive_test', 'listening', 'Keep your important documents in this waterproof folder.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hãy cất giữ các tài liệu quan trọng của bạn trong chiếc cặp chống nước này.","Ông của tôi mặc một chiếc áo khoác màu xám vào mỗi mùa đông.","Bàn chân tôi thấy lạnh khi chạm vào nền gạch trong bếp.","Chúng tôi thường cùng nhau nấu bữa tối ở nhà vào ngày thứ Sáu."]'::jsonb, 0, 'Keep your important documents in this waterproof folder. → Hãy cất giữ các tài liệu quan trọng của bạn trong chiếc cặp chống nước này.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_22_7', 'en-a1-22', NULL, 'comprehensive_test', 'listening', 'late', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cho đến khi","sân bay","muộn; trễ","câu"]'::jsonb, 2, 'late (/leɪt/) → muộn; trễ; muộn; trễ (về thời gian); quá cố; đã qua đời (dùng trước danh từ chỉ người)', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_22_8', 'en-a1-22', NULL, 'comprehensive_test', 'listening', 'We shared a slice of lemon cake after lunch.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã làm một chiếc bàn nhỏ từ những mảnh gỗ thừa.","Cảm ơn bạn đã giúp tôi khiêng những chiếc túi nặng này lên lầu.","Chúng tôi chia nhau một miếng bánh chanh sau bữa trưa.","Làm ơn hãy tưới nước cho mấy chậu cây trước khi chúng ta rời đi hôm nay."]'::jsonb, 2, 'We shared a slice of lemon cake after lunch. → Chúng tôi chia nhau một miếng bánh chanh sau bữa trưa.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_22_9', 'en-a1-22', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “pleasant or enjoyable”?', '["wash","rice","water","nice"]'::jsonb, 3, 'nice (/naɪs/) → tốt đẹp; dễ chịu; thú vị', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
