INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_22_18', 'en-a1-22', NULL, 'comprehensive_test', 'reading', NULL, 'Schools can make science more accessible by allowing students to conduct simple experiments with everyday materials.', 'Dựa vào câu trên, từ “make” có nghĩa phù hợp nhất là gì?', '["hồ bơi; vũng nước","làm; chế tạo; sản xuất","gọi điện thoại cho ai đó hoặc hét lên để thu hút sự chú ý","tốt nhất; tối ưu"]'::jsonb, 1, 'make: làm; chế tạo; sản xuất; khiến; bắt buộc; thương hiệu; nhãn hiệu; kiểu máy. Dịch cả câu: Nhà trường có thể giúp môn khoa học trở nên dễ tiếp cận hơn bằng cách cho phép học sinh thực hiện các thí nghiệm đơn giản với những vật liệu hằng ngày.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_22_19', 'en-a1-22', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should ensure that every student has access to reliable internet services for learning.', 'Dựa vào câu trên, từ “every” có nghĩa phù hợp nhất là gì?', '["hướng đông; phía đông","mỗi; mọi","cần; đòi hỏi","con gái"]'::jsonb, 1, 'every: mỗi; mọi; cứ mỗi; cách mỗi; tất cả; mọi (nhấn mạnh mức độ cao nhất). Dịch cả câu: Chính phủ nên đảm bảo rằng mọi học sinh đều có thể tiếp cận các dịch vụ internet đáng tin cậy để phục vụ việc học tập.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_22_20', 'en-a1-22', NULL, 'comprehensive_test', 'reading', NULL, 'Quiet study spaces in public libraries are essential for students who cannot concentrate at home.', 'Dựa vào câu trên, từ “quiet” có nghĩa phù hợp nhất là gì?', '["yên tĩnh; im ắng","kém; tồi; chất lượng không tốt hoặc không đạt yêu cầu","áo sơ mi","ví dụ; dẫn chứng"]'::jsonb, 0, 'quiet: yên tĩnh; im ắng; thanh bình; ít nhộn nhịp; sự yên tĩnh; sự thanh bình. Dịch cả câu: Không gian học tập yên tĩnh trong các thư viện công cộng rất cần thiết cho những học sinh không thể tập trung ở nhà.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_22_21', 'en-a1-22', NULL, 'comprehensive_test', 'reading', NULL, 'Adding more green spaces to urban neighbourhoods can improve residents'' wellbeing and provide habitats for wildlife.', 'Dựa vào câu trên, từ “add” có nghĩa phù hợp nhất là gì?', '["được yêu thích nhất (hơn bất kỳ thứ gì cùng loại)","mọi người; tất cả mọi người","nghĩ; cho rằng","thêm vào; bổ sung"]'::jsonb, 3, 'add: thêm vào; bổ sung; cộng; làm phép cộng; nói thêm; bổ sung ý. Dịch cả câu: Việc bổ sung thêm nhiều không gian xanh vào các khu dân cư đô thị có thể cải thiện sức khỏe tinh thần và thể chất của người dân, đồng thời cung cấp môi trường sống cho động vật hoang dã.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
