INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-23', 'en', 'Bài 23: Đời sống hằng ngày (8) - CEFR A1', 'CEFR A1', 'A1 · Đời sống', '27 từ vựng Tiếng Anh CEFR A1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1023, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bread', 'en-a1-23', 'bread', '/bred/', 'A1', 'bánh mì', 'n.', 'breadcrumbs (n.)', NULL, 'bread thường là danh từ không đếm được; để chỉ một phần nhỏ dùng cụm từ a slice of bread.', 'Fresh bread was cooling beside the kitchen window.', NULL, 'Ổ bánh mì mới ra lò đang được để nguội ngay bên khung cửa sổ nhà bếp.', '{"wordId":"bread","ukIpa":"/bred/","usIpa":"/bred/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a food made from flour and water, usually baked","vi":"bánh mì"}],"examples":[{"en":"Fresh bread was cooling beside the kitchen window.","vi":"Ổ bánh mì mới ra lò đang được để nguội ngay bên khung cửa sổ nhà bếp.","audioKind":"ex"},{"en":"Choosing wholegrain bread instead of refined varieties can increase fibre intake and support a balanced diet.","vi":"Việc lựa chọn bánh mì nguyên cám thay vì các loại bánh mì tinh chế có thể giúp tăng lượng chất xơ nạp vào và hỗ trợ một chế độ ăn uống cân bằng.","audioKind":"ex2"}],"collocations":[{"en":"a loaf of bread","vi":"một ổ bánh mì"},{"en":"a slice of bread","vi":"một lát bánh mì"},{"en":"wholemeal bread","vi":"bánh mì lúa mạch đen nguyên hạt"},{"en":"bake bread","vi":"nướng bánh mì"}],"wordFamily":["breadcrumbs (n.)"],"synonyms":[],"antonyms":[],"tipVi":"bread thường là danh từ không đếm được; để chỉ một phần nhỏ dùng cụm từ a slice of bread.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_between', 'en-a1-23', 'between', '/bɪˈtwiːn/', 'A1', 'ở giữa; trong khoảng thời gian giữa; giữa (các bên); chung giữa; ở khoảng giữa', 'prep.', NULL, NULL, 'Từ between không chỉ giới hạn ở hai đối tượng, mà còn có thể dùng cho nhiều đối tượng riêng biệt khác nhau.', 'The cat squeezed between the sofa and the wall.', NULL, 'Con mèo luồn lách vào khe giữa chiếc ghế sofa và bức tường.', '{"wordId":"between","ukIpa":"/bɪˈtwiːn/","usIpa":"/bɪˈtwiːn/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"In the space or period separating people, things, or events.","vi":"ở giữa; trong khoảng thời gian giữa"},{"pos":"prep.","en":"Connecting distinct people or groups, or shared by them.","vi":"giữa (các bên); chung giữa"},{"pos":"adv.","en":"In the space or interval separating things.","vi":"ở khoảng giữa"}],"examples":[{"en":"The cat squeezed between the sofa and the wall.","vi":"Con mèo luồn lách vào khe giữa chiếc ghế sofa và bức tường.","audioKind":"ex"},{"en":"Cooperation between schools and local businesses can help students develop practical skills before entering employment.","vi":"Sự hợp tác giữa các trường học và doanh nghiệp địa phương có thể giúp học sinh phát triển các kỹ năng thực tế trước khi bước chân vào thị trường lao động.","audioKind":"ex2"}],"collocations":[{"en":"between meals","vi":"giữa các bữa ăn"},{"en":"a link between","vi":"mối liên hệ giữa"},{"en":"choose between","vi":"lựa chọn giữa"},{"en":"between them","vi":"giữa họ với nhau"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ between không chỉ giới hạn ở hai đối tượng, mà còn có thể dùng cho nhiều đối tượng riêng biệt khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eighteen', 'en-a1-23', 'eighteen', '/ˌeɪˈtiːn/', 'A1', 'mười tám', 'num.', 'eighteenth (num.)', NULL, 'eighteen là mười tám, còn eighty là tám mươi; hãy chú ý phần phát âm ở đuôi từ.', 'We baked eighteen muffins for the picnic this morning.', NULL, 'Chúng tôi đã nướng mười tám chiếc bánh nướng nhỏ cho buổi dã ngoại sáng nay.', '{"wordId":"eighteen","ukIpa":"/ˌeɪˈtiːn/","usIpa":"/ˌeɪˈtiːn/","cefr":"A1","topic":"daily","senses":[{"pos":"num.","en":"The number after seventeen and before nineteen.","vi":"mười tám"}],"examples":[{"en":"We baked eighteen muffins for the picnic this morning.","vi":"Chúng tôi đã nướng mười tám chiếc bánh nướng nhỏ cho buổi dã ngoại sáng nay.","audioKind":"ex"},{"en":"In many countries, citizens gain the right to vote when they reach the age of eighteen.","vi":"Ở nhiều quốc gia, công dân có được quyền bầu cử khi đủ mười tám tuổi.","audioKind":"ex2"}],"collocations":[{"en":"eighteen years old","vi":"mười tám tuổi"},{"en":"at eighteen","vi":"vào năm mươi tuổi / ở tuổi mười tám"},{"en":"under eighteen","vi":"dưới mười tám tuổi"}],"wordFamily":["eighteenth (num.)"],"synonyms":[],"antonyms":[],"tipVi":"eighteen là mười tám, còn eighty là tám mươi; hãy chú ý phần phát âm ở đuôi từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_time', 'en-a1-23', 'time', '/taɪm/', 'A1', 'thời gian; thời điểm; lần; lượt; đo thời gian; bấm giờ; chọn thời điểm', 'n.', 'timing (n.), timely (adj.), timeless (adj.), timer (n.)', NULL, 'Danh từ time thường không đếm được; khi mang nghĩa "lần" thì đếm được, ví dụ như three times.', 'We still have time for a walk before dinner.', NULL, 'Chúng tôi vẫn còn thời gian để đi dạo trước bữa tối.', '{"wordId":"time","ukIpa":"/taɪm/","usIpa":"/taɪm/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"what clocks measure, or a particular point in its passage","vi":"thời gian; thời điểm"},{"pos":"n.","en":"an occasion when something happens","vi":"lần; lượt"},{"pos":"v.","en":"to measure duration or choose when something should happen","vi":"đo thời gian; bấm giờ; chọn thời điểm"}],"examples":[{"en":"We still have time for a walk before dinner.","vi":"Chúng tôi vẫn còn thời gian để đi dạo trước bữa tối.","audioKind":"ex"},{"en":"Schools should give students enough time to explore creative activities alongside their preparation for formal examinations.","vi":"Nhà trường nên cho học sinh đủ thời gian để khám phá các hoạt động sáng tạo bên cạnh việc chuẩn bị cho các kỳ thi chính thức.","audioKind":"ex2"}],"collocations":[{"en":"spend time doing something","vi":"dành thời gian làm việc gì"},{"en":"on time","vi":"đúng giờ"},{"en":"in time","vi":"kịp lúc"},{"en":"time management","vi":"quản lý thời gian"}],"wordFamily":["timing (n.)","timely (adj.)","timeless (adj.)","timer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ time thường không đếm được; khi mang nghĩa \"lần\" thì đếm được, ví dụ như three times.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bathroom', 'en-a1-23', 'bathroom', '/ˈbæθruːm/', 'A1', 'phòng tắm; phòng vệ sinh; phòng vệ sinh; nhà vệ sinh', 'n.', NULL, NULL, 'Trong tiếng Mỹ, bathroom cũng có thể chỉ nhà vệ sinh không có bồn tắm.', 'She hung a clean towel beside the bathroom sink.', NULL, 'Cô ấy treo một chiếc khăn sạch bên cạnh bồn rửa trong phòng tắm.', '{"wordId":"bathroom","ukIpa":"/ˈbɑːθruːm/","usIpa":"/ˈbæθruːm/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A room with a bath or shower, often including a toilet.","vi":"phòng tắm; phòng vệ sinh"},{"pos":"n.","en":"A room containing a toilet, especially in American English.","vi":"phòng vệ sinh; nhà vệ sinh"}],"examples":[{"en":"She hung a clean towel beside the bathroom sink.","vi":"Cô ấy treo một chiếc khăn sạch bên cạnh bồn rửa trong phòng tắm.","audioKind":"ex"},{"en":"Installing water-saving fixtures in the bathroom can help households reduce consumption without changing their daily routines.","vi":"Việc lắp đặt các thiết bị tiết kiệm nước trong phòng tắm có thể giúp các hộ gia đình giảm lượng nước tiêu thụ mà không làm thay đổi thói quen sinh hoạt hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"private bathroom","vi":"phòng tắm riêng"},{"en":"shared bathroom","vi":"phòng tắm chung"},{"en":"bathroom sink","vi":"bồn rửa trong phòng tắm"},{"en":"go to the bathroom","vi":"đi vệ sinh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Mỹ, bathroom cũng có thể chỉ nhà vệ sinh không có bồn tắm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_favorite', 'en-a1-23', 'favorite', '/ˈfeɪvərɪt/', 'A1', 'được ưa chuộng nhất; yêu thích nhất; người hoặc vật được yêu thích nhất; đối thủ được đánh giá cao nhất; ứng viên sáng giá cho chức vô địch', 'adj.', 'favor (n.), favor (v.), favorable (adj.), favoritism (n.)', 'Đồng nghĩa: preferred', 'Favorite là cách viết kiểu Mỹ, tiếng Anh-Anh là favourite; thông thường không dùng most đi trước từ này.', 'This blue sweater is my favorite winter item.', NULL, 'Chiếc áo len màu xanh này là món đồ mùa đông yêu thích của tôi.', '{"wordId":"favorite","ukIpa":"/ˈfeɪvərɪt/","usIpa":"/ˈfeɪvərɪt/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Liked or preferred more than others","vi":"được ưa chuộng nhất; yêu thích nhất"},{"pos":"n.","en":"A person or thing someone likes best","vi":"người hoặc vật được yêu thích nhất"},{"pos":"n.","en":"A competitor considered most likely to win","vi":"đối thủ được đánh giá cao nhất; ứng viên sáng giá cho chức vô địch"}],"examples":[{"en":"This blue sweater is my favorite winter item.","vi":"Chiếc áo len màu xanh này là món đồ mùa đông yêu thích của tôi.","audioKind":"ex"},{"en":"Surveys of children''s favorite leisure activities can help local authorities design more appealing public recreation spaces.","vi":"Các cuộc khảo sát về hoạt động giải trí yêu thích của trẻ em có thể giúp chính quyền địa phương thiết kế các không gian giải trí công cộng hấp dẫn hơn.","audioKind":"ex2"}],"collocations":[{"en":"a favorite pastime","vi":"thú tiêu khiển yêu thích"},{"en":"a firm favorite","vi":"người hoặc vật luôn được yêu thích"},{"en":"the clear favorite to win","vi":"ứng viên sáng giá nhất cho chiến thắng"}],"wordFamily":["favor (n.)","favor (v.)","favorable (adj.)","favoritism (n.)"],"synonyms":["preferred"],"antonyms":[],"tipVi":"Favorite là cách viết kiểu Mỹ, tiếng Anh-Anh là favourite; thông thường không dùng most đi trước từ này.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tea', 'en-a1-23', 'tea', '/tiː/', 'A1', 'trà; nước trà; lá trà khô; bữa xế; bữa tối nhẹ', 'n.', NULL, NULL, 'Nước trà thường là danh từ không đếm được; khi gọi món, two teas nghĩa là hai tách trà.', 'I made a pot of tea while you rested.', NULL, 'Tôi đã pha một ấm trà trong lúc bạn nghỉ ngơi.', '{"wordId":"tea","ukIpa":"/tiː/","usIpa":"/tiː/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a drink made by putting tea leaves in hot water","vi":"trà; nước trà"},{"pos":"n.","en":"dried leaves used to make tea","vi":"lá trà khô"},{"pos":"n.","en":"a light afternoon meal or, in Britain, an early evening meal","vi":"bữa xế; bữa tối nhẹ"}],"examples":[{"en":"I made a pot of tea while you rested.","vi":"Tôi đã pha một ấm trà trong lúc bạn nghỉ ngơi.","audioKind":"ex"},{"en":"In many cultures, sharing tea provides an opportunity for conversation and strengthens relationships between generations.","vi":"Trong nhiều nền văn hóa, việc cùng nhau thưởng thức trà tạo cơ hội trò chuyện và thắt chặt tình cảm giữa các thế hệ.","audioKind":"ex2"}],"collocations":[{"en":"a cup of tea","vi":"một tách trà"},{"en":"make tea","vi":"pha trà"},{"en":"tea leaves","vi":"lá trà"},{"en":"afternoon tea","vi":"tiệc trà chiều"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nước trà thường là danh từ không đếm được; khi gọi món, two teas nghĩa là hai tách trà.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_change', 'en-a1-23', 'change', '/tʃeɪndʒ/', 'A1', 'thay đổi; đổi; quy đổi tiền tệ; sự thay đổi; sự biến đổi; tiền lẻ; tiền thối lại', 'v.', 'changeable (adj.), unchanged (adj.), changing (adj.)', 'Đồng nghĩa: alter', 'Khi mang nghĩa "tiền lẻ, tiền thối lại", từ này không đếm được, không dùng a change.', 'We changed our plans when the rain started falling.', NULL, 'Chúng tôi đã thay đổi kế hoạch khi trời bắt đầu đổ mưa.', '{"wordId":"change","ukIpa":"/tʃeɪndʒ/","usIpa":"/tʃeɪndʒ/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to become different, replace something, or exchange money","vi":"thay đổi; đổi; quy đổi tiền tệ"},{"pos":"n.","en":"an instance or process of becoming different","vi":"sự thay đổi; sự biến đổi"},{"pos":"n.","en":"coins, or money returned when you pay more than the price","vi":"tiền lẻ; tiền thối lại"}],"examples":[{"en":"We changed our plans when the rain started falling.","vi":"Chúng tôi đã thay đổi kế hoạch khi trời bắt đầu đổ mưa.","audioKind":"ex"},{"en":"Governments should change transport policies to encourage cycling and reduce dependence on private cars in cities.","vi":"Chính phủ nên điều chỉnh các chính sách giao thông để khuyến khích việc đi xe đạp và giảm sự phụ thuộc vào ô tô cá nhân tại các thành phố.","audioKind":"ex2"}],"collocations":[{"en":"change your mind","vi":"thay đổi ý kiến"},{"en":"climate change","vi":"biến đổi khí hậu"},{"en":"social change","vi":"thay đổi xã hội"},{"en":"small change","vi":"tiền lẻ"}],"wordFamily":["changeable (adj.)","unchanged (adj.)","changing (adj.)"],"synonyms":["alter"],"antonyms":[],"tipVi":"Khi mang nghĩa \"tiền lẻ, tiền thối lại\", từ này không đếm được, không dùng a change.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ready', 'en-a1-23', 'ready', '/ˈredi/', 'A1', 'sẵn sàng; đã chuẩn bị xong; sẵn lòng; sẵn sàng làm gì; sắp sửa làm gì', 'adj.', 'readiness (n.), readily (adv.)', 'Đồng nghĩa: prepared, willing · Trái nghĩa: unprepared', 'ready for đi với danh từ; ready to đi với động từ nguyên thể.', 'Dinner is ready, so please bring your plate.', NULL, 'Bữa tối đã sẵn sàng, xin mời bạn lấy đĩa của mình.', '{"wordId":"ready","ukIpa":"/ˈredi/","usIpa":"/ˈredi/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Prepared or available for use or action.","vi":"sẵn sàng; đã chuẩn bị xong"},{"pos":"adj.","en":"Willing to do something.","vi":"sẵn lòng; sẵn sàng làm gì"},{"pos":"adj.","en":"About to do something very soon.","vi":"sắp sửa làm gì"}],"examples":[{"en":"Dinner is ready, so please bring your plate.","vi":"Bữa tối đã sẵn sàng, xin mời bạn lấy đĩa của mình.","audioKind":"ex"},{"en":"Schools must ensure that students are ready to meet the demands of a rapidly changing workplace.","vi":"Các nhà trường phải đảm bảo rằng học sinh đã sẵn sàng đáp ứng các yêu cầu của một thị trường lao động đang thay đổi nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"ready for","vi":"sẵn sàng cho"},{"en":"ready to use","vi":"sẵn sàng để sử dụng"},{"en":"get ready","vi":"chuẩn bị sẵn sàng"},{"en":"ready and willing","vi":"sẵn lòng và sẵn sàng"}],"wordFamily":["readiness (n.)","readily (adv.)"],"synonyms":["prepared","willing"],"antonyms":["unprepared"],"tipVi":"ready for đi với danh từ; ready to đi với động từ nguyên thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_down', 'en-a1-23', 'down', '/daʊn/', 'A1', 'xuống dưới; ở vị trí thấp hơn; dọc theo; từ trên xuống dưới; buồn bã; chán nản', 'adv.', 'downward (adj.), downwards (adv.)', 'Trái nghĩa: up', 'down đi sau danh từ có thể đóng vai trò là giới từ; feel down diễn tả tâm trạng buồn bã, chán nản.', 'The cat jumped down from the kitchen table.', NULL, 'Con mèo nhảy xuống từ bàn bếp.', '{"wordId":"down","ukIpa":"/daʊn/","usIpa":"/daʊn/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"Towards or in a lower place or position.","vi":"xuống dưới; ở vị trí thấp hơn"},{"pos":"prep.","en":"Along something, or from a higher to a lower point.","vi":"dọc theo; từ trên xuống dưới"},{"pos":"adj.","en":"Feeling unhappy or discouraged.","vi":"buồn bã; chán nản"}],"examples":[{"en":"The cat jumped down from the kitchen table.","vi":"Con mèo nhảy xuống từ bàn bếp.","audioKind":"ex"},{"en":"As housing costs go up, the amount young adults can save often goes down.","vi":"Khi chi phí nhà ở tăng lên, số tiền mà những người trẻ tuổi có thể tiết kiệm thường giảm xuống.","audioKind":"ex2"}],"collocations":[{"en":"sit down","vi":"ngồi xuống"},{"en":"go down","vi":"giảm xuống"},{"en":"down the street","vi":"dọc theo con phố"},{"en":"feel down","vi":"cảm thấy buồn bã"}],"wordFamily":["downward (adj.)","downwards (adv.)"],"synonyms":[],"antonyms":["up"],"tipVi":"down đi sau danh từ có thể đóng vai trò là giới từ; feel down diễn tả tâm trạng buồn bã, chán nản.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_get', 'en-a1-23', 'get', '/ɡet/', 'A1', 'có được; nhận được; thu được; trở nên; trở thành; đến một nơi nào đó', 'v.', NULL, 'Đồng nghĩa: obtain, receive, become', 'Quá khứ là got; trong tiếng Anh-Mỹ, quá khứ phân từ đôi khi cũng dùng gotten.', 'I got a warm scarf for my birthday.', NULL, 'Tôi nhận được một chiếc khăn choàng cổ ấm áp vào dịp sinh nhật.', '{"wordId":"get","ukIpa":"/ɡet/","usIpa":"/ɡet/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To obtain or receive something.","vi":"có được; nhận được; thu được"},{"pos":"v.","en":"To become a particular way.","vi":"trở nên; trở thành"},{"pos":"v.","en":"To arrive at a place.","vi":"đến một nơi nào đó"}],"examples":[{"en":"I got a warm scarf for my birthday.","vi":"Tôi nhận được một chiếc khăn choàng cổ ấm áp vào dịp sinh nhật.","audioKind":"ex"},{"en":"Students from low-income families may struggle to get the financial support they need to complete university courses.","vi":"Học sinh từ các gia đình có thu nhập thấp có thể gặp khó khăn trong việc nhận được sự hỗ trợ tài chính cần thiết để hoàn thành các khóa học đại học.","audioKind":"ex2"}],"collocations":[{"en":"get a job","vi":"tìm được việc làm"},{"en":"get better","vi":"trở nên tốt hơn"},{"en":"get to school","vi":"đến trường"},{"en":"get permission","vi":"có được sự cho phép"}],"wordFamily":[],"synonyms":["obtain","receive","become"],"antonyms":[],"tipVi":"Quá khứ là got; trong tiếng Anh-Mỹ, quá khứ phân từ đôi khi cũng dùng gotten.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_but', 'en-a1-23', 'but', '/bʌt/', 'A1', 'nhưng; nhưng mà; song; trừ; ngoại trừ', 'conj.', NULL, NULL, 'although và but thường không được dùng chung trong cùng một câu.', 'The bag looks small, but it holds everything I need.', NULL, 'Chiếc túi trông có vẻ nhỏ, nhưng nó chứa được mọi thứ tôi cần.', '{"wordId":"but","ukIpa":"/bʌt/","usIpa":"/bʌt/","cefr":"A1","topic":"daily","senses":[{"pos":"conj.","en":"Used to connect contrasting ideas or correct an earlier statement.","vi":"nhưng; nhưng mà; song"},{"pos":"prep.","en":"Except for someone or something.","vi":"trừ; ngoại trừ"}],"examples":[{"en":"The bag looks small, but it holds everything I need.","vi":"Chiếc túi trông có vẻ nhỏ, nhưng nó chứa được mọi thứ tôi cần.","audioKind":"ex"},{"en":"Public transport can reduce traffic congestion, but services must be reliable enough to attract regular users.","vi":"Giao thông công cộng có thể làm giảm tình trạng tắc nghẽn giao thông, nhưng các dịch vụ phải đủ độ tin cậy để thu hút hành khách thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"not only ... but also ...","vi":"không những... mà còn..."},{"en":"not ... but ...","vi":"không phải... mà là..."},{"en":"anything but","vi":"hoàn toàn không phải"},{"en":"nothing but","vi":"chỉ là; không gì khác ngoài"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"although và but thường không được dùng chung trong cùng một câu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_red', 'en-a1-23', 'red', '/red/', 'A1', 'màu đỏ; có màu đỏ; màu đỏ', 'adj.', 'reddish (adj.), redden (v.), redness (n.)', NULL, 'in the red mang nghĩa là nợ nần hoặc thua lỗ, không phải nghĩa đen là màu đỏ.', 'She wore a red coat to the winter market.', NULL, 'Cô ấy mặc một chiếc áo khoác màu đỏ khi đi chợ mùa đông.', '{"wordId":"red","ukIpa":"/red/","usIpa":"/red/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"having the colour of ripe tomatoes","vi":"màu đỏ; có màu đỏ"},{"pos":"n.","en":"the colour of ripe tomatoes","vi":"màu đỏ"}],"examples":[{"en":"She wore a red coat to the winter market.","vi":"Cô ấy mặc một chiếc áo khoác màu đỏ khi đi chợ mùa đông.","audioKind":"ex"},{"en":"Designers often use red to draw attention to important warnings on machinery and in public spaces.","vi":"Các nhà thiết kế thường sử dụng màu đỏ để thu hút sự chú ý vào các cảnh báo quan trọng trên máy móc và trong các không gian công cộng.","audioKind":"ex2"}],"collocations":[{"en":"bright red","vi":"màu đỏ tươi"},{"en":"turn red","vi":"trở nên đỏ; đỏ mặt"},{"en":"in the red","vi":"âm vốn; thua lỗ"}],"wordFamily":["reddish (adj.)","redden (v.)","redness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"in the red mang nghĩa là nợ nần hoặc thua lỗ, không phải nghĩa đen là màu đỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conversation', 'en-a1-23', 'conversation', '/ˌkɑːnvərˈseɪʃən/', 'A1', 'cuộc trò chuyện; cuộc đàm thoại; sự trò chuyện', 'n.', 'converse (v.), conversational (adj.)', 'Đồng nghĩa: chat, talk', 'Cấu trúc trò chuyện với ai về điều gì: have a conversation with ai đó about cái gì.', 'We had a friendly conversation while waiting for the bus.', NULL, 'Chúng tôi đã có một cuộc trò chuyện thân thiện trong lúc đợi xe buýt.', '{"wordId":"conversation","ukIpa":"/ˌkɒnvəˈseɪʃən/","usIpa":"/ˌkɑːnvərˈseɪʃən/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A talk in which people exchange ideas, feelings, or information.","vi":"cuộc trò chuyện; cuộc đàm thoại; sự trò chuyện"}],"examples":[{"en":"We had a friendly conversation while waiting for the bus.","vi":"Chúng tôi đã có một cuộc trò chuyện thân thiện trong lúc đợi xe buýt.","audioKind":"ex"},{"en":"Regular conversation with fluent speakers helps language learners develop confidence and improve their listening skills.","vi":"Việc thường xuyên trò chuyện với những người nói thành thạo giúp người học ngoại ngữ xây dựng sự tự tin và cải thiện kỹ năng nghe.","audioKind":"ex2"}],"collocations":[{"en":"have a conversation","vi":"có một cuộc trò chuyện"},{"en":"start a conversation","vi":"bắt đầu một cuộc trò chuyện"},{"en":"a conversation about","vi":"cuộc trò chuyện về"}],"wordFamily":["converse (v.)","conversational (adj.)"],"synonyms":["chat","talk"],"antonyms":[],"tipVi":"Cấu trúc trò chuyện với ai về điều gì: have a conversation with ai đó about cái gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dinner', 'en-a1-23', 'dinner', '/ˈdɪnər/', 'A1', 'bữa tối; bữa cơm chiều; bữa chính trong ngày; bữa tiệc tối trang trọng', 'n.', NULL, NULL, 'Trong giao tiếp hàng ngày nói have dinner, không dùng mạo từ; khi chỉ bữa tiệc trang trọng có thể dùng a dinner.', 'Dinner is ready, so please bring the plates.', NULL, 'Bữa tối đã sẵn sàng, xin vui lòng dọn dĩa lên bàn.', '{"wordId":"dinner","ukIpa":"/ˈdɪnə/","usIpa":"/ˈdɪnər/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The main meal of the day, usually eaten in the evening.","vi":"bữa tối; bữa cơm chiều; bữa chính trong ngày"},{"pos":"n.","en":"A formal social occasion at which people eat a meal.","vi":"bữa tiệc tối trang trọng"}],"examples":[{"en":"Dinner is ready, so please bring the plates.","vi":"Bữa tối đã sẵn sàng, xin vui lòng dọn dĩa lên bàn.","audioKind":"ex"},{"en":"Sharing dinner regularly can strengthen family relationships by giving everyone an opportunity to discuss their daily experiences.","vi":"Thường xuyên quây quần bên bữa tối có thể củng cố tình cảm gia đình bằng cách tạo cơ hội cho mọi người thảo luận về những trải nghiệm hằng ngày của họ.","audioKind":"ex2"}],"collocations":[{"en":"have dinner","vi":"ăn tối"},{"en":"cook dinner","vi":"nấu bữa tối"},{"en":"a formal dinner","vi":"một bữa tiệc tối trang trọng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong giao tiếp hàng ngày nói have dinner, không dùng mạo từ; khi chỉ bữa tiệc trang trọng có thể dùng a dinner.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bring', 'en-a1-23', 'bring', '/brɪŋ/', 'A1', 'mang lại; cầm tới; đem theo; gây ra; dẫn đến; đem đến', 'v.', NULL, 'Trái nghĩa: take', 'bring nhấn mạnh hành động mang đến người nói hoặc một địa điểm được chỉ định; quá khứ là brought.', 'Please bring a warm coat when you visit.', NULL, 'Xin vui lòng mang theo một chiếc áo khoác ấm khi bạn đến thăm nhé.', '{"wordId":"bring","ukIpa":"/brɪŋ/","usIpa":"/brɪŋ/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to carry someone or something to a place","vi":"mang lại; cầm tới; đem theo"},{"pos":"v.","en":"to cause a situation, feeling, or result","vi":"gây ra; dẫn đến; đem đến"}],"examples":[{"en":"Please bring a warm coat when you visit.","vi":"Xin vui lòng mang theo một chiếc áo khoác ấm khi bạn đến thăm nhé.","audioKind":"ex"},{"en":"Improved public transport can bring significant benefits to residents who cannot afford their own cars.","vi":"Việc cải thiện giao thông công cộng có thể mang lại những lợi ích đáng kể cho cư dân không đủ khả năng mua ô tô riêng.","audioKind":"ex2"}],"collocations":[{"en":"bring someone something","vi":"mang cho ai cái gì"},{"en":"bring about change","vi":"mang lại sự thay đổi"},{"en":"bring good luck","vi":"mang lại may mắn"}],"wordFamily":[],"synonyms":[],"antonyms":["take"],"tipVi":"bring nhấn mạnh hành động mang đến người nói hoặc một địa điểm được chỉ định; quá khứ là brought.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_colour', 'en-a1-23', 'colour', '/ˈkʌlər/', 'A1', 'màu sắc; tô màu; nhuộm màu', 'n.', 'colourful (adj.), colourless (adj.), colouring (n.)', 'Đồng nghĩa: hue, shade', 'Cách viết theo Anh-Anh là colour, còn Anh-Mỹ là color.', 'What colour should we paint the kitchen walls?', NULL, 'Chúng ta nên sơn các bức tường nhà bếp màu gì?', '{"wordId":"colour","ukIpa":"/ˈkʌlə/","usIpa":"/ˈkʌlər/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The appearance of something as red, blue, green, and so on.","vi":"màu sắc"},{"pos":"v.","en":"To give something a colour using pencils, paint, or dye.","vi":"tô màu; nhuộm màu"}],"examples":[{"en":"What colour should we paint the kitchen walls?","vi":"Chúng ta nên sơn các bức tường nhà bếp màu gì?","audioKind":"ex"},{"en":"The colour of classroom walls may influence students'' moods and their ability to concentrate.","vi":"Màu sắc của tường lớp học có thể ảnh hưởng đến tâm trạng và khả năng tập trung của học sinh.","audioKind":"ex2"}],"collocations":[{"en":"bright colours","vi":"màu sắc tươi sáng"},{"en":"colour scheme","vi":"bảng phối màu"},{"en":"colour in a picture","vi":"tô màu tranh"},{"en":"change colour","vi":"đổi màu"}],"wordFamily":["colourful (adj.)","colourless (adj.)","colouring (n.)"],"synonyms":["hue","shade"],"antonyms":[],"tipVi":"Cách viết theo Anh-Anh là colour, còn Anh-Mỹ là color.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_afternoon', 'en-a1-23', 'afternoon', '/ˌæftɚˈnuːn/', 'A1', 'buổi chiều; khoảng thời gian từ trưa đến tối', 'n.', NULL, NULL, 'Chỉ buổi chiều chung chung dùng in; chỉ một buổi chiều cụ thể dùng on.', 'We spent the afternoon baking bread in the kitchen.', NULL, 'Chúng tôi dành cả buổi chiều để nướng bánh mì trong bếp.', '{"wordId":"afternoon","ukIpa":"/ˌɑːftəˈnuːn/","usIpa":"/ˌæftɚˈnuːn/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The time between midday and evening.","vi":"buổi chiều; khoảng thời gian từ trưa đến tối"}],"examples":[{"en":"We spent the afternoon baking bread in the kitchen.","vi":"Chúng tôi dành cả buổi chiều để nướng bánh mì trong bếp.","audioKind":"ex"},{"en":"Schools could offer afternoon sports sessions to help students develop healthier habits and stronger friendships.","vi":"Các trường học có thể tổ chức các buổi thể thao buổi chiều để giúp học sinh hình thành thói quen lành mạnh hơn và gắn kết tình bạn.","audioKind":"ex2"}],"collocations":[{"en":"in the afternoon","vi":"vào buổi chiều"},{"en":"this afternoon","vi":"chiều nay"},{"en":"late afternoon","vi":"chiều muộn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ buổi chiều chung chung dùng in; chỉ một buổi chiều cụ thể dùng on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_t-shirt', 'en-a1-23', 'T-shirt', '/ˈtiː ʃɝːt/', 'A1', 'áo phông; áo thun', 'n.', NULL, NULL, 'Danh từ đếm được, số nhiều là T-shirts, giữ nguyên dấu gạch ngang.', 'I packed a clean T-shirt for the picnic.', NULL, 'Tôi đã xếp một chiếc áo phông sạch vào hành lý cho buổi dã ngoại.', '{"wordId":"t-shirt","ukIpa":"/ˈtiː ʃɜːt/","usIpa":"/ˈtiː ʃɝːt/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A casual shirt, usually with short sleeves and no collar.","vi":"áo phông; áo thun"}],"examples":[{"en":"I packed a clean T-shirt for the picnic.","vi":"Tôi đã xếp một chiếc áo phông sạch vào hành lý cho buổi dã ngoại.","audioKind":"ex"},{"en":"Choosing a durable cotton T-shirt instead of disposable fashion can reduce waste and encourage more responsible consumption.","vi":"Việc lựa chọn một chiếc áo phông cotton bền bỉ thay vì thời trang dùng một lần có thể làm giảm rác thải và thúc đẩy lối tiêu dùng có trách nhiệm hơn.","audioKind":"ex2"}],"collocations":[{"en":"cotton T-shirt","vi":"áo phông cotton"},{"en":"plain T-shirt","vi":"áo phông trơn"},{"en":"wear a T-shirt","vi":"mặc áo phông"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ đếm được, số nhiều là T-shirts, giữ nguyên dấu gạch ngang.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_end', 'en-a1-23', 'end', '/end/', 'A1', 'phần cuối; điểm tận cùng; hồi kết; chấm dứt; kết thúc; mục đích; mục tiêu', 'n.', 'ending (n.), endless (adj.), endlessly (adv.)', 'Trái nghĩa: beginning, begin', 'at the end chỉ phần cuối; in the end chỉ kết quả cuối cùng.', 'There''s a small bakery at the end of our street.', NULL, 'Có một tiệm bánh nhỏ nằm ở cuối con phố nhà chúng tôi.', '{"wordId":"end","ukIpa":"/end/","usIpa":"/end/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"the final part or furthest point of something","vi":"phần cuối; điểm tận cùng; hồi kết"},{"pos":"v.","en":"to stop, or cause something to stop","vi":"chấm dứt; kết thúc"},{"pos":"n.","en":"a purpose that someone wants to achieve","vi":"mục đích; mục tiêu"}],"examples":[{"en":"There''s a small bakery at the end of our street.","vi":"Có một tiệm bánh nhỏ nằm ở cuối con phố nhà chúng tôi.","audioKind":"ex"},{"en":"Governments should aim to end extreme poverty by improving access to education and secure employment.","vi":"Chính phủ nên hướng tới mục tiêu chấm dứt tình trạng nghèo cực độ bằng cách cải thiện khả năng tiếp cận giáo dục và việc làm ổn định.","audioKind":"ex2"}],"collocations":[{"en":"at the end of","vi":"ở cuối của..."},{"en":"come to an end","vi":"đi đến hồi kết"},{"en":"put an end to","vi":"chấm dứt; đặt dấu chấm hết cho"},{"en":"a means to an end","vi":"phương tiện để đạt được mục đích"}],"wordFamily":["ending (n.)","endless (adj.)","endlessly (adv.)"],"synonyms":[],"antonyms":["beginning","begin"],"tipVi":"at the end chỉ phần cuối; in the end chỉ kết quả cuối cùng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_delicious', 'en-a1-23', 'delicious', '/dɪˈlɪʃəs/', 'A1', 'ngon; ngon miệng; thơm ngon', 'adj.', 'deliciously (adv.)', 'Đồng nghĩa: tasty, flavourful · Trái nghĩa: unpalatable', 'delicious bản thân mang sắc thái mạnh, thường đi kèm với absolutely để nhấn mạnh.', 'This delicious vegetable pie is still warm from the oven.', NULL, 'Món bánh rau củ thơm ngon này vẫn còn ấm nóng vừa ra lò.', '{"wordId":"delicious","ukIpa":"/dɪˈlɪʃəs/","usIpa":"/dɪˈlɪʃəs/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Having a very pleasant taste.","vi":"ngon; ngon miệng; thơm ngon"}],"examples":[{"en":"This delicious vegetable pie is still warm from the oven.","vi":"Món bánh rau củ thơm ngon này vẫn còn ấm nóng vừa ra lò.","audioKind":"ex"},{"en":"School meals should be both nutritious and delicious to encourage children to develop healthier eating habits.","vi":"Các bữa ăn học đường nên đảm bảo vừa giàu dinh dưỡng vừa ngon miệng để khuyến khích trẻ em phát triển thói quen ăn uống lành mạnh hơn.","audioKind":"ex2"}],"collocations":[{"en":"delicious meal","vi":"bữa ăn ngon miệng"},{"en":"delicious food","vi":"thức ăn ngon"},{"en":"absolutely delicious","vi":"ngon tuyệt hảo"}],"wordFamily":["deliciously (adv.)"],"synonyms":["tasty","flavourful"],"antonyms":["unpalatable"],"tipVi":"delicious bản thân mang sắc thái mạnh, thường đi kèm với absolutely để nhấn mạnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fill', 'en-a1-23', 'fill', '/fɪl/', 'A1', 'làm đầy; lấp đầy; đổ đầy; lấp đầy (chỗ trống); đáp ứng (nhu cầu)', 'v.', 'filling (n.), filling (adj.), refill (v.)', 'Trái nghĩa: empty', 'fill A with B có nghĩa là dùng B làm đầy A; be filled with có nghĩa là được lấp đầy bởi.', 'Please fill the jug with water for our guests.', NULL, 'Làm ơn đổ đầy nước vào bình để phục vụ các vị khách của chúng ta.', '{"wordId":"fill","ukIpa":"/fɪl/","usIpa":"/fɪl/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"Make or become full","vi":"làm đầy; lấp đầy; đổ đầy"},{"pos":"v.","en":"Occupy an empty position or meet a particular need","vi":"lấp đầy (chỗ trống); đáp ứng (nhu cầu)"}],"examples":[{"en":"Please fill the jug with water for our guests.","vi":"Làm ơn đổ đầy nước vào bình để phục vụ các vị khách của chúng ta.","audioKind":"ex"},{"en":"Local training programmes can help fill vacancies in essential services such as healthcare and education.","vi":"Các chương trình đào tạo địa phương có thể giúp lấp đầy các vị trí còn trống trong các dịch vụ thiết yếu như y tế và giáo dục.","audioKind":"ex2"}],"collocations":[{"en":"fill with water","vi":"đổ đầy nước"},{"en":"fill in a form","vi":"điền vào tờ đơn"},{"en":"fill a gap","vi":"lấp đầy khoảng trống"},{"en":"fill a vacancy","vi":"lấp đầy chỗ trống việc làm"}],"wordFamily":["filling (n.)","filling (adj.)","refill (v.)"],"synonyms":[],"antonyms":["empty"],"tipVi":"fill A with B có nghĩa là dùng B làm đầy A; be filled with có nghĩa là được lấp đầy bởi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_become', 'en-a1-23', 'become', '/bɪˈkʌm/', 'A1', 'trở thành; trở nên', 'v.', NULL, 'Đồng nghĩa: grow, turn', 'Các dạng chia động từ: become—became—become; theo sau có thể là danh từ hoặc tính từ.', 'The streets become quiet after the shops close.', NULL, 'Đường phố trở nên yên tĩnh sau khi các cửa hàng đóng cửa.', '{"wordId":"become","ukIpa":"/bɪˈkʌm/","usIpa":"/bɪˈkʌm/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to start to be something or develop a particular quality","vi":"trở thành; trở nên"}],"examples":[{"en":"The streets become quiet after the shops close.","vi":"Đường phố trở nên yên tĩnh sau khi các cửa hàng đóng cửa.","audioKind":"ex"},{"en":"Public transport must become more reliable and affordable if cities want residents to drive less frequently.","vi":"Phương tiện giao thông công cộng phải trở nên đáng tin cậy hơn và có giá cả phải chăng hơn nếu các thành phố muốn cư dân lái xe ít thường xuyên hơn.","audioKind":"ex2"}],"collocations":[{"en":"become aware of","vi":"bắt đầu nhận thức được"},{"en":"become increasingly important","vi":"trở nên ngày càng quan trọng"},{"en":"become a teacher","vi":"trở thành giáo viên"}],"wordFamily":[],"synonyms":["grow","turn"],"antonyms":[],"tipVi":"Các dạng chia động từ: become—became—become; theo sau có thể là danh từ hoặc tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_up', 'en-a1-23', 'up', '/ʌp/', 'A1', 'lên trên; ở phía trên; hướng lên trên cao; dọc theo (đường, dốc); thức giấc; đã rời khỏi giường', 'adv.', NULL, 'Trái nghĩa: down', 'up theo sau bởi danh từ chỉ địa điểm có thể đóng vai trò là giới từ, ví dụ như up the hill.', 'The child looked up at the bright red balloon.', NULL, 'Đứa trẻ ngước nhìn lên quả bóng bay đỏ rực.', '{"wordId":"up","ukIpa":"/ʌp/","usIpa":"/ʌp/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"Towards or in a higher position.","vi":"lên trên; ở phía trên"},{"pos":"prep.","en":"Towards a higher point or further along something.","vi":"hướng lên trên cao; dọc theo (đường, dốc)"},{"pos":"adj.","en":"Awake and out of bed.","vi":"thức giấc; đã rời khỏi giường"}],"examples":[{"en":"The child looked up at the bright red balloon.","vi":"Đứa trẻ ngước nhìn lên quả bóng bay đỏ rực.","audioKind":"ex"},{"en":"As housing costs go up, many young adults find it harder to live independently.","vi":"Khi chi phí nhà ở leo thang, nhiều bạn trẻ cảm thấy khó khăn hơn trong việc sống tự lập.","audioKind":"ex2"}],"collocations":[{"en":"look up","vi":"ngước nhìn lên"},{"en":"go up","vi":"tăng lên; đi lên"},{"en":"up the stairs","vi":"đi lên cầu thang"},{"en":"be up early","vi":"dậy sớm"}],"wordFamily":[],"synonyms":[],"antonyms":["down"],"tipVi":"up theo sau bởi danh từ chỉ địa điểm có thể đóng vai trò là giới từ, ví dụ như up the hill.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grey', 'en-a1-23', 'grey', '/ɡreɪ/', 'A1', 'xám; có màu xám; màu xám; trở nên hoa râm; ngả màu xám', 'adj.', 'greyish (adj.), greyness (n.)', NULL, 'grey là cách viết theo tiếng Anh-Anh, còn gray là tiếng Anh-Mỹ.', 'A grey cat was sleeping on the windowsill.', NULL, 'Một con mèo xám đang ngủ trên bệ cửa sổ.', '{"wordId":"grey","ukIpa":"/ɡreɪ/","usIpa":"/ɡreɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Having a colour between black and white.","vi":"xám; có màu xám"},{"pos":"n.","en":"The colour between black and white.","vi":"màu xám"},{"pos":"v.","en":"Develop grey hair as you get older.","vi":"trở nên hoa râm; ngả màu xám"}],"examples":[{"en":"A grey cat was sleeping on the windowsill.","vi":"Một con mèo xám đang ngủ trên bệ cửa sổ.","audioKind":"ex"},{"en":"Grey concrete buildings can appear less welcoming than neighbourhoods with colourful homes and abundant green space.","vi":"Các tòa nhà bê tông xám xịt có thể kém thân thiện hơn so với những khu dân cư có nhà cửa rực rỡ và nhiều không gian xanh.","audioKind":"ex2"}],"collocations":[{"en":"grey hair","vi":"tóc hoa râm"},{"en":"grey clouds","vi":"mây xám"},{"en":"turn grey","vi":"chuyển sang màu xám"},{"en":"a grey area","vi":"vùng xám (chưa rõ ràng)"}],"wordFamily":["greyish (adj.)","greyness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"grey là cách viết theo tiếng Anh-Anh, còn gray là tiếng Anh-Mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_much', 'en-a1-23', 'much', '/mʌtʃ/', 'A1', 'nhiều (dùng với danh từ không đếm được); nhiều; một lượng lớn; nhiều; rất (thường dùng trong so sánh và với một số động từ)', 'det.', NULL, 'Trái nghĩa: little', 'much dùng để bổ nghĩa cho danh từ không đếm được; dùng many cho danh từ đếm được số nhiều.', 'We do not have much milk left for breakfast.', NULL, 'Chúng ta không còn lại nhiều sữa cho bữa sáng.', '{"wordId":"much","ukIpa":"/mʌtʃ/","usIpa":"/mʌtʃ/","cefr":"A1","topic":"daily","senses":[{"pos":"det.","en":"A large amount of something, used with uncountable nouns.","vi":"nhiều (dùng với danh từ không đếm được)"},{"pos":"pron.","en":"A large amount, without naming what is being discussed.","vi":"nhiều; một lượng lớn"},{"pos":"adv.","en":"To a great degree, especially with comparisons and certain verbs.","vi":"nhiều; rất (thường dùng trong so sánh và với một số động từ)"}],"examples":[{"en":"We do not have much milk left for breakfast.","vi":"Chúng ta không còn lại nhiều sữa cho bữa sáng.","audioKind":"ex"},{"en":"Investing in preventive healthcare can be much more economical than treating illnesses after they become severe.","vi":"Đầu tư vào chăm sóc sức khỏe dự phòng có thể tiết kiệm hơn rất nhiều so với việc điều trị bệnh sau khi đã trở nên nặng.","audioKind":"ex2"}],"collocations":[{"en":"too much","vi":"quá nhiều"},{"en":"much more","vi":"nhiều hơn đáng kể"},{"en":"much better","vi":"tốt hơn nhiều"},{"en":"as much as","vi":"nhiều như"}],"wordFamily":[],"synonyms":[],"antonyms":["little"],"tipVi":"much dùng để bổ nghĩa cho danh từ không đếm được; dùng many cho danh từ đếm được số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_can', 'en-a1-23', 'can', '/kæn/', 'A1', 'có thể (diễn tả năng lực, sự cho phép hoặc khả năng xảy ra); cái lon (bằng kim loại); đóng hộp (bảo quản thực phẩm trong lon)', 'v.', 'canning (n.), canned (adj.)', NULL, 'Khi là động từ khuyết thiếu, can đi với động từ nguyên thể và không thêm s ở ngôi thứ ba số ít.', 'I can carry both bags if you open the door.', NULL, 'Tôi có thể xách cả hai chiếc túi nếu bạn mở cửa giúp.', '{"wordId":"can","ukIpa":"/kæn/","usIpa":"/kæn/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"Used to express ability, permission, or possibility.","vi":"có thể (diễn tả năng lực, sự cho phép hoặc khả năng xảy ra)"},{"pos":"n.","en":"A metal container for food, drinks, or other substances.","vi":"cái lon (bằng kim loại)"},{"pos":"v.","en":"To preserve food by sealing it in cans.","vi":"đóng hộp (bảo quản thực phẩm trong lon)"}],"examples":[{"en":"I can carry both bags if you open the door.","vi":"Tôi có thể xách cả hai chiếc túi nếu bạn mở cửa giúp.","audioKind":"ex"},{"en":"Access to reliable internet can help rural students benefit from a wider range of educational resources.","vi":"Việc tiếp cận internet ổn định có thể giúp học sinh vùng nông thôn tận dụng được nhiều nguồn tài nguyên giáo dục phong phú hơn.","audioKind":"ex2"}],"collocations":[{"en":"can afford","vi":"có đủ khả năng chi trả"},{"en":"can of soup","vi":"một lon súp"},{"en":"canned food","vi":"thực phẩm đóng hộp"}],"wordFamily":["canning (n.)","canned (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi là động từ khuyết thiếu, can đi với động từ nguyên thể và không thêm s ở ngôi thứ ba số ít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_23_1', 'en-a1-23', 'Cách dùng “dinner” (n.) — bữa tối; bữa cơm chiều; bữa chính trong ngày', 'have dinner  ·  cook dinner  ·  a formal dinner', 'Trong giao tiếp hàng ngày nói have dinner, không dùng mạo từ; khi chỉ bữa tiệc trang trọng có thể dùng a dinner.', NULL, '[{"hanzi":"Dinner is ready, so please bring the plates.","pinyin":"","meaning":"Bữa tối đã sẵn sàng, xin vui lòng dọn dĩa lên bàn."},{"hanzi":"Sharing dinner regularly can strengthen family relationships by giving everyone an opportunity to discuss their daily experiences.","pinyin":"","meaning":"Thường xuyên quây quần bên bữa tối có thể củng cố tình cảm gia đình bằng cách tạo cơ hội cho mọi người thảo luận về những trải nghiệm hằng ngày của họ."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_23_2', 'en-a1-23', 'Cách dùng “between” (prep.) — ở giữa; trong khoảng thời gian giữa', 'between meals  ·  a link between  ·  choose between', 'Từ between không chỉ giới hạn ở hai đối tượng, mà còn có thể dùng cho nhiều đối tượng riêng biệt khác nhau.', NULL, '[{"hanzi":"The cat squeezed between the sofa and the wall.","pinyin":"","meaning":"Con mèo luồn lách vào khe giữa chiếc ghế sofa và bức tường."},{"hanzi":"Cooperation between schools and local businesses can help students develop practical skills before entering employment.","pinyin":"","meaning":"Sự hợp tác giữa các trường học và doanh nghiệp địa phương có thể giúp học sinh phát triển các kỹ năng thực tế trước khi bước chân vào thị trường lao động."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_23_3', 'en-a1-23', 'Cách dùng “favorite” (adj.) — được ưa chuộng nhất; yêu thích nhất', 'a favorite pastime  ·  a firm favorite  ·  the clear favorite to win', 'Favorite là cách viết kiểu Mỹ, tiếng Anh-Anh là favourite; thông thường không dùng most đi trước từ này.', 'Họ từ (Word Family): favor (n.), favor (v.), favorable (adj.), favoritism (n.) | Đồng nghĩa: preferred', '[{"hanzi":"This blue sweater is my favorite winter item.","pinyin":"","meaning":"Chiếc áo len màu xanh này là món đồ mùa đông yêu thích của tôi."},{"hanzi":"Surveys of children''s favorite leisure activities can help local authorities design more appealing public recreation spaces.","pinyin":"","meaning":"Các cuộc khảo sát về hoạt động giải trí yêu thích của trẻ em có thể giúp chính quyền địa phương thiết kế các không gian giải trí công cộng hấp dẫn hơn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_23_4', 'en-a1-23', 'Cách dùng “down” (adv.) — xuống dưới; ở vị trí thấp hơn', 'sit down  ·  go down  ·  down the street', 'down đi sau danh từ có thể đóng vai trò là giới từ; feel down diễn tả tâm trạng buồn bã, chán nản.', 'Họ từ (Word Family): downward (adj.), downwards (adv.) | Trái nghĩa: up', '[{"hanzi":"The cat jumped down from the kitchen table.","pinyin":"","meaning":"Con mèo nhảy xuống từ bàn bếp."},{"hanzi":"As housing costs go up, the amount young adults can save often goes down.","pinyin":"","meaning":"Khi chi phí nhà ở tăng lên, số tiền mà những người trẻ tuổi có thể tiết kiệm thường giảm xuống."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_23_1', 'en-a1-23', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_23_1_1', 'ten_23_1', 'bread', 'Fresh bread was cooling beside the kitchen window.', 'Fresh bread was cooling beside the kitchen window.', '/bred/', 'Ổ bánh mì mới ra lò đang được để nguội ngay bên khung cửa sổ nhà bếp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
