INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_23_2', 'en-a1-23', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_23_2_1', 'ten_23_2', 'bread', 'Choosing wholegrain bread instead of refined varieties can increase fibre intake and support a balanced diet.', 'Choosing wholegrain bread instead of refined varieties can increase fibre intake and support a balanced diet.', '/bred/', 'Việc lựa chọn bánh mì nguyên cám thay vì các loại bánh mì tinh chế có thể giúp tăng lượng chất xơ nạp vào và hỗ trợ một chế độ ăn uống cân bằng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_23_2_2', 'ten_23_2', 'between', 'Cooperation between schools and local businesses can help students develop practical skills before entering employment.', 'Cooperation between schools and local businesses can help students develop practical skills before entering employment.', '/bɪˈtwiːn/', 'Sự hợp tác giữa các trường học và doanh nghiệp địa phương có thể giúp học sinh phát triển các kỹ năng thực tế trước khi bước chân vào thị trường lao động.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_23_2_3', 'ten_23_2', 'eighteen', 'In many countries, citizens gain the right to vote when they reach the age of eighteen.', 'In many countries, citizens gain the right to vote when they reach the age of eighteen.', '/ˌeɪˈtiːn/', 'Ở nhiều quốc gia, công dân có được quyền bầu cử khi đủ mười tám tuổi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_23_2_4', 'ten_23_2', 'time', 'Schools should give students enough time to explore creative activities alongside their preparation for formal examinations.', 'Schools should give students enough time to explore creative activities alongside their preparation for formal examinations.', '/taɪm/', 'Nhà trường nên cho học sinh đủ thời gian để khám phá các hoạt động sáng tạo bên cạnh việc chuẩn bị cho các kỳ thi chính thức.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_23_2_5', 'ten_23_2', 'bathroom', 'Installing water-saving fixtures in the bathroom can help households reduce consumption without changing their daily routines.', 'Installing water-saving fixtures in the bathroom can help households reduce consumption without changing their daily routines.', '/ˈbæθruːm/', 'Việc lắp đặt các thiết bị tiết kiệm nước trong phòng tắm có thể giúp các hộ gia đình giảm lượng nước tiêu thụ mà không làm thay đổi thói quen sinh hoạt hàng ngày.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_23_2_6', 'ten_23_2', 'favorite', 'Surveys of children''s favorite leisure activities can help local authorities design more appealing public recreation spaces.', 'Surveys of children''s favorite leisure activities can help local authorities design more appealing public recreation spaces.', '/ˈfeɪvərɪt/', 'Các cuộc khảo sát về hoạt động giải trí yêu thích của trẻ em có thể giúp chính quyền địa phương thiết kế các không gian giải trí công cộng hấp dẫn hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_23_2_1', 'en-a1-23', 'ten_23_2', 'listening', 'listening', 'Choosing wholegrain bread instead of refined varieties can increase fibre intake and support a balanced diet.', NULL, 'Trong câu vừa nghe, từ “bread” mang nghĩa nào sau đây?', '["bánh mì","nữ phục vụ bàn; nữ bồi bàn","bàn học; bàn làm việc","áo khoác ngắn; áo vét-tông"]'::jsonb, 0, '“bread” (/bred/): bánh mì. Câu đầy đủ: Choosing wholegrain bread instead of refined varieties can increase fibre intake and support a balanced diet.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_23_2_2', 'en-a1-23', 'ten_23_2', 'listening', 'listening', 'Cooperation between schools and local businesses can help students develop practical skills before entering employment.', NULL, 'Trong câu vừa nghe, từ “between” mang nghĩa nào sau đây?', '["sớm; ở giai đoạn đầu","đóng; khép; kết thúc","ở giữa; trong khoảng thời gian giữa","đứng; đứng dậy"]'::jsonb, 2, '“between” (/bɪˈtwiːn/): ở giữa; trong khoảng thời gian giữa. Câu đầy đủ: Cooperation between schools and local businesses can help students develop practical skills before entering employment.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
