INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_23_2', 'en-a1-23', NULL, 'comprehensive_test', 'listening', 'The cat squeezed between the sofa and the wall.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi nhận được một chiếc khăn choàng cổ ấm áp vào dịp sinh nhật.","Con mèo luồn lách vào khe giữa chiếc ghế sofa và bức tường.","Chúng tôi đã có một cuộc trò chuyện thân thiện trong lúc đợi xe buýt.","Chúng ta không còn lại nhiều sữa cho bữa sáng."]'::jsonb, 1, 'The cat squeezed between the sofa and the wall. → Con mèo luồn lách vào khe giữa chiếc ghế sofa và bức tường.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
