INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_23_4', 'en-a1-23', NULL, 'comprehensive_test', 'listening', 'We still have time for a walk before dinner.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi vẫn còn thời gian để đi dạo trước bữa tối.","Bữa tối đã sẵn sàng, xin mời bạn lấy đĩa của mình.","Chúng ta không còn lại nhiều sữa cho bữa sáng.","Đứa trẻ ngước nhìn lên quả bóng bay đỏ rực."]'::jsonb, 0, 'We still have time for a walk before dinner. → Chúng tôi vẫn còn thời gian để đi dạo trước bữa tối.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
