INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_23_6', 'en-a1-23', NULL, 'comprehensive_test', 'listening', 'This blue sweater is my favorite winter item.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Con mèo nhảy xuống từ bàn bếp.","Cô ấy treo một chiếc khăn sạch bên cạnh bồn rửa trong phòng tắm.","Chúng tôi đã có một cuộc trò chuyện thân thiện trong lúc đợi xe buýt.","Chiếc áo len màu xanh này là món đồ mùa đông yêu thích của tôi."]'::jsonb, 3, 'This blue sweater is my favorite winter item. → Chiếc áo len màu xanh này là món đồ mùa đông yêu thích của tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
