INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_23_18', 'en-a1-23', NULL, 'comprehensive_test', 'reading', NULL, 'Choosing wholegrain bread instead of refined varieties can increase fibre intake and support a balanced diet.', 'Dựa vào câu trên, từ “bread” có nghĩa phù hợp nhất là gì?', '["châu Phi","một lần duy nhất","bánh mì","n. bạn; bạn bè; chiến hữu"]'::jsonb, 2, 'bread: bánh mì. Dịch cả câu: Việc lựa chọn bánh mì nguyên cám thay vì các loại bánh mì tinh chế có thể giúp tăng lượng chất xơ nạp vào và hỗ trợ một chế độ ăn uống cân bằng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_23_19', 'en-a1-23', NULL, 'comprehensive_test', 'reading', NULL, 'Cooperation between schools and local businesses can help students develop practical skills before entering employment.', 'Dựa vào câu trên, từ “between” có nghĩa phù hợp nhất là gì?', '["công ty; hãng","con đường; đường đi","ở giữa; trong khoảng thời gian giữa","khác nhau; không giống nhau"]'::jsonb, 2, 'between: ở giữa; trong khoảng thời gian giữa; giữa (các bên); chung giữa; ở khoảng giữa. Dịch cả câu: Sự hợp tác giữa các trường học và doanh nghiệp địa phương có thể giúp học sinh phát triển các kỹ năng thực tế trước khi bước chân vào thị trường lao động.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_23_20', 'en-a1-23', NULL, 'comprehensive_test', 'reading', NULL, 'In many countries, citizens gain the right to vote when they reach the age of eighteen.', 'Dựa vào câu trên, từ “eighteen” có nghĩa phù hợp nhất là gì?', '["mười tám","cha; bố","ngày sinh nhật; ngày kỷ niệm ngày sinh","video; đoạn ghi hình ảnh chuyển động, thường có kèm âm thanh"]'::jsonb, 0, 'eighteen: mười tám. Dịch cả câu: Ở nhiều quốc gia, công dân có được quyền bầu cử khi đủ mười tám tuổi.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_23_21', 'en-a1-23', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should give students enough time to explore creative activities alongside their preparation for formal examinations.', 'Dựa vào câu trên, từ “time” có nghĩa phù hợp nhất là gì?', '["tiếng Anh","tai","cầm, nắm hoặc đỡ cái gì đó trong lúc di chuyển nó đến đâu; mang vác","thời gian; thời điểm"]'::jsonb, 3, 'time: thời gian; thời điểm; lần; lượt; đo thời gian; bấm giờ; chọn thời điểm. Dịch cả câu: Nhà trường nên cho học sinh đủ thời gian để khám phá các hoạt động sáng tạo bên cạnh việc chuẩn bị cho các kỳ thi chính thức.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_23_22', 'en-a1-23', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “xám; có màu xám”', '["grey","cola","purple","white"]'::jsonb, 0, 'xám; có màu xám → grey (/ɡreɪ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_23_23', 'en-a1-23', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nhiều (dùng với danh từ không đếm được)”', '["much","change","class","Germany"]'::jsonb, 0, 'nhiều (dùng với danh từ không đếm được) → much (/mʌtʃ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_23_24', 'en-a1-23', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “có thể (diễn tả năng lực, sự cho phép hoặc khả năng xảy ra)”', '["door","gray","special","can"]'::jsonb, 3, 'có thể (diễn tả năng lực, sự cho phép hoặc khả năng xảy ra) → can (/kæn/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-24', 'en', 'Bài 24: Đời sống hằng ngày (9) - CEFR A1', 'CEFR A1', 'A1 · Đời sống', '27 từ vựng Tiếng Anh CEFR A1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1024, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hey', 'en-a1-24', 'hey', '/heɪ/', 'A1', 'này; chào (dùng thân mật để chào hỏi hoặc thu hút sự chú ý)', 'int.', NULL, 'Đồng nghĩa: hi, hello', 'Thích hợp dùng khi chào hỏi giữa những người thân quen; nên tránh dùng trong email trang trọng.', 'Hey, you left your umbrella beside the door!', NULL, 'Này, bạn bỏ quên ô ở cạnh cửa rồi!', '{"wordId":"hey","ukIpa":"/heɪ/","usIpa":"/heɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"int.","en":"Used informally to greet someone or attract their attention.","vi":"này; chào (dùng thân mật để chào hỏi hoặc thu hút sự chú ý)"}],"examples":[{"en":"Hey, you left your umbrella beside the door!","vi":"Này, bạn bỏ quên ô ở cạnh cửa rồi!","audioKind":"ex"},{"en":"Informal greetings such as hey may be inappropriate when students first contact university staff by email.","vi":"Những lời chào thân mật như hey có thể không phù hợp khi sinh viên lần đầu liên hệ với nhân viên trường đại học qua email.","audioKind":"ex2"}],"collocations":[{"en":"hey there","vi":"chào bạn nhé"},{"en":"hey everyone","vi":"chào mọi người"}],"wordFamily":[],"synonyms":["hi","hello"],"antonyms":[],"tipVi":"Thích hợp dùng khi chào hỏi giữa những người thân quen; nên tránh dùng trong email trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cola', 'en-a1-24', 'cola', '/ˈkoʊlə/', 'A1', 'nước cô-la; nước ngọt có gas', 'n.', NULL, NULL, 'Khi chỉ chung loại đồ uống thì không đếm được; a cola có thể dùng để chỉ một ly hoặc một phần nước cô-la.', 'He poured cold cola into a glass with ice.', NULL, 'Anh ấy rót nước cô-la lạnh vào một chiếc cốc có đá.', '{"wordId":"cola","ukIpa":"/ˈkəʊlə/","usIpa":"/ˈkoʊlə/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A sweet, dark, fizzy drink, usually containing caffeine.","vi":"nước cô-la; nước ngọt có gas"}],"examples":[{"en":"He poured cold cola into a glass with ice.","vi":"Anh ấy rót nước cô-la lạnh vào một chiếc cốc có đá.","audioKind":"ex"},{"en":"Reducing the consumption of sugary drinks such as cola may help prevent tooth decay in children.","vi":"Giảm tiêu thụ đồ uống có đường như nước cô-la có thể giúp ngăn ngừa sâu răng ở trẻ em.","audioKind":"ex2"}],"collocations":[{"en":"a can of cola","vi":"một lon nước cô-la"},{"en":"diet cola","vi":"nước cô-la ít calo"},{"en":"sugar-free cola","vi":"nước cô-la không đường"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ chung loại đồ uống thì không đếm được; a cola có thể dùng để chỉ một ly hoặc một phần nước cô-la.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shower', 'en-a1-24', 'shower', '/ˈʃaʊər/', 'A1', 'vòi hoa sen; việc tắm dưới vòi hoa sen; cơn mưa rào; tắm dưới vòi hoa sen', 'n.', NULL, NULL, 'Cụm từ tắm vòi hoa sen dùng take a shower hoặc have a shower; shower cũng chỉ cơn mưa rào ngắn.', 'I always take a warm shower after cycling home.', NULL, 'Tôi luôn tắm nước ấm sau khi đạp xe về nhà.', '{"wordId":"shower","ukIpa":"/ˈʃaʊə/","usIpa":"/ˈʃaʊər/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"Washing under falling water, or the equipment used for this","vi":"vòi hoa sen; việc tắm dưới vòi hoa sen"},{"pos":"n.","en":"A short period of rain","vi":"cơn mưa rào"},{"pos":"v.","en":"Wash your body under water falling from a shower","vi":"tắm dưới vòi hoa sen"}],"examples":[{"en":"I always take a warm shower after cycling home.","vi":"Tôi luôn tắm nước ấm sau khi đạp xe về nhà.","audioKind":"ex"},{"en":"Taking shorter showers is a simple way for households to reduce both water consumption and energy use.","vi":"Tắm vòi hoa sen nhanh hơn là một cách đơn giản để các hộ gia đình giảm cả lượng nước và năng lượng tiêu thụ.","audioKind":"ex2"}],"collocations":[{"en":"take a shower","vi":"tắm vòi hoa sen"},{"en":"have a shower","vi":"tắm vòi hoa sen"},{"en":"heavy showers","vi":"mưa rào nặng hạt"},{"en":"a shower head","vi":"bát sen vòi tắm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ tắm vòi hoa sen dùng take a shower hoặc have a shower; shower cũng chỉ cơn mưa rào ngắn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_early', 'en-a1-24', 'early', '/ˈɝːli/', 'A1', 'sớm; ở giai đoạn đầu; sớm; trước thời gian dự kiến', 'adj.', 'earlier (adv.), earliest (adj.)', 'Trái nghĩa: late', 'early vừa là tính từ vừa là trạng từ, không cần thêm đuôi -ly.', 'We caught an early train and arrived before breakfast.', NULL, 'Chúng tôi đã bắt một chuyến tàu sớm và đến nơi trước bữa sáng.', '{"wordId":"early","ukIpa":"/ˈɜːli/","usIpa":"/ˈɝːli/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Near the beginning of a period or before the usual time","vi":"sớm; ở giai đoạn đầu"},{"pos":"adv.","en":"Before the expected time or near the beginning","vi":"sớm; trước thời gian dự kiến"}],"examples":[{"en":"We caught an early train and arrived before breakfast.","vi":"Chúng tôi đã bắt một chuyến tàu sớm và đến nơi trước bữa sáng.","audioKind":"ex"},{"en":"Early investment in childhood education can reduce inequality and improve employment prospects later in life.","vi":"Đầu tư sớm vào giáo dục mầm non có thể làm giảm sự bất bình đẳng và cải thiện cơ hội việc làm sau này trong đời.","audioKind":"ex2"}],"collocations":[{"en":"early childhood","vi":"thời thơ ấu"},{"en":"early stages","vi":"giai đoạn đầu"},{"en":"arrive early","vi":"đến sớm"},{"en":"early detection","vi":"phát hiện sớm"}],"wordFamily":["earlier (adv.)","earliest (adj.)"],"synonyms":[],"antonyms":["late"],"tipVi":"early vừa là tính từ vừa là trạng từ, không cần thêm đuôi -ly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_these', 'en-a1-24', 'these', '/ðiːz/', 'A1', 'những... này (dùng trước danh từ số nhiều chỉ người hoặc vật ở gần); những người này; những vật này; những điều vừa nhắc đến', 'det.', 'this (det.), this (pron.)', 'Trái nghĩa: those', 'these là this của số nhiều, theo sau là danh từ số nhiều.', 'These strawberries smell lovely, so let''s buy a basket.', NULL, 'Những quả dâu tây này thơm quá, chúng ta mua một giỏ nhé.', '{"wordId":"these","ukIpa":"/ðiːz/","usIpa":"/ðiːz/","cefr":"A1","topic":"daily","senses":[{"pos":"det.","en":"Used before plural nouns for nearby people or things.","vi":"những... này (dùng trước danh từ số nhiều chỉ người hoặc vật ở gần)"},{"pos":"pron.","en":"Nearby people or things, or ones just mentioned.","vi":"những người này; những vật này; những điều vừa nhắc đến"}],"examples":[{"en":"These strawberries smell lovely, so let''s buy a basket.","vi":"Những quả dâu tây này thơm quá, chúng ta mua một giỏ nhé.","audioKind":"ex"},{"en":"These findings suggest that regular outdoor activities can improve children''s concentration and emotional health.","vi":"Những kết quả nghiên cứu này cho thấy các hoạt động ngoài trời thường xuyên có thể cải thiện khả năng tập trung và sức khỏe cảm xúc của trẻ em.","audioKind":"ex2"}],"collocations":[{"en":"these days","vi":"dạo này"},{"en":"these things","vi":"những thứ này"},{"en":"in these circumstances","vi":"trong những hoàn cảnh này"}],"wordFamily":["this (det.)","this (pron.)"],"synonyms":[],"antonyms":["those"],"tipVi":"these là this của số nhiều, theo sau là danh từ số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_favourite', 'en-a1-24', 'favourite', '/ˈfeɪvərɪt/', 'A1', 'được yêu thích nhất (hơn bất kỳ thứ gì cùng loại); người hoặc vật được yêu thích nhất; đối thủ được đánh giá có khả năng chiến thắng cao nhất', 'adj.', 'favour (v.), favouritism (n.)', 'Đồng nghĩa: preferred · Trái nghĩa: least favourite', 'favourite là cách viết kiểu Anh-Anh, favorite là Anh-Mỹ; thường không dùng most đi kèm.', 'This little bakery sells my favourite kind of bread.', NULL, 'Tiệm bánh nhỏ này bán loại bánh mì yêu thích của tôi.', '{"wordId":"favourite","ukIpa":"/ˈfeɪvərɪt/","usIpa":"/ˈfeɪvərɪt/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"liked more than any other of the same kind","vi":"được yêu thích nhất (hơn bất kỳ thứ gì cùng loại)"},{"pos":"n.","en":"a person or thing someone likes best","vi":"người hoặc vật được yêu thích nhất"},{"pos":"n.","en":"the competitor considered most likely to win","vi":"đối thủ được đánh giá có khả năng chiến thắng cao nhất"}],"examples":[{"en":"This little bakery sells my favourite kind of bread.","vi":"Tiệm bánh nhỏ này bán loại bánh mì yêu thích của tôi.","audioKind":"ex"},{"en":"Public libraries allow readers to discover new authors as well as revisit their favourite books without additional cost.","vi":"Các thư viện công cộng giúp độc giả khám phá các tác giả mới cũng như đọc lại những cuốn sách yêu thích của họ mà không phải tốn thêm chi phí.","audioKind":"ex2"}],"collocations":[{"en":"favourite subject","vi":"môn học yêu thích"},{"en":"a firm favourite","vi":"người hoặc vật luôn được yêu thích"},{"en":"the favourite to win","vi":"ứng cử viên sáng giá cho chức vô địch"}],"wordFamily":["favour (v.)","favouritism (n.)"],"synonyms":["preferred"],"antonyms":["least favourite"],"tipVi":"favourite là cách viết kiểu Anh-Anh, favorite là Anh-Mỹ; thường không dùng most đi kèm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clock', 'en-a1-24', 'clock', '/klɑːk/', 'A1', 'đồng hồ (treo tường hoặc để bàn); đo lường hoặc ghi lại thời gian hoặc tốc độ của cái gì đó', 'n.', 'clockwise (adv.), anticlockwise (adv.)', NULL, 'clock thường chỉ đồng hồ để bàn hoặc treo tường; đồng hồ đeo ở cổ tay gọi là watch.', 'The kitchen clock stopped while we were making lunch.', NULL, 'Đồng hồ trong bếp đã ngừng chạy khi chúng tôi đang chuẩn bị bữa trưa.', '{"wordId":"clock","ukIpa":"/klɒk/","usIpa":"/klɑːk/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a device that shows the time","vi":"đồng hồ (treo tường hoặc để bàn)"},{"pos":"v.","en":"to measure or record the time or speed of something","vi":"đo lường hoặc ghi lại thời gian hoặc tốc độ của cái gì đó"}],"examples":[{"en":"The kitchen clock stopped while we were making lunch.","vi":"Đồng hồ trong bếp đã ngừng chạy khi chúng tôi đang chuẩn bị bữa trưa.","audioKind":"ex"},{"en":"Flexible working arrangements allow employees to work when they are most productive, rather than watching the clock.","vi":"Các thỏa thuận làm việc linh hoạt cho phép nhân viên làm việc vào lúc họ đạt hiệu suất cao nhất, thay vì cứ chăm chăm nhìn đồng hồ mong hết giờ.","audioKind":"ex2"}],"collocations":[{"en":"alarm clock","vi":"đồng hồ báo thức"},{"en":"around the clock","vi":"suốt ngày đêm"},{"en":"clock in","vi":"chấm công vào làm"},{"en":"watch the clock","vi":"ngồi chờ hết giờ làm"}],"wordFamily":["clockwise (adv.)","anticlockwise (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"clock thường chỉ đồng hồ để bàn hoặc treo tường; đồng hồ đeo ở cổ tay gọi là watch.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_downstairs', 'en-a1-24', 'downstairs', '/ˌdaʊnˈsterz/', 'A1', 'ở tầng dưới; xuống tầng dưới; ở phía tầng dưới của một tòa nhà', 'adv.', 'upstairs (adv.)', 'Trái nghĩa: upstairs', 'Khi dùng làm phó từ, nói go downstairs mà không cần dùng to.', 'I went downstairs when I smelled fresh bread.', NULL, 'Tôi đi xuống tầng dưới khi ngửi thấy mùi bánh mì tươi.', '{"wordId":"downstairs","ukIpa":"/ˌdaʊnˈsteəz/","usIpa":"/ˌdaʊnˈsterz/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"On or towards a lower floor of a building","vi":"ở tầng dưới; xuống tầng dưới"},{"pos":"adj.","en":"Located on a lower floor of a building","vi":"ở phía tầng dưới của một tòa nhà"}],"examples":[{"en":"I went downstairs when I smelled fresh bread.","vi":"Tôi đi xuống tầng dưới khi ngửi thấy mùi bánh mì tươi.","audioKind":"ex"},{"en":"Providing a downstairs bedroom can help older residents remain independent in their own homes.","vi":"Việc bố trí một phòng ngủ ở tầng dưới có thể giúp cư dân lớn tuổi duy trì cuộc sống tự lập ngay tại ngôi nhà của họ.","audioKind":"ex2"}],"collocations":[{"en":"go downstairs","vi":"đi xuống lầu"},{"en":"downstairs bathroom","vi":"phòng tắm ở tầng dưới"},{"en":"downstairs neighbour","vi":"hàng xóm ở tầng dưới"}],"wordFamily":["upstairs (adv.)"],"synonyms":[],"antonyms":["upstairs"],"tipVi":"Khi dùng làm phó từ, nói go downstairs mà không cần dùng to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_meal', 'en-a1-24', 'meal', '/miːl/', 'A1', 'bữa ăn; bữa cơm', 'n.', NULL, NULL, 'meal chỉ một bữa ăn; food chỉ chung chung thức ăn và thường không đếm được.', 'Dad cooked a warm meal after our long walk.', NULL, 'Bố đã nấu một bữa ăn ấm cúng sau chuyến đi bộ đường dài mệt mỏi của chúng tôi.', '{"wordId":"meal","ukIpa":"/miːl/","usIpa":"/miːl/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"An occasion when you eat, or the food eaten then.","vi":"bữa ăn; bữa cơm"}],"examples":[{"en":"Dad cooked a warm meal after our long walk.","vi":"Bố đã nấu một bữa ăn ấm cúng sau chuyến đi bộ đường dài mệt mỏi của chúng tôi.","audioKind":"ex"},{"en":"Providing healthy school meals can improve children''s concentration and support their physical development.","vi":"Việc cung cấp các bữa ăn học đường lành mạnh có thể nâng cao sự tập trung của trẻ em và hỗ trợ sự phát triển thể chất của chúng.","audioKind":"ex2"}],"collocations":[{"en":"balanced meal","vi":"bữa ăn cân bằng dinh dưỡng"},{"en":"prepare a meal","vi":"chuẩn bị bữa ăn"},{"en":"skip a meal","vi":"bỏ bữa"},{"en":"main meal","vi":"bữa ăn chính"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"meal chỉ một bữa ăn; food chỉ chung chung thức ăn và thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chair', 'en-a1-24', 'chair', '/tʃer/', 'A1', 'ghế (có lưng dựa cho một người ngồi); chủ tọa; người chịu trách nhiệm điều hành cuộc họp hoặc ủy ban; chủ trì; điều hành một cuộc họp', 'n.', 'chairperson (n.)', NULL, 'chair khi là động từ sẽ đi thẳng với meeting để chỉ việc chủ trì cuộc họp.', 'She pulled a chair closer to the window.', NULL, 'Cô ấy kéo một chiếc ghế lại gần cửa sổ hơn.', '{"wordId":"chair","ukIpa":"/tʃeə/","usIpa":"/tʃer/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a seat for one person, usually with a back","vi":"ghế (có lưng dựa cho một người ngồi)"},{"pos":"n.","en":"the person responsible for leading a meeting or committee","vi":"chủ tọa; người chịu trách nhiệm điều hành cuộc họp hoặc ủy ban"},{"pos":"v.","en":"to lead a meeting and manage its discussion","vi":"chủ trì; điều hành một cuộc họp"}],"examples":[{"en":"She pulled a chair closer to the window.","vi":"Cô ấy kéo một chiếc ghế lại gần cửa sổ hơn.","audioKind":"ex"},{"en":"An independent expert should chair the meeting to ensure that all participants can contribute fairly.","vi":"Một chuyên gia độc lập nên chủ trì cuộc họp để đảm bảo tất cả những người tham gia đều có thể đóng góp ý kiến một cách công bằng.","audioKind":"ex2"}],"collocations":[{"en":"office chair","vi":"ghế văn phòng"},{"en":"committee chair","vi":"chủ tịch ủy ban"},{"en":"chair a meeting","vi":"chủ trì một cuộc họp"}],"wordFamily":["chairperson (n.)"],"synonyms":[],"antonyms":[],"tipVi":"chair khi là động từ sẽ đi thẳng với meeting để chỉ việc chủ trì cuộc họp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_never', 'en-a1-24', 'never', '/ˈnevər/', 'A1', 'không bao giờ; chưa từng; tuyệt đối không (dùng để diễn tả sự từ chối hoặc ý định mạnh mẽ)', 'adv.', NULL, 'Trái nghĩa: always', 'Thường đứng trước động từ thường, và đứng sau động từ to be hoặc trợ động từ.', 'I never leave home without my water bottle.', NULL, 'Tôi không bao giờ rời khỏi nhà mà không mang theo bình nước.', '{"wordId":"never","ukIpa":"/ˈnevə/","usIpa":"/ˈnevər/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"Not at any time.","vi":"không bao giờ; chưa từng"},{"pos":"adv.","en":"Certainly not, used to express strong refusal or intention.","vi":"tuyệt đối không (dùng để diễn tả sự từ chối hoặc ý định mạnh mẽ)"}],"examples":[{"en":"I never leave home without my water bottle.","vi":"Tôi không bao giờ rời khỏi nhà mà không mang theo bình nước.","audioKind":"ex"},{"en":"Public transport can never fully replace walking and cycling as accessible forms of daily exercise.","vi":"Phương tiện giao thông công cộng không bao giờ có thể thay thế hoàn toàn việc đi bộ và đi xe đạp như những hình thức tập thể dục hàng ngày dễ tiếp cận.","audioKind":"ex2"}],"collocations":[{"en":"never again","vi":"không bao giờ nữa"},{"en":"almost never","vi":"hầu như không bao giờ"},{"en":"never before","vi":"chưa từng có trước đây"}],"wordFamily":[],"synonyms":[],"antonyms":["always"],"tipVi":"Thường đứng trước động từ thường, và đứng sau động từ to be hoặc trợ động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_middle', 'en-a1-24', 'middle', '/ˈmɪdəl/', 'A1', 'phần giữa; điểm giữa; trung tâm; ở giữa; nằm giữa', 'n.', NULL, 'Đồng nghĩa: centre, central', 'Danh từ thường dùng cụm the middle of; tính từ đứng trước để bổ nghĩa trực tiếp cho danh từ.', 'Someone left a suitcase in the middle of the hallway.', NULL, 'Ai đó đã để một chiếc vali ở giữa hành lang.', '{"wordId":"middle","ukIpa":"/ˈmɪdəl/","usIpa":"/ˈmɪdəl/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The central part, point, or position of something","vi":"phần giữa; điểm giữa; trung tâm"},{"pos":"adj.","en":"Located between other things or between the beginning and end","vi":"ở giữa; nằm giữa"}],"examples":[{"en":"Someone left a suitcase in the middle of the hallway.","vi":"Ai đó đã để một chiếc vali ở giữa hành lang.","audioKind":"ex"},{"en":"Housing costs often force essential workers to live far from the middle of the cities they serve.","vi":"Chi phí nhà ở thường buộc những người lao động thiết yếu phải sống xa trung tâm các thành phố nơi họ phục vụ.","audioKind":"ex2"}],"collocations":[{"en":"in the middle of","vi":"ở giữa"},{"en":"middle age","vi":"tuổi trung niên"},{"en":"middle class","vi":"tầng lớp trung lưu"},{"en":"middle ground","vi":"lập trường trung dung"}],"wordFamily":[],"synonyms":["centre","central"],"antonyms":[],"tipVi":"Danh từ thường dùng cụm the middle of; tính từ đứng trước để bổ nghĩa trực tiếp cho danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cool', 'en-a1-24', 'cool', '/kuːl/', 'A1', 'mát mẻ; hơi lạnh; bình tĩnh; điềm đạm; làm mát; hạ nhiệt', 'adj.', 'coolness (n.), coolly (adv.), cooling (n.)', 'Đồng nghĩa: chilly, calm · Trái nghĩa: warm', 'cool nhẹ dịu hơn cold; trong văn nói còn có nghĩa là ngầu hoặc tuyệt vời.', 'A cool breeze drifted through the open kitchen window.', NULL, 'Một luồng gió mát thổi qua ô cửa sổ bếp đang mở.', '{"wordId":"cool","ukIpa":"/kuːl/","usIpa":"/kuːl/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"slightly cold, often in a pleasant way","vi":"mát mẻ; hơi lạnh"},{"pos":"adj.","en":"calm and able to think clearly under pressure","vi":"bình tĩnh; điềm đạm"},{"pos":"v.","en":"to become or make something less hot","vi":"làm mát; hạ nhiệt"}],"examples":[{"en":"A cool breeze drifted through the open kitchen window.","vi":"Một luồng gió mát thổi qua ô cửa sổ bếp đang mở.","audioKind":"ex"},{"en":"Planting more trees can help cool urban areas and reduce energy demand during summer.","vi":"Trồng nhiều cây xanh hơn có thể giúp làm mát các khu vực đô thị và giảm nhu cầu năng lượng trong mùa hè.","audioKind":"ex2"}],"collocations":[{"en":"cool breeze","vi":"gió mát"},{"en":"keep cool","vi":"giữ bình tĩnh"},{"en":"cool down","vi":"làm mát; hạ nhiệt"}],"wordFamily":["coolness (n.)","coolly (adv.)","cooling (n.)"],"synonyms":["chilly","calm"],"antonyms":["warm"],"tipVi":"cool nhẹ dịu hơn cold; trong văn nói còn có nghĩa là ngầu hoặc tuyệt vời.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_september', 'en-a1-24', 'September', '/sepˈtembər/', 'A1', 'tháng chín', 'n.', NULL, NULL, 'Tên tháng phải viết hoa chữ cái đầu; dùng in September, nhưng trước next September không dùng in.', 'Our evening photography course starts in September this year.', NULL, 'Khóa học nhiếp ảnh buổi tối của chúng tôi bắt đầu vào tháng Chín năm nay.', '{"wordId":"september","ukIpa":"/sepˈtembə/","usIpa":"/sepˈtembər/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The month after August and before October.","vi":"tháng chín"}],"examples":[{"en":"Our evening photography course starts in September this year.","vi":"Khóa học nhiếp ảnh buổi tối của chúng tôi bắt đầu vào tháng Chín năm nay.","audioKind":"ex"},{"en":"In many countries, the academic year begins in September, creating seasonal demand for student accommodation near universities.","vi":"Ở nhiều quốc gia, năm học bắt đầu vào tháng Chín, tạo ra nhu cầu theo mùa về chỗ ở cho sinh viên gần các trường đại học.","audioKind":"ex2"}],"collocations":[{"en":"in September","vi":"vào tháng Chín"},{"en":"early September","vi":"đầu tháng Chín"},{"en":"late September","vi":"cuối tháng Chín"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tên tháng phải viết hoa chữ cái đầu; dùng in September, nhưng trước next September không dùng in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_easy', 'en-a1-24', 'easy', '/ˈiːzi/', 'A1', 'dễ dàng; không phức tạp; thoải mái; thảnh thơi', 'adj.', 'easily (adv.), ease (n.), ease (v.)', 'Đồng nghĩa: simple, straightforward · Trái nghĩa: difficult, hard', 'Thường dùng cấu trúc easy to do; để bổ nghĩa cho động từ thường dùng trạng từ easily.', 'This soup is easy to make with fresh vegetables.', NULL, 'Món súp này rất dễ nấu với các loại rau tươi.', '{"wordId":"easy","ukIpa":"/ˈiːzi/","usIpa":"/ˈiːzi/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Not difficult and requiring little effort.","vi":"dễ dàng; không phức tạp"},{"pos":"adj.","en":"Relaxed and free from worry or pressure.","vi":"thoải mái; thảnh thơi"}],"examples":[{"en":"This soup is easy to make with fresh vegetables.","vi":"Món súp này rất dễ nấu với các loại rau tươi.","audioKind":"ex"},{"en":"Providing easy access to reliable health information can help people make better decisions about their lifestyles.","vi":"Việc giúp người dân dễ dàng tiếp cận thông tin y tế đáng tin cậy có thể giúp họ đưa ra những lựa chọn tốt hơn về lối sống.","audioKind":"ex2"}],"collocations":[{"en":"easy to use","vi":"dễ sử dụng"},{"en":"easy access to","vi":"dễ tiếp cận"},{"en":"take it easy","vi":"cứ thảnh thơi; cứ từ từ"},{"en":"easy life","vi":"cuộc sống an nhàn"}],"wordFamily":["easily (adv.)","ease (n.)","ease (v.)"],"synonyms":["simple","straightforward"],"antonyms":["difficult","hard"],"tipVi":"Thường dùng cấu trúc easy to do; để bổ nghĩa cho động từ thường dùng trạng từ easily.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thing', 'en-a1-24', 'thing', '/θɪŋ/', 'A1', 'đồ vật; vật dụng; sự việc; vấn đề; đồ đạc cá nhân', 'n.', NULL, NULL, 'thing có nghĩa rất chung chung; trong văn viết trang trọng nên thay thế bằng danh từ cụ thể.', 'Could you move that heavy thing off my chair?', NULL, 'Bạn có thể dịch chuyển thứ nặng nề đó ra khỏi ghế của tôi được không?', '{"wordId":"thing","ukIpa":"/θɪŋ/","usIpa":"/θɪŋ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"an object whose name is unknown or not specified","vi":"đồ vật; vật dụng"},{"pos":"n.","en":"an action, event, fact, or situation","vi":"sự việc; vấn đề"},{"pos":"n.","en":"possessions or equipment, usually referred to in the plural","vi":"đồ đạc cá nhân"}],"examples":[{"en":"Could you move that heavy thing off my chair?","vi":"Bạn có thể dịch chuyển thứ nặng nề đó ra khỏi ghế của tôi được không?","audioKind":"ex"},{"en":"One important thing governments can do is ensure that affordable housing is available near public transport.","vi":"Một điều quan trọng mà các chính phủ có thể làm là đảm bảo có nhà ở giá rẻ gần các phương tiện giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"the right thing to do","vi":"việc nên làm"},{"en":"personal things","vi":"đồ dùng cá nhân"},{"en":"first thing in the morning","vi":"việc đầu tiên vào buổi sáng"},{"en":"one thing at a time","vi":"làm từng việc một"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"thing có nghĩa rất chung chung; trong văn viết trang trọng nên thay thế bằng danh từ cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_anything', 'en-a1-24', 'anything', '/ˈeniθɪŋ/', 'A1', 'bất cứ thứ gì; bất cứ điều gì; thứ gì đó; điều gì đó (thường dùng trong câu hỏi và câu điều kiện)', 'pron.', NULL, 'Trái nghĩa: nothing', 'Trong câu hỏi thường mang nghĩa là "gì", "gì chứ"; trong câu khẳng định/phủ định có thể mang nghĩa là "bất cứ sự vật/điều gì".', 'You can choose anything from this basket of toys.', NULL, 'Bạn có thể chọn bất kỳ món đồ chơi nào từ giỏ này.', '{"wordId":"anything","ukIpa":"/ˈeniθɪŋ/","usIpa":"/ˈeniθɪŋ/","cefr":"A1","topic":"daily","senses":[{"pos":"pron.","en":"Any thing at all, without limits on choice","vi":"bất cứ thứ gì; bất cứ điều gì"},{"pos":"pron.","en":"Something, used especially in questions and conditional statements","vi":"thứ gì đó; điều gì đó (thường dùng trong câu hỏi và câu điều kiện)"}],"examples":[{"en":"You can choose anything from this basket of toys.","vi":"Bạn có thể chọn bất kỳ món đồ chơi nào từ giỏ này.","audioKind":"ex"},{"en":"Before introducing new policies, governments should check whether anything similar has worked successfully elsewhere.","vi":"Trước khi ban hành các chính sách mới, chính quyền nên kiểm tra xem có điều gì tương tự đã áp dụng thành công ở nơi khác hay chưa.","audioKind":"ex2"}],"collocations":[{"en":"anything else","vi":"thứ gì khác"},{"en":"anything at all","vi":"bất cứ thứ gì"},{"en":"anything but","vi":"hoàn toàn không phải; chứ không phải là"}],"wordFamily":[],"synonyms":[],"antonyms":["nothing"],"tipVi":"Trong câu hỏi thường mang nghĩa là \"gì\", \"gì chứ\"; trong câu khẳng định/phủ định có thể mang nghĩa là \"bất cứ sự vật/điều gì\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_forty', 'en-a1-24', 'forty', '/ˈfɔːrti/', 'A1', 'số bốn mươi', 'num.', 'fortieth (num.)', NULL, 'Chính tả là forty, không phải fourty; độ tuổi từ 40 đến 49 dùng in one''s forties.', 'We waited forty minutes before the bus finally arrived.', NULL, 'Chúng tôi đã đợi bốn mươi phút trước khi chiếc xe buýt cuối cùng cũng đến.', '{"wordId":"forty","ukIpa":"/ˈfɔːti/","usIpa":"/ˈfɔːrti/","cefr":"A1","topic":"daily","senses":[{"pos":"num.","en":"the number equal to four times ten","vi":"số bốn mươi"}],"examples":[{"en":"We waited forty minutes before the bus finally arrived.","vi":"Chúng tôi đã đợi bốn mươi phút trước khi chiếc xe buýt cuối cùng cũng đến.","audioKind":"ex"},{"en":"The survey found that forty percent of local residents preferred cycling to driving for short journeys.","vi":"Khảo sát cho thấy bốn mươi phần trăm cư dân địa phương thích đi xe đạp hơn là lái xe cho những chuyến đi ngắn.","audioKind":"ex2"}],"collocations":[{"en":"forty minutes","vi":"bốn mươi phút"},{"en":"forty percent","vi":"bốn mươi phần trăm"},{"en":"in her forties","vi":"ở độ tuổi ngoài bốn mươi"}],"wordFamily":["fortieth (num.)"],"synonyms":[],"antonyms":[],"tipVi":"Chính tả là forty, không phải fourty; độ tuổi từ 40 đến 49 dùng in one''s forties.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chocolate', 'en-a1-24', 'chocolate', '/ˈtʃɑːklət/', 'A1', 'sô-cô-la; viên sô-cô-la; kẹo sô-cô-la', 'n.', 'chocolaty (adj.), chocolatier (n.)', NULL, 'Danh từ chỉ nguyên liệu sô-cô-la là không đếm được; viên sô-cô-la hoặc kẹo sô-cô-la riêng lẻ là đếm được.', 'He shared a bar of chocolate with his sister.', NULL, 'Cậu ấy chia một thanh sô-cô-la với em gái của mình.', '{"wordId":"chocolate","ukIpa":"/ˈtʃɒklət/","usIpa":"/ˈtʃɑːklət/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A sweet food made from cocoa, often with milk and sugar.","vi":"sô-cô-la"},{"pos":"n.","en":"An individual sweet made of chocolate, sometimes with a filling.","vi":"viên sô-cô-la; kẹo sô-cô-la"}],"examples":[{"en":"He shared a bar of chocolate with his sister.","vi":"Cậu ấy chia một thanh sô-cô-la với em gái của mình.","audioKind":"ex"},{"en":"Consumers increasingly expect chocolate producers to ensure fair wages and safe working conditions throughout their supply chains.","vi":"Người tiêu dùng ngày càng kỳ vọng các nhà sản xuất sô-cô-la đảm bảo mức lương công bằng và điều kiện làm việc an toàn xuyên suốt chuỗi cung ứng của họ.","audioKind":"ex2"}],"collocations":[{"en":"dark chocolate","vi":"sô-cô-la đen"},{"en":"milk chocolate","vi":"sô-cô-la sữa"},{"en":"a bar of chocolate","vi":"một thanh sô-cô-la"},{"en":"a box of chocolates","vi":"một hộp sô-cô-la"}],"wordFamily":["chocolaty (adj.)","chocolatier (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ chỉ nguyên liệu sô-cô-la là không đếm được; viên sô-cô-la hoặc kẹo sô-cô-la riêng lẻ là đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_size', 'en-a1-24', 'size', '/saɪz/', 'A1', 'kích cỡ; quy mô; cỡ; số; phân loại theo kích cỡ; điều chỉnh kích thước', 'n.', 'sizable (adj.), sized (adj.)', NULL, 'Hỏi kích cỡ/số dùng What size, không dùng How much size.', 'This suitcase is just the right size for weekends.', NULL, 'Chiếc va-li này có kích cỡ vừa vặn cho các chuyến đi cuối tuần.', '{"wordId":"size","ukIpa":"/saɪz/","usIpa":"/saɪz/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"How big or small someone or something is.","vi":"kích cỡ; quy mô"},{"pos":"n.","en":"A standard measurement used for clothes and other products.","vi":"cỡ; số"},{"pos":"v.","en":"To sort by measurements or make something a particular size.","vi":"phân loại theo kích cỡ; điều chỉnh kích thước"}],"examples":[{"en":"This suitcase is just the right size for weekends.","vi":"Chiếc va-li này có kích cỡ vừa vặn cho các chuyến đi cuối tuần.","audioKind":"ex"},{"en":"Reducing class size may allow teachers to provide more individual support to students with learning difficulties.","vi":"Việc thu hẹp quy mô lớp học có thể giúp giáo viên hỗ trợ cá nhân tốt hơn cho những học sinh gặp khó khăn trong học tập.","audioKind":"ex2"}],"collocations":[{"en":"class size","vi":"quy mô lớp học"},{"en":"sample size","vi":"quy mô mẫu"},{"en":"shoe size","vi":"cỡ giày"},{"en":"in size","vi":"về kích thước"}],"wordFamily":["sizable (adj.)","sized (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Hỏi kích cỡ/số dùng What size, không dùng How much size.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_small', 'en-a1-24', 'small', '/smɔːl/', 'A1', 'nhỏ; ít; nhỏ tuổi; chưa trưởng thành; không quan trọng; nhỏ nhặt', 'adj.', 'smallness (n.)', 'Đồng nghĩa: little · Trái nghĩa: large, big', 'Số lượng ít có thể nói a small number of, nhưng không nói small people.', 'Our small kitchen has room for only two chairs.', NULL, 'Căn bếp nhỏ của chúng tôi chỉ đủ chỗ cho hai chiếc ghế.', '{"wordId":"small","ukIpa":"/smɔːl/","usIpa":"/smɔːl/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Limited in size, amount, or degree.","vi":"nhỏ; ít"},{"pos":"adj.","en":"Young and not yet fully grown.","vi":"nhỏ tuổi; chưa trưởng thành"},{"pos":"adj.","en":"Not very important or serious.","vi":"không quan trọng; nhỏ nhặt"}],"examples":[{"en":"Our small kitchen has room for only two chairs.","vi":"Căn bếp nhỏ của chúng tôi chỉ đủ chỗ cho hai chiếc ghế.","audioKind":"ex"},{"en":"Even small improvements in home insulation can reduce energy consumption and lower household bills.","vi":"Ngay cả những cải thiện nhỏ đối với khả năng cách nhiệt của ngôi nhà cũng có thể giảm mức tiêu thụ năng lượng và hạ hóa đơn sinh hoạt gia đình.","audioKind":"ex2"}],"collocations":[{"en":"a small amount of","vi":"một lượng nhỏ"},{"en":"small businesses","vi":"doanh nghiệp nhỏ"},{"en":"small children","vi":"trẻ nhỏ"},{"en":"a small change","vi":"một thay đổi nhỏ"}],"wordFamily":["smallness (n.)"],"synonyms":["little"],"antonyms":["large","big"],"tipVi":"Số lượng ít có thể nói a small number of, nhưng không nói small people.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_picnic', 'en-a1-24', 'picnic', '/ˈpɪknɪk/', 'A1', 'chuyến dã ngoại; bữa ăn ngoài trời; đi dã ngoại; ăn uống ngoài trời', 'n.', 'picnicker (n.)', NULL, 'Động từ quá khứ là picnicked, dạng tiếp diễn là picnicking.', 'We had a picnic under a shady tree.', NULL, 'Chúng tôi đã có một buổi dã ngoại dưới tán cây râm mát.', '{"wordId":"picnic","ukIpa":"/ˈpɪknɪk/","usIpa":"/ˈpɪknɪk/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a meal eaten outdoors, usually with food brought from home","vi":"chuyến dã ngoại; bữa ăn ngoài trời"},{"pos":"v.","en":"to eat a meal outdoors for pleasure","vi":"đi dã ngoại; ăn uống ngoài trời"}],"examples":[{"en":"We had a picnic under a shady tree.","vi":"Chúng tôi đã có một buổi dã ngoại dưới tán cây râm mát.","audioKind":"ex"},{"en":"Public parks provide affordable spaces where families can enjoy picnics and spend quality time together.","vi":"Các công viên công cộng cung cấp không gian vừa phải để các gia đình tận hưởng những buổi dã ngoại và quây quần bên nhau.","audioKind":"ex2"}],"collocations":[{"en":"have a picnic","vi":"tổ chức dã ngoại"},{"en":"go on a picnic","vi":"đi dã ngoại"},{"en":"picnic basket","vi":"giỏ đựng đồ dã ngoại"}],"wordFamily":["picnicker (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ quá khứ là picnicked, dạng tiếp diễn là picnicking.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_begin', 'en-a1-24', 'begin', '/bɪˈɡɪn/', 'A1', 'bắt đầu; khởi đầu', 'v.', 'beginning (n.), beginner (n.)', 'Đồng nghĩa: start, commence · Trái nghĩa: finish, end', 'Dạng quá khứ là began, quá khứ phân từ là begun; theo sau có thể là động từ nguyên mẫu có to hoặc động từ thêm đuôi -ing.', 'We begin dinner when everyone is sitting at the table.', NULL, 'Chúng tôi bắt đầu ăn tối khi mọi người đã ngồi vào bàn.', '{"wordId":"begin","ukIpa":"/bɪˈɡɪn/","usIpa":"/bɪˈɡɪn/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to start happening or start doing something","vi":"bắt đầu; khởi đầu"}],"examples":[{"en":"We begin dinner when everyone is sitting at the table.","vi":"Chúng tôi bắt đầu ăn tối khi mọi người đã ngồi vào bàn.","audioKind":"ex"},{"en":"Schools should begin teaching digital safety early so that children develop responsible habits when using the internet.","vi":"Các trường học nên bắt đầu giáo dục an toàn kỹ thuật số từ sớm để trẻ em hình thành thói quen sử dụng Internet có trách nhiệm.","audioKind":"ex2"}],"collocations":[{"en":"begin with","vi":"bắt đầu với"},{"en":"begin to understand","vi":"bắt đầu hiểu ra"},{"en":"begin a discussion","vi":"bắt đầu một cuộc thảo luận"},{"en":"to begin with","vi":"trước hết; thoạt đầu"}],"wordFamily":["beginning (n.)","beginner (n.)"],"synonyms":["start","commence"],"antonyms":["finish","end"],"tipVi":"Dạng quá khứ là began, quá khứ phân từ là begun; theo sau có thể là động từ nguyên mẫu có to hoặc động từ thêm đuôi -ing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_enough', 'en-a1-24', 'enough', '/ɪˈnʌf/', 'A1', 'đủ; số lượng đủ', 'det.', NULL, 'Đồng nghĩa: sufficient · Trái nghĩa: insufficient', 'Đặt enough đứng trước danh từ, nhưng đặt đứng sau tính từ hoặc trạng từ.', 'We have enough rice to feed everyone tonight.', NULL, 'Chúng ta có đủ gạo để nấu cho mọi người ăn tối nay.', '{"wordId":"enough","ukIpa":"/ɪˈnʌf/","usIpa":"/ɪˈnʌf/","cefr":"A1","topic":"daily","senses":[{"pos":"det.","en":"as much or as many as needed","vi":"đủ"},{"pos":"adv.","en":"to the degree that is needed","vi":"đủ"},{"pos":"pron.","en":"an amount that meets a need","vi":"số lượng đủ"}],"examples":[{"en":"We have enough rice to feed everyone tonight.","vi":"Chúng ta có đủ gạo để nấu cho mọi người ăn tối nay.","audioKind":"ex"},{"en":"Many rural schools lack enough resources to provide students with a broad range of subjects.","vi":"Nhiều trường học ở nông thôn thiếu nguồn lực cần thiết để cung cấp cho học sinh các môn học đa dạng.","audioKind":"ex2"}],"collocations":[{"en":"enough time","vi":"đủ thời gian"},{"en":"good enough","vi":"đủ tốt"},{"en":"enough to eat","vi":"đủ đồ ăn"}],"wordFamily":[],"synonyms":["sufficient"],"antonyms":["insufficient"],"tipVi":"Đặt enough đứng trước danh từ, nhưng đặt đứng sau tính từ hoặc trạng từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_few', 'en-a1-24', 'few', '/fjuː/', 'A1', 'ít; một vài; ít người; ít vật', 'det.', 'fewer (det.), fewest (det.)', 'Trái nghĩa: many', 'few mang nghĩa phủ định (hầu như không có), a few mang nghĩa khẳng định (có một vài); cả hai đều đi với danh từ đếm được số nhiều.', 'There were few customers in the shop this morning.', NULL, 'Sáng nay có rất ít khách hàng trong cửa hàng.', '{"wordId":"few","ukIpa":"/fjuː/","usIpa":"/fjuː/","cefr":"A1","topic":"daily","senses":[{"pos":"det.","en":"Not many; a small number of countable things.","vi":"ít; một vài"},{"pos":"pron.","en":"A small number of people or things.","vi":"ít người; ít vật"}],"examples":[{"en":"There were few customers in the shop this morning.","vi":"Sáng nay có rất ít khách hàng trong cửa hàng.","audioKind":"ex"},{"en":"Few rural communities have access to the specialist medical services available in major cities.","vi":"Rất ít cộng đồng nông thôn có thể tiếp cận các dịch vụ y tế chuyên khoa vốn có ở các thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"a few days","vi":"một vài ngày"},{"en":"very few people","vi":"rất ít người"},{"en":"few and far between","vi":"hiếm khi; rất ít"}],"wordFamily":["fewer (det.)","fewest (det.)"],"synonyms":[],"antonyms":["many"],"tipVi":"few mang nghĩa phủ định (hầu như không có), a few mang nghĩa khẳng định (có một vài); cả hai đều đi với danh từ đếm được số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_april', 'en-a1-24', 'April', '/ˈeɪprəl/', 'A1', 'tháng Tư', 'n.', NULL, NULL, 'Viết hoa chữ cái đầu của tháng; dùng "in" trước tháng, dùng "on" trước ngày cụ thể.', 'We are moving into our new flat in April.', NULL, 'Chúng tôi sẽ chuyển vào căn hộ mới vào tháng Tư.', '{"wordId":"april","ukIpa":"/ˈeɪprəl/","usIpa":"/ˈeɪprəl/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The fourth month of the year.","vi":"tháng Tư"}],"examples":[{"en":"We are moving into our new flat in April.","vi":"Chúng tôi sẽ chuyển vào căn hộ mới vào tháng Tư.","audioKind":"ex"},{"en":"The community garden will open in April, giving local residents more opportunities to grow their own vegetables.","vi":"Khu vườn cộng đồng sẽ mở cửa vào tháng Tư, mang lại cho cư dân địa phương nhiều cơ hội hơn để tự trồng rau.","audioKind":"ex2"}],"collocations":[{"en":"in April","vi":"vào tháng Tư"},{"en":"early April","vi":"đầu tháng Tư"},{"en":"late April","vi":"cuối tháng Tư"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Viết hoa chữ cái đầu của tháng; dùng \"in\" trước tháng, dùng \"on\" trước ngày cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_with', 'en-a1-24', 'with', '/wɪð/', 'A1', 'cùng với; với; có; mang theo; bằng; dùng', 'prep.', NULL, 'Trái nghĩa: without', 'Sau "with" là danh từ hoặc đại từ tân ngữ, ví dụ "with me".', 'I cooked dinner with my sister last night.', NULL, 'Tối qua tôi đã nấu bữa tối cùng chị gái.', '{"wordId":"with","ukIpa":"/wɪð/","usIpa":"/wɪð/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"Accompanied by another person or thing.","vi":"cùng với; với"},{"pos":"prep.","en":"Having or including a particular feature or thing.","vi":"có; mang theo"},{"pos":"prep.","en":"Using a particular tool, material, or means.","vi":"bằng; dùng"}],"examples":[{"en":"I cooked dinner with my sister last night.","vi":"Tối qua tôi đã nấu bữa tối cùng chị gái.","audioKind":"ex"},{"en":"Schools should work with local communities to provide children with safe spaces for outdoor activities.","vi":"Nhà trường nên phối hợp với cộng đồng địa phương để cung cấp cho trẻ em những không gian an toàn cho các hoạt động ngoài trời.","audioKind":"ex2"}],"collocations":[{"en":"work with someone","vi":"làm việc với ai đó"},{"en":"with care","vi":"cẩn thận"},{"en":"agree with someone","vi":"đồng ý với ai đó"},{"en":"with the help of","vi":"với sự giúp đỡ của"}],"wordFamily":[],"synonyms":[],"antonyms":["without"],"tipVi":"Sau \"with\" là danh từ hoặc đại từ tân ngữ, ví dụ \"with me\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_24_1', 'en-a1-24', 'Cách dùng “few” (det.) — ít; một vài', 'a few days  ·  very few people  ·  few and far between', 'few mang nghĩa phủ định (hầu như không có), a few mang nghĩa khẳng định (có một vài); cả hai đều đi với danh từ đếm được số nhiều.', 'Họ từ (Word Family): fewer (det.), fewest (det.) | Trái nghĩa: many', '[{"hanzi":"There were few customers in the shop this morning.","pinyin":"","meaning":"Sáng nay có rất ít khách hàng trong cửa hàng."},{"hanzi":"Few rural communities have access to the specialist medical services available in major cities.","pinyin":"","meaning":"Rất ít cộng đồng nông thôn có thể tiếp cận các dịch vụ y tế chuyên khoa vốn có ở các thành phố lớn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_24_2', 'en-a1-24', 'Cách dùng “anything” (pron.) — bất cứ thứ gì; bất cứ điều gì', 'anything else  ·  anything at all  ·  anything but', 'Trong câu hỏi thường mang nghĩa là "gì", "gì chứ"; trong câu khẳng định/phủ định có thể mang nghĩa là "bất cứ sự vật/điều gì".', 'Trái nghĩa: nothing', '[{"hanzi":"You can choose anything from this basket of toys.","pinyin":"","meaning":"Bạn có thể chọn bất kỳ món đồ chơi nào từ giỏ này."},{"hanzi":"Before introducing new policies, governments should check whether anything similar has worked successfully elsewhere.","pinyin":"","meaning":"Trước khi ban hành các chính sách mới, chính quyền nên kiểm tra xem có điều gì tương tự đã áp dụng thành công ở nơi khác hay chưa."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_24_3', 'en-a1-24', 'Cách dùng “begin” (v.) — bắt đầu; khởi đầu', 'begin with  ·  begin to understand  ·  begin a discussion', 'Dạng quá khứ là began, quá khứ phân từ là begun; theo sau có thể là động từ nguyên mẫu có to hoặc động từ thêm đuôi -ing.', 'Họ từ (Word Family): beginning (n.), beginner (n.) | Đồng nghĩa: start, commence | Trái nghĩa: finish, end', '[{"hanzi":"We begin dinner when everyone is sitting at the table.","pinyin":"","meaning":"Chúng tôi bắt đầu ăn tối khi mọi người đã ngồi vào bàn."},{"hanzi":"Schools should begin teaching digital safety early so that children develop responsible habits when using the internet.","pinyin":"","meaning":"Các trường học nên bắt đầu giáo dục an toàn kỹ thuật số từ sớm để trẻ em hình thành thói quen sử dụng Internet có trách nhiệm."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_24_4', 'en-a1-24', 'Cách dùng “chocolate” (n.) — sô-cô-la', 'dark chocolate  ·  milk chocolate  ·  a bar of chocolate', 'Danh từ chỉ nguyên liệu sô-cô-la là không đếm được; viên sô-cô-la hoặc kẹo sô-cô-la riêng lẻ là đếm được.', 'Họ từ (Word Family): chocolaty (adj.), chocolatier (n.)', '[{"hanzi":"He shared a bar of chocolate with his sister.","pinyin":"","meaning":"Cậu ấy chia một thanh sô-cô-la với em gái của mình."},{"hanzi":"Consumers increasingly expect chocolate producers to ensure fair wages and safe working conditions throughout their supply chains.","pinyin":"","meaning":"Người tiêu dùng ngày càng kỳ vọng các nhà sản xuất sô-cô-la đảm bảo mức lương công bằng và điều kiện làm việc an toàn xuyên suốt chuỗi cung ứng của họ."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_24_1', 'en-a1-24', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_24_1_1', 'ten_24_1', 'hey', 'Hey, you left your umbrella beside the door!', 'Hey, you left your umbrella beside the door!', '/heɪ/', 'Này, bạn bỏ quên ô ở cạnh cửa rồi!', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_24_1_2', 'ten_24_1', 'cola', 'He poured cold cola into a glass with ice.', 'He poured cold cola into a glass with ice.', '/ˈkoʊlə/', 'Anh ấy rót nước cô-la lạnh vào một chiếc cốc có đá.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_24_1_3', 'ten_24_1', 'shower', 'I always take a warm shower after cycling home.', 'I always take a warm shower after cycling home.', '/ˈʃaʊər/', 'Tôi luôn tắm nước ấm sau khi đạp xe về nhà.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_24_1_4', 'ten_24_1', 'early', 'We caught an early train and arrived before breakfast.', 'We caught an early train and arrived before breakfast.', '/ˈɝːli/', 'Chúng tôi đã bắt một chuyến tàu sớm và đến nơi trước bữa sáng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_24_1_5', 'ten_24_1', 'these', 'These strawberries smell lovely, so let''s buy a basket.', 'These strawberries smell lovely, so let''s buy a basket.', '/ðiːz/', 'Những quả dâu tây này thơm quá, chúng ta mua một giỏ nhé.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_24_1_6', 'ten_24_1', 'favourite', 'This little bakery sells my favourite kind of bread.', 'This little bakery sells my favourite kind of bread.', '/ˈfeɪvərɪt/', 'Tiệm bánh nhỏ này bán loại bánh mì yêu thích của tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_24_1_7', 'ten_24_1', 'clock', 'The kitchen clock stopped while we were making lunch.', 'The kitchen clock stopped while we were making lunch.', '/klɑːk/', 'Đồng hồ trong bếp đã ngừng chạy khi chúng tôi đang chuẩn bị bữa trưa.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_24_1_8', 'ten_24_1', 'downstairs', 'I went downstairs when I smelled fresh bread.', 'I went downstairs when I smelled fresh bread.', '/ˌdaʊnˈsterz/', 'Tôi đi xuống tầng dưới khi ngửi thấy mùi bánh mì tươi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_24_1_1', 'en-a1-24', 'ten_24_1', 'listening', 'listening', 'Hey, you left your umbrella beside the door!', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Anh ấy rót nước cô-la lạnh vào một chiếc cốc có đá.","Đồng hồ trong bếp đã ngừng chạy khi chúng tôi đang chuẩn bị bữa trưa.","Này, bạn bỏ quên ô ở cạnh cửa rồi!","Chúng tôi đã bắt một chuyến tàu sớm và đến nơi trước bữa sáng."]'::jsonb, 2, 'Hey, you left your umbrella beside the door! → Này, bạn bỏ quên ô ở cạnh cửa rồi!', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_24_1_2', 'en-a1-24', 'ten_24_1', 'listening', 'listening', 'He poured cold cola into a glass with ice.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Anh ấy rót nước cô-la lạnh vào một chiếc cốc có đá.","Tôi luôn tắm nước ấm sau khi đạp xe về nhà.","Này, bạn bỏ quên ô ở cạnh cửa rồi!","Đồng hồ trong bếp đã ngừng chạy khi chúng tôi đang chuẩn bị bữa trưa."]'::jsonb, 0, 'He poured cold cola into a glass with ice. → Anh ấy rót nước cô-la lạnh vào một chiếc cốc có đá.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_24_1_3', 'en-a1-24', 'ten_24_1', 'listening', 'listening', 'I always take a warm shower after cycling home.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Đồng hồ trong bếp đã ngừng chạy khi chúng tôi đang chuẩn bị bữa trưa.","Tôi luôn tắm nước ấm sau khi đạp xe về nhà.","Những quả dâu tây này thơm quá, chúng ta mua một giỏ nhé.","Chúng tôi đã bắt một chuyến tàu sớm và đến nơi trước bữa sáng."]'::jsonb, 1, 'I always take a warm shower after cycling home. → Tôi luôn tắm nước ấm sau khi đạp xe về nhà.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_24_2', 'en-a1-24', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_24_2_1', 'ten_24_2', 'hey', 'Informal greetings such as hey may be inappropriate when students first contact university staff by email.', 'Informal greetings such as hey may be inappropriate when students first contact university staff by email.', '/heɪ/', 'Những lời chào thân mật như hey có thể không phù hợp khi sinh viên lần đầu liên hệ với nhân viên trường đại học qua email.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_24_2_2', 'ten_24_2', 'cola', 'Reducing the consumption of sugary drinks such as cola may help prevent tooth decay in children.', 'Reducing the consumption of sugary drinks such as cola may help prevent tooth decay in children.', '/ˈkoʊlə/', 'Giảm tiêu thụ đồ uống có đường như nước cô-la có thể giúp ngăn ngừa sâu răng ở trẻ em.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_24_2_3', 'ten_24_2', 'shower', 'Taking shorter showers is a simple way for households to reduce both water consumption and energy use.', 'Taking shorter showers is a simple way for households to reduce both water consumption and energy use.', '/ˈʃaʊər/', 'Tắm vòi hoa sen nhanh hơn là một cách đơn giản để các hộ gia đình giảm cả lượng nước và năng lượng tiêu thụ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_24_2_4', 'ten_24_2', 'early', 'Early investment in childhood education can reduce inequality and improve employment prospects later in life.', 'Early investment in childhood education can reduce inequality and improve employment prospects later in life.', '/ˈɝːli/', 'Đầu tư sớm vào giáo dục mầm non có thể làm giảm sự bất bình đẳng và cải thiện cơ hội việc làm sau này trong đời.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_24_2_5', 'ten_24_2', 'these', 'These findings suggest that regular outdoor activities can improve children''s concentration and emotional health.', 'These findings suggest that regular outdoor activities can improve children''s concentration and emotional health.', '/ðiːz/', 'Những kết quả nghiên cứu này cho thấy các hoạt động ngoài trời thường xuyên có thể cải thiện khả năng tập trung và sức khỏe cảm xúc của trẻ em.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_24_2_6', 'ten_24_2', 'favourite', 'Public libraries allow readers to discover new authors as well as revisit their favourite books without additional cost.', 'Public libraries allow readers to discover new authors as well as revisit their favourite books without additional cost.', '/ˈfeɪvərɪt/', 'Các thư viện công cộng giúp độc giả khám phá các tác giả mới cũng như đọc lại những cuốn sách yêu thích của họ mà không phải tốn thêm chi phí.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_24_2_1', 'en-a1-24', 'ten_24_2', 'listening', 'listening', 'Informal greetings such as hey may be inappropriate when students first contact university staff by email.', NULL, 'Trong câu vừa nghe, từ “hey” mang nghĩa nào sau đây?', '["này; chào (dùng thân mật để chào hỏi hoặc thu hút sự chú ý)","khoảnh khắc; chốc lát","vậy; đến mức độ này; quá","xe ô tô; xe hơi"]'::jsonb, 0, '“hey” (/heɪ/): này; chào (dùng thân mật để chào hỏi hoặc thu hút sự chú ý). Câu đầy đủ: Informal greetings such as hey may be inappropriate when students first contact university staff by email.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_24_2_2', 'en-a1-24', 'ten_24_2', 'listening', 'listening', 'Reducing the consumption of sugary drinks such as cola may help prevent tooth decay in children.', NULL, 'Trong câu vừa nghe, từ “cola” mang nghĩa nào sau đây?', '["châu Á","quả cam; trái cam","ngôi sao; vì sao","nước cô-la; nước ngọt có gas"]'::jsonb, 3, '“cola” (/ˈkoʊlə/): nước cô-la; nước ngọt có gas. Câu đầy đủ: Reducing the consumption of sugary drinks such as cola may help prevent tooth decay in children.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
