INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_24_2', 'en-a1-24', NULL, 'comprehensive_test', 'listening', 'He poured cold cola into a glass with ice.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã bắt một chuyến tàu sớm và đến nơi trước bữa sáng.","Tối qua tôi đã nấu bữa tối cùng chị gái.","Món súp này rất dễ nấu với các loại rau tươi.","Anh ấy rót nước cô-la lạnh vào một chiếc cốc có đá."]'::jsonb, 3, 'He poured cold cola into a glass with ice. → Anh ấy rót nước cô-la lạnh vào một chiếc cốc có đá.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_24_3', 'en-a1-24', NULL, 'comprehensive_test', 'listening', 'shower', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["món salad; rau trộn","vòi hoa sen; việc tắm dưới vòi hoa sen","vì; bởi vì","có chiều dài lớn hoặc kéo dài trong khoảng thời gian lâu"]'::jsonb, 1, 'shower (/ˈʃaʊər/) → vòi hoa sen; việc tắm dưới vòi hoa sen; cơn mưa rào; tắm dưới vòi hoa sen', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_24_4', 'en-a1-24', NULL, 'comprehensive_test', 'listening', 'We caught an early train and arrived before breakfast.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh ấy rót nước cô-la lạnh vào một chiếc cốc có đá.","Chúng tôi đã đợi bốn mươi phút trước khi chiếc xe buýt cuối cùng cũng đến.","Chúng tôi đã bắt một chuyến tàu sớm và đến nơi trước bữa sáng.","Chúng ta có đủ gạo để nấu cho mọi người ăn tối nay."]'::jsonb, 2, 'We caught an early train and arrived before breakfast. → Chúng tôi đã bắt một chuyến tàu sớm và đến nơi trước bữa sáng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_24_5', 'en-a1-24', NULL, 'comprehensive_test', 'listening', 'these', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thứ nhất; đầu tiên","vườn; khu vườn","những... này (dùng trước danh từ số nhiều chỉ người hoặc vật ở gần)","thay đổi; đổi; quy đổi tiền tệ"]'::jsonb, 2, 'these (/ðiːz/) → những... này (dùng trước danh từ số nhiều chỉ người hoặc vật ở gần); những người này; những vật này; những điều vừa nhắc đến', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_24_6', 'en-a1-24', NULL, 'comprehensive_test', 'listening', 'This little bakery sells my favourite kind of bread.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một luồng gió mát thổi qua ô cửa sổ bếp đang mở.","Chúng ta có đủ gạo để nấu cho mọi người ăn tối nay.","Tiệm bánh nhỏ này bán loại bánh mì yêu thích của tôi.","Bạn có thể chọn bất kỳ món đồ chơi nào từ giỏ này."]'::jsonb, 2, 'This little bakery sells my favourite kind of bread. → Tiệm bánh nhỏ này bán loại bánh mì yêu thích của tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_24_7', 'en-a1-24', NULL, 'comprehensive_test', 'listening', 'clock', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thường xuyên; thông thường","gửi; truyền đi","bốn; số bốn","đồng hồ (treo tường hoặc để bàn)"]'::jsonb, 3, 'clock (/klɑːk/) → đồng hồ (treo tường hoặc để bàn); đo lường hoặc ghi lại thời gian hoặc tốc độ của cái gì đó', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_24_8', 'en-a1-24', NULL, 'comprehensive_test', 'listening', 'I went downstairs when I smelled fresh bread.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đi xuống tầng dưới khi ngửi thấy mùi bánh mì tươi.","Cậu ấy chia một thanh sô-cô-la với em gái của mình.","Chúng tôi đã có một buổi dã ngoại dưới tán cây râm mát.","Bạn có thể chọn bất kỳ món đồ chơi nào từ giỏ này."]'::jsonb, 0, 'I went downstairs when I smelled fresh bread. → Tôi đi xuống tầng dưới khi ngửi thấy mùi bánh mì tươi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_24_9', 'en-a1-24', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Used before plural nouns for nearby people or things.”?', '["chair","small","favourite","these"]'::jsonb, 3, 'these (/ðiːz/) → những... này (dùng trước danh từ số nhiều chỉ người hoặc vật ở gần)', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
