INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_24_18', 'en-a1-24', NULL, 'comprehensive_test', 'reading', NULL, 'Informal greetings such as hey may be inappropriate when students first contact university staff by email.', 'Dựa vào câu trên, từ “hey” có nghĩa phù hợp nhất là gì?', '["số không","này; chào (dùng thân mật để chào hỏi hoặc thu hút sự chú ý)","đói bụng; đói","đi (xe đạp, xe máy, ngựa hoặc phương tiện khác)"]'::jsonb, 1, 'hey: này; chào (dùng thân mật để chào hỏi hoặc thu hút sự chú ý). Dịch cả câu: Những lời chào thân mật như hey có thể không phù hợp khi sinh viên lần đầu liên hệ với nhân viên trường đại học qua email.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_24_19', 'en-a1-24', NULL, 'comprehensive_test', 'reading', NULL, 'Reducing the consumption of sugary drinks such as cola may help prevent tooth decay in children.', 'Dựa vào câu trên, từ “cola” có nghĩa phù hợp nhất là gì?', '["phòng; buồng","thú vị; hay; hấp dẫn","nước cô-la; nước ngọt có gas","phải; cần phải"]'::jsonb, 2, 'cola: nước cô-la; nước ngọt có gas. Dịch cả câu: Giảm tiêu thụ đồ uống có đường như nước cô-la có thể giúp ngăn ngừa sâu răng ở trẻ em.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_24_20', 'en-a1-24', NULL, 'comprehensive_test', 'reading', NULL, 'Taking shorter showers is a simple way for households to reduce both water consumption and energy use.', 'Dựa vào câu trên, từ “shower” có nghĩa phù hợp nhất là gì?', '["vòi hoa sen; việc tắm dưới vòi hoa sen","khóc; rơi nước mắt","có được; nhận được; thu được","kém; tồi; chất lượng không tốt hoặc không đạt yêu cầu"]'::jsonb, 0, 'shower: vòi hoa sen; việc tắm dưới vòi hoa sen; cơn mưa rào; tắm dưới vòi hoa sen. Dịch cả câu: Tắm vòi hoa sen nhanh hơn là một cách đơn giản để các hộ gia đình giảm cả lượng nước và năng lượng tiêu thụ.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_24_21', 'en-a1-24', NULL, 'comprehensive_test', 'reading', NULL, 'Early investment in childhood education can reduce inequality and improve employment prospects later in life.', 'Dựa vào câu trên, từ “early” có nghĩa phù hợp nhất là gì?', '["hiểu; nắm rõ","sớm; ở giai đoạn đầu","nói; phát biểu bằng lời","khó khăn; phức tạp"]'::jsonb, 1, 'early: sớm; ở giai đoạn đầu; sớm; trước thời gian dự kiến. Dịch cả câu: Đầu tư sớm vào giáo dục mầm non có thể làm giảm sự bất bình đẳng và cải thiện cơ hội việc làm sau này trong đời.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
