INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-25', 'en', 'Bài 25: Đời sống hằng ngày (10) - CEFR A1', 'CEFR A1', 'A1 · Đời sống', '27 từ vựng Tiếng Anh CEFR A1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1025, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plate', 'en-a1-25', 'plate', '/pleɪt/', 'A1', 'cái đĩa; tấm kim loại; bản mỏng; mạ (kim loại)', 'n.', 'plating (n.), plated (adj.)', NULL, '"plate" thường chỉ đĩa nông, còn "bowl" chỉ bát sâu lòng.', 'She placed a warm pancake on my plate.', NULL, 'Cô ấy đặt một chiếc bánh kếp ấm lên đĩa của tôi.', '{"wordId":"plate","ukIpa":"/pleɪt/","usIpa":"/pleɪt/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A flat, usually round dish used for serving food.","vi":"cái đĩa"},{"pos":"n.","en":"A flat piece of metal or another hard material.","vi":"tấm kim loại; bản mỏng"},{"pos":"v.","en":"To cover an object with a thin layer of metal.","vi":"mạ (kim loại)"}],"examples":[{"en":"She placed a warm pancake on my plate.","vi":"Cô ấy đặt một chiếc bánh kếp ấm lên đĩa của tôi.","audioKind":"ex"},{"en":"Restaurants can reduce food waste by offering smaller plates and allowing customers to request extra portions.","vi":"Các nhà hàng có thể giảm lãng phí thực phẩm bằng cách cung cấp đĩa nhỏ hơn và cho phép khách hàng yêu cầu thêm phần ăn.","audioKind":"ex2"}],"collocations":[{"en":"dinner plate","vi":"đĩa ăn tối"},{"en":"a plate of rice","vi":"một đĩa cơm"},{"en":"steel plate","vi":"tấm thép"},{"en":"gold-plated jewellery","vi":"trang sức mạ vàng"}],"wordFamily":["plating (n.)","plated (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"\"plate\" thường chỉ đĩa nông, còn \"bowl\" chỉ bát sâu lòng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_saturday', 'en-a1-25', 'Saturday', '/ˈsætərdeɪ/', 'A1', 'thứ Bảy', 'n.', NULL, NULL, 'Viết hoa chữ cái đầu; dùng "on Saturday", nhưng không dùng "on" trước "this Saturday".', 'We usually buy fresh vegetables at the market on Saturday.', NULL, 'Chúng tôi thường mua rau tươi ở chợ vào thứ Bảy.', '{"wordId":"saturday","ukIpa":"/ˈsætədeɪ/","usIpa":"/ˈsætərdeɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"the day after Friday and before Sunday","vi":"thứ Bảy"}],"examples":[{"en":"We usually buy fresh vegetables at the market on Saturday.","vi":"Chúng tôi thường mua rau tươi ở chợ vào thứ Bảy.","audioKind":"ex"},{"en":"Opening public libraries on Saturday allows more working parents to participate in educational activities with their children.","vi":"Việc mở cửa các thư viện công cộng vào thứ Bảy cho phép nhiều phụ huynh đi làm tham gia các hoạt động giáo dục cùng con cái hơn.","audioKind":"ex2"}],"collocations":[{"en":"on Saturday","vi":"vào thứ Bảy"},{"en":"Saturday morning","vi":"sáng thứ Bảy"},{"en":"every Saturday","vi":"mỗi thứ Bảy"},{"en":"this Saturday","vi":"thứ Bảy này"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Viết hoa chữ cái đầu; dùng \"on Saturday\", nhưng không dùng \"on\" trước \"this Saturday\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brown', 'en-a1-25', 'brown', '/braʊn/', 'A1', 'màu nâu; làm chín vàng; chuyển sang màu nâu', 'adj.', 'brownish (adj.), browning (n.)', NULL, '"brown" khi làm động từ thường dùng trong nấu ăn, chỉ việc rán hoặc nướng thực phẩm cho đến khi chuyển màu nâu.', 'A small brown dog was sleeping beside the door.', NULL, 'Một chú chó nhỏ màu nâu đang ngủ bên cạnh cửa.', '{"wordId":"brown","ukIpa":"/braʊn/","usIpa":"/braʊn/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Having the colour of chocolate or dark wood.","vi":"màu nâu"},{"pos":"n.","en":"The colour of chocolate or dark wood.","vi":"màu nâu"},{"pos":"v.","en":"To become brown, or make food brown through cooking.","vi":"làm chín vàng; chuyển sang màu nâu"}],"examples":[{"en":"A small brown dog was sleeping beside the door.","vi":"Một chú chó nhỏ màu nâu đang ngủ bên cạnh cửa.","audioKind":"ex"},{"en":"During dry periods, grass often turns brown as plants conserve water and reduce their growth.","vi":"Trong thời kỳ khô hạn, cỏ thường chuyển sang màu nâu khi thực vật giữ nước và giảm sự phát triển.","audioKind":"ex2"}],"collocations":[{"en":"dark brown","vi":"nâu sẫm"},{"en":"brown eyes","vi":"mắt nâu"},{"en":"brown rice","vi":"gạo lứt"},{"en":"golden brown","vi":"vàng nâu"}],"wordFamily":["brownish (adj.)","browning (n.)"],"synonyms":[],"antonyms":[],"tipVi":"\"brown\" khi làm động từ thường dùng trong nấu ăn, chỉ việc rán hoặc nướng thực phẩm cho đến khi chuyển màu nâu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_help', 'en-a1-25', 'help', '/help/', 'A1', 'giúp đỡ; hỗ trợ; sự giúp đỡ; sự hỗ trợ', 'v.', 'helpful (adj.), helpless (adj.), helper (n.)', 'Đồng nghĩa: assist, aid · Trái nghĩa: hinder', 'Sau "help" có thể dùng động từ nguyên mẫu có "to" hoặc không "to".', 'Could you help me carry these bags upstairs?', NULL, 'Bạn có thể giúp tôi mang những chiếc túi này lên lầu không?', '{"wordId":"help","ukIpa":"/help/","usIpa":"/help/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"Make something easier or better for someone.","vi":"giúp đỡ; hỗ trợ"},{"pos":"n.","en":"Support that makes a difficulty or task easier.","vi":"sự giúp đỡ; sự hỗ trợ"}],"examples":[{"en":"Could you help me carry these bags upstairs?","vi":"Bạn có thể giúp tôi mang những chiếc túi này lên lầu không?","audioKind":"ex"},{"en":"Affordable public transport can help residents access jobs and reduce their dependence on cars.","vi":"Giao thông công cộng giá cả phải chăng có thể giúp cư dân tiếp cận việc làm và giảm sự phụ thuộc vào ô tô.","audioKind":"ex2"}],"collocations":[{"en":"help someone with something","vi":"giúp ai đó làm việc gì"},{"en":"ask for help","vi":"kêu gọi sự giúp đỡ"},{"en":"help to reduce","vi":"giúp giảm bớt"}],"wordFamily":["helpful (adj.)","helpless (adj.)","helper (n.)"],"synonyms":["assist","aid"],"antonyms":["hinder"],"tipVi":"Sau \"help\" có thể dùng động từ nguyên mẫu có \"to\" hoặc không \"to\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_high', 'en-a1-25', 'high', '/haɪ/', 'A1', 'cao; cao; nhiều; lớn; ở trên cao; lên cao', 'adj.', 'height (n.), heighten (v.), highly (adv.)', 'Trái nghĩa: low', '"high" thường chỉ vị trí hoặc mức độ; chiều cao của người dùng "tall".', 'The shelf is too high for me to reach.', NULL, 'Cái kệ quá cao nên tôi không với tới được.', '{"wordId":"high","ukIpa":"/haɪ/","usIpa":"/haɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"extending far upwards or positioned far above the ground","vi":"cao"},{"pos":"adj.","en":"greater than usual in amount, degree, or quality","vi":"cao; nhiều; lớn"},{"pos":"adv.","en":"at or to a position far above the ground","vi":"ở trên cao; lên cao"}],"examples":[{"en":"The shelf is too high for me to reach.","vi":"Cái kệ quá cao nên tôi không với tới được.","audioKind":"ex"},{"en":"High housing costs can prevent young adults from living independently, particularly in major urban centres.","vi":"Chi phí nhà ở cao có thể ngăn cản người trẻ sống tự lập, đặc biệt là ở các trung tâm đô thị lớn.","audioKind":"ex2"}],"collocations":[{"en":"high standards","vi":"tiêu chuẩn cao"},{"en":"high prices","vi":"giá cao"},{"en":"high altitude","vi":"độ cao lớn"},{"en":"high above","vi":"cao hơn hẳn phía trên"}],"wordFamily":["height (n.)","heighten (v.)","highly (adv.)"],"synonyms":[],"antonyms":["low"],"tipVi":"\"high\" thường chỉ vị trí hoặc mức độ; chiều cao của người dùng \"tall\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_soup', 'en-a1-25', 'soup', '/suːp/', 'A1', 'súp; canh', 'n.', NULL, NULL, 'Thường là danh từ không đếm được; khi gọi món, "two soups" có thể chỉ hai phần súp.', 'She warmed her hands around a bowl of soup.', NULL, 'Cô ấy hơ tay quanh bát súp cho ấm.', '{"wordId":"soup","ukIpa":"/suːp/","usIpa":"/suːp/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A liquid food made by cooking ingredients in water or stock.","vi":"súp; canh"}],"examples":[{"en":"She warmed her hands around a bowl of soup.","vi":"Cô ấy hơ tay quanh bát súp cho ấm.","audioKind":"ex"},{"en":"Community kitchens can provide affordable vegetable soup to help residents access nutritious meals during difficult economic periods.","vi":"Các bếp ăn cộng đồng có thể cung cấp súp rau củ giá rẻ để giúp cư dân có được bữa ăn bổ dưỡng trong giai đoạn kinh tế khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"a bowl of soup","vi":"một bát súp"},{"en":"vegetable soup","vi":"súp rau củ"},{"en":"make soup","vi":"nấu súp"},{"en":"chicken soup","vi":"súp gà"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; khi gọi món, \"two soups\" có thể chỉ hai phần súp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_big', 'en-a1-25', 'big', '/bɪɡ/', 'A1', 'lớn; to lớn; quan trọng; có ảnh hưởng lớn', 'adj.', 'bigger (adj.), biggest (adj.)', 'Đồng nghĩa: large · Trái nghĩa: small', 'big mang tính văn phong giao tiếp; trong văn viết trang trọng, có thể dùng large hoặc major tùy theo ngữ cảnh.', 'We need a big bag for all these towels.', NULL, 'Chúng ta cần một chiếc túi lớn để đựng tất cả số khăn tắm này.', '{"wordId":"big","ukIpa":"/bɪɡ/","usIpa":"/bɪɡ/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Large in size, amount, or degree.","vi":"lớn; to lớn"},{"pos":"adj.","en":"Important or likely to have a strong effect.","vi":"quan trọng; có ảnh hưởng lớn"}],"examples":[{"en":"We need a big bag for all these towels.","vi":"Chúng ta cần một chiếc túi lớn để đựng tất cả số khăn tắm này.","audioKind":"ex"},{"en":"Public transport can make a big difference to air quality in rapidly growing cities.","vi":"Giao thông công cộng có thể tạo ra sự khác biệt lớn đối với chất lượng không khí ở các thành phố đang phát triển nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"a big difference","vi":"sự khác biệt lớn"},{"en":"a big decision","vi":"quyết định quan trọng"},{"en":"a big mistake","vi":"sai lầm lớn"}],"wordFamily":["bigger (adj.)","biggest (adj.)"],"synonyms":["large"],"antonyms":["small"],"tipVi":"big mang tính văn phong giao tiếp; trong văn viết trang trọng, có thể dùng large hoặc major tùy theo ngữ cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hand', 'en-a1-25', 'hand', '/hænd/', 'A1', 'bàn tay; sự giúp đỡ; trao cho; đưa cho', 'n.', 'handful (n.), handy (adj.), handmade (adj.)', NULL, 'give someone a hand dùng để chỉ việc giúp đỡ; by hand dùng để chỉ việc làm thủ công.', 'She held the warm cup in her left hand.', NULL, 'Cô ấy cầm chiếc cốc ấm áp trong bàn tay trái.', '{"wordId":"hand","ukIpa":"/hænd/","usIpa":"/hænd/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The body part at the arm''s end, with fingers and thumb.","vi":"bàn tay"},{"pos":"n.","en":"Help with doing a task.","vi":"sự giúp đỡ"},{"pos":"v.","en":"To give something to someone by holding it out.","vi":"trao cho; đưa cho"}],"examples":[{"en":"She held the warm cup in her left hand.","vi":"Cô ấy cầm chiếc cốc ấm áp trong bàn tay trái.","audioKind":"ex"},{"en":"Practical workshops allow students to develop skills by making objects with their own hands.","vi":"Các buổi hội thảo thực hành cho phép sinh viên phát triển kỹ năng bằng cách tự tay chế tạo các đồ vật.","audioKind":"ex2"}],"collocations":[{"en":"hold hands","vi":"nắm tay nhau"},{"en":"give someone a hand","vi":"giúp đỡ ai đó một tay"},{"en":"hand in an assignment","vi":"nộp bài tập"},{"en":"by hand","vi":"làm thủ công; bằng tay"}],"wordFamily":["handful (n.)","handy (adj.)","handmade (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"give someone a hand dùng để chỉ việc giúp đỡ; by hand dùng để chỉ việc làm thủ công.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_yellow', 'en-a1-25', 'yellow', '/ˈjeloʊ/', 'A1', 'màu vàng; sắc vàng; làm vàng; ngả vàng', 'adj.', 'yellowish (adj.), yellowing (adj.)', NULL, 'Có thể dùng như động từ để chỉ sự ngả vàng; tránh dùng từ này để miêu tả chủng tộc con người.', 'She picked a yellow umbrella for the rainy walk.', NULL, 'Cô ấy đã chọn một chiếc ô màu vàng cho buổi đi dạo trong mưa.', '{"wordId":"yellow","ukIpa":"/ˈjeləʊ/","usIpa":"/ˈjeloʊ/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"having the colour of lemons or ripe bananas","vi":"màu vàng"},{"pos":"n.","en":"the colour of lemons or ripe bananas","vi":"sắc vàng"},{"pos":"v.","en":"to become yellow or make something yellow","vi":"làm vàng; ngả vàng"}],"examples":[{"en":"She picked a yellow umbrella for the rainy walk.","vi":"Cô ấy đã chọn một chiếc ô màu vàng cho buổi đi dạo trong mưa.","audioKind":"ex"},{"en":"Yellow leaves may indicate that urban trees are suffering from water shortages or poor soil conditions.","vi":"Lá vàng có thể cho thấy cây cối đô thị đang chịu tình trạng thiếu nước hoặc điều kiện đất đai kém.","audioKind":"ex2"}],"collocations":[{"en":"bright yellow","vi":"vàng sáng"},{"en":"pale yellow","vi":"vàng nhạt"},{"en":"turn yellow","vi":"ngả vàng"}],"wordFamily":["yellowish (adj.)","yellowing (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể dùng như động từ để chỉ sự ngả vàng; tránh dùng từ này để miêu tả chủng tộc con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_november', 'en-a1-25', 'November', '/noʊˈvembɚ/', 'A1', 'tháng mười một', 'n.', NULL, NULL, 'Tên tháng phải viết hoa chữ cái đầu; dùng giới từ in trước tên tháng và on trước ngày cụ thể.', 'We are moving into our new flat in November.', NULL, 'Chúng tôi sẽ chuyển đến căn hộ mới của mình vào tháng Mười Một.', '{"wordId":"november","ukIpa":"/nəʊˈvembə/","usIpa":"/noʊˈvembɚ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The eleventh month of the year.","vi":"tháng mười một"}],"examples":[{"en":"We are moving into our new flat in November.","vi":"Chúng tôi sẽ chuyển đến căn hộ mới của mình vào tháng Mười Một.","audioKind":"ex"},{"en":"The university plans to launch its new scholarship programme in November, allowing more international students to apply.","vi":"Trường đại học có kế hoạch triển khai chương trình học bổng mới vào tháng Mười Một, cho phép nhiều sinh viên quốc tế nộp đơn hơn.","audioKind":"ex2"}],"collocations":[{"en":"in November","vi":"vào tháng Mười Một"},{"en":"early November","vi":"đầu tháng Mười Một"},{"en":"late November","vi":"cuối tháng Mười Một"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tên tháng phải viết hoa chữ cái đầu; dùng giới từ in trước tên tháng và on trước ngày cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cafe', 'en-a1-25', 'cafe', '/kæˈfeɪ/', 'A1', 'tiệm cà phê; quán ăn nhỏ', 'n.', NULL, NULL, 'Cũng viết là café; thường phục vụ đồ uống và các bữa ăn nhẹ.', 'We shared a sandwich at the cafe beside the station.', NULL, 'Chúng tôi đã ăn chung một cái bánh mì kẹp ở quán cà phê cạnh nhà ga.', '{"wordId":"cafe","ukIpa":"/ˈkæfeɪ/","usIpa":"/kæˈfeɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A small place serving drinks and light meals.","vi":"tiệm cà phê; quán ăn nhỏ"}],"examples":[{"en":"We shared a sandwich at the cafe beside the station.","vi":"Chúng tôi đã ăn chung một cái bánh mì kẹp ở quán cà phê cạnh nhà ga.","audioKind":"ex"},{"en":"A neighbourhood cafe can strengthen community ties by providing a welcoming space for residents to meet.","vi":"Một quán cà phê trong khu5 dân cư có thể thắt chặt tình làng nghĩa xóm bằng cách cung cấp một không gian thân thiện để cư dân gặp gỡ.","audioKind":"ex2"}],"collocations":[{"en":"outdoor cafe","vi":"quán cà phê ngoài trời"},{"en":"local cafe","vi":"quán cà phê địa phương"},{"en":"internet cafe","vi":"tiệm net; quán cà phê Internet"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cũng viết là café; thường phục vụ đồ uống và các bữa ăn nhẹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_live', 'en-a1-25', 'live', '/lɪv/, /laɪv/', 'A1', 'sống; cư trú; tồn tại; trực tiếp (phát sóng hoặc biểu diễn); còn sống', 'v.', 'living (adj.), alive (adj.), life (n.)', NULL, 'Động từ đọc là /lɪv/; tính từ và phó từ chỉ sự trực tiếp đọc là /laɪv/.', 'My grandparents live in a quiet village near the coast.', NULL, 'Ông bà tôi sống ở một ngôi làng yên tĩnh gần bờ biển.', '{"wordId":"live","ukIpa":"/lɪv/, /laɪv/","usIpa":"/lɪv/, /laɪv/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to have your home somewhere, lead a life, or remain alive","vi":"sống; cư trú; tồn tại"},{"pos":"adj.","en":"broadcast or performed as it happens, rather than recorded","vi":"trực tiếp (phát sóng hoặc biểu diễn)"},{"pos":"adj.","en":"alive rather than dead","vi":"còn sống"}],"examples":[{"en":"My grandparents live in a quiet village near the coast.","vi":"Ông bà tôi sống ở một ngôi làng yên tĩnh gần bờ biển.","audioKind":"ex"},{"en":"People who live near public transport often depend less on private cars for their daily journeys.","vi":"Những người sống gần các phương tiện giao thông công cộng thường ít phụ thuộc hơn vào xe hơi cá nhân cho việc đi lại hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"live alone","vi":"sống một mình"},{"en":"live a healthy life","vi":"sống một cuộc sống lành mạnh"},{"en":"live music","vi":"nhạc sống"},{"en":"live broadcast","vi":"phát sóng trực tiếp"}],"wordFamily":["living (adj.)","alive (adj.)","life (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ đọc là /lɪv/; tính từ và phó từ chỉ sự trực tiếp đọc là /laɪv/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_her', 'en-a1-25', 'her', '/hɚ/', 'A1', 'cô ấy; chị ấy; bà ấy (dạng tân ngữ); của cô ấy; của chị ấy', 'pron.', 'she (pron.), hers (pron.), herself (pron.)', NULL, 'her có thể làm tân ngữ hoặc đi trước danh từ chỉ sở hữu; hers dùng độc lập.', 'I called her after lunch to arrange a walk.', NULL, 'Tôi đã gọi cho cô ấy sau bữa trưa để hẹn đi dạo.', '{"wordId":"her","ukIpa":"/hə(r)/","usIpa":"/hɚ/","cefr":"A1","topic":"daily","senses":[{"pos":"pron.","en":"the female person or animal receiving an action","vi":"cô ấy; chị ấy; bà ấy (dạng tân ngữ)"},{"pos":"det.","en":"belonging to or connected with a female person or animal","vi":"của cô ấy; của chị ấy"}],"examples":[{"en":"I called her after lunch to arrange a walk.","vi":"Tôi đã gọi cho cô ấy sau bữa trưa để hẹn đi dạo.","audioKind":"ex"},{"en":"When a student requests additional support, teachers should help her access appropriate learning resources.","vi":"Khi một học sinh yêu cầu hỗ trợ thêm, giáo viên nên giúp em ấy tiếp cận các nguồn học tập phù hợp.","audioKind":"ex2"}],"collocations":[{"en":"with her","vi":"với cô ấy"},{"en":"for her","vi":"dành cho cô ấy"},{"en":"her own","vi":"của chính cô ấy"}],"wordFamily":["she (pron.)","hers (pron.)","herself (pron.)"],"synonyms":[],"antonyms":[],"tipVi":"her có thể làm tân ngữ hoặc đi trước danh từ chỉ sở hữu; hers dùng độc lập.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quick', 'en-a1-25', 'quick', '/kwɪk/', 'A1', 'nhanh chóng; nhanh nhẹn; nhanh; diễn ra trong thời gian ngắn', 'adj.', 'quickly (adv.), quickness (n.), quicken (v.)', 'Đồng nghĩa: fast, rapid, swift · Trái nghĩa: slow', 'Trong văn phong trang trọng, dùng phó từ quickly để bổ nghĩa cho động từ.', 'Her quick reaction stopped the glass from falling.', NULL, 'Phản ứng nhanh nhẹn của cô ấy đã ngăn chiếc ly không bị rơi xuống.', '{"wordId":"quick","ukIpa":"/kwɪk/","usIpa":"/kwɪk/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"moving or acting fast, without much delay","vi":"nhanh chóng; nhanh nhẹn"},{"pos":"adj.","en":"taking only a short time","vi":"nhanh; diễn ra trong thời gian ngắn"}],"examples":[{"en":"Her quick reaction stopped the glass from falling.","vi":"Phản ứng nhanh nhẹn của cô ấy đã ngăn chiếc ly không bị rơi xuống.","audioKind":"ex"},{"en":"A quick response to reports of water pollution can prevent serious damage to nearby ecosystems.","vi":"Phản ứng nhanh chóng đối với các báo cáo ô nhiễm nước có thể ngăn ngừa tổn hại nghiêm trọng cho các hệ sinh thái gần đó.","audioKind":"ex2"}],"collocations":[{"en":"quick response","vi":"phản ứng nhanh"},{"en":"quick decision","vi":"quyết định nhanh chóng"},{"en":"quick look","vi":"cái nhìn thoáng qua"},{"en":"quick to react","vi":"nhanh nhạy trong phản ứng"}],"wordFamily":["quickly (adv.)","quickness (n.)","quicken (v.)"],"synonyms":["fast","rapid","swift"],"antonyms":["slow"],"tipVi":"Trong văn phong trang trọng, dùng phó từ quickly để bổ nghĩa cho động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_august', 'en-a1-25', 'August', '/ˈɔːɡəst/', 'A1', 'tháng Tám', 'n.', NULL, NULL, 'Tên tháng phải viết hoa chữ cái đầu; dùng giới từ in trước tháng và on trước ngày cụ thể.', 'We usually visit our grandparents by the sea in August.', NULL, 'Chúng tôi thường đến thăm ông bà ở vùng biển vào tháng Tám.', '{"wordId":"august","ukIpa":"/ˈɔːɡəst/","usIpa":"/ˈɔːɡəst/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"the eighth month of the year","vi":"tháng Tám"}],"examples":[{"en":"We usually visit our grandparents by the sea in August.","vi":"Chúng tôi thường đến thăm ông bà ở vùng biển vào tháng Tám.","audioKind":"ex"},{"en":"Tourist destinations often experience increased demand in August, putting pressure on local transport and accommodation.","vi":"Các điểm đến du lịch thường chứng kiến nhu cầu tăng cao vào tháng Tám, gây áp lực lên hệ thống giao thông và chỗ ở địa phương.","audioKind":"ex2"}],"collocations":[{"en":"in August","vi":"vào tháng Tám"},{"en":"early August","vi":"đầu tháng Tám"},{"en":"late August","vi":"cuối tháng Tám"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tên tháng phải viết hoa chữ cái đầu; dùng giới từ in trước tháng và on trước ngày cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bag', 'en-a1-25', 'bag', '/bæɡ/', 'A1', 'cái túi; cái cặp; bao; bỏ vào túi; đóng gói', 'n.', 'bagful (n.)', NULL, 'Cụm a bag of đi sau với danh từ chỉ vật đựng bên trong, chẳng hạn như a bag of rice.', 'She put the apples in a reusable bag.', NULL, 'Cô ấy bỏ những quả táo vào một chiếc túi có thể tái sử dụng.', '{"wordId":"bag","ukIpa":"/bæɡ/","usIpa":"/bæɡ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A container made from flexible material, used for carrying things.","vi":"cái túi; cái cặp; bao"},{"pos":"v.","en":"To put something into a bag.","vi":"bỏ vào túi; đóng gói"}],"examples":[{"en":"She put the apples in a reusable bag.","vi":"Cô ấy bỏ những quả táo vào một chiếc túi có thể tái sử dụng.","audioKind":"ex"},{"en":"Charging customers for plastic bags can encourage shoppers to adopt more environmentally responsible habits.","vi":"Việc thu phí khách hàng đối với túi nhựa có thể khuyến khích người mua sắm hình thành các thói quen có trách nhiệm với môi trường hơn.","audioKind":"ex2"}],"collocations":[{"en":"a shopping bag","vi":"túi mua sắm"},{"en":"a reusable bag","vi":"túi tái sử dụng"},{"en":"pack a bag","vi":"sắp xếp hành lý"}],"wordFamily":["bagful (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm a bag of đi sau với danh từ chỉ vật đựng bên trong, chẳng hạn như a bag of rice.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_place', 'en-a1-25', 'place', '/pleɪs/', 'A1', 'nơi; địa điểm; chốn; đặt; để; chỗ ngồi; suất; vị trí', 'n.', 'placement (n.), misplace (v.), replace (v.)', NULL, 'Cụm take place mang nghĩa diễn ra hoặc tổ chức, không dùng ở thể bị động.', 'This shady spot is a lovely place for a picnic.', NULL, 'Góc râm mát này là một nơi tuyệt vời để tổ chức dã ngoại.', '{"wordId":"place","ukIpa":"/pleɪs/","usIpa":"/pleɪs/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A particular area, position, or location.","vi":"nơi; địa điểm; chốn"},{"pos":"v.","en":"To put something in a particular position.","vi":"đặt; để"},{"pos":"n.","en":"A space available for someone to sit, study, or participate.","vi":"chỗ ngồi; suất; vị trí"}],"examples":[{"en":"This shady spot is a lovely place for a picnic.","vi":"Góc râm mát này là một nơi tuyệt vời để tổ chức dã ngoại.","audioKind":"ex"},{"en":"Urban planners should place public facilities near residential areas to make essential services accessible to everyone.","vi":"Các nhà quy hoạch đô thị nên đặt các tiện ích công cộng gần khu dân cư để mọi người có thể tiếp cận các dịch vụ thiết yếu một cách thuận tiện.","audioKind":"ex2"}],"collocations":[{"en":"a public place","vi":"nơi công cộng"},{"en":"place an order","vi":"đặt hàng"},{"en":"take place","vi":"diễn ra; xảy ra"},{"en":"a university place","vi":"suất trúng tuyển đại học"}],"wordFamily":["placement (n.)","misplace (v.)","replace (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm take place mang nghĩa diễn ra hoặc tổ chức, không dùng ở thể bị động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dress', 'en-a1-25', 'dress', '/dres/', 'A1', 'váy liền thân; đầm; mặc quần áo; ăn mặc; trang phục; y phục', 'n.', 'dressed (adj.), undress (v.), dressy (adj.)', NULL, 'A dress chỉ váy liền thân; get dressed chỉ hành động mặc quần áo xong.', 'She wore a blue dress to her sister''s party.', NULL, 'Cô ấy mặc một chiếc đầm màu xanh lam đến bữa tiệc của chị gái.', '{"wordId":"dress","ukIpa":"/dres/","usIpa":"/dres/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a one-piece garment with a top and a skirt","vi":"váy liền thân; đầm"},{"pos":"v.","en":"to put clothes on yourself or someone else","vi":"mặc quần áo; ăn mặc"},{"pos":"n.","en":"clothing of a particular type or worn for a particular occasion","vi":"trang phục; y phục"}],"examples":[{"en":"She wore a blue dress to her sister''s party.","vi":"Cô ấy mặc một chiếc đầm màu xanh lam đến bữa tiệc của chị gái.","audioKind":"ex"},{"en":"Some employers require formal dress, while others allow staff to wear casual clothing at work.","vi":"Một số nhà tuyển dụng yêu cầu mặc trang phục trang trọng, trong khi những nơi khác cho phép nhân viên mặc quần áo thường ngày khi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"a summer dress","vi":"váy mùa hè"},{"en":"get dressed","vi":"mặc quần áo xong"},{"en":"dress code","vi":"quy định trang phục"},{"en":"dress up","vi":"ăn diện; diện đồ đẹp"}],"wordFamily":["dressed (adj.)","undress (v.)","dressy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"A dress chỉ váy liền thân; get dressed chỉ hành động mặc quần áo xong.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_breakfast', 'en-a1-25', 'breakfast', '/ˈbrekfəst/', 'A1', 'bữa sáng; bữa điểm tâm', 'n.', NULL, NULL, 'Nói chung chung việc ăn sáng dùng have breakfast, không thêm mạo từ.', 'I usually have breakfast before taking the bus.', NULL, 'Tôi thường ăn sáng trước khi đi xe buýt.', '{"wordId":"breakfast","ukIpa":"/ˈbrekfəst/","usIpa":"/ˈbrekfəst/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"the meal you eat at the start of the day","vi":"bữa sáng; bữa điểm tâm"}],"examples":[{"en":"I usually have breakfast before taking the bus.","vi":"Tôi thường ăn sáng trước khi đi xe buýt.","audioKind":"ex"},{"en":"Schools that provide a healthy breakfast may help students concentrate better during morning lessons.","vi":"Các trường học cung cấp bữa sáng đầy đủ dinh dưỡng có thể giúp học sinh tập trung tốt hơn trong các tiết học buổi sáng.","audioKind":"ex2"}],"collocations":[{"en":"have breakfast","vi":"ăn sáng"},{"en":"skip breakfast","vi":"bỏ bữa sáng"},{"en":"a balanced breakfast","vi":"bữa sáng cân bằng dinh dưỡng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nói chung chung việc ăn sáng dùng have breakfast, không thêm mạo từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_catch', 'en-a1-25', 'catch', '/kætʃ/', 'A1', 'bắt lấy; tóm lấy; bắt kịp; đón (xe, tàu); mắc phải; nhiễm (bệnh)', 'v.', 'catcher (n.)', NULL, 'Quá khứ và phân từ hai đều là caught; bị cảm dùng catch a cold.', 'Can you catch the ball with just one hand?', NULL, 'Bạn có thể bắt được quả bóng chỉ bằng một tay không?', '{"wordId":"catch","ukIpa":"/kætʃ/","usIpa":"/kætʃ/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to stop and hold something moving, or capture someone","vi":"bắt lấy; tóm lấy"},{"pos":"v.","en":"to reach a bus, train, or plane in time","vi":"bắt kịp; đón (xe, tàu)"},{"pos":"v.","en":"to become ill with an infectious disease","vi":"mắc phải; nhiễm (bệnh)"}],"examples":[{"en":"Can you catch the ball with just one hand?","vi":"Bạn có thể bắt được quả bóng chỉ bằng một tay không?","audioKind":"ex"},{"en":"More frequent bus services would help commuters catch connecting trains without relying on private cars.","vi":"Việc tăng tần suất xe buýt sẽ giúp người đi làm dễ dàng đón được các chuyến tàu nối chuyến mà không phải phụ thuộc vào xe cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"catch a ball","vi":"bắt bóng"},{"en":"catch a train","vi":"đón tàu"},{"en":"catch a cold","vi":"bị cảm lạnh"},{"en":"catch someone''s attention","vi":"thu hút sự chú ý của ai đó"}],"wordFamily":["catcher (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Quá khứ và phân từ hai đều là caught; bị cảm dùng catch a cold.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_four', 'en-a1-25', 'four', '/fɔːr/', 'A1', 'bốn; số bốn', 'num.', 'fourth (num.), fourteen (num.), forty (num.)', NULL, 'four là số đếm; số thứ tự ''thứ tư'' là fourth.', 'We put four chairs around the kitchen table.', NULL, 'Chúng tôi đặt bốn chiếc ghế xung quanh bàn bếp.', '{"wordId":"four","ukIpa":"/fɔː/","usIpa":"/fɔːr/","cefr":"A1","topic":"daily","senses":[{"pos":"num.","en":"the number after three and before five","vi":"bốn; số bốn"}],"examples":[{"en":"We put four chairs around the kitchen table.","vi":"Chúng tôi đặt bốn chiếc ghế xung quanh bàn bếp.","audioKind":"ex"},{"en":"The research team compared four methods of reducing household energy use during the winter months.","vi":"Nhóm nghiên cứu đã so sánh bốn phương pháp giảm lượng tiêu thụ năng lượng trong gia đình vào những tháng mùa đông.","audioKind":"ex2"}],"collocations":[{"en":"four times","vi":"bốn lần; gấp bốn"},{"en":"four hours","vi":"bốn tiếng"},{"en":"all four","vi":"cả bốn"}],"wordFamily":["fourth (num.)","fourteen (num.)","forty (num.)"],"synonyms":[],"antonyms":[],"tipVi":"four là số đếm; số thứ tự ''thứ tư'' là fourth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_show', 'en-a1-25', 'show', '/ʃoʊ/', 'A1', 'chỉ; trưng bày; cho xem; chứng minh; thể hiện; chương trình; buổi biểu diễn', 'v.', 'showing (n.), showy (adj.)', 'Đồng nghĩa: display, demonstrate · Trái nghĩa: hide', 'Quá khứ là showed, phân từ hai thường dùng là shown.', 'Please show me how to fold this paper bird.', NULL, 'Xin hãy hướng dẫn tôi cách gấp con hạc giấy này.', '{"wordId":"show","ukIpa":"/ʃəʊ/","usIpa":"/ʃoʊ/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To let someone see something or demonstrate how something works.","vi":"chỉ; trưng bày; cho xem"},{"pos":"v.","en":"To provide information or evidence that something is true.","vi":"chứng minh; thể hiện"},{"pos":"n.","en":"A performance, programme, or public display intended for an audience.","vi":"chương trình; buổi biểu diễn"}],"examples":[{"en":"Please show me how to fold this paper bird.","vi":"Xin hãy hướng dẫn tôi cách gấp con hạc giấy này.","audioKind":"ex"},{"en":"Recent studies show that access to green spaces can improve mental wellbeing in urban populations.","vi":"Các nghiên cứu gần đây chỉ ra rằng việc tiếp cận không gian xanh có thể cải thiện sức khỏe tinh thần cho người dân đô thị.","audioKind":"ex2"}],"collocations":[{"en":"show someone how to","vi":"chỉ cho ai cách làm gì"},{"en":"show that","vi":"chứng minh rằng"},{"en":"show an improvement","vi":"thể hiện sự tiến bộ"},{"en":"a live show","vi":"buổi biểu diễn trực tiếp"}],"wordFamily":["showing (n.)","showy (adj.)"],"synonyms":["display","demonstrate"],"antonyms":["hide"],"tipVi":"Quá khứ là showed, phân từ hai thường dùng là shown.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_above', 'en-a1-25', 'above', '/əˈbʌv/', 'A1', 'ở phía trên; cao hơn; vượt quá; trên (mức độ, số lượng); ở bên trên; phần trên', 'prep.', NULL, 'Trái nghĩa: below', 'above chỉ vị trí cao hơn, không nhất thiết phải nằm ngay chính diện hay chạm vào bề mặt.', 'A small wooden shelf hangs above the kitchen sink.', NULL, 'Một chiếc kệ gỗ nhỏ được treo ngay phía trên bồn rửa bát.', '{"wordId":"above","ukIpa":"/əˈbʌv/","usIpa":"/əˈbʌv/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"In a higher position than something else.","vi":"ở phía trên; cao hơn"},{"pos":"prep.","en":"Greater than a particular amount, level, or standard.","vi":"vượt quá; trên (mức độ, số lượng)"},{"pos":"adv.","en":"In a higher place or earlier in a piece of writing.","vi":"ở bên trên; phần trên"}],"examples":[{"en":"A small wooden shelf hangs above the kitchen sink.","vi":"Một chiếc kệ gỗ nhỏ được treo ngay phía trên bồn rửa bát.","audioKind":"ex"},{"en":"Temperatures above the seasonal average can increase water demand and put pressure on urban supplies.","vi":"Mức nhiệt cao hơn trung bình theo mùa có thể làm tăng nhu cầu sử dụng nước và gây áp lực lên hệ thống cấp nước đô thị.","audioKind":"ex2"}],"collocations":[{"en":"above sea level","vi":"trên mực nước biển"},{"en":"above average","vi":"trên mức trung bình"},{"en":"above all","vi":"trên hết; quan trọng nhất"},{"en":"as mentioned above","vi":"như đã đề cập ở trên"}],"wordFamily":[],"synonyms":[],"antonyms":["below"],"tipVi":"above chỉ vị trí cao hơn, không nhất thiết phải nằm ngay chính diện hay chạm vào bề mặt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_buy', 'en-a1-25', 'buy', '/baɪ/', 'A1', 'mua; tậu; tin tưởng; chấp nhận (lời giải thích/ý kiến); món hời', 'v.', 'buyer (n.)', 'Đồng nghĩa: purchase · Trái nghĩa: sell', 'Quá khứ và phân từ hai đều là bought; không viết thành buyed.', 'I need to buy some bread before breakfast.', NULL, 'Tôi cần mua ít bánh mì trước bữa sáng.', '{"wordId":"buy","ukIpa":"/baɪ/","usIpa":"/baɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to obtain something by paying money for it","vi":"mua; tậu"},{"pos":"v.","en":"to believe an explanation or accept an idea","vi":"tin tưởng; chấp nhận (lời giải thích/ý kiến)"},{"pos":"n.","en":"something bought, especially something offering good value","vi":"món hời"}],"examples":[{"en":"I need to buy some bread before breakfast.","vi":"Tôi cần mua ít bánh mì trước bữa sáng.","audioKind":"ex"},{"en":"Consumers can reduce packaging waste when they buy fresh produce from local markets.","vi":"Người tiêu dùng có thể giảm rác thải bao bì khi họ mua nông sản tươi từ các khu chợ địa phương.","audioKind":"ex2"}],"collocations":[{"en":"buy in bulk","vi":"mua sỉ; mua số lượng lớn"},{"en":"buy second-hand","vi":"mua đồ cũ"},{"en":"buy time","vi":"câu giờ; kéo dài thời gian"},{"en":"a good buy","vi":"một món hời"}],"wordFamily":["buyer (n.)"],"synonyms":["purchase"],"antonyms":["sell"],"tipVi":"Quá khứ và phân từ hai đều là bought; không viết thành buyed.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_short', 'en-a1-25', 'short', '/ʃɔːrt/', 'A1', 'ngắn; thấp; chớp nhoáng; thiếu; không đủ; chưa tới; dừng lại đột ngột', 'adj.', 'shorten (v.), shortness (n.), shortage (n.), shortly (adv.)', 'Đồng nghĩa: brief · Trái nghĩa: long, tall', 'short of nghĩa là thiếu hụt; shortly thường mang nghĩa "chẳng mấy chốc, sắp tới".', 'We took a short walk before dinner tonight.', NULL, 'Chúng tôi đã đi dạo một quãng ngắn trước bữa tối tối nay.', '{"wordId":"short","ukIpa":"/ʃɔːt/","usIpa":"/ʃɔːrt/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Having little length, height, or duration.","vi":"ngắn; thấp; chớp nhoáng"},{"pos":"adj.","en":"Not having as much of something as is needed.","vi":"thiếu; không đủ"},{"pos":"adv.","en":"Before reaching a target, or with a sudden stop.","vi":"chưa tới; dừng lại đột ngột"}],"examples":[{"en":"We took a short walk before dinner tonight.","vi":"Chúng tôi đã đi dạo một quãng ngắn trước bữa tối tối nay.","audioKind":"ex"},{"en":"Short training courses can help unemployed adults acquire practical skills without committing to several years of study.","vi":"Các khóa đào tạo ngắn hạn có thể giúp người lao động thất nghiệp tích lũy kỹ năng thực tế mà không cần theo học dài năm trời.","audioKind":"ex2"}],"collocations":[{"en":"a short distance","vi":"một khoảng cách ngắn"},{"en":"short of time","vi":"thiếu thời gian"},{"en":"in the short term","vi":"trong ngắn hạn"},{"en":"fall short of","vi":"không đạt đến; hụt"}],"wordFamily":["shorten (v.)","shortness (n.)","shortage (n.)","shortly (adv.)"],"synonyms":["brief"],"antonyms":["long","tall"],"tipVi":"short of nghĩa là thiếu hụt; shortly thường mang nghĩa \"chẳng mấy chốc, sắp tới\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wear', 'en-a1-25', 'wear', '/wer/', 'A1', 'mặc; đeo; đội; mang; hao mòn; hỏng theo thời gian; sự hao mòn; sự hư hại', 'v.', 'wearer (n.), worn (adj.), wearable (adj.)', NULL, 'wear nhấn mạnh trạng thái mặc/đeo, put on nhấn mạnh hành động mặc/đeo; dạng quá khứ là wore.', 'I always wear thick socks when the floor feels cold.', NULL, 'Tôi luôn mang tất dày khi sàn nhà có cảm giác lạnh.', '{"wordId":"wear","ukIpa":"/weə/","usIpa":"/wer/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to have clothes, jewellery, or accessories on your body","vi":"mặc; đeo; đội; mang"},{"pos":"v.","en":"to damage or become damaged through repeated use","vi":"hao mòn; hỏng theo thời gian"},{"pos":"n.","en":"damage caused by regular use over time","vi":"sự hao mòn; sự hư hại"}],"examples":[{"en":"I always wear thick socks when the floor feels cold.","vi":"Tôi luôn mang tất dày khi sàn nhà có cảm giác lạnh.","audioKind":"ex"},{"en":"Encouraging employees to wear protective equipment can significantly reduce the risk of injuries in industrial workplaces.","vi":"Việc khuyến khích nhân viên mặc đồ bảo hộ có thể làm giảm đáng kể nguy cơ chấn thương tại các nơi làm việc công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"wear glasses","vi":"đeo kính"},{"en":"wear a uniform","vi":"mặc đồng phục"},{"en":"wear out","vi":"dùng hỏng; mòn rách"},{"en":"wear and tear","vi":"sự hao mòn thông thường"}],"wordFamily":["wearer (n.)","worn (adj.)","wearable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"wear nhấn mạnh trạng thái mặc/đeo, put on nhấn mạnh hành động mặc/đeo; dạng quá khứ là wore.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_day', 'en-a1-25', 'day', '/deɪ/', 'A1', 'ngày; một ngày (24 giờ); ban ngày; ban trưa; thời kỳ; thời đại', 'n.', 'daily (adj.), daytime (n.), daylight (n.)', 'Trái nghĩa: night', 'every day nghĩa là mỗi ngày; everyday là tính từ, nghĩa là hàng ngày.', 'We spent the whole day building sandcastles on the beach.', NULL, 'Chúng tôi đã dành cả ngày để xây lâu đài cát trên bãi biển.', '{"wordId":"day","ukIpa":"/deɪ/","usIpa":"/deɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a period of twenty-four hours","vi":"ngày; một ngày (24 giờ)"},{"pos":"n.","en":"the part of each day when there is natural light","vi":"ban ngày; ban trưa"},{"pos":"n.","en":"a particular period in the past or present","vi":"thời kỳ; thời đại"}],"examples":[{"en":"We spent the whole day building sandcastles on the beach.","vi":"Chúng tôi đã dành cả ngày để xây lâu đài cát trên bãi biển.","audioKind":"ex"},{"en":"Shorter working days may improve employee wellbeing while allowing parents to spend more time with their children.","vi":"Thời gian làm việc ngắn hơn hàng ngày có thể cải thiện sức khỏe của nhân viên đồng thời cho phép các bậc phụ huynh có nhiều thời gian hơn bên con cái.","audioKind":"ex2"}],"collocations":[{"en":"every day","vi":"mỗi ngày"},{"en":"during the day","vi":"vào ban ngày"},{"en":"a day off","vi":"một ngày nghỉ"},{"en":"these days","vi":"ngày nay"}],"wordFamily":["daily (adj.)","daytime (n.)","daylight (n.)"],"synonyms":[],"antonyms":["night"],"tipVi":"every day nghĩa là mỗi ngày; everyday là tính từ, nghĩa là hàng ngày.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_25_1', 'en-a1-25', 'Cách dùng “brown” (adj.) — màu nâu', 'dark brown  ·  brown eyes  ·  brown rice', '"brown" khi làm động từ thường dùng trong nấu ăn, chỉ việc rán hoặc nướng thực phẩm cho đến khi chuyển màu nâu.', 'Họ từ (Word Family): brownish (adj.), browning (n.)', '[{"hanzi":"A small brown dog was sleeping beside the door.","pinyin":"","meaning":"Một chú chó nhỏ màu nâu đang ngủ bên cạnh cửa."},{"hanzi":"During dry periods, grass often turns brown as plants conserve water and reduce their growth.","pinyin":"","meaning":"Trong thời kỳ khô hạn, cỏ thường chuyển sang màu nâu khi thực vật giữ nước và giảm sự phát triển."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_25_2', 'en-a1-25', 'Cách dùng “big” (adj.) — lớn; to lớn', 'a big difference  ·  a big decision  ·  a big mistake', 'big mang tính văn phong giao tiếp; trong văn viết trang trọng, có thể dùng large hoặc major tùy theo ngữ cảnh.', 'Họ từ (Word Family): bigger (adj.), biggest (adj.) | Đồng nghĩa: large | Trái nghĩa: small', '[{"hanzi":"We need a big bag for all these towels.","pinyin":"","meaning":"Chúng ta cần một chiếc túi lớn để đựng tất cả số khăn tắm này."},{"hanzi":"Public transport can make a big difference to air quality in rapidly growing cities.","pinyin":"","meaning":"Giao thông công cộng có thể tạo ra sự khác biệt lớn đối với chất lượng không khí ở các thành phố đang phát triển nhanh chóng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_25_3', 'en-a1-25', 'Cách dùng “yellow” (adj.) — màu vàng', 'bright yellow  ·  pale yellow  ·  turn yellow', 'Có thể dùng như động từ để chỉ sự ngả vàng; tránh dùng từ này để miêu tả chủng tộc con người.', 'Họ từ (Word Family): yellowish (adj.), yellowing (adj.)', '[{"hanzi":"She picked a yellow umbrella for the rainy walk.","pinyin":"","meaning":"Cô ấy đã chọn một chiếc ô màu vàng cho buổi đi dạo trong mưa."},{"hanzi":"Yellow leaves may indicate that urban trees are suffering from water shortages or poor soil conditions.","pinyin":"","meaning":"Lá vàng có thể cho thấy cây cối đô thị đang chịu tình trạng thiếu nước hoặc điều kiện đất đai kém."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_25_4', 'en-a1-25', 'Cách dùng “November” (n.) — tháng mười một', 'in November  ·  early November  ·  late November', 'Tên tháng phải viết hoa chữ cái đầu; dùng giới từ in trước tên tháng và on trước ngày cụ thể.', NULL, '[{"hanzi":"We are moving into our new flat in November.","pinyin":"","meaning":"Chúng tôi sẽ chuyển đến căn hộ mới của mình vào tháng Mười Một."},{"hanzi":"The university plans to launch its new scholarship programme in November, allowing more international students to apply.","pinyin":"","meaning":"Trường đại học có kế hoạch triển khai chương trình học bổng mới vào tháng Mười Một, cho phép nhiều sinh viên quốc tế nộp đơn hơn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_25_1', 'en-a1-25', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_25_1_1', 'ten_25_1', 'plate', 'She placed a warm pancake on my plate.', 'She placed a warm pancake on my plate.', '/pleɪt/', 'Cô ấy đặt một chiếc bánh kếp ấm lên đĩa của tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_25_1_2', 'ten_25_1', 'Saturday', 'We usually buy fresh vegetables at the market on Saturday.', 'We usually buy fresh vegetables at the market on Saturday.', '/ˈsætərdeɪ/', 'Chúng tôi thường mua rau tươi ở chợ vào thứ Bảy.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
