INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_25_1_1', 'en-a1-25', 'ten_25_1', 'listening', 'listening', 'She placed a warm pancake on my plate.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy hơ tay quanh bát súp cho ấm.","Chúng tôi thường mua rau tươi ở chợ vào thứ Bảy.","Bạn có thể giúp tôi mang những chiếc túi này lên lầu không?","Cô ấy đặt một chiếc bánh kếp ấm lên đĩa của tôi."]'::jsonb, 3, 'She placed a warm pancake on my plate. → Cô ấy đặt một chiếc bánh kếp ấm lên đĩa của tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_25_1_2', 'en-a1-25', 'ten_25_1', 'listening', 'listening', 'We usually buy fresh vegetables at the market on Saturday.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy cầm chiếc cốc ấm áp trong bàn tay trái.","Chúng tôi thường mua rau tươi ở chợ vào thứ Bảy.","Một chú chó nhỏ màu nâu đang ngủ bên cạnh cửa.","Bạn có thể giúp tôi mang những chiếc túi này lên lầu không?"]'::jsonb, 1, 'We usually buy fresh vegetables at the market on Saturday. → Chúng tôi thường mua rau tươi ở chợ vào thứ Bảy.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
