INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_25_2_1', 'ten_25_2', 'plate', 'Restaurants can reduce food waste by offering smaller plates and allowing customers to request extra portions.', 'Restaurants can reduce food waste by offering smaller plates and allowing customers to request extra portions.', '/pleɪt/', 'Các nhà hàng có thể giảm lãng phí thực phẩm bằng cách cung cấp đĩa nhỏ hơn và cho phép khách hàng yêu cầu thêm phần ăn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_25_2_2', 'ten_25_2', 'Saturday', 'Opening public libraries on Saturday allows more working parents to participate in educational activities with their children.', 'Opening public libraries on Saturday allows more working parents to participate in educational activities with their children.', '/ˈsætərdeɪ/', 'Việc mở cửa các thư viện công cộng vào thứ Bảy cho phép nhiều phụ huynh đi làm tham gia các hoạt động giáo dục cùng con cái hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_25_2_3', 'ten_25_2', 'brown', 'During dry periods, grass often turns brown as plants conserve water and reduce their growth.', 'During dry periods, grass often turns brown as plants conserve water and reduce their growth.', '/braʊn/', 'Trong thời kỳ khô hạn, cỏ thường chuyển sang màu nâu khi thực vật giữ nước và giảm sự phát triển.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_25_2_4', 'ten_25_2', 'help', 'Affordable public transport can help residents access jobs and reduce their dependence on cars.', 'Affordable public transport can help residents access jobs and reduce their dependence on cars.', '/help/', 'Giao thông công cộng giá cả phải chăng có thể giúp cư dân tiếp cận việc làm và giảm sự phụ thuộc vào ô tô.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_25_2_5', 'ten_25_2', 'high', 'High housing costs can prevent young adults from living independently, particularly in major urban centres.', 'High housing costs can prevent young adults from living independently, particularly in major urban centres.', '/haɪ/', 'Chi phí nhà ở cao có thể ngăn cản người trẻ sống tự lập, đặc biệt là ở các trung tâm đô thị lớn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_25_2_6', 'ten_25_2', 'soup', 'Community kitchens can provide affordable vegetable soup to help residents access nutritious meals during difficult economic periods.', 'Community kitchens can provide affordable vegetable soup to help residents access nutritious meals during difficult economic periods.', '/suːp/', 'Các bếp ăn cộng đồng có thể cung cấp súp rau củ giá rẻ để giúp cư dân có được bữa ăn bổ dưỡng trong giai đoạn kinh tế khó khăn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
