INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_25_2_2', 'en-a1-25', 'ten_25_2', 'listening', 'listening', 'Opening public libraries on Saturday allows more working parents to participate in educational activities with their children.', NULL, 'Trong câu vừa nghe, từ “Saturday” mang nghĩa nào sau đây?', '["thứ Bảy","nhưng; nhưng mà; song","việc kinh doanh; thương mại","thuộc về hoặc liên quan đến Vương quốc Anh, người dân hoặc văn hóa nước này"]'::jsonb, 0, '“Saturday” (/ˈsætərdeɪ/): thứ Bảy. Câu đầy đủ: Opening public libraries on Saturday allows more working parents to participate in educational activities with their children.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
