INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_25_2', 'en-a1-25', NULL, 'comprehensive_test', 'listening', 'We usually buy fresh vegetables at the market on Saturday.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi thường mua rau tươi ở chợ vào thứ Bảy.","Cô ấy đặt một chiếc bánh kếp ấm lên đĩa của tôi.","Chúng tôi thường đến thăm ông bà ở vùng biển vào tháng Tám.","Xin hãy hướng dẫn tôi cách gấp con hạc giấy này."]'::jsonb, 0, 'We usually buy fresh vegetables at the market on Saturday. → Chúng tôi thường mua rau tươi ở chợ vào thứ Bảy.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_25_3', 'en-a1-25', NULL, 'comprehensive_test', 'listening', 'brown', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khỏe mạnh","kỳ thi; bài kiểm tra","màu nâu","thuộc Trung Quốc; thuộc tiếng Trung"]'::jsonb, 2, 'brown (/braʊn/) → màu nâu; làm chín vàng; chuyển sang màu nâu', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_25_4', 'en-a1-25', NULL, 'comprehensive_test', 'listening', 'Could you help me carry these bags upstairs?', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi thường mua rau tươi ở chợ vào thứ Bảy.","Ông bà tôi sống ở một ngôi làng yên tĩnh gần bờ biển.","Chúng ta cần một chiếc túi lớn để đựng tất cả số khăn tắm này.","Bạn có thể giúp tôi mang những chiếc túi này lên lầu không?"]'::jsonb, 3, 'Could you help me carry these bags upstairs? → Bạn có thể giúp tôi mang những chiếc túi này lên lầu không?', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
