INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_25_6', 'en-a1-25', NULL, 'comprehensive_test', 'listening', 'She warmed her hands around a bowl of soup.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đặt bốn chiếc ghế xung quanh bàn bếp.","Cô ấy hơ tay quanh bát súp cho ấm.","Xin hãy hướng dẫn tôi cách gấp con hạc giấy này.","Một chú chó nhỏ màu nâu đang ngủ bên cạnh cửa."]'::jsonb, 1, 'She warmed her hands around a bowl of soup. → Cô ấy hơ tay quanh bát súp cho ấm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
