INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_25_8', 'en-a1-25', NULL, 'comprehensive_test', 'listening', 'She held the warm cup in her left hand.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy cầm chiếc cốc ấm áp trong bàn tay trái.","Tôi luôn mang tất dày khi sàn nhà có cảm giác lạnh.","Chúng tôi đã ăn chung một cái bánh mì kẹp ở quán cà phê cạnh nhà ga.","Cái kệ quá cao nên tôi không với tới được."]'::jsonb, 0, 'She held the warm cup in her left hand. → Cô ấy cầm chiếc cốc ấm áp trong bàn tay trái.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
