INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_25_18', 'en-a1-25', NULL, 'comprehensive_test', 'reading', NULL, 'Restaurants can reduce food waste by offering smaller plates and allowing customers to request extra portions.', 'Dựa vào câu trên, từ “plate” có nghĩa phù hợp nhất là gì?', '["quá (vượt mức mong muốn, cần thiết hoặc phù hợp)","con gái","ướt; ẩm ướt","cái đĩa"]'::jsonb, 3, 'plate: cái đĩa; tấm kim loại; bản mỏng; mạ (kim loại). Dịch cả câu: Các nhà hàng có thể giảm lãng phí thực phẩm bằng cách cung cấp đĩa nhỏ hơn và cho phép khách hàng yêu cầu thêm phần ăn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_25_19', 'en-a1-25', NULL, 'comprehensive_test', 'reading', NULL, 'Opening public libraries on Saturday allows more working parents to participate in educational activities with their children.', 'Dựa vào câu trên, từ “Saturday” có nghĩa phù hợp nhất là gì?', '["thứ Bảy","môn quần vợt; môn tennis","lễ Giáng Sinh; mùa Giáng Sinh","màu hồng"]'::jsonb, 0, 'Saturday: thứ Bảy. Dịch cả câu: Việc mở cửa các thư viện công cộng vào thứ Bảy cho phép nhiều phụ huynh đi làm tham gia các hoạt động giáo dục cùng con cái hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_25_20', 'en-a1-25', NULL, 'comprehensive_test', 'reading', NULL, 'During dry periods, grass often turns brown as plants conserve water and reduce their growth.', 'Dựa vào câu trên, từ “brown” có nghĩa phù hợp nhất là gì?', '["màu đen; đen","việc mua sắm","màu nâu","tuyệt vời; thú vị"]'::jsonb, 2, 'brown: màu nâu; làm chín vàng; chuyển sang màu nâu. Dịch cả câu: Trong thời kỳ khô hạn, cỏ thường chuyển sang màu nâu khi thực vật giữ nước và giảm sự phát triển.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_25_21', 'en-a1-25', NULL, 'comprehensive_test', 'reading', NULL, 'Affordable public transport can help residents access jobs and reduce their dependence on cars.', 'Dựa vào câu trên, từ “help” có nghĩa phù hợp nhất là gì?', '["giúp đỡ; hỗ trợ","trường đại học","n. tin tức; thông tin mới","tháng Tư"]'::jsonb, 0, 'help: giúp đỡ; hỗ trợ; sự giúp đỡ; sự hỗ trợ. Dịch cả câu: Giao thông công cộng giá cả phải chăng có thể giúp cư dân tiếp cận việc làm và giảm sự phụ thuộc vào ô tô.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_25_22', 'en-a1-25', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ngắn; thấp; chớp nhoáng”', '["short","chocolate","desk","internet"]'::jsonb, 0, 'ngắn; thấp; chớp nhoáng → short (/ʃɔːrt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_25_23', 'en-a1-25', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “mặc; đeo; đội; mang”', '["wear","camera","thing","cheap"]'::jsonb, 0, 'mặc; đeo; đội; mang → wear (/wer/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_25_24', 'en-a1-25', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ngày; một ngày (24 giờ)”', '["group","need","day","grammar"]'::jsonb, 2, 'ngày; một ngày (24 giờ) → day (/deɪ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-26', 'en', 'Bài 26: Đời sống hằng ngày (11) - CEFR A1', 'CEFR A1', 'A1 · Đời sống', '27 từ vựng Tiếng Anh CEFR A1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1026, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_better', 'en-a1-26', 'better', '/ˈbetər/', 'A1', 'tốt hơn; phù hợp hơn; tốt hơn; hiệu quả hơn; khỏe hơn; đỡ hơn', 'adj.', 'good (adj.), well (adv.), best (adj.)', 'Đồng nghĩa: superior · Trái nghĩa: worse', 'Là dạng so sánh hơn của good và well, không dùng từ more better.', 'This backpack is better than my old one.', NULL, 'Chiếc balo này tốt hơn chiếc cũ của tôi.', '{"wordId":"better","ukIpa":"/ˈbetə/","usIpa":"/ˈbetər/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Of higher quality or more suitable than something else.","vi":"tốt hơn; phù hợp hơn"},{"pos":"adv.","en":"In a more effective or satisfactory way.","vi":"tốt hơn; hiệu quả hơn"},{"pos":"adj.","en":"Less ill than before.","vi":"khỏe hơn; đỡ hơn"}],"examples":[{"en":"This backpack is better than my old one.","vi":"Chiếc balo này tốt hơn chiếc cũ của tôi.","audioKind":"ex"},{"en":"Better public transport can reduce traffic congestion and improve access to employment in growing cities.","vi":"Hệ thống giao thông công cộng tốt hơn có thể làm giảm ùn tắc giao thông và cải thiện khả năng tiếp cận việc làm tại các thành phố đang phát triển.","audioKind":"ex2"}],"collocations":[{"en":"better than","vi":"tốt hơn"},{"en":"feel better","vi":"cảm thấy khá hơn"},{"en":"better understanding","vi":"hiểu rõ hơn"},{"en":"much better","vi":"tốt hơn nhiều"}],"wordFamily":["good (adj.)","well (adv.)","best (adj.)"],"synonyms":["superior"],"antonyms":["worse"],"tipVi":"Là dạng so sánh hơn của good và well, không dùng từ more better.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_into', 'en-a1-26', 'into', '/ˈɪntə/', 'A1', 'vào trong; đến bên trong; thành; hóa thành; đam mê; rất thích', 'prep.', NULL, NULL, 'into nhấn mạnh quá trình đi vào bên trong; in thường chỉ vị trí ở bên trong.', 'The kitten jumped into the basket beside my chair.', NULL, 'Chú mèo con đã nhảy vào chiếc giỏ bên cạnh ghế của tôi.', '{"wordId":"into","ukIpa":"/ˈɪntə/","usIpa":"/ˈɪntə/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"towards and then inside something","vi":"vào trong; đến bên trong"},{"pos":"prep.","en":"used to show the result of a change","vi":"thành; hóa thành"},{"pos":"prep.","en":"interested in or enthusiastic about something","vi":"đam mê; rất thích"}],"examples":[{"en":"The kitten jumped into the basket beside my chair.","vi":"Chú mèo con đã nhảy vào chiếc giỏ bên cạnh ghế của tôi.","audioKind":"ex"},{"en":"Converting unused offices into affordable housing could help cities address shortages without expanding into surrounding countryside.","vi":"Việc chuyển đổi các văn phòng không sử dụng thành nhà ở giá rẻ có thể giúp các thành phố giải quyết tình trạng thiếu thốn mà không cần mở rộng ra vùng nông thôn xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"walk into a room","vi":"đi vào phòng"},{"en":"turn into","vi":"biến thành"},{"en":"be into music","vi":"mê âm nhạc"},{"en":"look into a problem","vi":"điều tra một vấn đề"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"into nhấn mạnh quá trình đi vào bên trong; in thường chỉ vị trí ở bên trong.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wrong', 'en-a1-26', 'wrong', '/rɔːŋ/', 'A1', 'sai; không đúng; không phù hợp; sai trái; trái đạo đức; bất chính; sai; một cách sai lầm; hỏng việc', 'adj.', 'wrongly (adv.), wrongful (adj.), wrongdoing (n.)', 'Đồng nghĩa: incorrect, mistaken · Trái nghĩa: right, correct', 'go wrong diễn tả việc xảy ra trục trặc; âm w ở đầu từ wrong không phát âm.', 'I took the wrong bus and ended up near the airport.', NULL, 'Tôi đã lên nhầm xe buýt và cuối cùng lại đến gần khu vực sân bay.', '{"wordId":"wrong","ukIpa":"/rɒŋ/","usIpa":"/rɔːŋ/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Not correct, accurate, or suitable.","vi":"sai; không đúng; không phù hợp"},{"pos":"adj.","en":"Not morally acceptable or fair.","vi":"sai trái; trái đạo đức; bất chính"},{"pos":"adv.","en":"In an incorrect way, or with an unsuccessful result.","vi":"sai; một cách sai lầm; hỏng việc"}],"examples":[{"en":"I took the wrong bus and ended up near the airport.","vi":"Tôi đã lên nhầm xe buýt và cuối cùng lại đến gần khu vực sân bay.","audioKind":"ex"},{"en":"It is wrong to deny children educational opportunities simply because their families cannot afford school fees.","vi":"Thật sai trái khi tước đoạt cơ hội học tập của trẻ em chỉ vì gia đình các em không đủ khả năng đóng học phí.","audioKind":"ex2"}],"collocations":[{"en":"the wrong answer","vi":"câu trả lời sai"},{"en":"go wrong","vi":"gặp trục trặc; hỏng"},{"en":"get something wrong","vi":"hiểu nhầm việc gì; làm sai việc gì"},{"en":"something is wrong with","vi":"có điều gì không ổn với..."}],"wordFamily":["wrongly (adv.)","wrongful (adj.)","wrongdoing (n.)"],"synonyms":["incorrect","mistaken"],"antonyms":["right","correct"],"tipVi":"go wrong diễn tả việc xảy ra trục trặc; âm w ở đầu từ wrong không phát âm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_problem', 'en-a1-26', 'problem', '/ˈprɑːbləm/', 'A1', 'vấn đề; khó khăn; bài toán; câu đố', 'n.', 'problematic (adj.)', 'Đồng nghĩa: difficulty, issue', 'Vấn đề với cái gì dùng a problem with; giải pháp cho vấn đề dùng solution to.', 'There''s a problem with the kitchen tap: it keeps dripping.', NULL, 'Vòi nước trong bếp đang gặp vấn đề: nó cứ bị rỉ nước liên tục.', '{"wordId":"problem","ukIpa":"/ˈprɒbləm/","usIpa":"/ˈprɑːbləm/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a situation that causes difficulty and needs a solution","vi":"vấn đề; khó khăn"},{"pos":"n.","en":"a question requiring thought or calculation to answer","vi":"bài toán; câu đố"}],"examples":[{"en":"There''s a problem with the kitchen tap: it keeps dripping.","vi":"Vòi nước trong bếp đang gặp vấn đề: nó cứ bị rỉ nước liên tục.","audioKind":"ex"},{"en":"Traffic congestion is a growing problem that requires investment in reliable public transport rather than additional roads.","vi":"Tình trạng ùn tắc giao thông là một vấn đề ngày càng gia tăng, đòi hỏi phải đầu tư vào hệ thống giao thông công cộng đáng tin cậy thay vì làm thêm đường sá.","audioKind":"ex2"}],"collocations":[{"en":"solve a problem","vi":"giải quyết vấn đề"},{"en":"a major problem","vi":"vấn đề lớn"},{"en":"a maths problem","vi":"bài toán toán học"},{"en":"a problem with","vi":"vấn đề với cái gì"}],"wordFamily":["problematic (adj.)"],"synonyms":["difficulty","issue"],"antonyms":[],"tipVi":"Vấn đề với cái gì dùng a problem with; giải pháp cho vấn đề dùng solution to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_uncle', 'en-a1-26', 'uncle', '/ˈʌŋkəl/', 'A1', 'chú; bác; cậu; dượng', 'n.', NULL, NULL, 'Từ "uncle" không phân biệt là anh em của bố hay mẹ, cũng không phân biệt là bác hay chú/cậu.', 'My uncle taught me how to mend a bicycle.', NULL, 'Bác tôi đã dạy tôi cách sửa xe đạp.', '{"wordId":"uncle","ukIpa":"/ˈʌŋkəl/","usIpa":"/ˈʌŋkəl/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a parent''s brother or an aunt''s husband","vi":"chú; bác; cậu; dượng"}],"examples":[{"en":"My uncle taught me how to mend a bicycle.","vi":"Bác tôi đã dạy tôi cách sửa xe đạp.","audioKind":"ex"},{"en":"An uncle or aunt can provide valuable emotional support when parents are busy with work commitments.","vi":"Cô, dì, chú, bác có thể cung cấp sự hỗ trợ tinh thần vô giá khi cha mẹ bận rộn với công việc.","audioKind":"ex2"}],"collocations":[{"en":"maternal uncle","vi":"cậu (anh em trai của mẹ)"},{"en":"paternal uncle","vi":"bác hoặc chú (anh em trai của bố)"},{"en":"uncle and aunt","vi":"cô chú bác (họ hàng)"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ \"uncle\" không phân biệt là anh em của bố hay mẹ, cũng không phân biệt là bác hay chú/cậu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_key', 'en-a1-26', 'key', '/kiː/', 'A1', 'chìa khóa; chìa khóa; bí quyết; điều cốt lõi; chủ chốt; quan trọng', 'n.', NULL, NULL, 'the key to trong đó to là giới từ, theo sau là danh từ hoặc danh động từ.', 'I left my house key in my coat pocket.', NULL, 'Tôi để chìa khóa nhà trong túi áo khoác.', '{"wordId":"key","ukIpa":"/kiː/","usIpa":"/kiː/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"An object shaped to open or close a particular lock.","vi":"chìa khóa"},{"pos":"n.","en":"Something essential for understanding or achieving something.","vi":"chìa khóa; bí quyết; điều cốt lõi"},{"pos":"adj.","en":"Extremely important to a situation or its outcome.","vi":"chủ chốt; quan trọng"}],"examples":[{"en":"I left my house key in my coat pocket.","vi":"Tôi để chìa khóa nhà trong túi áo khoác.","audioKind":"ex"},{"en":"Access to reliable information is key to helping consumers make informed decisions about their health.","vi":"Việc tiếp cận thông tin đáng tin cậy là chìa khóa giúp người tiêu dùng đưa ra các quyết định sáng suốt về sức khỏe của họ.","audioKind":"ex2"}],"collocations":[{"en":"a spare key","vi":"một chiếc chìa khóa dự phòng"},{"en":"the key to success","vi":"chìa khóa thành công"},{"en":"a key factor","vi":"một yếu tố then chốt"},{"en":"play a key role","vi":"đóng vai trò quan trọng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"the key to trong đó to là giới từ, theo sau là danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_speak', 'en-a1-26', 'speak', '/spiːk/', 'A1', 'nói; trò chuyện; nói được; sử dụng (ngôn ngữ); phát biểu; diễn thuyết', 'v.', 'speaker (n.), speech (n.), spoken (adj.)', 'Đồng nghĩa: talk', 'Quá khứ là spoke, quá khứ phân từ là spoken; trước tên ngôn ngữ không dùng giới từ.', 'Could I speak to you after the lesson?', NULL, 'Tôi có thể nói chuyện với bạn sau buổi học được không?', '{"wordId":"speak","ukIpa":"/spiːk/","usIpa":"/spiːk/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"Use your voice to say words or communicate with someone.","vi":"nói; trò chuyện"},{"pos":"v.","en":"Be able to communicate in a particular language.","vi":"nói được; sử dụng (ngôn ngữ)"},{"pos":"v.","en":"Address an audience about a subject.","vi":"phát biểu; diễn thuyết"}],"examples":[{"en":"Could I speak to you after the lesson?","vi":"Tôi có thể nói chuyện với bạn sau buổi học được không?","audioKind":"ex"},{"en":"Students who speak more than one language may find it easier to communicate across cultural boundaries.","vi":"Học sinh biết nói nhiều hơn một ngôn ngữ có thể thấy việc giao tiếp qua các ranh giới văn hóa dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"speak fluently","vi":"nói trôi chảy"},{"en":"speak in public","vi":"nói trước công chúng"},{"en":"speak to someone","vi":"nói chuyện với ai đó"},{"en":"speak up","vi":"nói to lên; lên tiếng"}],"wordFamily":["speaker (n.)","speech (n.)","spoken (adj.)"],"synonyms":["talk"],"antonyms":[],"tipVi":"Quá khứ là spoke, quá khứ phân từ là spoken; trước tên ngôn ngữ không dùng giới từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_july', 'en-a1-26', 'July', '/dʒuˈlaɪ/', 'A1', 'tháng Bảy', 'n.', NULL, NULL, 'Tên tháng viết hoa chữ cái đầu; diễn tả vào tháng Bảy dùng in July.', 'We usually visit our cousins for a week in July.', NULL, 'Chúng tôi thường đến thăm họ hàng trong một tuần vào tháng Bảy.', '{"wordId":"july","ukIpa":"/dʒuˈlaɪ/","usIpa":"/dʒuˈlaɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The seventh month of the year, following June","vi":"tháng Bảy"}],"examples":[{"en":"We usually visit our cousins for a week in July.","vi":"Chúng tôi thường đến thăm họ hàng trong một tuần vào tháng Bảy.","audioKind":"ex"},{"en":"In many northern countries, tourism peaks in July, creating seasonal jobs but increasing pressure on local services.","vi":"Ở nhiều quốc gia phương bắc, du lịch đạt đỉnh điểm vào tháng Bảy, tạo ra việc làm theo mùa nhưng làm tăng áp lực lên các dịch vụ địa phương.","audioKind":"ex2"}],"collocations":[{"en":"in July","vi":"vào tháng Bảy"},{"en":"early July","vi":"đầu tháng Bảy"},{"en":"late July","vi":"cuối tháng Bảy"},{"en":"by the end of July","vi":"vào cuối tháng Bảy"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tên tháng viết hoa chữ cái đầu; diễn tả vào tháng Bảy dùng in July.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_again', 'en-a1-26', 'again', '/əˈɡen/', 'A1', 'lại; một lần nữa', 'adv.', NULL, 'Đồng nghĩa: once more', 'again chỉ sự lặp lại; again and again nhấn mạnh lặp đi lặp lại nhiều lần.', 'Could you say that again a little more slowly?', NULL, 'Bạn có thể nói lại điều đó chậm hơn một chút được không?', '{"wordId":"again","ukIpa":"/əˈɡen/","usIpa":"/əˈɡen/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"One more time, or on another occasion.","vi":"lại; một lần nữa"}],"examples":[{"en":"Could you say that again a little more slowly?","vi":"Bạn có thể nói lại điều đó chậm hơn một chút được không?","audioKind":"ex"},{"en":"If cities fail to address the causes of congestion, the same transport problems will occur again.","vi":"Nếu các thành phố không giải quyết nguyên nhân gây tắc nghẽn, các vấn đề giao thông tương tự sẽ lại xảy ra.","audioKind":"ex2"}],"collocations":[{"en":"try again","vi":"thử lại"},{"en":"once again","vi":"một lần nữa"},{"en":"again and again","vi":"hết lần này đến lần khác; lặp đi lặp lại"},{"en":"never again","vi":"không bao giờ lặp lại nữa"}],"wordFamily":[],"synonyms":["once more"],"antonyms":[],"tipVi":"again chỉ sự lặp lại; again and again nhấn mạnh lặp đi lặp lại nhiều lần.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hello', 'en-a1-26', 'hello', '/həˈloʊ/', 'A1', 'xin chào; alo; lời chào', 'int.', NULL, 'Đồng nghĩa: hi · Trái nghĩa: goodbye', 'Từ hello mở đầu cuộc gọi có thể dịch là "alo"; say hello to có nghĩa là gửi lời chào đến ai đó.', 'Hello, would you like to sit next to me?', NULL, 'Xin chào, bạn có muốn ngồi cạnh tôi không?', '{"wordId":"hello","ukIpa":"/həˈləʊ/","usIpa":"/həˈloʊ/","cefr":"A1","topic":"daily","senses":[{"pos":"int.","en":"used to greet someone or begin a phone conversation","vi":"xin chào; alo"},{"pos":"n.","en":"a greeting spoken when meeting someone","vi":"lời chào"}],"examples":[{"en":"Hello, would you like to sit next to me?","vi":"Xin chào, bạn có muốn ngồi cạnh tôi không?","audioKind":"ex"},{"en":"A simple hello between neighbours can encourage social contact and help newcomers feel welcome in a community.","vi":"Một lời chào đơn giản giữa những người hàng xóm có thể khuyến khích giao tiếp xã hội và giúp những người mới đến cảm thấy được chào đón trong cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"say hello","vi":"nói lời chào"},{"en":"hello there","vi":"chào bạn"},{"en":"a friendly hello","vi":"lời chào thân thiện"}],"wordFamily":[],"synonyms":["hi"],"antonyms":["goodbye"],"tipVi":"Từ hello mở đầu cuộc gọi có thể dịch là \"alo\"; say hello to có nghĩa là gửi lời chào đến ai đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sit', 'en-a1-26', 'sit', '/sɪt/', 'A1', 'ngồi; ngồi xuống; ở tại; nằm ở; dự thi; tham gia kỳ thi', 'v.', 'sitting (n.), sitter (n.)', 'Trái nghĩa: stand', 'Quá khứ và quá khứ phân từ đều là sat; hiện tại phân từ là sitting.', 'Come and sit beside me on the garden bench.', NULL, 'Đến đây ngồi cạnh tôi trên chiếc ghế dài ở vườn nhé.', '{"wordId":"sit","ukIpa":"/sɪt/","usIpa":"/sɪt/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to rest with your weight supported by your bottom","vi":"ngồi; ngồi xuống"},{"pos":"v.","en":"to be in a particular place or position","vi":"ở tại; nằm ở"},{"pos":"v.","en":"to take an examination","vi":"dự thi; tham gia kỳ thi"}],"examples":[{"en":"Come and sit beside me on the garden bench.","vi":"Đến đây ngồi cạnh tôi trên chiếc ghế dài ở vườn nhé.","audioKind":"ex"},{"en":"Students who sit for long periods should take regular breaks to support their physical health.","vi":"Những học sinh ngồi học trong thời gian dài nên nghỉ ngơi định kỳ để duy trì sức khỏe thể chất.","audioKind":"ex2"}],"collocations":[{"en":"sit down","vi":"ngồi xuống"},{"en":"sit still","vi":"ngồi yên"},{"en":"sit an exam","vi":"dự thi"},{"en":"sit beside someone","vi":"ngồi cạnh ai đó"}],"wordFamily":["sitting (n.)","sitter (n.)"],"synonyms":[],"antonyms":["stand"],"tipVi":"Quá khứ và quá khứ phân từ đều là sat; hiện tại phân từ là sitting.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_seat', 'en-a1-26', 'seat', '/siːt/', 'A1', 'chỗ ngồi; ghế; cung cấp chỗ ngồi; có sức chứa; ghế đại biểu; ghế nghị sĩ', 'n.', 'seating (n.), seated (adj.)', NULL, 'sit là nội động từ; seat thường đi với tân ngữ chỉ người, be seated diễn tả hành động đã ngồi.', 'She saved me a seat near the front.', NULL, 'Cô ấy giữ hộ tôi một chỗ ngồi gần phía trên.', '{"wordId":"seat","ukIpa":"/siːt/","usIpa":"/siːt/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A place or object for someone to sit on.","vi":"chỗ ngồi; ghế"},{"pos":"v.","en":"To provide a sitting place or have room for seated people.","vi":"cung cấp chỗ ngồi; có sức chứa"},{"pos":"n.","en":"A position as a member of an elected body.","vi":"ghế đại biểu; ghế nghị sĩ"}],"examples":[{"en":"She saved me a seat near the front.","vi":"Cô ấy giữ hộ tôi một chỗ ngồi gần phía trên.","audioKind":"ex"},{"en":"Providing more seats on public transport would make daily travel easier for older passengers and families.","vi":"Việc cung cấp nhiều chỗ ngồi hơn trên các phương tiện giao thông công cộng sẽ giúp việc đi lại hàng ngày dễ dàng hơn cho hành khách cao tuổi và các gia đình.","audioKind":"ex2"}],"collocations":[{"en":"take a seat","vi":"ngồi xuống"},{"en":"a window seat","vi":"ghế ngồi cạnh cửa sổ"},{"en":"reserve a seat","vi":"đặt chỗ trước"},{"en":"win a seat","vi":"giành được một ghế nghị sĩ"}],"wordFamily":["seating (n.)","seated (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"sit là nội động từ; seat thường đi với tân ngữ chỉ người, be seated diễn tả hành động đã ngồi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cup', 'en-a1-26', 'cup', '/kʌp/', 'A1', 'cái cốc; tách; một cốc (định lượng); cúp; giải thưởng; khum tay; khum lại', 'n.', 'cupful (n.)', NULL, 'a cup of đi kèm đồ uống; cup đóng vai trò động từ có nghĩa là khum tay cầm nắm vật gì.', 'I warmed my hands around a cup of tea.', NULL, 'Tôi ấp hai tay quanh một tách trà để sưởi ấm.', '{"wordId":"cup","ukIpa":"/kʌp/","usIpa":"/kʌp/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A small drinking container, or the amount it holds.","vi":"cái cốc; tách; một cốc (định lượng)"},{"pos":"n.","en":"A decorative container awarded for winning a competition.","vi":"cúp; giải thưởng"},{"pos":"v.","en":"To curve your hands into a hollow shape to hold something.","vi":"khum tay; khum lại"}],"examples":[{"en":"I warmed my hands around a cup of tea.","vi":"Tôi ấp hai tay quanh một tách trà để sưởi ấm.","audioKind":"ex"},{"en":"Encouraging customers to bring a reusable cup can help cafés reduce waste from disposable packaging.","vi":"Khuyến khích khách hàng mang theo cốc cá nhân có thể giúp các quán cà phê giảm thiểu rác thải từ bao bì dùng một lần.","audioKind":"ex2"}],"collocations":[{"en":"a cup of tea","vi":"một tách trà"},{"en":"a reusable cup","vi":"cốc dùng nhiều lần"},{"en":"win the cup","vi":"giành cúp"},{"en":"cup your hands","vi":"khum tay lại"}],"wordFamily":["cupful (n.)"],"synonyms":[],"antonyms":[],"tipVi":"a cup of đi kèm đồ uống; cup đóng vai trò động từ có nghĩa là khum tay cầm nắm vật gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_monday', 'en-a1-26', 'Monday', '/ˈmʌndeɪ/', 'A1', 'thứ Hai', 'n.', NULL, NULL, 'Tên các ngày trong tuần phải viết hoa chữ cái đầu; dùng giới từ on với Monday, nhưng trước next Monday thì không dùng on.', 'We usually buy fresh fruit at the market on Monday.', NULL, 'Chúng tôi thường mua trái cây tươi ở chợ vào ngày thứ Hai.', '{"wordId":"monday","ukIpa":"/ˈmʌndeɪ/","usIpa":"/ˈmʌndeɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"the day after Sunday and before Tuesday","vi":"thứ Hai"}],"examples":[{"en":"We usually buy fresh fruit at the market on Monday.","vi":"Chúng tôi thường mua trái cây tươi ở chợ vào ngày thứ Hai.","audioKind":"ex"},{"en":"Many employees find Monday mornings stressful because they must deal with tasks accumulated over the weekend.","vi":"Nhiều nhân viên cảm thấy sáng thứ Hai rất áp lực vì họ phải giải quyết những công việc tồn đọng từ cuối tuần.","audioKind":"ex2"}],"collocations":[{"en":"on Monday","vi":"vào thứ Hai"},{"en":"Monday morning","vi":"sáng thứ Hai"},{"en":"every Monday","vi":"mỗi thứ Hai"},{"en":"from Monday to Friday","vi":"từ thứ Hai đến thứ Sáu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tên các ngày trong tuần phải viết hoa chữ cái đầu; dùng giới từ on với Monday, nhưng trước next Monday thì không dùng on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_else', 'en-a1-26', 'else', '/els/', 'A1', 'khác; nữa; nếu không thì; bằng không', 'adv.', NULL, NULL, 'Được đặt sau đại từ bất định hoặc từ để hỏi, chẳng hạn như someone else.', 'Would you like anything else with your soup?', NULL, 'Bạn có muốn dùng thêm món gì khác cùng với súp không?', '{"wordId":"else","ukIpa":"/els/","usIpa":"/els/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"In addition to or different from someone or something mentioned","vi":"khác; nữa"},{"pos":"adv.","en":"Used after or to introduce an alternative or consequence","vi":"nếu không thì; bằng không"}],"examples":[{"en":"Would you like anything else with your soup?","vi":"Bạn có muốn dùng thêm món gì khác cùng với súp không?","audioKind":"ex"},{"en":"Governments must improve public transport, or else growing traffic congestion may undermine the economic benefits of urban development.","vi":"Chính phủ phải cải thiện giao thông công cộng, nếu không tình trạng ùn tắc giao thông gia tăng có thể làm suy giảm lợi ích kinh tế của quá trình phát triển đô thị.","audioKind":"ex2"}],"collocations":[{"en":"someone else","vi":"người khác"},{"en":"anything else","vi":"thứ khác"},{"en":"what else","vi":"còn gì nữa"},{"en":"or else","vi":"nếu không thì"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Được đặt sau đại từ bất định hoặc từ để hỏi, chẳng hạn như someone else.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_in', 'en-a1-26', 'in', '/ɪn/', 'A1', 'ở trong; bên trong; vào lúc; trong vòng; ở trong nhà; đi vào trong', 'prep.', NULL, 'Trái nghĩa: out', 'in two days thường mang nghĩa sau hai ngày nữa; giới từ in cũng đi với tháng và năm.', 'Your keys are in the bowl beside the door.', NULL, 'Chìa khóa của bạn ở trong chiếc bát cạnh cửa ra vào.', '{"wordId":"in","ukIpa":"/ɪn/","usIpa":"/ɪn/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"Inside a place, container, or larger area.","vi":"ở trong; bên trong"},{"pos":"prep.","en":"During a period or after a stated amount of time.","vi":"vào lúc; trong vòng"},{"pos":"adv.","en":"Inside a place, moving inside, or at home.","vi":"ở trong nhà; đi vào trong"}],"examples":[{"en":"Your keys are in the bowl beside the door.","vi":"Chìa khóa của bạn ở trong chiếc bát cạnh cửa ra vào.","audioKind":"ex"},{"en":"Investment in public libraries can help reduce educational inequality and strengthen connections within local communities.","vi":"Đầu tư vào các thư viện công cộng có thể giúp giảm bớt sự bấtégalité trong giáo dục và củng cố sự gắn kết trong các cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"in advance","vi":"trước; sẵn sàng"},{"en":"in the morning","vi":"vào buổi sáng"},{"en":"in public","vi":"trước công chúng; nơi công cộng"},{"en":"in time","vi":"kịp lúc"}],"wordFamily":[],"synonyms":[],"antonyms":["out"],"tipVi":"in two days thường mang nghĩa sau hai ngày nữa; giới từ in cũng đi với tháng và năm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_top', 'en-a1-26', 'top', '/tɑːp/', 'A1', 'đỉnh; bề mặt trên cùng; cao nhất; hàng đầu; đứng đầu; vượt qua', 'n.', NULL, 'Trái nghĩa: bottom', 'on top of có nghĩa là ở phía trên; at the top of có nghĩa là ở trên đỉnh.', 'She placed the star on top of the tree.', NULL, 'Cô ấy đặt ngôi sao lên đỉnh của cây thông Noel.', '{"wordId":"top","ukIpa":"/tɒp/","usIpa":"/tɑːp/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"the highest part or surface of something","vi":"đỉnh; bề mặt trên cùng"},{"pos":"adj.","en":"highest in position, rank, or quality","vi":"cao nhất; hàng đầu"},{"pos":"v.","en":"to rank highest or be greater than something","vi":"đứng đầu; vượt qua"}],"examples":[{"en":"She placed the star on top of the tree.","vi":"Cô ấy đặt ngôi sao lên đỉnh của cây thông Noel.","audioKind":"ex"},{"en":"Improving access to affordable housing should be a top priority for governments facing rapid urban population growth.","vi":"Việc cải thiện khả năng tiếp cận nhà ở giá rẻ nên là ưu tiên hàng đầu đối với các chính phủ đối mặt với tốc độ tăng trưởng dân số đô thị nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"at the top of","vi":"ở đỉnh của"},{"en":"top priority","vi":"ưu tiên hàng đầu"},{"en":"top marks","vi":"điểm số cao nhất"},{"en":"top the list","vi":"đứng đầu danh sách"}],"wordFamily":[],"synonyms":[],"antonyms":["bottom"],"tipVi":"on top of có nghĩa là ở phía trên; at the top of có nghĩa là ở trên đỉnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_purple', 'en-a1-26', 'purple', '/ˈpɝːpəl/', 'A1', 'màu tím; có màu tím; màu tím', 'adj.', 'purplish (adj.)', NULL, 'purple có thể đóng vai trò là tính từ hoặc danh từ; purplish mang ý nghĩa là hơi tía hoặc ngả tím.', 'He wore a purple scarf with his grey coat.', NULL, 'Anh ấy đeo một chiếc khăn quàng cổ màu tím cùng với chiếc áo khoác màu xám của mình.', '{"wordId":"purple","ukIpa":"/ˈpɜːpəl/","usIpa":"/ˈpɝːpəl/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Having a colour made by mixing red and blue","vi":"màu tím; có màu tím"},{"pos":"n.","en":"A colour between red and blue","vi":"màu tím"}],"examples":[{"en":"He wore a purple scarf with his grey coat.","vi":"Anh ấy đeo một chiếc khăn quàng cổ màu tím cùng với chiếc áo khoác màu xám của mình.","audioKind":"ex"},{"en":"Garden designers often combine purple flowers with yellow varieties to create a striking visual contrast.","vi":"Các nhà thiết kế cảnh quan thường kết hợp hoa màu tím với các giống hoa màu vàng để tạo ra sự tương phản thị giác nổi bật.","audioKind":"ex2"}],"collocations":[{"en":"dark purple","vi":"tím đậm"},{"en":"pale purple","vi":"tím nhạt"},{"en":"purple flowers","vi":"những bông hoa màu tím"}],"wordFamily":["purplish (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"purple có thể đóng vai trò là tính từ hoặc danh từ; purplish mang ý nghĩa là hơi tía hoặc ngả tím.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bottle', 'en-a1-26', 'bottle', '/ˈbɑːtl/', 'A1', 'bình; chai; dung tích một chai; đóng chai', 'n.', 'bottled (adj.), bottling (n.)', NULL, 'a bottle of water là một chai nước; water bottle là bình nước.', 'She filled her water bottle before leaving the house.', NULL, 'Cô ấy đã đổ đầy nước vào bình trước khi rời khỏi nhà.', '{"wordId":"bottle","ukIpa":"/ˈbɒtl/","usIpa":"/ˈbɑːtl/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A narrow-necked container for liquids, or the amount it holds.","vi":"bình; chai; dung tích một chai"},{"pos":"v.","en":"To put a liquid into bottles for storage or sale.","vi":"đóng chai"}],"examples":[{"en":"She filled her water bottle before leaving the house.","vi":"Cô ấy đã đổ đầy nước vào bình trước khi rời khỏi nhà.","audioKind":"ex"},{"en":"Choosing a reusable bottle instead of disposable plastic containers can help reduce waste in cities.","vi":"Việc lựa chọn một chiếc bình có thể táiusing thay vì các hộp nhựa dùng một lần có thể giúp giảm thiểu rác thải ở các đô thị.","audioKind":"ex2"}],"collocations":[{"en":"a bottle of water","vi":"một chai nước"},{"en":"reusable bottle","vi":"bình tái sử dụng"},{"en":"bottle cap","vi":"nắp chai"},{"en":"bottled water","vi":"nước đóng chai"}],"wordFamily":["bottled (adj.)","bottling (n.)"],"synonyms":[],"antonyms":[],"tipVi":"a bottle of water là một chai nước; water bottle là bình nước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_june', 'en-a1-26', 'June', '/dʒuːn/', 'A1', 'tháng Sáu', 'n.', NULL, NULL, 'Tên tháng phải viết hoa chữ cái đầu; đi với tháng Sáu dùng giới từ in.', 'My sister is getting married in June this year.', NULL, 'Chị gái tôi sẽ tổ chức đám cưới vào tháng Sáu năm nay.', '{"wordId":"june","ukIpa":"/dʒuːn/","usIpa":"/dʒuːn/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The sixth month of the year, between May and July.","vi":"tháng Sáu"}],"examples":[{"en":"My sister is getting married in June this year.","vi":"Chị gái tôi sẽ tổ chức đám cưới vào tháng Sáu năm nay.","audioKind":"ex"},{"en":"The community centre will open in June, providing local residents with affordable exercise classes.","vi":"Trung tâm cộng đồng sẽ mở cửa vào tháng Sáu, cung cấp cho cư dân địa phương các lớp tập thể dục với chi phí phải chăng.","audioKind":"ex2"}],"collocations":[{"en":"in June","vi":"vào tháng Sáu"},{"en":"early June","vi":"đầu tháng Sáu"},{"en":"by the end of June","vi":"vào cuối tháng Sáu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tên tháng phải viết hoa chữ cái đầu; đi với tháng Sáu dùng giới từ in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_turn', 'en-a1-26', 'turn', '/tɝːn/', 'A1', 'quay; xoay; rẽ; trở thành; biến thành; lượt; phiên', 'v.', 'turning (n.)', NULL, 'Khi chỉ sự biến đổi, turn đi với tính từ; turn into đi với danh từ.', 'Turn the handle gently and pull the door towards you.', NULL, 'Hãy nhẹ nhàng xoay tay nắm và kéo cửa về phía bạn.', '{"wordId":"turn","ukIpa":"/tɜːn/","usIpa":"/tɝːn/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"Move around a centre or change direction.","vi":"quay; xoay; rẽ"},{"pos":"v.","en":"Change to a different state, colour, or condition.","vi":"trở thành; biến thành"},{"pos":"n.","en":"An opportunity to do something in an agreed order.","vi":"lượt; phiên"}],"examples":[{"en":"Turn the handle gently and pull the door towards you.","vi":"Hãy nhẹ nhàng xoay tay nắm và kéo cửa về phía bạn.","audioKind":"ex"},{"en":"As populations age, governments must turn their attention to accessible housing and community healthcare.","vi":"Khi dân số già đi, các chính phủ phải chuyển hướng chú ý sang nhà ở dễ tiếp cận và chăm sóc sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"turn left","vi":"rẽ trái"},{"en":"turn red","vi":"chuyển sang màu đỏ"},{"en":"take turns","vi":"lần lượt; thay phiên nhau"},{"en":"turn into","vi":"biến thành"}],"wordFamily":["turning (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ sự biến đổi, turn đi với tính từ; turn into đi với danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_piece', 'en-a1-26', 'piece', '/piːs/', 'A1', 'miếng; mảnh; phần; cái; tác phẩm; bài (văn, nhạc, nghệ thuật); chắp vá; ghép nối', 'n.', NULL, NULL, 'a piece of dùng để định lượng các danh từ không đếm được như advice.', 'She saved the last piece of cake for her brother.', NULL, 'Cô ấy đã để dành miếng bánh ngọt cuối cùng cho em trai mình.', '{"wordId":"piece","ukIpa":"/piːs/","usIpa":"/piːs/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a part of something or a single item","vi":"miếng; mảnh; phần; cái"},{"pos":"n.","en":"a work of writing, music, or art","vi":"tác phẩm; bài (văn, nhạc, nghệ thuật)"},{"pos":"v.","en":"to join separate parts to make something complete","vi":"chắp vá; ghép nối"}],"examples":[{"en":"She saved the last piece of cake for her brother.","vi":"Cô ấy đã để dành miếng bánh ngọt cuối cùng cho em trai mình.","audioKind":"ex"},{"en":"Each piece of evidence should be carefully assessed before researchers draw conclusions about environmental change.","vi":"Mỗi bằng chứng cần được đánh giá kỹ lưỡng trước khi các nhà nghiên cứu đưa ra kết luận về biến đổi khí hậu.","audioKind":"ex2"}],"collocations":[{"en":"a piece of advice","vi":"một lời khuyên"},{"en":"a piece of equipment","vi":"một thiết bị"},{"en":"a piece of music","vi":"một bản nhạc"},{"en":"piece together","vi":"chắp vá lại; ghép lại với nhau"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"a piece of dùng để định lượng các danh từ không đếm được như advice.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pink', 'en-a1-26', 'pink', '/pɪŋk/', 'A1', 'màu hồng', 'adj.', 'pinkish (adj.)', NULL, 'pink vừa có thể làm tính từ vừa làm danh từ chỉ màu hồng.', 'The tree outside our window has pink flowers.', NULL, 'Cây bên ngoài cửa sổ của chúng tôi có những bông hoa màu hồng.', '{"wordId":"pink","ukIpa":"/pɪŋk/","usIpa":"/pɪŋk/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"having a pale red colour","vi":"màu hồng"},{"pos":"n.","en":"a colour made by mixing red with white","vi":"màu hồng"}],"examples":[{"en":"The tree outside our window has pink flowers.","vi":"Cây bên ngoài cửa sổ của chúng tôi có những bông hoa màu hồng.","audioKind":"ex"},{"en":"Designers often use soft colours such as pink to create a welcoming atmosphere in children''s healthcare facilities.","vi":"Các nhà thiết kế thường sử dụng các gam màu dịu nhẹ như màu hồng để tạo bầu không khí ấm cúng tại các cơ sở y tế nhi khoa.","audioKind":"ex2"}],"collocations":[{"en":"pale pink","vi":"màu hồng nhạt"},{"en":"bright pink","vi":"màu hồng sáng"},{"en":"turn pink","vi":"trở nên hồng"}],"wordFamily":["pinkish (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"pink vừa có thể làm tính từ vừa làm danh từ chỉ màu hồng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_garden', 'en-a1-26', 'garden', '/ˈɡɑːrdən/', 'A1', 'vườn; khu vườn; làm vườn', 'n.', 'gardener (n.), gardening (n.)', NULL, 'Trong tiếng Anh-Anh, garden có thể chỉ khoảng sân sau nhà; tiếng Anh-Mỹ thường dùng yard.', 'We picked fresh beans from the garden before lunch.', NULL, 'Chúng tôi đã hái đậu cô ve tươi từ khu vườn trước bữa trưa.', '{"wordId":"garden","ukIpa":"/ˈɡɑːdən/","usIpa":"/ˈɡɑːrdən/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"an area of land where flowers or vegetables are grown","vi":"vườn; khu vườn"},{"pos":"v.","en":"to grow and care for plants in a garden","vi":"làm vườn"}],"examples":[{"en":"We picked fresh beans from the garden before lunch.","vi":"Chúng tôi đã hái đậu cô ve tươi từ khu vườn trước bữa trưa.","audioKind":"ex"},{"en":"Community gardens can strengthen neighbourhood relationships while giving urban residents access to fresh vegetables and green space.","vi":"Các khu vườn cộng đồng có thể thắt chặt tình làng nghĩa xóm đồng thời giúp cư dân thành thị tiếp cận với rau sạch và không gian xanh.","audioKind":"ex2"}],"collocations":[{"en":"vegetable garden","vi":"vườn rau"},{"en":"community garden","vi":"vườn cộng đồng"},{"en":"botanical garden","vi":"vườn bách thảo"},{"en":"garden tools","vi":"dụng cụ làm vườn"}],"wordFamily":["gardener (n.)","gardening (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh, garden có thể chỉ khoảng sân sau nhà; tiếng Anh-Mỹ thường dùng yard.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_until', 'en-a1-26', 'until', '/ənˈtɪl/', 'A1', 'cho đến khi', 'prep.', NULL, 'Đồng nghĩa: till', 'until nhấn mạnh hành động kéo dài đến một thời điểm; by nhấn mạnh hoàn thành không muộn hơn một thời điểm.', 'We waited outside until the rain finally stopped.', NULL, 'Chúng tôi đứng đợi bên ngoài cho đến khi trời tạnh hẳn.', '{"wordId":"until","ukIpa":"/ənˈtɪl/","usIpa":"/ənˈtɪl/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"Up to a particular time or event.","vi":"cho đến khi"},{"pos":"conj.","en":"Up to the time when something happens.","vi":"cho đến khi"}],"examples":[{"en":"We waited outside until the rain finally stopped.","vi":"Chúng tôi đứng đợi bên ngoài cho đến khi trời tạnh hẳn.","audioKind":"ex"},{"en":"Governments should continue supporting renewable energy until cleaner technologies become affordable for the majority of households.","vi":"Chính phủ nên tiếp tục hỗ trợ năng lượng tái tạo cho đến khi các công nghệ sạch hơn trở nên vừa túi tiền đối với đa số hộ gia đình.","audioKind":"ex2"}],"collocations":[{"en":"until recently","vi":"cho đến gần đây"},{"en":"until further notice","vi":"cho đến khi có thông báo mới"},{"en":"not until","vi":"mãi cho đến khi"}],"wordFamily":[],"synonyms":["till"],"antonyms":[],"tipVi":"until nhấn mạnh hành động kéo dài đến một thời điểm; by nhấn mạnh hoàn thành không muộn hơn một thời điểm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_each', 'en-a1-26', 'each', '/iːtʃ/', 'A1', 'mỗi; từng; mỗi người; mỗi vật; mỗi (cho từng cá nhân hoặc sự vật)', 'det.', NULL, 'Đồng nghĩa: every', 'each đi với danh từ số ít; each of đi với danh từ hoặc đại từ số nhiều.', 'Each child carried a small basket into the garden.', NULL, 'Mỗi đứa trẻ đều mang theo một chiếc giỏ nhỏ đi vào khu vườn.', '{"wordId":"each","ukIpa":"/iːtʃ/","usIpa":"/iːtʃ/","cefr":"A1","topic":"daily","senses":[{"pos":"det.","en":"Every individual member of a group, considered separately.","vi":"mỗi; từng"},{"pos":"pron.","en":"Every person or thing in a group, taken separately.","vi":"mỗi người; mỗi vật"},{"pos":"adv.","en":"For every individual person or thing.","vi":"mỗi (cho từng cá nhân hoặc sự vật)"}],"examples":[{"en":"Each child carried a small basket into the garden.","vi":"Mỗi đứa trẻ đều mang theo một chiếc giỏ nhỏ đi vào khu vườn.","audioKind":"ex"},{"en":"Each household can reduce its environmental impact by conserving water and choosing products with less packaging.","vi":"Mỗi hộ gia đình đều có thể giảm tác động đến môi trường bằng cách tiết kiệm nước và chọn mua những sản phẩm ít lớp bao bì hơn.","audioKind":"ex2"}],"collocations":[{"en":"each student","vi":"mỗi học sinh"},{"en":"each of us","vi":"mỗi người chúng ta"},{"en":"each time","vi":"mỗi lần"},{"en":"each other","vi":"lẫn nhau; với nhau"}],"wordFamily":[],"synonyms":["every"],"antonyms":[],"tipVi":"each đi với danh từ số ít; each of đi với danh từ hoặc đại từ số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bath', 'en-a1-26', 'bath', '/bæθ/', 'A1', 'tắm; ngâm bồn; bồn tắm', 'n.', 'bathe (v.), bathtub (n.)', NULL, 'Tiếng Anh-Anh thường dùng have a bath; tiếng Anh-Mỹ thường dùng take a bath.', 'A warm bath helped me relax after the hike.', NULL, 'Một bồn nước ấm giúp tôi thư giãn sau chuyến leo núi.', '{"wordId":"bath","ukIpa":"/bɑːθ/","usIpa":"/bæθ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"Washing your body while sitting or lying in water.","vi":"tắm; ngâm bồn"},{"pos":"n.","en":"A large container that you fill with water for washing yourself.","vi":"bồn tắm"}],"examples":[{"en":"A warm bath helped me relax after the hike.","vi":"Một bồn nước ấm giúp tôi thư giãn sau chuyến leo núi.","audioKind":"ex"},{"en":"Taking shorter showers instead of a daily bath can reduce household water consumption significantly.","vi":"Việc tắm vòi sen nhanh thay vì ngâm bồn mỗi ngày có thể làm giảm đáng kể lượng nước tiêu thụ trong gia đình.","audioKind":"ex2"}],"collocations":[{"en":"have a bath","vi":"tắm"},{"en":"take a bath","vi":"tắm"},{"en":"run a bath","vi":"xả nước đầy bồn tắm"},{"en":"hot bath","vi":"tắm nước nóng"}],"wordFamily":["bathe (v.)","bathtub (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Anh-Anh thường dùng have a bath; tiếng Anh-Mỹ thường dùng take a bath.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_26_1', 'en-a1-26', 'Cách dùng “Monday” (n.) — thứ Hai', 'on Monday  ·  Monday morning  ·  every Monday', 'Tên các ngày trong tuần phải viết hoa chữ cái đầu; dùng giới từ on với Monday, nhưng trước next Monday thì không dùng on.', NULL, '[{"hanzi":"We usually buy fresh fruit at the market on Monday.","pinyin":"","meaning":"Chúng tôi thường mua trái cây tươi ở chợ vào ngày thứ Hai."},{"hanzi":"Many employees find Monday mornings stressful because they must deal with tasks accumulated over the weekend.","pinyin":"","meaning":"Nhiều nhân viên cảm thấy sáng thứ Hai rất áp lực vì họ phải giải quyết những công việc tồn đọng từ cuối tuần."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_26_2', 'en-a1-26', 'Cách dùng “until” (prep.) — cho đến khi', 'until recently  ·  until further notice  ·  not until', 'until nhấn mạnh hành động kéo dài đến một thời điểm; by nhấn mạnh hoàn thành không muộn hơn một thời điểm.', 'Đồng nghĩa: till', '[{"hanzi":"We waited outside until the rain finally stopped.","pinyin":"","meaning":"Chúng tôi đứng đợi bên ngoài cho đến khi trời tạnh hẳn."},{"hanzi":"Governments should continue supporting renewable energy until cleaner technologies become affordable for the majority of households.","pinyin":"","meaning":"Chính phủ nên tiếp tục hỗ trợ năng lượng tái tạo cho đến khi các công nghệ sạch hơn trở nên vừa túi tiền đối với đa số hộ gia đình."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_26_3', 'en-a1-26', 'Cách dùng “purple” (adj.) — màu tím; có màu tím', 'dark purple  ·  pale purple  ·  purple flowers', 'purple có thể đóng vai trò là tính từ hoặc danh từ; purplish mang ý nghĩa là hơi tía hoặc ngả tím.', 'Họ từ (Word Family): purplish (adj.)', '[{"hanzi":"He wore a purple scarf with his grey coat.","pinyin":"","meaning":"Anh ấy đeo một chiếc khăn quàng cổ màu tím cùng với chiếc áo khoác màu xám của mình."},{"hanzi":"Garden designers often combine purple flowers with yellow varieties to create a striking visual contrast.","pinyin":"","meaning":"Các nhà thiết kế cảnh quan thường kết hợp hoa màu tím với các giống hoa màu vàng để tạo ra sự tương phản thị giác nổi bật."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_26_4', 'en-a1-26', 'Cách dùng “hello” (int.) — xin chào; alo', 'say hello  ·  hello there  ·  a friendly hello', 'Từ hello mở đầu cuộc gọi có thể dịch là "alo"; say hello to có nghĩa là gửi lời chào đến ai đó.', 'Đồng nghĩa: hi | Trái nghĩa: goodbye', '[{"hanzi":"Hello, would you like to sit next to me?","pinyin":"","meaning":"Xin chào, bạn có muốn ngồi cạnh tôi không?"},{"hanzi":"A simple hello between neighbours can encourage social contact and help newcomers feel welcome in a community.","pinyin":"","meaning":"Một lời chào đơn giản giữa những người hàng xóm có thể khuyến khích giao tiếp xã hội và giúp những người mới đến cảm thấy được chào đón trong cộng đồng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
