INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_26_1_7', 'ten_26_1', 'speak', 'Could I speak to you after the lesson?', 'Could I speak to you after the lesson?', '/spiːk/', 'Tôi có thể nói chuyện với bạn sau buổi học được không?', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_26_1_8', 'ten_26_1', 'July', 'We usually visit our cousins for a week in July.', 'We usually visit our cousins for a week in July.', '/dʒuˈlaɪ/', 'Chúng tôi thường đến thăm họ hàng trong một tuần vào tháng Bảy.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_26_1_1', 'en-a1-26', 'ten_26_1', 'listening', 'listening', 'This backpack is better than my old one.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Vòi nước trong bếp đang gặp vấn đề: nó cứ bị rỉ nước liên tục.","Chiếc balo này tốt hơn chiếc cũ của tôi.","Chú mèo con đã nhảy vào chiếc giỏ bên cạnh ghế của tôi.","Chúng tôi thường đến thăm họ hàng trong một tuần vào tháng Bảy."]'::jsonb, 1, 'This backpack is better than my old one. → Chiếc balo này tốt hơn chiếc cũ của tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_26_1_2', 'en-a1-26', 'ten_26_1', 'listening', 'listening', 'The kitten jumped into the basket beside my chair.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chú mèo con đã nhảy vào chiếc giỏ bên cạnh ghế của tôi.","Bác tôi đã dạy tôi cách sửa xe đạp.","Tôi để chìa khóa nhà trong túi áo khoác.","Chiếc balo này tốt hơn chiếc cũ của tôi."]'::jsonb, 0, 'The kitten jumped into the basket beside my chair. → Chú mèo con đã nhảy vào chiếc giỏ bên cạnh ghế của tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_26_1_3', 'en-a1-26', 'ten_26_1', 'listening', 'listening', 'I took the wrong bus and ended up near the airport.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chú mèo con đã nhảy vào chiếc giỏ bên cạnh ghế của tôi.","Vòi nước trong bếp đang gặp vấn đề: nó cứ bị rỉ nước liên tục.","Tôi đã lên nhầm xe buýt và cuối cùng lại đến gần khu vực sân bay.","Bác tôi đã dạy tôi cách sửa xe đạp."]'::jsonb, 2, 'I took the wrong bus and ended up near the airport. → Tôi đã lên nhầm xe buýt và cuối cùng lại đến gần khu vực sân bay.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_26_2', 'en-a1-26', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_26_2_1', 'ten_26_2', 'better', 'Better public transport can reduce traffic congestion and improve access to employment in growing cities.', 'Better public transport can reduce traffic congestion and improve access to employment in growing cities.', '/ˈbetər/', 'Hệ thống giao thông công cộng tốt hơn có thể làm giảm ùn tắc giao thông và cải thiện khả năng tiếp cận việc làm tại các thành phố đang phát triển.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_26_2_2', 'ten_26_2', 'into', 'Converting unused offices into affordable housing could help cities address shortages without expanding into surrounding countryside.', 'Converting unused offices into affordable housing could help cities address shortages without expanding into surrounding countryside.', '/ˈɪntə/', 'Việc chuyển đổi các văn phòng không sử dụng thành nhà ở giá rẻ có thể giúp các thành phố giải quyết tình trạng thiếu thốn mà không cần mở rộng ra vùng nông thôn xung quanh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_26_2_3', 'ten_26_2', 'wrong', 'It is wrong to deny children educational opportunities simply because their families cannot afford school fees.', 'It is wrong to deny children educational opportunities simply because their families cannot afford school fees.', '/rɔːŋ/', 'Thật sai trái khi tước đoạt cơ hội học tập của trẻ em chỉ vì gia đình các em không đủ khả năng đóng học phí.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_26_2_4', 'ten_26_2', 'problem', 'Traffic congestion is a growing problem that requires investment in reliable public transport rather than additional roads.', 'Traffic congestion is a growing problem that requires investment in reliable public transport rather than additional roads.', '/ˈprɑːbləm/', 'Tình trạng ùn tắc giao thông là một vấn đề ngày càng gia tăng, đòi hỏi phải đầu tư vào hệ thống giao thông công cộng đáng tin cậy thay vì làm thêm đường sá.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_26_2_5', 'ten_26_2', 'uncle', 'An uncle or aunt can provide valuable emotional support when parents are busy with work commitments.', 'An uncle or aunt can provide valuable emotional support when parents are busy with work commitments.', '/ˈʌŋkəl/', 'Cô, dì, chú, bác có thể cung cấp sự hỗ trợ tinh thần vô giá khi cha mẹ bận rộn với công việc.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_26_2_6', 'ten_26_2', 'key', 'Access to reliable information is key to helping consumers make informed decisions about their health.', 'Access to reliable information is key to helping consumers make informed decisions about their health.', '/kiː/', 'Việc tiếp cận thông tin đáng tin cậy là chìa khóa giúp người tiêu dùng đưa ra các quyết định sáng suốt về sức khỏe của họ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_26_2_1', 'en-a1-26', 'ten_26_2', 'listening', 'listening', 'Better public transport can reduce traffic congestion and improve access to employment in growing cities.', NULL, 'Trong câu vừa nghe, từ “better” mang nghĩa nào sau đây?', '["tốt hơn; phù hợp hơn","đi theo; đi sát phía sau","cười; mỉm cười","nhiều hơn; thêm"]'::jsonb, 0, '“better” (/ˈbetər/): tốt hơn; phù hợp hơn. Câu đầy đủ: Better public transport can reduce traffic congestion and improve access to employment in growing cities.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_26_2_2', 'en-a1-26', 'ten_26_2', 'listening', 'listening', 'Converting unused offices into affordable housing could help cities address shortages without expanding into surrounding countryside.', NULL, 'Trong câu vừa nghe, từ “into” mang nghĩa nào sau đây?', '["rất; lắm","vào trong; đến bên trong","ướt; ẩm ướt","bánh mì"]'::jsonb, 1, '“into” (/ˈɪntə/): vào trong; đến bên trong. Câu đầy đủ: Converting unused offices into affordable housing could help cities address shortages without expanding into surrounding countryside.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
