INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_26_2', 'en-a1-26', NULL, 'comprehensive_test', 'listening', 'The kitten jumped into the basket beside my chair.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cây bên ngoài cửa sổ của chúng tôi có những bông hoa màu hồng.","Chú mèo con đã nhảy vào chiếc giỏ bên cạnh ghế của tôi.","Cô ấy đặt ngôi sao lên đỉnh của cây thông Noel.","Chiếc balo này tốt hơn chiếc cũ của tôi."]'::jsonb, 1, 'The kitten jumped into the basket beside my chair. → Chú mèo con đã nhảy vào chiếc giỏ bên cạnh ghế của tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
