INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_26_4', 'en-a1-26', NULL, 'comprehensive_test', 'listening', 'There''s a problem with the kitchen tap: it keeps dripping.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã hái đậu cô ve tươi từ khu vườn trước bữa trưa.","Vòi nước trong bếp đang gặp vấn đề: nó cứ bị rỉ nước liên tục.","Chiếc balo này tốt hơn chiếc cũ của tôi.","Tôi có thể nói chuyện với bạn sau buổi học được không?"]'::jsonb, 1, 'There''s a problem with the kitchen tap: it keeps dripping. → Vòi nước trong bếp đang gặp vấn đề: nó cứ bị rỉ nước liên tục.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
