INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_26_18', 'en-a1-26', NULL, 'comprehensive_test', 'reading', NULL, 'Better public transport can reduce traffic congestion and improve access to employment in growing cities.', 'Dựa vào câu trên, từ “better” có nghĩa phù hợp nhất là gì?', '["tốt hơn; phù hợp hơn","thủ đô của Vương quốc Anh","nhanh chóng; nhanh nhẹn","tin nhắn; lời nhắn"]'::jsonb, 0, 'better: tốt hơn; phù hợp hơn; tốt hơn; hiệu quả hơn; khỏe hơn; đỡ hơn. Dịch cả câu: Hệ thống giao thông công cộng tốt hơn có thể làm giảm ùn tắc giao thông và cải thiện khả năng tiếp cận việc làm tại các thành phố đang phát triển.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_26_19', 'en-a1-26', NULL, 'comprehensive_test', 'reading', NULL, 'Converting unused offices into affordable housing could help cities address shortages without expanding into surrounding countryside.', 'Dựa vào câu trên, từ “into” có nghĩa phù hợp nhất là gì?', '["quan tâm; có hứng thú","chính bạn; bản thân bạn","vào trong; đến bên trong","tìm thấy; tìm ra"]'::jsonb, 2, 'into: vào trong; đến bên trong; thành; hóa thành; đam mê; rất thích. Dịch cả câu: Việc chuyển đổi các văn phòng không sử dụng thành nhà ở giá rẻ có thể giúp các thành phố giải quyết tình trạng thiếu thốn mà không cần mở rộng ra vùng nông thôn xung quanh.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_26_20', 'en-a1-26', NULL, 'comprehensive_test', 'reading', NULL, 'It is wrong to deny children educational opportunities simply because their families cannot afford school fees.', 'Dựa vào câu trên, từ “wrong” có nghĩa phù hợp nhất là gì?', '["bảng chữ cái","trà; nước trà","sai; không đúng; không phù hợp","rất; vô cùng"]'::jsonb, 2, 'wrong: sai; không đúng; không phù hợp; sai trái; trái đạo đức; bất chính; sai; một cách sai lầm; hỏng việc. Dịch cả câu: Thật sai trái khi tước đoạt cơ hội học tập của trẻ em chỉ vì gia đình các em không đủ khả năng đóng học phí.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_26_21', 'en-a1-26', NULL, 'comprehensive_test', 'reading', NULL, 'Traffic congestion is a growing problem that requires investment in reliable public transport rather than additional roads.', 'Dựa vào câu trên, từ “problem” có nghĩa phù hợp nhất là gì?', '["vấn đề; khó khăn","bức ảnh; bức hình","mặt trước; phần trước","màu sắc"]'::jsonb, 0, 'problem: vấn đề; khó khăn; bài toán; câu đố. Dịch cả câu: Tình trạng ùn tắc giao thông là một vấn đề ngày càng gia tăng, đòi hỏi phải đầu tư vào hệ thống giao thông công cộng đáng tin cậy thay vì làm thêm đường sá.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_26_22', 'en-a1-26', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cho đến khi”', '["until","north","hair","January"]'::jsonb, 0, 'cho đến khi → until (/ənˈtɪl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_26_23', 'en-a1-26', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “mỗi; từng”', '["player","easy","each","desk"]'::jsonb, 2, 'mỗi; từng → each (/iːtʃ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
