INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-27', 'en', 'Bài 27: Đời sống hằng ngày (12) - CEFR A1', 'CEFR A1', 'A1 · Đời sống', '27 từ vựng Tiếng Anh CEFR A1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1027, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nine', 'en-a1-27', 'nine', '/naɪn/', 'A1', 'chín', 'num.', 'ninth (num.), nineteen (num.), ninety (num.)', NULL, 'nine là số đếm; số thứ tự chỉ số chín được viết là ninth.', 'We packed nine apples for our picnic today.', NULL, 'Chúng tôi đã chuẩn bị chín quả táo cho buổi dã ngoại hôm nay.', '{"wordId":"nine","ukIpa":"/naɪn/","usIpa":"/naɪn/","cefr":"A1","topic":"daily","senses":[{"pos":"num.","en":"The number after eight and before ten.","vi":"chín"}],"examples":[{"en":"We packed nine apples for our picnic today.","vi":"Chúng tôi đã chuẩn bị chín quả táo cho buổi dã ngoại hôm nay.","audioKind":"ex"},{"en":"The survey found that nine local schools had introduced cycling lessons to encourage more sustainable travel.","vi":"Khảo sát cho thấy chín trường học trong khu vực đã đưa các bài học đạp xe vào giảng dạy nhằm khuyến khích hình thức di chuyển bền vững hơn.","audioKind":"ex2"}],"collocations":[{"en":"nine o''clock","vi":"chín giờ"},{"en":"nine times out of ten","vi":"mười mươi; chắc chắn"},{"en":"nine months","vi":"chín tháng"}],"wordFamily":["ninth (num.)","nineteen (num.)","ninety (num.)"],"synonyms":[],"antonyms":[],"tipVi":"nine là số đếm; số thứ tự chỉ số chín được viết là ninth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_twelve', 'en-a1-27', 'twelve', '/twelv/', 'A1', 'mười hai', 'num.', 'twelfth (num.)', NULL, 'twelve là số đếm; số thứ tự twelfth có sự thay đổi về chính tả.', 'There are twelve fresh eggs in this carton.', NULL, 'Có mười hai quả trứng tươi trong hộp này.', '{"wordId":"twelve","ukIpa":"/twelv/","usIpa":"/twelv/","cefr":"A1","topic":"daily","senses":[{"pos":"num.","en":"the number after eleven and before thirteen","vi":"mười hai"}],"examples":[{"en":"There are twelve fresh eggs in this carton.","vi":"Có mười hai quả trứng tươi trong hộp này.","audioKind":"ex"},{"en":"The training programme lasts twelve weeks and combines practical experience with classroom instruction for young adults.","vi":"Chương trình đào tạo kéo dài mười hai tuần, kết hợp giữa kinh nghiệm thực tế và giảng dạy trên lớp dành cho thanh thiếu niên.","audioKind":"ex2"}],"collocations":[{"en":"twelve months","vi":"mười hai tháng"},{"en":"twelve o''clock","vi":"mười hai giờ"},{"en":"twelve years old","vi":"mười hai tuổi"}],"wordFamily":["twelfth (num.)"],"synonyms":[],"antonyms":[],"tipVi":"twelve là số đếm; số thứ tự twelfth có sự thay đổi về chính tả.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_moment', 'en-a1-27', 'moment', '/ˈmoʊmənt/', 'A1', 'khoảnh khắc; chốc lát; thời điểm; cơ hội', 'n.', 'momentary (adj.), momentarily (adv.)', 'Đồng nghĩa: instant', 'at the moment chỉ hiện tại; in a moment chỉ tương lai gần (ngay lập tức).', 'Wait a moment while I put my shoes on.', NULL, 'Đợi một lát trong lúc tôi đi giày nhé.', '{"wordId":"moment","ukIpa":"/ˈməʊmənt/","usIpa":"/ˈmoʊmənt/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A very short period of time.","vi":"khoảnh khắc; chốc lát"},{"pos":"n.","en":"A particular point in time, sometimes especially important.","vi":"thời điểm; cơ hội"}],"examples":[{"en":"Wait a moment while I put my shoes on.","vi":"Đợi một lát trong lúc tôi đi giày nhé.","audioKind":"ex"},{"en":"The opening of the new railway marked a significant moment in the region''s economic development.","vi":"Việc khai trương tuyến đường sắt mới đánh dấu một thời điểm quan trọng trong sự phát triển kinh tế của khu vực.","audioKind":"ex2"}],"collocations":[{"en":"at the moment","vi":"hiện tại; lúc này"},{"en":"in a moment","vi":"chốc nữa; lát nữa"},{"en":"a brief moment","vi":"một khoảnh khắc ngắn ngủi"},{"en":"a turning point moment","vi":"khoảnh khắc bước ngoặt"}],"wordFamily":["momentary (adj.)","momentarily (adv.)"],"synonyms":["instant"],"antonyms":[],"tipVi":"at the moment chỉ hiện tại; in a moment chỉ tương lai gần (ngay lập tức).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_want', 'en-a1-27', 'want', '/wɑːnt/', 'A1', 'muốn; ao ước; sự thiếu thốn; cảnh nghèo túng', 'v.', 'wanted (adj.), unwanted (adj.)', 'Đồng nghĩa: wish, desire', 'Dùng want to do hoặc want sb to do, không dùng want doing để diễn tả ý muốn làm gì.', 'I want to grow tomatoes on our balcony.', NULL, 'Tôi muốn trồng cà chua ngoài ban công nhà mình.', '{"wordId":"want","ukIpa":"/wɒnt/","usIpa":"/wɑːnt/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To desire something or wish for something to happen.","vi":"muốn; ao ước"},{"pos":"n.","en":"A lack of something needed, especially basic necessities.","vi":"sự thiếu thốn; cảnh nghèo túng"}],"examples":[{"en":"I want to grow tomatoes on our balcony.","vi":"Tôi muốn trồng cà chua ngoài ban công nhà mình.","audioKind":"ex"},{"en":"Many young adults want governments to invest more in affordable housing rather than expensive urban redevelopment projects.","vi":"Nhiều người trẻ tuổi muốn chính phủ đầu tư nhiều hơn vào nhà ở giá rẻ thay vì các dự án tái phát triển đô thị tốn kém.","audioKind":"ex2"}],"collocations":[{"en":"want to do something","vi":"muốn làm gì đó"},{"en":"want someone to do something","vi":"muốn ai đó làm gì đó"},{"en":"for want of","vi":"vì thiếu...; do không có..."}],"wordFamily":["wanted (adj.)","unwanted (adj.)"],"synonyms":["wish","desire"],"antonyms":[],"tipVi":"Dùng want to do hoặc want sb to do, không dùng want doing để diễn tả ý muốn làm gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_another', 'en-a1-27', 'another', '/əˈnʌðɚ/', 'A1', 'một... nữa; khác; người khác; vật khác', 'det.', NULL, NULL, 'Thường đi với danh từ số ít; cấu trúc another two days dùng để chỉ thêm hai ngày nữa.', 'This cup is cracked, so please bring me another.', NULL, 'Chiếc cốc này bị nứt rồi, làm ơn mang cho tôi cái khác nhé.', '{"wordId":"another","ukIpa":"/əˈnʌðə/","usIpa":"/əˈnʌðɚ/","cefr":"A1","topic":"daily","senses":[{"pos":"det.","en":"one more, or a different one","vi":"một... nữa; khác"},{"pos":"pron.","en":"one more person or thing, or a different one","vi":"người khác; vật khác"}],"examples":[{"en":"This cup is cracked, so please bring me another.","vi":"Chiếc cốc này bị nứt rồi, làm ơn mang cho tôi cái khác nhé.","audioKind":"ex"},{"en":"Another reason to invest in public transport is its potential to reduce urban air pollution.","vi":"Một lý do khác để đầu tư vào giao thông công cộng là tiềm năng giảm thiểu ô nhiễm không khí đô thị của nó.","audioKind":"ex2"}],"collocations":[{"en":"another chance","vi":"một cơ hội khác"},{"en":"another option","vi":"một lựa chọn khác"},{"en":"one after another","vi":"hết người này đến người khác"},{"en":"another two days","vi":"thêm hai ngày nữa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường đi với danh từ số ít; cấu trúc another two days dùng để chỉ thêm hai ngày nữa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slowly', 'en-a1-27', 'slowly', '/ˈsloʊli/', 'A1', 'chậm rãi; từ từ', 'adv.', 'slow (adj.), slow (v.), slowness (n.)', 'Đồng nghĩa: unhurriedly · Trái nghĩa: quickly, rapidly', 'slowly là trạng từ, dùng để bổ nghĩa cho động từ; slow thường đóng vai trò là tính từ.', 'She slowly poured the hot soup into bowls.', NULL, 'Cô ấy chậm rãi rót bát súp nóng ra các cái bát.', '{"wordId":"slowly","ukIpa":"/ˈsləʊli/","usIpa":"/ˈsloʊli/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"At a low speed or over a long time.","vi":"chậm rãi; từ từ"}],"examples":[{"en":"She slowly poured the hot soup into bowls.","vi":"Cô ấy chậm rãi rót bát súp nóng ra các cái bát.","audioKind":"ex"},{"en":"Although public attitudes are changing slowly, more consumers are choosing products with less plastic packaging.","vi":"Mặc dù thái độ của công cộng đang thay đổi chậm rãi, nhưng ngày càng có nhiều người tiêu dùng chọn các sản phẩm ít bao bì nhựa hơn.","audioKind":"ex2"}],"collocations":[{"en":"move slowly","vi":"di chuyển chậm rãi"},{"en":"speak slowly","vi":"nói chậm rãi"},{"en":"slowly but surely","vi":"chậm mà chắc"}],"wordFamily":["slow (adj.)","slow (v.)","slowness (n.)"],"synonyms":["unhurriedly"],"antonyms":["quickly","rapidly"],"tipVi":"slowly là trạng từ, dùng để bổ nghĩa cho động từ; slow thường đóng vai trò là tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_glasses', 'en-a1-27', 'glasses', '/ˈɡlæsɪz/', 'A1', 'kính đeo mắt; cốc thủy tinh', 'n.', 'glass (n.)', 'Đồng nghĩa: spectacles', 'Khi chỉ kính mắt thì dùng dạng số nhiều; một cặp kính dùng a pair of glasses.', 'I left my glasses beside the bed last night.', NULL, 'Tối qua tôi để quên kính ở cạnh giường.', '{"wordId":"glasses","ukIpa":"/ˈɡlɑːsɪz/","usIpa":"/ˈɡlæsɪz/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"Two lenses in a frame worn to improve sight.","vi":"kính đeo mắt"},{"pos":"n.","en":"Containers made of glass, usually used for drinking.","vi":"cốc thủy tinh"}],"examples":[{"en":"I left my glasses beside the bed last night.","vi":"Tối qua tôi để quên kính ở cạnh giường.","audioKind":"ex"},{"en":"Regular eye examinations help students obtain suitable glasses, allowing them to read comfortably and participate fully in lessons.","vi":"Việc kiểm tra mắt định kỳ giúp học sinh có được chiếc kính phù hợp, giúp các em đọc sách thoải mái và tham gia đầy đủ vào các bài học.","audioKind":"ex2"}],"collocations":[{"en":"a pair of glasses","vi":"một cặp kính"},{"en":"wear glasses","vi":"đeo kính"},{"en":"reading glasses","vi":"kính đọc sách"},{"en":"drinking glasses","vi":"cốc uống nước"}],"wordFamily":["glass (n.)"],"synonyms":["spectacles"],"antonyms":[],"tipVi":"Khi chỉ kính mắt thì dùng dạng số nhiều; một cặp kính dùng a pair of glasses.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_special', 'en-a1-27', 'special', '/ˈspeʃəl/', 'A1', 'đặc biệt; khác thường; riêng biệt; chuyên dụng; món đặc sản; sản phẩm đặc biệt', 'adj.', 'specially (adv.), specialise (v.), specialist (n.)', 'Đồng nghĩa: particular, exceptional · Trái nghĩa: ordinary', 'specially nhấn mạnh tính chuyên dụng; especially thường dùng để chỉ ý đặc biệt là / nhất là.', 'We saved this special cake for your birthday.', NULL, 'Chúng tôi đã để dành chiếc bánh đặc biệt này cho ngày sinh nhật của bạn.', '{"wordId":"special","ukIpa":"/ˈspeʃəl/","usIpa":"/ˈspeʃəl/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Different from usual, often in an important or valued way.","vi":"đặc biệt; khác thường"},{"pos":"adj.","en":"Intended for a particular purpose or person.","vi":"riêng biệt; chuyên dụng"},{"pos":"n.","en":"A specially priced product or a featured restaurant dish.","vi":"món đặc sản; sản phẩm đặc biệt"}],"examples":[{"en":"We saved this special cake for your birthday.","vi":"Chúng tôi đã để dành chiếc bánh đặc biệt này cho ngày sinh nhật của bạn.","audioKind":"ex"},{"en":"Schools should provide special equipment so that students with disabilities can participate fully in classroom activities.","vi":"Các trường học nên cung cấp các thiết bị chuyên dụng để học sinh khuyết tật có thể tham gia đầy đủ vào các hoạt động trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"special occasion","vi":"dịp đặc biệt"},{"en":"special offer","vi":"ưu đãi đặc biệt"},{"en":"special equipment","vi":"thiết bị chuyên dụng"},{"en":"special attention","vi":"sự quan tâm đặc biệt"}],"wordFamily":["specially (adv.)","specialise (v.)","specialist (n.)"],"synonyms":["particular","exceptional"],"antonyms":["ordinary"],"tipVi":"specially nhấn mạnh tính chuyên dụng; especially thường dùng để chỉ ý đặc biệt là / nhất là.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_meat', 'en-a1-27', 'meat', '/miːt/', 'A1', 'thịt; thịt động vật', 'n.', 'meaty (adj.), meatless (adj.)', NULL, 'Khi chỉ chung thịt để ăn thì không đếm được; dùng meats khi chỉ các loại thịt khác nhau.', 'We keep raw meat separate from vegetables in the fridge.', NULL, 'Chúng tôi để thịt sống tách riêng với rau củ trong tủ lạnh.', '{"wordId":"meat","ukIpa":"/miːt/","usIpa":"/miːt/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The flesh of animals eaten as food.","vi":"thịt; thịt động vật"}],"examples":[{"en":"We keep raw meat separate from vegetables in the fridge.","vi":"Chúng tôi để thịt sống tách riêng với rau củ trong tủ lạnh.","audioKind":"ex"},{"en":"Reducing meat consumption may lower the environmental impact of food production in many countries.","vi":"Việc giảm tiêu thụ thịt có thể làm giảm tác động môi trường của việc sản xuất thực phẩm ở nhiều quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"raw meat","vi":"thịt sống"},{"en":"lean meat","vi":"thịt nạc"},{"en":"red meat","vi":"thịt đỏ"},{"en":"meat consumption","vi":"tiêu thụ thịt"}],"wordFamily":["meaty (adj.)","meatless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ chung thịt để ăn thì không đếm được; dùng meats khi chỉ các loại thịt khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_carry', 'en-a1-27', 'carry', '/ˈkæri/', 'A1', 'cầm, nắm hoặc đỡ cái gì đó trong lúc di chuyển nó đến đâu; mang vác; mang theo thứ gì bên mình mọi lúc mọi nơi; chứa và có tiềm năng lây truyền dịch bệnh hoặc mầm bệnh', 'v.', 'carrier (n.)', NULL, 'carry nhấn mạnh việc mang hoặc vác; bring và take còn thể hiện hướng chuyển động.', 'Could you carry this heavy bag upstairs for me?', NULL, 'Bạn có thể giúp tôi xách chiếc túi nặng này lên lầu không?', '{"wordId":"carry","ukIpa":"/ˈkæri/","usIpa":"/ˈkæri/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"Hold or support something while moving it somewhere","vi":"cầm, nắm hoặc đỡ cái gì đó trong lúc di chuyển nó đến đâu; mang vác"},{"pos":"v.","en":"Have something with you wherever you go","vi":"mang theo thứ gì bên mình mọi lúc mọi nơi"},{"pos":"v.","en":"Contain and potentially pass on a disease or infection","vi":"chứa và có tiềm năng lây truyền dịch bệnh hoặc mầm bệnh"}],"examples":[{"en":"Could you carry this heavy bag upstairs for me?","vi":"Bạn có thể giúp tôi xách chiếc túi nặng này lên lầu không?","audioKind":"ex"},{"en":"Reusable bottles allow commuters to carry drinking water without purchasing disposable plastic containers every day.","vi":"Bình nước tái sử dụng cho phép người đi làm mang theo nước uống mà không cần phải mua chai nhựa dùng một lần mỗi ngày.","audioKind":"ex2"}],"collocations":[{"en":"carry a bag","vi":"xách túi"},{"en":"carry passengers","vi":"chở hành khách"},{"en":"carry a virus","vi":"mang vi-rút"},{"en":"carry out research","vi":"tiến hành nghiên cứu"}],"wordFamily":["carrier (n.)"],"synonyms":[],"antonyms":[],"tipVi":"carry nhấn mạnh việc mang hoặc vác; bring và take còn thể hiện hướng chuyển động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hair', 'en-a1-27', 'hair', '/her/', 'A1', 'tóc, lông mọc trên da người và động vật; một sợi tóc, một sợi lông mọc đơn lẻ trên da', 'n.', 'hairy (adj.), hairless (adj.), hairdresser (n.)', NULL, 'Danh từ chỉ tổng thể mái tóc thường không đếm được; một sợi tóc dùng a hair.', 'She tied her hair back before making lunch.', NULL, 'Cô ấy buộc tóc gọn lại trước khi làm bữa trưa.', '{"wordId":"hair","ukIpa":"/heə/","usIpa":"/her/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"Thin strands growing on the skin of people and animals.","vi":"tóc, lông mọc trên da người và động vật"},{"pos":"n.","en":"A single strand growing from skin.","vi":"một sợi tóc, một sợi lông mọc đơn lẻ trên da"}],"examples":[{"en":"She tied her hair back before making lunch.","vi":"Cô ấy buộc tóc gọn lại trước khi làm bữa trưa.","audioKind":"ex"},{"en":"Some workplaces are relaxing rules about hair and clothing to create a more inclusive environment.","vi":"Một số nơi làm việc đang nới lỏng các quy định về kiểu tóc và trang phục nhằm tạo ra một môi trường hòa nhập hơn.","audioKind":"ex2"}],"collocations":[{"en":"brush your hair","vi":"chải tóc"},{"en":"have your hair cut","vi":"cắt tóc"},{"en":"a strand of hair","vi":"một sợi tóc"},{"en":"hair loss","vi":"rụng tóc"}],"wordFamily":["hairy (adj.)","hairless (adj.)","hairdresser (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ chỉ tổng thể mái tóc thường không đếm được; một sợi tóc dùng a hair.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_green', 'en-a1-27', 'green', '/ɡriːn/', 'A1', 'có màu của cỏ và phần lớn lá cây; gây ít tác hại cho môi trường; màu xanh lá cây', 'adj.', 'greenish (adj.), greenness (n.), greenery (n.)', NULL, 'Ngoài màu sắc, green thường mang nghĩa thân thiện với môi trường; khi chỉ con người, từ này còn có thể chỉ sự thiếu kinh nghiệm.', 'She wore a green jacket to match her shoes.', NULL, 'Cô ấy mặc một chiếc áo khoác màu xanh lá cây để phối cùng đôi giày của mình.', '{"wordId":"green","ukIpa":"/ɡriːn/","usIpa":"/ɡriːn/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Having the colour of grass and most leaves.","vi":"có màu của cỏ và phần lớn lá cây"},{"pos":"adj.","en":"Causing little harm to the environment.","vi":"gây ít tác hại cho môi trường"},{"pos":"n.","en":"The colour of grass and most leaves.","vi":"màu xanh lá cây"}],"examples":[{"en":"She wore a green jacket to match her shoes.","vi":"Cô ấy mặc một chiếc áo khoác màu xanh lá cây để phối cùng đôi giày của mình.","audioKind":"ex"},{"en":"Governments can encourage green transport by improving public services and building safer routes for cyclists.","vi":"Chính phủ có thể khuyến khích giao thông xanh bằng cách cải thiện các dịch vụ công cộng và xây dựng những tuyến đường an toàn hơn cho người đi xe đạp.","audioKind":"ex2"}],"collocations":[{"en":"green vegetables","vi":"rau xanh"},{"en":"green energy","vi":"năng lượng xanh"},{"en":"green spaces","vi":"không gian xanh"},{"en":"go green","vi":"sống xanh"}],"wordFamily":["greenish (adj.)","greenness (n.)","greenery (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Ngoài màu sắc, green thường mang nghĩa thân thiện với môi trường; khi chỉ con người, từ này còn có thể chỉ sự thiếu kinh nghiệm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_call', 'en-a1-27', 'call', '/kɔːl/', 'A1', 'gọi điện thoại cho ai đó hoặc hét lên để thu hút sự chú ý; đặt tên cho ai hoặc cái gì đó; cuộc gọi điện thoại hoặc lời kêu gọi công chúng hành động', 'v.', 'caller (n.)', NULL, 'call sb nghĩa là gọi cho ai đó, không đi kèm giới từ to.', 'I''ll call you when I get home tonight.', NULL, 'Tôi sẽ gọi cho bạn khi tôi về đến nhà tối nay.', '{"wordId":"call","ukIpa":"/kɔːl/","usIpa":"/kɔːl/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To telephone someone or shout to get their attention.","vi":"gọi điện thoại cho ai đó hoặc hét lên để thu hút sự chú ý"},{"pos":"v.","en":"To give someone or something a particular name.","vi":"đặt tên cho ai hoặc cái gì đó"},{"pos":"n.","en":"A telephone conversation or a public request for action.","vi":"cuộc gọi điện thoại hoặc lời kêu gọi công chúng hành động"}],"examples":[{"en":"I''ll call you when I get home tonight.","vi":"Tôi sẽ gọi cho bạn khi tôi về đến nhà tối nay.","audioKind":"ex"},{"en":"Environmental groups call for stricter regulations to reduce plastic waste entering rivers and oceans.","vi":"Các nhóm bảo vệ môi trường kêu gọi ban hành các quy định nghiêm ngặt hơn để giảm thiểu lượng rác thải nhựa tràn vào sông ngòi và đại dương.","audioKind":"ex2"}],"collocations":[{"en":"make a call","vi":"gọi điện thoại"},{"en":"call for action","vi":"kêu gọi hành động"},{"en":"call someone back","vi":"gọi lại cho ai đó"}],"wordFamily":["caller (n.)"],"synonyms":[],"antonyms":[],"tipVi":"call sb nghĩa là gọi cho ai đó, không đi kèm giới từ to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cheese', 'en-a1-27', 'cheese', '/tʃiːz/', 'A1', 'phô mai, pho-mát được làm bằng cách ép hoặc ủ phần chất rắn của sữa', 'n.', 'cheesy (adj.)', NULL, 'Thông thường là danh từ không đếm được; một miếng phô mai dùng a piece of cheese.', 'I added some cheese to my warm vegetable sandwich.', NULL, 'Tôi đã cho thêm một ít phô mai vào chiếc bánh mì kẹp rau củ ấm nóng của mình.', '{"wordId":"cheese","ukIpa":"/tʃiːz/","usIpa":"/tʃiːz/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A food made by pressing or ripening the solids of milk.","vi":"phô mai, pho-mát được làm bằng cách ép hoặc ủ phần chất rắn của sữa"}],"examples":[{"en":"I added some cheese to my warm vegetable sandwich.","vi":"Tôi đã cho thêm một ít phô mai vào chiếc bánh mì kẹp rau củ ấm nóng của mình.","audioKind":"ex"},{"en":"Although cheese provides protein and calcium, some varieties contain high levels of salt and saturated fat.","vi":"Mặc dù phô mai cung cấp protein và canxi, một số loại lại chứa hàm lượng muối và chất béo bão hòa cao.","audioKind":"ex2"}],"collocations":[{"en":"a slice of cheese","vi":"một lát phô mai"},{"en":"grated cheese","vi":"phô mai bào"},{"en":"cream cheese","vi":"phô mai kem"},{"en":"cheese sandwich","vi":"bánh mì kẹp phô mai"}],"wordFamily":["cheesy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thông thường là danh từ không đếm được; một miếng phô mai dùng a piece of cheese.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_long', 'en-a1-27', 'long', '/lɔːŋ/', 'A1', 'có chiều dài lớn hoặc kéo dài trong khoảng thời gian lâu; trong một khoảng thời gian dài; khao khát, mong mỏi điều gì đó mãnh liệt, đặc biệt là thứ không có sẵn', 'adj.', 'length (n.), lengthen (v.), lengthy (adj.)', 'Trái nghĩa: short', 'Động từ long theo sau bởi for cộng danh từ, hoặc to cộng động từ nguyên mẫu.', 'Her long scarf nearly touched the wet pavement.', NULL, 'Chiếc khăn quàng cổ dài của cô ấy gần như chạm tới mặt đường ướt sũng.', '{"wordId":"long","ukIpa":"/lɒŋ/","usIpa":"/lɔːŋ/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Extending a great distance or lasting a great time.","vi":"có chiều dài lớn hoặc kéo dài trong khoảng thời gian lâu"},{"pos":"adv.","en":"For a great amount of time.","vi":"trong một khoảng thời gian dài"},{"pos":"v.","en":"To want something very strongly, especially something unavailable.","vi":"khao khát, mong mỏi điều gì đó mãnh liệt, đặc biệt là thứ không có sẵn"}],"examples":[{"en":"Her long scarf nearly touched the wet pavement.","vi":"Chiếc khăn quàng cổ dài của cô ấy gần như chạm tới mặt đường ướt sũng.","audioKind":"ex"},{"en":"Long commuting times can reduce workers'' leisure opportunities and negatively affect their overall quality of life.","vi":"Thời gian di chuyển dài có thể làm giảm cơ hội giải trí của người lao động và ảnh hưởng tiêu cực đến chất lượng cuộc sống tổng thể của họ.","audioKind":"ex2"}],"collocations":[{"en":"a long time","vi":"một khoảng thời gian dài"},{"en":"long hours","vi":"làm việc nhiều giờ liền"},{"en":"long for","vi":"khao khát"},{"en":"long to do something","vi":"khao khát làm điều gì đó"}],"wordFamily":["length (n.)","lengthen (v.)","lengthy (adj.)"],"synonyms":[],"antonyms":["short"],"tipVi":"Động từ long theo sau bởi for cộng danh từ, hoặc to cộng động từ nguyên mẫu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pay', 'en-a1-27', 'pay', '/peɪ/', 'A1', 'thanh toán; trả tiền; trả lương; lương; tiền công; thù lao; đáng giá; mang lại lợi ích', 'v.', 'payment (n.), payable (adj.), payer (n.), unpaid (adj.)', NULL, 'pay for đi với mặt hàng mua; pay đi với hóa đơn hoặc số tiền; quá khứ là paid.', 'Can I pay for these apples by card?', NULL, 'Tôi có thể thanh toán tiền những quả táo này bằng thẻ không?', '{"wordId":"pay","ukIpa":"/peɪ/","usIpa":"/peɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To give money for something or for someone''s work","vi":"thanh toán; trả tiền; trả lương"},{"pos":"n.","en":"Money received regularly for doing a job","vi":"lương; tiền công; thù lao"},{"pos":"v.","en":"To bring a benefit or be worth doing","vi":"đáng giá; mang lại lợi ích"}],"examples":[{"en":"Can I pay for these apples by card?","vi":"Tôi có thể thanh toán tiền những quả táo này bằng thẻ không?","audioKind":"ex"},{"en":"Employers should pay workers fairly to improve staff morale and reduce the number of people leaving.","vi":"Người lao động nên được trả lương công bằng để nâng cao tinh thần làm việc và giảm tỷ lệ nghỉ việc.","audioKind":"ex2"}],"collocations":[{"en":"pay a bill","vi":"thanh toán hóa đơn"},{"en":"pay for something","vi":"trả tiền cho cái gì"},{"en":"pay attention to","vi":"chú ý"},{"en":"equal pay","vi":"lương ngang nhau"}],"wordFamily":["payment (n.)","payable (adj.)","payer (n.)","unpaid (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"pay for đi với mặt hàng mua; pay đi với hóa đơn hoặc số tiền; quá khứ là paid.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_old', 'en-a1-27', 'old', '/oʊld/', 'A1', 'già; lớn tuổi; cũ; lâu đời; có độ tuổi nhất định; trước đây; cũ (trong quá khứ)', 'adj.', 'older (adj.), oldest (adj.)', 'Đồng nghĩa: aged · Trái nghĩa: young, new', 'an old friend thường chỉ người quen lâu năm chứ không nhất thiết phải lớn tuổi.', 'Our old dog sleeps beside the warm kitchen stove.', NULL, 'Con chó già của chúng tôi nằm ngủ cạnh chiếc lò sưởi ấm áp trong bếp.', '{"wordId":"old","ukIpa":"/əʊld/","usIpa":"/oʊld/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Having lived or existed for a long time.","vi":"già; lớn tuổi; cũ; lâu đời"},{"pos":"adj.","en":"Having a particular age.","vi":"có độ tuổi nhất định"},{"pos":"adj.","en":"Belonging to an earlier period of someone''s life.","vi":"trước đây; cũ (trong quá khứ)"}],"examples":[{"en":"Our old dog sleeps beside the warm kitchen stove.","vi":"Con chó già của chúng tôi nằm ngủ cạnh chiếc lò sưởi ấm áp trong bếp.","audioKind":"ex"},{"en":"Preserving old buildings can protect cultural heritage while attracting visitors and supporting the local economy.","vi":"Bảo tồn các tòa nhà cổ có thể bảo vệ di sản văn hóa đồng thời thu hút du khách và hỗ trợ nền kinh tế địa phương.","audioKind":"ex2"}],"collocations":[{"en":"old age","vi":"tuổi già"},{"en":"years old","vi":"tuổi..."},{"en":"old friend","vi":"bạn cũ"},{"en":"old buildings","vi":"các tòa nhà cổ"}],"wordFamily":["older (adj.)","oldest (adj.)"],"synonyms":["aged"],"antonyms":["young","new"],"tipVi":"an old friend thường chỉ người quen lâu năm chứ không nhất thiết phải lớn tuổi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_strawberry', 'en-a1-27', 'strawberry', '/ˈstrɔːberi/', 'A1', 'quả dâu tây', 'n.', NULL, NULL, 'Danh từ đếm được, dạng số nhiều là strawberries.', 'I picked a ripe strawberry and put it in my basket.', NULL, 'Tôi đã hái một quả dâu tây chín mọng và bỏ nó vào giỏ của mình.', '{"wordId":"strawberry","ukIpa":"/ˈstrɔːbəri/","usIpa":"/ˈstrɔːberi/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a soft red fruit with tiny seeds on its surface","vi":"quả dâu tây"}],"examples":[{"en":"I picked a ripe strawberry and put it in my basket.","vi":"Tôi đã hái một quả dâu tây chín mọng và bỏ nó vào giỏ của mình.","audioKind":"ex"},{"en":"Growing strawberries locally can reduce transport distances, although heated greenhouses may increase overall energy consumption.","vi":"Việc trồng dâu tây tại địa phương có thể làm giảm khoảng cách vận chuyển, mặc dù nhà kính sưởi ấm có thể làm tăng tổng lượng tiêu thụ năng lượng.","audioKind":"ex2"}],"collocations":[{"en":"strawberry jam","vi":"mứt dâu tây"},{"en":"ripe strawberries","vi":"những quả dâu tây chín"},{"en":"strawberry plants","vi":"cây dâu tây"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ đếm được, dạng số nhiều là strawberries.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sixteen', 'en-a1-27', 'sixteen', '/ˌsɪkˈstiːn/', 'A1', 'mười sáu', 'num.', 'sixteenth (num.)', NULL, 'Cần phân biệt với sixty (sáu mươi), sixteen có âm /n/ ở cuối.', 'We baked sixteen small cakes for the family picnic.', NULL, 'Chúng tôi đã nướng mười sáu chiếc bánh nhỏ cho chuyến dã ngoại của gia đình.', '{"wordId":"sixteen","ukIpa":"/ˌsɪkˈstiːn/","usIpa":"/ˌsɪkˈstiːn/","cefr":"A1","topic":"daily","senses":[{"pos":"num.","en":"the number after fifteen and before seventeen","vi":"mười sáu"}],"examples":[{"en":"We baked sixteen small cakes for the family picnic.","vi":"Chúng tôi đã nướng mười sáu chiếc bánh nhỏ cho chuyến dã ngoại của gia đình.","audioKind":"ex"},{"en":"In some countries, students can choose vocational training instead of continuing general education at the age of sixteen.","vi":"Ở một số quốc gia, học sinh có thể chọn học nghề thay vì tiếp tục giáo dục phổ thông ở tuổi mười sáu.","audioKind":"ex2"}],"collocations":[{"en":"sixteen years old","vi":"mười sáu tuổi"},{"en":"at sixteen","vi":"vào năm mười sáu tuổi"},{"en":"sixteen students","vi":"mười sáu học sinh"}],"wordFamily":["sixteenth (num.)"],"synonyms":[],"antonyms":[],"tipVi":"Cần phân biệt với sixty (sáu mươi), sixteen có âm /n/ ở cuối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_week', 'en-a1-27', 'week', '/wiːk/', 'A1', 'tuần; tuần lễ; tuần làm việc', 'n.', 'weekly (adj.), weekday (n.), weekend (n.)', NULL, 'Không dùng giới từ trước last, next, this week.', 'I borrowed this book from the library last week.', NULL, 'Tôi đã mượn cuốn sách này từ thư viện vào tuần trước.', '{"wordId":"week","ukIpa":"/wiːk/","usIpa":"/wiːk/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a period of seven days","vi":"tuần; tuần lễ"},{"pos":"n.","en":"the days or hours normally spent working each week","vi":"tuần làm việc"}],"examples":[{"en":"I borrowed this book from the library last week.","vi":"Tôi đã mượn cuốn sách này từ thư viện vào tuần trước.","audioKind":"ex"},{"en":"A shorter working week could improve employee wellbeing, provided that workloads are reduced rather than compressed.","vi":"Một tuần làm việc ngắn hơn có thể cải thiện sức khỏe của nhân viên, với điều kiện khối lượng công việc được cắt giảm thay vì bị dồn nén.","audioKind":"ex2"}],"collocations":[{"en":"last week","vi":"tuần trước"},{"en":"once a week","vi":"mỗi tuần một lần"},{"en":"working week","vi":"tuần làm việc"},{"en":"a week off","vi":"một tuần nghỉ phép"}],"wordFamily":["weekly (adj.)","weekday (n.)","weekend (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Không dùng giới từ trước last, next, this week.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_seventeen', 'en-a1-27', 'seventeen', '/ˌsevənˈtiːn/', 'A1', 'mười bảy', 'num.', 'seventeenth (num.)', NULL, 'Cần phân biệt với seventy (bảy mươi), phát âm rõ phần đuôi từ.', 'My sister is seventeen and loves playing volleyball.', NULL, 'Em gái tôi mười bảy tuổi và rất thích chơi bóng chuyền.', '{"wordId":"seventeen","ukIpa":"/ˌsevənˈtiːn/","usIpa":"/ˌsevənˈtiːn/","cefr":"A1","topic":"daily","senses":[{"pos":"num.","en":"The number after sixteen and before eighteen.","vi":"mười bảy"}],"examples":[{"en":"My sister is seventeen and loves playing volleyball.","vi":"Em gái tôi mười bảy tuổi và rất thích chơi bóng chuyền.","audioKind":"ex"},{"en":"The survey found that seventeen students preferred practical training to traditional classroom instruction.","vi":"Cuộc khảo sát cho thấy mười bảy học sinh thích thực hành hơn là học lý thuyết truyền thống trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"seventeen years old","vi":"mười bảy tuổi"},{"en":"seventeen students","vi":"mười bảy học sinh"},{"en":"at seventeen","vi":"vào năm mười bảy tuổi"}],"wordFamily":["seventeenth (num.)"],"synonyms":[],"antonyms":[],"tipVi":"Cần phân biệt với seventy (bảy mươi), phát âm rõ phần đuôi từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wednesday', 'en-a1-27', 'Wednesday', '/ˈwenzdeɪ/', 'A1', 'ngày thứ Tư', 'n.', NULL, NULL, 'Viết hoa chữ cái đầu; dùng on Wednesday, nhưng trước every Wednesday thì không dùng on.', 'We meet for lunch every Wednesday near the library.', NULL, 'Chúng tôi gặp nhau ăn trưa vào mỗi thứ Tư gần thư viện.', '{"wordId":"wednesday","ukIpa":"/ˈwenzdeɪ/","usIpa":"/ˈwenzdeɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"the day after Tuesday and before Thursday","vi":"ngày thứ Tư"}],"examples":[{"en":"We meet for lunch every Wednesday near the library.","vi":"Chúng tôi gặp nhau ăn trưa vào mỗi thứ Tư gần thư viện.","audioKind":"ex"},{"en":"The community centre offers free language classes every Wednesday to help newcomers participate in local life.","vi":"Trung tâm cộng đồng cung cấp các lớp học ngôn ngữ miễn phí vào mỗi thứ Tư để giúp những người mới đến hòa nhập với cuộc sống địa phương.","audioKind":"ex2"}],"collocations":[{"en":"on Wednesday","vi":"vào ngày thứ Tư"},{"en":"Wednesday morning","vi":"sáng thứ Tư"},{"en":"every Wednesday","vi":"mỗi thứ Tư"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Viết hoa chữ cái đầu; dùng on Wednesday, nhưng trước every Wednesday thì không dùng on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_a-m', 'en-a1-27', 'a.m.', '/ˌeɪ ˈem/', 'A1', 'sáng; trước trưa (tính từ nửa đêm đến trước buổi trưa)', 'adv.', NULL, 'Trái nghĩa: p.m.', 'Đặt sau số chỉ giờ; 12 a.m. là nửa đêm, 12 p.m. là buổi trưa.', 'My alarm rings at seven a.m. every weekday.', NULL, 'Chuông báo thức của tôi kêu vào lúc bảy giờ sáng mỗi ngày trong tuần.', '{"wordId":"a-m","ukIpa":"/ˌeɪ ˈem/","usIpa":"/ˌeɪ ˈem/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"During the time from midnight until just before midday.","vi":"sáng; trước trưa (tính từ nửa đêm đến trước buổi trưa)"}],"examples":[{"en":"My alarm rings at seven a.m. every weekday.","vi":"Chuông báo thức của tôi kêu vào lúc bảy giờ sáng mỗi ngày trong tuần.","audioKind":"ex"},{"en":"Starting school before eight a.m. may reduce the amount of sleep that teenagers get on weekdays.","vi":"Đi học trước tám giờ sáng có thể làm giảm thời gian ngủ của thanh thiếu niên trong các ngày trong tuần.","audioKind":"ex2"}],"collocations":[{"en":"at six a.m.","vi":"vào lúc sáu giờ sáng"},{"en":"from nine a.m.","vi":"từ chín giờ sáng"},{"en":"until eleven a.m.","vi":"cho đến mười một giờ sáng"}],"wordFamily":[],"synonyms":[],"antonyms":["p.m."],"tipVi":"Đặt sau số chỉ giờ; 12 a.m. là nửa đêm, 12 p.m. là buổi trưa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_new', 'en-a1-27', 'new', '/nuː/', 'A1', 'mới; mới tạo; mới xuất hiện; mới mua; mới tiếp nhận; chưa quen; bỡ ngỡ', 'adj.', 'newly (adv.), newness (n.), renew (v.), renewal (n.)', 'Đồng nghĩa: novel · Trái nghĩa: old', 'be new to chỉ sự bỡ ngỡ, chưa quen, trong đó to là giới từ.', 'Our new neighbours brought us a basket of apples.', NULL, 'Những người hàng xóm mới của chúng tôi đã mang đến cho chúng tôi một giỏ táo.', '{"wordId":"new","ukIpa":"/njuː/","usIpa":"/nuː/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Recently made, discovered, introduced, or begun.","vi":"mới; mới tạo; mới xuất hiện"},{"pos":"adj.","en":"Recently obtained or experienced by someone, though possibly already existing.","vi":"mới mua; mới tiếp nhận"},{"pos":"adj.","en":"Not yet familiar with a place, activity, or situation.","vi":"chưa quen; bỡ ngỡ"}],"examples":[{"en":"Our new neighbours brought us a basket of apples.","vi":"Những người hàng xóm mới của chúng tôi đã mang đến cho chúng tôi một giỏ táo.","audioKind":"ex"},{"en":"New technologies can make healthcare more accessible, but their benefits must be shared across different income groups.","vi":"Công nghệ mới có thể giúp việc tiếp cận dịch vụ y tế trở nên dễ dàng hơn, nhưng lợi ích của chúng cần được chia sẻ giữa các nhóm thu nhập khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"brand new","vi":"hoàn toàn mới"},{"en":"new technology","vi":"công nghệ mới"},{"en":"new to the job","vi":"mới làm quen với công việc"},{"en":"a new approach","vi":"một phương pháp mới"}],"wordFamily":["newly (adv.)","newness (n.)","renew (v.)","renewal (n.)"],"synonyms":["novel"],"antonyms":["old"],"tipVi":"be new to chỉ sự bỡ ngỡ, chưa quen, trong đó to là giới từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cooking', 'en-a1-27', 'cooking', '/ˈkʊkɪŋ/', 'A1', 'nấu nướng; việc nấu ăn; dùng để nấu ăn', 'n.', 'cook (v.), cook (n.), cooker (n.)', NULL, 'cooking chỉ hoạt động nấu nướng; cook có thể chỉ đầu bếp, còn cooker là thiết bị nấu ăn.', 'My brother does the cooking while I wash dishes.', NULL, 'Anh trai tôi nấu ăn trong khi tôi rửa bát.', '{"wordId":"cooking","ukIpa":"/ˈkʊkɪŋ/","usIpa":"/ˈkʊkɪŋ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The activity of preparing food by heating it.","vi":"nấu nướng; việc nấu ăn"},{"pos":"adj.","en":"Intended for use in preparing food.","vi":"dùng để nấu ăn"}],"examples":[{"en":"My brother does the cooking while I wash dishes.","vi":"Anh trai tôi nấu ăn trong khi tôi rửa bát.","audioKind":"ex"},{"en":"Teaching basic cooking skills at school can help young people develop healthier eating habits.","vi":"Dạy các kỹ năng nấu nướng cơ bản ở trường có thể giúp người trẻ tuổi xây dựng thói quen ăn uống lành mạnh hơn.","audioKind":"ex2"}],"collocations":[{"en":"do the cooking","vi":"nấu ăn; làm việc bếp núc"},{"en":"cooking skills","vi":"kỹ năng nấu nướng"},{"en":"cooking oil","vi":"dầu ăn"},{"en":"home cooking","vi":"đồ ăn nấu ở nhà"}],"wordFamily":["cook (v.)","cook (n.)","cooker (n.)"],"synonyms":[],"antonyms":[],"tipVi":"cooking chỉ hoạt động nấu nướng; cook có thể chỉ đầu bếp, còn cooker là thiết bị nấu ăn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_family', 'en-a1-27', 'family', '/ˈfæməli/', 'A1', 'gia đình; người thân; họ; loài; ngữ hệ', 'n.', NULL, NULL, 'family thường dùng ở số ít khi chỉ một tập thể; tiếng Anh - Anh có thể dùng số ít hoặc số nhiều tùy theo việc nhấn mạnh tính tập thể hay cá nhân.', 'My family gathers around the kitchen table every Sunday.', NULL, 'Gia đình tôi quây quần bên chiếc bàn trong bếp vào mỗi Chủ nhật.', '{"wordId":"family","ukIpa":"/ˈfæməli/","usIpa":"/ˈfæməli/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a group of people related to one another","vi":"gia đình; người thân"},{"pos":"n.","en":"a group of related animals, plants, languages, or other things","vi":"họ; loài; ngữ hệ"}],"examples":[{"en":"My family gathers around the kitchen table every Sunday.","vi":"Gia đình tôi quây quần bên chiếc bàn trong bếp vào mỗi Chủ nhật.","audioKind":"ex"},{"en":"Flexible working hours can help parents balance family responsibilities with the demands of paid employment.","vi":"Thời gian làm việc linh hoạt có thể giúp các bậc cha mẹ cân bằng giữa trách nhiệm gia đình và yêu cầu của công việc có trả lương.","audioKind":"ex2"}],"collocations":[{"en":"extended family","vi":"gia đình lớn (gồm nhiều thế hệ)"},{"en":"family member","vi":"thành viên trong gia đình"},{"en":"family responsibilities","vi":"trách nhiệm gia đình"},{"en":"language family","vi":"nhóm ngôn ngữ; ngữ hệ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"family thường dùng ở số ít khi chỉ một tập thể; tiếng Anh - Anh có thể dùng số ít hoặc số nhiều tùy theo việc nhấn mạnh tính tập thể hay cá nhân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_december', 'en-a1-27', 'December', '/dɪˈsembɚ/', 'A1', 'tháng mười hai', 'n.', NULL, NULL, 'Tên tháng phải viết hoa chữ cái đầu; dùng giới từ in trước tháng Mười Hai.', 'My cousin is coming to stay with us in December.', NULL, 'Anh họ tôi sẽ đến ở với chúng tôi vào tháng Mười Hai.', '{"wordId":"december","ukIpa":"/dɪˈsembə/","usIpa":"/dɪˈsembɚ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"the final month of the year, following November","vi":"tháng mười hai"}],"examples":[{"en":"My cousin is coming to stay with us in December.","vi":"Anh họ tôi sẽ đến ở với chúng tôi vào tháng Mười Hai.","audioKind":"ex"},{"en":"In many northern countries, energy demand increases in December as households need more heating during colder weather.","vi":"Ở nhiều quốc gia ôn đới phía bắc, nhu cầu năng lượng tăng lên vào tháng Mười Hai khi các hộ gia đình cần sưởi ấm nhiều hơn trong thời tiết lạnh giá.","audioKind":"ex2"}],"collocations":[{"en":"in December","vi":"vào tháng Mười Hai"},{"en":"early December","vi":"đầu tháng Mười Hai"},{"en":"late December","vi":"cuối tháng Mười Hai"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tên tháng phải viết hoa chữ cái đầu; dùng giới từ in trước tháng Mười Hai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_27_1', 'en-a1-27', 'Cách dùng “family” (n.) — gia đình; người thân', 'extended family  ·  family member  ·  family responsibilities', 'family thường dùng ở số ít khi chỉ một tập thể; tiếng Anh - Anh có thể dùng số ít hoặc số nhiều tùy theo việc nhấn mạnh tính tập thể hay cá nhân.', NULL, '[{"hanzi":"My family gathers around the kitchen table every Sunday.","pinyin":"","meaning":"Gia đình tôi quây quần bên chiếc bàn trong bếp vào mỗi Chủ nhật."},{"hanzi":"Flexible working hours can help parents balance family responsibilities with the demands of paid employment.","pinyin":"","meaning":"Thời gian làm việc linh hoạt có thể giúp các bậc cha mẹ cân bằng giữa trách nhiệm gia đình và yêu cầu của công việc có trả lương."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_27_2', 'en-a1-27', 'Cách dùng “green” (adj.) — có màu của cỏ và phần lớn lá cây', 'green vegetables  ·  green energy  ·  green spaces', 'Ngoài màu sắc, green thường mang nghĩa thân thiện với môi trường; khi chỉ con người, từ này còn có thể chỉ sự thiếu kinh nghiệm.', 'Họ từ (Word Family): greenish (adj.), greenness (n.), greenery (n.)', '[{"hanzi":"She wore a green jacket to match her shoes.","pinyin":"","meaning":"Cô ấy mặc một chiếc áo khoác màu xanh lá cây để phối cùng đôi giày của mình."},{"hanzi":"Governments can encourage green transport by improving public services and building safer routes for cyclists.","pinyin":"","meaning":"Chính phủ có thể khuyến khích giao thông xanh bằng cách cải thiện các dịch vụ công cộng và xây dựng những tuyến đường an toàn hơn cho người đi xe đạp."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_27_3', 'en-a1-27', 'Cách dùng “special” (adj.) — đặc biệt; khác thường', 'special occasion  ·  special offer  ·  special equipment', 'specially nhấn mạnh tính chuyên dụng; especially thường dùng để chỉ ý đặc biệt là / nhất là.', 'Họ từ (Word Family): specially (adv.), specialise (v.), specialist (n.) | Đồng nghĩa: particular, exceptional | Trái nghĩa: ordinary', '[{"hanzi":"We saved this special cake for your birthday.","pinyin":"","meaning":"Chúng tôi đã để dành chiếc bánh đặc biệt này cho ngày sinh nhật của bạn."},{"hanzi":"Schools should provide special equipment so that students with disabilities can participate fully in classroom activities.","pinyin":"","meaning":"Các trường học nên cung cấp các thiết bị chuyên dụng để học sinh khuyết tật có thể tham gia đầy đủ vào các hoạt động trên lớp."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_27_4', 'en-a1-27', 'Cách dùng “meat” (n.) — thịt; thịt động vật', 'raw meat  ·  lean meat  ·  red meat', 'Khi chỉ chung thịt để ăn thì không đếm được; dùng meats khi chỉ các loại thịt khác nhau.', 'Họ từ (Word Family): meaty (adj.), meatless (adj.)', '[{"hanzi":"We keep raw meat separate from vegetables in the fridge.","pinyin":"","meaning":"Chúng tôi để thịt sống tách riêng với rau củ trong tủ lạnh."},{"hanzi":"Reducing meat consumption may lower the environmental impact of food production in many countries.","pinyin":"","meaning":"Việc giảm tiêu thụ thịt có thể làm giảm tác động môi trường của việc sản xuất thực phẩm ở nhiều quốc gia."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_27_1', 'en-a1-27', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_27_1_1', 'ten_27_1', 'nine', 'We packed nine apples for our picnic today.', 'We packed nine apples for our picnic today.', '/naɪn/', 'Chúng tôi đã chuẩn bị chín quả táo cho buổi dã ngoại hôm nay.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_27_1_2', 'ten_27_1', 'twelve', 'There are twelve fresh eggs in this carton.', 'There are twelve fresh eggs in this carton.', '/twelv/', 'Có mười hai quả trứng tươi trong hộp này.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_27_1_3', 'ten_27_1', 'moment', 'Wait a moment while I put my shoes on.', 'Wait a moment while I put my shoes on.', '/ˈmoʊmənt/', 'Đợi một lát trong lúc tôi đi giày nhé.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_27_1_4', 'ten_27_1', 'want', 'I want to grow tomatoes on our balcony.', 'I want to grow tomatoes on our balcony.', '/wɑːnt/', 'Tôi muốn trồng cà chua ngoài ban công nhà mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_27_1_5', 'ten_27_1', 'another', 'This cup is cracked, so please bring me another.', 'This cup is cracked, so please bring me another.', '/əˈnʌðɚ/', 'Chiếc cốc này bị nứt rồi, làm ơn mang cho tôi cái khác nhé.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_27_1_6', 'ten_27_1', 'slowly', 'She slowly poured the hot soup into bowls.', 'She slowly poured the hot soup into bowls.', '/ˈsloʊli/', 'Cô ấy chậm rãi rót bát súp nóng ra các cái bát.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
