INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_27_1_8', 'ten_27_1', 'special', 'We saved this special cake for your birthday.', 'We saved this special cake for your birthday.', '/ˈspeʃəl/', 'Chúng tôi đã để dành chiếc bánh đặc biệt này cho ngày sinh nhật của bạn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_27_1_1', 'en-a1-27', 'ten_27_1', 'listening', 'listening', 'We packed nine apples for our picnic today.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tối qua tôi để quên kính ở cạnh giường.","Chúng tôi đã chuẩn bị chín quả táo cho buổi dã ngoại hôm nay.","Chiếc cốc này bị nứt rồi, làm ơn mang cho tôi cái khác nhé.","Đợi một lát trong lúc tôi đi giày nhé."]'::jsonb, 1, 'We packed nine apples for our picnic today. → Chúng tôi đã chuẩn bị chín quả táo cho buổi dã ngoại hôm nay.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_27_1_2', 'en-a1-27', 'ten_27_1', 'listening', 'listening', 'There are twelve fresh eggs in this carton.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chiếc cốc này bị nứt rồi, làm ơn mang cho tôi cái khác nhé.","Có mười hai quả trứng tươi trong hộp này.","Đợi một lát trong lúc tôi đi giày nhé.","Chúng tôi đã để dành chiếc bánh đặc biệt này cho ngày sinh nhật của bạn."]'::jsonb, 1, 'There are twelve fresh eggs in this carton. → Có mười hai quả trứng tươi trong hộp này.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_27_1_3', 'en-a1-27', 'ten_27_1', 'listening', 'listening', 'Wait a moment while I put my shoes on.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Đợi một lát trong lúc tôi đi giày nhé.","Chúng tôi đã để dành chiếc bánh đặc biệt này cho ngày sinh nhật của bạn.","Có mười hai quả trứng tươi trong hộp này.","Cô ấy chậm rãi rót bát súp nóng ra các cái bát."]'::jsonb, 0, 'Wait a moment while I put my shoes on. → Đợi một lát trong lúc tôi đi giày nhé.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
