INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_27_2_1', 'ten_27_2', 'nine', 'The survey found that nine local schools had introduced cycling lessons to encourage more sustainable travel.', 'The survey found that nine local schools had introduced cycling lessons to encourage more sustainable travel.', '/naɪn/', 'Khảo sát cho thấy chín trường học trong khu vực đã đưa các bài học đạp xe vào giảng dạy nhằm khuyến khích hình thức di chuyển bền vững hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_27_2_2', 'ten_27_2', 'twelve', 'The training programme lasts twelve weeks and combines practical experience with classroom instruction for young adults.', 'The training programme lasts twelve weeks and combines practical experience with classroom instruction for young adults.', '/twelv/', 'Chương trình đào tạo kéo dài mười hai tuần, kết hợp giữa kinh nghiệm thực tế và giảng dạy trên lớp dành cho thanh thiếu niên.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_27_2_3', 'ten_27_2', 'moment', 'The opening of the new railway marked a significant moment in the region''s economic development.', 'The opening of the new railway marked a significant moment in the region''s economic development.', '/ˈmoʊmənt/', 'Việc khai trương tuyến đường sắt mới đánh dấu một thời điểm quan trọng trong sự phát triển kinh tế của khu vực.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_27_2_4', 'ten_27_2', 'want', 'Many young adults want governments to invest more in affordable housing rather than expensive urban redevelopment projects.', 'Many young adults want governments to invest more in affordable housing rather than expensive urban redevelopment projects.', '/wɑːnt/', 'Nhiều người trẻ tuổi muốn chính phủ đầu tư nhiều hơn vào nhà ở giá rẻ thay vì các dự án tái phát triển đô thị tốn kém.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_27_2_5', 'ten_27_2', 'another', 'Another reason to invest in public transport is its potential to reduce urban air pollution.', 'Another reason to invest in public transport is its potential to reduce urban air pollution.', '/əˈnʌðɚ/', 'Một lý do khác để đầu tư vào giao thông công cộng là tiềm năng giảm thiểu ô nhiễm không khí đô thị của nó.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_27_2_6', 'ten_27_2', 'slowly', 'Although public attitudes are changing slowly, more consumers are choosing products with less plastic packaging.', 'Although public attitudes are changing slowly, more consumers are choosing products with less plastic packaging.', '/ˈsloʊli/', 'Mặc dù thái độ của công cộng đang thay đổi chậm rãi, nhưng ngày càng có nhiều người tiêu dùng chọn các sản phẩm ít bao bì nhựa hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
