INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_27_2', 'en-a1-27', NULL, 'comprehensive_test', 'listening', 'There are twelve fresh eggs in this carton.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Có mười hai quả trứng tươi trong hộp này.","Cô ấy buộc tóc gọn lại trước khi làm bữa trưa.","Con chó già của chúng tôi nằm ngủ cạnh chiếc lò sưởi ấm áp trong bếp.","Đợi một lát trong lúc tôi đi giày nhé."]'::jsonb, 0, 'There are twelve fresh eggs in this carton. → Có mười hai quả trứng tươi trong hộp này.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_27_3', 'en-a1-27', NULL, 'comprehensive_test', 'listening', 'moment', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khoảnh khắc; chốc lát","rất; lắm","ăn; dùng bữa","khi nào; lúc nào"]'::jsonb, 0, 'moment (/ˈmoʊmənt/) → khoảnh khắc; chốc lát; thời điểm; cơ hội', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_27_4', 'en-a1-27', NULL, 'comprehensive_test', 'listening', 'I want to grow tomatoes on our balcony.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Gia đình tôi quây quần bên chiếc bàn trong bếp vào mỗi Chủ nhật.","Tôi muốn trồng cà chua ngoài ban công nhà mình.","Tôi có thể thanh toán tiền những quả táo này bằng thẻ không?","Anh trai tôi nấu ăn trong khi tôi rửa bát."]'::jsonb, 1, 'I want to grow tomatoes on our balcony. → Tôi muốn trồng cà chua ngoài ban công nhà mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_27_5', 'en-a1-27', NULL, 'comprehensive_test', 'listening', 'another', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["một... nữa; khác","công ty; hãng","đường; đường ăn","chờ đợi; ngóng chờ"]'::jsonb, 0, 'another (/əˈnʌðɚ/) → một... nữa; khác; người khác; vật khác', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_27_6', 'en-a1-27', NULL, 'comprehensive_test', 'listening', 'She slowly poured the hot soup into bowls.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy chậm rãi rót bát súp nóng ra các cái bát.","Tôi muốn trồng cà chua ngoài ban công nhà mình.","Anh trai tôi nấu ăn trong khi tôi rửa bát.","Chúng tôi để thịt sống tách riêng với rau củ trong tủ lạnh."]'::jsonb, 0, 'She slowly poured the hot soup into bowls. → Cô ấy chậm rãi rót bát súp nóng ra các cái bát.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
