INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_27_8', 'en-a1-27', NULL, 'comprehensive_test', 'listening', 'We saved this special cake for your birthday.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã nướng mười sáu chiếc bánh nhỏ cho chuyến dã ngoại của gia đình.","Chúng tôi đã để dành chiếc bánh đặc biệt này cho ngày sinh nhật của bạn.","Cô ấy chậm rãi rót bát súp nóng ra các cái bát.","Chiếc cốc này bị nứt rồi, làm ơn mang cho tôi cái khác nhé."]'::jsonb, 1, 'We saved this special cake for your birthday. → Chúng tôi đã để dành chiếc bánh đặc biệt này cho ngày sinh nhật của bạn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
