INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_27_18', 'en-a1-27', NULL, 'comprehensive_test', 'reading', NULL, 'The survey found that nine local schools had introduced cycling lessons to encourage more sustainable travel.', 'Dựa vào câu trên, từ “nine” có nghĩa phù hợp nhất là gì?', '["chín","mười bảy","đi lại; du lịch","châu Á"]'::jsonb, 0, 'nine: chín. Dịch cả câu: Khảo sát cho thấy chín trường học trong khu vực đã đưa các bài học đạp xe vào giảng dạy nhằm khuyến khích hình thức di chuyển bền vững hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_27_19', 'en-a1-27', NULL, 'comprehensive_test', 'reading', NULL, 'The training programme lasts twelve weeks and combines practical experience with classroom instruction for young adults.', 'Dựa vào câu trên, từ “twelve” có nghĩa phù hợp nhất là gì?', '["mười hai","ở bên trong; vào bên trong","sách; quyển sách","thân yêu; quý giá; được trân trọng"]'::jsonb, 0, 'twelve: mười hai. Dịch cả câu: Chương trình đào tạo kéo dài mười hai tuần, kết hợp giữa kinh nghiệm thực tế và giảng dạy trên lớp dành cho thanh thiếu niên.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_27_20', 'en-a1-27', NULL, 'comprehensive_test', 'reading', NULL, 'The opening of the new railway marked a significant moment in the region''s economic development.', 'Dựa vào câu trên, từ “moment” có nghĩa phù hợp nhất là gì?', '["khoảnh khắc; chốc lát","rất; vô cùng","của bạn; của các bạn; của anh chị","sử dụng; dùng"]'::jsonb, 0, 'moment: khoảnh khắc; chốc lát; thời điểm; cơ hội. Dịch cả câu: Việc khai trương tuyến đường sắt mới đánh dấu một thời điểm quan trọng trong sự phát triển kinh tế của khu vực.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_27_21', 'en-a1-27', NULL, 'comprehensive_test', 'reading', NULL, 'Many young adults want governments to invest more in affordable housing rather than expensive urban redevelopment projects.', 'Dựa vào câu trên, từ “want” có nghĩa phù hợp nhất là gì?', '["muốn; ao ước","môn bơi lội; việc bơi","gặp gỡ; hội họp; làm quen","sáu mươi"]'::jsonb, 0, 'want: muốn; ao ước; sự thiếu thốn; cảnh nghèo túng. Dịch cả câu: Nhiều người trẻ tuổi muốn chính phủ đầu tư nhiều hơn vào nhà ở giá rẻ thay vì các dự án tái phát triển đô thị tốn kém.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_27_22', 'en-a1-27', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nấu nướng; việc nấu ăn”', '["thanks","cooking","snow","invite"]'::jsonb, 1, 'nấu nướng; việc nấu ăn → cooking (/ˈkʊkɪŋ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_27_23', 'en-a1-27', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “gia đình; người thân”', '["give","hobby","breakfast","family"]'::jsonb, 3, 'gia đình; người thân → family (/ˈfæməli/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_27_24', 'en-a1-27', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tháng mười hai”', '["wife","purple","December","look"]'::jsonb, 2, 'tháng mười hai → December (/dɪˈsembɚ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-28', 'en', 'Bài 28: Đời sống hằng ngày (13) - CEFR A1', 'CEFR A1', 'A1 · Đời sống', '27 từ vựng Tiếng Anh CEFR A1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1028, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_table', 'en-a1-28', 'table', '/ˈteɪbəl/', 'A1', 'cái bàn; bảng; biểu đồ', 'n.', 'tabletop (n.), tabular (adj.), tabulate (v.)', NULL, 'set the table có nghĩa là bày biện bàn ăn, không phải là dựng cái bàn lên.', 'We gathered around the table to share fresh bread.', NULL, 'Chúng tôi quây quần bên bàn để cùng thưởng thức bánh mì tươi.', '{"wordId":"table","ukIpa":"/ˈteɪbəl/","usIpa":"/ˈteɪbəl/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a piece of furniture with a flat top and legs","vi":"cái bàn"},{"pos":"n.","en":"information arranged in rows and columns","vi":"bảng; biểu đồ"}],"examples":[{"en":"We gathered around the table to share fresh bread.","vi":"Chúng tôi quây quần bên bàn để cùng thưởng thức bánh mì tươi.","audioKind":"ex"},{"en":"The table compares average household spending on transport in three cities over a ten-year period.","vi":"Bảng này so sánh mức chi tiêu trung bình của các hộ gia đình cho việc đi lại ở ba thành phố trong khoảng thời gian mười năm.","audioKind":"ex2"}],"collocations":[{"en":"dining table","vi":"bàn ăn"},{"en":"set the table","vi":"dọn bàn ăn"},{"en":"clear the table","vi":"dọn dẹp bàn ăn"},{"en":"a table of results","vi":"bảng kết quả"}],"wordFamily":["tabletop (n.)","tabular (adj.)","tabulate (v.)"],"synonyms":[],"antonyms":[],"tipVi":"set the table có nghĩa là bày biện bàn ăn, không phải là dựng cái bàn lên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_useful', 'en-a1-28', 'useful', '/ˈjuːsfəl/', 'A1', 'hữu ích; thiết thực', 'adj.', 'use (v.), usefully (adv.), usefulness (n.), useless (adj.)', 'Đồng nghĩa: helpful, practical · Trái nghĩa: useless', 'Phát âm bắt đầu bằng phụ âm /j/, vì vậy dùng a useful tool, không dùng an.', 'This little torch is useful when the power fails.', NULL, 'Chiếc đèn pin nhỏ này rất hữu ích khi mất điện.', '{"wordId":"useful","ukIpa":"/ˈjuːsfəl/","usIpa":"/ˈjuːsfəl/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Helping you do something or achieve a purpose","vi":"hữu ích; thiết thực"}],"examples":[{"en":"This little torch is useful when the power fails.","vi":"Chiếc đèn pin nhỏ này rất hữu ích khi mất điện.","audioKind":"ex"},{"en":"Reliable online resources can be useful for learners who lack access to well-equipped libraries.","vi":"Các nguồn tài nguyên trực tuyến đáng tin cậy có thể rất hữu ích cho những người học thiếu điều kiện tiếp cận các thư viện được trang bị đầy đủ.","audioKind":"ex2"}],"collocations":[{"en":"useful advice","vi":"lời khuyên hữu ích"},{"en":"useful information","vi":"thông tin hữu ích"},{"en":"useful for learning","vi":"hữu ích cho việc học"},{"en":"a useful tool","vi":"một công cụ hữu ích"}],"wordFamily":["use (v.)","usefully (adv.)","usefulness (n.)","useless (adj.)"],"synonyms":["helpful","practical"],"antonyms":["useless"],"tipVi":"Phát âm bắt đầu bằng phụ âm /j/, vì vậy dùng a useful tool, không dùng an.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_like', 'en-a1-28', 'like', '/laɪk/', 'A1', 'thích; yêu thích; giống; tương tự; chẳng hạn; ví dụ như', 'v.', 'dislike (v.), likeable (adj.), liking (n.)', 'Đồng nghĩa: enjoy · Trái nghĩa: dislike', 'would like to do lịch sự hơn want to do.', 'I like reading by the window on rainy afternoons.', NULL, 'Tôi thích đọc sách cạnh cửa sổ vào những buổi chiều mưa.', '{"wordId":"like","ukIpa":"/laɪk/","usIpa":"/laɪk/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to enjoy something or feel positively about someone","vi":"thích; yêu thích"},{"pos":"prep.","en":"similar to someone or something","vi":"giống; tương tự"},{"pos":"prep.","en":"used to introduce an example","vi":"chẳng hạn; ví dụ như"}],"examples":[{"en":"I like reading by the window on rainy afternoons.","vi":"Tôi thích đọc sách cạnh cửa sổ vào những buổi chiều mưa.","audioKind":"ex"},{"en":"Many residents like having green spaces nearby because they provide opportunities for exercise and relaxation.","vi":"Nhiều cư dân thích có không gian xanh gần nhà vì chúng tạo cơ hội tập thể dục và thư giãn.","audioKind":"ex2"}],"collocations":[{"en":"like doing something","vi":"thích làm gì đó"},{"en":"would like to","vi":"muốn"},{"en":"look like","vi":"trông giống như"},{"en":"feel like doing something","vi":"cảm thấy muốn làm gì đó"}],"wordFamily":["dislike (v.)","likeable (adj.)","liking (n.)"],"synonyms":["enjoy"],"antonyms":["dislike"],"tipVi":"would like to do lịch sự hơn want to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fall', 'en-a1-28', 'fall', '/fɔːl/', 'A1', 'rơi; ngã; giảm; sự rơi; sự giảm; mùa thu', 'v.', 'fallen (adj.), falling (adj.)', 'Đồng nghĩa: drop, decline · Trái nghĩa: rise', 'Quá khứ là fell, quá khứ phân từ là fallen; mùa thu tiếng Anh-Anh thường dùng autumn.', 'Golden leaves fall onto the path outside our house.', NULL, 'Những chiếc lá vàng rơi xuống lối đi bên ngoài ngôi nhà của chúng tôi.', '{"wordId":"fall","ukIpa":"/fɔːl/","usIpa":"/fɔːl/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To move downward, lose balance, or decrease.","vi":"rơi; ngã; giảm"},{"pos":"n.","en":"An act of falling or a decrease in amount.","vi":"sự rơi; sự giảm"},{"pos":"n.","en":"The season between summer and winter, especially in American English.","vi":"mùa thu"}],"examples":[{"en":"Golden leaves fall onto the path outside our house.","vi":"Những chiếc lá vàng rơi xuống lối đi bên ngoài ngôi nhà của chúng tôi.","audioKind":"ex"},{"en":"Energy consumption may fall if governments encourage households to install better insulation and efficient heating systems.","vi":"Mức tiêu thụ năng lượng có thể giảm nếu chính phủ khuyến khích các hộ gia đình lắp đặt lớp cách nhiệt tốt hơn và hệ thống sưởi hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"fall asleep","vi":"chìm vào giấc ngủ"},{"en":"fall in prices","vi":"giá giảm"},{"en":"fall sharply","vi":"giảm mạnh"},{"en":"in the fall","vi":"vào mùa thu"}],"wordFamily":["fallen (adj.)","falling (adj.)"],"synonyms":["drop","decline"],"antonyms":["rise"],"tipVi":"Quá khứ là fell, quá khứ phân từ là fallen; mùa thu tiếng Anh-Anh thường dùng autumn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thirty', 'en-a1-28', 'thirty', '/ˈθɝːti/', 'A1', 'ba mươi', 'num.', 'thirtieth (num.)', NULL, 'Từ thirty trọng âm ở âm tiết đầu; từ thirteen trọng âm thường ở âm tiết sau.', 'The soup needs another thirty minutes on the stove.', NULL, 'Món súp cần đun trên bếp thêm ba mươi phút nữa.', '{"wordId":"thirty","ukIpa":"/ˈθɜːti/","usIpa":"/ˈθɝːti/","cefr":"A1","topic":"daily","senses":[{"pos":"num.","en":"The number equal to three groups of ten.","vi":"ba mươi"}],"examples":[{"en":"The soup needs another thirty minutes on the stove.","vi":"Món súp cần đun trên bếp thêm ba mươi phút nữa.","audioKind":"ex"},{"en":"The survey found that thirty per cent of residents preferred cycling to driving for short journeys.","vi":"Cuộc khảo sát cho thấy ba mươi phần trăm cư dân thích đi xe đạp hơn lái xe cho những chuyến đi ngắn.","audioKind":"ex2"}],"collocations":[{"en":"thirty minutes","vi":"ba mươi phút"},{"en":"thirty per cent","vi":"ba mươi phần trăm"},{"en":"in your thirties","vi":"ở độ tuổi ba mươi"}],"wordFamily":["thirtieth (num.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ thirty trọng âm ở âm tiết đầu; từ thirteen trọng âm thường ở âm tiết sau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_best', 'en-a1-28', 'best', '/best/', 'A1', 'tốt nhất; tối ưu; tốt nhất; nhất; điều tốt nhất; thành tích tốt nhất', 'adj.', 'good (adj.), well (adv.), better (adj.)', 'Trái nghĩa: worst', 'best là dạng so sánh nhất của good và well; trước tính từ thường có mạo từ the.', 'This bakery makes the best bread in our neighbourhood.', NULL, 'Tiệm bánh này làm ra loại bánh mì ngon nhất trong khu phố của chúng tôi.', '{"wordId":"best","ukIpa":"/best/","usIpa":"/best/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Better than all others in quality or suitability.","vi":"tốt nhất; tối ưu"},{"pos":"adv.","en":"In the most successful way or to the greatest degree.","vi":"tốt nhất; nhất"},{"pos":"n.","en":"The finest performance, effort, or thing available.","vi":"điều tốt nhất; thành tích tốt nhất"}],"examples":[{"en":"This bakery makes the best bread in our neighbourhood.","vi":"Tiệm bánh này làm ra loại bánh mì ngon nhất trong khu phố của chúng tôi.","audioKind":"ex"},{"en":"Investing in early education may be the best way to reduce inequality over time.","vi":"Đầu tư vào giáo dục sớm có thể là cách tốt nhất để giảm bất bình đẳng theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"the best option","vi":"lựa chọn tốt nhất"},{"en":"do your best","vi":"làm hết sức mình"},{"en":"at its best","vi":"ở trạng thái tốt nhất"},{"en":"like something best","vi":"thích cái gì nhất"}],"wordFamily":["good (adj.)","well (adv.)","better (adj.)"],"synonyms":[],"antonyms":["worst"],"tipVi":"best là dạng so sánh nhất của good và well; trước tính từ thường có mạo từ the.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_any', 'en-a1-28', 'any', '/ˈeni/', 'A1', 'nào; bất kỳ (trong câu hỏi/phủ định); bất cứ... nào; bất kỳ ai; bất cứ thứ gì; chút nào; chút đỉnh', 'det.', NULL, NULL, 'Trong câu hỏi và phủ định thường mang nghĩa "một vài/nào đó"; trong câu khẳng định mang nghĩa "bất kỳ".', 'You can borrow any book from this shelf.', NULL, 'Bạn có thể mượn bất kỳ cuốn sách nào từ giá sách này.', '{"wordId":"any","ukIpa":"/ˈeni/","usIpa":"/ˈeni/","cefr":"A1","topic":"daily","senses":[{"pos":"det.","en":"Some in questions or negatives; whichever one, without restriction.","vi":"nào; bất kỳ (trong câu hỏi/phủ định); bất cứ... nào"},{"pos":"pron.","en":"Some or whichever ones, without naming the people or things.","vi":"bất kỳ ai; bất cứ thứ gì"},{"pos":"adv.","en":"At all, used mainly with comparisons in questions or negatives.","vi":"chút nào; chút đỉnh"}],"examples":[{"en":"You can borrow any book from this shelf.","vi":"Bạn có thể mượn bất kỳ cuốn sách nào từ giá sách này.","audioKind":"ex"},{"en":"Governments should ensure that all children can attend school without facing any financial barriers.","vi":"Chính phủ nên đảm bảo rằng tất cả trẻ em đều có thể đến trường mà không gặp phải bất kỳ rào cản tài chính nào.","audioKind":"ex2"}],"collocations":[{"en":"any questions","vi":"bất kỳ câu hỏi nào"},{"en":"at any time","vi":"bất cứ lúc nào"},{"en":"any of these","vi":"bất kỳ cái nào trong số này"},{"en":"hardly any","vi":"hầu như không"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong câu hỏi và phủ định thường mang nghĩa \"một vài/nào đó\"; trong câu khẳng định mang nghĩa \"bất kỳ\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shopping', 'en-a1-28', 'shopping', '/ˈʃɑːpɪŋ/', 'A1', 'việc mua sắm; đồ đạc đã mua', 'n.', 'shop (v.), shop (n.), shopper (n.)', NULL, 'shopping là danh từ không đếm được; cụm "đi mua sắm" dùng go shopping.', 'We usually do our shopping early on Saturday mornings.', NULL, 'Chúng tôi thường đi mua sắm vào sáng sớm thứ Bảy.', '{"wordId":"shopping","ukIpa":"/ˈʃɒpɪŋ/","usIpa":"/ˈʃɑːpɪŋ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The activity of looking for and buying things.","vi":"việc mua sắm"},{"pos":"n.","en":"The things you have bought during a shopping trip.","vi":"đồ đạc đã mua"}],"examples":[{"en":"We usually do our shopping early on Saturday mornings.","vi":"Chúng tôi thường đi mua sắm vào sáng sớm thứ Bảy.","audioKind":"ex"},{"en":"The growth of online shopping has changed consumer habits and increased demand for home delivery services.","vi":"Sự phát triển của mua sắm trực tuyến đã thay đổi thói quen của người tiêu dùng và làm tăng nhu cầu dịch vụ giao hàng tận nhà.","audioKind":"ex2"}],"collocations":[{"en":"go shopping","vi":"đi mua sắm"},{"en":"do the shopping","vi":"đi chợ mua nhu yếu phẩm"},{"en":"online shopping","vi":"mua sắm trực tuyến"},{"en":"shopping centre","vi":"trung tâm mua sắm"}],"wordFamily":["shop (v.)","shop (n.)","shopper (n.)"],"synonyms":[],"antonyms":[],"tipVi":"shopping là danh từ không đếm được; cụm \"đi mua sắm\" dùng go shopping.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_address', 'en-a1-28', 'address', '/ˈædres/', 'A1', 'địa chỉ; giải quyết; xử lý; đọc diễn văn; phát biểu', 'n.', 'addressee (n.)', NULL, 'Động từ trong tiếng Anh Mỹ đọc là /əˈdres/; address một vấn đề không đồng nghĩa với việc nó đã được giải quyết.', 'Please send me your address before I post the parcel.', NULL, 'Xin vui lòng gửi cho tôi địa chỉ của bạn trước khi tôi gửi bưu kiện.', '{"wordId":"address","ukIpa":"/əˈdres/","usIpa":"/ˈædres/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"Details identifying where someone lives or something can be found.","vi":"địa chỉ"},{"pos":"v.","en":"To give attention to a problem and try to solve it.","vi":"giải quyết; xử lý"},{"pos":"v.","en":"To speak directly to a person or group.","vi":"đọc diễn văn; phát biểu"}],"examples":[{"en":"Please send me your address before I post the parcel.","vi":"Xin vui lòng gửi cho tôi địa chỉ của bạn trước khi tôi gửi bưu kiện.","audioKind":"ex"},{"en":"Governments need to address housing shortages by supporting affordable construction and improving public transport links.","vi":"Chính phủ cần giải quyết tình trạng thiếu nhà ở bằng cách hỗ trợ xây dựng nhà ở giá rẻ và cải thiện kết nối giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"postal address","vi":"địa chỉ bưu điện"},{"en":"email address","vi":"địa chỉ email"},{"en":"address a problem","vi":"giải quyết một vấn đề"},{"en":"address an audience","vi":"phát biểu trước khán giả"}],"wordFamily":["addressee (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ trong tiếng Anh Mỹ đọc là /əˈdres/; address một vấn đề không đồng nghĩa với việc nó đã được giải quyết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_box', 'en-a1-28', 'box', '/bɑːks/', 'A1', 'hộp; thùng; đóng thùng; cho vào hộp; đánh quyền anh', 'n.', 'boxer (n.), boxing (n.), boxed (adj.)', NULL, 'Số nhiều là boxes; cụm a box of theo sau là các đồ vật bên trong hộp.', 'The kitten fell asleep inside an empty cardboard box.', NULL, 'Chú mèo con ngủ thiếp đi bên trong một chiếc hộp các tông trống.', '{"wordId":"box","ukIpa":"/bɒks/","usIpa":"/bɑːks/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a container with firm sides, often with a lid","vi":"hộp; thùng"},{"pos":"v.","en":"to put something into a box","vi":"đóng thùng; cho vào hộp"},{"pos":"v.","en":"to compete in a sport using punches and protective gloves","vi":"đánh quyền anh"}],"examples":[{"en":"The kitten fell asleep inside an empty cardboard box.","vi":"Chú mèo con ngủ thiếp đi bên trong một chiếc hộp các tông trống.","audioKind":"ex"},{"en":"Retailers can reduce packaging waste by choosing a box that closely matches the size of each product.","vi":"Các nhà bán lẻ có thể giảm thiểu rác thải đóng gói bằng cách chọn một chiếc hộp có kích thước phù hợp sát với từng sản phẩm.","audioKind":"ex2"}],"collocations":[{"en":"cardboard box","vi":"hộp các tông"},{"en":"a box of chocolates","vi":"một hộp sô-cô-la"},{"en":"box up","vi":"đóng gói vào hộp"}],"wordFamily":["boxer (n.)","boxing (n.)","boxed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Số nhiều là boxes; cụm a box of theo sau là các đồ vật bên trong hộp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fun', 'en-a1-28', 'fun', '/fʌn/', 'A1', 'niềm vui; sự thích thú; thú vị; vui vẻ', 'n.', NULL, 'Đồng nghĩa: enjoyment, amusement · Trái nghĩa: boredom', 'fun đóng vai trò là danh từ không đếm được; funny thường mang nghĩa buồn cười hoặc kỳ lạ.', 'We had so much fun building sandcastles together yesterday.', NULL, 'Hôm qua chúng tôi đã có rất nhiều niềm vui khi cùng nhau xây lâu đài cát.', '{"wordId":"fun","ukIpa":"/fʌn/","usIpa":"/fʌn/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"Enjoyment or pleasure from an activity or experience.","vi":"niềm vui; sự thích thú"},{"pos":"adj.","en":"Enjoyable and entertaining.","vi":"thú vị; vui vẻ"}],"examples":[{"en":"We had so much fun building sandcastles together yesterday.","vi":"Hôm qua chúng tôi đã có rất nhiều niềm vui khi cùng nhau xây lâu đài cát.","audioKind":"ex"},{"en":"Making physical activity fun can encourage children to exercise regularly and develop healthier habits throughout their lives.","vi":"Biến các hoạt động thể chất thành niềm vui có thể khuyến khích trẻ em tập luyện thường xuyên và xây dựng những thói quen lành mạnh hơn suốt đời.","audioKind":"ex2"}],"collocations":[{"en":"have fun","vi":"vui chơi; chơi đùa vui vẻ"},{"en":"for fun","vi":"cho vui; vì niềm vui"},{"en":"make fun of","vi":"trêu chọc; chế nhạo"},{"en":"good fun","vi":"rất vui; thú vị"}],"wordFamily":[],"synonyms":["enjoyment","amusement"],"antonyms":["boredom"],"tipVi":"fun đóng vai trò là danh từ không đếm được; funny thường mang nghĩa buồn cười hoặc kỳ lạ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_beard', 'en-a1-28', 'beard', '/bɪrd/', 'A1', 'râu quai nón; râu cằm', 'n.', 'bearded (adj.)', NULL, 'beard chỉ râu mọc ở cằm và hai bên má; moustache chỉ râu mọc ở mép trên.', 'He trimmed his beard before leaving for work.', NULL, 'Anh ấy đã tỉa tót bộ râu của mình trước khi đi làm.', '{"wordId":"beard","ukIpa":"/bɪəd/","usIpa":"/bɪrd/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"Hair growing on a person''s chin and cheeks.","vi":"râu quai nón; râu cằm"}],"examples":[{"en":"He trimmed his beard before leaving for work.","vi":"Anh ấy đã tỉa tót bộ râu của mình trước khi đi làm.","audioKind":"ex"},{"en":"In some workplaces, employees with beards must use special coverings to maintain food hygiene standards.","vi":"Tại một số môi trường làm việc, nhân viên để râu phải sử dụng mũ trùm chuyên dụng để duy trì các tiêu chuẩn vệ sinh an toàn thực phẩm.","audioKind":"ex2"}],"collocations":[{"en":"grow a beard","vi":"nuôi râu"},{"en":"trim a beard","vi":"tỉa râu"},{"en":"a thick beard","vi":"bộ râu rậm"}],"wordFamily":["bearded (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"beard chỉ râu mọc ở cằm và hai bên má; moustache chỉ râu mọc ở mép trên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wet', 'en-a1-28', 'wet', '/wet/', 'A1', 'ướt; ẩm ướt; mưa nhiều; ẩm ương; làm ướt', 'adj.', 'wetness (n.)', 'Đồng nghĩa: damp, soaked · Trái nghĩa: dry', 'damp chỉ mức độ hơi ẩm; soaking wet diễn tả trạng thái ướt sũng hoàn toàn.', 'My socks got wet when I stepped in a puddle.', NULL, 'Tất của tôi đã bị ướt khi tôi vô tình bước vào vũng nước.', '{"wordId":"wet","ukIpa":"/wet/","usIpa":"/wet/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Covered with or containing water or another liquid","vi":"ướt; ẩm ướt"},{"pos":"adj.","en":"Having rain or frequent rainfall","vi":"mưa nhiều; ẩm ương"},{"pos":"v.","en":"To put water or another liquid onto something","vi":"làm ướt"}],"examples":[{"en":"My socks got wet when I stepped in a puddle.","vi":"Tất của tôi đã bị ướt khi tôi vô tình bước vào vũng nước.","audioKind":"ex"},{"en":"Prolonged wet weather can damage crops and make it harder for farmers to harvest them efficiently.","vi":"Thời tiết mưa ẩm kéo dài có thể làm hư hại hoa màu và khiến nông dân khó thu hoạch hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"get wet","vi":"bị ướt"},{"en":"wet weather","vi":"thời tiết mưa ẩm"},{"en":"soaking wet","vi":"ướt sũng"},{"en":"wet the cloth","vi":"làm ướt tấm vải"}],"wordFamily":["wetness (n.)"],"synonyms":["damp","soaked"],"antonyms":["dry"],"tipVi":"damp chỉ mức độ hơi ẩm; soaking wet diễn tả trạng thái ướt sũng hoàn toàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_now', 'en-a1-28', 'now', '/naʊ/', 'A1', 'bây giờ; hiện tại; ngay lập tức; tức thì; vì rằng; từ khi mà', 'adv.', NULL, 'Đồng nghĩa: currently · Trái nghĩa: then', 'now that dùng để mở đầu mệnh đề chỉ nguyên nhân, nhấn mạnh tình hình thực tế đã thay đổi.', 'We live near the station now, so walking is easy.', NULL, 'Bây giờ chúng tôi sống gần ga tàu, nên việc đi bộ rất thuận tiện.', '{"wordId":"now","ukIpa":"/naʊ/","usIpa":"/naʊ/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"at the present time","vi":"bây giờ; hiện tại"},{"pos":"adv.","en":"immediately, without waiting","vi":"ngay lập tức; tức thì"},{"pos":"conj.","en":"because a situation has changed or become true","vi":"vì rằng; từ khi mà"}],"examples":[{"en":"We live near the station now, so walking is easy.","vi":"Bây giờ chúng tôi sống gần ga tàu, nên việc đi bộ rất thuận tiện.","audioKind":"ex"},{"en":"Now that online courses are widely available, more adults can continue their education while working.","vi":"Vì các khóa học trực tuyến đã trở nên phổ biến rộng rãi nên ngày càng có nhiều người trưởng thành có thể tiếp tục việc học trong khi vẫn đi làm.","audioKind":"ex2"}],"collocations":[{"en":"right now","vi":"ngay bây giờ; hiện tại"},{"en":"by now","vi":"cho đến nay"},{"en":"from now on","vi":"từ bây giờ trở đi"},{"en":"now that","vi":"vì rằng; một khi mà"}],"wordFamily":[],"synonyms":["currently"],"antonyms":["then"],"tipVi":"now that dùng để mở đầu mệnh đề chỉ nguyên nhân, nhấn mạnh tình hình thực tế đã thay đổi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_real', 'en-a1-28', 'real', '/ˈriːəl/', 'A1', 'thật; có thật; thực tế; chính hãng; không phải hàng giả; thực tế (đã trừ đi lạm phát)', 'adj.', 'reality (n.), really (adv.), realistic (adj.), unreal (adj.)', 'Đồng nghĩa: actual, genuine · Trái nghĩa: imaginary, fake', 'real đóng vai trò là tính từ bổ nghĩa cho danh từ; để diễn đạt ý "thực sự, rất" thường dùng trạng từ really.', 'I thought the bird was plastic, but it was real.', NULL, 'Tôi cứ nghĩ con chim đó làm bằng nhựa, hóa ra nó là thật.', '{"wordId":"real","ukIpa":"/rɪəl/","usIpa":"/ˈriːəl/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"existing in fact rather than being imagined","vi":"thật; có thật; thực tế"},{"pos":"adj.","en":"genuine rather than copied or artificial","vi":"chính hãng; không phải hàng giả"},{"pos":"adj.","en":"measured after allowing for changes in prices","vi":"thực tế (đã trừ đi lạm phát)"}],"examples":[{"en":"I thought the bird was plastic, but it was real.","vi":"Tôi cứ nghĩ con chim đó làm bằng nhựa, hóa ra nó là thật.","audioKind":"ex"},{"en":"Although average salaries have increased, rising prices mean that many workers have experienced a fall in real income.","vi":"Mặc dù mức lương trung bình đã tăng lên, nhưng vật giá leo thang đồng nghĩa với việc nhiều người lao động đang phải đối mặt với sự sụt giảm về thu nhập thực tế.","audioKind":"ex2"}],"collocations":[{"en":"real life","vi":"đời thực; cuộc sống thực tế"},{"en":"real leather","vi":"da thật"},{"en":"real income","vi":"thu nhập thực tế"},{"en":"real danger","vi":"mối nguy hiểm thực sự"}],"wordFamily":["reality (n.)","really (adv.)","realistic (adj.)","unreal (adj.)"],"synonyms":["actual","genuine"],"antonyms":["imaginary","fake"],"tipVi":"real đóng vai trò là tính từ bổ nghĩa cho danh từ; để diễn đạt ý \"thực sự, rất\" thường dùng trạng từ really.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_someone', 'en-a1-28', 'someone', '/ˈsʌmwʌn/', 'A1', 'ai đó; một người nào đó', 'pron.', NULL, 'Đồng nghĩa: somebody · Trái nghĩa: nobody, no one', 'Khi làm chủ ngữ, động từ theo sau chia số ít; vế sau có thể dùng they để chỉ đại từ.', 'Someone left a blue umbrella beside the front door.', NULL, 'Có ai đó để quên một chiếc ô màu xanh bên cạnh cửa trước.', '{"wordId":"someone","ukIpa":"/ˈsʌmwʌn/","usIpa":"/ˈsʌmwʌn/","cefr":"A1","topic":"daily","senses":[{"pos":"pron.","en":"a person whose identity is unknown or not stated","vi":"ai đó; một người nào đó"}],"examples":[{"en":"Someone left a blue umbrella beside the front door.","vi":"Có ai đó để quên một chiếc ô màu xanh bên cạnh cửa trước.","audioKind":"ex"},{"en":"Students may feel more confident seeking help when someone they trust is available to discuss their concerns.","vi":"Học sinh có thể cảm thấy tự tin hơn khi tìm kiếm sự giúp đỡ nếu có một người đáng tin cậy sẵn sàng lắng nghe những băn khoăn của các em.","audioKind":"ex2"}],"collocations":[{"en":"someone else","vi":"người khác"},{"en":"someone special","vi":"một người đặc biệt"},{"en":"someone to talk to","vi":"người để tâm sự"}],"wordFamily":[],"synonyms":["somebody"],"antonyms":["nobody","no one"],"tipVi":"Khi làm chủ ngữ, động từ theo sau chia số ít; vế sau có thể dùng they để chỉ đại từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hear', 'en-a1-28', 'hear', '/hɪr/', 'A1', 'nghe thấy; nghe; nghe nói; được biết; xét xử; lắng nghe', 'v.', 'hearing (n.), hearer (n.)', NULL, 'hear nhấn mạnh khả năng nghe thấy; listen to nhấn mạnh việc chủ động lắng nghe. Quá khứ là heard.', 'I can hear birds singing outside my bedroom window.', NULL, 'Tôi có thể nghe thấy tiếng chim hót ngoài cửa sổ phòng ngủ.', '{"wordId":"hear","ukIpa":"/hɪə/","usIpa":"/hɪr/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"notice a sound through your ears","vi":"nghe thấy; nghe"},{"pos":"v.","en":"receive information about something","vi":"nghe nói; được biết"},{"pos":"v.","en":"listen formally to evidence or arguments","vi":"xét xử; lắng nghe"}],"examples":[{"en":"I can hear birds singing outside my bedroom window.","vi":"Tôi có thể nghe thấy tiếng chim hót ngoài cửa sổ phòng ngủ.","audioKind":"ex"},{"en":"Local councils should hear residents'' concerns before making decisions about major changes to public transport.","vi":"Hội đồng địa phương nên lắng nghe những mối bận tâm của cư dân trước khi đưa ra quyết định về các thay đổi lớn đối với giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"hear from someone","vi":"nhận được tin từ ai"},{"en":"hear about something","vi":"nghe về điều gì"},{"en":"hear a case","vi":"xét xử một vụ án"},{"en":"hear both sides","vi":"lắng nghe từ cả hai phía"}],"wordFamily":["hearing (n.)","hearer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"hear nhấn mạnh khả năng nghe thấy; listen to nhấn mạnh việc chủ động lắng nghe. Quá khứ là heard.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_please', 'en-a1-28', 'please', '/pliːz/', 'A1', 'xin vui lòng; làm ơn; làm hài lòng; làm thỏa mãn', 'adv.', 'pleased (adj.), pleasing (adj.), pleasure (n.), pleasant (adj.)', NULL, 'please là động từ; cảm thấy hài lòng dùng be pleased.', 'Could you please hold the door for me?', NULL, 'Bạn có thể giữ giùm tôi cánh cửa được không?', '{"wordId":"please","ukIpa":"/pliːz/","usIpa":"/pliːz/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"Used to make a request or offer more polite.","vi":"xin vui lòng; làm ơn"},{"pos":"v.","en":"To make someone feel happy or satisfied.","vi":"làm hài lòng; làm thỏa mãn"}],"examples":[{"en":"Could you please hold the door for me?","vi":"Bạn có thể giữ giùm tôi cánh cửa được không?","audioKind":"ex"},{"en":"Public policies designed to please every group may fail to address the most urgent social problems.","vi":"Các chính sách công nhằm làm hài lòng mọi nhóm đối tượng có thể không giải quyết được các vấn đề xã hội cấp bách nhất.","audioKind":"ex2"}],"collocations":[{"en":"please do","vi":"xin cứ tự nhiên; xin mời"},{"en":"please everyone","vi":"làm hài lòng tất cả mọi người"},{"en":"hard to please","vi":"khó chiều; khó làm hài lòng"},{"en":"as you please","vi":"tùy bạn; theo ý bạn"}],"wordFamily":["pleased (adj.)","pleasing (adj.)","pleasure (n.)","pleasant (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"please là động từ; cảm thấy hài lòng dùng be pleased.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hard', 'en-a1-28', 'hard', '/hɑːrd/', 'A1', 'cứng; rắn; khó khăn; gian khổ; chăm chỉ; mạnh mẽ; dữ dội', 'adj.', 'harden (v.), hardness (n.), hardship (n.)', 'Trái nghĩa: soft, easy', 'hard có thể làm phó từ "nỗ lực, chăm chỉ"; hardly mang nghĩa là "hầu như không".', 'This bread is too hard to bite into.', NULL, 'Món bánh mì này quá cứng để cắn.', '{"wordId":"hard","ukIpa":"/hɑːd/","usIpa":"/hɑːrd/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Firm and not easily bent, cut, or pressed","vi":"cứng; rắn"},{"pos":"adj.","en":"Requiring considerable effort or being difficult to endure","vi":"khó khăn; gian khổ"},{"pos":"adv.","en":"With great effort, force, or intensity","vi":"chăm chỉ; mạnh mẽ; dữ dội"}],"examples":[{"en":"This bread is too hard to bite into.","vi":"Món bánh mì này quá cứng để cắn.","audioKind":"ex"},{"en":"Many students work hard to gain qualifications, yet still find it difficult to secure stable employment.","vi":"Nhiều học sinh nỗ lực học tập để lấy bằng cấp, nhưng vẫn thấy khó khăn để có được một công việc ổn định.","audioKind":"ex2"}],"collocations":[{"en":"hard work","vi":"công việc vất vả"},{"en":"work hard","vi":"làm việc chăm chỉ"},{"en":"hard evidence","vi":"chứng cứ xác thực"},{"en":"hard surface","vi":"bề mặt cứng"}],"wordFamily":["harden (v.)","hardness (n.)","hardship (n.)"],"synonyms":[],"antonyms":["soft","easy"],"tipVi":"hard có thể làm phó từ \"nỗ lực, chăm chỉ\"; hardly mang nghĩa là \"hầu như không\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_terrible', 'en-a1-28', 'terrible', '/ˈterəbl/', 'A1', 'tệ hại; khó chịu; khủng khiếp; nghiêm trọng', 'adj.', 'terribly (adv.)', 'Đồng nghĩa: awful, dreadful · Trái nghĩa: wonderful', 'terrible là tính từ; để diễn tả nghĩa "rất, cực kỳ" thường dùng terribly.', 'The soup tasted terrible, so I made a sandwich.', NULL, 'Món súp có vị rất tệ, nên tôi đã làm một chiếc bánh mì kẹp.', '{"wordId":"terrible","ukIpa":"/ˈterəbl/","usIpa":"/ˈterəbl/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Very bad or unpleasant.","vi":"tệ hại; khó chịu"},{"pos":"adj.","en":"Causing great fear, suffering, or harm.","vi":"khủng khiếp; nghiêm trọng"}],"examples":[{"en":"The soup tasted terrible, so I made a sandwich.","vi":"Món súp có vị rất tệ, nên tôi đã làm một chiếc bánh mì kẹp.","audioKind":"ex"},{"en":"Poor waste management can have terrible consequences for public health, especially in densely populated cities.","vi":"Việc quản lý rác thải kém có thể gây ra hậu quả nghiêm trọng đối với sức khỏe cộng đồng, đặc biệt là ở các thành phố đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"terrible weather","vi":"thời tiết xấu"},{"en":"a terrible mistake","vi":"một sai lầm nghiêm trọng"},{"en":"feel terrible","vi":"cảm thấy rất tệ"}],"wordFamily":["terribly (adv.)"],"synonyms":["awful","dreadful"],"antonyms":["wonderful"],"tipVi":"terrible là tính từ; để diễn tả nghĩa \"rất, cực kỳ\" thường dùng terribly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_toy', 'en-a1-28', 'toy', '/tɔɪ/', 'A1', 'đồ chơi; vọc; nghịch; cân nhắc qua loa', 'n.', NULL, NULL, 'Động từ thường đi với giới từ with; toy with an idea chỉ việc suy tính một cách không nghiêm túc.', 'The baby dropped her toy behind the sofa.', NULL, 'Em bé đánh rơi món đồ chơi của mình ra đằng sau ghế sô-pha.', '{"wordId":"toy","ukIpa":"/tɔɪ/","usIpa":"/tɔɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"An object that children use for play.","vi":"đồ chơi"},{"pos":"v.","en":"To handle casually or consider without serious commitment.","vi":"vọc; nghịch; cân nhắc qua loa"}],"examples":[{"en":"The baby dropped her toy behind the sofa.","vi":"Em bé đánh rơi món đồ chơi của mình ra đằng sau ghế sô-pha.","audioKind":"ex"},{"en":"Well-designed toys can encourage young children to develop practical skills through creative play and exploration.","vi":"Những món đồ chơi được thiết kế tốt có thể khuyến khích trẻ nhỏ phát triển các kỹ năng thực tế thông qua các trò chơi sáng tạo và sự khám phá.","audioKind":"ex2"}],"collocations":[{"en":"soft toy","vi":"đồ chơi nhồi bông"},{"en":"toy car","vi":"xe hơi đồ chơi"},{"en":"toy with an idea","vi":"hững hờ cân nhắc một ý tưởng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Động từ thường đi với giới từ with; toy with an idea chỉ việc suy tính một cách không nghiêm túc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_so', 'en-a1-28', 'so', '/soʊ/', 'A1', 'vậy; đến mức độ này; quá; cho nên; vì thế; do đó; như thế; như vậy', 'adv.', NULL, NULL, 'so dùng để bổ nghĩa cho tính từ hoặc phó từ; such thường đứng trước cụm danh từ.', 'The soup was so hot that I had to wait.', NULL, 'Món súp nóng quá khiến tôi phải đợi một lúc.', '{"wordId":"so","ukIpa":"/səʊ/","usIpa":"/soʊ/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"to such a degree or extent","vi":"vậy; đến mức độ này; quá"},{"pos":"conj.","en":"used to introduce a result or consequence","vi":"cho nên; vì thế; do đó"},{"pos":"adv.","en":"used instead of repeating an idea already mentioned","vi":"như thế; như vậy"}],"examples":[{"en":"The soup was so hot that I had to wait.","vi":"Món súp nóng quá khiến tôi phải đợi một lúc.","audioKind":"ex"},{"en":"Public transport is limited in rural areas, so many residents rely on private cars for essential journeys.","vi":"Giao thông công cộng ở các vùng nông thôn còn hạn chế, vì vậy nhiều cư dân phải phụ thuộc vào ô tô cá nhân cho các chuyến đi lại thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"so much","vi":"rất nhiều; bấy nhiêu"},{"en":"so far","vi":"cho đến nay"},{"en":"so that","vi":"để mà; do đó"},{"en":"think so","vi":"nghĩ là như vậy"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"so dùng để bổ nghĩa cho tính từ hoặc phó từ; such thường đứng trước cụm danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_single', 'en-a1-28', 'single', '/ˈsɪŋɡəl/', 'A1', 'đơn; duy nhất; một; độc thân; chưa kết hôn; một chiều', 'adj.', 'singly (adv.), singleness (n.)', 'Đồng nghĩa: sole, unmarried · Trái nghĩa: multiple, married', 'Vé một chiều tiếng Anh-Anh thường dùng single ticket, trong khi tiếng Anh-Mỹ dùng one-way ticket.', 'A single candle lit the room during the power cut.', NULL, 'Một ngọn nến duy nhất thắp sáng căn phòng trong lúc mất điện.', '{"wordId":"single","ukIpa":"/ˈsɪŋɡəl/","usIpa":"/ˈsɪŋɡəl/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Only one, rather than several or many.","vi":"đơn; duy nhất; một"},{"pos":"adj.","en":"Not married or not in a romantic relationship.","vi":"độc thân; chưa kết hôn"},{"pos":"adj.","en":"For travel to a destination without a return journey.","vi":"một chiều"}],"examples":[{"en":"A single candle lit the room during the power cut.","vi":"Một ngọn nến duy nhất thắp sáng căn phòng trong lúc mất điện.","audioKind":"ex"},{"en":"No single policy can solve urban congestion without improvements to public transport and local planning.","vi":"Không một chính sách đơn lẻ nào có thể giải quyết được tình trạng ùn tắc đô thị nếu không cải thiện giao thông công cộng và quy hoạch địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a single person","vi":"một người đơn lẻ; người độc thân"},{"en":"every single day","vi":"mỗi một ngày"},{"en":"a single ticket","vi":"vé một chiều"},{"en":"a single parent","vi":"cha hoặc mẹ đơn thân"}],"wordFamily":["singly (adv.)","singleness (n.)"],"synonyms":["sole","unmarried"],"antonyms":["multiple","married"],"tipVi":"Vé một chiều tiếng Anh-Anh thường dùng single ticket, trong khi tiếng Anh-Mỹ dùng one-way ticket.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_boy', 'en-a1-28', 'boy', '/bɔɪ/', 'A1', 'cậu bé; con trai', 'n.', 'boyhood (n.), boyish (adj.)', 'Đồng nghĩa: lad · Trái nghĩa: girl', 'Thường dùng để chỉ nam giới chưa thành niên; việc gọi nam giới trưởng thành là boy có thể gây mất lịch sự.', 'The boy carefully carried his puppy across the puddle.', NULL, 'Cậu bé cẩn thận ôm chú chó con bước qua vũng nước.', '{"wordId":"boy","ukIpa":"/bɔɪ/","usIpa":"/bɔɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a male child or young male person","vi":"cậu bé; con trai"}],"examples":[{"en":"The boy carefully carried his puppy across the puddle.","vi":"Cậu bé cẩn thận ôm chú chó con bước qua vũng nước.","audioKind":"ex"},{"en":"Every boy and girl should have equal access to education, regardless of their family''s income.","vi":"Mọi trẻ em nam và nữ đều nên có cơ hội tiếp cận giáo dục bình đẳng, bất kể thu nhập của gia đình.","audioKind":"ex2"}],"collocations":[{"en":"a little boy","vi":"một cậu bé nhỏ tuổi"},{"en":"a teenage boy","vi":"một thiếu niên"},{"en":"a baby boy","vi":"một bé trai sơ sinh"}],"wordFamily":["boyhood (n.)","boyish (adj.)"],"synonyms":["lad"],"antonyms":["girl"],"tipVi":"Thường dùng để chỉ nam giới chưa thành niên; việc gọi nam giới trưởng thành là boy có thể gây mất lịch sự.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chicken', 'en-a1-28', 'chicken', '/ˈtʃɪkɪn/', 'A1', 'con gà; thịt gà', 'n.', NULL, NULL, 'Chỉ gà sống là danh từ đếm được, chỉ thịt gà là danh từ không đếm được; gà con thường dùng chick.', 'The chickens scratched the soil beside our vegetable patch.', NULL, 'Những con gà đang bới đất ở bên cạnh mảnh vườn trồng rau của chúng tôi.', '{"wordId":"chicken","ukIpa":"/ˈtʃɪkɪn/","usIpa":"/ˈtʃɪkɪn/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A bird kept for its eggs or meat.","vi":"con gà"},{"pos":"n.","en":"Meat from a chicken, eaten as food.","vi":"thịt gà"}],"examples":[{"en":"The chickens scratched the soil beside our vegetable patch.","vi":"Những con gà đang bới đất ở bên cạnh mảnh vườn trồng rau của chúng tôi.","audioKind":"ex"},{"en":"Replacing some red meat with chicken can reduce the environmental impact of a person''s diet.","vi":"Việc thay thế một phần thịt đỏ bằng thịt gà có thể làm giảm tác động môi trường từ chế độ ăn uống của một người.","audioKind":"ex2"}],"collocations":[{"en":"keep chickens","vi":"nuôi gà"},{"en":"roast chicken","vi":"gà quay"},{"en":"chicken breast","vi":"ức gà"},{"en":"chicken soup","vi":"súp gà"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ gà sống là danh từ đếm được, chỉ thịt gà là danh từ không đếm được; gà con thường dùng chick.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_milk', 'en-a1-28', 'milk', '/mɪlk/', 'A1', 'sữa; vắt sữa', 'n.', 'milky (adj.)', NULL, 'milk thường không đếm được; nói a glass of milk, không nói a milk.', 'I poured some cold milk over my cereal.', NULL, 'Tôi đổ thêm ít sữa lạnh vào bát ngũ cốc của mình.', '{"wordId":"milk","ukIpa":"/mɪlk/","usIpa":"/mɪlk/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A white liquid female mammals produce to feed their young.","vi":"sữa"},{"pos":"v.","en":"Take milk from an animal, especially a cow.","vi":"vắt sữa"}],"examples":[{"en":"I poured some cold milk over my cereal.","vi":"Tôi đổ thêm ít sữa lạnh vào bát ngũ cốc của mình.","audioKind":"ex"},{"en":"Milk provides calcium and protein, although people with certain dietary needs may choose suitable alternatives.","vi":"Sữa cung cấp canxi và protein, mặc dù những người có nhu cầu ăn uống đặc biệt có thể chọn các loại thực phẩm thay thế phù hợp.","audioKind":"ex2"}],"collocations":[{"en":"a glass of milk","vi":"một cốc sữa"},{"en":"skimmed milk","vi":"sữa tách béo"},{"en":"milk a cow","vi":"vắt sữa bò"}],"wordFamily":["milky (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"milk thường không đếm được; nói a glass of milk, không nói a milk.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_and', 'en-a1-28', 'and', '/ænd/', 'A1', 'và; cùng với; rồi; sau đó', 'conj.', NULL, NULL, 'Kết nối các thành phần song song cần chú ý tính thống nhất về cấu trúc; trong văn nói thường đọc lướt thành /ən/.', 'I bought fresh bread and cheese for our picnic.', NULL, 'Tôi đã mua bánh mì tươi và phô mai cho chuyến dã ngoại của chúng ta.', '{"wordId":"and","ukIpa":"/ænd/","usIpa":"/ænd/","cefr":"A1","topic":"daily","senses":[{"pos":"conj.","en":"Connects words or statements that belong together.","vi":"và; cùng với"},{"pos":"conj.","en":"Connects an action with what follows or results from it.","vi":"rồi; sau đó"}],"examples":[{"en":"I bought fresh bread and cheese for our picnic.","vi":"Tôi đã mua bánh mì tươi và phô mai cho chuyến dã ngoại của chúng ta.","audioKind":"ex"},{"en":"Governments should invest in public transport and encourage cycling to reduce congestion in growing cities.","vi":"Chính phủ nên đầu tư vào giao thông công cộng và khuyến khích đạp xe để giảm thiểu tình trạng ùn tắc ở các thành phố đang phát triển.","audioKind":"ex2"}],"collocations":[{"en":"both ... and ...","vi":"cả... lẫn..."},{"en":"and so on","vi":"vân vân"},{"en":"more and more","vi":"ngày càng nhiều"},{"en":"again and again","vi":"hết lần này đến lần khác"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Kết nối các thành phần song song cần chú ý tính thống nhất về cấu trúc; trong văn nói thường đọc lướt thành /ən/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_28_1', 'en-a1-28', 'Cách dùng “and” (conj.) — và; cùng với', 'both ... and ...  ·  and so on  ·  more and more', 'Kết nối các thành phần song song cần chú ý tính thống nhất về cấu trúc; trong văn nói thường đọc lướt thành /ən/.', NULL, '[{"hanzi":"I bought fresh bread and cheese for our picnic.","pinyin":"","meaning":"Tôi đã mua bánh mì tươi và phô mai cho chuyến dã ngoại của chúng ta."},{"hanzi":"Governments should invest in public transport and encourage cycling to reduce congestion in growing cities.","pinyin":"","meaning":"Chính phủ nên đầu tư vào giao thông công cộng và khuyến khích đạp xe để giảm thiểu tình trạng ùn tắc ở các thành phố đang phát triển."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_28_2', 'en-a1-28', 'Cách dùng “address” (n.) — địa chỉ', 'postal address  ·  email address  ·  address a problem', 'Động từ trong tiếng Anh Mỹ đọc là /əˈdres/; address một vấn đề không đồng nghĩa với việc nó đã được giải quyết.', 'Họ từ (Word Family): addressee (n.)', '[{"hanzi":"Please send me your address before I post the parcel.","pinyin":"","meaning":"Xin vui lòng gửi cho tôi địa chỉ của bạn trước khi tôi gửi bưu kiện."},{"hanzi":"Governments need to address housing shortages by supporting affordable construction and improving public transport links.","pinyin":"","meaning":"Chính phủ cần giải quyết tình trạng thiếu nhà ở bằng cách hỗ trợ xây dựng nhà ở giá rẻ và cải thiện kết nối giao thông công cộng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_28_3', 'en-a1-28', 'Cách dùng “real” (adj.) — thật; có thật; thực tế', 'real life  ·  real leather  ·  real income', 'real đóng vai trò là tính từ bổ nghĩa cho danh từ; để diễn đạt ý "thực sự, rất" thường dùng trạng từ really.', 'Họ từ (Word Family): reality (n.), really (adv.), realistic (adj.), unreal (adj.) | Đồng nghĩa: actual, genuine | Trái nghĩa: imaginary, fake', '[{"hanzi":"I thought the bird was plastic, but it was real.","pinyin":"","meaning":"Tôi cứ nghĩ con chim đó làm bằng nhựa, hóa ra nó là thật."},{"hanzi":"Although average salaries have increased, rising prices mean that many workers have experienced a fall in real income.","pinyin":"","meaning":"Mặc dù mức lương trung bình đã tăng lên, nhưng vật giá leo thang đồng nghĩa với việc nhiều người lao động đang phải đối mặt với sự sụt giảm về thu nhập thực tế."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_28_4', 'en-a1-28', 'Cách dùng “boy” (n.) — cậu bé; con trai', 'a little boy  ·  a teenage boy  ·  a baby boy', 'Thường dùng để chỉ nam giới chưa thành niên; việc gọi nam giới trưởng thành là boy có thể gây mất lịch sự.', 'Họ từ (Word Family): boyhood (n.), boyish (adj.) | Đồng nghĩa: lad | Trái nghĩa: girl', '[{"hanzi":"The boy carefully carried his puppy across the puddle.","pinyin":"","meaning":"Cậu bé cẩn thận ôm chú chó con bước qua vũng nước."},{"hanzi":"Every boy and girl should have equal access to education, regardless of their family''s income.","pinyin":"","meaning":"Mọi trẻ em nam và nữ đều nên có cơ hội tiếp cận giáo dục bình đẳng, bất kể thu nhập của gia đình."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
