INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_28_1_1', 'en-a1-28', 'ten_28_1', 'listening', 'listening', 'We gathered around the table to share fresh bread.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi thích đọc sách cạnh cửa sổ vào những buổi chiều mưa.","Món súp cần đun trên bếp thêm ba mươi phút nữa.","Những chiếc lá vàng rơi xuống lối đi bên ngoài ngôi nhà của chúng tôi.","Chúng tôi quây quần bên bàn để cùng thưởng thức bánh mì tươi."]'::jsonb, 3, 'We gathered around the table to share fresh bread. → Chúng tôi quây quần bên bàn để cùng thưởng thức bánh mì tươi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_28_1_2', 'en-a1-28', 'ten_28_1', 'listening', 'listening', 'This little torch is useful when the power fails.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tiệm bánh này làm ra loại bánh mì ngon nhất trong khu phố của chúng tôi.","Tôi thích đọc sách cạnh cửa sổ vào những buổi chiều mưa.","Chiếc đèn pin nhỏ này rất hữu ích khi mất điện.","Chúng tôi quây quần bên bàn để cùng thưởng thức bánh mì tươi."]'::jsonb, 2, 'This little torch is useful when the power fails. → Chiếc đèn pin nhỏ này rất hữu ích khi mất điện.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_28_1_3', 'en-a1-28', 'ten_28_1', 'listening', 'listening', 'I like reading by the window on rainy afternoons.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi quây quần bên bàn để cùng thưởng thức bánh mì tươi.","Bạn có thể mượn bất kỳ cuốn sách nào từ giá sách này.","Chúng tôi thường đi mua sắm vào sáng sớm thứ Bảy.","Tôi thích đọc sách cạnh cửa sổ vào những buổi chiều mưa."]'::jsonb, 3, 'I like reading by the window on rainy afternoons. → Tôi thích đọc sách cạnh cửa sổ vào những buổi chiều mưa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_28_2', 'en-a1-28', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_28_2_1', 'ten_28_2', 'table', 'The table compares average household spending on transport in three cities over a ten-year period.', 'The table compares average household spending on transport in three cities over a ten-year period.', '/ˈteɪbəl/', 'Bảng này so sánh mức chi tiêu trung bình của các hộ gia đình cho việc đi lại ở ba thành phố trong khoảng thời gian mười năm.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_28_2_2', 'ten_28_2', 'useful', 'Reliable online resources can be useful for learners who lack access to well-equipped libraries.', 'Reliable online resources can be useful for learners who lack access to well-equipped libraries.', '/ˈjuːsfəl/', 'Các nguồn tài nguyên trực tuyến đáng tin cậy có thể rất hữu ích cho những người học thiếu điều kiện tiếp cận các thư viện được trang bị đầy đủ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_28_2_3', 'ten_28_2', 'like', 'Many residents like having green spaces nearby because they provide opportunities for exercise and relaxation.', 'Many residents like having green spaces nearby because they provide opportunities for exercise and relaxation.', '/laɪk/', 'Nhiều cư dân thích có không gian xanh gần nhà vì chúng tạo cơ hội tập thể dục và thư giãn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_28_2_4', 'ten_28_2', 'fall', 'Energy consumption may fall if governments encourage households to install better insulation and efficient heating systems.', 'Energy consumption may fall if governments encourage households to install better insulation and efficient heating systems.', '/fɔːl/', 'Mức tiêu thụ năng lượng có thể giảm nếu chính phủ khuyến khích các hộ gia đình lắp đặt lớp cách nhiệt tốt hơn và hệ thống sưởi hiệu quả.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_28_2_5', 'ten_28_2', 'thirty', 'The survey found that thirty per cent of residents preferred cycling to driving for short journeys.', 'The survey found that thirty per cent of residents preferred cycling to driving for short journeys.', '/ˈθɝːti/', 'Cuộc khảo sát cho thấy ba mươi phần trăm cư dân thích đi xe đạp hơn lái xe cho những chuyến đi ngắn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_28_2_6', 'ten_28_2', 'best', 'Investing in early education may be the best way to reduce inequality over time.', 'Investing in early education may be the best way to reduce inequality over time.', '/best/', 'Đầu tư vào giáo dục sớm có thể là cách tốt nhất để giảm bất bình đẳng theo thời gian.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_28_2_1', 'en-a1-28', 'ten_28_2', 'listening', 'listening', 'The table compares average household spending on transport in three cities over a ten-year period.', NULL, 'Trong câu vừa nghe, từ “table” mang nghĩa nào sau đây?', '["răng","cái bàn","ở tầng dưới; xuống tầng dưới","cảm thấy; thấy"]'::jsonb, 1, '“table” (/ˈteɪbəl/): cái bàn. Câu đầy đủ: The table compares average household spending on transport in three cities over a ten-year period.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
