INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_28_2', 'en-a1-28', NULL, 'comprehensive_test', 'listening', 'This little torch is useful when the power fails.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc đèn pin nhỏ này rất hữu ích khi mất điện.","Một ngọn nến duy nhất thắp sáng căn phòng trong lúc mất điện.","Tất của tôi đã bị ướt khi tôi vô tình bước vào vũng nước.","Món súp nóng quá khiến tôi phải đợi một lúc."]'::jsonb, 0, 'This little torch is useful when the power fails. → Chiếc đèn pin nhỏ này rất hữu ích khi mất điện.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
