INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_28_4', 'en-a1-28', NULL, 'comprehensive_test', 'listening', 'Golden leaves fall onto the path outside our house.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Món bánh mì này quá cứng để cắn.","Xin vui lòng gửi cho tôi địa chỉ của bạn trước khi tôi gửi bưu kiện.","Chúng tôi quây quần bên bàn để cùng thưởng thức bánh mì tươi.","Những chiếc lá vàng rơi xuống lối đi bên ngoài ngôi nhà của chúng tôi."]'::jsonb, 3, 'Golden leaves fall onto the path outside our house. → Những chiếc lá vàng rơi xuống lối đi bên ngoài ngôi nhà của chúng tôi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
