INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_28_18', 'en-a1-28', NULL, 'comprehensive_test', 'reading', NULL, 'The table compares average household spending on transport in three cities over a ten-year period.', 'Dựa vào câu trên, từ “table” có nghĩa phù hợp nhất là gì?', '["thường xuyên; thông thường","mùa hè; mùa hạ","cái bàn","đường; đường ăn"]'::jsonb, 2, 'table: cái bàn; bảng; biểu đồ. Dịch cả câu: Bảng này so sánh mức chi tiêu trung bình của các hộ gia đình cho việc đi lại ở ba thành phố trong khoảng thời gian mười năm.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_28_19', 'en-a1-28', NULL, 'comprehensive_test', 'reading', NULL, 'Reliable online resources can be useful for learners who lack access to well-equipped libraries.', 'Dựa vào câu trên, từ “useful” có nghĩa phù hợp nhất là gì?', '["kem đánh răng","tuổi; độ tuổi","châu Á","hữu ích; thiết thực"]'::jsonb, 3, 'useful: hữu ích; thiết thực. Dịch cả câu: Các nguồn tài nguyên trực tuyến đáng tin cậy có thể rất hữu ích cho những người học thiếu điều kiện tiếp cận các thư viện được trang bị đầy đủ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_28_20', 'en-a1-28', NULL, 'comprehensive_test', 'reading', NULL, 'Many residents like having green spaces nearby because they provide opportunities for exercise and relaxation.', 'Dựa vào câu trên, từ “like” có nghĩa phù hợp nhất là gì?', '["thích; yêu thích","phòng ăn; phòng ăn uống","giúp đỡ; hỗ trợ","ở khoảng cách xa; xa xôi"]'::jsonb, 0, 'like: thích; yêu thích; giống; tương tự; chẳng hạn; ví dụ như. Dịch cả câu: Nhiều cư dân thích có không gian xanh gần nhà vì chúng tạo cơ hội tập thể dục và thư giãn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_28_21', 'en-a1-28', NULL, 'comprehensive_test', 'reading', NULL, 'Energy consumption may fall if governments encourage households to install better insulation and efficient heating systems.', 'Dựa vào câu trên, từ “fall” có nghĩa phù hợp nhất là gì?', '["xe đạp","không có gì; không điều gì","tốt nhất; tối ưu","rơi; ngã; giảm"]'::jsonb, 3, 'fall: rơi; ngã; giảm; sự rơi; sự giảm; mùa thu. Dịch cả câu: Mức tiêu thụ năng lượng có thể giảm nếu chính phủ khuyến khích các hộ gia đình lắp đặt lớp cách nhiệt tốt hơn và hệ thống sưởi hiệu quả.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
