INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-29', 'en', 'Bài 29: Đời sống hằng ngày (14) - CEFR A1', 'CEFR A1', 'A1 · Đời sống', '27 từ vựng Tiếng Anh CEFR A1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1029, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_most', 'en-a1-29', 'most', '/moʊst/', 'A1', 'hầu hết; phần lớn; hầu hết; phần lớn nhất; nhất; cực kỳ', 'det.', 'more (adv.)', 'Trái nghĩa: least', 'Chỉ chung dùng most people; chỉ cụ thể dùng most of the people.', 'Most shops here close before we finish work.', NULL, 'Hầu hết các cửa hàng ở đây đều đóng cửa trước khi chúng tôi tan làm.', '{"wordId":"most","ukIpa":"/məʊst/","usIpa":"/moʊst/","cefr":"A1","topic":"daily","senses":[{"pos":"det.","en":"the majority of something, or the greatest amount or number","vi":"hầu hết; phần lớn"},{"pos":"pron.","en":"the majority or greatest part of a group or amount","vi":"hầu hết; phần lớn nhất"},{"pos":"adv.","en":"to the greatest degree; sometimes used to mean very","vi":"nhất; cực kỳ"}],"examples":[{"en":"Most shops here close before we finish work.","vi":"Hầu hết các cửa hàng ở đây đều đóng cửa trước khi chúng tôi tan làm.","audioKind":"ex"},{"en":"Most urban residents would benefit from reliable public transport that connects residential areas with major employment centres.","vi":"Đa số cư dân đô thị sẽ được hưởng lợi từ hệ thống giao thông công cộng đáng tin cậy kết nối các khu dân cư với các trung tâm việc làm lớn.","audioKind":"ex2"}],"collocations":[{"en":"most people","vi":"hầu hết mọi người"},{"en":"most of the time","vi":"phần lớn thời gian"},{"en":"at most","vi":"nhiều nhất"},{"en":"the most important","vi":"quan trọng nhất"}],"wordFamily":["more (adv.)"],"synonyms":[],"antonyms":["least"],"tipVi":"Chỉ chung dùng most people; chỉ cụ thể dùng most of the people.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_other', 'en-a1-29', 'other', '/ˈʌðər/', 'A1', 'khác; ngoài ra; người khác; vật khác', 'det.', NULL, NULL, 'other đứng trước danh từ; others dùng độc lập; vật còn lại trong hai vật dùng the other.', 'This shoe fits, but where is the other one?', NULL, 'Chiếc giày này vừa chân, nhưng chiếc kia đâu rồi?', '{"wordId":"other","ukIpa":"/ˈʌðə/","usIpa":"/ˈʌðər/","cefr":"A1","topic":"daily","senses":[{"pos":"det.","en":"Different from or additional to those already mentioned.","vi":"khác; ngoài ra"},{"pos":"pron.","en":"A remaining or different person or thing.","vi":"người khác; vật khác"}],"examples":[{"en":"This shoe fits, but where is the other one?","vi":"Chiếc giày này vừa chân, nhưng chiếc kia đâu rồi?","audioKind":"ex"},{"en":"Schools should teach practical skills alongside other subjects to prepare students for the demands of adult life.","vi":"Nhà trường nên giảng dạy các kỹ năng thực tế bên cạnh các môn học khác để trang bị cho học sinh trước những yêu cầu của cuộc sống trưởng thành.","audioKind":"ex2"}],"collocations":[{"en":"other people","vi":"những người khác"},{"en":"the other day","vi":"hôm nọ"},{"en":"each other","vi":"lẫn nhau"},{"en":"on the other hand","vi":"mặt khác"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"other đứng trước danh từ; others dùng độc lập; vật còn lại trong hai vật dùng the other.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_apple', 'en-a1-29', 'apple', '/ˈæpəl/', 'A1', 'quả táo', 'n.', NULL, NULL, 'Danh từ đếm được; "một quả táo" dùng an apple.', 'I packed an apple and a sandwich for lunch.', NULL, 'Tôi đã chuẩn bị một quả táo và một chiếc bánh mì kẹp cho bữa trưa.', '{"wordId":"apple","ukIpa":"/ˈæpəl/","usIpa":"/ˈæpəl/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a round fruit with firm flesh and red or green skin","vi":"quả táo"}],"examples":[{"en":"I packed an apple and a sandwich for lunch.","vi":"Tôi đã chuẩn bị một quả táo và một chiếc bánh mì kẹp cho bữa trưa.","audioKind":"ex"},{"en":"Providing fresh fruit, such as apples, in schools may encourage children to develop healthier eating habits.","vi":"Việc cung cấp trái cây tươi, chẳng hạn như táo, ở các trường học có thể giúp khuyến khích trẻ em phát triển thói quen ăn uống lành mạnh hơn.","audioKind":"ex2"}],"collocations":[{"en":"apple juice","vi":"nước ép táo"},{"en":"apple pie","vi":"bánh táo"},{"en":"an apple core","vi":"lõi táo"},{"en":"a crisp apple","vi":"quả táo giòn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ đếm được; \"một quả táo\" dùng an apple.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_because', 'en-a1-29', 'because', '/bɪˈkɔːz/', 'A1', 'vì; bởi vì', 'conj.', NULL, 'Đồng nghĩa: since, as', 'because đi với mệnh đề; because of đi với danh từ hoặc danh động từ.', 'I closed the window because the room felt cold.', NULL, 'Tôi đóng cửa sổ lại vì trong phòng có cảm giác hơi lạnh.', '{"wordId":"because","ukIpa":"/bɪˈkɒz/","usIpa":"/bɪˈkɔːz/","cefr":"A1","topic":"daily","senses":[{"pos":"conj.","en":"Introduces the reason why something happens or is true.","vi":"vì; bởi vì"}],"examples":[{"en":"I closed the window because the room felt cold.","vi":"Tôi đóng cửa sổ lại vì trong phòng có cảm giác hơi lạnh.","audioKind":"ex"},{"en":"Many commuters choose public transport because it is cheaper and produces fewer emissions than driving alone.","vi":"Nhiều người đi làm lựa chọn phương tiện giao thông công cộng vì nó tiết kiệm hơn và thải ra ít khí thải hơn so với việc tự lái xe.","audioKind":"ex2"}],"collocations":[{"en":"because of the weather","vi":"vì thời tiết"},{"en":"because of this","vi":"vì lý do này"},{"en":"partly because","vi":"một phần là vì"}],"wordFamily":[],"synonyms":["since","as"],"antonyms":[],"tipVi":"because đi với mệnh đề; because of đi với danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_right', 'en-a1-29', 'right', '/raɪt/', 'A1', 'đúng; phải; thích hợp; quyền lợi; bên phải', 'adj.', 'rightly (adv.), rightness (n.)', 'Đồng nghĩa: correct, appropriate · Trái nghĩa: wrong', 'Chỉ quyền lợi dùng a right to; chỉ vị trí bên phải dùng on the right.', 'You picked the right key to open the door.', NULL, 'Bạn đã chọn đúng chiếc chìa khóa để mở cửa.', '{"wordId":"right","ukIpa":"/raɪt/","usIpa":"/raɪt/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Correct, true, or suitable for a particular purpose.","vi":"đúng; phải; thích hợp"},{"pos":"n.","en":"Something you are legally or morally entitled to.","vi":"quyền lợi"},{"pos":"adj.","en":"On the side opposite to the left.","vi":"bên phải"}],"examples":[{"en":"You picked the right key to open the door.","vi":"Bạn đã chọn đúng chiếc chìa khóa để mở cửa.","audioKind":"ex"},{"en":"Every child has the right to receive an education, regardless of their family''s financial circumstances.","vi":"Mỗi đứa trẻ đều có quyền được học tập, bất kể hoàn cảnh kinh tế của gia đình các em ra sao.","audioKind":"ex2"}],"collocations":[{"en":"the right answer","vi":"câu trả lời đúng"},{"en":"the right to education","vi":"quyền được giáo dục"},{"en":"on the right","vi":"ở bên phải"},{"en":"make the right decision","vi":"đưa ra quyết định đúng đắn"}],"wordFamily":["rightly (adv.)","rightness (n.)"],"synonyms":["correct","appropriate"],"antonyms":["wrong"],"tipVi":"Chỉ quyền lợi dùng a right to; chỉ vị trí bên phải dùng on the right.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_difficult', 'en-a1-29', 'difficult', '/ˈdɪfɪkəlt/', 'A1', 'khó khăn; phức tạp; khó tính; khó chiều', 'adj.', 'difficulty (n.)', 'Đồng nghĩa: hard, challenging · Trái nghĩa: easy', 'Thường dùng cấu trúc find it difficult to do, không nhầm lẫn difficulty thành tính từ.', 'This heavy suitcase is difficult to carry upstairs.', NULL, 'Chiếc vali nặng này rất khó để khiêng lên lầu.', '{"wordId":"difficult","ukIpa":"/ˈdɪfɪkəlt/","usIpa":"/ˈdɪfɪkəlt/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Needing considerable effort or skill to do or understand.","vi":"khó khăn; phức tạp"},{"pos":"adj.","en":"Not easy to please, manage, or deal with.","vi":"khó tính; khó chiều"}],"examples":[{"en":"This heavy suitcase is difficult to carry upstairs.","vi":"Chiếc vali nặng này rất khó để khiêng lên lầu.","audioKind":"ex"},{"en":"Many graduates find it difficult to secure stable employment without previous experience in their chosen field.","vi":"Nhiều sinh viên mới tốt nghiệp cảm thấy khó có thể tìm được một công việc ổn định nếu thiếu kinh nghiệm trước đó trong lĩnh vực họ đã chọn.","audioKind":"ex2"}],"collocations":[{"en":"a difficult decision","vi":"một quyết định khó khăn"},{"en":"difficult to understand","vi":"khó hiểu"},{"en":"a difficult customer","vi":"một vị khách khó chiều"}],"wordFamily":["difficulty (n.)"],"synonyms":["hard","challenging"],"antonyms":["easy"],"tipVi":"Thường dùng cấu trúc find it difficult to do, không nhầm lẫn difficulty thành tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_somebody', 'en-a1-29', 'somebody', '/ˈsʌmbədi/', 'A1', 'ai đó; người nào đó', 'pron.', NULL, 'Đồng nghĩa: someone · Trái nghĩa: nobody', 'Khi làm chủ ngữ, động từ theo sau ở dạng số ít; khi quy chiếu lại thường dùng they.', 'Somebody left a blue umbrella beside the front door.', NULL, 'Ai đó đã để quên một chiếc ô màu xanh ở cạnh cửa trước.', '{"wordId":"somebody","ukIpa":"/ˈsʌmbədi/","usIpa":"/ˈsʌmbədi/","cefr":"A1","topic":"daily","senses":[{"pos":"pron.","en":"a person whose identity is unknown or not stated","vi":"ai đó; người nào đó"}],"examples":[{"en":"Somebody left a blue umbrella beside the front door.","vi":"Ai đó đã để quên một chiếc ô màu xanh ở cạnh cửa trước.","audioKind":"ex"},{"en":"Students are more likely to seek help when they know somebody will listen without judging them.","vi":"Học sinh có xu hướng tìm kiếm sự giúp đỡ nhiều hơn khi các em biết rằng sẽ có người lắng nghe mà không phán xét mình.","audioKind":"ex2"}],"collocations":[{"en":"somebody else","vi":"người khác"},{"en":"somebody to talk to","vi":"người để tâm sự"},{"en":"somebody special","vi":"một người đặc biệt"}],"wordFamily":[],"synonyms":["someone"],"antonyms":["nobody"],"tipVi":"Khi làm chủ ngữ, động từ theo sau ở dạng số ít; khi quy chiếu lại thường dùng they.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_include', 'en-a1-29', 'include', '/ɪnˈkluːd/', 'A1', 'bao gồm; gồm có; đưa vào; cho vào', 'v.', 'inclusion (n.), inclusive (adj.), including (prep.)', 'Đồng nghĩa: contain, incorporate · Trái nghĩa: exclude', 'Include thường liệt kê một phần nội dung chứ không biểu thị một danh sách đầy đủ.', 'Does the price include breakfast and a clean towel?', NULL, 'Giá này đã bao gồm bữa sáng và một chiếc khăn sạch chưa?', '{"wordId":"include","ukIpa":"/ɪnˈkluːd/","usIpa":"/ɪnˈkluːd/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"have someone or something as part of a whole","vi":"bao gồm; gồm có"},{"pos":"v.","en":"make someone or something part of a group or activity","vi":"đưa vào; cho vào"}],"examples":[{"en":"Does the price include breakfast and a clean towel?","vi":"Giá này đã bao gồm bữa sáng và một chiếc khăn sạch chưa?","audioKind":"ex"},{"en":"Urban development plans should include affordable housing and reliable public transport to support low-income residents.","vi":"Các kế hoạch phát triển đô thị nên bao gồm nhà ở giá rẻ và hệ thống giao thông công cộng đáng tin cậy để hỗ trợ cư dân thu nhập thấp.","audioKind":"ex2"}],"collocations":[{"en":"include someone in","vi":"cho ai tham gia"},{"en":"include a range of","vi":"bao gồm một loạt"},{"en":"price includes","vi":"giá đã bao gồm"}],"wordFamily":["inclusion (n.)","inclusive (adj.)","including (prep.)"],"synonyms":["contain","incorporate"],"antonyms":["exclude"],"tipVi":"Include thường liệt kê một phần nội dung chứ không biểu thị một danh sách đầy đủ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_evening', 'en-a1-29', 'evening', '/ˈiːvnɪŋ/', 'A1', 'buổi tối; chiều tối', 'n.', NULL, NULL, 'Chỉ chung buổi tối dùng in the evening; trước this evening không dùng giới từ.', 'We spent the evening cooking and listening to music.', NULL, 'Chúng tôi dành cả buổi tối để nấu ăn và nghe nhạc.', '{"wordId":"evening","ukIpa":"/ˈiːvnɪŋ/","usIpa":"/ˈiːvnɪŋ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The part of the day between afternoon and bedtime.","vi":"buổi tối; chiều tối"}],"examples":[{"en":"We spent the evening cooking and listening to music.","vi":"Chúng tôi dành cả buổi tối để nấu ăn và nghe nhạc.","audioKind":"ex"},{"en":"Evening classes allow working adults to gain new qualifications without giving up their current employment.","vi":"Các lớp học buổi tối tạo điều kiện cho người trưởng thành đi làm có thêm chứng chỉ mới mà không phải từ bỏ công việc hiện tại.","audioKind":"ex2"}],"collocations":[{"en":"in the evening","vi":"vào buổi tối"},{"en":"this evening","vi":"tối nay"},{"en":"evening classes","vi":"các lớp học buổi tối"},{"en":"early evening","vi":"vào lúc chiều tối"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ chung buổi tối dùng in the evening; trước this evening không dùng giới từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_everything', 'en-a1-29', 'everything', '/ˈevriθɪŋ/', 'A1', 'mọi thứ; tất cả mọi vật; điều quan trọng nhất', 'pron.', NULL, 'Trái nghĩa: nothing', 'Khi làm chủ ngữ, động từ đi kèm chia ở số ít: Everything is ready.', 'Everything in my bag got wet during the storm.', NULL, 'Mọi thứ trong túi xách của tôi đã bị ướt sũng trong trận bão.', '{"wordId":"everything","ukIpa":"/ˈevriθɪŋ/","usIpa":"/ˈevriθɪŋ/","cefr":"A1","topic":"daily","senses":[{"pos":"pron.","en":"All things or all the things in a particular situation.","vi":"mọi thứ; tất cả mọi vật"},{"pos":"pron.","en":"The most important thing in someone''s life or situation.","vi":"điều quan trọng nhất"}],"examples":[{"en":"Everything in my bag got wet during the storm.","vi":"Mọi thứ trong túi xách của tôi đã bị ướt sũng trong trận bão.","audioKind":"ex"},{"en":"Although digital resources are valuable, students should not assume that everything they read online is accurate.","vi":"Mặc dù tài nguyên kỹ thuật số rất có giá trị, học sinh không nên cho rằng mọi thứ mình đọc được trên mạng đều chính xác.","audioKind":"ex2"}],"collocations":[{"en":"everything else","vi":"mọi thứ khác"},{"en":"everything possible","vi":"mọi thứ có thể"},{"en":"mean everything to someone","vi":"có ý nghĩa quan trọng nhất đối với ai đó"}],"wordFamily":[],"synonyms":[],"antonyms":["nothing"],"tipVi":"Khi làm chủ ngữ, động từ đi kèm chia ở số ít: Everything is ready.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brother', 'en-a1-29', 'brother', '/ˈbrʌðər/', 'A1', 'anh trai; em trai', 'n.', 'brotherly (adj.), brotherhood (n.)', NULL, '"brother" không phân biệt anh hay em; dùng "older" hoặc "younger" để chỉ thứ bậc.', 'My younger brother borrowed my bicycle this morning.', NULL, 'Em trai tôi đã mượn xe đạp của tôi sáng nay.', '{"wordId":"brother","ukIpa":"/ˈbrʌðə/","usIpa":"/ˈbrʌðər/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A male who has one or both parents in common with you.","vi":"anh trai; em trai"}],"examples":[{"en":"My younger brother borrowed my bicycle this morning.","vi":"Em trai tôi đã mượn xe đạp của tôi sáng nay.","audioKind":"ex"},{"en":"Older brothers and sisters can support younger children''s learning by reading with them regularly at home.","vi":"Anh chị lớn có thể hỗ trợ việc học của các em nhỏ bằng cách thường xuyên đọc sách cùng các em tại nhà.","audioKind":"ex2"}],"collocations":[{"en":"older brother","vi":"anh trai"},{"en":"younger brother","vi":"em trai"},{"en":"twin brother","vi":"anh em sinh đôi"}],"wordFamily":["brotherly (adj.)","brotherhood (n.)"],"synonyms":[],"antonyms":[],"tipVi":"\"brother\" không phân biệt anh hay em; dùng \"older\" hoặc \"younger\" để chỉ thứ bậc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_than', 'en-a1-29', 'than', '/ðæn/', 'A1', 'hơn (dùng trong so sánh); hơn là (trước mệnh đề so sánh)', 'prep.', NULL, NULL, '"than" dùng để so sánh; "then" có nghĩa là "sau đó", cần chú ý chính tả.', 'My new backpack is lighter than my old one.', NULL, 'Chiếc ba lô mới của tôi nhẹ hơn chiếc cũ.', '{"wordId":"than","ukIpa":"/ðæn/","usIpa":"/ðæn/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"used to introduce the second thing in a comparison","vi":"hơn (dùng trong so sánh)"},{"pos":"conj.","en":"used before a clause expressing the other side of a comparison","vi":"hơn là (trước mệnh đề so sánh)"}],"examples":[{"en":"My new backpack is lighter than my old one.","vi":"Chiếc ba lô mới của tôi nhẹ hơn chiếc cũ.","audioKind":"ex"},{"en":"Investing in public transport may be more effective than building additional roads in crowded cities.","vi":"Đầu tư vào giao thông công cộng có thể hiệu quả hơn việc xây dựng thêm đường sá ở các thành phố đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"more than","vi":"nhiều hơn"},{"en":"less than","vi":"ít hơn"},{"en":"rather than","vi":"thay vì; hơn là"},{"en":"other than","vi":"ngoài... ra"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"\"than\" dùng để so sánh; \"then\" có nghĩa là \"sau đó\", cần chú ý chính tả.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_warm', 'en-a1-29', 'warm', '/wɔːrm/', 'A1', 'ấm áp; ấm; nồng nhiệt; thân thiện; trìu mến; làm ấm; trở nên ấm áp', 'adj.', 'warmth (n.), warmly (adv.), warming (n.)', 'Trái nghĩa: cold, cool', '"warm" có nhiệt độ thấp hơn "hot"; "warm to" ai đó có nghĩa là dần có thiện cảm với người đó.', 'This thick blanket keeps me warm on chilly evenings.', NULL, 'Chiếc chăn dày này giữ cho tôi ấm áp vào những buổi tối se lạnh.', '{"wordId":"warm","ukIpa":"/wɔːm/","usIpa":"/wɔːrm/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"having a comfortable temperature that is not hot","vi":"ấm áp; ấm"},{"pos":"adj.","en":"showing kindness, friendliness, or affection","vi":"nồng nhiệt; thân thiện; trìu mến"},{"pos":"v.","en":"to become warmer or make something warmer","vi":"làm ấm; trở nên ấm áp"}],"examples":[{"en":"This thick blanket keeps me warm on chilly evenings.","vi":"Chiếc chăn dày này giữ cho tôi ấm áp vào những buổi tối se lạnh.","audioKind":"ex"},{"en":"A warm welcome at school can help new students feel included and develop confidence.","vi":"Sự chào đón nồng nhiệt tại trường có thể giúp học sinh mới cảm thấy được hòa nhập và phát triển sự tự tin.","audioKind":"ex2"}],"collocations":[{"en":"keep warm","vi":"giữ ấm"},{"en":"a warm welcome","vi":"sự chào đón nồng nhiệt"},{"en":"warm up","vi":"khởi động; làm ấm lên"},{"en":"warm to someone","vi":"dần có thiện cảm với ai đó"}],"wordFamily":["warmth (n.)","warmly (adv.)","warming (n.)"],"synonyms":[],"antonyms":["cold","cool"],"tipVi":"\"warm\" có nhiệt độ thấp hơn \"hot\"; \"warm to\" ai đó có nghĩa là dần có thiện cảm với người đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_all', 'en-a1-29', 'all', '/ɔːl/', 'A1', 'tất cả; toàn bộ; tất cả mọi người; mọi thứ; hoàn toàn', 'det.', NULL, 'Trái nghĩa: none', 'all có thể kết hợp với danh từ số nhiều hoặc danh từ không đếm được; every đi với danh từ đếm được số ít.', 'All the children brought fruit for the picnic.', NULL, 'Tất cả lũ trẻ đều mang hoa quả đến buổi dã ngoại.', '{"wordId":"all","ukIpa":"/ɔːl/","usIpa":"/ɔːl/","cefr":"A1","topic":"daily","senses":[{"pos":"det.","en":"the whole amount of something or every member of a group","vi":"tất cả; toàn bộ"},{"pos":"pron.","en":"everything or everyone in a particular group","vi":"tất cả mọi người; mọi thứ"},{"pos":"adv.","en":"completely or entirely","vi":"hoàn toàn"}],"examples":[{"en":"All the children brought fruit for the picnic.","vi":"Tất cả lũ trẻ đều mang hoa quả đến buổi dã ngoại.","audioKind":"ex"},{"en":"Governments should ensure that all citizens have access to affordable healthcare, regardless of their income.","vi":"Chính phủ nên đảm bảo rằng tất cả công dân đều được tiếp cận dịch vụ chăm sóc sức khỏe giá cả phải chăng, bất kể thu nhập của họ.","audioKind":"ex2"}],"collocations":[{"en":"all day","vi":"cả ngày"},{"en":"all of us","vi":"tất cả chúng ta"},{"en":"all the time","vi":"luôn luôn; suốt"},{"en":"after all","vi":"rốt cuộc; xét cho cùng"}],"wordFamily":[],"synonyms":[],"antonyms":["none"],"tipVi":"all có thể kết hợp với danh từ số nhiều hoặc danh từ không đếm được; every đi với danh từ đếm được số ít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_come', 'en-a1-29', 'come', '/kʌm/', 'A1', 'đến; đi đến; đến đúng lúc; xảy ra; bắt nguồn từ; xuất phát từ', 'v.', NULL, 'Đồng nghĩa: arrive · Trái nghĩa: go', 'Chia động từ bất quy tắc: come–came–come; come from dùng để chỉ nguồn gốc.', 'Come inside and warm your hands by the fire.', NULL, 'Hãy bước vào trong nhà và sưởi ấm tay bên đống lửa nào.', '{"wordId":"come","ukIpa":"/kʌm/","usIpa":"/kʌm/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"Move towards the speaker or a particular place.","vi":"đến; đi đến"},{"pos":"v.","en":"Arrive in time or happen.","vi":"đến đúng lúc; xảy ra"},{"pos":"v.","en":"Have a particular origin or source.","vi":"bắt nguồn từ; xuất phát từ"}],"examples":[{"en":"Come inside and warm your hands by the fire.","vi":"Hãy bước vào trong nhà và sưởi ấm tay bên đống lửa nào.","audioKind":"ex"},{"en":"Much of the funding for public libraries comes from local government rather than private donations.","vi":"Phần lớn kinh phí cho các thư viện công cộng đến từ chính quyền địa phương chứ không phải từ các khoản đóng góp tư nhân.","audioKind":"ex2"}],"collocations":[{"en":"come home","vi":"về nhà"},{"en":"come from","vi":"đến từ; xuất thân từ"},{"en":"come true","vi":"trở thành sự thật"},{"en":"come to an end","vi":"đi đến hồi kết"}],"wordFamily":[],"synonyms":["arrive"],"antonyms":["go"],"tipVi":"Chia động từ bất quy tắc: come–came–come; come from dùng để chỉ nguồn gốc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eat', 'en-a1-29', 'eat', '/iːt/', 'A1', 'ăn; dùng bữa', 'v.', 'eater (n.), edible (adj.), inedible (adj.)', 'Đồng nghĩa: consume', 'Chia động từ bất quy tắc: eat—ate—eaten.', 'We usually eat breakfast together before leaving the house.', NULL, 'Chúng tôi thường ăn sáng cùng nhau trước khi rời khỏi nhà.', '{"wordId":"eat","ukIpa":"/iːt/","usIpa":"/iːt/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To put food in your mouth, chew it, and swallow","vi":"ăn; dùng bữa"}],"examples":[{"en":"We usually eat breakfast together before leaving the house.","vi":"Chúng tôi thường ăn sáng cùng nhau trước khi rời khỏi nhà.","audioKind":"ex"},{"en":"Schools can encourage children to eat more vegetables by providing affordable meals with a variety of fresh ingredients.","vi":"Nhà trường có thể khuyến khích học sinh ăn nhiều rau củ hơn bằng cách cung cấp các bữa ăn giá cả phải chăng với đa dạng nguyên liệu tươi ngon.","audioKind":"ex2"}],"collocations":[{"en":"eat breakfast","vi":"ăn sáng"},{"en":"eat out","vi":"đi ăn nhà hàng"},{"en":"eat a balanced diet","vi":"ăn uống cân đối, lành mạnh"},{"en":"eat well","vi":"ăn uống đầy đủ chất"}],"wordFamily":["eater (n.)","edible (adj.)","inedible (adj.)"],"synonyms":["consume"],"antonyms":[],"tipVi":"Chia động từ bất quy tắc: eat—ate—eaten.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_carrot', 'en-a1-29', 'carrot', '/ˈkærət/', 'A1', 'củ cà rốt; sự khích lệ; phần thưởng', 'n.', NULL, NULL, 'Mang nghĩa bóng là phần thưởng hoặc động lực; thành ngữ carrot and stick chỉ chính sách vừa đấm vừa xoa (thưởng và phạt kết hợp).', 'She sliced a carrot and added it to the soup.', NULL, 'Cô ấy thái lát một củ cà rốt và cho vào nồi súp.', '{"wordId":"carrot","ukIpa":"/ˈkærət/","usIpa":"/ˈkærət/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A long, usually orange root vegetable.","vi":"củ cà rốt"},{"pos":"n.","en":"A reward offered to encourage someone to do something.","vi":"sự khích lệ; phần thưởng"}],"examples":[{"en":"She sliced a carrot and added it to the soup.","vi":"Cô ấy thái lát một củ cà rốt và cho vào nồi súp.","audioKind":"ex"},{"en":"Governments can use tax reductions as a carrot to encourage businesses to invest in renewable energy.","vi":"Chính phủ có thể sử dụng việc giảm thuế như một phần thưởng khích lệ để khuyến khích các doanh nghiệp đầu tư vào năng lượng tái tạo.","audioKind":"ex2"}],"collocations":[{"en":"raw carrot","vi":"cà rốt sống"},{"en":"grated carrot","vi":"cà rốt bào sợi"},{"en":"carrot and stick","vi":"chính sách mềm dẻo (vừa thưởng vừa phạt)"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Mang nghĩa bóng là phần thưởng hoặc động lực; thành ngữ carrot and stick chỉ chính sách vừa đấm vừa xoa (thưởng và phạt kết hợp).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_near', 'en-a1-29', 'near', '/nɪr/', 'A1', 'ở gần; sát bên; gần đó; ở khoảng cách gần; gần; sắp đến', 'prep.', 'nearly (adv.), nearness (n.), nearby (adj.)', 'Đồng nghĩa: close · Trái nghĩa: far', 'near có thể đi thẳng với danh từ chỉ địa điểm; nearly thường mang nghĩa là "hầu như, gần như".', 'We found a quiet café near the station.', NULL, 'Chúng tôi đã tìm thấy một quán cà phê yên tĩnh ở gần nhà ga.', '{"wordId":"near","ukIpa":"/nɪə/","usIpa":"/nɪr/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"close to a place, time, or state","vi":"ở gần; sát bên"},{"pos":"adv.","en":"at or towards a short distance away in space or time","vi":"gần đó; ở khoảng cách gần"},{"pos":"adj.","en":"not far away in distance or time","vi":"gần; sắp đến"}],"examples":[{"en":"We found a quiet café near the station.","vi":"Chúng tôi đã tìm thấy một quán cà phê yên tĩnh ở gần nhà ga.","audioKind":"ex"},{"en":"Building affordable housing near public transport can reduce commuting costs and improve access to employment.","vi":"Việc xây dựng nhà ở giá rẻ gần các phương tiện giao thông công cộng có thể làm giảm chi phí đi lại và cải thiện khả năng tiếp cận việc làm.","audioKind":"ex2"}],"collocations":[{"en":"near the station","vi":"gần nhà ga"},{"en":"in the near future","vi":"trong tương lai gần"},{"en":"come near","vi":"tiến lại gần"},{"en":"nowhere near","vi":"còn lâu mới đạt được; còn rất xa"}],"wordFamily":["nearly (adv.)","nearness (n.)","nearby (adj.)"],"synonyms":["close"],"antonyms":["far"],"tipVi":"near có thể đi thẳng với danh từ chỉ địa điểm; nearly thường mang nghĩa là \"hầu như, gần như\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_just', 'en-a1-29', 'just', '/dʒʌst/', 'A1', 'chỉ; vừa vặn; vừa mới; chính xác; công bằng; hợp đạo lý', 'adv.', 'justly (adv.), justice (n.), unjust (adj.)', 'Đồng nghĩa: only, exactly, fair', 'Khi làm phó từ, từ này có nghĩa là chỉ mới hoặc vừa đúng; khi là tính từ, nó có nghĩa là công bằng.', 'I need just one more minute to finish packing.', NULL, 'Tôi chỉ cần thêm một phút nữa là chuẩn bị xong hành lý.', '{"wordId":"just","ukIpa":"/dʒʌst/","usIpa":"/dʒʌst/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"Only; no more than a particular amount or thing.","vi":"chỉ; vừa vặn"},{"pos":"adv.","en":"Very recently, or exactly at a particular point or degree.","vi":"vừa mới; chính xác"},{"pos":"adj.","en":"Fair and morally right.","vi":"công bằng; hợp đạo lý"}],"examples":[{"en":"I need just one more minute to finish packing.","vi":"Tôi chỉ cần thêm một phút nữa là chuẩn bị xong hành lý.","audioKind":"ex"},{"en":"A just society should ensure that all children can access quality education, regardless of family income.","vi":"Một xã hội công bằng phải đảm bảo rằng mọi trẻ em đều được tiếp cận giáo dục chất lượng, không bị ảnh hưởng bởi thu nhập gia đình.","audioKind":"ex2"}],"collocations":[{"en":"just a moment","vi":"chờ một lát"},{"en":"just in time","vi":"vừa đúng lúc"},{"en":"just enough","vi":"vừa đủ"},{"en":"a just society","vi":"một xã hội công bằng"}],"wordFamily":["justly (adv.)","justice (n.)","unjust (adj.)"],"synonyms":["only","exactly","fair"],"antonyms":[],"tipVi":"Khi làm phó từ, từ này có nghĩa là chỉ mới hoặc vừa đúng; khi là tính từ, nó có nghĩa là công bằng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_birthday', 'en-a1-29', 'birthday', '/ˈbɜːrθdeɪ/', 'A1', 'ngày sinh nhật; ngày kỷ niệm ngày sinh', 'n.', 'birth (n.)', NULL, 'Dùng giới từ on trong ngày sinh nhật, không dùng in hoặc at.', 'My sister baked a lemon cake for my birthday.', NULL, 'Chị gái tôi đã nướng một chiếc bánh kem chanh cho ngày sinh nhật của tôi.', '{"wordId":"birthday","ukIpa":"/ˈbɜːθdeɪ/","usIpa":"/ˈbɜːrθdeɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The yearly anniversary of the day someone was born.","vi":"ngày sinh nhật; ngày kỷ niệm ngày sinh"}],"examples":[{"en":"My sister baked a lemon cake for my birthday.","vi":"Chị gái tôi đã nướng một chiếc bánh kem chanh cho ngày sinh nhật của tôi.","audioKind":"ex"},{"en":"Although birthday celebrations vary across cultures, they often provide opportunities for families to spend time together.","vi":"Mặc dù lễ kỷ niệm sinh nhật có sự khác biệt giữa các nền văn hóa, chúng thường tạo cơ hội cho các thành viên trong gia đình quây quần bên nhau.","audioKind":"ex2"}],"collocations":[{"en":"a birthday cake","vi":"bánh sinh nhật"},{"en":"a birthday present","vi":"quà sinh nhật"},{"en":"celebrate a birthday","vi":"kỷ niệm ngày sinh"}],"wordFamily":["birth (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng giới từ on trong ngày sinh nhật, không dùng in hoặc at.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_butter', 'en-a1-29', 'butter', '/ˈbʌtər/', 'A1', 'bơ; phết bơ lên', 'n.', 'buttery (adj.)', NULL, 'butter là bơ, cream là kem; khi chỉ thực phẩm, từ này thường không đếm được.', 'She spread some butter on a slice of warm bread.', NULL, 'Cô ấy phết một ít bơ lên lát bánh mì còn ấm.', '{"wordId":"butter","ukIpa":"/ˈbʌtə/","usIpa":"/ˈbʌtər/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a pale yellow fat made from cream, used in food","vi":"bơ"},{"pos":"v.","en":"to spread butter on food","vi":"phết bơ lên"}],"examples":[{"en":"She spread some butter on a slice of warm bread.","vi":"Cô ấy phết một ít bơ lên lát bánh mì còn ấm.","audioKind":"ex"},{"en":"Replacing some butter with unsaturated oils can help people reduce their overall intake of saturated fat.","vi":"Việc thay thế một phần bơ bằng dầu chưa bão hòa có thể giúp mọi người giảm tổng lượng chất béo bão hòa nạp vào cơ thể.","audioKind":"ex2"}],"collocations":[{"en":"spread butter","vi":"phết bơ"},{"en":"melted butter","vi":"bơ tan chảy"},{"en":"a knob of butter","vi":"một miếng bơ"},{"en":"butter toast","vi":"phết bơ lên bánh mì nướng"}],"wordFamily":["buttery (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"butter là bơ, cream là kem; khi chỉ thực phẩm, từ này thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_close', 'en-a1-29', 'close', '/kloʊz/, /kloʊs/', 'A1', 'đóng; khép; kết thúc; gần; thân thiết; ở khoảng cách gần', 'v.', 'closed (adj.), closely (adv.), closeness (n.), closure (n.)', 'Đồng nghĩa: shut, near · Trái nghĩa: open, distant', 'Động từ phát âm là /z/; tính từ và trạng thái phát âm là /s/.', 'Please close the window before the rain comes in.', NULL, 'Làm ơn đóng cửa sổ lại trước khi trời mưa tạt vào.', '{"wordId":"close","ukIpa":"/kləʊz/, /kləʊs/","usIpa":"/kloʊz/, /kloʊs/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"Shut something or bring an activity to an end","vi":"đóng; khép; kết thúc"},{"pos":"adj.","en":"Near in distance or connected by a strong personal relationship","vi":"gần; thân thiết"},{"pos":"adv.","en":"At a short distance from someone or something","vi":"ở khoảng cách gần"}],"examples":[{"en":"Please close the window before the rain comes in.","vi":"Làm ơn đóng cửa sổ lại trước khi trời mưa tạt vào.","audioKind":"ex"},{"en":"When local libraries close, residents lose valuable spaces for independent learning and community activities.","vi":"Khi các thư viện địa phương đóng cửa, cư dân sẽ mất đi không gian quý giá dành cho việc tự học và các hoạt động cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"close a door","vi":"đóng cửa"},{"en":"close to home","vi":"gần nhà"},{"en":"a close friend","vi":"bạn thân"},{"en":"stay close","vi":"ở gần"}],"wordFamily":["closed (adj.)","closely (adv.)","closeness (n.)","closure (n.)"],"synonyms":["shut","near"],"antonyms":["open","distant"],"tipVi":"Động từ phát âm là /z/; tính từ và trạng thái phát âm là /s/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_off', 'en-a1-29', 'off', '/ɔːf/', 'A1', 'rời đi; cách xa; rời khỏi; không còn chạm vào; tắt; không hoạt động', 'adv.', NULL, 'Trái nghĩa: on', 'off nhấn mạnh sự rời đi hoặc tắt máy; of thường chỉ sự sở hữu, tránh nhầm lẫn.', 'The dog ran off when the gate opened.', NULL, 'Con chó đã chạy vụt đi ngay khi cánh cổng mở ra.', '{"wordId":"off","ukIpa":"/ɒf/","usIpa":"/ɔːf/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"away from a place or position","vi":"rời đi; cách xa"},{"pos":"prep.","en":"away from or no longer touching something","vi":"rời khỏi; không còn chạm vào"},{"pos":"adj.","en":"not operating or not working at a particular time","vi":"tắt; không hoạt động"}],"examples":[{"en":"The dog ran off when the gate opened.","vi":"Con chó đã chạy vụt đi ngay khi cánh cổng mở ra.","audioKind":"ex"},{"en":"Keeping unnecessary lights off in public buildings can reduce electricity consumption and lower operating costs.","vi":"Việc tắt các đèn không cần thiết ở các tòa nhà công cộng có thể làm giảm lượng điện tiêu thụ và hạ thấp chi phí vận hành.","audioKind":"ex2"}],"collocations":[{"en":"turn off","vi":"tắt"},{"en":"take off","vi":"cất cánh; cởi ra"},{"en":"off duty","vi":"hết ca trực"},{"en":"day off","vi":"ngày nghỉ"}],"wordFamily":[],"synonyms":[],"antonyms":["on"],"tipVi":"off nhấn mạnh sự rời đi hoặc tắt máy; of thường chỉ sự sở hữu, tránh nhầm lẫn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wait', 'en-a1-29', 'wait', '/weɪt/', 'A1', 'chờ đợi; ngóng chờ; tạm hoãn; để lại sau; khoảng thời gian chờ đợi', 'v.', 'waiting (n.)', NULL, 'Chờ ai đó dùng wait for someone; chờ để làm gì dùng wait to do.', 'Please wait here while I find my keys.', NULL, 'Vui lòng đợi ở đây trong lúc tôi tìm chìa khóa.', '{"wordId":"wait","ukIpa":"/weɪt/","usIpa":"/weɪt/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To let time pass until something happens or someone arrives.","vi":"chờ đợi; ngóng chờ"},{"pos":"v.","en":"To be left until a later time.","vi":"tạm hoãn; để lại sau"},{"pos":"n.","en":"A period spent expecting something to happen.","vi":"khoảng thời gian chờ đợi"}],"examples":[{"en":"Please wait here while I find my keys.","vi":"Vui lòng đợi ở đây trong lúc tôi tìm chìa khóa.","audioKind":"ex"},{"en":"Patients in rural areas often wait longer for specialist treatment because local medical services are limited.","vi":"Bệnh nhân ở các vùng nông thôn thường phải chờ đợi lâu hơn để được điều trị chuyên khoa vì dịch vụ y tế địa phương còn hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"wait for someone","vi":"chờ đợi ai đó"},{"en":"wait patiently","vi":"kiên nhẫn chờ đợi"},{"en":"a long wait","vi":"sự chờ đợi kéo dài"},{"en":"wait and see","vi":"chờ xem sao"}],"wordFamily":["waiting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chờ ai đó dùng wait for someone; chờ để làm gì dùng wait to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_under', 'en-a1-29', 'under', '/ˈʌndər/', 'A1', 'ở dưới; phía dưới; dưới (số lượng, độ tuổi, mức độ); trong tình trạng; chịu sự chi phối', 'prep.', NULL, 'Đồng nghĩa: below, beneath · Trái nghĩa: over, above', 'under có thể chỉ vị trí, số lượng hoặc trạng thái như under pressure.', 'The cat curled up under the kitchen table.', NULL, 'Con mèo cuộn tròn ở dưới gầm bàn bếp.', '{"wordId":"under","ukIpa":"/ˈʌndə/","usIpa":"/ˈʌndər/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"in or into a position below something","vi":"ở dưới; phía dưới"},{"pos":"prep.","en":"less than a particular amount, age, or level","vi":"dưới (số lượng, độ tuổi, mức độ)"},{"pos":"prep.","en":"experiencing a condition or being controlled by someone or something","vi":"trong tình trạng; chịu sự chi phối"}],"examples":[{"en":"The cat curled up under the kitchen table.","vi":"Con mèo cuộn tròn ở dưới gầm bàn bếp.","audioKind":"ex"},{"en":"Under the new policy, local authorities must provide safer cycling routes near schools and residential areas.","vi":"Theo chính sách mới, các cơ quan chức năng địa phương phải cung cấp các tuyến đường đi xe đạp an toàn hơn gần các trường học và khu dân cư.","audioKind":"ex2"}],"collocations":[{"en":"under pressure","vi":"chịu áp lực"},{"en":"under control","vi":"được kiểm soát"},{"en":"under construction","vi":"đang xây dựng"},{"en":"under the age of","vi":"dưới độ tuổi"}],"wordFamily":[],"synonyms":["below","beneath"],"antonyms":["over","above"],"tipVi":"under có thể chỉ vị trí, số lượng hoặc trạng thái như under pressure.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_on', 'en-a1-29', 'on', '/ɑːn/', 'A1', 'ở trên; tiếp xúc và được bề mặt nâng đỡ; vào (ngày, tháng); về (một chủ đề); đang hoạt động; đang bật', 'prep.', NULL, 'Trái nghĩa: off', 'Dùng on cho ngày cụ thể; in cho tháng; at cho giờ.', 'Your keys are on the table beside the door.', NULL, 'Chìa khóa của bạn ở trên chiếc bàn cạnh cửa ra vào.', '{"wordId":"on","ukIpa":"/ɒn/","usIpa":"/ɑːn/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"Touching and supported by a surface.","vi":"ở trên; tiếp xúc và được bề mặt nâng đỡ"},{"pos":"prep.","en":"Used for days and dates, or to introduce a topic.","vi":"vào (ngày, tháng); về (một chủ đề)"},{"pos":"adv.","en":"Operating or receiving power.","vi":"đang hoạt động; đang bật"}],"examples":[{"en":"Your keys are on the table beside the door.","vi":"Chìa khóa của bạn ở trên chiếc bàn cạnh cửa ra vào.","audioKind":"ex"},{"en":"Installing solar panels on public buildings can reduce energy costs and demonstrate a government''s commitment to sustainability.","vi":"Việc lắp đặt các tấm pin mặt trời trên các tòa nhà công cộng có thể giúp giảm chi phí năng lượng và thể hiện cam kết của chính phủ đối với sự phát triển bền vững.","audioKind":"ex2"}],"collocations":[{"en":"on the table","vi":"trên bàn"},{"en":"on Monday","vi":"vào thứ Hai"},{"en":"a report on education","vi":"một bản báo cáo về giáo dục"},{"en":"switch on","vi":"bật lên"}],"wordFamily":[],"synonyms":[],"antonyms":["off"],"tipVi":"Dùng on cho ngày cụ thể; in cho tháng; at cho giờ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_personal', 'en-a1-29', 'personal', '/ˈpɝːsənəl/', 'A1', 'cá nhân; của riêng ai đó; riêng tư; thuộc về đời tư; mang tính cá nhân; nhắm vào cá nhân thay vì ý tưởng hay hành động', 'adj.', 'person (n.), personally (adv.), personality (n.), impersonal (adj.)', 'Đồng nghĩa: individual, private · Trái nghĩa: impersonal', 'Personal chỉ tính cá nhân; personnel chỉ toàn thể nhân viên, hãy chú ý cách viết.', 'Please keep your personal belongings close while boarding the train.', NULL, 'Vui lòng giữ kỹ các đồ dùng cá nhân khi lên tàu.', '{"wordId":"personal","ukIpa":"/ˈpɜːsənəl/","usIpa":"/ˈpɝːsənəl/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Belonging or relating to one particular person.","vi":"cá nhân; của riêng ai đó"},{"pos":"adj.","en":"Concerning someone''s private life rather than public matters.","vi":"riêng tư; thuộc về đời tư"},{"pos":"adj.","en":"Directed at someone''s character rather than their ideas or actions.","vi":"mang tính cá nhân; nhắm vào cá nhân thay vì ý tưởng hay hành động"}],"examples":[{"en":"Please keep your personal belongings close while boarding the train.","vi":"Vui lòng giữ kỹ các đồ dùng cá nhân khi lên tàu.","audioKind":"ex"},{"en":"Online services should protect personal information and explain clearly how they collect and use customer data.","vi":"Các dịch vụ trực tuyến nên bảo vệ thông tin cá nhân và giải thích rõ ràng cách họ thu thập cũng như sử dụng dữ liệu của khách hàng.","audioKind":"ex2"}],"collocations":[{"en":"personal belongings","vi":"đồ dùng cá nhân"},{"en":"personal information","vi":"thông tin cá nhân"},{"en":"personal experience","vi":"trải nghiệm cá nhân"},{"en":"personal attack","vi":"tấn công cá nhân"}],"wordFamily":["person (n.)","personally (adv.)","personality (n.)","impersonal (adj.)"],"synonyms":["individual","private"],"antonyms":["impersonal"],"tipVi":"Personal chỉ tính cá nhân; personnel chỉ toàn thể nhân viên, hãy chú ý cách viết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_29_1', 'en-a1-29', 'Cách dùng “carrot” (n.) — củ cà rốt', 'raw carrot  ·  grated carrot  ·  carrot and stick', 'Mang nghĩa bóng là phần thưởng hoặc động lực; thành ngữ carrot and stick chỉ chính sách vừa đấm vừa xoa (thưởng và phạt kết hợp).', NULL, '[{"hanzi":"She sliced a carrot and added it to the soup.","pinyin":"","meaning":"Cô ấy thái lát một củ cà rốt và cho vào nồi súp."},{"hanzi":"Governments can use tax reductions as a carrot to encourage businesses to invest in renewable energy.","pinyin":"","meaning":"Chính phủ có thể sử dụng việc giảm thuế như một phần thưởng khích lệ để khuyến khích các doanh nghiệp đầu tư vào năng lượng tái tạo."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_29_2', 'en-a1-29', 'Cách dùng “all” (det.) — tất cả; toàn bộ', 'all day  ·  all of us  ·  all the time', 'all có thể kết hợp với danh từ số nhiều hoặc danh từ không đếm được; every đi với danh từ đếm được số ít.', 'Trái nghĩa: none', '[{"hanzi":"All the children brought fruit for the picnic.","pinyin":"","meaning":"Tất cả lũ trẻ đều mang hoa quả đến buổi dã ngoại."},{"hanzi":"Governments should ensure that all citizens have access to affordable healthcare, regardless of their income.","pinyin":"","meaning":"Chính phủ nên đảm bảo rằng tất cả công dân đều được tiếp cận dịch vụ chăm sóc sức khỏe giá cả phải chăng, bất kể thu nhập của họ."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_29_3', 'en-a1-29', 'Cách dùng “just” (adv.) — chỉ; vừa vặn', 'just a moment  ·  just in time  ·  just enough', 'Khi làm phó từ, từ này có nghĩa là chỉ mới hoặc vừa đúng; khi là tính từ, nó có nghĩa là công bằng.', 'Họ từ (Word Family): justly (adv.), justice (n.), unjust (adj.) | Đồng nghĩa: only, exactly, fair', '[{"hanzi":"I need just one more minute to finish packing.","pinyin":"","meaning":"Tôi chỉ cần thêm một phút nữa là chuẩn bị xong hành lý."},{"hanzi":"A just society should ensure that all children can access quality education, regardless of family income.","pinyin":"","meaning":"Một xã hội công bằng phải đảm bảo rằng mọi trẻ em đều được tiếp cận giáo dục chất lượng, không bị ảnh hưởng bởi thu nhập gia đình."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_29_4', 'en-a1-29', 'Cách dùng “near” (prep.) — ở gần; sát bên', 'near the station  ·  in the near future  ·  come near', 'near có thể đi thẳng với danh từ chỉ địa điểm; nearly thường mang nghĩa là "hầu như, gần như".', 'Họ từ (Word Family): nearly (adv.), nearness (n.), nearby (adj.) | Đồng nghĩa: close | Trái nghĩa: far', '[{"hanzi":"We found a quiet café near the station.","pinyin":"","meaning":"Chúng tôi đã tìm thấy một quán cà phê yên tĩnh ở gần nhà ga."},{"hanzi":"Building affordable housing near public transport can reduce commuting costs and improve access to employment.","pinyin":"","meaning":"Việc xây dựng nhà ở giá rẻ gần các phương tiện giao thông công cộng có thể làm giảm chi phí đi lại và cải thiện khả năng tiếp cận việc làm."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_29_1', 'en-a1-29', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_29_1_1', 'ten_29_1', 'most', 'Most shops here close before we finish work.', 'Most shops here close before we finish work.', '/moʊst/', 'Hầu hết các cửa hàng ở đây đều đóng cửa trước khi chúng tôi tan làm.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_29_1_2', 'ten_29_1', 'other', 'This shoe fits, but where is the other one?', 'This shoe fits, but where is the other one?', '/ˈʌðər/', 'Chiếc giày này vừa chân, nhưng chiếc kia đâu rồi?', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_29_1_3', 'ten_29_1', 'apple', 'I packed an apple and a sandwich for lunch.', 'I packed an apple and a sandwich for lunch.', '/ˈæpəl/', 'Tôi đã chuẩn bị một quả táo và một chiếc bánh mì kẹp cho bữa trưa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_29_1_4', 'ten_29_1', 'because', 'I closed the window because the room felt cold.', 'I closed the window because the room felt cold.', '/bɪˈkɔːz/', 'Tôi đóng cửa sổ lại vì trong phòng có cảm giác hơi lạnh.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_29_1_5', 'ten_29_1', 'right', 'You picked the right key to open the door.', 'You picked the right key to open the door.', '/raɪt/', 'Bạn đã chọn đúng chiếc chìa khóa để mở cửa.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_29_1_6', 'ten_29_1', 'difficult', 'This heavy suitcase is difficult to carry upstairs.', 'This heavy suitcase is difficult to carry upstairs.', '/ˈdɪfɪkəlt/', 'Chiếc vali nặng này rất khó để khiêng lên lầu.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_29_1_7', 'ten_29_1', 'somebody', 'Somebody left a blue umbrella beside the front door.', 'Somebody left a blue umbrella beside the front door.', '/ˈsʌmbədi/', 'Ai đó đã để quên một chiếc ô màu xanh ở cạnh cửa trước.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_29_1_8', 'ten_29_1', 'include', 'Does the price include breakfast and a clean towel?', 'Does the price include breakfast and a clean towel?', '/ɪnˈkluːd/', 'Giá này đã bao gồm bữa sáng và một chiếc khăn sạch chưa?', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_29_1_1', 'en-a1-29', 'ten_29_1', 'listening', 'listening', 'Most shops here close before we finish work.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ai đó đã để quên một chiếc ô màu xanh ở cạnh cửa trước.","Tôi đã chuẩn bị một quả táo và một chiếc bánh mì kẹp cho bữa trưa.","Chiếc giày này vừa chân, nhưng chiếc kia đâu rồi?","Hầu hết các cửa hàng ở đây đều đóng cửa trước khi chúng tôi tan làm."]'::jsonb, 3, 'Most shops here close before we finish work. → Hầu hết các cửa hàng ở đây đều đóng cửa trước khi chúng tôi tan làm.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_29_1_2', 'en-a1-29', 'ten_29_1', 'listening', 'listening', 'This shoe fits, but where is the other one?', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Giá này đã bao gồm bữa sáng và một chiếc khăn sạch chưa?","Chiếc giày này vừa chân, nhưng chiếc kia đâu rồi?","Bạn đã chọn đúng chiếc chìa khóa để mở cửa.","Hầu hết các cửa hàng ở đây đều đóng cửa trước khi chúng tôi tan làm."]'::jsonb, 1, 'This shoe fits, but where is the other one? → Chiếc giày này vừa chân, nhưng chiếc kia đâu rồi?', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_29_1_3', 'en-a1-29', 'ten_29_1', 'listening', 'listening', 'I packed an apple and a sandwich for lunch.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã chuẩn bị một quả táo và một chiếc bánh mì kẹp cho bữa trưa.","Ai đó đã để quên một chiếc ô màu xanh ở cạnh cửa trước.","Tôi đóng cửa sổ lại vì trong phòng có cảm giác hơi lạnh.","Hầu hết các cửa hàng ở đây đều đóng cửa trước khi chúng tôi tan làm."]'::jsonb, 0, 'I packed an apple and a sandwich for lunch. → Tôi đã chuẩn bị một quả táo và một chiếc bánh mì kẹp cho bữa trưa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_29_2', 'en-a1-29', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_29_2_1', 'ten_29_2', 'most', 'Most urban residents would benefit from reliable public transport that connects residential areas with major employment centres.', 'Most urban residents would benefit from reliable public transport that connects residential areas with major employment centres.', '/moʊst/', 'Đa số cư dân đô thị sẽ được hưởng lợi từ hệ thống giao thông công cộng đáng tin cậy kết nối các khu dân cư với các trung tâm việc làm lớn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_29_2_2', 'ten_29_2', 'other', 'Schools should teach practical skills alongside other subjects to prepare students for the demands of adult life.', 'Schools should teach practical skills alongside other subjects to prepare students for the demands of adult life.', '/ˈʌðər/', 'Nhà trường nên giảng dạy các kỹ năng thực tế bên cạnh các môn học khác để trang bị cho học sinh trước những yêu cầu của cuộc sống trưởng thành.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_29_2_3', 'ten_29_2', 'apple', 'Providing fresh fruit, such as apples, in schools may encourage children to develop healthier eating habits.', 'Providing fresh fruit, such as apples, in schools may encourage children to develop healthier eating habits.', '/ˈæpəl/', 'Việc cung cấp trái cây tươi, chẳng hạn như táo, ở các trường học có thể giúp khuyến khích trẻ em phát triển thói quen ăn uống lành mạnh hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_29_2_4', 'ten_29_2', 'because', 'Many commuters choose public transport because it is cheaper and produces fewer emissions than driving alone.', 'Many commuters choose public transport because it is cheaper and produces fewer emissions than driving alone.', '/bɪˈkɔːz/', 'Nhiều người đi làm lựa chọn phương tiện giao thông công cộng vì nó tiết kiệm hơn và thải ra ít khí thải hơn so với việc tự lái xe.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_29_2_5', 'ten_29_2', 'right', 'Every child has the right to receive an education, regardless of their family''s financial circumstances.', 'Every child has the right to receive an education, regardless of their family''s financial circumstances.', '/raɪt/', 'Mỗi đứa trẻ đều có quyền được học tập, bất kể hoàn cảnh kinh tế của gia đình các em ra sao.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_29_2_6', 'ten_29_2', 'difficult', 'Many graduates find it difficult to secure stable employment without previous experience in their chosen field.', 'Many graduates find it difficult to secure stable employment without previous experience in their chosen field.', '/ˈdɪfɪkəlt/', 'Nhiều sinh viên mới tốt nghiệp cảm thấy khó có thể tìm được một công việc ổn định nếu thiếu kinh nghiệm trước đó trong lĩnh vực họ đã chọn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_29_2_1', 'en-a1-29', 'ten_29_2', 'listening', 'listening', 'Most urban residents would benefit from reliable public transport that connects residential areas with major employment centres.', NULL, 'Trong câu vừa nghe, từ “most” mang nghĩa nào sau đây?', '["bốn; số bốn","giấy","hầu hết; phần lớn","đội; nhóm"]'::jsonb, 2, '“most” (/moʊst/): hầu hết; phần lớn. Câu đầy đủ: Most urban residents would benefit from reliable public transport that connects residential areas with major employment centres.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_29_2_2', 'en-a1-29', 'ten_29_2', 'listening', 'listening', 'Schools should teach practical skills alongside other subjects to prepare students for the demands of adult life.', NULL, 'Trong câu vừa nghe, từ “other” mang nghĩa nào sau đây?', '["khác; ngoài ra","số một (số nguyên dương nhỏ nhất)","hiểu; nắm rõ","con voi"]'::jsonb, 0, '“other” (/ˈʌðər/): khác; ngoài ra. Câu đầy đủ: Schools should teach practical skills alongside other subjects to prepare students for the demands of adult life.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
