INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_29_1', 'en-a1-29', NULL, 'comprehensive_test', 'listening', 'most', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["n. bạn; bạn bè; chiến hữu","phút; chốc lát","tắm; ngâm bồn","hầu hết; phần lớn"]'::jsonb, 3, 'most (/moʊst/) → hầu hết; phần lớn; hầu hết; phần lớn nhất; nhất; cực kỳ', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_29_2', 'en-a1-29', NULL, 'comprehensive_test', 'listening', 'This shoe fits, but where is the other one?', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã tìm thấy một quán cà phê yên tĩnh ở gần nhà ga.","Mọi thứ trong túi xách của tôi đã bị ướt sũng trong trận bão.","Chiếc vali nặng này rất khó để khiêng lên lầu.","Chiếc giày này vừa chân, nhưng chiếc kia đâu rồi?"]'::jsonb, 3, 'This shoe fits, but where is the other one? → Chiếc giày này vừa chân, nhưng chiếc kia đâu rồi?', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_29_3', 'en-a1-29', NULL, 'comprehensive_test', 'listening', 'apple', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhiều (dùng với danh từ đếm được số nhiều)","quả táo","trò chơi; cuộc thi đấu","tháng Tám"]'::jsonb, 1, 'apple (/ˈæpəl/) → quả táo', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_29_4', 'en-a1-29', NULL, 'comprehensive_test', 'listening', 'I closed the window because the room felt cold.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hầu hết các cửa hàng ở đây đều đóng cửa trước khi chúng tôi tan làm.","Cô ấy thái lát một củ cà rốt và cho vào nồi súp.","Mọi thứ trong túi xách của tôi đã bị ướt sũng trong trận bão.","Tôi đóng cửa sổ lại vì trong phòng có cảm giác hơi lạnh."]'::jsonb, 3, 'I closed the window because the room felt cold. → Tôi đóng cửa sổ lại vì trong phòng có cảm giác hơi lạnh.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_29_5', 'en-a1-29', NULL, 'comprehensive_test', 'listening', 'right', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mẩu giấy nhắn; ghi chú","tháng Tám","khác; ngoài ra","đúng; phải; thích hợp"]'::jsonb, 3, 'right (/raɪt/) → đúng; phải; thích hợp; quyền lợi; bên phải', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_29_6', 'en-a1-29', NULL, 'comprehensive_test', 'listening', 'This heavy suitcase is difficult to carry upstairs.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Con mèo cuộn tròn ở dưới gầm bàn bếp.","Tất cả lũ trẻ đều mang hoa quả đến buổi dã ngoại.","Cô ấy thái lát một củ cà rốt và cho vào nồi súp.","Chiếc vali nặng này rất khó để khiêng lên lầu."]'::jsonb, 3, 'This heavy suitcase is difficult to carry upstairs. → Chiếc vali nặng này rất khó để khiêng lên lầu.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
