INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_29_8', 'en-a1-29', NULL, 'comprehensive_test', 'listening', 'Does the price include breakfast and a clean towel?', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Giá này đã bao gồm bữa sáng và một chiếc khăn sạch chưa?","Chiếc chăn dày này giữ cho tôi ấm áp vào những buổi tối se lạnh.","Chúng tôi dành cả buổi tối để nấu ăn và nghe nhạc.","Chị gái tôi đã nướng một chiếc bánh kem chanh cho ngày sinh nhật của tôi."]'::jsonb, 0, 'Does the price include breakfast and a clean towel? → Giá này đã bao gồm bữa sáng và một chiếc khăn sạch chưa?', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
