INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_29_18', 'en-a1-29', NULL, 'comprehensive_test', 'reading', NULL, 'Most urban residents would benefit from reliable public transport that connects residential areas with major employment centres.', 'Dựa vào câu trên, từ “most” có nghĩa phù hợp nhất là gì?', '["hầu hết; phần lớn","giá cả; giá tiền","chỉ; trưng bày; cho xem","may mắn"]'::jsonb, 0, 'most: hầu hết; phần lớn; hầu hết; phần lớn nhất; nhất; cực kỳ. Dịch cả câu: Đa số cư dân đô thị sẽ được hưởng lợi từ hệ thống giao thông công cộng đáng tin cậy kết nối các khu dân cư với các trung tâm việc làm lớn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_29_19', 'en-a1-29', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should teach practical skills alongside other subjects to prepare students for the demands of adult life.', 'Dựa vào câu trên, từ “other” có nghĩa phù hợp nhất là gì?', '["người; cá nhân","cô ấy; chị ấy; bà ấy (dạng tân ngữ)","khác; ngoài ra","mát mẻ; hơi lạnh"]'::jsonb, 2, 'other: khác; ngoài ra; người khác; vật khác. Dịch cả câu: Nhà trường nên giảng dạy các kỹ năng thực tế bên cạnh các môn học khác để trang bị cho học sinh trước những yêu cầu của cuộc sống trưởng thành.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_29_20', 'en-a1-29', NULL, 'comprehensive_test', 'reading', NULL, 'Providing fresh fruit, such as apples, in schools may encourage children to develop healthier eating habits.', 'Dựa vào câu trên, từ “apple” có nghĩa phù hợp nhất là gì?', '["hoặc; hay (dùng để nối các lựa chọn)","ở phía trên; cao hơn","màu vàng","quả táo"]'::jsonb, 3, 'apple: quả táo. Dịch cả câu: Việc cung cấp trái cây tươi, chẳng hạn như táo, ở các trường học có thể giúp khuyến khích trẻ em phát triển thói quen ăn uống lành mạnh hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_29_21', 'en-a1-29', NULL, 'comprehensive_test', 'reading', NULL, 'Many commuters choose public transport because it is cheaper and produces fewer emissions than driving alone.', 'Dựa vào câu trên, từ “because” có nghĩa phù hợp nhất là gì?', '["dễ dàng; không phức tạp","quan trọng; có giá trị lớn hoặc ảnh hưởng đáng kể","vì; bởi vì","đàn ghi-ta; đàn guitar"]'::jsonb, 2, 'because: vì; bởi vì. Dịch cả câu: Nhiều người đi làm lựa chọn phương tiện giao thông công cộng vì nó tiết kiệm hơn và thải ra ít khí thải hơn so với việc tự lái xe.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_29_22', 'en-a1-29', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ở dưới; phía dưới”', '["plan","swimming","under","possible"]'::jsonb, 2, 'ở dưới; phía dưới → under (/ˈʌndər/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_29_23', 'en-a1-29', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ở trên; tiếp xúc và được bề mặt nâng đỡ”', '["on","T-shirt","American","dark"]'::jsonb, 0, 'ở trên; tiếp xúc và được bề mặt nâng đỡ → on (/ɑːn/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_29_24', 'en-a1-29', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cá nhân; của riêng ai đó”', '["clean","door","yesterday","personal"]'::jsonb, 3, 'cá nhân; của riêng ai đó → personal (/ˈpɝːsənəl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-30', 'en', 'Bài 30: Đời sống hằng ngày (15) - CEFR A1', 'CEFR A1', 'A1 · Đời sống', '27 từ vựng Tiếng Anh CEFR A1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1030, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_say', 'en-a1-30', 'say', '/seɪ/', 'A1', 'nói; phát biểu bằng lời; ghi rõ; thể hiện qua văn bản hoặc bằng chứng khác; quyền lên tiếng; quyền quyết định', 'v.', 'saying (n.), unsaid (adj.)', NULL, 'Nói điều gì đó dùng say something; nói với ai đó dùng tell someone.', 'Please say your name again so I can remember it.', NULL, 'Xin vui lòng nói lại tên của bạn để tôi có thể ghi nhớ.', '{"wordId":"say","ukIpa":"/seɪ/","usIpa":"/seɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To express something using words.","vi":"nói; phát biểu bằng lời"},{"pos":"v.","en":"To give information in writing or through other evidence.","vi":"ghi rõ; thể hiện qua văn bản hoặc bằng chứng khác"},{"pos":"n.","en":"The opportunity to influence a decision.","vi":"quyền lên tiếng; quyền quyết định"}],"examples":[{"en":"Please say your name again so I can remember it.","vi":"Xin vui lòng nói lại tên của bạn để tôi có thể ghi nhớ.","audioKind":"ex"},{"en":"Residents should have a say in planning decisions that directly affect their neighbourhoods and daily lives.","vi":"Cư dân nên có tiếng nói trong các quyết định quy hoạch ảnh hưởng trực tiếp đến khu1 phố và đời sống hàng ngày của họ.","audioKind":"ex2"}],"collocations":[{"en":"say hello","vi":"nói chào"},{"en":"say something to someone","vi":"nói điều gì với ai"},{"en":"have a say in","vi":"có tiếng nói trong"},{"en":"say for certain","vi":"nói chắc chắn"}],"wordFamily":["saying (n.)","unsaid (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nói điều gì đó dùng say something; nói với ai đó dùng tell someone.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lot', 'en-a1-30', 'lot', '/lɑːt/', 'A1', 'nhiều; một lượng lớn; rất nhiều; thường xuyên; một mảnh đất dùng cho mục đích cụ thể', 'pron.', NULL, NULL, 'A lot of đi với danh từ đếm được số nhiều hoặc không đếm được; a lot có thể bổ nghĩa cho động từ.', 'We bought a lot of fresh fruit today.', NULL, 'Hôm nay chúng tôi đã mua rất nhiều trái cây tươi.', '{"wordId":"lot","ukIpa":"/lɒt/","usIpa":"/lɑːt/","cefr":"A1","topic":"daily","senses":[{"pos":"pron.","en":"a large amount or number, in a lot or lots","vi":"nhiều; một lượng lớn"},{"pos":"adv.","en":"very much or often, in the phrase a lot","vi":"rất nhiều; thường xuyên"},{"pos":"n.","en":"an area of land used for a particular purpose","vi":"một mảnh đất dùng cho mục đích cụ thể"}],"examples":[{"en":"We bought a lot of fresh fruit today.","vi":"Hôm nay chúng tôi đã mua rất nhiều trái cây tươi.","audioKind":"ex"},{"en":"Cities can save a lot of energy by improving public transport and encouraging residents to walk.","vi":"Các thành phố có thể tiết kiệm rất nhiều năng lượng bằng cách cải thiện giao thông công cộng và khuyến khích người dân đi bộ.","audioKind":"ex2"}],"collocations":[{"en":"a lot of time","vi":"nhiều thời gian"},{"en":"lots of people","vi":"rất nhiều người"},{"en":"a lot better","vi":"tốt hơn nhiều"},{"en":"a parking lot","vi":"bãi đậu xe"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"A lot of đi với danh từ đếm được số nhiều hoặc không đếm được; a lot có thể bổ nghĩa cho động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_find', 'en-a1-30', 'find', '/faɪnd/', 'A1', 'tìm thấy; tìm ra; cảm thấy; cho là; nhận thấy; vật tìm được; phát hiện quý giá', 'v.', 'finder (n.), finding (n.)', 'Đồng nghĩa: discover, locate · Trái nghĩa: lose', 'Dạng quá khứ và quá khứ phân từ đều là found; cấu trúc find + tân ngữ + tính từ.', 'I finally found my keys inside my coat pocket.', NULL, 'Cuối cùng tôi đã tìm thấy chìa khóa của mình ở trong túi áo khoác.', '{"wordId":"find","ukIpa":"/faɪnd/","usIpa":"/faɪnd/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To discover something or locate what you were looking for.","vi":"tìm thấy; tìm ra"},{"pos":"v.","en":"To have a particular opinion or experience of something.","vi":"cảm thấy; cho là; nhận thấy"},{"pos":"n.","en":"Something useful or valuable that someone discovers.","vi":"vật tìm được; phát hiện quý giá"}],"examples":[{"en":"I finally found my keys inside my coat pocket.","vi":"Cuối cùng tôi đã tìm thấy chìa khóa của mình ở trong túi áo khoác.","audioKind":"ex"},{"en":"Many students find online courses convenient, although some struggle to stay motivated without classroom interaction.","vi":"Nhiều sinh viên thấy các khóa học trực tuyến rất tiện lợi, mặc dù một số người gặp khó khăn trong việc duy trì động lực khi thiếu sự tương tác trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"find a solution","vi":"tìm ra giải pháp"},{"en":"find out","vi":"tìm hiểu ra; phát hiện"},{"en":"find it difficult to","vi":"cảm thấy khó khăn khi làm gì"},{"en":"a valuable find","vi":"một phát hiện có giá trị"}],"wordFamily":["finder (n.)","finding (n.)"],"synonyms":["discover","locate"],"antonyms":["lose"],"tipVi":"Dạng quá khứ và quá khứ phân từ đều là found; cấu trúc find + tân ngữ + tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_walk', 'en-a1-30', 'walk', '/wɔːk/', 'A1', 'đi bộ; chuyến đi bộ; cuộc dạo chơi', 'v.', 'walker (n.), walking (n.), walkable (adj.)', 'Đồng nghĩa: stroll', 'Chữ cái l không phát âm; walk the dog nghĩa là dắt chó đi dạo.', 'We walk to the bakery every Sunday morning.', NULL, 'Chúng tôi đi bộ đến tiệm bánh vào mỗi sáng Chủ nhật.', '{"wordId":"walk","ukIpa":"/wɔːk/","usIpa":"/wɔːk/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To move on foot at a pace slower than running","vi":"đi bộ"},{"pos":"n.","en":"A journey made on foot, often for pleasure","vi":"chuyến đi bộ; cuộc dạo chơi"}],"examples":[{"en":"We walk to the bakery every Sunday morning.","vi":"Chúng tôi đi bộ đến tiệm bánh vào mỗi sáng Chủ nhật.","audioKind":"ex"},{"en":"Safe pavements and attractive public spaces encourage residents to walk rather than drive for short journeys.","vi":"Lối đi bộ an toàn và không gian công cộng hấp dẫn khuyến khích người dân đi bộ thay vì lái xe cho những chuyến đi ngắn.","audioKind":"ex2"}],"collocations":[{"en":"go for a walk","vi":"đi dạo"},{"en":"walk to school","vi":"đi bộ đến trường"},{"en":"walk the dog","vi":"dắt chó đi dạo"},{"en":"a brisk walk","vi":"một bước đi nhanh; đi bộ nhanh"}],"wordFamily":["walker (n.)","walking (n.)","walkable (adj.)"],"synonyms":["stroll"],"antonyms":[],"tipVi":"Chữ cái l không phát âm; walk the dog nghĩa là dắt chó đi dạo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_as', 'en-a1-30', 'as', '/əz/', 'A1', 'với tư cách là; như; khi; vì; như; như (bằng mức độ, trong so sánh)', 'prep.', NULL, NULL, 'as chỉ thực tế vai trò; like chỉ sự tương đồng. Khi đọc nhấn mạnh, phát âm là /æz/.', 'She works as a guide at the local museum.', NULL, 'Cô ấy làm hướng dẫn viên tại bảo tàng địa phương.', '{"wordId":"as","ukIpa":"/əz/","usIpa":"/əz/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"used to indicate someone''s role or something''s purpose","vi":"với tư cách là; như"},{"pos":"conj.","en":"introduces a time, reason, or way something happens","vi":"khi; vì; như"},{"pos":"adv.","en":"used in comparisons to show an equal degree","vi":"như (bằng mức độ, trong so sánh)"}],"examples":[{"en":"She works as a guide at the local museum.","vi":"Cô ấy làm hướng dẫn viên tại bảo tàng địa phương.","audioKind":"ex"},{"en":"As public transport becomes more reliable, fewer commuters may choose to drive to work.","vi":"Khi giao thông công cộng trở nên đáng tin cậy hơn, ít người đi làm hơn có thể chọn lái xe đi làm.","audioKind":"ex2"}],"collocations":[{"en":"work as","vi":"làm việc với tư cách là"},{"en":"as a result","vi":"kết quả là"},{"en":"as soon as","vi":"ngay khi"},{"en":"as well as","vi":"cũng như"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"as chỉ thực tế vai trò; like chỉ sự tương đồng. Khi đọc nhấn mạnh, phát âm là /æz/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_run', 'en-a1-30', 'run', '/rʌn/', 'A1', 'chạy; điều hành; quản lý; vận hành; chạy (máy móc, chương trình)', 'v.', 'runner (n), running (n)', 'Đồng nghĩa: sprint, manage, operate', 'Quá khứ là ran, quá khứ phân từ là run; hiện phân từ là running.', 'We ran through the park before breakfast today.', NULL, 'Hôm nay chúng tôi đã chạy qua công viên trước bữa sáng.', '{"wordId":"run","ukIpa":"/rʌn/","usIpa":"/rʌn/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"move quickly on foot, lifting both feet between steps","vi":"chạy"},{"pos":"v.","en":"manage a business, organisation, or activity","vi":"điều hành; quản lý"},{"pos":"v.","en":"operate, or make a machine or program operate","vi":"vận hành; chạy (máy móc, chương trình)"}],"examples":[{"en":"We ran through the park before breakfast today.","vi":"Hôm nay chúng tôi đã chạy qua công viên trước bữa sáng.","audioKind":"ex"},{"en":"Local councils often run training programmes to help unemployed residents develop skills needed by employers.","vi":"Các hội đồng địa phương thường tổ chức các chương trình đào tạo để giúp cư dân thất nghiệp phát triển các kỹ năng mà nhà tuyển dụng cần.","audioKind":"ex2"}],"collocations":[{"en":"run a business","vi":"điều hành doanh nghiệp"},{"en":"run a programme","vi":"chạy một chương trình"},{"en":"run smoothly","vi":"hoạt động trơn tru"},{"en":"run a marathon","vi":"chạy marathon"}],"wordFamily":["runner (n)","running (n)"],"synonyms":["sprint","manage","operate"],"antonyms":[],"tipVi":"Quá khứ là ran, quá khứ phân từ là run; hiện phân từ là running.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_light', 'en-a1-30', 'light', '/laɪt/', 'A1', 'ánh sáng; đèn; nhẹ; sáng; nhạt (màu sắc); thắp sáng; đốt', 'n.', 'lighting (n.), lightness (n.), lightly (adv.), lighten (v.)', 'Trái nghĩa: dark, heavy', 'Danh từ chỉ ánh sáng thường không đếm được; một chiếc đèn dùng a light; động từ quá khứ thường dùng lit.', 'Warm light came through the curtains into our bedroom.', NULL, 'Ánh sáng ấm áp chiếu qua rèm cửa vào phòng ngủ của chúng tôi.', '{"wordId":"light","ukIpa":"/laɪt/","usIpa":"/laɪt/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"brightness that enables sight, or a device producing it","vi":"ánh sáng; đèn"},{"pos":"adj.","en":"not heavy, bright, or pale in colour","vi":"nhẹ; sáng; nhạt (màu sắc)"},{"pos":"v.","en":"make something burn or provide brightness","vi":"thắp sáng; đốt"}],"examples":[{"en":"Warm light came through the curtains into our bedroom.","vi":"Ánh sáng ấm áp chiếu qua rèm cửa vào phòng ngủ của chúng tôi.","audioKind":"ex"},{"en":"Access to natural light in classrooms may improve students'' concentration and reduce electricity consumption.","vi":"Việc tiếp cận ánh sáng tự nhiên trong lớp học có thể nâng cao sự tập trung của học sinh và giảm lượng điện tiêu thụ.","audioKind":"ex2"}],"collocations":[{"en":"natural light","vi":"ánh sáng tự nhiên"},{"en":"turn on the light","vi":"bật đèn"},{"en":"light a candle","vi":"thắp nến"},{"en":"light luggage","vi":"hành lý nhẹ"}],"wordFamily":["lighting (n.)","lightness (n.)","lightly (adv.)","lighten (v.)"],"synonyms":[],"antonyms":["dark","heavy"],"tipVi":"Danh từ chỉ ánh sáng thường không đếm được; một chiếc đèn dùng a light; động từ quá khứ thường dùng lit.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_look', 'en-a1-30', 'look', '/lʊk/', 'A1', 'nhìn; ngắm; trông có vẻ; có vẻ như; cái nhìn; vẻ bề ngoài; thần thái', 'v.', NULL, NULL, 'look at đi kèm đối tượng được nhìn; look làm động từ liên kết theo sau bởi tính từ.', 'Look at the tiny bird beside the window.', NULL, 'Hãy nhìn con chim nhỏ bên cửa sổ kìa.', '{"wordId":"look","ukIpa":"/lʊk/","usIpa":"/lʊk/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"direct your eyes towards someone or something","vi":"nhìn; ngắm"},{"pos":"v.","en":"appear to have a particular quality or condition","vi":"trông có vẻ; có vẻ như"},{"pos":"n.","en":"an act of looking, or someone''s expression or appearance","vi":"cái nhìn; vẻ bề ngoài; thần thái"}],"examples":[{"en":"Look at the tiny bird beside the window.","vi":"Hãy nhìn con chim nhỏ bên cửa sổ kìa.","audioKind":"ex"},{"en":"Public parks often look more attractive when local residents help maintain their gardens and pathways.","vi":"Các công viên công cộng thường trông hấp dẫn hơn khi người dân địa phương giúp duy trì vườn tược và lối đi.","audioKind":"ex2"}],"collocations":[{"en":"look at","vi":"nhìn vào"},{"en":"look forward to","vi":"mong chờ"},{"en":"take a look","vi":"nhìn một cái"},{"en":"look like","vi":"trông giống như"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"look at đi kèm đối tượng được nhìn; look làm động từ liên kết theo sau bởi tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_first', 'en-a1-30', 'first', '/fɝːst/', 'A1', 'thứ nhất; đầu tiên; trước tiên; đầu tiên; trước hết', 'num.', NULL, 'Trái nghĩa: last', 'at first có nghĩa là ban đầu; first có thể dùng để liệt kê ý đầu tiên.', 'This is my first visit to the seaside.', NULL, 'Đây là lần đầu tiên tôi đến bờ biển.', '{"wordId":"first","ukIpa":"/fɜːst/","usIpa":"/fɝːst/","cefr":"A1","topic":"daily","senses":[{"pos":"num.","en":"coming before all others in order or time","vi":"thứ nhất; đầu tiên"},{"pos":"adv.","en":"before anything or anyone else","vi":"trước tiên; đầu tiên; trước hết"}],"examples":[{"en":"This is my first visit to the seaside.","vi":"Đây là lần đầu tiên tôi đến bờ biển.","audioKind":"ex"},{"en":"Governments should first improve public transport before encouraging residents to give up private cars.","vi":"Chính phủ nên cải thiện giao thông công cộng trước khi khuyến khích người dân từ bỏ xe hơi cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"first place","vi":"vị trí thứ nhất"},{"en":"at first","vi":"lúc đầu"},{"en":"first of all","vi":"trước hết"},{"en":"first aid","vi":"sơ cứu"}],"wordFamily":[],"synonyms":[],"antonyms":["last"],"tipVi":"at first có nghĩa là ban đầu; first có thể dùng để liệt kê ý đầu tiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_busy', 'en-a1-30', 'busy', '/ˈbɪzi/', 'A1', 'bận rộn; bận rộn; nhộn nhịp; tấp nập; đang bận (đường dây điện thoại)', 'adj.', 'busily (adv.), busyness (n.)', 'Đồng nghĩa: occupied, hectic · Trái nghĩa: idle, quiet', 'Dùng cấu trúc busy doing hoặc busy with, không dùng busy to do.', 'I am busy making soup for dinner right now.', NULL, 'Bây giờ tôi đang bận nấu súp cho bữa tối.', '{"wordId":"busy","ukIpa":"/ˈbɪzi/","usIpa":"/ˈbɪzi/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Having many things to do or being actively occupied.","vi":"bận rộn"},{"pos":"adj.","en":"Full of people, traffic, or activity.","vi":"bận rộn; nhộn nhịp; tấp nập"},{"pos":"adj.","en":"Already being used, especially a telephone line.","vi":"đang bận (đường dây điện thoại)"}],"examples":[{"en":"I am busy making soup for dinner right now.","vi":"Bây giờ tôi đang bận nấu súp cho bữa tối.","audioKind":"ex"},{"en":"Busy urban roads can discourage cycling unless local authorities provide safe routes separated from motor traffic.","vi":"Các con đường đô thị đông đúc có thể làm nản lòng việc đi xe đạp trừ khi cơ quan chức năng cung cấp các tuyến đường an toàn tách biệt với xe cơ giới.","audioKind":"ex2"}],"collocations":[{"en":"busy doing something","vi":"bận làm gì đó"},{"en":"busy with work","vi":"bận rộn với công việc"},{"en":"a busy street","vi":"một con đường tấp nập"},{"en":"a busy schedule","vi":"lịch trình bận rộn"}],"wordFamily":["busily (adv.)","busyness (n.)"],"synonyms":["occupied","hectic"],"antonyms":["idle","quiet"],"tipVi":"Dùng cấu trúc busy doing hoặc busy with, không dùng busy to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wine', 'en-a1-30', 'wine', '/waɪn/', 'A1', 'n. rượu vang; rượu nho', 'n.', 'winemaker (n.), winemaking (n.)', NULL, 'Là danh từ không đếm được khi chỉ chung rượu vang; dùng wines khi chỉ các loại rượu vang khác nhau.', 'The restaurant uses a little wine in this mushroom sauce.', NULL, 'Nhà hàng cho một chút rượu vang vào món sốt nấm này.', '{"wordId":"wine","ukIpa":"/waɪn/","usIpa":"/waɪn/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"An alcoholic drink usually made from fermented grapes","vi":"n. rượu vang; rượu nho"}],"examples":[{"en":"The restaurant uses a little wine in this mushroom sauce.","vi":"Nhà hàng cho một chút rượu vang vào món sốt nấm này.","audioKind":"ex"},{"en":"Climate change is affecting wine production as rising temperatures alter grape quality and harvest times.","vi":"Biến đổi khí hậu đang ảnh hưởng đến việc sản xuất rượu vang do nhiệt độ tăng làm thay đổi chất lượng nho và thời điểm thu hoạch.","audioKind":"ex2"}],"collocations":[{"en":"red wine","vi":"rượu vang đỏ"},{"en":"white wine","vi":"rượu vang trắng"},{"en":"wine production","vi":"sản xuất rượu vang"},{"en":"a bottle of wine","vi":"một chai rượu vang"}],"wordFamily":["winemaker (n.)","winemaking (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được khi chỉ chung rượu vang; dùng wines khi chỉ các loại rượu vang khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_talk', 'en-a1-30', 'talk', '/tɔːk/', 'A1', 'v. nói chuyện; trò chuyện; bàn luận; n. cuộc trò chuyện; cuộc trao đổi; n. bài phát biểu; bài diễn thuyết', 'v.', 'talker (n.), talkative (adj.)', 'Đồng nghĩa: speak, converse', 'talk about đi với chủ đề; talk to hoặc talk with đi với người.', 'We talked about our weekend plans over breakfast.', NULL, 'Chúng tôi đã trò chuyện về kế hoạch cuối tuần trong lúc ăn sáng.', '{"wordId":"talk","ukIpa":"/tɔːk/","usIpa":"/tɔːk/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to speak to someone or discuss something","vi":"v. nói chuyện; trò chuyện; bàn luận"},{"pos":"n.","en":"a conversation or discussion between people","vi":"n. cuộc trò chuyện; cuộc trao đổi"},{"pos":"n.","en":"a speech given to an audience about a subject","vi":"n. bài phát biểu; bài diễn thuyết"}],"examples":[{"en":"We talked about our weekend plans over breakfast.","vi":"Chúng tôi đã trò chuyện về kế hoạch cuối tuần trong lúc ăn sáng.","audioKind":"ex"},{"en":"Schools should encourage students to talk openly about stress and seek support when they need it.","vi":"Nhà trường nên khuyến khích học sinh cởi mở chia sẻ về áp lực và tìm kiếm sự hỗ trợ khi cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"talk about something","vi":"bàn về điều gì đó"},{"en":"talk to someone","vi":"nói chuyện với ai đó"},{"en":"give a talk","vi":"thuyết trình; phát biểu"},{"en":"hold talks","vi":"tiến hành đàm phán"}],"wordFamily":["talker (n.)","talkative (adj.)"],"synonyms":["speak","converse"],"antonyms":[],"tipVi":"talk about đi với chủ đề; talk to hoặc talk with đi với người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pants', 'en-a1-30', 'pants', '/pænts/', 'A1', 'n. quần dài (Mỹ); n. quần lót (Anh)', 'n.', NULL, NULL, 'Tiếng Mỹ chỉ quần dài, tiếng Anh-Anh thường chỉ quần lót; đi với a pair of khi đếm.', 'These pants have deep pockets for my keys.', NULL, 'Chiếc quần này có túi sâu để đựng chìa khóa của tôi.', '{"wordId":"pants","ukIpa":"/pænts/","usIpa":"/pænts/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"Clothing covering the legs separately, from the waist down.","vi":"n. quần dài (Mỹ)"},{"pos":"n.","en":"Underwear worn around the hips and bottom.","vi":"n. quần lót (Anh)"}],"examples":[{"en":"These pants have deep pockets for my keys.","vi":"Chiếc quần này có túi sâu để đựng chìa khóa của tôi.","audioKind":"ex"},{"en":"Some schools allow students to wear comfortable pants rather than requiring a traditional formal uniform.","vi":"Một số trường học cho phép học sinh mặc quần dài thoải mái thay vì bắt buộc mặc đồng phục trang trọng truyền thống.","audioKind":"ex2"}],"collocations":[{"en":"a pair of pants","vi":"một chiếc quần"},{"en":"loose pants","vi":"quần ống rộng"},{"en":"underpants","vi":"quần lót"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Mỹ chỉ quần dài, tiếng Anh-Anh thường chỉ quần lót; đi với a pair of khi đếm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_very', 'en-a1-30', 'very', '/ˈveri/', 'A1', 'rất; lắm; chính; đúng là (nhấn mạnh chính xác người, vật hoặc thời điểm)', 'adv.', NULL, NULL, 'very thường bổ nghĩa cho tính từ hoặc trạng từ; khi bổ nghĩa cho động từ thường dùng very much.', 'The soup is very hot, so let it cool.', NULL, 'Món súp rất nóng, hãy để nó nguội bớt đã.', '{"wordId":"very","ukIpa":"/ˈveri/","usIpa":"/ˈveri/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"Used to make an adjective or adverb stronger.","vi":"rất; lắm"},{"pos":"adj.","en":"Used to emphasize an exact person, thing, place, or time.","vi":"chính; đúng là (nhấn mạnh chính xác người, vật hoặc thời điểm)"}],"examples":[{"en":"The soup is very hot, so let it cool.","vi":"Món súp rất nóng, hãy để nó nguội bớt đã.","audioKind":"ex"},{"en":"Reliable public transport is very important for residents who cannot afford to own a car.","vi":"Hệ thống giao thông công cộng đáng tin cậy rất quan trọng đối với những cư dân không đủ khả năng mua ô tô.","audioKind":"ex2"}],"collocations":[{"en":"very important","vi":"rất quan trọng"},{"en":"very carefully","vi":"rất cẩn thận"},{"en":"the very beginning","vi":"ngay từ đầu; lúc ban đầu"},{"en":"the very same","vi":"chính cái đó; hoàn toàn giống nhau"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"very thường bổ nghĩa cho tính từ hoặc trạng từ; khi bổ nghĩa cho động từ thường dùng very much.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_more', 'en-a1-30', 'more', '/mɔːr/', 'A1', 'nhiều hơn; thêm; hơn; càng; thêm nữa; số lượng lớn hơn', 'det.', NULL, 'Trái nghĩa: less, fewer', 'Có thể bổ nghĩa cho cả danh từ đếm được và không đếm được; đây là dạng so sánh hơn của many và much.', 'Could you add more rice to my bowl, please?', NULL, 'Bạn có thể múc thêm cơm vào bát giúp tôi được không?', '{"wordId":"more","ukIpa":"/mɔː/","usIpa":"/mɔːr/","cefr":"A1","topic":"daily","senses":[{"pos":"det.","en":"A greater or additional amount or number of something.","vi":"nhiều hơn; thêm"},{"pos":"adv.","en":"To a greater degree or extent.","vi":"hơn; càng"},{"pos":"pron.","en":"A greater or additional amount or number.","vi":"thêm nữa; số lượng lớn hơn"}],"examples":[{"en":"Could you add more rice to my bowl, please?","vi":"Bạn có thể múc thêm cơm vào bát giúp tôi được không?","audioKind":"ex"},{"en":"Governments should invest more resources in preventive healthcare to reduce pressure on hospitals in the long term.","vi":"Chính phủ nên đầu tư nhiều nguồn lực hơn vào việc chăm sóc sức khỏe dự phòng để giảm bớt áp lực cho các bệnh viện về lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"more than","vi":"hơn; nhiều hơn"},{"en":"more and more","vi":"ngày càng nhiều"},{"en":"more likely","vi":"có nhiều khả năng hơn"},{"en":"more information","vi":"thêm thông tin"}],"wordFamily":[],"synonyms":[],"antonyms":["less","fewer"],"tipVi":"Có thể bổ nghĩa cho cả danh từ đếm được và không đếm được; đây là dạng so sánh hơn của many và much.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_home', 'en-a1-30', 'home', '/hoʊm/', 'A1', 'nhà; tổ ấm; quê hương; về nhà; ở nhà; thuộc về nhà; trong nước', 'n.', 'homeless (adj.), homely (adj.), homeward (adv.)', NULL, 'home khi làm trạng từ thì không đi kèm giới từ to, ví dụ: go home.', 'We walked home together after dinner at the café.', NULL, 'Chúng tôi cùng nhau đi bộ về nhà sau bữa tối tại quán cà phê.', '{"wordId":"home","ukIpa":"/həʊm/","usIpa":"/hoʊm/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The place where someone lives or feels they belong.","vi":"nhà; tổ ấm; quê hương"},{"pos":"adv.","en":"At or towards the place where you live.","vi":"về nhà; ở nhà"},{"pos":"adj.","en":"Relating to your house or your own country.","vi":"thuộc về nhà; trong nước"}],"examples":[{"en":"We walked home together after dinner at the café.","vi":"Chúng tôi cùng nhau đi bộ về nhà sau bữa tối tại quán cà phê.","audioKind":"ex"},{"en":"Working from home can reduce commuting costs, but it may also limit social interaction among colleagues.","vi":"Làm việc tại nhà có thể giảm chi phí đi lại, nhưng nó cũng có thể hạn chế sự tương tác xã hội giữa các đồng nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"feel at home","vi":"cảm thấy thoải mái như ở nhà"},{"en":"return home","vi":"trở về nhà"},{"en":"home country","vi":"quê hương; đất nước"},{"en":"leave home","vi":"rời khỏi nhà"}],"wordFamily":["homeless (adj.)","homely (adj.)","homeward (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"home khi làm trạng từ thì không đi kèm giới từ to, ví dụ: go home.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_date', 'en-a1-30', 'date', '/deɪt/', 'A1', 'ngày tháng; cuộc hẹn hò; buổi hẹn; xác định niên đại; có từ thời', 'n.', 'dated (adj.), dating (n.)', NULL, 'date back to có nghĩa là bắt nguồn từ một thời kỳ nào đó và không dùng ở thể bị động.', 'Have you chosen a date for the picnic?', NULL, 'Bạn đã chọn được ngày cho buổi dã ngoại chưa?', '{"wordId":"date","ukIpa":"/deɪt/","usIpa":"/deɪt/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A particular day of a month or year.","vi":"ngày tháng"},{"pos":"n.","en":"An arranged meeting, especially with someone you find romantically attractive.","vi":"cuộc hẹn hò; buổi hẹn"},{"pos":"v.","en":"To establish something''s age, or originate in a particular period.","vi":"xác định niên đại; có từ thời"}],"examples":[{"en":"Have you chosen a date for the picnic?","vi":"Bạn đã chọn được ngày cho buổi dã ngoại chưa?","audioKind":"ex"},{"en":"Researchers used wooden tools found nearby to date the remains of this ancient village.","vi":"Các nhà nghiên cứu đã sử dụng các công cụ bằng gỗ tìm thấy ở gần đó để xác định niên đại của di tích ngôi làng cổ này.","audioKind":"ex2"}],"collocations":[{"en":"set a date","vi":"ấn định ngày tháng"},{"en":"go on a date","vi":"đi hẹn hò"},{"en":"date back to","vi":"có từ thời; bắt nguồn từ"},{"en":"expiry date","vi":"ngày hết hạn"}],"wordFamily":["dated (adj.)","dating (n.)"],"synonyms":[],"antonyms":[],"tipVi":"date back to có nghĩa là bắt nguồn từ một thời kỳ nào đó và không dùng ở thể bị động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_toilet', 'en-a1-30', 'toilet', '/ˈtɔɪlət/', 'A1', 'bồn cầu; bệ xí; phòng vệ sinh; nhà vệ sinh', 'n.', NULL, 'Đồng nghĩa: lavatory', 'Trong tiếng Anh Mỹ, toilet thường chỉ bồn cầu; khi hỏi về phòng vệ sinh công cộng, người ta thường dùng restroom.', 'The toilet upstairs keeps making a strange dripping sound.', NULL, 'Cái bồn cầu ở trên lầu cứ phát ra tiếng nhỏ giọt kỳ lạ.', '{"wordId":"toilet","ukIpa":"/ˈtɔɪlət/","usIpa":"/ˈtɔɪlət/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a bowl-shaped fixture used for getting rid of bodily waste","vi":"bồn cầu; bệ xí"},{"pos":"n.","en":"a room containing a toilet","vi":"phòng vệ sinh; nhà vệ sinh"}],"examples":[{"en":"The toilet upstairs keeps making a strange dripping sound.","vi":"Cái bồn cầu ở trên lầu cứ phát ra tiếng nhỏ giọt kỳ lạ.","audioKind":"ex"},{"en":"Access to clean public toilets is essential for protecting health and making urban spaces welcoming to everyone.","vi":"Việc tiếp cận các nhà vệ sinh công cộng sạch sẽ là điều thiết yếu để bảo vệ sức khỏe và làm cho không gian đô thị thân thiện với mọi người.","audioKind":"ex2"}],"collocations":[{"en":"flush the toilet","vi":"xả nước bồn cầu"},{"en":"public toilets","vi":"nhà vệ sinh công cộng"},{"en":"toilet paper","vi":"giấy vệ sinh"},{"en":"toilet seat","vi":"nắp bồn cầu"}],"wordFamily":[],"synonyms":["lavatory"],"antonyms":[],"tipVi":"Trong tiếng Anh Mỹ, toilet thường chỉ bồn cầu; khi hỏi về phòng vệ sinh công cộng, người ta thường dùng restroom.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grandmother', 'en-a1-30', 'grandmother', '/ˈɡrænmʌðər/', 'A1', 'bà (bà nội hoặc bà ngoại)', 'n.', 'grandfather (n.), grandparent (n.), grandchild (n.)', 'Đồng nghĩa: grandma, granny', 'Có thể dùng để chỉ cả bà nội hoặc bà ngoại; trong văn phong giao tiếp hàng ngày thường dùng grandma.', 'My grandmother grows fresh herbs on her kitchen windowsill.', NULL, 'Bà tôi trồng các loại thảo mộc tươi trên bệ cửa sổ nhà bếp.', '{"wordId":"grandmother","ukIpa":"/ˈɡrænmʌðə/","usIpa":"/ˈɡrænmʌðər/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The mother of your father or mother.","vi":"bà (bà nội hoặc bà ngoại)"}],"examples":[{"en":"My grandmother grows fresh herbs on her kitchen windowsill.","vi":"Bà tôi trồng các loại thảo mộc tươi trên bệ cửa sổ nhà bếp.","audioKind":"ex"},{"en":"For many working parents, a grandmother provides essential childcare and helps maintain strong family connections.","vi":"Đối với nhiều bậc cha mẹ đi làm, bà nội hoặc bà ngoại cung cấp sự hỗ trợ chăm sóc trẻ em thiết yếu và giúp duy trì mối quan hệ gia đình gắn kết.","audioKind":"ex2"}],"collocations":[{"en":"maternal grandmother","vi":"bà ngoại"},{"en":"paternal grandmother","vi":"bà nội"},{"en":"great-grandmother","vi":"bà cố; bà ngoại cố"}],"wordFamily":["grandfather (n.)","grandparent (n.)","grandchild (n.)"],"synonyms":["grandma","granny"],"antonyms":[],"tipVi":"Có thể dùng để chỉ cả bà nội hoặc bà ngoại; trong văn phong giao tiếp hàng ngày thường dùng grandma.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wall', 'en-a1-30', 'wall', '/wɔːl/', 'A1', 'tường; vách tường; bức tường; xây tường ngăn; vây quanh bằng tường', 'n.', 'walled (adj.)', NULL, 'Tranh treo trên bề mặt tường dùng giới từ on; vật được khảm chìm trong tường dùng in.', 'We hung a colourful painting on the kitchen wall.', NULL, 'Chúng tôi treo một bức tranh đầy màu sắc lên bức tường nhà bếp.', '{"wordId":"wall","ukIpa":"/wɔːl/","usIpa":"/wɔːl/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"An upright structure enclosing, dividing, or supporting a space.","vi":"tường; vách tường; bức tường"},{"pos":"v.","en":"To surround or separate an area with a wall.","vi":"xây tường ngăn; vây quanh bằng tường"}],"examples":[{"en":"We hung a colourful painting on the kitchen wall.","vi":"Chúng tôi treo một bức tranh đầy màu sắc lên bức tường nhà bếp.","audioKind":"ex"},{"en":"Green walls covered with plants can improve air quality and reduce heat in crowded urban areas.","vi":"Những bức tường xanh phủ đầy thực vật có thể cải thiện chất lượng không khí và giảm nhiệt độ ở những khu đô thị đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"stone wall","vi":"tường đá"},{"en":"boundary wall","vi":"tường ranh giới"},{"en":"wall off","vi":"chặn vách ngăn lại; xây tường cô lập"}],"wordFamily":["walled (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Tranh treo trên bề mặt tường dùng giới từ on; vật được khảm chìm trong tường dùng in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_some', 'en-a1-30', 'some', '/sʌm/', 'A1', 'một vài; một số; một ít; một vài người; một vài thứ; khoảng; độ chừng', 'det.', NULL, NULL, 'Có thể bổ nghĩa cho danh từ đếm được số nhiều hoặc danh từ không đếm được; khi phát âm ở dạng yếu thường là /səm/.', 'I bought some fresh bread on my way home.', NULL, 'Tôi đã mua một ít bánh mì tươi trên đường về nhà.', '{"wordId":"some","ukIpa":"/sʌm/","usIpa":"/sʌm/","cefr":"A1","topic":"daily","senses":[{"pos":"det.","en":"An unspecified amount or number of something.","vi":"một vài; một số; một ít"},{"pos":"pron.","en":"An unspecified number or amount of people or things.","vi":"một vài người; một vài thứ"},{"pos":"adv.","en":"Approximately, used before an amount or number.","vi":"khoảng; độ chừng"}],"examples":[{"en":"I bought some fresh bread on my way home.","vi":"Tôi đã mua một ít bánh mì tươi trên đường về nhà.","audioKind":"ex"},{"en":"Some residents support the proposed cycle lanes, while others worry about losing parking spaces.","vi":"Một số cư dân ủng hộ các làn đường dành cho xe đạp được đề xuất, trong khi những người khác lo ngại về việc mất đi các chỗ đỗ xe.","audioKind":"ex2"}],"collocations":[{"en":"some of","vi":"một số trong..."},{"en":"some time","vi":"một khoảng thời gian"},{"en":"some advice","vi":"một vài lời khuyên"},{"en":"some twenty years","vi":"khoảng hai mươi năm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Có thể bổ nghĩa cho danh từ đếm được số nhiều hoặc danh từ không đếm được; khi phát âm ở dạng yếu thường là /səm/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_which', 'en-a1-30', 'which', '/wɪtʃ/', 'A1', 'nào; cái nào; người nào; mà; điều mà', 'det.', NULL, NULL, 'which thường dùng cho sự lựa chọn trong một phạm vi giới hạn; what có phạm vi mở hơn.', 'Which jacket should I wear to dinner tonight?', NULL, 'Tối nay tôi nên mặc chiếc áo khoác nào đi ăn tối?', '{"wordId":"which","ukIpa":"/wɪtʃ/","usIpa":"/wɪtʃ/","cefr":"A1","topic":"daily","senses":[{"pos":"det.","en":"Used before a noun to ask about a limited choice.","vi":"nào"},{"pos":"pron.","en":"Used to ask about a choice without repeating the noun.","vi":"cái nào; người nào"},{"pos":"pron.","en":"Introduces information about a thing or a previous statement.","vi":"mà; điều mà"}],"examples":[{"en":"Which jacket should I wear to dinner tonight?","vi":"Tối nay tôi nên mặc chiếc áo khoác nào đi ăn tối?","audioKind":"ex"},{"en":"Governments must decide which policies will improve air quality without placing excessive financial pressure on households.","vi":"Chính phủ phải quyết định những chính sách nào sẽ cải thiện chất lượng không khí mà không gây áp lực tài chính quá lớn cho các hộ gia đình.","audioKind":"ex2"}],"collocations":[{"en":"which of","vi":"cái nào trong số"},{"en":"which one","vi":"chiếc nào"},{"en":"in which case","vi":"trong trường hợp đó"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"which thường dùng cho sự lựa chọn trong một phạm vi giới hạn; what có phạm vi mở hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_way', 'en-a1-30', 'way', '/weɪ/', 'A1', 'cách thức; phương pháp; đường đi; hướng đi; hơn hẳn; nhiều', 'n.', NULL, 'Đồng nghĩa: method, route', 'Cụm "làm gì đó" có thể dùng way to do hoặc way of doing.', 'Show me an easier way to fold this sheet.', NULL, 'Chỉ cho tôi cách gấp chiếc ga giường này sao cho dễ hơn đi.', '{"wordId":"way","ukIpa":"/weɪ/","usIpa":"/weɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A method of doing something.","vi":"cách thức; phương pháp"},{"pos":"n.","en":"A route or direction leading somewhere.","vi":"đường đi; hướng đi"},{"pos":"adv.","en":"By a large amount or distance.","vi":"hơn hẳn; nhiều"}],"examples":[{"en":"Show me an easier way to fold this sheet.","vi":"Chỉ cho tôi cách gấp chiếc ga giường này sao cho dễ hơn đi.","audioKind":"ex"},{"en":"Improving public transport is an effective way to reduce traffic congestion and urban air pollution.","vi":"Cải thiện giao thông công cộng là một cách hiệu quả để giảm thiểu tình trạng tắc nghẽn giao thông và ô nhiễm không khí đô thị.","audioKind":"ex2"}],"collocations":[{"en":"an effective way","vi":"một cách hiệu quả"},{"en":"find a way","vi":"tìm cách"},{"en":"on the way","vi":"đang trên đường"},{"en":"way too expensive","vi":"đắt hơn nhiều"}],"wordFamily":[],"synonyms":["method","route"],"antonyms":[],"tipVi":"Cụm \"làm gì đó\" có thể dùng way to do hoặc way of doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_arm', 'en-a1-30', 'arm', '/ɑːrm/', 'A1', 'cánh tay; tay vịn; trang bị vũ khí; cung cấp công cụ', 'n.', 'armed (adj.), unarmed (adj.)', NULL, 'Chỉ vũ khí dùng số nhiều arms; arm cũng có thể là động từ.', 'She carried the sleeping baby gently in her arms.', NULL, 'Cô ấy nhẹ nhàng bế đứa bé đang ngủ trong vòng tay.', '{"wordId":"arm","ukIpa":"/ɑːm/","usIpa":"/ɑːrm/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"The body part connecting your shoulder to your hand.","vi":"cánh tay"},{"pos":"n.","en":"A projecting part of an object, especially a chair.","vi":"tay vịn"},{"pos":"v.","en":"To provide weapons or useful tools for a task.","vi":"trang bị vũ khí; cung cấp công cụ"}],"examples":[{"en":"She carried the sleeping baby gently in her arms.","vi":"Cô ấy nhẹ nhàng bế đứa bé đang ngủ trong vòng tay.","audioKind":"ex"},{"en":"Schools should arm students with practical skills that help them adapt to a rapidly changing workplace.","vi":"Nhà trường nên trang bị cho học sinh những kỹ năng thực tế giúp các em thích nghi với môi trường làm việc thay đổi nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"fold your arms","vi":"khoanh tay"},{"en":"a chair arm","vi":"tay vịn ghế"},{"en":"arm someone with knowledge","vi":"trang bị cho ai đó kiến thức"}],"wordFamily":["armed (adj.)","unarmed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ vũ khí dùng số nhiều arms; arm cũng có thể là động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_next', 'en-a1-30', 'next', '/nekst/', 'A1', 'tiếp theo; sau; tiếp tục; lần sau', 'adj.', NULL, 'Đồng nghĩa: following · Trái nghĩa: previous', 'Nói "tuần tới" dùng next week, không kèm the; the next week chỉ tuần ngay sau đó.', 'Our next bus leaves in about ten minutes.', NULL, 'Chuyến xe buýt tiếp theo của chúng ta sẽ khởi hành sau khoảng mười phút nữa.', '{"wordId":"next","ukIpa":"/nekst/","usIpa":"/nekst/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"coming immediately after the present one","vi":"tiếp theo; sau"},{"pos":"adv.","en":"immediately after this; on the following occasion","vi":"tiếp tục; lần sau"}],"examples":[{"en":"Our next bus leaves in about ten minutes.","vi":"Chuyến xe buýt tiếp theo của chúng ta sẽ khởi hành sau khoảng mười phút nữa.","audioKind":"ex"},{"en":"Over the next decade, governments will need to invest more heavily in affordable public transport.","vi":"Trong thập kỷ tới, các chính phủ sẽ cần đầu tư mạnh mẽ hơn vào các phương tiện giao thông công cộng giá cả phải chăng.","audioKind":"ex2"}],"collocations":[{"en":"next week","vi":"tuần tới"},{"en":"the next step","vi":"bước tiếp theo"},{"en":"next time","vi":"lần sau"},{"en":"next to","vi":"bên cạnh; sát cạnh"}],"wordFamily":[],"synonyms":["following"],"antonyms":["previous"],"tipVi":"Nói \"tuần tới\" dùng next week, không kèm the; the next week chỉ tuần ngay sau đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bookstore', 'en-a1-30', 'bookstore', '/ˈbʊkstɔːr/', 'A1', 'tiệm sách; hiệu sách', 'n.', 'book (n.), bookseller (n.), bookselling (n.)', 'Đồng nghĩa: bookshop', 'bookstore là từ thông dụng trong tiếng Anh-Mỹ, không phải thư viện (library) dùng để mượn sách.', 'The bookstore near my flat stays open until nine.', NULL, 'Hiệu sách gần căn hộ của tôi mở cửa đến tận chín giờ tối.', '{"wordId":"bookstore","ukIpa":"/ˈbʊkstɔː/","usIpa":"/ˈbʊkstɔːr/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a store that sells books","vi":"tiệm sách; hiệu sách"}],"examples":[{"en":"The bookstore near my flat stays open until nine.","vi":"Hiệu sách gần căn hộ của tôi mở cửa đến tận chín giờ tối.","audioKind":"ex"},{"en":"Although online shopping offers convenience, a physical bookstore allows customers to browse and receive personal recommendations.","vi":"Mặc dù mua sắm trực tuyến mang lại sự tiện lợi, nhưng hiệu sách truyền thống cho phép khách hàng tự tay lật giở sách và nhận được các gợi ý cá nhân hóa.","audioKind":"ex2"}],"collocations":[{"en":"online bookstore","vi":"tiệm sách trực tuyến"},{"en":"campus bookstore","vi":"tiệm sách trong khuôn viên trường"},{"en":"used bookstore","vi":"tiệm sách cũ"}],"wordFamily":["book (n.)","bookseller (n.)","bookselling (n.)"],"synonyms":["bookshop"],"antonyms":[],"tipVi":"bookstore là từ thông dụng trong tiếng Anh-Mỹ, không phải thư viện (library) dùng để mượn sách.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_young', 'en-a1-30', 'young', '/jʌŋ/', 'A1', 'trẻ; trẻ tuổi; non trẻ; con non; thú con', 'adj.', 'youth (n.), youngster (n.)', 'Đồng nghĩa: youthful · Trái nghĩa: old', 'the young chỉ nhóm người trẻ tuổi; từ young cũng có thể dùng để chỉ động vật non.', 'A young kitten fell asleep inside my empty shoe.', NULL, 'Một chú mèo con non nớt đã ngủ thiếp đi bên trong chiếc giày trống của tôi.', '{"wordId":"young","ukIpa":"/jʌŋ/","usIpa":"/jʌŋ/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Having lived or existed for only a short time","vi":"trẻ; trẻ tuổi; non trẻ"},{"pos":"n.","en":"The babies of an animal","vi":"con non; thú con"}],"examples":[{"en":"A young kitten fell asleep inside my empty shoe.","vi":"Một chú mèo con non nớt đã ngủ thiếp đi bên trong chiếc giày trống của tôi.","audioKind":"ex"},{"en":"Young people need affordable housing and stable employment to build independent lives in large cities.","vi":"Giới trẻ cần có nhà ở giá cả phải chăng và việc làm ổn định để xây dựng cuộc sống độc lập tại các thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"young people","vi":"giới trẻ"},{"en":"young children","vi":"trẻ nhỏ"},{"en":"from a young age","vi":"từ khi còn nhỏ"},{"en":"raise their young","vi":"nuôi dưỡng con non"}],"wordFamily":["youth (n.)","youngster (n.)"],"synonyms":["youthful"],"antonyms":["old"],"tipVi":"the young chỉ nhóm người trẻ tuổi; từ young cũng có thể dùng để chỉ động vật non.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_30_1', 'en-a1-30', 'Cách dùng “some” (det.) — một vài; một số; một ít', 'some of  ·  some time  ·  some advice', 'Có thể bổ nghĩa cho danh từ đếm được số nhiều hoặc danh từ không đếm được; khi phát âm ở dạng yếu thường là /səm/.', NULL, '[{"hanzi":"I bought some fresh bread on my way home.","pinyin":"","meaning":"Tôi đã mua một ít bánh mì tươi trên đường về nhà."},{"hanzi":"Some residents support the proposed cycle lanes, while others worry about losing parking spaces.","pinyin":"","meaning":"Một số cư dân ủng hộ các làn đường dành cho xe đạp được đề xuất, trong khi những người khác lo ngại về việc mất đi các chỗ đỗ xe."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_30_2', 'en-a1-30', 'Cách dùng “toilet” (n.) — bồn cầu; bệ xí', 'flush the toilet  ·  public toilets  ·  toilet paper', 'Trong tiếng Anh Mỹ, toilet thường chỉ bồn cầu; khi hỏi về phòng vệ sinh công cộng, người ta thường dùng restroom.', 'Đồng nghĩa: lavatory', '[{"hanzi":"The toilet upstairs keeps making a strange dripping sound.","pinyin":"","meaning":"Cái bồn cầu ở trên lầu cứ phát ra tiếng nhỏ giọt kỳ lạ."},{"hanzi":"Access to clean public toilets is essential for protecting health and making urban spaces welcoming to everyone.","pinyin":"","meaning":"Việc tiếp cận các nhà vệ sinh công cộng sạch sẽ là điều thiết yếu để bảo vệ sức khỏe và làm cho không gian đô thị thân thiện với mọi người."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_30_3', 'en-a1-30', 'Cách dùng “light” (n.) — ánh sáng; đèn', 'natural light  ·  turn on the light  ·  light a candle', 'Danh từ chỉ ánh sáng thường không đếm được; một chiếc đèn dùng a light; động từ quá khứ thường dùng lit.', 'Họ từ (Word Family): lighting (n.), lightness (n.), lightly (adv.), lighten (v.) | Trái nghĩa: dark, heavy', '[{"hanzi":"Warm light came through the curtains into our bedroom.","pinyin":"","meaning":"Ánh sáng ấm áp chiếu qua rèm cửa vào phòng ngủ của chúng tôi."},{"hanzi":"Access to natural light in classrooms may improve students'' concentration and reduce electricity consumption.","pinyin":"","meaning":"Việc tiếp cận ánh sáng tự nhiên trong lớp học có thể nâng cao sự tập trung của học sinh và giảm lượng điện tiêu thụ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_30_4', 'en-a1-30', 'Cách dùng “more” (det.) — nhiều hơn; thêm', 'more than  ·  more and more  ·  more likely', 'Có thể bổ nghĩa cho cả danh từ đếm được và không đếm được; đây là dạng so sánh hơn của many và much.', 'Trái nghĩa: less, fewer', '[{"hanzi":"Could you add more rice to my bowl, please?","pinyin":"","meaning":"Bạn có thể múc thêm cơm vào bát giúp tôi được không?"},{"hanzi":"Governments should invest more resources in preventive healthcare to reduce pressure on hospitals in the long term.","pinyin":"","meaning":"Chính phủ nên đầu tư nhiều nguồn lực hơn vào việc chăm sóc sức khỏe dự phòng để giảm bớt áp lực cho các bệnh viện về lâu dài."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
