INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_30_1_1', 'en-a1-30', 'ten_30_1', 'listening', 'listening', 'Please say your name again so I can remember it.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đi bộ đến tiệm bánh vào mỗi sáng Chủ nhật.","Hôm nay chúng tôi đã mua rất nhiều trái cây tươi.","Xin vui lòng nói lại tên của bạn để tôi có thể ghi nhớ.","Cô ấy làm hướng dẫn viên tại bảo tàng địa phương."]'::jsonb, 2, 'Please say your name again so I can remember it. → Xin vui lòng nói lại tên của bạn để tôi có thể ghi nhớ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
