INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_30_2', 'en-a1-30', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_30_2_1', 'ten_30_2', 'say', 'Residents should have a say in planning decisions that directly affect their neighbourhoods and daily lives.', 'Residents should have a say in planning decisions that directly affect their neighbourhoods and daily lives.', '/seɪ/', 'Cư dân nên có tiếng nói trong các quyết định quy hoạch ảnh hưởng trực tiếp đến khu1 phố và đời sống hàng ngày của họ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_30_2_2', 'ten_30_2', 'lot', 'Cities can save a lot of energy by improving public transport and encouraging residents to walk.', 'Cities can save a lot of energy by improving public transport and encouraging residents to walk.', '/lɑːt/', 'Các thành phố có thể tiết kiệm rất nhiều năng lượng bằng cách cải thiện giao thông công cộng và khuyến khích người dân đi bộ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_30_2_3', 'ten_30_2', 'find', 'Many students find online courses convenient, although some struggle to stay motivated without classroom interaction.', 'Many students find online courses convenient, although some struggle to stay motivated without classroom interaction.', '/faɪnd/', 'Nhiều sinh viên thấy các khóa học trực tuyến rất tiện lợi, mặc dù một số người gặp khó khăn trong việc duy trì động lực khi thiếu sự tương tác trên lớp.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_30_2_4', 'ten_30_2', 'walk', 'Safe pavements and attractive public spaces encourage residents to walk rather than drive for short journeys.', 'Safe pavements and attractive public spaces encourage residents to walk rather than drive for short journeys.', '/wɔːk/', 'Lối đi bộ an toàn và không gian công cộng hấp dẫn khuyến khích người dân đi bộ thay vì lái xe cho những chuyến đi ngắn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_30_2_5', 'ten_30_2', 'as', 'As public transport becomes more reliable, fewer commuters may choose to drive to work.', 'As public transport becomes more reliable, fewer commuters may choose to drive to work.', '/əz/', 'Khi giao thông công cộng trở nên đáng tin cậy hơn, ít người đi làm hơn có thể chọn lái xe đi làm.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_30_2_6', 'ten_30_2', 'run', 'Local councils often run training programmes to help unemployed residents develop skills needed by employers.', 'Local councils often run training programmes to help unemployed residents develop skills needed by employers.', '/rʌn/', 'Các hội đồng địa phương thường tổ chức các chương trình đào tạo để giúp cư dân thất nghiệp phát triển các kỹ năng mà nhà tuyển dụng cần.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_30_2_1', 'en-a1-30', 'ten_30_2', 'listening', 'listening', 'Residents should have a say in planning decisions that directly affect their neighbourhoods and daily lives.', NULL, 'Trong câu vừa nghe, từ “say” mang nghĩa nào sau đây?', '["nói; phát biểu bằng lời","cái túi; cái cặp; bao","quần dài","con khỉ"]'::jsonb, 0, '“say” (/seɪ/): nói; phát biểu bằng lời. Câu đầy đủ: Residents should have a say in planning decisions that directly affect their neighbourhoods and daily lives.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_30_2_2', 'en-a1-30', 'ten_30_2', 'listening', 'listening', 'Cities can save a lot of energy by improving public transport and encouraging residents to walk.', NULL, 'Trong câu vừa nghe, từ “lot” mang nghĩa nào sau đây?', '["phút; chốc lát","giá cả; giá tiền","tháng Tám","nhiều; một lượng lớn"]'::jsonb, 3, '“lot” (/lɑːt/): nhiều; một lượng lớn. Câu đầy đủ: Cities can save a lot of energy by improving public transport and encouraging residents to walk.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
