INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_30_6', 'en-a1-30', NULL, 'comprehensive_test', 'listening', 'We ran through the park before breakfast today.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hôm nay chúng tôi đã chạy qua công viên trước bữa sáng.","Chỉ cho tôi cách gấp chiếc ga giường này sao cho dễ hơn đi.","Hôm nay chúng tôi đã mua rất nhiều trái cây tươi.","Đây là lần đầu tiên tôi đến bờ biển."]'::jsonb, 0, 'We ran through the park before breakfast today. → Hôm nay chúng tôi đã chạy qua công viên trước bữa sáng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
