INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_30_8', 'en-a1-30', NULL, 'comprehensive_test', 'listening', 'Look at the tiny bird beside the window.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy nhẹ nhàng bế đứa bé đang ngủ trong vòng tay.","Chỉ cho tôi cách gấp chiếc ga giường này sao cho dễ hơn đi.","Nhà hàng cho một chút rượu vang vào món sốt nấm này.","Hãy nhìn con chim nhỏ bên cửa sổ kìa."]'::jsonb, 3, 'Look at the tiny bird beside the window. → Hãy nhìn con chim nhỏ bên cửa sổ kìa.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
