INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_30_18', 'en-a1-30', NULL, 'comprehensive_test', 'reading', NULL, 'Residents should have a say in planning decisions that directly affect their neighbourhoods and daily lives.', 'Dựa vào câu trên, từ “say” có nghĩa phù hợp nhất là gì?', '["nói; phát biểu bằng lời","đội; nhóm","màu vàng","sống; cư trú; tồn tại"]'::jsonb, 0, 'say: nói; phát biểu bằng lời; ghi rõ; thể hiện qua văn bản hoặc bằng chứng khác; quyền lên tiếng; quyền quyết định. Dịch cả câu: Cư dân nên có tiếng nói trong các quyết định quy hoạch ảnh hưởng trực tiếp đến khu1 phố và đời sống hàng ngày của họ.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_30_19', 'en-a1-30', NULL, 'comprehensive_test', 'reading', NULL, 'Cities can save a lot of energy by improving public transport and encouraging residents to walk.', 'Dựa vào câu trên, từ “lot” có nghĩa phù hợp nhất là gì?', '["n. bạn; bạn bè; chiến hữu","nhiều; một lượng lớn","rơi; ngã; giảm","thân yêu; quý giá; được trân trọng"]'::jsonb, 1, 'lot: nhiều; một lượng lớn; rất nhiều; thường xuyên; một mảnh đất dùng cho mục đích cụ thể. Dịch cả câu: Các thành phố có thể tiết kiệm rất nhiều năng lượng bằng cách cải thiện giao thông công cộng và khuyến khích người dân đi bộ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_30_20', 'en-a1-30', NULL, 'comprehensive_test', 'reading', NULL, 'Many students find online courses convenient, although some struggle to stay motivated without classroom interaction.', 'Dựa vào câu trên, từ “find” có nghĩa phù hợp nhất là gì?', '["áo len; áo chui đầu bằng len","đặc biệt; khác thường","tìm thấy; tìm ra","mạng internet; mạng toàn cầu"]'::jsonb, 2, 'find: tìm thấy; tìm ra; cảm thấy; cho là; nhận thấy; vật tìm được; phát hiện quý giá. Dịch cả câu: Nhiều sinh viên thấy các khóa học trực tuyến rất tiện lợi, mặc dù một số người gặp khó khăn trong việc duy trì động lực khi thiếu sự tương tác trên lớp.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_30_21', 'en-a1-30', NULL, 'comprehensive_test', 'reading', NULL, 'Safe pavements and attractive public spaces encourage residents to walk rather than drive for short journeys.', 'Dựa vào câu trên, từ “walk” có nghĩa phù hợp nhất là gì?', '["đi bộ","ngân hàng, tổ chức tài chính giữ tiền và cung cấp dịch vụ tài chính","chị gái; em gái","người mới bắt đầu; người mới học"]'::jsonb, 0, 'walk: đi bộ; chuyến đi bộ; cuộc dạo chơi. Dịch cả câu: Lối đi bộ an toàn và không gian công cộng hấp dẫn khuyến khích người dân đi bộ thay vì lái xe cho những chuyến đi ngắn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_30_22', 'en-a1-30', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tiếp theo; sau”', '["next","kind","good","by"]'::jsonb, 0, 'tiếp theo; sau → next (/nekst/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_30_23', 'en-a1-30', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tiệm sách; hiệu sách”', '["news","bookstore","both","sixteen"]'::jsonb, 1, 'tiệm sách; hiệu sách → bookstore (/ˈbʊkstɔːr/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
