INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a1-31', 'en', 'Bài 31: Đời sống hằng ngày (16) - CEFR A1', 'CEFR A1', 'A1 · Đời sống', '27 từ vựng Tiếng Anh CEFR A1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-25', 1031, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_photo', 'en-a1-31', 'photo', '/ˈfoʊtoʊ/', 'A1', 'bức ảnh; bức hình', 'n.', 'photograph (n.), photographer (n.), photography (n.), photographic (adj.)', 'Đồng nghĩa: photograph, picture', 'photo là dạng viết tắt phổ biến của photograph; dạng số nhiều là photos.', 'We took a photo beside the old bridge.', NULL, 'Chúng tôi đã chụp một bức ảnh ngay bên cạnh cây cầu cổ.', '{"wordId":"photo","ukIpa":"/ˈfəʊtəʊ/","usIpa":"/ˈfoʊtoʊ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A picture made using a camera.","vi":"bức ảnh; bức hình"}],"examples":[{"en":"We took a photo beside the old bridge.","vi":"Chúng tôi đã chụp một bức ảnh ngay bên cạnh cây cầu cổ.","audioKind":"ex"},{"en":"Historical photos provide valuable evidence of how urban landscapes and everyday lifestyles have changed over time.","vi":"Những bức ảnh lịch sử cung cấp bằng chứng quý giá về sự thay đổi của cảnh quan đô thị và lối sống đời thường qua thời gian.","audioKind":"ex2"}],"collocations":[{"en":"take a photo","vi":"chụp ảnh"},{"en":"a family photo","vi":"bức ảnh gia đình"},{"en":"a photo album","vi":"cuốn album ảnh"},{"en":"a photo of","vi":"bức ảnh chụp..."}],"wordFamily":["photograph (n.)","photographer (n.)","photography (n.)","photographic (adj.)"],"synonyms":["photograph","picture"],"antonyms":[],"tipVi":"photo là dạng viết tắt phổ biến của photograph; dạng số nhiều là photos.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_orange', 'en-a1-31', 'orange', '/ˈɔːrɪndʒ/', 'A1', 'quả cam; trái cam; màu cam', 'n.', NULL, NULL, 'Cam (quả) là danh từ đếm được; khi chỉ màu sắc thì thường không đếm được.', 'I peeled an orange and shared it with my sister.', NULL, 'Tôi đã bóc một quả cam và chia cho em gái mình.', '{"wordId":"orange","ukIpa":"/ˈɒrɪndʒ/","usIpa":"/ˈɔːrɪndʒ/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A round citrus fruit with orange skin and juicy flesh.","vi":"quả cam; trái cam"},{"pos":"adj.","en":"Having a colour between red and yellow.","vi":"màu cam"},{"pos":"n.","en":"The colour between red and yellow.","vi":"màu cam"}],"examples":[{"en":"I peeled an orange and shared it with my sister.","vi":"Tôi đã bóc một quả cam và chia cho em gái mình.","audioKind":"ex"},{"en":"An orange provides vitamin C, but a balanced diet requires a variety of foods.","vi":"Cam cung cấp vitamin C, nhưng một chế độ ăn uống cân bằng đòi hỏi sự đa dạng về thực phẩm.","audioKind":"ex2"}],"collocations":[{"en":"orange juice","vi":"nước cam"},{"en":"orange peel","vi":"vỏ cam"},{"en":"bright orange","vi":"màu cam sáng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cam (quả) là danh từ đếm được; khi chỉ màu sắc thì thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dining-room', 'en-a1-31', 'dining-room', '/ˈdaɪnɪŋ ruːm/', 'A1', 'phòng ăn; phòng ăn uống', 'n.', 'dine (v.), diner (n.), dining (n.)', NULL, 'Ngày nay từ này thường được viết tách thành dining room để chỉ căn phòng dùng cho việc ăn uống.', 'We put fresh flowers on the dining-room table.', NULL, 'Chúng tôi cắm những bông hoa tươi trên chiếc bàn ở phòng ăn.', '{"wordId":"dining-room","ukIpa":"/ˈdaɪnɪŋ ruːm/","usIpa":"/ˈdaɪnɪŋ ruːm/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A room where people eat meals.","vi":"phòng ăn; phòng ăn uống"}],"examples":[{"en":"We put fresh flowers on the dining-room table.","vi":"Chúng tôi cắm những bông hoa tươi trên chiếc bàn ở phòng ăn.","audioKind":"ex"},{"en":"A shared dining-room can encourage social interaction among older residents who might otherwise eat alone.","vi":"Một phòng ăn chung có thể thúc đẩy sự giao lưu xã hội giữa những cư dân cao tuổi, những người mà nếu không có thể sẽ phải ăn uống một mình.","audioKind":"ex2"}],"collocations":[{"en":"dining-room table","vi":"bàn ăn"},{"en":"dining-room furniture","vi":"đồ nội thất phòng ăn"},{"en":"a spacious dining-room","vi":"phòng ăn rộng rãi"}],"wordFamily":["dine (v.)","diner (n.)","dining (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Ngày nay từ này thường được viết tách thành dining room để chỉ căn phòng dùng cho việc ăn uống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_need', 'en-a1-31', 'need', '/niːd/', 'A1', 'cần; đòi hỏi; nhu cầu; sự cần thiết; cảnh ngộ khó khăn; sự túng thiếu', 'v.', 'needy (adj.), needless (adj.)', 'Đồng nghĩa: require', 'need to do mang nghĩa chủ động (cần làm gì); need doing mang nghĩa bị động (cần được làm gì).', 'These plants need more water during hot weather.', NULL, 'Những loại cây này cần nhiều nước hơn trong thời tiết nắng nóng.', '{"wordId":"need","ukIpa":"/niːd/","usIpa":"/niːd/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To require something because it is necessary or important","vi":"cần; đòi hỏi"},{"pos":"n.","en":"Something necessary or the condition of requiring it","vi":"nhu cầu; sự cần thiết"},{"pos":"n.","en":"A situation in which essential things are lacking","vi":"cảnh ngộ khó khăn; sự túng thiếu"}],"examples":[{"en":"These plants need more water during hot weather.","vi":"Những loại cây này cần nhiều nước hơn trong thời tiết nắng nóng.","audioKind":"ex"},{"en":"Cities need to improve public transport if they want to reduce dependence on private cars.","vi":"Các thành phố cần cải thiện giao thông công cộng nếu họ muốn giảm bớt sự phụ thuộc vào ô tô cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"need to do something","vi":"cần làm điều gì đó"},{"en":"meet basic needs","vi":"đáp ứng các nhu cầu cơ bản"},{"en":"in need","vi":"lâm vào cảnh khó khăn"},{"en":"an urgent need","vi":"nhu cầu cấp thiết"}],"wordFamily":["needy (adj.)","needless (adj.)"],"synonyms":["require"],"antonyms":[],"tipVi":"need to do mang nghĩa chủ động (cần làm gì); need doing mang nghĩa bị động (cần được làm gì).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hungry', 'en-a1-31', 'hungry', '/ˈhʌŋɡri/', 'A1', 'đói bụng; đói; khao khát; thèm muốn', 'adj.', 'hunger (n.), hunger (v.), hungrily (adv.)', 'Đồng nghĩa: ravenous, eager · Trái nghĩa: full', 'Cụm "hungry for" thường đi sau bởi một danh từ, mang nghĩa khao khát hoặc tha thiết muốn có được điều gì đó.', 'I felt hungry after our long walk by the river.', NULL, 'Tôi cảm thấy đói sau chuyến đi bộ dài dọc bờ sông.', '{"wordId":"hungry","ukIpa":"/ˈhʌŋɡri/","usIpa":"/ˈhʌŋɡri/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Feeling the need or desire to eat.","vi":"đói bụng; đói"},{"pos":"adj.","en":"Having a strong desire for something.","vi":"khao khát; thèm muốn"}],"examples":[{"en":"I felt hungry after our long walk by the river.","vi":"Tôi cảm thấy đói sau chuyến đi bộ dài dọc bờ sông.","audioKind":"ex"},{"en":"School meal programmes help hungry children concentrate in class and participate more actively in learning.","vi":"Các chương trình bữa ăn học đường giúp những trẻ em bị đói tập trung hơn trong lớp và tham gia học tập tích cực hơn.","audioKind":"ex2"}],"collocations":[{"en":"feel hungry","vi":"cảm thấy đói"},{"en":"go hungry","vi":"bị đói; chịu đói"},{"en":"hungry for success","vi":"khao khát thành công"}],"wordFamily":["hunger (n.)","hunger (v.)","hungrily (adv.)"],"synonyms":["ravenous","eager"],"antonyms":["full"],"tipVi":"Cụm \"hungry for\" thường đi sau bởi một danh từ, mang nghĩa khao khát hoặc tha thiết muốn có được điều gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ago', 'en-a1-31', 'ago', '/əˈɡoʊ/', 'A1', 'trước đây; cách đây', 'adv.', NULL, NULL, 'ago thường đứng sau cụm từ chỉ thời gian và đi kèm với thì quá khứ đơn.', 'I left my umbrella on the bus an hour ago.', NULL, 'Tôi để quên ô trên xe buýt cách đây một tiếng.', '{"wordId":"ago","ukIpa":"/əˈɡəʊ/","usIpa":"/əˈɡoʊ/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"Before the present time, following an expression of time","vi":"trước đây; cách đây"}],"examples":[{"en":"I left my umbrella on the bus an hour ago.","vi":"Tôi để quên ô trên xe buýt cách đây một tiếng.","audioKind":"ex"},{"en":"Many jobs that seemed secure a decade ago now require workers to develop new digital skills.","vi":"Nhiều công việc từng có vẻ ổn định một thập kỷ trước giờ đây đòi hỏi người lao động phải phát triển các kỹ năng số mới.","audioKind":"ex2"}],"collocations":[{"en":"a few days ago","vi":"vài ngày trước"},{"en":"a long time ago","vi":"cách đây rất lâu"},{"en":"not long ago","vi":"chưa lâu trước đây"},{"en":"as recently as a year ago","vi":"mới chỉ cách đây một năm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"ago thường đứng sau cụm từ chỉ thời gian và đi kèm với thì quá khứ đơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_over', 'en-a1-31', 'over', '/ˈoʊvər/', 'A1', 'ở phía trên; vượt qua; hơn; quá; kết thúc', 'prep.', NULL, 'Trái nghĩa: under', 'over có thể chỉ vị trí vượt qua hoặc mức độ lớn hơn; cấu trúc be over mang nghĩa là kết thúc.', 'A small bird flew over the garden wall.', NULL, 'Một chú chim nhỏ bay qua bức tường vườn.', '{"wordId":"over","ukIpa":"/ˈəʊvə/","usIpa":"/ˈoʊvər/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"above something or from one side to the other","vi":"ở phía trên; vượt qua"},{"pos":"prep.","en":"more than a particular amount, age, or level","vi":"hơn; quá"},{"pos":"adv.","en":"finished or no longer happening","vi":"kết thúc"}],"examples":[{"en":"A small bird flew over the garden wall.","vi":"Một chú chim nhỏ bay qua bức tường vườn.","audioKind":"ex"},{"en":"Over half of the residents surveyed supported plans to create more green spaces in their neighbourhood.","vi":"Hơn một nửa số cư dân được khảo sát ủng hộ các kế hoạch tạo thêm nhiều không gian xanh trong khu Neighborhood của họ.","audioKind":"ex2"}],"collocations":[{"en":"over the bridge","vi":"đi qua cầu"},{"en":"over half","vi":"hơn một nửa"},{"en":"be over","vi":"đã kết thúc"},{"en":"all over the world","vi":"trên toàn thế giới"}],"wordFamily":[],"synonyms":[],"antonyms":["under"],"tipVi":"over có thể chỉ vị trí vượt qua hoặc mức độ lớn hơn; cấu trúc be over mang nghĩa là kết thúc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_they', 'en-a1-31', 'they', '/ðeɪ/', 'A1', 'họ; bọn họ; chúng nó (dùng cho người hoặc vật đã được nhắc đến); họ (dùng cho một người không rõ giới tính hoặc có giới tính phi nhị nguyên)', 'pron.', 'them (pron.), their (det.), theirs (pron.), themselves (pron.)', NULL, 'Đại từ số ít they vẫn đi với are và have, không dùng is và has.', 'The children waved as they boarded the bus.', NULL, 'Lũ trẻ vẫy tay chào khi chúng lên xe buýt.', '{"wordId":"they","ukIpa":"/ðeɪ/","usIpa":"/ðeɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"pron.","en":"Used for people or things already mentioned or understood.","vi":"họ; bọn họ; chúng nó (dùng cho người hoặc vật đã được nhắc đến)"},{"pos":"pron.","en":"Used for someone of unknown or nonbinary gender.","vi":"họ (dùng cho một người không rõ giới tính hoặc có giới tính phi nhị nguyên)"}],"examples":[{"en":"The children waved as they boarded the bus.","vi":"Lũ trẻ vẫy tay chào khi chúng lên xe buýt.","audioKind":"ex"},{"en":"When a student receives constructive feedback, they are more likely to identify weaknesses and improve their performance.","vi":"Khi một học sinh nhận được phản hồi mang tính xây dựng, họ sẽ có nhiều khả năng nhận ra điểm yếu và cải thiện thành tích của mình hơn.","audioKind":"ex2"}],"collocations":[{"en":"they are","vi":"họ là"},{"en":"they have","vi":"họ có"},{"en":"they say","vi":"người ta nói rằng"}],"wordFamily":["them (pron.)","their (det.)","theirs (pron.)","themselves (pron.)"],"synonyms":[],"antonyms":[],"tipVi":"Đại từ số ít they vẫn đi với are và have, không dùng is và has.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_many', 'en-a1-31', 'many', '/ˈmeni/', 'A1', 'nhiều (dùng với danh từ đếm được số nhiều); nhiều người; nhiều vật', 'det.', NULL, 'Đồng nghĩa: numerous · Trái nghĩa: few', 'many đi với danh từ đếm được số nhiều; much đi với danh từ không đếm được.', 'How many apples do we need for the pie?', NULL, 'Chúng ta cần bao nhiêu quả táo để làm chiếc bánh?', '{"wordId":"many","ukIpa":"/ˈmeni/","usIpa":"/ˈmeni/","cefr":"A1","topic":"daily","senses":[{"pos":"det.","en":"a large number of, used with plural countable nouns","vi":"nhiều (dùng với danh từ đếm được số nhiều)"},{"pos":"pron.","en":"a large number of people or things","vi":"nhiều người; nhiều vật"}],"examples":[{"en":"How many apples do we need for the pie?","vi":"Chúng ta cần bao nhiêu quả táo để làm chiếc bánh?","audioKind":"ex"},{"en":"Many cities are investing in cycling infrastructure to reduce traffic congestion and improve public health.","vi":"Nhiều thành phố đang đầu tư vào cơ sở hạ tầng xe đạp để giảm ùn tắc giao thông và cải thiện sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"how many","vi":"bao nhiêu"},{"en":"too many","vi":"quá nhiều"},{"en":"many of","vi":"nhiều trong số"},{"en":"a great many","vi":"rất nhiều"}],"wordFamily":[],"synonyms":["numerous"],"antonyms":["few"],"tipVi":"many đi với danh từ đếm được số nhiều; much đi với danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cook', 'en-a1-31', 'cook', '/kʊk/', 'A1', 'nấu ăn; nấu; luộc; đầu bếp; người nấu ăn', 'v.', 'cooking (n.), cooker (n.), cooked (adj.)', NULL, 'cook có thể chỉ đầu bếp; cooker trong tiếng Anh-Anh chỉ cái bếp nấu.', 'I usually cook vegetable soup when the weather turns cold.', NULL, 'Tôi thường nấu súp rau củ khi trời chuyển lạnh.', '{"wordId":"cook","ukIpa":"/kʊk/","usIpa":"/kʊk/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to prepare food by heating it, or become ready through heating","vi":"nấu ăn; nấu; luộc"},{"pos":"n.","en":"someone who prepares and cooks food","vi":"đầu bếp; người nấu ăn"}],"examples":[{"en":"I usually cook vegetable soup when the weather turns cold.","vi":"Tôi thường nấu súp rau củ khi trời chuyển lạnh.","audioKind":"ex"},{"en":"Teaching children to cook simple meals can encourage healthier eating habits and greater independence later in life.","vi":"Dạy trẻ em nấu những món ăn đơn giản có thể khuyến khích thói quen ăn uống lành mạnh hơn và rèn luyện tính tự lập cao hơn trong tương lai.","audioKind":"ex2"}],"collocations":[{"en":"cook a meal","vi":"nấu một bữa ăn"},{"en":"cook from scratch","vi":"nấu từ nguyên liệu tươi; tự tay nấu từ đầu"},{"en":"a good cook","vi":"một đầu bếp giỏi"},{"en":"cook over low heat","vi":"nấu bằng lửa nhỏ"}],"wordFamily":["cooking (n.)","cooker (n.)","cooked (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"cook có thể chỉ đầu bếp; cooker trong tiếng Anh-Anh chỉ cái bếp nấu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_away', 'en-a1-31', 'away', '/əˈweɪ/', 'A1', 'rời xa; cách xa; ở một khoảng cách nhất định; đi vắng; không ở nhà', 'adv.', NULL, NULL, 'away là trạng từ; để diễn tả ý "rời xa khỏi nơi nào đó" thì dùng away from.', 'The little bird flew away when I opened the window.', NULL, 'Con chim nhỏ bay vụt đi khi tôi mở cửa sổ.', '{"wordId":"away","ukIpa":"/əˈweɪ/","usIpa":"/əˈweɪ/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"Moving or staying at a distance from someone or something.","vi":"rời xa; cách xa; ở một khoảng cách nhất định"},{"pos":"adv.","en":"Not at home or at the usual place.","vi":"đi vắng; không ở nhà"}],"examples":[{"en":"The little bird flew away when I opened the window.","vi":"Con chim nhỏ bay vụt đi khi tôi mở cửa sổ.","audioKind":"ex"},{"en":"Moving away from crowded cities can improve wellbeing, but may reduce access to employment.","vi":"Việc chuyển khỏi các thành phố đông đúc có thể cải thiện sức khỏe tinh thần, nhưng có thể làm giảm cơ hội việc làm.","audioKind":"ex2"}],"collocations":[{"en":"go away","vi":"rời đi; đi chỗ khác"},{"en":"far away","vi":"ở xa"},{"en":"away from home","vi":"đi vắng nhà"},{"en":"put away","vi":"cất đi; thu dọn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"away là trạng từ; để diễn tả ý \"rời xa khỏi nơi nào đó\" thì dùng away from.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_salad', 'en-a1-31', 'salad', '/ˈsæləd/', 'A1', 'món salad; rau trộn', 'n.', NULL, NULL, 'Có thể dùng như danh từ đếm được để chỉ một phần salad, hoặc danh từ không đếm được để chỉ món salad nói chung.', 'I added cucumber and tomatoes to the salad.', NULL, 'Tôi đã cho thêm dưa chuột và cà chua vào món salad.', '{"wordId":"salad","ukIpa":"/ˈsæləd/","usIpa":"/ˈsæləd/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"a cold dish of vegetables or other mixed ingredients","vi":"món salad; rau trộn"}],"examples":[{"en":"I added cucumber and tomatoes to the salad.","vi":"Tôi đã cho thêm dưa chuột và cà chua vào món salad.","audioKind":"ex"},{"en":"Offering fresh salad in school cafeterias can encourage children to eat a wider variety of vegetables.","vi":"Việc cung cấp salad tươi trong các căn tin trường học có thể khuyến khích trẻ em ăn nhiều loại rau củ hơn.","audioKind":"ex2"}],"collocations":[{"en":"green salad","vi":"salad rau xanh"},{"en":"fruit salad","vi":"salad hoa quả"},{"en":"salad dressing","vi":"nước sốt salad"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Có thể dùng như danh từ đếm được để chỉ một phần salad, hoặc danh từ không đếm được để chỉ món salad nói chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_out', 'en-a1-31', 'out', '/aʊt/', 'A1', 'ở ngoài; ra ngoài; vắng nhà; tắt; không còn cháy hay hoạt động; được công bố; xuất bản; ra mắt', 'adv.', NULL, 'Trái nghĩa: in', 'out thường đóng vai trò là trạng từ; khi chỉ vị trí ở bên ngoài một vật nào đó thì dùng outside.', 'We went out for a walk after dinner.', NULL, 'Chúng tôi đã ra ngoài đi dạo sau bữa tối.', '{"wordId":"out","ukIpa":"/aʊt/","usIpa":"/aʊt/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"Away from the inside of a place, or from home.","vi":"ở ngoài; ra ngoài; vắng nhà"},{"pos":"adv.","en":"No longer burning, shining, or working.","vi":"tắt; không còn cháy hay hoạt động"},{"pos":"adv.","en":"Available to the public or no longer secret.","vi":"được công bố; xuất bản; ra mắt"}],"examples":[{"en":"We went out for a walk after dinner.","vi":"Chúng tôi đã ra ngoài đi dạo sau bữa tối.","audioKind":"ex"},{"en":"When a new research report comes out, journalists should examine its evidence before reporting its conclusions.","vi":"Khi một báo cáo nghiên cứu mới ra mắt, các nhà báo nên xem xét các bằng chứng của nó trước khi đưa ra kết luận.","audioKind":"ex2"}],"collocations":[{"en":"go out","vi":"đi chơi; đi ra ngoài"},{"en":"eat out","vi":"ăn tiệm; ăn ngoài"},{"en":"come out","vi":"xuất bản; phát hành"},{"en":"put out a fire","vi":"dập tắt ngọn lửa"}],"wordFamily":[],"synonyms":[],"antonyms":["in"],"tipVi":"out thường đóng vai trò là trạng từ; khi chỉ vị trí ở bên ngoài một vật nào đó thì dùng outside.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_miss', 'en-a1-31', 'miss', '/mɪs/', 'A1', 'bỏ lỡ; trễ; nhớ nhung; bắn hụt; bỏ sót', 'v.', 'missing (adj.)', NULL, 'Sau miss đi trực tiếp với danh từ hoặc danh động từ, không dùng to do.', 'Hurry up, or we will miss the last bus.', NULL, 'Nhanh lên, nếu không chúng ta sẽ lỡ chuyến xe buýt cuối cùng.', '{"wordId":"miss","ukIpa":"/mɪs/","usIpa":"/mɪs/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to fail to catch, attend, or experience something","vi":"bỏ lỡ; trễ"},{"pos":"v.","en":"to feel sad because someone or something is absent","vi":"nhớ nhung"},{"pos":"v.","en":"to fail to hit a target or notice something","vi":"bắn hụt; bỏ sót"}],"examples":[{"en":"Hurry up, or we will miss the last bus.","vi":"Nhanh lên, nếu không chúng ta sẽ lỡ chuyến xe buýt cuối cùng.","audioKind":"ex"},{"en":"Students who miss several lessons may need additional support to keep up with their classmates.","vi":"Những học sinh bỏ lỡ một số bài học có thể cần được hỗ trợ thêm để theo kịp các bạn cùng lớp.","audioKind":"ex2"}],"collocations":[{"en":"miss the bus","vi":"lỡ xe buýt"},{"en":"miss an opportunity","vi":"bỏ lỡ cơ hội"},{"en":"miss someone","vi":"nhớ ai đó"},{"en":"miss the point","vi":"không hiểu ý chính"}],"wordFamily":["missing (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Sau miss đi trực tiếp với danh từ hoặc danh động từ, không dùng to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_follow', 'en-a1-31', 'follow', '/ˈfɑːloʊ/', 'A1', 'đi theo; đi sát phía sau; tuân theo; làm theo; hiểu; nắm bắt', 'v.', 'follower (n.), following (adj.)', NULL, 'Theo sau follow là tân ngữ trực tiếp: follow me, không dùng kèm giới từ with.', 'Follow this path until you reach the wooden bridge.', NULL, 'Hãy đi theo con đường này cho đến khi bạn tới cây cầu gỗ.', '{"wordId":"follow","ukIpa":"/ˈfɒləʊ/","usIpa":"/ˈfɑːloʊ/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"To move behind someone or along a route.","vi":"đi theo; đi sát phía sau"},{"pos":"v.","en":"To act according to instructions, rules, or advice.","vi":"tuân theo; làm theo"},{"pos":"v.","en":"To understand what someone says or explains.","vi":"hiểu; nắm bắt"}],"examples":[{"en":"Follow this path until you reach the wooden bridge.","vi":"Hãy đi theo con đường này cho đến khi bạn tới cây cầu gỗ.","audioKind":"ex"},{"en":"Schools should teach children how to follow safety guidelines when using digital devices and online services.","vi":"Nhà trường nên dạy trẻ em cách tuân thủ các nguyên tắc an toàn khi sử dụng thiết bị số và dịch vụ trực tuyến.","audioKind":"ex2"}],"collocations":[{"en":"follow instructions","vi":"làm theo hướng dẫn"},{"en":"follow advice","vi":"nghe theo lời khuyên"},{"en":"follow a path","vi":"đi theo lối mòn"},{"en":"follow an argument","vi":"hiểu mạch lập luận"}],"wordFamily":["follower (n.)","following (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Theo sau follow là tân ngữ trực tiếp: follow me, không dùng kèm giới từ with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_twice', 'en-a1-31', 'twice', '/twaɪs/', 'A1', 'hai lần; gấp đôi', 'adv.', NULL, NULL, 'Cấu trúc chỉ hai lần nhiều hơn dùng twice as…as hoặc twice kèm theo danh từ.', 'I checked my bag twice but couldn''t find my keys.', NULL, 'Tôi đã kiểm tra túi của mình hai lần nhưng không tìm thấy chìa khóa.', '{"wordId":"twice","ukIpa":"/twaɪs/","usIpa":"/twaɪs/","cefr":"A1","topic":"daily","senses":[{"pos":"adv.","en":"On two occasions.","vi":"hai lần"},{"pos":"adv.","en":"To double the amount, degree, or size.","vi":"gấp đôi"}],"examples":[{"en":"I checked my bag twice but couldn''t find my keys.","vi":"Tôi đã kiểm tra túi của mình hai lần nhưng không tìm thấy chìa khóa.","audioKind":"ex"},{"en":"Residents who exercise at least twice a week may experience improvements in their physical and mental health.","vi":"Những cư dân tập thể dục ít nhất hai tuần một lần có thể thấy sức khỏe thể chất và tinh thần được cải thiện.","audioKind":"ex2"}],"collocations":[{"en":"twice a week","vi":"hai lần một tuần"},{"en":"twice as much","vi":"nhiều gấp đôi"},{"en":"think twice","vi":"suy nghĩ kỹ"},{"en":"twice the size","vi":"lớn gấp đôi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc chỉ hai lần nhiều hơn dùng twice as…as hoặc twice kèm theo danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_give', 'en-a1-31', 'give', '/ɡɪv/', 'A1', 'đưa; trao; tặng; cung cấp; đem lại; mang lại; tổ chức; đưa ra; thực hiện', 'v.', 'giver (n.), giving (adj.)', 'Trái nghĩa: receive', 'give sb sth tương đương với give sth to sb; dạng quá khứ là gave.', 'Please give your sister a clean towel after swimming.', NULL, 'Hãy đưa cho em gái con một chiếc khăn sạch sau khi bơi nhé.', '{"wordId":"give","ukIpa":"/ɡɪv/","usIpa":"/ɡɪv/","cefr":"A1","topic":"daily","senses":[{"pos":"v.","en":"to hand something to someone or let them have it","vi":"đưa; trao; tặng"},{"pos":"v.","en":"to provide something or cause someone to experience something","vi":"cung cấp; đem lại; mang lại"},{"pos":"v.","en":"to hold an event or perform an action for others","vi":"tổ chức; đưa ra; thực hiện"}],"examples":[{"en":"Please give your sister a clean towel after swimming.","vi":"Hãy đưa cho em gái con một chiếc khăn sạch sau khi bơi nhé.","audioKind":"ex"},{"en":"Schools should give students opportunities to develop practical skills through projects that address real community needs.","vi":"Nhà trường nên tạo cơ hội cho học sinh phát triển các kỹ năng thực tế thông qua các dự án đáp ứng nhu cầu thực tế của cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"give advice","vi":"đưa ra lời khuyên"},{"en":"give a presentation","vi":"thuyết trình"},{"en":"give someone a chance","vi":"cho ai đó cơ hội"},{"en":"give permission","vi":"cấp phép; cho phép"}],"wordFamily":["giver (n.)","giving (adj.)"],"synonyms":[],"antonyms":["receive"],"tipVi":"give sb sth tương đương với give sth to sb; dạng quá khứ là gave.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shirt', 'en-a1-31', 'shirt', '/ʃɝːt/', 'A1', 'áo sơ mi', 'n.', 'shirtless (adj.)', NULL, 'shirt thường chỉ áo sơ mi cài khuy; T-shirt mới là áo phông.', 'He ironed his blue shirt before the interview.', NULL, 'Anh ấy đã ủi chiếc áo sơ mi màu xanh của mình trước buổi phỏng vấn.', '{"wordId":"shirt","ukIpa":"/ʃɜːt/","usIpa":"/ʃɝːt/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"an upper-body garment, usually with sleeves, a collar, and front buttons","vi":"áo sơ mi"}],"examples":[{"en":"He ironed his blue shirt before the interview.","vi":"Anh ấy đã ủi chiếc áo sơ mi màu xanh của mình trước buổi phỏng vấn.","audioKind":"ex"},{"en":"Some employers require staff to wear a formal shirt, while others allow more casual clothing.","vi":"Một số nhà tuyển dụng yêu cầu nhân viên mặc áo sơ mi lịch sự, trong khi những nơi khác cho phép trang phục thoải mái hơn.","audioKind":"ex2"}],"collocations":[{"en":"a cotton shirt","vi":"áo sơ mi bằng vải cotton"},{"en":"a short-sleeved shirt","vi":"áo sơ mi ngắn tay"},{"en":"button up a shirt","vi":"cài cúc áo sơ mi"}],"wordFamily":["shirtless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"shirt thường chỉ áo sơ mi cài khuy; T-shirt mới là áo phông.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_behind', 'en-a1-31', 'behind', '/bɪˈhaɪnd/', 'A1', 'ở phía sau; đằng sau; ở phía sau; thụt lùi; chậm tiến độ; chủ mưu; đứng sau gây ra', 'prep.', NULL, 'Trái nghĩa: ahead', 'behind có thể làm giới từ hoặc phó từ; fall behind có nghĩa là thụt lùi hoặc tụt lại phía sau.', 'Your umbrella is behind the door in the kitchen.', NULL, 'Cây ô của bạn để ở phía sau cánh cửa trong nhà bếp.', '{"wordId":"behind","ukIpa":"/bɪˈhaɪnd/","usIpa":"/bɪˈhaɪnd/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"at or towards the back of someone or something","vi":"ở phía sau; đằng sau"},{"pos":"adv.","en":"at the back or making less progress than expected","vi":"ở phía sau; thụt lùi; chậm tiến độ"},{"pos":"prep.","en":"responsible for causing or supporting something","vi":"chủ mưu; đứng sau gây ra"}],"examples":[{"en":"Your umbrella is behind the door in the kitchen.","vi":"Cây ô của bạn để ở phía sau cánh cửa trong nhà bếp.","audioKind":"ex"},{"en":"Students who fall behind at school may benefit from additional support rather than stricter discipline.","vi":"Những học sinh bị thụt lùi việc học ở trường có thể sẽ tiến bộ hơn nhờ nhận được sự hỗ trợ thêm thay vì phải chịu kỷ luật nghiêm khắc hơn.","audioKind":"ex2"}],"collocations":[{"en":"behind the scenes","vi":"đằng sau hậu trường"},{"en":"fall behind","vi":"bị tụt lại phía sau"},{"en":"behind schedule","vi":"chậm tiến độ"}],"wordFamily":[],"synonyms":[],"antonyms":["ahead"],"tipVi":"behind có thể làm giới từ hoặc phó từ; fall behind có nghĩa là thụt lùi hoặc tụt lại phía sau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_great', 'en-a1-31', 'great', '/ɡreɪt/', 'A1', 'tuyệt vời; thú vị; lớn; rất nhiều; đáng kể; vĩ đại; xuất sắc; thành công', 'adj.', 'greatness (n.), greatly (adv.)', 'Đồng nghĩa: excellent, outstanding · Trái nghĩa: terrible', 'a great deal of đi với danh từ không đếm được, dùng để chỉ số lượng lớn.', 'We had a great afternoon swimming in the lake.', NULL, 'Chúng tôi đã có một buổi chiều tuyệt vời bơi lội ở hồ.', '{"wordId":"great","ukIpa":"/ɡreɪt/","usIpa":"/ɡreɪt/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Very good or enjoyable.","vi":"tuyệt vời; thú vị"},{"pos":"adj.","en":"Very large in amount, size, or degree.","vi":"lớn; rất nhiều; đáng kể"},{"pos":"adj.","en":"Highly important, admired, or successful.","vi":"vĩ đại; xuất sắc; thành công"}],"examples":[{"en":"We had a great afternoon swimming in the lake.","vi":"Chúng tôi đã có một buổi chiều tuyệt vời bơi lội ở hồ.","audioKind":"ex"},{"en":"Access to reliable internet is of great importance for students living in remote areas.","vi":"Khả năng tiếp cận internet đáng tin cậy có tầm quan trọng lớn đối với học sinh sống ở các vùng sâu vùng xa.","audioKind":"ex2"}],"collocations":[{"en":"a great opportunity","vi":"cơ hội tuyệt vời"},{"en":"of great importance","vi":"có tầm quan trọng lớn"},{"en":"a great deal of","vi":"rất nhiều"},{"en":"a great achievement","vi":"thành tựu xuất sắc"}],"wordFamily":["greatness (n.)","greatly (adv.)"],"synonyms":["excellent","outstanding"],"antonyms":["terrible"],"tipVi":"a great deal of đi với danh từ không đếm được, dùng để chỉ số lượng lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_good', 'en-a1-31', 'good', '/ɡʊd/', 'A1', 'tốt; chất lượng cao; có ích; có lợi; điều hay; việc thiện', 'adj.', 'goodness (n.)', 'Đồng nghĩa: fine · Trái nghĩa: bad', 'good là tính từ; khi bổ nghĩa cho động từ thường dùng well.', 'This bakery makes good bread with a crisp crust.', NULL, 'Tiệm bánh này làm ra những ổ bánh mì ngon với lớp vỏ giòn rụm.', '{"wordId":"good","ukIpa":"/ɡʊd/","usIpa":"/ɡʊd/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Of a high or satisfactory standard.","vi":"tốt; chất lượng cao"},{"pos":"adj.","en":"Having a helpful or healthy effect.","vi":"có ích; có lợi"},{"pos":"n.","en":"Something that benefits people or is morally right.","vi":"điều hay; việc thiện"}],"examples":[{"en":"This bakery makes good bread with a crisp crust.","vi":"Tiệm bánh này làm ra những ổ bánh mì ngon với lớp vỏ giòn rụm.","audioKind":"ex"},{"en":"Good public transport allows residents to reach essential services without relying on private cars.","vi":"Giao thông công cộng chất lượng tốt giúp cư dân tiếp cận các dịch vụ thiết yếu mà không cần phụ thuộc vào xe ô tô cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"good quality","vi":"chất lượng tốt"},{"en":"good at","vi":"giỏi về"},{"en":"good for","vi":"có lợi cho"},{"en":"do good","vi":"làm điều thiện; có ích"}],"wordFamily":["goodness (n.)"],"synonyms":["fine"],"antonyms":["bad"],"tipVi":"good là tính từ; khi bổ nghĩa cho động từ thường dùng well.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_both', 'en-a1-31', 'both', '/boʊθ/', 'A1', 'cả hai; cả hai người hoặc vật', 'det.', NULL, NULL, 'both dùng để chỉ hai đối tượng; cấu trúc both A and B khi làm chủ ngữ sẽ đi với động từ số nhiều.', 'Both windows were open, letting in the cool breeze.', NULL, 'Cả hai cửa sổ đều mở, mang theo làn gió mát thổi vào trong.', '{"wordId":"both","ukIpa":"/bəʊθ/","usIpa":"/boʊθ/","cefr":"A1","topic":"daily","senses":[{"pos":"det.","en":"referring to two people or things together","vi":"cả hai"},{"pos":"pron.","en":"the two people or things already mentioned","vi":"cả hai người hoặc vật"}],"examples":[{"en":"Both windows were open, letting in the cool breeze.","vi":"Cả hai cửa sổ đều mở, mang theo làn gió mát thổi vào trong.","audioKind":"ex"},{"en":"Both governments and individuals have a responsibility to reduce waste and protect natural resources.","vi":"Cả chính phủ lẫn cá nhân đều có trách nhiệm giảm thiểu rác thải và bảo vệ tài nguyên thiên nhiên.","audioKind":"ex2"}],"collocations":[{"en":"both sides","vi":"cả hai bên"},{"en":"both of them","vi":"cả hai người họ"},{"en":"both ... and ...","vi":"cả... lẫn..."}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"both dùng để chỉ hai đối tượng; cấu trúc both A and B khi làm chủ ngữ sẽ đi với động từ số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inside', 'en-a1-31', 'inside', '/ˌɪnˈsaɪd/', 'A1', 'ở bên trong; vào bên trong; ở trong; vào trong; phía bên trong; phần nội vi', 'prep.', NULL, 'Trái nghĩa: outside', 'inside hoạt động như giới từ khi đi kèm danh từ; khi đứng độc lập nó đóng vai trò trạng từ.', 'Your keys are inside the small pocket of your bag.', NULL, 'Chìa khóa của bạn nằm ở chiếc túi nhỏ bên trong chiếc cặp.', '{"wordId":"inside","ukIpa":"/ˌɪnˈsaɪd/","usIpa":"/ˌɪnˈsaɪd/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"in or into the inner part of something","vi":"ở bên trong; vào bên trong"},{"pos":"adv.","en":"in or into an enclosed place or container","vi":"ở trong; vào trong"},{"pos":"n.","en":"the inner part or surface of something","vi":"phía bên trong; phần nội vi"}],"examples":[{"en":"Your keys are inside the small pocket of your bag.","vi":"Chìa khóa của bạn nằm ở chiếc túi nhỏ bên trong chiếc cặp.","audioKind":"ex"},{"en":"Air quality inside buildings deserves greater attention because many people spend most of their day indoors.","vi":"Chất lượng không khí bên trong các tòa nhà rất đáng được quan tâm hơn bởi vì nhiều người dành phần lớn thời gian trong ngày ở trong nhà.","audioKind":"ex2"}],"collocations":[{"en":"inside the building","vi":"bên trong tòa nhà"},{"en":"stay inside","vi":"ở trong nhà"},{"en":"on the inside","vi":"ở phía bên trong"},{"en":"from the inside","vi":"từ bên trong"}],"wordFamily":[],"synonyms":[],"antonyms":["outside"],"tipVi":"inside hoạt động như giới từ khi đi kèm danh từ; khi đứng độc lập nó đóng vai trò trạng từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_one', 'en-a1-31', 'one', '/wʌn/', 'A1', 'số một (số nguyên dương nhỏ nhất); một; cái nào đó (dùng thay cho danh từ đếm được đã nhắc trước đó); mọi người nói chung, bao gồm cả người nói (văn phong trang trọng)', 'num.', NULL, NULL, 'one có thể thay thế cho danh từ đếm được số ít; dạng số nhiều là ones.', 'There is only one apple left in the bowl.', NULL, 'Trong bát chỉ còn lại đúng một quả táo.', '{"wordId":"one","ukIpa":"/wʌn/","usIpa":"/wʌn/","cefr":"A1","topic":"daily","senses":[{"pos":"num.","en":"the smallest positive whole number","vi":"số một (số nguyên dương nhỏ nhất)"},{"pos":"pron.","en":"used instead of a countable noun already mentioned","vi":"một; cái nào đó (dùng thay cho danh từ đếm được đã nhắc trước đó)"},{"pos":"pron.","en":"people in general, including the speaker, in formal language","vi":"mọi người nói chung, bao gồm cả người nói (văn phong trang trọng)"}],"examples":[{"en":"There is only one apple left in the bowl.","vi":"Trong bát chỉ còn lại đúng một quả táo.","audioKind":"ex"},{"en":"One major benefit of public transport is that it reduces the demand for parking spaces in cities.","vi":"Một lợi ích lớn của giao thông công cộng là làm giảm nhu cầu về chỗ đỗ xe trong các thành phố.","audioKind":"ex2"}],"collocations":[{"en":"one at a time","vi":"từng cái một"},{"en":"one another","vi":"lẫn nhau; với nhau"},{"en":"one by one","vi":"từng cái một; lần lượt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"one có thể thay thế cho danh từ đếm được số ít; dạng số nhiều là ones.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bed', 'en-a1-31', 'bed', '/bed/', 'A1', 'cái giường (đồ nội thất dùng để ngủ); đáy sông; đáy biển; lòng hồ; luống đất; bồn hoa (vùng đất được chuẩn bị để trồng cây)', 'n.', 'bedroom (n.), bedding (n.), bedtime (n.)', NULL, 'go to bed chỉ hành động đi ngủ, không dùng mạo từ the; make the bed chỉ việc dọn dẹp, gấp chăn gối trên giường.', 'The cat curled up on my bed after lunch.', NULL, 'Con mèo cuộn tròn trên chiếc giường của tôi sau bữa trưa.', '{"wordId":"bed","ukIpa":"/bed/","usIpa":"/bed/","cefr":"A1","topic":"daily","senses":[{"pos":"n.","en":"A piece of furniture used for sleeping","vi":"cái giường (đồ nội thất dùng để ngủ)"},{"pos":"n.","en":"The ground at the bottom of a river, sea, or lake","vi":"đáy sông; đáy biển; lòng hồ"},{"pos":"n.","en":"An area of soil prepared for growing plants","vi":"luống đất; bồn hoa (vùng đất được chuẩn bị để trồng cây)"}],"examples":[{"en":"The cat curled up on my bed after lunch.","vi":"Con mèo cuộn tròn trên chiếc giường của tôi sau bữa trưa.","audioKind":"ex"},{"en":"Maintaining a regular time to go to bed can improve sleep quality and support mental health.","vi":"Duy trì một giờ đi ngủ đều đặn có thể cải thiện chất lượng giấc ngủ và hỗ trợ sức khỏe tinh thần.","audioKind":"ex2"}],"collocations":[{"en":"go to bed","vi":"đi ngủ"},{"en":"make the bed","vi":"dọn giường; gấp chăn gối"},{"en":"river bed","vi":"đáy sông"},{"en":"flower bed","vi":"luống hoa; bồn hoa"}],"wordFamily":["bedroom (n.)","bedding (n.)","bedtime (n.)"],"synonyms":[],"antonyms":[],"tipVi":"go to bed chỉ hành động đi ngủ, không dùng mạo từ the; make the bed chỉ việc dọn dẹp, gấp chăn gối trên giường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_same', 'en-a1-31', 'same', '/seɪm/', 'A1', 'giống hệt; cùng một (sự vật, sự việc); chính điều vừa nhắc đến; sự vật y hệt như vậy', 'adj.', 'sameness (n.)', 'Đồng nghĩa: identical · Trái nghĩa: different', 'thường dùng the same; khi so sánh dùng cấu trúc the same as.', 'We take the same bus to school every morning.', NULL, 'Chúng tôi đi chung một chuyến xe buýt đến trường mỗi buổi sáng.', '{"wordId":"same","ukIpa":"/seɪm/","usIpa":"/seɪm/","cefr":"A1","topic":"daily","senses":[{"pos":"adj.","en":"Exactly alike, or referring to one particular thing rather than another.","vi":"giống hệt; cùng một (sự vật, sự việc)"},{"pos":"pron.","en":"The very thing already mentioned, or something exactly like it.","vi":"chính điều vừa nhắc đến; sự vật y hệt như vậy"}],"examples":[{"en":"We take the same bus to school every morning.","vi":"Chúng tôi đi chung một chuyến xe buýt đến trường mỗi buổi sáng.","audioKind":"ex"},{"en":"Students from different backgrounds should have the same opportunities to access high-quality education and develop their talents.","vi":"Học sinh từ các hoàn cảnh khác nhau nên có cơ hội như nhau để tiếp cận nền giáo dục chất lượng cao và phát triển tài năng của mình.","audioKind":"ex2"}],"collocations":[{"en":"the same as","vi":"giống như..."},{"en":"at the same time","vi":"cùng một lúc; đồng thời"},{"en":"stay the same","vi":"giữ nguyên không đổi"},{"en":"the same age","vi":"cùng độ tuổi; bằng tuổi"}],"wordFamily":["sameness (n.)"],"synonyms":["identical"],"antonyms":["different"],"tipVi":"thường dùng the same; khi so sánh dùng cấu trúc the same as.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_during', 'en-a1-31', 'during', '/ˈdʊrɪŋ/', 'A1', 'trong suốt; vào một thời điểm nào đó trong khoảng thời gian cụ thể', 'prep.', NULL, NULL, 'during đi sau là danh từ; while thường đi với mệnh đề (có chủ ngữ và động từ); for dùng để chỉ khoảng thời gian kéo dài.', 'Please keep your phone silent during the concert.', NULL, 'Xin vui lòng để điện thoại ở chế độ im lặng trong suốt buổi biểu diễn.', '{"wordId":"during","ukIpa":"/ˈdjʊərɪŋ/","usIpa":"/ˈdʊrɪŋ/","cefr":"A1","topic":"daily","senses":[{"pos":"prep.","en":"at some point within, or throughout, a particular period","vi":"trong suốt; vào một thời điểm nào đó trong khoảng thời gian cụ thể"}],"examples":[{"en":"Please keep your phone silent during the concert.","vi":"Xin vui lòng để điện thoại ở chế độ im lặng trong suốt buổi biểu diễn.","audioKind":"ex"},{"en":"During periods of extreme heat, local authorities should provide cool indoor spaces for vulnerable residents.","vi":"Trong những đợt nắng nóng cực đoan, chính quyền địa phương nên cung cấp các không gian mát mẻ trong nhà cho cư dân dễ bị tổn thương.","audioKind":"ex2"}],"collocations":[{"en":"during the day","vi":"vào ban ngày"},{"en":"during the summer","vi":"vào mùa hè"},{"en":"during working hours","vi":"trong giờ làm việc"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"during đi sau là danh từ; while thường đi với mệnh đề (có chủ ngữ và động từ); for dùng để chỉ khoảng thời gian kéo dài.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_31_1', 'en-a1-31', 'Cách dùng “during” (prep.) — trong suốt; vào một thời điểm nào đó trong khoảng thời gian cụ thể', 'during the day  ·  during the summer  ·  during working hours', 'during đi sau là danh từ; while thường đi với mệnh đề (có chủ ngữ và động từ); for dùng để chỉ khoảng thời gian kéo dài.', NULL, '[{"hanzi":"Please keep your phone silent during the concert.","pinyin":"","meaning":"Xin vui lòng để điện thoại ở chế độ im lặng trong suốt buổi biểu diễn."},{"hanzi":"During periods of extreme heat, local authorities should provide cool indoor spaces for vulnerable residents.","pinyin":"","meaning":"Trong những đợt nắng nóng cực đoan, chính quyền địa phương nên cung cấp các không gian mát mẻ trong nhà cho cư dân dễ bị tổn thương."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_31_2', 'en-a1-31', 'Cách dùng “bed” (n.) — cái giường (đồ nội thất dùng để ngủ)', 'go to bed  ·  make the bed  ·  river bed', 'go to bed chỉ hành động đi ngủ, không dùng mạo từ the; make the bed chỉ việc dọn dẹp, gấp chăn gối trên giường.', 'Họ từ (Word Family): bedroom (n.), bedding (n.), bedtime (n.)', '[{"hanzi":"The cat curled up on my bed after lunch.","pinyin":"","meaning":"Con mèo cuộn tròn trên chiếc giường của tôi sau bữa trưa."},{"hanzi":"Maintaining a regular time to go to bed can improve sleep quality and support mental health.","pinyin":"","meaning":"Duy trì một giờ đi ngủ đều đặn có thể cải thiện chất lượng giấc ngủ và hỗ trợ sức khỏe tinh thần."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_31_3', 'en-a1-31', 'Cách dùng “salad” (n.) — món salad; rau trộn', 'green salad  ·  fruit salad  ·  salad dressing', 'Có thể dùng như danh từ đếm được để chỉ một phần salad, hoặc danh từ không đếm được để chỉ món salad nói chung.', NULL, '[{"hanzi":"I added cucumber and tomatoes to the salad.","pinyin":"","meaning":"Tôi đã cho thêm dưa chuột và cà chua vào món salad."},{"hanzi":"Offering fresh salad in school cafeterias can encourage children to eat a wider variety of vegetables.","pinyin":"","meaning":"Việc cung cấp salad tươi trong các căn tin trường học có thể khuyến khích trẻ em ăn nhiều loại rau củ hơn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_31_4', 'en-a1-31', 'Cách dùng “hungry” (adj.) — đói bụng; đói', 'feel hungry  ·  go hungry  ·  hungry for success', 'Cụm "hungry for" thường đi sau bởi một danh từ, mang nghĩa khao khát hoặc tha thiết muốn có được điều gì đó.', 'Họ từ (Word Family): hunger (n.), hunger (v.), hungrily (adv.) | Đồng nghĩa: ravenous, eager | Trái nghĩa: full', '[{"hanzi":"I felt hungry after our long walk by the river.","pinyin":"","meaning":"Tôi cảm thấy đói sau chuyến đi bộ dài dọc bờ sông."},{"hanzi":"School meal programmes help hungry children concentrate in class and participate more actively in learning.","pinyin":"","meaning":"Các chương trình bữa ăn học đường giúp những trẻ em bị đói tập trung hơn trong lớp và tham gia học tập tích cực hơn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_31_1', 'en-a1-31', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_31_1_1', 'ten_31_1', 'photo', 'We took a photo beside the old bridge.', 'We took a photo beside the old bridge.', '/ˈfoʊtoʊ/', 'Chúng tôi đã chụp một bức ảnh ngay bên cạnh cây cầu cổ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_31_1_2', 'ten_31_1', 'orange', 'I peeled an orange and shared it with my sister.', 'I peeled an orange and shared it with my sister.', '/ˈɔːrɪndʒ/', 'Tôi đã bóc một quả cam và chia cho em gái mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_31_1_3', 'ten_31_1', 'dining-room', 'We put fresh flowers on the dining-room table.', 'We put fresh flowers on the dining-room table.', '/ˈdaɪnɪŋ ruːm/', 'Chúng tôi cắm những bông hoa tươi trên chiếc bàn ở phòng ăn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_31_1_4', 'ten_31_1', 'need', 'These plants need more water during hot weather.', 'These plants need more water during hot weather.', '/niːd/', 'Những loại cây này cần nhiều nước hơn trong thời tiết nắng nóng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_31_1_5', 'ten_31_1', 'hungry', 'I felt hungry after our long walk by the river.', 'I felt hungry after our long walk by the river.', '/ˈhʌŋɡri/', 'Tôi cảm thấy đói sau chuyến đi bộ dài dọc bờ sông.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_31_1_6', 'ten_31_1', 'ago', 'I left my umbrella on the bus an hour ago.', 'I left my umbrella on the bus an hour ago.', '/əˈɡoʊ/', 'Tôi để quên ô trên xe buýt cách đây một tiếng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_31_1_7', 'ten_31_1', 'over', 'A small bird flew over the garden wall.', 'A small bird flew over the garden wall.', '/ˈoʊvər/', 'Một chú chim nhỏ bay qua bức tường vườn.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_31_1_8', 'ten_31_1', 'they', 'The children waved as they boarded the bus.', 'The children waved as they boarded the bus.', '/ðeɪ/', 'Lũ trẻ vẫy tay chào khi chúng lên xe buýt.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_31_1_1', 'en-a1-31', 'ten_31_1', 'listening', 'listening', 'We took a photo beside the old bridge.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã chụp một bức ảnh ngay bên cạnh cây cầu cổ.","Tôi để quên ô trên xe buýt cách đây một tiếng.","Một chú chim nhỏ bay qua bức tường vườn.","Lũ trẻ vẫy tay chào khi chúng lên xe buýt."]'::jsonb, 0, 'We took a photo beside the old bridge. → Chúng tôi đã chụp một bức ảnh ngay bên cạnh cây cầu cổ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_31_1_2', 'en-a1-31', 'ten_31_1', 'listening', 'listening', 'I peeled an orange and shared it with my sister.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi để quên ô trên xe buýt cách đây một tiếng.","Những loại cây này cần nhiều nước hơn trong thời tiết nắng nóng.","Tôi đã bóc một quả cam và chia cho em gái mình.","Tôi cảm thấy đói sau chuyến đi bộ dài dọc bờ sông."]'::jsonb, 2, 'I peeled an orange and shared it with my sister. → Tôi đã bóc một quả cam và chia cho em gái mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_31_1_3', 'en-a1-31', 'ten_31_1', 'listening', 'listening', 'We put fresh flowers on the dining-room table.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những loại cây này cần nhiều nước hơn trong thời tiết nắng nóng.","Tôi cảm thấy đói sau chuyến đi bộ dài dọc bờ sông.","Tôi để quên ô trên xe buýt cách đây một tiếng.","Chúng tôi cắm những bông hoa tươi trên chiếc bàn ở phòng ăn."]'::jsonb, 3, 'We put fresh flowers on the dining-room table. → Chúng tôi cắm những bông hoa tươi trên chiếc bàn ở phòng ăn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
