INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_31_2_1', 'ten_31_2', 'photo', 'Historical photos provide valuable evidence of how urban landscapes and everyday lifestyles have changed over time.', 'Historical photos provide valuable evidence of how urban landscapes and everyday lifestyles have changed over time.', '/ˈfoʊtoʊ/', 'Những bức ảnh lịch sử cung cấp bằng chứng quý giá về sự thay đổi của cảnh quan đô thị và lối sống đời thường qua thời gian.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_31_2_2', 'ten_31_2', 'orange', 'An orange provides vitamin C, but a balanced diet requires a variety of foods.', 'An orange provides vitamin C, but a balanced diet requires a variety of foods.', '/ˈɔːrɪndʒ/', 'Cam cung cấp vitamin C, nhưng một chế độ ăn uống cân bằng đòi hỏi sự đa dạng về thực phẩm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_31_2_3', 'ten_31_2', 'dining-room', 'A shared dining-room can encourage social interaction among older residents who might otherwise eat alone.', 'A shared dining-room can encourage social interaction among older residents who might otherwise eat alone.', '/ˈdaɪnɪŋ ruːm/', 'Một phòng ăn chung có thể thúc đẩy sự giao lưu xã hội giữa những cư dân cao tuổi, những người mà nếu không có thể sẽ phải ăn uống một mình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_31_2_4', 'ten_31_2', 'need', 'Cities need to improve public transport if they want to reduce dependence on private cars.', 'Cities need to improve public transport if they want to reduce dependence on private cars.', '/niːd/', 'Các thành phố cần cải thiện giao thông công cộng nếu họ muốn giảm bớt sự phụ thuộc vào ô tô cá nhân.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
