INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_31_1', 'en-a1-31', NULL, 'comprehensive_test', 'listening', 'photo', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bức ảnh; bức hình","ngoài ra; cũng","trẻ em; đứa trẻ","khỏe mạnh"]'::jsonb, 0, 'photo (/ˈfoʊtoʊ/) → bức ảnh; bức hình', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_31_2', 'en-a1-31', NULL, 'comprehensive_test', 'listening', 'I peeled an orange and shared it with my sister.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hãy đi theo con đường này cho đến khi bạn tới cây cầu gỗ.","Cây ô của bạn để ở phía sau cánh cửa trong nhà bếp.","Tôi đã cho thêm dưa chuột và cà chua vào món salad.","Tôi đã bóc một quả cam và chia cho em gái mình."]'::jsonb, 3, 'I peeled an orange and shared it with my sister. → Tôi đã bóc một quả cam và chia cho em gái mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_31_3', 'en-a1-31', NULL, 'comprehensive_test', 'listening', 'dining-room', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bài tập về nhà","thức ăn; đồ ăn; thực phẩm","sạch sẽ; không vấy bẩn","phòng ăn; phòng ăn uống"]'::jsonb, 3, 'dining-room (/ˈdaɪnɪŋ ruːm/) → phòng ăn; phòng ăn uống', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_31_4', 'en-a1-31', NULL, 'comprehensive_test', 'listening', 'These plants need more water during hot weather.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng ta cần bao nhiêu quả táo để làm chiếc bánh?","Tôi thường nấu súp rau củ khi trời chuyển lạnh.","Tôi đã kiểm tra túi của mình hai lần nhưng không tìm thấy chìa khóa.","Những loại cây này cần nhiều nước hơn trong thời tiết nắng nóng."]'::jsonb, 3, 'These plants need more water during hot weather. → Những loại cây này cần nhiều nước hơn trong thời tiết nắng nóng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_31_5', 'en-a1-31', NULL, 'comprehensive_test', 'listening', 'hungry', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["xu (đơn vị tiền tệ bằng một phần trăm của đô-la hoặc ơ-rô)","đói bụng; đói","chào đón; hoan nghênh; đón tiếp nồng nhiệt","ở phía trên; cao hơn"]'::jsonb, 1, 'hungry (/ˈhʌŋɡri/) → đói bụng; đói; khao khát; thèm muốn', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_31_6', 'en-a1-31', NULL, 'comprehensive_test', 'listening', 'I left my umbrella on the bus an hour ago.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã có một buổi chiều tuyệt vời bơi lội ở hồ.","Chúng tôi cắm những bông hoa tươi trên chiếc bàn ở phòng ăn.","Tôi để quên ô trên xe buýt cách đây một tiếng.","Con chim nhỏ bay vụt đi khi tôi mở cửa sổ."]'::jsonb, 2, 'I left my umbrella on the bus an hour ago. → Tôi để quên ô trên xe buýt cách đây một tiếng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_31_7', 'en-a1-31', NULL, 'comprehensive_test', 'listening', 'over', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhà văn; tác giả; người viết sách, bài báo hoặc các văn bản khác","bút chì","từ; đến từ","ở phía trên; vượt qua"]'::jsonb, 3, 'over (/ˈoʊvər/) → ở phía trên; vượt qua; hơn; quá; kết thúc', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_31_8', 'en-a1-31', NULL, 'comprehensive_test', 'listening', 'The children waved as they boarded the bus.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đi chung một chuyến xe buýt đến trường mỗi buổi sáng.","Lũ trẻ vẫy tay chào khi chúng lên xe buýt.","Tôi đã bóc một quả cam và chia cho em gái mình.","Tôi đã kiểm tra túi của mình hai lần nhưng không tìm thấy chìa khóa."]'::jsonb, 1, 'The children waved as they boarded the bus. → Lũ trẻ vẫy tay chào khi chúng lên xe buýt.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
