INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_31_18', 'en-a1-31', NULL, 'comprehensive_test', 'reading', NULL, 'Historical photos provide valuable evidence of how urban landscapes and everyday lifestyles have changed over time.', 'Dựa vào câu trên, từ “photo” có nghĩa phù hợp nhất là gì?', '["nóng; có nhiệt độ cao","tháng Bảy","bức ảnh; bức hình","mùa thu"]'::jsonb, 2, 'photo: bức ảnh; bức hình. Dịch cả câu: Những bức ảnh lịch sử cung cấp bằng chứng quý giá về sự thay đổi của cảnh quan đô thị và lối sống đời thường qua thời gian.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_31_19', 'en-a1-31', NULL, 'comprehensive_test', 'reading', NULL, 'An orange provides vitamin C, but a balanced diet requires a variety of foods.', 'Dựa vào câu trên, từ “orange” có nghĩa phù hợp nhất là gì?', '["kỳ nghỉ; ngày nghỉ phép","adj. thân thiện; cởi mở; niềm nở","phòng; buồng","quả cam; trái cam"]'::jsonb, 3, 'orange: quả cam; trái cam; màu cam. Dịch cả câu: Cam cung cấp vitamin C, nhưng một chế độ ăn uống cân bằng đòi hỏi sự đa dạng về thực phẩm.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_31_20', 'en-a1-31', NULL, 'comprehensive_test', 'reading', NULL, 'A shared dining-room can encourage social interaction among older residents who might otherwise eat alone.', 'Dựa vào câu trên, từ “dining-room” có nghĩa phù hợp nhất là gì?', '["căm ghét; rất ghét","bài kiểm tra; bài trắc nghiệm; sự xét nghiệm","phòng ăn; phòng ăn uống","mở; mở cửa; hoạt động"]'::jsonb, 2, 'dining-room: phòng ăn; phòng ăn uống. Dịch cả câu: Một phòng ăn chung có thể thúc đẩy sự giao lưu xã hội giữa những cư dân cao tuổi, những người mà nếu không có thể sẽ phải ăn uống một mình.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_31_21', 'en-a1-31', NULL, 'comprehensive_test', 'reading', NULL, 'Cities need to improve public transport if they want to reduce dependence on private cars.', 'Dựa vào câu trên, từ “need” có nghĩa phù hợp nhất là gì?', '["ánh sáng; đèn","có thể xảy ra; có thể thực hiện được","cần; đòi hỏi","nhanh; cao tốc"]'::jsonb, 2, 'need: cần; đòi hỏi; nhu cầu; sự cần thiết; cảnh ngộ khó khăn; sự túng thiếu. Dịch cả câu: Các thành phố cần cải thiện giao thông công cộng nếu họ muốn giảm bớt sự phụ thuộc vào ô tô cá nhân.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
